CREATE OR REPLACE FUNCTION "public"."_can_act_on_behalf_of_others"() RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT auth.uid() IS NULL
    OR public.has_role(auth.uid(), 'admin'::app_role)
    OR public.has_role(auth.uid(), 'manager'::app_role)
    OR public.has_role(auth.uid(), 'supervisor'::app_role)
    OR public.has_role(auth.uid(), 'dev'::app_role);
$$;


ALTER FUNCTION "public"."_can_act_on_behalf_of_others"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_get_user_primary_role"("_user_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE v_role text;
BEGIN
  SELECT ur.role::text INTO v_role
  FROM public.user_roles ur
  WHERE ur.user_id = _user_id
  ORDER BY CASE ur.role::text
    WHEN 'dev' THEN 1
    WHEN 'admin' THEN 2
    WHEN 'supervisor' THEN 3
    WHEN 'manager' THEN 4
    WHEN 'agente' THEN 5
    ELSE 99
  END
  LIMIT 1;
  RETURN COALESCE(v_role, 'agente');
END;
$$;


ALTER FUNCTION "public"."_get_user_primary_role"("_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_ai_quota"("_user_id" "uuid", "_function_name" "text", "_model" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_check jsonb;
  v_log_id uuid;
BEGIN
  v_check := public.check_ai_quota(_user_id);

  IF NOT (v_check->>'allowed')::boolean THEN
    RETURN v_check;
  END IF;

  INSERT INTO public.ai_usage_logs (user_id, function_name, model, status)
  VALUES (_user_id, _function_name, _model, 'pending')
  RETURNING id INTO v_log_id;

  RETURN v_check || jsonb_build_object('log_id', v_log_id);
END;
$$;


