CREATE OR REPLACE FUNCTION "public"."apply_transform"("p_value" "text", "p_transform_type" character varying, "p_transform_config" "jsonb" DEFAULT NULL::"jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_numeric_value NUMERIC;
    v_factor NUMERIC;
    v_result TEXT;
    v_pattern TEXT;
    v_group INTEGER;
    v_matches TEXT[];
BEGIN
    IF p_value IS NULL THEN
        RETURN NULL;
    END IF;
    
    CASE LOWER(p_transform_type)
        WHEN 'direct' THEN
            RETURN p_value;
        
        WHEN 'multiply' THEN
            BEGIN
                v_numeric_value := p_value::NUMERIC;
                v_factor := (p_transform_config->>'factor')::NUMERIC;
                RETURN (v_numeric_value * v_factor)::TEXT;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Erro em multiply transform: %', SQLERRM;
                RETURN p_value;
            END;
        
        WHEN 'divide' THEN
            BEGIN
                v_numeric_value := p_value::NUMERIC;
                v_factor := (p_transform_config->>'factor')::NUMERIC;
                IF v_factor = 0 THEN
                    RAISE WARNING 'Tentativa de divisão por zero';
                    RETURN p_value;
                END IF;
                RETURN (v_numeric_value / v_factor)::TEXT;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Erro em divide transform: %', SQLERRM;
                RETURN p_value;
            END;
        
        WHEN 'prefix' THEN
            RETURN (p_transform_config->>'prefix') || p_value;
        
        WHEN 'suffix' THEN
            RETURN p_value || (p_transform_config->>'suffix');
        
        WHEN 'uppercase' THEN
            RETURN UPPER(p_value);
        
        WHEN 'lowercase' THEN
            RETURN LOWER(p_value);
        
        WHEN 'trim' THEN
            RETURN TRIM(p_value);
        
        WHEN 'replace' THEN
            RETURN REPLACE(
                p_value,
                p_transform_config->>'find',
                p_transform_config->>'replace'
            );
        
        WHEN 'regex_extract' THEN
            BEGIN
                v_pattern := p_transform_config->>'pattern';
                v_group := COALESCE((p_transform_config->>'group')::INTEGER, 1);
                v_matches := regexp_matches(p_value, v_pattern);
                IF array_length(v_matches, 1) >= v_group THEN
                    RETURN v_matches[v_group];
                ELSE
                    RETURN NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Erro em regex_extract: %', SQLERRM;
                RETURN p_value;
            END;
        
        ELSE
            RAISE WARNING 'Transform type não suportado: %', p_transform_type;
            RETURN p_value;
    END CASE;
    
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Erro em apply_transform: %', SQLERRM;
    RETURN p_value;
END;
$$;


ALTER FUNCTION "public"."apply_transform"("p_value" "text", "p_transform_type" character varying, "p_transform_config" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_transform"("p_value" "text", "p_transform_type" character varying, "p_transform_config" "jsonb") IS 'Aplica transformações configuráveis (multiply, divide, prefix, suffix, regex, etc).';



CREATE OR REPLACE FUNCTION "public"."assert_quote_discount_integrity"("_quote_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _q public.quotes;
  _owner_id uuid;
  _max_allowed numeric;
  _snapshot text;
BEGIN
  SELECT * INTO _q FROM public.quotes WHERE id = _quote_id;
  IF NOT FOUND OR _q.status IN ('expired', 'cancelled', 'rejected', 'converted') THEN
    RETURN;
  END IF;
  IF current_setting('request.jwt.claim.role', true) = 'service_role'
     OR current_setting('app.write_source', true) = 'cron_expire'
     OR auth.uid() IS NULL THEN
    RETURN;
  END IF;

  _owner_id := COALESCE(_q.seller_id, _q.created_by);
  IF COALESCE(_q.real_discount_percent, 0) <= 0
     OR _owner_id IS NULL
     OR public.is_supervisor_or_above(_owner_id) THEN
    RETURN;
  END IF;

  SELECT max_discount_percent INTO _max_allowed
  FROM public.seller_discount_limits
  WHERE user_id = _owner_id;

  IF _max_allowed IS NULL THEN
    RAISE EXCEPTION 'Vendedor sem limite de desconto cadastrado.' USING ERRCODE = '23514';
  END IF;
  IF _q.real_discount_percent <= _max_allowed THEN
    RETURN;
  END IF;

  _snapshot := public.compute_quote_snapshot_hash(_quote_id);

  IF _q.status = 'pending_approval' THEN
    IF EXISTS (
      SELECT 1 FROM public.discount_approval_requests dar
      WHERE dar.quote_id = _quote_id AND dar.status = 'pending'
        AND dar.requested_discount_percent >= _q.real_discount_percent
        AND dar.quote_snapshot_hash = _snapshot
    ) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'Orçamento pending_approval não possui solicitação pendente para o snapshot final.'
      USING ERRCODE = '23514';
  END IF;

  IF _q.status = 'draft' AND EXISTS (
    SELECT 1 FROM public.discount_approval_requests dar
    WHERE dar.quote_id = _quote_id AND dar.status = 'rejected'
      AND dar.quote_snapshot_hash = _snapshot
  ) THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.discount_approval_requests dar
    WHERE dar.quote_id = _quote_id AND dar.status = 'approved'
      AND (dar.valid_until IS NULL OR dar.valid_until > now())
      AND dar.requested_discount_percent >= _q.real_discount_percent
      AND dar.quote_snapshot_hash = _snapshot
  ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'Snapshot final do orçamento não possui aprovação de desconto válida.'
    USING ERRCODE = '23514';
END;
$$;


ALTER FUNCTION "public"."assert_quote_discount_integrity"("_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_cart_item_sort_order"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF (TG_OP = 'INSERT' AND NEW.sort_order IS NULL)
     OR (TG_OP = 'UPDATE' AND NEW.cart_id <> OLD.cart_id) THEN
    -- Serializa a atribuicao de sort_order POR CARRINHO: evita que dois INSERTs
    -- concorrentes (READ COMMITTED) leiam o mesmo MAX e gerem sort_order duplicado.
    -- Advisory lock por transacao (liberado no commit); chave namespeada (415263)
    -- + hash do cart_id => so serializa inserts/moves no MESMO carrinho.
    PERFORM pg_advisory_xact_lock(415263, hashtext(NEW.cart_id::text));
    SELECT COALESCE(MAX(sort_order), -1) + 1
      INTO NEW.sort_order
      FROM public.seller_cart_items
     WHERE cart_id = NEW.cart_id
       AND id <> NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."assign_cart_item_sort_order"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_mcp_api_keys_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_action text; v_user_id uuid; v_resource_id text; v_details jsonb;
  v_old_scopes text[]; v_new_scopes text[];
  v_old_revoked timestamptz; v_new_revoked timestamptz;
  v_old_expires timestamptz; v_new_expires timestamptz;
  v_old_name text; v_new_name text;
  v_changed jsonb := '{}'::jsonb;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_user_id := COALESCE(OLD.created_by, auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
    v_resource_id := OLD.id::text;
    v_action := 'mcp_key.db_deleted';
    v_details := jsonb_build_object('name', OLD.name, 'key_prefix', OLD.key_prefix,
      'scopes', to_jsonb(OLD.scopes), 'was_revoked', (OLD.revoked_at IS NOT NULL), 'created_by', OLD.created_by);
  ELSIF TG_OP = 'INSERT' THEN
    v_user_id := COALESCE(NEW.created_by, auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
    v_resource_id := NEW.id::text;
    v_action := 'mcp_key.db_inserted';
    v_details := jsonb_build_object('name', NEW.name, 'key_prefix', NEW.key_prefix,
      'scopes', to_jsonb(NEW.scopes), 'is_full', (NEW.scopes @> ARRAY['*']::text[]),
      'expires_at', NEW.expires_at, 'rotated_from', NEW.rotated_from, 'created_by', NEW.created_by);
  ELSE
    v_user_id := COALESCE(auth.uid(), NEW.created_by, '00000000-0000-0000-0000-000000000000'::uuid);
    v_resource_id := NEW.id::text;
    v_old_scopes := OLD.scopes; v_new_scopes := NEW.scopes;
    v_old_revoked := OLD.revoked_at; v_new_revoked := NEW.revoked_at;
    v_old_expires := OLD.expires_at; v_new_expires := NEW.expires_at;
    v_old_name := OLD.name; v_new_name := NEW.name;
    IF v_old_name IS DISTINCT FROM v_new_name THEN
      v_changed := v_changed || jsonb_build_object('name', jsonb_build_object('old', v_old_name, 'new', v_new_name));
    END IF;
    IF v_old_scopes IS DISTINCT FROM v_new_scopes THEN
      v_changed := v_changed || jsonb_build_object('scopes', jsonb_build_object('old', to_jsonb(v_old_scopes), 'new', to_jsonb(v_new_scopes)));
    END IF;
    IF v_old_expires IS DISTINCT FROM v_new_expires THEN
      v_changed := v_changed || jsonb_build_object('expires_at', jsonb_build_object('old', v_old_expires, 'new', v_new_expires));
    END IF;
    IF v_old_revoked IS DISTINCT FROM v_new_revoked THEN
      v_changed := v_changed || jsonb_build_object('revoked_at', jsonb_build_object('old', v_old_revoked, 'new', v_new_revoked));
    END IF;
    IF v_changed = '{}'::jsonb THEN RETURN NEW; END IF;
    IF v_old_revoked IS NULL AND v_new_revoked IS NOT NULL THEN v_action := 'mcp_key.db_revoked';
    ELSIF v_old_scopes IS DISTINCT FROM v_new_scopes AND (v_new_scopes @> ARRAY['*']::text[]) 
          AND NOT (COALESCE(v_old_scopes, ARRAY[]::text[]) @> ARRAY['*']::text[]) THEN v_action := 'mcp_key.db_scope_escalated';
    ELSE v_action := 'mcp_key.db_updated'; END IF;
    v_details := jsonb_build_object('name', NEW.name, 'key_prefix', NEW.key_prefix, 'changed', v_changed,
      'is_full_now', (NEW.scopes @> ARRAY['*']::text[]), 'created_by', NEW.created_by);
  END IF;
  INSERT INTO public.admin_audit_log (user_id, action, resource_type, resource_id, details, source, status, created_at)
  VALUES (v_user_id, v_action, 'mcp_api_key', v_resource_id, v_details, 'db_trigger:mcp_api_keys', 'success', now());
  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'audit_mcp_api_keys_changes failed: %', SQLERRM;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."audit_mcp_api_keys_changes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_mcp_api_keys_changes"() IS 'Trigger de auditoria de MCP API keys. Executável apenas pelo trigger owner. T28 piloto Fase 3.';



CREATE OR REPLACE FUNCTION "public"."audit_mcp_key_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _is_full BOOLEAN := '*' = ANY(NEW.scopes);
BEGIN
  INSERT INTO public.admin_audit_log (user_id, action, resource_type, resource_id, details)
  VALUES (COALESCE(NEW.created_by, auth.uid()),
    CASE WHEN _is_full THEN 'mcp_key.issued_full' ELSE 'mcp_key.issued' END,
    'mcp_api_key', NEW.id::text,
    jsonb_build_object('name', NEW.name, 'key_prefix', NEW.key_prefix, 'scopes', NEW.scopes,
      'is_full_access', _is_full, 'expires_at', NEW.expires_at, 'created_by', NEW.created_by, 'auto_logged', true));
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."audit_mcp_key_insert"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_mcp_key_insert"() IS 'Trigger de auditoria de MCP key INSERT. service_role apenas. T28 piloto Fase 3.';



CREATE OR REPLACE FUNCTION "public"."audit_mcp_key_revoke"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL THEN
    INSERT INTO public.admin_audit_log (user_id, action, resource_type, resource_id, details)
    VALUES (auth.uid(), 'mcp_key.revoked', 'mcp_api_key', NEW.id::text,
      jsonb_build_object('name', NEW.name, 'key_prefix', NEW.key_prefix, 'scopes', NEW.scopes,
        'revoked_at', NEW.revoked_at, 'auto_logged', true));
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."audit_mcp_key_revoke"() OWNER TO "postgres";


