COMMENT ON FUNCTION "public"."buscar_equivalencia_spot"("p_spot_sigla" "text", "p_spot_nome" "text") IS 'Busca equivalência SPOT → Supabase. 
Uso: SELECT * FROM buscar_equivalencia_spot(''LSR'', NULL);';



CREATE OR REPLACE FUNCTION "public"."calculate_category_hierarchy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_parent_level   INTEGER;
    v_parent_path    TEXT;
    v_parent_fpr     TEXT;
BEGIN
    IF NEW.parent_id IS NULL THEN
        -- Categoria raiz
        NEW.level              := 1;
        NEW.path               := '/' || NEW.id::TEXT || '/';
        NEW.full_path_readable := UPPER(COALESCE(NEW.name, ''));
    ELSE
        -- Subcategoria: buscar level, path e full_path_readable do parent
        SELECT level, path, full_path_readable
        INTO   v_parent_level, v_parent_path, v_parent_fpr
        FROM   categories
        WHERE  id = NEW.parent_id;

        IF v_parent_level IS NULL THEN
            RAISE EXCEPTION 'Parent category % not found', NEW.parent_id;
        END IF;

        NEW.level  := v_parent_level + 1;
        NEW.path   := v_parent_path || NEW.id::TEXT || '/';
        -- Usar FPR do pai (ou fallback para UPPER(name) se pai ainda não tiver FPR)
        NEW.full_path_readable :=
            COALESCE(v_parent_fpr, UPPER(COALESCE(NEW.name, '')))
            || ' > '
            || UPPER(COALESCE(NEW.name, ''));
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_category_hierarchy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_mockup_job_estimated_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  base_cost       numeric(10,4);
  color_count     integer;
  area_count      integer;
  tech_multiplier numeric(4,2);
BEGIN
  IF NEW.ai_model = 'pro' THEN base_cost := 0.60;
  ELSE base_cost := 0.10;
  END IF;
  
  color_count := jsonb_array_length(NEW.product_colors);
  area_count  := jsonb_array_length(NEW.areas_config);
  
  SELECT COALESCE(base_cost_multiplier, 1.0) INTO tech_multiplier
  FROM public.personalization_techniques WHERE id = NEW.technique_id;
  
  NEW.total_mockups   := color_count * area_count;
  NEW.estimated_cost  := base_cost * color_count * area_count * COALESCE(tech_multiplier, 1.0);
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."calculate_mockup_job_estimated_cost"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_quote_item_pricing"("p_variant_id" "uuid", "p_quantity" integer, "p_organization_id" "uuid") RETURNS TABLE("unit_cost" numeric, "unit_price" numeric, "total_cost" numeric, "total_price" numeric, "margin_percent" numeric, "total_profit" numeric, "cost_tier" integer, "price_tier" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_cost DECIMAL(10,4);
    v_price DECIMAL(10,2);
    v_cost_tier INT;
    v_price_tier INT;
BEGIN
    SELECT gcfq.cost_per_unit, gcfq.tier_number 
    INTO v_cost, v_cost_tier
    FROM get_cost_for_quantity(p_variant_id, p_quantity) gcfq;
    
    SELECT gspfq.price_per_unit, gspfq.tier_number
    INTO v_price, v_price_tier
    FROM get_sale_price_for_quantity(p_variant_id, p_quantity, p_organization_id) gspfq;
    
    RETURN QUERY
    SELECT 
        COALESCE(v_cost, 0::DECIMAL(10,4)) AS unit_cost,
        COALESCE(v_price, 0::DECIMAL(10,2)) AS unit_price,
        ROUND(COALESCE(v_cost, 0) * p_quantity, 2)::DECIMAL(12,2) AS total_cost,
        ROUND(COALESCE(v_price, 0) * p_quantity, 2)::DECIMAL(12,2) AS total_price,
        CASE 
            WHEN v_cost > 0 THEN ROUND(((v_price - v_cost) / v_cost) * 100, 2)
            ELSE 0::DECIMAL(8,2)
        END AS margin_percent,
        ROUND((COALESCE(v_price, 0) - COALESCE(v_cost, 0)) * p_quantity, 2)::DECIMAL(12,2) AS total_profit,
        COALESCE(v_cost_tier, 1) AS cost_tier,
        COALESCE(v_price_tier, 1) AS price_tier;
END;
$$;


ALTER FUNCTION "public"."calculate_quote_item_pricing"("p_variant_id" "uuid", "p_quantity" integer, "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_seo_score"("p_product_id" "uuid") RETURNS TABLE("score" integer, "issues" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product     RECORD;
  v_score       INTEGER := 0;
  v_issues      JSONB   := '[]'::jsonb;
  v_image_count INTEGER;
  v_faq_count   INTEGER;
  v_spec_count  INTEGER;
  v_alt_count   INTEGER;
BEGIN
  SELECT * INTO v_product FROM products WHERE id = p_product_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 0, '["Produto não encontrado"]'::jsonb;
    RETURN;
  END IF;

  IF v_product.name IS NOT NULL AND LENGTH(TRIM(v_product.name)) >= 10 THEN
    v_score := v_score + 10;
  ELSE
    v_issues := v_issues || '["Nome muito curto (mínimo 10 caracteres)"]'::jsonb;
  END IF;
  IF v_product.slug IS NOT NULL AND LENGTH(TRIM(v_product.slug)) >= 5 THEN
    v_score := v_score + 10;
  ELSE
    v_issues := v_issues || '["Slug não definido ou muito curto"]'::jsonb;
  END IF;
  IF v_product.meta_title IS NOT NULL AND LENGTH(TRIM(v_product.meta_title)) > 0 THEN
    v_score := v_score + 10;
    IF LENGTH(v_product.meta_title) BETWEEN 30 AND 70 THEN
      v_score := v_score + 5;
    ELSE
      v_issues := v_issues || '["Meta title fora do tamanho ideal (30-70 chars)"]'::jsonb;
    END IF;
  ELSE
    v_issues := v_issues || '["Meta title não definido"]'::jsonb;
  END IF;
  IF v_product.meta_description IS NOT NULL AND LENGTH(TRIM(v_product.meta_description)) > 0 THEN
    v_score := v_score + 10;
    IF LENGTH(v_product.meta_description) BETWEEN 100 AND 170 THEN
      v_score := v_score + 5;
    ELSE
      v_issues := v_issues || '["Meta description fora do tamanho ideal (100-170 chars)"]'::jsonb;
    END IF;
  ELSE
    v_issues := v_issues || '["Meta description não definida"]'::jsonb;
  END IF;
  IF v_product.description IS NOT NULL AND LENGTH(TRIM(v_product.description)) > 0 THEN
    IF LENGTH(v_product.description) >= 300 THEN
      v_score := v_score + 15;
    ELSIF LENGTH(v_product.description) >= 100 THEN
      v_score := v_score + 10;
      v_issues := v_issues || '["Descrição poderia ser mais detalhada (ideal 300+ chars)"]'::jsonb;
    ELSE
      v_score := v_score + 5;
      v_issues := v_issues || '["Descrição muito curta (ideal 300+ chars)"]'::jsonb;
    END IF;
  ELSE
    v_issues := v_issues || '["Descrição não definida"]'::jsonb;
  END IF;
  IF v_product.short_description IS NOT NULL AND LENGTH(TRIM(v_product.short_description)) >= 30 THEN
    v_score := v_score + 5;
  ELSE
    v_issues := v_issues || '["Descrição curta não definida ou muito breve (ideal 30+ chars)"]'::jsonb;
  END IF;
  IF v_product.ai_summary IS NOT NULL AND LENGTH(TRIM(v_product.ai_summary)) >= 100 THEN
    v_score := v_score + 5;
  END IF;

  SELECT COUNT(*) INTO v_image_count FROM product_images WHERE product_id = p_product_id AND is_active = true;
  IF v_image_count >= 5 THEN v_score := v_score + 15;
  ELSIF v_image_count >= 3 THEN v_score := v_score + 10; v_issues := v_issues || '["Adicionar mais imagens (ideal 5+)"]'::jsonb;
  ELSIF v_image_count >= 1 THEN v_score := v_score + 5; v_issues := v_issues || '["Poucas imagens (ideal 5+)"]'::jsonb;
  ELSE v_issues := v_issues || '["Sem imagens cadastradas"]'::jsonb;
  END IF;

  IF v_image_count > 0 THEN
    SELECT COUNT(*) INTO v_alt_count FROM product_images WHERE product_id = p_product_id AND is_active = true AND alt_text IS NOT NULL;
    IF v_alt_count = v_image_count THEN v_score := v_score + 3; END IF;
  END IF;

  SELECT COUNT(*) INTO v_faq_count FROM product_faqs WHERE product_id = p_product_id AND is_active = true;
  IF v_faq_count >= 3 THEN v_score := v_score + 5;
  ELSIF v_faq_count >= 1 THEN v_score := v_score + 3;
  END IF;

  -- product_specifications movida para archive em 2026-06-15 (sempre vazia)
  SELECT COUNT(*) INTO v_spec_count FROM archive.product_specifications WHERE product_id = p_product_id AND is_active = true;
  IF v_spec_count >= 5 THEN v_score := v_score + 5;
  ELSIF v_spec_count >= 1 THEN v_score := v_score + 3;
  END IF;

  IF v_product.schema_json IS NOT NULL THEN v_score := v_score + 2; END IF;

  v_score := LEAST(GREATEST(v_score, 0), 100);
  RETURN QUERY SELECT v_score, v_issues;
END;
$$;


ALTER FUNCTION "public"."calculate_seo_score"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_seo_score"("p_product_id" "uuid") IS 'Calcula score SEO 0-100 de um produto. Critérios: nome, slug, meta_title, meta_description, description, short_description, ai_summary, imagens, alt_text, FAQs, specs, schema_json';



