CREATE OR REPLACE FUNCTION "public"."charge_mockup_credits_for_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_balance   numeric(10,2);
  v_credit_id uuid;
BEGIN
  IF NEW.status = 'processing' AND (OLD.status IS NULL OR OLD.status != 'processing') THEN
    SELECT id, balance INTO v_credit_id, v_balance
    FROM public.mockup_credits
    WHERE user_id = NEW.user_id
    FOR UPDATE;
    
    IF v_credit_id IS NULL THEN
      RAISE EXCEPTION 'Conta de créditos não encontrada pro user %', NEW.user_id;
    END IF;
    
    IF v_balance < NEW.estimated_cost THEN
      RAISE EXCEPTION 'Saldo insuficiente: necessário R$ %, disponível R$ %', 
        NEW.estimated_cost, v_balance;
    END IF;
    
    UPDATE public.mockup_credits SET 
      balance             = balance - NEW.estimated_cost,
      lifetime_spent      = lifetime_spent + NEW.estimated_cost,
      current_month_spent = current_month_spent + NEW.estimated_cost,
      current_day_spent   = current_day_spent + NEW.estimated_cost
    WHERE user_id = NEW.user_id;
    
    INSERT INTO public.mockup_credit_transactions (
      user_id, credit_account_id, type, amount, balance_before, balance_after, job_id, description
    ) VALUES (
      NEW.user_id, v_credit_id, 'charge', NEW.estimated_cost, v_balance, 
      v_balance - NEW.estimated_cost, NEW.id, 
      format('Geração de %s mockups - Job %s', NEW.total_mockups, NEW.id)
    );
  END IF;
  RETURN NEW;
END $_$;


ALTER FUNCTION "public"."charge_mockup_credits_for_job"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_ai_quota"("_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role       text;
  v_limit      int;
  v_unlimited  boolean;
  v_used       int;
BEGIN
  v_role := public._get_user_primary_role(_user_id);

  -- FIX BUG-QUOTA-001: cast role::text para comparar com v_role text
  SELECT monthly_limit, is_unlimited INTO v_limit, v_unlimited
  FROM public.ai_usage_quotas WHERE role::text = v_role;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'allowed', true, 'used', 0, 'limit', -1, 'remaining', -1,
      'unlimited', true, 'reason', 'no_quota_for_role'
    );
  END IF;

  -- FIX BUG-QUOTA-002: excluir rows 'pending' órfãs (> 5 min) da contagem.
  -- Justificativa:
  --   status='success' → request concluiu com êxito → conta na quota
  --   status='pending' < 5 min → request em voo → conta (evita double-spend)
  --   status='pending' > 5 min → isolate morreu antes de updateAiLog → NÃO conta
  --   status='error' → request falhou → NÃO conta (check_ai_quota usa != 'error')
  -- Coerente com pg_cron job 149 que converte pending > 5 min → error a cada 10 min.
  SELECT count(*)::int INTO v_used
  FROM public.ai_usage_logs
  WHERE user_id = _user_id
    AND created_at >= date_trunc('month', now())
    AND status != 'error'
    AND (
      status != 'pending'
      OR created_at >= NOW() - INTERVAL '5 minutes'
    );

  IF v_unlimited THEN
    RETURN jsonb_build_object(
      'allowed', true, 'used', v_used, 'limit', -1, 'remaining', -1, 'unlimited', true
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed', v_used < v_limit,
    'used', v_used,
    'limit', v_limit,
    'remaining', greatest(0, v_limit - v_used),
    'unlimited', false
  );
END;
$$;


ALTER FUNCTION "public"."check_ai_quota"("_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_auth_throttling"("_email" "text", "_ip" "text") RETURNS TABLE("allowed" boolean, "remaining_seconds" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  recent_failures     INT;
  last_failure_at     TIMESTAMP WITH TIME ZONE;
  lockout_duration    INT;
  elapsed_since_last  INT;
BEGIN
  -- MIGRADO em 2026-06-15: era auth_login_attempts (0 linhas).
  -- Agora lê de login_attempts (canônica). Lógica de throttling idêntica.
  SELECT COUNT(*), MAX(created_at)
    INTO recent_failures, last_failure_at
  FROM public.login_attempts
  WHERE (email = _email OR ip_address = _ip)
    AND success = false
    AND created_at > now() - INTERVAL '15 minutes';

  IF recent_failures < 5 THEN
    RETURN QUERY SELECT true, 0;
    RETURN;
  END IF;

  IF    recent_failures < 10 THEN lockout_duration := 300;
  ELSIF recent_failures < 15 THEN lockout_duration := 900;
  ELSE                             lockout_duration := 3600;
  END IF;

  elapsed_since_last := EXTRACT(EPOCH FROM (now() - last_failure_at))::INT;

  IF elapsed_since_last >= lockout_duration THEN
    RETURN QUERY SELECT true, 0;
  ELSE
    RETURN QUERY SELECT false, (lockout_duration - elapsed_since_last);
  END IF;
END;
$$;


ALTER FUNCTION "public"."check_auth_throttling"("_email" "text", "_ip" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_edge_rate_limit"("p_key" "text", "p_window_ms" integer, "p_max_requests" integer) RETURNS TABLE("allowed" boolean, "remaining" integer, "reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := now();
    v_reset_at TIMESTAMP WITH TIME ZONE;
    v_count INTEGER;
BEGIN
    -- Busca ou cria o registro
    INSERT INTO public.edge_rate_limits (key, count, reset_at)
    VALUES (p_key, 1, v_now + (p_window_ms || ' milliseconds')::interval)
    ON CONFLICT (key) DO UPDATE
    SET 
        count = CASE 
            WHEN public.edge_rate_limits.reset_at < v_now THEN 1 
            ELSE public.edge_rate_limits.count + 1 
        END,
        reset_at = CASE 
            WHEN public.edge_rate_limits.reset_at < v_now THEN v_now + (p_window_ms || ' milliseconds')::interval 
            ELSE public.edge_rate_limits.reset_at 
        END,
        updated_at = v_now
    RETURNING public.edge_rate_limits.count, public.edge_rate_limits.reset_at INTO v_count, v_reset_at;

    RETURN QUERY SELECT 
        v_count <= p_max_requests,
        GREATEST(0, p_max_requests - v_count),
        v_reset_at;
END;
$$;


ALTER FUNCTION "public"."check_edge_rate_limit"("p_key" "text", "p_window_ms" integer, "p_max_requests" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_edge_rate_limit"("p_key" "text", "p_window_ms" integer, "p_max_requests" integer) IS 'Rate limit atômico via UPSERT. Usado pelas edge functions via service_role.';



