CREATE OR REPLACE FUNCTION "public"."check_login_rate_limit"("_email" "text", "_ip" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  _max_failures int := 5;
  _window_minutes int := 15;
  _lockout_minutes int := 5;
  _failed_count int := 0;
  _last_failure timestamptz;
  _last_success timestamptz;
  _lockout_until timestamptz;
BEGIN
  IF _email IS NULL OR length(trim(_email)) = 0 THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'invalid_email',
      'remaining_seconds', 0
    );
  END IF;

  _email := lower(trim(_email));

  SELECT max(created_at) INTO _last_success
  FROM public.login_attempts
  WHERE email = _email AND success = true;

  SELECT count(*), max(created_at)
    INTO _failed_count, _last_failure
  FROM public.login_attempts
  WHERE email = _email
    AND success = false
    AND created_at > now() - (_window_minutes || ' minutes')::interval
    AND (_last_success IS NULL OR created_at > _last_success);

  IF _failed_count >= _max_failures THEN
    _lockout_until := _last_failure + (_lockout_minutes || ' minutes')::interval;
    IF _lockout_until > now() THEN
      RETURN jsonb_build_object(
        'allowed', false,
        'reason', 'rate_limited_email',
        'failed_count', _failed_count,
        'remaining_seconds', ceil(extract(epoch FROM (_lockout_until - now())))::int,
        'lockout_until', _lockout_until
      );
    END IF;
  END IF;

  IF _ip IS NOT NULL AND length(trim(_ip)) > 0 AND _ip <> 'unknown' AND _ip <> 'client' THEN
    SELECT count(*), max(created_at)
      INTO _failed_count, _last_failure
    FROM public.login_attempts
    WHERE ip_address = _ip
      AND success = false
      AND created_at > now() - (_window_minutes || ' minutes')::interval;

    IF _failed_count >= 20 THEN
      _lockout_until := _last_failure + (_lockout_minutes || ' minutes')::interval;
      IF _lockout_until > now() THEN
        RETURN jsonb_build_object(
          'allowed', false,
          'reason', 'rate_limited_ip',
          'failed_count', _failed_count,
          'remaining_seconds', ceil(extract(epoch FROM (_lockout_until - now())))::int,
          'lockout_until', _lockout_until
        );
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'failed_count', _failed_count,
    'remaining_seconds', 0
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'allowed', false,
    'reason', 'rate_limit_check_error',
    'remaining_seconds', 0
  );
END;
$$;


ALTER FUNCTION "public"."check_login_rate_limit"("_email" "text", "_ip" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_login_rate_limit"("_email" "text", "_ip" "text") IS 'RLS-002 audit (2026-05-22): SECURITY DEFINER intencionalmente exposto a anon. Necessário para verificar rate limit ANTES de login. Sem ação adicional necessária.';



CREATE OR REPLACE FUNCTION "public"."check_mcp_abuse_threshold"("_user_id" "uuid", "_ip" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_window INTERVAL := INTERVAL '10 minutes';
  v_threshold INTEGER := 5;
  v_count_user INTEGER := 0;
  v_count_ip INTEGER := 0;
  v_admin RECORD;
  v_already_alerted BOOLEAN := false;
BEGIN
  IF _user_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_count_user
    FROM public.mcp_access_violations
    WHERE user_id = _user_id
      AND created_at >= now() - v_window;
  END IF;

  IF _ip IS NOT NULL AND _ip <> '' THEN
    SELECT COUNT(*) INTO v_count_ip
    FROM public.mcp_access_violations
    WHERE ip_address = _ip
      AND created_at >= now() - v_window;
  END IF;

  IF v_count_user < v_threshold AND v_count_ip < v_threshold THEN
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.admin_audit_log
    WHERE action = 'mcp_abuse_detected'
      AND created_at >= now() - v_window
      AND (
        (details->>'user_id') = _user_id::text
        OR (details->>'ip_address') = _ip
      )
  ) INTO v_already_alerted;

  IF v_already_alerted THEN
    RETURN;
  END IF;

  INSERT INTO public.admin_audit_log (
    user_id, action, resource_type, resource_id,
    ip_address, details, source, status
  ) VALUES (
    COALESCE(_user_id, '00000000-0000-0000-0000-000000000000'::uuid),
    'mcp_abuse_detected',
    'mcp_api_keys',
    NULL,
    _ip,
    jsonb_build_object(
      'user_id', _user_id,
      'ip_address', _ip,
      'window_minutes', 10,
      'threshold', v_threshold,
      'violations_user', v_count_user,
      'violations_ip', v_count_ip
    ),
    'mcp_abuse_detector',
    'denied'
  );

  FOR v_admin IN
    SELECT user_id FROM public.user_roles WHERE role = 'admin'::public.app_role
  LOOP
    INSERT INTO public.workspace_notifications (
      user_id, title, message, type, category, action_url, metadata
    ) VALUES (
      v_admin.user_id,
      'Possível abuso em chaves MCP',
      format(
        'Detectadas %s tentativas bloqueadas em 10 min%s.',
        GREATEST(v_count_user, v_count_ip),
        CASE WHEN _ip IS NOT NULL THEN ' (IP: ' || _ip || ')' ELSE '' END
      ),
      'warning',
      'security',
      '/admin/seguranca',
      jsonb_build_object(
        'event', 'mcp_abuse_detected',
        'user_id', _user_id,
        'ip_address', _ip,
        'violations_user', v_count_user,
        'violations_ip', v_count_ip
      )
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."check_mcp_abuse_threshold"("_user_id" "uuid", "_ip" "text") OWNER TO "postgres";


