CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("_identifier" "text", "_endpoint" "text", "_max_requests" integer DEFAULT 60, "_window_seconds" integer DEFAULT 60, "_block_duration_seconds" integer DEFAULT 3600) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _row record;
  _now timestamptz := now();
  _window_start timestamptz := _now - make_interval(secs => _window_seconds);
BEGIN
  INSERT INTO public.request_rate_limits (identifier, endpoint, request_count, window_start)
  VALUES (_identifier, _endpoint, 1, _now)
  ON CONFLICT (identifier, endpoint) DO UPDATE
  SET 
    request_count = CASE 
      WHEN request_rate_limits.window_start < _window_start THEN 1
      ELSE request_rate_limits.request_count + 1
    END,
    window_start = CASE
      WHEN request_rate_limits.window_start < _window_start THEN _now
      ELSE request_rate_limits.window_start
    END,
    blocked_until = CASE
      WHEN request_rate_limits.blocked_until IS NOT NULL AND request_rate_limits.blocked_until > _now 
        THEN request_rate_limits.blocked_until
      WHEN request_rate_limits.window_start >= _window_start AND request_rate_limits.request_count + 1 > _max_requests
        THEN _now + make_interval(secs => _block_duration_seconds)
      ELSE NULL
    END,
    updated_at = _now
  RETURNING * INTO _row;

  IF _row.blocked_until IS NOT NULL AND _row.blocked_until > _now THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'blocked',
      'blocked_until', _row.blocked_until,
      'retry_after_seconds', EXTRACT(EPOCH FROM (_row.blocked_until - _now))::integer);
  END IF;

  IF _row.request_count > _max_requests THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'rate_exceeded',
      'count', _row.request_count, 'limit', _max_requests,
      'retry_after_seconds', _block_duration_seconds);
  END IF;

  RETURN jsonb_build_object('allowed', true, 'count', _row.request_count,
    'limit', _max_requests, 'remaining', GREATEST(_max_requests - _row.request_count, 0));
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("_identifier" "text", "_endpoint" "text", "_max_requests" integer, "_window_seconds" integer, "_block_duration_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_telemetry_regression"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  current_window_start timestamptz := now() - interval '2 hours';
  baseline_window_start timestamptz := now() - interval '26 hours';
  baseline_window_end timestamptz := now() - interval '24 hours';
  cur_samples int := 0; cur_p95 numeric := 0; cur_avg numeric := 0;
  cur_errors int := 0; cur_very_slow int := 0; cur_error_rate numeric := 0;
  base_samples int := 0; base_p95 numeric := 0; base_error_rate numeric := 0; base_very_slow int := 0;
  p95_delta_pct numeric := 0; error_rate_delta_pp numeric := 0; very_slow_ratio numeric := 1;
  status text := 'ok'; reasons jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RETURN jsonb_build_object('error', 'forbidden');
  END IF;
  SELECT count(*), COALESCE(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY duration_ms), 0),
    COALESCE(AVG(duration_ms), 0), count(*) FILTER (WHERE severity = 'error'),
    count(*) FILTER (WHERE severity = 'very_slow')
  INTO cur_samples, cur_p95, cur_avg, cur_errors, cur_very_slow
  FROM public.query_telemetry WHERE created_at >= current_window_start AND cache_hit = false;
  cur_error_rate := CASE WHEN cur_samples > 0 THEN ROUND(100.0 * cur_errors / cur_samples, 2) ELSE 0 END;
  SELECT count(*), COALESCE(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY duration_ms), 0),
    CASE WHEN count(*) > 0 THEN ROUND(100.0 * count(*) FILTER (WHERE severity = 'error') / count(*), 2) ELSE 0 END,
    count(*) FILTER (WHERE severity = 'very_slow')
  INTO base_samples, base_p95, base_error_rate, base_very_slow
  FROM public.query_telemetry WHERE created_at >= baseline_window_start AND created_at < baseline_window_end AND cache_hit = false;
  IF cur_samples < 5 OR base_samples < 5 THEN
    RETURN jsonb_build_object('status', 'insufficient_data',
      'reasons', jsonb_build_array(format('Amostras insuficientes (atual=%s, baseline=%s)', cur_samples, base_samples)),
      'current', jsonb_build_object('samples', cur_samples, 'p95_ms', cur_p95, 'error_rate_pct', cur_error_rate, 'very_slow', cur_very_slow),
      'baseline', jsonb_build_object('samples', base_samples, 'p95_ms', base_p95, 'error_rate_pct', base_error_rate, 'very_slow', base_very_slow),
      'checked_at', now());
  END IF;
  p95_delta_pct := CASE WHEN base_p95 > 0 THEN ROUND(100.0 * (cur_p95 - base_p95) / base_p95, 1) ELSE 0 END;
  error_rate_delta_pp := ROUND(cur_error_rate - base_error_rate, 2);
  very_slow_ratio := CASE WHEN base_very_slow > 0 THEN ROUND(cur_very_slow::numeric / base_very_slow, 2)
                          ELSE CASE WHEN cur_very_slow > 0 THEN 999 ELSE 1 END END;
  IF p95_delta_pct > 50 THEN
    status := 'regression';
    reasons := reasons || jsonb_build_array(format('Latência P95 piorou %s%% (atual %sms vs baseline %sms)', p95_delta_pct, ROUND(cur_p95)::int, ROUND(base_p95)::int));
  END IF;
  IF error_rate_delta_pp > 5 THEN
    status := 'regression';
    reasons := reasons || jsonb_build_array(format('Taxa de erro subiu %spp', error_rate_delta_pp));
  END IF;
  IF very_slow_ratio > 2 AND cur_very_slow >= 3 THEN
    status := 'regression';
    reasons := reasons || jsonb_build_array(format('Queries muito lentas %sx baseline', very_slow_ratio));
  END IF;
  IF status = 'ok' THEN
    IF p95_delta_pct > 25 THEN
      status := 'warning';
      reasons := reasons || jsonb_build_array(format('Latência P95 subiu %s%%', p95_delta_pct));
    END IF;
    IF error_rate_delta_pp > 2 THEN
      status := 'warning';
      reasons := reasons || jsonb_build_array(format('Taxa de erro subiu %spp', error_rate_delta_pp));
    END IF;
  END IF;
  RETURN jsonb_build_object('status', status, 'reasons', reasons,
    'current', jsonb_build_object('samples', cur_samples, 'p95_ms', ROUND(cur_p95)::int, 'avg_ms', ROUND(cur_avg)::int, 'error_rate_pct', cur_error_rate, 'very_slow', cur_very_slow),
    'baseline', jsonb_build_object('samples', base_samples, 'p95_ms', ROUND(base_p95)::int, 'error_rate_pct', base_error_rate, 'very_slow', base_very_slow),
    'deltas', jsonb_build_object('p95_delta_pct', p95_delta_pct, 'error_rate_delta_pp', error_rate_delta_pp, 'very_slow_ratio', very_slow_ratio),
    'checked_at', now());
END; $$;


ALTER FUNCTION "public"."check_telemetry_regression"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_video_health"() RETURNS TABLE("categoria" "text", "metrica" "text", "valor" "text", "status" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Total de vídeos
    RETURN QUERY
    SELECT 'GERAL'::TEXT, 'Total de vídeos'::TEXT,
           COUNT(*)::TEXT, '📊'::TEXT
    FROM product_videos WHERE is_active = true;
    
    -- Vídeos prontos no Cloudflare
    RETURN QUERY
    SELECT 'CLOUDFLARE'::TEXT, 'Vídeos prontos (ready)'::TEXT,
           COUNT(*)::TEXT,
           CASE WHEN COUNT(*) > 0 THEN '✅' ELSE '⚠️' END::TEXT
    FROM product_videos 
    WHERE is_active = true AND cloudflare_status = 'ready';
    
    -- Vídeos com erro
    RETURN QUERY
    SELECT 'CLOUDFLARE'::TEXT, 'Vídeos com erro'::TEXT,
           COUNT(*)::TEXT,
           CASE WHEN COUNT(*) = 0 THEN '✅' ELSE '❌' END::TEXT
    FROM product_videos 
    WHERE is_active = true AND cloudflare_status = 'error';
    
    -- Vídeos pendentes
    RETURN QUERY
    SELECT 'CLOUDFLARE'::TEXT, 'Vídeos pendentes'::TEXT,
           COUNT(*)::TEXT,
           CASE WHEN COUNT(*) = 0 THEN '✅' ELSE '⏳' END::TEXT
    FROM product_videos 
    WHERE is_active = true AND cloudflare_status IN ('pending', 'uploading', 'processing');
    
    -- Produtos com vídeo
    RETURN QUERY
    SELECT 'COBERTURA'::TEXT, 'Produtos com vídeo'::TEXT,
           COUNT(DISTINCT product_id)::TEXT, '📹'::TEXT
    FROM product_videos 
    WHERE is_active = true AND cloudflare_status = 'ready';
    
    -- Produtos sem vídeo
    RETURN QUERY
    SELECT 'COBERTURA'::TEXT, 'Produtos SEM vídeo'::TEXT,
           COUNT(*)::TEXT,
           CASE WHEN COUNT(*) = 0 THEN '✅' ELSE '📋' END::TEXT
    FROM products p
    WHERE p.is_active = true
      AND NOT EXISTS (
        SELECT 1 FROM product_videos pv 
        WHERE pv.product_id = p.id AND pv.is_active = true
      );
    
    -- Vídeos sem duração
    RETURN QUERY
    SELECT 'QUALIDADE'::TEXT, 'Vídeos sem duração'::TEXT,
           COUNT(*)::TEXT,
           CASE WHEN COUNT(*) = 0 THEN '✅' ELSE '⚠️' END::TEXT
    FROM product_videos 
    WHERE is_active = true AND duration_seconds IS NULL;
    
    -- Vídeos Full HD
    RETURN QUERY
    SELECT 'QUALIDADE'::TEXT, 'Vídeos Full HD (1080p+)'::TEXT,
           COUNT(*)::TEXT, '🎬'::TEXT
    FROM product_videos 
    WHERE is_active = true AND width_px >= 1920;
    
    -- Tipos configurados
    RETURN QUERY
    SELECT 'CONFIG'::TEXT, 'Tipos de vídeo'::TEXT,
           COUNT(*)::TEXT,
           CASE WHEN COUNT(*) >= 10 THEN '✅' ELSE '⚠️' END::TEXT
    FROM video_types WHERE is_active = true;
    
    RETURN;
END;
$$;


ALTER FUNCTION "public"."check_video_health"() OWNER TO "postgres";

