CREATE OR REPLACE FUNCTION "public"."classify_sacochila"("product_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_name TEXT;
    v_id UUID;
    v_slug TEXT;
    v_mat TEXT;
