CREATE OR REPLACE FUNCTION "public"."complete_optimization"("_id" "uuid", "_status" "text", "_notes" "text" DEFAULT NULL::"text", "_guardrail_status" "text" DEFAULT NULL::"text", "_result" "jsonb" DEFAULT NULL::"jsonb", "_error" "text" DEFAULT NULL::"text") RETURNS "public"."optimization_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  updated public.optimization_queue;
  duration int;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF _status NOT IN ('done','failed','skipped','blocked') THEN
    RAISE EXCEPTION 'invalid status: %', _status;
  END IF;
  UPDATE public.optimization_queue
     SET status = _status,
         finished_at = now(),
         result = COALESCE(_result, result),
         error = _error,
         guardrail_status = COALESCE(_guardrail_status, guardrail_status)
   WHERE id = _id
   RETURNING * INTO updated;
  IF updated.id IS NULL THEN
    RAISE EXCEPTION 'optimization not found';
  END IF;
  duration := EXTRACT(EPOCH FROM (updated.finished_at - COALESCE(updated.started_at, updated.finished_at))) * 1000;
  INSERT INTO public.optimization_queue_runs (queue_id, status, notes, guardrail_status, duration_ms, executed_by)
  VALUES (_id, _status, _notes, _guardrail_status, duration, auth.uid());
  RETURN updated;
END;
$$;


ALTER FUNCTION "public"."complete_optimization"("_id" "uuid", "_status" "text", "_notes" "text", "_guardrail_status" "text", "_result" "jsonb", "_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_xbz_image_import"("p_staging_id" "uuid", "p_cloudflare_id" character varying, "p_product_id" "uuid" DEFAULT NULL::"uuid", "p_variant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_staging RECORD;
    v_image_id UUID;
    v_cloudflare_url TEXT;
BEGIN
    SELECT * INTO v_staging 
    FROM xbz_image_import_staging 
    WHERE id = p_staging_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Staging record not found: %', p_staging_id;
    END IF;
    
    v_cloudflare_url := format(
        'https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/%s/public',
        p_cloudflare_id
    );
    
    INSERT INTO product_images (
        product_id,
        variant_id,
        cloudflare_image_id,
        url_cdn,
        url_original,
        filename,
        format,
        image_type,
        image_type_id,
        is_primary,
        is_active,
        source_supplier,
        supplier_code,
        created_at
    ) VALUES (
        COALESCE(p_product_id, v_staging.product_id),
        COALESCE(p_variant_id, v_staging.variant_id),
        p_cloudflare_id,
        v_cloudflare_url,
        v_staging.original_url,
        v_staging.filename,
        'jpg',
        v_staging.image_type,
        (SELECT id FROM image_types WHERE code = v_staging.image_type LIMIT 1),
        (v_staging.image_type = 'main'),
        true,
        'XBZ',
        'XBZ',
        NOW()
    ) RETURNING id INTO v_image_id;
    
    UPDATE xbz_image_import_staging SET
        cloudflare_id = p_cloudflare_id,
        cloudflare_url = v_cloudflare_url,
        product_id = COALESCE(p_product_id, product_id),
        variant_id = COALESCE(p_variant_id, variant_id),
        product_image_id = v_image_id,
        status = 'completed',
        processed_at = NOW()
    WHERE id = p_staging_id;
    
    RETURN v_image_id;
END;
$$;


ALTER FUNCTION "public"."complete_xbz_image_import"("p_staging_id" "uuid", "p_cloudflare_id" character varying, "p_product_id" "uuid", "p_variant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_quote_snapshot_hash"("_quote_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _hash_input text;
  _quote_data text;
  _items_data text;
  _personalizations_data text;
BEGIN
  SELECT 
    COALESCE(client_id::text, '') || '|' ||
    COALESCE(client_name, '') || '|' ||
    COALESCE(subtotal::text, '0') || '|' ||
    COALESCE(discount_percent::text, '0') || '|' ||
    COALESCE(discount_amount::text, '0') || '|' ||
    COALESCE(negotiation_markup_percent::text, '0') || '|' ||
    COALESCE(total::text, '0')
  INTO _quote_data
  FROM public.quotes
  WHERE id = _quote_id;

  -- FIX QBP-02: usa product_id + sort_order como chave estável (sem qi.id volátil)
  SELECT COALESCE(string_agg(
    COALESCE(qi.product_id::text, '') || ':' ||
    COALESCE(qi.product_sku, '') || ':' ||
    COALESCE(qi.quantity::text, '0') || ':' ||
    COALESCE(qi.unit_price::text, '0') || ':' ||
    COALESCE(qi.subtotal::text, '0'),
    '|' ORDER BY qi.sort_order, qi.product_id
  ), '') INTO _items_data
  FROM public.quote_items qi
  WHERE qi.quote_id = _quote_id;

  -- FIX QBP-02: personalizations sem qip.id
  SELECT COALESCE(string_agg(
    COALESCE(qip.technique_id::text, '') || ':' ||
    COALESCE(qip.colors_count::text, '0') || ':' ||
    COALESCE(qip.positions_count::text, '0') || ':' ||
    COALESCE(qip.total_cost::text, '0'),
    '|' ORDER BY qi.sort_order, qip.technique_id
  ), '') INTO _personalizations_data
  FROM public.quote_item_personalizations qip
  JOIN public.quote_items qi ON qi.id = qip.quote_item_id
  WHERE qi.quote_id = _quote_id;

  _hash_input := COALESCE(_quote_data, '') || '||' || 
                 COALESCE(_items_data, '') || '||' || 
                 COALESCE(_personalizations_data, '');

  RETURN encode(extensions.digest(_hash_input, 'sha1'), 'hex');
END;
$$;


ALTER FUNCTION "public"."compute_quote_snapshot_hash"("_quote_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_quote_snapshot_hash"("_quote_id" "uuid") IS 'FIX QBP-02 (2026-06-22): Removidos qi.id e qip.id do hash — UUIDs eram regenerados no update_quote_transactional (delete+reinsert), invalidando aprovações mesmo sem mudanças financeiras.';



