CREATE OR REPLACE FUNCTION "public"."consolidate_variant_stock"("p_variant_id" "uuid") RETURNS TABLE("variant_id" "uuid", "previous_stock" integer, "new_stock" integer, "supplier_count" bigint, "suppliers_detail" "jsonb")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_previous INTEGER;
    v_new INTEGER;
    v_supplier_count BIGINT;
    v_detail JSONB;
    v_product_id UUID;
BEGIN
    -- Obter estoque anterior e product_id
    SELECT pv.stock_quantity, pv.product_id INTO v_previous, v_product_id
    FROM product_variants pv
    WHERE pv.id = p_variant_id;
    
    -- Calcular novo estoque agregado
    SELECT 
        COALESCE(SUM(vss.quantity), 0)::INTEGER,
        COUNT(*)::BIGINT,
        COALESCE(jsonb_agg(
            jsonb_build_object(
                'supplier_id', vss.supplier_id,
                'quantity', vss.quantity,
                'is_active', vss.is_active
            )
        ), '[]'::jsonb)
    INTO v_new, v_supplier_count, v_detail
    FROM variant_supplier_sources vss
    WHERE vss.variant_id = p_variant_id
      AND vss.is_active = true;
    
    -- Atualizar product_variants
    UPDATE product_variants pv
    SET 
        stock_quantity = v_new,
        updated_at = NOW()
    WHERE pv.id = p_variant_id;
    
    -- Também atualizar o produto pai se existir
    IF v_product_id IS NOT NULL THEN
        UPDATE products p
        SET 
            stock_quantity = (
                SELECT COALESCE(SUM(pv2.stock_quantity), 0)
                FROM product_variants pv2
                WHERE pv2.product_id = v_product_id AND pv2.is_active = true
            ),
            is_stockout = (
                SELECT COALESCE(SUM(pv2.stock_quantity), 0) = 0
                FROM product_variants pv2
                WHERE pv2.product_id = v_product_id AND pv2.is_active = true
            ),
            last_stock_update_at = NOW(),
            updated_at = NOW()
        WHERE p.id = v_product_id;
    END IF;
    
    RETURN QUERY SELECT 
        p_variant_id,
        COALESCE(v_previous, 0),
        COALESCE(v_new, 0),
        COALESCE(v_supplier_count, 0),
        COALESCE(v_detail, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."consolidate_variant_stock"("p_variant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."consolidate_variant_stock"("p_variant_id" "uuid") IS 'Recalcula e consolida o estoque de uma variante específica.';



CREATE OR REPLACE FUNCTION "public"."consume_step_up_token"("_token" "text", "_expected_action" "public"."step_up_action", "_expected_target" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid UUID := auth.uid();
  _token_h TEXT;
  _row RECORD;
BEGIN
  IF _uid IS NULL THEN RETURN false; END IF;
  IF _token IS NULL OR length(_token) < 32 THEN RETURN false; END IF;

  IF NOT public.is_dev(_uid) THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, metadata)
    VALUES (_uid, _expected_action, _expected_target, 'unauthorized', '{"reason":"role_lost_at_consume"}'::jsonb);
    RETURN false;
  END IF;

  _token_h := encode(digest(_token, 'sha256'), 'hex');

  SELECT * INTO _row FROM public.step_up_tokens
  WHERE token_hash = _token_h AND user_id = _uid AND consumed = false AND expires_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, metadata)
    VALUES (_uid, _expected_action, _expected_target, 'failed', '{"reason":"token_invalid_or_expired"}'::jsonb);
    RETURN false;
  END IF;

  IF _row.action <> _expected_action THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, token_id, metadata)
    VALUES (_uid, _expected_action, _expected_target, 'failed', _row.id, jsonb_build_object('reason','action_mismatch','expected',_expected_action,'got',_row.action));
    RETURN false;
  END IF;

  IF _expected_target IS NOT NULL AND _row.target_ref IS DISTINCT FROM _expected_target THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, token_id, metadata)
    VALUES (_uid, _expected_action, _expected_target, 'failed', _row.id, '{"reason":"target_mismatch"}'::jsonb);
    RETURN false;
  END IF;

  UPDATE public.step_up_tokens SET consumed = true, consumed_at = now() WHERE id = _row.id;

  INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, token_id)
  VALUES (_uid, _expected_action, _expected_target, 'token_consumed', _row.id);

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."consume_step_up_token"("_token" "text", "_expected_action" "public"."step_up_action", "_expected_target" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_quote_to_order"("p_quote_id" "uuid", "p_seller_id" "uuid", "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quote       RECORD;
  v_order_id    UUID;
  v_order_number TEXT;
  v_item        RECORD;
  v_new_item_id UUID;
  v_actor_id    UUID;
BEGIN
  -- ── 0. Auth check explícito (além do RLS implícito via SELECT abaixo) ────
  -- Em contexto service_role (automações internas) a checagem é dispensada.
  IF current_setting('request.jwt.claim.role', true) <> 'service_role' AND auth.uid() IS NOT NULL THEN
    IF auth.uid() <> p_seller_id AND NOT public.is_coord_or_above(auth.uid()) THEN
      RAISE EXCEPTION
        'Sem permissão: apenas o vendedor responsável ou um coordenador pode converter este orçamento'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- ── 1. Carrega o orçamento (RLS aplicado — SECURITY INVOKER) ─────────────
  SELECT * INTO v_quote FROM public.quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Orçamento não encontrado'; END IF;
  IF v_quote.status != 'approved' THEN
    RAISE EXCEPTION 'Apenas orçamentos aprovados podem ser convertidos';
  END IF;
  IF EXISTS (SELECT 1 FROM public.orders WHERE quote_id = p_quote_id) THEN
    RAISE EXCEPTION 'Este orçamento já foi convertido em pedido';
  END IF;

  -- ── 2. Cria o pedido ──────────────────────────────────────────────────────
  INSERT INTO public.orders (
    seller_id, organization_id, quote_id, client_id, client_name, client_email,
    client_phone, client_company, subtotal, discount_amount, shipping_cost,
    shipping_type, total, payment_terms, delivery_time, notes, internal_notes,
    status, fulfillment_status
  ) VALUES (
    p_seller_id,
    COALESCE(p_organization_id, v_quote.organization_id),
    p_quote_id,
    v_quote.client_id, v_quote.client_name, v_quote.client_email,
    v_quote.client_phone, v_quote.client_company,
    v_quote.subtotal, v_quote.discount_amount, v_quote.shipping_cost,
    v_quote.shipping_type, v_quote.total, v_quote.payment_terms,
    v_quote.delivery_time, v_quote.notes, v_quote.internal_notes,
    'confirmed', 'pending'
  ) RETURNING id, order_number INTO v_order_id, v_order_number;

  -- ── 3. Copia itens ────────────────────────────────────────────────────────
  FOR v_item IN SELECT * FROM public.quote_items WHERE quote_id = p_quote_id LOOP
    INSERT INTO public.order_items (
      order_id, quote_item_id, product_id, product_sku, product_name,
      product_image_url, quantity, unit_price, subtotal,
      discount_amount, personalization_cost
    ) VALUES (
      v_order_id, v_item.id, v_item.product_id, v_item.product_sku, v_item.product_name,
      v_item.product_image_url, v_item.quantity, v_item.unit_price, v_item.subtotal,
      COALESCE(v_item.discount_amount, 0), COALESCE(v_item.personalization_cost, 0)
    ) RETURNING id INTO v_new_item_id;
  END LOOP;

  -- ── 4. Atualiza status do orçamento ───────────────────────────────────────
  UPDATE public.quotes
  SET    status = 'converted',
         converted_to_order_id = v_order_id,
         converted_at = now()
  WHERE  id = p_quote_id;

  -- ── 5. Audit trail ────────────────────────────────────────────────────────
  v_actor_id := COALESCE(auth.uid(), p_seller_id);
  IF v_actor_id IS NOT NULL THEN
    INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
    VALUES (
      p_quote_id,
      v_actor_id,
      'converted',
      format('Orçamento %s convertido em pedido %s',
             v_quote.quote_number, v_order_number),
      jsonb_build_object(
        'order_id',     v_order_id,
        'order_number', v_order_number,
        'total',        v_quote.total,
        'n_items',      (SELECT count(*) FROM public.order_items WHERE order_id = v_order_id)
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'id',           v_order_id,
    'order_number', v_order_number,
    'status',       'confirmed',
    'total',        v_quote.total
  );
END;
$$;


ALTER FUNCTION "public"."convert_quote_to_order"("p_quote_id" "uuid", "p_seller_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_string_to_unit"("p_input" "text", "p_target_unit" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_parsed RECORD;
BEGIN
    SELECT * INTO v_parsed FROM parse_unit_from_string(p_input);
    
    IF v_parsed.valor IS NULL THEN
        RETURN NULL;
    END IF;
    
    RETURN normalize_unit(v_parsed.valor, v_parsed.unidade, p_target_unit);
END;
$$;


