COMMENT ON FUNCTION "public"."convert_string_to_unit"("p_input" "text", "p_target_unit" "text") IS 'Converte string com unidade para outra unidade. Ex: convert_string_to_unit(''0,35kg'', ''g'') → 350';



CREATE TABLE IF NOT EXISTS "public"."quotes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "quote_number" "text" NOT NULL,
    "client_id" "uuid",
    "client_name" "text" NOT NULL,
    "created_by" "uuid",
    "assigned_to" "uuid",
    "status" "text" DEFAULT 'draft'::"text",
    "stage" "text" DEFAULT 'elaboration'::"text",
    "priority" "text" DEFAULT 'normal'::"text",
    "subtotal" numeric(10,2) DEFAULT 0,
    "discount_amount" numeric(10,2) DEFAULT 0,
    "shipping_cost" numeric(10,2) DEFAULT 0,
    "tax_amount" numeric(10,2) DEFAULT 0,
    "total" numeric(10,2) DEFAULT 0,
    "valid_until" "date",
    "estimated_delivery_days" integer,
    "notes" "text",
    "internal_notes" "text",
    "payment_terms" "text",
    "tags" "jsonb" DEFAULT '[]'::"jsonb",
    "approval_token" "text",
    "approved_at" timestamp with time zone,
    "approved_by_client_name" "text",
    "client_feedback" "text",
    "viewed_at" timestamp with time zone,
    "view_count" integer DEFAULT 0,
    "last_sent_at" timestamp with time zone,
    "converted_to_order_id" "uuid",
    "converted_at" timestamp with time zone,
    "conversion_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "organization_id" "uuid" NOT NULL,
    "seller_id" "uuid" NOT NULL,
    "discount_percent" numeric(5,2) DEFAULT 0,
    "negotiation_markup_percent" numeric(5,2) DEFAULT 0,
    "real_subtotal" numeric(10,2) DEFAULT 0,
    "real_discount_percent" numeric(5,2) DEFAULT 0,
    "version" integer DEFAULT 1 NOT NULL,
    "client_email" "text",
    "client_phone" "text",
    "client_company" "text",
    "client_cnpj" "text",
    "delivery_time" "text",
    "shipping_type" "text",
    "bitrix_deal_id" "text",
    "bitrix_quote_id" "text",
    "synced_to_bitrix" boolean DEFAULT false NOT NULL,
    "synced_at" timestamp with time zone,
    "client_response" "text",
    "client_response_at" timestamp with time zone,
    "client_response_notes" "text",
    "shipping_method" "text",
    "parent_quote_id" "uuid",
    "is_latest_version" boolean DEFAULT true NOT NULL,
    "payment_method" "text",
    "sent_at" timestamp with time zone,
    "contact_id" "uuid",
    "discount_approval_status" "text",
    "discount_approved_at" timestamp with time zone,
    CONSTRAINT "chk_quotes_discount_approval_status" CHECK ((("discount_approval_status" IS NULL) OR ("discount_approval_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'expired'::"text"])))),
    CONSTRAINT "valid_discount_amount_nonnegative" CHECK ((("discount_amount" IS NULL) OR ("discount_amount" >= (0)::numeric))),
    CONSTRAINT "valid_discount_percent_range" CHECK ((("discount_percent" IS NULL) OR (("discount_percent" >= (0)::numeric) AND ("discount_percent" <= (100)::numeric)))),
    CONSTRAINT "valid_negotiation_markup_range" CHECK ((("negotiation_markup_percent" IS NULL) OR (("negotiation_markup_percent" >= (0)::numeric) AND ("negotiation_markup_percent" <= (50)::numeric)))),
    CONSTRAINT "valid_priority" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "valid_quote_status" CHECK (("status" = ANY (ARRAY['draft'::"text", 'pending'::"text", 'pending_approval'::"text", 'sent'::"text", 'viewed'::"text", 'approved'::"text", 'converted'::"text", 'rejected'::"text", 'expired'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "valid_real_discount_pct_max" CHECK ((("real_discount_percent" IS NULL) OR ("real_discount_percent" <= (100)::numeric))),
    CONSTRAINT "valid_shipping_cost_nonnegative" CHECK ((("shipping_cost" IS NULL) OR ("shipping_cost" >= (0)::numeric))),
    CONSTRAINT "valid_shipping_type" CHECK ((("shipping_type" IS NULL) OR ("shipping_type" = ANY (ARRAY['cif'::"text", 'fob'::"text", 'fob_pre'::"text"])))),
    CONSTRAINT "valid_subtotal_nonnegative" CHECK ((("subtotal" IS NULL) OR ("subtotal" >= (0)::numeric))),
    CONSTRAINT "valid_total_nonnegative" CHECK ((("total" IS NULL) OR ("total" >= (0)::numeric))),
    CONSTRAINT "valid_until_not_expired_for_active" CHECK ((("status" = ANY (ARRAY['draft'::"text", 'expired'::"text", 'cancelled'::"text", 'rejected'::"text", 'converted'::"text"])) OR ("valid_until" IS NULL) OR ("valid_until" >= CURRENT_DATE)))
);

