CREATE OR REPLACE FUNCTION "public"."create_kit_quote_transactional"("_request_id" "uuid", "_quote" "jsonb", "_items" "jsonb") RETURNS "public"."quotes"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  _actor_id uuid := auth.uid();
  _payload_hash text;
  _existing public.kit_quote_requests%ROWTYPE;
  _quote_result public.quotes;
  _item jsonb;
  _ordinality bigint;
  _variant_id uuid;
  _product_id uuid;
  _artwork_urls jsonb;
  _updated_count integer;
BEGIN
  IF _actor_id IS NULL THEN
    RAISE EXCEPTION 'Authentication is required to create a Kit Maker quote'
      USING ERRCODE = '28000';
  END IF;

  IF _request_id IS NULL THEN
    RAISE EXCEPTION 'A request id is required for idempotent quote creation'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(_quote) IS DISTINCT FROM 'object'
     OR jsonb_typeof(_items) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Invalid quote payload'
      USING ERRCODE = '22023';
  END IF;

  IF _quote ? 'tags' AND jsonb_typeof(_quote->'tags') <> 'object' THEN
    RAISE EXCEPTION 'Kit Maker quote tags must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  _payload_hash := md5(_quote::text || E'\n' || _items::text);

  -- Serializes equal request ids before the underlying writer is invoked.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(_actor_id::text || ':' || _request_id::text, 0)
  );

  SELECT *
  INTO _existing
  FROM public.kit_quote_requests
  WHERE request_id = _request_id
    AND user_id = _actor_id;

  IF FOUND THEN
    IF _existing.payload_hash <> _payload_hash THEN
      RAISE EXCEPTION 'The request id was already used with a different payload'
        USING ERRCODE = '22023';
    END IF;

    SELECT * INTO _quote_result
    FROM public.quotes
    WHERE id = _existing.quote_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Idempotency ledger references a missing quote'
        USING ERRCODE = '23503';
    END IF;

    RETURN _quote_result;
  END IF;

  SELECT * INTO _quote_result
  FROM public.create_quote_transactional(_quote, _items);

  IF _quote ? 'tags' THEN
    UPDATE public.quotes
    SET tags = _quote->'tags'
    WHERE id = _quote_result.id;
  END IF;

  FOR _item, _ordinality IN
    SELECT value, ordinality
    FROM jsonb_array_elements(_items) WITH ORDINALITY
  LOOP
    IF _item ? 'artwork_urls' AND jsonb_typeof(_item->'artwork_urls') <> 'array' THEN
      RAISE EXCEPTION 'artwork_urls must be a JSON array'
        USING ERRCODE = '22023';
    END IF;

    _product_id := nullif(_item->>'product_id', '')::uuid;
    _variant_id := nullif(_item->>'product_variant_id', '')::uuid;
    _artwork_urls := CASE
      WHEN _item ? 'artwork_urls' THEN _item->'artwork_urls'
      ELSE '[]'::jsonb
    END;

    IF _variant_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.product_variants variant
      WHERE variant.id = _variant_id
        AND variant.product_id = _product_id
    ) THEN
      RAISE EXCEPTION 'Selected variant does not belong to the quoted product'
        USING ERRCODE = '23503';
    END IF;

    UPDATE public.quote_items
    SET artwork_urls = _artwork_urls,
        product_variant_id = _variant_id
    WHERE quote_id = _quote_result.id
      AND sort_order = coalesce(nullif(_item->>'sort_order', '')::integer, _ordinality::integer - 1)
      AND product_id IS NOT DISTINCT FROM _product_id;

    GET DIAGNOSTICS _updated_count = ROW_COUNT;
    IF _updated_count <> 1 THEN
      RAISE EXCEPTION 'Kit Maker quote lineage could not match exactly one quote item (sort order %, product %)',
        coalesce(nullif(_item->>'sort_order', '')::integer, _ordinality::integer - 1),
        _product_id
        USING ERRCODE = '23505';
    END IF;
  END LOOP;

  INSERT INTO public.kit_quote_requests (request_id, user_id, quote_id, payload_hash)
  VALUES (_request_id, _actor_id, _quote_result.id, _payload_hash);

  RETURN _quote_result;
END;
$$;


ALTER FUNCTION "public"."create_kit_quote_transactional"("_request_id" "uuid", "_quote" "jsonb", "_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_kit_quote_transactional"("_request_id" "uuid", "_quote" "jsonb", "_items" "jsonb") IS 'Idempotent Kit Maker quote writer; persists Kit context, artwork URLs and the selected catalog variant.';



CREATE OR REPLACE FUNCTION "public"."create_material_with_equivalence"("p_supplier_id" "uuid", "p_material_key" "text", "p_material_name" "text", "p_material_group" "text" DEFAULT NULL::"text", "p_force_type_slug" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_supplier_material_id UUID;
    v_material_type_id UUID;
    v_material_group_id UUID;
    v_matched_slug TEXT;
    v_confidence NUMERIC;
    v_normalized_name TEXT;
    v_result JSONB;
    v_supplier_code TEXT;
BEGIN
    -- Buscar código do fornecedor
    SELECT code INTO v_supplier_code FROM suppliers WHERE id = p_supplier_id;
    
    IF v_supplier_code IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Fornecedor não encontrado',
            'supplier_id', p_supplier_id
        );
    END IF;

    -- ========================================================================
    -- PASSO 1: Criar ou buscar supplier_material
    -- ========================================================================
    SELECT id INTO v_supplier_material_id
    FROM supplier_materials
    WHERE supplier_id = p_supplier_id AND api_material_key = p_material_key;
    
    IF v_supplier_material_id IS NULL THEN
        INSERT INTO supplier_materials (
            id, supplier_id, api_material_key, api_material_name, 
            api_material_group, created_at, updated_at
        ) VALUES (
            gen_random_uuid(), p_supplier_id, p_material_key, p_material_name,
            p_material_group, NOW(), NOW()
        )
        RETURNING id INTO v_supplier_material_id;
    END IF;

    -- ========================================================================
    -- PASSO 2: Verificar se já existe equivalência
    -- ========================================================================
    IF EXISTS (SELECT 1 FROM material_equivalences WHERE supplier_material_id = v_supplier_material_id) THEN
        SELECT jsonb_build_object(
            'success', true,
            'action', 'already_exists',
            'supplier_material_id', v_supplier_material_id,
            'message', 'Equivalência já existe'
        ) INTO v_result;
        RETURN v_result;
    END IF;

    -- ========================================================================
    -- PASSO 3: Encontrar material_type correspondente
    -- ========================================================================
    
    -- Normalizar nome para busca
    v_normalized_name := LOWER(unaccent(p_material_name));
    
    -- Se foi forçado um slug específico, usar ele
    IF p_force_type_slug IS NOT NULL THEN
        SELECT id, group_id, slug INTO v_material_type_id, v_material_group_id, v_matched_slug
        FROM material_types
        WHERE slug = p_force_type_slug;
        
        v_confidence := 1.0;
    ELSE
        -- Busca inteligente por similaridade
        
        -- Tentativa 1: Match exato por slug normalizado
        SELECT id, group_id, slug INTO v_material_type_id, v_material_group_id, v_matched_slug
        FROM material_types
        WHERE LOWER(unaccent(slug)) = REPLACE(REPLACE(v_normalized_name, ' ', '-'), '|', '-')
           OR LOWER(unaccent(slug)) = REPLACE(v_normalized_name, ' ', '|')
        LIMIT 1;
        
        IF v_material_type_id IS NOT NULL THEN
            v_confidence := 1.0;
        END IF;
        
        -- Tentativa 2: Match por nome contém
        IF v_material_type_id IS NULL THEN
            SELECT id, group_id, slug INTO v_material_type_id, v_material_group_id, v_matched_slug
            FROM material_types
            WHERE LOWER(unaccent(name)) = v_normalized_name
            LIMIT 1;
            
            IF v_material_type_id IS NOT NULL THEN
                v_confidence := 1.0;
            END IF;
        END IF;
        
        -- Tentativa 3: Match parcial (nome contém a palavra principal)
        IF v_material_type_id IS NULL THEN
            SELECT id, group_id, slug INTO v_material_type_id, v_material_group_id, v_matched_slug
            FROM material_types
            WHERE LOWER(unaccent(name)) ILIKE '%' || v_normalized_name || '%'
               OR v_normalized_name ILIKE '%' || LOWER(unaccent(name)) || '%'
            ORDER BY 
                CASE WHEN LOWER(unaccent(name)) = v_normalized_name THEN 0 ELSE 1 END,
                LENGTH(name)
            LIMIT 1;
            
            IF v_material_type_id IS NOT NULL THEN
                v_confidence := 0.90;
            END IF;
        END IF;
        
        -- Tentativa 4: Match por slug parcial
        IF v_material_type_id IS NULL THEN
            SELECT id, group_id, slug INTO v_material_type_id, v_material_group_id, v_matched_slug
            FROM material_types
            WHERE slug ILIKE '%' || SPLIT_PART(v_normalized_name, ' ', 1) || '%'
            ORDER BY LENGTH(slug)
            LIMIT 1;
            
            IF v_material_type_id IS NOT NULL THEN
                v_confidence := 0.80;
            END IF;
        END IF;
        
        -- Tentativa 5: Mapeamentos específicos conhecidos
        IF v_material_type_id IS NULL THEN
            v_matched_slug := CASE 
                WHEN v_normalized_name ILIKE '%pu%' OR v_normalized_name ILIKE '%couro sint%' THEN 'couro|sintetico|ecologico'
                WHEN v_normalized_name ILIKE '%tnt%' THEN 'tnt-nowen'
                WHEN v_normalized_name ILIKE '%canvas%' OR v_normalized_name ILIKE '%lona%' THEN 'lona-nao-resinada'
                WHEN v_normalized_name ILIKE '%papel%' AND v_normalized_name NOT ILIKE '%kraft%' THEN 'offset'
                WHEN v_normalized_name ILIKE '%papelao%' OR v_normalized_name ILIKE '%cartao%' THEN 'cartao'
                WHEN v_normalized_name ILIKE '%plastico%' AND v_normalized_name NOT ILIKE '%pet%' THEN 'plastico|generico'
                WHEN v_normalized_name ILIKE '%pet%' THEN 'plastico-pet'
                WHEN v_normalized_name ILIKE '%metal%' THEN 'metal|generico'
                WHEN v_normalized_name ILIKE '%palha%' OR v_normalized_name ILIKE '%fibra%' THEN 'fibras|naturais'
                WHEN v_normalized_name ILIKE '%inox%' OR v_normalized_name ILIKE '%aco%' THEN 'aco-inox'
                WHEN v_normalized_name ILIKE '%eva%' THEN 'eva-acetato-de-vinila'
                WHEN v_normalized_name ILIKE '%abs%' THEN 'abs-acrilonitrila-butadieno-estireno'
                ELSE NULL
            END;
            
            IF v_matched_slug IS NOT NULL THEN
                SELECT id, group_id INTO v_material_type_id, v_material_group_id
                FROM material_types WHERE slug = v_matched_slug;
                
                v_confidence := 0.85;
            END IF;
        END IF;
    END IF;

    -- ========================================================================
    -- PASSO 4: Criar material_equivalence
    -- ========================================================================
    IF v_material_type_id IS NOT NULL THEN
        INSERT INTO material_equivalences (
            id, supplier_material_id, promo_type_id, promo_group_id,
            match_level, match_quality, confidence_score, notes,
            created_at, updated_at
        ) VALUES (
            gen_random_uuid(), v_supplier_material_id, v_material_type_id, v_material_group_id,
            'type', 'manual', v_confidence,
            v_supplier_code || ' ''' || p_material_name || ''' → ''' || v_matched_slug || '''',
            NOW(), NOW()
        );
        
        v_result := jsonb_build_object(
            'success', true,
            'action', 'created',
            'supplier_material_id', v_supplier_material_id,
            'material_type_id', v_material_type_id,
            'matched_slug', v_matched_slug,
            'confidence', v_confidence,
            'message', 'Material e equivalência criados com sucesso'
        );
    ELSE
        v_result := jsonb_build_object(
            'success', true,
            'action', 'partial',
            'supplier_material_id', v_supplier_material_id,
            'material_type_id', NULL,
            'warning', 'supplier_material criado, mas não foi possível encontrar material_type correspondente',
            'suggestion', 'Use p_force_type_slug para especificar manualmente'
        );
    END IF;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."create_material_with_equivalence"("p_supplier_id" "uuid", "p_material_key" "text", "p_material_name" "text", "p_material_group" "text", "p_force_type_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_material_with_equivalence"("p_supplier_id" "uuid", "p_material_key" "text", "p_material_name" "text", "p_material_group" "text", "p_force_type_slug" "text") IS 'Função universal para criar supplier_material + material_equivalence para qualquer fornecedor.
Usa mapeamento inteligente por similaridade de nome/slug.
Parâmetros:
  - p_supplier_id: UUID do fornecedor
  - p_material_key: Código único (ex: ASIA-POLIESTER)
  - p_material_name: Nome do material
  - p_material_group: Grupo do fornecedor (opcional)
  - p_force_type_slug: Slug específico para forçar mapeamento (opcional)';



CREATE OR REPLACE FUNCTION "public"."create_materials_batch"("p_supplier_id" "uuid", "p_materials" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_material JSONB;
    v_result JSONB;
    v_results JSONB := '[]'::JSONB;
    v_success_count INT := 0;
    v_error_count INT := 0;
BEGIN
    FOR v_material IN SELECT * FROM jsonb_array_elements(p_materials)
    LOOP
        v_result := create_material_with_equivalence(
            p_supplier_id,
            v_material->>'key',
            v_material->>'name',
            v_material->>'group',
            v_material->>'force_slug'
        );
        
        v_results := v_results || jsonb_build_array(v_result);
        
        IF (v_result->>'success')::BOOLEAN THEN
            v_success_count := v_success_count + 1;
        ELSE
            v_error_count := v_error_count + 1;
        END IF;
    END LOOP;
    
    RETURN jsonb_build_object(
        'total', jsonb_array_length(p_materials),
        'success_count', v_success_count,
        'error_count', v_error_count,
        'results', v_results
    );
END;
$$;


ALTER FUNCTION "public"."create_materials_batch"("p_supplier_id" "uuid", "p_materials" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_materials_batch"("p_supplier_id" "uuid", "p_materials" "jsonb") IS 'Processa múltiplos materiais em lote.
Entrada: JSONB array [{key, name, group, force_slug?}, ...]';



CREATE OR REPLACE FUNCTION "public"."create_organization_with_owner"("_name" "text", "_slug" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE _org_id uuid;
BEGIN
  INSERT INTO public.organizations (name, slug) VALUES (_name, _slug)
  RETURNING id INTO _org_id;
  INSERT INTO public.organization_members (organization_id, user_id, role)
  VALUES (_org_id, auth.uid(), 'owner');
  RETURN _org_id;
END;
$$;


ALTER FUNCTION "public"."create_organization_with_owner"("_name" "text", "_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_quote_transactional"("_quote" "jsonb", "_items" "jsonb") RETURNS "public"."quotes"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _new_quote    public.quotes;
  _new_quote_id uuid;
  _item         jsonb;
  _pers         jsonb;
  _new_item_id  uuid;
  _actor_id     uuid;
  _uid          uuid := auth.uid();
  _org_id       uuid := nullif(_quote->>'organization_id', '')::uuid;
  _seller_id    uuid := nullif(_quote->>'seller_id', '')::uuid;
BEGIN
  -- Usuários autenticados só podem usar uma organização à qual pertencem.
  -- Chamadas internas sem auth.uid() preservam os IDs explícitos e continuam
  -- sujeitas ao contexto/RLS do chamador porque a função é SECURITY INVOKER.
  IF _uid IS NOT NULL THEN
    IF _org_id IS NULL OR NOT public.user_is_org_member(_org_id) THEN
      SELECT uo.organization_id
      INTO _org_id
      FROM public.user_organizations uo
      WHERE uo.user_id = _uid
      ORDER BY uo.created_at ASC, uo.organization_id ASC
      LIMIT 1;
    END IF;

    IF _seller_id IS NULL THEN
      _seller_id := _uid;
    END IF;
  END IF;

  IF _org_id IS NULL THEN
    RAISE EXCEPTION 'Não foi possível determinar a organização do orçamento: usuário sem organização vinculada.'
      USING ERRCODE = '23502';
  END IF;

  INSERT INTO public.quotes (
    quote_number, client_id, contact_id,
    client_name, client_email, client_phone, client_company, client_cnpj,
    seller_id, created_by, organization_id, status,
    subtotal, discount_percent, discount_amount, total, negotiation_markup_percent,
    payment_method, payment_terms, delivery_time, shipping_type, shipping_cost,
    notes, internal_notes, valid_until
  )
  VALUES (
    coalesce(_quote->>'quote_number', ''),
    nullif(_quote->>'client_id', '')::uuid,
    nullif(_quote->>'contact_id', '')::uuid,
    coalesce(_quote->>'client_name', ''),
    _quote->>'client_email',
    _quote->>'client_phone',
    _quote->>'client_company',
    nullif(_quote->>'client_cnpj', ''),
    _seller_id,
    coalesce(_uid, _seller_id),
    _org_id,
    coalesce(_quote->>'status', 'draft'),
    coalesce((_quote->>'subtotal')::numeric, 0),
    coalesce((_quote->>'discount_percent')::numeric, 0),
    coalesce((_quote->>'discount_amount')::numeric, 0),
    coalesce((_quote->>'total')::numeric, 0),
    coalesce((_quote->>'negotiation_markup_percent')::numeric, 0),
    _quote->>'payment_method',
    _quote->>'payment_terms',
    _quote->>'delivery_time',
    _quote->>'shipping_type',
    coalesce((_quote->>'shipping_cost')::numeric, 0),
    _quote->>'notes',
    _quote->>'internal_notes',
    nullif(_quote->>'valid_until', '')::date
  )
  RETURNING * INTO _new_quote;

  _new_quote_id := _new_quote.id;

  FOR _item IN
    SELECT value FROM jsonb_array_elements(coalesce(_items, '[]'::jsonb))
  LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days,
      bitrix_product_id, personalization_cost
    )
    VALUES (
      _new_quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', ''),
      coalesce((_item->>'personalization_cost')::numeric, 0)
    )
    RETURNING id INTO _new_item_id;

    FOR _pers IN
      SELECT value
      FROM jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb))
    LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      VALUES (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    END LOOP;
  END LOOP;

  SELECT * INTO _new_quote FROM public.quotes WHERE id = _new_quote_id;

  _actor_id := coalesce(_uid, _seller_id);
  IF _actor_id IS NOT NULL THEN
    INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
    VALUES (
      _new_quote_id,
      _actor_id,
      'created',
      format(
        'Orçamento %s criado com %s item(s) via RPC',
        _new_quote.quote_number,
        (SELECT count(*) FROM public.quote_items WHERE quote_id = _new_quote_id)
      ),
      jsonb_build_object(
        'status', _new_quote.status,
        'subtotal', _new_quote.subtotal,
        'total', _new_quote.total,
        'markup', _new_quote.negotiation_markup_percent,
        'n_items', (SELECT count(*) FROM public.quote_items WHERE quote_id = _new_quote_id)
      )
    );
  END IF;

  RETURN _new_quote;
END;
$$;


ALTER FUNCTION "public"."create_quote_transactional"("_quote" "jsonb", "_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_quote_transactional"("_quote" "jsonb", "_items" "jsonb") IS 'Criação atômica de orçamento; resolve organização autenticada no servidor e preserva custos de personalização.';



CREATE OR REPLACE FUNCTION "public"."create_quote_with_discount_approval_transactional"("_quote" "jsonb", "_items" "jsonb", "_seller_notes" "text" DEFAULT NULL::"text") RETURNS "public"."quotes"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _saved public.quotes;
BEGIN
  _saved := public.create_quote_transactional(_quote, _items);
  PERFORM public.request_discount_approval_transactional(_saved.id, _seller_notes);
  SELECT * INTO STRICT _saved FROM public.quotes WHERE id = _saved.id;
  RETURN _saved;
END;
$$;


