CREATE OR REPLACE FUNCTION "public"."dispatch_quote_webhook_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  _event text;
  _payload jsonb;
BEGIN
  -- Determinar tipo de evento
  IF TG_OP = 'INSERT' THEN
    _event := 'quote.created';
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      _event := 'quote.' || NEW.status;
    ELSE
      RETURN NEW;  -- Sem mudança de status → sem webhook
    END IF;
  ELSE
    RETURN NEW;
  END IF;

  -- Construir payload
  _payload := jsonb_build_object(
    'quote_id',     NEW.id,
    'quote_number', NEW.quote_number,
    'status',       NEW.status,
    'old_status',   OLD.status,
    'seller_id',    NEW.seller_id,
    'client_id',    NEW.client_id,
    'client_name',  NEW.client_name,
    'client_company', NEW.client_company,
    'subtotal',     NEW.subtotal,
    'total',        NEW.total,
    'discount_percent', NEW.discount_percent,
    'valid_until',  NEW.valid_until,
    'event_at',     now()
  );

  -- FIX QBP-05: Inserir na outbox ao invés de http_post síncrono
  -- Worker processa assincronamente sem bloquear a transação de orçamento
  INSERT INTO public.webhook_outbox (event, payload, next_attempt_at)
  VALUES (_event, _payload, now());

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  -- Falha na outbox não deve bloquear a transação principal
  -- Log do erro mas continua
  RAISE WARNING 'dispatch_quote_webhook_event: falha ao enfileirar evento % para quote %: %',
    _event, NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dispatch_quote_webhook_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dispatch_quote_webhook_event"() IS 'FIX QBP-05 (2026-06-22): Migrado de http_post() síncrono (5s timeout) para INSERT na webhook_outbox (assíncrono). Elimina latência de até 5s por transação de orçamento.';



CREATE OR REPLACE FUNCTION "public"."e2e_cleanup_check_rate_limit"("p_key" "text", "p_max" integer, "p_window_seconds" integer) RETURNS TABLE("allowed" boolean, "current_count" integer, "reset_in_seconds" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now TIMESTAMPTZ := now();
  v_count INT;
  v_window_start TIMESTAMPTZ;
BEGIN
  INSERT INTO public.e2e_cleanup_rate_limit AS r (key, count, window_start, updated_at)
  VALUES (p_key, 1, v_now, v_now)
  ON CONFLICT (key) DO UPDATE
    SET count = CASE
          WHEN r.window_start < v_now - make_interval(secs => p_window_seconds) THEN 1
          ELSE r.count + 1
        END,
        window_start = CASE
          WHEN r.window_start < v_now - make_interval(secs => p_window_seconds) THEN v_now
          ELSE r.window_start
        END,
        updated_at = v_now
  RETURNING r.count, r.window_start INTO v_count, v_window_start;

  RETURN QUERY SELECT
    (v_count <= p_max) AS allowed,
    v_count AS current_count,
    GREATEST(0, p_window_seconds - EXTRACT(EPOCH FROM (v_now - v_window_start))::INT) AS reset_in_seconds;
END;
$$;


