CREATE OR REPLACE FUNCTION "public"."extract_youtube_id"("p_url" "text") RETURNS character varying
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_id VARCHAR(20);
BEGIN
    IF p_url IS NULL OR p_url = '' THEN
        RETURN NULL;
    END IF;
    
    -- Formato: https://youtu.be/VIDEO_ID
    IF p_url LIKE '%youtu.be/%' THEN
        v_id := SUBSTRING(p_url FROM 'youtu\.be/([a-zA-Z0-9_-]+)');
    -- Formato: https://www.youtube.com/watch?v=VIDEO_ID
    ELSIF p_url LIKE '%youtube.com/watch%' THEN
        v_id := SUBSTRING(p_url FROM '[?&]v=([a-zA-Z0-9_-]+)');
    -- Formato: https://www.youtube.com/embed/VIDEO_ID
    ELSIF p_url LIKE '%youtube.com/embed/%' THEN
        v_id := SUBSTRING(p_url FROM 'youtube\.com/embed/([a-zA-Z0-9_-]+)');
    ELSE
        v_id := NULL;
    END IF;
    
    -- Validar que extraiu corretamente (11 caracteres é o padrão do YouTube)
    IF v_id IS NOT NULL AND LENGTH(v_id) != 11 THEN
        v_id := LEFT(v_id, 11);
    END IF;
    
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."extract_youtube_id"("p_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."extract_youtube_id"("p_url" "text") IS 'Extrai o ID do vídeo de uma URL do YouTube';



CREATE OR REPLACE FUNCTION "public"."fill_integration_credential_metadata"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW.length := COALESCE(char_length(NEW.secret_value), 0);
  IF NEW.length >= 4 THEN
    NEW.masked_suffix := right(NEW.secret_value, 4);
  ELSE
    NEW.masked_suffix := NEW.secret_value;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fill_integration_credential_metadata"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_add_packaging_compatibility"("p_product_id" "uuid", "p_packaging_id" "uuid", "p_source" character varying DEFAULT 'manual'::character varying, "p_recommended" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_fit JSONB; v_id UUID;
    v_same_supplier BOOLEAN;
BEGIN
    v_fit := fn_calculate_packaging_fit(p_product_id, p_packaging_id);
    IF v_fit ? 'error' THEN RETURN jsonb_build_object('success', FALSE, 'error', v_fit->>'error'); END IF;
    IF NOT (v_fit->>'compatible')::BOOLEAN THEN 
        RETURN jsonb_build_object('success', FALSE, 'error', 'Não cabe', 'fit', v_fit); 
    END IF;
    
    SELECT (p1.supplier_id = p2.supplier_id) INTO v_same_supplier
    FROM products p1, products p2 WHERE p1.id = p_product_id AND p2.id = p_packaging_id;
    
    INSERT INTO product_packaging_compatibility (
        product_id, packaging_id, compatibility_source,
        fit_gap_height_mm, fit_gap_width_mm, fit_gap_length_mm, fit_gap_diameter_mm,
        fit_gap_min_mm, fit_gap_avg_mm, fit_rating, is_recommended, is_same_supplier
    ) VALUES (
        p_product_id, p_packaging_id, p_source,
        (v_fit->>'gap_height_mm')::DECIMAL, (v_fit->>'gap_width_mm')::DECIMAL,
        (v_fit->>'gap_length_mm')::DECIMAL, (v_fit->>'gap_diameter_mm')::DECIMAL,
        (v_fit->>'gap_min_mm')::DECIMAL, (v_fit->>'gap_avg_mm')::DECIMAL,
        v_fit->>'fit_rating', p_recommended, COALESCE(v_same_supplier, FALSE)
    )
    ON CONFLICT (product_id, packaging_id) DO UPDATE SET
        fit_gap_min_mm = EXCLUDED.fit_gap_min_mm,
        fit_rating = EXCLUDED.fit_rating,
        updated_at = NOW()
    RETURNING id INTO v_id;
    
    RETURN jsonb_build_object('success', TRUE, 'id', v_id, 'fit', v_fit);
END;
$$;


ALTER FUNCTION "public"."fn_add_packaging_compatibility"("p_product_id" "uuid", "p_packaging_id" "uuid", "p_source" character varying, "p_recommended" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_add_supplier_mapping"("p_supplier_code" "text", "p_raw_pattern" "text", "p_property_code" "text", "p_priority" integer DEFAULT 80, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO supplier_property_mappings (
        supplier_code,
        raw_pattern,
        property_code,
        priority,
        notes
    ) VALUES (
        p_supplier_code,
        p_raw_pattern,
        p_property_code,
        p_priority,
        p_notes
    )
    ON CONFLICT (supplier_code, raw_pattern)
    DO UPDATE SET
        property_code = EXCLUDED.property_code,
        priority = EXCLUDED.priority,
        notes = EXCLUDED.notes,
        updated_at = NOW()
    RETURNING id INTO v_id;
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'id', v_id,
        'supplier_code', p_supplier_code,
        'pattern', p_raw_pattern,
        'property_code', p_property_code
    );
END;
$$;


ALTER FUNCTION "public"."fn_add_supplier_mapping"("p_supplier_code" "text", "p_raw_pattern" "text", "p_property_code" "text", "p_priority" integer, "p_notes" "text") OWNER TO "postgres";


