CREATE OR REPLACE FUNCTION "public"."fn_anon_insert_rate_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role  text;
  v_limit integer := COALESCE(NULLIF(TG_ARGV[0], '')::integer, 120);
  v_ip    text;
  v_key   text;
  v_n     integer;
BEGIN
  v_role := COALESCE(
    NULLIF(current_setting('request.jwt.claim.role', true), ''),
    (NULLIF(current_setting('request.jwt.claims', true), ''))::jsonb ->> 'role',
    ''
  );
  IF v_role <> 'anon' THEN
    RETURN NEW;
  END IF;

  v_ip := COALESCE(
    NULLIF(btrim(split_part((NULLIF(current_setting('request.headers', true), ''))::jsonb ->> 'x-forwarded-for', ',', 1)), ''),
    'unknown'
  );
  v_key := TG_TABLE_NAME || '|' || v_ip || '|' || to_char(now() AT TIME ZONE 'UTC', 'YYYYMMDDHH24MI');

  INSERT INTO public.anon_insert_rate (bucket_key, n, window_start)
  VALUES (v_key, 1, date_trunc('minute', now()))
  ON CONFLICT (bucket_key) DO UPDATE SET n = public.anon_insert_rate.n + 1
  RETURNING n INTO v_n;

  IF v_n > v_limit THEN
    RAISE EXCEPTION 'anon_insert_rate_limit_exceeded: % (limite %/min por IP)', TG_TABLE_NAME, v_limit
      USING ERRCODE = 'P0001', HINT = 'Reduza a frequência de envio ou autentique-se.';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."fn_anon_insert_rate_guard"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_anon_insert_rate_guard"() IS 'Trigger BEFORE INSERT: limita INSERTs de anon por IP/minuto (arg = limite). Ignora authenticated/service_role.';



CREATE OR REPLACE FUNCTION "public"."fn_apply_auto_tag_rules"("p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product        products%ROWTYPE;
  v_rule           RECORD;
  v_tag_id         uuid;
  v_matches        boolean;
  v_added          integer := 0;
  v_skipped        integer := 0;
  v_cat_name       text;
  v_material_names text;
  v_technique_text text;
  v_price          numeric;
BEGIN
  SELECT * INTO v_product FROM products WHERE id = p_product_id AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'product_not_found');
  END IF;

  SELECT LOWER(c.name) INTO v_cat_name FROM categories c WHERE c.id = v_product.category_id;

  SELECT LOWER(string_agg(mt.name, ' | ')) INTO v_material_names
  FROM product_materials pm JOIN material_types mt ON mt.id = pm.material_id
  WHERE pm.product_id = p_product_id;

  SELECT LOWER(string_agg(te.value, ' | ')) INTO v_technique_text
  FROM product_print_positions ppp,
       LATERAL jsonb_array_elements_text(
         CASE WHEN jsonb_typeof(ppp.technique_list) = 'array' THEN ppp.technique_list ELSE '[]'::jsonb END
       ) AS te(value)
  WHERE ppp.product_id = p_product_id;

  -- Preço: usar cost_price, fallback para suggested_price
  v_price := COALESCE(v_product.cost_price, v_product.suggested_price);

  FOR v_rule IN
    SELECT * FROM auto_tag_rules WHERE is_active = true ORDER BY priority, rule_name
  LOOP
    v_matches := false;

    CASE v_rule.rule_type
      WHEN 'keyword' THEN
        IF v_rule.condition_operator = 'contains' THEN
          v_matches := (
            LOWER(COALESCE(v_product.name,               '')) ILIKE '%' || LOWER(v_rule.condition_value) || '%'
            OR LOWER(COALESCE(v_product.description,     '')) ILIKE '%' || LOWER(v_rule.condition_value) || '%'
            OR LOWER(COALESCE(v_product.short_description,'')) ILIKE '%' || LOWER(v_rule.condition_value) || '%'
          );
        END IF;
      WHEN 'material' THEN
        IF v_rule.condition_operator = 'contains' AND v_material_names IS NOT NULL THEN
          v_matches := v_material_names ILIKE '%' || LOWER(v_rule.condition_value) || '%';
        END IF;
      WHEN 'category' THEN
        IF v_rule.condition_operator = 'contains' AND v_cat_name IS NOT NULL THEN
          v_matches := v_cat_name ILIKE '%' || LOWER(v_rule.condition_value) || '%';
        END IF;
      WHEN 'technique' THEN
        IF v_rule.condition_operator = 'contains' AND v_technique_text IS NOT NULL THEN
          v_matches := v_technique_text ILIKE '%' || LOWER(v_rule.condition_value) || '%';
        END IF;
      WHEN 'price' THEN
        IF v_price IS NOT NULL THEN
          CASE v_rule.condition_operator
            WHEN 'less_than'    THEN v_matches := v_price <  v_rule.condition_value::numeric;
            WHEN 'greater_than' THEN v_matches := v_price >  v_rule.condition_value::numeric;
            WHEN 'between'      THEN v_matches := v_price BETWEEN v_rule.condition_value::numeric AND v_rule.condition_value_max::numeric;
            ELSE NULL;
          END CASE;
        END IF;
      WHEN 'stock' THEN
        IF v_product.stock_quantity IS NOT NULL THEN
          CASE v_rule.condition_operator
            WHEN 'greater_than' THEN v_matches := v_product.stock_quantity >  v_rule.condition_value::integer;
            WHEN 'equals'       THEN v_matches := v_product.stock_quantity =  v_rule.condition_value::integer;
            WHEN 'less_than'    THEN v_matches := v_product.stock_quantity <  v_rule.condition_value::integer;
            ELSE NULL;
          END CASE;
        END IF;
      ELSE NULL;
    END CASE;

    IF v_matches THEN
      SELECT id INTO v_tag_id FROM tags WHERE slug = v_rule.tag_slug AND is_active = true LIMIT 1;
      IF v_tag_id IS NOT NULL THEN
        INSERT INTO product_tags (product_id, tag_id, created_at)
        VALUES (p_product_id, v_tag_id, now())
        ON CONFLICT (product_id, tag_id) DO NOTHING;
        IF FOUND THEN v_added := v_added + 1; ELSE v_skipped := v_skipped + 1; END IF;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'product_id', p_product_id,
    'tags_added', v_added, 'tags_skipped', v_skipped);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'product_id', p_product_id, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."fn_apply_auto_tag_rules"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_apply_auto_tag_rules"("p_product_id" "uuid") IS 'Motor completo de regras de tags. Processa auto_tag_rules por tipo: keyword, material, category, technique, price, stock. Idempotente via ON CONFLICT DO NOTHING. Substitui fn_auto_link_tags.';



CREATE OR REPLACE FUNCTION "public"."fn_apply_crm_callback"("p_quote_id" "uuid", "p_event_type" "text", "p_occurred_at" timestamp with time zone, "p_approved_by" "text" DEFAULT NULL::"text", "p_rejection_reason" "text" DEFAULT NULL::"text", "p_order_id" "uuid" DEFAULT NULL::"uuid", "p_order_number" "text" DEFAULT NULL::"text") RETURNS TABLE("affected" integer, "applied" boolean, "detail" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _rows           INTEGER;
  _current_status TEXT;
BEGIN
  -- fix_version=2026-07-10-fn-apply-state-validation ANTI-REGRESSÃO
  -- Adiciona validação de transição de estado para evitar sequências inválidas
  -- (ex: rejected→converted, expired→approved, converted→rejected, etc.)

  CASE p_event_type

    WHEN 'sent_to_client' THEN
      -- sent_to_client não muda status, só atualiza datas — sem restrição de estado
      UPDATE public.quotes
      SET last_sent_at = p_occurred_at,
          sent_at      = COALESCE(sent_at, p_occurred_at),
          updated_at   = NOW()
      WHERE id = p_quote_id;

    WHEN 'approved' THEN
      -- Só quotes em 'draft' podem ser aprovadas pelo cliente
      SELECT status INTO _current_status FROM public.quotes WHERE id = p_quote_id;
      IF _current_status IS NULL THEN
        RETURN QUERY SELECT 0, FALSE, 'quote_not_found'; RETURN;
      END IF;
      IF _current_status NOT IN ('draft') THEN
        RETURN QUERY SELECT 0, FALSE, 'invalid_transition:' || _current_status || '->approved'; RETURN;
      END IF;
      UPDATE public.quotes
      SET status                  = 'approved',
          approved_at             = p_occurred_at,
          client_response         = 'approved',
          client_response_at      = p_occurred_at,
          approved_by_client_name = COALESCE(p_approved_by, approved_by_client_name),
          updated_at              = NOW()
      WHERE id = p_quote_id;

    WHEN 'rejected' THEN
      -- Só quotes em 'draft' ou 'approved' podem ser rejeitadas
      SELECT status INTO _current_status FROM public.quotes WHERE id = p_quote_id;
      IF _current_status IS NULL THEN
        RETURN QUERY SELECT 0, FALSE, 'quote_not_found'; RETURN;
      END IF;
      IF _current_status NOT IN ('draft', 'approved') THEN
        RETURN QUERY SELECT 0, FALSE, 'invalid_transition:' || _current_status || '->rejected'; RETURN;
      END IF;
      UPDATE public.quotes
      SET status             = 'rejected',
          client_response    = 'rejected',
          client_response_at = p_occurred_at,
          client_feedback    = COALESCE(p_rejection_reason, client_feedback),
          updated_at         = NOW()
      WHERE id = p_quote_id;

    WHEN 'order_created' THEN
      -- Só quotes em 'approved' podem ser convertidas em pedido
      SELECT status INTO _current_status FROM public.quotes WHERE id = p_quote_id;
      IF _current_status IS NULL THEN
        RETURN QUERY SELECT 0, FALSE, 'quote_not_found'; RETURN;
      END IF;
      IF _current_status NOT IN ('approved') THEN
        RETURN QUERY SELECT 0, FALSE, 'invalid_transition:' || _current_status || '->converted'; RETURN;
      END IF;
      UPDATE public.quotes
      SET status                = 'converted',
          converted_at          = p_occurred_at,
          converted_to_order_id = COALESCE(p_order_id, converted_to_order_id),
          conversion_notes      = CASE
                                    WHEN p_order_number IS NOT NULL
                                    THEN 'Pedido criado no CRM: ' || p_order_number
                                    ELSE conversion_notes
                                  END,
          updated_at            = NOW()
      WHERE id = p_quote_id;

    WHEN 'expired' THEN
      -- Quotes 'converted' não podem expirar (negócio já foi fechado)
      SELECT status INTO _current_status FROM public.quotes WHERE id = p_quote_id;
      IF _current_status IS NULL THEN
        RETURN QUERY SELECT 0, FALSE, 'quote_not_found'; RETURN;
      END IF;
      IF _current_status IN ('converted') THEN
        RETURN QUERY SELECT 0, FALSE, 'invalid_transition:converted->expired'; RETURN;
      END IF;
      UPDATE public.quotes
      SET status     = 'expired',
          updated_at = NOW()
      WHERE id = p_quote_id;

    ELSE
      RETURN QUERY SELECT 0, FALSE, 'unknown_event_type: ' || COALESCE(p_event_type, 'NULL');
      RETURN;
  END CASE;

  GET DIAGNOSTICS _rows = ROW_COUNT;

  IF _rows = 0 THEN
    RETURN QUERY SELECT 0, FALSE, 'quote_not_found';
  ELSE
    RETURN QUERY SELECT _rows, TRUE, p_event_type || '_applied';
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_apply_crm_callback"("p_quote_id" "uuid", "p_event_type" "text", "p_occurred_at" timestamp with time zone, "p_approved_by" "text", "p_rejection_reason" "text", "p_order_id" "uuid", "p_order_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_apply_print_profiles"("p_limit" integer DEFAULT 200, "p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_applied  integer := 0;
  v_areas    integer := 0;
  v_skipped  integer := 0;
  v_prod     RECORD;
  v_template uuid;
  v_conf     numeric;
  v_n        integer;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;

  FOR v_prod IN
    SELECT p.id, p.category_id
    FROM public.products p
    WHERE p.is_active
      AND p.category_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM public.print_area_techniques pat WHERE pat.product_id = p.id)
    ORDER BY p.created_at DESC
    LIMIT p_limit
  LOOP
    -- perfil da categoria: fingerprint modal + produto exemplar (template) + confiança
    WITH fp AS (
      SELECT pat.product_id,
             string_agg(DISTINCT pat.location_code||'|'||pat.tabela_preco_id::text, ';'
                        ORDER BY pat.location_code||'|'||pat.tabela_preco_id::text) AS f
      FROM public.print_area_techniques pat
      JOIN public.products px ON px.id = pat.product_id
      WHERE px.category_id = v_prod.category_id AND pat.is_active
      GROUP BY pat.product_id
    ),
    modal AS (
      SELECT f, count(*) AS n_modal, sum(count(*)) OVER () AS n_total
      FROM fp GROUP BY f ORDER BY count(*) DESC LIMIT 1
    )
    SELECT (SELECT fp.product_id FROM fp JOIN modal m ON fp.f = m.f LIMIT 1),
           m.n_modal::numeric / NULLIF(m.n_total,0), m.n_total::integer
      INTO v_template, v_conf, v_n
    FROM modal m;

    IF v_template IS NULL OR v_n IS NULL OR v_n < 3 OR v_conf IS NULL OR v_conf < 0.60 THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    IF NOT p_dry_run THEN
      INSERT INTO public.print_area_techniques
        (product_id, tabela_preco_id, location_code, location_name, location_order,
         max_width, max_height, is_curved, shape, technique_order, is_active, notes)
      SELECT v_prod.id, t.tabela_preco_id, t.location_code, t.location_name, t.location_order,
             t.max_width, t.max_height, t.is_curved, t.shape, t.technique_order, true,
             'profile_inference v1 (cat='||v_prod.category_id||', conf='||round(v_conf*100)||'%, n='||v_n||')'
      FROM public.print_area_techniques t
      WHERE t.product_id = v_template AND t.is_active;
      GET DIAGNOSTICS v_areas = ROW_COUNT;
    ELSE
      SELECT count(*) INTO v_areas FROM public.print_area_techniques t
      WHERE t.product_id = v_template AND t.is_active;
    END IF;

    v_applied := v_applied + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'dry_run', p_dry_run,
    'produtos_processados', v_applied + v_skipped,
    'produtos_aplicados', v_applied, 'produtos_sem_perfil_confiavel', v_skipped);
END;
$$;


ALTER FUNCTION "public"."fn_apply_print_profiles"("p_limit" integer, "p_dry_run" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_apply_print_profiles"("p_limit" integer, "p_dry_run" boolean) IS 'Fase 9: aplica areas de gravacao (print_area_techniques) por PERFIL MODAL da categoria. Gate: >=3 exemplares + dominancia >=60% (paridade simulada 91,8% em 1.848 cenarios). Fill-only, auditavel via notes, dry_run default true.';



CREATE OR REPLACE FUNCTION "public"."fn_apply_supplier_flag_tags"("p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_raw      RECORD;
  v_catalogs text;
  v_added    integer := 0;
  v_rows     integer;
BEGIN
  FOR v_raw IN
    SELECT spr.raw_data
    FROM supplier_products_raw spr
    WHERE spr.product_id = p_product_id
      AND spr.status = 'processed'
  LOOP
    v_catalogs := LOWER(COALESCE(v_raw.raw_data->>'Catalogs', ''));

    -- IsStockOut → sob-encomenda
    IF (v_raw.raw_data->>'IsStockOut' = 'true') THEN
      INSERT INTO product_tags (product_id, tag_id)
      SELECT p_product_id, id FROM tags WHERE slug = 'sob-encomenda' AND is_active = true
      ON CONFLICT (product_id, tag_id) DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_added := v_added + v_rows;
    END IF;

    -- NewProduct → lancamento + novidades-spot
    IF (v_raw.raw_data->>'NewProduct' = 'true') THEN
      INSERT INTO product_tags (product_id, tag_id)
      SELECT p_product_id, id FROM tags WHERE slug IN ('lancamento','novidades-spot') AND is_active = true
      ON CONFLICT (product_id, tag_id) DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_added := v_added + v_rows;
    END IF;

    -- Our Nature → our-nature + sustentavel + eco-friendly
    IF v_catalogs ILIKE '%our nature%' THEN
      INSERT INTO product_tags (product_id, tag_id)
      SELECT p_product_id, id FROM tags WHERE slug IN ('our-nature','sustentavel','eco-friendly') AND is_active = true
      ON CONFLICT (product_id, tag_id) DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_added := v_added + v_rows;
    END IF;

    -- Novidades → lancamento + novidades-spot
    IF v_catalogs ILIKE '%novidades%' THEN
      INSERT INTO product_tags (product_id, tag_id)
      SELECT p_product_id, id FROM tags WHERE slug IN ('lancamento','novidades-spot') AND is_active = true
      ON CONFLICT (product_id, tag_id) DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_added := v_added + v_rows;
    END IF;

    -- Últimas Chegadas → ultimas-chegadas
    IF v_catalogs ILIKE '%timas chegadas%' THEN
      INSERT INTO product_tags (product_id, tag_id)
      SELECT p_product_id, id FROM tags WHERE slug = 'ultimas-chegadas' AND is_active = true
      ON CONFLICT (product_id, tag_id) DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_added := v_added + v_rows;
    END IF;

    -- TimeVaiBrasil → time-vai-brasil
    IF v_catalogs ILIKE '%timevai%' OR v_catalogs ILIKE '%time vai%' THEN
      INSERT INTO product_tags (product_id, tag_id)
      SELECT p_product_id, id FROM tags WHERE slug = 'time-vai-brasil' AND is_active = true
      ON CONFLICT (product_id, tag_id) DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_added := v_added + v_rows;
    END IF;

    -- PvcFree → pvc-free
    IF (v_raw.raw_data->>'PvcFree' = 'true') THEN
      INSERT INTO product_tags (product_id, tag_id)
      SELECT p_product_id, id FROM tags WHERE slug = 'pvc-free' AND is_active = true
      ON CONFLICT (product_id, tag_id) DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_added := v_added + v_rows;
    END IF;

    -- NoReplenishment → sem-reposicao
    IF (v_raw.raw_data->>'NoReplenishment' = 'true') THEN
      INSERT INTO product_tags (product_id, tag_id)
      SELECT p_product_id, id FROM tags WHERE slug = 'sem-reposicao' AND is_active = true
      ON CONFLICT (product_id, tag_id) DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_added := v_added + v_rows;
    END IF;

    -- IsSeasonal → sazonal
    IF (v_raw.raw_data->>'IsSeasonal' = 'true') THEN
      INSERT INTO product_tags (product_id, tag_id)
      SELECT p_product_id, id FROM tags WHERE slug = 'sazonal' AND is_active = true
      ON CONFLICT (product_id, tag_id) DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_added := v_added + v_rows;
    END IF;

  END LOOP;

  RETURN jsonb_build_object('success', true, 'product_id', p_product_id, 'added', v_added);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'product_id', p_product_id, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."fn_apply_supplier_flag_tags"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_apply_supplier_flag_tags"("p_product_id" "uuid") IS 'Aplica tags de flags do fornecedor (raw_data SPOT): IsStockOut, NewProduct, PvcFree, NoReplenishment, IsSeasonal, Catalogs(Our Nature/Novidades/etc). Idempotente via ON CONFLICT DO NOTHING.';



CREATE OR REPLACE FUNCTION "public"."fn_apply_transform"("p_value" "text", "p_transform_type" "text", "p_transform_config" "jsonb" DEFAULT NULL::"jsonb", "p_supplier_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- NULL in = NULL out
    IF p_value IS NULL OR p_value = '' THEN
        RETURN p_value;
    END IF;

    CASE p_transform_type

        WHEN 'direct' THEN
            RETURN p_value;

        WHEN 'custom' THEN
            -- Aplica prefix e/ou suffix da config
            IF p_transform_config IS NOT NULL THEN
                IF p_transform_config->>'prefix' IS NOT NULL THEN
                    p_value := (p_transform_config->>'prefix') || p_value;
                END IF;
                IF p_transform_config->>'suffix' IS NOT NULL THEN
                    p_value := p_value || (p_transform_config->>'suffix');
                END IF;
            END IF;
            RETURN p_value;

        WHEN 'multiply' THEN
            -- Multiplica valor numérico pelo factor
            IF p_transform_config IS NOT NULL AND p_transform_config->>'factor' IS NOT NULL THEN
                RETURN (p_value::NUMERIC * (p_transform_config->>'factor')::NUMERIC)::TEXT;
            END IF;
            RETURN p_value;

        WHEN 'cast' THEN
            -- Cast simples, tipo inferido no destino
            RETURN p_value;

        WHEN 'jsonpath' THEN
            -- Valor já extraído pelo source_field flattenado
            RETURN p_value;

        WHEN 'lookup' THEN
            -- Placeholder para lookups futuros
            RETURN p_value;

        WHEN 'prefix' THEN
            -- Tipo alternativo de prefix
            IF p_transform_config IS NOT NULL AND p_transform_config->>'prefix' IS NOT NULL THEN
                RETURN (p_transform_config->>'prefix') || p_value;
            END IF;
            RETURN p_value;

        ELSE
            -- Tipo desconhecido, retorna valor original
            RETURN p_value;

    END CASE;
END;
$$;


ALTER FUNCTION "public"."fn_apply_transform"("p_value" "text", "p_transform_type" "text", "p_transform_config" "jsonb", "p_supplier_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_apply_transform"("p_value" "text", "p_transform_type" "text", "p_transform_config" "jsonb", "p_supplier_id" "uuid") IS 'Aplica transformação configurada a um valor.
Tipos suportados: direct, multiply, divide, convert_unit, lookup, custom
Exemplo: fn_apply_transform(''0.28'', ''custom'', ''{"function": "fn_convert_box_dimension_to_cm"}'') → ''28.0''';



CREATE OR REPLACE FUNCTION "public"."fn_apply_transform"("p_value" "text", "p_transform_type" character varying, "p_transform_config" "jsonb", "p_source_unit" character varying, "p_target_unit" character varying, "p_supplier_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_result     TEXT;
    v_numeric    DECIMAL;
    v_multiplier DECIMAL;
    v_fn         VARCHAR;
    v_op         VARCHAR;
    v_pattern    TEXT;
    v_group      INTEGER;
    v_matches    TEXT[];
    v_max_length INTEGER;
    v_ftype      TEXT;
BEGIN
    -- Transforms que ignoram valor de entrada: bypass null-check
    IF p_transform_type = 'constant' THEN RETURN p_transform_config->>'value'; END IF;
    IF p_transform_type = 'custom' AND p_transform_config IS NOT NULL
       AND (p_transform_config->>'op') = 'constant' THEN
        RETURN p_transform_config->>'value';
    END IF;
    IF p_value IS NULL OR TRIM(p_value) = '' THEN RETURN NULL; END IF;

    CASE p_transform_type

        WHEN 'direct' THEN v_result := p_value;

        WHEN 'constant' THEN v_result := p_transform_config->>'value';

        WHEN 'generate_short_description' THEN
            BEGIN
                DECLARE
                    v_max_chars   INT  := COALESCE((p_transform_config->>'max_chars')::INT,  200);
                    v_min_sent    INT  := COALESCE((p_transform_config->>'min_sentence')::INT, 30);
                    v_hard_cap    INT  := COALESCE((p_transform_config->>'hard_cap')::INT,   250);
                    v_norm        TEXT;
                    v_dot_pos     INT;
                    v_first_sent  TEXT;
                    v_word_trunc  TEXT;
                BEGIN
                    IF length(trim(p_value)) <= v_max_chars THEN
                        v_result := trim(p_value);
                    ELSE
                        v_norm := regexp_replace(trim(p_value), E'[\\r\\n]+', '. ', 'g');
                        v_dot_pos := position('.' IN v_norm);
                        v_first_sent := CASE WHEN v_dot_pos > 0 THEN trim(left(v_norm, v_dot_pos)) ELSE '' END;
                        v_word_trunc := trim(left(p_value,
                            v_max_chars - position(' ' IN reverse(left(p_value, v_max_chars)))));
                        IF length(v_first_sent) BETWEEN v_min_sent AND v_hard_cap THEN
                            v_result := v_first_sent;
                        ELSE
                            v_result := left(v_word_trunc, v_hard_cap);
                        END IF;
                    END IF;
                EXCEPTION WHEN OTHERS THEN v_result := left(trim(p_value), v_hard_cap); END;
            END;

        WHEN 'multiply' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'multiplier')::DECIMAL,
                                         (p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM
                              ROUND(v_numeric * v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'divide' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'divisor')::DECIMAL,
                                         (p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL OR v_multiplier = 0 THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM
                              ROUND(v_numeric / v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'convert_unit' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_result  := public.fn_convert_unit(v_numeric, p_source_unit, p_target_unit,
                                                    p_supplier_id)::TEXT;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'lookup' THEN
            v_result := public.fn_map_value(p_supplier_id,
                                            p_transform_config->>'lookup_type', p_value);

        WHEN 'extract_keywords_lookup' THEN
            BEGIN
                v_ftype := COALESCE(p_transform_config->>'field_type', 'material');
                SELECT to_jsonb(
                    COALESCE(
                        array_agg(DISTINCT svm.target_value ORDER BY svm.target_value)
                        FILTER (WHERE svm.target_value IS NOT NULL),
                        ARRAY[]::text[]
                    )
                )::TEXT
                INTO v_result
                FROM public.supplier_value_mappings svm
                WHERE svm.supplier_id = p_supplier_id
                  AND svm.field_type  = v_ftype
                  AND svm.is_active   = TRUE
                  AND UPPER(p_value)  LIKE '%' || UPPER(svm.source_value) || '%';
                IF v_result IS NULL OR v_result = '[]' OR v_result = 'null' THEN
                  v_result := NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN v_result := NULL; END;

        -- [SM-FIX-v3] extract_dominant_technique com boundary UV correto
        WHEN 'extract_dominant_technique' THEN
            BEGIN
                IF upper(trim(p_value)) IN ('LAS1','SER1','UV1') THEN
                    v_result := upper(trim(p_value));
                ELSIF lower(p_value) ~* 'laser' AND lower(p_value) ~* '(silk|screen|serigrafia|silkscreen)' THEN
                    v_result := 'LAS1';
                ELSIF lower(p_value) ~* 'laser' AND lower(p_value) ~* 'digital' THEN
                    v_result := 'LAS1';
                ELSIF lower(p_value) ~* '\mlaser\M' THEN
                    v_result := 'LAS1';
                ELSIF lower(p_value) ~* '(silk|screen|serigrafia|silkscreen)' THEN
                    v_result := 'SER1';
                -- [FIX B20] UV com word-boundary \m\M para capturar "Gravação UV" (sem espaço após)
                ELSIF lower(p_value) ~* '(digital|\muv\M)' THEN
                    v_result := 'UV1';
                ELSIF lower(p_value) ~* 'sem grava' THEN
                    v_result := NULL;
                ELSE
                    v_result := NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN v_result := NULL; END;

        WHEN 'bool_sim_nao' THEN
            v_result := CASE
                WHEN lower(trim(p_value)) IN ('sim','s','yes','y','1','true','t') THEN 'true'
                WHEN lower(trim(p_value)) IN ('não','nao','n','no','0','false','f') THEN 'false'
                ELSE public.fn_safe_bool(p_value)::TEXT
            END;

        WHEN 'warranty_parse' THEN
            BEGIN
                IF p_value ~* '(\d+)\s*m[êe]s' THEN
                    v_result := (regexp_match(p_value, '(\d+)\s*m[êe]s'))[1];
                ELSIF p_value ~* '(\d+)\s*ano' THEN
                    v_result := ((regexp_match(p_value, '(\d+)\s*ano'))[1]::int * 12)::text;
                ELSE v_result := NULL; END IF;
            EXCEPTION WHEN OTHERS THEN v_result := NULL; END;

        WHEN 'custom' THEN
            BEGIN
                v_fn := p_transform_config->>'function';
                v_op := p_transform_config->>'op';
                CASE
                    WHEN v_fn = 'fn_parse_capacity_ml'           THEN v_result := public.fn_parse_capacity_ml(p_value)::TEXT;
                    WHEN v_fn = 'fn_convert_box_dimension_to_cm' THEN v_result := public.fn_convert_box_dimension_to_cm(p_value)::TEXT;
                    WHEN v_fn = 'fn_clean_spot_name'             THEN v_result := public.fn_clean_spot_name(p_value);
                    WHEN v_fn = 'fn_normalize_ncm'               THEN v_result := public.fn_normalize_ncm(p_value)::TEXT;
                    WHEN v_fn = 'fn_spot_split_list'             THEN v_result := public.fn_spot_split_list(p_value)::TEXT;
                    WHEN v_fn = 'fn_spot_image_list'             THEN v_result := public.fn_spot_image_list(
                                                                          p_value,
                                                                          COALESCE(p_transform_config->>'base',
                                                                                   'https://www.spotgifts.com.br/fotos/produtos/')
                                                                        )::TEXT;
                    WHEN v_op = 'array_url'  THEN v_result := jsonb_build_array(p_value)::TEXT;
                    WHEN v_op = 'is_present' THEN v_result := CASE WHEN NULLIF(TRIM(p_value),'') IS NOT NULL
                                                                    THEN 'true' ELSE 'false' END;
                    WHEN v_op = 'constant'   THEN v_result := p_transform_config->>'value';
                    ELSE v_result := p_value;
                END CASE;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'cast_integer'  THEN v_result := public.fn_safe_int(p_value)::TEXT;
        WHEN 'cast_decimal'  THEN v_result := public.fn_safe_num(p_value)::TEXT;
        WHEN 'cast_datetime' THEN
            BEGIN
                v_result := CASE WHEN p_value ~ '^\d{4}-\d{2}-\d{2}'
                                 THEN LEFT(p_value, 10) ELSE NULL END;
            EXCEPTION WHEN OTHERS THEN v_result := NULL; END;
        WHEN 'cast_boolean'  THEN v_result := public.fn_safe_bool(p_value)::TEXT;
        WHEN 'cast' THEN
            BEGIN
                v_result := CASE COALESCE(p_transform_config->>'to', 'text')
                    WHEN 'boolean' THEN public.fn_safe_bool(p_value)::TEXT
                    WHEN 'integer' THEN public.fn_safe_int(p_value)::TEXT
                    WHEN 'decimal' THEN public.fn_safe_num(p_value)::TEXT
                    ELSE p_value
                END;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'split_pipe' THEN
            -- Filtro URL: remove fragmentos inválidos (ex: 'https:/') quando validate_urls='true'
            -- ou quando nenhum elemento seria válido como URL completa mas algum tem protocolo.
            -- Por padrão, filtra elementos não-vazios; com validate_urls sempre filtra URLs quebradas.
            IF COALESCE(p_transform_config->>'validate_urls', 'false') = 'true' THEN
                v_result := (
                    SELECT to_jsonb(COALESCE(
                        array_agg(BTRIM(e) ORDER BY ord) FILTER (
                            WHERE BTRIM(e) <> ''
                              AND length(BTRIM(e)) >= 12
                              AND BTRIM(e) ~ '^https?://[a-zA-Z0-9]'
                        ),
                        ARRAY[]::text[]))::TEXT
                    FROM unnest(string_to_array(p_value,
                         COALESCE(p_transform_config->>'delimiter', ',')))
                         WITH ORDINALITY AS t(e, ord)
                );
            ELSE
                v_result := (
                    SELECT to_jsonb(COALESCE(
                        array_agg(BTRIM(e)) FILTER (WHERE BTRIM(e) <> ''),
                        ARRAY[]::text[]))::TEXT
                    FROM unnest(string_to_array(p_value,
                         COALESCE(p_transform_config->>'delimiter', ','))) AS e
                );
            END IF;
        WHEN 'prefix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'prefix' IS NOT NULL THEN
                v_result := (p_transform_config->>'prefix') || p_value;
            ELSE v_result := p_value; END IF;
        WHEN 'suffix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'suffix' IS NOT NULL THEN
                v_result := p_value || (p_transform_config->>'suffix');
            ELSE v_result := p_value; END IF;
        WHEN 'uppercase' THEN v_result := UPPER(p_value);
        WHEN 'lowercase' THEN v_result := LOWER(p_value);
        WHEN 'trim'      THEN v_result := BTRIM(p_value);
        WHEN 'replace' THEN
            IF p_transform_config IS NOT NULL THEN
                v_result := REPLACE(p_value,
                    COALESCE(p_transform_config->>'find',''),
                    COALESCE(p_transform_config->>'replace',''));
            ELSE v_result := p_value; END IF;

        WHEN 'regex_extract' THEN
            BEGIN
                v_pattern := p_transform_config->>'pattern';
                v_group   := COALESCE((p_transform_config->>'group')::INTEGER, 1);
                IF v_pattern IS NULL THEN RETURN p_value; END IF;
                v_matches := regexp_matches(p_value, v_pattern);
                IF array_length(v_matches, 1) >= v_group THEN v_result := v_matches[v_group];
                ELSE v_result := NULL; END IF;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        -- [SM-FIX-v3] dim_to_cm: fallback para labels com dígito antes de ":"
        WHEN 'dim_to_cm' THEN
            BEGIN
                DECLARE
                    v_dim_str TEXT := TRIM(p_value);
                    v_src_unit TEXT := LOWER(COALESCE(p_source_unit, p_transform_config->>'unit', 'cm'));
                    v_divisor DECIMAL := CASE v_src_unit WHEN 'mm' THEN 10 WHEN 'm' THEN 0.01 ELSE 1 END;
                    v_h DECIMAL; v_w DECIMAL; v_l DECIMAL;
                    v_rx TEXT := '(\d+(?:[.,]\d+)?)';
                BEGIN
                    -- 1. Strip label prefix (letras sem dígitos antes de ":")
                    v_dim_str := regexp_replace(v_dim_str, '^[^:0-9]*:\s*', '');
                    -- 2. First component
                    v_dim_str := split_part(v_dim_str, '/', 1);
                    v_dim_str := TRIM(v_dim_str);
                    -- 3. Strip trailing unit
                    v_dim_str := REGEXP_REPLACE(v_dim_str, '\s*(mm|cm|m)\s*(?:\(.*?\))?$', '', 'i');
                    -- 4. Strip Ø markers
                    v_dim_str := regexp_replace(v_dim_str, '[Øø∅]', '', 'g');
                    v_dim_str := TRIM(v_dim_str);

                    IF v_dim_str ~ '^\d' THEN
                        -- Caminho padrão: string já começa com dígito
                        v_matches := REGEXP_MATCHES(v_dim_str,
                          v_rx || '(?:\s*[xX]\s*' || v_rx || ')?(?:\s*[xX]\s*' || v_rx || ')?');
                    ELSIF v_dim_str ~ '\d+[.,]?\d*\s*[xX]\s*\d' THEN
                        -- [SM-FIX-v3 A08] Fallback: label com dígito antes de ":" (ex: "Faca 8":")
                        -- Encontra PRIMEIRO padrão "num x num" em qualquer posição
                        v_matches := REGEXP_MATCHES(v_dim_str,
                          v_rx || '\s*[xX]\s*' || v_rx || '(?:\s*[xX]\s*' || v_rx || ')?');
                    END IF;

                    IF v_matches IS NOT NULL THEN
                        v_h := REPLACE(v_matches[1], ',', '.')::DECIMAL / v_divisor;
                        v_w := CASE WHEN v_matches[2] IS NOT NULL
                                    THEN REPLACE(v_matches[2], ',', '.')::DECIMAL / v_divisor END;
                        v_l := CASE WHEN v_matches[3] IS NOT NULL
                                    THEN REPLACE(v_matches[3], ',', '.')::DECIMAL / v_divisor END;
                        IF v_h = 0 AND (v_w IS NULL OR v_w = 0) THEN
                            v_result := NULL;
                        ELSIF p_transform_config->>'position' IS NOT NULL THEN
                            v_result := CASE (p_transform_config->>'position')::int
                                WHEN 1 THEN CASE WHEN v_h > 0 THEN ROUND(v_h, 2)::TEXT ELSE NULL END
                                WHEN 2 THEN CASE WHEN v_w IS NOT NULL AND v_w > 0 THEN ROUND(v_w, 2)::TEXT ELSE NULL END
                                WHEN 3 THEN CASE WHEN v_l IS NOT NULL AND v_l > 0 THEN ROUND(v_l, 2)::TEXT ELSE NULL END
                                ELSE ROUND(v_h, 2)::TEXT
                            END;
                        ELSE
                            v_result := jsonb_build_object(
                                'h', ROUND(v_h, 2),
                                'w', CASE WHEN v_w IS NOT NULL THEN ROUND(v_w, 2) END,
                                'l', CASE WHEN v_l IS NOT NULL THEN ROUND(v_l, 2) END
                            )::TEXT;
                        END IF;
                    END IF;
                EXCEPTION WHEN OTHERS THEN v_result := NULL; END;
            END;

        ELSE v_result := p_value;
    END CASE;

    IF v_result IS NOT NULL AND p_transform_config IS NOT NULL
       AND (p_transform_config->>'max_length') IS NOT NULL THEN
        v_max_length := (p_transform_config->>'max_length')::INTEGER;
        IF v_max_length > 0 AND length(v_result) > v_max_length THEN
            v_result := LEFT(v_result, v_max_length);
        END IF;
    END IF;

    RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."fn_apply_transform"("p_value" "text", "p_transform_type" character varying, "p_transform_config" "jsonb", "p_source_unit" character varying, "p_target_unit" character varying, "p_supplier_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_apply_transform"("p_value" "text", "p_transform_type" character varying, "p_transform_config" "jsonb", "p_source_unit" character varying, "p_target_unit" character varying, "p_supplier_id" "uuid") IS 'Motor de transformações do DE>PARA (supplier_field_mappings). v2 (2026-06-06):
 + custom: fn_spot_split_list, fn_spot_image_list, op=array_url, op=is_present
 + cast_integer, cast_decimal, cast_datetime, cast_boolean, cast (genérico com config.to)
 + split_pipe (jsonb array via delimiter)';



CREATE OR REPLACE FUNCTION "public"."fn_approve_product_deactivation"("p_request_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_req   product_deactivation_requests%ROWTYPE;
  v_uid   uuid := auth.uid();
  v_name  text;
  v_prod  products%ROWTYPE;
  v_auth_id uuid;
BEGIN
  IF v_uid IS NOT NULL AND NOT public.is_admin_or_above(v_uid) THEN
    RETURN jsonb_build_object('ok',false,'error','Acesso negado: requer credencial de administrador ou superior');
  END IF;

  SELECT * INTO v_req FROM product_deactivation_requests
  WHERE id=p_request_id AND status='pending';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error','solicitacao_nao_encontrada_ou_nao_pendente');
  END IF;

  SELECT * INTO v_prod FROM products WHERE id=v_req.product_id;
  IF NOT FOUND THEN
    UPDATE product_deactivation_requests SET status='cancelled',notes='produto_deletado' WHERE id=p_request_id;
    RETURN jsonb_build_object('ok',false,'error','produto_nao_existe_mais');
  END IF;

  IF NOT v_prod.is_active THEN
    UPDATE product_deactivation_requests SET status='executed',executed_at=now() WHERE id=p_request_id;
    RETURN jsonb_build_object('ok',true,'note','produto_ja_estava_inativo','product_id',v_req.product_id);
  END IF;

  SELECT COALESCE(raw_user_meta_data->>'full_name',email) INTO v_name FROM auth.users WHERE id=v_uid;

  UPDATE product_deactivation_requests SET
    status='approved', approved_by=v_uid, approved_by_name=COALESCE(v_name,'admin'),
    approved_at=now(), notes=COALESCE(p_notes,notes)
  WHERE id=p_request_id;

  -- MECANISMO SEGURO: inserir token de autorização one-shot na tabela
  INSERT INTO product_deactivation_tokens(product_id,request_id,authorized_by)
  VALUES(v_req.product_id,p_request_id,v_uid)
  RETURNING id INTO v_auth_id;

  -- Executar a desativação (trigger vai verificar o token)
  UPDATE products SET is_active=false, updated_at=now() WHERE id=v_req.product_id;

  -- Limpar token (já foi usado, mas por segurança)
  DELETE FROM product_deactivation_tokens WHERE id=v_auth_id;

  UPDATE product_deactivation_requests SET status='executed',executed_at=now() WHERE id=p_request_id;

  RETURN jsonb_build_object(
    'ok',true,'product_id',v_req.product_id,
    'supplier_reference',v_req.supplier_reference,'product_name',v_req.product_name,
    'deactivated_at',now(),'approved_by',COALESCE(v_name,'admin'),'reason',v_req.reason
  );
END;
$$;


ALTER FUNCTION "public"."fn_approve_product_deactivation"("p_request_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_complete_image_upload"("p_queue_id" "uuid", "p_cf_image_id" "text", "p_cf_filename" "text", "p_cf_url_cdn" "text", "p_cf_width" integer DEFAULT NULL::integer, "p_cf_height" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_q   RECORD;
  v_img UUID;
BEGIN
  SELECT * INTO v_q FROM public.asia_image_import_queue WHERE id = p_queue_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'queue_item_not_found');
  END IF;

  BEGIN
    INSERT INTO public.product_images (
      product_id, variant_id, cloudflare_image_id, url_cdn, url_original, filename,
      image_type, is_primary, display_order, source_supplier,
      width_px, height_px, is_active, organization_id
    )
    VALUES (
      v_q.product_id, v_q.variant_id,
      p_cf_image_id, p_cf_url_cdn, v_q.url_original, p_cf_filename,
      v_q.image_type, v_q.image_type = 'main', v_q.display_order, 'ASIA',
      p_cf_width, p_cf_height, true, '5db5aee1-064b-4ef4-9193-345dcd8274ea'
    )
    ON CONFLICT (product_id, filename)
      WHERE (is_active = true AND filename IS NOT NULL)
    DO UPDATE SET
      cloudflare_image_id = EXCLUDED.cloudflare_image_id,
      url_cdn             = EXCLUDED.url_cdn,
      url_original        = EXCLUDED.url_original,
      variant_id          = COALESCE(product_images.variant_id, EXCLUDED.variant_id),
      display_order       = EXCLUDED.display_order,
      width_px            = COALESCE(EXCLUDED.width_px,  product_images.width_px),
      height_px           = COALESCE(EXCLUDED.height_px, product_images.height_px),
      updated_at          = now()
    RETURNING id INTO v_img;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_img FROM public.product_images
    WHERE cloudflare_image_id = p_cf_image_id AND is_active = true LIMIT 1;
  END;

  -- PATCH: atualizar primary_image_url mesmo quando já é URL externa (não CF)
  IF v_q.image_type = 'main' THEN
    UPDATE public.products
    SET primary_image_url = p_cf_url_cdn, updated_at = now()
    WHERE id = v_q.product_id
      AND (primary_image_url IS NULL
           OR primary_image_url NOT LIKE '%imagedelivery%');
  END IF;

  UPDATE public.asia_image_import_queue
  SET status              = 'done',
      cloudflare_image_id = p_cf_image_id,
      cf_url_cdn          = p_cf_url_cdn,
      cf_filename         = p_cf_filename,
      updated_at          = now()
  WHERE id = p_queue_id;

  RETURN jsonb_build_object('ok', true, 'image_id', v_img, 'cf_image_id', p_cf_image_id);
END;
$$;


ALTER FUNCTION "public"."fn_asia_complete_image_upload"("p_queue_id" "uuid", "p_cf_image_id" "text", "p_cf_filename" "text", "p_cf_url_cdn" "text", "p_cf_width" integer, "p_cf_height" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_complete_image_upload_batch"("p_uploads" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item jsonb;
  v_q    RECORD;
  v_ok   INT := 0;
  v_err  INT := 0;
BEGIN
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_uploads)
  LOOP
    BEGIN
      SELECT * INTO v_q FROM public.asia_image_import_queue
      WHERE id = (v_item->>'queue_id')::uuid;

      IF NOT FOUND THEN v_err := v_err + 1; CONTINUE; END IF;

      INSERT INTO public.product_images (
        product_id, cloudflare_image_id, url_cdn, url_original, filename,
        image_type, is_primary, display_order, source_supplier, is_active, organization_id
      )
      VALUES (
        v_q.product_id, v_item->>'cf_image_id', v_item->>'cf_url_cdn',
        v_q.url_original, v_item->>'cf_filename',
        v_q.image_type, v_q.image_type = 'main', v_q.display_order,
        'ASIA', true, '5db5aee1-064b-4ef4-9193-345dcd8274ea'
      )
      ON CONFLICT (cloudflare_image_id) DO UPDATE SET
        url_cdn    = EXCLUDED.url_cdn,
        filename   = EXCLUDED.filename,
        updated_at = now();

      -- PATCH: atualizar primary_image_url mesmo quando é URL externa
      IF v_q.image_type = 'main' THEN
        UPDATE public.products
        SET primary_image_url = v_item->>'cf_url_cdn', updated_at = now()
        WHERE id = v_q.product_id
          AND (primary_image_url IS NULL
               OR primary_image_url NOT LIKE '%imagedelivery%');
      END IF;

      UPDATE public.asia_image_import_queue
      SET status              = 'done',
          cloudflare_image_id = v_item->>'cf_image_id',
          cf_url_cdn          = v_item->>'cf_url_cdn',
          cf_filename         = v_item->>'cf_filename',
          updated_at          = now()
      WHERE id = (v_item->>'queue_id')::uuid;

      v_ok := v_ok + 1;

    EXCEPTION WHEN OTHERS THEN
      v_err := v_err + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('ok', v_ok, 'err', v_err, 'ts', now());
END;
$$;


ALTER FUNCTION "public"."fn_asia_complete_image_upload_batch"("p_uploads" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_dispatch_queue_batch"("p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net'
    AS $$
DECLARE
  v_count        integer := 0;
  v_first_req_id bigint;
  v_last_req_id  bigint;
  v_req_id       bigint;
  v_mcp_id       integer := 0;
  v_item         RECORD;
BEGIN
  FOR v_item IN
    SELECT id, url_original, cf_image_id_canonical, image_type, product_id
    FROM asia_image_import_queue
    WHERE status = 'pending'
    ORDER BY created_at
    LIMIT p_limit
  LOOP
    v_mcp_id := v_mcp_id + 1;

    SELECT net.http_post(
      url     := 'https://cloudflare-deploy-mcp.adm01.workers.dev/mcp',
      body    := jsonb_build_object(
        'jsonrpc', '2.0', 'id', v_mcp_id, 'method', 'tools/call',
        'params', jsonb_build_object(
          'name', 'cf_images_upload_url',
          'arguments', jsonb_build_object(
            'source_url', v_item.url_original,
            'custom_id',  v_item.cf_image_id_canonical,
            'metadata',   jsonb_build_object(
              'supplier',   'asia',
              'image_type', v_item.image_type,
              'product_id', v_item.product_id::text
            )
          )
        )
      ),
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Accept',       'application/json, text/event-stream'
      ),
      timeout_milliseconds := 30000
    ) INTO v_req_id;

    INSERT INTO asia_upload_mapping (request_id, queue_id, cf_custom_id, source_url)
    VALUES (v_req_id, v_item.id, v_item.cf_image_id_canonical, v_item.url_original);

    UPDATE asia_image_import_queue
    SET status = 'uploading', attempts = attempts + 1, updated_at = NOW()
    WHERE id = v_item.id;

    v_count := v_count + 1;
    IF v_first_req_id IS NULL THEN v_first_req_id := v_req_id; END IF;
    v_last_req_id := v_req_id;
  END LOOP;

  RETURN jsonb_build_object('dispatched', v_count, 'first_req_id', v_first_req_id, 'last_req_id', v_last_req_id);
END;
$$;


ALTER FUNCTION "public"."fn_asia_dispatch_queue_batch"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_enqueue_primary_url_images"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inserted integer;
BEGIN
  INSERT INTO asia_image_import_queue (
    codigo_pai,
    url_original,
    cf_image_id_canonical,
    image_type,
    display_order,
    product_id,
    status
  )
  SELECT
    lower(regexp_replace(p.supplier_reference, '[^a-zA-Z0-9]', '', 'g')) AS codigo_pai,
    p.primary_image_url                                                    AS url_original,
    'asia-' || lower(regexp_replace(p.supplier_reference, '[^a-zA-Z0-9]', '', 'g')) || '-01'
                                                                           AS cf_image_id_canonical,
    'main'                                                                 AS image_type,
    1                                                                      AS display_order,
    p.id                                                                   AS product_id,
    'pending'
  FROM products p
  WHERE p.supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'
    AND p.is_active = true
    AND p.primary_image_url IS NOT NULL
    AND p.primary_image_url NOT LIKE '%imagedelivery%'
    AND NOT EXISTS (
      SELECT 1 FROM asia_image_import_queue q
      WHERE q.product_id = p.id
        AND q.status != 'done'
    )
  ON CONFLICT (url_original) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RETURN jsonb_build_object(
    'inserted', v_inserted,
    'ts',       now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_asia_enqueue_primary_url_images"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_enqueue_videos"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enfileirados int := 0;
BEGIN
  INSERT INTO video_import_queue (
    youtube_id,
    youtube_url,
    source_supplier,
    product_references,
    status
  )
  SELECT DISTINCT ON (pv.source_youtube_id)
    pv.source_youtube_id                AS youtube_id,
    pv.url_original                     AS youtube_url,
    'asia'                              AS source_supplier,
    ARRAY[p.supplier_reference]         AS product_references,
    'pending'                           AS status
  FROM product_videos pv
  JOIN products p ON p.id = pv.product_id
  WHERE pv.source_supplier = 'ASIA'
    AND pv.cloudflare_status = 'youtube'
    AND pv.source_youtube_id IS NOT NULL
    AND p.supplier_reference IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM video_import_queue viq
      WHERE viq.youtube_id = pv.source_youtube_id
        AND viq.source_supplier = 'asia'
    )
  ORDER BY pv.source_youtube_id, pv.created_at ASC;

  GET DIAGNOSTICS v_enfileirados = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok',            true,
    'enfileirados',  v_enfileirados,
    'fila_pendente', (SELECT COUNT(*) FROM video_import_queue
                       WHERE source_supplier = 'asia' AND status = 'pending')
  );
END;
$$;


ALTER FUNCTION "public"."fn_asia_enqueue_videos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_enrich_parent"("p_supplier_id" "uuid", "p_parent_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_raw jsonb; v_asia jsonb; v_asia_prop jsonb; v_n int;
  v_h numeric; v_w numeric; v_l numeric;
  v_cap_raw text; v_cap_ml int;
BEGIN
  SELECT (SELECT raw_data FROM public.supplier_products_raw WHERE id = pv.raw_id)
    INTO v_raw
  FROM public.produtos_padronizacao_variantes pv
  WHERE pv.supplier_id = p_supplier_id
    AND pv.parent_reference = p_parent_reference
    AND pv.raw_id IS NOT NULL
  ORDER BY length((SELECT raw_data::text FROM public.supplier_products_raw WHERE id = pv.raw_id)) DESC NULLS LAST, pv.raw_id
  LIMIT 1;

  IF v_raw IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'sem_representante', 'parent', p_parent_reference);
  END IF;

  v_asia := public.fn_parse_asia_properties(
    COALESCE(v_raw->'propriedades', '{}'::jsonb),
    COALESCE(public.fn_safe_num(v_raw->>'altura'), 0),
    COALESCE(public.fn_safe_num(v_raw->>'largura'), 0),
    COALESCE(public.fn_safe_num(v_raw->>'comprimento'), 0),
    COALESCE(public.fn_safe_num(v_raw->>'peso'), 0),
    v_raw->>'origem_faturamento');

  v_asia_prop := public.fn_parse_asia_properties(
    COALESCE(v_raw->'propriedades', '{}'::jsonb), 0, 0, 0, 0, v_raw->>'origem_faturamento');

  -- PATCH: usar fn_safe_num para proteger casts diretos de dims
  v_h := COALESCE(public.fn_safe_num(v_asia_prop->>'height_cm'), public.fn_safe_num(v_asia->>'height_cm'));
  v_w := COALESCE(public.fn_safe_num(v_asia_prop->>'width_cm'),  public.fn_safe_num(v_asia->>'width_cm'));
  v_l := COALESCE(public.fn_safe_num(v_asia_prop->>'length_cm'), public.fn_safe_num(v_asia->>'length_cm'));

  -- PATCH: capacidade — tomar só 1ª parte antes de "/" para tratar "14,4/7,5L"
  v_cap_raw := lower(split_part(COALESCE(
     v_raw->'atributos'->'capacidade'->>'value',
     v_raw->'atributos'->'capacidade'->>'valor',
     v_raw->'atributos'->'volume-litros'->>'value',
     v_raw->'atributos'->'volume-litros'->>'valor',
     v_raw->'propriedades'->>'volume',
     v_raw->'propriedades'->>'capacidade',
     ''), '/', 1));   -- <-- PATCH: só parte antes de "/"

  v_cap_ml := CASE
     WHEN v_cap_raw ~ 'ml' THEN
       NULLIF(regexp_replace(v_cap_raw, '[^0-9]', '', 'g'), '')::int
     WHEN v_cap_raw ~ 'l'  THEN
       round(NULLIF(replace(regexp_replace(v_cap_raw, '[^0-9,\.]', '', 'g'), ',', '.'), '')::numeric * 1000)::int
     ELSE NULL END;

  UPDATE public.produtos_padronizacao SET
    description        = COALESCE(NULLIF(v_raw->>'descricao', ''), description),
    short_description  = COALESCE(LEFT(NULLIF(v_raw->>'descricao', ''), 300), short_description),
    images             = CASE WHEN jsonb_typeof(v_raw->'galeria') = 'array'
                               AND jsonb_array_length(v_raw->'galeria') > 0
                              THEN v_raw->'galeria' ELSE images END,
    height_cm          = COALESCE(v_h, height_cm),
    width_cm           = COALESCE(v_w, width_cm),
    length_cm          = COALESCE(v_l, length_cm),
    weight_g           = COALESCE((v_asia->>'weight_g')::int, weight_g),
    box_length_cm      = COALESCE(public.fn_safe_num(v_asia->>'box_length_cm'), box_length_cm),
    box_width_cm       = COALESCE(public.fn_safe_num(v_asia->>'box_width_cm'),  box_width_cm),
    box_height_cm      = COALESCE(public.fn_safe_num(v_asia->>'box_height_cm'), box_height_cm),
    box_weight_kg      = COALESCE(public.fn_safe_num(v_asia->>'box_weight_kg'), box_weight_kg),
    box_quantity       = COALESCE((v_asia->>'box_quantity')::int, box_quantity),
    packing_type       = COALESCE(v_asia->>'packing_type', packing_type),
    capacity_ml        = COALESCE(v_cap_ml, (v_asia->>'capacity_ml')::int, capacity_ml),
    dimensions_display = COALESCE(NULLIF(v_raw->'propriedades'->>'dimensao-do-produto', ''),
                                  NULLIF(v_raw->'propriedades'->>'dimensao-produto', ''), dimensions_display),
    updated_at = now()
  WHERE supplier_id = p_supplier_id AND supplier_reference = p_parent_reference;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('success', v_n > 0, 'parent', p_parent_reference, 'rows', v_n,
                            'dims_cm', jsonb_build_object('h', v_h, 'w', v_w, 'l', v_l),
                            'capacity_ml', v_cap_ml);
END;
$$;


ALTER FUNCTION "public"."fn_asia_enrich_parent"("p_supplier_id" "uuid", "p_parent_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_find_not_found"("p_skus" "jsonb") RETURNS TABLE("api_sku" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_item jsonb; v_sku text; v_found boolean;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_skus) LOOP
    v_sku := trim(v_item->>'sku');
    IF v_sku IS NULL OR v_sku = '' THEN CONTINUE; END IF;
    SELECT EXISTS(
      SELECT 1 FROM product_variants pv
      JOIN products p ON p.id=pv.product_id
      WHERE p.supplier_id='d2734e23-d633-4819-bb15-e51aa44e2118'
        AND (pv.supplier_sku = v_sku OR pv.sku = 'ASIA-' || v_sku)
      LIMIT 1
    ) INTO v_found;
    IF NOT v_found THEN
      api_sku := v_sku;
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_asia_find_not_found"("p_skus" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_fix_multi_main_images"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier_id uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_demovidos   int  := 0;
  v_atualizados int  := 0;
BEGIN
  -- Política canônica:
  --   A imagem MAIN que FICA é a que tem cloudflare_image_id = 'asia-' || lower(supplier_reference) || '-01'
  --   As demais main images (cor-específicas) são rebaixadas para 'gallery'
  --
  -- Para produtos onde a imagem '-01' NÃO existe, mantém a de menor display_order
  -- (tie-breaker: menor cf_id alfabético)

  WITH
  -- Identificar produtos com múltiplas main images
  multi_main AS (
    SELECT pi.product_id
    FROM product_images pi
    JOIN products p ON p.id = pi.product_id
    WHERE p.supplier_id = v_supplier_id
      AND pi.image_type = 'main' AND pi.is_active = true
    GROUP BY pi.product_id
    HAVING COUNT(*) > 1
  ),
  -- Para cada produto, determinar qual é o canônico (keeper)
  canonical AS (
    SELECT DISTINCT ON (pi.product_id)
      pi.product_id,
      pi.id AS keeper_id,
      pi.cloudflare_image_id AS keeper_cf_id
    FROM product_images pi
    JOIN products p ON p.id = pi.product_id
    JOIN multi_main mm ON mm.product_id = pi.product_id
    WHERE pi.image_type = 'main' AND pi.is_active = true
    ORDER BY
      pi.product_id,
      -- Prioridade 1: o que termina em '-01' (padrão da API)
      CASE WHEN pi.cloudflare_image_id = 'asia-' || lower(p.supplier_reference) || '-01' THEN 0 ELSE 1 END,
      -- Prioridade 2: menor display_order
      pi.display_order,
      -- Prioridade 3: CF ID alfabético (tie-breaker determinístico)
      pi.cloudflare_image_id
  )
  -- Rebaixar todos os NON-canonical de main → gallery
  UPDATE product_images pi
  SET image_type  = 'gallery',
      updated_at  = now()
  FROM canonical c
  WHERE pi.product_id = c.product_id
    AND pi.id        <> c.keeper_id
    AND pi.image_type = 'main'
    AND pi.is_active  = true;

  GET DIAGNOSTICS v_demovidos = ROW_COUNT;

  -- Atualizar primary_image_url nos produtos para o canonical CF URL
  WITH canonical2 AS (
    SELECT DISTINCT ON (pi.product_id)
      pi.product_id,
      'https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/' || pi.cloudflare_image_id || '/public' AS canonical_url
    FROM product_images pi
    JOIN products p ON p.id = pi.product_id
    WHERE p.supplier_id = v_supplier_id
      AND pi.image_type = 'main' AND pi.is_active = true
      AND p.primary_image_url NOT ILIKE '%' || pi.cloudflare_image_id || '%'
    ORDER BY pi.product_id, pi.display_order, pi.cloudflare_image_id
  )
  UPDATE products p
  SET primary_image_url = c2.canonical_url, updated_at = now()
  FROM canonical2 c2
  WHERE p.id = c2.product_id;

  GET DIAGNOSTICS v_atualizados = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'imagens_demovidas_para_gallery', v_demovidos,
    'produtos_primary_url_atualizado', v_atualizados,
    'executado_em', now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_asia_fix_multi_main_images"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_harvest_queue_batch"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net'
    AS $$
DECLARE
  v_succeeded  integer := 0;
  v_dup        integer := 0;
  v_failed     integer := 0;
  v_rec        RECORD;
  v_inner_json jsonb;
  v_outcome    text;
  v_cf_url     text;
  c_org CONSTANT uuid := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
  c_tid_main    CONSTANT uuid := '7ea182ff-edcc-4c4c-b7a1-443b07500f6c';
BEGIN
  FOR v_rec IN
    SELECT
      m.request_id,
      m.queue_id,
      m.cf_custom_id,
      q.product_id,
      q.image_type,
      q.display_order,
      q.url_original,
      r.status_code,
      (r.content::jsonb)->'result'->'content'->0->>'text' AS inner_text
    FROM asia_upload_mapping m
    JOIN net._http_response r         ON r.id  = m.request_id
    JOIN asia_image_import_queue q    ON q.id  = m.queue_id
    WHERE m.status = 'pending'
      AND r.status_code IS NOT NULL
  LOOP
    v_inner_json := NULL;
    BEGIN
      IF v_rec.inner_text LIKE '{%}' THEN
        v_inner_json := v_rec.inner_text::jsonb;
      END IF;
    EXCEPTION WHEN OTHERS THEN v_inner_json := NULL; END;

    v_outcome := CASE
      WHEN v_inner_json IS NOT NULL AND v_inner_json->>'id' IS NOT NULL THEN 'uploaded'
      WHEN v_rec.inner_text LIKE '%already exists%' OR v_rec.inner_text LIKE '%5414%' THEN 'duplicate'
      WHEN v_rec.status_code != 200 OR v_rec.inner_text ILIKE '%error%' OR v_rec.inner_text IS NULL THEN 'error'
      ELSE 'unknown'
    END;

    v_cf_url := 'https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/' || v_rec.cf_custom_id || '/public';

    IF v_outcome IN ('uploaded', 'duplicate') THEN
      -- Inserir em product_images
      INSERT INTO product_images (
        product_id, cloudflare_image_id, url_cdn, url_original, filename,
        image_type, image_type_id, is_primary, display_order,
        source_supplier, supplier_code, is_active, organization_id
      )
      VALUES (
        v_rec.product_id, v_rec.cf_custom_id, v_cf_url, v_rec.url_original,
        v_rec.cf_custom_id || '.jpg',
        v_rec.image_type,
        CASE v_rec.image_type WHEN 'main' THEN c_tid_main
                              ELSE '1590e144-e3f8-41e6-98f9-f4a25bae496d'::uuid END,
        v_rec.image_type = 'main',
        v_rec.display_order,
        'ASIA', 'ASIA', true, c_org
      )
      ON CONFLICT (cloudflare_image_id) DO UPDATE SET
        url_cdn    = EXCLUDED.url_cdn,
        updated_at = NOW();

      -- Atualizar primary_image_url (inclui URLs externas)
      IF v_rec.image_type = 'main' THEN
        UPDATE products
        SET primary_image_url = v_cf_url, updated_at = NOW()
        WHERE id = v_rec.product_id
          AND (primary_image_url IS NULL OR primary_image_url NOT LIKE '%imagedelivery%');
      END IF;

      -- Fechar fila
      UPDATE asia_image_import_queue
      SET status = 'done', cloudflare_image_id = v_rec.cf_custom_id,
          cf_url_cdn = v_cf_url, updated_at = NOW()
      WHERE id = v_rec.queue_id;

      IF v_outcome = 'duplicate' THEN v_dup := v_dup + 1;
      ELSE v_succeeded := v_succeeded + 1; END IF;

    ELSE
      UPDATE asia_image_import_queue
      SET status = 'error', last_error = LEFT(COALESCE(v_rec.inner_text,'no_response'), 200),
          updated_at = NOW()
      WHERE id = v_rec.queue_id;
      v_failed := v_failed + 1;
    END IF;

    UPDATE asia_upload_mapping
    SET status = v_outcome, harvested_at = NOW()
    WHERE request_id = v_rec.request_id;

  END LOOP;

  RETURN jsonb_build_object(
    'succeeded', v_succeeded, 'duplicates', v_dup, 'failed', v_failed,
    'still_pending_mapping', (SELECT COUNT(*) FROM asia_upload_mapping WHERE status='pending')
  );
END;
$$;


ALTER FUNCTION "public"."fn_asia_harvest_queue_batch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_import_youtube_videos"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_supplier_id  uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_org_id       uuid := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
  v_inserted     int  := 0;
  v_skipped      int  := 0;
  v_no_product   int  := 0;
  v_error_url    int  := 0;
  v_rec          record;
  v_yt_id        text;
  v_product_id   uuid;
  v_codigo       text;
BEGIN
  FOR v_rec IN
    SELECT DISTINCT
      -- FIX P2: usa codigo do site_data; se NULL, extrai do supplier_sku removendo sufixo de cor
      COALESCE(
        NULLIF(upper(spr.site_data->>'codigo'), ''),
        upper(regexp_replace(spr.supplier_sku, '-[^-]+$', ''))
      ) AS codigo,
      url_elem AS embed_url
    FROM supplier_products_raw spr
    CROSS JOIN LATERAL jsonb_array_elements_text(spr.site_data->'video_embed_urls') AS url_elem
    WHERE spr.supplier_id = v_supplier_id
      AND spr.site_data ? 'video_embed_urls'
      AND jsonb_array_length(spr.site_data->'video_embed_urls') > 0
      AND url_elem <> ''   -- FIX P1: ignora strings vazias cedo
  LOOP
    -- FIX P1: extrai ID de /embed/ OU de /shorts/
    v_yt_id := COALESCE(
      substring(v_rec.embed_url FROM '/embed/([a-zA-Z0-9_-]{11})'),
      substring(v_rec.embed_url FROM '/shorts/([a-zA-Z0-9_-]{11})')
    );

    IF v_yt_id IS NULL OR v_yt_id = '' THEN
      v_error_url := v_error_url + 1;
      CONTINUE;
    END IF;

    v_codigo := v_rec.codigo;

    SELECT p.id INTO v_product_id
    FROM products p
    WHERE p.supplier_id = v_supplier_id
      AND upper(p.supplier_reference) = v_codigo
    LIMIT 1;

    IF v_product_id IS NULL THEN
      v_no_product := v_no_product + 1;
      CONTINUE;
    END IF;

    IF EXISTS (
      SELECT 1 FROM product_videos pv
      WHERE pv.product_id       = v_product_id
        AND pv.source_youtube_id = v_yt_id
    ) THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    INSERT INTO product_videos (
      product_id, cloudflare_video_id, url_stream, url_thumbnail,
      url_original, source_youtube_id, cloudflare_status, video_type,
      is_primary, display_order, source_supplier, organization_id,
      is_active, created_at, updated_at
    ) VALUES (
      v_product_id, v_yt_id, v_rec.embed_url,
      'https://img.youtube.com/vi/' || v_yt_id || '/hqdefault.jpg',
      v_rec.embed_url, v_yt_id, 'youtube', 'promo',
      true, 1, 'ASIA', v_org_id, true, now(), now()
    );
    v_inserted := v_inserted + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true, 'inserted', v_inserted, 'skipped', v_skipped,
    'no_product', v_no_product, 'error_url', v_error_url, 'ts', now()
  );
END;
$_$;


ALTER FUNCTION "public"."fn_asia_import_youtube_videos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_ingest_all_pages"("p_por_pagina" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_api_key    text := public.fn_get_asia_api_key();
  v_secret_key text := public.fn_get_asia_secret_key();
  v_url        text := 'https://api.asiaimport.com.br/';
  v_inseridos  int  := 0;
  v_atualizados int := 0;
  v_erros      int  := 0;
  v_paginas    int  := 0;
  v_req_id     bigint;
  v_status     int;
  v_content    text;
  v_resp       jsonb;
  v_produtos   jsonb;
  v_result     jsonb;
  v_total_pag  int  := 5;  -- 5 páginas × 100 = 500 produtos (cobre os 455)
  i            int;
  v_t0         timestamptz := clock_timestamp();
BEGIN
  IF v_api_key IS NULL OR v_secret_key IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','credenciais_nao_configuradas');
  END IF;

  FOR i IN 1..v_total_pag LOOP
    BEGIN
      SELECT net.http_post(
        url     := v_url,
        headers := jsonb_build_object('Content-Type', 'application/x-www-form-urlencoded'),
        body    := ('api_key=' || v_api_key ||
                    '&secret_key=' || v_secret_key ||
                    '&funcao=listarProdutos2' ||
                    '&pagina=' || i::text ||
                    '&por_pagina=' || p_por_pagina::text)::bytea
      ) INTO v_req_id;

      -- Aguardar resposta async
      PERFORM pg_sleep(3);

      SELECT status_code, content::text
      INTO v_status, v_content
      FROM net._http_response WHERE id = v_req_id;

      IF v_status = 200 AND v_content IS NOT NULL THEN
        v_resp     := v_content::jsonb;
        v_produtos := COALESCE(v_resp->'produtos', '[]'::jsonb);

        IF jsonb_array_length(v_produtos) = 0 THEN
          EXIT;  -- Sem mais páginas
        END IF;

        v_result      := public.fn_ingest_asia_api_batch(v_produtos);
        v_inseridos   := v_inseridos   + COALESCE((v_result->>'inseridos')::int, 0);
        v_atualizados := v_atualizados + COALESCE((v_result->>'atualizados')::int, 0);
        v_erros       := v_erros       + COALESCE((v_result->>'erros')::int, 0);
        v_paginas     := v_paginas + 1;
      ELSE
        v_erros := v_erros + 1;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
    END;
  END LOOP;

  -- Disparar pipeline Bronze → Silver → Gold para novos/atualizados
  IF v_inseridos + v_atualizados > 0 THEN
    PERFORM public.fn_pipeline_promote_tick();
  END IF;

  RETURN jsonb_build_object(
    'success',      true,
    'paginas',      v_paginas,
    'inseridos',    v_inseridos,
    'atualizados',  v_atualizados,
    'erros',        v_erros,
    'segundos',     round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,1)
  );
END;
$$;


ALTER FUNCTION "public"."fn_asia_ingest_all_pages"("p_por_pagina" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_legacy_dispatch_batch"("p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'archive'
    AS $$
DECLARE
  v_count   INT := 0;
  v_item    RECORD;
  v_req_id  BIGINT;
  v_mcp_id  INT := 0;
BEGIN
  FOR v_item IN
    SELECT id, product_id, source_url, cf_custom_id, supplier_code
    FROM asia_legacy_upload_queue
    WHERE status = 'pending' AND attempt_count < 3
    ORDER BY created_at
    LIMIT p_limit
  LOOP
    v_mcp_id := v_mcp_id + 1;

    SELECT net.http_post(
      url := 'https://cloudflare-deploy-mcp.adm01.workers.dev/mcp',
      body := jsonb_build_object(
        'jsonrpc', '2.0',
        'id', v_mcp_id,
        'method', 'tools/call',
        'params', jsonb_build_object(
          'name', 'cf_images_upload_url',
          'arguments', jsonb_build_object(
            'source_url', v_item.source_url,
            'custom_id',  v_item.cf_custom_id,
            'metadata',   jsonb_build_object(
              'supplier',   v_item.supplier_code,
              'product_id', v_item.product_id::text,
              'pipeline',   'asia_legacy'
            )
          )
        )
      ),
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Accept', 'application/json, text/event-stream'
      ),
      timeout_milliseconds := 30000
    ) INTO v_req_id;

    UPDATE asia_legacy_upload_queue
    SET status = 'uploading',
        request_id = v_req_id,
        attempt_count = attempt_count + 1,
        updated_at = NOW()
    WHERE id = v_item.id;

    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('dispatched', v_count);
END;
$$;


ALTER FUNCTION "public"."fn_asia_legacy_dispatch_batch"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_legacy_harvest_batch"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'archive'
    AS $$
DECLARE
  v_done     INT := 0;
  v_fail     INT := 0;
  v_item     RECORD;
  v_resp     RECORD;
  v_body     TEXT;
  v_cf_id    TEXT;
  v_cf_url   TEXT;
  v_org      CONSTANT UUID := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
  v_cdnbase  CONSTANT TEXT := 'https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw';
BEGIN
  FOR v_item IN
    SELECT q.id, q.product_id, q.request_id, q.cf_custom_id,
           q.source_url, q.supplier_code
    FROM asia_legacy_upload_queue q
    WHERE q.status = 'uploading' AND q.request_id IS NOT NULL
  LOOP
    SELECT * INTO v_resp FROM net._http_response
    WHERE id = v_item.request_id LIMIT 1;

    IF NOT FOUND THEN CONTINUE; END IF;

    v_body := COALESCE(v_resp.content, '');

    -- Verificar se houve erro HTTP
    IF v_resp.status_code NOT IN (200, 201) THEN
      UPDATE asia_legacy_upload_queue
      SET status = 'error',
          error_msg = LEFT('HTTP ' || v_resp.status_code::text || ': ' || v_body, 300),
          updated_at = NOW()
      WHERE id = v_item.id;
      v_fail := v_fail + 1;
      CONTINUE;
    END IF;

    -- Extração do cf_image_id da resposta SSE/JSON
    -- O MCP Worker retorna SSE com "data: {...}" contendo o resultado
    BEGIN
      -- Tentar parsear como JSON direto
      v_cf_id := (v_body::jsonb->'result'->'content'->0->'text')::text;
      IF v_cf_id IS NOT NULL THEN
        -- É texto com o JSON da resposta CF dentro
        v_cf_id := ((v_cf_id::text)::jsonb->>'id');
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_cf_id := NULL;
    END;

    -- Fallback: regex para extrair "id":"..."
    IF v_cf_id IS NULL OR TRIM(REPLACE(v_cf_id, '"', '')) = '' THEN
      v_cf_id := (REGEXP_MATCH(v_body, '"id"\s*:\s*"([a-z0-9A-Z\-_]+)"'))[1];
    END IF;

    -- Se a resposta menciona "already exists", usar o custom_id
    IF v_cf_id IS NULL AND v_body ILIKE '%already exists%' THEN
      v_cf_id := v_item.cf_custom_id;
    END IF;

    IF v_cf_id IS NULL OR TRIM(v_cf_id) = '' THEN
      -- Fallback final: usar o cf_custom_id
      -- (CF aceita o custom_id como ID se o upload foi aceito)
      IF v_body ILIKE '%"success":true%' OR v_body ILIKE '%asia-%' THEN
        v_cf_id := v_item.cf_custom_id;
      ELSE
        UPDATE asia_legacy_upload_queue
        SET status = 'error',
            error_msg = LEFT('no_cf_id: ' || v_body, 300),
            updated_at = NOW()
        WHERE id = v_item.id;
        v_fail := v_fail + 1;
        CONTINUE;
      END IF;
    END IF;

    v_cf_id := TRIM(REPLACE(v_cf_id, '"', ''));
    v_cf_url := v_cdnbase || '/' || v_cf_id || '/public';

    -- Inserir product_images (trigger fn_sync_product_images_to_products
    -- atualiza products.primary_image_url automaticamente)
    BEGIN
      INSERT INTO product_images (
        product_id, cloudflare_image_id, url_cdn, url_original,
        image_type, is_primary, is_active, display_order,
        source_supplier, organization_id,
        filename, alt_text
      ) VALUES (
        v_item.product_id,
        v_cf_id,
        v_cf_url,
        v_item.source_url,
        'main', true, true, 1,
        v_item.supplier_code,
        v_org,
        SPLIT_PART(v_item.source_url, '/', -1),
        SPLIT_PART(v_item.source_url, '/', -1)
      )
      ON CONFLICT (cloudflare_image_id) DO NOTHING;

      UPDATE asia_legacy_upload_queue
      SET status = 'done',
          cf_image_id = v_cf_id,
          updated_at = NOW()
      WHERE id = v_item.id;

      v_done := v_done + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE asia_legacy_upload_queue
      SET status = 'error',
          error_msg = LEFT(SQLERRM, 300),
          updated_at = NOW()
      WHERE id = v_item.id;
      v_fail := v_fail + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('harvested_ok', v_done, 'harvested_fail', v_fail);
END;
$$;


ALTER FUNCTION "public"."fn_asia_legacy_harvest_batch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_legacy_run_cycle"("p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'archive'
    AS $$
DECLARE
  v_lock     BOOLEAN;
  v_dispatch JSONB;
  v_harvest  JSONB;
  v_pending  INT; v_uploading INT; v_done INT; v_error INT;
BEGIN
  v_lock := pg_try_advisory_xact_lock(hashtext('fn_asia_legacy_run_cycle')::BIGINT);
  IF NOT v_lock THEN RETURN jsonb_build_object('status', 'skipped_lock'); END IF;

  v_harvest  := fn_asia_legacy_harvest_batch();
  v_dispatch := fn_asia_legacy_dispatch_batch(p_limit);

  SELECT COUNT(*) FILTER (WHERE status='pending')   INTO v_pending   FROM asia_legacy_upload_queue;
  SELECT COUNT(*) FILTER (WHERE status='uploading') INTO v_uploading FROM asia_legacy_upload_queue;
  SELECT COUNT(*) FILTER (WHERE status='done')      INTO v_done      FROM asia_legacy_upload_queue;
  SELECT COUNT(*) FILTER (WHERE status='error')     INTO v_error     FROM asia_legacy_upload_queue;

  RETURN jsonb_build_object(
    'status', 'ok',
    'dispatch', v_dispatch, 'harvest', v_harvest,
    'pending', v_pending, 'uploading', v_uploading,
    'done', v_done, 'error', v_error
  );
END;
$$;


ALTER FUNCTION "public"."fn_asia_legacy_run_cycle"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_asia_legacy_run_cycle"("p_limit" integer) IS 'Dispatch+harvest upload CF Images para produtos ASIA/XBZ legados. 20 itens/ciclo.';



CREATE OR REPLACE FUNCTION "public"."fn_asia_link_video"("p_queue_id" "uuid", "p_youtube_id" "text", "p_cf_stream_uid" "text", "p_url_hls" "text", "p_url_thumbnail" "text", "p_url_embed" "text", "p_duration_seconds" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated    int;
  v_pid        uuid;
  -- FIXED 2026-06-14: accountHash correto (era cd0f4eee...)
  v_cf_sub     CONSTANT text := 'customer-ksi0mrlcw6rwzezz';
  v_hls        text;
  v_thumbnail  text;
  v_embed      text;
BEGIN
  v_hls       := 'https://' || v_cf_sub || '.cloudflarestream.com/' || p_cf_stream_uid || '/manifest/video.m3u8';
  v_thumbnail := 'https://' || v_cf_sub || '.cloudflarestream.com/' || p_cf_stream_uid || '/thumbnails/thumbnail.jpg';
  v_embed     := 'https://iframe.cloudflarestream.com/' || p_cf_stream_uid;

  -- 1. product_videos: youtube → ready (pode afetar múltiplos produtos)
  UPDATE product_videos
  SET
    cloudflare_video_id = p_cf_stream_uid,
    url_stream          = v_embed,
    url_hls             = v_hls,
    url_thumbnail       = v_thumbnail,
    cloudflare_status   = 'ready',
    duration_seconds    = COALESCE(p_duration_seconds, duration_seconds),
    uploaded_at         = now(),
    updated_at          = now()
  WHERE source_youtube_id = p_youtube_id
    AND source_supplier   = 'ASIA'
    AND is_active         = true;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- 2. Atualizar products.videos cache para CADA produto afetado
  FOR v_pid IN
    SELECT DISTINCT product_id FROM product_videos
    WHERE source_youtube_id = p_youtube_id
      AND source_supplier   = 'ASIA'
      AND is_active         = true
  LOOP
    UPDATE products
    SET
      videos = (
        SELECT jsonb_agg(
          CASE
            WHEN entry->>'youtube_id' = p_youtube_id THEN
              jsonb_build_object(
                'id',         (SELECT id::text FROM product_videos
                               WHERE source_youtube_id = p_youtube_id
                                 AND source_supplier = 'ASIA'
                                 AND product_id = v_pid LIMIT 1),
                'youtube_id', p_youtube_id,
                'cf_uid',     p_cf_stream_uid,
                'embed_url',  v_embed,
                'hls_url',    v_hls,
                'thumbnail',  v_thumbnail,
                'watch_url',  entry->>'watch_url',
                'is_primary', (entry->>'is_primary')::boolean,
                'title',      entry->>'title',
                'plataforma', 'cloudflare_stream',
                'duration_s', p_duration_seconds
              )
            ELSE entry
          END
          ORDER BY (entry->>'is_primary')::boolean DESC NULLS LAST
        )
        FROM jsonb_array_elements(videos) AS entry
      ),
      updated_at = now()
    WHERE id = v_pid
      AND videos IS NOT NULL
      AND jsonb_array_length(videos) > 0;
  END LOOP;

  -- 3. video_import_queue: linked
  UPDATE video_import_queue
  SET
    cloudflare_video_id         = p_cf_stream_uid,
    cloudflare_hls              = v_hls,
    cloudflare_thumbnail        = v_thumbnail,
    cloudflare_embed            = v_embed,
    cloudflare_duration_seconds = p_duration_seconds,
    status                      = 'linked',
    completed_at                = now()
  WHERE id = p_queue_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'youtube_id',     p_youtube_id,
    'cf_stream_uid',  p_cf_stream_uid,
    'videos_updated', v_updated
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;
$$;


