CREATE OR REPLACE FUNCTION "public"."fn_asia_monitor_variants"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier_id       uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_baseline_inativas int  := 26;   -- estado intencional após limpeza 2026-06-08
  v_limite_alerta     int  := 40;   -- 54% acima do baseline = investigar
  v_inativas          int;
  v_ativas            int;
  v_stock_neg         int;
  v_sem_sku           int;
  v_dup_sku           int;
  v_alert             boolean := false;
  v_msgs              text[]  := '{}';
BEGIN
  SELECT COUNT(*) INTO v_inativas FROM product_variants pv JOIN products p ON p.id=pv.product_id WHERE p.supplier_id=v_supplier_id AND pv.is_active=false;
  SELECT COUNT(*) INTO v_ativas   FROM product_variants pv JOIN products p ON p.id=pv.product_id WHERE p.supplier_id=v_supplier_id AND pv.is_active=true;
  SELECT COUNT(*) INTO v_stock_neg FROM product_variants pv JOIN products p ON p.id=pv.product_id WHERE p.supplier_id=v_supplier_id AND pv.stock_quantity < 0;
  SELECT COUNT(*) INTO v_sem_sku   FROM product_variants pv JOIN products p ON p.id=pv.product_id WHERE p.supplier_id=v_supplier_id AND (pv.sku IS NULL OR pv.sku='');
  SELECT COUNT(*) INTO v_dup_sku   FROM (SELECT pv.sku FROM product_variants pv JOIN products p ON p.id=pv.product_id WHERE p.supplier_id=v_supplier_id AND pv.is_active=true GROUP BY pv.sku HAVING COUNT(*)>1) d;

  IF v_inativas > v_limite_alerta     THEN v_alert:=true; v_msgs:=array_append(v_msgs,'ALERTA: inativas='||v_inativas||' > limite='||v_limite_alerta); END IF;
  IF v_stock_neg > 0                  THEN v_alert:=true; v_msgs:=array_append(v_msgs,'ALERTA: stock_negativo='||v_stock_neg); END IF;
  IF v_sem_sku > 0                    THEN v_alert:=true; v_msgs:=array_append(v_msgs,'ALERTA: sem_sku='||v_sem_sku); END IF;
  IF v_dup_sku > 0                    THEN v_alert:=true; v_msgs:=array_append(v_msgs,'ALERTA: sku_duplicados='||v_dup_sku); END IF;

  RETURN jsonb_build_object(
    'ok', NOT v_alert, 'checado_em', now(),
    'variants_ativas', v_ativas, 'variants_inativas', v_inativas,
    'baseline_intencional', v_baseline_inativas, 'limite_alerta', v_limite_alerta,
    'stock_negativo', v_stock_neg, 'sem_sku', v_sem_sku, 'sku_duplicados', v_dup_sku,
    'alertas', to_jsonb(v_msgs)
  );
END;
$$;


ALTER FUNCTION "public"."fn_asia_monitor_variants"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_populate_image_queue"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inseridos INT := 0;
BEGIN
  /*
    Gera CF IDs no padrão: asia-{sku_lower}-{lpad(ordem,2,'0')}
    Exemplo: asia-bac008-01, asia-bac008-02 ...
    Deduplica por url_original (UNIQUE na tabela).
    Pula imagens já em product_images com CF ID válido e source_supplier='ASIA'.
  */
  WITH imagens_brutas AS (
    SELECT DISTINCT ON (img->>'url_origem')
      lower(spr.site_data->>'codigo')                                     AS codigo_pai,
      img->>'url_origem'                                                   AS url_original,
      CASE WHEN img->>'tipo' = 'principal' THEN 'main' ELSE 'gallery' END AS image_type,
      (img->>'ordem')::int                                                 AS ordem,
      p.id                                                                 AS product_id
    FROM public.supplier_products_raw spr
    CROSS JOIN jsonb_array_elements(
      coalesce(spr.site_data->'imagens', '[]'::jsonb)
    ) AS img
    JOIN public.products p
      ON p.sku = spr.site_data->>'codigo'
    JOIN public.produtos_padronizacao pp
      ON pp.product_id = p.id
     AND pp.supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'
    WHERE spr.supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'
      AND spr.site_data IS NOT NULL
      AND (img->>'url_origem') IS NOT NULL
      AND length(img->>'url_origem') > 10
      -- pular imagens já importadas com sucesso
      AND NOT EXISTS (
        SELECT 1 FROM public.product_images pi
        WHERE pi.url_original    = img->>'url_origem'
          AND pi.source_supplier = 'ASIA'
          AND pi.cloudflare_image_id IS NOT NULL
      )
    ORDER BY img->>'url_origem', spr.supplier_sku
  )
  INSERT INTO public.asia_image_import_queue
    (codigo_pai, url_original, cf_image_id_canonical, image_type, display_order, product_id)
  SELECT
    codigo_pai,
    url_original,
    'asia-' || codigo_pai || '-' || lpad(ordem::text, 2, '0') AS cf_image_id_canonical,
    image_type,
    ordem,
    product_id
  FROM imagens_brutas
  ON CONFLICT (url_original) DO NOTHING;

  GET DIAGNOSTICS v_inseridos = ROW_COUNT;

  RETURN jsonb_build_object(
    'inseridos', v_inseridos,
    'ts',        now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_asia_populate_image_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_recover_stale_queue"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_recovered integer; v_retried integer; v_mapping_stale integer;
BEGIN
  -- Reset uploading → pending (stuck > 5 min)
  UPDATE asia_image_import_queue
  SET status = 'pending', updated_at = NOW()
  WHERE status = 'uploading' AND updated_at < NOW() - INTERVAL '5 minutes';
  GET DIAGNOSTICS v_recovered = ROW_COUNT;

  -- Retry errors transientes (≤ 2 tentativas)
  UPDATE asia_image_import_queue
  SET status = 'pending', updated_at = NOW()
  WHERE status = 'error' AND attempts <= 2;
  GET DIAGNOSTICS v_retried = ROW_COUNT;

  -- Stale mappings
  UPDATE asia_upload_mapping SET status = 'stale'
  WHERE status = 'pending' AND created_at < NOW() - INTERVAL '5 minutes';
  GET DIAGNOSTICS v_mapping_stale = ROW_COUNT;

  RETURN jsonb_build_object(
    'queue_recovered', v_recovered, 'errors_retried', v_retried,
    'mapping_stale', v_mapping_stale
  );
END;
$$;


ALTER FUNCTION "public"."fn_asia_recover_stale_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_run_image_cycle"("p_limit" integer DEFAULT 20, "p_wait_seconds" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net'
    AS $$
DECLARE
  v_lock    boolean;
  v_dispatch jsonb;
  v_harvest  jsonb;
  v_stale    jsonb;
BEGIN
  v_lock := pg_try_advisory_lock(74108913);
  IF NOT v_lock THEN
    RETURN jsonb_build_object(
      'status', 'skipped_already_running',
      'pending_queue', (SELECT COUNT(*) FROM asia_image_import_queue WHERE status = 'pending')
    );
  END IF;

  BEGIN
    v_stale   := fn_asia_recover_stale_queue();
    PERFORM fn_asia_harvest_queue_batch();

    IF (SELECT COUNT(*) FROM asia_image_import_queue WHERE status = 'pending') = 0 THEN
      PERFORM pg_advisory_unlock(74108913);
      RETURN jsonb_build_object('status', 'no_pending', 'stale', v_stale);
    END IF;

    v_dispatch := fn_asia_dispatch_queue_batch(p_limit);

    IF (v_dispatch->>'dispatched')::int = 0 THEN
      PERFORM pg_advisory_unlock(74108913);
      RETURN jsonb_build_object('status', 'dispatch_empty', 'stale', v_stale);
    END IF;

    PERFORM pg_sleep(p_wait_seconds);
    v_harvest := fn_asia_harvest_queue_batch();

    PERFORM pg_advisory_unlock(74108913);

    RETURN jsonb_build_object(
      'status',        'ok',
      'dispatched',    v_dispatch->>'dispatched',
      'harvest',       v_harvest,
      'stale',         v_stale,
      'pending_queue', (SELECT COUNT(*) FROM asia_image_import_queue WHERE status = 'pending')
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_advisory_unlock(74108913);
    RAISE;
  END;
END;
$$;


ALTER FUNCTION "public"."fn_asia_run_image_cycle"("p_limit" integer, "p_wait_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_site_promote_to_gold"("p_limit" integer DEFAULT NULL::integer, "p_only_new" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ASIA     uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_linked   int  := 0;
  v_phys     int  := 0;
  v_scalars  int  := 0;
  v_promoted int  := 0;
  v_zombies  int  := 0;
BEGIN

  -- ── STEP -1: Limpar produtos-zombie com supplier_reference IS NULL
  WITH zombie_candidates AS (
    SELECT p.id AS zombie_id
    FROM products p
    WHERE p.supplier_id = v_ASIA
      AND (p.supplier_reference IS NULL OR p.supplier_reference = '')
      AND p.is_active = false
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.is_active=true)
      AND NOT EXISTS (SELECT 1 FROM product_videos pv WHERE pv.product_id=p.id AND pv.is_active=true)
      AND EXISTS (
        SELECT 1 FROM products p2
        WHERE p2.supplier_id = v_ASIA
          AND p2.is_active = true
          AND p2.supplier_reference IS NOT NULL
          AND lower(trim(p2.name)) = lower(trim(p.name))
      )
  )
  DELETE FROM product_variants pv2
  USING zombie_candidates zc
  WHERE pv2.product_id = zc.zombie_id;

  WITH zombie_products AS (
    SELECT p.id AS zombie_id
    FROM products p
    WHERE p.supplier_id = v_ASIA
      AND (p.supplier_reference IS NULL OR p.supplier_reference = '')
      AND p.is_active = false
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.is_active=true)
      AND NOT EXISTS (SELECT 1 FROM product_videos pv WHERE pv.product_id=p.id AND pv.is_active=true)
      AND EXISTS (
        SELECT 1 FROM products p2
        WHERE p2.supplier_id = v_ASIA AND p2.is_active = true
          AND p2.supplier_reference IS NOT NULL
          AND lower(trim(p2.name)) = lower(trim(p.name))
      )
  )
  DELETE FROM products p3 USING zombie_products zp WHERE p3.id = zp.zombie_id;
  GET DIAGNOSTICS v_zombies = ROW_COUNT;

  -- ── STEP 0: Vincular product_id via Silver principal
  WITH lnk AS (
    SELECT s.id, p.product_id
    FROM public.produtos_site_padronizacao s
    JOIN public.produtos_padronizacao p
      ON p.supplier_id = s.supplier_id
     AND p.supplier_reference = s.supplier_reference
    WHERE s.supplier_id = v_ASIA
      AND p.product_id IS NOT NULL
      AND s.product_id IS NULL
      AND s.status <> 'rejected'
  )
  UPDATE public.produtos_site_padronizacao t
     SET product_id = lnk.product_id, updated_at = now()
    FROM lnk WHERE t.id = lnk.id;
  GET DIAGNOSTICS v_linked = ROW_COUNT;

  CREATE TEMP TABLE _asia_site_scope ON COMMIT DROP AS
    SELECT s.* FROM public.produtos_site_padronizacao s
    WHERE s.supplier_id = v_ASIA
      AND s.product_id IS NOT NULL
      AND s.status = CASE WHEN p_only_new
                          THEN 'standardized'::public.produtos_padronizacao_status
                          ELSE s.status END
      AND s.status <> 'rejected'
    LIMIT COALESCE(p_limit, 1000000000);

  IF NOT EXISTS (SELECT 1 FROM _asia_site_scope) THEN
    RETURN jsonb_build_object(
      'linked', v_linked, 'note', 'nada_novo', 'zombies_removidos', v_zombies
    );
  END IF;

  -- (e) product_physical: peso + dimensoes (incluindo circumference_cm)
  INSERT INTO public.product_physical (
    product_id, weight_g, height_cm, width_cm, length_cm, circumference_cm
  )
  SELECT
    product_id,
    weight_g::numeric,
    height_cm,
    width_cm,
    depth_cm,
    circumference_cm
  FROM _asia_site_scope
  WHERE weight_g IS NOT NULL OR height_cm IS NOT NULL
     OR width_cm IS NOT NULL  OR depth_cm IS NOT NULL
     OR circumference_cm IS NOT NULL
  ON CONFLICT (product_id) DO UPDATE SET
    weight_g         = COALESCE(public.product_physical.weight_g,         EXCLUDED.weight_g),
    height_cm        = COALESCE(public.product_physical.height_cm,        EXCLUDED.height_cm),
    width_cm         = COALESCE(public.product_physical.width_cm,         EXCLUDED.width_cm),
    length_cm        = COALESCE(public.product_physical.length_cm,        EXCLUDED.length_cm),
    circumference_cm = COALESCE(public.product_physical.circumference_cm, EXCLUDED.circumference_cm),
    updated_at = now();
  GET DIAGNOSTICS v_phys = ROW_COUNT;

  -- (f) products: propagar circumference_cm diretamente na tabela Gold
  -- (fill-only — não sobrescreve valor já preenchido manualmente)
  UPDATE public.products p SET
    circumference_cm = COALESCE(p.circumference_cm, s.circumference_cm),
    updated_at       = now()
  FROM _asia_site_scope s
  WHERE p.id = s.product_id
    AND s.circumference_cm IS NOT NULL
    AND p.circumference_cm IS NULL;

  -- (h) products: fill-only escalares WP-exclusive
  UPDATE public.products p SET
    brand                  = COALESCE(p.brand,                  s.brand),
    min_order_quantity     = COALESCE(p.min_order_quantity,     s.moq),
    min_quantity           = COALESCE(p.min_quantity,           s.min_quantity),
    requires_minimum_order = COALESCE(p.requires_minimum_order,
                               CASE WHEN s.moq IS NOT NULL THEN (s.moq > 1) ELSE NULL END),
    sale_price             = COALESCE(p.sale_price,             s.sale_price),
    is_on_sale             = COALESCE(p.is_on_sale,             s.is_on_sale),
    suggested_price        = COALESCE(p.suggested_price,        s.regular_price),
    updated_at             = now()
  FROM _asia_site_scope s
  WHERE p.id = s.product_id
    AND (s.brand IS NOT NULL OR s.moq IS NOT NULL
      OR s.sale_price IS NOT NULL OR s.regular_price IS NOT NULL
      OR s.is_on_sale IS NOT NULL);
  GET DIAGNOSTICS v_scalars = ROW_COUNT;

  -- Marcar promovidas
  UPDATE public.produtos_site_padronizacao t
     SET status      = 'promoted'::public.produtos_padronizacao_status,
         promoted_at = now(),
         updated_at  = now()
   WHERE t.id IN (SELECT id FROM _asia_site_scope);
  GET DIAGNOSTICS v_promoted = ROW_COUNT;

  RETURN jsonb_build_object(
    'linked',            v_linked,
    'physical',          v_phys,
    'scalars',           v_scalars,
    'promoted',          v_promoted,
    'zombies_removidos', v_zombies
  );
END;
$$;


ALTER FUNCTION "public"."fn_asia_site_promote_to_gold"("p_limit" integer, "p_only_new" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_asia_site_promote_to_gold"("p_limit" integer, "p_only_new" boolean) IS 'Promote WP site_data -> Gold para ASIA. Pattern supplier-especifico (consistente com fn_xbz_enrich_gold_extractors). Nao toca fn_site_promote_to_gold (XBZ).';



CREATE OR REPLACE FUNCTION "public"."fn_asia_stock_fast_sync"("p_skus" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_asia   uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_org    uuid := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
  r        jsonb;
  v_sku    text; v_stock int; v_price numeric; v_vid uuid; v_pid uuid;
  v_seen   int := 0; v_ok int := 0; v_nao int := 0; v_erros int := 0;
  v_nq_propagados int := 0; v_vss_nq_updated int := 0;
  v_prods  uuid[] := '{}';
  v_skus_processados text[] := '{}';
  v_t0     timestamptz := clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_asia_stock_fast_sync')::bigint) THEN
    RETURN jsonb_build_object('success', true, 'skipped', 'lock_ocupado');
  END IF;

  FOR r IN SELECT * FROM jsonb_array_elements(p_skus)
  LOOP
    BEGIN
      v_seen  := v_seen + 1;
      v_sku   := r->>'sku';
      v_stock := GREATEST(0, COALESCE(fn_safe_int(r->>'qtd_estoque'), 0));
      v_price := fn_safe_num(r->>'preco');

      IF v_sku IS NULL OR v_sku = '' THEN CONTINUE; END IF;

      SELECT pv.id, pv.product_id INTO v_vid, v_pid
      FROM product_variants pv
      JOIN products p ON p.id = pv.product_id
      WHERE p.supplier_id = v_asia
        AND (pv.supplier_sku = v_sku OR pv.sku = 'ASIA-' || v_sku)
        AND pv.is_active = true
      LIMIT 1;

      IF v_vid IS NULL THEN v_nao := v_nao + 1; CONTINUE; END IF;

      UPDATE product_variants
      SET stock_quantity = v_stock, updated_at = now()
      WHERE id = v_vid;

      INSERT INTO variant_supplier_sources (
        variant_id, supplier_id, quantity, cost_price,
        last_synced_at, sync_status, updated_at, organization_id
      ) VALUES (
        v_vid, v_asia, v_stock, v_price, now(), 'synced', now(), v_org
      )
      ON CONFLICT (variant_id, supplier_id) DO UPDATE SET
        quantity       = EXCLUDED.quantity,
        cost_price     = CASE WHEN EXCLUDED.cost_price > 0 THEN EXCLUDED.cost_price ELSE variant_supplier_sources.cost_price END,
        last_synced_at = now(), sync_status = 'synced', updated_at = now();

      v_ok := v_ok + 1;
      IF NOT (v_pid = ANY(v_prods)) THEN v_prods := array_append(v_prods, v_pid); END IF;
      v_skus_processados := array_append(v_skus_processados, v_sku);

    EXCEPTION WHEN OTHERS THEN v_erros := v_erros + 1;
    END;
  END LOOP;

  UPDATE products p
  SET stock_quantity = (SELECT COALESCE(SUM(pv.stock_quantity),0) FROM product_variants pv WHERE pv.product_id=p.id AND pv.is_active=true),
      last_sync_at=now(), updated_at=now()
  WHERE p.id = ANY(v_prods);

  -- PASSO 4: Bronze -> VSS (sem guard -- auditavel)
  UPDATE variant_supplier_sources vss
  SET
    next_quantity_1 = fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'quantidade'),
    next_date_1     = CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                      THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data',10)::date ELSE NULL END,
    next_quantity_2 = fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'quantidade'),
    next_date_2     = CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                      THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data',10)::date ELSE NULL END,
    next_quantity_3 = fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'quantidade'),
    next_date_3     = CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                      THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data',10)::date ELSE NULL END,
    updated_at      = now()
  FROM supplier_products_raw spr
  WHERE vss.supplier_id=v_asia AND spr.supplier_id=v_asia
    AND (vss.supplier_sku=spr.supplier_sku OR vss.supplier_sku='ASIA-'||spr.supplier_sku)
    AND spr.supplier_sku=ANY(v_skus_processados);
  GET DIAGNOSTICS v_vss_nq_updated = ROW_COUNT;

  -- PASSO 5: Bronze -> PV GOLD com GUARD > CURRENT_DATE
  -- FIX FINAL-02: nq1/nq2/nq3 agora usam o MESMO guard de regex dos ndX.
  -- Antes, nq1 fazia LEFT(COALESCE(...,''),10)::date sem regex -> ''::date -> erro 22007 (data NULL/vazia).
  PERFORM set_config('app.bulk_import_mode','true',true);
  WITH bronze_data AS (
    SELECT spr.supplier_sku AS sku,
           -- Guard: so datas futuras e ISO-validas chegam ao Gold
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data',10)::date > CURRENT_DATE
                THEN fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'quantidade') ELSE NULL END AS nq1,
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data',10)::date > CURRENT_DATE
                THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data',10)::date ELSE NULL END AS nd1,
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data',10)::date > CURRENT_DATE
                THEN fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'quantidade') ELSE NULL END AS nq2,
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data',10)::date > CURRENT_DATE
                THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data',10)::date ELSE NULL END AS nd2,
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data',10)::date > CURRENT_DATE
                THEN fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'quantidade') ELSE NULL END AS nq3,
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data',10)::date > CURRENT_DATE
                THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data',10)::date ELSE NULL END AS nd3
    FROM supplier_products_raw spr
    WHERE spr.supplier_id=v_asia AND spr.supplier_sku=ANY(v_skus_processados)
  )
  UPDATE product_variants pv
  SET next_quantity_1=b.nq1, next_date_1=b.nd1,
      next_quantity_2=b.nq2, next_date_2=b.nd2,
      next_quantity_3=b.nq3, next_date_3=b.nd3,
      updated_at=now()
  FROM bronze_data b
  WHERE (pv.supplier_sku=b.sku OR pv.supplier_sku='ASIA-'||b.sku) AND pv.is_active=true
    AND (pv.next_quantity_1 IS DISTINCT FROM b.nq1 OR pv.next_date_1 IS DISTINCT FROM b.nd1
      OR pv.next_quantity_2 IS DISTINCT FROM b.nq2 OR pv.next_date_2 IS DISTINCT FROM b.nd2
      OR pv.next_quantity_3 IS DISTINCT FROM b.nq3 OR pv.next_date_3 IS DISTINCT FROM b.nd3);
  GET DIAGNOSTICS v_nq_propagados = ROW_COUNT;

  RETURN jsonb_build_object(
    'success',true,'vistos',v_seen,'aplicados',v_ok,'nao_encontrados',v_nao,
    'produtos_recalc',array_length(v_prods,1),'erros',v_erros,
    'vss_nq_updated',v_vss_nq_updated,'pv_nq_propagados',v_nq_propagados,
    'guard_pv','datas_passadas_NAO_chegam_ao_gold_ASIA',
    'fixes',jsonb_build_array('B01a','B01b','B01c','B01d','FINAL-01-GUARD-ASIA','FINAL-02-NQ-REGEX-GUARD'),
    'segundos',round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,1)
  );
END;
$$;


ALTER FUNCTION "public"."fn_asia_stock_fast_sync"("p_skus" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_asia_wp_to_canonical"("p_wp" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'codigo',               p_wp->>'sku',
    'id_interno_site',      p_wp->>'id',
    'url',                  p_wp->>'permalink',
    'nome',                 p_wp->>'name',
    'descricao',            p_wp->>'description',
    'disponibilidade_site', p_wp#>>'{stock_availability,text}',
    'peso_g',               CASE WHEN NULLIF(p_wp->>'weight','') IS NOT NULL
                                 THEN round((p_wp->>'weight')::numeric*1000)::int END,
    'dimensoes', jsonb_strip_nulls(jsonb_build_object(
        'altura_cm',       NULLIF(p_wp#>>'{dimensions,height}','')::numeric,
        'largura_cm',      NULLIF(p_wp#>>'{dimensions,width}','')::numeric,
        'profundidade_cm', NULLIF(p_wp#>>'{dimensions,length}','')::numeric)),
    'imagens', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                  'tipo', CASE WHEN ord=1 THEN 'principal' ELSE 'galeria' END,
                  'ordem', ord, 'url_origem', img->>'src',
                  'alt', NULLIF(img->>'alt','')) ORDER BY ord),'[]'::jsonb)
                FROM jsonb_array_elements(COALESCE(p_wp->'images','[]'::jsonb))
                     WITH ORDINALITY AS t(img,ord)),
    'cores', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'id',term->>'id','nome',term->>'name','slug',term->>'slug')),'[]'::jsonb)
              FROM jsonb_array_elements(COALESCE(p_wp->'attributes','[]'::jsonb)) attr
              CROSS JOIN jsonb_array_elements(COALESCE(attr->'terms','[]'::jsonb)) term
              WHERE attr->>'taxonomy'='pa_cor'),
    'categorias', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                     'id',cat->>'id','nome',cat->>'name','slug',cat->>'slug','link',cat->>'link')),'[]'::jsonb)
                   FROM jsonb_array_elements(COALESCE(p_wp->'categories','[]'::jsonb)) cat),
    -- extensões de valor (WP-only)
    'preco_normal', CASE WHEN NULLIF(p_wp#>>'{prices,regular_price}','') IS NOT NULL
        THEN round((p_wp#>>'{prices,regular_price}')::numeric
                   /power(10::numeric,COALESCE(NULLIF(p_wp#>>'{prices,currency_minor_unit}','')::int,2)::numeric),2) END,
    'preco_promo', CASE WHEN NULLIF(p_wp#>>'{prices,sale_price}','') IS NOT NULL
        THEN round((p_wp#>>'{prices,sale_price}')::numeric
                   /power(10::numeric,COALESCE(NULLIF(p_wp#>>'{prices,currency_minor_unit}','')::int,2)::numeric),2) END,
    'em_promocao',    (p_wp->>'on_sale')::boolean,
    'moq',            NULLIF(p_wp#>>'{add_to_cart,multiple_of}','')::int,
    'qtd_minima',     NULLIF(p_wp#>>'{add_to_cart,minimum}','')::int,
    'qtd_maxima',     NULLIF(p_wp#>>'{add_to_cart,maximum}','')::int,
    'marca',          (SELECT b->>'name' FROM jsonb_array_elements(COALESCE(p_wp->'brands','[]'::jsonb)) b LIMIT 1),
    'avaliacao',      NULLIF(p_wp->>'average_rating','0')::numeric,
    'num_avaliacoes', NULLIF(p_wp->>'review_count','0')::int,
    '_meta', jsonb_build_object('scraper_version','wc_store_v1','fonte','woocommerce_store_api')
  ));
$$;


