CREATE OR REPLACE FUNCTION "public"."fn_auto_classify_kit_product"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_res   JSONB;
  v_catid UUID;
BEGIN
  IF NOT COALESCE(NEW.is_kit, FALSE) OR NEW.name IS NULL THEN
    RETURN NEW;
  END IF;

  v_res := classify_kit_churrasco(NEW.name);
  IF (v_res->>'is_kit_churrasco')::BOOLEAN IS TRUE THEN
    v_catid := (v_res->>'category_id')::UUID;

  ELSIF ((classify_kit_vinho(NEW.name))->>'is_kit_vinho')::BOOLEAN IS TRUE THEN
    v_catid := ((classify_kit_vinho(NEW.name))->>'category_id')::UUID;

  ELSIF ((classify_kit_queijo(NEW.name))->>'is_kit_queijo')::BOOLEAN IS TRUE THEN
    v_catid := ((classify_kit_queijo(NEW.name))->>'category_id')::UUID;

  ELSIF ((classify_kit_banho(NEW.name))->>'is_kit_banho')::BOOLEAN IS TRUE THEN
    v_catid := ((classify_kit_banho(NEW.name))->>'category_id')::UUID;

  ELSE
    v_res := classify_kit_ferramentas(NEW.name);
    IF (v_res->>'category_id') IS NOT NULL THEN
      v_catid := (v_res->>'category_id')::UUID;
    END IF;
  END IF;

  IF v_catid IS NOT NULL THEN
    NEW.category_id      := COALESCE(NEW.category_id, v_catid);
    NEW.main_category_id := COALESCE(NEW.main_category_id, v_catid);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_classify_kit_product"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_classify_kit_product"() IS 'Trigger BEFORE INSERT/UPDATE em products: classifica automaticamente kits
   usando as funções classify_kit_* (churrasco, vinho, queijo, banho, ferramentas).
   Aplica category_id apenas se ainda NULL (não sobrescreve edição manual).';



CREATE OR REPLACE FUNCTION "public"."fn_auto_classify_packing"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_classification TEXT;
    v_packing_result JSONB;
    v_extract_result JSONB;
BEGIN
    IF NEW.packing_classification IS NOT NULL THEN
        RETURN NEW;
    END IF;
    
    -- PRIORIDADE 1: packing_type
    IF NEW.packing_type IS NOT NULL AND TRIM(NEW.packing_type) != '' THEN
        v_packing_result := fn_classify_packing_type(NEW.packing_type);
        v_classification := v_packing_result->>'classification';
        IF v_classification IS NOT NULL THEN
            NEW.packing_classification := v_classification;
            RETURN NEW;
        END IF;
    END IF;
    
    -- PRIORIDADE 2: descrição
    IF NEW.description IS NOT NULL AND TRIM(NEW.description) != '' THEN
        v_extract_result := fn_extract_packaging_from_description(NEW.description);
        IF (v_extract_result->>'found')::BOOLEAN = TRUE THEN
            v_packing_result := fn_classify_packing_type(v_extract_result->>'packaging_text');
            v_classification := v_packing_result->>'classification';
            IF v_classification IS NOT NULL THEN
                NEW.packing_classification := v_classification;
                RETURN NEW;
            END IF;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_classify_packing"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_classify_product_image"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_filename TEXT;
    v_image_type TEXT;
    v_image_type_id UUID;
    v_is_primary BOOLEAN := FALSE;
    v_display_order INTEGER;
    v_existing_primary_count INTEGER;
    v_color_id UUID;
    v_variant_id UUID;
    v_n_cores INTEGER;
    v_id_set       UUID;
    v_id_logo      UUID;
    v_id_box       UUID;
    v_id_pouch     UUID;
    v_id_bag       UUID;
    v_id_ambient   UUID;
    v_id_detail    UUID;
    v_id_gallery   UUID;
    v_id_main      UUID;
    v_id_other     UUID;
BEGIN
    -- Resolver UUIDs por code — MAX(id::text)::uuid (PostgreSQL não tem MAX(uuid) nativo)
    SELECT
      MAX(CASE WHEN code='set'     THEN id::text END)::uuid,
      MAX(CASE WHEN code='logo'    THEN id::text END)::uuid,
      MAX(CASE WHEN code='box'     THEN id::text END)::uuid,
      MAX(CASE WHEN code='pouch'   THEN id::text END)::uuid,
      MAX(CASE WHEN code='bag'     THEN id::text END)::uuid,
      MAX(CASE WHEN code='ambient' THEN id::text END)::uuid,
      MAX(CASE WHEN code='detail'  THEN id::text END)::uuid,
      MAX(CASE WHEN code='gallery' THEN id::text END)::uuid,
      MAX(CASE WHEN code='main'    THEN id::text END)::uuid,
      MAX(CASE WHEN code='other'   THEN id::text END)::uuid
    INTO
      v_id_set, v_id_logo, v_id_box, v_id_pouch, v_id_bag,
      v_id_ambient, v_id_detail, v_id_gallery, v_id_main, v_id_other
    FROM image_types;

    IF v_id_gallery IS NULL OR v_id_main IS NULL THEN
      RAISE EXCEPTION 'fn_auto_classify: image_types incompleta — tipos essenciais (gallery, main) ausentes. fix_version:anti_uuid_hardcode_20260627';
    END IF;

    IF NEW.image_type IS NOT NULL 
       AND NEW.image_type NOT IN ('other', '')
       AND NEW.image_type_id IS NULL THEN
        SELECT id INTO NEW.image_type_id 
        FROM image_types WHERE code = NEW.image_type LIMIT 1;
    END IF;

    v_filename := LOWER(COALESCE(
        SUBSTRING(NEW.url_original FROM '[^/]+$'),
        SUBSTRING(NEW.url_cdn FROM '[^/]+$'),
        ''
    ));

    IF v_filename ~ '[-_]set[._-]' OR v_filename ~ '[-_]set$' THEN
        v_image_type := 'set'; v_image_type_id := v_id_set;
    ELSIF v_filename ~ '[-_]c\.' THEN
        v_image_type := 'logo'; v_image_type_id := v_id_logo;
    ELSIF v_filename ~ '[-_]box[._-]' OR v_filename ~ '[-_]box$' THEN
        v_image_type := 'box'; v_image_type_id := v_id_box;
    ELSIF v_filename ~ '[-_]pouch[._-]' OR v_filename ~ '[-_]estojo[._-]' OR v_filename ~ '[-_]pouch$' THEN
        v_image_type := 'pouch'; v_image_type_id := v_id_pouch;
    ELSIF v_filename ~ '[-_]bag[._-]' OR v_filename ~ '[-_]sacola[._-]' OR v_filename ~ '[-_]bag$' THEN
        v_image_type := 'bag'; v_image_type_id := v_id_bag;
    ELSIF v_filename ~ '[-_]amb[._-]' OR v_filename ~ '[-_]ambiente[._-]' OR v_filename ~ '[-_]lifestyle[._-]'
       OR v_filename ~ '[-_]amb$' THEN
        v_image_type := 'ambient'; v_image_type_id := v_id_ambient;
    ELSIF v_filename ~ '[-_]det[._-]' OR v_filename ~ '[-_]detalhe[._-]' OR v_filename ~ '[-_]detail[._-]'
       OR v_filename ~ '[-_]det$' THEN
        v_image_type := 'detail'; v_image_type_id := v_id_detail;
    ELSIF v_filename ~ '[-_][de]\.' THEN
        v_image_type := 'gallery'; v_image_type_id := v_id_gallery;
    ELSIF v_filename ~ '_\d{3}\.' THEN
        SELECT COUNT(*) INTO v_existing_primary_count FROM product_images 
        WHERE product_id = NEW.product_id AND is_primary = TRUE AND is_active = TRUE;
        IF v_existing_primary_count = 0 THEN
            v_image_type := 'main'; v_image_type_id := v_id_main; v_is_primary := TRUE;
        ELSE
            v_image_type := 'gallery'; v_image_type_id := v_id_gallery;
        END IF;
    ELSIF v_filename ~ '_[a-z]\.' AND v_filename !~ '[-_]c\.' THEN
        v_image_type := 'gallery'; v_image_type_id := v_id_gallery;
    ELSIF NEW.cloudflare_image_id ~ '-gal-\d+$' OR NEW.cloudflare_image_id ~ '-d\d+$' THEN
        v_image_type := 'gallery'; v_image_type_id := v_id_gallery;
    ELSIF NEW.cloudflare_image_id ~ '-main$' THEN
        SELECT COUNT(*) INTO v_existing_primary_count FROM product_images 
        WHERE product_id = NEW.product_id AND is_primary = TRUE AND is_active = TRUE;
        IF v_existing_primary_count = 0 THEN
            v_image_type := 'main'; v_image_type_id := v_id_main; v_is_primary := TRUE;
        ELSE
            v_image_type := 'gallery'; v_image_type_id := v_id_gallery;
        END IF;
    ELSIF NEW.cloudflare_image_id ~ '-set$' OR NEW.cloudflare_image_id ~ '_set$' THEN
        v_image_type := 'set'; v_image_type_id := v_id_set;
    ELSIF NEW.cloudflare_image_id ~ '-amb$' OR NEW.cloudflare_image_id ~ '_amb$' THEN
        v_image_type := 'ambient'; v_image_type_id := v_id_ambient;
    ELSIF NEW.cloudflare_image_id ~ '-det$' OR NEW.cloudflare_image_id ~ '_det$' THEN
        v_image_type := 'detail'; v_image_type_id := v_id_detail;
    ELSIF NEW.cloudflare_image_id ~ '-logo$' OR NEW.cloudflare_image_id ~ '-logo-[a-z]' OR NEW.cloudflare_image_id ~ '_logo$' THEN
        v_image_type := 'logo'; v_image_type_id := v_id_logo;
    ELSIF NEW.cloudflare_image_id ~ '-box$' OR NEW.cloudflare_image_id ~ '_box$' THEN
        v_image_type := 'box'; v_image_type_id := v_id_box;
    ELSIF NEW.image_type IS NOT NULL AND NEW.image_type NOT IN ('other', '') THEN
        v_image_type := NEW.image_type;
        v_image_type_id := COALESCE(
            NEW.image_type_id,
            (SELECT id FROM image_types WHERE code = NEW.image_type LIMIT 1)
        );
    ELSE
        v_image_type := 'other'; v_image_type_id := v_id_other;
    END IF;

    IF NOT v_is_primary THEN
        SELECT COUNT(*) INTO v_existing_primary_count FROM product_images 
        WHERE product_id = NEW.product_id AND is_primary = TRUE AND is_active = TRUE;
        IF v_existing_primary_count = 0 AND v_image_type = 'main' THEN
            v_is_primary := TRUE;
        END IF;
    END IF;

    IF NEW.display_order IS NULL OR NEW.display_order = 0 THEN
        SELECT COALESCE(MAX(display_order), 0) + 1 INTO v_display_order
        FROM product_images WHERE product_id = NEW.product_id AND is_active = TRUE;
    ELSE
        v_display_order := NEW.display_order;
    END IF;

    NEW.image_type    := v_image_type;
    NEW.image_type_id := v_image_type_id;
    NEW.is_primary    := v_is_primary;
    NEW.display_order := v_display_order;

    IF v_is_primary THEN NEW.is_og_image := TRUE; END IF;
    IF NEW.is_active IS NULL THEN NEW.is_active := TRUE; END IF;

    IF NEW.color_id IS NULL AND NEW.supplier_code = 'XBZ' THEN
        IF NEW.variant_id IS NOT NULL THEN
            SELECT color_id INTO v_color_id FROM product_variants
            WHERE id = NEW.variant_id AND is_active = true;
            IF v_color_id IS NOT NULL THEN NEW.color_id := v_color_id; END IF;
        ELSE
            SELECT COUNT(DISTINCT pv.color_id) INTO v_n_cores FROM product_variants pv
            WHERE pv.product_id = NEW.product_id AND pv.is_active = true AND pv.color_id IS NOT NULL;
            IF v_n_cores = 1 THEN
                SELECT pv.id, pv.color_id INTO v_variant_id, v_color_id FROM product_variants pv
                WHERE pv.product_id = NEW.product_id AND pv.is_active = true AND pv.color_id IS NOT NULL
                ORDER BY pv.id LIMIT 1;
                NEW.color_id := v_color_id; NEW.variant_id := v_variant_id;
            ELSIF v_n_cores > 1 THEN
                SELECT pv.id, pv.color_id INTO v_variant_id, v_color_id FROM product_variants pv
                WHERE pv.product_id = NEW.product_id AND pv.is_active = true AND pv.color_id IS NOT NULL
                  AND NEW.url_original ILIKE '%' || REPLACE(pv.color_name, ' ', '-') || '%'
                GROUP BY pv.id, pv.color_id HAVING COUNT(*) = 1 LIMIT 1;
                IF v_color_id IS NOT NULL AND (
                  SELECT COUNT(DISTINCT pv2.color_id) FROM product_variants pv2
                  WHERE pv2.product_id = NEW.product_id AND pv2.is_active = true AND pv2.color_id IS NOT NULL
                    AND NEW.url_original ILIKE '%' || REPLACE(pv2.color_name, ' ', '-') || '%'
                ) = 1 THEN
                    NEW.color_id := v_color_id; NEW.variant_id := v_variant_id;
                END IF;
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."fn_auto_classify_product_image"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_classify_product_image"() IS 'Função de trigger que classifica automaticamente imagens de produtos.

PADRÕES RECONHECIDOS:
- _set.jpg, _set_ → set (todas as cores)
- -c.jpg, _c.jpg → logo (com gravação)
- _box.jpg → box (embalagem)
- _pouch.jpg, _estojo.jpg → pouch (estojo)
- _bag.jpg, _sacola.jpg → bag (sacola)
- _amb.jpg, _ambiente.jpg → ambient (lifestyle)
- _det.jpg, _detalhe.jpg → detail (close-up)
- _XXX.jpg (3 dígitos) → main (primeira) ou gallery (demais)
- -d.jpg, -e.jpg → gallery (vistas alternativas)

REGRAS AUTOMÁTICAS:
1. Primeira imagem válida do produto vira is_primary=true
2. display_order é calculado sequencialmente
3. is_og_image=true se for primary

Criado em: 2026-02-04
';



CREATE OR REPLACE FUNCTION "public"."fn_auto_criar_equivalencia_spot"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_variation_id UUID;
    v_confidence INT;
    v_note TEXT;
BEGIN
    -- Verificar se já existe equivalência
    IF EXISTS (
        SELECT 1 FROM color_equivalences 
        WHERE supplier_color_id = NEW.id
    ) THEN
        RETURN NEW;
    END IF;
    
    -- Buscar melhor match por nome
    SELECT 
        cv.id,
        CASE 
            WHEN LOWER(TRIM(cv.name)) = LOWER(TRIM(NEW.name)) THEN 100
            WHEN LOWER(cv.name) LIKE LOWER(TRIM(NEW.name)) || '%' THEN 95
            WHEN LOWER(TRIM(NEW.name)) LIKE LOWER(cv.name) || '%' THEN 90
            ELSE 80
        END,
        CASE 
            WHEN LOWER(TRIM(cv.name)) = LOWER(TRIM(NEW.name)) THEN 'Match exato automático'
            ELSE 'Match por similaridade automático'
        END
    INTO v_variation_id, v_confidence, v_note
    FROM color_variations cv
    WHERE cv.is_active = true
      AND (
          LOWER(TRIM(cv.name)) = LOWER(TRIM(NEW.name))
          OR LOWER(cv.name) LIKE LOWER(TRIM(NEW.name)) || '%'
          OR LOWER(TRIM(NEW.name)) LIKE LOWER(cv.name) || '%'
      )
    ORDER BY 
        CASE WHEN LOWER(TRIM(cv.name)) = LOWER(TRIM(NEW.name)) THEN 1 ELSE 2 END,
        LENGTH(cv.name)
    LIMIT 1;
    
    -- Se encontrou match, criar equivalência
    IF v_variation_id IS NOT NULL THEN
        INSERT INTO color_equivalences (
            organization_id,
            supplier_color_id,
            promo_variation_id,
            confidence_score,
            verified,
            source,
            notes,
            is_active
        ) VALUES (
            NEW.organization_id,
            NEW.id,
            v_variation_id,
            v_confidence,
            false,  -- Não verificado (automático)
            'automatic_trigger',
            v_note,
            true
        );
    END IF;
    
    RETURN NEW;
END;
$$;


