COMMENT ON FUNCTION "public"."fn_auto_criar_equivalencia_spot"() IS 'Tenta criar equivalência automaticamente quando nova cor SPOT é inserida';



CREATE OR REPLACE FUNCTION "public"."fn_auto_discover_all_compatible_packagings"("p_min_fit_rating" "text" DEFAULT 'good'::"text", "p_config_type" "text" DEFAULT 'default'::"text", "p_only_missing" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_prefix TEXT; v_min DECIMAL; v_tight DECIMAL; v_good DECIMAL; v_max DECIMAL;
    v_inserted INT := 0; v_ranked INT := 0;
BEGIN
    v_prefix := lower(trim(COALESCE(p_config_type,'default')));
    IF v_prefix NOT IN ('fragile','precision','bottles') THEN v_prefix := ''; END IF;
    IF v_prefix <> '' THEN v_prefix := v_prefix || '_'; END IF;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key=v_prefix||'min_gap_mm'),(SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key='min_gap_mm'),2) INTO v_min;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key=v_prefix||'tight_max_mm'),(SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key='tight_gap_max_mm'),5) INTO v_tight;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key=v_prefix||'good_max_mm'),(SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key='good_gap_max_mm'),15) INTO v_good;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key=v_prefix||'max_gap_mm'),(SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key='max_gap_mm'),50) INTO v_max;

    WITH prods AS (
        SELECT p.id, p.height_cm, p.width_cm, p.length_cm, p.diameter_cm, p.shape_type, p.supplier_id
        FROM products p WHERE p.is_active=true AND p.product_type IN ('product','kit')
          AND p.height_cm IS NOT NULL AND p.width_cm IS NOT NULL
          AND (NOT p_only_missing OR NOT EXISTS (SELECT 1 FROM product_packaging_compatibility x WHERE x.product_id=p.id AND x.active=true))
    ),
    pkgs AS (
        SELECT pk.id, pk.internal_height_cm, pk.internal_width_cm, pk.internal_length_cm, pk.supplier_id
        FROM products pk WHERE pk.product_type='packaging' AND pk.is_active=true AND pk.internal_height_cm IS NOT NULL
    ),
    pairs AS (
        SELECT pr.id AS product_id, pk.id AS packaging_id, pr.supplier_id AS prod_supplier, pk.supplier_id AS pkg_supplier, pr.shape_type,
            CASE WHEN pr.shape_type='cylindrical' THEN (GREATEST(pk.internal_height_cm,pk.internal_width_cm,pk.internal_length_cm)-pr.height_cm)*10
                 ELSE (pk.internal_height_cm-pr.height_cm)*10 END AS gap_h_mm,
            CASE WHEN pr.shape_type='cylindrical' THEN NULL ELSE (pk.internal_width_cm-pr.width_cm)*10 END AS gap_w_mm,
            CASE WHEN pr.shape_type='cylindrical' THEN NULL ELSE (pk.internal_length_cm-pr.length_cm)*10 END AS gap_l_mm,
            CASE WHEN pr.shape_type='cylindrical' THEN (LEAST(pk.internal_height_cm,pk.internal_width_cm,pk.internal_length_cm)-COALESCE(pr.diameter_cm,pr.width_cm))*10 ELSE NULL END AS gap_d_mm
        FROM prods pr CROSS JOIN pkgs pk
    ),
    classified AS (
        SELECT product_id, packaging_id, prod_supplier, pkg_supplier, shape_type, gap_h_mm, gap_w_mm, gap_l_mm, gap_d_mm,
            CASE WHEN shape_type='cylindrical' THEN LEAST(COALESCE(gap_h_mm,999),COALESCE(gap_d_mm,999)) ELSE LEAST(COALESCE(gap_h_mm,999),COALESCE(gap_w_mm,999),COALESCE(gap_l_mm,999)) END AS gap_min,
            CASE WHEN shape_type='cylindrical' THEN (COALESCE(gap_h_mm,0)+COALESCE(gap_d_mm,0))/2.0 ELSE (COALESCE(gap_h_mm,0)+COALESCE(gap_w_mm,0)+COALESCE(gap_l_mm,0))/3.0 END AS gap_avg
        FROM pairs
    ),
    rated AS (
        SELECT *, CASE WHEN gap_min IS NULL OR gap_min>=900 THEN 'incompatible' WHEN gap_min<0 THEN 'too_tight'
            WHEN gap_min<v_min THEN 'too_tight' WHEN gap_min<=v_tight THEN 'tight' WHEN gap_min<=v_good THEN 'good'
            WHEN gap_min<=v_max THEN 'loose' ELSE 'too_large' END AS fit_rating FROM classified
    ),
    compatibles AS (
        SELECT * FROM rated WHERE fit_rating = ANY(CASE p_min_fit_rating WHEN 'tight' THEN ARRAY['tight'] WHEN 'good' THEN ARRAY['tight','good'] WHEN 'loose' THEN ARRAY['tight','good','loose'] ELSE ARRAY['tight','good','loose'] END)
    ),
    ins AS (
        INSERT INTO product_packaging_compatibility (product_id, packaging_id, compatibility_source, fit_rating, fit_gap_height_mm, fit_gap_width_mm, fit_gap_length_mm, fit_gap_diameter_mm, fit_gap_min_mm, fit_gap_avg_mm, is_same_supplier, auto_discovered_at, config_type_used, active)
        SELECT product_id, packaging_id, 'dimension_calculated', fit_rating, ROUND(COALESCE(gap_h_mm,0)::numeric,2), ROUND(COALESCE(gap_w_mm,0)::numeric,2), ROUND(COALESCE(gap_l_mm,0)::numeric,2), ROUND(COALESCE(gap_d_mm,0)::numeric,2), ROUND(gap_min::numeric,2), ROUND(gap_avg::numeric,2), (prod_supplier=pkg_supplier), now(), COALESCE(NULLIF(p_config_type,'default'),'default'), true
        FROM compatibles ON CONFLICT (product_id, packaging_id) DO NOTHING RETURNING 1
    )
    SELECT COUNT(*) INTO v_inserted FROM ins;

    IF v_inserted > 0 THEN
        WITH ranking AS (
            SELECT id, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY
                CASE compatibility_source WHEN 'supplier_indicated' THEN 1 WHEN 'dimension_matching' THEN 2 WHEN 'dimension_calculated' THEN 3 ELSE 4 END,
                CASE fit_rating WHEN 'tight' THEN 1 WHEN 'good' THEN 2 WHEN 'loose' THEN 3 ELSE 4 END, COALESCE(fit_gap_min_mm,99999) ASC) rn
            FROM product_packaging_compatibility WHERE active=true AND fit_rating IN ('tight','good','loose')
              AND product_id IN (SELECT product_id FROM product_packaging_compatibility WHERE active=true GROUP BY product_id HAVING BOOL_OR(is_recommended)=false)
        )
        UPDATE product_packaging_compatibility ppc SET is_recommended=true, updated_at=now() FROM ranking r WHERE ppc.id=r.id AND r.rn=1;
        GET DIAGNOSTICS v_ranked = ROW_COUNT;
    END IF;

    RETURN jsonb_build_object('success',true,'inserted',v_inserted,'ranked',v_ranked,'config_type',p_config_type,'min_fit_rating',p_min_fit_rating,'only_missing',p_only_missing,'limits_mm',jsonb_build_object('min',v_min,'tight',v_tight,'good',v_good,'max',v_max));
END;$$;


ALTER FUNCTION "public"."fn_auto_discover_all_compatible_packagings"("p_min_fit_rating" "text", "p_config_type" "text", "p_only_missing" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_discover_all_compatible_packagings"("p_min_fit_rating" "text", "p_config_type" "text", "p_only_missing" boolean) IS 'v2 — FIX: mapeamento correto gap_h/gap_d para cilíndrico.
FIX: ranking is_recommended auto-executado após insert.
Cilíndrico: gap_h_mm=altura vs maior dim, gap_d_mm=diâmetro vs menor dim.
Retangular: gap_h/w/l_mm conforme dimensões da caixa.';



CREATE OR REPLACE FUNCTION "public"."fn_auto_discover_compatible_packagings"("p_product_id" "uuid", "p_min_fit_rating" character varying DEFAULT 'good'::character varying) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count_discovered INT := 0; v_count_existing INT := 0; v_count_incompatible INT := 0;
    v_packaging RECORD; v_fit JSONB; v_valid_ratings TEXT[]; v_config_type TEXT;
BEGIN
    -- ANTI-REGRESSAO(2026-06-26 perfis_v1): inferir perfil e repassar a fn_calculate_packaging_fit;
    -- popular config_type_used + auto_discovered_at. NAO remover a inferencia nem voltar a chamar
    -- fn_calculate_packaging_fit com apenas 2 argumentos.
    v_config_type := fn_infer_packaging_config_type(p_product_id);

    IF p_min_fit_rating = 'precise' THEN v_valid_ratings := ARRAY['tight','good'];
    ELSIF p_min_fit_rating = 'tight' THEN v_valid_ratings := ARRAY['tight','good','loose'];
    ELSIF p_min_fit_rating = 'good' THEN v_valid_ratings := ARRAY['good','loose'];
    ELSIF p_min_fit_rating = 'loose' THEN v_valid_ratings := ARRAY['loose'];
    ELSE v_valid_ratings := ARRAY['good','loose']; END IF;

    IF NOT EXISTS (SELECT 1 FROM products WHERE id = p_product_id) THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Produto não encontrado');
    END IF;

    FOR v_packaging IN
        SELECT id, name FROM products
        WHERE product_type = 'packaging' AND is_active = TRUE AND internal_height_cm IS NOT NULL AND id <> p_product_id
    LOOP
        IF EXISTS (SELECT 1 FROM product_packaging_compatibility
                   WHERE product_id = p_product_id AND packaging_id = v_packaging.id) THEN
            v_count_existing := v_count_existing + 1; CONTINUE;
        END IF;

        v_fit := fn_calculate_packaging_fit(p_product_id, v_packaging.id, v_config_type);

        IF (v_fit->>'compatible')::BOOLEAN AND (v_fit->>'fit_rating') = ANY(v_valid_ratings) THEN
            INSERT INTO product_packaging_compatibility (
                product_id, packaging_id, compatibility_source,
                fit_gap_height_mm, fit_gap_width_mm, fit_gap_length_mm, fit_gap_diameter_mm,
                fit_gap_min_mm, fit_gap_avg_mm, fit_rating, config_type_used, auto_discovered_at
            ) VALUES (
                p_product_id, v_packaging.id, 'dimension_calculated',
                (v_fit->>'gap_height_mm')::DECIMAL, (v_fit->>'gap_width_mm')::DECIMAL,
                (v_fit->>'gap_length_mm')::DECIMAL, (v_fit->>'gap_diameter_mm')::DECIMAL,
                (v_fit->>'gap_min_mm')::DECIMAL, (v_fit->>'gap_avg_mm')::DECIMAL,
                v_fit->>'fit_rating', v_config_type, now()
            );
            v_count_discovered := v_count_discovered + 1;
        ELSE
            v_count_incompatible := v_count_incompatible + 1;
        END IF;
    END LOOP;

    RETURN jsonb_build_object('success', TRUE, 'product_id', p_product_id, 'config_type', v_config_type,
        'min_fit_rating', p_min_fit_rating, 'discovered', v_count_discovered,
        'already_existed', v_count_existing, 'incompatible', v_count_incompatible);
END;
$$;


ALTER FUNCTION "public"."fn_auto_discover_compatible_packagings"("p_product_id" "uuid", "p_min_fit_rating" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_discover_compatible_packagings"("p_product_id" "uuid", "p_min_fit_rating" character varying) IS 'Descobre automaticamente TODAS as embalagens compatíveis com um produto, baseado em dimensões.';



CREATE OR REPLACE FUNCTION "public"."fn_auto_link_commemorative_dates"("p_product_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_category_id UUID;
    v_category_name TEXT;
    v_date_record RECORD;
    v_linked_count INTEGER := 0;
BEGIN
    -- 1. Buscar categoria do produto
    SELECT c.id, LOWER(unaccent(c.name))
    INTO v_category_id, v_category_name
    FROM products p
    JOIN categories c ON c.id = p.category_id
    WHERE p.id = p_product_id;

    IF v_category_id IS NULL THEN
        RETURN 0;
    END IF;

    -- 2. Buscar datas relacionadas à categoria (SEM target_audience='todos' — esse critério era o bug
    --    que linkava todos os 7200 produtos a cada data genérica)
    FOR v_date_record IN (
        SELECT cd.id AS date_id, cd.name AS date_name
        FROM commemorative_dates cd
        WHERE cd.is_active = true
          AND cd.target_audience IS NOT NULL
          AND cd.target_audience <> 'todos'
          AND (
              v_category_name ILIKE '%' || LOWER(cd.target_audience) || '%'
              OR LOWER(cd.target_audience) ILIKE '%' || v_category_name || '%'
          )
    )
    LOOP
        INSERT INTO product_commemorative_dates (
            product_id, commemorative_date_id, relevance_score, source, created_at
        )
        VALUES (
            p_product_id,
            v_date_record.date_id,
            CASE WHEN v_date_record.date_name ILIKE '%' || v_category_name || '%' THEN 10 ELSE 5 END,
            'auto',
            NOW()
        )
        ON CONFLICT (product_id, commemorative_date_id) DO NOTHING;

        IF FOUND THEN v_linked_count := v_linked_count + 1; END IF;
    END LOOP;

    RETURN v_linked_count;

EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Erro vinculando datas do produto %: %', p_product_id, SQLERRM;
    RETURN 0;
END;
$$;


ALTER FUNCTION "public"."fn_auto_link_commemorative_dates"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_link_commemorative_dates"("p_product_id" "uuid") IS 'Vincula datas comemorativas automaticamente baseado na categoria do produto. v1.0 - 30/01/2026';



CREATE OR REPLACE FUNCTION "public"."fn_auto_link_eco"("p_product_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_material_name TEXT;
    v_is_eco BOOLEAN := FALSE;
    v_eco_tag_id UUID;
    v_eco_materials TEXT[] := ARRAY[
        'bambu', 'bamboo', 'cortiça', 'cork', 'juta', 'juco',
        'algodão orgânico', 'organic cotton', 'reciclado', 'recycled',
        'rpet', 'pet reciclado', 'kraft', 'palha de trigo', 'wheat straw',
        'fibra de bambu', 'bamboo fiber', 'madeira', 'wood', 'algodão reciclado'
    ];
    i INTEGER;
BEGIN
    -- 1. Buscar material do produto (primeiro de product_materials)
    SELECT LOWER(mt.name) INTO v_material_name
    FROM product_materials pm
    JOIN material_types mt ON mt.id = pm.material_id
    WHERE pm.product_id = p_product_id
    LIMIT 1;
    
    -- Se não encontrou em product_materials, tentar em supplier_products_raw
    IF v_material_name IS NULL THEN
        SELECT LOWER(raw_data->>'Materials')
        INTO v_material_name
        FROM supplier_products_raw
        WHERE product_id = p_product_id
        LIMIT 1;
    END IF;
    
    IF v_material_name IS NULL OR v_material_name = '' THEN
        RETURN FALSE;
    END IF;
    
    -- 2. Verificar se é material ECO
    FOR i IN 1..array_length(v_eco_materials, 1)
    LOOP
        IF v_material_name ILIKE '%' || v_eco_materials[i] || '%' THEN
            v_is_eco := TRUE;
            EXIT;
        END IF;
    END LOOP;
    
    -- 3. Se é ECO, vincular tag
    IF v_is_eco THEN
        -- Buscar tag ECO (pode ter vários nomes)
        SELECT id INTO v_eco_tag_id
        FROM tags
        WHERE LOWER(name) IN ('eco-friendly', 'ecológico', 'sustentável', 'eco', 'sustentavel')
           OR LOWER(slug) IN ('eco-friendly', 'ecologico', 'sustentavel', 'eco')
        LIMIT 1;
        
        IF v_eco_tag_id IS NOT NULL THEN
            INSERT INTO product_tags (product_id, tag_id, created_at)
            VALUES (p_product_id, v_eco_tag_id, NOW())
            ON CONFLICT (product_id, tag_id) DO NOTHING;
            
            RAISE NOTICE 'ECO tag vinculada para produto %', p_product_id;
        ELSE
            RAISE NOTICE 'Tag ECO não encontrada no banco';
        END IF;
    END IF;
    
    RETURN v_is_eco;
    
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Erro vinculando ECO do produto %: %', p_product_id, SQLERRM;
    RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."fn_auto_link_eco"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_link_eco"("p_product_id" "uuid") IS 'Vincula tag ECO automaticamente baseado no material do produto. v1.0 - 30/01/2026';



CREATE OR REPLACE FUNCTION "public"."fn_auto_link_eco_material"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_ecologia_category_id  UUID := '896277ce-50ee-4bf5-9e5f-c118e6b4a36a';
    v_meio_ambiente_date_id UUID := '11b59fa3-14f1-4f5b-8c92-2e9bcb03e216';
    v_is_eco BOOLEAN;
BEGIN
    SELECT EXISTS(SELECT 1 FROM eco_material_config WHERE material_id = NEW.material_id AND is_active = TRUE) INTO v_is_eco;
    IF v_is_eco THEN
        BEGIN
            INSERT INTO product_category_assignments (product_id, category_id, is_primary, created_at)
            VALUES (NEW.product_id, v_ecologia_category_id, FALSE, NOW())
            ON CONFLICT (product_id, category_id) DO NOTHING;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE WARNING 'Auto-link ECO: categoria Ecologia (%) inexistente; link de categoria pulado', v_ecologia_category_id;
        END;
        BEGIN
            INSERT INTO product_commemorative_dates (product_id, commemorative_date_id, created_at)
            VALUES (NEW.product_id, v_meio_ambiente_date_id, NOW())
            ON CONFLICT (product_id, commemorative_date_id) DO NOTHING;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE WARNING 'Auto-link ECO: data Meio Ambiente (%) inexistente; link de data pulado', v_meio_ambiente_date_id;
        END;
    END IF;
    RETURN NEW;
END;
$$;


