COMMENT ON FUNCTION "public"."fn_auto_set_same_supplier"() IS 'Calcula automaticamente se produto e embalagem são do mesmo fornecedor';



CREATE OR REPLACE FUNCTION "public"."fn_auto_similarity_groups_v2"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_groups_created int := 0;
  v_members_added  int := 0;
  v_group_id       uuid;
  v_rec            RECORD;
  v_name           text;
BEGIN
  -- CTE para calcular grupos candidatos (orphans com ≥2 suppliers e ≥3 produtos)
  FOR v_rec IN
    WITH material_map AS (
      SELECT 
        p.id AS product_id,
        p.supplier_id,
        p.supplier_type,
        CASE 
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%alumin%'                        THEN 'ALUMINIO'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%plast%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '% pp%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%abs%'                           THEN 'PLASTICO'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%inox%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%aço inox%'
            OR (LOWER(COALESCE(p.materials::text,'')) LIKE '%metal%'
              AND LOWER(COALESCE(p.materials::text,'')) NOT LIKE '%alumin%')                THEN 'METAL'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%bambu%'                         THEN 'BAMBU'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%algodão%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%cotton%'                        THEN 'ALGODAO'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%tecido%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%oxford%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%nylon%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%poliéster%'                    THEN 'TECIDO'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%madeira%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%wood%'                          THEN 'MADEIRA'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%couro%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '% pu %'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%sintético%'                    THEN 'COURO_PU'
          ELSE 'MISTO'
        END AS material_key
      FROM products p
      WHERE p.is_active = true AND p.is_deleted = false
        AND p.supplier_type IS NOT NULL AND p.supplier_type != ''
        AND NOT EXISTS (
          SELECT 1 FROM product_similarity_group_members psgm WHERE psgm.product_id = p.id
        )
    ),
    group_candidates AS (
      SELECT 
        supplier_type,
        material_key,
        COUNT(*) AS n_products,
        COUNT(DISTINCT supplier_id) AS n_suppliers,
        ARRAY_AGG(product_id ORDER BY product_id) AS product_ids
      FROM material_map
      GROUP BY supplier_type, material_key
      HAVING COUNT(*) >= 3 AND COUNT(DISTINCT supplier_id) >= 2
    )
    SELECT * FROM group_candidates ORDER BY n_products DESC
  LOOP
    -- Nome do grupo
    v_name := initcap(regexp_replace(
      COALESCE(v_rec.supplier_type, 'Outros'), '[|/\\&]+', ' | ', 'g'
    )) || ' — ' || v_rec.material_key;

    -- Inserir grupo
    INSERT INTO product_similarity_groups(
      id, name, material_family, capacity_band,
      capacity_min, capacity_max,
      match_criteria, match_source, is_active,
      created_at, updated_at
    ) VALUES (
      gen_random_uuid(), v_name, v_rec.material_key, 'ALL',
      0, 99999,
      jsonb_build_object(
        'supplier_type', v_rec.supplier_type,
        'material_key',  v_rec.material_key,
        'min_products',  3,
        'min_suppliers', 2
      ),
      'automatic_v2', true, NOW(), NOW()
    )
    RETURNING id INTO v_group_id;
    v_groups_created := v_groups_created + 1;

    -- Inserir membros
    INSERT INTO product_similarity_group_members(
      id, group_id, product_id, supplier_id,
      is_reference_product, similarity_score,
      match_source, created_at
    )
    SELECT
      gen_random_uuid(), v_group_id, p.id, p.supplier_id,
      false, 1.00, 'automatic_v2', NOW()
    FROM products p
    WHERE p.id = ANY(v_rec.product_ids);

    v_members_added := v_members_added + array_length(v_rec.product_ids, 1);
  END LOOP;

  RETURN jsonb_build_object(
    'groups_created', v_groups_created,
    'members_added',  v_members_added
  );
END;
$$;


ALTER FUNCTION "public"."fn_auto_similarity_groups_v2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_similarity_groups_v3"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ins int:=0; v_mem int:=0;
  v_gid uuid; v_rec RECORD;
BEGIN
  FOR v_rec IN
    WITH mm AS (
      SELECT p.id AS pid, p.supplier_id, p.supplier_type,
        CASE
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%alumin%' THEN 'ALUMINIO'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%plast%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '% pp%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%abs%' THEN 'PLASTICO'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%inox%'
            OR (LOWER(COALESCE(p.materials::text,'')) LIKE '%metal%'
              AND LOWER(COALESCE(p.materials::text,'')) NOT LIKE '%alumin%') THEN 'METAL'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%bambu%' THEN 'BAMBU'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%algodão%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%cotton%' THEN 'ALGODAO'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%tecido%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%oxford%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%nylon%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '%poliéster%' THEN 'TECIDO'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%madeira%' THEN 'MADEIRA'
          WHEN LOWER(COALESCE(p.materials::text,'')) LIKE '%couro%'
            OR LOWER(COALESCE(p.materials::text,'')) LIKE '% pu %' THEN 'COURO_PU'
          ELSE 'MISTO'
        END AS material_key
      FROM products p
      WHERE p.is_active=true AND p.is_deleted=false
        AND p.supplier_type IS NOT NULL AND p.supplier_type!=''
        AND NOT EXISTS (
          SELECT 1 FROM product_similarity_group_members x WHERE x.product_id=p.id
        )
    )
    SELECT supplier_type, material_key,
      COUNT(*) AS n_prod, COUNT(DISTINCT supplier_id) AS n_sup,
      ARRAY_AGG(pid ORDER BY pid) AS pids
    FROM mm
    GROUP BY supplier_type, material_key
    HAVING COUNT(*) >= 3
    ORDER BY COUNT(*) DESC
  LOOP
    INSERT INTO product_similarity_groups(
      id,name,material_family,capacity_band,capacity_min,capacity_max,
      match_criteria,match_source,is_active,created_at,updated_at
    ) VALUES (
      gen_random_uuid(),
      initcap(regexp_replace(COALESCE(v_rec.supplier_type,'Outros'),'[|/\\&]+',' | ','g'))
        || ' — ' || v_rec.material_key || ' (intra)',
      v_rec.material_key,'ALL',0,99999,
      jsonb_build_object('supplier_type',v_rec.supplier_type,'material_key',v_rec.material_key,
        'min_products',3,'min_suppliers',1,'pass','v3_intra'),
      'automatic_v3_intra',true,NOW(),NOW()
    )
    RETURNING id INTO v_gid;
    v_ins:=v_ins+1;

    INSERT INTO product_similarity_group_members(
      id,group_id,product_id,supplier_id,is_reference_product,similarity_score,match_source,created_at
    )
    SELECT gen_random_uuid(),v_gid,p.id,p.supplier_id,false,0.85,'automatic_v3_intra',NOW()
    FROM products p WHERE p.id=ANY(v_rec.pids);

    v_mem:=v_mem+array_length(v_rec.pids,1);
  END LOOP;

  RETURN jsonb_build_object('groups_created',v_ins,'members_added',v_mem);
END;
$$;


ALTER FUNCTION "public"."fn_auto_similarity_groups_v3"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_vincular_cor_variante"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_codigo_cor     TEXT;
    v_nome_cor       TEXT;
    v_variation_id   UUID;
    v_variation_name TEXT;
    v_variation_hex  TEXT;
BEGIN
    v_codigo_cor := NEW.attributes->>'codigo_cor';
    v_nome_cor   := NEW.attributes->>'cor';

    -- Se já tem color_id preenchido, não sobrescrever
    IF NEW.color_id IS NOT NULL THEN
        RETURN NEW;
    END IF;

    -- ────────────────────────────────────────────────────────────────────────
    -- ESTRATÉGIA 1: código SPOT via color_equivalences (mais específico)
    -- ────────────────────────────────────────────────────────────────────────
    IF v_codigo_cor IS NOT NULL THEN
        SELECT cv.id, cv.name, cv.hex_code
        INTO v_variation_id, v_variation_name, v_variation_hex
        FROM supplier_colors sc
        JOIN color_equivalences ce ON ce.supplier_color_id = sc.id AND ce.is_active = true
        JOIN color_variations cv   ON cv.id = ce.promo_variation_id AND cv.is_active = true
        WHERE sc.code = v_codigo_cor
        ORDER BY ce.confidence_score DESC NULLS LAST
        LIMIT 1;

        IF v_variation_id IS NOT NULL THEN
            NEW.color_id   := v_variation_id;
            NEW.color_name := v_variation_name;
            NEW.color_hex  := v_variation_hex;
            RETURN NEW;
        END IF;
    END IF;

    -- ────────────────────────────────────────────────────────────────────────
    -- ESTRATÉGIA 2: match exato de nome em color_variations (rápido)
    -- ────────────────────────────────────────────────────────────────────────
    IF v_nome_cor IS NOT NULL THEN
        SELECT cv.id, cv.name, cv.hex_code
        INTO v_variation_id, v_variation_name, v_variation_hex
        FROM color_variations cv
        WHERE cv.is_active = true
          AND (
              LOWER(TRIM(cv.name)) = LOWER(TRIM(v_nome_cor))
              OR LOWER(cv.name) LIKE LOWER(TRIM(v_nome_cor)) || '%'
          )
        ORDER BY
            CASE WHEN LOWER(TRIM(cv.name)) = LOWER(TRIM(v_nome_cor)) THEN 1 ELSE 2 END,
            LENGTH(cv.name)
        LIMIT 1;

        IF v_variation_id IS NOT NULL THEN
            NEW.color_id   := v_variation_id;
            NEW.color_name := v_variation_name;
            NEW.color_hex  := v_variation_hex;
            RETURN NEW;
        END IF;
    END IF;

    -- ────────────────────────────────────────────────────────────────────────
    -- ESTRATÉGIA 3 (GAP FIX): fn_match_canonical_color como fallback canônico
    -- Abrange P1-P5: hex exato, supplier_colors por nome/hex via equivalences,
    -- e match parcial via color_groups.
    -- Usa color_name já normalizado em NEW ou extrai de attributes.
    -- ────────────────────────────────────────────────────────────────────────
    DECLARE
        v_match_name TEXT := COALESCE(NEW.color_name, v_nome_cor);
        v_match_hex  TEXT := COALESCE(NEW.color_hex, NEW.attributes->>'hex');
    BEGIN
        IF v_match_name IS NOT NULL OR v_match_hex IS NOT NULL THEN
            v_variation_id := public.fn_match_canonical_color(v_match_name, v_match_hex);

            IF v_variation_id IS NOT NULL THEN
                SELECT cv.name, cv.hex_code
                INTO v_variation_name, v_variation_hex
                FROM color_variations cv
                WHERE cv.id = v_variation_id;

                NEW.color_id   := v_variation_id;
                NEW.color_name := COALESCE(NEW.color_name, v_variation_name);
                NEW.color_hex  := COALESCE(NEW.color_hex, v_variation_hex);
            END IF;
        END IF;
    END;

    RETURN NEW;
END;
$$;


