COMMENT ON FUNCTION "public"."fn_auto_vincular_cor_variante"() IS 'Auto-vincula color_id em product_variants baseado em codigo_cor ou nome da cor';



CREATE OR REPLACE FUNCTION "public"."fn_autolink_canonical_on_content_hash"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_root_id               uuid;
  v_existing_canonical_hash text;
  v_old_group_root        uuid;
  v_elected_dep_root      uuid;
BEGIN
  -- Only act when content_hash is being set or changed
  IF NEW.content_hash IS NULL OR (OLD.content_hash IS NOT NULL AND OLD.content_hash = NEW.content_hash) THEN
    RETURN NEW;
  END IF;

  -- If image already has a canonical assignment:
  IF NEW.canonical_image_id IS NOT NULL THEN
    IF OLD.content_hash IS NOT NULL AND OLD.content_hash IS DISTINCT FROM NEW.content_hash THEN
      -- Hash CHANGED (not first-set): clear old canonical → re-link to correct group
      NEW.canonical_image_id := NULL;
      NEW.is_shared := false;
    ELSE
      -- First-set (OLD.content_hash was NULL): validate canonical belongs to SAME hash group
      -- GAP-C6: existing canonical may point to a different-hash group
      SELECT content_hash INTO v_existing_canonical_hash
      FROM public.product_images
      WHERE id = NEW.canonical_image_id;

      IF v_existing_canonical_hash IS NOT DISTINCT FROM NEW.content_hash THEN
        RETURN NEW;  -- Same hash group: respect existing canonical
      END IF;
      -- Wrong hash group: fall through to re-link to correct root
      NEW.canonical_image_id := NULL;
      NEW.is_shared := false;
    END IF;
  END IF;

  -- Find the oldest root in the new hash group
  SELECT id INTO v_root_id
  FROM public.product_images
  WHERE content_hash = NEW.content_hash
    AND deleted_at IS NULL
    AND canonical_image_id IS NULL
    AND id <> NEW.id
    AND is_shared = false
  ORDER BY created_at ASC, id ASC
  LIMIT 1;

  IF v_root_id IS NOT NULL THEN
    NEW.canonical_image_id := v_root_id;
    NEW.is_shared := true;
  ELSE
    -- Fallback: inherit root from existing dependent in same group
    SELECT pi2.canonical_image_id INTO v_root_id
    FROM public.product_images pi2
    WHERE pi2.content_hash = NEW.content_hash
      AND pi2.deleted_at IS NULL
      AND pi2.canonical_image_id IS NOT NULL
      AND pi2.id <> NEW.id
    LIMIT 1;

    IF v_root_id IS NOT NULL THEN
      NEW.canonical_image_id := v_root_id;
      NEW.is_shared := true;
    END IF;
    -- If only member → remain as standalone root
  END IF;

  -- ══════════════════════════════════════════════════════════════
  -- GAP-C5 / GAP-C5b: This row WAS a root (OLD.canonical_image_id IS NULL)
  -- in a previous hash group (OLD.content_hash IS NOT NULL).
  -- Former deps need re-grouping by THEIR OWN content_hash, regardless of
  -- whether this row joined a group (v_root_id IS NOT NULL) or stayed standalone.
  --
  -- Condition changed from migration 008:
  --   OLD: IF OLD.canonical_image_id IS NULL AND v_root_id IS NOT NULL
  --   NEW: IF OLD.canonical_image_id IS NULL AND OLD.content_hash IS NOT NULL
  -- ══════════════════════════════════════════════════════════════
  IF OLD.canonical_image_id IS NULL AND OLD.content_hash IS NOT NULL THEN

    -- Case A: Is there another live root for OLD.content_hash?
    SELECT id INTO v_old_group_root
    FROM public.product_images
    WHERE content_hash = OLD.content_hash
      AND deleted_at IS NULL
      AND canonical_image_id IS NULL
      AND id <> NEW.id
    ORDER BY created_at ASC, id ASC
    LIMIT 1;

    IF v_old_group_root IS NOT NULL THEN
      -- Link all former deps to the surviving root of OLD.content_hash group
      UPDATE public.product_images
      SET canonical_image_id = v_old_group_root,
          is_shared           = true,
          updated_at          = now()
      WHERE canonical_image_id = NEW.id
        AND id <> NEW.id
        AND deleted_at IS NULL;

    ELSE
      -- Case B: No other root for OLD.content_hash — elect oldest former dep as new root

      SELECT id INTO v_elected_dep_root
      FROM public.product_images
      WHERE canonical_image_id = NEW.id
        AND id <> NEW.id
        AND deleted_at IS NULL
      ORDER BY created_at ASC, id ASC
      LIMIT 1;

      IF v_elected_dep_root IS NOT NULL THEN
        -- Promote elected dep to standalone root
        UPDATE public.product_images
        SET canonical_image_id = NULL,
            is_shared           = false,
            updated_at          = now()
        WHERE id = v_elected_dep_root;

        -- Link all remaining former deps to the elected root
        UPDATE public.product_images
        SET canonical_image_id = v_elected_dep_root,
            is_shared           = true,
            updated_at          = now()
        WHERE canonical_image_id = NEW.id
          AND id <> NEW.id
          AND id <> v_elected_dep_root
          AND deleted_at IS NULL;
      END IF;
      -- If no former deps → nothing to do
    END IF;

  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_autolink_canonical_on_content_hash"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_autopromote_primary_on_deactivation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_next_id UUID;
BEGIN
  -- Only act when: was primary & active, now either inactive or no longer primary
  IF OLD.is_primary = true AND OLD.is_active = true THEN
    IF NEW.is_active = false OR NEW.is_primary = false THEN
      -- Check if any other primary already exists for this product
      IF NOT EXISTS (
        SELECT 1 FROM product_images
        WHERE product_id = OLD.product_id
          AND is_primary = true
          AND is_active = true
          AND id != OLD.id
      ) THEN
        -- Promote the next best active image (same priority as fn_sync_product_images_to_products)
        SELECT id INTO v_next_id
        FROM product_images
        WHERE product_id = OLD.product_id
          AND is_active = true
          AND id != OLD.id
          AND image_type NOT IN ('box','pouch','location','area','component')
        ORDER BY
          CASE
            WHEN image_type = 'main'                           THEN 0
            WHEN image_type IN ('gallery','product')           THEN 1
            WHEN image_type = 'ambient'                        THEN 2
            WHEN image_type = 'set'                            THEN 3
            WHEN image_type = 'logo'                           THEN 4
            ELSE 5
          END,
          display_order ASC NULLS LAST
        LIMIT 1;

        IF v_next_id IS NOT NULL THEN
          UPDATE product_images
          SET is_primary = true, updated_at = NOW()
          WHERE id = v_next_id;
        END IF;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_autopromote_primary_on_deactivation"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_autopromote_primary_on_deactivation"() IS 'Quando a imagem primária ativa é desativada ou desmarcada, promove automaticamente a próxima melhor imagem ativa para is_primary=true. Mantém o invariante: todo produto com imagens ativas tem exatamente uma marcada como primária.';



CREATE OR REPLACE FUNCTION "public"."fn_backfill_all_product_tags"("p_limit" integer DEFAULT 500, "p_only_empty" boolean DEFAULT false, "p_after_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pid       uuid;
  v_last_id   uuid;
  v_processed integer := 0;
  v_added     integer := 0;
  v_errors    integer := 0;
  v_result    jsonb;
BEGIN
  FOR v_pid IN
    SELECT p.id
    FROM products p
    WHERE p.is_active = true
      AND (p_after_id IS NULL OR p.id > p_after_id)
      AND (
        NOT p_only_empty
        OR NOT EXISTS (SELECT 1 FROM product_tags pt WHERE pt.product_id = p.id)
      )
    ORDER BY p.id
    LIMIT p_limit
  LOOP
    BEGIN
      v_result := public.fn_tag_product_complete(v_pid);
      v_added  := v_added + COALESCE((v_result->>'total_added')::int, 0);
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
    v_processed := v_processed + 1;
    v_last_id   := v_pid;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', v_processed, 'tags_added', v_added,
    'errors', v_errors, 'last_id', v_last_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_backfill_all_product_tags"("p_limit" integer, "p_only_empty" boolean, "p_after_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_backfill_asia_properties"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total        integer := 0;
  v_ok           integer := 0;
  v_skip         integer := 0;
  v_err          integer := 0;
  r              record;
  v_raw_text     text;
  v_result       jsonb;
BEGIN
  FOR r IN
    SELECT DISTINCT ON (p.id)
      p.id AS product_id,
      p.name AS product_name,
      spr.raw_data->>'descricao' AS descricao,
      spr.raw_data->>'nome'      AS nome_raw
    FROM products p
    JOIN suppliers s ON s.id = p.supplier_id
    JOIN supplier_products_raw spr ON spr.supplier_id = s.id
      AND (spr.supplier_sku = p.supplier_reference
           OR spr.supplier_sku LIKE p.supplier_reference || '-%'
           OR spr.supplier_sku LIKE p.supplier_reference || '|%')
    LEFT JOIN product_properties pp ON pp.product_id = p.id
    WHERE s.code = 'ASIA' AND p.is_active = true AND pp.id IS NULL
      AND spr.status = 'processed'
    ORDER BY p.id, spr.updated_at DESC NULLS LAST
  LOOP
    v_total := v_total + 1;
    v_raw_text := CONCAT_WS(', ', NULLIF(TRIM(r.nome_raw),''), NULLIF(TRIM(r.descricao),''), NULLIF(TRIM(r.product_name),''));
    IF v_raw_text IS NULL OR TRIM(v_raw_text) = '' THEN v_skip := v_skip + 1; CONTINUE; END IF;
    BEGIN
      SELECT public.fn_import_product_properties(r.product_id, v_raw_text, 'backfill_asia', 'asia') INTO v_result;
      IF (v_result->>'properties_imported')::integer > 0 THEN v_ok := v_ok + 1; ELSE v_skip := v_skip + 1; END IF;
    EXCEPTION WHEN OTHERS THEN v_err := v_err + 1;
    END;
  END LOOP;

  -- FASE 2: sem raw_data — usa product.name
  FOR r IN
    SELECT p.id AS product_id, p.name AS product_name
    FROM products p
    JOIN suppliers s ON s.id = p.supplier_id
    LEFT JOIN product_properties pp ON pp.product_id = p.id
    WHERE s.code = 'ASIA' AND p.is_active = true AND pp.id IS NULL
      AND NOT EXISTS (
        SELECT 1 FROM supplier_products_raw spr2
        JOIN suppliers s2 ON s2.id = spr2.supplier_id
        WHERE s2.code = 'ASIA'
          AND (spr2.supplier_sku = p.supplier_reference
               OR spr2.supplier_sku LIKE p.supplier_reference || '-%'
               OR spr2.supplier_sku LIKE p.supplier_reference || '|%')
      )
  LOOP
    v_total := v_total + 1;
    v_raw_text := TRIM(r.product_name);
    IF v_raw_text IS NULL OR v_raw_text = '' THEN v_skip := v_skip + 1; CONTINUE; END IF;
    BEGIN
      SELECT public.fn_import_product_properties(r.product_id, v_raw_text, 'backfill_asia_name', 'asia') INTO v_result;
      IF (v_result->>'properties_imported')::integer > 0 THEN v_ok := v_ok + 1; ELSE v_skip := v_skip + 1; END IF;
    EXCEPTION WHEN OTHERS THEN v_err := v_err + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('total_processados', v_total, 'com_properties', v_ok, 'sem_match', v_skip, 'erros', v_err,
    'cobertura_pct', ROUND(v_ok::numeric / NULLIF(v_total, 0) * 100, 1));
END;
$$;


ALTER FUNCTION "public"."fn_backfill_asia_properties"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_backfill_asia_properties"() IS 'Backfill de product_properties para produtos ASIA usando descricao+nome do Bronze. v1.0 2026-06-11';



CREATE OR REPLACE FUNCTION "public"."fn_backfill_eco_links"() RETURNS TABLE("produtos_processados" integer, "links_categoria_criados" integer, "links_data_criados" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_ecologia_category_id UUID := '896277ce-50ee-4bf5-9e5f-c118e6b4a36a';
    v_meio_ambiente_date_id UUID := '11b59fa3-14f1-4f5b-8c92-2e9bcb03e216';
    v_produtos INTEGER;
    v_cat_links INTEGER;
    v_date_links INTEGER;
BEGIN
    -- Contar produtos com materiais eco
    SELECT COUNT(DISTINCT pm.product_id)
    INTO v_produtos
    FROM product_materials pm
    JOIN eco_material_config emc ON pm.material_id = emc.material_id
    WHERE emc.is_active = TRUE;
    
    -- Inserir links de categoria
    WITH inserted AS (
        INSERT INTO product_category_assignments (product_id, category_id, is_primary, created_at)
        SELECT DISTINCT pm.product_id, v_ecologia_category_id, FALSE, NOW()
        FROM product_materials pm
        JOIN eco_material_config emc ON pm.material_id = emc.material_id
        WHERE emc.is_active = TRUE
        ON CONFLICT (product_id, category_id) DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_cat_links FROM inserted;
    
    -- Inserir links de data comemorativa
    WITH inserted AS (
        INSERT INTO product_commemorative_dates (product_id, commemorative_date_id, created_at)
        SELECT DISTINCT pm.product_id, v_meio_ambiente_date_id, NOW()
        FROM product_materials pm
        JOIN eco_material_config emc ON pm.material_id = emc.material_id
        WHERE emc.is_active = TRUE
        ON CONFLICT (product_id, commemorative_date_id) DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_date_links FROM inserted;
    
    RETURN QUERY SELECT v_produtos, v_cat_links, v_date_links;
END;
$$;


ALTER FUNCTION "public"."fn_backfill_eco_links"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_backfill_eco_links"() IS 'Processa produtos existentes e cria links eco retroativamente';



CREATE OR REPLACE FUNCTION "public"."fn_backfill_feminine_links"() RETURNS TABLE("variantes_processadas" integer, "produtos_atualizados" integer, "links_dia_mulher_criados" integer, "links_dia_maes_criados" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_dia_mulher_id UUID := 'ba801bb8-b48f-4b02-be72-4670584d92c0';
    v_dia_maes_id UUID := 'cdecfcac-e4f4-43a3-8839-196acf05ee5b';
    v_variantes INTEGER;
    v_produtos INTEGER;
    v_mulher_links INTEGER;
    v_maes_links INTEGER;
BEGIN
    -- Contar variantes com cores femininas
    SELECT COUNT(DISTINCT pv.id)
    INTO v_variantes
    FROM product_variants pv
    JOIN color_variations cv ON cv.id = pv.color_id
    JOIN feminine_color_config fcc ON fcc.color_group_id = cv.group_id
    WHERE fcc.is_active = TRUE;
    
    -- Atualizar target_audience dos produtos (CORREÇÃO: usar ARRAY)
    WITH updated AS (
        UPDATE products p
        SET target_audience = CASE 
                WHEN p.target_audience IS NULL THEN ARRAY['feminino']
                WHEN NOT ('feminino' = ANY(p.target_audience)) THEN array_append(p.target_audience, 'feminino')
                ELSE p.target_audience
            END,
            updated_at = NOW()
        FROM product_variants pv
        JOIN color_variations cv ON cv.id = pv.color_id
        JOIN feminine_color_config fcc ON fcc.color_group_id = cv.group_id
        WHERE p.id = pv.product_id
          AND fcc.is_active = TRUE
          AND (p.target_audience IS NULL OR NOT ('feminino' = ANY(p.target_audience)))
        RETURNING p.id
    )
    SELECT COUNT(DISTINCT id) INTO v_produtos FROM updated;
    
    -- Inserir links Dia da Mulher
    WITH inserted AS (
        INSERT INTO product_commemorative_dates (product_id, commemorative_date_id, created_at)
        SELECT DISTINCT pv.product_id, v_dia_mulher_id, NOW()
        FROM product_variants pv
        JOIN color_variations cv ON cv.id = pv.color_id
        JOIN feminine_color_config fcc ON fcc.color_group_id = cv.group_id
        WHERE fcc.is_active = TRUE
        ON CONFLICT (product_id, commemorative_date_id) DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_mulher_links FROM inserted;
    
    -- Inserir links Dia das Mães
    WITH inserted AS (
        INSERT INTO product_commemorative_dates (product_id, commemorative_date_id, created_at)
        SELECT DISTINCT pv.product_id, v_dia_maes_id, NOW()
        FROM product_variants pv
        JOIN color_variations cv ON cv.id = pv.color_id
        JOIN feminine_color_config fcc ON fcc.color_group_id = cv.group_id
        WHERE fcc.is_active = TRUE
        ON CONFLICT (product_id, commemorative_date_id) DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_maes_links FROM inserted;
    
    RETURN QUERY SELECT v_variantes, v_produtos, v_mulher_links, v_maes_links;
END;
$$;


ALTER FUNCTION "public"."fn_backfill_feminine_links"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_backfill_feminine_links"() IS '[CORRIGIDO] Processa variantes existentes e cria links femininos retroativamente (target_audience como ARRAY)';



CREATE OR REPLACE FUNCTION "public"."fn_backfill_is_thermal"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_via_props integer := 0;
  v_via_name  integer := 0;
  v_cleared   integer := 0;
BEGIN
  PERFORM set_config('app.bulk_import_mode', 'true', true);
  PERFORM set_config('app.write_source', 'pipeline', true);

  -- PASSO 1: true via product_properties
  UPDATE products p SET is_thermal = true
  WHERE p.is_active = true
    AND (p.is_thermal IS NULL OR p.is_thermal = false)
    AND EXISTS (
      SELECT 1 FROM product_properties pp
      WHERE pp.product_id = p.id
        AND pp.property_code IN (
          'DOUBLE_WALL','THERMAL_COLD_HOT_HOURS','THERMAL_COLD_24_HOT_12',
          'THERMAL_COLD_24_HOT_6','THERMAL_COLD','THERMAL_HOT','THERMAL_PROTECTION'
        )
    );
  GET DIAGNOSTICS v_via_props = ROW_COUNT;

  -- PASSO 2: true via nome/descrição
  UPDATE products p SET is_thermal = true
  WHERE p.is_active = true
    AND (p.is_thermal IS NULL OR p.is_thermal = false)
    AND (
      p.name ~* '\y(t[eé]rmic|garrafa\s+t[eé]rm|bolsa\s+t[eé]rm|lancheira|caneca\s+t[eé]rm|copo\s+t[eé]rm|squeeze\s+t[eé]rm|cooler|isotérm|isot[eé]rm)\y'
      OR p.name ~* 'parede\s+dupla'
      OR (p.name ~* 'inox' AND p.name ~* '(garrafa|copo|caneca|squeeze|bolsa|cuia)')
      OR p.description ~* '(parede\s+dupla|isolad[ao]\s+a\s+v[aá]cuo|mant[eé]m\s+(fria|quente|temperatura)|horas\s+(fria|quente)|frias\s+e\s+quentes)'
    );
  GET DIAGNOSTICS v_via_name = ROW_COUNT;

  -- PASSO 3: false para produtos que não têm evidência de thermal (seguro = só NULLs)
  UPDATE products p SET is_thermal = false
  WHERE p.is_active = true
    AND p.is_thermal IS NULL;
  GET DIAGNOSTICS v_cleared = ROW_COUNT;

  RETURN jsonb_build_object(
    'marcados_via_properties', v_via_props,
    'marcados_via_nome',       v_via_name,
    'default_false',           v_cleared,
    'total_ativados',          v_via_props + v_via_name
  );
END;
$$;


ALTER FUNCTION "public"."fn_backfill_is_thermal"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_backfill_is_thermal"() IS 'Sincroniza is_thermal em products via product_properties + nome/descrição. Safe para bulk. v1.0 2026-06-11';



CREATE OR REPLACE FUNCTION "public"."fn_backfill_product_attributes_safe"("p_batch_size" integer DEFAULT 100, "p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_product RECORD;
    v_colors TEXT[];
    v_capacity INTEGER;
    v_dimensions JSONB;
    v_weight INTEGER;
    v_processed INTEGER := 0;
    v_updated INTEGER := 0;
    v_sample JSONB[] := '{}';
BEGIN
    FOR v_product IN (
        SELECT id, name
        FROM products
        WHERE name IS NOT NULL
          AND (
            (colors IS NULL OR jsonb_array_length(colors) = 0)
            OR capacity_ml IS NULL
          )
        ORDER BY created_at DESC
        LIMIT p_batch_size
    ) LOOP
        v_processed := v_processed + 1;
        
        -- Extrair atributos do nome
        v_colors := fn_extract_color_from_name(v_product.name);
        v_capacity := fn_extract_capacity_from_name(v_product.name);
        v_dimensions := fn_extract_dimensions_from_name(v_product.name);
        v_weight := fn_extract_weight_from_name(v_product.name);
        
        -- Verificar se tem algo para atualizar
        IF array_length(v_colors, 1) > 0 OR 
           v_capacity IS NOT NULL OR
           v_weight IS NOT NULL OR
           v_dimensions IS NOT NULL THEN
            
            IF NOT p_dry_run THEN
                -- ⚠️ NÃO ATUALIZA materials (evita erro de trigger)
                UPDATE products SET
                    colors = CASE WHEN array_length(v_colors, 1) > 0 THEN to_jsonb(v_colors) ELSE colors END,
                    has_colors = CASE WHEN array_length(v_colors, 1) > 0 THEN true ELSE has_colors END,
                    capacity_ml = COALESCE(v_capacity, capacity_ml),
                    has_capacity = CASE WHEN v_capacity IS NOT NULL THEN true ELSE has_capacity END,
                    length_cm = COALESCE((v_dimensions->>'length_cm')::NUMERIC, length_cm),
                    width_cm = COALESCE((v_dimensions->>'width_cm')::NUMERIC, width_cm),
                    height_cm = COALESCE((v_dimensions->>'height_cm')::NUMERIC, height_cm),
                    weight_g = COALESCE(v_weight, weight_g)
                WHERE id = v_product.id;
            END IF;
            
            v_updated := v_updated + 1;
            
            IF v_updated <= 5 THEN
                v_sample := array_append(v_sample, jsonb_build_object(
                    'name', LEFT(v_product.name, 50),
                    'colors', v_colors,
                    'capacity_ml', v_capacity,
                    'weight_g', v_weight
                ));
            END IF;
        END IF;
    END LOOP;
    
    RETURN jsonb_build_object(
        'processed', v_processed,
        'updated', v_updated,
        'dry_run', p_dry_run,
        'sample', to_jsonb(v_sample)
    );
END;
$$;


ALTER FUNCTION "public"."fn_backfill_product_attributes_safe"("p_batch_size" integer, "p_dry_run" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_backfill_product_categories"("p_batch_size" integer DEFAULT 100, "p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_product RECORD;
    v_result JSONB;
    v_category_id UUID;
    v_processed INTEGER := 0;
    v_success INTEGER := 0;
    v_failed INTEGER := 0;
    v_skipped INTEGER := 0;
    v_results JSONB[] := '{}';
BEGIN
    -- Buscar produtos sem categoria
    FOR v_product IN (
        SELECT id, name
        FROM products
        WHERE category_id IS NULL
          AND name IS NOT NULL
          AND TRIM(name) != ''
        ORDER BY created_at DESC
        LIMIT p_batch_size
    ) LOOP
        v_processed := v_processed + 1;
        
        BEGIN
            -- Classificar produto
            SELECT fn_master_classify_product(v_product.name, v_product.id) INTO v_result;
            
            IF v_result IS NOT NULL AND v_result->>'category_id' IS NOT NULL THEN
                v_category_id := (v_result->>'category_id')::UUID;
                
                IF NOT p_dry_run THEN
                    -- Atualizar produto (desabilitar trigger temporariamente para evitar loop)
                    UPDATE products 
                    SET category_id = v_category_id,
                        updated_at = NOW()
                    WHERE id = v_product.id;
                END IF;
                
                v_success := v_success + 1;
                
                -- Guardar amostra dos resultados
                IF v_success <= 10 THEN
                    v_results := array_append(v_results, jsonb_build_object(
                        'product_id', v_product.id,
                        'name', v_product.name,
                        'category_slug', v_result->>'category_slug',
                        'detected_type', v_result->>'detected_type'
                    ));
                END IF;
            ELSE
                v_skipped := v_skipped + 1;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            v_failed := v_failed + 1;
            RAISE WARNING 'Erro ao processar %: %', v_product.id, SQLERRM;
        END;
    END LOOP;
    
    RETURN jsonb_build_object(
        'processed', v_processed,
        'success', v_success,
        'failed', v_failed,
        'skipped', v_skipped,
        'dry_run', p_dry_run,
        'sample_results', to_jsonb(v_results)
    );
END;
$$;


ALTER FUNCTION "public"."fn_backfill_product_categories"("p_batch_size" integer, "p_dry_run" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_batch_extract_materials_from_name"("p_limit" integer DEFAULT 100) RETURNS TABLE("processed" integer, "total_materials" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_product RECORD;
    v_processed INTEGER := 0;
    v_total_materials INTEGER := 0;
    v_materials INTEGER;
BEGIN
    -- Processar produtos sem vínculos em product_materials
    FOR v_product IN 
        SELECT p.id, p.name
        FROM products p
        LEFT JOIN product_materials pm ON pm.product_id = p.id
        WHERE pm.id IS NULL
          AND p.name IS NOT NULL
        LIMIT p_limit
    LOOP
        v_materials := fn_extract_materials_from_name(v_product.id, FALSE);
        v_total_materials := v_total_materials + v_materials;
        v_processed := v_processed + 1;
    END LOOP;
    
    RETURN QUERY SELECT v_processed, v_total_materials;
END;
$$;


