Parâmetros:
  - p_limit: Número máximo de produtos a processar (default: 100)
Retorno: processed (produtos processados), total_materials (vínculos criados)
Criado: 30/01/2026';



CREATE OR REPLACE FUNCTION "public"."fn_batch_populate_packing"("p_limit" integer DEFAULT 100) RETURNS TABLE("processed" integer, "updated" integer, "commercial" integer, "protective" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_processed INTEGER := 0;
    v_updated INTEGER := 0;
    v_commercial INTEGER := 0;
    v_protective INTEGER := 0;
    v_product RECORD;
    v_packing TEXT;
    v_classification JSONB;
BEGIN
    FOR v_product IN 
        SELECT p.id, p.sku
        FROM products p
        WHERE p.packing_classification IS NULL
          AND p.sku LIKE 'SPOT-%'
        LIMIT p_limit
    LOOP
        v_processed := v_processed + 1;
        
        -- CORRIGIDO: Usar product_id diretamente
        SELECT DISTINCT raw_data->>'Packing' INTO v_packing
        FROM supplier_products_raw spr
        WHERE spr.product_id = v_product.id
          AND raw_data->>'Packing' IS NOT NULL
          AND raw_data->>'Packing' <> ''
        LIMIT 1;
        
        IF v_packing IS NOT NULL AND v_packing <> '' THEN
            v_classification := fn_classify_packing_type(v_packing);
            
            IF v_classification IS NOT NULL THEN
                UPDATE products
                SET packing_type = v_packing,
                    packing_classification = (v_classification->>'classification')::VARCHAR
                WHERE id = v_product.id;
                
                v_updated := v_updated + 1;
                
                IF (v_classification->>'classification') = 'commercial' THEN
                    v_commercial := v_commercial + 1;
                ELSIF (v_classification->>'classification') = 'protective' THEN
                    v_protective := v_protective + 1;
                END IF;
            END IF;
        END IF;
    END LOOP;
    
    RETURN QUERY SELECT v_processed, v_updated, v_commercial, v_protective;
END;
$$;


ALTER FUNCTION "public"."fn_batch_populate_packing"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_batch_update_cart_item_sort_order"("p_updates" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado' USING ERRCODE = '28000';
  END IF;

  -- Valida entrada: deve ser um array JSON não-vazio
  IF jsonb_typeof(p_updates) <> 'array' OR jsonb_array_length(p_updates) = 0 THEN
    RETURN; -- no-op silencioso para chamadas vazias/inválidas
  END IF;

  -- Atualiza em um único UPDATE ... FROM (VALUES) com guard de ownership.
  -- RLS não se aplica em SECURITY DEFINER — usamos o EXISTS manual.
  UPDATE public.seller_cart_items sci
  SET
    sort_order = (u->>'sort_order')::integer,
    updated_at = now()
  FROM jsonb_array_elements(p_updates) AS u
  WHERE
    sci.id = (u->>'id')::uuid
    AND EXISTS (
      SELECT 1 FROM public.seller_carts sc
      WHERE sc.id = sci.cart_id
        AND sc.seller_id = v_uid
    );
END;
$$;


ALTER FUNCTION "public"."fn_batch_update_cart_item_sort_order"("p_updates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_best_packaging_price"("p_packaging_id" "uuid", "p_quantity" integer DEFAULT 1) RETURNS TABLE("supplier_id" "uuid", "supplier_name" character varying, "unit_price" numeric, "total_price" numeric, "lead_time_days" integer)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        sp.supplier_id,
        s.name as supplier_name,
        sp.unit_price,
        (sp.unit_price * p_quantity) as total_price,
        sp.lead_time_days
    FROM supplier_packagings sp
    JOIN suppliers s ON s.id = sp.supplier_id
    WHERE sp.packaging_id = p_packaging_id
      AND sp.active = TRUE
      AND sp.is_available = TRUE
      AND sp.min_order_quantity <= p_quantity
    ORDER BY sp.unit_price ASC
    LIMIT 5;
END;
$$;


