COMMENT ON FUNCTION "public"."fn_calculate_kit_dimensions"("p_kit_id" "uuid") IS 'Calcula peso total, dimensões da embalagem (ext + int), lista de materiais
   e percentual de enriquecimento para um kit. Funciona quando enrichment_status=complete.';



CREATE OR REPLACE FUNCTION "public"."fn_calculate_packaging_fit"("p_product_id" "uuid", "p_packaging_id" "uuid", "p_config_type" "text" DEFAULT 'default'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_product RECORD; v_packaging RECORD;
    v_gap_h DECIMAL; v_gap_w DECIMAL; v_gap_l DECIMAL; v_gap_d DECIMAL;
    v_gap_min DECIMAL; v_gap_avg DECIMAL; v_rating VARCHAR(20); v_prefix TEXT;
    v_min DECIMAL := 2; v_tight DECIMAL := 5; v_good DECIMAL := 15; v_max DECIMAL := 50;
    v_pkg_dims DECIMAL[]; v_pkg_long DECIMAL; v_pkg_short DECIMAL; v_pkg_mid DECIMAL;
    v_needs_padding BOOLEAN := false;
BEGIN
    v_prefix := lower(trim(COALESCE(p_config_type,'default')));
    IF v_prefix NOT IN ('fragile','precision','bottles') THEN v_prefix := ''; END IF;
    IF v_prefix <> '' THEN v_prefix := v_prefix || '_'; END IF;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key=v_prefix||'min_gap_mm'),(SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key='min_gap_mm'),2) INTO v_min;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key=v_prefix||'tight_max_mm'),(SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key='tight_gap_max_mm'),5) INTO v_tight;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key=v_prefix||'good_max_mm'),(SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key='good_gap_max_mm'),15) INTO v_good;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key=v_prefix||'max_gap_mm'),(SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key='max_gap_mm'),50) INTO v_max;
    SELECT height_cm, width_cm, length_cm, diameter_cm, shape_type INTO v_product FROM products WHERE id=p_product_id;
    IF v_product IS NULL THEN RETURN jsonb_build_object('error','Produto não encontrado: '||p_product_id,'compatible',false,'fit_rating','error','needs_padding',false); END IF;
    -- FIX: internal_diameter_cm NAO existe em products -> NULL.
    SELECT internal_height_cm, internal_width_cm, internal_length_cm, NULL::numeric AS internal_diameter_cm, product_type
      INTO v_packaging FROM products WHERE id=p_packaging_id;
    IF v_packaging IS NULL OR v_packaging.product_type <> 'packaging' THEN
        RETURN jsonb_build_object('error',CASE WHEN v_packaging IS NULL THEN 'Embalagem não encontrada: '||p_packaging_id ELSE 'Produto '||p_packaging_id||' não é do tipo packaging' END,'compatible',false,'fit_rating','error','needs_padding',false);
    END IF;
    IF v_product.shape_type = 'cylindrical' THEN
        IF v_packaging.internal_diameter_cm IS NOT NULL THEN
            v_gap_d := (v_packaging.internal_diameter_cm - COALESCE(v_product.diameter_cm,v_product.width_cm)) * 10;
            v_gap_h := (v_packaging.internal_height_cm - v_product.height_cm) * 10;
        ELSE
            v_pkg_dims := ARRAY[COALESCE(v_packaging.internal_height_cm,0),COALESCE(v_packaging.internal_width_cm,0),COALESCE(v_packaging.internal_length_cm,0)];
            v_pkg_long := GREATEST(v_pkg_dims[1],v_pkg_dims[2],v_pkg_dims[3]);
            v_pkg_short := LEAST(v_pkg_dims[1],v_pkg_dims[2],v_pkg_dims[3]);
            v_pkg_mid := v_pkg_dims[1]+v_pkg_dims[2]+v_pkg_dims[3]-v_pkg_long-v_pkg_short;
            v_gap_h := (v_pkg_long - v_product.height_cm) * 10;
            v_gap_d := (v_pkg_short - COALESCE(v_product.diameter_cm,v_product.width_cm)) * 10;
            IF v_pkg_mid < COALESCE(v_product.diameter_cm,v_product.width_cm) THEN
                v_gap_d := LEAST(v_gap_d,(v_pkg_mid-COALESCE(v_product.diameter_cm,v_product.width_cm))*10);
            END IF;
        END IF;
        v_gap_min := LEAST(COALESCE(v_gap_d,999),COALESCE(v_gap_h,999));
        v_gap_avg := (COALESCE(v_gap_d,0)+COALESCE(v_gap_h,0))/2.0;
        IF COALESCE(v_gap_h,0) > 200 THEN v_needs_padding := true; END IF;
    ELSE
        v_gap_h := (v_packaging.internal_height_cm - v_product.height_cm) * 10;
        v_gap_w := (v_packaging.internal_width_cm - v_product.width_cm) * 10;
        v_gap_l := (v_packaging.internal_length_cm - v_product.length_cm) * 10;
        v_gap_min := LEAST(COALESCE(v_gap_h,999),COALESCE(v_gap_w,999),COALESCE(v_gap_l,999));
        v_gap_avg := (COALESCE(v_gap_h,0)+COALESCE(v_gap_w,0)+COALESCE(v_gap_l,0))/3.0;
    END IF;
    IF    v_gap_min IS NULL OR v_gap_min >= 900 THEN v_rating := 'incompatible';
    ELSIF v_gap_min < 0 THEN v_rating := 'too_tight';
    ELSIF v_gap_min < v_min THEN v_rating := 'too_tight';
    ELSIF v_gap_min <= v_tight THEN v_rating := 'tight';
    ELSIF v_gap_min <= v_good THEN v_rating := 'good';
    ELSIF v_gap_min <= v_max THEN v_rating := 'loose';
    ELSE v_rating := 'too_large'; END IF;
    IF v_needs_padding AND v_rating IN ('tight','good') THEN v_rating := 'loose'; END IF;
    RETURN jsonb_build_object('compatible',v_rating IN ('tight','good','loose'),'fit_rating',v_rating,
        'config_type',COALESCE(NULLIF(p_config_type,'default'),'default'),
        'gap_height_mm',ROUND(COALESCE(v_gap_h,0)::numeric,2),'gap_width_mm',ROUND(COALESCE(v_gap_w,0)::numeric,2),
        'gap_length_mm',ROUND(COALESCE(v_gap_l,0)::numeric,2),'gap_diameter_mm',ROUND(COALESCE(v_gap_d,0)::numeric,2),
        'gap_min_mm',CASE WHEN v_gap_min < 900 THEN ROUND(v_gap_min::numeric,2) ELSE NULL END,
        'gap_avg_mm',ROUND(v_gap_avg::numeric,2),'shape',v_product.shape_type,'needs_padding',v_needs_padding,
        'limits_mm',jsonb_build_object('min',v_min,'tight',v_tight,'good',v_good,'max',v_max));
END;$$;


ALTER FUNCTION "public"."fn_calculate_packaging_fit"("p_product_id" "uuid", "p_packaging_id" "uuid", "p_config_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_calculate_packaging_fit"("p_product_id" "uuid", "p_packaging_id" "uuid", "p_config_type" "text") IS 'v4 — Inclui regra B11 (disco plano): se gap_height > 200mm → needs_padding=true, fit_rating cap=loose.
Schema consistente: erro retorna fit_rating=''error''.
Cilíndrico×retangular: orientação ótima (produto na maior dim da caixa).
Suporta config_type: default|fragile|precision|bottles.';



CREATE OR REPLACE FUNCTION "public"."fn_calculate_sale_price"("p_product_id" "uuid", "p_quantity" integer DEFAULT 1, "p_price_list_id" "uuid" DEFAULT NULL::"uuid") RETURNS numeric
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_cost_price NUMERIC;
    v_fallback_cost NUMERIC;
    v_markup_percent NUMERIC;
    v_supplier_id UUID;
    v_category_id UUID;
BEGIN
    SELECT cost_price, category_id INTO v_fallback_cost, v_category_id
    FROM products WHERE id = p_product_id;
    
    IF v_fallback_cost IS NULL OR v_fallback_cost = 0 THEN RETURN NULL; END IF;
    
    SELECT 
        CASE 
            WHEN p_quantity >= COALESCE(vss.min_qty_5, 999999) AND vss.cost_price_5 IS NOT NULL THEN vss.cost_price_5
            WHEN p_quantity >= COALESCE(vss.min_qty_4, 999999) AND vss.cost_price_4 IS NOT NULL THEN vss.cost_price_4
            WHEN p_quantity >= COALESCE(vss.min_qty_3, 999999) AND vss.cost_price_3 IS NOT NULL THEN vss.cost_price_3
            WHEN p_quantity >= COALESCE(vss.min_qty_2, 999999) AND vss.cost_price_2 IS NOT NULL THEN vss.cost_price_2
            WHEN vss.cost_price_1 IS NOT NULL THEN vss.cost_price_1
            ELSE vss.cost_price
        END,
        vss.supplier_id
    INTO v_cost_price, v_supplier_id
    FROM product_variants pv
    JOIN variant_supplier_sources vss ON vss.variant_id = pv.id AND vss.is_preferred = true
    WHERE pv.product_id = p_product_id
    LIMIT 1;
    
    v_cost_price := COALESCE(v_cost_price, v_fallback_cost);
    
    SELECT markup_percent INTO v_markup_percent
    FROM markup_configurations
    WHERE category_id = v_category_id AND product_id IS NULL AND variant_id IS NULL AND is_active = true
    LIMIT 1;
    
    IF v_markup_percent IS NULL AND v_supplier_id IS NOT NULL THEN
        SELECT default_markup_percent INTO v_markup_percent
        FROM suppliers WHERE id = v_supplier_id;
    END IF;
    
    IF v_markup_percent IS NULL THEN
        SELECT markup_percent INTO v_markup_percent
        FROM markup_configurations
        WHERE category_id IS NULL AND product_id IS NULL AND variant_id IS NULL AND is_active = true
        ORDER BY priority DESC LIMIT 1;
    END IF;
    
    v_markup_percent := COALESCE(v_markup_percent, 115.0);
    
    RETURN ROUND(v_cost_price * (1 + v_markup_percent / 100), 2);
END;
$$;


ALTER FUNCTION "public"."fn_calculate_sale_price"("p_product_id" "uuid", "p_quantity" integer, "p_price_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_capacity_forecast"("p_days_ahead" integer DEFAULT 90) RETURNS TABLE("metric" "text", "current_value" bigint, "growth_per_day" numeric, "projected_value" bigint, "projection_date" "date", "status" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_products_growth numeric;
  v_variants_growth numeric;
  v_images_growth numeric;
  v_snapshots_growth numeric;
  v_db_size bigint;
BEGIN
  SELECT COALESCE(COUNT(*) FILTER (WHERE created_at > now() - interval '30 days')::numeric / 30, 0)
    INTO v_products_growth FROM products;
  SELECT COALESCE(COUNT(*) FILTER (WHERE created_at > now() - interval '30 days')::numeric / 30, 0)
    INTO v_variants_growth FROM product_variants;
  SELECT COALESCE(COUNT(*) FILTER (WHERE created_at > now() - interval '30 days')::numeric / 30, 0)
    INTO v_images_growth FROM product_images;
  SELECT COALESCE(COUNT(*) FILTER (WHERE captured_at > now() - interval '7 days')::numeric / 7, 0)
    INTO v_snapshots_growth FROM stock_snapshots;
  SELECT pg_database_size(current_database()) INTO v_db_size;

  RETURN QUERY SELECT 'products'::text, (SELECT COUNT(*) FROM products)::bigint, v_products_growth,
    ((SELECT COUNT(*) FROM products) + (v_products_growth * p_days_ahead))::bigint,
    (CURRENT_DATE + (p_days_ahead || ' days')::interval)::date,
    CASE WHEN (SELECT COUNT(*) FROM products) + (v_products_growth * p_days_ahead) > 100000 
      THEN '⚠️ Considere particionamento' ELSE '✅ OK' END;

  RETURN QUERY SELECT 'product_variants'::text, (SELECT COUNT(*) FROM product_variants)::bigint, v_variants_growth,
    ((SELECT COUNT(*) FROM product_variants) + (v_variants_growth * p_days_ahead))::bigint,
    (CURRENT_DATE + (p_days_ahead || ' days')::interval)::date,
    CASE WHEN (SELECT COUNT(*) FROM product_variants) + (v_variants_growth * p_days_ahead) > 500000 
      THEN '⚠️ Considere particionamento' ELSE '✅ OK' END;

  RETURN QUERY SELECT 'product_images'::text, (SELECT COUNT(*) FROM product_images)::bigint, v_images_growth,
    ((SELECT COUNT(*) FROM product_images) + (v_images_growth * p_days_ahead))::bigint,
    (CURRENT_DATE + (p_days_ahead || ' days')::interval)::date,
    CASE WHEN (SELECT COUNT(*) FROM product_images) + (v_images_growth * p_days_ahead) > 1000000 
      THEN '⚠️ Considere particionamento' ELSE '✅ OK' END;

  RETURN QUERY SELECT 'stock_snapshots'::text, (SELECT COUNT(*) FROM stock_snapshots)::bigint, v_snapshots_growth,
    ((SELECT COUNT(*) FROM stock_snapshots) + (v_snapshots_growth * p_days_ahead))::bigint,
    (CURRENT_DATE + (p_days_ahead || ' days')::interval)::date,
    CASE WHEN v_snapshots_growth > 1000 
      THEN '💡 Purge 14d já ativo via cron' ELSE '✅ OK' END;

  RETURN QUERY SELECT 'database_size_mb'::text, (v_db_size / 1024 / 1024)::bigint, 0.0::numeric, 0::bigint,
    CURRENT_DATE, '💾 ' || pg_size_pretty(v_db_size);
END;
$$;


ALTER FUNCTION "public"."fn_capacity_forecast"("p_days_ahead" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_capacity_forecast"("p_days_ahead" integer) IS 'Previsão de crescimento para capacity planning. Usage: SELECT * FROM fn_capacity_forecast(90);';



CREATE OR REPLACE FUNCTION "public"."fn_capture_connection_snapshot"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total int; v_active int; v_idle_tx int; v_max int;
  v_pct numeric(5,2); v_top_users jsonb; v_result jsonb;
BEGIN
  SELECT COUNT(*), COUNT(*) FILTER (WHERE state='active'),
    COUNT(*) FILTER (WHERE state='idle in transaction'),
    (SELECT setting::int FROM pg_settings WHERE name='max_connections')
  INTO v_total, v_active, v_idle_tx, v_max
  FROM pg_stat_activity WHERE pid != pg_backend_pid();
  v_pct := ROUND((v_total::numeric / NULLIF(v_max,0)) * 100, 2);
  SELECT jsonb_agg(row_to_json(t)) INTO v_top_users FROM (
    SELECT usename, state, COUNT(*) as n FROM pg_stat_activity
    WHERE pid != pg_backend_pid()
    GROUP BY usename, state ORDER BY n DESC LIMIT 8) t;
  INSERT INTO public.db_connection_snapshots
    (total_conns,active_conns,idle_in_tx_conns,max_conns,usage_pct,top_users)
  VALUES(v_total,v_active,v_idle_tx,v_max,v_pct,v_top_users);
  DELETE FROM public.db_connection_snapshots WHERE captured_at < now()-interval '7 days';
  v_result := jsonb_build_object('total',v_total,'active',v_active,
    'idle_in_tx',v_idle_tx,'max',v_max,'usage_pct',v_pct,'alert',v_pct>=75);
  RETURN v_result;
END; $$;


ALTER FUNCTION "public"."fn_capture_connection_snapshot"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_capture_connection_snapshot"() IS 'Captura snapshot de conexões do banco. Alerta quando uso >= 75%. Chamado a cada 1 minuto pelo cron monitor-connections.';



CREATE OR REPLACE FUNCTION "public"."fn_capture_schema_baseline"("p_label" "text" DEFAULT 'manual'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  -- fix_version: baseline_capture_allowlist_aware_v2_20260627
  -- PATCH 2026-06-27: exclui tabelas na schema_signature_drift_allowlist
  --   (coluna IS NULL = exclusão de tabela inteira) para manter o baseline
  --   limpo de objetos de teste/infra que não devem ser monitorados.
  DELETE FROM public.schema_signature_baseline;

  INSERT INTO public.schema_signature_baseline
    (table_name, column_name, data_type, baseline_label, captured_at)
  SELECT
    c.table_name, c.column_name, c.data_type, p_label, now()
  FROM information_schema.columns c
  WHERE c.table_schema = 'public'
    AND c.table_name NOT LIKE 'pg_%'
    AND c.table_name NOT LIKE '_backup_%'
    -- excluir tabelas/views inteiras da allowlist
    AND c.table_name NOT IN (
      SELECT a.table_name
      FROM public.schema_signature_drift_allowlist a
      WHERE a.column_name IS NULL
    );

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_capture_schema_baseline"("p_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_capture_stock_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product_id    uuid;
  v_stock_changed boolean;
  v_price_changed boolean;
  v_date_changed  boolean;
  v_change_type   varchar(20);
BEGIN
  -- Supressão controlada (correções em massa): SET LOCAL app.skip_stock_snapshot='true'
  IF current_setting('app.skip_stock_snapshot', true) = 'true' THEN
    RETURN NEW;
  END IF;

  v_stock_changed := (
    OLD.stock_main_warehouse  IS DISTINCT FROM NEW.stock_main_warehouse
    OR OLD.stock_other_warehouses IS DISTINCT FROM NEW.stock_other_warehouses
  );
  v_price_changed := (OLD.cost_price IS DISTINCT FROM NEW.cost_price);
  v_date_changed  := (OLD.next_date_1 IS DISTINCT FROM NEW.next_date_1);

  IF NOT v_stock_changed AND NOT v_price_changed AND NOT v_date_changed THEN
    RETURN NEW;
  END IF;

  IF v_stock_changed AND v_price_changed THEN
    v_change_type := 'both';
  ELSIF v_price_changed THEN
    v_change_type := 'price';
  ELSIF v_date_changed AND NOT v_stock_changed THEN
    v_change_type := 'restock_date';
  ELSE
    v_change_type := 'stock';
  END IF;

  SELECT pv.product_id INTO v_product_id
  FROM product_variants pv WHERE pv.id = NEW.variant_id;

  IF v_product_id IS NULL THEN RETURN NEW; END IF;

  INSERT INTO stock_snapshots (
    variant_supplier_source_id, supplier_id, supplier_branch_id,
    variant_id, product_id,
    stock_main_old, stock_main_new,
    stock_other_old, stock_other_new,
    cost_price_old, cost_price_new,
    change_type, captured_at, sync_source
  ) VALUES (
    NEW.id, NEW.supplier_id, NEW.supplier_branch_id,
    NEW.variant_id, v_product_id,
    CASE WHEN v_stock_changed THEN OLD.stock_main_warehouse  ELSE NULL END,
    CASE WHEN v_stock_changed THEN NEW.stock_main_warehouse  ELSE NULL END,
    CASE WHEN v_stock_changed THEN OLD.stock_other_warehouses ELSE NULL END,
    CASE WHEN v_stock_changed THEN NEW.stock_other_warehouses ELSE NULL END,
    CASE WHEN v_price_changed THEN OLD.cost_price ELSE NULL END,
    CASE WHEN v_price_changed THEN NEW.cost_price ELSE NULL END,
    v_change_type, now(), NEW.source
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_capture_stock_snapshot"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_capture_stock_snapshot"() IS 'Captura snapshots de mudanças de estoque e preço em variant_supplier_sources. Grava na tabela stock_snapshots para análise histórica.';



CREATE OR REPLACE FUNCTION "public"."fn_capture_supplier_promise"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_slot     smallint;
  v_date     date;
  v_qty      integer;
  v_old_date date;
  v_old_qty  integer;
BEGIN
  FOR v_slot IN 1..6 LOOP

    v_date := CASE v_slot
      WHEN 1 THEN NEW.next_date_1 WHEN 2 THEN NEW.next_date_2
      WHEN 3 THEN NEW.next_date_3 WHEN 4 THEN NEW.next_date_4
      WHEN 5 THEN NEW.next_date_5 WHEN 6 THEN NEW.next_date_6
    END;
    v_qty := CASE v_slot
      WHEN 1 THEN NEW.next_quantity_1 WHEN 2 THEN NEW.next_quantity_2
      WHEN 3 THEN NEW.next_quantity_3 WHEN 4 THEN NEW.next_quantity_4
      WHEN 5 THEN NEW.next_quantity_5 WHEN 6 THEN NEW.next_quantity_6
    END;

    IF TG_OP = 'UPDATE' THEN
      v_old_date := CASE v_slot
        WHEN 1 THEN OLD.next_date_1 WHEN 2 THEN OLD.next_date_2
        WHEN 3 THEN OLD.next_date_3 WHEN 4 THEN OLD.next_date_4
        WHEN 5 THEN OLD.next_date_5 WHEN 6 THEN OLD.next_date_6
      END;
      v_old_qty := CASE v_slot
        WHEN 1 THEN OLD.next_quantity_1 WHEN 2 THEN OLD.next_quantity_2
        WHEN 3 THEN OLD.next_quantity_3 WHEN 4 THEN OLD.next_quantity_4
        WHEN 5 THEN OLD.next_quantity_5 WHEN 6 THEN OLD.next_quantity_6
      END;

      -- Slot foi zerado antes de expirar → superseded
      IF (v_old_date IS NOT NULL AND COALESCE(v_old_qty, 0) > 0)
         AND (v_date IS NULL OR COALESCE(v_qty, 0) <= 0)
         AND v_old_date >= (current_date - 15) THEN
        UPDATE public.supplier_replenishment_events
        SET resolution = 'superseded', resolved_at = now(), updated_at = now()
        WHERE source_id = NEW.id AND slot = v_slot
          AND promised_date = v_old_date AND resolution = 'pending';
        CONTINUE;
      END IF;

      -- Sem mudança → skip
      IF (v_old_date IS NOT DISTINCT FROM v_date)
         AND (v_old_qty IS NOT DISTINCT FROM v_qty) THEN
        CONTINUE;
      END IF;
    END IF;

    IF v_date IS NOT NULL AND COALESCE(v_qty, 0) > 0 THEN
      INSERT INTO public.supplier_replenishment_events (
        source_id, supplier_id, variant_id, slot, promised_date, promised_quantity, observed_at
      ) VALUES (
        NEW.id, NEW.supplier_id, NEW.variant_id,
        v_slot, v_date, v_qty, COALESCE(NEW.updated_at, now())
      )
      ON CONFLICT (source_id, slot, promised_date, promised_quantity, observed_at) DO NOTHING;
    END IF;

  END LOOP;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_capture_supplier_promise"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_capture_supplier_promise"() IS 'Trigger AFTER INSERT (trg_csp_insert) e AFTER UPDATE (trg_csp_update WHEN next_date/qty mudam) em variant_supplier_sources. Itera slots 1-6, inserindo promessas novas com ON CONFLICT DO NOTHING e marcando superseded slots que foram zerados antes de 15 dias da data prometida.';



CREATE OR REPLACE FUNCTION "public"."fn_cascade_deactivate_vss"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Quando variante é desativada, desativar VSS correspondentes
  IF (TG_OP = 'UPDATE') AND (OLD.is_active IS DISTINCT FROM NEW.is_active) AND NOT NEW.is_active THEN
    UPDATE variant_supplier_sources
    SET is_active = FALSE, updated_at = NOW()
    WHERE variant_id = NEW.id AND is_active = TRUE;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_cascade_deactivate_vss"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cascade_product_deactivation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- fix_version: orphan-variants-cascade-2026-07-03
  -- ANTI-REGRESSÃO: não remover este trigger — previne variantes órfãs
  -- quando produto é desativado. Cascateia apenas FALSE (reativação é manual).
  IF OLD.is_active = TRUE AND NEW.is_active = FALSE THEN
    UPDATE public.product_variants
    SET is_active = FALSE, updated_at = NOW()
    WHERE product_id = NEW.id
      AND is_active = TRUE;
  END IF;
  RETURN NEW;
END;
$$;


