CREATE OR REPLACE FUNCTION "public"."fn_cf_collect_sm_legacy_dispatch"("p_start_page" integer, "p_end_page" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net'
    AS $$
DECLARE
  v_creds jsonb;
  v_token text;
  v_account_id text;
  v_page integer;
  v_url text;
  v_request_id bigint;
  v_request_ids bigint[] := ARRAY[]::bigint[];
BEGIN
  v_creds := fn_get_cf_credentials();
  v_account_id := v_creds->>'account_id';
  v_token := v_creds->>'api_token';
  
  FOR v_page IN p_start_page..p_end_page LOOP
    v_url := format(
      'https://api.cloudflare.com/client/v4/accounts/%s/images/v1?page=%s&per_page=100&sort_order=asc',
      v_account_id, v_page
    );
    
    SELECT net.http_get(
      url := v_url,
      headers := jsonb_build_object(
        'Authorization', 'Bearer ' || v_token,
        'Content-Type', 'application/json'
      )
    ) INTO v_request_id;
    
    v_request_ids := array_append(v_request_ids, v_request_id);
  END LOOP;
  
  RETURN jsonb_build_object(
    'dispatched_count', array_length(v_request_ids, 1),
    'first_id', v_request_ids[1],
    'last_id', v_request_ids[array_length(v_request_ids, 1)]
  );
END;
$$;


ALTER FUNCTION "public"."fn_cf_collect_sm_legacy_dispatch"("p_start_page" integer, "p_end_page" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cf_collect_sm_legacy_harvest"("p_first_id" bigint, "p_last_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'archive'
    AS $$
DECLARE
  v_total_responses integer;
  v_pending integer;
  v_inserted integer := 0;
BEGIN
  SELECT COUNT(*) INTO v_total_responses 
  FROM net._http_response 
  WHERE id BETWEEN p_first_id AND p_last_id;
  
  v_pending := (p_last_id - p_first_id + 1) - v_total_responses;
  
  WITH responses AS (
    SELECT id, content::jsonb AS body
    FROM net._http_response 
    WHERE id BETWEEN p_first_id AND p_last_id
      AND status_code = 200
  ),
  images_raw AS (
    SELECT 
      img->>'id' AS cf_id,
      img->>'filename' AS filename,
      (img->>'uploaded')::timestamptz AS uploaded_at
    FROM responses r,
         jsonb_array_elements(r.body->'result'->'images') AS img
    WHERE img->>'id' LIKE 'sm-%'
  ),
  inserted AS (
    INSERT INTO cf_sm_legacy (cf_id, filename, uploaded_at)
    SELECT cf_id, filename, uploaded_at FROM images_raw
    ON CONFLICT (cf_id) DO NOTHING
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_inserted FROM inserted;
  
  RETURN jsonb_build_object(
    'responses_received', v_total_responses,
    'pending_responses', v_pending,
    'inserted_this_call', v_inserted,
    'cf_sm_legacy_total_now', (SELECT COUNT(*) FROM cf_sm_legacy)
  );
END;
$$;


ALTER FUNCTION "public"."fn_cf_collect_sm_legacy_harvest"("p_first_id" bigint, "p_last_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cf_recon_collect"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net'
    AS $$
DECLARE n int := 0;
BEGIN
  BEGIN EXECUTE 'SET LOCAL session_replication_role = replica'; EXCEPTION WHEN OTHERS THEN NULL; END;

  WITH resolved AS (
    SELECT q.image_id, r.status_code, r.error_msg,
           CASE WHEN r.status_code IN (200,206) AND r.content IS NOT NULL
                     AND left(btrim(r.content),1)='{'
                THEN r.content::jsonb ELSE NULL END AS body
    FROM public.cf_recon_inflight q
    JOIN net._http_response r ON r.id = q.request_id
  )
  UPDATE public.product_images p SET
    cf_sync_status = CASE
      WHEN res.status_code IN (200,206) THEN 'verified'
      WHEN res.status_code IN (404,410) THEN 'missing'
      ELSE 'failed' END,
    cf_verified_at = now(),
    cf_check_attempts = p.cf_check_attempts + 1,
    cf_last_error = CASE
      WHEN res.status_code IN (200,206,404,410) THEN NULL
      ELSE COALESCE(res.error_msg, 'http_'||COALESCE(res.status_code::text,'timeout')) END,
    cf_uploaded_at = COALESCE((res.body->'result'->>'uploaded')::timestamptz, p.cf_uploaded_at),
    requires_signed_url = COALESCE((res.body->'result'->>'requireSignedURLs')::boolean, p.requires_signed_url)
  FROM resolved res
  WHERE p.id = res.image_id;
  GET DIAGNOSTICS n = ROW_COUNT;

  WITH done AS (
    DELETE FROM public.cf_recon_inflight q
    USING net._http_response r
    WHERE r.id = q.request_id
    RETURNING q.request_id
  )
  DELETE FROM net._http_response WHERE id IN (SELECT request_id FROM done);

  DELETE FROM public.cf_recon_inflight WHERE dispatched_at < now() - interval '15 minutes';
  RETURN n;
END $$;


ALTER FUNCTION "public"."fn_cf_recon_collect"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_cf_recon_collect"() IS 'Processa net._http_response -> cf_sync_status (verified/missing/failed); idempotente.';



CREATE OR REPLACE FUNCTION "public"."fn_cf_recon_dispatch"("p_batch" integer DEFAULT 150) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'vault'
    AS $$
DECLARE r record; n int := 0; rid bigint; _acct text; _tok text; _base text;
BEGIN
  SELECT decrypted_secret INTO _acct FROM vault.decrypted_secrets WHERE name='CF_ACCOUNT_ID' LIMIT 1;
  SELECT decrypted_secret INTO _tok  FROM vault.decrypted_secrets WHERE name='CF_API_TOKEN'  LIMIT 1;
  IF _acct IS NULL OR _tok IS NULL THEN
    RAISE EXCEPTION 'CF_ACCOUNT_ID/CF_API_TOKEN ausentes no vault';
  END IF;
  _base := 'https://api.cloudflare.com/client/v4/accounts/'||_acct||'/images/v1/';

  FOR r IN
    SELECT id, cloudflare_image_id
    FROM public.product_images
    WHERE cf_sync_status IN ('pending','failed')
      AND cf_check_attempts < 5
      AND NOT EXISTS (SELECT 1 FROM public.cf_recon_inflight q WHERE q.image_id = product_images.id)
    ORDER BY is_primary DESC NULLS LAST, is_active DESC NULLS LAST, created_at
    LIMIT p_batch
  LOOP
    rid := net.http_get(url := _base || r.cloudflare_image_id,
                        headers := jsonb_build_object('Authorization','Bearer '||_tok),
                        timeout_milliseconds := 8000);
    INSERT INTO public.cf_recon_inflight(request_id, image_id)
      VALUES (rid, r.id) ON CONFLICT (request_id) DO NOTHING;
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;


ALTER FUNCTION "public"."fn_cf_recon_dispatch"("p_batch" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_cf_recon_dispatch"("p_batch" integer) IS 'Enfileira checagens na CF Images API (token do vault) p/ linhas pending/failed; prioriza primarias.';



CREATE OR REPLACE FUNCTION "public"."fn_cf_sm_legacy_insert_batch"("p_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'archive'
    AS $$
DECLARE
  v_inserted integer;
BEGIN
  INSERT INTO cf_sm_legacy (cf_id, filename, uploaded_at)
  SELECT 
    (elem->>'cf_id')::text,
    (elem->>'filename')::text,
    (elem->>'uploaded_at')::timestamptz
  FROM jsonb_array_elements(p_rows) AS elem
  ON CONFLICT (cf_id) DO NOTHING;
  
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted;
END;
$$;


