CREATE OR REPLACE FUNCTION "public"."fn_check_item_fits"("p_packaging_id" "uuid", "p_product_id" "uuid", "p_current_used_liters" numeric DEFAULT 0) RETURNS TABLE("fits" boolean, "packaging_volume" numeric, "product_volume" numeric, "used_volume" numeric, "available_volume" numeric, "percentage_used" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE v_pkg NUMERIC; v_prod NUMERIC; v_avail NUMERIC; v_has_dims BOOLEAN;
BEGIN
  SELECT ((COALESCE(p.internal_length_cm,0)*COALESCE(p.internal_width_cm,0)*COALESCE(p.internal_height_cm,0))/1000)::NUMERIC
  INTO v_pkg FROM products p WHERE p.id=p_packaging_id AND p.product_type='packaging';
  SELECT (CASE
      WHEN p.length_cm IS NOT NULL AND p.width_cm IS NOT NULL AND p.height_cm IS NOT NULL THEN (p.length_cm*p.width_cm*p.height_cm)/1000
      WHEN p.diameter_cm IS NOT NULL AND p.height_cm IS NOT NULL THEN (PI()*POWER(p.diameter_cm/2,2)*p.height_cm)/1000
      WHEN p.is_kit THEN (SELECT SUM(COALESCE(pkc.quantity,1)*CASE
            WHEN pkc.shape_type='cylindrical' AND pkc.diameter_mm IS NOT NULL AND pkc.height_mm IS NOT NULL THEN PI()*POWER(pkc.diameter_mm/20.0,2)*(pkc.height_mm/10.0)
            WHEN pkc.length_mm IS NOT NULL AND pkc.width_mm IS NOT NULL AND pkc.height_mm IS NOT NULL THEN (pkc.length_mm/10.0)*(pkc.width_mm/10.0)*(pkc.height_mm/10.0)
            WHEN pkc.shape_type='flat' AND pkc.length_mm IS NOT NULL AND pkc.width_mm IS NOT NULL THEN (pkc.length_mm/10.0)*(pkc.width_mm/10.0)*0.8
            ELSE 0 END)/1000 FROM product_kit_components pkc WHERE pkc.kit_product_id=p.id AND pkc.is_packaging=FALSE)
      ELSE NULL END)::NUMERIC,
    (p.length_cm IS NOT NULL OR p.diameter_cm IS NOT NULL OR p.is_kit)
  INTO v_prod, v_has_dims FROM products p WHERE p.id=p_product_id;
  v_avail := v_pkg - p_current_used_liters;
  RETURN QUERY SELECT CASE WHEN v_prod IS NULL OR NOT COALESCE(v_has_dims,FALSE) THEN NULL ELSE (v_prod <= v_avail) END,
    ROUND(v_pkg,2), ROUND(v_prod,4), p_current_used_liters, ROUND(v_avail,2), ROUND((p_current_used_liters/NULLIF(v_pkg,0))*100,1);
END;$$;


ALTER FUNCTION "public"."fn_check_item_fits"("p_packaging_id" "uuid", "p_product_id" "uuid", "p_current_used_liters" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_check_item_fits"("p_packaging_id" "uuid", "p_product_id" "uuid", "p_current_used_liters" numeric) IS 'Verifica se produto cabe na embalagem';



CREATE OR REPLACE FUNCTION "public"."fn_check_login_allowed"("p_email" "text", "p_ip_address" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS TABLE("allowed" boolean, "reason" "text", "blocked_until" timestamp with time zone, "check_details" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  _s              RECORD;
  _failed_count   INT   := 0;
  _last_failure   TIMESTAMPTZ;
  _last_success   TIMESTAMPTZ;
  _lockout_until  TIMESTAMPTZ;
  _details        JSONB := '{}'::JSONB;
  _ip_safe        TEXT;
BEGIN
  _ip_safe := COALESCE(p_ip_address, 'unknown');

  IF p_email IS NULL OR length(trim(p_email)) = 0 THEN
    RETURN QUERY SELECT false, 'invalid_email'::TEXT,
      NULL::TIMESTAMPTZ, '{}'::JSONB;
    RETURN;
  END IF;
  p_email := lower(trim(p_email));

  SELECT * INTO _s FROM public.access_security_settings LIMIT 1;
  IF NOT FOUND THEN
    _s.ip_whitelist_enabled     := false;
    _s.city_whitelist_enabled   := false;
    _s.block_unknown_locations  := false;
    _s.max_failed_attempts      := 5;
    _s.lockout_duration_minutes := 30;
    _s.strict_access_mode       := false;
    _details := _details || '{"settings_source":"defaults"}'::JSONB;
  ELSE
    _details := _details || '{"settings_source":"db"}'::JSONB;
  END IF;

  _s.max_failed_attempts      := GREATEST(COALESCE(_s.max_failed_attempts, 5), 1);
  _s.lockout_duration_minutes := GREATEST(COALESCE(_s.lockout_duration_minutes, 30), 1);

  IF _s.ip_whitelist_enabled THEN
    IF p_ip_address IS NULL THEN
      _details := _details || '{"ip_check":"blocked_null_ip"}'::JSONB;
      BEGIN
        INSERT INTO public.access_blocked_log
          (email, ip_address, city, block_reason, user_agent)
        VALUES (p_email, 'unknown', p_city, 'ip_unknown_blocked', p_user_agent);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
      RETURN QUERY SELECT false, 'ip_unknown_blocked'::TEXT,
        NULL::TIMESTAMPTZ, _details;
      RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM public.ip_whitelist WHERE is_active = true LIMIT 1) THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.ip_whitelist
        WHERE ip_address = p_ip_address AND is_active = true
      ) THEN
        _details := _details
          || jsonb_build_object('ip_check','blocked','ip',p_ip_address);
        BEGIN
          INSERT INTO public.access_blocked_log
            (email, ip_address, city, block_reason, user_agent)
          VALUES (p_email, _ip_safe, p_city, 'ip_not_whitelisted', p_user_agent);
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        RETURN QUERY SELECT false, 'ip_not_whitelisted'::TEXT,
          NULL::TIMESTAMPTZ, _details;
        RETURN;
      END IF;
      _details := _details || '{"ip_check":"allowed"}'::JSONB;
    ELSE
      _details := _details || '{"ip_check":"skipped_empty_whitelist"}'::JSONB;
    END IF;
  ELSE
    _details := _details || '{"ip_check":"disabled"}'::JSONB;
  END IF;

  IF _s.city_whitelist_enabled THEN
    IF p_city IS NULL THEN
      _details := _details || '{"city_check":"blocked_null_city"}'::JSONB;
      BEGIN
        INSERT INTO public.access_blocked_log
          (email, ip_address, city, block_reason, user_agent)
        VALUES (p_email, _ip_safe, NULL, 'city_unknown_blocked', p_user_agent);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
      RETURN QUERY SELECT false, 'city_unknown_blocked'::TEXT,
        NULL::TIMESTAMPTZ, _details;
      RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM public.city_whitelist WHERE is_active = true LIMIT 1) THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.city_whitelist
        WHERE upper(city_name) = upper(p_city) AND is_active = true
      ) THEN
        _details := _details
          || jsonb_build_object('city_check','blocked','city',p_city);
        BEGIN
          INSERT INTO public.access_blocked_log
            (email, ip_address, city, block_reason, user_agent)
          VALUES (p_email, _ip_safe, p_city, 'city_not_whitelisted', p_user_agent);
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        RETURN QUERY SELECT false, 'city_not_whitelisted'::TEXT,
          NULL::TIMESTAMPTZ, _details;
        RETURN;
      END IF;
      _details := _details || '{"city_check":"allowed"}'::JSONB;
    ELSE
      _details := _details || '{"city_check":"skipped_empty_whitelist"}'::JSONB;
    END IF;
  ELSE
    _details := _details || '{"city_check":"disabled"}'::JSONB;
  END IF;

  SELECT max(created_at) INTO _last_success
  FROM public.login_attempts
  WHERE email = p_email AND success = true;

  SELECT count(*), max(created_at)
    INTO _failed_count, _last_failure
  FROM public.login_attempts
  WHERE email = p_email
    AND success = false
    AND created_at > now()
        - (_s.lockout_duration_minutes || ' minutes')::interval
    AND (_last_success IS NULL OR created_at > _last_success);

  _details := _details || jsonb_build_object(
    'failed_attempts',   _failed_count,
    'max_allowed',       _s.max_failed_attempts,
    'window_minutes',    _s.lockout_duration_minutes
  );

  IF _failed_count >= _s.max_failed_attempts AND _last_failure IS NOT NULL THEN
    _lockout_until := _last_failure
      + (_s.lockout_duration_minutes || ' minutes')::interval;
    IF _lockout_until > now() THEN
      _details := _details
        || jsonb_build_object('lockout_until', _lockout_until);
      BEGIN
        INSERT INTO public.access_blocked_log
          (email, ip_address, city, block_reason, user_agent)
        VALUES (p_email, _ip_safe, p_city,
                'too_many_failed_attempts', p_user_agent);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
      RETURN QUERY SELECT false, 'too_many_failed_attempts'::TEXT,
        _lockout_until, _details;
      RETURN;
    END IF;
  END IF;

  _details := _details || '{"result":"all_checks_passed"}'::JSONB;
  RETURN QUERY SELECT true, 'allowed'::TEXT, NULL::TIMESTAMPTZ, _details;

EXCEPTION WHEN OTHERS THEN
  RETURN QUERY SELECT false, 'security_check_error_fail_closed'::TEXT,
    NULL::TIMESTAMPTZ, '{}'::JSONB;
END;
$$;


ALTER FUNCTION "public"."fn_check_login_allowed"("p_email" "text", "p_ip_address" "text", "p_city" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_check_preco_minimo_faixa"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_minimo NUMERIC;
  v_codigo TEXT;
BEGIN
  SELECT preco_minimo_unitario, codigo_tabela 
  INTO v_minimo, v_codigo
  FROM tabela_preco_gravacao_oficial
  WHERE id = NEW.tabela_preco_gravacao_id;

  -- Se mínimo é NULL, ignorar check (compatibilidade com tabelas antigas)
  IF v_minimo IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.preco_unitario < v_minimo THEN
    RAISE EXCEPTION 
      'Preço unitário (R$ %) abaixo do mínimo da tabela % (R$ %). Para cadastrar este valor, ajuste preco_minimo_unitario na tabela-mãe primeiro ou revise se este preço está correto.',
      NEW.preco_unitario, v_codigo, v_minimo
      USING HINT = 'UPDATE tabela_preco_gravacao_oficial SET preco_minimo_unitario = ' || NEW.preco_unitario || ' WHERE codigo_tabela = ' || quote_literal(v_codigo);
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."fn_check_preco_minimo_faixa"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_check_preco_minimo_faixa"() IS 'Previne cadastro de faixa com preço abaixo do mínimo declarado na tabela-mãe (semantica oficial após PAD-02).';



CREATE OR REPLACE FUNCTION "public"."fn_check_rowtype_staleness"() RETURNS TABLE("funcao" "text", "tabela_referenciada" "text", "coluna_usada" "text", "status" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH funcoes_com_rowtype AS (
    SELECT p.proname AS fname, p.prosrc AS fsrc
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prolang = (SELECT oid FROM pg_language WHERE lanname = 'plpgsql')
      AND p.prosrc ILIKE '%produtos_padronizacao%ROWTYPE%'
      AND p.proname NOT ILIKE '%check_rowtype%'
  ),
  colunas_silver AS (
    SELECT column_name FROM information_schema.columns
    WHERE table_name = 'produtos_padronizacao' AND table_schema = 'public'
      AND column_name IN (
        'diameter_cm','circumference_cm','combined_sizes','supplier_type','supplier_subtype',
        'dimensions_display','box_volume_cm3','is_textil','capacity_ml','box_quantity',
        'box_inner_quantity','ipi_rate','engraving_type','colors','brand',
        'packing_type','repacking_type','capacities','box_image'
      )
  )
  SELECT 
    f.fname,
    'produtos_padronizacao'::text,
    c.column_name,
    CASE WHEN f.fsrc ILIKE ('%s.' || c.column_name || '%')
         THEN '✅ OK — função acessa e compila corretamente'
         ELSE '📋 INFO — coluna não copiada por esta função (normal)'
    END AS status
  FROM funcoes_com_rowtype f
  CROSS JOIN colunas_silver c
  ORDER BY f.fname, status DESC, c.column_name;
$$;


ALTER FUNCTION "public"."fn_check_rowtype_staleness"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_check_schema_signature_drift"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_added jsonb := '{}'::jsonb; v_removed jsonb := '{}'::jsonb; v_retyped jsonb := '{}'::jsonb;
  v_tadded text[]; v_tremoved text[];
  v_n_add int; v_n_rem int; v_n_ret int;
  v_has_drift boolean; v_label text; v_log_id uuid;
BEGIN
  -- fix_version: schema_drift_local_guard_v4 (idempotente intra-transacao: DROP IF EXISTS
  --   das TEMP TABLEs _live/_diff; ON COMMIT DROP so limpa no commit, entao 2 chamadas na
  --   mesma transacao colidiam com 42P07 relation "_live" already exists)
  DROP TABLE IF EXISTS _live;
  DROP TABLE IF EXISTS _diff;
  SELECT baseline_label INTO v_label FROM public.schema_signature_baseline LIMIT 1;
  CREATE TEMP TABLE _live ON COMMIT DROP AS
    SELECT table_name, column_name, data_type FROM information_schema.columns
    WHERE table_schema='public' AND table_name NOT LIKE 'pg_%' AND table_name NOT LIKE '_backup_%';
  CREATE TEMP TABLE _diff ON COMMIT DROP AS
    SELECT COALESCE(b.table_name,l.table_name) AS table_name, COALESCE(b.column_name,l.column_name) AS column_name,
      b.data_type AS base_type, l.data_type AS live_type,
      CASE WHEN b.column_name IS NULL THEN 'added' WHEN l.column_name IS NULL THEN 'removed'
           WHEN b.data_type IS DISTINCT FROM l.data_type THEN 'retyped' ELSE 'same' END AS verdict
    FROM public.schema_signature_baseline b
    FULL OUTER JOIN _live l ON b.table_name=l.table_name AND b.column_name=l.column_name;
  DELETE FROM _diff d USING public.schema_signature_drift_allowlist a
   WHERE d.table_name=a.table_name AND (a.column_name IS NULL OR a.column_name=d.column_name);
  SELECT array_agg(t ORDER BY t) INTO v_tadded FROM (
    SELECT DISTINCT table_name t FROM _live EXCEPT SELECT DISTINCT table_name FROM public.schema_signature_baseline
  ) x WHERE t NOT IN (SELECT table_name FROM public.schema_signature_drift_allowlist WHERE column_name IS NULL);
  SELECT array_agg(t ORDER BY t) INTO v_tremoved FROM (
    SELECT DISTINCT table_name t FROM public.schema_signature_baseline EXCEPT SELECT DISTINCT table_name FROM _live
  ) x WHERE t NOT IN (SELECT table_name FROM public.schema_signature_drift_allowlist WHERE column_name IS NULL);
  v_tadded := COALESCE(v_tadded,'{}'); v_tremoved := COALESCE(v_tremoved,'{}');
  SELECT COALESCE(jsonb_object_agg(table_name,cols),'{}'::jsonb) INTO v_added
   FROM (SELECT table_name, jsonb_agg(column_name ORDER BY column_name) cols FROM _diff WHERE verdict='added' GROUP BY table_name) s;
  SELECT COALESCE(jsonb_object_agg(table_name,cols),'{}'::jsonb) INTO v_removed
   FROM (SELECT table_name, jsonb_agg(column_name ORDER BY column_name) cols FROM _diff WHERE verdict='removed' GROUP BY table_name) s;
  SELECT COALESCE(jsonb_object_agg(table_name,cols),'{}'::jsonb) INTO v_retyped
   FROM (SELECT table_name, jsonb_agg(jsonb_build_object('column',column_name,'from',base_type,'to',live_type) ORDER BY column_name) cols FROM _diff WHERE verdict='retyped' GROUP BY table_name) s;
  SELECT count(*) FILTER (WHERE verdict='added'), count(*) FILTER (WHERE verdict='removed'), count(*) FILTER (WHERE verdict='retyped')
    INTO v_n_add, v_n_rem, v_n_ret FROM _diff;
  v_has_drift := (COALESCE(v_n_add,0)+COALESCE(v_n_rem,0)+COALESCE(v_n_ret,0))>0 OR cardinality(v_tadded)>0 OR cardinality(v_tremoved)>0;
  INSERT INTO public.schema_signature_drift_log
    (has_drift,n_added,n_removed,n_retyped,columns_added,columns_removed,columns_retyped,tables_added,tables_removed,baseline_label)
  VALUES (v_has_drift,v_n_add,v_n_rem,v_n_ret,v_added,v_removed,v_retyped,v_tadded,v_tremoved,v_label)
  RETURNING id INTO v_log_id;
  RETURN jsonb_build_object('ok',true,'has_drift',v_has_drift,'log_id',v_log_id,'baseline_label',v_label,
    'n_added',v_n_add,'n_removed',v_n_rem,'n_retyped',v_n_ret,
    'columns_added',v_added,'columns_removed',v_removed,'columns_retyped',v_retyped,
    'tables_added',to_jsonb(v_tadded),'tables_removed',to_jsonb(v_tremoved));
END;
$$;


ALTER FUNCTION "public"."fn_check_schema_signature_drift"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_circumference_to_diameter"("p_circumference" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public', 'extensions'
    AS $$ SELECT CASE WHEN p_circumference IS NULL OR p_circumference <= 0 THEN NULL
              ELSE round(p_circumference / pi()::numeric, 2) END $$;


ALTER FUNCTION "public"."fn_circumference_to_diameter"("p_circumference" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_circumference_to_diameter"("p_circumference" numeric) IS 'Converte circunferência em diâmetro (÷π), mesma unidade de entrada.
 Uso: normalização prata de fornecedores que informam circunferência (ex.: XBZ site/scraping — garrafa 02429A: 21,1cm → 6,72cm).
 Retorna NULL para entrada nula/não-positiva.';



CREATE OR REPLACE FUNCTION "public"."fn_classify_category_residual"("p_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  n text := lower(COALESCE(p_name,''));
  v_id uuid;
BEGIN
  IF n = '' THEN RETURN NULL; END IF;

  -- som / áudio
  IF n ~ 'caixa de som|caixa som|speaker' THEN
    SELECT id INTO v_id FROM categories WHERE slug='caixa-de-som' LIMIT 1; RETURN v_id;
  END IF;

  -- mouse pad
  IF n ~ 'mouse ?pad' THEN
    IF n ~ 'ergon[ôo]mico' THEN SELECT id INTO v_id FROM categories WHERE slug='mouse_pad_espuma_ergonomico' LIMIT 1; END IF;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='mouse_pad' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- churrasco
  IF n ~ 'churrasqueira|churrasco' THEN
    IF n ~ '\mkit\M' THEN SELECT id INTO v_id FROM categories WHERE slug='kit_churrasco' LIMIT 1; END IF;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='churrasco' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- kits específicos
  IF n ~ '\mkit\M' AND n ~ 'drink|coquetel' THEN
    SELECT id INTO v_id FROM categories WHERE slug='kit-drink' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ '\mkit\M' AND n ~ 'executivo' THEN
    SELECT id INTO v_id FROM categories WHERE slug='kit_executivo' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'talher' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bar_e_cozinha' LIMIT 1; RETURN v_id;
  END IF;

  -- utilidades / casa
  IF n ~ 'umidificador|aromatizador' THEN
    SELECT id INTO v_id FROM categories WHERE slug='ferramentas-utilidades' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'frasqueira' THEN
    SELECT id INTO v_id FROM categories WHERE slug='frasqueiras' LIMIT 1; RETURN v_id;
  END IF;

  -- pet
  IF n ~ 'bebedouro|comedouro' AND n ~ '\mpet|cachorro|gato' THEN
    SELECT id INTO v_id FROM categories WHERE slug='brinquedos_pet' LIMIT 1; RETURN v_id;
  END IF;

  -- chapéus
  IF n ~ 'chap[ée]u' THEN
    IF n ~ 'ecoflex' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_ecoflex' LIMIT 1;
    ELSIF n ~ 'juta' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_juta' LIMIT 1;
    ELSIF n ~ 'palha' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_palha' LIMIT 1;
    ELSIF n ~ 'bucket' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu-bucket' LIMIT 1;
    END IF;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='chapeus' OR name='Chapéus' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- cadernos / cadernetas / blocos
  IF n ~ 'caderno|caderneta|bloco de anota' THEN
    SELECT id INTO v_id FROM categories WHERE slug='cadernetas-cadernos' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE name ILIKE 'caderno%' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- marmitas
  IF n ~ 'marmita' THEN
    SELECT id INTO v_id FROM categories WHERE name ILIKE 'marmit%' OR slug ILIKE 'marmit%' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='bar_e_cozinha' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- malas e bolsas
  IF n ~ '\mmala\M' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsas_de_viagem' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'bolsa t[ée]rmica' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsa_termica' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ '\mbolsa\M' AND n ~ 'esport|viagem|mochila' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsas_de_viagem' LIMIT 1; RETURN v_id;
  END IF;

  -- brinquedos / antiestresse
  IF n ~ 'brinquedo' AND n ~ '\mpet\M|cachorro|gato' THEN
    SELECT id INTO v_id FROM categories WHERE slug='brinquedos_pet' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'antiestresse|anti-estresse|anti estresse|apert[áa]vel|brinquedo' THEN
    SELECT id INTO v_id FROM categories WHERE slug='jogos_e_brinquedos' LIMIT 1; RETURN v_id;
  END IF;

  -- escritório / pastas
  IF n ~ 'pasta|escrit[óo]rio|porta document' THEN
    SELECT id INTO v_id FROM categories WHERE slug ILIKE 'escritorio%' OR name ILIKE 'escritório%' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='acessorios' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_classify_category_residual"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_classify_packing_type"("p_packing_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE v_n TEXT;
BEGIN
    IF p_packing_type IS NULL OR TRIM(p_packing_type) = '' THEN
        RETURN jsonb_build_object('raw',p_packing_type,'classification','none',
            'is_commercial',FALSE,'is_protective',FALSE,'can_be_customized',FALSE,'has_image_expected',FALSE);
    END IF;
    v_n := LOWER(TRIM(p_packing_type));

    -- PRÉ-CHECK A: Polybag
    IF (v_n ~ 'polybag|poly[- ]bag')
       AND NOT (v_n ~ '(caixa|estojo|maleta|kraft|tnt|non-woven|bolsa|saco de|sacola de)') THEN
        RETURN jsonb_build_object('raw',p_packing_type,'classification','protective',
            'is_commercial',FALSE,'is_protective',TRUE,'can_be_customized',FALSE,'has_image_expected',FALSE);
    END IF;

    -- PRÉ-CHECK B: "Sem polybag/packing"
    IF v_n ~ '^sem polybag' OR v_n ~ '^sem packing' THEN
        RETURN jsonb_build_object('raw',p_packing_type,'classification','protective',
            'is_commercial',FALSE,'is_protective',TRUE,'can_be_customized',FALSE,'has_image_expected',FALSE);
    END IF;

    -- PRÉ-CHECK C: "Plástic[ao] (lote/qtd/mochila)" → protective
    -- Excluir somente quando "sacola" está nos parênteses (aquela = commercial bag/gift)
    IF  v_n ~ '^plástic[ao]\s+(embalad|de\s+\d)'
     OR (v_n ~ '^plástic[ao]\s*\(' AND v_n !~ 'sacola') THEN
        RETURN jsonb_build_object('raw',p_packing_type,'classification','protective',
            'is_commercial',FALSE,'is_protective',TRUE,'can_be_customized',FALSE,'has_image_expected',FALSE);
    END IF;

    -- COMMERCIAL
    IF  v_n ~ '(caixa|box|caixinha)'
     OR v_n ~ '(kraft|cartonagem|cartão|cartao|carton)'
     OR v_n ~ '(bolsa|\ybag\y|sacola|saco de algodão|saco de algodao)'
     OR v_n ~ '(tnt|non-woven|non woven|nonwoven)'
     OR v_n ~ '(estojo|case|pouch|pochete)'
     OR v_n ~ '(maleta|mala|porta-)'
     OR v_n ~ '(sleeve|luva|manga craft|manga branca|manga preta|manga de cortiça|manga de cortica|manga kraft|manga cartão|manga cartao|manga de papel|manga de bambu)'
     OR v_n ~ '(presente|gift|oferta|luxo|premium)'
     OR v_n ~ '(veludo|velvet|madeira|wood|bambu|bamboo|bambu print)'
     OR v_n ~ '(lata|tin|metal[^ó]|metálica|alumínio|aluminio)'
     OR v_n ~ '(acrílico|acrilico|acrylic)'
     OR v_n ~ '(couro|leather|^pu$|courino)'
     OR v_n ~ '(berço|berco|espuma|eva)'
     OR v_n ~ '(blister)'
     OR v_n ~ '(saco de algodão|saco algodão|saco algodao)'
     OR v_n ~ 'embalados na sacola|embalados no kit|embalada na sacola'
    THEN
        RETURN jsonb_build_object('raw',p_packing_type,'classification','commercial',
            'is_commercial',TRUE,'is_protective',FALSE,'can_be_customized',TRUE,'has_image_expected',TRUE);

    -- PROTECTIVE
    ELSIF v_n ~ '(saquinho|saco plástico|saco plastico)'
       OR v_n ~ '(película|pelicula|plástico bolha|plastico bolha|plástica bolha)'
       OR v_n ~ '(filme|shrink|stretch|celofane|cello)'
       OR v_n ~ '(bolha|bubble|aderente)'
       OR v_n ~ '(plástico em vácuo|plastico em vacuo|em vácuo|em vacuo)'
       OR v_n ~ '(papel seda|manga plástico|manga plastico)'
       OR v_n ~ '(tabuleiro de plástico|tabuleiro)'
       OR v_n ~ '(zip lock|ziplock|zip-lock|fecho adesivo|fecho c/|c/ fecho)'
       OR v_n ~ '(plástico vedado|plástica vedada|plastico vedado|plastica vedada|vedado)'
       OR v_n ~ '^plástic[ao]\.?\s*$'
       OR v_n ~ '^plastic[ao]\.?\s*$'
       OR v_n ~ '^plástic\s*$'
       OR (v_n ~ '^saco plástico' AND v_n !~ '(algodão|algodao|tnt|non-woven|veludo|kraft|papel de|cartão|cartao)')
       OR v_n ~ '^embalagem plástica( individual)?\.?$'
       OR v_n ~ '^(sem |nenhum|nenhuma|n\/a|sem embalagem|sem embagem|a granel)'
       OR v_n IN ('sem','nenhum','nenhuma','n/a','a granel')
       OR v_n ~ '(película retrátil|pelicula retratil|manga plástica$|manga plastica$)'
    THEN
        RETURN jsonb_build_object('raw',p_packing_type,'classification','protective',
            'is_commercial',FALSE,'is_protective',TRUE,'can_be_customized',FALSE,'has_image_expected',FALSE);
    ELSE
        RETURN jsonb_build_object('raw',p_packing_type,'classification','unknown',
            'is_commercial',FALSE,'is_protective',FALSE,'can_be_customized',FALSE,'has_image_expected',FALSE);
    END IF;
END;
$_$;


ALTER FUNCTION "public"."fn_classify_packing_type"("p_packing_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_classify_packing_type"("p_packing_type" "text") IS 'Classifica o tipo de embalagem (packing_type) em:
- protective: embalagens de proteção (polybag, película, etc.) - NÃO agrega valor
- commercial: embalagens comerciais/presente (caixa, bolsa, estojo) - AGREGA valor
- none: sem embalagem ou valor vazio
- unknown: não foi possível classificar

IMPORTANTE: Polybag = PROTECTIVE (não é embalagem comercial conforme RN03)

Corrigido em 22/01/2026 após análise exaustiva.';



CREATE OR REPLACE FUNCTION "public"."fn_classify_spot_image"("p_filename" "text") RETURNS TABLE("image_type" "text", "image_type_id" "uuid", "is_color_specific" boolean, "is_primary_image" boolean, "display_order_hint" integer, "color_code" "text", "prod_reference" "text")
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_base TEXT;
    v_color TEXT;
    v_suffix TEXT;
BEGIN
    -- Remove extensão
    v_base := SPLIT_PART(p_filename, '.', 1);
    
    -- Detectar padrões de vitrine (sem cor): {ref}-vp, {ref}-va, {ref}-vp-#, {ref}-va-#
    IF v_base ~ '^[0-9]+-v[pa]' THEN
        prod_reference := SPLIT_PART(v_base, '-', 1);
        color_code := NULL;
        is_color_specific := false;
        is_primary_image := false;
        
        IF v_base ~ '-vp' THEN
            image_type := 'vitrine_pessoa';
            image_type_id := '03426962-2d59-483a-a157-3f6a4a5c6a77';
            display_order_hint := 80;
        ELSE
            image_type := 'vitrine_ambiente';
            image_type_id := '57780389-64ce-4945-b7ca-ed22ef73caa9';
            display_order_hint := 81;
        END IF;
        RETURN NEXT;
        RETURN;
    END IF;
    
    -- Padrões com cor: {ref}_{cor}[-sufixo]
    IF v_base ~ '^[0-9]+_[0-9]+' THEN
        prod_reference := SPLIT_PART(v_base, '_', 1);
        -- Extrair cor (parte após _ e antes do primeiro -)
        v_color := SPLIT_PART(SPLIT_PART(v_base, '_', 2), '-', 1);
        color_code := v_color;
        
        -- Extrair sufixo (parte após {ref}_{cor})
        v_suffix := SUBSTRING(v_base FROM '^[0-9]+_[0-9]+(.*)$');
        
        CASE v_suffix
            -- Sem sufixo = imagem principal
            WHEN '' THEN
                image_type := 'main';
                image_type_id := '7ea182ff-edcc-4c4c-b7a1-443b07500f6c';
                is_color_specific := true;
                is_primary_image := true;
                display_order_hint := 1;
            
            -- Vistas alternativas
            WHEN '-b' THEN
                image_type := 'gallery';
                image_type_id := '1590e144-e3f8-41e6-98f9-f4a25bae496d';
                is_color_specific := true;
                is_primary_image := false;
                display_order_hint := 10;
            WHEN '-c' THEN
                image_type := 'gallery';
                image_type_id := '1590e144-e3f8-41e6-98f9-f4a25bae496d';
                is_color_specific := true;
                is_primary_image := false;
                display_order_hint := 11;
            WHEN '-d' THEN
                image_type := 'gallery';
                image_type_id := '1590e144-e3f8-41e6-98f9-f4a25bae496d';
                is_color_specific := true;
                is_primary_image := false;
                display_order_hint := 12;
            WHEN '-e' THEN
                image_type := 'gallery';
                image_type_id := '1590e144-e3f8-41e6-98f9-f4a25bae496d';
                is_color_specific := true;
                is_primary_image := false;
                display_order_hint := 13;
            
            -- Logo/gravação
            WHEN '-logo' THEN
                image_type := 'logo';
                image_type_id := '2d5aca72-6eb9-4b16-906d-8e0f91c9bf40';
                is_color_specific := true;
                is_primary_image := false;
                display_order_hint := 30;
            
            -- SET (todas as cores)
            WHEN '-set' THEN
                image_type := 'set';
                image_type_id := 'c305d8b3-9af8-469e-aea5-88208def353f';
                is_color_specific := true;  -- vinculado à cor na URL
                is_primary_image := false;
                display_order_hint := 50;
            
            -- Embalagem
            WHEN '-box' THEN
                image_type := 'box';
                image_type_id := 'f980378d-3ac5-4525-8941-52715f3e320f';
                is_color_specific := false;
                is_primary_image := false;
                display_order_hint := 60;
            WHEN '-pouch' THEN
                image_type := 'pouch';
                image_type_id := '9da408a0-21bd-4b45-b7f5-4ad5f29822da';
                is_color_specific := false;
                is_primary_image := false;
                display_order_hint := 61;
            WHEN '-bag' THEN
                image_type := 'bag';
                image_type_id := '196e69a9-6962-4494-8919-ee1d2737e6e7';
                is_color_specific := false;
                is_primary_image := false;
                display_order_hint := 62;
            
            -- Vitrines por cor
            WHEN '-vp' THEN
                image_type := 'vitrine_pessoa';
                image_type_id := '03426962-2d59-483a-a157-3f6a4a5c6a77';
                is_color_specific := true;
                is_primary_image := false;
                display_order_hint := 80;
            WHEN '-va' THEN
                image_type := 'vitrine_ambiente';
                image_type_id := '57780389-64ce-4945-b7ca-ed22ef73caa9';
                is_color_specific := true;
                is_primary_image := false;
                display_order_hint := 81;
            
            -- Sufixo desconhecido → gallery
            ELSE
                image_type := 'gallery';
                image_type_id := '1590e144-e3f8-41e6-98f9-f4a25bae496d';
                is_color_specific := true;
                is_primary_image := false;
                display_order_hint := 20;
        END CASE;
        
        RETURN NEXT;
        RETURN;
    END IF;
    
    -- Fallback: não reconhecido
    prod_reference := NULL;
    color_code := NULL;
    image_type := 'other';
    image_type_id := '953d054a-3bbc-4954-a319-b3c806ac596f';
    is_color_specific := false;
    is_primary_image := false;
    display_order_hint := 99;
    RETURN NEXT;
    RETURN;
END;
$_$;


ALTER FUNCTION "public"."fn_classify_spot_image"("p_filename" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_classify_spot_image"("p_filename" "text") IS 'Classifica um filename de imagem SPOT/Stricker e retorna o tipo semântico interno.
Função utilitária — não é um trigger, pode ser chamada diretamente para debug.

COMO FUNCIONA:
  Analisa o filename via regex e retorna via OUT params:
    prod_reference    → referência do produto no SPOT (ex: "94053")
    color_code        → código de cor do SPOT (ex: "119") — NULL se imagem genérica
    image_type        → code do tipo interno (gallery, main, set, vitrine_pessoa...)
    image_type_id     → UUID do tipo em image_types
    is_color_specific → se TRUE, imagem é específica de uma cor
    is_primary_image  → se TRUE, deve ser is_primary=true em product_images
    display_order_hint→ sugestão de display_order (menor = aparece primeiro)

PADRÕES RECONHECIDOS (Stricker/SPOT):
  {ref}-vp, {ref}-vp-#   → vitrine_pessoa (mockup com pessoa)
  {ref}-va, {ref}-va-#   → vitrine_ambiente (mockup ambiente)
  {ref}_{cor}_1          → product (foto principal da cor — candidata a primary)
  {ref}_{cor}_2..N       → gallery (ângulos extras da cor)
  {ref}_set              → set (todas as cores juntas)
  {ref}_amb              → ambient (lifestyle sem cor)
  {ref}_det              → detail (close-up)
  {ref}_logo             → logo (com logotipo aplicado)
  {ref}_box, _pouch, _bag→ packaging
  {ref}_{cor}            → product (fallback: cor sem número de ordem)

COMO USAR PARA DEBUG:
  SELECT * FROM fn_classify_spot_image(''94053-119-1-1-1.jpg'');
  SELECT * FROM fn_classify_spot_image(''94053-119-1-1-2.jpg'');
  -- Retorna classificação sem escrever nada no banco

COM QUEM CONVIVE:
  Usada por fn_import_spot_image, fn_classify_spot_image callers no pipeline SPOT.
  Análoga ao comportamento de fn_auto_classify_product_image para o supplier SPOT.';



CREATE OR REPLACE FUNCTION "public"."fn_classify_spot_image_v3"("p_filename" "text", "p_main_image" "text" DEFAULT NULL::"text") RETURNS TABLE("image_type" "text", "color_code" "text", "is_primary" boolean, "display_order" integer, "is_color_specific" boolean, "spot_ref" "text", "image_type_id" "uuid")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_base TEXT;
  v_ext TEXT;
  v_is_primary BOOLEAN;
  v_parts TEXT[];
  v_ref TEXT;
  v_cor TEXT;
  v_suffix TEXT;
  v_suffix_lower TEXT;
  v_suffix_parts TEXT[];
  v_angle TEXT;
  v_order_map JSONB := '{"a":10,"b":11,"c":12,"d":13,"e":14,"f":15,"g":16}'::jsonb;
  v_letter TEXT;
  -- UUIDs
  UUID_MAIN     UUID := '7ea182ff-edcc-4c4c-b7a1-443b07500f6c';
  UUID_GALLERY  UUID := '1590e144-e3f8-41e6-98f9-f4a25bae496d';
  UUID_SET      UUID := 'c305d8b3-9af8-469e-aea5-88208def353f';
  UUID_LOGO     UUID := '2d5aca72-6eb9-4b16-906d-8e0f91c9bf40';
  UUID_AMBIENT  UUID := 'e8bf8d1f-b6f5-47c1-953b-616d354318a6';
  UUID_VP       UUID := '03426962-2d59-483a-a157-3f6a4a5c6a77';
  UUID_VA       UUID := '57780389-64ce-4945-b7ca-ed22ef73caa9';
  UUID_BOX      UUID := 'f980378d-3ac5-4525-8941-52715f3e320f';
  UUID_POUCH    UUID := '9da408a0-21bd-4b45-b7f5-4ad5f29822da';
  UUID_BAG      UUID := '196e69a9-6962-4494-8919-ee1d2737e6e7';
BEGIN
  -- Preparar
  v_base := regexp_replace(p_filename, '\.[^.]+$', '');
  v_ext  := lower(regexp_replace(p_filename, '.*\.', ''));
  v_is_primary := (p_filename = p_main_image);

  -- ══════════════════════════════════════════════
  -- GRUPO A: Padrões genéricos (sem cor numérica)
  -- ══════════════════════════════════════════════

  -- A1: REF_set.jpg (1.163 ocorrências)
  IF v_base ~ '^\d+_set$' THEN
    v_ref := regexp_replace(v_base, '_set$', '');
    RETURN QUERY SELECT 'set'::TEXT, NULL::TEXT, v_is_primary, 5, FALSE, v_ref, UUID_SET;
    RETURN;
  END IF;

  -- A2: REF_amb.jpg (526 ocorrências)
  IF v_base ~ '^\d+_amb$' THEN
    v_ref := regexp_replace(v_base, '_amb$', '');
    RETURN QUERY SELECT 'ambient'::TEXT, NULL::TEXT, v_is_primary, 6, FALSE, v_ref, UUID_AMBIENT;
    RETURN;
  END IF;

  -- A3: REF_box.jpg (148 ocorrências)
  IF v_base ~ '^\d+_box$' THEN
    v_ref := regexp_replace(v_base, '_box$', '');
    RETURN QUERY SELECT 'box'::TEXT, NULL::TEXT, v_is_primary, 40, FALSE, v_ref, UUID_BOX;
    RETURN;
  END IF;

  -- A4: REF_pouch.jpg (14 ocorrências)
  IF v_base ~ '^\d+_pouch$' THEN
    v_ref := regexp_replace(v_base, '_pouch$', '');
    RETURN QUERY SELECT 'pouch'::TEXT, NULL::TEXT, v_is_primary, 41, FALSE, v_ref, UUID_POUCH;
    RETURN;
  END IF;

  -- A5: REF_logo.jpg (1 ocorrência)
  IF v_base ~ '^\d+_logo$' THEN
    v_ref := regexp_replace(v_base, '_logo$', '');
    RETURN QUERY SELECT 'logo'::TEXT, NULL::TEXT, v_is_primary, 30, FALSE, v_ref, UUID_LOGO;
    RETURN;
  END IF;

  -- A6: REF.jpg (só referência - 10 ocorrências)
  IF v_base ~ '^\d+$' THEN
    RETURN QUERY SELECT 'gallery'::TEXT, NULL::TEXT, v_is_primary, 20, FALSE, v_base, UUID_GALLERY;
    RETURN;
  END IF;

  -- A7: REF_LETRA.jpg (42058_a.jpg - 102 ocorrências)
  IF v_base ~ '^\d+_[a-zA-Z]$' THEN
    v_ref := split_part(v_base, '_', 1);
    v_letter := lower(split_part(v_base, '_', 2));
    RETURN QUERY SELECT 'gallery'::TEXT, NULL::TEXT, v_is_primary,
      COALESCE((v_order_map->>v_letter)::int, 20), FALSE, v_ref, UUID_GALLERY;
    RETURN;
  END IF;

  -- ══════════════════════════════════════════════
  -- GRUPO B: REF_COR com sufixo
  -- ══════════════════════════════════════════════

  -- B0: REF_COR_SUFIXO com underscore (28040_119_logo.jpg)
  IF v_base ~ '^\d+_\d+_.+$' THEN
    v_parts := regexp_match(v_base, '^(\d+)_(\d+)_(.+)$');
    v_ref := v_parts[1];
    v_cor := v_parts[2];

    -- Terceiro segmento numérico = multi-ref
    IF v_parts[3] ~ '^\d+$' THEN
      RETURN QUERY SELECT 'gallery'::TEXT, v_parts[3], v_is_primary, 20, TRUE, v_ref, UUID_GALLERY;
      RETURN;
    END IF;

    -- Sufixo com underscore → normalizar
    v_suffix := '-' || v_parts[3];
    -- Fall through para classificação de sufixo
  END IF;

  -- B1: REF_COR.jpg ou REF_COR-SUFIXO.jpg
  IF v_suffix IS NULL AND v_base ~ '^\d+_\d+(-.*)?$' THEN
    v_parts := regexp_match(v_base, '^(\d+)_(\d+)(-.*)?$');
    v_ref := v_parts[1];
    v_cor := v_parts[2];
    v_suffix := COALESCE(v_parts[3], '');
  END IF;

  -- Classificar sufixo se temos ref + cor
  IF v_ref IS NOT NULL AND v_cor IS NOT NULL THEN
    -- Sem sufixo = imagem principal da cor
    IF v_suffix IS NULL OR v_suffix = '' THEN
      RETURN QUERY SELECT 'main'::TEXT, v_cor, v_is_primary, 1, TRUE, v_ref, UUID_MAIN;
      RETURN;
    END IF;

    v_suffix_lower := lower(ltrim(v_suffix, '-'));
    v_suffix_parts := string_to_array(v_suffix_lower, '-');

    -- PACKAGING (prioridade máxima)
    IF 'box' = ANY(v_suffix_parts) THEN
      IF 'logo' = ANY(v_suffix_parts) THEN
        RETURN QUERY SELECT 'box'::TEXT, v_cor, v_is_primary, 43, TRUE, v_ref, UUID_BOX;
      ELSE
        RETURN QUERY SELECT 'box'::TEXT, v_cor, v_is_primary, 40, TRUE, v_ref, UUID_BOX;
      END IF;
      RETURN;
    END IF;

    IF 'pouch' = ANY(v_suffix_parts) THEN
      IF 'logo' = ANY(v_suffix_parts) THEN
        RETURN QUERY SELECT 'pouch'::TEXT, v_cor, v_is_primary, 44, TRUE, v_ref, UUID_POUCH;
      ELSE
        RETURN QUERY SELECT 'pouch'::TEXT, v_cor, v_is_primary, 41, TRUE, v_ref, UUID_POUCH;
      END IF;
      RETURN;
    END IF;

    IF 'bag' = ANY(v_suffix_parts) THEN
      IF 'logo' = ANY(v_suffix_parts) THEN
        RETURN QUERY SELECT 'bag'::TEXT, v_cor, v_is_primary, 45, TRUE, v_ref, UUID_BAG;
      ELSE
        RETURN QUERY SELECT 'bag'::TEXT, v_cor, v_is_primary, 42, TRUE, v_ref, UUID_BAG;
      END IF;
      RETURN;
    END IF;

    -- LOGO
    IF 'logo' = ANY(v_suffix_parts) THEN
      v_angle := NULL;
      FOR i IN 1..array_length(v_suffix_parts, 1) LOOP
        IF v_suffix_parts[i] ~ '^[a-g]$' THEN
          v_angle := v_suffix_parts[i];
          EXIT;
        END IF;
      END LOOP;
      RETURN QUERY SELECT 'logo'::TEXT, v_cor, v_is_primary,
        30 + COALESCE((v_order_map->>v_angle)::int, 0), TRUE, v_ref, UUID_LOGO;
      RETURN;
    END IF;

    -- SET cor-específico
    IF 'set' = ANY(v_suffix_parts) THEN
      RETURN QUERY SELECT 'set'::TEXT, v_cor, v_is_primary, 5, TRUE, v_ref, UUID_SET;
      RETURN;
    END IF;

    -- AMBIENTE
    IF 'amb' = ANY(v_suffix_parts) THEN
      RETURN QUERY SELECT 'ambient'::TEXT, v_cor, v_is_primary, 25, TRUE, v_ref, UUID_AMBIENT;
      RETURN;
    END IF;

    -- VITRINE
    IF 'vp' = ANY(v_suffix_parts) THEN
      RETURN QUERY SELECT 'vitrine_pessoa'::TEXT, v_cor, v_is_primary, 12, TRUE, v_ref, UUID_VP;
      RETURN;
    END IF;
    IF 'va' = ANY(v_suffix_parts) THEN
      RETURN QUERY SELECT 'vitrine_ambiente'::TEXT, v_cor, v_is_primary, 13, TRUE, v_ref, UUID_VA;
      RETURN;
    END IF;

    -- GALLERY (ângulos simples)
    FOR i IN 1..array_length(v_suffix_parts, 1) LOOP
      IF v_suffix_parts[i] ~ '^[a-g]$' THEN
        RETURN QUERY SELECT 'gallery'::TEXT, v_cor, v_is_primary,
          COALESCE((v_order_map->>v_suffix_parts[i])::int, 20), TRUE, v_ref, UUID_GALLERY;
        RETURN;
      END IF;
    END LOOP;

    -- Fallback: sufixo não reconhecido
    RETURN QUERY SELECT 'gallery'::TEXT, v_cor, v_is_primary, 20, TRUE, v_ref, UUID_GALLERY;
    RETURN;
  END IF;

  -- ══════════════════════════════════════════════
  -- GRUPO C: Multi-referência
  -- ══════════════════════════════════════════════

  IF v_base ~ '^\d+_\d+_\d+' THEN
    v_parts := regexp_match(v_base, '^(\d+)');
    RETURN QUERY SELECT 'gallery'::TEXT, NULL::TEXT, v_is_primary, 20, FALSE,
      COALESCE(v_parts[1], NULL), UUID_GALLERY;
    RETURN;
  END IF;

  -- ══════════════════════════════════════════════
  -- FALLBACK ABSOLUTO — NUNCA CRASH
  -- ══════════════════════════════════════════════

  v_parts := regexp_match(v_base, '^(\d+)');
  RETURN QUERY SELECT 'gallery'::TEXT, NULL::TEXT, v_is_primary, 99, FALSE,
    COALESCE(v_parts[1], NULL), UUID_GALLERY;
  RETURN;
END;
$_$;


ALTER FUNCTION "public"."fn_classify_spot_image_v3"("p_filename" "text", "p_main_image" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_classify_spot_image_v3"("p_filename" "text", "p_main_image" "text") IS 'Classifica filename de imagem SPOT em image_type, color_code, display_order.
v3.0 - 06/02/2026 - 40 padrões, 0 exceptions, 100% cobertura.
Validado contra 9.240 filenames reais da API.

Uso:
  SELECT * FROM fn_classify_spot_image_v3(''11103_103.jpg'', ''11103_set.jpg'');
  -- Retorna: main, 103, false, 1, true, 11103, UUID_MAIN

  SELECT * FROM fn_classify_spot_image_v3(''11103_set.jpg'', ''11103_set.jpg'');
  -- Retorna: set, NULL, true, 5, false, 11103, UUID_SET
';



CREATE OR REPLACE FUNCTION "public"."fn_clean_spot_name"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN s IS NULL OR s = '' THEN NULLIF(s, '')
    ELSE upper(left(s, 1)) || lower(substr(s, 2))
  END
  FROM (
    SELECT btrim(regexp_replace(
      translate(
        replace(replace(replace(replace(p_name, chr(8203), ''), chr(8204), ''), chr(8205), ''), chr(65279), ''),
        chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288),
        repeat(' ', 18)
      ),
      '\s+', ' ', 'g')) AS s
  ) t;
$$;


