CREATE OR REPLACE FUNCTION "public"."fn_color_equiv_clear_primary_on_inactive"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT NEW.is_active THEN NEW.is_primary := false; END IF;
  RETURN NEW;
END;$$;


ALTER FUNCTION "public"."fn_color_equiv_clear_primary_on_inactive"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_color_equiv_clear_primary_on_inactive"() IS 'Garante que equivalencia inativa nunca seja is_primary. fix_version 2026-06-26 - anti-regressao, NAO REMOVER.';



CREATE OR REPLACE FUNCTION "public"."fn_color_equiv_ensure_primary"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NULL; END IF;  -- evita recursao das proprias updates

  -- 1) rebaixa primarias ATIVAS que nao sao a melhor (ANTES de promover -> nunca 2 primarias)
  WITH best AS (
    SELECT DISTINCT ON (ce.supplier_color_id) ce.supplier_color_id AS sc, ce.id AS best_id
    FROM color_equivalences ce JOIN color_variations cv ON cv.id=ce.promo_variation_id
    WHERE ce.is_active
    ORDER BY ce.supplier_color_id,
             (CASE ce.match_quality WHEN 'exact' THEN 1 WHEN 'close' THEN 2 WHEN 'approximate' THEN 3 ELSE 4 END),
             ce.confidence_score DESC NULLS LAST,
             COALESCE(NULLIF(split_part(cv.internal_code,'.',1),'')::int,9999),
             COALESCE(NULLIF(split_part(cv.internal_code,'.',2),'')::int,9999), ce.id
  )
  UPDATE color_equivalences ce SET is_primary=false
  FROM best WHERE ce.supplier_color_id=best.sc AND ce.is_active AND ce.is_primary AND ce.id<>best.best_id;

  -- 2) higiene: linha inativa nunca permanece primaria
  UPDATE color_equivalences SET is_primary=false WHERE is_primary AND NOT is_active;

  -- 3) promove a melhor onde ainda nao e primaria
  UPDATE color_equivalences ce SET is_primary=true
  FROM (
    SELECT DISTINCT ON (ce.supplier_color_id) ce.id AS best_id
    FROM color_equivalences ce JOIN color_variations cv ON cv.id=ce.promo_variation_id
    WHERE ce.is_active
    ORDER BY ce.supplier_color_id,
             (CASE ce.match_quality WHEN 'exact' THEN 1 WHEN 'close' THEN 2 WHEN 'approximate' THEN 3 ELSE 4 END),
             ce.confidence_score DESC NULLS LAST,
             COALESCE(NULLIF(split_part(cv.internal_code,'.',1),'')::int,9999),
             COALESCE(NULLIF(split_part(cv.internal_code,'.',2),'')::int,9999), ce.id
  ) b WHERE ce.id=b.best_id AND NOT ce.is_primary;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_color_equiv_ensure_primary"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_color_equiv_ensure_primary"() IS 'Mantem is_primary = melhor equivalencia ativa por supplier_color (auto-cura). fix_version 2026-06-26 - anti-regressao, NAO REMOVER.';



CREATE OR REPLACE FUNCTION "public"."fn_color_equiv_ensure_primary_stmt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE r record; v_best uuid;
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NULL; END IF;  -- anti-recursao
  FOR r IN
    SELECT supplier_color_id AS sc FROM color_equivalences GROUP BY supplier_color_id
    HAVING count(*) FILTER (WHERE is_active) > 0
       AND count(*) FILTER (WHERE is_active AND is_primary) = 0
  LOOP
    SELECT ce.id INTO v_best
    FROM color_equivalences ce JOIN color_variations cv ON cv.id = ce.promo_variation_id
    WHERE ce.supplier_color_id = r.sc AND ce.is_active
    ORDER BY (CASE ce.match_quality WHEN 'exact' THEN 1 WHEN 'close' THEN 2
                                    WHEN 'approximate' THEN 3 ELSE 4 END),
             ce.confidence_score DESC NULLS LAST,
             COALESCE(NULLIF(split_part(cv.internal_code,'.',1),'')::int, 9999),
             COALESCE(NULLIF(split_part(cv.internal_code,'.',2),'')::int, 9999),
             ce.id
    LIMIT 1;
    IF v_best IS NOT NULL THEN
      UPDATE color_equivalences SET is_primary = true WHERE id = v_best;
    END IF;
  END LOOP;
  RETURN NULL;
END;$$;


ALTER FUNCTION "public"."fn_color_equiv_ensure_primary_stmt"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_color_equiv_ensure_primary_stmt"() IS 'Elege a equivalencia primaria (mesma precedencia do backfill) para supplier_colors com >=1 ativa e 0 primaria. fix_version 2026-06-26 - anti-regressao, NAO REMOVER.';



CREATE OR REPLACE FUNCTION "public"."fn_color_health_full"() RETURNS TABLE("check_id" "text", "categoria" "text", "status" "text", "total" bigint, "detalhes" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_spot_ok   boolean;
    v_spot_cnt  bigint;
    v_spot_det  text;
BEGIN
    -- C01: Cobertura color_id
    RETURN QUERY
    SELECT 'C01'::text, 'Cobertura color_id Gold'::text,
        CASE WHEN COUNT(*) FILTER (WHERE pv.color_id IS NULL) = 0 THEN '✅ OK' ELSE '❌ ERRO' END::text,
        COUNT(*) FILTER (WHERE pv.color_id IS NOT NULL)::bigint,
        FORMAT('Total ativas: %s | Sem color_id: %s', COUNT(*), COUNT(*) FILTER (WHERE pv.color_id IS NULL))::text
    FROM product_variants pv WHERE pv.is_active = true;

    -- C02: Cobertura color_code
    RETURN QUERY
    SELECT 'C02'::text, 'Cobertura color_code Gold'::text,
        CASE WHEN COUNT(*) FILTER (WHERE pv.color_code IS NULL OR pv.color_code = '') = 0 THEN '✅ OK' ELSE '⚠️ PARCIAL' END::text,
        COUNT(*) FILTER (WHERE pv.color_code IS NOT NULL AND pv.color_code != '')::bigint,
        FORMAT('Total: %s | Sem code: %s | Cobertura: %s%%',
            COUNT(*), COUNT(*) FILTER (WHERE pv.color_code IS NULL OR pv.color_code = ''),
            ROUND(100.0 * COUNT(*) FILTER (WHERE pv.color_code IS NOT NULL AND pv.color_code != '') / NULLIF(COUNT(*),0),1))::text
    FROM product_variants pv WHERE pv.is_active = true;

    -- C03: has_colors consistência
    RETURN QUERY
    SELECT 'C03'::text, 'Consistência has_colors × colors[]'::text,
        CASE WHEN COUNT(*) FILTER (WHERE has_colors = false AND jsonb_array_length(colors) > 1) = 0 THEN '✅ OK' ELSE '⚠️ GAP' END::text,
        COUNT(*) FILTER (WHERE has_colors = false AND jsonb_array_length(colors) > 1)::bigint,
        FORMAT('Multi-cor com has_colors=false: %s', COUNT(*) FILTER (WHERE has_colors = false AND jsonb_array_length(colors) > 1))::text
    FROM products WHERE is_active = true;

    -- C04: Supplier colors sem equivalência
    RETURN QUERY
    SELECT 'C04'::text, 'Supplier colors sem equivalência ativa'::text,
        CASE WHEN COUNT(*) = 0 THEN '✅ OK' ELSE '⚠️ PENDENTE' END::text,
        COUNT(*)::bigint,
        FORMAT('Cores sem mapeamento: %s', COUNT(*))::text
    FROM supplier_colors sc
    LEFT JOIN color_equivalences ce ON ce.supplier_color_id = sc.id AND ce.is_active = true
    WHERE ce.id IS NULL AND sc.is_active = true;

    -- C05: Silver XBZ bicolor
    RETURN QUERY
    SELECT 'C05'::text, 'Silver XBZ bicolor color_id_2'::text,
        CASE WHEN COUNT(*) FILTER (WHERE color_code_2 IS NOT NULL AND color_id_2 IS NULL) = 0 THEN '✅ OK' ELSE '⚠️ GAP' END::text,
        COUNT(*) FILTER (WHERE color_code_2 IS NOT NULL AND color_id_2 IS NOT NULL)::bigint,
        FORMAT('Bicolor: %s | id_2 OK: %s | id_2 NULL: %s',
            COUNT(*) FILTER (WHERE color_code_2 IS NOT NULL),
            COUNT(*) FILTER (WHERE color_code_2 IS NOT NULL AND color_id_2 IS NOT NULL),
            COUNT(*) FILTER (WHERE color_code_2 IS NOT NULL AND color_id_2 IS NULL))::text
    FROM produtos_padronizacao_variantes
    WHERE supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900';

    -- C06: Qualidade equivalências
    RETURN QUERY
    SELECT 'C06'::text, 'Qualidade das equivalências'::text,
        CASE WHEN ROUND(100.0 * COUNT(*) FILTER (WHERE match_quality='exact') / NULLIF(COUNT(*),0),0) >= 70 THEN '✅ OK' ELSE '⚠️ BAIXA' END::text,
        COUNT(*) FILTER (WHERE match_quality = 'exact')::bigint,
        FORMAT('Exact: %s | Close: %s | Approx: %s | %%Exact: %s%%',
            COUNT(*) FILTER (WHERE match_quality='exact'),
            COUNT(*) FILTER (WHERE match_quality='close'),
            COUNT(*) FILTER (WHERE match_quality='approximate'),
            ROUND(100.0 * COUNT(*) FILTER (WHERE match_quality='exact') / NULLIF(COUNT(*),0),1))::text
    FROM color_equivalences WHERE is_active = true;

    -- C07: SPOT integrity (usando variável para evitar ambiguidade)
    SELECT
        bool_and(r.status = '✅ OK'),
        COUNT(*) FILTER (WHERE r.status = '✅ OK'),
        STRING_AGG(r.check_name || ':' || r.status, ' | ')
    INTO v_spot_ok, v_spot_cnt, v_spot_det
    FROM fn_spot_color_integrity_check() r;

    RETURN QUERY
    SELECT 'C07'::text, 'Integridade SPOT color_integrity'::text,
        CASE WHEN v_spot_ok THEN '✅ OK' ELSE '❌ FALHAS' END::text,
        v_spot_cnt, v_spot_det;

    -- C08: fn_relatorio_cores_pendentes operacional
    RETURN QUERY
    SELECT 'C08'::text, 'fn_relatorio_cores_pendentes operacional'::text, '✅ OK'::text,
        (SELECT COUNT(*) FROM fn_relatorio_cores_pendentes())::bigint,
        FORMAT('Pendências: %s', (SELECT COUNT(*) FROM fn_relatorio_cores_pendentes()))::text;
END;
$$;


ALTER FUNCTION "public"."fn_color_health_full"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_color_health_full"() IS 'Health check completo do subsistema de cores. 8 checks cobrindo Gold, Silver, equivalências e integridade SPOT. Executar: SELECT * FROM fn_color_health_full();';



CREATE OR REPLACE FUNCTION "public"."fn_color_link_all_suppliers"("p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_xbz_mono    int := 0;
  v_spot_sm_mono int := 0;
  v_asia_varcor  int := 0;
  v_asia_prefix  int := 0;
  v_xbz_cross    int := 0;
  v_t04          int := 0;
BEGIN

  -- 1. XBZ Mono-cor
  IF NOT p_dry_run THEN
    WITH m AS (
      SELECT DISTINCT ON (pi.id)
        pi.id iid, pv.id vid, pv.color_id cid
      FROM product_images pi
      JOIN LATERAL (
        SELECT pv2.id, pv2.color_id
        FROM product_variants pv2
        WHERE pv2.product_id=pi.product_id AND pv2.is_active=true AND pv2.color_id IS NOT NULL
        ORDER BY pv2.id LIMIT 1
      ) pv ON true
      WHERE pi.supplier_code='XBZ' AND pi.is_active=true
        AND pi.color_id IS NULL AND pi.variant_id IS NULL
        AND (SELECT COUNT(DISTINCT pv3.color_id) FROM product_variants pv3
             WHERE pv3.product_id=pi.product_id AND pv3.is_active=true AND pv3.color_id IS NOT NULL)=1
      ORDER BY pi.id
    )
    UPDATE product_images SET color_id=m.cid, variant_id=m.vid, updated_at=NOW()
    FROM m WHERE id=m.iid;
    GET DIAGNOSTICS v_xbz_mono = ROW_COUNT;
  ELSE
    SELECT COUNT(DISTINCT pi.id) INTO v_xbz_mono
    FROM product_images pi
    WHERE pi.supplier_code='XBZ' AND pi.is_active=true
      AND pi.color_id IS NULL AND pi.variant_id IS NULL
      AND (SELECT COUNT(DISTINCT pv3.color_id) FROM product_variants pv3
           WHERE pv3.product_id=pi.product_id AND pv3.is_active=true AND pv3.color_id IS NOT NULL)=1;
  END IF;

  -- 2. SPOT+SOMARCAS Mono-cor
  IF NOT p_dry_run THEN
    WITH m AS (
      SELECT DISTINCT ON (pi.id)
        pi.id iid, pv.id vid, pv.color_id cid
      FROM product_images pi
      JOIN LATERAL (
        SELECT pv2.id, pv2.color_id
        FROM product_variants pv2
        WHERE pv2.product_id=pi.product_id AND pv2.is_active=true AND pv2.color_id IS NOT NULL
        ORDER BY pv2.id LIMIT 1
      ) pv ON true
      WHERE pi.supplier_code IN ('SPOT','SOMARCAS') AND pi.is_active=true
        AND pi.color_id IS NULL AND pi.variant_id IS NULL
        AND (SELECT COUNT(DISTINCT pv3.color_id) FROM product_variants pv3
             WHERE pv3.product_id=pi.product_id AND pv3.is_active=true AND pv3.color_id IS NOT NULL)=1
      ORDER BY pi.id
    )
    UPDATE product_images SET color_id=m.cid, variant_id=m.vid, updated_at=NOW()
    FROM m WHERE id=m.iid;
    GET DIAGNOSTICS v_spot_sm_mono = ROW_COUNT;
  ELSE
    SELECT COUNT(DISTINCT pi.id) INTO v_spot_sm_mono
    FROM product_images pi
    WHERE pi.supplier_code IN ('SPOT','SOMARCAS') AND pi.is_active=true
      AND pi.color_id IS NULL AND pi.variant_id IS NULL
      AND (SELECT COUNT(DISTINCT pv3.color_id) FROM product_variants pv3
           WHERE pv3.product_id=pi.product_id AND pv3.is_active=true AND pv3.color_id IS NOT NULL)=1;
  END IF;

  -- 3. ASIA via var_cor_nome (raw_data)
  IF NOT p_dry_run THEN
    WITH af AS (
      SELECT DISTINCT ON (pi.id)
        pi.id iid, pv.id vid, pv.color_id cid
      FROM supplier_products_raw spr
      JOIN product_variants pv ON pv.product_id=spr.product_id
        AND pv.is_active=true AND pv.color_id IS NOT NULL
        AND (UPPER(TRIM(spr.raw_data->>'var_cor_nome'))=UPPER(TRIM(pv.color_name))
          OR UPPER(TRIM(spr.raw_data->>'var_cor_nome'))=UPPER(TRIM(
             (SELECT cv.name FROM color_variations cv WHERE cv.id=pv.color_id LIMIT 1))))
        AND NOT EXISTS (SELECT 1 FROM product_images pi2
                        WHERE pi2.product_id=pv.product_id AND pi2.color_id=pv.color_id AND pi2.is_active=true)
      JOIN product_images pi ON pi.product_id=spr.product_id
        AND REGEXP_REPLACE(pi.url_original,'.*/(.+)$','\1')=REGEXP_REPLACE(spr.raw_data->>'imagem','.*/(.+)$','\1')
        AND pi.is_active=true AND pi.color_id IS NULL
      WHERE spr.supplier_id='d2734e23-d633-4819-bb15-e51aa44e2118'::uuid
        AND spr.raw_data->>'var_cor_nome' IS NOT NULL AND spr.raw_data->>'imagem' IS NOT NULL
      ORDER BY pi.id, pv.color_id
    ),
    unamb AS (
      SELECT iid, vid, cid FROM af
      WHERE iid IN (SELECT iid FROM af GROUP BY iid HAVING COUNT(DISTINCT cid)=1)
    )
    UPDATE product_images SET color_id=u.cid, variant_id=u.vid, updated_at=NOW()
    FROM unamb u WHERE id=u.iid;
    GET DIAGNOSTICS v_asia_varcor = ROW_COUNT;
  ELSE
    SELECT COUNT(DISTINCT pi.id) INTO v_asia_varcor
    FROM product_images pi
    JOIN supplier_products_raw spr ON spr.product_id=pi.product_id
    JOIN product_variants pv ON pv.product_id=spr.product_id
      AND pv.is_active=true AND pv.color_id IS NOT NULL
      AND (UPPER(TRIM(spr.raw_data->>'var_cor_nome'))=UPPER(TRIM(pv.color_name))
        OR UPPER(TRIM(spr.raw_data->>'var_cor_nome'))=UPPER(TRIM(
           (SELECT cv.name FROM color_variations cv WHERE cv.id=pv.color_id LIMIT 1))))
      AND NOT EXISTS (SELECT 1 FROM product_images pi2
                      WHERE pi2.product_id=pv.product_id AND pi2.color_id=pv.color_id AND pi2.is_active=true)
    WHERE spr.supplier_id='d2734e23-d633-4819-bb15-e51aa44e2118'::uuid
      AND spr.raw_data->>'var_cor_nome' IS NOT NULL AND spr.raw_data->>'imagem' IS NOT NULL
      AND REGEXP_REPLACE(pi.url_original,'.*/(.+)$','\1')=REGEXP_REPLACE(spr.raw_data->>'imagem','.*/(.+)$','\1')
      AND pi.is_active=true AND pi.color_id IS NULL;
  END IF;

  -- 4. ASIA via prefixo de cor no filename (VD-PERSONALIZACAO, PT-CANETA...)
  IF NOT p_dry_run THEN
    WITH af AS (
      SELECT DISTINCT ON (pi.id)
        pi.id iid, pv.id vid, pv.color_id cid
      FROM product_images pi
      JOIN product_variants pv ON pv.product_id=pi.product_id
        AND pv.is_active=true AND pv.color_id IS NOT NULL
      WHERE pi.supplier_code='ASIA' AND pi.is_active=true
        AND pi.color_id IS NULL AND pi.variant_id IS NULL
        AND (
          UPPER(REGEXP_REPLACE(pi.url_original,'^.*[/-]([A-Z]{2,3})[-_][A-Z].*\.(?:jpg|png|jpeg)$','\1'))
            = UPPER(TRIM(pv.color_code))
          OR UPPER(REGEXP_REPLACE(pi.url_original,'^.+[-_]([A-Z]{2,4})[-_]?\d*\.(?:jpg|png|jpeg)$','\1'))
            = UPPER(TRIM(pv.color_code))
          OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '-%'
          OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '.'
          OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '_'
        )
        AND NOT EXISTS (SELECT 1 FROM product_images pi2
                        WHERE pi2.product_id=pv.product_id AND pi2.color_id=pv.color_id AND pi2.is_active=true)
      ORDER BY pi.id, pv.color_id
    ),
    unamb AS (
      SELECT iid, vid, cid FROM af
      WHERE iid IN (SELECT iid FROM af GROUP BY iid HAVING COUNT(DISTINCT cid)=1)
    )
    UPDATE product_images SET color_id=u.cid, variant_id=u.vid, updated_at=NOW()
    FROM unamb u WHERE id=u.iid;
    GET DIAGNOSTICS v_asia_prefix = ROW_COUNT;
  ELSE
    SELECT COUNT(DISTINCT pi.id) INTO v_asia_prefix
    FROM product_images pi
    JOIN product_variants pv ON pv.product_id=pi.product_id
      AND pv.is_active=true AND pv.color_id IS NOT NULL
    WHERE pi.supplier_code='ASIA' AND pi.is_active=true
      AND pi.color_id IS NULL AND pi.variant_id IS NULL
      AND (
        UPPER(REGEXP_REPLACE(pi.url_original,'^.*[/-]([A-Z]{2,3})[-_][A-Z].*\.(?:jpg|png|jpeg)$','\1'))
          = UPPER(TRIM(pv.color_code))
        OR UPPER(REGEXP_REPLACE(pi.url_original,'^.+[-_]([A-Z]{2,4})[-_]?\d*\.(?:jpg|png|jpeg)$','\1'))
          = UPPER(TRIM(pv.color_code))
        OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '-%'
        OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '.'
        OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '_'
      )
      AND NOT EXISTS (SELECT 1 FROM product_images pi2
                      WHERE pi2.product_id=pv.product_id AND pi2.color_id=pv.color_id AND pi2.is_active=true);
  END IF;

  -- 5. XBZ cross-product color fix (mono-cor com cor errada)
  IF NOT p_dry_run THEN
    WITH fix AS (
      SELECT DISTINCT ON (pi.id)
        pi.id iid, pv.color_id cid, pv.id vid
      FROM product_images pi
      JOIN product_variants pv ON pv.product_id=pi.product_id
        AND pv.is_active=true AND pv.color_id IS NOT NULL
      WHERE pi.is_active=true AND pi.color_id IS NOT NULL AND pi.color_id != pv.color_id
        AND (SELECT COUNT(DISTINCT pv2.color_id) FROM product_variants pv2
             WHERE pv2.product_id=pi.product_id AND pv2.is_active=true AND pv2.color_id IS NOT NULL)=1
        AND NOT EXISTS (SELECT 1 FROM product_images pi3
                        WHERE pi3.product_id=pi.product_id AND pi3.color_id=pv.color_id AND pi3.is_active=true)
        AND NOT EXISTS (SELECT 1 FROM product_variants pv4
                        WHERE pv4.product_id=pi.product_id AND pv4.color_id=pi.color_id AND pv4.is_active=true)
        AND EXISTS (SELECT 1 FROM product_images pi5
                    WHERE pi5.product_id=pi.product_id AND pi5.supplier_code='XBZ' AND pi5.is_active=true)
      ORDER BY pi.id
    )
    UPDATE product_images SET color_id=f.cid, variant_id=f.vid, updated_at=NOW()
    FROM fix f WHERE id=f.iid;
    GET DIAGNOSTICS v_xbz_cross = ROW_COUNT;
  ELSE
    SELECT COUNT(DISTINCT pi.id) INTO v_xbz_cross
    FROM product_images pi
    JOIN product_variants pv ON pv.product_id=pi.product_id AND pv.is_active=true AND pv.color_id IS NOT NULL
    WHERE pi.is_active=true AND pi.color_id IS NOT NULL AND pi.color_id != pv.color_id
      AND (SELECT COUNT(DISTINCT pv2.color_id) FROM product_variants pv2
           WHERE pv2.product_id=pi.product_id AND pv2.is_active=true AND pv2.color_id IS NOT NULL)=1
      AND NOT EXISTS (SELECT 1 FROM product_images pi3
                      WHERE pi3.product_id=pi.product_id AND pi3.color_id=pv.color_id AND pi3.is_active=true)
      AND NOT EXISTS (SELECT 1 FROM product_variants pv4
                      WHERE pv4.product_id=pi.product_id AND pv4.color_id=pi.color_id AND pv4.is_active=true)
      AND EXISTS (SELECT 1 FROM product_images pi5
                  WHERE pi5.product_id=pi.product_id AND pi5.supplier_code='XBZ' AND pi5.is_active=true);
  END IF;

  -- 6. T04 fix: color_id ← variant.color_id quando divergem (nuance vs canonical)
  IF NOT p_dry_run THEN
    WITH div AS (
      SELECT pi.id, pv.color_id cid
      FROM product_images pi
      JOIN product_variants pv ON pv.id=pi.variant_id
      WHERE pi.is_active=true AND pi.color_id IS DISTINCT FROM pv.color_id
        AND pi.variant_id IS NOT NULL AND pv.color_id IS NOT NULL
    )
    UPDATE product_images SET color_id=d.cid, updated_at=NOW()
    FROM div d WHERE product_images.id=d.id;
    GET DIAGNOSTICS v_t04 = ROW_COUNT;
  ELSE
    SELECT COUNT(*) INTO v_t04
    FROM product_images pi JOIN product_variants pv ON pv.id=pi.variant_id
    WHERE pi.is_active=true AND pi.color_id IS DISTINCT FROM pv.color_id
      AND pi.variant_id IS NOT NULL AND pv.color_id IS NOT NULL;
  END IF;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'xbz_mono', v_xbz_mono,
    'spot_sm_mono', v_spot_sm_mono,
    'asia_varcor', v_asia_varcor,
    'asia_prefix', v_asia_prefix,
    'xbz_cross', v_xbz_cross,
    't04_fix', v_t04,
    'total', v_xbz_mono+v_spot_sm_mono+v_asia_varcor+v_asia_prefix+v_xbz_cross+v_t04,
    'run_at', NOW()
  );
END;
$_$;


