CREATE OR REPLACE FUNCTION "public"."fn_convert_box_dimension_to_cm"("p_value" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_num DECIMAL;
BEGIN
    IF p_value IS NULL OR TRIM(p_value) = '' THEN
        RETURN NULL;
    END IF;
    
    v_num := p_value::DECIMAL;
    
    -- Detectar automaticamente:
    -- Se valor < 10, provavelmente está em METROS (ex: 0.42)
    -- Se valor >= 10, provavelmente está em MILÍMETROS (ex: 420)
    
    IF v_num < 10 THEN
        -- Valor em METROS → multiplicar por 100 para cm
        RETURN ROUND(v_num * 100, 2);
    ELSE
        -- Valor em MILÍMETROS → dividir por 10 para cm
        RETURN ROUND(v_num / 10, 2);
    END IF;
    
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_convert_box_dimension_to_cm"("p_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_convert_box_dimension_to_cm"("p_value" "text") IS 'Converte dimensão de caixa para cm (detecta automaticamente se entrada é metros ou mm)';



CREATE OR REPLACE FUNCTION "public"."fn_convert_unit"("p_value" numeric, "p_source_unit" character varying, "p_target_unit" character varying, "p_supplier_id" "uuid" DEFAULT NULL::"uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_multiplier DECIMAL;
BEGIN
    -- Se valor nulo, retorna nulo
    IF p_value IS NULL THEN
        RETURN NULL;
    END IF;
    
    -- Se unidades iguais, retorna valor original
    IF LOWER(TRIM(p_source_unit)) = LOWER(TRIM(p_target_unit)) THEN
        RETURN p_value;
    END IF;
    
    -- Buscar conversão (primeiro específica do fornecedor, depois global)
    SELECT multiplier INTO v_multiplier
    FROM supplier_unit_conversions
    WHERE LOWER(source_unit) = LOWER(TRIM(p_source_unit))
      AND LOWER(target_unit) = LOWER(TRIM(p_target_unit))
      AND (supplier_id = p_supplier_id OR supplier_id IS NULL)
      AND is_active = TRUE
    ORDER BY supplier_id NULLS LAST
    LIMIT 1;
    
    IF v_multiplier IS NULL THEN
        RAISE WARNING 'Conversão não encontrada: % → %', p_source_unit, p_target_unit;
        RETURN p_value;
    END IF;
    
    RETURN ROUND(p_value * v_multiplier, 4);
END;
$$;


ALTER FUNCTION "public"."fn_convert_unit"("p_value" numeric, "p_source_unit" character varying, "p_target_unit" character varying, "p_supplier_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_convert_unit"("p_value" numeric, "p_source_unit" character varying, "p_target_unit" character varying, "p_supplier_id" "uuid") IS 'Converte valor entre unidades usando tabela de conversões';



CREATE OR REPLACE FUNCTION "public"."fn_cor_generate_slug"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NEW.slug IS NULL OR NEW.slug = '' THEN
        NEW.slug := lower(regexp_replace(NEW.codigo, '[^a-zA-Z0-9]+', '-', 'g'));
        NEW.slug := trim(BOTH '-' FROM NEW.slug);
    END IF;
    RETURN NEW;
END;
$$;


