CREATE OR REPLACE FUNCTION "public"."fn_create_multiple_equivalences"("p_supplier_material_id" "uuid", "p_organization_id" "uuid" DEFAULT '4f2f91ed-beec-4fa4-867d-5f20c8a4ef00'::"uuid") RETURNS TABLE("material_part" "text", "promo_type_id" "uuid", "promo_type_name" "text", "created" boolean, "status" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_api_name TEXT;
    v_part RECORD;
    v_type_id UUID;
    v_type_name TEXT;
BEGIN
    SELECT api_material_name INTO v_api_name
    FROM supplier_materials
    WHERE id = p_supplier_material_id;
    
    IF v_api_name IS NULL THEN
        material_part := NULL;
        promo_type_id := NULL;
        promo_type_name := NULL;
        created := FALSE;
        status := 'ERRO: supplier_material_id não encontrado';
        RETURN NEXT;
        RETURN;
    END IF;
    
    FOR v_part IN SELECT * FROM fn_parse_composite_material(v_api_name)
    LOOP
        material_part := v_part.material_part;
        v_type_id := fn_find_material_type_id(v_part.material_part);
        promo_type_id := v_type_id;
        
        IF v_type_id IS NOT NULL THEN
            SELECT name INTO v_type_name FROM material_types WHERE id = v_type_id;
            promo_type_name := v_type_name;
            
            IF NOT EXISTS (
                SELECT 1 FROM material_equivalences
                WHERE supplier_material_id = p_supplier_material_id
                  AND promo_type_id = v_type_id
            ) THEN
                INSERT INTO material_equivalences (
                    supplier_material_id,
                    promo_type_id,
                    match_level,
                    match_quality,
                    confidence_score,
                    notes,
                    created_at,
                    updated_at
                ) VALUES (
                    p_supplier_material_id,
                    v_type_id,
                    'type',
                    'automatic',
                    0.85,
                    'Gerado por fn_create_multiple_equivalences',
                    now(),
                    now()
                );
                created := TRUE;
                status := 'CRIADO';
            ELSE
                created := FALSE;
                status := 'JÁ EXISTE';
            END IF;
        ELSE
            promo_type_name := '(não encontrado)';
            created := FALSE;
            status := 'TIPO NÃO ENCONTRADO';
        END IF;
        
        RETURN NEXT;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_create_multiple_equivalences"("p_supplier_material_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_create_quote_v3"("p_quote_data" "jsonb", "p_items_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _result public.quotes;
  _quote_payload  jsonb;
  _items_payload  jsonb;
  _item           jsonb;
  _item_converted jsonb;
BEGIN
  -- Verifica autenticação (mantém comportamento original)
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  -- Converte o payload do formato v3 para o formato esperado por create_quote_transactional
  -- seller_id é sempre auth.uid() (mesma semântica da v3 original)
  _quote_payload := jsonb_build_object(
    'quote_number',               '',
    'client_id',                  p_quote_data->>'client_id',
    'client_name',                COALESCE(p_quote_data->>'client_name', ''),
    'client_email',               p_quote_data->>'client_email',
    'client_phone',               p_quote_data->>'client_phone',
    'client_company',             p_quote_data->>'client_company',
    'seller_id',                  auth.uid()::text,
    'organization_id',            p_quote_data->>'organization_id',
    'status',                     COALESCE(p_quote_data->>'status', 'draft'),
    'subtotal',                   COALESCE(p_quote_data->>'subtotal', '0'),
    'discount_percent',           COALESCE(p_quote_data->>'discount_percent', '0'),
    'discount_amount',            COALESCE(p_quote_data->>'discount_amount', '0'),
    'total',                      COALESCE(p_quote_data->>'total', '0'),
    'negotiation_markup_percent', COALESCE(p_quote_data->>'negotiation_markup_percent', '0'),
    'notes',                      p_quote_data->>'notes',
    'internal_notes',             p_quote_data->>'internal_notes',
    'valid_until',                p_quote_data->>'valid_until',
    'payment_terms',              p_quote_data->>'payment_terms',
    'delivery_time',              p_quote_data->>'delivery_time',
    'shipping_type',              p_quote_data->>'shipping_type',
    'shipping_cost',              COALESCE(p_quote_data->>'shipping_cost', '0')
  );

  -- Garante que os itens tenham 'personalizations' (v3 não exigia o campo)
  SELECT jsonb_agg(
    item || CASE WHEN item ? 'personalizations' THEN '{}'::jsonb
                 ELSE jsonb_build_object('personalizations','[]'::jsonb)
            END)
  INTO _items_payload
  FROM jsonb_array_elements(COALESCE(p_items_data,'[]'::jsonb)) AS item;

  _items_payload := COALESCE(_items_payload, '[]'::jsonb);

  -- Delega para a RPC canônica (inclui audit trail, validações, atomic)
  _result := public.create_quote_transactional(_quote_payload, _items_payload);

  -- Retorna no mesmo formato da v3 original para retrocompatibilidade
  RETURN jsonb_build_object('id', _result.id, 'quote_number', _result.quote_number);
END;
$$;


ALTER FUNCTION "public"."fn_create_quote_v3"("p_quote_data" "jsonb", "p_items_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cron_guard"("p_key" bigint, "p_sql" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF pg_try_advisory_xact_lock(p_key) THEN
    EXECUTE p_sql;
  ELSE
    RAISE NOTICE 'fn_cron_guard: job % ainda em execução, tick ignorado', p_key;
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_cron_guard"("p_key" bigint, "p_sql" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cron_safe_run"("p_key" bigint, "p_sql" "text", "p_timeout_ms" integer DEFAULT 45000, "p_job_label" "text" DEFAULT 'cron'::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_start timestamptz := clock_timestamp(); v_duration_ms int;
BEGIN
  IF NOT pg_try_advisory_xact_lock(p_key) THEN
    RETURN format('[%s] SKIP: job ainda em execução (lock=%s)', p_job_label, p_key);
  END IF;
  EXECUTE format('SET LOCAL statement_timeout = %L', p_timeout_ms || 'ms');
  EXECUTE p_sql;
  v_duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - v_start)) * 1000;
  RETURN format('[%s] OK: %sms', p_job_label, v_duration_ms);
EXCEPTION
  WHEN query_canceled THEN
    RETURN format('[%s] TIMEOUT após %sms (limite=%sms)', p_job_label,
      EXTRACT(EPOCH FROM (clock_timestamp() - v_start))::int * 1000, p_timeout_ms);
  WHEN OTHERS THEN
    RETURN format('[%s] ERRO: %s', p_job_label, SQLERRM);
END; $$;


ALTER FUNCTION "public"."fn_cron_safe_run"("p_key" bigint, "p_sql" "text", "p_timeout_ms" integer, "p_job_label" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_cron_safe_run"("p_key" bigint, "p_sql" "text", "p_timeout_ms" integer, "p_job_label" "text") IS 'v2 — Guard universal para cron jobs. Correções: (B1) timeout via set_config(is_local=true) propaga corretamente para SPI calls internas; (B2) duração em ms sem truncamento prematuro.';



CREATE OR REPLACE FUNCTION "public"."fn_cron_watchdog"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_killed int := 0; v_result jsonb; v_rec record;
BEGIN
  FOR v_rec IN
    SELECT a.pid, a.query, a.query_start,
      ROUND(EXTRACT(EPOCH FROM (now() - a.query_start)) * 1000)::bigint AS duration_ms,
      (regexp_match(a.query, '''([^'']+)'''))[1] AS job_label,
      COALESCE(
        (SELECT m.timeout_sec FROM public.cron_job_timeout_map m
         WHERE a.query ILIKE '%' || m.jobname || '%' LIMIT 1), 55
      ) AS timeout_sec
    FROM pg_stat_activity a
    WHERE a.application_name = 'pg_cron' AND a.state = 'active'
      AND a.query_start IS NOT NULL
      AND a.query NOT ILIKE '%fn_cron_watchdog%'
      AND a.pid != pg_backend_pid()
  LOOP
    IF v_rec.duration_ms > (v_rec.timeout_sec * 1000) THEN
      INSERT INTO public.cron_watchdog_log
        (pid, jobname, query_start, duration_ms, query_preview)
      VALUES (v_rec.pid, COALESCE(v_rec.job_label,'unknown'),
              v_rec.query_start, v_rec.duration_ms, LEFT(v_rec.query,200));
      PERFORM pg_cancel_backend(v_rec.pid);
      v_killed := v_killed + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('killed', v_killed, 'action',
    CASE WHEN v_killed > 0 THEN 'KILLED:'||v_killed ELSE 'ALL_OK' END);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END; $$;


ALTER FUNCTION "public"."fn_cron_watchdog"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_cron_watchdog"() IS 'Watchdog externo para enforcement de timeouts em cron jobs. Cancela gracefully (pg_cancel_backend) jobs que excederam timeout de cron_job_timeout_map. Executado a cada minuto via fn_capture_connection_snapshot → monitor-connections.';



