CREATE OR REPLACE FUNCTION "public"."fn_decompose_kit_from_ficha"("p_sku" "text", "p_dry" boolean DEFAULT true) RETURNS TABLE("acao" "text", "slot" "text", "nome" "text", "tipo" "text", "a" integer, "l" integer, "p" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_kid uuid; v_ph_id uuid; v_ph_slot text; v_ph_pkg boolean; v_ph_sku text; v_ic text; v_ncomp int; v_phnum int; v_legacy boolean:=false;
  r record; v_kidx int:=0; v_eidx int:=0; v_first_item boolean:=false; v_first_pkg boolean:=false;
  v_kind text; v_type text; v_code text; v_csku text; v_a int; v_l int; v_pp int; v_tgt uuid; v_nm text;
BEGIN
  SELECT id INTO v_kid FROM products WHERE sku=p_sku AND is_kit=true;
  IF v_kid IS NULL THEN RAISE EXCEPTION 'kit % nao encontrado', p_sku; END IF;
  SELECT count(*) INTO v_ncomp FROM product_kit_components WHERE kit_product_id=v_kid;
  IF v_ncomp<>1 THEN RAISE EXCEPTION 'kit % tem % componentes (esperado 1)', p_sku, v_ncomp; END IF;

  SELECT id, slot_code, is_packaging, component_sku INTO v_ph_id, v_ph_slot, v_ph_pkg, v_ph_sku
  FROM product_kit_components WHERE kit_product_id=v_kid;
  v_phnum := (substring(v_ph_slot from 2))::int;

  v_ic := (regexp_match(v_ph_sku, '^'||p_sku||'-([0-9.]+)-(K|E)[0-9]+$'))[1];
  IF v_ic IS NULL THEN
    v_ic := (regexp_match(v_ph_sku, '^'||p_sku||'-([A-Za-z]{2,6})$'))[1];
    v_legacy := (v_ic IS NOT NULL);
  END IF;
  IF v_ic IS NULL THEN RAISE EXCEPTION 'internal_code/cor nao extraivel do sku % - defer manual', v_ph_sku; END IF;

  FOR r IN
    SELECT s.id sid, s.piece_label, s.source_url, s.dim_a_mm, s.dim_l_mm, s.dim_p_mm, fn_norm_piece_label(s.piece_label) pnorm
    FROM kit_component_ficha_staging s
    WHERE s.product_sku=p_sku AND s.piece_label NOT LIKE '\_\_%'
      AND s.match_status IN ('no_component','ambiguous','pending')
    ORDER BY (CASE WHEN fn_norm_piece_label(s.piece_label) ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa)' THEN 1 ELSE 0 END), s.id
  LOOP
    v_kind := CASE WHEN r.pnorm ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa)' THEN 'packaging' ELSE 'item' END;
    v_type := CASE
      WHEN r.pnorm ~ 'faca' THEN 'FACA' WHEN r.pnorm ~ 'tabua' THEN 'TABUA'
      WHEN r.pnorm ~ 'garfo' THEN 'GARFO' WHEN r.pnorm ~ 'espatula' THEN 'ESPATULA'
      WHEN r.pnorm ~ '(colher|concha|escumadeira)' THEN 'COLHER' WHEN r.pnorm ~ 'pegador' THEN 'PEGADOR'
      WHEN r.pnorm ~ 'pincel' THEN 'PINCEL' WHEN r.pnorm ~ '(caderno|caderneta)' THEN 'CADERNO'
      WHEN r.pnorm ~ 'caneta' THEN 'CANETA' WHEN r.pnorm ~ 'copo' THEN 'COPO'
      WHEN r.pnorm ~ 'caneca' THEN 'CANECA' WHEN r.pnorm ~ 'garrafa' THEN 'GARRAFA'
      WHEN r.pnorm ~ 'chaveiro' THEN 'CHAVEIRO' WHEN r.pnorm ~ 'porta ?cart' THEN 'PORTA_CARTAO'
      WHEN r.pnorm ~ 'tesoura' THEN 'TESOURA' WHEN r.pnorm ~ 'canudo' THEN 'CANUDO'
      WHEN r.pnorm ~ 'frasco' THEN 'FRASCO' WHEN r.pnorm ~ 'pote' THEN 'POTE'
      WHEN r.pnorm ~ 'bandeja' THEN 'BANDEJA' WHEN r.pnorm ~ 'squeeze' THEN 'SQUEEZE'
      WHEN r.pnorm ~ 'coquetel' THEN 'COQUETELEIRA' WHEN r.pnorm ~ 'saca.?rolha' THEN 'SACA_ROLHAS'
      WHEN r.pnorm ~ 'dosador' THEN 'BICO_DOSADOR' WHEN r.pnorm ~ 'socador' THEN 'SOCADOR'
      WHEN r.pnorm ~ 'escova' THEN 'ESCOVA' WHEN r.pnorm ~ 'xicara' THEN 'XICARA'
      WHEN r.pnorm ~ 'pires' THEN 'PIRES' WHEN r.pnorm ~ '(taca|taça)' THEN 'TACA_VINHO'
      WHEN r.pnorm ~ 'chaira' THEN 'CHAIRA' WHEN r.pnorm ~ 'avental' THEN 'AVENTAL'
      WHEN r.pnorm ~ 'necessaire' THEN 'NECESSAIRE' WHEN r.pnorm ~ 'fone' THEN 'FONE'
      WHEN r.pnorm ~ 'mochila' THEN 'MOCHILA' WHEN r.pnorm ~ 'caixa' THEN 'CAIXA'
      WHEN r.pnorm ~ 'anel' THEN 'ANEL_SALVA_GOTAS' WHEN r.pnorm ~ 'tampa' THEN 'TAMPA'
      WHEN r.pnorm ~ 'porta ?copo' THEN 'TAMPA' WHEN r.pnorm ~ 'marmita' THEN 'POTE'
      ELSE NULL END;
    v_a := CASE WHEN r.dim_a_mm BETWEEN 1 AND 1500 THEN r.dim_a_mm END;
    v_l := CASE WHEN r.dim_l_mm BETWEEN 1 AND 1500 THEN r.dim_l_mm END;
    v_pp := CASE WHEN r.dim_p_mm BETWEEN 1 AND 1500 THEN r.dim_p_mm END;
    v_nm := left(initcap(r.piece_label), 80);

    IF v_kind='item' THEN
      IF (NOT v_ph_pkg) AND (NOT v_first_item) THEN
        slot:=v_ph_slot; acao:='UPDATE placeholder->item'; v_tgt:=v_ph_id; v_first_item:=true; v_kidx:=greatest(v_kidx,v_phnum);
        IF NOT p_dry THEN
          UPDATE product_kit_components SET component_name=v_nm, component_type_code=v_type,
                 component_code=CASE WHEN v_legacy THEN p_sku||'-'||v_ph_slot ELSE component_code END,
                 component_sku =CASE WHEN v_legacy THEN p_sku||'-'||v_ic||'-'||v_ph_slot ELSE component_sku END,
                 height_mm=v_a, width_mm=v_l, length_mm=v_pp, dim_source='ficha', dim_source_url=r.source_url WHERE id=v_ph_id;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_ph_id, product_id=v_kid,
                 piece_kind='item', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:placeholder' WHERE id=r.sid;
        END IF;
      ELSE
        v_kidx:=v_kidx+1; IF (NOT v_ph_pkg) AND v_kidx=v_phnum THEN v_kidx:=v_kidx+1; END IF;
        slot:='K'||v_kidx; acao:='INSERT item'; v_code:=p_sku||'-'||slot; v_csku:=p_sku||'-'||v_ic||'-'||slot;
        IF NOT p_dry THEN
          INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
            is_packaging,quantity,is_standalone_sellable,height_mm,width_mm,length_mm,dim_source,dim_source_url)
          VALUES (v_kid,v_nm,v_type,slot,v_code,v_csku,false,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_tgt, product_id=v_kid,
                 piece_kind='item', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:novo' WHERE id=r.sid;
        END IF;
      END IF;
    ELSE
      IF v_ph_pkg AND (NOT v_first_pkg) THEN
        slot:=v_ph_slot; acao:='UPDATE placeholder->pkg'; v_tgt:=v_ph_id; v_first_pkg:=true; v_eidx:=greatest(v_eidx,v_phnum);
        IF NOT p_dry THEN
          UPDATE product_kit_components SET component_name=v_nm, component_type_code=coalesce(v_type,'CAIXA'),
                 component_code=CASE WHEN v_legacy THEN p_sku||'-'||v_ph_slot ELSE component_code END,
                 component_sku =CASE WHEN v_legacy THEN p_sku||'-'||v_ic||'-'||v_ph_slot ELSE component_sku END,
                 pkg_ext_height_mm=v_a, pkg_ext_width_mm=v_l, pkg_ext_length_mm=v_pp, dim_source='ficha', dim_source_url=r.source_url WHERE id=v_ph_id;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_ph_id, product_id=v_kid,
                 piece_kind='packaging', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:placeholder pkg' WHERE id=r.sid;
        END IF;
      ELSE
        v_eidx:=v_eidx+1; IF v_ph_pkg AND v_eidx=v_phnum THEN v_eidx:=v_eidx+1; END IF;
        slot:='E'||v_eidx; acao:='INSERT pkg'; v_code:=p_sku||'-'||slot; v_csku:=p_sku||'-'||v_ic||'-'||slot;
        IF NOT p_dry THEN
          INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
            is_packaging,quantity,is_standalone_sellable,pkg_ext_height_mm,pkg_ext_width_mm,pkg_ext_length_mm,dim_source,dim_source_url)
          VALUES (v_kid,v_nm,coalesce(v_type,'CAIXA'),slot,v_code,v_csku,true,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_tgt, product_id=v_kid,
                 piece_kind='packaging', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:novo pkg' WHERE id=r.sid;
        END IF;
      END IF;
    END IF;

    tipo:=v_type; nome:=v_nm; a:=v_a; l:=v_l; p:=v_pp; RETURN NEXT;
  END LOOP;
END $_$;


ALTER FUNCTION "public"."fn_decompose_kit_from_ficha"("p_sku" "text", "p_dry" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_deferred_dar_quote_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _old_quote_id uuid;
  _new_quote_id uuid;
BEGIN
  IF TG_OP <> 'INSERT' THEN _old_quote_id := OLD.quote_id; END IF;
  IF TG_OP <> 'DELETE' THEN _new_quote_id := NEW.quote_id; END IF;

  IF _old_quote_id IS NOT NULL THEN
    PERFORM public.assert_quote_discount_integrity(_old_quote_id);
  END IF;
  IF _new_quote_id IS NOT NULL AND _new_quote_id IS DISTINCT FROM _old_quote_id THEN
    PERFORM public.assert_quote_discount_integrity(_new_quote_id);
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_deferred_dar_quote_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_deferred_quote_discount_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _old_quote_id uuid;
  _new_quote_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'quotes' THEN
    PERFORM public.assert_quote_discount_integrity(COALESCE(NEW.id, OLD.id));
    RETURN NULL;
  END IF;

  IF TG_TABLE_NAME = 'quote_items' THEN
    IF TG_OP <> 'INSERT' THEN _old_quote_id := OLD.quote_id; END IF;
    IF TG_OP <> 'DELETE' THEN _new_quote_id := NEW.quote_id; END IF;
  ELSE
    IF TG_OP <> 'INSERT' THEN
      SELECT qi.quote_id INTO _old_quote_id
      FROM public.quote_items qi WHERE qi.id = OLD.quote_item_id;
    END IF;
    IF TG_OP <> 'DELETE' THEN
      SELECT qi.quote_id INTO _new_quote_id
      FROM public.quote_items qi WHERE qi.id = NEW.quote_item_id;
    END IF;
  END IF;

  IF _old_quote_id IS NOT NULL THEN
    PERFORM public.assert_quote_discount_integrity(_old_quote_id);
  END IF;
  IF _new_quote_id IS NOT NULL AND _new_quote_id IS DISTINCT FROM _old_quote_id THEN
    PERFORM public.assert_quote_discount_integrity(_new_quote_id);
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_deferred_quote_discount_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_deploy_readiness_check"() RETURNS TABLE("check_name" "text", "check_status" "text", "severity" "text", "details" "text", "recommendation" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 'cron_jobs_healthy'::text,
    (CASE WHEN COALESCE(failures, 0) = 0 THEN '✅ OK' ELSE '❌ FAIL' END)::text,
    'critical'::text,
    ('Falhas última hora: ' || COALESCE(failures, 0)::text)::text,
    (CASE WHEN COALESCE(failures, 0) > 0 THEN 'Investigar cron.job_run_details' ELSE 'OK' END)::text
  FROM (
    SELECT COUNT(*) AS failures FROM cron.job_run_details d
    WHERE d.start_time > now() - interval '1 hour' AND d.status='failed'
  ) t;

  RETURN QUERY
  SELECT 'no_orphan_variants'::text,
    (CASE WHEN orphans = 0 THEN '✅ OK' ELSE '❌ FAIL' END)::text,
    'critical'::text,
    ('Variants órfãs: ' || orphans::text)::text,
    (CASE WHEN orphans > 0 THEN 'DELETE órfãs' ELSE 'OK' END)::text
  FROM (
    SELECT COUNT(*) AS orphans FROM product_variants pv
    WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.id = pv.product_id)
  ) t;

  RETURN QUERY
  SELECT 'stock_cache_positive'::text,
    (CASE WHEN negativos = 0 THEN '✅ OK' ELSE '❌ FAIL' END)::text,
    'critical'::text,
    ('Produtos com stock negativo: ' || negativos::text)::text,
    (CASE WHEN negativos > 0 THEN 'Rodar fn_sync_product_stock_cache' ELSE 'OK' END)::text
  FROM (SELECT COUNT(*) AS negativos FROM products WHERE stock_quantity < 0) t;

  RETURN QUERY
  SELECT 'rls_coverage'::text,
    (CASE WHEN sem_rls = 0 THEN '✅ OK' ELSE '⚠️ ATENÇÃO' END)::text,
    'critical'::text,
    ('Tabelas sem RLS: ' || sem_rls::text)::text,
    (CASE WHEN sem_rls > 0 THEN 'ALTER TABLE ENABLE RLS' ELSE 'OK' END)::text
  FROM (
    SELECT COUNT(*) AS sem_rls
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relkind = 'r' AND NOT c.relrowsecurity
  ) t;

  RETURN QUERY
  SELECT 'users_have_profile'::text,
    (CASE WHEN orfaos = 0 THEN '✅ OK' ELSE '⚠️ ATENÇÃO' END)::text,
    'high'::text,
    ('Users sem profile: ' || orfaos::text)::text,
    (CASE WHEN orfaos > 0 THEN 'Verificar handle_new_user' ELSE 'OK' END)::text
  FROM (
    SELECT COUNT(*) AS orfaos FROM auth.users u
    WHERE NOT EXISTS (SELECT 1 FROM profiles p WHERE p.id = u.id)
  ) t;

  RETURN QUERY
  SELECT 'seo_redirects_unique_index'::text,
    (CASE WHEN existe = 1 THEN '✅ OK' ELSE '❌ FAIL' END)::text,
    'critical'::text,
    (CASE WHEN existe = 1 THEN 'uq_seo_redirects_source_active presente'
          ELSE 'AUSENTE - trigger quebra' END)::text,
    (CASE WHEN existe = 0 
      THEN 'CREATE UNIQUE INDEX uq_seo_redirects_source_active'
      ELSE 'OK' END)::text
  FROM (
    SELECT COUNT(*) AS existe FROM pg_indexes
    WHERE indexname = 'uq_seo_redirects_source_active' AND tablename='seo_redirects'
  ) t;

  RETURN QUERY
  SELECT 'fiscal_ncm_coverage'::text,
    (CASE WHEN sem_ncm = 0 THEN '✅ OK' ELSE '❌ FAIL' END)::text,
    'critical'::text,
    ('Produtos ativos sem NCM: ' || sem_ncm::text)::text,
    (CASE WHEN sem_ncm > 0 THEN 'UPDATE ncm_code' ELSE 'OK' END)::text
  FROM (
    SELECT COUNT(*) AS sem_ncm FROM products p
    WHERE p.is_active AND (p.ncm_code IS NULL OR p.ncm_id IS NULL)
  ) t;

  RETURN QUERY
  SELECT 'health_score_min'::text,
    (CASE WHEN score::numeric >= 90 THEN '✅ OK' ELSE '⚠️ ATENÇÃO' END)::text,
    'high'::text,
    ('Score: ' || score || ' - ' || grade)::text,
    (CASE WHEN score::numeric >= 90 THEN 'OK' ELSE 'fn_calculate_health_score' END)::text
  FROM fn_calculate_health_score();

  RETURN QUERY
  SELECT 'smoke_tests_pass'::text,
    (CASE WHEN falhas = 0 THEN '✅ OK' ELSE '❌ FAIL' END)::text,
    'critical'::text,
    ('Smoke tests falhando: ' || falhas::text || '/12')::text,
    (CASE WHEN falhas > 0 THEN 'fn_run_smoke_tests' ELSE 'OK' END)::text
  FROM (
    SELECT COUNT(*) AS falhas FROM fn_run_smoke_tests() s WHERE s.result NOT LIKE '%PASS%'
  ) t;

  RETURN QUERY
  SELECT 'zero_critical_alerts'::text,
    (CASE WHEN criticos = 0 THEN '✅ OK' ELSE '❌ FAIL' END)::text,
    'critical'::text,
    ('Alertas críticos ativos: ' || criticos::text)::text,
    (CASE WHEN criticos > 0 THEN 'v_system_alerts' ELSE 'OK' END)::text
  FROM (
    SELECT COUNT(*) AS criticos FROM v_system_alerts a WHERE a.severidade = 'critical'
  ) t;

  RETURN QUERY
  SELECT 'audit_recency'::text,
    (CASE WHEN ultima IS NULL THEN '⚠️ SEM AUDIT'
         WHEN now() - ultima < interval '30 days' THEN '✅ OK'
         ELSE '⚠️ DESATUALIZADA' END)::text,
    'medium'::text,
    ('Última auditoria: ' || COALESCE(ultima::text, 'nunca'))::text,
    (CASE WHEN ultima IS NULL OR now() - ultima > interval '30 days'
      THEN 'Rodar nova bateria' ELSE 'OK' END)::text
  FROM (
    SELECT MAX(r.executed_at) AS ultima FROM prod_audit.test_results r
  ) t;
END;
$$;


ALTER FUNCTION "public"."fn_deploy_readiness_check"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_deploy_readiness_check"() IS '11 verificações obrigatórias antes de deploy. Criada na auditoria pre-prod 23/04/2026.';



CREATE OR REPLACE FUNCTION "public"."fn_dequeue_ai_enrichment"("p_batch_size" integer DEFAULT 100, "p_locked_by" "text" DEFAULT 'n8n'::"text", "p_enrichment_type" "text" DEFAULT 'all'::"text") RETURNS TABLE("queue_id" "uuid", "product_id" "uuid", "product_name" "text", "sku" "text", "supplier_ref" "text", "description" "text", "short_desc" "text", "brand" "text", "materials" "jsonb", "dimensions_display" "text", "capacity_ml" integer, "weight_g" integer, "allows_person" boolean, "category_id" "uuid", "category_name" "text", "category_path" "text", "ai_version_current" integer, "ai_title_exists" boolean, "ai_description_exists" boolean, "ai_summary_exists" boolean, "schema_exists" boolean, "enrichment_type" "text", "copywriting_config" "jsonb", "raw_data_snapshot" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH dequeued AS (
    UPDATE ai_enrichment_queue q
    SET
      status          = 'processing',
      locked_at       = now(),
      locked_by       = p_locked_by,
      last_attempt_at = now(),
      attempts        = q.attempts + 1,
      updated_at      = now()
    WHERE q.id IN (
      SELECT iq.id FROM ai_enrichment_queue iq
      WHERE iq.status = 'pending'
        AND iq.attempts < iq.max_attempts
        AND (p_enrichment_type = 'all' OR iq.enrichment_type = p_enrichment_type)
      ORDER BY iq.priority ASC, iq.created_at ASC
      LIMIT p_batch_size   -- ✅ CORRIGIDO: respeita exatamente o que o caller passa
      FOR UPDATE SKIP LOCKED
    )
    RETURNING q.id, q.product_id, q.enrichment_type AS q_enrichment_type
  )
  SELECT
    d.id,
    p.id,
    p.name::TEXT,
    p.sku::TEXT,
    p.supplier_reference::TEXT,
    p.description::TEXT,
    p.short_description::TEXT,
    p.brand::TEXT,
    p.materials,
    COALESCE(p.dimensions_display, p.combined_sizes)::TEXT,
    p.capacity_ml,
    p.weight_g,
    COALESCE(p.allows_personalization, false),
    COALESCE(p.main_category_id, p.category_id),
    c.name::TEXT,
    c.full_path_readable::TEXT,
    COALESCE(p.ai_version, 0),
    (p.ai_title IS NOT NULL AND LENGTH(TRIM(COALESCE(p.ai_title,''))) > 0),
    (p.ai_description IS NOT NULL AND LENGTH(TRIM(COALESCE(p.ai_description,''))) > 0),
    (p.ai_summary IS NOT NULL AND LENGTH(TRIM(COALESCE(p.ai_summary,''))) > 0),
    (p.schema_json IS NOT NULL),
    d.q_enrichment_type::TEXT,
    public.get_copywriting_config(COALESCE(p.main_category_id, p.category_id)),
    jsonb_strip_nulls(jsonb_build_object(
      'Area1',                    COALESCE(spr.raw_data->>'Area1',             p.engraving_type),
      'Area2',                    spr.raw_data->>'Area2',
      'CustomizationTypes',       COALESCE(spr.raw_data->>'CustomizationTypes', p.engraving_type),
      'CustomizationDefaultType', spr.raw_data->>'CustomizationDefaultType',
      'DefaultCustomization',     COALESCE(spr.raw_data->>'DefaultCustomization', p.engraving_description),
      'ProductComponents',        spr.raw_data->>'ProductComponents',
      'ProductCertifications',    spr.raw_data->>'ProductCertifications',
      'Certificates',             spr.raw_data->>'Certificates',
      'Materials',                COALESCE(spr.raw_data->>'Materials', p.materials::text),
      'Capacity',                 spr.raw_data->>'Capacity',
      'WeightGr',                 spr.raw_data->>'WeightGr',
      'KeyWords',                 spr.raw_data->>'KeyWords',
      'Properties',               spr.raw_data->>'Properties',
      'Type',                     COALESCE(spr.raw_data->>'Type',          p.supplier_type),
      'SubType',                  COALESCE(spr.raw_data->>'SubType',       p.supplier_subtype),
      'CountryOfOrigin',          COALESCE(spr.raw_data->>'CountryOfOrigin', p.origin_country),
      'Brand',                    COALESCE(spr.raw_data->>'Brand',            p.brand),
      'CombinedSizes',            COALESCE(spr.raw_data->>'CombinedSizes',
                                            p.combined_sizes, p.dimensions_display),
      'EngravingType',            p.engraving_type,
      'SupplierCode',             s.code,
      'SupplierReference',        p.supplier_reference,
      'MinQuantity',              p.min_quantity,
      'PackingType',              p.packing_type,
      'OgImageUrl',               p.og_image_url
    ))
  FROM dequeued d
  JOIN products  p ON p.id = d.product_id
  JOIN suppliers s ON s.id = p.supplier_id
  LEFT JOIN LATERAL (
    SELECT spr2.*
    FROM supplier_products_raw spr2
    WHERE spr2.product_id = p.id AND spr2.raw_data IS NOT NULL
    ORDER BY spr2.updated_at DESC, spr2.id DESC LIMIT 1
  ) spr ON true
  LEFT JOIN categories c ON c.id = COALESCE(p.main_category_id, p.category_id);
END;
$$;


