Campos canônicos adicionados: EngravingType, SupplierCode, SupplierReference, MinQuantity, PackingType, OgImageUrl.
Taxonomia Type/SubType agora populada para todos os fornecedores via supplier_type/supplier_subtype do Gold.';



CREATE OR REPLACE FUNCTION "public"."fn_derive_parent_ref"("p_supplier_id" "uuid", "p_variant_ref" "text", "p_raw" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $_$
BEGIN
  IF p_variant_ref IS NULL OR TRIM(p_variant_ref) = '' THEN
    RETURN NULL;
  END IF;

  -- Spot | Stricker
  IF p_supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0' THEN
    RETURN COALESCE(NULLIF(TRIM(p_raw->>'ProdReference'), ''), p_variant_ref);
  END IF;

  -- XBZ Brindes
  IF p_supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900' THEN
    RETURN COALESCE(NULLIF(TRIM(p_raw->>'CodigoAmigavel'), ''),
                   regexp_replace(p_variant_ref, '-[^-]*$', ''));
  END IF;

  -- Asia Import: usa raw_data->>'referencia' quando está presente E é diferente da variante.
  -- Esse campo foi corrigido na migration asia_bronze_fix_referencia_pai (antes era == var).
  -- Fallback: heurística sufixo-P para registros legados/descontinuados sem o campo.
  IF p_supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118' THEN
    IF p_raw IS NOT NULL
       AND NULLIF(TRIM(p_raw->>'referencia'), '') IS NOT NULL
       AND (p_raw->>'referencia') IS DISTINCT FROM p_variant_ref THEN
      RETURN TRIM(p_raw->>'referencia');
    END IF;
    -- fallback heurístico
    IF position('-' IN p_variant_ref) > 0 THEN
      RETURN regexp_replace(p_variant_ref, '-[^-]*$', '');
    ELSE
      RETURN p_variant_ref || 'P';
    END IF;
  END IF;

  -- Só Marcas: 1:1
  IF p_supplier_id = '841cd690-210a-422a-908c-7676828db272' THEN
    RETURN p_variant_ref;
  END IF;

  -- Demais: corte no último hífen
  IF position('-' IN p_variant_ref) > 0 THEN
    RETURN regexp_replace(p_variant_ref, '-[^-]*$', '');
  END IF;
  RETURN p_variant_ref;
END;
$_$;


ALTER FUNCTION "public"."fn_derive_parent_ref"("p_supplier_id" "uuid", "p_variant_ref" "text", "p_raw" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_derive_parent_ref"("p_supplier_id" "uuid", "p_variant_ref" "text", "p_raw" "jsonb") IS 'Deriva referência do produto-pai. Asia: usa raw_data->>''referencia'' (corrigido em
   asia_bronze_fix_referencia_pai) com fallback heurístico sufixo-P. XBZ: CodigoAmigavel.
   Spot: ProdReference. Só Marcas: 1:1. Demais: corte-hífen.';



CREATE OR REPLACE FUNCTION "public"."fn_derive_similarity_pairs_on_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM product_similarity_groups
    WHERE id = NEW.group_id AND is_active = true
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO product_relationships
    (product_id, related_product_id, relationship_type, is_bidirectional, is_active, display_order)
  SELECT NEW.product_id, m.product_id, 'similar', true, true, 0
  FROM product_similarity_group_members m
  WHERE m.group_id = NEW.group_id
    AND m.product_id != NEW.product_id
    AND m.supplier_id != NEW.supplier_id
  ON CONFLICT (product_id, related_product_id, relationship_type) DO NOTHING;

  INSERT INTO product_relationships
    (product_id, related_product_id, relationship_type, is_bidirectional, is_active, display_order)
  SELECT m.product_id, NEW.product_id, 'similar', true, true, 0
  FROM product_similarity_group_members m
  WHERE m.group_id = NEW.group_id
    AND m.product_id != NEW.product_id
    AND m.supplier_id != NEW.supplier_id
  ON CONFLICT (product_id, related_product_id, relationship_type) DO NOTHING;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_derive_similarity_pairs_on_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_detecta_familia_cor"("p_r" integer, "p_g" integer, "p_b" integer) RETURNS character varying
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_familia VARCHAR(20);
    v_max INTEGER;
    v_min INTEGER;
    v_hue FLOAT;
    v_saturation FLOAT;
    v_lightness FLOAT;
BEGIN
    -- Calcular valores para determinar a cor
    v_max := GREATEST(p_r, p_g, p_b);
    v_min := LEAST(p_r, p_g, p_b);
    v_lightness := (v_max + v_min) / 2.0 / 255.0;
    
    -- Se muito claro ou escuro, neutro
    IF v_max - v_min < 20 THEN
        RETURN 'neutro';
    END IF;
    
    -- Calcular saturação
    IF v_lightness <= 0.5 THEN
        v_saturation := (v_max - v_min)::FLOAT / (v_max + v_min)::FLOAT;
    ELSE
        v_saturation := (v_max - v_min)::FLOAT / (510 - v_max - v_min)::FLOAT;
    END IF;
    
    -- Se baixa saturação, neutro ou marrom/bege
    IF v_saturation < 0.15 THEN
        IF v_lightness > 0.6 THEN
            RETURN 'bege';
        ELSIF v_lightness < 0.3 THEN
            RETURN 'neutro';
        ELSE
            RETURN 'marrom';
        END IF;
    END IF;
    
    -- Calcular matiz (hue)
    IF v_max = v_min THEN
        v_hue := 0;
    ELSIF v_max = p_r THEN
        v_hue := 60 * ((p_g - p_b)::FLOAT / (v_max - v_min)::FLOAT);
    ELSIF v_max = p_g THEN
        v_hue := 60 * (2 + (p_b - p_r)::FLOAT / (v_max - v_min)::FLOAT);
    ELSE
        v_hue := 60 * (4 + (p_r - p_g)::FLOAT / (v_max - v_min)::FLOAT);
    END IF;
    
    IF v_hue < 0 THEN
        v_hue := v_hue + 360;
    END IF;
    
    -- Classificar por matiz
    IF v_hue >= 0 AND v_hue < 20 THEN
        v_familia := 'vermelho';
    ELSIF v_hue >= 20 AND v_hue < 45 THEN
        v_familia := 'laranja';
    ELSIF v_hue >= 45 AND v_hue < 70 THEN
        v_familia := 'amarelo';
    ELSIF v_hue >= 70 AND v_hue < 150 THEN
        v_familia := 'verde';
    ELSIF v_hue >= 150 AND v_hue < 200 THEN
        v_familia := 'ciano';
    ELSIF v_hue >= 200 AND v_hue < 260 THEN
        v_familia := 'azul';
    ELSIF v_hue >= 260 AND v_hue < 290 THEN
        v_familia := 'roxo';
    ELSIF v_hue >= 290 AND v_hue < 330 THEN
        IF v_saturation > 0.5 THEN
            v_familia := 'magenta';
        ELSE
            v_familia := 'rosa';
        END IF;
    ELSE
        v_familia := 'vermelho';
    END IF;
    
    RETURN v_familia;
END;
$$;


ALTER FUNCTION "public"."fn_detecta_familia_cor"("p_r" integer, "p_g" integer, "p_b" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_display_product_name"("p_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  s text;
  seg text;
  parts text[];
  i int;
  pairs text[][] := ARRAY[
    ARRAY['(\d)l\M','\1L'], ARRAY['(\d)d\M','\1D'], ARRAY['(\d)t\M','\1T'],
    ARRAY['(\d)w\M','\1W'], ARRAY['(\d)v\M','\1V'], ARRAY['(\d)gb\M','\1GB'],
    ARRAY['(\d)mah\M','\1mAh'],
    ARRAY['\ma([3-6])\M','A\1'], ARRAY['\mb([5-6])\M','B\1'],
    ARRAY['\musb\M','USB'], ARRAY['\mled\M','LED'], ARRAY['\mabs\M','ABS'],
    ARRAY['\mpvc\M','PVC'], ARRAY['\mpu\M','PU'],   ARRAY['\mpp\M','PP'],
    ARRAY['\mrpet\M','RPET'], ARRAY['\mpet\M','PET'], ARRAY['\meva\M','EVA'],
    ARRAY['\mmdf\M','MDF'], ARRAY['\mtnt\M','TNT'], ARRAY['\muv\M','UV'],
    ARRAY['\mgps\M','GPS'], ARRAY['\mnfc\M','NFC'], ARRAY['\mlcd\M','LCD'],
    ARRAY['\mrgb\M','RGB'], ARRAY['\mcob\M','COB'], ARRAY['\mtv\M','TV'],
    ARRAY['\mfm\M','FM'], ARRAY['\mgg\M','GG'], ARRAY['\mxg\M','XG']
  ];
  pr text[];
BEGIN
  IF p_name IS NULL THEN RETURN NULL; END IF;
  s := btrim(regexp_replace(
         translate(
           replace(replace(replace(replace(p_name, chr(8203),''), chr(8204),''), chr(8205),''), chr(65279),''),
           chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288),
           repeat(' ', 18)),
         '\s+', ' ', 'g'));
  IF s = '' THEN RETURN NULL; END IF;
  s := lower(s);
  -- sentence-case por segmento: capitaliza início e após '. '
  parts := string_to_array(s, '. ');
  FOR i IN 1..COALESCE(array_length(parts,1),0) LOOP
    seg := parts[i];
    IF seg <> '' THEN
      parts[i] := upper(left(seg,1)) || substr(seg,2);
    END IF;
  END LOOP;
  s := array_to_string(parts, '. ');
  FOREACH pr SLICE 1 IN ARRAY pairs LOOP
    s := regexp_replace(s, pr[1], pr[2], 'gi');
  END LOOP;
  s := upper(left(s,1)) || substr(s,2);
  RETURN s;
END;
$$;


ALTER FUNCTION "public"."fn_display_product_name"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_distribute_percentage"("p_total" numeric DEFAULT 100.0, "p_count" integer DEFAULT 1) RETURNS numeric[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_base NUMERIC;
    v_result NUMERIC[] := '{}';
    v_sum NUMERIC := 0;
    i INTEGER;
BEGIN
    IF p_count <= 0 THEN RETURN ARRAY[p_total]; END IF;
    IF p_count = 1 THEN RETURN ARRAY[p_total]; END IF;
    v_base := FLOOR(p_total / p_count * 100) / 100;
    FOR i IN 1..(p_count - 1) LOOP
        v_result := array_append(v_result, v_base);
        v_sum := v_sum + v_base;
    END LOOP;
    v_result := array_append(v_result, ROUND(p_total - v_sum, 2));
    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_distribute_percentage"("p_total" numeric, "p_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_dryrun_raw_v2"("p_supplier_id" "uuid", "p_parents" integer DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pkey_field text;
  v_keys       text[];
  v_before     jsonb;
  v_after      jsonb;
  v_engine     jsonb;
  v_out        jsonb;
BEGIN
  SELECT parent_key_source INTO v_pkey_field FROM supplier_settings WHERE supplier_id=p_supplier_id;
  IF v_pkey_field IS NULL THEN RETURN jsonb_build_object('error','sem parent_key_source'); END IF;

  SELECT array_agg(pkey) INTO v_keys FROM (
     SELECT raw_data->>v_pkey_field AS pkey
       FROM supplier_products_raw
      WHERE supplier_id=p_supplier_id AND NULLIF(raw_data->>v_pkey_field,'') IS NOT NULL
      GROUP BY raw_data->>v_pkey_field HAVING count(*) > 1
      ORDER BY count(*) DESC LIMIT p_parents
  ) t;

  SELECT jsonb_object_agg(ref, jsonb_build_object(
            'name',name,'brand',brand,'origin',origin,'box_w',box_w,'box_q',box_q,
            'pack_class',pack_class,'main_cat',main_cat,'is_active',is_active,
            'n_locked',n_locked,'n_variantes',nv,'amostra',amostra)) INTO v_before
  FROM (
     SELECT p.supplier_reference ref, p.name, p.brand, p.origin_country origin,
            p.box_weight_kg box_w, p.box_quantity box_q, p.packing_classification pack_class,
            p.main_category_id main_cat, p.is_active,
            COALESCE(array_length(p.locked_fields,1),0) n_locked,
            (SELECT count(*) FROM product_variants v WHERE v.product_id=p.id) nv,
            (SELECT jsonb_agg(jsonb_build_object('sku',x.sku,'sup_sku',x.supplier_sku,'cor',x.color_name,'attrs',x.attributes))
               FROM (SELECT sku,supplier_sku,color_name,attributes FROM product_variants
                      WHERE product_id=p.id ORDER BY sku LIMIT 2) x) amostra
       FROM products p WHERE p.supplier_id=p_supplier_id AND p.supplier_reference=ANY(v_keys)
  ) q;

  BEGIN
     UPDATE supplier_products_raw SET status='pending'::supplier_raw_status
      WHERE supplier_id=p_supplier_id AND raw_data->>v_pkey_field = ANY(v_keys);

     v_engine := fn_process_raw_v2(p_supplier_id, p_parents + 10);

     SELECT jsonb_object_agg(ref, jsonb_build_object(
               'name',name,'brand',brand,'origin',origin,'box_w',box_w,'box_q',box_q,
               'pack_class',pack_class,'main_cat',main_cat,'is_active',is_active,
               'n_locked',n_locked,'n_variantes',nv,'amostra',amostra)) INTO v_after
     FROM (
        SELECT p.supplier_reference ref, p.name, p.brand, p.origin_country origin,
               p.box_weight_kg box_w, p.box_quantity box_q, p.packing_classification pack_class,
               p.main_category_id main_cat, p.is_active,
               COALESCE(array_length(p.locked_fields,1),0) n_locked,
               (SELECT count(*) FROM product_variants v WHERE v.product_id=p.id) nv,
               (SELECT jsonb_agg(jsonb_build_object('sku',x.sku,'sup_sku',x.supplier_sku,'cor',x.color_name,'attrs',x.attributes))
                  FROM (SELECT sku,supplier_sku,color_name,attributes FROM product_variants
                         WHERE product_id=p.id ORDER BY sku LIMIT 2) x) amostra
          FROM products p WHERE p.supplier_id=p_supplier_id AND p.supplier_reference=ANY(v_keys)
     ) q;

     v_out := jsonb_build_object('keys',to_jsonb(v_keys),'engine',v_engine,'before',v_before,'after',v_after);
     RAISE EXCEPTION 'DRYRUN_ROLLBACK';
  EXCEPTION WHEN OTHERS THEN
     IF SQLERRM <> 'DRYRUN_ROLLBACK' THEN
        v_out := jsonb_build_object('keys',to_jsonb(v_keys),'erro_motor',SQLERRM,'before',v_before);
     END IF;
  END;
  RETURN v_out;
END $$;


ALTER FUNCTION "public"."fn_dryrun_raw_v2"("p_supplier_id" "uuid", "p_parents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_dryrun_standardize_supplier"("p_supplier_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_preview jsonb;
  v_detail  text;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;

  BEGIN
    PERFORM set_config('app.write_source', 'pipeline', true);

    v_preview := jsonb_build_object(
      'standardize', public.fn_standardize_supplier(p_supplier_id, p_limit));

    v_preview := v_preview || jsonb_build_object(
      'silver_depois', jsonb_build_object(
        'pais_standardized', (SELECT COUNT(*) FROM public.produtos_padronizacao
           WHERE supplier_id=p_supplier_id AND status='standardized'),
        'pais_rejected', (SELECT COUNT(*) FROM public.produtos_padronizacao
           WHERE supplier_id=p_supplier_id AND status='rejected'),
        'variantes_standardized', (SELECT COUNT(*) FROM public.produtos_padronizacao_variantes
           WHERE supplier_id=p_supplier_id AND status='standardized'),
        'amostra_rejeitados', (SELECT jsonb_agg(jsonb_build_object(
             'ref', p.supplier_reference, 'erros', p.validation_errors))
           FROM (SELECT supplier_reference, validation_errors
                 FROM public.produtos_padronizacao
                 WHERE supplier_id=p_supplier_id AND status='rejected'
                 ORDER BY updated_at DESC LIMIT 5) p)));

    RAISE EXCEPTION 'DRYRUN_ROLLBACK' USING DETAIL = v_preview::text;

  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM = 'DRYRUN_ROLLBACK' THEN
      GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
      RETURN jsonb_build_object(
        'success', true, 'dry_run', true, 'reverted', true,
        'supplier_id', p_supplier_id, 'preview', v_detail::jsonb);
    END IF;
    RETURN jsonb_build_object(
      'success', false, 'dry_run', true, 'reverted', true,
      'supplier_id', p_supplier_id, 'error', SQLERRM);
  END;
END;
$$;


ALTER FUNCTION "public"."fn_dryrun_standardize_supplier"("p_supplier_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_dryrun_standardize_supplier"("p_supplier_id" "uuid", "p_limit" integer) IS 'Dry-run REAL do Bronze->Silver: executa fn_standardize_supplier numa subtransação, coleta preview (contagens + amostra de rejeitados) e REVERTE tudo via exceção sentinela. 2026-06-11: antes escrevia no Silver apesar do nome.';



