CREATE OR REPLACE FUNCTION "public"."fn_enqueue_ai_enrichment"("p_enrichment_type" "text" DEFAULT 'all'::"text", "p_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 5000, "p_priority" integer DEFAULT 5, "p_force_version_zero" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_inserted  INTEGER := 0;
    v_reset     INTEGER := 0;
    v_skipped   INTEGER := 0;
    v_start     TIMESTAMPTZ := clock_timestamp();
BEGIN
    -- ─────────────────────────────────────────────────────────
    -- 1. Inserir novos produtos pendentes
    -- ─────────────────────────────────────────────────────────
    WITH eligible AS (
        SELECT p.id AS product_id
        FROM products p
        WHERE p.is_active  = true
          AND p.is_deleted = false
          AND p.name IS NOT NULL
          AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
          AND (
            -- Condição principal por tipo
            CASE p_enrichment_type
              WHEN 'ai_title' THEN
                (p.ai_title IS NULL OR LENGTH(TRIM(p.ai_title)) = 0
                 OR (p_force_version_zero AND p.ai_version = 0))
              WHEN 'ai_description' THEN
                (p.ai_description IS NULL OR LENGTH(TRIM(p.ai_description)) = 0
                 OR (p_force_version_zero AND p.ai_version = 0))
              WHEN 'ai_summary' THEN
                (p.ai_summary IS NULL OR LENGTH(TRIM(p.ai_summary)) = 0)
              WHEN 'schema_json' THEN
                p.schema_json IS NULL
              WHEN 'all' THEN (
                (p.ai_title IS NULL OR LENGTH(TRIM(p.ai_title)) = 0
                 OR (p_force_version_zero AND p.ai_version = 0))
                OR (p.ai_description IS NULL OR LENGTH(TRIM(p.ai_description)) = 0)
                OR (p.ai_summary IS NULL OR LENGTH(TRIM(p.ai_summary)) = 0)
                OR p.schema_json IS NULL
              )
              ELSE true
            END
          )
        LIMIT p_limit
    )
    INSERT INTO ai_enrichment_queue
        (product_id, enrichment_type, status, priority, attempts, max_attempts)
    SELECT
        e.product_id,
        p_enrichment_type,
        'pending',
        p_priority,
        0,
        3
    FROM eligible e
    ON CONFLICT (product_id, enrichment_type) DO UPDATE
        -- Resetar produtos com erro para tentar novamente
        SET status      = CASE
                            WHEN EXCLUDED.status = 'pending'
                             AND ai_enrichment_queue.status = 'error'
                            THEN 'pending'
                            ELSE ai_enrichment_queue.status
                          END,
            priority    = CASE
                            WHEN ai_enrichment_queue.status = 'error'
                            THEN EXCLUDED.priority
                            ELSE ai_enrichment_queue.priority
                          END,
            attempts    = CASE
                            WHEN ai_enrichment_queue.status = 'error'
                            THEN 0
                            ELSE ai_enrichment_queue.attempts
                          END,
            updated_at  = CASE
                            WHEN ai_enrichment_queue.status = 'error'
                            THEN now()
                            ELSE ai_enrichment_queue.updated_at
                          END;

    GET DIAGNOSTICS v_inserted = ROW_COUNT;

    -- ─────────────────────────────────────────────────────────
    -- 2. Contar status da fila
    -- ─────────────────────────────────────────────────────────
    SELECT
        COUNT(*) FILTER (WHERE status = 'pending')    INTO v_skipped
    FROM ai_enrichment_queue
    WHERE enrichment_type = p_enrichment_type;

    RETURN jsonb_build_object(
        'success',          true,
        'upserted',         v_inserted,
        'pending_in_queue', v_skipped,
        'enrichment_type',  p_enrichment_type,
        'force_v0',         p_force_version_zero,
        'duration_ms',      EXTRACT(MILLISECONDS FROM (clock_timestamp() - v_start))::INTEGER
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'state', SQLSTATE);
END;
$$;


ALTER FUNCTION "public"."fn_enqueue_ai_enrichment"("p_enrichment_type" "text", "p_supplier_id" "uuid", "p_limit" integer, "p_priority" integer, "p_force_version_zero" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_enqueue_ai_enrichment"("p_enrichment_type" "text", "p_supplier_id" "uuid", "p_limit" integer, "p_priority" integer, "p_force_version_zero" boolean) IS 'v2 — Enfileira produtos para enriquecimento AI.
     p_force_version_zero=true (default) inclui produtos com ai_version=0 mesmo com campos preenchidos.
     ON CONFLICT reseta status=error para status=pending automaticamente.';



CREATE OR REPLACE FUNCTION "public"."fn_enrich_asia_components_batch"("p_items" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item   JSONB;
  v_rid    UUID;
  v_pad_id UUID;
  v_count  INTEGER := 0;
BEGIN
  FOR v_item IN SELECT jsonb_array_elements(p_items)
  LOOP
    BEGIN
      v_rid := fn_extract_dimensions_from_text(
        (v_item->>'component_id')::UUID,
        'asia_api:' || COALESCE(v_item->>'source',''),
        jsonb_strip_nulls(jsonb_build_object(
          'unit',        'mm',
          'length_mm',   (v_item->>'length_mm')::INTEGER,
          'width_mm',    (v_item->>'width_mm')::INTEGER,
          'height_mm',   (v_item->>'height_mm')::INTEGER,
          'diameter_mm', (v_item->>'diameter_mm')::INTEGER,
          'weight_g',    (v_item->>'weight_g')::INTEGER,
          'shape_type',  COALESCE(v_item->>'shape_type','rectangular'),
          'is_packaging', (v_item->>'is_packaging')::BOOLEAN,
          'source_field', 'asia_api'
        )),
        0.85
      );
      IF v_rid IS NOT NULL THEN
        PERFORM fn_standardize_kit_component(v_rid);
        UPDATE kit_component_padronizacao
        SET padronizacao_status='approved', reviewed_at=NOW()
        WHERE raw_id=v_rid AND padronizacao_status='pending';
        SELECT id INTO v_pad_id FROM kit_component_padronizacao
        WHERE raw_id=v_rid AND padronizacao_status='approved' LIMIT 1;
        IF v_pad_id IS NOT NULL THEN
          PERFORM fn_promote_kit_component_padronizacao(v_pad_id);
          v_count := v_count + 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_enrich_asia_components_batch"("p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enrich_commercial_xbz"("p_commercial" "jsonb") RETURNS TABLE("vss_atualizadas" integer, "produtos_rollup" integer, "sem_match" integer, "recebidos" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_sup uuid; v_upd int:=0; v_roll int:=0; v_nomatch int:=0;
BEGIN
  SELECT id INTO v_sup FROM public.suppliers WHERE code='XBZ' LIMIT 1;
  IF v_sup IS NULL THEN RAISE EXCEPTION 'XBZ nao encontrado'; END IF;

  -- 1) VSS: VendaMinima->min_order_qty, Multiplos->sale_multiplier, IpiTaxa->supplier_ipi_rate
  WITH inp AS (
    SELECT e->>'CodigoXbz' AS cx,
           GREATEST(COALESCE((e->>'VendaMinima')::int,1),1) AS vmin,
           GREATEST(COALESCE((e->>'Multiplos')::int,1),1) AS mult,
           GREATEST(COALESCE((e->>'IpiTaxa')::numeric,0),0) AS ipi
    FROM jsonb_array_elements(p_commercial) e
  ),
  res AS (
    SELECT spr.supplier_sku, i.vmin, i.mult, i.ipi
    FROM inp i
    JOIN public.supplier_products_raw spr ON spr.supplier_id=v_sup AND spr.raw_data->>'CodigoXbz'=i.cx
  ),
  upd AS (
    UPDATE public.variant_supplier_sources vss
       SET min_order_qty=res.vmin, sale_multiplier=res.mult, supplier_ipi_rate=res.ipi, updated_at=now()
    FROM res
    WHERE vss.supplier_id=v_sup AND vss.supplier_sku=res.supplier_sku
      AND (vss.min_order_qty IS DISTINCT FROM res.vmin
        OR vss.sale_multiplier IS DISTINCT FROM res.mult
        OR vss.supplier_ipi_rate IS DISTINCT FROM res.ipi)
    RETURNING vss.id
  )
  SELECT count(*) INTO v_upd FROM upd;

  -- 2) rollup produto-pai (min_order_quantity, ipi_rate) dos afetados
  WITH inp AS (SELECT e->>'CodigoXbz' AS cx FROM jsonb_array_elements(p_commercial) e),
  prod AS (
    SELECT DISTINCT pv.product_id
    FROM inp i
    JOIN public.supplier_products_raw spr ON spr.supplier_id=v_sup AND spr.raw_data->>'CodigoXbz'=i.cx
    JOIN public.variant_supplier_sources vss ON vss.supplier_id=v_sup AND vss.supplier_sku=spr.supplier_sku
    JOIN public.product_variants pv ON pv.id=vss.variant_id
  ),
  agg AS (
    SELECT pr.product_id, MAX(vss.min_order_qty) AS moq, MAX(vss.supplier_ipi_rate) AS ipi
    FROM prod pr
    JOIN public.product_variants pv ON pv.product_id=pr.product_id
    JOIN public.variant_supplier_sources vss ON vss.variant_id=pv.id AND vss.supplier_id=v_sup
    GROUP BY pr.product_id
  ),
  roll AS (
    UPDATE public.products p
       SET min_order_quantity=agg.moq, ipi_rate=agg.ipi, updated_at=now()
    FROM agg WHERE p.id=agg.product_id
      AND (p.min_order_quantity IS DISTINCT FROM agg.moq OR p.ipi_rate IS DISTINCT FROM agg.ipi)
    RETURNING p.id
  )
  SELECT count(*) INTO v_roll FROM roll;

  -- 3) entradas sem correspondencia no bronze (diagnostico)
  SELECT count(*) INTO v_nomatch FROM (
    SELECT e->>'CodigoXbz' cx FROM jsonb_array_elements(p_commercial) e
    EXCEPT SELECT spr.raw_data->>'CodigoXbz' FROM public.supplier_products_raw spr WHERE spr.supplier_id=v_sup
  ) z;

  RETURN QUERY SELECT v_upd, v_roll, v_nomatch, jsonb_array_length(p_commercial);
END; $$;


ALTER FUNCTION "public"."fn_enrich_commercial_xbz"("p_commercial" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enrich_kits_daily"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_spot INTEGER := 0; v_somarcas INTEGER := 0; v_xbz INTEGER := 0;
  v_typical INTEGER := 0; v_material INTEGER := 0;
  v_missing_antes INTEGER; v_missing_depois INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_missing_antes FROM product_kit_components WHERE enrichment_status='missing';

  -- 1. Extrair dimensões do Bronze por fornecedor
  BEGIN
    SELECT COUNT(*) INTO v_spot FROM fn_extract_kit_dims_from_spot_bronze(500);
  EXCEPTION WHEN OTHERS THEN v_spot := -1; END;
  BEGIN
    SELECT COUNT(*) INTO v_somarcas FROM fn_extract_kit_dims_from_somarcas_bronze(500);
  EXCEPTION WHEN OTHERS THEN v_somarcas := -1; END;
  BEGIN
    SELECT COUNT(*) INTO v_xbz FROM fn_extract_kit_dims_from_xbz_bronze(500);
  EXCEPTION WHEN OTHERS THEN v_xbz := -1; END;

  -- 2. Aplicar dimensões típicas para os ainda 'missing'
  --    Inclui correção de shape_type para têxteis planos
  WITH upd AS (
    UPDATE product_kit_components pkc
    SET
      length_mm   = CASE WHEN td.shape != 'cylindrical' THEN td.length_mm ELSE pkc.length_mm END,
      width_mm    = CASE WHEN td.shape != 'cylindrical' THEN td.width_mm  ELSE pkc.width_mm  END,
      height_mm   = CASE WHEN td.shape IN ('rectangular','cylindrical')
                         THEN td.height_mm ELSE pkc.height_mm END,
      diameter_mm = CASE WHEN td.shape = 'cylindrical' THEN td.diameter_mm ELSE pkc.diameter_mm END,
      -- Correção: têxteis planos (AVENTAL, TOALHA, ALMOFADA, etc.) → 'flat'
      shape_type  = CASE
                      WHEN pkc.component_type_code IN ('AVENTAL','TOALHA','FAIXA_ELASTICA',
                                                       'MASCARA_DORMIR','CAPA_CHUVA','ALMOFADA',
                                                       'LUVA','MOUSE_PAD','ECOBAG','CAMISETA')
                      THEN 'flat'
                      ELSE td.shape
                    END,
      weight_g    = COALESCE(pkc.weight_g, td.weight_g_typical),
      enrichment_confidence = 0.40,
      enrichment_source = 'estimated_typical_dims',
      pkg_ext_length_mm = CASE WHEN pkc.is_packaging AND td.shape='rectangular'
        THEN COALESCE(pkc.pkg_ext_length_mm, td.length_mm) ELSE pkc.pkg_ext_length_mm END,
      pkg_ext_width_mm  = CASE WHEN pkc.is_packaging AND td.shape='rectangular'
        THEN COALESCE(pkc.pkg_ext_width_mm, td.width_mm) ELSE pkc.pkg_ext_width_mm END,
      pkg_ext_height_mm = CASE WHEN pkc.is_packaging AND td.shape='rectangular'
        THEN COALESCE(pkc.pkg_ext_height_mm, td.height_mm) ELSE pkc.pkg_ext_height_mm END
    FROM kit_typical_dims td
    WHERE pkc.enrichment_status = 'missing'
      AND pkc.component_type_code = td.type_code
      AND pkc.length_mm IS NULL AND pkc.diameter_mm IS NULL
    RETURNING pkc.id
  ) SELECT COUNT(*) INTO v_typical FROM upd;

  -- 3. Propagar material_type_id para componentes que não têm
  --    (inclui novos que entraram via fn_extract_kit_dims_from_*_bronze)
  WITH mat AS (
    UPDATE product_kit_components pkc
    SET material_type_id = kct.default_material_type_id,
        secondary_material_type_id = COALESCE(pkc.secondary_material_type_id, kct.secondary_material_type_id),
        updated_at = NOW()
    FROM kit_component_types kct
    WHERE pkc.component_type_code = kct.code
      AND pkc.material_type_id IS NULL
      AND kct.default_material_type_id IS NOT NULL
    RETURNING pkc.id
  ) SELECT COUNT(*) INTO v_material FROM mat;

  SELECT COUNT(*) INTO v_missing_depois FROM product_kit_components WHERE enrichment_status='missing';

  RETURN jsonb_build_object(
    'spot_rows', v_spot, 'somarcas_rows', v_somarcas, 'xbz_rows', v_xbz,
    'typical_applied', v_typical, 'material_propagated', v_material,
    'missing_antes', v_missing_antes, 'missing_depois', v_missing_depois,
    'ts', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."fn_enrich_kits_daily"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enrich_packaging_post_promote"("p_supplier_id" "uuid", "p_max_discover" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_extract_cnt int := 0;
  v_compat_cnt  int := 0;
  v_pip_cnt     int := 0;
  v_pip_norm    int := 0;
  v_discover_cnt int := 0;
  v_product RECORD;
  v_disc jsonb;
BEGIN
  PERFORM set_config('app.write_source','pipeline', true);

  -- PASSO 1: Atualizar description_packaging_info e optional_packaging_ref em gold
  WITH upd AS (
    UPDATE products p
    SET description_packaging_info = fn_extract_packaging_info(p.description, p.packing_type),
        optional_packaging_ref = NULLIF((fn_extract_packaging_info(p.description, p.packing_type)->'optional_refs'->>0),''),
        has_optional_packaging = CASE
          WHEN fn_extract_packaging_info(p.description, p.packing_type)->>'has_optional_mention' = 'true'
               OR p.optional_packaging_ref IS NOT NULL THEN true
          ELSE p.has_optional_packaging END
    WHERE p.supplier_id = p_supplier_id
      AND p.description IS NOT NULL
    RETURNING 1
  ) SELECT count(*) INTO v_extract_cnt FROM upd;

  -- PASSO 2: Inserir/atualizar product_packaging_compatibility supplier_indicated
  WITH pares AS (
    SELECT p.id AS product_id, pk.id AS packaging_id, r.ref,
           substring(p.description from '[^.]{0,80}' || r.ref || '[^.]{0,40}') AS trecho
    FROM products p
    CROSS JOIN LATERAL jsonb_array_elements_text(p.description_packaging_info->'optional_refs') r(ref)
    JOIN products pk ON pk.sku = r.ref AND pk.supplier_id = p.supplier_id AND pk.product_type='packaging'
    WHERE p.supplier_id = p_supplier_id AND jsonb_array_length(p.description_packaging_info->'optional_refs') > 0
  )
  INSERT INTO product_packaging_compatibility (
    product_id, packaging_id, compatibility_source, supplier_reference_code,
    supplier_reference_text, is_recommended,
    fit_gap_height_mm, fit_gap_width_mm, fit_gap_length_mm, fit_gap_diameter_mm,
    fit_gap_min_mm, fit_gap_avg_mm, fit_rating
  )
  SELECT pr.product_id, pr.packaging_id, 'supplier_indicated', pr.ref, pr.trecho, true,
         (f->>'gap_height_mm')::numeric, (f->>'gap_width_mm')::numeric,
         (f->>'gap_length_mm')::numeric, (f->>'gap_diameter_mm')::numeric,
         (f->>'gap_min_mm')::numeric, (f->>'gap_avg_mm')::numeric,
         NULLIF(f->>'fit_rating','')
  FROM pares pr
  CROSS JOIN LATERAL (SELECT fn_calculate_packaging_fit(pr.product_id, pr.packaging_id) AS f) c
  ON CONFLICT (product_id, packaging_id) DO UPDATE
     SET compatibility_source='supplier_indicated',
         supplier_reference_code=EXCLUDED.supplier_reference_code,
         supplier_reference_text=EXCLUDED.supplier_reference_text,
         is_recommended=true;
  GET DIAGNOSTICS v_compat_cnt = ROW_COUNT;

  -- PASSO 3: Criar/atualizar product_included_packagings para produtos novos
  WITH candidatos AS (
    SELECT p.id AS product_id,
           COALESCE(NULLIF(trim(p.packing_type),''), initcap(p.description_packaging_info->>'included_mention')) AS nome,
           p.packing_type AS raw_packing,
           p.packing_type_canonical,
           CASE WHEN p.packing_type_canonical ~* 'veludo|aveludad|berco|berço' THEN true ELSE false END AS tem_berco,
           CASE WHEN p.packing_type_canonical ~* 'kraft|craft' THEN 'kraft'
                WHEN p.packing_type_canonical ~* 'veludo|aveludad' THEN 'veludo'
                WHEN p.packing_type_canonical ~* 'non[- ]?woven|tnt' THEN 'non-woven'
                WHEN p.packing_type_canonical ~* 'madeira|bambu' THEN 'madeira'
                WHEN p.packing_type_canonical ~* 'metal|lata|alum' THEN 'metal'
                WHEN p.packing_type_canonical ~* 'pl[aá]stic|pvc' THEN 'plástico'
                WHEN p.packing_type_canonical ~* 'papel seda|manteiga' THEN 'papel seda'
                WHEN p.packing_type_canonical ~* 'caixa|cart[aã]o|estojo' THEN 'cartão'
                WHEN p.packing_type_canonical ~* 'bolsa|saco' THEN 'tecido'
                ELSE NULL END AS material,
           CASE WHEN p.packing_type_canonical ~* 'pret[ao]' THEN 'Preto'
                WHEN p.packing_type_canonical ~* 'branc[ao]' THEN 'Branco'
                WHEN p.packing_type_canonical ~* 'kraft|craft' THEN 'Kraft natural'
                WHEN p.packing_type_canonical ~* 'transparente' THEN 'Transparente' ELSE NULL END AS cor
    FROM products p
    WHERE p.supplier_id = p_supplier_id
      AND p.product_type = 'product'
      AND p.packing_classification = 'commercial'
      AND NOT EXISTS (SELECT 1 FROM product_included_packagings pip WHERE pip.product_id = p.id)
  )
  INSERT INTO product_included_packagings
    (product_id, name, material, color, has_inner_cradle, supplier_packaging_name, is_default, can_be_disabled, can_be_customized, active, notes)
  SELECT product_id, left(nome,200), material, cor, tem_berco, raw_packing, true, true, true, true,
         'Gerado pelo pipeline (fn_enrich_packaging_post_promote)'
  FROM candidatos WHERE nome IS NOT NULL;
  GET DIAGNOSTICS v_pip_cnt = ROW_COUNT;

  -- PASSO 4: Normalizar nomes pip para produtos deste fornecedor
  WITH upd AS (
    UPDATE product_included_packagings pip
    SET name = p.packing_type_canonical
    FROM products p
    WHERE pip.product_id = p.id AND p.supplier_id = p_supplier_id
      AND p.packing_type_canonical IS NOT NULL
      AND pip.name != p.packing_type_canonical AND pip.name = p.packing_type
    RETURNING 1
  ) SELECT count(*) INTO v_pip_norm FROM upd;

  -- PASSO 5: Auto-discover compatibilidade dimensional (limitado a p_max_discover produtos)
  FOR v_product IN
    SELECT id FROM products
    WHERE supplier_id = p_supplier_id AND product_type='product'
      AND is_active = true AND height_cm IS NOT NULL
    ORDER BY updated_at DESC LIMIT p_max_discover
  LOOP
    v_disc := fn_auto_discover_compatible_packagings(v_product.id, 'good');
    v_discover_cnt := v_discover_cnt + COALESCE((v_disc->>'discovered')::int, 0);
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'supplier_id', p_supplier_id,
    'gold_packaging_info_updated', v_extract_cnt,
    'compatibility_supplier_indicated', v_compat_cnt,
    'pip_created', v_pip_cnt,
    'pip_names_normalized', v_pip_norm,
    'compatibility_discovered', v_discover_cnt
  );
END;
$$;


ALTER FUNCTION "public"."fn_enrich_packaging_post_promote"("p_supplier_id" "uuid", "p_max_discover" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_enrich_packaging_post_promote"("p_supplier_id" "uuid", "p_max_discover" integer) IS 'Enriquecimento de embalagem pós-promoção ao gold (M12+M13). Executa:
 1. Atualiza description_packaging_info + optional_packaging_ref no gold.
 2. Insere/atualiza product_packaging_compatibility supplier_indicated.
 3. Cria product_included_packagings para produtos novos commercial.
 4. Normaliza nomes pip via fn_normalize_packing_type.
 5. Roda fn_auto_discover_compatible_packagings (tight/good/loose).
 Chamar após fn_promote_supplier ou no fim de qualquer pipeline de ingestão.';



CREATE OR REPLACE FUNCTION "public"."fn_enrich_padronizacao"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  pp     public.produtos_padronizacao%ROWTYPE;
  v_raw  jsonb;
  v_filled jsonb := '{}'::jsonb;
  v_tags jsonb;
  v_raw_tags jsonb;
  v_mats jsonb;
  v_mat_txt text;
  v_ipi  numeric;
  v_ncm  text;
  v_desc text;
  v_prefix text;
BEGIN
  SELECT * INTO pp FROM public.produtos_padronizacao WHERE id = p_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'pad_nao_encontrado');
  END IF;

  SELECT raw_data INTO v_raw FROM public.supplier_products_raw WHERE id = pp.raw_id;

  -- 1) description ← raw (quando mapping não populou)
  IF NULLIF(TRIM(COALESCE(pp.description,'')),'') IS NULL AND v_raw IS NOT NULL THEN
    v_desc := NULLIF(TRIM(COALESCE(
      v_raw->>'descricao', v_raw->>'Descricao', v_raw->>'Description', v_raw->>'DESCRICAO')), '');
    IF v_desc IS NOT NULL THEN
      v_filled := v_filled || jsonb_build_object('description', true);
    END IF;
  END IF;

  -- 2) materials ← raw material direto OU extração por nome/descrição
  IF jsonb_array_length(COALESCE(pp.materials, '[]'::jsonb)) = 0 THEN
    v_mats := public.fn_safe_jsonb_arr(COALESCE(
      v_raw->>'material', v_raw->>'materiais', v_raw->>'Materials', v_raw->>'MATERIAL'));
    IF v_mats IS NULL THEN
      v_mat_txt := public.extract_xbz_material_primary(pp.name, pp.description);
      IF v_mat_txt IS NOT NULL THEN
        v_mats := jsonb_build_array(v_mat_txt);
      END IF;
    END IF;
    IF v_mats IS NOT NULL THEN
      v_filled := v_filled || jsonb_build_object('materials', true);
    END IF;
  END IF;

  -- 3) tags ← raw tags (objeto/array/pipe) ∪ tokenização do nome (dedup, máx 16)
  IF jsonb_array_length(COALESCE(pp.tags, '[]'::jsonb)) = 0 THEN
    v_raw_tags := public.fn_safe_jsonb_arr(v_raw->>'tags');
    SELECT COALESCE(jsonb_agg(tok ORDER BY first_ord), '[]'::jsonb) INTO v_tags
    FROM (
      SELECT tok, MIN(ord) AS first_ord FROM (
        SELECT e.value #>> '{}' AS tok, e.ordinality AS ord
        FROM jsonb_array_elements(COALESCE(v_raw_tags,'[]'::jsonb)) WITH ORDINALITY e
        UNION ALL
        SELECT e2.value #>> '{}', 100 + e2.ordinality
        FROM jsonb_array_elements(public.fn_tokenize_product_tags(pp.name)) WITH ORDINALITY e2
      ) u
      WHERE NULLIF(TRIM(tok),'') IS NOT NULL
      GROUP BY tok ORDER BY MIN(ord) LIMIT 16
    ) t;
    IF jsonb_array_length(v_tags) > 0 THEN
      v_filled := v_filled || jsonb_build_object('tags', true);
    ELSE
      v_tags := NULL;
    END IF;
  END IF;

  -- 4) ipi_rate ← ncm_codes OU moda dos irmãos de mesmo NCM (inequívoca)
  IF pp.ipi_rate IS NULL AND NULLIF(TRIM(COALESCE(pp.ncm_code,'')),'') IS NOT NULL THEN
    v_ipi := public.fn_get_ncm_ipi_rate(pp.ncm_code);
    IF v_ipi IS NULL THEN
      SELECT MIN(x.ipi_rate) INTO v_ipi
      FROM public.produtos_padronizacao x
      WHERE x.ncm_code = pp.ncm_code AND x.ipi_rate IS NOT NULL
      HAVING COUNT(DISTINCT x.ipi_rate) = 1;
    END IF;
    IF v_ipi IS NOT NULL THEN
      v_filled := v_filled || jsonb_build_object('ipi_rate', v_ipi);
    END IF;
  END IF;

  -- 5) ncm_code ← prefixo de nome (2 primeiras palavras, mesmo fornecedor, inequívoco)
  IF NULLIF(TRIM(COALESCE(pp.ncm_code,'')),'') IS NULL AND pp.name IS NOT NULL THEN
    v_prefix := (SELECT string_agg(w, ' ') FROM (
      SELECT w FROM regexp_split_to_table(UPPER(pp.name), '\s+') WITH ORDINALITY t(w, o)
      WHERE o <= 2 ORDER BY o) z);
    IF v_prefix IS NOT NULL AND LENGTH(v_prefix) >= 5 THEN
      SELECT MIN(x.ncm_code) INTO v_ncm
      FROM public.produtos_padronizacao x
      WHERE x.supplier_id = pp.supplier_id
        AND x.id <> pp.id
        AND x.ncm_code IS NOT NULL
        AND UPPER(x.name) LIKE v_prefix || '%'
      HAVING COUNT(DISTINCT x.ncm_code) = 1;
      IF v_ncm IS NOT NULL THEN
        v_filled := v_filled || jsonb_build_object('ncm_code', v_ncm);
      END IF;
    END IF;
  END IF;

  -- 6) meta_keywords ← tags finais
  -- (aplicado no UPDATE abaixo quando vazio)

  UPDATE public.produtos_padronizacao SET
    description   = CASE WHEN v_desc IS NOT NULL THEN v_desc ELSE description END,
    materials     = CASE WHEN v_mats IS NOT NULL THEN v_mats ELSE materials END,
    tags          = CASE WHEN v_tags IS NOT NULL THEN v_tags ELSE tags END,
    ipi_rate      = COALESCE(ipi_rate, v_ipi),
    ncm_code      = COALESCE(ncm_code, v_ncm),
    meta_keywords = CASE
                      WHEN COALESCE(array_length(meta_keywords,1),0) = 0 THEN
                        COALESCE(
                          (SELECT array_agg(e #>> '{}') FROM jsonb_array_elements(
                             COALESCE(v_tags, NULLIF(tags,'[]'::jsonb))) e),
                          meta_keywords)
                      ELSE meta_keywords
                    END,
    updated_at    = now()
  WHERE id = p_id
    AND (v_desc IS NOT NULL OR v_mats IS NOT NULL OR v_tags IS NOT NULL
         OR v_ipi IS NOT NULL OR v_ncm IS NOT NULL
         OR COALESCE(array_length(meta_keywords,1),0) = 0);

  RETURN jsonb_build_object('success', true, 'pad_id', p_id, 'filled', v_filled);
END;
$$;


ALTER FUNCTION "public"."fn_enrich_padronizacao"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enrich_pen_categories"("p_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_batch_size" integer DEFAULT 300, "p_force_reclassify" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_processed     integer := 0;
    v_classified    integer := 0;
    v_skipped       integer := 0;
    v_errors        integer := 0;
    v_rec           RECORD;
    v_pen_result    jsonb;
    v_category_id   uuid;
    v_pen_category_ids uuid[];
BEGIN
    -- Pré-carregar IDs das categorias de canetas
    SELECT ARRAY_AGG(id) INTO v_pen_category_ids
    FROM categories
    WHERE (slug ILIKE 'caneta%' OR slug = 'lapiseiras')
    AND is_active = true;

    FOR v_rec IN
        SELECT p.id, p.name, p.supplier_id
        FROM products p
        WHERE p.is_active = true
        AND (
            p.name ILIKE '%caneta%'
            OR p.name ILIKE '%esferograf%'
            OR p.name ILIKE '%lapiseira%'
            OR p.name ILIKE '%roller%'
            OR p.name ILIKE '%stylus%'
        )
        AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
        AND (
            p_force_reclassify = TRUE
            OR NOT EXISTS (
                SELECT 1 FROM product_category_assignments pca
                WHERE pca.product_id = p.id
                AND pca.category_id = ANY(v_pen_category_ids)
            )
        )
        ORDER BY p.id
        LIMIT p_batch_size
    LOOP
        v_processed := v_processed + 1;

        BEGIN
            v_pen_result := classify_pen(v_rec.name);

            IF (v_pen_result->>'is_pen')::boolean = TRUE
               AND (v_pen_result->>'category_id') IS NOT NULL THEN

                v_category_id := (v_pen_result->>'category_id')::uuid;

                INSERT INTO product_category_assignments (
                    product_id,
                    category_id,
                    is_primary,
                    display_order,
                    created_at
                )
                VALUES (
                    v_rec.id,
                    v_category_id,
                    FALSE,
                    0,
                    now()
                )
                ON CONFLICT (product_id, category_id) DO NOTHING;

                v_classified := v_classified + 1;
            ELSE
                v_skipped := v_skipped + 1;
            END IF;

        EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'status',      'ok',
        'processed',   v_processed,
        'classified',  v_classified,
        'skipped',     v_skipped,
        'errors',      v_errors,
        'timestamp',   now()
    );
END;
$$;


