CREATE OR REPLACE FUNCTION "public"."fn_ensure_single_primary_image"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NEW.is_primary = true THEN
        -- Desmarcar outras imagens primary do mesmo produto
        UPDATE product_images 
        SET is_primary = false, updated_at = NOW()
        WHERE product_id = NEW.product_id 
          AND id != NEW.id 
          AND is_primary = true;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_ensure_single_primary_image"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_ensure_single_primary_image"() IS 'Trigger BEFORE INSERT/UPDATE em product_images.
Garante a invariante: apenas UMA imagem por produto pode ter is_primary = true.

COMO FUNCIONA:
  Quando NEW.is_primary = TRUE → faz UPDATE nas outras imagens do mesmo produto
  definindo is_primary = FALSE antes de salvar o novo registro.
  Estratégia: "last-write-wins" — a imagem que foi salva por último é a primary.

ATENÇÃO — CASO DE DEADLOCK POTENCIAL:
  Em INSERTs em lote (pipeline inserindo múltiplas imagens em paralelo),
  múltiplas transações podem tentar o UPDATE nas mesmas rows simultaneamente.
  Se isso ocorrer: aguardar rollback automático, reexecutar em série.
  Para bulk imports: inserir com is_primary = FALSE e depois promover uma via UPDATE.

COMO RECUPERAR SE HOUVER MAIS DE 1 PRIMARY:
  -- Detectar:
  SELECT product_id, COUNT(*) FROM product_images
  WHERE is_primary = true AND is_active = true GROUP BY product_id HAVING COUNT(*) > 1;

  -- Corrigir (mantém a de menor display_order):
  WITH ranked AS (
    SELECT id, product_id,
           ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY display_order) AS rn
    FROM product_images WHERE is_primary = true AND is_active = true
  )
  UPDATE product_images SET is_primary = false
  WHERE id IN (SELECT id FROM ranked WHERE rn > 1);

NOTA: O índice UNIQUE uq_product_images_one_primary_per_product complementa esta trigger
reforçando a invariante a nível de constraint de DB.';



CREATE OR REPLACE FUNCTION "public"."fn_expire_novelties"() RETURNS TABLE("expired_count" integer, "still_inactive" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_expired integer;
  v_inactive integer;
BEGIN
  UPDATE product_novelties
  SET is_active = false,
      updated_at = NOW()
  WHERE is_active = true
    AND expires_at IS NOT NULL
    AND expires_at < NOW();
  GET DIAGNOSTICS v_expired = ROW_COUNT;

  SELECT COUNT(*) INTO v_inactive
  FROM product_novelties WHERE is_active = false;

  RETURN QUERY SELECT v_expired, v_inactive;
END;
$$;


ALTER FUNCTION "public"."fn_expire_novelties"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_expire_novelties"() IS 'Sweep diário: marca is_active=false em product_novelties com expires_at < NOW().';



CREATE OR REPLACE FUNCTION "public"."fn_expire_novelties_with_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
/*
  v2_2026-06-13 — Expira novidades vencidas + sincroniza is_new=false imediatamente.
  FIX vs v1: v1 só desativava product_novelties mas não sincronizava is_new em products.
  Isso causava janela de até ~65min onde o produto ainda mostrava is_new=true
  (até fn_reactivate Frente 4 rodar na hora seguinte).
*/
DECLARE
    v_expired        INTEGER;
    v_before_count   INTEGER;
    v_after_count    INTEGER;
    v_is_new_cleared INTEGER;
BEGIN
    -- Contar antes
    SELECT COUNT(*) INTO v_before_count
    FROM product_novelties WHERE is_active = TRUE;

    -- Expirar novidades onde expires_at já passou
    WITH expired_ids AS (
        UPDATE product_novelties
        SET is_active = FALSE, updated_at = now()
        WHERE is_active = TRUE
          AND expires_at IS NOT NULL
          AND expires_at < NOW()
        RETURNING product_id
    )
    -- Sincronizar is_new=false para produtos cujas novidades expiraram
    -- e que NÃO têm nenhuma outra novelty ativa
    UPDATE products p
    SET is_new              = FALSE,
        novelty_detected_at = NULL,
        novelty_expires_at  = NULL,
        is_new_expires_at   = NULL,
        updated_at          = now()
    WHERE p.id IN (SELECT product_id FROM expired_ids)
      AND p.is_new = TRUE
      AND NOT EXISTS (
          SELECT 1 FROM product_novelties pn
          WHERE pn.product_id = p.id AND pn.is_active = TRUE
      );

    GET DIAGNOSTICS v_is_new_cleared = ROW_COUNT;

    -- Total expirado (separado para não usar CTEs no GET DIAGNOSTICS)
    SELECT COUNT(*) INTO v_expired
    FROM product_novelties
    WHERE is_active = FALSE
      AND updated_at >= now() - interval '10 seconds';

    SELECT COUNT(*) INTO v_after_count
    FROM product_novelties WHERE is_active = TRUE;

    RAISE NOTICE 'fn_expire v2: expiradas=% is_new_cleared=% ativas_antes=% ativas_depois=%',
                 v_expired, v_is_new_cleared, v_before_count, v_after_count;

    RETURN jsonb_build_object(
        'version',         'v2_2026-06-13',
        'expired_count',   v_expired,
        'is_new_cleared',  v_is_new_cleared,
        'active_before',   v_before_count,
        'active_after',    v_after_count,
        'executed_at',     NOW(),
        'next_expiring', (
            SELECT MIN(expires_at)
            FROM product_novelties
            WHERE is_active = TRUE AND expires_at > NOW()
        )
    );
END;
$$;


ALTER FUNCTION "public"."fn_expire_novelties_with_stats"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_expire_novelties_with_stats"() IS 'Expira product_novelties onde expires_at < NOW(). Usa expires_at (correto). 
   NOTA: fn_expire_product_novelties foi removida em 2026-06-12 por usar 
   products.created_at em vez de expires_at — causaria expiração incorreta de 6016 produtos válidos.';



CREATE OR REPLACE FUNCTION "public"."fn_expire_overdue_quotes"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  _expired_ids uuid[];
  _count integer;
  _fallback_uid uuid;
  rec RECORD;
BEGIN
  -- fix_version: expire-quotes-discount-bypass-2026-07-03
  -- Sinaliza para fn_quotes_validate_discount que este é o cron de expiração
  -- (camada defensiva extra; o bypass por NEW.status='expired' já é suficiente)
  PERFORM set_config('app.write_source', 'cron_expire', true);

  -- Uid de fallback para histórico (usar um admin/sistema)
  SELECT id INTO _fallback_uid FROM auth.users ORDER BY created_at LIMIT 1;

  -- Coletar quotes a expirar
  SELECT array_agg(id) INTO _expired_ids
  FROM quotes
  WHERE valid_until < CURRENT_DATE
    AND status NOT IN ('expired', 'cancelled', 'converted', 'rejected', 'draft');

  IF _expired_ids IS NULL OR array_length(_expired_ids, 1) = 0 THEN
    RETURN jsonb_build_object('expired_count', 0, 'quote_ids', '[]'::jsonb);
  END IF;

  _count := array_length(_expired_ids, 1);

  -- Inserir histórico para cada quote expirado
  INSERT INTO quote_history (quote_id, user_id, action, field_changed, old_value, new_value, description, metadata, created_at)
  SELECT 
    q.id,
    COALESCE(q.seller_id, q.created_by, _fallback_uid),
    'status_change',
    'status',
    q.status,
    'expired',
    'Auto-expirado: valid_until ' || q.valid_until::text || ' anterior a ' || CURRENT_DATE::text,
    jsonb_build_object('auto_expired', true, 'valid_until', q.valid_until::text, 'previous_status', q.status),
    now()
  FROM quotes q
  WHERE q.id = ANY(_expired_ids);

  -- Atualizar status em batch
  -- fn_quotes_validate_discount é bypassado para NEW.status='expired' (fix acima)
  UPDATE quotes
  SET status = 'expired', updated_at = now()
  WHERE id = ANY(_expired_ids);

  RETURN jsonb_build_object(
    'expired_count', _count,
    'quote_ids', to_jsonb(_expired_ids),
    'executed_at', now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_expire_overdue_quotes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_expire_overdue_quotes"() IS 'FIX-02 (2026-06-22): Auto-expiração de orçamentos com valid_until < CURRENT_DATE. Chamada pelo cronjob daily-expire-quotes às 00:30.';



