    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_expired integer;
BEGIN
  UPDATE public.supplier_replenishment_events
  SET resolution = 'expired', resolved_at = now(), updated_at = now()
