CREATE OR REPLACE FUNCTION "public"."fn_extract_capacity_from_name"("p_name" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_match TEXT[];
    v_value INTEGER;
BEGIN
    -- 1. Match mL pattern with word boundary
    v_match := regexp_match(p_name, '(\d+)\s*(ml)\M', 'i');
    IF v_match IS NOT NULL THEN
        v_value := v_match[1]::INTEGER;
        IF v_value > 0 AND v_value <= 10000 THEN
            RETURN v_value;
        END IF;
    END IF;
    
    -- 2. Match L/litro/litros with word boundary + apostrophe decimal
    v_match := regexp_match(p_name, '(\d+[''.,]?\d*)\s*(litros?|l)\M', 'i');
    IF v_match IS NOT NULL THEN
        v_value := (REPLACE(REPLACE(v_match[1], '''', '.'), ',', '.')::NUMERIC * 1000)::INTEGER;
        IF v_value > 0 AND v_value <= 10000 THEN
            RETURN v_value;
        END IF;
    END IF;
    
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_extract_capacity_from_name"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_extract_color_from_name"("p_name" "text") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_name_lower TEXT;
    v_colors TEXT[] := '{}';
BEGIN
    v_name_lower := LOWER(unaccent(COALESCE(p_name, '')));
    
    IF v_name_lower ~ '\m(preto|preta|black)\M' THEN v_colors := array_append(v_colors, 'Preto'); END IF;
    IF v_name_lower ~ '\m(branco|branca|white)\M' THEN v_colors := array_append(v_colors, 'Branco'); END IF;
    IF v_name_lower ~ '\m(azul|blue)\M' THEN v_colors := array_append(v_colors, 'Azul'); END IF;
    IF v_name_lower ~ '\m(vermelho|vermelha|red)\M' THEN v_colors := array_append(v_colors, 'Vermelho'); END IF;
    IF v_name_lower ~ '\m(verde|green)\M' THEN v_colors := array_append(v_colors, 'Verde'); END IF;
    IF v_name_lower ~ '\m(amarelo|amarela|yellow)\M' THEN v_colors := array_append(v_colors, 'Amarelo'); END IF;
    IF v_name_lower ~ '\m(laranja|orange)\M' THEN v_colors := array_append(v_colors, 'Laranja'); END IF;
    IF v_name_lower ~ '\m(rosa|pink)\M' THEN v_colors := array_append(v_colors, 'Rosa'); END IF;
    IF v_name_lower ~ '\m(roxo|roxa|purple|violeta)\M' THEN v_colors := array_append(v_colors, 'Roxo'); END IF;
    IF v_name_lower ~ '\m(cinza|cinzento|grey|gray)\M' THEN v_colors := array_append(v_colors, 'Cinza'); END IF;
    IF v_name_lower ~ '\m(marrom|marron|brown)\M' THEN v_colors := array_append(v_colors, 'Marrom'); END IF;
    IF v_name_lower ~ '\m(bege|beige)\M' THEN v_colors := array_append(v_colors, 'Bege'); END IF;
    IF v_name_lower ~ '\m(dourado|dourada|gold)\M' THEN v_colors := array_append(v_colors, 'Dourado'); END IF;
    IF v_name_lower ~ '\m(prata|prateado|prateada|silver)\M' THEN v_colors := array_append(v_colors, 'Prata'); END IF;
    IF v_name_lower ~ '\m(cromado|cromada|chrome)\M' THEN v_colors := array_append(v_colors, 'Cromado'); END IF;
    IF v_name_lower ~ '\m(transparente|cristal|clear)\M' THEN v_colors := array_append(v_colors, 'Transparente'); END IF;
    IF v_name_lower ~ '\m(natural|cru)\M' THEN v_colors := array_append(v_colors, 'Natural'); END IF;
    
    RETURN v_colors;
END;
$$;


ALTER FUNCTION "public"."fn_extract_color_from_name"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_extract_color_from_title"("p_titulo" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tok text;
  v_up  text;
BEGIN
  IF p_titulo IS NULL OR TRIM(p_titulo)='' THEN RETURN NULL; END IF;
  v_up := UPPER(p_titulo);

  SELECT m[1] INTO v_tok FROM regexp_matches(v_up,
    '\y(PRET[AO]|BRANC[AO]|AZUL|VERMELH[AO]|VERDE|CINZA|AMAREL[AO]|ROSA|ROX[AO]|LARANJA|BEGE|MARROM|DOURAD[AO]|PRATEAD[AO]|PRATA|NATURAL|BAMBU|MADEIRA|INOX|VINHO|CAQUI|NUDE|TURQUESA|LIL[AÁ]S|FUM[EÊ]|TRANSPARENTE|GRAFITE|CHUMBO|CORAL|MOSTARDA)\y'
  ) m LIMIT 1;

  IF v_tok IS NULL THEN RETURN NULL; END IF;

  RETURN CASE
    WHEN v_tok LIKE 'PRET%'    THEN 'Preto'
    WHEN v_tok LIKE 'BRANC%'   THEN 'Branco'
    WHEN v_tok LIKE 'VERMELH%' THEN 'Vermelho'
    WHEN v_tok LIKE 'AMAREL%'  THEN 'Amarelo'
    WHEN v_tok LIKE 'ROX%'     THEN 'Roxo'
    WHEN v_tok LIKE 'DOURAD%'  THEN 'Dourado'
    WHEN v_tok LIKE 'PRATEAD%' THEN 'Prata'
    WHEN v_tok='AZUL'          THEN 'Azul'
    WHEN v_tok='VERDE'         THEN 'Verde'
    WHEN v_tok='CINZA'         THEN 'Cinza'
    WHEN v_tok='ROSA'          THEN 'Rosa'
    WHEN v_tok='LARANJA'       THEN 'Laranja'
    WHEN v_tok='BEGE'          THEN 'Bege'
    WHEN v_tok='MARROM'        THEN 'Marrom'
    WHEN v_tok='PRATA'         THEN 'Prata'
    WHEN v_tok='NATURAL'       THEN 'Natural'
    WHEN v_tok='BAMBU'         THEN 'Bambu'
    WHEN v_tok='MADEIRA'       THEN 'Madeira'
    WHEN v_tok='INOX'          THEN 'Inox'
    WHEN v_tok='VINHO'         THEN 'Vinho'
    WHEN v_tok='CAQUI'         THEN 'Caqui'
    WHEN v_tok='NUDE'          THEN 'Nude'
    WHEN v_tok='TURQUESA'      THEN 'Turquesa'
    WHEN v_tok LIKE 'LIL%'     THEN 'Lilás'
    WHEN v_tok LIKE 'FUM%'     THEN 'Fumê'
    WHEN v_tok='TRANSPARENTE'  THEN 'Transparente'
    WHEN v_tok='GRAFITE'       THEN 'Grafite'
    WHEN v_tok='CHUMBO'        THEN 'Chumbo'
    WHEN v_tok='CORAL'         THEN 'Coral'
    WHEN v_tok='MOSTARDA'      THEN 'Mostarda'
    ELSE initcap(v_tok)
  END;
END;
$$;


ALTER FUNCTION "public"."fn_extract_color_from_title"("p_titulo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_extract_color_from_title"("p_titulo" "text") IS 'Extrai cor do título (vocabulário + normalização de gênero) p/ fornecedores sem campo de cor (Só Marcas). NULL quando não há cor.';



CREATE OR REPLACE FUNCTION "public"."fn_extract_dimensions_from_name"("p_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_match TEXT[];
    v_result JSONB := '{}';
BEGIN
    -- Padrão: 30x20x10 cm
    v_match := regexp_match(p_name, '(\d+[,.]?\d*)\s*[xX×]\s*(\d+[,.]?\d*)\s*[xX×]\s*(\d+[,.]?\d*)\s*(cm|mm)?', 'i');
    IF v_match IS NOT NULL THEN
        v_result := jsonb_build_object(
            'length_cm', REPLACE(v_match[1], ',', '.')::NUMERIC,
            'width_cm', REPLACE(v_match[2], ',', '.')::NUMERIC,
            'height_cm', REPLACE(v_match[3], ',', '.')::NUMERIC
        );
        IF v_match[4] = 'mm' THEN
            v_result := jsonb_build_object(
                'length_cm', (REPLACE(v_match[1], ',', '.')::NUMERIC / 10),
                'width_cm', (REPLACE(v_match[2], ',', '.')::NUMERIC / 10),
                'height_cm', (REPLACE(v_match[3], ',', '.')::NUMERIC / 10)
            );
        END IF;
        RETURN v_result;
    END IF;
    
    -- Padrão: 30x20 cm (2 dimensões)
    v_match := regexp_match(p_name, '(\d+[,.]?\d*)\s*[xX×]\s*(\d+[,.]?\d*)\s*(cm|mm)?', 'i');
    IF v_match IS NOT NULL THEN
        v_result := jsonb_build_object(
            'length_cm', REPLACE(v_match[1], ',', '.')::NUMERIC,
            'width_cm', REPLACE(v_match[2], ',', '.')::NUMERIC
        );
        RETURN v_result;
    END IF;
    
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_extract_dimensions_from_name"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_extract_dimensions_from_text"("p_kit_component_id" "uuid", "p_source_text" "text", "p_extracted_data" "jsonb", "p_confidence" numeric DEFAULT 0.7) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pkc    product_kit_components%ROWTYPE;
  v_raw_id UUID;
BEGIN
  SELECT * INTO v_pkc FROM product_kit_components WHERE id = p_kit_component_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'component % not found', p_kit_component_id;
  END IF;

  INSERT INTO kit_component_enrichment_raw (
    kit_product_id, kit_component_id,
    raw_component_name, raw_component_type,
    raw_data, source, source_ref, source_confidence
  ) VALUES (
    v_pkc.kit_product_id, p_kit_component_id,
    v_pkc.component_name, v_pkc.component_type_code,
    p_extracted_data || jsonb_build_object(
      'component_name',      v_pkc.component_name,
      'component_type_code', v_pkc.component_type_code,
      'unit',                COALESCE(p_extracted_data->>'unit', 'mm'),
      'ai_source_text',      LEFT(p_source_text, 500),
      'is_packaging',        v_pkc.is_packaging,
      'allows_personalization', v_pkc.allows_personalization,
      'quantity',            v_pkc.quantity
    ),
    'ai_extraction',
    LEFT(p_source_text, 200),
    p_confidence
  ) RETURNING id INTO v_raw_id;

  RETURN v_raw_id;
END;
$$;


ALTER FUNCTION "public"."fn_extract_dimensions_from_text"("p_kit_component_id" "uuid", "p_source_text" "text", "p_extracted_data" "jsonb", "p_confidence" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_extract_dimensions_from_text"("p_kit_component_id" "uuid", "p_source_text" "text", "p_extracted_data" "jsonb", "p_confidence" numeric) IS 'Recebe resultado de extração de dimensões por IA (Claude/GPT) e insere no bronze.
   Usado pelo pipeline externo (n8n/edge function) que chama a API de IA
   e passa o resultado estruturado para cá.
   Retorna raw_id para rastreamento.';



CREATE OR REPLACE FUNCTION "public"."fn_extract_item_dims_xbz_from_bronze"("p_limit" integer DEFAULT 200) RETURNS TABLE("component_id" "uuid", "component_name" "text", "sku" "text", "resultado" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_rec    RECORD;
  v_raw    RECORD;
  v_raw_id UUID;
  v_alt    NUMERIC; v_lar NUMERIC; v_prof NUMERIC; v_peso NUMERIC;
  v_base   TEXT;
BEGIN
  FOR v_rec IN
    SELECT pkc.id AS comp_id, pkc.component_name,
           pkc.component_sku AS sku,
           REGEXP_REPLACE(pkc.component_sku, '-[A-Z]{2,4}$', '') AS base_sku,
           pkc.kit_product_id
    FROM product_kit_components pkc
    JOIN products p ON p.id = pkc.kit_product_id
    JOIN suppliers s ON s.id = p.supplier_id AND s.code = 'XBZ'
    WHERE pkc.enrichment_status = 'missing'
      AND pkc.is_packaging = FALSE
      AND pkc.component_sku IS NOT NULL
    LIMIT p_limit
  LOOP
    -- Match exato primeiro, depois base SKU
    SELECT raw_data INTO v_raw
    FROM supplier_products_raw
    WHERE supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900'
      AND (
        raw_data->>'CodigoAmigavel' = v_rec.sku  OR
        raw_data->>'CodigoAmigavel' = v_rec.base_sku OR
        raw_data->>'CodigoAmigavel' ILIKE v_rec.base_sku || '%'
      )
    ORDER BY CASE WHEN raw_data->>'CodigoAmigavel' = v_rec.sku THEN 0 ELSE 1 END
    LIMIT 1;

    IF NOT FOUND THEN
      component_id := v_rec.comp_id; component_name := v_rec.component_name;
      sku := v_rec.sku; resultado := 'no_match';
      RETURN NEXT; CONTINUE;
    END IF;

    v_alt  := NULLIF((v_raw.raw_data->>'Altura')::NUMERIC, 0);
    v_lar  := NULLIF((v_raw.raw_data->>'Largura')::NUMERIC, 0);
    v_prof := NULLIF((v_raw.raw_data->>'Profundidade')::NUMERIC, 0);
    v_peso := NULLIF((v_raw.raw_data->>'Peso')::NUMERIC, 0);

    IF v_alt IS NULL AND v_lar IS NULL AND v_peso IS NULL THEN
      component_id := v_rec.comp_id; component_name := v_rec.component_name;
      sku := v_rec.sku; resultado := 'zero_dims';
      RETURN NEXT; CONTINUE;
    END IF;

    INSERT INTO kit_component_enrichment_raw (
      kit_product_id, kit_component_id, raw_component_name,
      supplier_component_code, source, source_ref, source_confidence, raw_data
    ) VALUES (
      v_rec.kit_product_id, v_rec.comp_id, v_rec.component_name,
      v_rec.sku, 'supplier_api', v_rec.sku, 0.85,
      jsonb_strip_nulls(jsonb_build_object(
        'component_name',    v_rec.component_name,
        'unit',              'cm',
        'height_mm',         CASE WHEN v_alt  IS NOT NULL THEN ROUND(v_alt  * 10)::INTEGER END,
        'width_mm',          CASE WHEN v_lar  IS NOT NULL THEN ROUND(v_lar  * 10)::INTEGER END,
        'length_mm',         CASE WHEN v_prof IS NOT NULL THEN ROUND(v_prof * 10)::INTEGER END,
        'weight_g',          CASE WHEN v_peso IS NOT NULL THEN ROUND(v_peso)::INTEGER END,
        'is_packaging',      FALSE
      ))
    ) RETURNING id INTO v_raw_id;

    component_id := v_rec.comp_id; component_name := v_rec.component_name; sku := v_rec.sku;
    resultado := 'ok:h' || COALESCE(ROUND(v_alt*10)::TEXT,'?') || 'mm';
    RETURN NEXT;
  END LOOP;
END;
$_$;


ALTER FUNCTION "public"."fn_extract_item_dims_xbz_from_bronze"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_extract_keywords_from_name"("p_name" "text") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_name_clean TEXT;
    v_words TEXT[];
    v_keywords TEXT[] := '{}';
    v_word TEXT;
    v_stopwords TEXT[] := ARRAY['em', 'de', 'da', 'do', 'para', 'com', 'por', 'a', 'o', 'e', 'ou', 'que', 'um', 'uma', 'os', 'as', 'na', 'no', 'ao', 'aos', 'pela', 'pelo'];
BEGIN
    v_name_clean := LOWER(unaccent(COALESCE(p_name, '')));
    v_name_clean := regexp_replace(v_name_clean, '[^a-z0-9\s]', ' ', 'g');
    v_name_clean := regexp_replace(v_name_clean, '\s+', ' ', 'g');
    
    v_words := string_to_array(TRIM(v_name_clean), ' ');
    
    FOREACH v_word IN ARRAY v_words LOOP
        IF LENGTH(v_word) >= 3 AND NOT v_word = ANY(v_stopwords) THEN
            v_keywords := array_append(v_keywords, v_word);
        END IF;
    END LOOP;
    
    SELECT array_agg(DISTINCT x) INTO v_keywords FROM unnest(v_keywords) x;
    
    RETURN COALESCE(v_keywords, '{}');
END;
$$;


ALTER FUNCTION "public"."fn_extract_keywords_from_name"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_extract_kit_dims_from_somarcas_bronze"("p_limit" integer DEFAULT 500) RETURNS TABLE("component_id" "uuid", "component_name" "text", "dims_raw" "text", "length_mm" integer, "width_mm" integer, "height_mm" integer, "weight_g" integer, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rec   RECORD;
  v_dims  TEXT;
  v_peso  TEXT;
  v_3d    TEXT[]; v_2d TEXT[];
  v_len   NUMERIC; v_wid NUMERIC; v_hgt NUMERIC; v_wgt NUMERIC;
  v_unit  TEXT;
  v_is_pkg BOOLEAN;
  v_rid   UUID; v_pad_id UUID;
BEGIN
  FOR v_rec IN
    SELECT DISTINCT ON (pkc.id)
      pkc.id AS comp_id, pkc.kit_product_id,
      pkc.component_name, pkc.component_type_code, pkc.is_packaging,
      spr.raw_data->>'dimensoes_do_produto' AS dims_raw,
      spr.raw_data->>'peso_da_embalagem'    AS peso_raw
    FROM product_kit_components pkc
    JOIN products p ON p.id = pkc.kit_product_id
    JOIN suppliers s ON s.id = p.supplier_id AND s.name = 'Só Marcas'
    JOIN supplier_products_raw spr ON spr.product_id = p.id AND spr.supplier_id = s.id
    WHERE pkc.enrichment_status = 'missing'
      AND (spr.raw_data->>'dimensoes_do_produto' IS NOT NULL
           OR spr.raw_data->>'peso_da_embalagem' IS NOT NULL)
    ORDER BY pkc.id, spr.updated_at DESC
    LIMIT p_limit
  LOOP
    v_len:=NULL; v_wid:=NULL; v_hgt:=NULL; v_wgt:=NULL;
    v_dims := v_rec.dims_raw;
    v_peso := v_rec.peso_raw;
    v_is_pkg := v_rec.is_packaging;

    IF v_dims IS NOT NULL AND v_dims != '' AND v_dims !~ '^0x0' THEN
      -- Detectar unidade
      v_unit := CASE WHEN v_dims ~* 'mm' THEN 'mm' ELSE 'cm' END;
      -- Normalizar: vírgula → ponto
      v_dims := regexp_replace(v_dims, ',', '.', 'g');
      -- Remover unidades: cm, mm, metros
      v_dims := regexp_replace(v_dims, '(?:mm|cm|m)', '', 'gi');
      -- Tentar 3D
      v_3d := regexp_match(v_dims, '(\d+(?:\.\d+)?)\s*[xX×]\s*(\d+(?:\.\d+)?)\s*[xX×]\s*(\d+(?:\.\d+)?)');
      IF v_3d IS NOT NULL THEN
        v_len:=v_3d[1]::NUMERIC; v_wid:=v_3d[2]::NUMERIC; v_hgt:=v_3d[3]::NUMERIC;
        IF v_unit='cm' THEN v_len:=v_len*10; v_wid:=v_wid*10; v_hgt:=v_hgt*10; END IF;
      ELSE
        -- Tentar 2D
        v_2d := regexp_match(v_dims, '(\d+(?:\.\d+)?)\s*[xX×]\s*(\d+(?:\.\d+)?)');
        IF v_2d IS NOT NULL THEN
          v_len:=v_2d[1]::NUMERIC; v_hgt:=v_2d[2]::NUMERIC;
          IF v_unit='cm' THEN v_len:=v_len*10; v_hgt:=v_hgt*10; END IF;
        END IF;
      END IF;
    END IF;

    -- Peso: "147 g" | "0.250 kg" | "250g"
    IF v_peso IS NOT NULL AND v_peso ~ '\d' THEN
      IF v_peso ~* 'kg' THEN
        v_wgt := (regexp_match(regexp_replace(v_peso,',','.','g'), '(\d+(?:\.\d+)?)(?:\s*kg)'))[1]::NUMERIC * 1000;
      ELSE
        v_wgt := (regexp_match(v_peso, '(\d+(?:[.,]\d+)?)'))[1]::NUMERIC;
        IF v_wgt < 1 THEN v_wgt := v_wgt * 1000; END IF;
      END IF;
    END IF;

    IF COALESCE(v_len,0)>0 OR COALESCE(v_wgt,0)>0 THEN
      BEGIN
        v_rid := fn_extract_dimensions_from_text(
          v_rec.comp_id,
          'somarcas_dimensoes: '||COALESCE(v_rec.dims_raw,'')||' peso:'||COALESCE(v_rec.peso_raw,''),
          jsonb_strip_nulls(jsonb_build_object(
            'unit','mm',
            'length_mm', CASE WHEN COALESCE(v_len,0)>0 THEN v_len::INTEGER END,
            'width_mm',  CASE WHEN COALESCE(v_wid,0)>0 THEN v_wid::INTEGER END,
            'height_mm', CASE WHEN COALESCE(v_hgt,0)>0 THEN v_hgt::INTEGER END,
            'weight_g',  CASE WHEN COALESCE(v_wgt,0)>0 THEN v_wgt::INTEGER END,
            'shape_type','rectangular',
            'is_packaging',v_is_pkg,
            'source_field','dimensoes_do_produto'
          )),
          0.80
        );
        PERFORM fn_standardize_kit_component(v_rid);
        UPDATE kit_component_padronizacao SET padronizacao_status='approved',reviewed_at=NOW()
        WHERE raw_id=v_rid AND padronizacao_status='pending';
        SELECT id INTO v_pad_id FROM kit_component_padronizacao WHERE raw_id=v_rid AND padronizacao_status='approved' LIMIT 1;
        IF v_pad_id IS NOT NULL THEN PERFORM fn_promote_kit_component_padronizacao(v_pad_id); END IF;
        component_id:=v_rec.comp_id; component_name:=v_rec.component_name;
        dims_raw:=v_rec.dims_raw; length_mm:=v_len::INTEGER; width_mm:=v_wid::INTEGER;
        height_mm:=v_hgt::INTEGER; weight_g:=v_wgt::INTEGER; status:='extracted'; RETURN NEXT;
      EXCEPTION WHEN OTHERS THEN
        component_id:=v_rec.comp_id; component_name:=v_rec.component_name;
        dims_raw:=v_rec.dims_raw; length_mm:=NULL; width_mm:=NULL; height_mm:=NULL; weight_g:=NULL;
        status:='error: '||SQLERRM; RETURN NEXT;
      END;
    ELSE
      component_id:=v_rec.comp_id; component_name:=v_rec.component_name;
      dims_raw:=v_rec.dims_raw; length_mm:=NULL; width_mm:=NULL; height_mm:=NULL; weight_g:=NULL;
      status:='no_dims'; RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_extract_kit_dims_from_somarcas_bronze"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_extract_kit_dims_from_spot_bronze"("p_limit" integer DEFAULT 500) RETURNS TABLE("component_id" "uuid", "component_name" "text", "component_type" "text", "matched_segment" "text", "length_mm" integer, "width_mm" integer, "height_mm" integer, "diameter_mm" integer, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rec   RECORD;
  v_segs  TEXT[];
  v_seg   TEXT;
  v_match TEXT;
  v_len   NUMERIC; v_wid NUMERIC; v_hgt NUMERIC; v_dia NUMERIC;
  v_3d    TEXT[]; v_2d TEXT[]; v_dia_t TEXT[];
  v_is_pkg BOOLEAN;
  v_rid   UUID; v_pad_id UUID;
BEGIN
  FOR v_rec IN
    SELECT DISTINCT ON (pkc.id)
      pkc.id          AS comp_id,
      pkc.kit_product_id,
      pkc.component_name,
      pkc.component_type_code,
      pkc.is_packaging,
      spr.raw_data->>'CombinedSizes' AS combined
    FROM product_kit_components pkc
    JOIN products p ON p.id = pkc.kit_product_id
    JOIN suppliers s ON s.id = p.supplier_id AND s.name = 'Spot | Stricker'
    JOIN supplier_products_raw spr ON spr.product_id = p.id AND spr.supplier_id = s.id
    WHERE pkc.enrichment_status = 'missing'
      AND spr.raw_data->>'CombinedSizes' IS NOT NULL
      AND spr.raw_data->>'CombinedSizes' != ''
    ORDER BY pkc.id, spr.updated_at DESC
    LIMIT p_limit
  LOOP
    v_match := NULL; v_len := NULL; v_wid := NULL; v_hgt := NULL; v_dia := NULL;
    v_segs  := string_to_array(v_rec.combined, ' | ');
    v_is_pkg := v_rec.component_type_code IN ('CAIXA','NECESSAIRE','ESTOJO_NYLON',
      'ESTOJO_ALUMINIO','ESTOJO_BAMBU','ESTOJO_PU','ESTOJO');

    -- FASE 1: match por label no segmento
    FOREACH v_seg IN ARRAY v_segs LOOP
      IF v_match IS NOT NULL THEN CONTINUE; END IF;
      IF  (v_rec.component_type_code = 'TABUA'        AND v_seg ~* '(?:tábua|tabua)')
       OR (v_rec.component_type_code IN ('FACA','FACA_TRINCHAR') AND v_seg ~* '(?:faca|talher|chaira|pão|queijo|chefe|japonesa|legumes|boning|média|pequena|trinchar)')
       OR (v_rec.component_type_code = 'GARFO'        AND v_seg ~* '(?:garfo|fork)')
       OR (v_rec.component_type_code = 'COLHER'       AND v_seg ~* '(?:colher|spoon|colh)')
       OR (v_rec.component_type_code = 'CHAIRA'       AND v_seg ~* '(?:chaira|steel|afiador)')
       OR (v_rec.component_type_code = 'SACA_ROLHAS'  AND v_seg ~* '(?:saca|rolha|abridor|sommelier)')
       OR (v_rec.component_type_code IN ('CAIXA','NECESSAIRE') AND v_seg ~* '(?:caixa|estojo|box|almofad|presente|kraft|bambu|lata|cortiça|hermét|garrafa|cartão)')
       OR (v_rec.component_type_code = 'ESTOJO_NYLON' AND v_seg ~* '(?:estojo|mala|bolsa|nylon|210d|pouch|algodão|190t|eva|pu)')
       OR (v_rec.component_type_code = 'ESTOJO_ALUMINIO' AND v_seg ~* '(?:estojo|alumin)')
       OR (v_rec.component_type_code = 'CHAVEIRO'     AND v_seg ~* '(?:chaveiro|keychain)')
       OR (v_rec.component_type_code = 'PORTA_CARTAO' AND v_seg ~* '(?:porta.?cart|card)')
       OR (v_rec.component_type_code = 'CANETA'       AND v_seg ~* '(?:esfer|roller|caneta|pen|lápis|lapiseira|ponteira|touch)')
       OR (v_rec.component_type_code = 'CADERNO'      AND v_seg ~* '(?:caderno|notebook|bloco)')
       OR (v_rec.component_type_code = 'ALMOFADA'     AND v_seg ~* '(?:almofada)')
       THEN v_match := v_seg;
      END IF;
    END LOOP;

    -- FASE 2: fallback primeiro segmento sem label
    IF v_match IS NULL AND array_length(v_segs,1) >= 1 THEN
      IF v_segs[1] !~ '^[A-ZÀ-ú][A-Za-zÀ-ú ]+:' AND v_segs[1] ~ '\d+' THEN
        v_match := v_segs[1];
      END IF;
    END IF;

    -- EXTRAIR DIMENSÕES do segmento
    IF v_match IS NOT NULL THEN
      -- ø (cilíndrico)
      v_dia_t := regexp_match(regexp_replace(v_match,',','.','g'),
        'ø\s*(\d+(?:\.\d+)?)\s*[xX×]\s*(\d+(?:\.\d+)?)');
      IF v_dia_t IS NOT NULL THEN
        v_dia := v_dia_t[1]::NUMERIC; v_hgt := v_dia_t[2]::NUMERIC;
        IF v_dia < 20 THEN v_dia := v_dia*10; END IF;
        IF v_hgt < 20 THEN v_hgt := v_hgt*10; END IF;
      ELSE
        -- 3D
        v_3d := regexp_match(regexp_replace(v_match,',','.','g'),
          '(\d+(?:\.\d+)?)\s*[xX×]\s*(\d+(?:\.\d+)?)\s*[xX×]\s*(\d+(?:\.\d+)?)');
        IF v_3d IS NOT NULL THEN
          v_len := v_3d[1]::NUMERIC; v_wid := v_3d[2]::NUMERIC; v_hgt := v_3d[3]::NUMERIC;
          IF v_len<30 AND v_wid<30 AND v_hgt<30 THEN v_len:=v_len*10; v_wid:=v_wid*10; v_hgt:=v_hgt*10; END IF;
        ELSE
          -- 2D
          v_2d := regexp_match(regexp_replace(v_match,',','.','g'),
            '(\d+(?:\.\d+)?)\s*[xX×]\s*(\d+(?:\.\d+)?)');
          IF v_2d IS NOT NULL THEN
            v_len := v_2d[1]::NUMERIC; v_hgt := v_2d[2]::NUMERIC;
            IF v_len<30 AND v_hgt<30 THEN v_len:=v_len*10; v_hgt:=v_hgt*10; END IF;
          END IF;
        END IF;
      END IF;
    END IF;

    -- COMITAR se tem pelo menos 1 dimensão
    IF COALESCE(v_len,0)>0 OR COALESCE(v_dia,0)>0 THEN
      BEGIN
        v_rid := fn_extract_dimensions_from_text(
          v_rec.comp_id,
          'spot_combined_sizes: '||COALESCE(v_rec.combined,''),
          jsonb_strip_nulls(jsonb_build_object(
            'unit','mm',
            'length_mm',   CASE WHEN COALESCE(v_len,0)>0 THEN v_len::INTEGER END,
            'width_mm',    CASE WHEN COALESCE(v_wid,0)>0 THEN v_wid::INTEGER END,
            'height_mm',   CASE WHEN COALESCE(v_hgt,0)>0 THEN v_hgt::INTEGER END,
            'diameter_mm', CASE WHEN COALESCE(v_dia,0)>0 THEN v_dia::INTEGER END,
            'shape_type',  CASE WHEN COALESCE(v_dia,0)>0 THEN 'cylindrical' ELSE 'rectangular' END,
            'is_packaging', v_is_pkg,
            'source_field','CombinedSizes'
          )),
          0.85
        );
        PERFORM fn_standardize_kit_component(v_rid);
        UPDATE kit_component_padronizacao SET padronizacao_status='approved',reviewed_at=NOW()
        WHERE raw_id=v_rid AND padronizacao_status='pending';
        SELECT id INTO v_pad_id FROM kit_component_padronizacao WHERE raw_id=v_rid AND padronizacao_status='approved' LIMIT 1;
        IF v_pad_id IS NOT NULL THEN PERFORM fn_promote_kit_component_padronizacao(v_pad_id); END IF;
        component_id:=v_rec.comp_id; component_name:=v_rec.component_name; component_type:=v_rec.component_type_code;
        matched_segment:=v_match; length_mm:=v_len::INTEGER; width_mm:=v_wid::INTEGER;
        height_mm:=v_hgt::INTEGER; diameter_mm:=v_dia::INTEGER; status:='extracted'; RETURN NEXT;
      EXCEPTION WHEN OTHERS THEN
        component_id:=v_rec.comp_id; component_name:=v_rec.component_name; component_type:=v_rec.component_type_code;
        matched_segment:=v_match; length_mm:=NULL; width_mm:=NULL; height_mm:=NULL; diameter_mm:=NULL;
        status:='error: '||SQLERRM; RETURN NEXT;
      END;
    ELSE
      component_id:=v_rec.comp_id; component_name:=v_rec.component_name; component_type:=v_rec.component_type_code;
      matched_segment:=v_match; length_mm:=NULL; width_mm:=NULL; height_mm:=NULL; diameter_mm:=NULL;
      status:='no_dims'; RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_extract_kit_dims_from_spot_bronze"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_extract_kit_dims_from_xbz_bronze"("p_limit" integer DEFAULT 300) RETURNS TABLE("component_id" "uuid", "component_name" "text", "length_mm" integer, "width_mm" integer, "height_mm" integer, "weight_g" integer, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_rec RECORD; v_rid UUID; v_pad_id UUID;
BEGIN
  FOR v_rec IN
    SELECT DISTINCT ON (pkc.id)
      pkc.id AS comp_id, pkc.kit_product_id, pkc.component_name, pkc.component_type_code, pkc.is_packaging,
      (spr.raw_data->>'Profundidade')::NUMERIC AS len,
      (spr.raw_data->>'Largura')::NUMERIC      AS wid,
      (spr.raw_data->>'Altura')::NUMERIC       AS hgt,
      (spr.raw_data->>'Peso')::NUMERIC         AS wgt
    FROM product_kit_components pkc
    JOIN products p ON p.id = pkc.kit_product_id
    JOIN suppliers s ON s.id = p.supplier_id AND s.code = 'XBZ'
    JOIN supplier_products_raw spr ON spr.product_id = p.id AND spr.supplier_id = s.id
    WHERE pkc.enrichment_status = 'missing'
      AND (
        (spr.raw_data->>'Profundidade')::NUMERIC > 0 OR
        (spr.raw_data->>'Largura')::NUMERIC > 0 OR
        (spr.raw_data->>'Altura')::NUMERIC > 0
      )
    ORDER BY pkc.id, spr.updated_at DESC
    LIMIT p_limit
  LOOP
    IF COALESCE(v_rec.len,0)>0 OR COALESCE(v_rec.wid,0)>0 OR COALESCE(v_rec.hgt,0)>0 THEN
      BEGIN
        v_rid := fn_extract_dimensions_from_text(
          v_rec.comp_id,
          'xbz_bronze: Profundidade='||v_rec.len||' Largura='||v_rec.wid||' Altura='||v_rec.hgt||' Peso='||v_rec.wgt,
          jsonb_strip_nulls(jsonb_build_object(
            'unit','mm',
            'length_mm',  CASE WHEN COALESCE(v_rec.len,0)>0 THEN v_rec.len::INTEGER END,
            'width_mm',   CASE WHEN COALESCE(v_rec.wid,0)>0 THEN v_rec.wid::INTEGER END,
            'height_mm',  CASE WHEN COALESCE(v_rec.hgt,0)>0 THEN v_rec.hgt::INTEGER END,
            'weight_g',   CASE WHEN COALESCE(v_rec.wgt,0)>0 THEN v_rec.wgt::INTEGER END,
            'is_packaging', v_rec.is_packaging,
            'shape_type', 'rectangular',
            'source_field','xbz_bronze'
          )), 0.80
        );
        PERFORM fn_standardize_kit_component(v_rid);
        UPDATE kit_component_padronizacao SET padronizacao_status='approved',reviewed_at=NOW()
        WHERE raw_id=v_rid AND padronizacao_status='pending';
        SELECT id INTO v_pad_id FROM kit_component_padronizacao WHERE raw_id=v_rid AND padronizacao_status='approved' LIMIT 1;
        IF v_pad_id IS NOT NULL THEN PERFORM fn_promote_kit_component_padronizacao(v_pad_id); END IF;
        component_id:=v_rec.comp_id; component_name:=v_rec.component_name;
        length_mm:=v_rec.len::INTEGER; width_mm:=v_rec.wid::INTEGER;
        height_mm:=v_rec.hgt::INTEGER; weight_g:=v_rec.wgt::INTEGER;
        status:='extracted'; RETURN NEXT;
      EXCEPTION WHEN OTHERS THEN
        component_id:=v_rec.comp_id; component_name:=v_rec.component_name;
        length_mm:=NULL; width_mm:=NULL; height_mm:=NULL; weight_g:=NULL;
        status:='error: '||SQLERRM; RETURN NEXT;
      END;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_extract_kit_dims_from_xbz_bronze"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_extract_material_from_name"("p_name" "text") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_name_lower TEXT;
  v_materials TEXT[] := '{}';
BEGIN
  v_name_lower := LOWER(unaccent(COALESCE(p_name, '')));

  -- ── Metais ─────────────────────────────────────────────────────────
  IF v_name_lower ~ '\m(aco\s*inox|inox|stainless)\M' THEN v_materials := array_append(v_materials, 'Aço Inox'); END IF;
  IF v_name_lower ~ '\m(aluminio|aluminum)\M' THEN v_materials := array_append(v_materials, 'Alumínio'); END IF;
  IF v_name_lower ~ '\m(metal)\M' AND NOT v_name_lower ~ '\m(inox|aluminio)\M' THEN v_materials := array_append(v_materials, 'Metal'); END IF;
  IF v_name_lower ~ '\m(latao|brass)\M' THEN v_materials := array_append(v_materials, 'Latão'); END IF;
  IF v_name_lower ~ '\m(zinco|zinc)\M' THEN v_materials := array_append(v_materials, 'Zinco'); END IF;

  -- ── Plásticos ──────────────────────────────────────────────────────
  IF v_name_lower ~ '\m(plastico|plastic)\M' THEN v_materials := array_append(v_materials, 'Plástico'); END IF;
  IF v_name_lower ~ '\m(abs)\M' THEN v_materials := array_append(v_materials, 'ABS'); END IF;
  IF v_name_lower ~ '\m(rabs|r-abs)\M' THEN v_materials := array_append(v_materials, 'rABS'); END IF;
  IF v_name_lower ~ '\m(pp|polipropileno)\M' THEN v_materials := array_append(v_materials, 'Polipropileno (PP)'); END IF;
  IF v_name_lower ~ '\m(rpet|r-pet)\M' THEN v_materials := array_append(v_materials, 'rPET'); END IF;
  IF v_name_lower ~ '\m(pet)\M' AND NOT v_name_lower ~ '\m(rpet)\M' THEN v_materials := array_append(v_materials, 'PET'); END IF;
  IF v_name_lower ~ '\m(pc|policarbonato)\M' THEN v_materials := array_append(v_materials, 'Policarbonato'); END IF;
  IF v_name_lower ~ '\m(ps|poliestireno)\M' THEN v_materials := array_append(v_materials, 'Poliestireno (PS)'); END IF;
  IF v_name_lower ~ '\m(pvc)\M' THEN v_materials := array_append(v_materials, 'PVC'); END IF;
  IF v_name_lower ~ '\m(silicone)\M' THEN v_materials := array_append(v_materials, 'Silicone'); END IF;
  IF v_name_lower ~ '\m(tritan)\M' THEN v_materials := array_append(v_materials, 'Tritan'); END IF;
  IF v_name_lower ~ '\m(acrilico)\M' THEN v_materials := array_append(v_materials, 'Acrílico'); END IF;

  -- ── Vidro ──────────────────────────────────────────────────────────
  IF v_name_lower ~ '\m(vidro|glass|borossilicato)\M' THEN v_materials := array_append(v_materials, 'Vidro'); END IF;

  -- ── Madeira / Natural ──────────────────────────────────────────────
  IF v_name_lower ~ '\m(madeira|wood|mdf)\M' THEN v_materials := array_append(v_materials, 'Madeira'); END IF;
  IF v_name_lower ~ '\m(bambu|bamboo)\M' THEN v_materials := array_append(v_materials, 'Bambu'); END IF;
  IF v_name_lower ~ '\m(cortica|cork)\M' THEN v_materials := array_append(v_materials, 'Cortiça'); END IF;

  -- ── Fibras naturais e sustentáveis (NOVO) ──────────────────────────
  IF v_name_lower ILIKE '%fibra de coco%' OR v_name_lower ILIKE '%coco%' AND v_name_lower ILIKE '%fibra%' THEN v_materials := array_append(v_materials, 'Fibra de Coco'); END IF;
  IF v_name_lower ILIKE '%fibra de arroz%' OR v_name_lower ILIKE '%arroz%' AND v_name_lower ILIKE '%fibra%' THEN v_materials := array_append(v_materials, 'Fibra de Arroz'); END IF;
  IF v_name_lower ILIKE '%fibra de cana%' THEN v_materials := array_append(v_materials, 'Fibra de Cana'); END IF;
  IF v_name_lower ILIKE '%fibra de cafe%' OR v_name_lower ILIKE '%fibra de café%' THEN v_materials := array_append(v_materials, 'Fibra de Café'); END IF;
  IF v_name_lower ILIKE '%percalux%' THEN v_materials := array_append(v_materials, 'Percalux'); END IF;
  IF v_name_lower ILIKE '%kraft%' THEN v_materials := array_append(v_materials, 'Papel Kraft'); END IF;
  IF v_name_lower ILIKE '%linho%' THEN v_materials := array_append(v_materials, 'Linho'); END IF;

  -- ── Tecidos ────────────────────────────────────────────────────────
  IF v_name_lower ~ '\m(algodao|cotton)\M' THEN v_materials := array_append(v_materials, 'Algodão'); END IF;
  IF v_name_lower ~ '\m(poliester|polyester)\M' THEN v_materials := array_append(v_materials, 'Poliéster'); END IF;
  IF v_name_lower ~ '\m(nylon|nailon)\M' THEN v_materials := array_append(v_materials, 'Nylon'); END IF;
  IF v_name_lower ~ '\m(tnt|non.?woven)\M' THEN v_materials := array_append(v_materials, 'TNT'); END IF;
  IF v_name_lower ~ '\m(lona|canvas)\M' THEN v_materials := array_append(v_materials, 'Lona'); END IF;
  IF v_name_lower ~ '\m(juta|jute)\M' THEN v_materials := array_append(v_materials, 'Juta'); END IF;
  IF v_name_lower ~ '\m(couro|leather)\M' THEN v_materials := array_append(v_materials, 'Couro'); END IF;
  IF v_name_lower ~ '\m(sintetico|courino|pu)\M' THEN v_materials := array_append(v_materials, 'Couro Sintético'); END IF;

  -- ── Borracha / Espuma ──────────────────────────────────────────────
  IF v_name_lower ~ '\m(borracha|rubber)\M' THEN v_materials := array_append(v_materials, 'Borracha'); END IF;
  IF v_name_lower ~ '\m(espuma|foam)\M' THEN v_materials := array_append(v_materials, 'Espuma'); END IF;

  -- ── Papel / Cartão ─────────────────────────────────────────────────
  IF v_name_lower ~ '\m(papel|paper)\M' AND NOT v_name_lower ILIKE '%kraft%' THEN v_materials := array_append(v_materials, 'Papel'); END IF;
  IF v_name_lower ~ '\m(cartao|cardboard)\M' THEN v_materials := array_append(v_materials, 'Cartão'); END IF;
  IF v_name_lower ~ '\m(reciclado|recycled)\M' THEN v_materials := array_append(v_materials, 'Reciclado'); END IF;

  -- ── Cerâmica ───────────────────────────────────────────────────────
  IF v_name_lower ~ '\m(ceramica|ceramic|porcelana)\M' THEN v_materials := array_append(v_materials, 'Cerâmica'); END IF;

  RETURN v_materials;
END;
$$;


ALTER FUNCTION "public"."fn_extract_material_from_name"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_extract_material_from_name_or_desc"("p_name" "text", "p_description" "text" DEFAULT NULL::"text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN array_length(public.fn_extract_material_from_name(p_name), 1) > 0
      THEN public.fn_extract_material_from_name(p_name)
    ELSE
      public.fn_extract_material_from_name(
        COALESCE(p_description, '')
      )
  END;
$$;


ALTER FUNCTION "public"."fn_extract_material_from_name_or_desc"("p_name" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_extract_materials_from_name"("p_product_id" "uuid", "p_replace_existing" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_product RECORD;
    v_material RECORD;
    v_count INTEGER := 0;
    v_search_text TEXT;
    v_org_id UUID := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
    v_found_materials UUID[] := '{}';
    v_material_id UUID;
    v_percentage NUMERIC;
    v_n INTEGER;
    v_idx INTEGER;
    v_accumulated NUMERIC := 0;
BEGIN
    SELECT id, name, description, short_description, organization_id
    INTO v_product FROM products WHERE id = p_product_id;

    IF v_product.id IS NULL THEN RETURN 0; END IF;
    IF v_product.organization_id IS NOT NULL THEN v_org_id := v_product.organization_id; END IF;

    v_search_text := LOWER(COALESCE(v_product.name, '') || ' ' ||
                          COALESCE(v_product.description, '') || ' ' ||
                          COALESCE(v_product.short_description, ''));

    IF p_replace_existing THEN
        DELETE FROM product_materials WHERE product_id = p_product_id;
    ELSE
        IF EXISTS (SELECT 1 FROM product_materials WHERE product_id = p_product_id) THEN
            RETURN 0;
        END IF;
    END IF;

    FOR v_material IN SELECT mt.id, mt.name FROM material_types mt WHERE mt.is_active = true
    LOOP
        IF (
            (v_material.name = 'Alumínio' AND (v_search_text ILIKE '%alumínio%' OR v_search_text ILIKE '%aluminio%'))
            OR (v_material.name = 'Aço Inox' AND (v_search_text ILIKE '%aço inox%' OR v_search_text ILIKE '%inox%'))
            OR (v_material.name = 'Metal Genérico' AND (v_search_text ILIKE '%em metal%' OR v_search_text ILIKE '%e metal%' OR v_search_text ILIKE '% metal %'))
            OR (v_material.name = 'Zinco' AND v_search_text ILIKE '%zinco%')
            OR (v_material.name = 'Cobre' AND v_search_text ILIKE '%cobre%')
            OR (v_material.name = 'Bronze' AND v_search_text ILIKE '%bronze%')
            OR (v_material.name ILIKE '%ABS%' AND (v_search_text ILIKE '% abs %' OR v_search_text ILIKE '%e abs%' OR v_search_text ILIKE '%em abs%' OR v_search_text ILIKE '%rabs%'))
            OR (v_material.name ILIKE '%PVC%' AND (v_search_text ILIKE '%pvc%' OR v_search_text ILIKE '% pu %' OR v_search_text ILIKE '%em pu%'))
            OR (v_material.name = 'Policarbonato' AND (v_search_text ILIKE '%policarbonato%' OR v_search_text ILIKE '% pc %' OR v_search_text ILIKE '%em pc%'))
            OR (v_material.name = 'Polipropileno (PP)' AND (v_search_text ILIKE '%polipropileno%' OR v_search_text ILIKE '% pp %' OR v_search_text ILIKE '%em pp%'))
            OR (v_material.name = 'Poliestireno - PS' AND (v_search_text ILIKE '%poliestireno%' OR v_search_text ILIKE '% ps %' OR v_search_text ILIKE '%e ps%'))
            OR (v_material.name = 'Plástico - PET' AND (v_search_text ILIKE '% pet %' OR v_search_text ILIKE '%em pet%' OR v_search_text ILIKE '%rpet%'))
            OR (v_material.name = 'Plástico - rPET' AND v_search_text ILIKE '%rpet%')
            OR (v_material.name = 'Acrílico' AND (v_search_text ILIKE '%acrílico%' OR v_search_text ILIKE '%acrilico%'))
            OR (v_material.name = 'Silicone' AND v_search_text ILIKE '%silicone%')
            OR (v_material.name = 'Tritan' AND v_search_text ILIKE '%tritan%')
            OR (v_material.name = 'EVA (Acetato de Vinila)' AND v_search_text ILIKE '%eva%')
            OR (v_material.name = 'POE (Poliolefina Elastomérica)' AND (v_search_text ILIKE '% poe %' OR v_search_text ILIKE '%em poe%'))
            OR (v_material.name = 'Poliéster' AND (v_search_text ILIKE '%poliéster%' OR v_search_text ILIKE '%poliester%' OR v_search_text ILIKE '%300d%' OR v_search_text ILIKE '%600d%' OR v_search_text ILIKE '%1680d%'))
            OR (v_material.name = 'Algodão' AND (v_search_text ILIKE '%algodão%' OR v_search_text ILIKE '%algodao%' OR v_search_text ILIKE '%canvas%' OR v_search_text ILIKE '%camiseta%'))
            OR (v_material.name = 'Nylon' AND v_search_text ILIKE '%nylon%')
            OR (v_material.name = 'Pongee' AND v_search_text ILIKE '%pongee%')
            OR (v_material.name = 'Oxford' AND v_search_text ILIKE '%oxford%')
            OR (v_material.name = 'Ripstop' AND (v_search_text ILIKE '%ripstop%' OR v_search_text ILIKE '%210d%'))
            OR (v_material.name = 'Jacquard' AND (v_search_text ILIKE '%jacquard%' OR v_search_text ILIKE '%840d%'))
            OR (v_material.name = 'Polar' AND v_search_text ILIKE '%polar%')
            OR (v_material.name = 'Microfibra' AND v_search_text ILIKE '%microfibra%')
            OR (v_material.name = 'Feltro' AND v_search_text ILIKE '%feltro%')
            OR (v_material.name = 'TNT (Nowen)' AND (v_search_text ILIKE '%tnt%' OR v_search_text ILIKE '%non-woven%' OR v_search_text ILIKE '%nonwoven%'))
            OR (v_material.name = 'Neoprene' AND v_search_text ILIKE '%neoprene%')
            OR (v_material.name = 'Fibras Naturais' AND (v_search_text ILIKE '%palha%' OR v_search_text ILIKE '%juta%' OR v_search_text ILIKE '%fibras naturais%'))
            OR (v_material.name = 'Bambu' AND v_search_text ILIKE '%bambu%')
            OR (v_material.name = 'Madeira' AND v_search_text ILIKE '%madeira%')
            OR (v_material.name = 'MDF' AND v_search_text ILIKE '%mdf%')
            OR (v_material.name = 'Cortiça' AND (v_search_text ILIKE '%cortiça%' OR v_search_text ILIKE '%cortica%'))
            OR (v_material.name = 'Vidro Borossilicado' AND v_search_text ILIKE '%borossilicato%')
            OR (v_material.name = 'Vidro' AND v_search_text ILIKE '%vidro%' AND NOT v_search_text ILIKE '%borossilicato%')
            OR (v_material.name = 'Cerâmica' AND (v_search_text ILIKE '%cerâmica%' OR v_search_text ILIKE '%ceramica%'))
            OR (v_material.name = 'Porcelana' AND v_search_text ILIKE '%porcelana%')
            OR (v_material.name ILIKE '%Couro%' AND (v_search_text ILIKE '%couro%' OR v_search_text ILIKE '%pele%' OR v_search_text ILIKE '%c.sintético%'))
            OR (v_material.name = 'Cartão' AND (v_search_text ILIKE '%cartão%' OR v_search_text ILIKE '%cartao%' OR v_search_text ILIKE '%papel pedra%' OR v_search_text ILIKE '%em papel%'))
            OR (v_material.name = 'Kraft' AND v_search_text ILIKE '%kraft%')
            OR (v_material.name = 'Borracha' AND v_search_text ILIKE '%borracha%')
            OR (v_material.name = 'Espuma' AND v_search_text ILIKE '%espuma%')
        )
        THEN
            v_found_materials := array_append(v_found_materials, v_material.id);
        END IF;
    END LOOP;

    v_n := COALESCE(array_length(v_found_materials, 1), 0);
    IF v_n > 0 THEN
        -- Distribuição com resíduo: os (n-1) primeiros recebem ROUND(100/n,2);
        -- o último recebe (100 - soma acumulada) garantindo total exato = 100.
        v_percentage := ROUND(100.0 / v_n, 2);
        v_idx := 0;
        FOREACH v_material_id IN ARRAY v_found_materials LOOP
            v_idx := v_idx + 1;
            IF v_idx < v_n THEN
                INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, sort_order, is_active)
                VALUES (v_org_id, p_product_id, v_material_id, 'corpo', v_percentage, v_idx, true);
                v_accumulated := v_accumulated + v_percentage;
            ELSE
                INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, sort_order, is_active)
                VALUES (v_org_id, p_product_id, v_material_id, 'corpo', ROUND(100 - v_accumulated, 2), v_idx, true);
            END IF;
            v_count := v_count + 1;
        END LOOP;
    END IF;

    RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_extract_materials_from_name"("p_product_id" "uuid", "p_replace_existing" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_extract_notebook_feature_codes"("p_tags" "jsonb", "p_description" "text", "p_name" "text") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_all    text := lower(
    coalesce(p_tags::text,'') || ' ' ||
    coalesce(p_description,'') || ' ' ||
    coalesce(p_name,'')
  );
  v_result text[] := ARRAY[]::text[];
BEGIN
  -- ELASTIC
  IF v_all ILIKE ANY(ARRAY[
    '%elástico%','%elastico%','%faixa elástica%','%tira elástica%',
    '%lacre%','%fecho elástico%','%elastic closure%','%elastic band%'
  ]) THEN v_result := array_append(v_result, 'ELASTIC'); END IF;

  -- BOOKMARK
  IF v_all ILIKE ANY(ARRAY[
    '%marca-página%','%marca página%','%marcador de página%',
    '%marcador em fita%','%fita marcadora%','%ribbon%',
    '%fita de cetim%','%fita cetim%','%bookmark%','%fita marcação%'
  ]) THEN v_result := array_append(v_result, 'BOOKMARK'); END IF;

  -- MULTIPLE_BOOKMARK — quando menciona 2+ marcadores (adiciona BOOKMARK se não está)
  IF v_all ILIKE ANY(ARRAY['%2 fitas%','%duas fitas%','%múltiplos marcadores%','%multiple bookmark%']) THEN
    IF NOT ('BOOKMARK' = ANY(v_result)) THEN
      v_result := array_append(v_result, 'BOOKMARK');
    END IF;
    v_result := array_append(v_result, 'MULTIPLE_BOOKMARK');
  END IF;

  -- POCKET
  IF v_all ILIKE ANY(ARRAY[
    '%bolso%','%pocket%','%compartimento%','%bolso frontal%',
    '%bolso na contracapa%','%bolso interior%'
  ]) THEN v_result := array_append(v_result, 'POCKET'); END IF;

  -- PEN_LOOP
  IF v_all ILIKE ANY(ARRAY[
    '%porta-caneta%','%porta caneta%','%suporte para caneta%',
    '%suporte para esferográfica%','%suporte para lapiseira%',
    '%loop caneta%','%pen loop%','%pen holder%','%porta-esferográfica%'
  ]) THEN v_result := array_append(v_result, 'PEN_LOOP'); END IF;

  -- ROUNDED
  IF v_all ILIKE ANY(ARRAY['%cantos arredondados%','%rounded corners%']) THEN
    v_result := array_append(v_result, 'ROUNDED');
  END IF;

  -- PERFORATED
  IF v_all ILIKE ANY(ARRAY[
    '%microperfurado%','%perfurad%','%destacável%','%destaca%','%perforated%','%folhas removíveis%'
  ]) THEN v_result := array_append(v_result, 'PERFORATED'); END IF;

  -- NUMBERED
  IF v_all ILIKE ANY(ARRAY['%páginas numeradas%','%numeração%','%numbered%','%paginado%']) THEN
    v_result := array_append(v_result, 'NUMBERED');
  END IF;

  -- INDEX
  IF v_all ILIKE ANY(ARRAY['%índice%','%indice%','%index%','%sumário%']) THEN
    v_result := array_append(v_result, 'INDEX');
  END IF;

  -- CALENDAR
  IF v_all ILIKE ANY(ARRAY['%calendário%','%calendario%','%calendar%','%datas%importantes%']) THEN
    v_result := array_append(v_result, 'CALENDAR');
  END IF;

  -- MAGNETIC
  IF v_all ILIKE ANY(ARRAY[
    '%fecho magnético%','%fecho magnetico%','%magnetic%','%imã%','%magnético%'
  ]) THEN v_result := array_append(v_result, 'MAGNETIC'); END IF;

  -- PEN_INCLUDED — caneta explicitamente inclusa
  -- (inclusa) e (incluída) são variações do mesmo
  IF v_all ILIKE ANY(ARRAY[
    '%(inclusa)%','%caneta inclusa%','%esferográfica inclusa%',
    '%inclui caneta%','%inclui esferográfica%','%caneta incluída%',
    '% com caneta%','%(incluída)%','%esferográfica incluída%'
  ]) THEN v_result := array_append(v_result, 'PEN_INCLUDED'); END IF;

  -- PENCIL_INCLUDED — lápis incluído
  IF v_all ILIKE ANY(ARRAY[
    '%inclus%lápis%','%inclui lápis%','%lápis inclus%','%pencil%'
  ]) AND v_all NOT ILIKE '%porta-lápis%' THEN
    v_result := array_append(v_result, 'PENCIL_INCLUDED');
  END IF;

  -- RULER
  IF v_all ILIKE ANY(ARRAY['%régua%','%regua%','%ruler%']) THEN
    v_result := array_append(v_result, 'RULER');
  END IF;

  -- STICKY_NOTES — bloco adesivo ou autoadesivo no produto
  IF v_all ILIKE ANY(ARRAY[
    '%bloco adesivo%','%sticky%','%post-it%','%notas adesivas inclus%',
    '%autoadesivo inclus%','%bloco de notas autoadesivo%'
  ]) THEN v_result := array_append(v_result, 'STICKY_NOTES'); END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_extract_notebook_feature_codes"("p_tags" "jsonb", "p_description" "text", "p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_extract_notebook_feature_codes"("p_tags" "jsonb", "p_description" "text", "p_name" "text") IS 'Extrai array de feature codes de notebooks de tags + descrição. Retorna ARRAY vazio se nenhuma feature detectada.';



CREATE OR REPLACE FUNCTION "public"."fn_extract_numeric"("p_value" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_clean TEXT;
    v_result DECIMAL;
BEGIN
    IF p_value IS NULL THEN
        RETURN NULL;
    END IF;
    
    -- Remove tudo exceto números, ponto e vírgula
    v_clean := REGEXP_REPLACE(p_value, '[^0-9.,]', '', 'g');
    
    -- Troca vírgula por ponto
    v_clean := REPLACE(v_clean, ',', '.');
    
    -- Se tiver múltiplos pontos, mantém apenas o último como decimal
    IF LENGTH(v_clean) - LENGTH(REPLACE(v_clean, '.', '')) > 1 THEN
        v_clean := REPLACE(v_clean, '.', '', LENGTH(v_clean) - POSITION('.' IN REVERSE(v_clean)));
    END IF;
    
    BEGIN
        v_result := v_clean::DECIMAL;
    EXCEPTION WHEN OTHERS THEN
        v_result := NULL;
    END;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_extract_numeric"("p_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_extract_numeric"("p_value" "text") IS 'Extrai valor numérico de string com unidade (ex: "500 mL" → 500)';



CREATE OR REPLACE FUNCTION "public"."fn_extract_optional_packaging_ref"("p_description" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE v_match TEXT[];
BEGIN
    IF p_description IS NULL THEN RETURN NULL; END IF;

    -- Padrão 1: "Caixa branca 94651 vendida opcionalmente"
    v_match := regexp_match(p_description, '[Cc]aixa\s+\w*\s*(\d{5})\s+vendida?\s+opcionalmente', 'i');
    IF v_match IS NOT NULL AND v_match[1] IS NOT NULL THEN RETURN v_match[1]; END IF;

    -- Padrão 2: "embalagem opcional: 94651" ou "embalagem vendida opcionalmente: 94651"
    v_match := regexp_match(p_description, 'embalagem\s+(?:opcional|vendida\s+opcionalmente)[:\s]+(\d{5})', 'i');
    IF v_match IS NOT NULL AND v_match[1] IS NOT NULL THEN RETURN v_match[1]; END IF;

    -- Padrão 3: genérico "\d{5} (embalagem/bolsa/caixa)" com contexto "opcionalmente"
    v_match := regexp_match(p_description, '(\d{5})\s+\((?:bolsa|caixa|estojo|saco|sacola)[^)]*\).*opcionalmente', 'i');
    IF v_match IS NOT NULL AND v_match[1] IS NOT NULL THEN RETURN v_match[1]; END IF;

    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_extract_optional_packaging_ref"("p_description" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_extract_optional_packaging_ref"("p_description" "text") IS 'Extrai a referência de embalagem opcional da descrição do produto';



CREATE OR REPLACE FUNCTION "public"."fn_extract_packaging_from_description"("p_description" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_desc TEXT;
    v_type TEXT := NULL;
    v_text TEXT := NULL;
    v_gift BOOLEAN := FALSE;
    v_m TEXT[];
BEGIN
    IF p_description IS NULL OR TRIM(p_description) = '' THEN
        RETURN jsonb_build_object('found',FALSE,'packaging_type',NULL,'packaging_text',NULL,'is_gift_packaging',FALSE,'source','description');
    END IF;
    v_desc := LOWER(TRIM(p_description));

    -- P1: fornecid[oa]s? em X
    v_m := regexp_match(v_desc,'fornecid[oa]s?\s+em\s+(polybag|poly[\s-]?bag)','i');
    IF v_m[1] IS NOT NULL THEN v_type:='protective'; v_text:=v_m[1]; v_gift:=FALSE; END IF;

    IF v_type IS NULL THEN
        v_m := regexp_match(v_desc,'fornecid[oa]s?\s+em\s+(caixa(?:\s+(?:de\s+)?(?:presente|oferta|gift|kraft|preta|branca|individual|papelão|padrão))?)','i');
        IF v_m[1] IS NOT NULL THEN v_type:='box'; v_text:=v_m[1]; v_gift:=TRUE; END IF;
    END IF;

    IF v_type IS NULL THEN
        v_m := regexp_match(v_desc,'fornecid[oa]s?\s+em\s+(estojo(?:\s+(?:de\s+)?(?:veludo|couro|eva|madeira|plástico|acrílico|metal|bambu))?)','i');
        IF v_m[1] IS NOT NULL THEN v_type:='pouch'; v_text:=v_m[1]; v_gift:=TRUE; END IF;
    END IF;

    IF v_type IS NULL THEN
        v_m := regexp_match(v_desc,'fornecid[oa]s?\s+em\s+((?:bolsa|saco|sacola)(?:\s+(?:de\s+)?(?:tnt|non.?woven|algodão|tecido|papel|veludo|couro))?)','i');
        IF v_m[1] IS NOT NULL THEN v_type:='bag'; v_text:=v_m[1]; v_gift:=TRUE; END IF;
    END IF;

    -- P2: inclui/incluso em X
    IF v_type IS NULL THEN
        v_m := regexp_match(v_desc,'(?:inclus[oa]s?|inclu[ií]dos?|inclui)\s+(?:em\s+)?(caixa(?:\s+(?:de\s+)?(?:presente|oferta|gift|kraft|papelão|preta|branca))?)','i');
        IF v_m[1] IS NOT NULL THEN v_type:='box'; v_text:=v_m[1]; v_gift:=TRUE; END IF;
    END IF;

    IF v_type IS NULL THEN
        v_m := regexp_match(v_desc,'(?:inclus[oa]s?|inclu[ií]dos?|inclui)\s+(?:em\s+)?(estojo(?:\s+\S+)?)','i');
        IF v_m[1] IS NOT NULL THEN v_type:='pouch'; v_text:=v_m[1]; v_gift:=TRUE; END IF;
    END IF;

    -- P3: apresentad[oa]s? em X
    IF v_type IS NULL THEN
        v_m := regexp_match(v_desc,'apresentad[oa]s?\s+em\s+(caixa(?:\s+(?:de\s+)?(?:presente|oferta|gift|kraft))?)','i');
        IF v_m[1] IS NOT NULL THEN v_type:='box'; v_text:=v_m[1]; v_gift:=TRUE; END IF;
    END IF;
    IF v_type IS NULL THEN
        v_m := regexp_match(v_desc,'apresentad[oa]s?\s+em\s+(estojo(?:\s+\S+)?)','i');
        IF v_m[1] IS NOT NULL THEN v_type:='pouch'; v_text:=v_m[1]; v_gift:=TRUE; END IF;
    END IF;

    -- P4: Embalagem: X
    IF v_type IS NULL THEN
        v_m := regexp_match(v_desc,'embalagem[:\s]+(\S+(?:\s+\S+)?)','i');
        IF v_m[1] IS NOT NULL AND v_m[1] !~* 'adequada|para|individual|prot' THEN
            IF v_m[1] ~* '(polybag|poly\s*bag)' THEN v_type:='protective'; v_text:=v_m[1]; v_gift:=FALSE;
            ELSIF v_m[1] ~* '(caixa|box)' THEN v_type:='box'; v_text:=v_m[1]; v_gift:=v_m[1]~*'(presente|oferta|gift)';
            ELSIF v_m[1] ~* '(estojo|case)' THEN v_type:='pouch'; v_text:=v_m[1]; v_gift:=TRUE;
            ELSIF v_m[1] ~* '(bolsa|saco|bag)' THEN v_type:='bag'; v_text:=v_m[1]; v_gift:=v_m[1]!~*'(plástico|polybag)';
            END IF;
        END IF;
    END IF;

    -- P5: "com caixa de X" / "entregue em X" / "com estojo" (sem \b)
    IF v_type IS NULL THEN
        IF v_desc ~* 'com\s+caixa\s+(?:de\s+)?(?:presente|oferta|gift|kraft|papelão|preta|branca|individual)' THEN
            v_m := regexp_match(v_desc,'com\s+caixa\s+(?:de\s+)?((?:presente|oferta|gift|kraft|papelão|preta|branca|individual)(?:\s+\S+)?)','i');
            v_type:='box'; v_text:='caixa '||COALESCE(v_m[1],''); v_gift:=TRUE;
        ELSIF v_desc ~* 'entregue\s+em\s+(?:caixa|estojo|polybag)' THEN
            v_m := regexp_match(v_desc,'entregue\s+em\s+((?:caixa|estojo|polybag)(?:\s+\S+)?)','i');
            IF v_m[1] ~* 'polybag' THEN v_type:='protective'; v_text:=v_m[1]; v_gift:=FALSE;
            ELSIF v_m[1] ~* 'estojo' THEN v_type:='pouch'; v_text:=v_m[1]; v_gift:=TRUE;
            ELSE v_type:='box'; v_text:=v_m[1]; v_gift:=TRUE; END IF;
        ELSIF v_desc ~* 'com\s+estojo' THEN
            v_type:='pouch'; v_text:='estojo'; v_gift:=TRUE;
        END IF;
    END IF;

    -- P6: "embalado individualmente em X"
    IF v_type IS NULL THEN
        v_m := regexp_match(v_desc,'embalad[oa]s?\s+individualmente\s+em\s+((?:polybag|poly\s*bag|caixa|estojo)(?:\s+\S+)?)','i');
        IF v_m[1] IS NOT NULL THEN
            IF v_m[1] ~* 'polybag' THEN v_type:='protective'; v_text:=v_m[1]; v_gift:=FALSE;
            ELSE v_type:='box'; v_text:=v_m[1]; v_gift:=TRUE; END IF;
        END IF;
    END IF;

    IF v_type IS NOT NULL THEN
        RETURN jsonb_build_object('found',TRUE,'packaging_type',v_type,'packaging_text',INITCAP(TRIM(v_text)),'is_gift_packaging',v_gift,'source','description');
    ELSE
        RETURN jsonb_build_object('found',FALSE,'packaging_type',NULL,'packaging_text',NULL,'is_gift_packaging',FALSE,'source','description');
    END IF;
END;
$$;


ALTER FUNCTION "public"."fn_extract_packaging_from_description"("p_description" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_extract_packaging_from_description"("p_description" "text") IS 'Extrai informações de embalagem da descrição do produto.
Procura padrões como "Fornecido em caixa presente", "Inclui estojo", etc.
Retorna: {found, packaging_type (box/pouch/bag), packaging_text, is_gift_packaging, source}';



CREATE OR REPLACE FUNCTION "public"."fn_extract_packaging_info"("p_description" "text", "p_packing" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_refs   text[]; v_refs2 text[]; v_all text[];
  v_included text;
  v_extract JSONB;
BEGIN
  IF p_description IS NULL OR length(trim(p_description)) = 0 THEN
    RETURN jsonb_build_object('optional_refs','[]'::jsonb,'included_mention',NULL,
                              'has_optional_mention',false,'packing_raw',p_packing);
  END IF;

  -- Extrair referências opcionais (padrões existentes mantidos)
  SELECT array_agg(DISTINCT m[1]) INTO v_refs
  FROM regexp_matches(p_description,'(\d{5})\s+vendid[ao]s?\s+opcionalmente','gi') m;

  SELECT array_agg(DISTINCT m[1]) INTO v_refs2
  FROM regexp_matches(p_description,'vendid[ao]s?\s+opcionalmente\s*[:.]?\s*(\d{5})','gi') m;

  v_all := ARRAY(SELECT DISTINCT unnest(COALESCE(v_refs,'{}') || COALESCE(v_refs2,'{}')) ORDER BY 1);
  IF array_length(v_all,1) IS NULL THEN v_all := NULL; END IF;

  -- Usar fn_extract_packaging_from_description (abrangente) para included_mention
  v_extract := fn_extract_packaging_from_description(p_description);
  IF (v_extract->>'found')::boolean = true THEN
    v_included := v_extract->>'packaging_text';
  ELSE
    v_included := NULL;
  END IF;

  RETURN jsonb_build_object(
    'optional_refs', COALESCE(to_jsonb(v_all), '[]'::jsonb),
    'included_mention', v_included,
    'has_optional_mention', (p_description ~* 'vendid[ao]s?\s+opcionalmente'),
    'packing_raw', p_packing
  );
END;
$$;


ALTER FUNCTION "public"."fn_extract_packaging_info"("p_description" "text", "p_packing" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_extract_packaging_info"("p_description" "text", "p_packing" "text") IS 'Extrai informações de embalagem de descrições de fornecedor (camada prata).
 optional_refs: SKUs de embalagens vendidas separadamente (padrão Spot R27).
 included_mention: trecho indicando embalagem original inclusa (ex.: "caixa presente").';



CREATE OR REPLACE FUNCTION "public"."fn_extract_pkg_dims_from_bronze"("p_limit" integer DEFAULT 500) RETURNS TABLE("component_id" "uuid", "component_name" "text", "kit_ref" "text", "raw_id" "uuid", "resultado" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rec  RECORD;
  v_raw  RECORD;
  v_dims JSONB;
  v_raw_id UUID;
  v_pad_id UUID;
  v_ext_l  INTEGER; v_ext_w INTEGER; v_ext_h INTEGER;
  v_unit   TEXT;
BEGIN
  FOR v_rec IN
    SELECT
      pkc.id            AS comp_id,
      pkc.component_name,
      pkc.kit_product_id,
      p.supplier_reference AS kit_ref,
      p.supplier_id,
      s.code            AS supplier_code
    FROM product_kit_components pkc
    JOIN products p ON p.id = pkc.kit_product_id
    JOIN suppliers s ON s.id = p.supplier_id
    WHERE pkc.enrichment_status = 'missing'
      AND pkc.is_packaging = TRUE
      AND s.code IN ('STRICKER','SOMARCAS','ASIA','XBZ')
    LIMIT p_limit
  LOOP
    -- Buscar o raw_data do KIT no bronze
    SELECT raw_data INTO v_raw
    FROM supplier_products_raw spr
    WHERE spr.supplier_id = v_rec.supplier_id
      AND (
        spr.raw_data->>'ProdReference'  = v_rec.kit_ref OR  -- SPOT
        spr.raw_data->>'CodigoAmigavel' = v_rec.kit_ref OR  -- XBZ
        spr.raw_data->>'referencia'     = REPLACE(v_rec.kit_ref, 'ASIA-','') OR -- ASIA
        spr.raw_data->>'codigo'         = v_rec.kit_ref     -- SOMARCAS
      )
    LIMIT 1;

    IF NOT FOUND THEN
      component_id   := v_rec.comp_id;
      component_name := v_rec.component_name;
      kit_ref        := v_rec.kit_ref;
      raw_id         := NULL;
      resultado      := 'no_bronze_match';
      RETURN NEXT;
      CONTINUE;
    END IF;

    -- Extrair dimensões por fornecedor
    v_dims := NULL;
    v_ext_l := NULL; v_ext_w := NULL; v_ext_h := NULL;

    IF v_rec.supplier_code = 'STRICKER' THEN
      -- Box em MM direto
      v_ext_l := NULLIF(ROUND((v_raw.raw_data->>'BoxLengthMM')::NUMERIC * 1000), 0)::INTEGER; -- está em metros!
      v_ext_w := NULLIF(ROUND((v_raw.raw_data->>'BoxWidthMM')::NUMERIC * 1000), 0)::INTEGER;
      v_ext_h := NULLIF(ROUND((v_raw.raw_data->>'BoxHeightMM')::NUMERIC * 1000), 0)::INTEGER;
      v_unit := 'mm_from_spot_bronze';

    ELSIF v_rec.supplier_code IN ('SOMARCAS','ASIA') THEN
      -- Parsear texto "142x142x95 mm (AxLxP)" ou "235x230x93 mm (AxLxP)"
      DECLARE
        v_text TEXT := v_raw.raw_data->>'dimensoes_da_embalagem';
        v_match TEXT[];
      BEGIN
        v_match := REGEXP_MATCH(v_text,
          '(\d+)\s*[xX×]\s*(\d+)\s*[xX×]\s*(\d+)\s*(mm|cm)',
          'i'
        );
        IF v_match IS NOT NULL THEN
          v_unit := v_match[4];
          IF LOWER(v_unit) = 'cm' THEN
            v_ext_l := ROUND(v_match[1]::NUMERIC * 10)::INTEGER;
            v_ext_w := ROUND(v_match[2]::NUMERIC * 10)::INTEGER;
            v_ext_h := ROUND(v_match[3]::NUMERIC * 10)::INTEGER;
          ELSE
            v_ext_l := v_match[1]::INTEGER;
            v_ext_w := v_match[2]::INTEGER;
            v_ext_h := v_match[3]::INTEGER;
          END IF;
          v_unit := 'mm_from_bronze_text';
        END IF;
      END;

    ELSIF v_rec.supplier_code = 'XBZ' THEN
      -- XBZ: Altura/Largura/Profundidade em CM
      v_ext_l := NULLIF(ROUND((v_raw.raw_data->>'Profundidade')::NUMERIC * 10), 0)::INTEGER;
      v_ext_w := NULLIF(ROUND((v_raw.raw_data->>'Largura')::NUMERIC * 10), 0)::INTEGER;
      v_ext_h := NULLIF(ROUND((v_raw.raw_data->>'Altura')::NUMERIC * 10), 0)::INTEGER;
      v_unit := 'mm_from_xbz_bronze_cm';
    END IF;

    IF v_ext_l IS NULL AND v_ext_w IS NULL AND v_ext_h IS NULL THEN
      component_id := v_rec.comp_id; component_name := v_rec.component_name;
      kit_ref := v_rec.kit_ref; raw_id := NULL; resultado := 'no_dims_in_raw';
      RETURN NEXT;
      CONTINUE;
    END IF;

    v_dims := jsonb_build_object(
      'component_name',   v_rec.component_name,
      'is_packaging',     TRUE,
      'unit',             'mm',
      'pkg_ext_length_mm', v_ext_l,
      'pkg_ext_width_mm',  v_ext_w,
      'pkg_ext_height_mm', v_ext_h,
      'source_note',      v_unit,
      'kit_ref',          v_rec.kit_ref
    );

    INSERT INTO kit_component_enrichment_raw (
      kit_product_id, kit_component_id,
      raw_component_name, source, source_ref, source_confidence, raw_data
    ) VALUES (
      v_rec.kit_product_id, v_rec.comp_id,
      v_rec.component_name,
      'supplier_api', v_rec.kit_ref, 0.75,
      v_dims
    ) RETURNING id INTO v_raw_id;

    component_id   := v_rec.comp_id;
    component_name := v_rec.component_name;
    kit_ref        := v_rec.kit_ref;
    raw_id         := v_raw_id;
    resultado      := 'inserted:' || COALESCE(v_ext_l::TEXT,'?') || 'x' || COALESCE(v_ext_w::TEXT,'?') || 'x' || COALESCE(v_ext_h::TEXT,'?') || 'mm';
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_extract_pkg_dims_from_bronze"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_extract_pkg_dims_from_bronze"("p_limit" integer) IS 'Extrai dimensões de embalagem do bronze para componentes is_packaging=TRUE.
   Funciona para Spot (BoxLengthMM em metros), Asia/SóMarcas (texto "AxLxP mm"), XBZ (Altura/Largura cm).
   Insere diretamente em kit_component_enrichment_raw.';



CREATE OR REPLACE FUNCTION "public"."fn_extract_properties_by_supplier"("p_raw_properties" "text", "p_supplier_code" "text" DEFAULT 'spot'::"text") RETURNS TABLE("property_code" "text", "property_value" "text", "raw_value" "text", "matched_pattern" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_prop TEXT;
    v_mapping RECORD;
    v_found BOOLEAN;
BEGIN
    IF p_raw_properties IS NULL OR TRIM(p_raw_properties) = '' THEN
        RETURN;
    END IF;

    -- Para cada property na string
    FOR v_prop IN 
        SELECT TRIM(unnest(string_to_array(p_raw_properties, ',')))
    LOOP
        IF v_prop IS NULL OR TRIM(v_prop) = '' THEN
            CONTINUE;
        END IF;
        
        v_found := FALSE;
        
        -- Buscar mapeamento na tabela (ordenado por prioridade DESC)
        FOR v_mapping IN 
            SELECT spm.property_code, spm.raw_pattern
            FROM supplier_property_mappings spm
            WHERE spm.supplier_code = p_supplier_code
              AND spm.active = TRUE
              AND v_prop ILIKE spm.raw_pattern
            ORDER BY spm.priority DESC
            LIMIT 1
        LOOP
            property_code := v_mapping.property_code;
            property_value := NULL;
            raw_value := v_prop;
            matched_pattern := v_mapping.raw_pattern;
            v_found := TRUE;
            RETURN NEXT;
        END LOOP;
        
        -- Se não encontrou mapeamento, criar código genérico
        IF NOT v_found THEN
            property_code := 'OTHER_' || UPPER(REGEXP_REPLACE(SUBSTRING(v_prop, 1, 30), '[^a-zA-Z0-9]', '_', 'g'));
            property_value := NULL;
            raw_value := v_prop;
            matched_pattern := NULL;
            RETURN NEXT;
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_extract_properties_by_supplier"("p_raw_properties" "text", "p_supplier_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_extract_properties_by_supplier"("p_raw_properties" "text", "p_supplier_code" "text") IS 'Extrai properties usando mapeamentos do fornecedor específico';



CREATE OR REPLACE FUNCTION "public"."fn_extract_properties_from_api"("p_raw_properties" "text", "p_supplier_code" "text" DEFAULT 'spot'::"text") RETURNS TABLE("property_code" "text", "property_value" "text", "raw_value" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF p_raw_properties IS NULL OR TRIM(p_raw_properties) = '' THEN
        RETURN;
    END IF;

    -- Usar a função multi-fornecedor
    RETURN QUERY
    SELECT 
        e.property_code,
        e.property_value,
        e.raw_value
    FROM fn_extract_properties_by_supplier(p_raw_properties, p_supplier_code) e;
END;
$$;


