CREATE OR REPLACE FUNCTION "public"."fn_extract_properties_text_from_raw"("p_raw_data" "jsonb", "p_supplier_code" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE p_supplier_code
    -- SPOT/STRICKER: campo Properties CSV
    WHEN 'spot' THEN
      NULLIF(TRIM(COALESCE(p_raw_data->>'Properties', '')), '')

    -- XBZ: Descricao + Nome (camelCase)
    WHEN 'xbz' THEN
      NULLIF(TRIM(CONCAT_WS(', ',
        NULLIF(TRIM(COALESCE(p_raw_data->>'Nome', '')), ''),
        NULLIF(TRIM(COALESCE(p_raw_data->>'Descricao', '')), '')
      )), '')

    -- ASIA: nome + descricao (lowercase)
    WHEN 'asia' THEN
      NULLIF(TRIM(CONCAT_WS(', ',
        NULLIF(TRIM(COALESCE(p_raw_data->>'nome', '')), ''),
        NULLIF(TRIM(COALESCE(p_raw_data->>'descricao', '')), '')
      )), '')

    -- 88BRINDES: descricao
    WHEN '88brindes' THEN
      NULLIF(TRIM(COALESCE(p_raw_data->>'descricao', '')), '')

    -- Outros: tenta campos comuns
    ELSE
      NULLIF(TRIM(CONCAT_WS(', ',
        NULLIF(TRIM(COALESCE(p_raw_data->>'nome', p_raw_data->>'Nome', '')), ''),
        NULLIF(TRIM(COALESCE(p_raw_data->>'descricao', p_raw_data->>'Descricao', '')), '')
      )), '')
  END;
$$;


ALTER FUNCTION "public"."fn_extract_properties_text_from_raw"("p_raw_data" "jsonb", "p_supplier_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_extract_properties_text_from_raw"("p_raw_data" "jsonb", "p_supplier_code" "text") IS 'Extrai texto de properties do raw Bronze por fornecedor. v1.0 2026-06-11';



CREATE OR REPLACE FUNCTION "public"."fn_extract_weight_from_name"("p_name" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_match TEXT[];
    v_value INTEGER;
BEGIN
    -- Padrão: 500g
    v_match := regexp_match(p_name, '(\d+)\s*(g|gr|gramas)\M', 'i');
    IF v_match IS NOT NULL THEN
        v_value := v_match[1]::INTEGER;
        IF v_value > 0 AND v_value <= 50000 THEN
            RETURN v_value;
        END IF;
    END IF;
    
    -- Padrão: 1.5kg
    v_match := regexp_match(p_name, '(\d+[,.]?\d*)\s*(kg|quilos)', 'i');
    IF v_match IS NOT NULL THEN
        v_value := (REPLACE(v_match[1], ',', '.')::NUMERIC * 1000)::INTEGER;
        IF v_value > 0 AND v_value <= 50000 THEN
            RETURN v_value;
        END IF;
    END IF;
    
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_extract_weight_from_name"("p_name" "text") OWNER TO "postgres";


