COMMENT ON FUNCTION "public"."fn_get_all_leaf_categories"() IS 'Retorna TODAS as categorias-folha (7 574 linhas) da mv_product_leaf_category sem paginação.
 Criada em 2026-06-18 para fix BUG-C: useProductLeafCategories disparava batched GETs
 com URLs > 11 KB + wave queries de categories. Esta função retorna tudo numa única chamada
 que o frontend armazena em cache por toda a sessão (gcTime = Infinity).';



CREATE OR REPLACE FUNCTION "public"."fn_get_asia_api_key"() RETURNS "text"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $$
  SELECT decrypted_secret FROM vault.decrypted_secrets
  WHERE name = 'asia_api_key' LIMIT 1;
$$;


ALTER FUNCTION "public"."fn_get_asia_api_key"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_asia_product_dims_for_kit"("p_kit_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'altura',      (spr.raw_data->'atributos'->>'altura'),
    'largura',     (spr.raw_data->'atributos'->>'largura'),
    'comprimento', (spr.raw_data->'atributos'->>'comprimento'),
    'peso',        (spr.raw_data->'atributos'->>'peso_produto'),
    'ref',         spr.supplier_reference
  )
  FROM supplier_products_raw spr
  JOIN suppliers s ON s.id = spr.supplier_id AND s.code = 'ASIA'
  WHERE spr.product_id = p_kit_product_id
    AND spr.raw_data->'atributos' IS NOT NULL
  LIMIT 1;
$$;


ALTER FUNCTION "public"."fn_get_asia_product_dims_for_kit"("p_kit_product_id" "uuid") OWNER TO "postgres";


