CREATE OR REPLACE FUNCTION "public"."fn_get_discontinued_products"("p_supplier_code" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT 'stock_zero'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rows    jsonb;
  v_total   int;
  v_limit   int  := GREATEST(0, LEAST(COALESCE(p_limit, 50), 500));
  v_offset  int  := GREATEST(0, COALESCE(p_offset, 0));
  v_status  text := COALESCE(p_status, 'stock_zero');
  v_suppliers uuid[] := ARRAY[
    'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'::uuid,
    'd6718a29-e954-4c1b-bd84-03ea24884900'::uuid,
    'd2734e23-d633-4819-bb15-e51aa44e2118'::uuid,
    '841cd690-210a-422a-908c-7676828db272'::uuid
  ];
BEGIN
  SELECT COUNT(*) INTO v_total
  FROM products p JOIN suppliers s ON s.id = p.supplier_id
  WHERE p.supplier_id = ANY(v_suppliers)
    AND p.is_active = true
    AND (v_status = 'has_request' OR p.stock_quantity = 0)
    AND (p_supplier_code IS NULL OR s.code = p_supplier_code)
    AND (p_search IS NULL OR
         p.name ILIKE '%' || p_search || '%' OR
         p.supplier_reference ILIKE '%' || p_search || '%')
    AND (v_status NOT IN ('has_request') OR EXISTS (
      SELECT 1 FROM product_deactivation_requests pdr
      WHERE pdr.product_id = p.id AND pdr.status = 'pending'
    ));

  SELECT jsonb_agg(row)
  INTO v_rows
  FROM (
    SELECT jsonb_build_object(
      'id',                 p.id,
      'supplier_code',      s.code,
      'supplier_name',      s.name,
      'supplier_reference', p.supplier_reference,
      'name',               p.name,
      'sku',                p.sku,
      'stock_quantity',     p.stock_quantity,
      'is_stockout',        p.is_stockout,
      'is_active',          p.is_active,
      'sale_price',         p.sale_price,
      'cost_price',         p.cost_price,
      'primary_image_url',  p.primary_image_url,
      'last_sync_at',       p.last_sync_at,
      'updated_at',         p.updated_at,
      'stock_zero_since',   p.updated_at,
      'deactivation_request', (
        SELECT jsonb_build_object(
          'id',           pdr.id,
          'status',       pdr.status,
          'reason',       pdr.reason,
          'reason_code',  pdr.reason_code,
          'requested_by', pdr.requested_by_name,
          'requested_at', pdr.requested_at,
          'approved_by',  pdr.approved_by_name,
          'approved_at',  pdr.approved_at
        )
        FROM product_deactivation_requests pdr
        WHERE pdr.product_id = p.id ORDER BY pdr.requested_at DESC LIMIT 1
      ),
      'variants_ativas',     (SELECT COUNT(*) FROM product_variants pv WHERE pv.product_id=p.id AND pv.is_active=true),
      'variants_com_estoque',(SELECT COUNT(*) FROM product_variants pv WHERE pv.product_id=p.id AND pv.is_active=true AND pv.stock_quantity>0)
    ) AS row
    FROM products p JOIN suppliers s ON s.id = p.supplier_id
    WHERE p.supplier_id = ANY(v_suppliers)
      AND p.is_active = true
      AND (v_status = 'has_request' OR p.stock_quantity = 0)
      AND (p_supplier_code IS NULL OR s.code = p_supplier_code)
      AND (p_search IS NULL OR
           p.name ILIKE '%' || p_search || '%' OR
           p.supplier_reference ILIKE '%' || p_search || '%')
      AND (v_status NOT IN ('has_request') OR EXISTS (
        SELECT 1 FROM product_deactivation_requests pdr
        WHERE pdr.product_id = p.id AND pdr.status = 'pending'
      ))
    ORDER BY p.updated_at DESC, p.id   -- ← TIE-BREAKER ADICIONADO
    LIMIT v_limit OFFSET v_offset
  ) sub;

  RETURN jsonb_build_object(
    'total',   v_total,
    'limit',   v_limit,
    'offset',  v_offset,
    'items',   COALESCE(v_rows, '[]')
  );
END;
$$;


ALTER FUNCTION "public"."fn_get_discontinued_products"("p_supplier_code" "text", "p_search" "text", "p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_discontinued_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_por_forn jsonb;
  v_totals   jsonb;
BEGIN
  -- Stats por fornecedor
  SELECT jsonb_agg(row ORDER BY row->>'supplier_code')
  INTO v_por_forn
  FROM (
    SELECT jsonb_build_object(
      'supplier_code',  s.code,
      'supplier_name',  s.name,
      'supplier_id',    p.supplier_id::text,
      'total_ativos',   COUNT(*) FILTER (WHERE p.is_active = true),
      'stock_zero',     COUNT(*) FILTER (WHERE p.stock_quantity = 0 AND p.is_active = true),
      'inativos',       COUNT(*) FILTER (WHERE p.is_active = false),
      'pendentes',      COUNT(*) FILTER (WHERE EXISTS (
                          SELECT 1 FROM product_deactivation_requests pdr
                          WHERE pdr.product_id=p.id AND pdr.status='pending'
                        ))
    ) AS row
    FROM products p
    JOIN suppliers s ON s.id = p.supplier_id
    WHERE p.supplier_id IN (
      'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0',
      'd6718a29-e954-4c1b-bd84-03ea24884900',
      'd2734e23-d633-4819-bb15-e51aa44e2118',
      '841cd690-210a-422a-908c-7676828db272'
    )
    GROUP BY s.code, s.name, p.supplier_id
  ) sub;

  -- Totais globais
  SELECT jsonb_build_object(
    'total_stock_zero',     SUM(CASE WHEN p.stock_quantity = 0 AND p.is_active = true  THEN 1 ELSE 0 END),
    'total_inativos',       SUM(CASE WHEN p.is_active = false THEN 1 ELSE 0 END),
    'total_ativos',         SUM(CASE WHEN p.is_active = true  THEN 1 ELSE 0 END),
    'pendentes_aprovacao',  (SELECT COUNT(*) FROM product_deactivation_requests WHERE status='pending')
  ) INTO v_totals
  FROM products p
  WHERE p.supplier_id IN (
    'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0',
    'd6718a29-e954-4c1b-bd84-03ea24884900',
    'd2734e23-d633-4819-bb15-e51aa44e2118',
    '841cd690-210a-422a-908c-7676828db272'
  );

  RETURN v_totals || jsonb_build_object('por_fornecedor', COALESCE(v_por_forn, '[]'));
END;
$$;


ALTER FUNCTION "public"."fn_get_discontinued_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_image_upload_queue"("p_supplier" "text", "p_limit" integer DEFAULT 25) RETURNS TABLE("id" "uuid", "product_id" "uuid", "url_original" "text", "url_cdn" "text", "image_type" "text", "is_primary" boolean, "color_id" "uuid", "display_order" integer, "cloudflare_image_id" character varying)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    pi.id, pi.product_id,
    COALESCE(pi.url_original, pi.url_cdn) AS url_original,
    pi.url_cdn, pi.image_type, pi.is_primary,
    pi.color_id, pi.display_order, pi.cloudflare_image_id
  FROM product_images pi
  WHERE pi.source_supplier = p_supplier
    AND pi.url_cdn NOT LIKE 'https://imagedelivery.net%'
    AND pi.is_active = true
  ORDER BY pi.created_at ASC
  LIMIT p_limit;
$$;


