Campos de classificação: image_type | color_id | is_primary | display_order.
Nunca derivar tipo/cor/prioridade a partir do CF Image ID.';



CREATE OR REPLACE FUNCTION "public"."fn_get_low_stock_alerts"("p_limit" integer DEFAULT 50, "p_since" "date" DEFAULT NULL::"date") RETURNS TABLE("product_id" "uuid", "product_name" "text", "product_sku" "text", "image_url" "text", "stock_quantity" integer, "supplier_id" "uuid", "supplier_name" "text", "low_stock_threshold" integer, "last_stock_update_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT p.id, p.name::text, p.sku::text, p.primary_image_url::text, p.stock_quantity,
         p.supplier_id, s.name::text, COALESCE(s.low_stock_threshold,10), p.last_stock_update_at
  FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
  WHERE p.is_active=true AND p.is_stockout=false
    AND p.stock_quantity>0 AND p.stock_quantity <= COALESCE(s.low_stock_threshold,10)
    AND (p_since IS NULL OR p.last_stock_update_at >= p_since::timestamptz)
  ORDER BY p.stock_quantity ASC, p.id
  LIMIT GREATEST(p_limit,0);
$$;


ALTER FUNCTION "public"."fn_get_low_stock_alerts"("p_limit" integer, "p_since" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_navigation_patterns"("p_user_id" "uuid" DEFAULT NULL::"uuid", "p_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_since   timestamptz;
  v_result  jsonb;
BEGIN
  IF p_user_id IS NOT NULL
     AND p_user_id != auth.uid()
     AND NOT is_manager_or_admin()
  THEN
    RETURN jsonb_build_object('error','Acesso negado');
  END IF;

  p_days  := GREATEST(1, LEAST(COALESCE(p_days, 30), 999));
  v_since := NOW() - (p_days || ' days')::interval;

  WITH nav_events AS (
    SELECT
      event_type,
      event_data->>'source_path'      AS source_path,
      event_data->>'destination_path' AS destination_path,
      event_data->>'button_name'      AS button_name,
      created_at
    FROM public.navigation_analytics
    WHERE created_at >= v_since
      AND (p_user_id IS NULL OR user_id = p_user_id)
  ),
  -- Páginas de origem mais comuns
  top_sources AS (
    SELECT source_path, COUNT(*) AS hits
    FROM nav_events
    WHERE source_path IS NOT NULL
    GROUP BY source_path
    ORDER BY hits DESC
    LIMIT 10
  ),
  -- Botões mais clicados
  top_buttons AS (
    SELECT button_name, COUNT(*) AS hits
    FROM nav_events
    WHERE button_name IS NOT NULL
    GROUP BY button_name
    ORDER BY hits DESC
    LIMIT 10
  ),
  -- Saídas de páginas de produto (product bounce)
  product_bounces AS (
    SELECT
      COUNT(*) FILTER (WHERE source_path LIKE '/produto/%') AS saidas_de_produto,
      COUNT(*) FILTER (WHERE source_path LIKE '/produto/%'
                         AND destination_path = '/') AS retorno_para_home,
      COUNT(*) FILTER (WHERE source_path = '/orcamentos/novo') AS saidas_de_orcamento
    FROM nav_events
  )
  SELECT jsonb_build_object(
    'period_days',   p_days,
    'generated_at',  NOW(),
    'total_events',  (SELECT COUNT(*) FROM nav_events),
    'top_sources',   (SELECT jsonb_agg(jsonb_build_object('path', source_path, 'hits', hits) ORDER BY hits DESC) FROM top_sources),
    'top_buttons',   (SELECT jsonb_agg(jsonb_build_object('button', button_name, 'hits', hits) ORDER BY hits DESC) FROM top_buttons),
    'product_navigation', jsonb_build_object(
      'exits_from_product_pages',  (SELECT saidas_de_produto FROM product_bounces),
      'returned_to_home',          (SELECT retorno_para_home FROM product_bounces),
      'exits_from_quote_creation', (SELECT saidas_de_orcamento FROM product_bounces)
    )
  ) INTO v_result;

  RETURN v_result;

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."fn_get_navigation_patterns"("p_user_id" "uuid", "p_days" integer) OWNER TO "postgres";


