CREATE OR REPLACE FUNCTION "public"."fn_get_novelty_alerts"("p_limit" integer DEFAULT 30, "p_since" "date" DEFAULT NULL::"date") RETURNS TABLE("product_id" "uuid", "product_name" "text", "product_sku" "text", "image_url" "text", "stock_quantity" integer, "supplier_id" "uuid", "supplier_name" "text", "detected_at" timestamp with time zone, "days_remaining" integer, "is_highlighted" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH dedup AS (
    SELECT DISTINCT ON (pn.product_id)
           pn.product_id, p.name::text, p.sku::text, p.primary_image_url::text, p.stock_quantity,
           p.supplier_id, s.name::text, pn.detected_at,
           EXTRACT(DAY FROM (pn.expires_at - now()))::int, pn.is_highlighted
    FROM product_novelties pn
    JOIN products p ON p.id=pn.product_id
    LEFT JOIN suppliers s ON s.id=p.supplier_id
    WHERE pn.is_active=true AND (pn.expires_at IS NULL OR pn.expires_at>now())
      AND p.is_active=true AND p.is_stockout=false
      AND p.sale_price IS NOT NULL AND p.sale_price>0
      AND p.primary_image_url IS NOT NULL AND p.primary_image_url<>''
      AND (p_since IS NULL OR pn.detected_at >= p_since::timestamptz)
    ORDER BY pn.product_id, pn.detected_at DESC
  )
  SELECT * FROM dedup ORDER BY detected_at DESC, product_id
  LIMIT GREATEST(p_limit,0);
$$;


ALTER FUNCTION "public"."fn_get_novelty_alerts"("p_limit" integer, "p_since" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_price_by_quantity"("p_variant_id" "uuid", "p_quantity" integer DEFAULT 1, "p_price_list_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_cost NUMERIC;
    v_markup NUMERIC := 115.0;
    v_tier INTEGER := 1;
    v_result JSONB;
    v_vss RECORD;
BEGIN
    -- Buscar dados da variante
    SELECT 
        vss.*,
        s.default_markup_percent
    INTO v_vss
    FROM variant_supplier_sources vss
    LEFT JOIN suppliers s ON s.id = vss.supplier_id
    WHERE vss.variant_id = p_variant_id
      AND vss.is_preferred = true
    LIMIT 1;
    
    IF v_vss IS NULL THEN
        RETURN jsonb_build_object('error', 'Variante não encontrada');
    END IF;
    
    -- Determinar faixa e custo
    IF p_quantity >= COALESCE(v_vss.min_qty_5, 999999) AND v_vss.cost_price_5 IS NOT NULL THEN
        v_cost := v_vss.cost_price_5;
        v_tier := 5;
    ELSIF p_quantity >= COALESCE(v_vss.min_qty_4, 999999) AND v_vss.cost_price_4 IS NOT NULL THEN
        v_cost := v_vss.cost_price_4;
        v_tier := 4;
    ELSIF p_quantity >= COALESCE(v_vss.min_qty_3, 999999) AND v_vss.cost_price_3 IS NOT NULL THEN
        v_cost := v_vss.cost_price_3;
        v_tier := 3;
    ELSIF p_quantity >= COALESCE(v_vss.min_qty_2, 999999) AND v_vss.cost_price_2 IS NOT NULL THEN
        v_cost := v_vss.cost_price_2;
        v_tier := 2;
    ELSE
        v_cost := COALESCE(v_vss.cost_price_1, v_vss.cost_price);
        v_tier := 1;
    END IF;
    
    -- Obter markup
    IF p_price_list_id IS NOT NULL THEN
        SELECT base_markup_percent INTO v_markup
        FROM price_lists WHERE id = p_price_list_id;
    ELSE
        v_markup := COALESCE(v_vss.default_markup_percent, 115.0);
    END IF;
    
    -- Retornar resultado
    RETURN jsonb_build_object(
        'variant_id', p_variant_id,
        'quantity', p_quantity,
        'tier', v_tier,
        'cost_price', v_cost,
        'markup_percent', v_markup,
        'sale_price', ROUND(v_cost * (1 + v_markup / 100), 2),
        'unit_price', ROUND(v_cost * (1 + v_markup / 100), 2),
        'total_price', ROUND(v_cost * (1 + v_markup / 100) * p_quantity, 2),
        'price_tiers', jsonb_build_object(
            'tier_1', jsonb_build_object('min_qty', COALESCE(v_vss.min_qty_1, 1), 'cost', v_vss.cost_price_1),
            'tier_2', jsonb_build_object('min_qty', v_vss.min_qty_2, 'cost', v_vss.cost_price_2),
            'tier_3', jsonb_build_object('min_qty', v_vss.min_qty_3, 'cost', v_vss.cost_price_3),
            'tier_4', jsonb_build_object('min_qty', v_vss.min_qty_4, 'cost', v_vss.cost_price_4),
            'tier_5', jsonb_build_object('min_qty', v_vss.min_qty_5, 'cost', v_vss.cost_price_5)
        )
    );
END;
$$;


ALTER FUNCTION "public"."fn_get_price_by_quantity"("p_variant_id" "uuid", "p_quantity" integer, "p_price_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_product_accessories"("p_product_id" "uuid") RETURNS TABLE("accessory_category_id" "uuid", "accessory_category_name" "text", "relationship_type" character varying, "display_label" character varying, "is_required" boolean)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT
        c_acc.id,
        c_acc.name::TEXT,
        cac.relationship_type,
        cac.display_label,
        cac.is_required
    FROM products p
    JOIN category_accessory_categories cac ON cac.category_id = p.category_id AND cac.is_active = TRUE
    JOIN categories c_acc ON c_acc.id = cac.accessory_category_id
    WHERE p.id = p_product_id
    
    UNION
    
    -- Incluir subcategorias se include_children = TRUE
    SELECT DISTINCT
        c_child.id,
        c_child.name::TEXT,
        cac.relationship_type,
        cac.display_label,
        cac.is_required
    FROM products p
    JOIN category_accessory_categories cac ON cac.category_id = p.category_id 
        AND cac.is_active = TRUE 
        AND cac.include_children = TRUE
    JOIN categories c_child ON c_child.parent_id = cac.accessory_category_id AND c_child.is_active = TRUE
    WHERE p.id = p_product_id
    
    ORDER BY display_label, accessory_category_name;
END;
$$;


ALTER FUNCTION "public"."fn_get_product_accessories"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_get_product_accessories"("p_product_id" "uuid") IS 'Retorna as categorias de acessórios disponíveis para um produto específico.';



CREATE OR REPLACE FUNCTION "public"."fn_get_product_ai_context"("p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier_code    TEXT;
  v_supplier_id      UUID;
  v_name             TEXT;
  v_description      TEXT;
  v_short_desc       TEXT;
  v_brand            TEXT;
  v_supplier_ref     TEXT;
  v_sku              TEXT;
  v_primary_img      TEXT;
  v_allows_pers      BOOLEAN;
  v_gold_materials   JSONB;
  v_gold_colors      JSONB;
  v_gold_weight      INT;
  v_gold_combined    TEXT;
  v_gold_capacity    INT;
  v_gold_capacities  TEXT;
  v_gold_engraving   TEXT;
  v_gold_type        TEXT;
  v_gold_subtype     TEXT;
  v_gold_min_qty     INT;
  v_gold_category_id UUID;
  v_raw              JSONB;
  v_materials        TEXT[];
  v_colors           TEXT[];
  v_weight_out       INT;
  v_dimensions       TEXT;
  v_capacity_out     TEXT;
  v_cat_type         TEXT;
  v_cat_subtype      TEXT;
  v_engraving_type   TEXT;
  v_engraving_areas  TEXT[];
  v_components       TEXT[];
  v_certificates     TEXT[];
  v_min_quantity     INT;
  v_packaging        TEXT;
  v_og_image_url     TEXT;
  v_extras           JSONB := '{}';
BEGIN
  SELECT p.supplier_id, p.name, p.description, p.short_description, p.brand,
         p.supplier_reference, p.sku, p.primary_image_url, p.allows_personalization,
         p.materials, p.colors, p.weight_g, p.combined_sizes, p.capacity_ml,
         p.capacities, p.engraving_type, p.supplier_type, p.supplier_subtype,
         p.min_order_quantity, p.category_id
  INTO v_supplier_id, v_name, v_description, v_short_desc, v_brand,
       v_supplier_ref, v_sku, v_primary_img, v_allows_pers,
       v_gold_materials, v_gold_colors, v_gold_weight, v_gold_combined,
       v_gold_capacity, v_gold_capacities, v_gold_engraving,
       v_gold_type, v_gold_subtype, v_gold_min_qty, v_gold_category_id
  FROM products p
  WHERE p.id = p_product_id AND p.is_active = true AND p.is_deleted = false;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','product_not_found','product_id',p_product_id);
  END IF;

  SELECT code INTO v_supplier_code FROM suppliers WHERE id = v_supplier_id;

  SELECT spr.raw_data INTO v_raw
  FROM supplier_products_raw spr
  WHERE spr.supplier_id = v_supplier_id
    AND spr.raw_data IS NOT NULL
    AND (spr.product_id = p_product_id
         OR (v_supplier_ref IS NOT NULL AND spr.supplier_sku LIKE v_supplier_ref || '%'))
  ORDER BY CASE WHEN spr.product_id = p_product_id THEN 0 ELSE 1 END, spr.updated_at DESC
  LIMIT 1;

  CASE v_supplier_code

  WHEN 'STRICKER' THEN
    v_name        := COALESCE(v_raw->>'Name', v_name);
    v_description := COALESCE(v_raw->>'Description', v_raw->>'ShortDescription', v_description);
    v_short_desc  := COALESCE(v_raw->>'ShortDescription', v_short_desc);
    v_brand       := COALESCE(v_raw->>'Brand', v_brand);
    IF v_raw->>'Materials' IS NOT NULL AND v_raw->>'Materials' <> '' THEN
      SELECT array_agg(trim(x)) INTO v_materials FROM unnest(string_to_array(v_raw->>'Materials', ',')) AS x;
    ELSE
      SELECT array_agg(x) INTO v_materials FROM jsonb_array_elements_text(COALESCE(v_gold_materials,'[]')) x;
    END IF;
    SELECT array_agg(x) INTO v_colors
    FROM unnest(ARRAY[NULLIF(v_raw->>'ColorDesc1',''), NULLIF(v_raw->>'ColorDesc2','')]) AS x WHERE x IS NOT NULL;
    v_weight_out   := v_gold_weight;
    v_dimensions   := COALESCE(v_gold_combined, v_raw->>'CombinedSizes');
    v_capacity_out := COALESCE(v_gold_capacities, NULLIF(v_raw->>'Capacity',''));
    v_cat_type     := COALESCE(v_gold_type,    v_raw->>'Type');
    v_cat_subtype  := COALESCE(v_gold_subtype, v_raw->>'SubType');
    v_engraving_type := NULLIF(v_raw->>'CustomizationTypes','');
    SELECT array_agg(a) INTO v_engraving_areas
    FROM unnest(ARRAY[v_raw->>'Area1',v_raw->>'Area2',v_raw->>'Area3',v_raw->>'Area4',
                      v_raw->>'Area5',v_raw->>'Area6',v_raw->>'Area7',v_raw->>'Area8']) AS a
    WHERE a IS NOT NULL AND a <> '';
    SELECT array_agg(DISTINCT c) INTO v_components
    FROM unnest(ARRAY[v_raw->>'Component1',v_raw->>'Component2',v_raw->>'Component3',v_raw->>'Component4']) AS c
    WHERE c IS NOT NULL AND c <> '';
    IF v_raw->>'Certificates' IS NOT NULL AND v_raw->>'Certificates' <> '' THEN
      SELECT array_agg(trim(x)) INTO v_certificates FROM unnest(string_to_array(v_raw->>'Certificates',',')) AS x;
    END IF;
    v_min_quantity := COALESCE(v_gold_min_qty, (v_raw->>'MinQt1')::INT);
    v_packaging    := NULLIF(COALESCE(v_raw->>'Packing','') ||
      CASE WHEN NULLIF(v_raw->>'Repacking','') IS NOT NULL THEN ' / '||(v_raw->>'Repacking') ELSE '' END,'');
    v_og_image_url := v_primary_img;
    v_extras := jsonb_build_object(
      'videolink', NULLIF(v_raw->>'VideoLink',''),
      'video_vimeo', NULLIF(v_raw->>'VideoLinkVimeo',''),
      'is_stockout', (v_raw->>'IsStockOut')::BOOLEAN,
      'pvc_free', (v_raw->>'PvcFree')::BOOLEAN,
      'default_customization', NULLIF(v_raw->>'DefaultCustomization',''),
      'location1', NULLIF(v_raw->>'Location1',''),
      'table_codes', NULLIF(v_raw->>'CustomizationTables',''));

  WHEN 'XBZ' THEN
    v_name        := COALESCE(v_raw->>'Nome', v_name);
    v_description := COALESCE(v_raw->>'Descricao', v_description);
    v_brand       := 'XBZ Brindes';
    SELECT array_agg(x) INTO v_materials FROM jsonb_array_elements_text(COALESCE(v_gold_materials,'[]')) x;
    SELECT array_agg(DISTINCT c) INTO v_colors
    FROM unnest(ARRAY[NULLIF(v_raw->>'CorWebPrincipal',''),
      CASE WHEN NULLIF(v_raw->>'CorWebSecundaria','') IS DISTINCT FROM NULLIF(v_raw->>'CorWebPrincipal','')
           THEN NULLIF(v_raw->>'CorWebSecundaria','') ELSE NULL END]) AS c WHERE c IS NOT NULL;
    v_weight_out   := v_gold_weight;
    v_dimensions   := v_gold_combined;
    v_capacity_out := v_gold_capacities;
    v_cat_type     := COALESCE(v_gold_type,    NULLIF(v_raw->>'WebTipo',''));
    v_cat_subtype  := COALESCE(v_gold_subtype, NULLIF(v_raw->>'WebSubTipo',''));
    v_engraving_type  := v_gold_engraving;
    IF v_gold_engraving IS NOT NULL THEN v_engraving_areas := ARRAY[v_gold_engraving]; END IF;
    v_min_quantity := COALESCE(v_gold_min_qty, (v_raw->>'VendaMinima')::INT);
    v_og_image_url := v_primary_img;
    v_extras := jsonb_build_object(
      'codigo_xbz', v_raw->>'CodigoXbz', 'site_link', v_raw->>'SiteLink',
      'disponivel', v_raw->>'Disponivel', 'ponta_estoque', (v_raw->>'PontaDeEstoque')::BOOLEAN,
      'preco_venda', (v_raw->>'PrecoVenda')::NUMERIC);

  WHEN 'ASIA' THEN
    v_name        := COALESCE(v_raw->>'nome', v_name);
    v_brand       := 'Asia Import';
    SELECT array_agg(x) INTO v_materials FROM jsonb_array_elements_text(COALESCE(v_gold_materials,'[]')) x;
    SELECT array_agg(DISTINCT c) INTO v_colors
    FROM unnest(ARRAY[NULLIF(v_raw->>'var_cor_nome',''), NULLIF(v_raw->'atributos'->'cor'->>'value','')]) AS c
    WHERE c IS NOT NULL;
    IF v_colors IS NULL THEN
      SELECT array_agg(x) INTO v_colors FROM jsonb_array_elements_text(COALESCE(v_gold_colors,'[]')) x;
    END IF;
    v_weight_out   := v_gold_weight;
    v_dimensions   := v_gold_combined;
    v_capacity_out := COALESCE(v_raw->'atributos'->'volume-litros'->>'value', v_gold_capacities);
    v_cat_type     := v_gold_type;
    v_cat_subtype  := v_gold_subtype;
    v_min_quantity := v_gold_min_qty;
    IF v_primary_img LIKE '%imagedelivery.net%' THEN
      v_og_image_url := v_primary_img;
    ELSIF v_supplier_ref IS NOT NULL THEN
      v_og_image_url := 'https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/asia-'
                        || lower(v_supplier_ref) || '-01/public';
    ELSE
      v_og_image_url := v_primary_img;
    END IF;
    v_extras := jsonb_build_object(
      'referencia', v_raw->>'referencia', 'var_referencia', v_raw->>'var_referencia',
      'preco', v_raw->>'preco', 'atributos', v_raw->'atributos', 'var_cor_hex', v_raw->>'var_cor_hex');

  WHEN 'SOMARCAS' THEN
    v_name        := COALESCE(v_raw->>'titulo',   v_name);
    v_description := COALESCE(v_raw->>'descricao', v_description);
    v_brand       := 'Só Marcas';
    SELECT array_agg(x) INTO v_materials FROM jsonb_array_elements_text(COALESCE(v_gold_materials,'[]')) x;
    SELECT array_agg(x) INTO v_colors    FROM jsonb_array_elements_text(COALESCE(v_gold_colors,'[]')) x;
    v_weight_out := COALESCE(v_gold_weight,
      CASE WHEN v_raw->>'peso_da_embalagem' ~ '^\d+'
           THEN (regexp_match(v_raw->>'peso_da_embalagem','^\d+'))[1]::INT ELSE NULL END);
    v_dimensions   := COALESCE(v_gold_combined, v_raw->>'dimensoes_do_produto');
    v_capacity_out := v_gold_capacities;
    v_cat_type  := COALESCE(v_gold_type,    NULLIF(split_part(COALESCE(v_raw->>'matriz_de_categorias',''),'|',1),''));
    v_cat_subtype:= COALESCE(v_gold_subtype, NULLIF(split_part(COALESCE(v_raw->>'matriz_de_categorias',''),'|',2),''));
    v_engraving_type := COALESCE(NULLIF(v_raw->>'tipo_gravacao',''), v_gold_engraving);
    v_packaging      := NULLIF(v_raw->>'embalagem_do_produto','');
    IF v_raw->>'garantia_do_produto' IS NOT NULL THEN
      v_certificates := ARRAY[v_raw->>'garantia_do_produto'];
    END IF;
    v_min_quantity := COALESCE(v_gold_min_qty, (v_raw->>'quantidade_minima_sugerida')::INT);
    v_og_image_url := COALESCE(
      CASE WHEN v_primary_img LIKE '%imagedelivery.net%' THEN v_primary_img ELSE NULL END,
      NULLIF(v_raw->>'url_foto',''), v_primary_img);
    v_extras := jsonb_build_object(
      'codigo', v_raw->>'codigo', 'garantia', v_raw->>'garantia_do_produto',
      'preco_gravacao', (v_raw->>'preco_com_gravacao_com_impostos')::NUMERIC,
      'preco_sem_gravacao', (v_raw->>'preco_sem_gravacao_com_impostos')::NUMERIC,
      'qtd_calculo_preco', (v_raw->>'quantidade_calculo_preco')::INT,
      'fotos_adicionais', v_raw->>'matriz_de_fotos_adicionais');

  ELSE
    SELECT array_agg(x) INTO v_materials FROM jsonb_array_elements_text(COALESCE(v_gold_materials,'[]')) x;
    SELECT array_agg(x) INTO v_colors    FROM jsonb_array_elements_text(COALESCE(v_gold_colors,'[]')) x;
    v_weight_out     := v_gold_weight;
    v_dimensions     := v_gold_combined;
    v_cat_type       := v_gold_type;
    v_cat_subtype    := v_gold_subtype;
    v_engraving_type := v_gold_engraving;
    v_og_image_url   := v_primary_img;
    v_extras         := COALESCE(v_raw,'{}');

  END CASE;

  RETURN jsonb_build_object(
    'product_id',       p_product_id,
    'supplier_code',    v_supplier_code,
    'sku',              v_sku,
    'supplier_reference', v_supplier_ref,
    'name',             v_name,
    'description',      v_description,
    'short_description', v_short_desc,
    'brand',            v_brand,
    'materials',        to_jsonb(COALESCE(v_materials,'{}'::TEXT[])),
    'colors',           to_jsonb(COALESCE(v_colors,'{}'::TEXT[])),
    'weight_g',         v_weight_out,
    'dimensions_display', v_dimensions,
    'capacity',         v_capacity_out,
    'category_type',    v_cat_type,
    'category_subtype', v_cat_subtype,
    'category_id',      v_gold_category_id,
    'allows_personalization', v_allows_pers,
    'engraving_type',   v_engraving_type,
    'engraving_areas',  to_jsonb(COALESCE(v_engraving_areas,'{}'::TEXT[])),
    'components',       to_jsonb(COALESCE(v_components,'{}'::TEXT[])),
    'certificates',     to_jsonb(COALESCE(v_certificates,'{}'::TEXT[])),
    'min_quantity',     v_min_quantity,
    'packaging_info',   v_packaging,
    'og_image_url',     v_og_image_url,
    'extras',           v_extras
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM, 'supplier_code', v_supplier_code, 'product_id', p_product_id);
END;
$$;


ALTER FUNCTION "public"."fn_get_product_ai_context"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_get_product_ai_context"("p_product_id" "uuid") IS 'Contexto canônico normalizado (Gold + Bronze raw_data) para geração de descrições por IA. Cobre: STRICKER, XBZ, ASIA, SOMARCAS + fallback. Gold-layer enrichment — somente leitura.';



CREATE OR REPLACE FUNCTION "public"."fn_get_product_customization_options"("p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'product_id', p_product_id,
    'locations', COALESCE(jsonb_agg(loc_data ORDER BY loc_order), '[]'::jsonb)
  )
  INTO v_result
  FROM (
    SELECT
      pat.location_code,
      pat.location_name,
      pat.location_order AS loc_order,
      jsonb_build_object(
        'location_code',  pat.location_code,
        'location_name',  pat.location_name,
        'location_order', pat.location_order,
        'options', (
          SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
              'technique_id',       p2.id,
              'grupo_tecnica',      t.grupo_tecnica,
              'tecnica_nome',       t.nome,
              'variacao_label',     t.nome,
              'codigo_tabela',      t.codigo_tabela,
              'cobra_por_cor',      t.cobra_por_cor,
              'max_cores',          COALESCE(t.max_cores, 1),
              'custo_setup',        COALESCE(t.custo_setup, 0),
              'max_width',          p2.max_width,
              'max_height',         p2.max_height,
              'gravacao_largura_max', p2.max_width,
              'gravacao_altura_max',  p2.max_height,
              'is_curved',          p2.is_curved,
              'shape',              p2.shape,
              'usa_dimensao',       COALESCE(t.usa_faixa_dimensional, false),
              'efetiva_largura_max', p2.max_width,
              'efetiva_altura_max',  p2.max_height,
              -- NOVO: dimensões mínimas das faixas (crítico para validação frontend)
              'min_width', (
                SELECT MIN(f.largura_min)
                FROM tabela_preco_gravacao_oficial_faixa f
                WHERE f.tabela_preco_gravacao_id = t.id
                  AND f.largura_min IS NOT NULL
              ),
              'min_height', (
                SELECT MIN(f.altura_min)
                FROM tabela_preco_gravacao_oficial_faixa f
                WHERE f.tabela_preco_gravacao_id = t.id
                  AND f.altura_min IS NOT NULL
              ),
              -- NOVO: markup e preço mínimo para estimativa frontend
              'markup_percent',        COALESCE(t.markup_percent, 115),
              'preco_minimo_unitario', COALESCE(t.preco_minimo_unitario, 0)
            )
          ORDER BY t.grupo_tecnica, t.codigo_tabela), '[]'::jsonb)
          FROM print_area_techniques p2
          JOIN tabela_preco_gravacao_oficial t ON t.id = p2.tabela_preco_id
          WHERE p2.product_id = p_product_id
            AND p2.location_code = pat.location_code
            AND p2.is_active = true
            AND t.ativo = true
        )
      ) AS loc_data
    FROM (
      SELECT DISTINCT location_code, location_name, location_order
      FROM print_area_techniques
      WHERE product_id = p_product_id AND is_active = true
    ) pat
    ORDER BY pat.location_order
  ) sub;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_get_product_customization_options"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_product_dates"("p_product_id" "uuid") RETURNS TABLE("date_id" "uuid", "date_name" "text", "date_day" integer, "date_month" integer, "target_audience" "text", "is_featured" boolean, "source" character varying)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        cd.id,
        cd.name::TEXT,
        cd.date_day,
        cd.date_month,
        cd.target_audience::TEXT,
        pcd.is_featured,
        pcd.source
    FROM product_commemorative_dates pcd
    JOIN commemorative_dates cd ON cd.id = pcd.commemorative_date_id
    WHERE pcd.product_id = p_product_id AND pcd.is_active = TRUE
    ORDER BY cd.date_month, cd.date_day;
END;
$$;


ALTER FUNCTION "public"."fn_get_product_dates"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_product_intelligence_all"() RETURNS TABLE("product_id" "uuid", "turnover_score" numeric, "avg_depletion_7d" numeric, "avg_depletion_30d" numeric, "abc_classification" "text", "total_depleted_30d" numeric, "total_depleted_90d" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- FIX GAP-2 (2026-06-18 audit): filtra produtos inativos/deletados.
  -- analytics.mv_product_intelligence incluía 72 registros de produtos desativados
  -- (originados de analytics.mv_stock_velocity que não filtra por is_active).
  -- Adicionar JOIN com products garante que a API sempre retorna apenas produtos ativos.
  SELECT
    mi.product_id,
    mi.turnover_score,
    mi.avg_depletion_7d,
    mi.avg_depletion_30d,
    mi.abc_classification,
    mi.total_depleted_30d,
    mi.total_depleted_90d
  FROM mv_product_intelligence mi          -- public view → analytics.mv_product_intelligence
  JOIN products p ON p.id = mi.product_id  -- filter: apenas ativos e não deletados
  WHERE p.is_active = true
    AND (p.is_deleted IS NOT TRUE OR p.is_deleted IS NULL);
$$;


ALTER FUNCTION "public"."fn_get_product_intelligence_all"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_get_product_intelligence_all"() IS 'Retorna TODAS as linhas de mv_product_intelligence para produtos ATIVOS (7 153+) sem limitação de max_rows.
   FIX BUG-A (2026-06-18): bypassa PostgREST max_rows=1000.
   FIX GAP-2 (2026-06-18 audit): filtra inativos/deletados via JOIN com products.
   Consumida por useSupplierSalesRanking para popular supplierSalesMap.';



CREATE OR REPLACE FUNCTION "public"."fn_get_product_packaging_summary"("p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_included  JSONB;
    v_compat    JSONB;
    v_product   RECORD;
BEGIN
    SELECT sku, name, product_type, shape_type, height_cm, width_cm, length_cm, diameter_cm
    INTO v_product FROM products WHERE id = p_product_id;

    IF v_product IS NULL THEN
        RETURN jsonb_build_object('error','Produto não encontrado');
    END IF;

    -- Embalagens inclusas
    SELECT jsonb_agg(jsonb_build_object(
        'id',            pip.id,
        'name',          pip.name,
        'material',      pip.material,
        'color',         pip.color,
        'can_customize', pip.can_be_customized,
        'can_disable',   pip.can_be_disabled,
        'has_cradle',    pip.has_inner_cradle,
        'dims_internal', CASE WHEN pip.internal_height_cm IS NOT NULL
            THEN jsonb_build_object('h',pip.internal_height_cm,'w',pip.internal_width_cm,'l',pip.internal_length_cm)
            ELSE NULL END,
        'areas_count',   (SELECT COUNT(*) FROM included_packaging_print_areas WHERE packaging_id = pip.id AND active = true),
        'techniques',    (SELECT jsonb_agg(technique_name ORDER BY display_order) FROM included_packaging_techniques WHERE packaging_id = pip.id AND active = true)
    ) ORDER BY pip.is_default DESC)
    INTO v_included
    FROM product_included_packagings pip
    WHERE pip.product_id = p_product_id AND pip.active = true;

    -- Embalagens compatíveis (opcionais recomendadas)
    SELECT jsonb_agg(jsonb_build_object(
        'packaging_id',  ppc.packaging_id,
        'sku',           pkg.sku,
        'name',          pkg.name,
        'fit_rating',    ppc.fit_rating,
        'gap_min_mm',    ppc.fit_gap_min_mm,
        'source',        ppc.compatibility_source,
        'recommended',   ppc.is_recommended,
        'same_supplier', ppc.is_same_supplier,
        'supplier',      (SELECT name FROM suppliers WHERE id = pkg.supplier_id),
        'price',         (SELECT unit_price FROM supplier_packagings WHERE packaging_id = ppc.packaging_id AND is_available = true ORDER BY unit_price LIMIT 1)
    ) ORDER BY ppc.is_recommended DESC, ppc.fit_gap_min_mm NULLS LAST)
    INTO v_compat
    FROM product_packaging_compatibility ppc
    JOIN products pkg ON pkg.id = ppc.packaging_id
    WHERE ppc.product_id = p_product_id AND ppc.active = true
      AND ppc.fit_rating IN ('tight','good','loose');

    RETURN jsonb_build_object(
        'product',       jsonb_build_object('sku',v_product.sku,'name',v_product.name,'shape',v_product.shape_type,
                            'dims',jsonb_build_object('h',v_product.height_cm,'w',v_product.width_cm,'l',v_product.length_cm,'d',v_product.diameter_cm)),
        'included',      COALESCE(v_included, '[]'::jsonb),
        'compatible',    COALESCE(v_compat, '[]'::jsonb),
        'has_packaging', (v_included IS NOT NULL AND jsonb_array_length(COALESCE(v_included,'[]'::jsonb)) > 0),
        'has_options',   (v_compat IS NOT NULL AND jsonb_array_length(COALESCE(v_compat,'[]'::jsonb)) > 0),
        'generated_at',  now()
    );
END;
$$;


