CREATE OR REPLACE FUNCTION "public"."fn_get_recent_restocks"("p_limit" integer DEFAULT 30, "p_since" "date" DEFAULT NULL::"date") RETURNS TABLE("product_id" "uuid", "product_name" "text", "product_sku" "text", "image_url" "text", "stock_quantity" integer, "supplier_id" "uuid", "supplier_name" "text", "last_restock_date" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH cenario_a AS (
    SELECT sds.product_id, max(sds.summary_date) AS last_restock_date
    FROM stock_daily_summary sds
    WHERE COALESCE(sds.stock_open,0)=0 AND COALESCE(sds.stock_close,0)>0
      AND sds.restock_detected=true
      AND sds.summary_date >= GREATEST(
        COALESCE(p_since, (CURRENT_DATE - INTERVAL '30 days')::date),
        (CURRENT_DATE - INTERVAL '30 days')::date
      )
    GROUP BY sds.product_id
  )
  SELECT p.id, p.name::text, p.sku::text, p.primary_image_url::text, p.stock_quantity,
         p.supplier_id, s.name::text, ca.last_restock_date
  FROM cenario_a ca
  JOIN products p ON p.id=ca.product_id
  LEFT JOIN suppliers s ON s.id=p.supplier_id
  WHERE p.is_active=true AND p.stock_quantity>0
  ORDER BY ca.last_restock_date DESC, p.stock_quantity DESC, p.id
  LIMIT GREATEST(p_limit,0);
$$;


ALTER FUNCTION "public"."fn_get_recent_restocks"("p_limit" integer, "p_since" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_replenishment_stats"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH
  cfg AS (SELECT (now() AT TIME ZONE 'America/Sao_Paulo')::date AS today),
  cenario_a AS (
    SELECT DISTINCT sds.product_id, sds.supplier_id, sds.summary_date
    FROM stock_daily_summary sds
    JOIN products p ON p.id = sds.product_id AND p.is_active = true
    WHERE sds.restock_zero_to_positive = true
      AND COALESCE(sds.stock_close, 0) > 0
      AND sds.summary_date >= (SELECT today FROM cfg) - 30
  ),
  cenario_b AS (
    SELECT DISTINCT sds.product_id, sds.supplier_id, sds.summary_date
    FROM stock_daily_summary sds
    JOIN products p ON p.id = sds.product_id AND p.is_active = true
    WHERE COALESCE(sds.stock_open, 0) > 0
      AND COALESCE(sds.stock_close, 0) > COALESCE(sds.stock_open, 0)
      AND sds.restock_detected = true
      AND sds.summary_date >= (SELECT today FROM cfg) - 30
  ),
  a_hoje AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a WHERE summary_date = (SELECT today FROM cfg)),
  a_7d   AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a WHERE summary_date >= (SELECT today FROM cfg) - 7),
  a_15d  AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a WHERE summary_date >= (SELECT today FROM cfg) - 15),
  a_30d  AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a),
  a_expiring AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a WHERE summary_date <= (SELECT today FROM cfg) - 23),
  b_7d   AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_b WHERE summary_date >= (SELECT today FROM cfg) - 7),
  b_30d  AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_b),
  top_a AS (
    SELECT s.name, COUNT(DISTINCT ca.product_id)::int AS cnt
    FROM cenario_a ca
    JOIN suppliers s ON s.id = ca.supplier_id
    WHERE s.name IS NOT NULL
    GROUP BY s.name ORDER BY cnt DESC LIMIT 1
  ),
  ativas AS (
    SELECT
      COUNT(*)::int                                             AS total_var,
      COUNT(*) FILTER (WHERE has_incoming_stock  = true)::int  AS incoming,
      COUNT(*) FILTER (WHERE has_upcoming_restock = true)::int AS upcoming
    FROM vw_product_availability
  )
  SELECT jsonb_build_object(
    'restockedToday',           (SELECT n FROM a_hoje),
    'restockedThisWeek',        (SELECT n FROM a_7d),
    'restockedLast15Days',      (SELECT n FROM a_15d),
    'restockedLast30Days',      (SELECT n FROM a_30d),
    'expiringSoon',             (SELECT n FROM a_expiring),
    'topSupplierName',          COALESCE((SELECT name FROM top_a), null),
    'topSupplierCount',         COALESCE((SELECT cnt  FROM top_a), 0),
    'activeReplenishments',     (SELECT incoming FROM ativas),
    'totalVariants',            (SELECT total_var FROM ativas),
    'replenishmentRate',        ROUND((SELECT incoming::numeric FROM ativas) / NULLIF((SELECT total_var FROM ativas), 0) * 100),
    'reorderedThisWeek',        (SELECT n FROM b_7d),
    'reorderedThisMonth',       (SELECT n FROM b_30d),
    'upcomingRestockVariants',  (SELECT upcoming FROM ativas),
    '_version',                 'v5_fixes_20260619'
  );
$$;


ALTER FUNCTION "public"."fn_get_replenishment_stats"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_get_replenishment_stats"() IS 'KPI cards do módulo Reposição. restockedToday/Week/15d = Cenário A: produtos que saíram de stock=0 para >0 (voltaram do esgotamento). activeReplenishments = variantes esgotadas com next_date_1 futura (prospectivo). topSupplierName/Count = fornecedor líder em restocks reais (Cenário A).';



CREATE OR REPLACE FUNCTION "public"."fn_get_reposicao_listing"("p_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_sort_by" "text" DEFAULT 'mais_recentes'::"text", "p_limit" integer DEFAULT 48, "p_offset" integer DEFAULT 0, "p_days" integer DEFAULT 30) RETURNS TABLE("product_id" "uuid", "name" "text", "slug" "text", "sku" "text", "sale_price" numeric, "is_stockout" boolean, "is_new" boolean, "total_stock" bigint, "primary_image_url" "text", "primary_image_cdn" "text", "supplier_id" "uuid", "supplier_name" "text", "supplier_code" "text", "ultimo_restock_date" "date", "earliest_restock_date" "date", "earliest_restock_qty" bigint, "has_upcoming_restock" boolean, "category_names" "text"[], "primary_category_id" "uuid", "primary_category_name" "text", "is_low_stock" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_today date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
BEGIN
  p_limit := GREATEST(p_limit, 0);
  RETURN QUERY
  WITH
  restock_events AS (
    SELECT DISTINCT ON (g.product_id) g.product_id, g.supplier_id, g.ultimo_restock
    FROM (
      SELECT sd.product_id, sd.supplier_id, MAX(sd.summary_date) AS ultimo_restock
      FROM stock_daily_summary sd
      WHERE sd.restock_zero_to_positive = true AND COALESCE(sd.stock_close, 0) > 0
        AND sd.summary_date >= v_today - p_days
      GROUP BY sd.product_id, sd.supplier_id
    ) g
    ORDER BY g.product_id, g.ultimo_restock DESC, g.supplier_id
  ),
  variant_agg AS (
    SELECT pv.product_id,
      SUM(pv.stock_quantity) AS total_stock,
      LEAST(
        MIN(pv.next_date_1) FILTER (WHERE pv.next_date_1 > v_today),
        MIN(pv.next_date_2) FILTER (WHERE pv.next_date_2 > v_today),
        MIN(pv.next_date_3) FILTER (WHERE pv.next_date_3 > v_today),
        MIN(pv.next_date_4) FILTER (WHERE pv.next_date_4 > v_today),
        MIN(pv.next_date_5) FILTER (WHERE pv.next_date_5 > v_today),
        MIN(pv.next_date_6) FILTER (WHERE pv.next_date_6 > v_today)
      ) AS earliest_restock_date,
      COALESCE(SUM(pv.next_quantity_1) FILTER (WHERE pv.next_date_1 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_2) FILTER (WHERE pv.next_date_2 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_3) FILTER (WHERE pv.next_date_3 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_4) FILTER (WHERE pv.next_date_4 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_5) FILTER (WHERE pv.next_date_5 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_6) FILTER (WHERE pv.next_date_6 > v_today), 0)
        AS earliest_restock_qty,
      BOOL_OR(
        (pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today) OR
        (pv.next_date_2 IS NOT NULL AND pv.next_date_2 > v_today) OR
        (pv.next_date_3 IS NOT NULL AND pv.next_date_3 > v_today) OR
        (pv.next_date_4 IS NOT NULL AND pv.next_date_4 > v_today) OR
        (pv.next_date_5 IS NOT NULL AND pv.next_date_5 > v_today) OR
        (pv.next_date_6 IS NOT NULL AND pv.next_date_6 > v_today)
      ) AS has_upcoming_restock
    FROM product_variants pv
    WHERE pv.is_active = true AND pv.product_id IN (SELECT re2.product_id FROM restock_events re2)
    GROUP BY pv.product_id
  ),
  primary_imgs AS (
    SELECT DISTINCT ON (pi.product_id) pi.product_id, pi.url_cdn
    FROM product_images pi
    WHERE pi.is_primary = true AND pi.is_active = true
      AND pi.product_id IN (SELECT re3.product_id FROM restock_events re3)
    ORDER BY pi.product_id, pi.updated_at DESC NULLS LAST
  ),
  category_agg AS (
    SELECT d.product_id,
      (ARRAY_AGG(d.resolved_name ORDER BY d.resolved_name))[1:3] AS category_names,
      (ARRAY_AGG(d.resolved_id   ORDER BY d.resolved_name))[1]   AS primary_category_id,
      (ARRAY_AGG(d.resolved_name ORDER BY d.resolved_name))[1]   AS primary_category_name
    FROM (
      SELECT DISTINCT pca.product_id,
        COALESCE(
          CASE WHEN c.level  IN (1,2) THEN c.id  END,
          CASE WHEN p1.level IN (1,2) THEN p1.id END,
          CASE WHEN p2.level IN (1,2) THEN p2.id END,
          CASE WHEN p3.level IN (1,2) THEN p3.id END,
          CASE WHEN p4.level IN (1,2) THEN p4.id END,
          c.id
        ) AS resolved_id,
        COALESCE(
          CASE WHEN c.level  IN (1,2) THEN c.name  END,
          CASE WHEN p1.level IN (1,2) THEN p1.name END,
          CASE WHEN p2.level IN (1,2) THEN p2.name END,
          CASE WHEN p3.level IN (1,2) THEN p3.name END,
          CASE WHEN p4.level IN (1,2) THEN p4.name END,
          c.name
        ) AS resolved_name
      FROM product_category_assignments pca
      JOIN categories c ON c.id = pca.category_id
      LEFT JOIN categories p1 ON p1.id = c.parent_id
      LEFT JOIN categories p2 ON p2.id = p1.parent_id
      LEFT JOIN categories p3 ON p3.id = p2.parent_id
      LEFT JOIN categories p4 ON p4.id = p3.parent_id
      WHERE pca.product_id IN (SELECT re4.product_id FROM restock_events re4)
    ) d
    GROUP BY d.product_id
  ),
  product_base AS (
    SELECT p.id, p.name, p.slug, p.sku, p.sale_price, p.is_stockout, p.is_new,
      re.supplier_id, p.primary_image_url, re.ultimo_restock,
      s.name AS supplier_name, s.code AS supplier_code, s.low_stock_threshold,
      pi.url_cdn AS primary_image_cdn,
      COALESCE(va.total_stock, 0) AS total_stock,
      va.earliest_restock_date,
      COALESCE(va.earliest_restock_qty, 0) AS earliest_restock_qty,
      COALESCE(va.has_upcoming_restock, false) AS has_upcoming_restock,
      COALESCE(ca.category_names, ARRAY[]::text[]) AS category_names,
      ca.primary_category_id, ca.primary_category_name
    FROM restock_events re
    JOIN products p  ON p.id = re.product_id AND p.is_active = true
    JOIN suppliers s ON s.id = re.supplier_id
    LEFT JOIN primary_imgs pi ON pi.product_id = p.id
    LEFT JOIN variant_agg va  ON va.product_id = p.id
    LEFT JOIN category_agg ca ON ca.product_id = p.id
    WHERE (p_supplier_id IS NULL OR re.supplier_id = p_supplier_id)
      AND (p_category_id IS NULL OR EXISTS (
            SELECT 1 FROM product_category_assignments pca5
            WHERE pca5.product_id = p.id AND pca5.category_id = p_category_id))
  )
  SELECT pb.id, pb.name::text, pb.slug::text, pb.sku::text, pb.sale_price,
    pb.is_stockout, pb.is_new, pb.total_stock,
    pb.primary_image_url::text, pb.primary_image_cdn::text,
    pb.supplier_id, pb.supplier_name::text, pb.supplier_code::text,
    pb.ultimo_restock, pb.earliest_restock_date, pb.earliest_restock_qty,
    pb.has_upcoming_restock, pb.category_names,
    pb.primary_category_id, pb.primary_category_name::text,
    (pb.total_stock > 0 AND pb.low_stock_threshold IS NOT NULL
     AND pb.total_stock <= pb.low_stock_threshold) AS is_low_stock
  FROM product_base pb
  ORDER BY
    CASE WHEN p_sort_by = 'nome_az'       THEN pb.name        END ASC  NULLS LAST,
    CASE WHEN p_sort_by = 'nome_za'       THEN pb.name        END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'preco_menor'   THEN pb.sale_price  END ASC  NULLS LAST,
    CASE WHEN p_sort_by = 'preco_maior'   THEN pb.sale_price  END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'maior_estoque' THEN pb.total_stock END DESC NULLS LAST,
    CASE WHEN p_sort_by NOT IN ('nome_az','nome_za','preco_menor','preco_maior','maior_estoque')
         THEN pb.ultimo_restock END DESC NULLS LAST,
    pb.id
  LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."fn_get_reposicao_listing"("p_supplier_id" "uuid", "p_category_id" "uuid", "p_sort_by" "text", "p_limit" integer, "p_offset" integer, "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_reposicao_metrics"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_hoje int; v_7d int; v_15d int; v_30d int;
  v_top_supplier text; v_top_count int;
  v_ativas int; v_aguardando int; v_pct_ativas numeric;
  v_total_vars int; v_data_min date; v_dias_hist int;
BEGIN
  SELECT
    COUNT(DISTINCT CASE WHEN sd.summary_date = v_today       THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 7  THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 15 THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 30 THEN sd.product_id END),
    MIN(sd.summary_date), (v_today - MIN(sd.summary_date))
  INTO v_hoje, v_7d, v_15d, v_30d, v_data_min, v_dias_hist
  FROM stock_daily_summary sd JOIN products p ON p.id = sd.product_id
  WHERE sd.restock_zero_to_positive = true AND sd.summary_date >= v_today - 30
    AND sd.stock_close > 0 AND p.is_active = true;

  SELECT s.name, COUNT(DISTINCT sd.product_id) INTO v_top_supplier, v_top_count
  FROM stock_daily_summary sd JOIN suppliers s ON s.id = sd.supplier_id
  JOIN products p ON p.id = sd.product_id
  WHERE sd.restock_zero_to_positive = true AND sd.summary_date >= v_today - 7
    AND sd.stock_close > 0 AND p.is_active = true
  GROUP BY s.name ORDER BY COUNT(DISTINCT sd.product_id) DESC LIMIT 1;

  SELECT COUNT(*) INTO v_total_vars FROM product_variants WHERE is_active = true;

  SELECT
    COUNT(*) FILTER (WHERE pv.stock_quantity = 0 AND pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today),
    COUNT(*) FILTER (WHERE pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today)
  INTO v_ativas, v_aguardando FROM product_variants pv WHERE pv.is_active = true;

  v_pct_ativas := ROUND(100.0 * v_ativas / NULLIF(v_total_vars, 0), 1);

  RETURN jsonb_build_object(
    'dias_historico_real', v_dias_hist, 'data_inicio_historico', v_data_min,
    'aviso_historico', CASE WHEN v_dias_hist < 30
      THEN 'Histórico incompleto: ' || v_dias_hist::text || ' dias disponíveis (meta: 30)'
      ELSE 'OK' END,
    'repostos_hoje', v_hoje, 'repostos_7d', v_7d, 'repostos_15d', v_15d, 'repostos_30d', v_30d,
    '7d_igual_15d_aviso', (v_7d = v_15d AND v_dias_hist < 15),
    'top_supplier_nome', v_top_supplier, 'top_supplier_count', v_top_count,
    'variacoes_ativas_zero_com_previsao', v_ativas, 'variacoes_aguardando_lote', v_aguardando,
    'pct_variacoes_com_reposicao', v_pct_ativas, 'gerado_em', now(), 'versao', 'v3_stable_20260619'
  );
END;
$$;


ALTER FUNCTION "public"."fn_get_reposicao_metrics"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_get_reposicao_metrics"() IS 'KPIs oficiais do módulo Reposição. Usa restock_zero_to_positive (transição real 0→+) com filtro stock_close>0 para excluir restocks transientes. Retorna aviso quando histórico < 30 dias. v1_semantica_correta.';



CREATE OR REPLACE FUNCTION "public"."fn_get_reposicao_variants_summary"("p_product_ids" "uuid"[]) RETURNS TABLE("product_id" "uuid", "variants_summary" "jsonb", "total_variants" integer, "variants_in_stock" integer, "variants_zeroed" integer, "variants_with_upcoming" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH v_today AS (
    SELECT (now() AT TIME ZONE 'America/Sao_Paulo')::date AS d
  ),
  future_dates AS (
    SELECT pv.id AS variant_id, x.d::date AS dt
    FROM public.product_variants pv
    CROSS JOIN LATERAL (VALUES
      (pv.next_date_1),(pv.next_date_2),(pv.next_date_3),
      (pv.next_date_4),(pv.next_date_5),(pv.next_date_6)
    ) AS x(d)
    WHERE pv.product_id = ANY(p_product_ids)
      AND x.d IS NOT NULL
      AND x.d::date > (SELECT v_today.d FROM v_today)
    UNION ALL
    SELECT vss.variant_id, x.d::date
    FROM public.variant_supplier_sources vss
    JOIN public.product_variants pv2 ON pv2.id = vss.variant_id
    CROSS JOIN LATERAL (VALUES
      (vss.next_date_1),(vss.next_date_2),(vss.next_date_3),
      (vss.next_date_4),(vss.next_date_5),(vss.next_date_6)
    ) AS x(d)
    WHERE pv2.product_id = ANY(p_product_ids)
      AND COALESCE(vss.is_active, true) = true
      AND x.d IS NOT NULL
      AND x.d::date > (SELECT v_today.d FROM v_today)
  ),
  next_per_variant AS (
    SELECT variant_id, MIN(dt) AS next_restock_date
    FROM future_dates
    GROUP BY variant_id
  ),
  vs AS (
    SELECT
      pv.product_id,
      pv.id                                   AS variant_id,
      pv.color_name                           AS nome,
      pv.color_hex                            AS hex,
      COALESCE(pv.stock_quantity, 0)::int     AS stock_qty,
      npv.next_restock_date
    FROM public.product_variants pv
    LEFT JOIN next_per_variant npv ON npv.variant_id = pv.id
    WHERE pv.product_id = ANY(p_product_ids)
      AND COALESCE(pv.is_active, true) = true
  )
  SELECT
    vs.product_id,
    jsonb_agg(
      jsonb_build_object(
        'variant_id',           vs.variant_id,
        'nome',                 vs.nome,
        'hex',                  vs.hex,
        'stock_qty',            vs.stock_qty,
        'has_upcoming_restock', (vs.next_restock_date IS NOT NULL),
        'next_restock_date',    vs.next_restock_date
      )
      ORDER BY vs.nome NULLS LAST
    )                                                              AS variants_summary,
    COUNT(*)::int                                                  AS total_variants,
    COUNT(*) FILTER (WHERE vs.stock_qty > 0)::int                  AS variants_in_stock,
    COUNT(*) FILTER (WHERE vs.stock_qty = 0
                     AND vs.next_restock_date IS NULL)::int        AS variants_zeroed,
    COUNT(*) FILTER (WHERE vs.next_restock_date IS NOT NULL)::int  AS variants_with_upcoming
  FROM vs
  GROUP BY vs.product_id;
$$;


