CREATE OR REPLACE FUNCTION "public"."fn_get_repressed_demand"("p_user_id" "uuid" DEFAULT NULL::"uuid", "p_days" integer DEFAULT 30, "p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_since   timestamptz;
  v_result  jsonb;
BEGIN
  IF p_user_id IS NOT NULL
     AND p_user_id != auth.uid()
     AND NOT is_manager_or_admin()
  THEN
    RETURN jsonb_build_object('error','Acesso negado');
  END IF;

  p_days  := GREATEST(1, LEAST(COALESCE(p_days, 30), 999));
  p_limit := GREATEST(1, LEAST(COALESCE(p_limit, 20), 100));
  v_since := NOW() - (p_days || ' days')::interval;

  WITH zero_terms AS (
    SELECT
      search_term,
      COUNT(*) FILTER (WHERE results_count != -1)          AS total_buscas,
      SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END)   AS zeros,
      ROUND(
        100.0 * SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END)
        / NULLIF(COUNT(*) FILTER (WHERE results_count != -1), 0), 1
      ) AS pct_zero
    FROM public.search_analytics
    WHERE created_at >= v_since
    GROUP BY search_term
    HAVING SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END) > 0
    ORDER BY SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END) DESC
    LIMIT p_limit
  ),
  enriched AS (
    SELECT
      zt.search_term, zt.total_buscas,
      zt.zeros AS zero_result_searches, zt.pct_zero,
      (SELECT COUNT(*)::int FROM public.products p
       WHERE p.is_active = true
         AND (p.is_deleted IS NULL OR p.is_deleted = false)
         AND p.sale_price IS NOT NULL
         AND p.search_vector @@ websearch_to_tsquery('portuguese', unaccent(zt.search_term))
      ) AS db_fulltext_count,
      (SELECT COUNT(*)::int FROM public.products p
       WHERE p.is_active = true
         AND (p.is_deleted IS NULL OR p.is_deleted = false)
         AND (p.sku ILIKE zt.search_term OR p.sku_promo ILIKE zt.search_term)
      ) AS db_sku_exact_count
    FROM zero_terms zt
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'term',                 e.search_term,
      'searches',             e.total_buscas,
      'zero_result_searches', e.zero_result_searches,
      'pct_zero',             e.pct_zero,
      'db_fulltext_results',  e.db_fulltext_count,
      'db_sku_results',       e.db_sku_exact_count,
      'diagnosis', CASE
        WHEN e.db_fulltext_count > 0 OR e.db_sku_exact_count > 0 THEN 'false_zero'
        ELSE 'true_gap' END,
      'diagnosis_label', CASE
        WHEN e.db_fulltext_count > 0 OR e.db_sku_exact_count > 0
          THEN 'Produto existe no catálogo — verificar busca no frontend'
        ELSE 'Produto ausente — oportunidade de cadastro' END
    )
    ORDER BY e.zero_result_searches DESC
  ) INTO v_result
  FROM enriched e;

  RETURN jsonb_build_object(
    'period_days', p_days, 'generated_at', NOW(),
    'items', COALESCE(v_result, '[]'::jsonb)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM, 'items', '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."fn_get_repressed_demand"("p_user_id" "uuid", "p_days" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_similar_products"("p_product_id" "uuid", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("similar_product_id" "uuid", "direction" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  -- Direção outgoing: este produto é o "origin" (product_id = p_product_id)
  -- Usa o índice UNIQUE (product_id, related_product_id, relationship_type) → Bitmap Index Scan eficiente
  (
    SELECT pr.related_product_id AS similar_product_id,
           'outgoing'            AS direction
    FROM   public.product_relationships pr
    WHERE  pr.product_id        = p_product_id
      AND  pr.relationship_type = 'similar'
      AND  pr.is_active         = true
    ORDER  BY pr.related_product_id
  )
  UNION ALL
  -- Direção incoming: este produto está no lado "destination" (related_product_id = p_product_id)
  -- Usa o índice idx_product_relationships_related_product_id → Index Scan eficiente
  (
    SELECT pr.product_id   AS similar_product_id,
           'incoming'      AS direction
    FROM   public.product_relationships pr
    WHERE  pr.related_product_id = p_product_id
      AND  pr.relationship_type  = 'similar'
      AND  pr.is_active          = true
    ORDER  BY pr.product_id
  )
  LIMIT  p_limit
  OFFSET p_offset
$$;


ALTER FUNCTION "public"."fn_get_similar_products"("p_product_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_get_similar_products"("p_product_id" "uuid", "p_limit" integer, "p_offset" integer) IS 'Retorna produtos similares consultando AMBAS as direções de product_relationships
   (product_id = X  e  related_product_id = X), corrigindo o gap causado pelo
   armazenamento canônico unidirecional imposto por idx_product_relationships_canonical_pair.
   Substitui a query direta na tabela pelo hook useSimilarProducts.ts via RPC.';



