COMMENT ON FUNCTION "public"."fn_global_search"("p_term" "text", "p_limit" integer, "p_types" "text"[]) IS 'Busca global. anon EXECUTE OK (quotes gated por auth.uid() IS NOT NULL). fix_version 20260717_grant_anon_catalog_rpcs_v1. ANTI-REGRESSAO: nao revogar anon.';



CREATE OR REPLACE FUNCTION "public"."fn_grant_default_role_on_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = NEW.id) THEN
    INSERT INTO public.user_roles (user_id, role, granted_by)
    VALUES (
      NEW.id,
      CASE 
        WHEN NEW.role = 'admin'             THEN 'admin'::public.app_role
        WHEN NEW.role = 'manager'           THEN 'coordenador'::public.app_role
        WHEN NEW.role IN ('sales','seller') THEN 'vendedor'::public.app_role
        WHEN NEW.role = 'dev'               THEN 'dev'::public.app_role
        ELSE 'vendedor'::public.app_role
      END,
      NEW.id  -- self-granted; trigger only fires on first INSERT
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_grant_default_role_on_profile"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_grant_default_role_on_profile"() IS 'A1-1c: cria linha em user_roles na criacao de profile, mapeando profile.role (text) para app_role (enum 4-niveis). Default seguro: vendedor.';



CREATE OR REPLACE FUNCTION "public"."fn_handle_canonical_root_soft_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_new_root uuid;
BEGIN
  -- Find oldest active dep to promote
  SELECT id INTO v_new_root
  FROM public.product_images
  WHERE canonical_image_id = NEW.id
    AND deleted_at IS NULL
  ORDER BY created_at ASC, id ASC
  LIMIT 1;

  IF v_new_root IS NOT NULL THEN
    -- Promote oldest dep to root (canonical=NULL, is_shared=false)
    UPDATE public.product_images
    SET canonical_image_id = NULL,
        is_shared = false,
        last_modified_source = 'edge_function',
        updated_at = now()
    WHERE id = v_new_root;

    -- Re-point other deps to new root
    UPDATE public.product_images
    SET canonical_image_id = v_new_root,
        last_modified_source = 'edge_function',
        updated_at = now()
    WHERE canonical_image_id = NEW.id
      AND id <> v_new_root
      AND deleted_at IS NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_handle_canonical_root_soft_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_handle_image_restoration"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_canon_deleted boolean;
BEGIN
  -- Only act on restoration (deleted → live)
  IF NEW.deleted_at IS NOT NULL OR OLD.deleted_at IS NULL THEN
    RETURN NEW;
  END IF;

  -- If image has a canonical assignment, check if that root is still alive
  IF NEW.canonical_image_id IS NOT NULL THEN
    SELECT (deleted_at IS NOT NULL) INTO v_canon_deleted
    FROM public.product_images
    WHERE id = NEW.canonical_image_id;

    IF v_canon_deleted IS TRUE THEN
      -- Stale canonical: canonical was deleted after this dep was soft-deleted.
      -- Detach: make this image a standalone root.
      NEW.canonical_image_id := NULL;
      NEW.is_shared := false;
      NEW.last_modified_source := COALESCE(NULLIF(NEW.last_modified_source, ''), 'edge_function');
      NEW.updated_at := now();
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_handle_image_restoration"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, 'vendedor'::public.app_role)
  ON CONFLICT DO NOTHING;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Mantemos o trigger não-bloqueante (signup nunca falha por causa da role),
  -- mas agora deixamos rastro em log em vez de engolir o erro em silêncio.
  RAISE NOTICE 'fn_handle_new_user falhou para user_id=%: %', NEW.id, SQLERRM;
  RETURN NEW;
END
$$;


