CREATE OR REPLACE FUNCTION "public"."fn_import_spot_image"("p_filename" "text", "p_cloudflare_id" "text", "p_url_original" "text", "p_width" integer DEFAULT NULL::integer, "p_height" integer DEFAULT NULL::integer, "p_file_size" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_class RECORD;
    v_product_id UUID;
    v_new_id UUID;
    v_cf_url TEXT;
BEGIN
    SELECT * INTO v_class FROM fn_classify_spot_image(p_filename) LIMIT 1;
    
    IF v_class.prod_reference IS NULL THEN
        RAISE EXCEPTION 'Filename não reconhecido: %', p_filename;
    END IF;
    
    SELECT p.id INTO v_product_id
    FROM products p
    WHERE p.supplier_reference = v_class.prod_reference
      AND p.supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'::uuid
    LIMIT 1;
    
    IF v_product_id IS NULL THEN
        RAISE WARNING 'Produto não encontrado para ref: %', v_class.prod_reference;
        RETURN NULL;
    END IF;
    
    v_cf_url := 'https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/' || p_cloudflare_id || '/public';
    
    INSERT INTO product_images (
        id, product_id, 
        image_type, image_type_id,
        cloudflare_image_id, url_cdn, url_original,
        filename, format,
        width_px, height_px, file_size_bytes,
        is_primary, is_active, is_og_image,
        applies_to_color, display_order,
        source_supplier, supplier_code,
        organization_id,
        alt_text, title_text,
        created_at, updated_at
    ) VALUES (
        gen_random_uuid(), v_product_id,
        v_class.image_type, v_class.image_type_id,
        p_cloudflare_id, v_cf_url, p_url_original,
        p_filename, LOWER(SPLIT_PART(p_filename, '.', 2)),
        p_width, p_height, p_file_size,
        v_class.is_primary_image, true, v_class.is_primary_image,
        v_class.is_color_specific, v_class.display_order_hint,
        'SPOT', 'SPOT',
        '5db5aee1-064b-4ef4-9193-345dcd8274ea',
        NULL, NULL,
        NOW(), NOW()
    )
    ON CONFLICT (cloudflare_image_id) WHERE cloudflare_image_id IS NOT NULL
    DO NOTHING
    RETURNING id INTO v_new_id;
    
    IF v_new_id IS NULL THEN
        RAISE WARNING 'Imagem já existe (duplicata): %', p_filename;
    END IF;
    
    RETURN v_new_id;
END;
$$;


ALTER FUNCTION "public"."fn_import_spot_image"("p_filename" "text", "p_cloudflare_id" "text", "p_url_original" "text", "p_width" integer, "p_height" integer, "p_file_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_import_stock_from_spot"("p_stocks" "jsonb") RETURNS TABLE("total_processed" integer, "total_updated" integer, "total_created" integer, "total_skipped" integer, "total_errors" integer, "details" "jsonb")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_stock         JSONB;
    v_processed     INTEGER := 0;
    v_updated       INTEGER := 0;
    v_created       INTEGER := 0;
    v_skipped       INTEGER := 0;
    v_errors        INTEGER := 0;
    v_bronze_closed INTEGER := 0;
    v_supplier_id   UUID;
    v_variant_id    UUID;
    v_sku           TEXT;
    v_error_skus    TEXT[] := '{}';
    v_skipped_skus  TEXT[] := '{}';
BEGIN
    SELECT id INTO v_supplier_id
    FROM suppliers
    WHERE code = 'STRICKER' OR code = 'SPOT'
       OR name ILIKE '%spot%' OR name ILIKE '%stricker%'
    LIMIT 1;

    IF v_supplier_id IS NULL THEN
        RAISE EXCEPTION 'Fornecedor SPOT/Stricker não encontrado';
    END IF;

    FOR v_stock IN SELECT * FROM jsonb_array_elements(p_stocks)
    LOOP
        v_processed := v_processed + 1;
        v_sku := v_stock->>'Sku';

        BEGIN
            -- FIX B12: UPDATE com 6 janelas (antes tinha só 3)
            UPDATE variant_supplier_sources
            SET
                quantity        = COALESCE((v_stock->>'Quantity')::INTEGER, 0),
                -- Janelas 1-3 (antes existiam)
                next_quantity_1 = NULLIF((v_stock->>'NextQuantity1')::INTEGER, 0),
                next_date_1     = NULLIF(v_stock->>'NextDate1', '')::DATE,
                next_quantity_2 = NULLIF((v_stock->>'NextQuantity2')::INTEGER, 0),
                next_date_2     = NULLIF(v_stock->>'NextDate2', '')::DATE,
                next_quantity_3 = NULLIF((v_stock->>'NextQuantity3')::INTEGER, 0),
                next_date_3     = NULLIF(v_stock->>'NextDate3', '')::DATE,
                -- FIX B12: Janelas 4-6 (antes ausentes)
                next_quantity_4 = NULLIF((v_stock->>'NextQuantity4')::INTEGER, 0),
                next_date_4     = NULLIF(v_stock->>'NextDate4', '')::DATE,
                next_quantity_5 = NULLIF((v_stock->>'NextQuantity5')::INTEGER, 0),
                next_date_5     = NULLIF(v_stock->>'NextDate5', '')::DATE,
                next_quantity_6 = NULLIF((v_stock->>'NextQuantity6')::INTEGER, 0),
                next_date_6     = NULLIF(v_stock->>'NextDate6', '')::DATE,
                last_synced_at  = NOW(),
                sync_status     = 'synced',
                sync_error      = NULL,
                source          = 'spot_api',
                raw_data        = v_stock,
                updated_at      = NOW()
            WHERE supplier_sku = v_sku
              AND supplier_id  = v_supplier_id;

            IF FOUND THEN
                -- FIX B12: também propagar janelas 1-3 para product_variants
                UPDATE product_variants pv
                SET
                    stock_quantity  = COALESCE((v_stock->>'Quantity')::INTEGER, 0),
                    next_quantity_1 = NULLIF((v_stock->>'NextQuantity1')::INTEGER, 0),
                    next_date_1     = NULLIF(v_stock->>'NextDate1', '')::DATE,
                    next_quantity_2 = NULLIF((v_stock->>'NextQuantity2')::INTEGER, 0),
                    next_date_2     = NULLIF(v_stock->>'NextDate2', '')::DATE,
                    next_quantity_3 = NULLIF((v_stock->>'NextQuantity3')::INTEGER, 0),
                    next_date_3     = NULLIF(v_stock->>'NextDate3', '')::DATE,
                    last_sync_at    = NOW()
                WHERE pv.supplier_sku = v_sku
                  AND pv.is_active    = true;

                v_updated := v_updated + 1;
            ELSE
                SELECT id INTO v_variant_id
                FROM product_variants
                WHERE sku = v_sku OR supplier_sku = v_sku
                LIMIT 1;

                IF v_variant_id IS NOT NULL THEN
                    INSERT INTO variant_supplier_sources (
                        organization_id, variant_id, supplier_id, supplier_sku,
                        quantity,
                        next_quantity_1, next_date_1,
                        next_quantity_2, next_date_2,
                        next_quantity_3, next_date_3,
                        next_quantity_4, next_date_4,
                        next_quantity_5, next_date_5,
                        next_quantity_6, next_date_6,
                        pack_quantity, min_qty_1, min_order_qty,
                        is_active, is_preferred, priority,
                        source, sync_status, last_synced_at, raw_data, sale_multiplier
                    ) VALUES (
                        '5db5aee1-064b-4ef4-9193-345dcd8274ea',
                        v_variant_id, v_supplier_id, v_sku,
                        COALESCE((v_stock->>'Quantity')::INTEGER, 0),
                        NULLIF((v_stock->>'NextQuantity1')::INTEGER, 0),
                        NULLIF(v_stock->>'NextDate1', '')::DATE,
                        NULLIF((v_stock->>'NextQuantity2')::INTEGER, 0),
                        NULLIF(v_stock->>'NextDate2', '')::DATE,
                        NULLIF((v_stock->>'NextQuantity3')::INTEGER, 0),
                        NULLIF(v_stock->>'NextDate3', '')::DATE,
                        NULLIF((v_stock->>'NextQuantity4')::INTEGER, 0),
                        NULLIF(v_stock->>'NextDate4', '')::DATE,
                        NULLIF((v_stock->>'NextQuantity5')::INTEGER, 0),
                        NULLIF(v_stock->>'NextDate5', '')::DATE,
                        NULLIF((v_stock->>'NextQuantity6')::INTEGER, 0),
                        NULLIF(v_stock->>'NextDate6', '')::DATE,
                        1, 1, 1, true, true, 1,
                        'spot_api', 'synced', NOW(), v_stock, 1
                    )
                    ON CONFLICT (organization_id, variant_id, supplier_id)
                    DO UPDATE SET
                        quantity        = EXCLUDED.quantity,
                        next_quantity_1 = EXCLUDED.next_quantity_1, next_date_1 = EXCLUDED.next_date_1,
                        next_quantity_2 = EXCLUDED.next_quantity_2, next_date_2 = EXCLUDED.next_date_2,
                        next_quantity_3 = EXCLUDED.next_quantity_3, next_date_3 = EXCLUDED.next_date_3,
                        next_quantity_4 = EXCLUDED.next_quantity_4, next_date_4 = EXCLUDED.next_date_4,
                        next_quantity_5 = EXCLUDED.next_quantity_5, next_date_5 = EXCLUDED.next_date_5,
                        next_quantity_6 = EXCLUDED.next_quantity_6, next_date_6 = EXCLUDED.next_date_6,
                        last_synced_at  = NOW(), sync_status = 'synced',
                        raw_data        = EXCLUDED.raw_data, updated_at = NOW();

                    v_created := v_created + 1;
                ELSE
                    v_skipped := v_skipped + 1;
                    v_skipped_skus := array_append(v_skipped_skus, v_sku);
                END IF;
            END IF;

        EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors + 1;
            v_error_skus := array_append(v_error_skus, v_sku || ': ' || SQLERRM);
            CONTINUE;
        END;
    END LOOP;

    -- Fechar ciclo de vida Bronze
    UPDATE public.supplier_products_raw
    SET stock_status    = 'processed'::supplier_raw_status,
        stock_synced_at = now()
    WHERE supplier_id = v_supplier_id
      AND stock_status IS DISTINCT FROM 'processed'::supplier_raw_status;
    GET DIAGNOSTICS v_bronze_closed = ROW_COUNT;

    RETURN QUERY SELECT
        v_processed, v_updated, v_created, v_skipped, v_errors,
        jsonb_build_object(
            'error_skus',        to_jsonb(v_error_skus[1:10]),
            'skipped_skus_sample', to_jsonb(v_skipped_skus[1:10]),
            'supplier_id',       v_supplier_id,
            'bronze_closed',     v_bronze_closed,
            'fix_b12',           '6_janelas_n8n_path_alinhado_com_pg_cron'
        );
END;
$$;


ALTER FUNCTION "public"."fn_import_stock_from_spot"("p_stocks" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_import_stock_from_spot"("p_stocks" "jsonb") IS 'Importa estoque da API SPOT. 
Parâmetro: Array JSONB do endpoint /stocks.
Atualiza quantity, previsões (next_quantity_1..3, next_date_1..3), timestamps.
Retorna estatísticas de processamento.';



CREATE OR REPLACE FUNCTION "public"."fn_import_stock_xbz"("p_parent_reference" "text" DEFAULT NULL::"text") RETURNS TABLE("vss_atualizadas" integer, "bronze_fechadas" integer, "produtos_rollup" integer, "bronze_sem_vss" integer, "details" "jsonb")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_supplier_id uuid;
  v_updated int := 0; v_closed int := 0; v_rollup int := 0; v_skipped int := 0;
  v_pv_updated int := 0;
BEGIN
  SELECT id INTO v_supplier_id FROM public.suppliers WHERE code='XBZ' LIMIT 1;
  IF v_supplier_id IS NULL THEN RAISE EXCEPTION 'Fornecedor XBZ nao encontrado'; END IF;

  -- PASSO 1: Bronze → VSS (stock + next_date_1 com sentinela filtrada)
  WITH src AS (
    SELECT spr.supplier_sku,
           GREATEST(COALESCE(NULLIF(spr.stock_data->>'Quantity','')::int,0),0) AS q,
           NULLIF(NULLIF(LEFT(COALESCE(spr.stock_data->>'NextDate1',''),10),'0001-01-01'),'')::date AS nd1
    FROM public.supplier_products_raw spr
    WHERE spr.supplier_id=v_supplier_id AND spr.stock_data ? 'Quantity'
      AND (p_parent_reference IS NULL OR spr.supplier_reference=p_parent_reference)
  ),
  upd AS (
    UPDATE public.variant_supplier_sources vss
       SET quantity=src.q, stock_main_warehouse=src.q, stock_other_warehouses=0,
           next_date_1     = CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss.next_quantity_1,0)>0
                                  THEN src.nd1 ELSE NULL END,
           next_quantity_1 = CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss.next_quantity_1,0)>0
                                  THEN vss.next_quantity_1 ELSE NULL END,
           last_synced_at=now(), sync_status='synced',
           sync_error=NULL, source='xbz_api', updated_at=now()
    FROM src
    WHERE vss.supplier_id=v_supplier_id AND vss.supplier_sku=src.supplier_sku
      AND (
        vss.quantity IS DISTINCT FROM src.q
        OR vss.next_date_1 IS DISTINCT FROM
           CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss.next_quantity_1,0)>0
                THEN src.nd1 ELSE NULL END
        OR (src.nd1 IS NULL AND COALESCE(vss.next_quantity_1, 0) > 0)
        OR (src.nd1 IS NOT NULL AND COALESCE(vss.next_quantity_1,0)=0 AND vss.next_date_1 IS NOT NULL)
      )
    RETURNING vss.id
  )
  SELECT count(*) INTO v_updated FROM upd;

  -- PASSO 2: VSS → product_variants
  PERFORM set_config('app.bulk_import_mode', 'true', true);
  WITH src AS (
    SELECT spr.supplier_sku,
           GREATEST(COALESCE(NULLIF(spr.stock_data->>'Quantity','')::int,0),0) AS q,
           NULLIF(NULLIF(LEFT(COALESCE(spr.stock_data->>'NextDate1',''),10),'0001-01-01'),'')::date AS nd1
    FROM public.supplier_products_raw spr
    WHERE spr.supplier_id=v_supplier_id AND spr.stock_data ? 'Quantity'
      AND (p_parent_reference IS NULL OR spr.supplier_reference=p_parent_reference)
  )
  UPDATE public.product_variants pv
  SET stock_quantity  = src.q,
      next_date_1     = CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss2.next_quantity_1,0)>0
                             THEN src.nd1 ELSE NULL END,
      next_quantity_1 = CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss2.next_quantity_1,0)>0
                             THEN vss2.next_quantity_1 ELSE NULL END,
      last_sync_at    = now()
  FROM src
  JOIN public.variant_supplier_sources vss2
    ON vss2.supplier_sku = src.supplier_sku
   AND vss2.supplier_id  = v_supplier_id
   AND vss2.is_active    = true
  WHERE pv.supplier_sku = src.supplier_sku
    AND pv.is_active    = true
    AND (
      pv.stock_quantity IS DISTINCT FROM src.q
      OR pv.next_date_1 IS DISTINCT FROM
         CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss2.next_quantity_1,0)>0
              THEN src.nd1 ELSE NULL END
      OR pv.next_quantity_1 IS DISTINCT FROM
         CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss2.next_quantity_1,0)>0
              THEN vss2.next_quantity_1 ELSE NULL END
    );
  GET DIAGNOSTICS v_pv_updated = ROW_COUNT;

  -- PASSO 3: Fechar Bronze processados
  WITH closed AS (
    UPDATE public.supplier_products_raw spr
       SET stock_status='processed', stock_synced_at=now()
    WHERE spr.supplier_id=v_supplier_id AND spr.stock_data ? 'Quantity'
      AND (p_parent_reference IS NULL OR spr.supplier_reference=p_parent_reference)
      AND spr.stock_status IS DISTINCT FROM 'processed'
      AND EXISTS (SELECT 1 FROM public.variant_supplier_sources vss
                  WHERE vss.supplier_id=v_supplier_id AND vss.supplier_sku=spr.supplier_sku)
    RETURNING spr.id
  )
  SELECT count(*) INTO v_closed FROM closed;

  -- PASSO 4: Rollup produto-pai
  WITH agg AS (
    SELECT p2.id, COALESCE(SUM(pv.stock_quantity),0) AS sum_v
    FROM public.products p2
    LEFT JOIN public.product_variants pv ON pv.product_id=p2.id AND pv.is_active=true
    WHERE p2.supplier_id=v_supplier_id
      AND (p_parent_reference IS NULL OR p2.supplier_reference=p_parent_reference)
    GROUP BY p2.id
  ),
  rollup AS (
    UPDATE public.products p
       SET stock_quantity=agg.sum_v, is_stockout=(agg.sum_v<=0),
           last_stock_update_at=now(), price_verified_at=now(),
           -- FIX M3 2026-06-26 (fix_version=price_freshness_honest_v1):
           -- carimbar TAMBÉM price_last_verified_at (lido por v_product_active_badge).
           -- O rollup roda a cada <=12h por produto e reconfirma os dados do
           -- fornecedor; sem este carimbo, produtos de preço ESTÁVEL (>60d sem
           -- mudança) apareciam como is_price_stale=true (falso-positivo).
           -- ANTI-REGRESSAO: NAO remover esta linha — mantém o badge de frescor honesto.
           price_last_verified_at=now()
    FROM agg WHERE p.id=agg.id
      AND (p.stock_quantity IS DISTINCT FROM agg.sum_v
        OR p.is_stockout IS DISTINCT FROM (agg.sum_v<=0)
        OR p.price_verified_at IS NULL
        OR p.price_verified_at < now() - INTERVAL '12 hours')
    RETURNING p.id
  )
  SELECT count(*) INTO v_rollup FROM rollup;

  SELECT count(*) INTO v_skipped
  FROM public.supplier_products_raw spr
  WHERE spr.supplier_id=v_supplier_id AND spr.stock_data ? 'Quantity'
    AND (p_parent_reference IS NULL OR spr.supplier_reference=p_parent_reference)
    AND NOT EXISTS (SELECT 1 FROM public.variant_supplier_sources vss
                    WHERE vss.supplier_id=v_supplier_id AND vss.supplier_sku=spr.supplier_sku);

  -- HEARTBEAT FIX 2026-06-22: Atualiza last_full_sync_at SEMPRE (independente de mudanças)
  -- Permite que v_system_alerts detecte corretamente se o sync está rodando
  UPDATE public.suppliers
    SET last_full_sync_at = now(), last_sync_status = 'completed'
  WHERE id = v_supplier_id;

  RETURN QUERY SELECT v_updated, v_closed, v_rollup, v_skipped,
    jsonb_build_object(
      'supplier_id', v_supplier_id,
      'scope', COALESCE(p_parent_reference,'ALL'),
      'pv_updated', v_pv_updated,
      'fixes', jsonb_build_array(
        'nd1_null_clears_nq1_residual',
        'pv_is_active_guard',
        'nd1_only_when_nq1_positive',
        'heartbeat_last_full_sync_at',
        'price_last_verified_at_honest_v1'  -- NOVO: badge de frescor honesto (M3)
      )
    );
END;
$$;


