COMMENT ON FUNCTION "public"."fn_import_stock_xbz"("p_parent_reference" "text") IS 'CANONICO 2026-06-06 (Fase 8): fast-path de estoque XBZ. Le supplier_products_raw.stock_data e atualiza variant_supplier_sources (fonte-da-verdade de estoque, ADR 0007) + rollup em products. NAO e violacao Bronze->Gold (escreve na camada de sourcing canonica). Cron xbz-stock-sync */15.';



CREATE OR REPLACE FUNCTION "public"."fn_import_xbz_image"("p_product_id" "uuid", "p_cloudflare_id" "text", "p_url_original" "text", "p_filename" "text" DEFAULT NULL::"text", "p_width" integer DEFAULT NULL::integer, "p_height" integer DEFAULT NULL::integer, "p_file_size" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_new_id UUID;
    v_cf_url TEXT;
    v_fn TEXT;
BEGIN
    v_cf_url := 'https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/' || p_cloudflare_id || '/public';
    v_fn := COALESCE(p_filename, REVERSE(SPLIT_PART(REVERSE(p_url_original), '/', 1)));
    
    INSERT INTO product_images (
        id, product_id,
        image_type, image_type_id,
        cloudflare_image_id, url_cdn, url_original,
        filename, format,
        width_px, height_px, file_size_bytes,
        is_primary, is_active, is_og_image,
        applies_to_color, display_order,
        source_supplier, supplier_code,
        organization_id,
        created_at, updated_at
    ) VALUES (
        gen_random_uuid(), p_product_id,
        'main', '7ea182ff-edcc-4c4c-b7a1-443b07500f6c',
        p_cloudflare_id, v_cf_url, p_url_original,
        v_fn, 'jpg',
        p_width, p_height, p_file_size,
        true, true, true,
        true, 1,
        'XBZ', 'XBZ',
        '5db5aee1-064b-4ef4-9193-345dcd8274ea',
        NOW(), NOW()
    )
    ON CONFLICT (cloudflare_image_id) WHERE cloudflare_image_id IS NOT NULL
    DO NOTHING
    RETURNING id INTO v_new_id;
    
    IF v_new_id IS NULL THEN
        RAISE WARNING 'Imagem XBZ já existe (duplicata): %', v_fn;
    END IF;
    
    RETURN v_new_id;
END;
$$;


ALTER FUNCTION "public"."fn_import_xbz_image"("p_product_id" "uuid", "p_cloudflare_id" "text", "p_url_original" "text", "p_filename" "text", "p_width" integer, "p_height" integer, "p_file_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_index_usage_report"() RETURNS TABLE("tabela" "text", "indice" "text", "tamanho" "text", "scans" bigint, "tipo" "text", "recomendacao" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT 
    (s.schemaname || '.' || s.relname)::text AS tabela,
    s.indexrelname::text AS indice,
    pg_size_pretty(pg_relation_size(s.indexrelid))::text AS tamanho,
    s.idx_scan AS scans,
    CASE 
      WHEN s.indexrelname LIKE '%_pkey' THEN 'PRIMARY KEY'
      WHEN s.indexrelname LIKE 'uq_%' THEN 'UNIQUE'
      WHEN s.indexrelname LIKE '%_brin' THEN 'BRIN'
      WHEN s.indexrelname LIKE 'idx_%_gin' THEN 'GIN'
      WHEN s.indexrelname LIKE 'idx_%_fkey%' OR s.indexrelname LIKE '%_fk_idx' THEN 'FK support'
      ELSE 'BTREE'
    END::text AS tipo,
    CASE 
      WHEN s.indexrelname LIKE '%_pkey' THEN 'MANTER (PK)'
      WHEN s.indexrelname LIKE 'uq_%' THEN 'MANTER (UNIQUE)'
      WHEN s.idx_scan = 0 AND pg_relation_size(s.indexrelid) > 1024*1024 
        THEN 'AVALIAR: sem uso e >1MB (mas verifique FK)'
      WHEN s.idx_scan = 0 THEN 'AVALIAR: sem uso'
      WHEN s.idx_scan < 10 THEN 'OK (uso baixo)'
      ELSE 'OK (usado)'
    END::text AS recomendacao
  FROM pg_stat_user_indexes s
  WHERE s.schemaname = 'public'
  ORDER BY pg_relation_size(s.indexrelid) DESC, s.idx_scan DESC;
$$;


ALTER FUNCTION "public"."fn_index_usage_report"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_index_usage_report"() IS 'Relatório de uso de índices. NUNCA dropar automaticamente — avaliar cada caso.';



CREATE OR REPLACE FUNCTION "public"."fn_infer_packaging_config_type"("p_product_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN p.shape_type = 'cylindrical' THEN 'bottles'
    WHEN p.category_name ~* 'vidro|cerâmic|ceramic|porcelan|cristal|louça'
      OR (COALESCE(p.materials::text,'')||COALESCE(p.auto_material,'')) ~* 'vidro|cerâmic|ceramic|porcelan|cristal' THEN 'fragile'
    WHEN p.category_name ~* 'eletrôni|eletroni|relógio|relogio|smartwatch|power\s*bank|powerbank|fone|speaker|caixa de som|wireless|bluetooth' THEN 'precision'
    ELSE 'default'
  END
  FROM products p WHERE p.id = p_product_id;
$$;


