CREATE OR REPLACE FUNCTION "public"."fn_ingest_asia_api_batch"("p_produtos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_supplier_id  uuid    := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_batch_id     uuid    := gen_random_uuid();
  v_inseridos    int     := 0;
  v_atualizados  int     := 0;
  v_sem_mudanca  int     := 0;
  v_erros        int     := 0;
  v_produto      jsonb;
  v_referencia   text;
  v_hash         text;
  v_hash_atual   text;
BEGIN
  -- Cria batch de importação
  INSERT INTO supplier_import_batches (id, supplier_id, status, started_at, notes)
  VALUES (v_batch_id, v_supplier_id, 'running', now(), 'API oficial api.asiaimport.com.br — listarProdutos2');

  -- Itera sobre cada produto-pai
  FOR v_produto IN SELECT * FROM jsonb_array_elements(p_produtos)
  LOOP
    BEGIN
      v_referencia := v_produto->>'referencia';

      -- Valida referência
      IF v_referencia IS NULL OR v_referencia = '' THEN
        v_erros := v_erros + 1;
        CONTINUE;
      END IF;

      -- Calcula hash usando SHA-256 (igual à coluna GENERATED)
      v_hash := encode(extensions.digest(v_produto::text, 'sha256'), 'hex');

      -- Verifica se existe e qual o hash atual (gerado pela coluna GENERATED)
      SELECT content_hash INTO v_hash_atual
      FROM supplier_products_raw
      WHERE supplier_id = v_supplier_id
        AND supplier_sku = v_referencia;

      IF NOT FOUND THEN
        -- Novo produto — content_hash é GENERATED (não incluir na INSERT)
        INSERT INTO supplier_products_raw (
          supplier_id,
          supplier_sku,
          supplier_reference,
          raw_data,
          status,
          source_channel,
          import_batch_id,
          imported_at,
          updated_at
        ) VALUES (
          v_supplier_id,
          v_referencia,
          v_referencia,
          v_produto,
          'pending',
          'api_oficial',
          v_batch_id,
          now(),
          now()
        );
        v_inseridos := v_inseridos + 1;

      ELSIF v_hash_atual IS DISTINCT FROM v_hash THEN
        -- Produto mudou — content_hash é GENERATED (não incluir no UPDATE)
        UPDATE supplier_products_raw SET
          raw_data        = v_produto,
          status          = 'pending',
          source_channel  = 'api_oficial',
          import_batch_id = v_batch_id,
          updated_at      = now()
        WHERE supplier_id = v_supplier_id
          AND supplier_sku = v_referencia;
        v_atualizados := v_atualizados + 1;

      ELSE
        -- Produto idêntico — sem alteração
        v_sem_mudanca := v_sem_mudanca + 1;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      -- Continua processando os demais
    END;
  END LOOP;

  -- Finaliza batch
  UPDATE supplier_import_batches SET
    status            = CASE WHEN v_erros = 0 THEN 'ok' ELSE 'ok_com_erros' END,
    finished_at       = now(),
    products_imported = v_inseridos,
    products_updated  = v_atualizados,
    notes             = notes || format(' | inseridos=%s atualizados=%s sem_mudanca=%s erros=%s',
                          v_inseridos, v_atualizados, v_sem_mudanca, v_erros)
  WHERE id = v_batch_id;

  RETURN jsonb_build_object(
    'batch_id',     v_batch_id,
    'inseridos',    v_inseridos,
    'atualizados',  v_atualizados,
    'sem_mudanca',  v_sem_mudanca,
    'erros',        v_erros,
    'total',        v_inseridos + v_atualizados + v_sem_mudanca + v_erros
  );
END;
$$;


ALTER FUNCTION "public"."fn_ingest_asia_api_batch"("p_produtos" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_ingest_asia_api_batch"("p_produtos" "jsonb") IS 'UPSERT de produtos-pai da API oficial Asia Import (api.asiaimport.com.br / listarProdutos2).
   Grain: 1 linha por produto-pai (supplier_sku = referencia pai, ex: MC511P).
   Hash guard: só atualiza Bronze e re-dispara status=pending se conteúdo mudou.';



CREATE OR REPLACE FUNCTION "public"."fn_ingest_asia_hg_batch"("p_produtos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier_id     uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_atualizados     int  := 0;
  v_nao_encontrados int  := 0;
  v_erros           int  := 0;
  v_row_count       int;
  v_produto         jsonb;
  v_sku             text;
  v_f3_patch        jsonb;
  v_hash_novo       text;
  v_sqf             int;
  v_sp              boolean;
  v_asp             boolean;
BEGIN
  FOR v_produto IN SELECT * FROM jsonb_array_elements(p_produtos)
  LOOP
    BEGIN
      v_sku := trim(v_produto->>'sku');
      IF v_sku IS NULL OR v_sku = '' THEN CONTINUE; END IF;

      v_sqf := NULLIF(NULLIF(trim(COALESCE(v_produto->>'stock_quantity_future','')), ''), 'null')::numeric::int;
      v_sp  := CASE WHEN (v_produto->>'susceptible_product') IN ('true','false')
                    THEN (v_produto->>'susceptible_product')::boolean
                    ELSE NULL END;
      v_asp := CASE WHEN (v_produto->>'active_stock_sp') IN ('true','false')
                    THEN (v_produto->>'active_stock_sp')::boolean
                    ELSE NULL END;

      v_f3_patch := jsonb_build_object(
        '_f3_fonte',              'hg_products_publico',
        '_f3_updated_at',         to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSZ'),
        'hg_id',                  v_produto->>'id',
        'susceptible_product',    v_sp,
        'active_stock_sp',        v_asp,
        'stock_quantity_future',  v_sqf,
        'characteristics_image',  COALESCE(v_produto->'characteristics_images'->'featured_image', 'null'::jsonb),
        'video_embed_urls', COALESCE(
          (SELECT jsonb_agg(emb)
           FROM jsonb_array_elements(COALESCE(v_produto->'video_product','[]'::jsonb)) vp,
                jsonb_array_elements(COALESCE(vp->'embedUrl','[]'::jsonb)) emb),
          '[]'::jsonb
        ),
        'tags_styled',    COALESCE(v_produto->'tags',       '[]'::jsonb),
        'variations_hg',  COALESCE(v_produto->'variations', '[]'::jsonb)
      );

      v_hash_novo := md5(v_f3_patch::text);

      WITH rows_to_update AS (
        SELECT id, site_data->>'_f3_hash' as hash_atual
        FROM supplier_products_raw
        WHERE supplier_id = v_supplier_id
          AND (
            supplier_sku = v_sku
            OR supplier_sku = v_sku || 'P'
            OR supplier_sku LIKE v_sku || '-%'
            OR raw_data->>'referencia' = v_sku
            OR (raw_data->>'referencia' IS NOT NULL
                AND raw_data->>'referencia' != ''
                AND v_sku LIKE (raw_data->>'referencia') || '%')
          )
      )
      UPDATE supplier_products_raw spr SET
        site_data  = COALESCE(site_data, '{}'::jsonb)
                     || v_f3_patch
                     || jsonb_build_object('_f3_hash', v_hash_novo),
        updated_at = now()
      FROM rows_to_update rtu
      WHERE spr.id = rtu.id
        AND (rtu.hash_atual IS DISTINCT FROM v_hash_novo);

      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      v_atualizados := v_atualizados + v_row_count;

      IF NOT EXISTS (
        SELECT 1 FROM supplier_products_raw
        WHERE supplier_id = v_supplier_id
          AND (
            supplier_sku = v_sku
            OR supplier_sku = v_sku || 'P'
            OR supplier_sku LIKE v_sku || '-%'
            OR raw_data->>'referencia' = v_sku
            OR (raw_data->>'referencia' IS NOT NULL
                AND raw_data->>'referencia' != ''
                AND v_sku LIKE (raw_data->>'referencia') || '%')
          )
      ) THEN
        v_nao_encontrados := v_nao_encontrados + 1;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'atualizados',     v_atualizados,
    'nao_encontrados', v_nao_encontrados,
    'erros',           v_erros,
    'total_input',     jsonb_array_length(p_produtos)
  );
END;
$$;


