CREATE OR REPLACE FUNCTION "public"."fn_ingest_asia_hg_debug_sample"("p_produtos" "jsonb", "p_max_erros" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier_id uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_produto     jsonb;
  v_sku         text;
  v_erros       jsonb := '[]'::jsonb;
  v_sqf         int;
  v_patch       jsonb;
  v_ok          int := 0;
BEGIN
  FOR v_produto IN SELECT * FROM jsonb_array_elements(p_produtos)
  LOOP
    BEGIN
      v_sku := trim(v_produto->>'sku');
      IF v_sku IS NULL OR v_sku = '' THEN CONTINUE; END IF;
      
      v_sqf := NULLIF(NULLIF(trim(COALESCE(v_produto->>'stock_quantity_future','')), ''), 'null')::int;

      v_patch := jsonb_build_object(
        '_f3_fonte',              'hg_products_publico',
        '_f3_updated_at',         to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSZ'),
        'hg_id',                  v_produto->>'id',
        'susceptible_product',    CASE WHEN (v_produto->>'susceptible_product') IN ('true','false') THEN (v_produto->>'susceptible_product')::boolean ELSE NULL END,
        'active_stock_sp',        CASE WHEN (v_produto->>'active_stock_sp') IN ('true','false') THEN (v_produto->>'active_stock_sp')::boolean ELSE NULL END,
        'stock_quantity_future',  v_sqf,
        'characteristics_image',  COALESCE(v_produto->'characteristics_images'->'featured_image', 'null'::jsonb),
        'video_embed_urls', COALESCE(
          (SELECT jsonb_agg(emb)
           FROM jsonb_array_elements(COALESCE(v_produto->'video_product','[]'::jsonb)) vp,
                jsonb_array_elements(COALESCE(vp->'embedUrl','[]'::jsonb)) emb),
          '[]'::jsonb
        ),
        'tags_styled',    COALESCE(v_produto->'tags',       '[]'::jsonb),
        'variations_hg',  COALESCE(v_produto->'variations', '[]'::jsonb)
      );
      
      -- Tenta o UPDATE sem capturar erro
      UPDATE supplier_products_raw SET
        site_data  = COALESCE(site_data, '{}'::jsonb) || v_patch,
        updated_at = now()
      WHERE supplier_id = v_supplier_id
        AND (
          supplier_sku = v_sku OR supplier_sku = v_sku || 'P'
          OR supplier_sku LIKE v_sku || '-%'
          OR raw_data->>'referencia' = v_sku
          OR (raw_data->>'referencia' IS NOT NULL AND raw_data->>'referencia' != ''
              AND v_sku LIKE (raw_data->>'referencia') || '%')
        );
      v_ok := v_ok + 1;

    EXCEPTION WHEN OTHERS THEN
      IF jsonb_array_length(v_erros) < p_max_erros THEN
        v_erros := v_erros || jsonb_build_object(
          'sku', v_sku,
          'erro', SQLERRM,
          'estado', SQLSTATE,
          'sqf_raw', v_produto->>'stock_quantity_future',
          'sp_raw', v_produto->>'susceptible_product'
        );
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('ok', v_ok, 'erros', v_erros);
END;
$$;


ALTER FUNCTION "public"."fn_ingest_asia_hg_debug_sample"("p_produtos" "jsonb", "p_max_erros" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ingest_asia_page"("p_produtos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_prod jsonb; v_n int := 0; v_vars int := 0; v_r jsonb;
BEGIN
  IF jsonb_typeof(p_produtos) <> 'array' THEN
    RETURN jsonb_build_object('success', false, 'error', 'esperado_array_de_produtos');
  END IF;
  FOR v_prod IN SELECT * FROM jsonb_array_elements(p_produtos) LOOP
    v_r := public.fn_ingest_asia_product(v_prod);
    IF (v_r->>'success')::bool THEN
      v_n := v_n + 1;
      v_vars := v_vars + COALESCE((v_r->>'variacoes')::int, 0);
    END IF;
  END LOOP;
  RETURN jsonb_build_object('success', true, 'produtos', v_n, 'variacoes', v_vars);
END;
$$;


ALTER FUNCTION "public"."fn_ingest_asia_page"("p_produtos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ingest_asia_product"("p_prod" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_ASIA    uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_parent  text := p_prod->>'referencia';
  v_var     jsonb;
  v_var_ref text;
  v_content jsonb;
  v_stock   jsonb;
  v_props   jsonb;
  v_chash   text;
  v_shash   text;
  v_vars    int := 0;
BEGIN
  IF v_parent IS NULL OR jsonb_typeof(p_prod->'variacoes') <> 'array' THEN
    RETURN jsonb_build_object('success', false, 'error', 'payload_invalido', 'parent', v_parent);
  END IF;

  -- Normaliza propriedades: OBJETO ou ARRAY de {slug, valor/value}
  IF jsonb_typeof(p_prod->'propriedades') = 'array' THEN
    SELECT COALESCE(jsonb_object_agg(slug, valor), '{}'::jsonb) INTO v_props
    FROM (
      SELECT DISTINCT ON (e->>'slug')
             e->>'slug' AS slug,
             COALESCE(e->>'valor', e->>'value') AS valor
      FROM jsonb_array_elements(p_prod->'propriedades') WITH ORDINALITY AS x(e, ord)
      WHERE NULLIF(e->>'slug', '') IS NOT NULL
      ORDER BY e->>'slug', ord
    ) d;
  ELSIF jsonb_typeof(p_prod->'propriedades') = 'object' THEN
    v_props := p_prod->'propriedades';
  ELSE
    v_props := '{}'::jsonb;
  END IF;

  FOR v_var IN SELECT * FROM jsonb_array_elements(p_prod->'variacoes')
  LOOP
    -- Canal 1 NOVO (asia.ajung.site): variações têm 'sku' (ex: CAD005-AZ)
    -- Canal 1 LEGADO: variações tinham 'referencia'
    v_var_ref := COALESCE(
      NULLIF(TRIM(v_var->>'sku'),        ''),
      NULLIF(TRIM(v_var->>'referencia'), '')
    );
    CONTINUE WHEN v_var_ref IS NULL;
    v_vars := v_vars + 1;

    v_content := jsonb_strip_nulls(jsonb_build_object(
      'referencia',          v_parent,
      'var_referencia',      v_var_ref,
      'nome',                p_prod->>'nome',
      'descricao',           p_prod->>'descricao',
      'preco',               v_var->>'preco',
      'imagem',              COALESCE(v_var->>'imagem', p_prod->>'imagem'),
      'galeria',             COALESCE(p_prod->'galeria', '[]'::jsonb),
      'video',               p_prod->>'video',
      'ncm',                 COALESCE(v_var->>'ncm', v_props->>'ncm', p_prod->>'ncm'),
      -- Dimensões: novo API usa objeto 'dimensoes_cm', legado usava campos soltos
      'altura',              COALESCE(p_prod->'dimensoes_cm'->>'altura',      p_prod->>'altura'),
      'largura',             COALESCE(p_prod->'dimensoes_cm'->>'largura',     p_prod->>'largura'),
      'comprimento',         COALESCE(p_prod->'dimensoes_cm'->>'comprimento', p_prod->>'comprimento'),
      -- Peso: novo API usa 'peso_kg', legado usava 'peso'
      'peso',                COALESCE(p_prod->>'peso_kg', p_prod->>'peso'),
      'status',              p_prod->>'status',
      'promocao',            p_prod->>'promocao',
      'origem_faturamento',  p_prod->>'origem_faturamento',
      'propriedades',        v_props,
      'categorias',          COALESCE(p_prod->'categorias', '{}'::jsonb),
      'tags',                COALESCE(p_prod->'tags',       '{}'::jsonb),
      'embalagem',           COALESCE(p_prod->'embalagem',  '{}'::jsonb),
      'atributos',           COALESCE(v_var->'atributos',   '{}'::jsonb),
      'var_cor_nome',        COALESCE(
                               v_var->'atributos'->'cor'->>'value',
                               v_var->'atributos'->'cor'->>'valor',
                               v_var->>'cor'
                             ),
      'var_cor_hex',         COALESCE(
                               v_var->'atributos'->'cor'->>'hexadecimal',
                               v_var->'atributos'->'cor'->>'hex',
                               v_var->>'cor_hex'
                             ),
      'var_capacidade',      v_var->>'capacidade',
      'var_volume',          v_var->>'volume'
    ));

    v_stock := jsonb_build_object(
      'qtd_estoque',       COALESCE(public.fn_safe_int(v_var->>'qtd_estoque'),       0),
      'qtd_estoque_em_sp', COALESCE(public.fn_safe_int(v_var->>'qtd_estoque_em_sp'), 0),
      'previsao_entrega',  COALESCE(v_var->'previsao_entrega', '[]'::jsonb)
    );

    -- content_hash é GENERATED COLUMN — NÃO inserir, o Postgres calcula automaticamente
    v_chash := encode(digest(v_content::text, 'sha256'), 'hex');
    v_shash := encode(digest(v_stock::text,   'sha256'), 'hex');

    INSERT INTO public.supplier_products_raw AS spr (
      supplier_id, supplier_reference, supplier_sku,
      raw_data,
      stock_data, stock_hash, stock_status, stock_synced_at,
      source_channel, source_endpoint,
      status, images_status
    ) VALUES (
      v_ASIA, v_var_ref, v_var_ref,
      v_content,
      v_stock, v_shash, 'pending'::supplier_raw_status, now(),
      'n8n_workflow', 'asia.ajung.site/api/products',
      'pending'::supplier_raw_status, 'pending'::supplier_raw_status
    )
    ON CONFLICT (supplier_id, supplier_sku) DO UPDATE SET
      raw_data           = EXCLUDED.raw_data,
      supplier_reference = EXCLUDED.supplier_reference,
      -- content_hash é GENERATED: atualiza automaticamente quando raw_data muda
      -- Status: pending só se conteúdo mudou (compara hash atual com novo esperado)
      status             = CASE WHEN spr.content_hash IS DISTINCT FROM v_chash
                                THEN 'pending'::supplier_raw_status
                                ELSE spr.status
                           END,
      stock_data         = EXCLUDED.stock_data,
      stock_hash         = EXCLUDED.stock_hash,
      stock_status       = CASE WHEN spr.stock_hash IS DISTINCT FROM EXCLUDED.stock_hash
                                THEN 'pending'::supplier_raw_status
                                ELSE spr.stock_status
                           END,
      stock_synced_at    = now(),
      source_channel     = EXCLUDED.source_channel,
      source_endpoint    = EXCLUDED.source_endpoint,
      updated_at         = now();
  END LOOP;

  RETURN jsonb_build_object('success', true, 'parent', v_parent, 'variacoes', v_vars);
END;
$$;


ALTER FUNCTION "public"."fn_ingest_asia_product"("p_prod" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ingest_bronze_batch"("p_supplier_code" "text", "p_feed" "text", "p_run_id" "uuid", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sid uuid := public.fn_resolve_supplier(p_supplier_code);
  v_item jsonb; v_ref text; v_tco text;
  v_fetched int := 0; v_upserted int := 0; v_skipped int := 0; v_errors int := 0;
  v_errsamples jsonb := '[]'::jsonb;
begin
  if p_feed not in ('products','stock','customization') then raise exception 'feed invalido: %', p_feed; end if;
  if jsonb_typeof(p_items) <> 'array' then raise exception 'p_items deve ser array jsonb'; end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_fetched := v_fetched + 1;
    begin
      if p_feed in ('products','stock') then
        v_ref := coalesce(nullif(v_item->>'Sku',''), nullif(v_item->>'sku',''),
                          nullif(v_item->>'supplier_reference',''), nullif(v_item->>'referencia',''),
                          nullif(v_item->>'ProdReference',''), nullif(v_item->>'codigo',''));
        if v_ref is null then
          v_skipped := v_skipped + 1;
          if jsonb_array_length(v_errsamples) < 20 then
            v_errsamples := v_errsamples || jsonb_build_object('motivo','sem_chave_natural','item',v_item);
          end if;
          continue;
        end if;
        if p_feed = 'products'
          then perform public.insert_supplier_product_raw(v_sid, v_ref, v_item, p_run_id);
          else perform public.upsert_supplier_stock_raw  (v_sid, v_ref, v_item, p_run_id);
        end if;
        v_upserted := v_upserted + 1;
      else  -- customization
        v_tco := coalesce(nullif(v_item->>'TableCodeOption',''), nullif(v_item->>'table_code_option',''));
        if v_tco is null then
          v_skipped := v_skipped + 1;
          if jsonb_array_length(v_errsamples) < 20 then
            v_errsamples := v_errsamples || jsonb_build_object('motivo','sem_table_code_option','item',v_item);
          end if;
          continue;
        end if;
        perform public.upsert_supplier_customization_raw(
          v_sid, v_tco, v_item,
          nullif(v_item->>'TableCode',''),
          coalesce(nullif(v_item->>'CustomizationTypeName',''), nullif(v_item->>'customization_type','')),
          p_run_id);
        v_upserted := v_upserted + 1;
      end if;
    exception when others then
      v_errors := v_errors + 1;
      if jsonb_array_length(v_errsamples) < 20 then
        v_errsamples := v_errsamples || jsonb_build_object('erro',SQLERRM,'sqlstate',SQLSTATE,'ref',coalesce(v_ref,v_tco));
      end if;
    end;
  end loop;

  return jsonb_build_object('supplier_code',p_supplier_code,'feed',p_feed,'run_id',p_run_id,
    'fetched',v_fetched,'upserted',v_upserted,'skipped',v_skipped,'errors',v_errors,
    'error_samples',v_errsamples);
end $$;


ALTER FUNCTION "public"."fn_ingest_bronze_batch"("p_supplier_code" "text", "p_feed" "text", "p_run_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ingest_colors_batch"("p_supplier_code" "text", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sid          uuid := public.fn_resolve_supplier(p_supplier_code);
  v_org_id       uuid;
  v_item         jsonb;
  v_color_code   text;
  v_description  text;
  v_hex          text;
  v_fetched      int := 0;
  v_upserted     int := 0;
  v_skipped      int := 0;
  v_errors       int := 0;
  v_errsamples   jsonb := '[]'::jsonb;
BEGIN
  -- Obter organization_id do fornecedor
  SELECT organization_id INTO v_org_id
  FROM public.suppliers
  WHERE id = v_sid
  LIMIT 1;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'organization_id não encontrado para supplier %', p_supplier_code;
  END IF;

  IF jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'p_items deve ser array jsonb';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_fetched := v_fetched + 1;
    BEGIN
      -- Extrair campos do payload SPOT Colors
      v_color_code  := NULLIF(TRIM(COALESCE(v_item->>'ColorCode', v_item->>'color_code', v_item->>'code')), '');
      v_description := NULLIF(TRIM(COALESCE(v_item->>'Description', v_item->>'description', v_item->>'name')), '');
      v_hex         := NULLIF(TRIM(COALESCE(v_item->>'ColorHex', v_item->>'hex', v_item->>'HexCode')), '');

      IF v_color_code IS NULL OR v_description IS NULL THEN
        v_skipped := v_skipped + 1;
        IF jsonb_array_length(v_errsamples) < 10 THEN
          v_errsamples := v_errsamples || jsonb_build_object('motivo','sem_chave','item',v_item);
        END IF;
        CONTINUE;
      END IF;

      INSERT INTO public.supplier_colors (
        id, supplier_id, organization_id,
        api_color_id, code, name, hex_code,
        source, is_active, is_available,
        api_description, api_raw_data,
        created_at, updated_at
      ) VALUES (
        gen_random_uuid(), v_sid, v_org_id,
        v_color_code, v_color_code, v_description, v_hex,
        'api_spot', true, true,
        v_description, v_item,
        now(), now()
      )
      ON CONFLICT (organization_id, supplier_id, name)
      DO UPDATE SET
        api_color_id    = EXCLUDED.api_color_id,
        code            = EXCLUDED.code,
        hex_code        = COALESCE(EXCLUDED.hex_code, supplier_colors.hex_code),
        api_description = EXCLUDED.api_description,
        api_raw_data    = EXCLUDED.api_raw_data,
        is_active       = true,
        updated_at      = now();

      v_upserted := v_upserted + 1;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      IF jsonb_array_length(v_errsamples) < 10 THEN
        v_errsamples := v_errsamples || jsonb_build_object(
          'erro', SQLERRM, 'sqlstate', SQLSTATE, 'code', v_color_code
        );
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'supplier_code', p_supplier_code,
    'feed', 'colors',
    'fetched',   v_fetched,
    'upserted',  v_upserted,
    'skipped',   v_skipped,
    'errors',    v_errors,
    'error_samples', v_errsamples
  );
END;
$$;


ALTER FUNCTION "public"."fn_ingest_colors_batch"("p_supplier_code" "text", "p_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_ingest_colors_batch"("p_supplier_code" "text", "p_items" "jsonb") IS 'Ingere feed Colors do SPOT (ColorCode+Description+hex) em supplier_colors via upsert idempotente';



CREATE OR REPLACE FUNCTION "public"."fn_ingest_customization_options_batch"("p_supplier_code" "text", "p_run_id" "uuid", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_sid        uuid := public.fn_resolve_supplier(p_supplier_code);
  v_item       jsonb;
  v_ref        text;
  v_service    text;
  v_table      text;
  v_component  text;
  v_location   text;
  v_hotspot    text;
  v_fetched    int := 0;
  v_upserted   int := 0;
  v_skipped    int := 0;
  v_errors     int := 0;
  v_errsamples jsonb := '[]'::jsonb;
BEGIN
  IF jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'p_items deve ser array jsonb';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_fetched := v_fetched + 1;
    BEGIN
      v_ref := NULLIF(TRIM(COALESCE(
                 v_item->>'ProdReference', v_item->>'prodReference',
                 v_item->>'product_reference', v_item->>'Reference')), '');

      IF v_ref IS NULL THEN
        v_skipped := v_skipped + 1;
        IF jsonb_array_length(v_errsamples) < 15 THEN
          v_errsamples := v_errsamples || jsonb_build_object('motivo','sem_prod_reference','item',v_item);
        END IF;
        CONTINUE;
      END IF;

      v_service   := COALESCE(NULLIF(TRIM(COALESCE(v_item->>'ServiceCode', v_item->>'serviceCode')), ''), '');
      v_table     := COALESCE(NULLIF(TRIM(COALESCE(v_item->>'TableCode', v_item->>'tableCode')), ''), '');
      v_component := COALESCE(NULLIF(TRIM(COALESCE(v_item->>'Component', v_item->>'component')), ''), '');
      v_location  := COALESCE(NULLIF(TRIM(COALESCE(v_item->>'Location', v_item->>'location')), ''), '');

      -- HotSpot real: campos HotSpot1*/HotSpot2* (NAO existe campo unico "HotSpot").
      -- Monta JSON compacto com as duas zonas, quando presentes.
      v_hotspot := NULL;
      IF NULLIF(v_item->>'HotSpot1Type','') IS NOT NULL THEN
        v_hotspot := (
          jsonb_build_object(
            'hotspot1', jsonb_build_object(
              'type',   v_item->>'HotSpot1Type',
              'originX',v_item->>'HotSpot1OriginX',
              'originY',v_item->>'HotSpot1OriginY',
              'top',    v_item->'HotSpot1Top',
              'left',   v_item->'HotSpot1Left',
              'width',  v_item->'HotSpot1Width',
              'height', v_item->'HotSpot1Height'
            )
          )
          || CASE WHEN NULLIF(v_item->>'HotSpot2Type','') IS NOT NULL THEN
               jsonb_build_object('hotspot2', jsonb_build_object(
                 'type',   v_item->>'HotSpot2Type',
                 'originX',v_item->>'HotSpot2OriginX',
                 'originY',v_item->>'HotSpot2OriginY',
                 'top',    v_item->'HotSpot2Top',
                 'left',   v_item->'HotSpot2Left',
                 'width',  v_item->'HotSpot2Width',
                 'height', v_item->'HotSpot2Height'
               ))
             ELSE '{}'::jsonb END
        )::text;
      END IF;

      INSERT INTO public.supplier_customization_options_raw (
        id, supplier_id,
        product_reference, service_code, table_code, component, location,
        hotspot, handling_cost, table_max_area_cm2, max_stitches,
        raw_data, imported_at
      ) VALUES (
        gen_random_uuid(), v_sid,
        v_ref, v_service, v_table, v_component, v_location,
        v_hotspot,
        CASE WHEN replace(COALESCE(v_item->>'HandlingCost',''), ',', '.') ~ '^-?[0-9]+(\.[0-9]+)?$'
             THEN replace(v_item->>'HandlingCost', ',', '.')::numeric ELSE NULL END,
        CASE WHEN replace(COALESCE(v_item->>'TableMaxAreaCM2',''), ',', '.') ~ '^-?[0-9]+(\.[0-9]+)?$'
             THEN replace(v_item->>'TableMaxAreaCM2', ',', '.')::numeric ELSE NULL END,
        CASE WHEN COALESCE(v_item->>'MaxStitches','') ~ '^-?[0-9]+$'
             THEN (v_item->>'MaxStitches')::int ELSE NULL END,
        v_item, now()
      )
      ON CONFLICT (supplier_id, product_reference, service_code, table_code, component, location)
      DO UPDATE SET
        hotspot            = EXCLUDED.hotspot,
        handling_cost      = EXCLUDED.handling_cost,
        table_max_area_cm2 = EXCLUDED.table_max_area_cm2,
        max_stitches       = EXCLUDED.max_stitches,
        raw_data           = EXCLUDED.raw_data,
        imported_at        = now();

      v_upserted := v_upserted + 1;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      IF jsonb_array_length(v_errsamples) < 15 THEN
        v_errsamples := v_errsamples || jsonb_build_object('erro', SQLERRM, 'sqlstate', SQLSTATE, 'ref', v_ref);
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'supplier_code', p_supplier_code, 'feed', 'customization_options', 'run_id', p_run_id,
    'fetched', v_fetched, 'upserted', v_upserted, 'skipped', v_skipped, 'errors', v_errors,
    'error_samples', v_errsamples
  );
END;
$_$;


ALTER FUNCTION "public"."fn_ingest_customization_options_batch"("p_supplier_code" "text", "p_run_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_ingest_customization_options_batch"("p_supplier_code" "text", "p_run_id" "uuid", "p_items" "jsonb") IS 'Ingere feed CustomizationOptions do SPOT (HotSpot + possibilidades de impressão por produto) em supplier_customization_options_raw via upsert idempotente pela chave natural';



CREATE OR REPLACE FUNCTION "public"."fn_ingest_supplier_raw"("p_supplier_id" "uuid", "p_reference" "text", "p_raw" "jsonb", "p_sku" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'n8n'::"text") RETURNS TABLE("acao" "text", "raw_id" "uuid", "content_hash" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_ref     text := btrim(p_reference);
  v_existed boolean;
  v_id      uuid;
  v_hash    text;
begin
  if p_supplier_id is null or v_ref is null or v_ref = '' then
    raise exception 'fn_ingest_supplier_raw: supplier_id e reference sao obrigatorios';
  end if;
  if p_raw is null or jsonb_typeof(p_raw) <> 'object' then
    raise exception 'fn_ingest_supplier_raw: raw deve ser um objeto jsonb';
  end if;

  v_existed := exists (
    select 1 from public.supplier_products_raw
     where supplier_id = p_supplier_id and supplier_reference = v_ref
  );

  insert into public.supplier_products_raw
    (supplier_id, supplier_reference, supplier_sku, raw_data, source_channel)
  values
    (p_supplier_id, v_ref, coalesce(nullif(btrim(p_sku), ''), v_ref), p_raw, coalesce(p_source, 'n8n'))
  on conflict (supplier_id, supplier_reference) do update
     set raw_data       = excluded.raw_data,
         supplier_sku   = excluded.supplier_sku,
         source_channel = excluded.source_channel,
         status         = case
                            when supplier_products_raw.content_hash is distinct from excluded.content_hash
                            then 'pending'::supplier_raw_status
                            else supplier_products_raw.status
                          end,
         updated_at     = now()
  returning id, supplier_products_raw.content_hash into v_id, v_hash;

  return query select case when v_existed then 'updated' else 'inserted' end, v_id, v_hash;
end;
$$;


ALTER FUNCTION "public"."fn_ingest_supplier_raw"("p_supplier_id" "uuid", "p_reference" "text", "p_raw" "jsonb", "p_sku" "text", "p_source" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_ingest_supplier_raw"("p_supplier_id" "uuid", "p_reference" "text", "p_raw" "jsonb", "p_sku" "text", "p_source" "text") IS 'Porta de ingestao idempotente (UPSERT) para supplier_products_raw. Recomendada para o n8n substituir DELETE+INSERT. Atualiza raw_data no conflito, disparando versionamento via trg_spr_history.';



CREATE OR REPLACE FUNCTION "public"."fn_ingestion_health"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'checked_at', now(),
    'por_fornecedor_feed', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'supplier_code', supplier_code, 'feed', feed, 'ultimo_status', status,
               'ultimo_run', started_at,
               'idade_horas', round((extract(epoch from (now()-started_at))/3600)::numeric,2),
               'fetched', fetched, 'upserted', upserted, 'errors', errors) order by supplier_code, feed), '[]'::jsonb)
      from (select distinct on (supplier_code,feed) supplier_code,feed,status,started_at,fetched,upserted,errors
            from ingestion_run_log order by supplier_code,feed,started_at desc) ult),
    'corridas_24h', (select count(*) from ingestion_run_log where started_at > now()-interval '24 hours'),
    'falhas_24h',   (select count(*) from ingestion_run_log where started_at > now()-interval '24 hours'
                                                                and status in ('failed','aborted_rate_limit')))
$$;


ALTER FUNCTION "public"."fn_ingestion_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ingestion_run_close"("p_run_id" "uuid", "p_status" "text", "p_fetched" integer, "p_upserted" integer, "p_skipped" integer, "p_errors" integer, "p_error_samples" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update ingestion_run_log
     set finished_at=now(), duration_s=extract(epoch from (now()-started_at)),
         status=p_status, fetched=p_fetched, upserted=p_upserted, skipped=p_skipped, errors=p_errors,
         error_samples=coalesce(p_error_samples, error_samples)
   where run_id=p_run_id;
  update supplier_import_batches
     set finished_at=now(), status=p_status,
         products_imported=p_upserted, products_errors=p_errors,
         error_log=coalesce(p_error_samples, error_log)
   where id=p_run_id;
end $$;


ALTER FUNCTION "public"."fn_ingestion_run_close"("p_run_id" "uuid", "p_status" "text", "p_fetched" integer, "p_upserted" integer, "p_skipped" integer, "p_errors" integer, "p_error_samples" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ingestion_run_open"("p_supplier_code" "text", "p_feed" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_sid uuid := public.fn_resolve_supplier(p_supplier_code); v_run uuid;
begin
  if p_feed not in ('products','stock','customization','customization_options') then
    raise exception 'feed invalido: %', p_feed;
  end if;
  insert into supplier_import_batches(supplier_id, status, notes)
    values (v_sid, 'running', 'ingestao '||p_feed||' ('||p_supplier_code||')')
    returning id into v_run;
  insert into ingestion_run_log(run_id, supplier_code, feed, status)
    values (v_run, p_supplier_code, p_feed, 'running');
  return v_run;
end $$;


ALTER FUNCTION "public"."fn_ingestion_run_open"("p_supplier_code" "text", "p_feed" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_inherit_techniques_from_material"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_material_id UUID;
    v_component_id UUID;
    v_compat RECORD;
BEGIN
    -- Buscar material do componente vinculado à área
    SELECT pkc.material_type_id, pkc.id
    INTO v_material_id, v_component_id
    FROM product_print_areas ppa
    JOIN product_kit_components pkc ON ppa.kit_component_id = pkc.id
    WHERE ppa.id = NEW.id;
    
    -- Se não tem material definido, sair
    IF v_material_id IS NULL THEN
        RETURN NEW;
    END IF;
    
    -- Inserir técnicas compatíveis com o material
    FOR v_compat IN 
        SELECT 
            mtc.tecnica_gravacao_id,
            mtc.tecnica_gravacao_variante_id,
            mtc.is_primary_technique,
            mtc.max_colors
        FROM material_technique_compatibility mtc
        WHERE mtc.material_type_id = v_material_id
          AND mtc.is_active = true
    LOOP
        INSERT INTO kit_component_area_techniques (
            print_area_id,
            tecnica_gravacao_id,
            tecnica_gravacao_variante_id,
            is_inherited,
            inherited_from_material_id,
            is_primary,
            max_colors
        ) VALUES (
            NEW.id,
            v_compat.tecnica_gravacao_id,
            v_compat.tecnica_gravacao_variante_id,
            true,
            v_material_id,
            v_compat.is_primary_technique,
            v_compat.max_colors
        )
        ON CONFLICT (print_area_id, tecnica_gravacao_id, tecnica_gravacao_variante_id) 
        DO NOTHING;
    END LOOP;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_inherit_techniques_from_material"() OWNER TO "postgres";


