CREATE OR REPLACE FUNCTION "public"."fn_kit_component_calc_circumference"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Para cilíndricos: circumference = π × diameter
  -- Só calcula se:
  --   (a) shape é cylindrical
  --   (b) diameter_mm está preenchido
  --   (c) circumference_mm não foi informado manualmente
  --       OU o diameter mudou (recalcula)
  IF NEW.shape_type = 'cylindrical'
     AND NEW.diameter_mm IS NOT NULL
     AND (
       NEW.circumference_mm IS NULL
       OR (TG_OP = 'UPDATE' AND OLD.diameter_mm IS DISTINCT FROM NEW.diameter_mm)
     )
  THEN
    NEW.circumference_mm := ROUND(PI() * NEW.diameter_mm);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_kit_component_calc_circumference"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_kit_component_calc_circumference"() IS 'Trigger PRATA: calcula circumference_mm = ROUND(π × diameter_mm)
   para shape_type=cylindrical. Respeitado override manual.';



CREATE OR REPLACE FUNCTION "public"."fn_kit_component_inherit_personalization"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Só atua se o INSERT veio com allows_personalization NULL
  IF NEW.allows_personalization IS NULL AND NEW.component_type_code IS NOT NULL THEN
    SELECT kct.is_personalizable_by_default 
      INTO NEW.allows_personalization
    FROM public.kit_component_types kct 
    WHERE kct.code = NEW.component_type_code;
  END IF;
  RETURN NEW;
END;
$$;


