CREATE OR REPLACE FUNCTION "public"."fn_kit_from_ficha"("p_sku" "text", "p_dry" boolean DEFAULT true) RETURNS TABLE("acao" "text", "slot" "text", "nome" "text", "tipo" "text", "a" integer, "l" integer, "p" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_kid uuid; v_ic text; v_ncomp int; r record; v_kidx int:=0; v_eidx int:=0;
  v_kind text; v_type text; v_a int; v_l int; v_pp int; v_tgt uuid; v_nm text; v_slot text; v_npieces int;
BEGIN
  SELECT id INTO v_kid FROM products WHERE sku=p_sku;
  IF v_kid IS NULL THEN RAISE EXCEPTION 'produto % nao encontrado', p_sku; END IF;
  SELECT count(*) INTO v_ncomp FROM product_kit_components WHERE kit_product_id=v_kid;
  IF v_ncomp>0 THEN RAISE EXCEPTION 'produto % ja tem % componentes', p_sku, v_ncomp; END IF;
  SELECT count(*) INTO v_npieces FROM kit_component_ficha_staging s
   WHERE s.product_sku=p_sku AND s.piece_label NOT LIKE '\_\_%' AND s.match_status IN ('no_component','ambiguous','pending')
     AND fn_norm_piece_label(s.piece_label) !~ '^(kit|conjunto|jogo completo)( |$)';
  IF v_npieces<2 THEN RAISE EXCEPTION 'produto % tem so % pecas reais (<2)', p_sku, v_npieces; END IF;

  SELECT cv.internal_code INTO v_ic FROM product_variants v JOIN color_variations cv ON cv.id=v.color_id
   WHERE v.product_id=v_kid AND cv.internal_code IS NOT NULL AND cv.internal_code<>'' ORDER BY v.id LIMIT 1;

  IF NOT p_dry THEN UPDATE products SET is_kit=true WHERE id=v_kid AND is_kit=false; END IF;

  FOR r IN
    SELECT s.id sid, s.piece_label, s.source_url, s.dim_a_mm, s.dim_l_mm, s.dim_p_mm, fn_norm_piece_label(s.piece_label) pnorm
    FROM kit_component_ficha_staging s
    WHERE s.product_sku=p_sku AND s.piece_label NOT LIKE '\_\_%' AND s.match_status IN ('no_component','ambiguous','pending')
    ORDER BY (CASE WHEN fn_norm_piece_label(s.piece_label) ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa|embalagem)' THEN 1 ELSE 0 END), s.id
  LOOP
    -- pula linhas-resumo do kit inteiro (nao sao componentes)
    IF r.pnorm ~ '^(kit|conjunto|jogo completo)( |$)' THEN
      IF NOT p_dry THEN UPDATE kit_component_ficha_staging SET match_status='skipped', piece_norm=r.pnorm,
        product_id=v_kid, notes='linha resumo do kit (nao e componente)' WHERE id=r.sid; END IF;
      CONTINUE;
    END IF;

    v_kind := CASE WHEN r.pnorm ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa|embalagem)' THEN 'packaging' ELSE 'item' END;
    v_type := CASE
      WHEN r.pnorm ~ 'faca' THEN 'FACA' WHEN r.pnorm ~ 'tabua' THEN 'TABUA'
      WHEN r.pnorm ~ 'garfo' THEN 'GARFO' WHEN r.pnorm ~ 'espatula' THEN 'ESPATULA'
      WHEN r.pnorm ~ '(colher|concha|escumadeira)' THEN 'COLHER' WHEN r.pnorm ~ 'pegador' THEN 'PEGADOR'
      WHEN r.pnorm ~ 'pincel' THEN 'PINCEL' WHEN r.pnorm ~ '(caderno|caderneta)' THEN 'CADERNO'
      WHEN r.pnorm ~ 'caneta' THEN 'CANETA' WHEN r.pnorm ~ 'copo' THEN 'COPO'
      WHEN r.pnorm ~ 'caneca' THEN 'CANECA' WHEN r.pnorm ~ 'garrafa' THEN 'GARRAFA'
      WHEN r.pnorm ~ 'chaveiro' THEN 'CHAVEIRO' WHEN r.pnorm ~ 'porta ?cart' THEN 'PORTA_CARTAO'
      WHEN r.pnorm ~ 'tesoura' THEN 'TESOURA' WHEN r.pnorm ~ 'canudo' THEN 'CANUDO'
      WHEN r.pnorm ~ 'frasco' THEN 'FRASCO' WHEN r.pnorm ~ 'pote' THEN 'POTE'
      WHEN r.pnorm ~ 'bandeja' THEN 'BANDEJA' WHEN r.pnorm ~ 'squeeze' THEN 'SQUEEZE'
      WHEN r.pnorm ~ 'coquetel' THEN 'COQUETELEIRA' WHEN r.pnorm ~ 'saca.?rolha' THEN 'SACA_ROLHAS'
      WHEN r.pnorm ~ 'dosador' THEN 'BICO_DOSADOR' WHEN r.pnorm ~ 'socador' THEN 'SOCADOR'
      WHEN r.pnorm ~ 'escova' THEN 'ESCOVA' WHEN r.pnorm ~ 'xicara' THEN 'XICARA'
      WHEN r.pnorm ~ 'pires' THEN 'PIRES' WHEN r.pnorm ~ '(taca|taça)' THEN 'TACA_VINHO'
      WHEN r.pnorm ~ 'chaira' THEN 'CHAIRA' WHEN r.pnorm ~ 'avental' THEN 'AVENTAL'
      WHEN r.pnorm ~ 'necessaire' THEN 'NECESSAIRE' WHEN r.pnorm ~ 'fone' THEN 'FONE'
      WHEN r.pnorm ~ 'mochila' THEN 'MOCHILA' WHEN r.pnorm ~ 'caixa' THEN 'CAIXA'
      WHEN r.pnorm ~ 'anel' THEN 'ANEL_SALVA_GOTAS' WHEN r.pnorm ~ 'tampa' THEN 'TAMPA'
      WHEN r.pnorm ~ 'abridor' THEN 'SACA_ROLHAS' WHEN r.pnorm ~ 'termometro' THEN 'TERMOMETRO'
      ELSE NULL END;
    v_a := CASE WHEN r.dim_a_mm BETWEEN 1 AND 1500 THEN r.dim_a_mm END;
    v_l := CASE WHEN r.dim_l_mm BETWEEN 1 AND 1500 THEN r.dim_l_mm END;
    v_pp := CASE WHEN r.dim_p_mm BETWEEN 1 AND 1500 THEN r.dim_p_mm END;
    -- limpa cauda de medida que ficou no rotulo (ex.: "Caderneta 21,2 cm x 15,")
    v_nm := left(initcap(btrim(regexp_replace(r.piece_label, '\s+[0-9]+([.,][0-9]+)?\s*cm\s*[x×].*$', '', 'i'))), 80);
    IF length(v_nm)<2 THEN v_nm := left(initcap(r.piece_label),80); END IF;

    IF v_kind='item' THEN v_kidx:=v_kidx+1; v_slot:='K'||v_kidx; acao:='INSERT item';
    ELSE v_eidx:=v_eidx+1; v_slot:='E'||v_eidx; acao:='INSERT pkg'; END IF;

    IF NOT p_dry THEN
      IF v_kind='item' THEN
        INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
          is_packaging,quantity,is_standalone_sellable,height_mm,width_mm,length_mm,dim_source,dim_source_url)
        VALUES (v_kid,v_nm,v_type,v_slot,p_sku||'-'||v_slot, CASE WHEN v_ic IS NOT NULL THEN p_sku||'-'||v_ic||'-'||v_slot END,
                false,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
      ELSE
        INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
          is_packaging,quantity,is_standalone_sellable,pkg_ext_height_mm,pkg_ext_width_mm,pkg_ext_length_mm,dim_source,dim_source_url)
        VALUES (v_kid,v_nm,coalesce(v_type,'CAIXA'),v_slot,p_sku||'-'||v_slot, CASE WHEN v_ic IS NOT NULL THEN p_sku||'-'||v_ic||'-'||v_slot END,
                true,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
      END IF;
      UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_tgt, product_id=v_kid,
             piece_kind=v_kind, piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='kit_from_ficha' WHERE id=r.sid;
    END IF;

    slot:=v_slot; tipo:=v_type; nome:=v_nm; a:=v_a; l:=v_l; p:=v_pp; RETURN NEXT;
  END LOOP;
END $_$;


ALTER FUNCTION "public"."fn_kit_from_ficha"("p_sku" "text", "p_dry" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_kit_material_quick_propagate"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_gold INTEGER := 0; v_silver INTEGER := 0;
BEGIN
  -- Propagar para Gold
  WITH g AS (
    UPDATE product_kit_components pkc
    SET material_type_id = kct.default_material_type_id,
        secondary_material_type_id = COALESCE(pkc.secondary_material_type_id, kct.secondary_material_type_id),
        updated_at = NOW()
    FROM kit_component_types kct
    WHERE pkc.component_type_code = kct.code
      AND pkc.material_type_id IS NULL
      AND kct.default_material_type_id IS NOT NULL
    RETURNING pkc.id
  ) SELECT COUNT(*) INTO v_gold FROM g;

  -- Propagar para Silver via Gold
  WITH s AS (
    UPDATE kit_component_padronizacao kcp
    SET material_type_id = pkc.material_type_id,
        secondary_material_type_id = COALESCE(kcp.secondary_material_type_id, pkc.secondary_material_type_id),
        updated_at = NOW()
    FROM product_kit_components pkc
    WHERE kcp.kit_component_id = pkc.id
      AND kcp.material_type_id IS NULL
      AND pkc.material_type_id IS NOT NULL
    RETURNING kcp.id
  ) SELECT COUNT(*) INTO v_silver FROM s;

  RETURN jsonb_build_object(
    'gold_updated', v_gold, 'silver_updated', v_silver, 'ts', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."fn_kit_material_quick_propagate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_kit_print_area_normalizar_eixos"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_temp numeric;
BEGIN
  IF NEW.max_width IS NOT NULL THEN
    NEW.max_width := ROUND(NEW.max_width::numeric, 2);
  END IF;
  IF NEW.max_height IS NOT NULL THEN
    NEW.max_height := ROUND(NEW.max_height::numeric, 2);
  END IF;

  IF NEW.max_height IS NOT NULL AND NEW.max_width IS NOT NULL
     AND NEW.max_height > NEW.max_width THEN
    v_temp        := NEW.max_width;
    NEW.max_width  := NEW.max_height;
    NEW.max_height := v_temp;
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."fn_kit_print_area_normalizar_eixos"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_kit_print_area_normalizar_eixos"() IS 'Onda 19 follow-up: registra em migrations função que existia só como drift. Arredonda max_width/max_height a 2 casas e normaliza eixos (largura >= altura). Usada pelo trigger trg_kit_print_area_normalizar_eixos.';



CREATE OR REPLACE FUNCTION "public"."fn_kit_sync_personalization_notes"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Atualizar notas de personalização para componentes com print_areas e sem notas
  WITH notas_calculadas AS (
    SELECT 
      pkc.id AS comp_id,
      STRING_AGG(
        kpa.location_name 
        || ': ' || ROUND(kpa.max_width, 0)::text || ' × ' || ROUND(kpa.max_height, 0)::text || ' mm'
        || CASE WHEN kpa.is_curved THEN ' (curvo)' ELSE '' END
        || ' | ' || COALESCE(tpg.grupo_tecnica, 'Gravação')
        || CASE WHEN tpg.max_cores IS NOT NULL AND tpg.max_cores > 0 
                THEN ' | Máx ' || tpg.max_cores || ' cor(es)' ELSE '' END
        || CASE WHEN tpg.codigo_tabela IS NOT NULL 
                THEN ' [' || tpg.codigo_tabela || ']' ELSE '' END,
        E'\n' ORDER BY kpa.location_order, kpa.location_name
      ) AS nota_texto
    FROM product_kit_components pkc
    JOIN kit_component_print_areas kpa ON kpa.kit_component_id = pkc.id
    LEFT JOIN tabela_preco_gravacao_oficial tpg ON tpg.id = kpa.tabela_preco_id
    WHERE pkc.personalization_notes IS NULL
      AND kpa.location_name IS NOT NULL
    GROUP BY pkc.id
  )
  UPDATE product_kit_components pkc
  SET 
    personalization_notes = nc.nota_texto,
    updated_at = NOW()
  FROM notas_calculadas nc
  WHERE pkc.id = nc.comp_id
    AND nc.nota_texto IS NOT NULL;
END;
$$;


ALTER FUNCTION "public"."fn_kit_sync_personalization_notes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_link_asia_colors_from_bronze"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier_id     uuid   := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_updated_bronze  int    := 0;
  v_updated_name    int    := 0;
  v_total_before    int;
  v_total_after     int;
BEGIN
  SELECT COUNT(*) INTO v_total_before
  FROM product_variants pv
  JOIN products p ON p.id = pv.product_id
  WHERE p.supplier_id = v_supplier_id AND pv.color_id IS NULL AND pv.is_active = true;

  -- ESTRATÉGIA 1: Cor via Bronze (atributos.cor.value)
  WITH bronze_resolved AS (
    SELECT DISTINCT ON (pv.id)
      pv.id AS variant_id,
      vm.color_variation_id,
      vm.internal_color_name,
      vm.internal_hex
    FROM product_variants pv
    JOIN products p ON p.id = pv.product_id
    JOIN supplier_products_raw spr
      ON spr.supplier_id = p.supplier_id
      AND spr.supplier_sku = RTRIM(p.supplier_reference, 'P')
    JOIN supplier_colors sc
      ON sc.supplier_id = v_supplier_id AND sc.is_active = true
      AND LOWER(TRIM(sc.name)) = LOWER(TRIM(spr.raw_data->'atributos'->'cor'->>'value'))
    JOIN vw_color_mapping vm ON vm.supplier_color_id = sc.id AND vm.rank = 1
    WHERE p.supplier_id = v_supplier_id AND pv.color_id IS NULL AND pv.is_active = true
      AND spr.raw_data->'atributos'->'cor'->>'value' IS NOT NULL
    ORDER BY pv.id, vm.confidence_score DESC
  )
  UPDATE product_variants pv
  SET color_id = br.color_variation_id, color_name = br.internal_color_name,
      color_hex = br.internal_hex, updated_at = now()
  FROM bronze_resolved br WHERE pv.id = br.variant_id AND pv.color_id IS NULL;
  GET DIAGNOSTICS v_updated_bronze = ROW_COUNT;

  -- ESTRATÉGIA 2: Cor via nome no Bronze (palavras-chave no campo 'nome')
  WITH kw_map(keyword, cv_id, cv_name, cv_hex) AS (
    VALUES
      ('PRETO',       'aaa46113-20f7-4585-83ab-1ec49cc40fc2'::uuid, 'Preto', '#000000'),
      ('PRETA',       'aaa46113-20f7-4585-83ab-1ec49cc40fc2'::uuid, 'Preto', '#000000'),
      ('BRANCO',      '77ec212c-47f8-4a6f-ba66-1734c286d67b'::uuid, 'Branco', '#FFFFFF'),
      ('BRANCA',      '77ec212c-47f8-4a6f-ba66-1734c286d67b'::uuid, 'Branco', '#FFFFFF'),
      ('AZUL',        '34b1361e-f965-4aea-b801-2001246c7d1e'::uuid, 'Azul', '#0000FF'),
      ('VERDE',       'a366339c-b41d-4c3d-80cb-d8baabdf8f32'::uuid, 'Verde Floresta', '#228B22'),
      ('VERMELHO',    'c98f9e38-a2e7-48a2-8260-a8f11c744670'::uuid, 'Vermelho Escarlate', '#FF2400'),
      ('AMARELO',     '7598ef45-35be-4c56-8569-8eeaf3d0bd99'::uuid, 'Amarelo Milho', '#FBEC5D'),
      ('ROSA',        '81ab1f0f-6db5-4b5d-9364-a1b8b0c2ad84'::uuid, 'Rosa Bebê', '#F4C2C2'),
      ('CINZA',       'beb6fa6a-eca8-4b9e-b861-b4a12c2c0020'::uuid, 'Cinza', '#808080'),
      ('GRAFITE',     'cb83a06e-25b0-4060-9668-e7835e141af3'::uuid, 'Cinza Grafite', '#2F2F2F'),
      ('DOURADO',     'a276ea9b-73ad-44e4-b6e3-14ee820ba89d'::uuid, 'Dourado Brilhante', '#FFD700'),
      ('PRATA',       'b4feaacd-2442-4597-bf55-c9c36ea61756'::uuid, 'Prata', '#C0C0C0'),
      ('MARROM',      'ba704fdf-2bec-4d03-b02e-37a36417bf99'::uuid, 'Marrom Conhaque', '#795548'),
      ('NATURAL',     '0ee9d87f-9a1f-4d8f-b54a-a66ea06bab86'::uuid, 'Natural', '#BB8B64'),
      ('BAMBU',       '73c0af09-efb9-4fea-9cdb-cbaff0ee2626'::uuid, 'Bambu', '#D4B87A'),
      ('MADEIRA',     'fb0f72cb-e35d-45bb-9766-19fac825253b'::uuid, 'Madeira', '#8B5E3C'),
      ('TRANSPARENTE','779c443f-0367-4b67-8774-687f7673cfb4'::uuid, 'Transparente', '#d8d8d8'),
      ('LARANJA',     'ae8d181a-1bea-4a75-8fa1-26abb4078420'::uuid, 'Laranja', '#FF9800'),
      ('ROXO',        '56dd484f-b17f-47d2-a8ae-f6612069227d'::uuid, 'Roxo Púrpura', '#800080'),
      ('VINHO',       '1a88e747-d496-4614-96e2-19f800c0f922'::uuid, 'Vermelho Bordô', '#800020')
  ),
  name_resolved AS (
    SELECT DISTINCT ON (pv.id) pv.id AS variant_id, km.cv_id, km.cv_name, km.cv_hex
    FROM product_variants pv
    JOIN products p ON p.id = pv.product_id
    JOIN supplier_products_raw spr
      ON spr.supplier_id = p.supplier_id
      AND spr.supplier_sku = RTRIM(p.supplier_reference, 'P')
    JOIN kw_map km ON spr.raw_data->>'nome' ILIKE '%' || km.keyword || '%'
    WHERE p.supplier_id = v_supplier_id AND pv.color_id IS NULL AND pv.is_active = true
    ORDER BY pv.id
  )
  UPDATE product_variants pv
  SET color_id = nr.cv_id, color_name = nr.cv_name, color_hex = nr.cv_hex, updated_at = now()
  FROM name_resolved nr WHERE pv.id = nr.variant_id AND pv.color_id IS NULL;
  GET DIAGNOSTICS v_updated_name = ROW_COUNT;

  SELECT COUNT(*) INTO v_total_after
  FROM product_variants pv
  JOIN products p ON p.id = pv.product_id
  WHERE p.supplier_id = v_supplier_id AND pv.color_id IS NULL AND pv.is_active = true;

  RETURN jsonb_build_object(
    'status','ok','supplier','ASIA',
    'antes', v_total_before, 'depois', v_total_after,
    'resolvidos_bronze', v_updated_bronze,
    'resolvidos_nome', v_updated_name,
    'restam_sem_cor', v_total_after
  );
END;
$$;


ALTER FUNCTION "public"."fn_link_asia_colors_from_bronze"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_link_cf_image"("p_img_id" "uuid", "p_cf_id" "text", "p_url_cdn" "text", "p_product_id" "uuid" DEFAULT NULL::"uuid", "p_is_primary" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Atualizar product_images (mantém URL CF bruta)
  UPDATE product_images
  SET
    cloudflare_image_id = p_cf_id,
    url_cdn             = p_url_cdn,
    updated_at          = now()
  WHERE id = p_img_id;

  -- Se for imagem principal, atualizar products.primary_image_url
  -- FIX 2026-06-09: usa url_cdn CF direto (remove conversão proxy Workers.dev)
  IF p_is_primary AND p_product_id IS NOT NULL THEN
    UPDATE products
    SET
      primary_image_url = p_url_cdn,
      updated_at        = now()
    WHERE id = p_product_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'img_id', p_img_id, 'cf_id', p_cf_id);

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM, 'img_id', p_img_id);
END;
$$;


