COMMENT ON FUNCTION "public"."fn_link_images_to_variants_by_synonym"("p_dry_run" boolean) IS 'Liga product_images.variant_id para imagens XBZ applies_to_color=true que têm color_id
mas não têm variant_id. Usa o "effective color code" extraído do variant_reference da Silver:
- Single-color 1089T-FUM → suffix = FUM → imagem Fumê
- Multi-color 15051-PRE/AZU → após / = AZU → imagem Azul
Use p_dry_run=true para preview. Execute p_dry_run=false para aplicar.
Invoke quando novos produtos XBZ forem ingested ou após re-sync do catálogo.';



CREATE OR REPLACE FUNCTION "public"."fn_link_product_materials"("p_product_id" "uuid", "p_supplier_id" "uuid" DEFAULT 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'::"uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_raw_materials TEXT;
    v_material_name TEXT;
    v_material_names TEXT[];
    v_supplier_material_id UUID;
    v_promo_type_id UUID;
    v_linked_count INTEGER := 0;
    v_total_materials INTEGER;
    v_percentage DECIMAL(5,2);
BEGIN
    -- ═══════════════════════════════════════════════════════════════════
    -- 1. BUSCAR MATERIALS DO RAW_DATA
    -- ═══════════════════════════════════════════════════════════════════
    SELECT raw_data->>'Materials'
    INTO v_raw_materials
    FROM supplier_products_raw
    WHERE product_id = p_product_id
      AND supplier_id = p_supplier_id
    LIMIT 1;
    
    IF v_raw_materials IS NULL OR v_raw_materials = '' OR v_raw_materials = '-' THEN
        RETURN 0;
    END IF;
    
    -- ═══════════════════════════════════════════════════════════════════
    -- 2. NORMALIZAR SEPARADORES E SEPARAR MATERIAIS
    --    Converte " e " e ". " para ", " (exceto ":")
    -- ═══════════════════════════════════════════════════════════════════
    v_raw_materials := REPLACE(v_raw_materials, ' e ', ', ');
    v_raw_materials := REPLACE(v_raw_materials, '. ', ', ');
    
    -- Separar em array
    v_material_names := string_to_array(v_raw_materials, ', ');
    v_total_materials := array_length(v_material_names, 1);
    
    IF v_total_materials IS NULL OR v_total_materials = 0 THEN
        RETURN 0;
    END IF;
    
    -- Calcular percentual (100% / quantidade de materiais)
    v_percentage := ROUND(100.0 / v_total_materials, 2);
    
    -- ═══════════════════════════════════════════════════════════════════
    -- 3. PARA CADA MATERIAL, BUSCAR E VINCULAR
    -- ═══════════════════════════════════════════════════════════════════
    FOREACH v_material_name IN ARRAY v_material_names
    LOOP
        v_material_name := TRIM(v_material_name);
        
        IF v_material_name = '' THEN
            CONTINUE;
        END IF;
        
        -- Buscar supplier_material_id pelo nome EXATO
        SELECT id INTO v_supplier_material_id
        FROM supplier_materials
        WHERE LOWER(api_material_name) = LOWER(v_material_name)
          AND supplier_id = p_supplier_id
        LIMIT 1;
        
        -- Se não encontrou exato, tentar busca parcial
        IF v_supplier_material_id IS NULL THEN
            SELECT id INTO v_supplier_material_id
            FROM supplier_materials
            WHERE LOWER(api_material_name) ILIKE '%' || LOWER(v_material_name) || '%'
              AND supplier_id = p_supplier_id
            LIMIT 1;
        END IF;
        
        IF v_supplier_material_id IS NOT NULL THEN
            -- Buscar material equivalente interno (material_types)
            SELECT me.promo_type_id INTO v_promo_type_id
            FROM material_equivalences me
            WHERE me.supplier_material_id = v_supplier_material_id
            LIMIT 1;
            
            -- Inserir vínculo em product_materials
            IF v_promo_type_id IS NOT NULL THEN
                INSERT INTO product_materials (
                    product_id,
                    material_id,       -- ✅ CORRIGIDO: era material_type_id
                    part,
                    percentage,
                    sort_order,
                    is_active,
                    organization_id,
                    created_at
                )
                VALUES (
                    p_product_id,
                    v_promo_type_id,
                    'corpo',           -- Parte padrão
                    v_percentage,      -- Percentual calculado
                    v_linked_count + 1,
                    true,
                    '5db5aee1-064b-4ef4-9193-345dcd8274ea',  -- organization_id fixo
                    NOW()
                )
                ON CONFLICT (product_id, material_id) DO UPDATE SET
                    percentage = v_percentage,
                    updated_at = NOW();
                
                v_linked_count := v_linked_count + 1;
            END IF;
        END IF;
    END LOOP;
    
    RETURN v_linked_count;
    
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Erro vinculando materiais do produto %: %', p_product_id, SQLERRM;
    RETURN 0;
END;
$$;


ALTER FUNCTION "public"."fn_link_product_materials"("p_product_id" "uuid", "p_supplier_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_link_product_materials"("p_product_id" "uuid", "p_supplier_id" "uuid") IS 'Vincula materiais do raw_data ao produto usando material_equivalences. v2.0 (CORRIGIDO) - 30/01/2026';



CREATE OR REPLACE FUNCTION "public"."fn_link_sm_colors_from_title"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier_id uuid := '841cd690-210a-422a-908c-7676828db272';
  v_updated     int  := 0;
  v_total_before int;
  v_total_after  int;
BEGIN
  SELECT COUNT(*) INTO v_total_before
  FROM product_variants pv
  JOIN products p ON p.id = pv.product_id
  WHERE p.supplier_id = v_supplier_id AND pv.color_id IS NULL AND pv.is_active = true;

  -- Mapeamento semântico por título do Bronze
  -- Regras em ordem de prioridade (DISTINCT ON preserva a 1ª)
  WITH titulo_map(pattern, cv_id, cv_name, cv_hex, prioridade) AS (
    VALUES
      -- Materiais específicos (maior prioridade)
      ('%BAMBU%',           '73c0af09-efb9-4fea-9cdb-cbaff0ee2626'::uuid, 'Bambu',           '#D4B87A', 1),
      ('%MADEIRA%',         'fb0f72cb-e35d-45bb-9766-19fac825253b'::uuid, 'Madeira',          '#8B5E3C', 1),
      ('%INOX%',            'b0342859-437c-439b-a4bf-d323a2b6681e'::uuid, 'Prata Inox',       '#B4BDC7', 2),
      ('%KRAFT%',           '27eeaf94-4493-4f0e-9878-50100df4ef56'::uuid, 'Kraft',             '#C4A36D', 2),
      ('%VIDRO%',           '779c443f-0367-4b67-8774-687f7673cfb4'::uuid, 'Transparente',     '#d8d8d8', 2),
      ('%CRISTAL%',         '779c443f-0367-4b67-8774-687f7673cfb4'::uuid, 'Transparente',     '#d8d8d8', 2),
      ('%TRANSPARENTE%',    '779c443f-0367-4b67-8774-687f7673cfb4'::uuid, 'Transparente',     '#d8d8d8', 2),
      -- Cores diretas no título
      ('% PRETO%',          'aaa46113-20f7-4585-83ab-1ec49cc40fc2'::uuid, 'Preto',            '#000000', 3),
      ('% PRETA%',          'aaa46113-20f7-4585-83ab-1ec49cc40fc2'::uuid, 'Preto',            '#000000', 3),
      ('PRETO %',           'aaa46113-20f7-4585-83ab-1ec49cc40fc2'::uuid, 'Preto',            '#000000', 3),
      ('PRETA %',           'aaa46113-20f7-4585-83ab-1ec49cc40fc2'::uuid, 'Preto',            '#000000', 3),
      ('% BRANCO%',         '77ec212c-47f8-4a6f-ba66-1734c286d67b'::uuid, 'Branco',           '#FFFFFF', 3),
      ('% BRANCA%',         '77ec212c-47f8-4a6f-ba66-1734c286d67b'::uuid, 'Branco',           '#FFFFFF', 3),
      ('% AZUL%',           '34b1361e-f965-4aea-b801-2001246c7d1e'::uuid, 'Azul',             '#2196F3', 3),
      ('% VERDE%',          'a366339c-b41d-4c3d-80cb-d8baabdf8f32'::uuid, 'Verde Floresta',   '#228B22', 3),
      ('% VERMELHO%',       'c98f9e38-a2e7-48a2-8260-a8f11c744670'::uuid, 'Vermelho Escarlate','#FF2400', 3),
      ('% AMARELO%',        '7598ef45-35be-4c56-8569-8eeaf3d0bd99'::uuid, 'Amarelo Milho',    '#FBEC5D', 3),
      ('% ROSA%',           '81ab1f0f-6db5-4b5d-9364-a1b8b0c2ad84'::uuid, 'Rosa Bebê',       '#F4C2C2', 3),
      ('% CINZA%',          'beb6fa6a-eca8-4b9e-b861-b4a12c2c0020'::uuid, 'Cinza',            '#9E9E9E', 3),
      ('% DOURADO%',        'a276ea9b-73ad-44e4-b6e3-14ee820ba89d'::uuid, 'Dourado Brilhante','#FFD700', 3),
      ('% DOURADA%',        'a276ea9b-73ad-44e4-b6e3-14ee820ba89d'::uuid, 'Dourado Brilhante','#FFD700', 3),
      ('% NATURAL%',        '0ee9d87f-9a1f-4d8f-b54a-a66ea06bab86'::uuid, 'Natural',          '#BB8B64', 3),
      -- KITs e produtos multi-componente → Colorido (menor prioridade, fallback)
      ('%KIT%',             '2006d7eb-9d4d-4d96-9e0d-fed83c8a5b59'::uuid, 'Colorido',         '#ababab', 10),
      ('%JOGO%',            '2006d7eb-9d4d-4d96-9e0d-fed83c8a5b59'::uuid, 'Colorido',         '#ababab', 10),
      ('%CONJUNTO%',        '2006d7eb-9d4d-4d96-9e0d-fed83c8a5b59'::uuid, 'Colorido',         '#ababab', 10),
      -- Fallback universal
      ('%',                 '2006d7eb-9d4d-4d96-9e0d-fed83c8a5b59'::uuid, 'Colorido',         '#ababab', 99)
  ),
  resolved AS (
    SELECT DISTINCT ON (pv.id)
      pv.id AS variant_id,
      tm.cv_id, tm.cv_name, tm.cv_hex
    FROM product_variants pv
    JOIN products p ON p.id = pv.product_id
    JOIN supplier_products_raw spr
      ON spr.supplier_id = p.supplier_id AND spr.supplier_sku = p.supplier_reference
    JOIN titulo_map tm ON spr.raw_data->>'titulo' ILIKE tm.pattern
    WHERE p.supplier_id = v_supplier_id
      AND pv.color_id IS NULL AND pv.is_active = true
    ORDER BY pv.id, tm.prioridade ASC
  )
  UPDATE product_variants pv
  SET
    color_id   = r.cv_id,
    color_name = r.cv_name,
    color_hex  = r.cv_hex,
    updated_at = now()
  FROM resolved r WHERE pv.id = r.variant_id AND pv.color_id IS NULL;
  GET DIAGNOSTICS v_updated = ROW_COUNT;

  SELECT COUNT(*) INTO v_total_after
  FROM product_variants pv
  JOIN products p ON p.id = pv.product_id
  WHERE p.supplier_id = v_supplier_id AND pv.color_id IS NULL AND pv.is_active = true;

  RETURN jsonb_build_object(
    'status','ok','supplier','SOMARCAS',
    'antes', v_total_before, 'depois', v_total_after,
    'resolvidos', v_updated,
    'restam_sem_cor', v_total_after
  );
END;
$$;


ALTER FUNCTION "public"."fn_link_sm_colors_from_title"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_list_deactivation_requests"("p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_limit  int := GREATEST(1, LEAST(COALESCE(p_limit, 50), 5000));
BEGIN
  SELECT jsonb_agg(row)
  INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'id',                r.id,
      'product_id',        r.product_id,
      'supplier_reference', r.supplier_reference,
      'product_name',      r.product_name,
      'reason',            r.reason,
      'reason_code',       r.reason_code,
      'requested_by',      r.requested_by_name,
      'requested_at',      r.requested_at,
      'status',            r.status,
      'approved_by',       r.approved_by_name,
      'approved_at',       r.approved_at,
      'rejected_by',       r.rejected_by,
      'rejected_at',       r.rejected_at,
      'rejection_reason',  r.rejection_reason,
      'executed_at',       r.executed_at,
      'notes',             r.notes
    ) AS row
    FROM product_deactivation_requests r
    WHERE (p_status = 'all' OR r.status = p_status)
    ORDER BY r.requested_at DESC
    LIMIT v_limit
  ) sub;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


