COMMENT ON FUNCTION "public"."fn_master_classify_product"("p_name" "text", "p_product_id" "uuid") IS 'Função master que classifica produtos - v2.1 CORRIGIDA - 30/01/2026';



CREATE OR REPLACE FUNCTION "public"."fn_match_canonical_color"("p_name" "text", "p_hex" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id       uuid;
  v_name_norm text := NULLIF(UPPER(TRIM(p_name)), '');
  v_hex_norm  text := NULLIF(UPPER(TRIM(p_hex)),  '');
BEGIN
  IF v_name_norm IS NULL AND v_hex_norm IS NULL THEN RETURN NULL; END IF;

  -- P1: Match exato por nome em color_variations
  SELECT cv.id INTO v_id FROM public.color_variations cv
  WHERE cv.is_active = TRUE AND v_name_norm IS NOT NULL AND UPPER(TRIM(cv.name)) = v_name_norm
  ORDER BY cv.sort_order NULLS LAST LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  -- P2: Match exato por hex em color_variations
  SELECT cv.id INTO v_id FROM public.color_variations cv
  WHERE cv.is_active = TRUE AND v_hex_norm IS NOT NULL AND UPPER(TRIM(cv.hex_code)) = v_hex_norm
  ORDER BY cv.sort_order NULLS LAST LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  -- P3: Match via supplier_colors → equivalences (por nome)
  SELECT cv.id INTO v_id
  FROM public.supplier_colors sc
  JOIN public.color_equivalences ce ON ce.supplier_color_id = sc.id AND ce.is_active = TRUE
  JOIN public.color_variations cv ON cv.id = ce.promo_variation_id AND cv.is_active = TRUE
  WHERE sc.is_active = TRUE AND v_name_norm IS NOT NULL AND UPPER(TRIM(sc.name)) = v_name_norm
  ORDER BY ce.confidence_score DESC NULLS LAST, cv.sort_order NULLS LAST LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  -- P3.5: color_synonym_map — lookup direto por nome (novo: antes de hex e sinônimos)
  SELECT csm.canonical_color_id INTO v_id
  FROM public.color_synonym_map csm
  WHERE v_name_norm IS NOT NULL
    AND UPPER(TRIM(csm.supplier_color_name)) = v_name_norm
  ORDER BY csm.confidence DESC NULLS LAST
  LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  -- P4: Match via hex em supplier_colors → equivalences
  SELECT cv.id INTO v_id
  FROM public.supplier_colors sc
  JOIN public.color_equivalences ce ON ce.supplier_color_id = sc.id AND ce.is_active = TRUE
  JOIN public.color_variations cv ON cv.id = ce.promo_variation_id AND cv.is_active = TRUE
  WHERE sc.is_active = TRUE AND v_hex_norm IS NOT NULL AND UPPER(TRIM(sc.hex_code)) = v_hex_norm
  ORDER BY ce.confidence_score DESC NULLS LAST, cv.sort_order NULLS LAST LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  -- P4.5: Tabela de sinônimos universais inline — v4 (inclui VINHO, FUMÊ, BRONZE + acento)
  IF v_name_norm IS NOT NULL THEN
    SELECT syn.variation_id INTO v_id
    FROM (VALUES
      ('BLACK','aaa46113-20f7-4585-83ab-1ec49cc40fc2'::uuid),
