      ('CHUMBO','885cd2ff-9854-4382-beec-fc5a9e904c34'::uuid),
      ('PRATA FOSCO','65f4ed80-89ae-4ec6-9e3a-8513f3d89dd6'::uuid),
      ('FOSCO','beb6fa6a-eca8-4b9e-b861-b4a12c2c0020'::uuid),
      ('VINHO','8e9984bf-0139-42ed-aa2a-26eb6a121aed'::uuid),    -- ← NOVO
      ('BRONZE','b4feaacd-2442-4597-bf55-c9c36ea61756'::uuid)    -- ← NOVO: Bronze → Prata (metálico)
    ) AS syn(alias, variation_id)
    WHERE syn.alias = v_name_norm LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  END IF;

  -- P5: Match parcial por nome via color_groups (fallback)
  SELECT cv.id INTO v_id
  FROM public.color_groups cg
  JOIN public.color_variations cv ON cv.color_group_id = cg.id AND cv.is_active = TRUE
  WHERE cg.is_active = TRUE AND v_name_norm IS NOT NULL
    AND v_name_norm LIKE '%' || UPPER(TRIM(cg.name)) || '%'
  ORDER BY CASE WHEN UPPER(TRIM(cv.name)) = UPPER(TRIM(cg.name)) THEN 0 ELSE 1 END,
    cv.sort_order NULLS LAST LIMIT 1;

  RETURN v_id;
END;
$$;


