COMMENT ON FUNCTION "public"."fn_notebook_specs_health"() IS 'Relatório de saúde do módulo material gráfico. Retorna cobertura, fill-rates, alertas e stats de features.';



CREATE OR REPLACE FUNCTION "public"."fn_notify_champions_on_quote_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'vault', 'net'
    AS $$
DECLARE
  _secret  TEXT;
  _url     TEXT;
  _payload JSONB;
  _hmac    TEXT;
  _req_id  BIGINT;
  _log_id  UUID;
  _start   TIMESTAMPTZ;
  _ck      TEXT;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;

  _start := clock_timestamp();
  _ck := NEW.id::text || ':' || NEW.status || ':' || (extract(epoch from clock_timestamp()) * 1000)::bigint::text;

  BEGIN
    SELECT ds.decrypted_secret INTO _url
    FROM vault.decrypted_secrets ds WHERE ds.name = 'CHAMPIONS_RECEIVE_QUOTE_SYNC_URL' LIMIT 1;
    SELECT ds.decrypted_secret INTO _secret
    FROM vault.decrypted_secrets ds WHERE ds.name = 'WEBHOOK_DISPATCHER_SECRET' LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_notify_champions v8: vault error: %', SQLERRM;
    RETURN NEW;
  END;

  IF _url IS NULL OR _secret IS NULL THEN
    RAISE WARNING 'fn_notify_champions v8: URL ou secret NULL';
    RETURN NEW;
  END IF;

  _payload := json_build_object(
    'event',           'quote.' || NEW.status,
    'correlation_key', _ck,
    'payload', json_build_object(
      'quote_id',     NEW.id,
      'quote_number', NEW.quote_number,
      'status',       NEW.status,
      'old_status',   OLD.status,
      'seller_id',    NEW.seller_id,
      'client_id',    NEW.client_id,
      'client_name',  NEW.client_name,
      'total',        NEW.total,
      'event_at',     clock_timestamp()   -- ← v8 FIX: monotônico intra-transação
    )
  )::jsonb;

  _hmac := 'sha256=' || encode(
    extensions.hmac(_payload::text::bytea, _secret::bytea, 'sha256'), 'hex');

  BEGIN
    INSERT INTO public.webhook_dispatcher_log (
      trigger_event, quote_id, quote_status, seller_id,
      target_url, correlation_key, payload_hash, delivery_status, fired_at
    ) VALUES (
      'quote.' || NEW.status, NEW.id, NEW.status, NEW.seller_id,
      regexp_replace(_url, 'https://[^/]+\.supabase\.co', 'https://[REDACTED].supabase.co'),
      _ck,
      encode(extensions.hmac(_payload::text::bytea, 'log-salt'::bytea, 'sha256'), 'hex'),
      'pending', _start
    ) RETURNING id INTO _log_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_notify_champions v8: pre-log error: %', SQLERRM;
  END;

  BEGIN
    SELECT net.http_post(
      _url, _payload, '{}'::jsonb,
      json_build_object(
        'Content-Type',        'application/json',
        'x-webhook-signature', _hmac,
        'x-webhook-event',     'quote.' || NEW.status,
        'x-correlation-key',   _ck
      )::jsonb,
      10000
    ) INTO _req_id;

    IF _log_id IS NOT NULL THEN
      UPDATE public.webhook_dispatcher_log
      SET response_body = 'pg_net_request_id=' || _req_id::text,
          delivery_status = 'delivered',
          responded_at = clock_timestamp(),
          duration_ms = EXTRACT(EPOCH FROM (clock_timestamp() - _start)) * 1000
      WHERE id = _log_id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_notify_champions v8: http_post error quote %: %', NEW.id, SQLERRM;
    IF _log_id IS NOT NULL THEN
      BEGIN
        UPDATE public.webhook_dispatcher_log
        SET delivery_status = 'failed', error_message = SQLERRM,
            responded_at = clock_timestamp(),
            duration_ms = EXTRACT(EPOCH FROM (clock_timestamp() - _start)) * 1000
        WHERE id = _log_id;
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;
  END;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_notify_champions v8: outer error quote %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_notify_champions_on_quote_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_notify_user"("_target_user_id" "uuid", "_title" "text", "_message" "text", "_type" "text" DEFAULT 'info'::"text", "_category" "text" DEFAULT 'system'::"text", "_action_url" "text" DEFAULT NULL::"text", "_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _notification_id uuid;
  _caller_id uuid;
BEGIN
  _caller_id := auth.uid();
  
  -- Deve ser chamada por usuário autenticado
  IF _caller_id IS NULL THEN
    RAISE EXCEPTION 'fn_notify_user: authentication required'
      USING ERRCODE = '42501';
  END IF;
  
  -- Target user deve existir
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = _target_user_id) THEN
    RAISE EXCEPTION 'fn_notify_user: target user does not exist'
      USING ERRCODE = 'P0001';
  END IF;
  
  -- Validar type
  IF _type NOT IN ('info', 'success', 'warning', 'error') THEN
    RAISE EXCEPTION 'fn_notify_user: invalid type %', _type
      USING ERRCODE = 'P0001';
  END IF;
  
  -- Inserir a notificação (bypassa RLS via SECURITY DEFINER)
  INSERT INTO public.workspace_notifications (
    user_id, title, message, type, category, action_url, metadata
  )
  VALUES (
    _target_user_id, _title, _message, _type, _category, _action_url, _metadata
  )
  RETURNING id INTO _notification_id;
  
  RETURN _notification_id;
END;
$$;


ALTER FUNCTION "public"."fn_notify_user"("_target_user_id" "uuid", "_title" "text", "_message" "text", "_type" "text", "_category" "text", "_action_url" "text", "_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_notify_user"("_target_user_id" "uuid", "_title" "text", "_message" "text", "_type" "text", "_category" "text", "_action_url" "text", "_metadata" "jsonb") IS 'Envia notificação para qualquer usuário do sistema (cross-user). SECURITY DEFINER: bypassa RLS de workspace_notifications. Valida: caller autenticado, target_user_id existe, type é enum válido. Para uso no frontend e edge functions quando o caller ≠ target.';



CREATE OR REPLACE FUNCTION "public"."fn_order_items_calc_subtotal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  NEW.subtotal := COALESCE(NEW.quantity, 0) * COALESCE(NEW.unit_price, 0)
                + COALESCE(NEW.personalization_cost, 0)
                - COALESCE(NEW.discount_amount, 0);
  RETURN NEW;
END $$;


