 Resolve pad_id (link para produto-pai) e color_id (cor canônica).
 fix_version: padvar-sync-color-resolution-2026-07-03
 ANTI-REGRESSÃO: não remover o bloco de auto-resolve color_id.';



CREATE OR REPLACE FUNCTION "public"."fn_parse_asia_properties"("p_propriedades" "jsonb", "p_api_altura" numeric DEFAULT 0, "p_api_largura" numeric DEFAULT 0, "p_api_comprimento" numeric DEFAULT 0, "p_api_peso" numeric DEFAULT 0, "p_origem_faturamento" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_result JSONB;
    v_height_cm NUMERIC;
    v_width_cm NUMERIC;
    v_length_cm NUMERIC;
    v_weight_g INTEGER;
    v_box_weight_kg NUMERIC;
    v_box_quantity INTEGER;
    v_box_length_cm NUMERIC;
    v_box_width_cm NUMERIC;
    v_box_height_cm NUMERIC;
    v_packing_type TEXT;
    v_capacity_ml INTEGER;
    v_raw TEXT;
    v_match TEXT[];
    v_num_str TEXT;
BEGIN
    -- ========================================
    -- 1. DIMENSÕES DO PRODUTO
    -- ========================================
    IF p_api_altura > 0 AND p_api_largura > 0 THEN
        v_height_cm := p_api_altura;
        v_width_cm := p_api_largura;
        v_length_cm := NULLIF(p_api_comprimento, 0);
    ELSE
        v_raw := COALESCE(
            NULLIF(TRIM(p_propriedades->>'dimensao-produto'), ''),
            NULLIF(TRIM(p_propriedades->>'dimensao-do-produto'), ''),
            NULLIF(TRIM(p_propriedades->>'medidas-do-produto'), ''),
            NULLIF(TRIM(p_propriedades->>'dimensao'), '')
        );
        IF v_raw IS NOT NULL THEN
            v_raw := REGEXP_REPLACE(v_raw, '\s*\(.*?\)', '', 'g');
            v_raw := REGEXP_REPLACE(v_raw, 'cm$', '', 'i');
            v_raw := TRIM(v_raw);
            IF v_raw ~ '[øØ]' THEN
                v_match := REGEXP_MATCH(v_raw, '^([\d.,]+)\s*[xX×]\s*[øØ]?\s*([\d.,]+)');
                IF v_match IS NOT NULL THEN
                    v_height_cm := REPLACE(v_match[1], ',', '.')::NUMERIC;
                    v_width_cm := REPLACE(v_match[2], ',', '.')::NUMERIC;
                    v_length_cm := v_width_cm;
                END IF;
            ELSE
                v_match := REGEXP_MATCH(v_raw, '^([\d.,]+)\s*[xX×]\s*([\d.,]+)\s*[xX×]\s*([\d.,]+)');
                IF v_match IS NOT NULL THEN
                    v_height_cm := REPLACE(v_match[1], ',', '.')::NUMERIC;
                    v_width_cm := REPLACE(v_match[2], ',', '.')::NUMERIC;
                    v_length_cm := REPLACE(v_match[3], ',', '.')::NUMERIC;
                ELSE
                    v_match := REGEXP_MATCH(v_raw, '^([\d.,]+)\s*[xX×]\s*([\d.,]+)');
                    IF v_match IS NOT NULL THEN
                        v_height_cm := REPLACE(v_match[1], ',', '.')::NUMERIC;
                        v_width_cm := REPLACE(v_match[2], ',', '.')::NUMERIC;
                    END IF;
                END IF;
            END IF;
        END IF;
    END IF;
    IF v_height_cm IS NOT NULL AND v_width_cm IS NOT NULL AND v_length_cm IS NULL THEN
        v_length_cm := v_width_cm;
    END IF;

    -- ========================================
    -- 2. PESO DO PRODUTO
    -- FIX v3: Detecta "g" vs "kg" via POSIX regex
    -- Regra: se contém "kg" → quilos | se contém "g" sem "k" → gramas | senão → assume kg
    -- ========================================
    IF p_api_peso > 0 THEN
        v_weight_g := ROUND(p_api_peso * 1000)::INTEGER;
    ELSE
        v_raw := COALESCE(
            NULLIF(TRIM(p_propriedades->>'peso-do-produto'), ''),
            NULLIF(TRIM(p_propriedades->>'peso-produto'), ''),
            NULLIF(TRIM(p_propriedades->>'peso'), ''),
            NULLIF(TRIM(p_propriedades->>'peso-caneta'), ''),
            NULLIF(TRIM(p_propriedades->>'peso-do-chaveiro'), '')
        );
        IF v_raw IS NOT NULL THEN
            v_raw := LOWER(TRIM(v_raw));
            v_raw := REGEXP_REPLACE(v_raw, '\s*\(.*?\)', '', 'g');
            v_match := REGEXP_MATCH(v_raw, '^([\d.,]+)');
            IF v_match IS NOT NULL THEN
                v_num_str := REPLACE(v_match[1], ',', '.');
                BEGIN
                    IF v_raw ~ 'kg' THEN
                        -- Explicitamente kg → converter para gramas
                        v_weight_g := ROUND(v_num_str::NUMERIC * 1000)::INTEGER;
                    ELSIF v_raw ~ 'g' THEN
                        -- Só "g" (sem k) → já está em gramas
                        v_weight_g := ROUND(v_num_str::NUMERIC)::INTEGER;
                    ELSE
                        -- Sem unidade → assume kg (padrão Asia)
                        v_weight_g := ROUND(v_num_str::NUMERIC * 1000)::INTEGER;
                    END IF;
                EXCEPTION WHEN OTHERS THEN
                    v_weight_g := NULL;
                END;
            END IF;
        END IF;
    END IF;

    -- ========================================
    -- 3. BOX WEIGHT
    -- FIX v3: Detecta "g" vs "kg" via POSIX regex
    -- "885g" → 0.885kg | "8.85kg" → 8.85kg | "9,5kgs" → 9.5kg
    -- ========================================
    v_raw := COALESCE(
        NULLIF(TRIM(p_propriedades->>'peso-da-caixa'), ''),
        NULLIF(TRIM(p_propriedades->>'peso-caixa'), '')
    );
    IF v_raw IS NOT NULL THEN
        v_raw := LOWER(TRIM(v_raw));
        v_raw := REGEXP_REPLACE(v_raw, '\s*\(.*?\)', '', 'g');
        v_raw := REGEXP_REPLACE(v_raw, '\s*\*.*', '', 'g');
        v_match := REGEXP_MATCH(v_raw, '^([\d.,]+)');
        IF v_match IS NOT NULL THEN
            v_num_str := v_match[1];
            
            -- Parse do número (vírgula/ponto)
            IF v_num_str ~ '\.' AND v_num_str ~ ',' THEN
                v_num_str := REPLACE(REPLACE(v_num_str, '.', ''), ',', '.');
            ELSIF v_num_str ~ ',' THEN
                v_num_str := REPLACE(v_num_str, ',', '.');
            END IF;
            
            BEGIN
                IF v_raw ~ 'kg' THEN
                    -- Explicitamente kg
                    v_box_weight_kg := ROUND(v_num_str::NUMERIC, 3);
                ELSIF v_raw ~ 'g' THEN
                    -- Só "g" (sem k) → converter gramas para kg
                    v_box_weight_kg := ROUND(v_num_str::NUMERIC / 1000, 3);
                ELSE
                    -- Sem unidade → assume kg
                    v_box_weight_kg := ROUND(v_num_str::NUMERIC, 3);
                END IF;
            EXCEPTION WHEN OTHERS THEN
                v_box_weight_kg := NULL;
            END;
        END IF;
    END IF;

    -- ========================================
    -- 4. BOX QUANTITY
    -- ========================================
    v_raw := COALESCE(
        NULLIF(TRIM(p_propriedades->>'quant-por-caixa'), ''),
        NULLIF(TRIM(p_propriedades->>'quantidade-por-caixa'), ''),
        NULLIF(TRIM(p_propriedades->>'qtde-por-caixa'), ''),
        NULLIF(TRIM(p_propriedades->>'quant-da-caixa'), ''),
        NULLIF(TRIM(p_propriedades->>'qtde-caixa'), '')
    );
    IF v_raw IS NOT NULL THEN
        v_raw := REGEXP_REPLACE(v_raw, '\s*\(.*?\)', '', 'g');
        v_match := REGEXP_MATCH(v_raw, '^([\d.]+)');
        IF v_match IS NOT NULL THEN
            BEGIN
                v_box_quantity := REPLACE(v_match[1], '.', '')::INTEGER;
            EXCEPTION WHEN OTHERS THEN
                v_box_quantity := NULL;
            END;
        END IF;
    END IF;

    -- ========================================
    -- 5. BOX DIMENSIONS
    -- ========================================
    v_raw := COALESCE(
        NULLIF(TRIM(p_propriedades->>'dimensao-da-caixa'), ''),
        NULLIF(TRIM(p_propriedades->>'dimensao-caixa'), ''),
        NULLIF(TRIM(p_propriedades->>'tamanho-da-caixa'), ''),
        NULLIF(TRIM(p_propriedades->>'medidas-da-caixa'), ''),
        NULLIF(TRIM(p_propriedades->>'dimensao-por-caixa'), '')
    );
    IF v_raw IS NOT NULL THEN
        v_raw := REGEXP_REPLACE(LOWER(TRIM(v_raw)), 'cm', '', 'gi');
        v_raw := REGEXP_REPLACE(v_raw, '\s*\(.*?\)', '', 'g');
        v_match := REGEXP_MATCH(v_raw, '^([\d.,]+)\s*[xX×]\s*([\d.,]+)\s*[xX×]\s*([\d.,]+)');
        IF v_match IS NOT NULL THEN
            BEGIN
                v_box_length_cm := ROUND(REPLACE(v_match[1], ',', '.')::NUMERIC, 2);
                v_box_width_cm := ROUND(REPLACE(v_match[2], ',', '.')::NUMERIC, 2);
                v_box_height_cm := ROUND(REPLACE(v_match[3], ',', '.')::NUMERIC, 2);
            EXCEPTION WHEN OTHERS THEN
                v_box_length_cm := NULL; v_box_width_cm := NULL; v_box_height_cm := NULL;
            END;
        END IF;
    END IF;

    -- ========================================
    -- 6. PACKING TYPE
    -- ========================================
    v_packing_type := NULLIF(TRIM(p_propriedades->>'embalagem'), '');

    -- ========================================
    -- 7. CAPACITY ML
    -- ========================================
    v_raw := NULLIF(TRIM(p_propriedades->>'capacidade'), '');
    IF v_raw IS NOT NULL THEN
        v_match := REGEXP_MATCH(LOWER(v_raw), '^(\d+)\s*ml');
        IF v_match IS NOT NULL THEN
            v_capacity_ml := v_match[1]::INTEGER;
        END IF;
    END IF;

    -- ========================================
    -- 8. RESULTADO
    -- ========================================
    RETURN jsonb_build_object(
        'height_cm', v_height_cm, 'width_cm', v_width_cm, 'length_cm', v_length_cm,
        'weight_g', v_weight_g,
        'box_weight_kg', v_box_weight_kg, 'box_quantity', v_box_quantity,
        'box_length_cm', v_box_length_cm, 'box_width_cm', v_box_width_cm, 'box_height_cm', v_box_height_cm,
        'packing_type', v_packing_type, 'tax_reference_state', p_origem_faturamento,
        'capacity_ml', v_capacity_ml,
        'source', CASE 
            WHEN p_api_altura > 0 THEN 'api_root' 
            WHEN v_height_cm IS NOT NULL THEN 'propriedades_fallback'
            ELSE 'no_data'
        END
    );
END;
$_$;


ALTER FUNCTION "public"."fn_parse_asia_properties"("p_propriedades" "jsonb", "p_api_altura" numeric, "p_api_largura" numeric, "p_api_comprimento" numeric, "p_api_peso" numeric, "p_origem_faturamento" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_parse_asia_properties"("p_propriedades" "jsonb", "p_api_altura" numeric, "p_api_largura" numeric, "p_api_comprimento" numeric, "p_api_peso" numeric, "p_origem_faturamento" "text") IS 'Parser de propriedades da API Asia Import. Extrai dimensões do produto (com fallback), box data, peso, embalagem e origem. Corrige bug do ponto decimal no peso da caixa. Aplica regra 2D (length=width) quando só tem 2 dimensões.';



CREATE OR REPLACE FUNCTION "public"."fn_parse_binding_color_code"("p_description" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_desc text := lower(coalesce(p_description,''));
BEGIN
  -- Só detectar cor de espiral quando há CONTEXTO explícito de encadernação
  -- Padrões: "espiral preto", "wire-o prata", "encadernação espiral branca", 
  --           "espiral em prata", "wire-o em preto"
  IF v_desc ~ '(?i)(espiral|wire.?o|encadernação).{0,30}(pret[ao]|negr[ao])'
     OR v_desc ~ '(?i)(pret[ao]|negr[ao]).{0,30}(espiral|wire.?o)' THEN RETURN 'BLACK'; END IF;

  IF v_desc ~ '(?i)(espiral|wire.?o|encadernação).{0,30}(prat[ao]|prateado|inox|cinza metálico|alumín)'
     OR v_desc ~ '(?i)(prat[ao]|prateado|inox).{0,30}(espiral|wire.?o)' THEN RETURN 'SILVER'; END IF;

  IF v_desc ~ '(?i)(espiral|wire.?o|encadernação).{0,30}(dourad[ao]|gold|golden)'
     OR v_desc ~ '(?i)(dourad[ao]|gold).{0,30}(espiral|wire.?o)' THEN RETURN 'GOLD'; END IF;

  IF v_desc ~ '(?i)(espiral|wire.?o|encadernação).{0,30}(branc[ao]|white)'
     OR v_desc ~ '(?i)(branc[ao]|white).{0,30}(espiral|wire.?o)' THEN RETURN 'WHITE'; END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_parse_binding_color_code"("p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parse_binding_type_code"("p_name" "text", "p_description" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_all text := lower(coalesce(p_name,'') || ' ' || coalesce(p_description,''));
BEGIN
  IF v_all ILIKE ANY(ARRAY['%wire-o%','%wire o%','%wire_o%','%wiire%']) THEN RETURN 'WIRE_O'; END IF;
  IF v_all ILIKE '%espiral%' OR v_all ILIKE '%spiral%' THEN RETURN 'SPIRAL'; END IF;
  IF v_all ILIKE ANY(ARRAY['%argolas%','%fichário%','%ring bound%','%ring-bound%']) THEN RETURN 'RING'; END IF;
  -- costurado/costurada
  IF v_all ILIKE '%costurad%' OR v_all ILIKE '%sewn%' OR v_all ILIKE '%stitched%' THEN RETURN 'SEWN'; END IF;
  -- grampo/grampeado/grampeada
  IF v_all ILIKE ANY(ARRAY['%gramp%','%canoa%','%saddle%']) THEN RETURN 'SADDLE'; END IF;
  IF v_all ILIKE '%brochura%' OR v_all ILIKE '%lombada quadrada%' OR v_all ILIKE '%perfect bound%' THEN RETURN 'PERFECT'; END IF;
  IF v_all ILIKE '%disco%' OR v_all ILIKE '%disc bound%' THEN RETURN 'DISC'; END IF;
  -- Capa dura sem argolas → CASE
  IF v_all ILIKE '%capa dura%' AND v_all NOT ILIKE '%espiral%' AND v_all NOT ILIKE '%wire%' THEN
    RETURN 'CASE';
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_parse_binding_type_code"("p_name" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parse_capacity_ml"("p_capacity" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_input TEXT;
    v_part TEXT;
    v_parts TEXT[];
    v_value DECIMAL;
    v_unit TEXT;
    v_result INT;
    v_max_result INT := NULL;
BEGIN
    IF p_capacity IS NULL OR TRIM(p_capacity) = '' THEN
        RETURN NULL;
    END IF;

    -- PATCH M3 2026-06-11: vírgula decimal BR ("1,5 L"→1.5 L) convertida ANTES
    -- do split multivalor. Só converte (\d),(\d{1,2}) imediatamente seguido de
    -- unidade de volume — preserva separador multivalor ("400 mL, 550mL", a
    -- vírgula é precedida de letra) e milhar de 3 dígitos ("2,250 mL", \d{1,2}
    -- não casa 3 dígitos com unidade logo após).
    v_input := REGEXP_REPLACE(p_capacity, '(\d),(\d{1,2})(\s*(?:ml|l|litros?)\M)', '\1.\2\3', 'gi');

    v_parts := string_to_array(v_input, ',');

    FOREACH v_part IN ARRAY v_parts
    LOOP
        v_part := TRIM(v_part);
        IF v_part = '' THEN CONTINUE; END IF;

        v_value := fn_extract_numeric(v_part);
        IF v_value IS NULL THEN CONTINUE; END IF;

        v_unit := LOWER(v_part);

        IF v_unit LIKE '%ml%' OR v_unit LIKE '%mililitro%' THEN
            v_result := v_value::INT;
        ELSIF v_unit ~ '(litros?|\dl\s*$|\dl$|\d\s+l\s*$|\d\s+l\s)' THEN
            v_result := (v_value * 1000)::INT;
        ELSIF v_unit LIKE '%gal%' THEN
            v_result := (v_value * 3785.41)::INT;
        ELSE
            v_result := v_value::INT;
        END IF;

        IF v_max_result IS NULL OR v_result > v_max_result THEN
            v_max_result := v_result;
        END IF;
    END LOOP;

    RETURN v_max_result;
END;
$_$;


ALTER FUNCTION "public"."fn_parse_capacity_ml"("p_capacity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_parse_capacity_ml"("p_capacity" "text") IS 'Converte string de capacidade para mililitros';



CREATE OR REPLACE FUNCTION "public"."fn_parse_composite_material"("material_string" "text") RETURNS TABLE("material_part" "text", "sort_order" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_working_string TEXT;
    v_parts TEXT[];
    v_part TEXT;
    v_counter INT := 0;
BEGIN
    IF material_string IS NULL OR trim(material_string) = '' THEN
        RETURN;
    END IF;
    
    v_working_string := trim(material_string);
    
    -- Proteger "C. sintético" (é unidade única, não separar)
    v_working_string := regexp_replace(v_working_string, 'C\.\s*sint[ée]tico', '@@COURO_SINTETICO@@', 'gi');
    v_working_string := regexp_replace(v_working_string, 'c\.\s*sint[ée]tico', '@@COURO_SINTETICO@@', 'gi');
    
    -- Proteger gramaturas (não são separadores)
    v_working_string := regexp_replace(v_working_string, '(\d+)\s*g/m²', '\1@@GRAMATURA@@', 'g');
    v_working_string := regexp_replace(v_working_string, '(\d+)\s*g/m2', '\1@@GRAMATURA@@', 'gi');
    
    -- Normalizar separadores: ". " e " e " viram @@SEP@@
    v_working_string := regexp_replace(v_working_string, '\.\s+', '@@SEP@@', 'g');
    v_working_string := regexp_replace(v_working_string, '\s+e\s+', '@@SEP@@', 'gi');
    
    -- Dividir em partes
    v_parts := string_to_array(v_working_string, '@@SEP@@');
    
    FOREACH v_part IN ARRAY v_parts
    LOOP
        v_part := trim(v_part);
        
        IF v_part = '' OR v_part IS NULL THEN
            CONTINUE;
        END IF;
        
        -- Ignorar se for só gramatura isolada
        IF v_part ~ '^[\d\s]+@@GRAMATURA@@$' THEN
            CONTINUE;
        END IF;
        
        IF length(v_part) < 2 THEN
            CONTINUE;
        END IF;
        
        -- Restaurar padrões protegidos
        v_part := regexp_replace(v_part, '@@COURO_SINTETICO@@', 'Couro Sintético', 'g');
        v_part := regexp_replace(v_part, '@@GRAMATURA@@', ' g/m²', 'g');
        
        -- Remover percentuais no início (ex: "100% algodão" → "algodão")
        v_part := regexp_replace(v_part, '^\d+%\s*', '', 'g');
        
        -- Limpar espaços extras
        v_part := trim(regexp_replace(v_part, '\s+', ' ', 'g'));
        
        IF v_part = '' OR v_part IS NULL THEN
            CONTINUE;
        END IF;
        
        v_counter := v_counter + 1;
        material_part := v_part;
        sort_order := v_counter;
        RETURN NEXT;
    END LOOP;
END;
$_$;


ALTER FUNCTION "public"."fn_parse_composite_material"("material_string" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parse_cover_material_code"("p_materials" "jsonb", "p_name" "text", "p_description" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mat_lower   text;
  v_pname       text := lower(coalesce(p_name,''));
  v_desc        text := lower(coalesce(p_description,''));
  v_has_papel   boolean := false;   -- "Papel", "Papelão", "Cartão"
  v_has_plastic boolean := false;   -- "Plástico" genérico
  v_has_rpet    boolean := false;   -- "Plástico - rPET" ou similar
  v_desc_result text;
BEGIN
  -- ── PRIORIDADE 1: materials jsonb ─────────────────────────────
  IF p_materials IS NOT NULL
     AND jsonb_typeof(p_materials) = 'array'
     AND jsonb_array_length(p_materials) > 0
  THEN
    FOR v_mat_lower IN
      SELECT lower(elem) FROM jsonb_array_elements_text(p_materials) AS t(elem)
    LOOP
      IF v_mat_lower IS NULL OR v_mat_lower = '' THEN CONTINUE; END IF;
      -- Específicos — retornar imediatamente
      IF v_mat_lower ILIKE '%pele reciclada%' OR v_mat_lower ILIKE '%couro reciclado%' THEN RETURN 'RECYCLED_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%pu à base de água%' THEN RETURN 'PU_WATER'; END IF;
      IF v_mat_lower ILIKE '%couro legítimo%' OR v_mat_lower ILIKE '%couro natural%' THEN RETURN 'GENUINE_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%couro sintético%' OR v_mat_lower ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%polipele%' THEN RETURN 'POLYLEATHER'; END IF;
      IF v_mat_lower ~ '(?i)\bpu\b' AND v_mat_lower NOT ILIKE '%plástico%' THEN RETURN 'PU'; END IF;
      -- rPET: detectar ANTES de retornar PLASTIC genérico
      IF v_mat_lower ILIKE '%rpet%' OR v_mat_lower ILIKE '%r-pet%' OR v_mat_lower ILIKE '%pet reciclado%' THEN
        v_has_rpet := true; CONTINUE;
      END IF;
      IF v_mat_lower ILIKE '%cortiça%' OR v_mat_lower ILIKE '%cork%' THEN RETURN 'CORK'; END IF;
      IF v_mat_lower ILIKE '%bambu%' OR v_mat_lower ILIKE '%bamboo%' THEN RETURN 'BAMBOO'; END IF;
      IF v_mat_lower ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
      IF v_mat_lower = 'borracha' OR v_mat_lower ILIKE 'emborrachad%' THEN RETURN 'RUBBER'; END IF;
      IF v_mat_lower ILIKE '%linho%' OR v_mat_lower ILIKE '%linen%' THEN RETURN 'LINEN'; END IF;
      -- Tecido/fabric: verificar que não é plástico ecológico
      IF v_mat_lower ILIKE '%tecido%' OR v_mat_lower ILIKE '%poliéster%' OR v_mat_lower ILIKE '%algodão%' OR v_mat_lower ILIKE '%feltro%' THEN RETURN 'FABRIC'; END IF;
      IF v_mat_lower ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;
      IF v_mat_lower ILIKE '%couchê%' OR v_mat_lower ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
      -- Polipropileno e plásticos específicos (PP, PVC) = PLASTIC direto
      IF v_mat_lower ILIKE '%polipropileno%' OR v_mat_lower ILIKE '%(pp)%' OR v_mat_lower ILIKE '%pvc%' THEN RETURN 'PLASTIC'; END IF;
      -- Papel/Papelão/Cartão = fallback (material interno, não capa específica)
      IF v_mat_lower ILIKE '%papel%' OR v_mat_lower ILIKE '%papelão%' OR v_mat_lower ILIKE '%cartão%' OR v_mat_lower ILIKE '%cardboard%' THEN
        v_has_papel := true; CONTINUE;
      END IF;
      -- Plástico genérico = fallback também (Asia usa "Plástico" para materiais mistos)
      IF v_mat_lower ILIKE '%plástico%' OR v_mat_lower ILIKE '%plastic%' THEN
        v_has_plastic := true; CONTINUE;
      END IF;
    END LOOP;
    -- rPET foi encontrado (sem outro material específico mais prioritário)
    IF v_has_rpet THEN RETURN 'RPET'; END IF;
  END IF;

  -- ── PRIORIDADE 2: Nome do produto ─────────────────────────────
  IF v_pname ILIKE '%couro sintético%' OR v_pname ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
  IF v_pname ILIKE '%cortiça%' THEN RETURN 'CORK'; END IF;
  IF v_pname ILIKE '%bambu%' THEN RETURN 'BAMBOO'; END IF;
  IF v_pname ILIKE '%rpet%' THEN RETURN 'RPET'; END IF;
  IF v_pname ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
  IF v_pname ILIKE '%emborrachad%' THEN RETURN 'RUBBER'; END IF;
  IF v_pname ILIKE '%linho%' THEN RETURN 'LINEN'; END IF;
  IF v_pname ILIKE '%couchê%' OR v_pname ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
  IF v_pname ~ '(?i)\bpu\b' OR v_pname ILIKE '% em pu' OR v_pname ILIKE '%caderneta pu%' THEN RETURN 'PU'; END IF;
  IF v_pname ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;
  IF v_pname ILIKE '%feltro%' THEN RETURN 'FABRIC'; END IF;

  -- ── PRIORIDADE 3: Descrição (contexto de capa) — sempre antes dos fallbacks ─
  v_desc_result := NULL;
  IF    v_desc ILIKE '%capa%couro sintético%' OR v_desc ILIKE '%couro sintético%capa%' THEN v_desc_result := 'SYNTHETIC_LEATHER';
  ELSIF v_desc ILIKE '%capa dura em pu%' OR v_desc ILIKE '%capa em pu%' OR v_desc ILIKE '%em pu%capa%' THEN v_desc_result := 'PU';
  ELSIF v_desc ILIKE '%capa%cortiça%' THEN v_desc_result := 'CORK';
  ELSIF v_desc ILIKE '%capa%bambu%' THEN v_desc_result := 'BAMBOO';
  ELSIF v_desc ILIKE '%capa%rpet%' OR v_desc ILIKE '%rpet%capa%' OR v_desc ILIKE '%tecido rpet%' THEN v_desc_result := 'RPET';
  ELSIF v_desc ILIKE '%capa%percalux%' THEN v_desc_result := 'PERCALUX';
  ELSIF v_desc ILIKE '%capa%borracha%' AND v_desc NOT ILIKE '%borracha na ponta%' AND v_desc NOT ILIKE '%lápis%borracha%' THEN v_desc_result := 'RUBBER';
  ELSIF v_desc ILIKE '%capa%linho%' OR v_desc ILIKE '%capa%feltro%' THEN v_desc_result := 'FABRIC';
  ELSIF v_desc ILIKE '%capa%kraft%' THEN v_desc_result := 'KRAFT';
  ELSIF v_desc ILIKE '%capa%plástico%' OR v_desc ILIKE '%capa dura cartonada%' OR v_desc ILIKE '%cartonada%' THEN v_desc_result := 'CARDBOARD';
  ELSIF v_desc ILIKE '%capa%papelão%' OR v_desc ILIKE '%papelão reciclado%' THEN v_desc_result := 'CARDBOARD';
  ELSIF v_desc ILIKE '%couro reciclado%' OR v_desc ILIKE '%pele reciclada%' THEN v_desc_result := 'RECYCLED_LEATHER';
  END IF;
  IF v_desc_result IS NOT NULL THEN RETURN v_desc_result; END IF;

  -- ── FALLBACK 1: Papel/Papelão/Cartão ──────────────────────────
  IF v_has_papel THEN RETURN 'CARDBOARD'; END IF;
  -- ── FALLBACK 2: Plástico genérico ─────────────────────────────
  IF v_has_plastic THEN RETURN 'PLASTIC'; END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_parse_cover_material_code"("p_materials" "jsonb", "p_name" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parse_cover_type_code"("p_name" "text", "p_description" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_all text := lower(coalesce(p_name,'') || ' ' || coalesce(p_description,''));
BEGIN
  -- Semi-rígida (antes de HARD para não pegar "dura" de semi-rígida)
  IF v_all ILIKE '%semi%rígida%' OR v_all ILIKE '%semi rígida%' THEN RETURN 'SEMI'; END IF;
  -- HARD
  IF v_all ILIKE ANY(ARRAY[
    '%capa dura%','%capa rígida%','%hard cover%','%hardcover%',
    '%cartonada%','%capa dura%'
  ]) THEN RETURN 'HARD'; END IF;
  -- SOFT
  IF v_all ILIKE ANY(ARRAY[
    '%capa flexível%','%capa mole%','%soft cover%','%softcover%',
    '%capa flex%'
  ]) THEN RETURN 'SOFT'; END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_parse_cover_type_code"("p_name" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parse_ficha_tecnica_text"("p_product_sku" "text", "p_text" "text", "p_source_url" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'xbz_ficha'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE m text[]; lbl text; n int := 0;
BEGIN
  IF p_text IS NULL OR btrim(p_text)='' THEN RETURN 0; END IF;
  FOR m IN
    SELECT regexp_match(
             line,
             '^(.*?)([0-9]+(?:,[0-9]+)?)\s*cm\s*[x×]\s*([0-9]+(?:,[0-9]+)?)\s*cm(?:\s*[x×]\s*([0-9]+(?:,[0-9]+)?)\s*cm)?',
             'i')
    FROM regexp_split_to_table(replace(p_text, E'\r',''), E'\n') AS line
    WHERE line ~* '[0-9]\s*cm\s*[x×]\s*[0-9]'   -- tem medida cm x cm
      AND line !~* 'grava'                       -- NAO e area de gravacao
      AND line !~* 'aproxim.{0,6}para'           -- "aproximadas para gravacao"
  LOOP
    IF m IS NULL THEN CONTINUE; END IF;
    lbl := m[1];
    lbl := regexp_replace(lbl, '\(.*?\)', '', 'g');                                  -- remove (A x L), (CxL)...
    lbl := regexp_replace(lbl, '(?i)^\s*medidas?\s+(da\s+|de\s+|do\s+|das\s+|dos\s+)?', ''); -- "Medidas (da/de..)"
    lbl := regexp_replace(lbl, '^[\s\-*•\d.|>#]+', '');                               -- bullets/numeros/markdown no inicio
    lbl := regexp_replace(lbl, '[*_:|]+', ' ', 'g');                                  -- markdown/colon
    lbl := btrim(regexp_replace(lbl, '\s+', ' ', 'g'), ' -');
    CONTINUE WHEN lbl IS NULL OR length(lbl) < 2 OR length(lbl) > 60;
    CONTINUE WHEN lbl ~* '^(peso|volume|capacidade|conteudo|conteúdo|cor|cores|material|garantia|composic|composiç|dimens)';
    INSERT INTO kit_component_ficha_staging
      (product_sku, piece_label, dim_a_mm, dim_l_mm, dim_p_mm, raw_text, source, source_url)
    VALUES (
      p_product_sku, lbl,
      round(replace(m[2],',','.')::numeric*10)::int,
      round(replace(m[3],',','.')::numeric*10)::int,
      CASE WHEN m[4] IS NOT NULL THEN round(replace(m[4],',','.')::numeric*10)::int END,
      lbl||': '||m[2]||' cm x '||m[3]||' cm'||COALESCE(' x '||m[4]||' cm',''),
      p_source, p_source_url
    );
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;


ALTER FUNCTION "public"."fn_parse_ficha_tecnica_text"("p_product_sku" "text", "p_text" "text", "p_source_url" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parse_kit_page_dimensions"("p_kit_product_id" "uuid", "p_page_html" "text", "p_source_url" "text", "p_supplier_code" "text", "p_confidence" numeric DEFAULT 0.75) RETURNS TABLE("component_id" "uuid", "component_name" "text", "dims_found" "text", "raw_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_comp     RECORD;
  v_pattern  TEXT;
  v_matches  TEXT[];
  v_raw_id   UUID;
  v_len_mm   INTEGER; v_wid_mm INTEGER; v_hgt_mm INTEGER;
  v_unit     TEXT;
  v_found    TEXT;
BEGIN
  -- Para cada componente do kit
  FOR v_comp IN
    SELECT pkc.id, pkc.component_name, pkc.is_packaging, pkc.kit_product_id
    FROM product_kit_components pkc
    WHERE pkc.kit_product_id = p_kit_product_id
      AND pkc.enrichment_status = 'missing'
  LOOP
    v_found := NULL;
    v_len_mm := NULL; v_wid_mm := NULL; v_hgt_mm := NULL;

    -- Buscar o nome do componente no texto (case-insensitive, partial)
    -- Extrair dimensões na mesma linha/próxima linha
    -- Padrão XBZ: "Faca 40,3 cm x 2,4 cm" ou "Faca: 40.3 x 2.4 cm"
    -- Padrão SóMarcas: "Faca: 30 x 2 cm" ou "30x2x0,5 cm"
    v_matches := REGEXP_MATCH(p_page_html,
      '(?i)' || REGEXP_REPLACE(v_comp.component_name, '[^a-zA-Z0-9À-ú\s]', '.', 'g')
      || '[^0-9\n]{0,60}?(\d+[,.]?\d*)\s*(cm|mm)\s*[xXÃ—×]\s*(\d+[,.]?\d*)\s*(cm|mm)(?:\s*[xXÃ—×]\s*(\d+[,.]?\d*)\s*(cm|mm))?',
      'gi'
    );

    IF v_matches IS NULL THEN
      -- Tentar com apenas as primeiras palavras do nome
      DECLARE v_partial TEXT := (REGEXP_MATCH(v_comp.component_name, '^\S+'))[1];
      BEGIN
        IF v_partial IS NOT NULL AND LENGTH(v_partial) >= 4 THEN
          v_matches := REGEXP_MATCH(p_page_html,
            '(?i)' || v_partial
            || '[^0-9\n]{0,80}?(\d+[,.]?\d*)\s*(cm|mm)\s*[xXÃ—×]\s*(\d+[,.]?\d*)\s*(cm|mm)',
            'gi'
          );
        END IF;
      END;
    END IF;

    IF v_matches IS NOT NULL THEN
      v_unit := LOWER(v_matches[2]);

      IF v_unit = 'cm' THEN
        v_len_mm := ROUND(REPLACE(v_matches[1], ',', '.')::NUMERIC * 10)::INTEGER;
        v_wid_mm := ROUND(REPLACE(v_matches[3], ',', '.')::NUMERIC * 10)::INTEGER;
        IF v_matches[5] IS NOT NULL THEN
          v_hgt_mm := ROUND(REPLACE(v_matches[5], ',', '.')::NUMERIC * 10)::INTEGER;
        END IF;
      ELSE
        v_len_mm := ROUND(REPLACE(v_matches[1], ',', '.')::NUMERIC)::INTEGER;
        v_wid_mm := ROUND(REPLACE(v_matches[3], ',', '.')::NUMERIC)::INTEGER;
        IF v_matches[5] IS NOT NULL THEN
          v_hgt_mm := ROUND(REPLACE(v_matches[5], ',', '.')::NUMERIC)::INTEGER;
        END IF;
      END IF;

      v_found := v_matches[1] || v_unit || 'x' || v_matches[3] || v_unit;
    END IF;

    IF v_len_mm IS NULL AND v_wid_mm IS NULL THEN
      component_id := v_comp.id; component_name := v_comp.component_name;
      dims_found := 'not_found'; raw_id := NULL;
      RETURN NEXT; CONTINUE;
    END IF;

    INSERT INTO kit_component_enrichment_raw (
      kit_product_id, kit_component_id, raw_component_name,
      source, source_url, source_ref, source_confidence, raw_data
    ) VALUES (
      p_kit_product_id, v_comp.id, v_comp.component_name,
      'site_scraping', p_source_url, p_supplier_code, p_confidence,
      jsonb_strip_nulls(jsonb_build_object(
        'component_name',  v_comp.component_name,
        'unit',            'mm',
        'length_mm',       v_len_mm,
        'width_mm',        v_wid_mm,
        'height_mm',       v_hgt_mm,
        'is_packaging',    v_comp.is_packaging,
        'source_url',      p_source_url
      ))
    ) RETURNING id INTO v_raw_id;

    component_id := v_comp.id; component_name := v_comp.component_name;
    dims_found := v_found; raw_id := v_raw_id;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_parse_kit_page_dimensions"("p_kit_product_id" "uuid", "p_page_html" "text", "p_source_url" "text", "p_supplier_code" "text", "p_confidence" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_parse_kit_page_dimensions"("p_kit_product_id" "uuid", "p_page_html" "text", "p_source_url" "text", "p_supplier_code" "text", "p_confidence" numeric) IS 'Recebe HTML de uma página de kit scrapeada e extrai dimensões por componente via regex.
   Detecta padrão "ComponenteNome X,X cm x Y,Y cm" e insere no bronze.
   Chamada por n8n workflow de scraping após cada fetch de página.';



CREATE OR REPLACE FUNCTION "public"."fn_parse_paper_color_code"("p_tags" "jsonb", "p_description" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_all text := lower(coalesce(p_tags::text,'') || ' ' || coalesce(p_description,''));
BEGIN
  IF v_all ILIKE ANY(ARRAY['%marfim%','%amarelad%','%cor marfim%','%amarelas%','%amber%']) THEN RETURN 'IVORY'; END IF;
  IF v_all ILIKE ANY(ARRAY['%reciclado%','%kraft%','%natural%']) AND v_all ILIKE '%papel%' THEN RETURN 'RECYCLED'; END IF;
  IF v_all ILIKE '%brancas%' OR v_all ILIKE '%folhas brancas%' THEN RETURN 'WHITE'; END IF;
  RETURN NULL;  -- white é o default implícito
END;
$$;


ALTER FUNCTION "public"."fn_parse_paper_color_code"("p_tags" "jsonb", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parse_paper_format"("p_tags" "jsonb", "p_name" "text", "p_description" "text", "p_combined_sizes" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tags  text := lower(coalesce(p_tags::text,''));
  v_name  text := upper(coalesce(p_name,''));
  v_desc  text := lower(coalesce(p_description,''));
  v_sizes text := lower(coalesce(p_combined_sizes,''));
  v_dim   text;
  v_nums  text[];
  v_w_mm  numeric;
  v_h_mm  numeric;
  v_tmp   numeric;
BEGIN
  -- ── Prioridade 1: tags estruturadas ───────────────────────
  IF v_tags ILIKE '%tamanho a3%' THEN RETURN 'A3'; END IF;
  IF v_tags ILIKE '%tamanho a4%' THEN RETURN 'A4'; END IF;
  IF v_tags ILIKE '%tamanho b5%' THEN RETURN 'B5'; END IF;
  IF v_tags ILIKE '%tamanho a5%' THEN RETURN 'A5'; END IF;
  IF v_tags ILIKE '%tamanho a6%' THEN RETURN 'A6'; END IF;
  IF v_tags ILIKE '%tamanho a7%' THEN RETURN 'A7'; END IF;

  -- ── Prioridade 2: nome (word boundary \m...\M) ────────────
  IF v_name ~ '\mA3\M' THEN RETURN 'A3'; END IF;
  IF v_name ~ '\mA4\M' THEN RETURN 'A4'; END IF;
  IF v_name ~ '\mB5\M' THEN RETURN 'B5'; END IF;
  IF v_name ~ '\mA5\M' THEN RETURN 'A5'; END IF;
  IF v_name ~ '\mA6\M' THEN RETURN 'A6'; END IF;
  IF v_name ~ '\mA7\M' THEN RETURN 'A7'; END IF;

  -- ── Prioridade 3: descrição ───────────────────────────────
  IF v_desc ~ '\ma3\M' THEN RETURN 'A3'; END IF;
  IF v_desc ~ '\ma4\M' THEN RETURN 'A4'; END IF;
  IF v_desc ~ '\mb5\M' THEN RETURN 'B5'; END IF;
  IF v_desc ~ '\ma5\M' THEN RETURN 'A5'; END IF;
  IF v_desc ~ '\ma6\M' THEN RETURN 'A6'; END IF;
  IF v_desc ~ '\ma7\M' THEN RETURN 'A7'; END IF;

  -- ── Prioridade 4: combined_sizes por dimensão ─────────────
  -- Pegar primeira parte (antes de '|')
  v_dim := trim(split_part(v_sizes, '|', 1));
  IF length(v_dim) < 3 THEN RETURN NULL; END IF;

  -- Extrair números usando regexp_matches corretamente (m[1] não m)
  SELECT array_agg(m[1]) INTO v_nums
  FROM regexp_matches(v_dim, '(\d+(?:[,\.]\d+)?)', 'g') AS t(m);

  IF v_nums IS NULL OR array_length(v_nums, 1) < 2 THEN RETURN NULL; END IF;

  -- Converter para numérico (tratar vírgula como separador decimal)
  v_w_mm := replace(v_nums[1], ',', '.')::numeric;
  v_h_mm := replace(v_nums[2], ',', '.')::numeric;

  -- Detectar cm vs mm: valores < 50 são provavelmente cm
  IF v_w_mm < 50 THEN v_w_mm := v_w_mm * 10; END IF;
  IF v_h_mm < 50 THEN v_h_mm := v_h_mm * 10; END IF;

  -- Normalizar para portrait (width ≤ height)
  IF v_w_mm > v_h_mm THEN
    v_tmp  := v_w_mm;
    v_w_mm := v_h_mm;
    v_h_mm := v_tmp;
  END IF;

  -- Comparar com dimensões ISO (tolerância ±8mm)
  IF abs(v_w_mm - 297) <= 8 AND abs(v_h_mm - 420) <= 8 THEN RETURN 'A3'; END IF;
  IF abs(v_w_mm - 210) <= 8 AND abs(v_h_mm - 297) <= 8 THEN RETURN 'A4'; END IF;
  IF abs(v_w_mm - 176) <= 8 AND abs(v_h_mm - 250) <= 8 THEN RETURN 'B5'; END IF;
  IF abs(v_w_mm - 148) <= 8 AND abs(v_h_mm - 210) <= 8 THEN RETURN 'A5'; END IF;
  IF abs(v_w_mm - 105) <= 8 AND abs(v_h_mm - 148) <= 8 THEN RETURN 'A6'; END IF;
  IF abs(v_w_mm - 74)  <= 8 AND abs(v_h_mm - 105) <= 8 THEN RETURN 'A7'; END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_parse_paper_format"("p_tags" "jsonb", "p_name" "text", "p_description" "text", "p_combined_sizes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_parse_paper_format"("p_tags" "jsonb", "p_name" "text", "p_description" "text", "p_combined_sizes" "text") IS 'Extrai código de formato de papel (A3-A7, B5) de múltiplas fontes. Retorna NULL se não determinado.';



CREATE OR REPLACE FUNCTION "public"."fn_parse_paper_ruling"("p_tags" "jsonb", "p_name" "text", "p_description" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tags text := lower(coalesce(p_tags::text,''));
  v_desc text := lower(coalesce(p_description,''));
  v_name text := lower(coalesce(p_name,''));
  v_all  text := v_tags || ' ' || v_desc || ' ' || v_name;
BEGIN
  -- ── Prioridade: BLANK antes de RULED para "sem pauta" ────────
  -- (sem pauta / sem linhas são detectados ANTES dos positivos)
  IF v_all ILIKE ANY(ARRAY[
    '%sem pauta%','%sem linhas%','%folhas lisas%','%páginas lisas%',
    '%liso%','%lisas%','%em branco%','%plain%','%without lines%'
  ]) THEN RETURN 'BLANK'; END IF;

  -- PLANNER
  IF v_all ILIKE '%planner%' AND v_all ILIKE ANY(ARRAY['%planejamento%','%agenda%','%metas%','%anual%']) THEN
    RETURN 'PLANNER';
  END IF;
  -- Pontilhado
  IF v_all ILIKE ANY(ARRAY['%pontilhado%','%dotted%','%bullet journal%']) THEN RETURN 'DOTTED'; END IF;
  -- Quadriculado
  IF v_all ILIKE '%quadriculado%' THEN RETURN 'GRID'; END IF;
  -- Pautado — padrões explícitos (evitar "sem pauta")
  IF v_all ILIKE ANY(ARRAY[
    '%pautado%','%folhas pautadas%','%com pauta%','%pautadas%','%papel pautado%',
    '%linhas%','%lines for%','%pages with lines%','%lined%'
  ]) THEN RETURN 'RULED'; END IF;
  -- Agenda/diário implica ruled
  IF v_all ILIKE ANY(ARRAY[
    '%diária%','%semanal%','%plano diário%','%plano semanal%'
  ]) THEN RETURN 'RULED'; END IF;
  -- Para anotações → ruled (padrão SM)
  IF v_all ILIKE '%para anotações%' THEN RETURN 'RULED'; END IF;
  -- Agenda no nome/tags → ruled
  IF v_all ILIKE '%agenda%' AND v_name ILIKE '%agenda%' THEN RETURN 'RULED'; END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_parse_paper_ruling"("p_tags" "jsonb", "p_name" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parse_paper_weight"("p_description" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_desc  text := lower(coalesce(p_description,''));
  v_match text[];
  v_n     int;
BEGIN
  -- Tentar capturar gramatura em diversas formas:
  -- "75 g/m²", "75g/m2", "75 gsm", "80g", "80g.", "80g,"
  -- Padrão: número + opcional espaço + g + (/ ou espaço ou pontuação não-alfa ou fim)
  SELECT m INTO v_match
  FROM regexp_matches(
    v_desc,
    '(\d+)\s*(?:g/m[²2]|gsm|g(?![a-z]))',
    'ig'  -- case insensitive, multiline
  ) AS t(m)
  LIMIT 1;

  IF v_match IS NOT NULL THEN
    v_n := v_match[1]::int;
    -- Faixa válida para papel de caderno (50–250 g/m²)
    IF v_n BETWEEN 50 AND 250 THEN RETURN v_n; END IF;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_parse_paper_weight"("p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parse_product_dimensions"("p_dimensions_text" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_original TEXT; v_work_text TEXT; v_unit TEXT; v_unit_factor NUMERIC;
    v_is_diameter BOOLEAN; v_is_axlxp BOOLEAN;
    v_numbers TEXT[]; v_nums NUMERIC[]; v_result JSONB; v_i INT; v_num NUMERIC;
BEGIN
    IF p_dimensions_text IS NULL OR TRIM(p_dimensions_text) = '' THEN
        RETURN jsonb_build_object('error','empty_input','original',p_dimensions_text);
    END IF;
    v_original := TRIM(p_dimensions_text);
    IF POSITION('|' IN v_original) > 0 THEN
        v_work_text := TRIM(SPLIT_PART(v_original,'|',1));
    ELSE
        v_work_text := v_original;
    END IF;
    v_work_text := REPLACE(v_work_text, ',', '.');

    -- PATCH M3 2026-06-11 (guard #1): texto sem indicador dimensional
    -- (sem 'x'/'×' entre tokens, sem ø, sem unidade mm/cm/m) não é dimensão.
    -- Mata falsos positivos tipo "Tamanho 5" (bola) e "Tamanho: 58" (boné).
    IF v_work_text !~* '[x×øØ]' AND v_work_text !~* '\m(mm|cm|m)\M' THEN
        RETURN jsonb_build_object('error','no_dimension_pattern','original',v_original);
    END IF;

    IF v_work_text ~* 'cm' THEN v_unit := 'cm'; v_unit_factor := 1.0;
    ELSIF v_work_text ~* 'mm' THEN v_unit := 'mm'; v_unit_factor := 0.1;
    ELSIF v_work_text ~ '(?<![c])\mm\M(?!m)' THEN v_unit := 'm'; v_unit_factor := 100.0;
    ELSE v_unit := 'mm'; v_unit_factor := 0.1;
    END IF;

    v_is_diameter := (v_work_text ~ '[øØ]');
    v_is_axlxp := (v_work_text ~* '\(\s*[AH]\s*[x×]\s*[LW]\s*[x×]\s*[PD]\s*\)');

    SELECT ARRAY_AGG(m[1]) INTO v_numbers
    FROM REGEXP_MATCHES(v_work_text, '(\d+\.?\d*)', 'g') AS m;
    IF v_numbers IS NULL OR ARRAY_LENGTH(v_numbers,1) IS NULL THEN
        RETURN jsonb_build_object('error','no_numbers','original',v_original);
    END IF;

    v_nums := ARRAY[]::NUMERIC[];
    FOR v_i IN 1..ARRAY_LENGTH(v_numbers,1) LOOP
        v_num := v_numbers[v_i]::NUMERIC;
        IF v_num > 0 THEN v_nums := ARRAY_APPEND(v_nums, v_num); END IF;
    END LOOP;
    IF ARRAY_LENGTH(v_nums,1) IS NULL THEN
        RETURN jsonb_build_object('error','no_valid_numbers','original',v_original);
    END IF;

    -- PATCH M3 2026-06-11 (guard #2): valor convertido > 1000 cm é lixo de feed.
    FOR v_i IN 1..ARRAY_LENGTH(v_nums,1) LOOP
        IF v_nums[v_i] * v_unit_factor > 1000 THEN
            RETURN jsonb_build_object('error','out_of_range','original',v_original);
        END IF;
    END LOOP;

    v_result := jsonb_build_object('original',v_original,'unit_detected',v_unit,
        'shape_type',CASE WHEN v_is_diameter THEN 'cylindrical' ELSE 'rectangular' END,
        'length_cm',NULL,'width_cm',NULL,'height_cm',NULL,'diameter_cm',NULL);

    IF v_is_diameter THEN
        IF ARRAY_LENGTH(v_nums,1) >= 2 THEN
            v_result := v_result || jsonb_build_object(
                'diameter_cm',ROUND(v_nums[1]*v_unit_factor,2),'height_cm',ROUND(v_nums[2]*v_unit_factor,2),
                'length_cm',ROUND(v_nums[1]*v_unit_factor,2),'width_cm',ROUND(v_nums[1]*v_unit_factor,2));
        ELSIF ARRAY_LENGTH(v_nums,1) = 1 THEN
            v_result := v_result || jsonb_build_object(
                'diameter_cm',ROUND(v_nums[1]*v_unit_factor,2),
                'length_cm',ROUND(v_nums[1]*v_unit_factor,2),'width_cm',ROUND(v_nums[1]*v_unit_factor,2));
        END IF;
    ELSIF v_is_axlxp THEN
        IF ARRAY_LENGTH(v_nums,1) >= 3 THEN
            v_result := v_result || jsonb_build_object('height_cm',ROUND(v_nums[1]*v_unit_factor,2),
                'width_cm',ROUND(v_nums[2]*v_unit_factor,2),'length_cm',ROUND(v_nums[3]*v_unit_factor,2));
        ELSIF ARRAY_LENGTH(v_nums,1) >= 2 THEN
            v_result := v_result || jsonb_build_object('height_cm',ROUND(v_nums[1]*v_unit_factor,2),
                'width_cm',ROUND(v_nums[2]*v_unit_factor,2));
        END IF;
    ELSE
        IF ARRAY_LENGTH(v_nums,1) >= 3 THEN
            v_result := v_result || jsonb_build_object('width_cm',ROUND(v_nums[1]*v_unit_factor,2),
                'height_cm',ROUND(v_nums[2]*v_unit_factor,2),'length_cm',ROUND(v_nums[3]*v_unit_factor,2));
        ELSIF ARRAY_LENGTH(v_nums,1) >= 2 THEN
            v_result := v_result || jsonb_build_object('width_cm',ROUND(v_nums[1]*v_unit_factor,2),
                'height_cm',ROUND(v_nums[2]*v_unit_factor,2));
        ELSIF ARRAY_LENGTH(v_nums,1) = 1 THEN
            v_result := v_result || jsonb_build_object('width_cm',ROUND(v_nums[1]*v_unit_factor,2));
        END IF;
    END IF;
    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_parse_product_dimensions"("p_dimensions_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_parse_product_dimensions"("p_dimensions_text" "text") IS 'Parse UNIVERSAL de dimensões de produtos v3.2 - Funciona com QUALQUER fornecedor.

FORMATOS SUPORTADOS:
- SPOT: "370 x 410 mm" (L x A), "55 x 22 x 12 mm" (L x A x P), "ø65 x 220 mm"
- XBZ: "39x42x18cm (AxLxP)"
- Asia/Genérico: "100x50x25"

CORREÇÃO v3.2: Mapeamento corrigido para padrão SPOT
  - 2 valores: primeiro=width (largura), segundo=height (altura)
  - 3 valores: primeiro=width, segundo=height, terceiro=length (profundidade)

Versão 3.2 - 01/02/2026';



CREATE OR REPLACE FUNCTION "public"."fn_parse_product_weight"("p_weight" numeric, "p_weight_unit" "text" DEFAULT NULL::"text", "p_box_weight_kg" numeric DEFAULT NULL::numeric, "p_box_quantity" integer DEFAULT NULL::integer, "p_product_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_weight_g NUMERIC;
    v_weight_kg NUMERIC;
    v_source TEXT;
    v_confidence TEXT;
    v_unit_used TEXT;
    v_detection_reason TEXT;
    v_calculation_details TEXT;
    v_extracted_weight NUMERIC;
BEGIN
    -- ========================================
    -- 1. VALIDAÇÃO DE ENTRADA
    -- ========================================
    
    -- Se peso é NULL ou zero, tentar fallbacks
    IF p_weight IS NULL OR p_weight = 0 THEN
        -- Tentar calcular via caixa
        IF p_box_weight_kg IS NOT NULL AND p_box_weight_kg > 0 
           AND p_box_quantity IS NOT NULL AND p_box_quantity > 0 THEN
            v_weight_g := ROUND((p_box_weight_kg * 1000) / p_box_quantity, 2);
            v_weight_kg := ROUND(v_weight_g / 1000, 4);
            v_source := 'calculated';
            v_confidence := 'high';
            v_calculation_details := FORMAT('BoxWeightKG(%s) * 1000 / BoxQuantity(%s) = %sg', 
                                            p_box_weight_kg, p_box_quantity, v_weight_g);
            
            RETURN jsonb_build_object(
                'weight_g', v_weight_g,
                'weight_kg', v_weight_kg,
                'source', v_source,
                'confidence', v_confidence,
                'original_value', p_weight,
                'original_unit', COALESCE(p_weight_unit, 'unknown'),
                'detection_reason', 'weight was null/zero, calculated from box',
                'calculation_details', v_calculation_details
            );
        END IF;
        
        -- Tentar extrair do nome
        IF p_product_name IS NOT NULL AND p_product_name != '' THEN
            BEGIN
                SELECT fn_extract_weight_from_name(p_product_name) INTO v_extracted_weight;
                
                IF v_extracted_weight IS NOT NULL AND v_extracted_weight > 0 THEN
                    RETURN jsonb_build_object(
                        'weight_g', v_extracted_weight,
                        'weight_kg', ROUND(v_extracted_weight / 1000, 4),
                        'source', 'extracted',
                        'confidence', 'medium',
                        'original_value', p_weight,
                        'original_unit', COALESCE(p_weight_unit, 'unknown'),
                        'detection_reason', 'extracted from product name',
                        'calculation_details', FORMAT('Extracted %sg from name: %s', 
                                                      v_extracted_weight, LEFT(p_product_name, 50))
                    );
                END IF;
            EXCEPTION WHEN OTHERS THEN
                -- Função de extração não existe ou falhou, continuar
                NULL;
            END;
        END IF;
        
        -- Sem dados suficientes
        RETURN jsonb_build_object(
            'weight_g', NULL,
            'weight_kg', NULL,
            'source', 'none',
            'confidence', 'none',
            'original_value', p_weight,
            'original_unit', COALESCE(p_weight_unit, 'unknown'),
            'error', 'no_weight_data',
            'detection_reason', 'weight is null/zero and no fallback available'
        );
    END IF;
    
    -- ========================================
    -- 2. DETERMINAR UNIDADE
    -- ========================================
    
    IF p_weight_unit IS NOT NULL AND LOWER(p_weight_unit) IN ('g', 'gram', 'grams', 'gramas') THEN
        -- Unidade informada: GRAMAS
        v_unit_used := 'g';
        v_detection_reason := 'unit provided as grams';
        
    ELSIF p_weight_unit IS NOT NULL AND LOWER(p_weight_unit) IN ('kg', 'kilo', 'kilos', 'quilos', 'quilogramas') THEN
        -- Unidade informada: QUILOGRAMAS
        v_unit_used := 'kg';
        v_detection_reason := 'unit provided as kilograms';
        
    ELSE
        -- AUTO-DETECTAR baseado no valor
        -- Regra: produtos promocionais típicos pesam entre 10g e 5kg
        -- Se valor > 50, provavelmente está em gramas
        -- Se valor < 10, provavelmente está em kg
        -- Zona cinza (10-50): assumir kg por segurança (mais comum em APIs)
        
        IF p_weight > 50 THEN
            v_unit_used := 'g';
            v_detection_reason := FORMAT('auto-detected as grams (value %s > 50)', p_weight);
        ELSIF p_weight < 10 THEN
            v_unit_used := 'kg';
            v_detection_reason := FORMAT('auto-detected as kg (value %s < 10)', p_weight);
        ELSE
            -- Zona cinza: assumir kg (padrão de mercado)
            v_unit_used := 'kg';
            v_detection_reason := FORMAT('auto-detected as kg (value %s in gray zone 10-50, defaulting to kg)', p_weight);
        END IF;
    END IF;
    
    -- ========================================
    -- 3. CONVERTER PARA GRAMAS
    -- ========================================
    
    IF v_unit_used = 'kg' THEN
        v_weight_g := ROUND(p_weight * 1000, 2);
    ELSE
        v_weight_g := ROUND(p_weight, 2);
    END IF;
    
    v_weight_kg := ROUND(v_weight_g / 1000, 4);
    
    -- ========================================
    -- 4. VERIFICAR SE PESO É PLACEHOLDER
    -- ========================================
    
    -- Se peso convertido for <= 1g, provavelmente é placeholder (comum na SPOT)
    IF v_weight_g <= 1 THEN
        -- Tentar calcular via caixa
        IF p_box_weight_kg IS NOT NULL AND p_box_weight_kg > 0 
           AND p_box_quantity IS NOT NULL AND p_box_quantity > 0 THEN
            v_weight_g := ROUND((p_box_weight_kg * 1000) / p_box_quantity, 2);
            v_weight_kg := ROUND(v_weight_g / 1000, 4);
            v_source := 'calculated';
            v_confidence := 'high';
            v_calculation_details := FORMAT('BoxWeightKG(%s) * 1000 / BoxQuantity(%s) = %sg (original weight was placeholder: %s%s)', 
                                            p_box_weight_kg, p_box_quantity, v_weight_g, p_weight, v_unit_used);
            
            RETURN jsonb_build_object(
                'weight_g', v_weight_g,
                'weight_kg', v_weight_kg,
                'source', v_source,
                'confidence', v_confidence,
                'original_value', p_weight,
                'original_unit', v_unit_used,
                'detection_reason', 'original weight was placeholder (<=1g), calculated from box',
                'calculation_details', v_calculation_details
            );
        END IF;
        
        -- Tentar extrair do nome
        IF p_product_name IS NOT NULL AND p_product_name != '' THEN
            BEGIN
                SELECT fn_extract_weight_from_name(p_product_name) INTO v_extracted_weight;
                
                IF v_extracted_weight IS NOT NULL AND v_extracted_weight > 1 THEN
                    RETURN jsonb_build_object(
                        'weight_g', v_extracted_weight,
                        'weight_kg', ROUND(v_extracted_weight / 1000, 4),
                        'source', 'extracted',
                        'confidence', 'medium',
                        'original_value', p_weight,
                        'original_unit', v_unit_used,
                        'detection_reason', 'original weight was placeholder, extracted from product name',
                        'calculation_details', FORMAT('Extracted %sg from name: %s', 
                                                      v_extracted_weight, LEFT(p_product_name, 50))
                    );
                END IF;
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
        
        -- Retornar o placeholder com aviso
        RETURN jsonb_build_object(
            'weight_g', v_weight_g,
            'weight_kg', v_weight_kg,
            'source', 'api',
            'confidence', 'low',
            'original_value', p_weight,
            'original_unit', v_unit_used,
            'detection_reason', v_detection_reason,
            'warning', 'weight seems to be a placeholder (<=1g), no fallback available'
        );
    END IF;
    
    -- ========================================
    -- 5. VALIDAR PESO RAZOÁVEL
    -- ========================================
    
    -- Produtos promocionais típicos: 5g a 10kg
    IF v_weight_g < 5 THEN
        v_confidence := 'low';
    ELSIF v_weight_g > 10000 THEN
        v_confidence := 'medium'; -- Peso alto mas possível (ex: caixa de som grande)
    ELSE
        v_confidence := 'high';
    END IF;
    
    -- ========================================
    -- 6. RETORNAR RESULTADO
    -- ========================================
    
    RETURN jsonb_build_object(
        'weight_g', v_weight_g,
        'weight_kg', v_weight_kg,
        'source', 'api',
        'confidence', v_confidence,
        'original_value', p_weight,
        'original_unit', v_unit_used,
        'detection_reason', v_detection_reason,
        'calculation_details', NULL
    );
    
END;
$$;


ALTER FUNCTION "public"."fn_parse_product_weight"("p_weight" numeric, "p_weight_unit" "text", "p_box_weight_kg" numeric, "p_box_quantity" integer, "p_product_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_parse_product_weight"("p_weight" numeric, "p_weight_unit" "text", "p_box_weight_kg" numeric, "p_box_quantity" integer, "p_product_name" "text") IS 'Parse UNIVERSAL de peso de produtos v1.0 - Funciona com QUALQUER fornecedor.

PARÂMETROS:
  p_weight: Peso da API (pode ser g ou kg)
  p_weight_unit: Unidade do peso (''g'', ''kg'', ou NULL para auto-detectar)
  p_box_weight_kg: Peso da caixa em kg (opcional, SPOT tem)
  p_box_quantity: Quantidade por caixa (opcional, SPOT tem)
  p_product_name: Nome do produto (opcional, para extração fallback)

RETORNA JSONB:
  weight_g: Peso em gramas (padrão interno)
  weight_kg: Peso em kg (para logística)
  source: "api" | "calculated" | "extracted" | "none"
  confidence: "high" | "medium" | "low" | "none"
  original_value: Valor original recebido
  original_unit: Unidade usada (informada ou detectada)
  detection_reason: Explicação da detecção/decisão
  calculation_details: Detalhes do cálculo (se calculado)

FORNECEDORES:
  SPOT: fn_parse_product_weight(Weight, ''g'', BoxWeightKG, BoxQuantity, Name)
  XBZ: fn_parse_product_weight(Peso, ''kg'', NULL, NULL, Nome)
  Asia: fn_parse_product_weight(peso, ''kg'', NULL, NULL, nome)

Versão 1.0 - 01/02/2026';



CREATE OR REPLACE FUNCTION "public"."fn_parse_sheet_count"("p_description" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_desc  text := lower(coalesce(p_description,''));
  v_match text[];
  v_n     int;
BEGIN
  -- "N folhas" (com ou sem aproximadamente/possui/contém)
  SELECT m INTO v_match
  FROM regexp_matches(
    v_desc,
    '(?:(?:aproximadamente|com|possui|contém|tem)\s+)?(\d+)\s*folhas?',
    'g'
  ) AS t(m)
  LIMIT 1;
  IF v_match IS NOT NULL THEN
    v_n := v_match[1]::int;
    IF v_n BETWEEN 10 AND 1000 THEN RETURN v_n; END IF;
  END IF;

  -- "N páginas" → divir por 2
  SELECT m INTO v_match
  FROM regexp_matches(
    v_desc,
    '(?:(?:aproximadamente|com|possui|contém|tem)\s+)?(\d+)\s*páginas?',
    'g'
  ) AS t(m)
  LIMIT 1;
  IF v_match IS NOT NULL THEN
    v_n := v_match[1]::int;
    IF v_n BETWEEN 20 AND 2000 THEN RETURN v_n / 2; END IF;
  END IF;

  -- "Nff" (abreviatura pt-br de folhas) — usa (?!\w) em vez de \b
  SELECT m INTO v_match
  FROM regexp_matches(v_desc, '(\d+)\s*ff(?!\w)', 'g') AS t(m)
  LIMIT 1;
  IF v_match IS NOT NULL THEN
    v_n := v_match[1]::int;
    IF v_n BETWEEN 10 AND 500 THEN RETURN v_n; END IF;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_parse_sheet_count"("p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parse_sm_site_markdown"("p_md" "text", "p_source_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_codigo      text;
  v_video_url   text;
  v_spec_url    text;
  v_photos      text[];
  v_related     jsonb    := '[]'::jsonb;
  v_price_tiers jsonb;
  v_master      jsonb;
  v_ncm         text;
  v_ipi         numeric;
  v_estoque     int;
  v_m           text[];
  v_m2          text[];
  v_tiers       jsonb    := '[]'::jsonb;
  v_qtds        text[];
  v_p_si        text[];
  v_p_ci        text[];
  v_i           int;
  v_rel_sid     int;
  v_rel_slug    text;
  v_rel_codigo  text;
  v_ctx_start   int;
  v_ctx         text;
BEGIN
  IF p_md IS NULL OR length(btrim(p_md)) < 200 THEN
    RETURN jsonb_build_object('error','conteudo_vazio','len',length(COALESCE(p_md,'')));
  END IF;

  -- 1. Código do produto (SM código: AS-00610, LE-31723, etc.)
  v_m := regexp_match(p_md, '\b([A-Z]{2,3}-[0-9]{4,6}(?:-[0-9]+)?)\b');
  IF v_m IS NOT NULL THEN v_codigo := v_m[1]; END IF;

  -- 2. Vídeo YouTube
  v_m := regexp_match(p_md, 'youtube\.com/watch\?v=([A-Za-z0-9_-]{6,15})');
  IF v_m IS NOT NULL THEN
    v_video_url := 'https://www.youtube.com/watch?v=' || v_m[1];
  ELSE
    v_m := regexp_match(p_md, 'youtube\.com/embed/([A-Za-z0-9_-]{6,15})');
    IF v_m IS NOT NULL THEN
      v_video_url := 'https://www.youtube.com/watch?v=' || v_m[1];
    END IF;
  END IF;

  -- 3. Spec técnica (BUG 7 FIX: aceitar .jpg E .png no hash-filename)
  v_m := regexp_match(p_md,
    'Especifica[cç][oõ]es? T[eé]cnicas\]\((https://[^)]+\.(?:png|jpg|jpeg))\)', 'i');
  IF v_m IS NOT NULL THEN
    v_spec_url := v_m[1];
  ELSE
    -- Hash-filename: 30+ hex chars + extensão (.png ou .jpg)
    v_m := regexp_match(p_md,
      '(https://somarcascdn\.azureedge\.net/upload/imagens_site_v4/[a-f0-9]{30,}\.(?:png|jpg|jpeg))');
    IF v_m IS NOT NULL THEN v_spec_url := v_m[1]; END IF;
  END IF;

  -- 4. Fotos CDN (BUG 6 FIX: excluir thumbnails m/ de produtos relacionados)
  --    Aceitar apenas:
  --    • /imagens_site_v4/g/  ← fotos grandes do produto
  --    • /imagens_site_v4/p/  ← thumbnails do produto
  --    • /imagens_site_v4/{hash}.{ext}  ← spec técnica / hero
  --    • /imagens_site/{filename}  ← imagens legado
  --    EXCLUIR: /imagens_site_v4/m/ (thumbnails de relacionados)
  SELECT array_agg(DISTINCT m[1])
  INTO   v_photos
  FROM   regexp_matches(p_md,
    '(https://somarcas(?:cdn)?\.azureedge\.net/upload/(?:'
      'imagens_site_v4/[gp]/[^"\)\s]+\.(?:webp|jpg|png|jpeg)'
      '|imagens_site_v4/[a-f0-9]{20,}\.[a-z]+'    -- hash-filename spec
      '|imagens_site/[^"\)\s]+\.(?:webp|jpg|png|jpeg)'  -- legado sem v4
    '))', 'g') m
  WHERE m[1] NOT ILIKE '%/m/%';   -- guaraná extra: excluir /m/ explicitamente

  -- 5. Produtos relacionados (BUG 5 FIX: emitir TODOS, com ou sem codigo)
  FOR v_m IN
    SELECT regexp_matches(p_md,
      'somarcas\.com\.br/([0-9]+)/produto/([a-z0-9][a-z0-9-]+[a-z0-9])', 'g')
  LOOP
    v_rel_sid  := v_m[1]::int;
    v_rel_slug := v_m[2];
    v_rel_codigo := NULL;

    -- Tenta extrair codigo do contexto próximo (janela de 250 chars antes/depois)
    v_ctx_start := strpos(p_md, v_m[1] || '/produto/' || v_m[2]);
    IF v_ctx_start > 0 THEN
      v_ctx := substring(p_md FROM GREATEST(1, v_ctx_start - 250) FOR 280);
      -- Formato bold: **AS-00610**
      v_m2 := regexp_match(v_ctx, '\*\*([A-Z]{2,3}-[0-9]{4,6}(?:-[0-9]+)?)\*\*');
      IF v_m2 IS NOT NULL THEN v_rel_codigo := v_m2[1]; END IF;
    END IF;

    -- BUG 5 FIX: emitir SEMPRE (mesmo sem codigo)
    -- fn_sm_site_collect vai decidir o que fazer com cada tipo
    v_related := v_related || jsonb_build_object(
      'site_id', v_rel_sid,
      'slug',    v_rel_slug,
      'codigo',  v_rel_codigo   -- NULL quando não detectado — OK
    );
  END LOOP;

  -- Desduplicar por site_id
  IF jsonb_array_length(v_related) > 0 THEN
    SELECT jsonb_agg(r) INTO v_related
    FROM (
      SELECT DISTINCT ON ((r->>'site_id')::int) r
      FROM jsonb_array_elements(v_related) r
      ORDER BY (r->>'site_id')::int,
               CASE WHEN r->>'codigo' IS NOT NULL THEN 0 ELSE 1 END  -- prioriza com codigo
    ) s;
  END IF;

  -- 6. Tabela de preços (requer auth)
  IF position('50 un' IN p_md) > 0 AND position('Sem impostos' IN p_md) > 0 THEN
    v_m := regexp_match(p_md, 'Qualquer un\.[^\n]*([0-9]+\s*un[^\n]+)\n');
    IF v_m IS NOT NULL THEN
      SELECT array_agg(trim(q.q)) INTO v_qtds
      FROM regexp_split_to_table(v_m[1], '\|') q(q)
      WHERE trim(q.q) ~ '[0-9]+\s*un';
    END IF;
    v_m := regexp_match(p_md, 'Sem impostos[^\n]*\n([^\n]+)');
    IF v_m IS NOT NULL THEN
      SELECT array_agg(replace(m[1],',','.')) INTO v_p_si
      FROM regexp_matches(v_m[1], 'R\$\s*([0-9]+[,\.][0-9]+)', 'g') m;
    END IF;
    v_m := regexp_match(p_md, 'Com IPI[^\n]*\n([^\n]+)');
    IF v_m IS NOT NULL THEN
      SELECT array_agg(replace(m[1],',','.')) INTO v_p_ci
      FROM regexp_matches(v_m[1], 'R\$\s*([0-9]+[,\.][0-9]+)', 'g') m;
    END IF;
    IF v_qtds IS NOT NULL AND v_p_si IS NOT NULL THEN
      FOR v_i IN 1..LEAST(array_length(v_qtds,1), array_length(v_p_si,1)) LOOP
        v_tiers := v_tiers || jsonb_build_object(
          'qtd_label',     v_qtds[v_i],
          'preco_sem_ipi', v_p_si[v_i]::numeric,
          'preco_com_ipi', CASE WHEN v_p_ci IS NOT NULL
                                AND v_i <= array_length(v_p_ci,1)
                                THEN v_p_ci[v_i]::numeric ELSE NULL END
        );
      END LOOP;
      IF jsonb_array_length(v_tiers) > 0 THEN v_price_tiers := v_tiers; END IF;
    END IF;
  END IF;

  -- 7. Caixa Master
  DECLARE v_mq text[]; v_mw text[]; BEGIN
    v_m  := regexp_match(p_md, 'DIMENS[OÕ]ES[^\n]*CAIXA[^\n]*\n[^\n]*?([0-9].{5,25}cm)', 'i');
    v_mq := regexp_match(p_md, '([0-9]+)\s+unidades?\s+por\s+caixa', 'i');
    v_mw := regexp_match(p_md, 'PESO\s+TOTAL[^\n]*\n[^\n]*?([0-9]+[,.]?[0-9]*)\s*kg', 'i');
    IF v_m IS NOT NULL OR v_mq IS NOT NULL OR v_mw IS NOT NULL THEN
      v_master := jsonb_strip_nulls(jsonb_build_object(
        'dims',    CASE WHEN v_m  IS NOT NULL THEN v_m[1]  ELSE NULL END,
        'qtd',     CASE WHEN v_mq IS NOT NULL THEN v_mq[1]::int ELSE NULL END,
        'peso_kg', CASE WHEN v_mw IS NOT NULL THEN replace(v_mw[1],',','.')::numeric ELSE NULL END
      ));
      IF v_master = '{}'::jsonb THEN v_master := NULL; END IF;
    END IF;
  END;

  -- 8. NCM / IPI / Estoque
  v_m := regexp_match(p_md, '\bNCM\b[^\n]*?([0-9]{8})', 'i');
  IF v_m IS NOT NULL THEN v_ncm := v_m[1]; END IF;

  v_m := regexp_match(p_md, 'IPI[^0-9]*([0-9]+[,.]?[0-9]*)\s*%', 'i');
  IF v_m IS NOT NULL THEN v_ipi := replace(v_m[1],',','.')::numeric; END IF;

  v_m := regexp_match(p_md, 'Estoque\s+de\s+([0-9.]+)\s+unidades', 'i');
  IF v_m IS NOT NULL THEN v_estoque := replace(v_m[1],'.','')::int; END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'scraped_at',        now(),
    'source_url',        p_source_url,
    'codigo_detectado',  v_codigo,
    'video_url',         v_video_url,
    'spec_tecnica_url',  v_spec_url,
    'fotos_cdn',         CASE WHEN v_photos IS NOT NULL THEN to_jsonb(v_photos) ELSE NULL END,
    'relacionados',      CASE WHEN jsonb_array_length(v_related) > 0 THEN v_related ELSE NULL END,
    'price_tiers',       v_price_tiers,
    'caixa_master',      v_master,
    'ncm_site',          v_ncm,
    'ipi_site',          v_ipi,
    'estoque_site',      v_estoque,
    'is_authenticated',  (v_price_tiers IS NOT NULL OR v_master IS NOT NULL)
  ));
END;
$_$;


ALTER FUNCTION "public"."fn_parse_sm_site_markdown"("p_md" "text", "p_source_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_parse_sm_site_markdown"("p_md" "text", "p_source_url" "text") IS 'v3 — Fixes: (6) fotos_cdn exclui thumbnails m/ de relacionados; (7) spec_tecnica aceita .jpg e .png; (5) relacionados emitidos mesmo sem codigo; VOLATILE (usa now()).';



CREATE OR REPLACE FUNCTION "public"."fn_parse_xbz_ficha_site_batch"("p_key" "text" DEFAULT 'caracteristicas_tecnicas'::"text", "p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("produtos_processados" integer, "linhas_extraidas" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE r record; v_prod int:=0; v_lin int:=0; v_n int;
BEGIN
  FOR r IN
    SELECT DISTINCT ON (p.sku) p.sku AS product_sku,
           spr.site_data->>p_key AS texto,
           coalesce(spr.site_data->>'ficha_tecnica_pdf', spr.site_data->>'url') AS src_url
    FROM supplier_products_raw spr
    JOIN products p ON p.id=spr.product_id
    WHERE spr.supplier_id='d6718a29-e954-4c1b-bd84-03ea24884900'
      AND spr.site_data ? p_key
      AND coalesce(spr.site_data->>p_key,'')<>''
      AND NOT EXISTS (SELECT 1 FROM kit_component_ficha_staging s
                       WHERE s.product_sku=p.sku AND s.source='xbz_site_caracteristicas')
    ORDER BY p.sku
    LIMIT p_limit
  LOOP
    v_n := fn_parse_ficha_tecnica_text(r.product_sku, r.texto, r.src_url, 'xbz_site_caracteristicas');
    IF v_n>0 THEN v_prod:=v_prod+1; v_lin:=v_lin+v_n; END IF;
  END LOOP;
  RETURN QUERY SELECT v_prod, v_lin;
END $$;


ALTER FUNCTION "public"."fn_parse_xbz_ficha_site_batch"("p_key" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parse_xbz_site_html"("p_html" "text", "p_codigo" "text", "p_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_idint text; v_nome text; v_desc text; v_modo text; v_grav text; v_main text;
  v_b64 text; v_video text; v_vid text;
  v_imgs jsonb; v_cores jsonb; v_cats jsonb; v_rel jsonb;
BEGIN
  p_html := regexp_replace(replace(p_html,'&amp;','&'), '&#160;|&nbsp;', ' ', 'g');
  v_main := split_part(p_html, 'Produtos relacionados', 1);   -- trecho do produto (antes dos relacionados)

  v_idint := substring(p_html from 'getPdfProduto/([0-9]+)');
  v_nome  := btrim(coalesce(substring(p_html from '<title>(?:Brinde )?([^<]+)</title>'),''));
  v_desc  := btrim(coalesce(substring(p_html from 'desc-sub my-desc-sub">([^<]{10,})'),''));
  v_modo  := btrim(coalesce(substring(p_html from 'Modo de uso[^A-Za-z0-9]{0,40}([^<]{20,})'),''));
  v_grav  := btrim(coalesce(substring(p_html from 'Medidas aproximadas para gravação[^0-9]{0,55}([0-9][^<]{2,80})'),''));

  v_b64 := substring(p_html from 'id="thumbvideo"[^>]*?data-src="([^"]+)"');
  IF v_b64 IS NOT NULL AND length(v_b64) > 8 THEN
    BEGIN
      v_video := convert_from(decode(v_b64,'base64'),'UTF8');
      v_vid   := substring(v_video from 'embed/([A-Za-z0-9_-]{6,20})');
    EXCEPTION WHEN OTHERS THEN v_video := NULL; v_vid := NULL; END;
  END IF;

  SELECT jsonb_agg(DISTINCT jsonb_build_object(
           'nome', m[1], 'swatch_url','https://www.xbzbrindes.com.br/img/cores/'||m[1]||'.jpg'))
    INTO v_cores FROM regexp_matches(p_html,'img/cores/([A-Z]+)\.jpg','g') m;

  -- GALERIA: imagens /img/produtos/ que aparecem ANTES da secao de relacionados, em ordem, sem duplicar
  SELECT jsonb_agg(jsonb_build_object(
           'url_origem','https://www.xbzbrindes.com.br/'||u,
           'ordem', rn-1,
           'tipo', CASE WHEN rn=1 THEN 'principal' ELSE 'galeria' END) ORDER BY rn)
    INTO v_imgs
  FROM (
    SELECT u, row_number() OVER (ORDER BY mo) AS rn
    FROM (
      SELECT t.m[1] AS u, min(t.o) AS mo
      FROM regexp_matches(v_main,'(img/produtos/[0-9]+/[^"'' )]+\.jpg)','g') WITH ORDINALITY AS t(m,o)
      GROUP BY t.m[1]
    ) g
  ) r;

  SELECT jsonb_agg(c ORDER BY c->>'path') INTO v_cats FROM (
    SELECT DISTINCT jsonb_build_object(
             'nivel', (length(path)-length(replace(path,'/',''))) - 1,
             'path', path,
             'url','http://www.xbzbrindes.com.br'||path,
             'nome', initcap(replace(regexp_replace(path,'^.*/',''),'-',' '))) AS c
    FROM (
      SELECT m[1] AS path FROM regexp_matches(p_html,'(/brindes/[A-Za-z0-9-]+/[A-Za-z0-9-]+)','g') m
      UNION
      SELECT DISTINCT regexp_replace(m[1],'^(/brindes/[^/]+)/.*','\1')
        FROM regexp_matches(p_html,'(/brindes/[A-Za-z0-9-]+/[A-Za-z0-9-]+)','g') m
    ) p
  ) s;

  SELECT jsonb_agg(DISTINCT jsonb_build_object(
           'codigo', m[1], 'url','https://www.xbzbrindes.com.br/'||m[1]))
    INTO v_rel
    FROM regexp_matches(p_html,'href="https://www\.xbzbrindes\.com\.br/(-?[0-9]{4,6}[a-zA-Z]?)"','g') m
   WHERE m[1] <> p_codigo AND m[1] <> ('-'||p_codigo);

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'codigo', p_codigo, 'url', p_url, 'id_interno_site', v_idint,
    'nome', nullif(v_nome,''), 'descricao', nullif(v_desc,''), 'modo_de_uso', nullif(v_modo,''),
    'dimensoes', jsonb_build_object(
      'altura_cm',         nullif(replace(coalesce(substring(p_html from 'Altura[^0-9]{0,45}([0-9]+[.,]?[0-9]*)'),''),',','.'),'')::numeric,
      'largura_cm',        nullif(replace(coalesce(substring(p_html from 'Largura[^0-9]{0,45}([0-9]+[.,]?[0-9]*)'),''),',','.'),'')::numeric,
      'circunferencia_cm', nullif(replace(coalesce(substring(p_html from 'Circunfer[^0-9]{0,45}([0-9]+[.,]?[0-9]*)'),''),',','.'),'')::numeric,
      'diametro_cm',       nullif(replace(coalesce(substring(p_html from 'Di.metro[^0-9]{0,45}([0-9]+[.,]?[0-9]*)'),''),',','.'),'')::numeric,
      'profundidade_cm',   nullif(replace(coalesce(substring(p_html from 'Profundidade[^0-9]{0,45}([0-9]+[.,]?[0-9]*)'),''),',','.'),'')::numeric
    ),
    'peso_g', nullif(coalesce(substring(p_html from 'Peso aproximado[^0-9]{0,55}([0-9]+)'),''),'')::int,
    'gravacao', jsonb_build_object(
      'medida_texto',   nullif(v_grav,''),
      'comprimento_cm', nullif(replace(coalesce(substring(v_grav from '^([0-9]+[.,]?[0-9]*)'),''),',','.'),'')::numeric,
      'largura_cm',     nullif(replace(coalesce(substring(v_grav from '[xX]\s*([0-9]+[.,]?[0-9]*)'),''),',','.'),'')::numeric,
      'local',          nullif(btrim(coalesce(substring(v_grav from '\(([^)]+)\)'),'')),'')
    ),
    'cores', coalesce(v_cores,'[]'::jsonb),
    'imagens', coalesce(v_imgs,'[]'::jsonb),
    'video', CASE WHEN v_vid IS NOT NULL
       THEN jsonb_build_object('indicador',true,'plataforma','youtube','embed_id',v_vid,'embed_url',v_video,'watch_url','https://www.youtube.com/watch?v='||v_vid)
       ELSE jsonb_build_object('indicador',(p_html ~ 'thumbvideo')) END,
    'ficha_tecnica_pdf', CASE WHEN v_idint IS NOT NULL THEN 'https://www.xbzbrindes.com.br/getPdfProduto/'||v_idint END,
    'categorias', coalesce(v_cats,'[]'::jsonb),
    'relacionados', coalesce(v_rel,'[]'::jsonb),
    '_meta', jsonb_build_object('scraper_version','2.2-html','render','headless (r.jina.ai)','fonte','parser generico HTML')
  ));
END;
$$;


ALTER FUNCTION "public"."fn_parse_xbz_site_html"("p_html" "text", "p_codigo" "text", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_pbd_before_write"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- fix_version=pbd_v1_3_20260627 | ANTI-REGRESSAO: manter SET search_path
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := COALESCE(NEW.created_at, now());
    NEW.updated_at := now();
    IF NEW.created_by IS NULL THEN NEW.created_by := auth.uid(); END IF;
    NEW.updated_by := COALESCE(auth.uid(), NEW.updated_by);
    -- Simetria com UPDATE: usuario autenticado nao-dev nao pode CRIAR badge de sistema.
    -- Preserva seed/migracao (auth.uid() IS NULL) e dev.
    IF NEW.is_system = true AND auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(), 'dev'::app_role) THEN
      NEW.is_system := false;
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.badge_key IS DISTINCT FROM OLD.badge_key THEN
      RAISE EXCEPTION 'badge_key e imutavel (% -> %)', OLD.badge_key, NEW.badge_key USING ERRCODE = '23514';
    END IF;
    IF NEW.is_system IS DISTINCT FROM OLD.is_system AND NOT public.has_role(auth.uid(), 'dev'::app_role) THEN
      NEW.is_system := OLD.is_system;
    END IF;
    NEW.created_at := OLD.created_at;
    NEW.created_by := OLD.created_by;
    NEW.updated_at := now();
    NEW.updated_by := COALESCE(auth.uid(), OLD.updated_by);
  END IF;
  RETURN NEW;
END;$$;


ALTER FUNCTION "public"."fn_pbd_before_write"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_pbd_before_write"() IS 'fix_version=pbd_v1_3_20260627. BEFORE INSERT/UPDATE de product_badge_definitions: auditoria (created_*/updated_*), badge_key imutavel, is_system protegido SIMETRICAMENTE (nao-dev autenticado nao cria nem altera badge de sistema; seed sem-JWT e dev preservados).';



CREATE OR REPLACE FUNCTION "public"."fn_pbd_block_system_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- fix_version=pbd_v1_20260627
  IF OLD.is_system THEN
    RAISE EXCEPTION 'Badge de sistema "%" nao pode ser excluida (apenas desabilitada via is_enabled).', OLD.badge_key USING ERRCODE = '42501';
  END IF;
  RETURN OLD;
END;$$;


