CREATE OR REPLACE FUNCTION "public"."fn_pkc_auto_enrich_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_has_dims       BOOLEAN;
  v_has_all        BOOLEAN;
  v_real_weight    BOOLEAN;  -- peso real: excluí inherited_total (copiado do total do produto-pai)
BEGIN
  -- circunferência a partir do diâmetro (lógica original preservada)
  IF NEW.shape_type = 'cylindrical' AND NEW.diameter_mm IS NOT NULL
     AND (NEW.circumference_mm IS NULL OR (TG_OP='UPDATE' AND OLD.diameter_mm IS DISTINCT FROM NEW.diameter_mm))
  THEN NEW.circumference_mm := ROUND(PI() * NEW.diameter_mm);
  END IF;

  -- peso "real" = preenchido E NÃO é herança do total do produto-pai
  v_real_weight := (NEW.weight_g IS NOT NULL
    AND coalesce(NEW.weight_source, 'estimated_heuristic') <> 'inherited_total');

  IF NEW.is_packaging = TRUE THEN
    v_has_all  := (NEW.pkg_ext_length_mm IS NOT NULL
                   AND NEW.pkg_ext_width_mm  IS NOT NULL
                   AND NEW.pkg_ext_height_mm IS NOT NULL
                   AND v_real_weight);
    v_has_dims := (NEW.pkg_ext_length_mm IS NOT NULL
                   AND NEW.pkg_ext_width_mm  IS NOT NULL
                   AND NEW.pkg_ext_height_mm IS NOT NULL)
               OR NEW.length_mm IS NOT NULL;
  ELSE
    CASE COALESCE(NEW.shape_type, 'rectangular')
      WHEN 'cylindrical' THEN
        v_has_all  := NEW.diameter_mm IS NOT NULL AND NEW.height_mm IS NOT NULL AND v_real_weight;
        v_has_dims := NEW.diameter_mm IS NOT NULL OR NEW.height_mm IS NOT NULL;
      WHEN 'flat' THEN
        v_has_all  := NEW.length_mm IS NOT NULL AND NEW.width_mm IS NOT NULL AND v_real_weight;
        v_has_dims := NEW.length_mm IS NOT NULL OR v_real_weight;
      WHEN 'spherical' THEN
        v_has_all  := NEW.diameter_mm IS NOT NULL AND v_real_weight;
        v_has_dims := NEW.diameter_mm IS NOT NULL;
      ELSE -- rectangular: weight não é requisito para 'complete' (exige 3 dims)
        v_has_all  := NEW.length_mm IS NOT NULL AND NEW.width_mm IS NOT NULL AND NEW.height_mm IS NOT NULL;
        v_has_dims := NEW.length_mm IS NOT NULL OR v_real_weight OR NEW.diameter_mm IS NOT NULL;
    END CASE;
  END IF;

  NEW.enrichment_status := CASE
    WHEN v_has_all  THEN 'complete'
    WHEN v_has_dims THEN 'partial'
    ELSE 'missing'
  END;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_pkc_auto_enrich_status"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_pkc_auto_enrich_status"() IS 'Trigger GOLD: calcula enrichment_status (missing|partial|complete) e
   circumference_mm automático para cilíndricos a cada INSERT/UPDATE.';



CREATE OR REPLACE FUNCTION "public"."fn_pkc_auto_inherit_material"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_new_material UUID;
  v_new_secondary UUID;
  v_old_default_material UUID;
BEGIN
  IF NEW.component_type_code IS NOT NULL THEN
    -- Buscar material padrão do NOVO tipo
    SELECT default_material_type_id, secondary_material_type_id
      INTO v_new_material, v_new_secondary
      FROM kit_component_types
     WHERE code = NEW.component_type_code;

    -- Caso 1: INSERT ou material ainda NULL → herdar do tipo
    IF NEW.material_type_id IS NULL THEN
      NEW.material_type_id := v_new_material;
      IF NEW.secondary_material_type_id IS NULL THEN
        NEW.secondary_material_type_id := v_new_secondary;
      END IF;

    -- Caso 2: UPDATE com mudança de type_code E material atual = default do tipo ANTIGO
    -- (material não foi customizado manualmente → deve acompanhar o novo tipo)
    ELSIF TG_OP = 'UPDATE'
      AND OLD.component_type_code IS DISTINCT FROM NEW.component_type_code
    THEN
      -- Verificar se o material atual era o default do tipo antigo
      SELECT default_material_type_id INTO v_old_default_material
        FROM kit_component_types WHERE code = OLD.component_type_code;

      -- Se o material atual era o padrão do tipo antigo → atualiza
      IF NEW.material_type_id = v_old_default_material THEN
        NEW.material_type_id := v_new_material;
        -- Atualiza secondary só se também era o padrão do tipo antigo
        IF NEW.secondary_material_type_id IS NULL OR NEW.secondary_material_type_id = v_old_default_material THEN
          NEW.secondary_material_type_id := v_new_secondary;
        END IF;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_pkc_auto_inherit_material"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_pkc_freeze_slot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.slot_code IS NOT NULL AND NEW.slot_code IS DISTINCT FROM OLD.slot_code THEN
    RAISE EXCEPTION 'slot_code é imutável (% -> %) no componente %', OLD.slot_code, NEW.slot_code, OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


