COMMENT ON FUNCTION "public"."fn_process_asia_stock_pending"("p_limit" integer) IS 'Lane de ESTOQUE ASIA: drena supplier_products_raw.stock_status=pending, aplica stock_quantity + reposicao (previsao_entrega[0]) em produtos_padronizacao_variantes e marca stock_status=processed. Espelha o branch ASIA de fn_standardize_variant. Agendada via pg_cron (asia-stock-sync).';



CREATE OR REPLACE FUNCTION "public"."fn_process_composite_materials"("p_product_id" "uuid", "p_materials_string" "text", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_replace_existing" boolean DEFAULT false) RETURNS TABLE("material_name" "text", "material_type_id" "uuid", "status" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_part RECORD;
    v_type_id UUID;
    v_total_parts INTEGER;
    v_percentages NUMERIC[];
    v_idx INTEGER := 1;
    v_existing_count INTEGER;
    v_org_id UUID;
BEGIN
    v_org_id := COALESCE(p_organization_id, '5db5aee1-064b-4ef4-9193-345dcd8274ea'::UUID);

    SELECT COUNT(*) INTO v_existing_count
    FROM product_materials
    WHERE product_id = p_product_id AND is_active = true;

    IF v_existing_count > 0 AND NOT p_replace_existing THEN
        material_name := 'AVISO';
        material_type_id := NULL;
        status := 'Produto ja tem materiais';
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_replace_existing AND v_existing_count > 0 THEN
        UPDATE product_materials
        SET is_active = false, updated_at = NOW()
        WHERE product_id = p_product_id;
    END IF;

    -- Contar APENAS materiais que serão encontrados (têm type_id)
    SELECT COUNT(*) INTO v_total_parts
    FROM fn_split_materials(p_materials_string) s
    WHERE fn_find_material_type_id(s.material_part) IS NOT NULL;

    IF v_total_parts = 0 THEN
        material_name := 'AVISO';
        material_type_id := NULL;
        status := 'Nenhum material encontrado';
        RETURN NEXT;
        RETURN;
    END IF;

    v_percentages := fn_distribute_percentage(100.0, v_total_parts);
    v_idx := 1;

    FOR v_part IN SELECT * FROM fn_split_materials(p_materials_string)
    LOOP
        v_type_id := fn_find_material_type_id(v_part.material_part);

        IF v_type_id IS NOT NULL THEN
            -- Upsert idempotente: reativa/atualiza a linha existente (mesmo soft-deletada)
            -- em vez de inserir duplicado e violar a constraint única.
            INSERT INTO product_materials (
                organization_id, product_id, material_id, part,
                percentage, sort_order, notes, is_active
            ) VALUES (
                v_org_id, p_product_id, v_type_id, 'corpo',
                v_percentages[v_idx], v_part.sort_order, 'Auto', true
            )
            ON CONFLICT (product_id, material_id) DO UPDATE SET
                is_active       = true,
                part            = 'corpo',
                percentage      = EXCLUDED.percentage,
                sort_order      = EXCLUDED.sort_order,
                notes           = 'Auto',
                organization_id = EXCLUDED.organization_id,
                updated_at      = NOW();

            material_name := v_part.material_part;
            material_type_id := v_type_id;
            status := 'OK (' || v_percentages[v_idx] || '%)';
            v_idx := v_idx + 1;
        ELSE
            material_name := v_part.material_part;
            material_type_id := NULL;
            status := 'NAO ENCONTRADO';
        END IF;

        RETURN NEXT;
    END LOOP;

    RETURN;
END;
$$;


ALTER FUNCTION "public"."fn_process_composite_materials"("p_product_id" "uuid", "p_materials_string" "text", "p_organization_id" "uuid", "p_replace_existing" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_process_product_materials_auto"("p_product_id" "uuid", "p_replace_existing" boolean DEFAULT false) RETURNS TABLE("material_name" "text", "material_type_id" "uuid", "status" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_product RECORD;
    v_combined TEXT;
BEGIN
    SELECT id, name, organization_id, materials
    INTO v_product
    FROM products
    WHERE id = p_product_id;

    IF v_product IS NULL THEN
        material_name := 'ERRO'; material_type_id := NULL;
        status := 'Produto não encontrado: ' || p_product_id;
        RETURN NEXT; RETURN;
    END IF;

    IF v_product.materials IS NULL
       OR v_product.materials = '[]'::jsonb
       OR jsonb_array_length(v_product.materials) = 0 THEN
        material_name := 'AVISO'; material_type_id := NULL;
        status := 'Produto "' || v_product.name || '" não tem materials preenchido';
        RETURN NEXT; RETURN;
    END IF;

    SELECT string_agg(elem #>> '{}', ', ')
      INTO v_combined
      FROM jsonb_array_elements(v_product.materials) elem
      WHERE NULLIF(TRIM(elem #>> '{}'), '') IS NOT NULL;

    IF NULLIF(TRIM(COALESCE(v_combined,'')), '') IS NULL THEN
        material_name := 'AVISO'; material_type_id := NULL;
        status := 'Materials vazio após normalização';
        RETURN NEXT; RETURN;
    END IF;

    RETURN QUERY
    SELECT * FROM fn_process_composite_materials(
        p_product_id, v_combined, v_product.organization_id, p_replace_existing
    );
    RETURN;
END;
$$;


ALTER FUNCTION "public"."fn_process_product_materials_auto"("p_product_id" "uuid", "p_replace_existing" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_process_product_materials_auto"("p_product_id" "uuid", "p_replace_existing" boolean) IS 'Processa automaticamente os materiais de um produto usando o campo materials[].
Exemplo: Se produto tem materials = ["ABS e silicone"], 
         cria 2 registros em product_materials (ABS e Silicone).';



CREATE OR REPLACE FUNCTION "public"."fn_process_raw_v2"("p_supplier_id" "uuid", "p_batch_size" integer DEFAULT 100, "p_bulk_mode" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_std jsonb; v_prom jsonb; v_pkg jsonb;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;
  v_std  := public.fn_standardize_supplier(p_supplier_id, p_batch_size);
  v_prom := public.fn_promote_supplier(p_supplier_id, NULL);
  -- M12/M13: enriquecimento de embalagem pós-promoção
  v_pkg  := public.fn_enrich_packaging_post_promote(p_supplier_id, 500);
  RETURN jsonb_build_object(
    'success', true, 'redirected', true,
    'pipeline', 'fn_standardize_supplier + fn_promote_supplier + fn_enrich_packaging_post_promote',
    'supplier_id', p_supplier_id,
    'parents_processed',  COALESCE((v_prom->>'pais_promovidos')::int, 0),
    'variants_processed', COALESCE((v_prom->>'variantes_promovidas')::int, 0),
    'packaging_enrichment', v_pkg,
    'standardize', v_std, 'promote', v_prom);
END;
$$;


