CREATE OR REPLACE FUNCTION "public"."fn_product_images_health_check"() RETURNS TABLE("check_name" "text", "status" "text", "value" bigint, "threshold" bigint, "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- C01: Todas as imagens ativas são verified no CF
  RETURN QUERY SELECT
    'c01_all_active_verified'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images not verified in CF'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND cf_sync_status <> 'verified';

  -- C02: Zero orphans no CF — excludes images already tracked in remediation
  RETURN QUERY SELECT
    'c02_zero_cf_orphans'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'CF images not in product_images (untracked)'::text
  FROM cf_recon.cf_image c
  WHERE NOT EXISTS (
    SELECT 1 FROM public.product_images p
    WHERE p.cloudflare_image_id = c.image_id AND p.deleted_at IS NULL
  )
  AND NOT EXISTS (
    SELECT 1 FROM cf_recon.remediation r
    WHERE r.cf_image_id = c.image_id
      AND r.kind = 'cf_orphan_no_pi'
  );

  -- C03: Recon = product_images ativas (excluding tracked orphans from recon total)
  RETURN QUERY SELECT
    'c03_recon_pi_sync'::text,
    CASE WHEN ABS(c.recon_effective - c.pi_total) <= 5 THEN 'OK' ELSE 'WARN' END,
    ABS(c.recon_effective - c.pi_total), 5::bigint,
    'Difference between effective CF recon (excl. tracked orphans) and active product_images'::text
  FROM (SELECT
    (SELECT COUNT(*) FROM cf_recon.cf_image c2
     WHERE NOT EXISTS (
       SELECT 1 FROM cf_recon.remediation rem
       WHERE rem.cf_image_id = c2.image_id AND rem.kind = 'cf_orphan_no_pi'
     )
    ) AS recon_effective,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL) AS pi_total
  ) c;

  -- C04: Sem cloudflare_image_id duplicados
  RETURN QUERY SELECT
    'c04_no_duplicate_cf_id'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Duplicate cloudflare_image_id in active images'::text
  FROM (SELECT cloudflare_image_id
    FROM public.product_images WHERE deleted_at IS NULL
    GROUP BY cloudflare_image_id HAVING COUNT(*) > 1) dup;

  -- C05: Soft-delete sempre tem razão
  RETURN QUERY SELECT
    'c05_soft_delete_has_reason'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Soft-deleted images without deleted_reason'::text
  FROM public.product_images
  WHERE deleted_at IS NOT NULL AND (deleted_reason IS NULL OR deleted_reason = '');

  -- C06: Sem is_active=true em deletadas
  RETURN QUERY SELECT
    'c06_no_active_deleted'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active=true but soft-deleted images'::text
  FROM public.product_images
  WHERE deleted_at IS NOT NULL AND is_active = true;

  -- C07: Cadeias canônicas flat (sem encadeamento)
  RETURN QUERY SELECT
    'c07_canonical_chains_flat'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical pointing to non-root (chain detected)'::text
  FROM public.product_images pi_child
  JOIN public.product_images pi_root ON pi_root.id = pi_child.canonical_image_id
  WHERE pi_child.canonical_image_id IS NOT NULL AND pi_root.canonical_image_id IS NOT NULL;

  -- C08: Sem ciclos canônicos
  RETURN QUERY SELECT
    'c08_no_canonical_cycles'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical cycles detected (A→B, B→A)'::text
  FROM public.product_images a
  JOIN public.product_images b ON b.id = a.canonical_image_id AND b.canonical_image_id = a.id;

  -- C09: is_shared consistência
  RETURN QUERY SELECT
    'c09_shared_has_canonical'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'is_shared=true without canonical_image_id'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND is_shared = true AND canonical_image_id IS NULL;

  -- C10: URL CDN válida
  RETURN QUERY SELECT
    'c10_valid_cdn_urls'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with invalid url_cdn'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND (url_cdn IS NULL OR url_cdn NOT LIKE 'https://imagedelivery.net/%');

  -- C11: Format válido (sem null)
  RETURN QUERY SELECT
    'c11_no_null_format'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with NULL format'::text
  FROM public.product_images WHERE deleted_at IS NULL AND format IS NULL;

  -- C12: Alt-text cobertura (>=10 chars)
  RETURN QUERY SELECT
    'c12_alt_text_coverage'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with missing/short alt_text'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND (alt_text IS NULL OR LENGTH(alt_text) < 10);

  -- C13: Canonical não aponta para imagem deletada
  RETURN QUERY SELECT
    'c13_canonical_not_deleted'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical pointing to soft-deleted image'::text
  FROM public.product_images pi
  WHERE pi.canonical_image_id IS NOT NULL
    AND EXISTS (SELECT 1 FROM public.product_images root
      WHERE root.id = pi.canonical_image_id AND root.deleted_at IS NOT NULL);

  -- C14: Display_order sem nulos
  RETURN QUERY SELECT
    'c14_display_order_not_null'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with NULL display_order'::text
  FROM public.product_images WHERE deleted_at IS NULL AND display_order IS NULL;

  -- C15: products.primary_image_url em sync
  RETURN QUERY SELECT
    'c15_primary_image_url_sync'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'WARN' END,
    COUNT(*), 5::bigint,
    'Products where primary_image_url diverges from product_images primary'::text
  FROM public.products p
  JOIN public.product_images pi ON pi.product_id = p.id
    AND pi.is_primary = true AND pi.is_active = true AND pi.deleted_at IS NULL
  WHERE p.is_active = true AND (p.is_deleted IS NULL OR p.is_deleted = false)
    AND p.primary_image_url IS NOT NULL AND p.primary_image_url <> pi.url_cdn;

  -- C16: Deps whose content_hash does not match their canonical's content_hash
  RETURN QUERY SELECT
    'c16_canonical_hash_group_consistent'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Deps with content_hash mismatching their canonical group hash'::text
  FROM public.product_images dep
  JOIN public.product_images canon ON canon.id = dep.canonical_image_id
  WHERE dep.deleted_at IS NULL
    AND dep.canonical_image_id IS NOT NULL
    AND dep.content_hash IS NOT NULL
    AND canon.content_hash IS NOT NULL
    AND dep.content_hash <> canon.content_hash;

  -- C17: Open remediation items (known issues being tracked)
  RETURN QUERY SELECT
    'c17_open_remediation_items'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'WARN' END,
    COUNT(*), 0::bigint,
    'Open remediation items (CF orphans and other known issues pending resolution)'::text
  FROM cf_recon.remediation rem
  WHERE rem.status IN ('open', 'in_progress');

END;
$$;


ALTER FUNCTION "public"."fn_product_images_health_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_product_market_intelligence"("p_product_id" "uuid", "p_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'analytics'
    AS $$
DECLARE
  v_result jsonb;
  v_kpis jsonb;
  v_chart jsonb;
  v_suppliers jsonb;
  v_price_alerts jsonb;
  v_avg_depletion numeric;
  v_trend numeric;
  v_total_stock bigint;
  v_supplier_count bigint;
  v_demand_label text;
  v_classification text;
  v_turnover_score numeric;
BEGIN

  -- ═══════════════════════════════════
  -- KPIs PRINCIPAIS (período dinâmico)
  -- ═══════════════════════════════════
  WITH period_data AS (
    SELECT
      sd.supplier_id,
      SUM(sd.units_depleted) AS total_depleted,
      COUNT(*) FILTER (WHERE sd.sync_count > 0) AS active_days,
      MIN(sd.stock_close) AS min_stock,
      MAX(sd.stock_close) AS max_stock
    FROM stock_daily_summary sd
    WHERE sd.product_id = p_product_id
      AND sd.summary_date >= CURRENT_DATE - p_days
    GROUP BY sd.supplier_id
  ),
  -- Período recente (últimos 7 dias) pra calcular velocidade atual
  recent_data AS (
    SELECT
      SUM(sd.units_depleted) AS depleted_7d,
      COUNT(*) FILTER (WHERE sd.sync_count > 0) AS active_days_7d
    FROM stock_daily_summary sd
    WHERE sd.product_id = p_product_id
      AND sd.summary_date >= CURRENT_DATE - 7
  ),
  -- Estoque atual de cada fornecedor
  current_stock AS (
    SELECT 
      COUNT(DISTINCT vss.supplier_id) AS supplier_count,
      SUM(vss.stock_main_warehouse + vss.stock_other_warehouses) AS total_stock
    FROM variant_supplier_sources vss
    JOIN product_variants pv ON pv.id = vss.variant_id
    WHERE pv.product_id = p_product_id
      AND (vss.stock_main_warehouse + vss.stock_other_warehouses) > 0
  )
  SELECT INTO v_avg_depletion, v_total_stock, v_supplier_count
    COALESCE(
      (SELECT depleted_7d::numeric / NULLIF(active_days_7d, 0) FROM recent_data),
      COALESCE(SUM(pd.total_depleted)::numeric / NULLIF(SUM(pd.active_days), 0), 0)
    ),
    COALESCE(cs.total_stock, 0),
    COALESCE(cs.supplier_count, 0)
  FROM current_stock cs
  LEFT JOIN period_data pd ON true
  GROUP BY cs.total_stock, cs.supplier_count;

  -- Defaults se não houver dados
  v_avg_depletion := COALESCE(v_avg_depletion, 0);
  v_total_stock := COALESCE(v_total_stock, 0);
  v_supplier_count := COALESCE(v_supplier_count, 0);

  -- Tendência: comparar primeira metade vs segunda metade do período
  SELECT INTO v_trend
    CASE 
      WHEN COALESCE(first_half, 0) > 0 
      THEN ROUND(((second_half::numeric / NULLIF(first_half, 0)) - 1) * 100, 0)
      ELSE 0
    END
  FROM (
    SELECT
      SUM(CASE WHEN sd.summary_date < CURRENT_DATE - (p_days / 2) THEN sd.units_depleted ELSE 0 END) AS first_half,
      SUM(CASE WHEN sd.summary_date >= CURRENT_DATE - (p_days / 2) THEN sd.units_depleted ELSE 0 END) AS second_half
    FROM stock_daily_summary sd
    WHERE sd.product_id = p_product_id
      AND sd.summary_date >= CURRENT_DATE - p_days
  ) halves;

  v_trend := COALESCE(v_trend, 0);

  -- Classificação de demanda
  v_demand_label := CASE
    WHEN v_avg_depletion >= 10 AND v_trend > 10 THEN 'Muito Alta'
    WHEN v_avg_depletion >= 5 OR v_trend > 20 THEN 'Alta'
    WHEN v_avg_depletion >= 1 THEN 'Normal'
    WHEN v_avg_depletion > 0 THEN 'Baixa'
    ELSE 'Sem dados'
  END;

  -- Classificação do produto
  SELECT INTO v_classification, v_turnover_score
    CASE
      WHEN pi.is_hot_product THEN 'Quente'
      WHEN pi.is_stockout_risk THEN 'Risco de Ruptura'
      WHEN pi.is_stagnant THEN 'Estagnado'
      WHEN pi.is_negotiation_opportunity THEN 'Oportunidade'
      ELSE 'Normal'
    END,
    COALESCE(pi.turnover_score, 0)
  FROM mv_product_intelligence pi
  WHERE pi.product_id = p_product_id;

  v_classification := COALESCE(v_classification, 'Sem dados');
  v_turnover_score := COALESCE(v_turnover_score, 0);

  v_kpis := jsonb_build_object(
    'vendas_dia_media', ROUND(v_avg_depletion, 1),
    'demanda', v_demand_label,
    'demanda_crescendo', v_trend > 0,
    'tendencia_pct', v_trend,
    'disponivel_total', v_total_stock,
    'fornecedores_count', v_supplier_count,
    'potencial', v_turnover_score,
    'classificacao', v_classification,
    'dias_ate_ruptura', (
      SELECT ROUND(MIN(sv.days_to_stockout), 0)
      FROM mv_stock_velocity sv 
      WHERE sv.product_id = p_product_id
    )
  );

  -- ═══════════════════════════════════
  -- DADOS DO GRÁFICO (série temporal)
  -- ═══════════════════════════════════
  SELECT INTO v_chart
    COALESCE(jsonb_agg(
      jsonb_build_object(
        'data', dia.summary_date,
        'disponivel', dia.disponivel,
        'compras_mercado', dia.compras,
        'reposicao', dia.reposicao
      ) ORDER BY dia.summary_date
    ), '[]'::jsonb)
  FROM (
    SELECT
      sd.summary_date,
      SUM(sd.stock_close) AS disponivel,
      SUM(sd.units_depleted) AS compras,
      SUM(CASE WHEN sd.restock_detected THEN sd.restock_quantity ELSE 0 END) AS reposicao
    FROM stock_daily_summary sd
    WHERE sd.product_id = p_product_id
      AND sd.summary_date >= CURRENT_DATE - p_days
    GROUP BY sd.summary_date
  ) dia;

  -- ═══════════════════════════════════
  -- COMPARATIVO POR FORNECEDOR
  -- ═══════════════════════════════════
  SELECT INTO v_suppliers
    COALESCE(jsonb_agg(
      jsonb_build_object(
        'fornecedor', sup.name,
        'supplier_id', sup.supplier_id,
        'saida_dia', sup.saida_dia,
        'estoque', sup.estoque,
        'tendencia_pct', sup.tendencia_pct,
        'maior_saida', sup.ranking = 1,
        'preco_atual', sup.preco_atual,
        'dias_ate_ruptura', sup.dias_ruptura
      ) ORDER BY sup.saida_dia DESC NULLS LAST
    ), '[]'::jsonb)
  FROM (
    SELECT 
      s.name,
      sv.supplier_id,
      sv.avg_daily_depletion_7d AS saida_dia,
      sv.current_stock AS estoque,
      ROUND((COALESCE(sv.velocity_trend, 1) - 1) * 100, 0) AS tendencia_pct,
      sv.current_price AS preco_atual,
      ROUND(sv.days_to_stockout, 0) AS dias_ruptura,
      RANK() OVER (ORDER BY sv.avg_daily_depletion_7d DESC NULLS LAST) AS ranking
    FROM mv_stock_velocity sv
    JOIN suppliers s ON s.id = sv.supplier_id
    WHERE sv.product_id = p_product_id
  ) sup;

  -- ═══════════════════════════════════
  -- ALERTAS DE PREÇO
  -- ═══════════════════════════════════
  SELECT INTO v_price_alerts
    COALESCE(jsonb_agg(
      jsonb_build_object(
        'fornecedor', s.name,
        'mudancas_preco_30d', sv.price_changes_30d
      )
    ), '[]'::jsonb)
  FROM mv_stock_velocity sv
  JOIN suppliers s ON s.id = sv.supplier_id
  WHERE sv.product_id = p_product_id
    AND sv.price_changes_30d > 0;

  -- ═══════════════════════════════════
  -- RESULTADO FINAL
  -- ═══════════════════════════════════
  v_result := jsonb_build_object(
    'product_id', p_product_id,
    'periodo_dias', p_days,
    'kpis', v_kpis,
    'grafico', v_chart,
    'fornecedores', v_suppliers,
    'alertas_preco', v_price_alerts,
    'gerado_em', now()
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_product_market_intelligence"("p_product_id" "uuid", "p_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_product_market_intelligence"("p_product_id" "uuid", "p_days" integer) IS 'Retorna todos os dados necessários para a tela de Inteligência de Mercado de um produto: KPIs, gráfico temporal, comparativo de fornecedores e alertas de preço. Parâmetro p_days permite filtrar por qualquer período (15, 30, 60, 90, 120, 180, 360 dias).';



CREATE OR REPLACE FUNCTION "public"."fn_product_name_quality_score"("p_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_score   integer := 100;
  v_issues  text[]  := '{}';
BEGIN
  -- Nome nulo ou vazio (erro grave)
  IF p_name IS NULL OR length(TRIM(p_name)) = 0 THEN
    RETURN jsonb_build_object(
      'score',  0,
      'issues', ARRAY['name_null_or_empty'],
      'grade',  'F'
    );
  END IF;

  -- Espaços duplos ou laterais
  IF p_name LIKE '%  %' THEN
    v_score  := v_score - 25;
    v_issues := array_append(v_issues, 'double_spaces');
  END IF;
  IF p_name <> TRIM(p_name) THEN
    v_score  := v_score - 15;
    v_issues := array_append(v_issues, 'leading_trailing_spaces');
  END IF;

  -- Tabs / newlines / carriage return
  IF p_name ~ E'[\\t\\n\\r]' THEN
    v_score  := v_score - 25;
    v_issues := array_append(v_issues, 'contains_tabs_newlines');
  END IF;

  -- Comprimento excessivo
  IF length(p_name) > 150 THEN
    v_score  := v_score - 20;
    v_issues := array_append(v_issues, 'too_long_over_150');
  ELSIF length(p_name) > 100 THEN
    v_score  := v_score - 10;
    v_issues := array_append(v_issues, 'long_100_to_150');
  END IF;

  -- Muito curto (< 8 chars — dificulta busca)
  IF length(TRIM(p_name)) < 8 THEN
    v_score  := v_score - 15;
    v_issues := array_append(v_issues, 'too_short_under_8');
  END IF;

  -- Todo UPPERCASE (é padrão de variants, não de products)
  IF p_name = UPPER(p_name) AND p_name ~ '[A-Za-z]{3,}' THEN
    v_score  := v_score - 15;
    v_issues := array_append(v_issues, 'all_uppercase_variant_style');
  END IF;

  -- Sem letras ou números
  IF p_name !~ '[A-Za-zÀ-ú0-9]' THEN
    v_score  := v_score - 10;
    v_issues := array_append(v_issues, 'no_alphanumeric');
  END IF;

  -- Unicode além de Latin Extended + ™®©
  IF p_name ~ '[^\x00-\xFF™®©]' THEN
    v_score  := v_score - 5;
    v_issues := array_append(v_issues, 'unusual_unicode');
  END IF;

  -- Curly quotes (U+2018/U+2019) — devem ser substituídas por apostrofe simples
  IF p_name ~ U&'\2018|\2019' THEN
    v_score  := v_score - 5;
    v_issues := array_append(v_issues, 'curly_quotes');
  END IF;

  -- Clamp 0-100
  v_score := GREATEST(0, LEAST(100, v_score));

  RETURN jsonb_build_object(
    'score',  v_score,
    'issues', v_issues,
    'length', length(p_name),
    'grade',  CASE
                WHEN v_score >= 90 THEN 'A'
                WHEN v_score >= 75 THEN 'B'
                WHEN v_score >= 60 THEN 'C'
                WHEN v_score >= 40 THEN 'D'
                ELSE 'F'
              END
  );
END;
$$;


ALTER FUNCTION "public"."fn_product_name_quality_score"("p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_product_name_quality_score"("p_name" "text") IS 'Retorna score 0-100 de qualidade de products.name com issues detalhados.
NÃO usar para product_variants.name (que é UPPER por design).
Deduções: double_spaces(-25), tabs_newlines(-25), all_uppercase(-15),
too_short(-15), too_long(-10...-20), no_alphanumeric(-10), unusual_unicode(-5), curly_quotes(-5).';



CREATE OR REPLACE FUNCTION "public"."fn_products_capture_manual_edits"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_src text := current_setting('app.write_source', true);
  v_campos text[] := ARRAY[
    'name','description','short_description','sku','cost_price','sale_price','suggested_price',
    'primary_image_url','images','ncm_code','weight_g','height_cm','width_cm','length_cm',
    'dimensions_display','box_length_cm','box_width_cm','box_height_cm','box_weight_kg','box_volume_cm3',
    'box_quantity','box_inner_quantity','brand','packing_type','repacking_type','capacities','capacity_ml',
    'min_quantity','stock_quantity','is_active','warranty_months','ipi_rate','engraving_type','colors',
    'category_id','main_category_id'
  ];
  v_campo text;
  v_old jsonb := to_jsonb(OLD);
  v_new jsonb := to_jsonb(NEW);
BEGIN
  IF TG_OP = 'UPDATE' AND COALESCE(v_src,'ui') <> 'pipeline' THEN
    FOREACH v_campo IN ARRAY v_campos LOOP
      IF (v_old -> v_campo) IS DISTINCT FROM (v_new -> v_campo) THEN
        IF NOT (v_campo = ANY(NEW.locked_fields)) THEN
          NEW.locked_fields := array_append(NEW.locked_fields, v_campo);
        END IF;
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_products_capture_manual_edits"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_products_quality_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total   integer;
  v_ativos  integer;
  v_result  jsonb;
  v_by_sup  jsonb;
BEGIN
  SELECT COUNT(*) INTO v_total FROM products;
  SELECT COUNT(*) INTO v_ativos FROM products WHERE is_active = true;

  SELECT jsonb_agg(t.row_data)
  INTO v_by_sup
  FROM (
    SELECT jsonb_build_object(
      'supplier', COALESCE(s.name,'(sem fornecedor)'),
      'total',  COUNT(*)::int,
      'ativos', COUNT(*) FILTER (WHERE p.is_active)::int
    ) AS row_data,
    COUNT(*) AS cnt
    FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
    GROUP BY s.name
    ORDER BY COUNT(*) DESC
  ) t;

  v_result := jsonb_build_object(
    'snapshot_at', now(),
    'totais', jsonb_build_object(
      'total', v_total, 'ativos', v_ativos,
      'inativos', v_total-v_ativos,
      'is_deleted', (SELECT COUNT(*)::int FROM products WHERE is_deleted=true)
    ),
    'cobertura_pct', jsonb_build_object(
      'description',ROUND(100.0*(SELECT COUNT(*) FROM products WHERE description IS NOT NULL AND length(description)>10)/NULLIF(v_total,0),1),
      'ncm',         ROUND(100.0*(SELECT COUNT(*) FROM products WHERE ncm_code IS NOT NULL)/NULLIF(v_total,0),1),
      'ipi_rate',    ROUND(100.0*(SELECT COUNT(*) FROM products WHERE ipi_rate IS NOT NULL)/NULLIF(v_total,0),1),
      'weight',      ROUND(100.0*(SELECT COUNT(*) FROM products WHERE weight_g IS NOT NULL)/NULLIF(v_total,0),1),
      'dimensions',  ROUND(100.0*(SELECT COUNT(*) FROM products WHERE length_cm IS NOT NULL AND width_cm IS NOT NULL)/NULLIF(v_total,0),1),
      'image',       ROUND(100.0*(SELECT COUNT(*) FROM products WHERE primary_image_url IS NOT NULL)/NULLIF(v_total,0),1),
      'slug',        ROUND(100.0*(SELECT COUNT(*) FROM products WHERE slug IS NOT NULL)/NULLIF(v_total,0),1),
      'ai_desc',     ROUND(100.0*(SELECT COUNT(*) FROM products WHERE ai_description IS NOT NULL AND length(ai_description)>10)/NULLIF(v_total,0),1)
    ),
    'nome_grade', jsonb_build_object(
      'A',(SELECT COUNT(*)::int FROM products WHERE (fn_product_name_quality_score(name)->>'grade')='A'),
      'B',(SELECT COUNT(*)::int FROM products WHERE (fn_product_name_quality_score(name)->>'grade')='B'),
      'C',(SELECT COUNT(*)::int FROM products WHERE (fn_product_name_quality_score(name)->>'grade')='C')
    ),
    'estoque', jsonb_build_object(
      'ruptura',(SELECT COUNT(*)::int FROM products WHERE is_stockout=true AND is_active=true),
      'com',(SELECT COUNT(*)::int FROM products WHERE stock_quantity>0 AND is_active=true),
      'avg_qty',ROUND((SELECT AVG(stock_quantity) FROM products WHERE is_active=true AND stock_quantity>0)::numeric,0)
    ),
    'seo', jsonb_build_object(
      'sem_slug',(SELECT COUNT(*)::int FROM products WHERE slug IS NULL AND is_deleted IS NOT TRUE),
      'sem_meta',(SELECT COUNT(*)::int FROM products WHERE meta_title IS NULL AND is_active=true)
    ),
    'ai_queue', jsonb_build_object(
      'pending',(SELECT COUNT(*)::int FROM ai_enrichment_queue WHERE status='pending'),
      'done',(SELECT COUNT(*)::int FROM ai_enrichment_queue WHERE status='done'),
      'error',(SELECT COUNT(*)::int FROM ai_enrichment_queue WHERE status='error')
    ),
    'por_fornecedor', v_by_sup
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_products_quality_dashboard"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_products_quality_dashboard"() IS 'Dashboard de qualidade do catálogo. SELECT fn_products_quality_dashboard(); Criado 2026-06-23.';



CREATE OR REPLACE FUNCTION "public"."fn_promote_category_fallback"("p_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  BEGIN
    SELECT c.category_id INTO v_id
    FROM public.classify_xbz_category(p_name) c
    ORDER BY CASE c.confidence WHEN 'alta' THEN 1 WHEN 'média' THEN 2 ELSE 3 END
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN v_id := NULL;
  END;
  IF v_id IS NULL THEN
    v_id := public.fn_classify_category_residual(p_name);
  END IF;
  RETURN v_id;
END;
$$;


