CREATE OR REPLACE FUNCTION "public"."fn_promote_kit_ficha_staging"("p_only_sku" "text" DEFAULT NULL::"text") RETURNS TABLE("promoted" integer, "no_component" integer, "ambiguous" integer, "skipped" integer, "pending" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE r record; v_pid uuid; v_norm text; v_kind text; v_comp uuid; v_cnt int; v_conf numeric; v_src_url text; v_tie int;
BEGIN
  FOR r IN SELECT * FROM kit_component_ficha_staging
           WHERE match_status='pending' AND (p_only_sku IS NULL OR product_sku=p_only_sku)
           ORDER BY product_sku, id
  LOOP
    v_norm := fn_norm_piece_label(r.piece_label);
    SELECT id INTO v_pid FROM products WHERE sku=r.product_sku AND is_kit=true;
    IF v_pid IS NULL THEN
      UPDATE kit_component_ficha_staging SET match_status='no_component', notes='kit nao encontrado/is_kit=false', piece_norm=v_norm WHERE id=r.id; CONTINUE;
    END IF;

    v_kind := r.piece_kind;
    IF v_kind IS NULL THEN
      IF v_norm ~ '(maleta|estojo|pouch|bolsa|sacola|necessaire|\mcase\M)' THEN v_kind:='packaging';
      ELSIF v_norm ~ 'embalagem' OR fn_norm_piece_label(coalesce(r.raw_text,'')) ~ '(papel|papelao)' THEN v_kind:='outer_box';
      ELSE v_kind:='item'; END IF;
    END IF;

    IF v_kind='outer_box' THEN
      UPDATE kit_component_ficha_staging SET match_status='skipped', piece_kind='outer_box', product_id=v_pid, piece_norm=v_norm,
             notes='caixa de transporte, nao e componente' WHERE id=r.id; CONTINUE;
    END IF;

    v_comp:=NULL; v_conf:=NULL; v_tie:=0;
    IF v_kind='packaging' THEN
      SELECT count(*) INTO v_cnt FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging;
      IF v_cnt=1 THEN SELECT id INTO v_comp FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging; v_conf:=0.95;
      ELSIF v_cnt>1 THEN
        SELECT id, extensions.similarity(fn_norm_piece_label(component_name), v_norm) INTO v_comp, v_conf
        FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging
        ORDER BY extensions.similarity(fn_norm_piece_label(component_name), v_norm) DESC NULLS LAST LIMIT 1;
      END IF;
    ELSE
      WITH cand AS (
        SELECT c.id,
          CASE WHEN fn_norm_piece_label(c.component_name)=v_norm THEN 1.00
               WHEN length(fn_norm_piece_label(c.component_name))>=4 AND v_norm LIKE '%'||fn_norm_piece_label(c.component_name)||'%' THEN 0.92
               WHEN length(v_norm)>=4 AND fn_norm_piece_label(c.component_name) LIKE '%'||v_norm||'%' THEN 0.90
               ELSE extensions.similarity(fn_norm_piece_label(c.component_name), v_norm) END AS score
        FROM product_kit_components c WHERE c.kit_product_id=v_pid AND NOT c.is_packaging
      ), ranked AS (SELECT id, score, row_number() OVER (ORDER BY score DESC) rn FROM cand)
      SELECT id, score, (SELECT count(*) FROM ranked r2 WHERE r2.score >= ranked.score - 0.08 AND r2.id<>ranked.id)
        INTO v_comp, v_conf, v_tie FROM ranked WHERE rn=1;
      -- exato (>=0.999) vence sempre; nao-exato exige ausencia de empate e >=0.50
      IF v_conf IS NULL OR v_conf < 0.50 OR (v_conf < 0.999 AND v_tie > 0) THEN v_comp:=NULL; END IF;
    END IF;

    IF v_comp IS NULL THEN
      UPDATE kit_component_ficha_staging
        SET match_status = CASE WHEN v_tie>0 THEN 'ambiguous' ELSE 'no_component' END,
            piece_kind=v_kind, product_id=v_pid, piece_norm=v_norm,
            notes = CASE WHEN v_tie>0 THEN 'rotulo casa com multiplos componentes' ELSE 'nenhum componente '||v_kind||' casou' END
        WHERE id=r.id; CONTINUE;
    END IF;

    v_src_url := coalesce(r.source_url, (SELECT spr.site_data->>'ficha_tecnica_pdf' FROM supplier_products_raw spr WHERE spr.product_id=v_pid AND spr.site_data ? 'ficha_tecnica_pdf' LIMIT 1));

    IF v_kind='packaging' THEN
      UPDATE product_kit_components SET pkg_ext_height_mm=r.dim_a_mm, pkg_ext_width_mm=r.dim_l_mm, pkg_ext_length_mm=r.dim_p_mm,
             dim_source='ficha', dim_source_url=v_src_url
       WHERE id=v_comp AND coalesce(dim_source,'heuristic') IN ('heuristic','supplier_api');
    ELSE
      UPDATE product_kit_components SET height_mm=r.dim_a_mm, width_mm=r.dim_l_mm, length_mm=r.dim_p_mm,
             weight_g=CASE WHEN weight_g IS NULL AND r.weight_g IS NOT NULL THEN r.weight_g ELSE weight_g END,
             dim_source='ficha', dim_source_url=v_src_url
       WHERE id=v_comp AND coalesce(dim_source,'heuristic') IN ('heuristic','supplier_api');
    END IF;

    UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_comp, piece_kind=v_kind,
           product_id=v_pid, piece_norm=v_norm, match_confidence=round(coalesce(v_conf,0)::numeric,3), promoted_at=now(), notes=NULL
     WHERE id=r.id;
  END LOOP;

  RETURN QUERY SELECT count(*) FILTER (WHERE match_status='promoted')::int, count(*) FILTER (WHERE match_status='no_component')::int,
                      count(*) FILTER (WHERE match_status='ambiguous')::int, count(*) FILTER (WHERE match_status='skipped')::int,
                      count(*) FILTER (WHERE match_status='pending')::int
               FROM kit_component_ficha_staging WHERE (p_only_sku IS NULL OR product_sku=p_only_sku);
END $$;


ALTER FUNCTION "public"."fn_promote_kit_ficha_staging"("p_only_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_promote_notebook_specs"("p_product_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 500, "p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_processed   int := 0;
  v_inserted    int := 0;
  v_updated     int := 0;
  v_feat_added  int := 0;
  v_skipped     int := 0;
  v_errors      int := 0;
  v_error_sample text[] := ARRAY[]::text[];

  -- Cursor de produtos
  r RECORD;

  -- Valores extraídos
  v_format_code   text;
  v_ruling_code   text;
  v_weight_gsm    int;
  v_color_code    text;
  v_binding_code  text;
  v_binding_color text;
  v_cover_type    text;
  v_cover_mat     text;
  v_cover_finish  text;
  v_sheets        int;
  v_feature_codes text[];
  v_confidence    numeric;

  -- IDs das lookup tables
  v_format_id    uuid; v_ruling_id   uuid; v_weight_id   uuid;
  v_color_id     uuid; v_binding_id  uuid; v_bcolor_id   uuid;
  v_ctype_id     uuid; v_cmat_id     uuid; v_cfinish_id  uuid;
  v_feat_id      uuid;
  v_spec_id      uuid;

  v_lock_key     bigint := 88675432;  -- advisory lock para evitar runs paralelos
BEGIN
  -- ── Advisory lock (não-blocking) ─────────────────────────────
  IF NOT pg_try_advisory_xact_lock(v_lock_key) THEN
    RETURN jsonb_build_object('skipped','already_running');
  END IF;

  -- ── Cursor de produtos a processar ───────────────────────────
  FOR r IN (
    SELECT DISTINCT
      p.id                         AS product_id,
      p.supplier_id,
      s.name                       AS supplier_name,
      pp.supplier_reference,
      pp.supplier_subtype,
      pp.supplier_subtype_code,
      pp.name,
      pp.description,
      pp.combined_sizes,
      pp.materials,
      pp.tags,
      pp.meta_keywords,
      pp.is_textil
    FROM products p
    JOIN suppliers s ON s.id = p.supplier_id
    -- Pegar dados do Silver (último promoted para este product_id)
    JOIN LATERAL (
      SELECT pp2.*
      FROM produtos_padronizacao pp2
      WHERE pp2.product_id = p.id
        AND pp2.status = 'promoted'
      ORDER BY pp2.promoted_at DESC NULLS LAST
      LIMIT 1
    ) pp ON true
    -- Filtrar por produto específico OU todos sem spec (ou force=true)
    WHERE (p_product_id IS NULL OR p.id = p_product_id)
      AND p.is_active = true
      AND fn_is_graphic_material(
            pp.supplier_subtype, pp.supplier_subtype_code,
            pp.name, pp.meta_keywords, pp.tags, pp.is_textil
          ) = true
      AND (
        p_force = true
        OR NOT EXISTS (
          SELECT 1 FROM product_notebook_specs pns WHERE pns.product_id = p.id
        )
      )
    ORDER BY p.id
    LIMIT p_limit
  ) LOOP

    BEGIN  -- Per-product exception block
      v_processed := v_processed + 1;

      -- ── Extrair todos os atributos ──────────────────────────
      v_format_code  := fn_parse_paper_format(r.tags, r.name, r.description, r.combined_sizes);
      v_ruling_code  := fn_parse_paper_ruling(r.tags, r.name, r.description);
      v_weight_gsm   := fn_parse_paper_weight(r.description);
      v_color_code   := fn_parse_paper_color_code(r.tags, r.description);
      v_binding_code := fn_parse_binding_type_code(r.name, r.description);
      v_cover_type   := fn_parse_cover_type_code(r.name, r.description);
      v_cover_mat    := fn_parse_cover_material_code(r.materials, r.name, r.description);
      v_cover_finish := NULL;  -- extraído via COVER_FINISHES na v2
      v_sheets       := fn_parse_sheet_count(r.description);
      v_feature_codes := fn_extract_notebook_feature_codes(r.tags, r.description, r.name);

      -- ── Resolver binding color ──────────────────────────────
      v_binding_color := fn_parse_binding_color_code(r.description);

      -- ── Calcular confidence score ───────────────────────────
      v_confidence := (
        (CASE WHEN v_format_code  IS NOT NULL THEN 0.20 ELSE 0 END) +
        (CASE WHEN v_cover_mat    IS NOT NULL THEN 0.20 ELSE 0 END) +
        (CASE WHEN v_ruling_code  IS NOT NULL THEN 0.15 ELSE 0 END) +
        (CASE WHEN v_cover_type   IS NOT NULL THEN 0.15 ELSE 0 END) +
        (CASE WHEN v_sheets       IS NOT NULL THEN 0.15 ELSE 0 END) +
        (CASE WHEN v_weight_gsm   IS NOT NULL THEN 0.10 ELSE 0 END) +
        (CASE WHEN v_binding_code IS NOT NULL THEN 0.05 ELSE 0 END)
      )::numeric(3,2);

      -- ── Resolver IDs das lookup tables ─────────────────────
      SELECT id INTO v_format_id   FROM paper_formats   WHERE code = v_format_code;
      SELECT id INTO v_ruling_id   FROM paper_rulings   WHERE code = v_ruling_code;
      SELECT id INTO v_weight_id   FROM paper_weights   WHERE weight_gsm = v_weight_gsm;
      SELECT id INTO v_color_id    FROM paper_colors    WHERE code = v_color_code;
      SELECT id INTO v_binding_id  FROM binding_types   WHERE code = v_binding_code;
      SELECT id INTO v_bcolor_id   FROM binding_colors  WHERE code = v_binding_color;
      SELECT id INTO v_ctype_id    FROM cover_types     WHERE code = v_cover_type;
      SELECT id INTO v_cmat_id     FROM cover_materials WHERE code = v_cover_mat;
      -- cover_finish: detectar MATTE/SOFT_TOUCH/GLOSSY via nome/descrição
      SELECT id INTO v_cfinish_id FROM cover_finishes WHERE code = (
        CASE 
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%soft touch%' THEN 'SOFT_TOUCH'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%fosco%' THEN 'MATTE'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%brilhante%' THEN 'GLOSSY'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%metalizado%' THEN 'METALLIC'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%alto relevo%' OR
               lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%emboss%' THEN 'EMBOSSED'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%baixo relevo%' OR
               lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%deboss%' THEN 'DEBOSSED'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%uv%' THEN 'UV_SPOT'
          ELSE NULL
        END
      );

      -- ── UPSERT em product_notebook_specs ───────────────────
      INSERT INTO product_notebook_specs (
        product_id, paper_format_id, paper_ruling_id, paper_weight_id,
        paper_color_id, binding_type_id, binding_color_id,
        cover_type_id, cover_material_id, cover_finish_id,
        sheet_count, source_supplier, confidence_score
      ) VALUES (
        r.product_id, v_format_id, v_ruling_id, v_weight_id,
        v_color_id, v_binding_id, v_bcolor_id,
        v_ctype_id, v_cmat_id, v_cfinish_id,
        v_sheets, r.supplier_name, v_confidence
      )
      ON CONFLICT (product_id) DO UPDATE SET
        paper_format_id   = EXCLUDED.paper_format_id,
        paper_ruling_id   = EXCLUDED.paper_ruling_id,
        paper_weight_id   = EXCLUDED.paper_weight_id,
        paper_color_id    = EXCLUDED.paper_color_id,
        binding_type_id   = EXCLUDED.binding_type_id,
        binding_color_id  = EXCLUDED.binding_color_id,
        cover_type_id     = EXCLUDED.cover_type_id,
        cover_material_id = EXCLUDED.cover_material_id,
        cover_finish_id   = EXCLUDED.cover_finish_id,
        sheet_count       = EXCLUDED.sheet_count,
        source_supplier   = EXCLUDED.source_supplier,
        confidence_score  = EXCLUDED.confidence_score,
        updated_at        = now()
      WHERE product_notebook_specs.manually_reviewed = false
      RETURNING id INTO v_spec_id;

      IF v_spec_id IS NOT NULL THEN
        v_inserted := v_inserted + 1;
      ELSE
        -- updated (ON CONFLICT hit mas NOT RETURNING = manually reviewed, skip)
        v_updated := v_updated + 1;
      END IF;

      -- ── Sincronizar product_notebook_features ───────────────
      -- Remove features antigas não-manuais e reinsere
      DELETE FROM product_notebook_features
      WHERE product_id = r.product_id;

      FOREACH v_format_code IN ARRAY coalesce(v_feature_codes, ARRAY[]::text[]) LOOP
        SELECT id INTO v_feat_id FROM notebook_features WHERE code = v_format_code;
        IF v_feat_id IS NOT NULL THEN
          INSERT INTO product_notebook_features (product_id, feature_id)
          VALUES (r.product_id, v_feat_id)
          ON CONFLICT (product_id, feature_id) DO NOTHING;
          v_feat_added := v_feat_added + 1;
        END IF;
      END LOOP;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      v_error_sample := array_append(v_error_sample,
        format('%s: %s', r.supplier_reference, SQLERRM)
      );
      IF array_length(v_error_sample, 1) > 5 THEN EXIT; END IF;
    END;

  END LOOP;

  v_skipped := p_limit - v_processed;
  IF v_skipped < 0 THEN v_skipped := 0; END IF;

  RETURN jsonb_build_object(
    'processed',      v_processed,
    'inserted',       v_inserted,
    'updated',        v_updated,
    'features_added', v_feat_added,
    'errors',         v_errors,
    'error_samples',  v_error_sample,
    'confidence_avg', (
      SELECT round(avg(confidence_score)::numeric, 2)
      FROM product_notebook_specs
      WHERE updated_at > now() - interval '5 minutes'
    )
  );
END;
$$;


ALTER FUNCTION "public"."fn_promote_notebook_specs"("p_product_id" "uuid", "p_limit" integer, "p_force" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_promote_notebook_specs"("p_product_id" "uuid", "p_limit" integer, "p_force" boolean) IS 'Promove specs de material gráfico do Silver → Gold. 
   Usa advisory lock. Idempotente. Respeita manually_reviewed=true.
   Retorna jsonb com métricas de execução.';



CREATE OR REPLACE FUNCTION "public"."fn_promote_packaging_to_gold"("p_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_batch_size" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_promoted_included  INT := 0;
    v_promoted_compat    INT := 0;
    v_promoted_type      INT := 0;
    v_errors             INT := 0;
BEGIN
    -- ─────────────────────────────────────────────────────────
    -- PASSO 1: Atualizar product_type='packaging' para produtos
    --          que têm is_packaging_product=true no Silver
    --          (via product_packaging.has_optional_packaging e packing_classification)
    -- ─────────────────────────────────────────────────────────
    WITH candidates AS (
        SELECT DISTINCT pp.product_id
        FROM product_packaging pp
        JOIN products p ON p.id = pp.product_id
        WHERE p.product_type <> 'packaging'
          AND pp.packing_classification = 'packaging_product'
          AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
        LIMIT p_batch_size
    )
    UPDATE products p
    SET product_type = 'packaging', updated_at = now()
    FROM candidates c
    WHERE p.id = c.product_id;
    GET DIAGNOSTICS v_promoted_type = ROW_COUNT;

    -- ─────────────────────────────────────────────────────────
    -- PASSO 2: Criar/atualizar product_included_packagings
    --          a partir de product_packaging (Silver) onde
    --          has_commercial_packaging = true e sem registo existente
    -- ─────────────────────────────────────────────────────────
    WITH silver AS (
        SELECT 
            pp.product_id,
            pp.packing_type       AS pip_name,
            pp.packaging_material AS pip_material,
            pp.packaging_color    AS pip_color,
            pp.packaging_finish   AS pip_finish,
            pp.has_inner_cradle   AS pip_cradle,
            pp.cradle_material    AS pip_cradle_mat,
            p.supplier_id
        FROM product_packaging pp
        JOIN products p ON p.id = pp.product_id
        WHERE pp.packing_classification = 'commercial'
          AND pp.packing_type IS NOT NULL
          AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
          AND NOT EXISTS (
              SELECT 1 FROM product_included_packagings pip
              WHERE pip.product_id = pp.product_id AND pip.active = true
          )
        LIMIT p_batch_size
    )
    INSERT INTO product_included_packagings (
        product_id, name, material, color, finish,
        has_inner_cradle, cradle_material,
        can_be_customized, can_be_disabled, is_default,
        supplier_id, ingest_source, active
    )
    SELECT 
        product_id,
        COALESCE(NULLIF(trim(pip_name),''), 'Embalagem'),
        pip_material,
        pip_color,
        pip_finish,
        COALESCE(pip_cradle, false),
        pip_cradle_mat,
        -- Determinar can_be_customized por material
        CASE WHEN pip_material ILIKE ANY(ARRAY['%polybag%','%plástico bolha%','%película%'])
             THEN false ELSE true END,
        true,   -- can_be_disabled
        true,   -- is_default
        supplier_id,
        CASE 
            WHEN supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0' THEN 'spot_properties'
            WHEN supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118' THEN 'asia_manual'
            WHEN supplier_id = '841cd690-210a-422a-908c-7676828db272' THEN 'sm_scraping'
            WHEN supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900' THEN 'xbz_manual'
            ELSE 'pipeline_auto'
        END,
        true
    FROM silver
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_promoted_included = ROW_COUNT;

    -- ─────────────────────────────────────────────────────────
    -- PASSO 3: Criar compatibilidades supplier_indicated
    --          a partir de optional_packaging_ref em products
    -- ─────────────────────────────────────────────────────────
    WITH refs AS (
        SELECT DISTINCT
            p.id AS product_id,
            p.optional_packaging_ref AS ref_sku
        FROM products p
        WHERE p.optional_packaging_ref IS NOT NULL
          AND p.is_active = true
          AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
    ),
    resolved AS (
        SELECT r.product_id, pkg.id AS packaging_id
        FROM refs r
        JOIN products pkg ON pkg.sku = r.ref_sku AND pkg.product_type = 'packaging' AND pkg.is_active = true
        WHERE NOT EXISTS (
            SELECT 1 FROM product_packaging_compatibility ppc
            WHERE ppc.product_id = r.product_id AND ppc.packaging_id = pkg.id
        )
        LIMIT p_batch_size
    )
    INSERT INTO product_packaging_compatibility (
        product_id, packaging_id, compatibility_source,
        is_recommended, is_same_supplier, active
    )
    SELECT 
        product_id, packaging_id, 'supplier_indicated',
        true,
        (SELECT supplier_id FROM products WHERE id = product_id) = 
        (SELECT supplier_id FROM products WHERE id = packaging_id),
        true
    FROM resolved
    ON CONFLICT (product_id, packaging_id) DO NOTHING;
    GET DIAGNOSTICS v_promoted_compat = ROW_COUNT;

    RETURN jsonb_build_object(
        'success',           true,
        'promoted_type',     v_promoted_type,
        'promoted_included', v_promoted_included,
        'promoted_compat',   v_promoted_compat,
        'errors',            v_errors,
        'supplier_id',       p_supplier_id,
        'batch_size',        p_batch_size,
        'executed_at',       now()
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error',   SQLERRM,
        'sqlstate', SQLSTATE
    );
END;
$$;


ALTER FUNCTION "public"."fn_promote_packaging_to_gold"("p_supplier_id" "uuid", "p_batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_promote_packaging_to_gold"("p_supplier_id" "uuid", "p_batch_size" integer) IS 'Pipeline Silver → Gold para módulo de embalagens.
- Passo 1: Classifica products como product_type=packaging
- Passo 2: Cria product_included_packagings a partir de product_packaging (Silver)
- Passo 3: Cria product_packaging_compatibility supplier_indicated via optional_packaging_ref
p_supplier_id: NULL = todos | UUID = fornecedor específico
p_batch_size: limite por execução (default 500)';



CREATE OR REPLACE FUNCTION "public"."fn_promote_padronizacao"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  s        public.produtos_padronizacao%ROWTYPE;
  v_pid    uuid;
  v_org    uuid;
  v_locked text[];
  v_is_new boolean := false;
  v_cat_id   uuid    := NULL;
  v_cat_src  text;
  v_cat_l1   text;
  v_existing_cat uuid := NULL;
  v_min_qty  integer := NULL;
  v_display_name text;
BEGIN
  SELECT * INTO s FROM public.produtos_padronizacao WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'padronizacao_nao_encontrada', 'id', p_id);
  END IF;
  IF s.status <> 'standardized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'status_invalido', 'status', s.status);
  END IF;

  PERFORM set_config('app.write_source',     'pipeline', true);
  PERFORM set_config('app.bulk_import_mode', 'true',     true);

  v_display_name := public.fn_display_product_name(s.name);

  SELECT id, locked_fields, category_id INTO v_pid, v_locked, v_existing_cat
  FROM public.products
  WHERE supplier_id = s.supplier_id AND supplier_reference = s.supplier_reference;

  IF v_pid IS NULL THEN
    v_is_new := true;
    SELECT organization_id INTO v_org FROM public.suppliers WHERE id = s.supplier_id;
    INSERT INTO public.products (organization_id, supplier_id, supplier_reference, sku, name, is_active, product_type, category_id)
    VALUES (v_org, s.supplier_id, s.supplier_reference,
            COALESCE(s.supplier_reference, s.name),
            COALESCE(v_display_name, s.name, 'Produto ' || s.supplier_reference),
            true, 'product', 'c0000000-0000-0000-0000-000000000000')
    RETURNING id, locked_fields INTO v_pid, v_locked;
  END IF;

  v_locked := COALESCE(v_locked, '{}');

  -- Categoria nível 1
  IF s.raw_id IS NOT NULL AND NOT ('category_id' = ANY(v_locked)) THEN
    BEGIN
      SELECT sfm.source_field INTO v_cat_src
      FROM public.supplier_field_mappings sfm
      WHERE sfm.supplier_id = s.supplier_id AND sfm.target_field = 'categories'
      LIMIT 1;
      IF v_cat_src IS NOT NULL THEN
        SELECT split_part(COALESCE(spr.raw_data ->> v_cat_src, ''), '|', 1)
        INTO v_cat_l1
        FROM public.supplier_products_raw spr WHERE spr.id = s.raw_id;
        IF v_cat_l1 IS NOT NULL AND TRIM(v_cat_l1) <> '' THEN
          SELECT scm.category_id INTO v_cat_id
          FROM public.supplier_categories sc
          JOIN public.supplier_category_mappings scm ON scm.supplier_category_id = sc.id
          WHERE sc.supplier_id = s.supplier_id AND TRIM(sc.supplier_code) = TRIM(v_cat_l1)
          LIMIT 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  IF v_cat_id IS NULL AND v_existing_cat IS NULL AND NOT ('category_id' = ANY(v_locked)) THEN
    v_cat_id := public.fn_promote_category_fallback(s.name);
  END IF;

  IF s.min_quantity IS NOT NULL THEN
    SELECT GREATEST(s.min_quantity, COALESCE(c.min_order_quantity, 1))
    INTO v_min_qty
    FROM public.categories c
    WHERE c.id = COALESCE(v_cat_id,
        (SELECT category_id FROM public.products WHERE id = v_pid));
    v_min_qty := COALESCE(v_min_qty, s.min_quantity);
  END IF;

  UPDATE public.products p SET
    sku                = COALESCE(p.sku, s.supplier_reference, s.name),
    name               = CASE WHEN 'name'               = ANY(v_locked) THEN p.name               ELSE COALESCE(v_display_name, s.name, p.name)           END,
    description        = CASE WHEN 'description'        = ANY(v_locked) THEN p.description        ELSE COALESCE(s.description,        p.description)        END,
    short_description  = CASE WHEN 'short_description'  = ANY(v_locked) THEN p.short_description  ELSE COALESCE(s.short_description,  p.short_description)  END,
    cost_price         = CASE WHEN 'cost_price'         = ANY(v_locked) THEN p.cost_price         ELSE COALESCE(NULLIF(s.cost_price,      0), p.cost_price)      END,
    suggested_price    = CASE WHEN 'suggested_price'    = ANY(v_locked) THEN p.suggested_price    ELSE COALESCE(NULLIF(s.suggested_price, 0), p.suggested_price) END,
    stock_quantity     = CASE WHEN 'stock_quantity'     = ANY(v_locked) THEN p.stock_quantity     ELSE COALESCE(s.stock_quantity,     p.stock_quantity)     END,
    min_quantity       = CASE WHEN 'min_quantity'       = ANY(v_locked) THEN p.min_quantity
                              WHEN v_min_qty IS NOT NULL                THEN v_min_qty
                              ELSE COALESCE(s.min_quantity, p.min_quantity)              END,
    primary_image_url  = CASE
      WHEN 'primary_image_url' = ANY(v_locked)        THEN p.primary_image_url
      WHEN p.primary_image_url LIKE '%imagedelivery%' THEN p.primary_image_url
      ELSE COALESCE(s.primary_image_url, p.primary_image_url)
    END,
    images             = CASE WHEN 'images'             = ANY(v_locked) THEN p.images             ELSE COALESCE(s.images,             p.images)             END,
    ncm_code           = CASE WHEN 'ncm_code'           = ANY(v_locked) THEN p.ncm_code           ELSE COALESCE(NULLIF(s.ncm_code,'00000000'), p.ncm_code)  END,
    weight_g           = CASE WHEN 'weight_g'           = ANY(v_locked) THEN p.weight_g           ELSE COALESCE(NULLIF(s.weight_g,   0), p.weight_g)   END,
    height_cm          = CASE WHEN 'height_cm'          = ANY(v_locked) THEN p.height_cm          ELSE COALESCE(NULLIF(s.height_cm,  0), p.height_cm)  END,
    width_cm           = CASE WHEN 'width_cm'           = ANY(v_locked) THEN p.width_cm           ELSE COALESCE(NULLIF(s.width_cm,   0), p.width_cm)   END,
    length_cm          = CASE WHEN 'length_cm'          = ANY(v_locked) THEN p.length_cm          ELSE COALESCE(NULLIF(s.length_cm,  0), p.length_cm)  END,
    circumference_cm   = CASE WHEN 'circumference_cm'   = ANY(v_locked) THEN p.circumference_cm   ELSE COALESCE(NULLIF(s.circumference_cm, 0), p.circumference_cm) END,
    diameter_cm        = CASE WHEN 'diameter_cm'        = ANY(v_locked) THEN p.diameter_cm        ELSE COALESCE(NULLIF(s.diameter_cm, 0), p.diameter_cm) END,
    dimensions_display = CASE WHEN 'dimensions_display' = ANY(v_locked) THEN p.dimensions_display ELSE COALESCE(s.dimensions_display, p.dimensions_display) END,
    box_length_cm      = CASE WHEN 'box_length_cm'      = ANY(v_locked) THEN p.box_length_cm      ELSE COALESCE(s.box_length_cm,      p.box_length_cm)      END,
    box_width_cm       = CASE WHEN 'box_width_cm'       = ANY(v_locked) THEN p.box_width_cm       ELSE COALESCE(s.box_width_cm,       p.box_width_cm)       END,
    box_height_cm      = CASE WHEN 'box_height_cm'      = ANY(v_locked) THEN p.box_height_cm      ELSE COALESCE(s.box_height_cm,      p.box_height_cm)      END,
    box_weight_kg      = CASE WHEN 'box_weight_kg'      = ANY(v_locked) THEN p.box_weight_kg      ELSE COALESCE(s.box_weight_kg,      p.box_weight_kg)      END,
    box_volume_cm3     = CASE WHEN 'box_volume_cm3'     = ANY(v_locked) THEN p.box_volume_cm3     ELSE COALESCE(s.box_volume_cm3,     p.box_volume_cm3)     END,
    box_quantity       = CASE WHEN 'box_quantity'       = ANY(v_locked) THEN p.box_quantity       ELSE COALESCE(s.box_quantity,       p.box_quantity)       END,
    box_inner_quantity = CASE WHEN 'box_inner_quantity' = ANY(v_locked) THEN p.box_inner_quantity ELSE COALESCE(s.box_inner_quantity, p.box_inner_quantity) END,
    brand              = CASE WHEN 'brand'              = ANY(v_locked) THEN p.brand              ELSE COALESCE(s.brand,              p.brand)              END,
    packing_type       = CASE WHEN 'packing_type'       = ANY(v_locked) THEN p.packing_type       ELSE COALESCE(s.packing_type,       p.packing_type)       END,
    repacking_type     = CASE WHEN 'repacking_type'     = ANY(v_locked) THEN p.repacking_type     ELSE COALESCE(s.repacking_type,     p.repacking_type)     END,
    capacities         = CASE WHEN 'capacities'         = ANY(v_locked) THEN p.capacities         ELSE COALESCE(s.capacities,         p.capacities)         END,
    capacity_ml        = CASE WHEN 'capacity_ml'        = ANY(v_locked) THEN p.capacity_ml        ELSE COALESCE(NULLIF(s.capacity_ml, 0), p.capacity_ml) END,
    ipi_rate           = CASE WHEN 'ipi_rate'           = ANY(v_locked) THEN p.ipi_rate           ELSE COALESCE(s.ipi_rate,           p.ipi_rate)           END,
    engraving_type     = CASE WHEN 'engraving_type'     = ANY(v_locked) THEN p.engraving_type     ELSE COALESCE(s.engraving_type,     p.engraving_type)     END,
    colors             = CASE WHEN 'colors'             = ANY(v_locked) THEN p.colors             ELSE COALESCE(s.colors,             p.colors)             END,
    combined_sizes     = CASE WHEN 'combined_sizes'     = ANY(v_locked) THEN p.combined_sizes     ELSE COALESCE(s.combined_sizes,     p.combined_sizes)     END,
    box_image          = CASE WHEN 'box_image'          = ANY(v_locked) THEN p.box_image          ELSE COALESCE(s.box_image,          p.box_image)          END,
    is_textil          = CASE WHEN 'is_textil'          = ANY(v_locked) THEN p.is_textil          ELSE COALESCE(s.is_textil,          p.is_textil)          END,
    category_id        = CASE WHEN 'category_id'        = ANY(v_locked) THEN p.category_id        ELSE COALESCE(v_cat_id, v_existing_cat, p.category_id)     END,
    updated_at         = now()
  WHERE p.id = v_pid;

  INSERT INTO public.product_physical (product_id, weight_g, height_cm, width_cm, length_cm, diameter_cm, circumference_cm, capacity_ml)
  VALUES (v_pid, NULLIF(s.weight_g,0), NULLIF(s.height_cm,0), NULLIF(s.width_cm,0), NULLIF(s.length_cm,0), NULLIF(s.diameter_cm,0), NULLIF(s.circumference_cm,0), NULLIF(s.capacity_ml,0))
  ON CONFLICT (product_id) DO UPDATE SET
    weight_g         = COALESCE(public.product_physical.weight_g,         EXCLUDED.weight_g),
    height_cm        = COALESCE(public.product_physical.height_cm,        EXCLUDED.height_cm),
    width_cm         = COALESCE(public.product_physical.width_cm,         EXCLUDED.width_cm),
    length_cm        = COALESCE(public.product_physical.length_cm,        EXCLUDED.length_cm),
    diameter_cm      = COALESCE(public.product_physical.diameter_cm,      EXCLUDED.diameter_cm),
    circumference_cm = COALESCE(public.product_physical.circumference_cm, EXCLUDED.circumference_cm),
    capacity_ml      = COALESCE(public.product_physical.capacity_ml,      EXCLUDED.capacity_ml),
    updated_at       = now();

  UPDATE public.produtos_padronizacao SET status = 'promoted', product_id = v_pid, updated_at = now()
  WHERE id = p_id;

  RETURN jsonb_build_object('success', true, 'created', v_is_new, 'product_id', v_pid);
END;
$$;


ALTER FUNCTION "public"."fn_promote_padronizacao"("p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_promote_padronizacao"("p_id" "uuid") IS 'Promove uma linha silver→products com merge soberano: campos em products.locked_fields nunca são sobrescritos pelo fornecedor.';



CREATE OR REPLACE FUNCTION "public"."fn_promote_supplier"("p_supplier_id" "uuid", "p_limit" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_par RECORD;
  v_prom jsonb; v_vres jsonb;
  v_pais int := 0; v_novos int := 0; v_var int := 0; v_erros int := 0;
  v_orfas int := 0;
  v_t0 timestamptz := clock_timestamp();
  v_err_amostra jsonb := '[]'::jsonb;
  v_created boolean; v_vcount int;
BEGIN
  PERFORM set_config('app.write_source','pipeline', true);

  FOR v_par IN
    SELECT id, supplier_reference
    FROM public.produtos_padronizacao
    WHERE supplier_id = p_supplier_id AND status = 'standardized'
    ORDER BY supplier_reference
    LIMIT p_limit
  LOOP
    BEGIN
      v_prom := public.fn_promote_padronizacao(v_par.id);
      IF NOT COALESCE((v_prom->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'pai_falhou:%', COALESCE(v_prom->>'error','desconhecido');
      END IF;
      v_created := COALESCE((v_prom->>'created')::boolean, false);

      v_vres := public.fn_promote_variants_of_parent(p_supplier_id, v_par.supplier_reference);
      IF NOT COALESCE((v_vres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'variantes_falharam:%', COALESCE(v_vres->>'error','desconhecido');
      END IF;
      v_vcount := COALESCE((v_vres->>'variantes_promovidas')::int, 0);

      v_pais := v_pais + 1;
      IF v_created THEN v_novos := v_novos + 1; END IF;
      v_var := v_var + v_vcount;

    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra || jsonb_build_object('ref', v_par.supplier_reference, 'erro', SQLERRM);
      END IF;
      BEGIN
        UPDATE public.supplier_products_raw r
           SET process_errors = jsonb_build_object(
                 'stage','promote','parent', v_par.supplier_reference,
                 'erro', SQLERRM, 'at', now())
         WHERE r.supplier_id = p_supplier_id
           AND r.status IN ('pending','failed')
           AND r.id IN (
             SELECT pv.raw_id FROM public.produtos_padronizacao_variantes pv
              WHERE pv.supplier_id = p_supplier_id
                AND pv.parent_reference = v_par.supplier_reference
                AND pv.raw_id IS NOT NULL
             UNION
             SELECT pp.raw_id FROM public.produtos_padronizacao pp
              WHERE pp.id = v_par.id AND pp.raw_id IS NOT NULL);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END;
  END LOOP;

  -- SWEEP 2026-06-11: variantes 'standardized' órfãs (pai já no Gold).
  FOR v_par IN
    SELECT DISTINCT pv.parent_reference AS supplier_reference
    FROM public.produtos_padronizacao_variantes pv
    JOIN public.products p
      ON p.supplier_id = pv.supplier_id
     AND p.supplier_reference = pv.parent_reference
    WHERE pv.supplier_id = p_supplier_id
      AND pv.status = 'standardized'
      AND NULLIF(pv.parent_reference, '') IS NOT NULL
  LOOP
    BEGIN
      v_vres := public.fn_promote_variants_of_parent(p_supplier_id, v_par.supplier_reference);
      IF NOT COALESCE((v_vres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'sweep_falhou:%', COALESCE(v_vres->>'error','desconhecido');
      END IF;
      v_orfas := v_orfas + COALESCE((v_vres->>'variantes_promovidas')::int, 0);
    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra
          || jsonb_build_object('ref', v_par.supplier_reference, 'stage', 'sweep', 'erro', SQLERRM);
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'supplier_id', p_supplier_id,
    'pais_promovidos', v_pais, 'pais_novos', v_novos, 'variantes_promovidas', v_var,
    'variantes_orfas_promovidas', v_orfas,
    'erros', v_erros, 'amostra_erros', v_err_amostra,
    'segundos', round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,1));
END $$;


ALTER FUNCTION "public"."fn_promote_supplier"("p_supplier_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_promote_supplier"("p_supplier_id" "uuid", "p_limit" integer) IS 'Orquestrador Silver->Gold por fornecedor. Promove pais standardized (atomico pai+variantes) e, desde 2026-06-11, faz sweep de variantes standardized orfas cujo pai ja esta no Gold (backfills/re-padronizacoes). NULL-safe, idempotente.';



CREATE OR REPLACE FUNCTION "public"."fn_promote_variants_of_parent"("p_supplier_id" "uuid", "p_parent_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_pid uuid; v_org uuid; pv RECORD; v_vid uuid; v_count int := 0; v_attrs jsonb;
  v_existing_pid uuid;
BEGIN
  PERFORM set_config('app.write_source','pipeline',true);
  SELECT id, organization_id INTO v_pid, v_org FROM public.products
  WHERE supplier_id=p_supplier_id AND supplier_reference=p_parent_reference;
  IF v_pid IS NULL THEN RETURN jsonb_build_object('success',false,'error','produto_pai_nao_promovido','parent',p_parent_reference); END IF;

  FOR pv IN
    SELECT * FROM public.produtos_padronizacao_variantes
    WHERE supplier_id=p_supplier_id AND parent_reference=p_parent_reference AND status='standardized'
  LOOP
    -- M2 2026-06-11: tamanho entra nos attributes (jsonb_strip_nulls ignora NULL)
    v_attrs := jsonb_strip_nulls(jsonb_build_object('cor', pv.color_name, 'codigo_cor', pv.color_code, 'hex', pv.color_hex, 'tamanho', pv.size_code));

    SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants WHERE sku = pv.sku;
    IF v_vid IS NULL THEN
      SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants
      WHERE product_id=v_pid AND supplier_sku=pv.supplier_sku;
    END IF;

    IF v_vid IS NULL THEN
      INSERT INTO public.product_variants (product_id, sku, supplier_sku, name, attributes, color_name, color_code, color_hex, color_id, stock_quantity, is_active, last_sync_at, last_sync_supplier_id,
                                           size_code, size_length_cm, size_width_cm, capacity_ml)
      VALUES (v_pid, pv.sku, pv.supplier_sku, COALESCE(pv.color_name, pv.sku), v_attrs,
              pv.color_name, pv.color_code, pv.color_hex, pv.color_id,
              COALESCE(pv.stock_quantity,0), COALESCE(pv.is_active,true), now(), p_supplier_id,
              pv.size_code, pv.size_length_cm, pv.size_width_cm, pv.capacity_ml)
      ON CONFLICT (sku) DO UPDATE SET
        supplier_sku = EXCLUDED.supplier_sku,
        attributes   = COALESCE(public.product_variants.attributes,'{}'::jsonb) || EXCLUDED.attributes,
        color_name   = COALESCE(EXCLUDED.color_name, public.product_variants.color_name),
        color_code   = COALESCE(EXCLUDED.color_code, public.product_variants.color_code),
        color_hex    = COALESCE(EXCLUDED.color_hex, public.product_variants.color_hex),
        color_id     = COALESCE(EXCLUDED.color_id, public.product_variants.color_id),
        stock_quantity = CASE WHEN public.product_variants.is_active
                              THEN COALESCE(EXCLUDED.stock_quantity, public.product_variants.stock_quantity)
                              ELSE 0 END,
        size_code      = COALESCE(EXCLUDED.size_code, public.product_variants.size_code),
        size_length_cm = COALESCE(EXCLUDED.size_length_cm, public.product_variants.size_length_cm),
        size_width_cm  = COALESCE(EXCLUDED.size_width_cm, public.product_variants.size_width_cm),
        capacity_ml    = COALESCE(EXCLUDED.capacity_ml, public.product_variants.capacity_ml),
        last_sync_at = now(), last_sync_supplier_id = EXCLUDED.last_sync_supplier_id
      RETURNING id INTO v_vid;
    ELSE
      UPDATE public.product_variants SET
        attributes = COALESCE(attributes,'{}'::jsonb) || v_attrs,
        color_name=COALESCE(pv.color_name,color_name), color_code=COALESCE(pv.color_code,color_code),
        color_hex=COALESCE(pv.color_hex,color_hex), color_id=COALESCE(pv.color_id,color_id),
        stock_quantity = CASE WHEN is_active THEN COALESCE(pv.stock_quantity, stock_quantity) ELSE 0 END,
        size_code=COALESCE(pv.size_code,size_code),
        size_length_cm=COALESCE(pv.size_length_cm,size_length_cm),
        size_width_cm=COALESCE(pv.size_width_cm,size_width_cm),
        capacity_ml=COALESCE(pv.capacity_ml,capacity_ml),
        last_sync_at=now(), last_sync_supplier_id=p_supplier_id
      WHERE id=v_vid;
    END IF;

    -- FIX (chk_vss_cost_price_not_zero): só grava source de custo quando custo > 0.
    IF pv.cost_price IS NOT NULL AND pv.cost_price > 0 THEN
      INSERT INTO public.variant_supplier_sources (organization_id, variant_id, supplier_id, cost_price, supplier_sku, supplier_color_code, supplier_color_name, is_active, source, last_synced_at)
      VALUES (v_org, v_vid, p_supplier_id, pv.cost_price, pv.supplier_sku, pv.color_code, pv.color_name, true, 'silver', now())
      ON CONFLICT (variant_id, supplier_id) DO UPDATE SET
        cost_price          = EXCLUDED.cost_price,
        supplier_sku        = EXCLUDED.supplier_sku,
        supplier_color_code = EXCLUDED.supplier_color_code,
        supplier_color_name = EXCLUDED.supplier_color_name,
        is_active           = EXCLUDED.is_active,
        source              = EXCLUDED.source,
        last_synced_at      = EXCLUDED.last_synced_at;
    END IF;

    UPDATE public.produtos_padronizacao_variantes SET status='promoted', variant_id=v_vid, updated_at=now() WHERE id=pv.id;

    -- 3-fases: raw concluída ao chegar no Gold. FIX: limpa process_errors
    -- (promoção bem-sucedida supera erro anterior; respeita chk_spr_no_processed_with_errors).
    IF pv.raw_id IS NOT NULL THEN
      UPDATE public.supplier_products_raw
         SET status='processed', processed_at=now(), product_id=v_pid, variant_id=v_vid,
             process_errors=NULL
       WHERE id=pv.raw_id AND status <> 'processed';
    END IF;

    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('success',true,'product_id',v_pid,'variantes_promovidas',v_count);
END;
$$;


ALTER FUNCTION "public"."fn_promote_variants_of_parent"("p_supplier_id" "uuid", "p_parent_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_propagar_atualizacao_cor"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Só propaga se nome ou hex mudou
    IF OLD.name IS DISTINCT FROM NEW.name OR OLD.hex_code IS DISTINCT FROM NEW.hex_code THEN
        UPDATE product_variants
        SET 
            color_name = NEW.name,
            color_hex = NEW.hex_code,
            updated_at = now()
        WHERE color_id = NEW.id;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_propagar_atualizacao_cor"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_propagar_atualizacao_cor"() IS 'Propaga mudanças de nome/hex da cor para todas as variantes vinculadas';



CREATE OR REPLACE FUNCTION "public"."fn_propagate_category_min_quantity"("p_category_id" "uuid", "p_new_min_quantity" integer) RETURNS TABLE("updated_products" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_updated INTEGER;
BEGIN
    -- Atualizar todos os produtos da categoria que NÃO têm override
    UPDATE products
    SET min_quantity = p_new_min_quantity
    WHERE category_id = p_category_id
      AND min_order_quantity IS NULL;
    
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    
    RETURN QUERY SELECT v_updated;
END;
$$;


ALTER FUNCTION "public"."fn_propagate_category_min_quantity"("p_category_id" "uuid", "p_new_min_quantity" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_propagate_category_min_quantity"("p_category_id" "uuid", "p_new_min_quantity" integer) IS 'Propaga a quantidade mínima da categoria para todos os produtos
que não têm override (min_order_quantity IS NULL).
Usar quando alterar o min_order_quantity de uma categoria.';



CREATE OR REPLACE FUNCTION "public"."fn_purge_expired_restock_dates"("p_dry_run" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_pv_nd1  int:=0; v_pv_nd2 int:=0; v_pv_nd3 int:=0;
    v_pv_nd4  int:=0; v_pv_nd5 int:=0; v_pv_nd6 int:=0;
    v_vss_nd1 int:=0; v_vss_nd2 int:=0; v_vss_nd3 int:=0;
    v_vss_nd4 int:=0; v_vss_nd5 int:=0; v_vss_nd6 int:=0;
    v_silver  int:=0; v_inactive int:=0;
    v_today   date := CURRENT_DATE;
    v_t0      timestamptz := clock_timestamp();
BEGIN
    IF NOT pg_try_advisory_xact_lock(hashtext('fn_purge_expired_restock_dates')::bigint) THEN
        RETURN jsonb_build_object('skipped','lock_ocupado','ts',now());
    END IF;
    PERFORM set_config('app.bulk_import_mode','true',true);
    PERFORM set_config('app.write_source','pipeline_cleanup',true);

    -- Diagnóstico
    SELECT COUNT(CASE WHEN next_date_1<v_today AND next_date_1 IS NOT NULL THEN 1 END),
           COUNT(CASE WHEN next_date_2<v_today AND next_date_2 IS NOT NULL THEN 1 END),
           COUNT(CASE WHEN next_date_3<v_today AND next_date_3 IS NOT NULL THEN 1 END),
           COUNT(CASE WHEN next_date_4<v_today AND next_date_4 IS NOT NULL THEN 1 END),
           COUNT(CASE WHEN next_date_5<v_today AND next_date_5 IS NOT NULL THEN 1 END),
           COUNT(CASE WHEN next_date_6<v_today AND next_date_6 IS NOT NULL THEN 1 END)
    INTO v_pv_nd1,v_pv_nd2,v_pv_nd3,v_pv_nd4,v_pv_nd5,v_pv_nd6 FROM product_variants;

    SELECT COUNT(CASE WHEN next_date_1<v_today AND next_date_1 IS NOT NULL THEN 1 END),
           COUNT(CASE WHEN next_date_2<v_today AND next_date_2 IS NOT NULL THEN 1 END),
           COUNT(CASE WHEN next_date_3<v_today AND next_date_3 IS NOT NULL THEN 1 END),
           COUNT(CASE WHEN next_date_4<v_today AND next_date_4 IS NOT NULL THEN 1 END),
           COUNT(CASE WHEN next_date_5<v_today AND next_date_5 IS NOT NULL THEN 1 END),
           COUNT(CASE WHEN next_date_6<v_today AND next_date_6 IS NOT NULL THEN 1 END)
    INTO v_vss_nd1,v_vss_nd2,v_vss_nd3,v_vss_nd4,v_vss_nd5,v_vss_nd6 FROM variant_supplier_sources;

    SELECT COUNT(*) INTO v_silver FROM produtos_padronizacao_variantes
    WHERE next_date_1 IS NOT NULL AND next_date_1 < v_today;

    SELECT COUNT(*) INTO v_inactive FROM product_variants
    WHERE is_active=false AND (next_date_1 IS NOT NULL OR next_date_2 IS NOT NULL);

    IF p_dry_run THEN
        RETURN jsonb_build_object('dry_run',true,
            'pv',  jsonb_build_object('nd1',v_pv_nd1,'nd2',v_pv_nd2,'nd3',v_pv_nd3,'nd4',v_pv_nd4,'nd5',v_pv_nd5,'nd6',v_pv_nd6),
            'vss', jsonb_build_object('nd1',v_vss_nd1,'nd2',v_vss_nd2,'nd3',v_vss_nd3,'nd4',v_vss_nd4,'nd5',v_vss_nd5,'nd6',v_vss_nd6),
            'silver_expiradas',v_silver,'inactive_with_dates',v_inactive,'cutoff_date',v_today);
    END IF;

    -- PV (janelas 1-6)
    UPDATE product_variants SET next_date_1=NULL,next_quantity_1=NULL,updated_at=now() WHERE next_date_1 IS NOT NULL AND next_date_1<v_today;
    UPDATE product_variants SET next_date_2=NULL,next_quantity_2=NULL,updated_at=now() WHERE next_date_2 IS NOT NULL AND next_date_2<v_today;
    UPDATE product_variants SET next_date_3=NULL,next_quantity_3=NULL,updated_at=now() WHERE next_date_3 IS NOT NULL AND next_date_3<v_today;
    UPDATE product_variants SET next_date_4=NULL,next_quantity_4=NULL,updated_at=now() WHERE next_date_4 IS NOT NULL AND next_date_4<v_today;
    UPDATE product_variants SET next_date_5=NULL,next_quantity_5=NULL,updated_at=now() WHERE next_date_5 IS NOT NULL AND next_date_5<v_today;
    UPDATE product_variants SET next_date_6=NULL,next_quantity_6=NULL,updated_at=now() WHERE next_date_6 IS NOT NULL AND next_date_6<v_today;

    -- VSS (janelas 1-6)
    UPDATE variant_supplier_sources SET next_date_1=NULL,next_quantity_1=NULL,updated_at=now() WHERE next_date_1 IS NOT NULL AND next_date_1<v_today;
    UPDATE variant_supplier_sources SET next_date_2=NULL,next_quantity_2=NULL,updated_at=now() WHERE next_date_2 IS NOT NULL AND next_date_2<v_today;
    UPDATE variant_supplier_sources SET next_date_3=NULL,next_quantity_3=NULL,updated_at=now() WHERE next_date_3 IS NOT NULL AND next_date_3<v_today;
    UPDATE variant_supplier_sources SET next_date_4=NULL,next_quantity_4=NULL,updated_at=now() WHERE next_date_4 IS NOT NULL AND next_date_4<v_today;
    UPDATE variant_supplier_sources SET next_date_5=NULL,next_quantity_5=NULL,updated_at=now() WHERE next_date_5 IS NOT NULL AND next_date_5<v_today;
    UPDATE variant_supplier_sources SET next_date_6=NULL,next_quantity_6=NULL,updated_at=now() WHERE next_date_6 IS NOT NULL AND next_date_6<v_today;

    -- SILVER: rede de segurança contra re-injeção via Medallion tick
    UPDATE produtos_padronizacao_variantes
    SET next_date_1=NULL,next_quantity_1=NULL,next_date_2=NULL,next_quantity_2=NULL,
        next_date_3=NULL,next_quantity_3=NULL,updated_at=now()
    WHERE (next_date_1 IS NOT NULL AND next_date_1<v_today)
       OR (next_date_2 IS NOT NULL AND next_date_2<v_today)
       OR (next_date_3 IS NOT NULL AND next_date_3<v_today);

    -- Pares incoerentes
    UPDATE product_variants SET next_quantity_1=NULL WHERE next_date_1 IS NULL AND next_quantity_1 IS NOT NULL;
    UPDATE variant_supplier_sources SET next_quantity_1=NULL WHERE next_date_1 IS NULL AND next_quantity_1 IS NOT NULL;

    -- PASSO 4: inativas
    UPDATE product_variants SET
        next_date_1=NULL,next_quantity_1=NULL,next_date_2=NULL,next_quantity_2=NULL,
        next_date_3=NULL,next_quantity_3=NULL,next_date_4=NULL,next_quantity_4=NULL,
        next_date_5=NULL,next_quantity_5=NULL,next_date_6=NULL,next_quantity_6=NULL,
        updated_at=now()
    WHERE is_active=false AND (next_date_1 IS NOT NULL OR next_date_2 IS NOT NULL
        OR next_date_3 IS NOT NULL OR next_date_4 IS NOT NULL);

    RETURN jsonb_build_object('success',true,
        'pv_limpos',  jsonb_build_object('nd1',v_pv_nd1,'nd2',v_pv_nd2,'nd3',v_pv_nd3,'nd4',v_pv_nd4,'nd5',v_pv_nd5,'nd6',v_pv_nd6),
        'vss_limpos', jsonb_build_object('nd1',v_vss_nd1,'nd2',v_vss_nd2,'nd3',v_vss_nd3,'nd4',v_vss_nd4,'nd5',v_vss_nd5,'nd6',v_vss_nd6),
        'silver_limpos',v_silver,'inactive_cleaned',v_inactive,
        'cobertura','PV+VSS+SILVER+INATIVAS_6janelas',
        'segundos',round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,2),'ts',now());
END;
$$;


ALTER FUNCTION "public"."fn_purge_expired_restock_dates"("p_dry_run" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_purge_old_stock_snapshots"("p_retention_days" integer DEFAULT 60, "p_batch" integer DEFAULT 500000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cutoff timestamptz := now() - make_interval(days => GREATEST(p_retention_days, 31));
  v_deleted integer := 0;
BEGIN
  -- fix_version: purge_stock_snapshots_bounded_daily_v1
  -- lock transacional: se outra execucao roda, sai sem erro
  IF NOT pg_try_advisory_xact_lock(91010060) THEN
    RETURN jsonb_build_object('status','skipped_locked','ts',now());
  END IF;

  -- piso de seguranca: nunca apaga abaixo de 31 dias (protege o lookback de 30d do forecast)
  DELETE FROM public.stock_snapshots
   WHERE id IN (
     SELECT id FROM public.stock_snapshots
      WHERE captured_at < v_cutoff
      ORDER BY captured_at
      LIMIT GREATEST(p_batch, 1)
   );
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'status','ok',
    'cutoff', v_cutoff,
    'retention_days_efetivo', GREATEST(p_retention_days, 31),
    'batch', GREATEST(p_batch, 1),
    'deletados', v_deleted,
    'ts', now()
  );
END
$$;


ALTER FUNCTION "public"."fn_purge_old_stock_snapshots"("p_retention_days" integer, "p_batch" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_purge_spr_history"("p_keep_days" integer DEFAULT 90) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cutoff   timestamptz := now() - make_interval(days => GREATEST(p_keep_days, 30));
  v_deleted  integer := 0;
  v_n        integer;
  r          RECORD;
  v_m        date;
  v_nome     text;
BEGIN
  FOR r IN
    SELECT c.oid::regclass::text AS part,
           (regexp_match(pg_get_expr(c.relpartbound, c.oid),
                         'TO \(''([^'']+)''\)'))[1]::timestamptz AS ub
    FROM pg_inherits i
    JOIN pg_class c ON c.oid = i.inhrelid
    WHERE i.inhparent = 'public.supplier_products_raw_history'::regclass
  LOOP
    IF r.ub IS NOT NULL AND r.ub <= v_cutoff THEN
      EXECUTE format('DROP TABLE %s', r.part);
    END IF;
  END LOOP;

  IF to_regclass('archive.supplier_products_raw_history_legacy') IS NOT NULL THEN
    IF (SELECT max(captured_at)
        FROM archive.supplier_products_raw_history_legacy) < v_cutoff THEN
      EXECUTE 'DROP TABLE archive.supplier_products_raw_history_legacy';
      v_deleted := -1;
    END IF;
  END IF;

  FOR i IN 0..3 LOOP
    v_m := (date_trunc('month', now()) + (i || ' months')::interval)::date;
    v_nome := 'supplier_products_raw_history_p' || to_char(v_m, 'YYYY_MM');
    IF to_regclass('public.' || v_nome) IS NULL THEN
      EXECUTE format(
        'CREATE TABLE public.%I PARTITION OF public.supplier_products_raw_history'
        ' FOR VALUES FROM (%L) TO (%L)',
        v_nome, v_m, (v_m + interval '1 month')::date);
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', v_nome);
      EXECUTE format('CREATE POLICY hist_all_service ON public.%I FOR ALL TO service_role USING (true) WITH CHECK (true)', v_nome);
      EXECUTE format('CREATE POLICY hist_select_admin ON public.%I FOR SELECT TO authenticated USING (public.is_admin_or_above((SELECT auth.uid())))', v_nome);
    END IF;
  END LOOP;

  RETURN v_deleted;
END
$$;


ALTER FUNCTION "public"."fn_purge_spr_history"("p_keep_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_purge_spr_history"("p_keep_days" integer) IS 'Housekeeping do histórico Bronze.
Job1: DROP de partições de supplier_products_raw_history com data_fim < cutoff.
Job2: DROP de archive.supplier_products_raw_history_legacy quando max(captured_at) < cutoff
      (snapshot fixo — não recebe novos dados desde 2026-06-15). Retorna -1 se executou DROP.
Job3: CREATE de partições futuras (próximos 4 meses).
Guard: p_keep_days é flooreado em 30 para prevenir DROP acidental.
Cron: purge-spr-history-daily 03:30 daily com p_keep_days=90.';



CREATE OR REPLACE FUNCTION "public"."fn_qa_alert_on_activate_without_image"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_has_image boolean;
BEGIN
  -- Só dispara quando is_active muda de false/null → true
  IF NOT (OLD.is_active IS DISTINCT FROM NEW.is_active AND NEW.is_active = true) THEN
    RETURN NEW;
  END IF;

  -- Checar se há alguma imagem
  SELECT EXISTS(
    SELECT 1 FROM product_images pi WHERE pi.product_id = NEW.id AND pi.is_active = true
  ) OR COALESCE(NEW.primary_image_url, '') <> ''
    OR (jsonb_typeof(NEW.images) = 'array' AND jsonb_array_length(NEW.images) > 0)
  INTO v_has_image;

  IF NOT v_has_image THEN
    -- 'activated_no_image' = 18 chars (dentro do limit de VARCHAR(20))
    NEW.sync_status := 'activated_no_image';

    INSERT INTO product_qa_image_alerts (
      product_id, supplier_id, sku_promo, product_name, alert_type
    )
    VALUES (
      NEW.id, NEW.supplier_id,
      COALESCE(NEW.sku_promo, NEW.sku),
      left(NEW.name, 200),
      'active_without_image'
    )
    ON CONFLICT DO NOTHING;

    RAISE WARNING '[QA-ALERT] Produto % (SKU: %) ativado SEM imagem!',
      left(NEW.name,40), COALESCE(NEW.sku_promo, NEW.sku);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_qa_alert_on_activate_without_image"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_qa_check_image_coverage"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_crit int; v_semnorm int; v_sample jsonb;
BEGIN
  SELECT count(*) FILTER (WHERE severidade='CRITICO'),
         count(*) FILTER (WHERE severidade='SEM_NORMALIZACAO')
    INTO v_crit, v_semnorm
  FROM public.vw_qa_products_missing_images;

  SELECT jsonb_agg(x) INTO v_sample FROM (
    SELECT sku, name, supplier_id FROM public.vw_qa_products_missing_images
    WHERE severidade='CRITICO' LIMIT 20) x;

  INSERT INTO public.qa_image_coverage_log(critico_count, sem_normalizacao_count, sample)
  VALUES (v_crit, v_semnorm, COALESCE(v_sample,'[]'::jsonb));

  RETURN jsonb_build_object('ran_at', now(), 'critico', v_crit, 'sem_normalizacao', v_semnorm);
END;
$$;


ALTER FUNCTION "public"."fn_qa_check_image_coverage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_qa_scan_imageless_products"() RETURNS TABLE("total_violacoes" bigint, "alertas_novos" bigint, "alertas_resolvidos" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_novos bigint := 0; v_resolvidos bigint := 0; v_total bigint := 0;
BEGIN
  -- 1. Auto-resolver alertas: produto tem imagem agora, OU foi desativado/deletado
  WITH resolvidos AS (
    UPDATE product_qa_image_alerts qa
    SET is_resolved = true, resolved_at = now(),
        resolution_notes = CASE
          WHEN COALESCE(p.is_deleted, false) THEN 'produto deletado'
          WHEN NOT COALESCE(p.is_active, false) THEN 'produto desativado'
          ELSE 'imagem detectada na varredura automática'
        END
    FROM products p
    WHERE qa.product_id = p.id AND qa.is_resolved = false
      AND (
        COALESCE(p.is_deleted, false)              -- deletado → resolver
        OR NOT COALESCE(p.is_active, false)        -- desativado → resolver
        OR EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.is_active=true)
        OR COALESCE(p.primary_image_url,'') <> ''
        OR (jsonb_typeof(p.images)='array' AND jsonb_array_length(p.images)>0)
      )
    RETURNING qa.id
  )
  SELECT count(*) INTO v_resolvidos FROM resolvidos;

  -- 2. Detectar novos violadores (apenas ativos e não-deletados)
  WITH novos AS (
    INSERT INTO product_qa_image_alerts (product_id, supplier_id, sku_promo, product_name, alert_type)
    SELECT p.id, p.supplier_id, COALESCE(p.sku_promo, p.sku), left(p.name,200), 'active_without_image'
    FROM products p
    WHERE COALESCE(p.is_active,false) AND NOT COALESCE(p.is_deleted,false)
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.is_active=true)
      AND COALESCE(p.primary_image_url,'') = ''
      AND NOT (jsonb_typeof(p.images)='array' AND jsonb_array_length(p.images)>0)
      AND NOT EXISTS (SELECT 1 FROM product_qa_image_alerts qa WHERE qa.product_id=p.id AND qa.is_resolved=false)
    ON CONFLICT DO NOTHING
    RETURNING id
  )
  SELECT count(*) INTO v_novos FROM novos;

  SELECT count(*) INTO v_total FROM product_qa_image_alerts WHERE is_resolved=false;
  RETURN QUERY SELECT v_total, v_novos, v_resolvidos;
END;
$$;


ALTER FUNCTION "public"."fn_qa_scan_imageless_products"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_qip_propagate_to_quote_items"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _quote_item_id uuid;
  _new_personalization_cost numeric(12,2);
BEGIN
  _quote_item_id := COALESCE(NEW.quote_item_id, OLD.quote_item_id);
  
  SELECT COALESCE(SUM(total_cost), 0) INTO _new_personalization_cost
  FROM public.quote_item_personalizations
  WHERE quote_item_id = _quote_item_id;
  
  UPDATE public.quote_items 
  SET personalization_cost = _new_personalization_cost,
      has_personalization = (_new_personalization_cost > 0),
      updated_at = now()
  WHERE id = _quote_item_id
    AND personalization_cost IS DISTINCT FROM _new_personalization_cost;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."fn_qip_propagate_to_quote_items"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_qip_propagate_to_quote_items"() IS 'A1-6: Propaga mudancas em personalizations para quote_items.personalization_cost.';



CREATE OR REPLACE FUNCTION "public"."fn_quote_children_enforce_parent_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _parent_quote_id uuid;
  _parent_status text;
  _msg text;
BEGIN
  -- fix_version=2026-07-09-quote-children-immutability-bypass ANTI-REGRESSÃO
  -- Bypass para service_role via JWT claim (PostgREST com JWT token)
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- NOVO: Bypass para contexto sem usuário autenticado (service_role sem JWT,
  -- edge functions com service_role_key, execute_sql, migrations, crons).
  IF auth.uid() IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_TABLE_NAME = 'quote_items' THEN
    _parent_quote_id := COALESCE(NEW.quote_id, OLD.quote_id);
  ELSIF TG_TABLE_NAME = 'quote_item_personalizations' THEN
    SELECT qi.quote_id INTO _parent_quote_id
    FROM public.quote_items qi
    WHERE qi.id = COALESCE(NEW.quote_item_id, OLD.quote_item_id);
  END IF;

  IF _parent_quote_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT status INTO _parent_status
  FROM public.quotes WHERE id = _parent_quote_id;

  IF _parent_status IN ('approved', 'converted') THEN
    _msg := 'Nao e possivel alterar itens de orcamento ja aprovado/convertido (status ' ||
            _parent_status || '). Crie um novo orcamento.';
    RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."fn_quote_children_enforce_parent_immutability"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_quote_children_enforce_parent_immutability"() IS 'A1-2: Bloqueia INSERT/UPDATE/DELETE em quote_items e quote_item_personalizations quando quote pai esta em status approved ou converted.';



CREATE OR REPLACE FUNCTION "public"."fn_quote_items_calc_subtotal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  NEW.subtotal := COALESCE(NEW.quantity, 0) * COALESCE(NEW.unit_price, 0)
                + COALESCE(NEW.personalization_cost, 0)
                - COALESCE(NEW.discount_amount, 0);
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."fn_quote_items_calc_subtotal"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_quote_items_calc_subtotal"() IS 'Calcula subtotal: (quantity*unit_price) + personalization_cost - discount_amount. Resolve bug do hook que não envia subtotal.';



CREATE OR REPLACE FUNCTION "public"."fn_quotes_calc_real_values"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_markup numeric;
  v_effective_discount numeric;
BEGIN
  -- Cópia local clampada usada APENAS como divisor defensivo (não regrava a coluna).
  -- A faixa válida é garantida pelo CHECK valid_negotiation_markup_range ([0,50]):
  -- valores fora de faixa são rejeitados pelo constraint (fail-loud), não silenciados.
  v_markup := LEAST(50, GREATEST(0, COALESCE(NEW.negotiation_markup_percent, 0)));

  IF v_markup > 0 THEN
    NEW.real_subtotal := ROUND(NEW.subtotal / (1 + v_markup / 100.0), 2);
  ELSE
    NEW.real_subtotal := NEW.subtotal;
  END IF;

  -- Desconto efetivo derivado no servidor (não confia no cliente):
  -- se há percentual, ele tem precedência e é convertido sobre o subtotal apresentado;
  -- caso contrário usa o valor absoluto. Fecha o gap onde discount_percent setado
  -- com discount_amount=0 zerava o real_discount_percent e burlava a alçada.
  IF COALESCE(NEW.discount_percent, 0) > 0 THEN
    v_effective_discount := ROUND(NEW.subtotal * NEW.discount_percent / 100.0, 2);
  ELSE
    v_effective_discount := COALESCE(NEW.discount_amount, 0);
  END IF;

  IF NEW.real_subtotal > 0 THEN
    NEW.real_discount_percent := ROUND(
      ((NEW.real_subtotal - (NEW.subtotal - v_effective_discount)) / NEW.real_subtotal) * 100,
      2
    );
  ELSE
    NEW.real_discount_percent := 0;
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."fn_quotes_calc_real_values"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_quotes_calc_real_values"() IS 'Onda 19 follow-up: registra em migrations função que existia só como drift. Calcula real_subtotal e real_discount_percent a partir do subtotal COM markup; clamp markup 0-50%. Usada pelo trigger trg_quotes_calc_real_values.';



CREATE OR REPLACE FUNCTION "public"."fn_quotes_enforce_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _msg text;
BEGIN
  -- fix_version=2026-07-09-immutability-service-role-bypass ANTI-REGRESSÃO
  -- Bypass para service_role via JWT claim (PostgREST com JWT token)
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN NEW;
  END IF;

  -- NOVO: Bypass para contexto sem usuário autenticado (service_role sem JWT,
  -- edge functions com service_role_key, execute_sql, migrations, crons).
  -- auth.uid() IS NULL = indicador robusto de service_role sem JWT.
  -- O bypass request.jwt.claim.role acima falha quando NULL (NULL='service_role'→FALSE).
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF OLD.status NOT IN ('approved', 'converted') THEN
    RETURN NEW;
  END IF;

  IF OLD.* IS NOT DISTINCT FROM NEW.* THEN
    RETURN NEW;
  END IF;

  IF OLD.status <> NEW.status THEN
    IF (OLD.status = 'approved' AND NEW.status IN ('converted', 'expired'))
       OR (OLD.status = 'converted' AND NEW.status = 'expired') THEN
      IF (
        OLD.client_id IS DISTINCT FROM NEW.client_id OR
        OLD.client_name IS DISTINCT FROM NEW.client_name OR
        OLD.subtotal IS DISTINCT FROM NEW.subtotal OR
        OLD.discount_percent IS DISTINCT FROM NEW.discount_percent OR
        OLD.discount_amount IS DISTINCT FROM NEW.discount_amount OR
        OLD.total IS DISTINCT FROM NEW.total OR
        OLD.negotiation_markup_percent IS DISTINCT FROM NEW.negotiation_markup_percent OR
        OLD.real_subtotal IS DISTINCT FROM NEW.real_subtotal OR
        OLD.real_discount_percent IS DISTINCT FROM NEW.real_discount_percent OR
        OLD.shipping_cost IS DISTINCT FROM NEW.shipping_cost OR
        OLD.tax_amount IS DISTINCT FROM NEW.tax_amount OR
        OLD.seller_id IS DISTINCT FROM NEW.seller_id OR
        OLD.created_by IS DISTINCT FROM NEW.created_by OR
        OLD.assigned_to IS DISTINCT FROM NEW.assigned_to
      ) THEN
        _msg := 'Orcamento em status ' || OLD.status ||
                ' e imutavel. So a transicao de status e permitida; valores e atribuicoes nao podem mudar. Crie um novo orcamento.';
        RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    ELSE
      _msg := 'Transicao de status nao permitida: ' || OLD.status || ' para ' || NEW.status ||
              '. Orcamento em status ' || OLD.status || ' so pode ir para converted ou expired.';
      RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
    END IF;
  END IF;

  _msg := 'Orcamento em status ' || OLD.status ||
          ' e imutavel. Crie um novo orcamento para alterar valores.';
  RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
END;
$$;


ALTER FUNCTION "public"."fn_quotes_enforce_immutability"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_quotes_enforce_immutability"() IS 'A1-2: Bloqueia mudancas em quotes com status approved/converted. Permite apenas: approved->converted, approved->expired, converted->expired. service_role bypassa.';



CREATE OR REPLACE FUNCTION "public"."fn_quotes_recalc_subtotal_from_items"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _quote_id uuid;
  _quote_status text;
  _markup numeric;
  _disc_amount_db numeric;
  _disc_pct numeric;
  _ship_type text;
  _ship_cost numeric;
  _real_subtotal numeric(12,2);
  _new_subtotal numeric(12,2);
  _ship_value numeric(12,2);
  _disc_value numeric(12,2);
  _new_total numeric(12,2);
BEGIN
  _quote_id := COALESCE(NEW.quote_id, OLD.quote_id);
  IF _quote_id IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;

  SELECT
    status,
    LEAST(50, GREATEST(0, COALESCE(negotiation_markup_percent, 0))),
    COALESCE(discount_amount, 0),
    COALESCE(discount_percent, 0),
    shipping_type,
    COALESCE(shipping_cost, 0)
  INTO _quote_status, _markup, _disc_amount_db, _disc_pct, _ship_type, _ship_cost
  FROM public.quotes WHERE id = _quote_id;

  -- Nao mexer em quotes aprovados/convertidos (imutaveis)
  IF _quote_status IN ('approved', 'converted') THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- REAL: soma pura dos itens (sem markup)
  SELECT COALESCE(SUM(quantity * unit_price + COALESCE(personalization_cost, 0)), 0)
  INTO _real_subtotal
  FROM public.quote_items
  WHERE quote_id = _quote_id;

  -- APRESENTADO ao cliente: aplica markup
  _new_subtotal := ROUND(_real_subtotal * (1 + _markup / 100.0), 2);

  -- DESCONTO: discount_percent tem prioridade (espelha logica do frontend)
  IF _disc_pct > 0 THEN
    _disc_value := ROUND(_new_subtotal * (_disc_pct / 100.0), 2);
  ELSE
    _disc_value := _disc_amount_db;
  END IF;

  -- FRETE: somente 'fob_pre' (pré-negociado com custo) entra no total.
  -- Alinhado ao frontend (calculateQuoteTotals): cif/fob/null não somam.
  _ship_value := CASE WHEN _ship_type = 'fob_pre' THEN _ship_cost ELSE 0 END;

  -- TOTAL final
  _new_total := _new_subtotal - _disc_value + _ship_value;

  -- UPDATE apenas se mudou (evita loop com trigger BEFORE em quotes)
  UPDATE public.quotes
  SET subtotal = _new_subtotal,
      total = _new_total,
      discount_amount = _disc_value,
      updated_at = now()
  WHERE id = _quote_id
    AND (subtotal IS DISTINCT FROM _new_subtotal
      OR total IS DISTINCT FROM _new_total
      OR discount_amount IS DISTINCT FROM _disc_value);

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."fn_quotes_recalc_subtotal_from_items"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_quotes_recalc_subtotal_from_items"() IS 'Onda 17 / item 5.1: recalcula quotes.subtotal/total/discount_amount a partir de quote_items, aplicando negotiation_markup_percent e discount_percent. Espelha logica de calculateQuoteTotals do frontend. Skip para approved/converted.';



CREATE OR REPLACE FUNCTION "public"."fn_quotes_sync_seller"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Se um dos dois é NULL e o outro tem valor, copiar
  IF NEW.seller_id IS NULL AND NEW.created_by IS NOT NULL THEN
    NEW.seller_id := NEW.created_by;
  ELSIF NEW.created_by IS NULL AND NEW.seller_id IS NOT NULL THEN
    NEW.created_by := NEW.seller_id;
  END IF;
  RETURN NEW;
END $$;


