CREATE OR REPLACE FUNCTION "public"."fn_quotes_validate_discount"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _max_allowed numeric;
  _real_discount_pct numeric;
  _has_valid_approval boolean;
  _current_hash text;
  _seller_id uuid;
  _msg text;
  _decision_request_id uuid;
BEGIN
  IF NEW.status = 'expired' THEN RETURN NEW; END IF;
  IF current_setting('app.write_source', true) = 'cron_expire' THEN RETURN NEW; END IF;
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN RETURN NEW; END IF;
  IF auth.uid() IS NULL THEN RETURN NEW; END IF;

  BEGIN
    _decision_request_id := NULLIF(
      current_setting('app.discount_approval_request_id', true), ''
    )::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    _decision_request_id := NULL;
  END;

  IF TG_OP = 'UPDATE'
     AND OLD.status = 'pending_approval' AND NEW.status = 'draft'
     AND _decision_request_id IS NOT NULL
     AND NEW.client_id IS NOT DISTINCT FROM OLD.client_id
     AND NEW.client_name IS NOT DISTINCT FROM OLD.client_name
     AND NEW.subtotal IS NOT DISTINCT FROM OLD.subtotal
     AND NEW.discount_percent IS NOT DISTINCT FROM OLD.discount_percent
     AND NEW.discount_amount IS NOT DISTINCT FROM OLD.discount_amount
     AND NEW.negotiation_markup_percent IS NOT DISTINCT FROM OLD.negotiation_markup_percent
     AND NEW.total IS NOT DISTINCT FROM OLD.total
     AND NEW.real_discount_percent IS NOT DISTINCT FROM OLD.real_discount_percent
     AND NEW.seller_id IS NOT DISTINCT FROM OLD.seller_id
     AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by
     AND EXISTS (
       SELECT 1 FROM public.discount_approval_requests dar
       WHERE dar.id = _decision_request_id AND dar.quote_id = NEW.id
         AND dar.status = 'rejected' AND dar.admin_id = auth.uid()
         AND dar.quote_snapshot_hash = public.compute_quote_snapshot_hash(NEW.id)
     ) THEN
    RETURN NEW;
  END IF;

  _seller_id := COALESCE(NEW.seller_id, NEW.created_by);
  IF _seller_id IS NULL THEN RETURN NEW; END IF;
  IF public.is_supervisor_or_above(_seller_id) THEN RETURN NEW; END IF;

  _real_discount_pct := COALESCE(NEW.real_discount_percent, 0);
  IF _real_discount_pct <= 0 THEN RETURN NEW; END IF;

  SELECT max_discount_percent INTO _max_allowed
  FROM public.seller_discount_limits WHERE user_id = _seller_id;
  IF _max_allowed IS NULL THEN
    RAISE EXCEPTION 'Vendedor sem limite de desconto cadastrado. Solicite ao admin que configure seu limite antes de salvar orcamentos.'
      USING ERRCODE = '23514';
  END IF;
  IF _real_discount_pct <= _max_allowed THEN RETURN NEW; END IF;

  IF TG_OP = 'INSERT' THEN
    IF COALESCE(NEW.status, 'draft') = 'pending_approval' THEN RETURN NEW; END IF;
    _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
      ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
      ' por cento. Para solicitar aprovacao, use o botao "Solicitar aprovacao ao coordenador" que cria o orcamento em status pendente.';
    RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
  END IF;

  _current_hash := public.compute_quote_snapshot_hash(NEW.id);
  SELECT EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id AND status = 'approved'
      AND (valid_until IS NULL OR valid_until > now())
      AND requested_discount_percent >= _real_discount_pct
      AND quote_snapshot_hash = _current_hash
  ) INTO _has_valid_approval;
  IF _has_valid_approval THEN RETURN NEW; END IF;

  IF EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id AND status = 'approved'
      AND ((valid_until IS NOT NULL AND valid_until <= now())
        OR quote_snapshot_hash <> _current_hash)
  ) THEN
    RAISE EXCEPTION 'Aprovacao anterior nao vale mais (orcamento foi alterado ou aprovacao expirou). Solicite nova aprovacao ao coordenador.'
      USING ERRCODE = '23514';
  END IF;

  IF COALESCE(NEW.status, 'draft') = 'pending_approval' THEN RETURN NEW; END IF;
  _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
    ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
    ' por cento. Solicite aprovacao ao coordenador antes de salvar.';
  RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
END;
$$;


ALTER FUNCTION "public"."fn_quotes_validate_discount"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_quotes_validate_discount"() IS 'Valida alçada e permite rejeição pending_approval→draft somente pela RPC transacional; assert diferido valida snapshot final.';



CREATE OR REPLACE FUNCTION "public"."fn_reactivate_valid_novelties"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
/*
  v6_2026-06-13 — Quadrupla proteção:
  1. DISTINCT ON + NOT EXISTS active (v4)
  2. Hard block: migration_from_supplier NUNCA reativa (source denylist)
  3. Sincroniza is_new_expires_at ao setar is_new=true (M3)
  4. [NOVO] Frente 5: limpa is_new_expires_at/novelty_expires_at órfão
     quando is_new=false mas is_new_expires_at ainda preenchido (gap detectado em 2026-06-13)
*/
DECLARE
  v_novelties_fixed      int := 0;
  v_products_fixed       int := 0;
  v_orphans_fixed        int := 0;
  v_expires_at_cleaned   int := 0;
BEGIN
  -- Frente 1: reativar APENAS produtos SEM novelty ativa, 1 por produto (DISTINCT ON)
  -- v6: quadrupla proteção
  WITH candidates AS (
    SELECT DISTINCT ON (pn.product_id) pn.id
    FROM product_novelties pn
    JOIN products p ON pn.product_id = p.id
    WHERE p.is_active    = true
      AND p.is_stockout  = false
      AND pn.is_active   = false
      AND pn.expires_at  IS NOT NULL
      AND pn.expires_at  > now()
      -- BLOQUEIO ABSOLUTO: migration_from_supplier nunca volta a ativo
      AND pn.source      != 'migration_from_supplier'
      -- CRÍTICO v4: só produtos SEM nenhuma novelty ativa
      AND NOT EXISTS (
        SELECT 1 FROM product_novelties pn_active
        WHERE pn_active.product_id = pn.product_id
          AND pn_active.is_active  = true
      )
    ORDER BY pn.product_id, pn.expires_at DESC
  ),
  fixed AS (
    UPDATE product_novelties pn
    SET is_active = true, updated_at = clock_timestamp()
    WHERE pn.id IN (SELECT id FROM candidates)
    RETURNING pn.product_id
  )
  SELECT COUNT(*) INTO v_novelties_fixed FROM fixed;

  -- Frente 2: desativar novelties de produtos INATIVOS
  WITH deact AS (
    UPDATE product_novelties pn
    SET is_active = false, updated_at = clock_timestamp()
    FROM products p
    WHERE pn.product_id = p.id AND p.is_active = false AND pn.is_active = true
    RETURNING pn.product_id
  ) SELECT COUNT(*) INTO v_orphans_fixed FROM deact;

  -- Frente 2b: desativar novelties de produtos STOCKOUT
  UPDATE product_novelties pn
  SET is_active = false, updated_at = clock_timestamp()
  FROM products p
  WHERE pn.product_id = p.id AND p.is_active = true
    AND p.is_stockout = true AND pn.is_active = true;

  -- Frente 3: sincronizar products.is_new + is_new_expires_at (M3)
  UPDATE products p
  SET is_new = true,
      novelty_detected_at = pn.detected_at,
      novelty_expires_at  = pn.expires_at,
      is_new_expires_at   = pn.expires_at,
      updated_at = now()
  FROM product_novelties pn
  WHERE pn.product_id = p.id AND pn.is_active = true
    AND p.is_active = true AND p.is_stockout = false AND p.is_new = false;
  GET DIAGNOSTICS v_products_fixed = ROW_COUNT;

  -- Frente 4: limpar is_new=true órfão + todos os campos de novelty
  UPDATE products SET
    is_new              = false,
    novelty_detected_at = NULL,
    novelty_expires_at  = NULL,
    is_new_expires_at   = NULL,
    updated_at          = now()
  WHERE is_new = true
    AND NOT EXISTS (SELECT 1 FROM product_novelties pn
      WHERE pn.product_id = products.id AND pn.is_active = true);

  -- Frente 5 [v6 — gap fix 2026-06-13]:
  -- Limpar is_new_expires_at/novelty_expires_at residuais quando:
  -- is_new = false (já limpo) mas is_new_expires_at ainda preenchido
  -- Cenário: produto foi novo → foi para stockout (Frente 2b desativou novelty)
  -- → algo externo setou is_new=false (trigger, gold promote) mas não limpou expires_at
  UPDATE products SET
    is_new_expires_at   = NULL,
    novelty_expires_at  = NULL,
    updated_at          = now()
  WHERE is_new = false
    AND is_new_expires_at IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM product_novelties pn
      WHERE pn.product_id = products.id AND pn.is_active = true);
  GET DIAGNOSTICS v_expires_at_cleaned = ROW_COUNT;

  RETURN jsonb_build_object(
    'novelties_reactivated',         v_novelties_fixed,
    'inactive_products_deactivated', v_orphans_fixed,
    'products_synced',               v_products_fixed,
    'expires_at_residuals_cleaned',  v_expires_at_cleaned,
    'version',                       'v6_2026-06-13_frente5_gap_fix',
    'ran_at',                        now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_reactivate_valid_novelties"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_reactivate_valid_novelties"() IS 'Safeguard de consistência: reativa novelties com expires_at futuro indevidamente desativadas
e sincroniza products.is_new. Rodar antes de fn_expire_novelties.
Job pg_cron recomendado: a cada hora (0 * * * *).';



CREATE OR REPLACE FUNCTION "public"."fn_rebuild_category_ancestors"() RETURNS TABLE("deleted_rows" bigint, "inserted_rows" bigint, "duration_ms" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_deleted  bigint;
  v_inserted bigint;
  v_start    timestamptz := clock_timestamp();
BEGIN
  -- Contar antes para reporting
  SELECT COUNT(*) INTO v_deleted FROM category_ancestors;

  -- Limpar e reconstruir atomicamente
  TRUNCATE category_ancestors;

  -- Inserir todos os pares antepassado→descendente via CTE recursiva
  -- Nota: exclui self-references (ancestor_id != descendant_id)
  WITH RECURSIVE tree AS (
    -- Base: cada categoria é "ancestral de si mesma" (ponto de partida)
    SELECT id AS ancestor_id, id AS node_id, 0 AS depth
    FROM   categories

    UNION ALL

    -- Expandir: cada filho passa a ser descendente de todos os ancestrais do pai
    SELECT t.ancestor_id, c.id AS node_id, t.depth + 1
    FROM   tree t
    JOIN   categories c ON c.parent_id = t.node_id
    WHERE  t.depth < 15  -- safety depth limit
  )
  INSERT INTO category_ancestors (ancestor_id, descendant_id, depth)
  SELECT DISTINCT ancestor_id, node_id, MIN(depth) OVER (PARTITION BY ancestor_id, node_id)
  FROM tree
  WHERE ancestor_id != node_id  -- excluir self-references
  ON CONFLICT (ancestor_id, descendant_id) DO UPDATE
    SET depth = EXCLUDED.depth;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RETURN QUERY SELECT v_deleted, v_inserted, 
    EXTRACT(milliseconds FROM clock_timestamp() - v_start)::numeric(10,2);
END;
$$;


ALTER FUNCTION "public"."fn_rebuild_category_ancestors"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_rebuild_category_ancestors"() IS 'Rebuild completo da closure table category_ancestors a partir do parent_id tree.
TRUNCATE + INSERT via CTE recursiva com depth safety limit = 15.
Retorna (deleted_rows, inserted_rows, duration_ms). Criado: 2026-06-23.
Uso: SELECT * FROM fn_rebuild_category_ancestors();';



CREATE OR REPLACE FUNCTION "public"."fn_rebuild_color_swatches"("p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    jsonb_agg(
      swatch
      ORDER BY (swatch->>'stock_quantity')::int DESC, swatch->>'color_name' ASC
    ),
    '[]'::jsonb
  )
  FROM (
    SELECT DISTINCT ON (agg.color_id)
      jsonb_build_object(
        'variant_id',     agg.lead_variant_id,
        'sku',            agg.lead_sku,
        'color_id',       agg.color_id,
        'color_name',     agg.color_name,
        'color_hex',      agg.color_hex,
        'stock_quantity', agg.total_stock,
        'is_in_stock',    agg.total_stock > 0,
        'image_url',      COALESCE(
          (SELECT pi.url_cdn
           FROM product_images pi
           WHERE pi.product_id  = p_product_id
             AND pi.variant_id  = agg.lead_variant_id
             AND pi.is_active   = true
             AND pi.image_type  IN ('main','gallery','product')
           ORDER BY pi.is_primary DESC, pi.display_order ASC NULLS LAST
           LIMIT 1),
          (SELECT pi.url_cdn
           FROM product_images pi
           WHERE pi.product_id  = p_product_id
             AND pi.color_id    = agg.color_id
             AND pi.variant_id  IS NULL
             AND pi.is_active   = true
             AND pi.image_type  IN ('main','gallery','product')
           ORDER BY pi.is_primary DESC, pi.display_order ASC NULLS LAST
           LIMIT 1),
          (SELECT pi.url_cdn
           FROM product_images pi
           WHERE pi.product_id  = p_product_id
             AND pi.color_id    = agg.color_id
             AND pi.variant_id  IS NOT NULL
             AND pi.is_active   = true
             AND pi.image_type  IN ('main','gallery','product')
           ORDER BY pi.is_primary DESC, pi.display_order ASC NULLS LAST
           LIMIT 1),
          agg.lead_images_first,
          (SELECT p.primary_image_url FROM products p WHERE p.id = p_product_id)
        )
      ) AS swatch
    FROM (
      SELECT
        pv2.color_id,
        COALESCE(pv2.color_name, cv.name)    AS color_name,
        COALESCE(pv2.color_hex, cv.hex_code) AS color_hex,
        SUM(COALESCE(pv2.stock_quantity, 0)) AS total_stock,
        (ARRAY_AGG(pv2.id   ORDER BY COALESCE(pv2.stock_quantity,0) DESC, pv2.sku ASC))[1] AS lead_variant_id,
        (ARRAY_AGG(pv2.sku  ORDER BY COALESCE(pv2.stock_quantity,0) DESC, pv2.sku ASC))[1] AS lead_sku,
        (ARRAY_AGG(pv2.images->>0 ORDER BY COALESCE(pv2.stock_quantity,0) DESC, pv2.sku ASC))[1] AS lead_images_first
      FROM product_variants pv2
      LEFT JOIN color_variations cv ON cv.id = pv2.color_id
      WHERE pv2.product_id = p_product_id
        AND pv2.is_active  = true
        AND pv2.color_id   IS NOT NULL
      GROUP BY
        pv2.color_id,
        COALESCE(pv2.color_name, cv.name),
        COALESCE(pv2.color_hex, cv.hex_code)
    ) agg
    ORDER BY agg.color_id, agg.total_stock DESC
  ) sub;
$$;


ALTER FUNCTION "public"."fn_rebuild_color_swatches"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_rebuild_color_swatches"("p_product_id" "uuid") IS 'Reconstrói swatches de cor para um produto. stock = SUM por cor (suporta têxteis/tamanhos).
   P1(PI.variant_id→CF) → P2(PI.color_id→CF) → P3(pv.images[0]) → P4(primary_image_url). 2026-06-22';



CREATE OR REPLACE FUNCTION "public"."fn_recalc_compat_on_dim_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE product_packaging_compatibility c
  SET fit_rating=(f.fit->>'fit_rating'),
      fit_gap_min_mm=NULLIF(f.fit->>'gap_min_mm','')::numeric,
      fit_gap_avg_mm=NULLIF(f.fit->>'gap_avg_mm','')::numeric,
      fit_gap_height_mm=NULLIF(f.fit->>'gap_height_mm','')::numeric,
      fit_gap_width_mm=NULLIF(f.fit->>'gap_width_mm','')::numeric,
      fit_gap_length_mm=NULLIF(f.fit->>'gap_length_mm','')::numeric,
      fit_gap_diameter_mm=NULLIF(f.fit->>'gap_diameter_mm','')::numeric,
      needs_padding=COALESCE((f.fit->>'needs_padding')::boolean,false),
      updated_at=now()
  FROM (SELECT cc.id, fn_calculate_packaging_fit(cc.product_id, cc.packaging_id, cc.config_type_used) AS fit
        FROM product_packaging_compatibility cc WHERE (cc.product_id=NEW.id OR cc.packaging_id=NEW.id) AND cc.active) f
  WHERE c.id=f.id
    AND (c.fit_rating IS DISTINCT FROM (f.fit->>'fit_rating')
         OR c.fit_gap_min_mm IS DISTINCT FROM NULLIF(f.fit->>'gap_min_mm','')::numeric);

  WITH ranked AS (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY
      CASE compatibility_source WHEN 'supplier_indicated' THEN 1 WHEN 'dimension_matching' THEN 2 WHEN 'dimension_calculated' THEN 3 ELSE 4 END,
      CASE fit_rating WHEN 'tight' THEN 1 WHEN 'good' THEN 2 WHEN 'loose' THEN 3 ELSE 4 END, COALESCE(fit_gap_min_mm,99999)) rn
    FROM product_packaging_compatibility
    WHERE product_id IN (SELECT DISTINCT product_id FROM product_packaging_compatibility WHERE (product_id=NEW.id OR packaging_id=NEW.id) AND active)
      AND active AND fit_rating IN ('tight','good','loose'))
  UPDATE product_packaging_compatibility c SET is_recommended=COALESCE(r.rn=1,false)
  FROM ranked r WHERE c.id=r.id AND c.is_recommended IS DISTINCT FROM COALESCE(r.rn=1,false);

  UPDATE product_packaging_compatibility SET is_recommended=false
  WHERE active AND is_recommended AND COALESCE(fit_rating,'x') NOT IN ('tight','good','loose')
    AND product_id IN (SELECT DISTINCT product_id FROM product_packaging_compatibility WHERE (product_id=NEW.id OR packaging_id=NEW.id) AND active);
  RETURN NEW;
END$$;


ALTER FUNCTION "public"."fn_recalc_compat_on_dim_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_recalc_has_optional_packaging"("p_product_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE products p SET has_optional_packaging = (
        COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
        OR p.optional_packaging_ref IS NOT NULL OR p.packing_classification='protective'
        OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active AND c.fit_rating IN ('tight','good','loose')))
  WHERE p.id=p_product_id AND p.has_optional_packaging IS DISTINCT FROM (
        COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
        OR p.optional_packaging_ref IS NOT NULL OR p.packing_classification='protective'
        OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active AND c.fit_rating IN ('tight','good','loose')));
END$$;


ALTER FUNCTION "public"."fn_recalc_has_optional_packaging"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_recalc_has_optional_packaging"("p_product_id" "uuid") IS 'fix_version 2026-06-26.m1 — recalcula has_optional_packaging (menção OR compat ativa). Mantém SET search_path=public.';



CREATE OR REPLACE FUNCTION "public"."fn_recalcular_markup"("p_nivel" "text", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_atualizados int;
BEGIN
    IF p_nivel NOT IN ('supplier','category','product','all') THEN
        RETURN jsonb_build_object('success', false, 'error', 'nivel_invalido');
    END IF;

    -- Informa pipeline para não travar locked_fields
    PERFORM set_config('app.write_source', 'pipeline', true);

    -- Atualiza sale_price diretamente com a mesma hierarquia do trigger
    -- Mais confiável que +/- delta pois não depende de detectar mudança
    UPDATE products p
    SET sale_price = ROUND(
        p.cost_price * (
            1 + COALESCE(
                -- 1. produto específico
                (SELECT mc.markup_percent
                 FROM markup_configurations mc
                 WHERE mc.is_active = true
                   AND (mc.product_id  IS NULL OR mc.product_id  = p.id)
                   AND (mc.category_id IS NULL OR mc.category_id = p.category_id)
                   AND (mc.supplier_id IS NULL OR mc.supplier_id = p.supplier_id)
                 ORDER BY
                   (CASE WHEN mc.product_id  IS NOT NULL THEN 1000 ELSE 0 END) +
                   (CASE WHEN mc.category_id IS NOT NULL THEN 100  ELSE 0 END) +
                   (CASE WHEN mc.supplier_id IS NOT NULL THEN 10   ELSE 0 END) DESC
                 LIMIT 1),
                -- 2. fallback: default_markup_percent do fornecedor
                (SELECT s.default_markup_percent
                 FROM suppliers s
                 WHERE s.id = p.supplier_id AND s.active = true),
                -- 3. fallback final
                115.0
            ) / 100.0
        ), 2
    )
    WHERE p.cost_price IS NOT NULL
      AND p.cost_price > 0
      AND CASE p_nivel
            WHEN 'supplier' THEN p.supplier_id = p_id
            WHEN 'category' THEN p.category_id = p_id
            WHEN 'product'  THEN p.id = p_id
            WHEN 'all'      THEN true
            ELSE false
          END;

    GET DIAGNOSTICS v_atualizados = ROW_COUNT;

    RETURN jsonb_build_object(
        'success',      true,
        'nivel',        p_nivel,
        'id_alvo',      p_id,
        'recalculados', v_atualizados
    );
END;
$$;


ALTER FUNCTION "public"."fn_recalcular_markup"("p_nivel" "text", "p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_recalcular_markup"("p_nivel" "text", "p_id" "uuid") IS 'Recalcula sale_price usando a hierarquia de markup_configurations.
Útil após alterar markup via fn_set_markup.
Exemplos:
  SELECT fn_recalcular_markup(''supplier'', ''uuid-xbz'');
  SELECT fn_recalcular_markup(''category'', ''uuid-cat'');
  SELECT fn_recalcular_markup(''product'',  ''uuid-prod'');
  SELECT fn_recalcular_markup(''all'');';



CREATE OR REPLACE FUNCTION "public"."fn_recalculate_all_sale_prices"("p_batch_size" integer DEFAULT 500) RETURNS TABLE("processed" integer, "updated" integer, "errors" integer, "message" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_processed INTEGER := 0;
  v_updated INTEGER := 0;
  v_errors INTEGER := 0;
  v_record RECORD;
  v_new_price NUMERIC;
BEGIN
  FOR v_record IN 
    SELECT id, name, cost_price, sale_price  -- CORRIGIDO: base_price → cost_price
    FROM products
    WHERE cost_price IS NOT NULL AND cost_price > 0  -- CORRIGIDO: base_price → cost_price
    LIMIT p_batch_size
  LOOP
    BEGIN
      v_processed := v_processed + 1;
      v_new_price := fn_calculate_sale_price(v_record.id, 1, NULL);
      IF v_new_price IS NOT NULL AND v_new_price != COALESCE(v_record.sale_price, 0) THEN
        UPDATE products
        SET sale_price = v_new_price, updated_at = NOW()
        WHERE id = v_record.id;
        v_updated := v_updated + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;
  RETURN QUERY SELECT v_processed, v_updated, v_errors,
    format('Processados: %s, Atualizados: %s, Erros: %s', v_processed, v_updated, v_errors);
END;
$$;


ALTER FUNCTION "public"."fn_recalculate_all_sale_prices"("p_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_recalculate_all_stock"() RETURNS TABLE("variants_updated" integer, "products_updated" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_variants_updated INTEGER := 0;
    v_products_updated INTEGER := 0;
BEGIN
    -- Atualizar todas as variantes
    WITH vss_totals AS (
        SELECT 
            variant_id,
            COALESCE(SUM(quantity), 0) as total_qty
        FROM variant_supplier_sources
        WHERE is_active = true
        GROUP BY variant_id
    )
    UPDATE product_variants pv
    SET stock_quantity = COALESCE(vt.total_qty, 0)
    FROM vss_totals vt
    WHERE pv.id = vt.variant_id
      AND pv.stock_quantity IS DISTINCT FROM COALESCE(vt.total_qty, 0);
    
    GET DIAGNOSTICS v_variants_updated = ROW_COUNT;
    
    -- Atualizar todos os produtos
    WITH pv_totals AS (
        SELECT 
            product_id,
            COALESCE(SUM(stock_quantity), 0) as total_qty
        FROM product_variants
        WHERE is_active = true
        GROUP BY product_id
    )
    UPDATE products p
    SET 
        stock_quantity = COALESCE(pt.total_qty, 0),
        is_stockout = (COALESCE(pt.total_qty, 0) = 0),
        last_stock_update_at = NOW()
    FROM pv_totals pt
    WHERE p.id = pt.product_id
      AND (p.stock_quantity IS DISTINCT FROM COALESCE(pt.total_qty, 0)
           OR p.is_stockout IS DISTINCT FROM (COALESCE(pt.total_qty, 0) = 0));
    
    GET DIAGNOSTICS v_products_updated = ROW_COUNT;
    
    RETURN QUERY SELECT v_variants_updated, v_products_updated;
END;
$$;


ALTER FUNCTION "public"."fn_recalculate_all_stock"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_recalculate_all_stock"() IS 'Recalcula estoque de todas as variantes e produtos. Usar após importação em massa.';



CREATE OR REPLACE FUNCTION "public"."fn_recomendar_tecnica"("p_categoria" "text" DEFAULT NULL::"text", "p_n_cores" integer DEFAULT 1, "p_complexidade_arte" "text" DEFAULT 'simples'::"text", "p_material" "text" DEFAULT NULL::"text", "p_qty" integer DEFAULT 100) RETURNS TABLE("rank" integer, "codigo_tabela" character varying, "nome" character varying, "grupo_tecnica" character varying, "motivo" "text", "alerta" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH base AS (
    SELECT 
      t.codigo_tabela,
      t.nome,
      t.grupo_tecnica,
      t.cobra_por_cor,
      t.max_cores,
      t.opcoes_modificadores->'materiais_aplicaveis' AS materiais,
      -- Score baseado em compatibilidade
      CASE 
        -- Se cliente quer arte complexa/fotorrealista, priorizar full-color
        WHEN p_complexidade_arte = 'complexa' AND t.grupo_tecnica IN ('TRANSFER_DIGITAL','UV_DIGITAL','SUBLIMACAO') THEN 100
        WHEN p_complexidade_arte = 'complexa' AND t.cobra_por_cor THEN 30  -- silk/tampo limitam cores
        -- Se cliente quer 1 cor simples, priorizar técnicas eficientes
        WHEN p_n_cores = 1 AND t.grupo_tecnica IN ('SERIGRAFIA','TAMPOGRAFIA','LASER','LASER_CO2') THEN 100
        WHEN p_n_cores = 1 AND t.grupo_tecnica IN ('TRANSFER_DIGITAL','UV_DIGITAL','SUBLIMACAO') THEN 40
        -- Se cliente quer 2-3 cores chapadas, silk/tampo dominam
        WHEN p_n_cores BETWEEN 2 AND 3 AND t.cobra_por_cor THEN 90
        WHEN p_n_cores BETWEEN 2 AND 3 AND NOT t.cobra_por_cor THEN 60
        -- Se cliente quer 4+ cores, full-color dominante
        WHEN p_n_cores >= 4 AND NOT t.cobra_por_cor THEN 100
        WHEN p_n_cores >= 4 AND t.cobra_por_cor AND p_n_cores <= t.max_cores THEN 50
        ELSE 50
      END AS score_cores,
      -- Compatibilidade categoria via codigo_tabela
      CASE
        WHEN p_categoria = 'caneta' AND t.codigo_tabela ~ '(-CN-|-MCN-)' THEN 100
        WHEN p_categoria = 'sacochila' AND t.codigo_tabela LIKE '%-SAC-%' THEN 100
        WHEN p_categoria = 'camiseta' AND t.codigo_tabela LIKE '%-CAM-%' THEN 100
        WHEN p_categoria = 'mochila' AND t.codigo_tabela LIKE '%-MOC-%' THEN 100
        WHEN p_categoria = 'sacola' AND t.codigo_tabela LIKE '%-SAE-%' THEN 100
        WHEN p_categoria = 'cilindrico' AND t.codigo_tabela LIKE '%-CIL-%' THEN 100
        WHEN p_categoria = 'plano' AND t.codigo_tabela LIKE '%-PL-%' THEN 100
        WHEN p_categoria IS NULL THEN 50  -- sem filtro
        ELSE 0
      END AS score_categoria,
      -- Compatibilidade de material
      CASE
        WHEN p_material IS NULL THEN 50
        WHEN t.opcoes_modificadores->'materiais_aplicaveis' ? p_material THEN 100
        WHEN p_material = 'sublimatica' AND t.grupo_tecnica = 'SUBLIMACAO' THEN 100
        WHEN p_material = 'metal' AND t.codigo_tabela ~ 'M(CN|T|OC)' THEN 100
        WHEN p_material = 'plastico' AND t.codigo_tabela ~ '(PL|CN-01)' THEN 100
        ELSE 30
      END AS score_material,
      -- Excluir sublimação se material não for sublimática
      CASE
        WHEN t.grupo_tecnica = 'SUBLIMACAO' AND p_material IS NOT NULL 
             AND p_material NOT IN ('sublimatica','poliester','microfibra','dryfit') THEN 0
        ELSE 1
      END AS aplicavel,
      -- Mensagem
      CASE
        WHEN t.grupo_tecnica = 'SERIGRAFIA' AND p_n_cores = 1 THEN 'Imbativel para 1 cor chapada em volume.'
        WHEN t.grupo_tecnica = 'TAMPOGRAFIA' AND p_n_cores BETWEEN 1 AND 3 THEN 'Ideal para superficies pequenas/curvas com poucas cores.'
        WHEN t.grupo_tecnica = 'TRANSFER_DIGITAL' AND p_complexidade_arte = 'complexa' THEN 'Full color CMYK - perfeito para artes complexas.'
        WHEN t.grupo_tecnica = 'TRANSFER_DIGITAL' AND p_n_cores = 1 THEN 'Cuidado: DTF em 1 cor pode ficar 3-4x mais caro que silk.'
        WHEN t.grupo_tecnica = 'SUBLIMACAO' THEN 'Exclusiva: nao combina com outras tecnicas na mesma peca.'
        WHEN t.grupo_tecnica = 'UV_DIGITAL' AND p_complexidade_arte = 'complexa' THEN 'Otima qualidade fotografica em superficies rigidas.'
        WHEN t.grupo_tecnica IN ('LASER','LASER_CO2') THEN 'Acabamento sofisticado, sem cor mas elegante.'
        WHEN t.grupo_tecnica = 'BORDADO' THEN 'Premium em texteis - alto valor percebido.'
        ELSE 'Tecnica disponivel para o cenario.'
      END AS mensagem,
      CASE
        WHEN t.grupo_tecnica = 'TRANSFER_DIGITAL' AND p_n_cores <= 2 THEN 'ATENCAO: silk/tampo geralmente mais economicos para poucas cores.'
        WHEN t.grupo_tecnica = 'SUBLIMACAO' THEN 'NAO COMBINA com outras tecnicas na mesma peca.'
        WHEN t.grupo_tecnica IN ('UV_DIGITAL') AND p_n_cores <= 2 THEN 'ATENCAO: tampografia normalmente mais economica para 1-2 cores.'
        ELSE NULL
      END AS alerta_msg
    FROM tabela_preco_gravacao_oficial t
    WHERE t.ativo = true
  ),
  ranked AS (
    SELECT 
      ROW_NUMBER() OVER (ORDER BY (score_cores + score_categoria + score_material) DESC, codigo_tabela)::integer AS rk,
      codigo_tabela::varchar,
      nome::varchar,
      grupo_tecnica::varchar,
      mensagem::text AS motivo,
      alerta_msg::text AS alerta,
      (score_cores + score_categoria + score_material) AS total_score,
      aplicavel
    FROM base
    WHERE aplicavel = 1
  )
  SELECT rk AS rank, codigo_tabela, nome, grupo_tecnica, motivo, alerta
  FROM ranked
  WHERE total_score >= 150  -- só recomenda quando há boa aderência
  ORDER BY rk
  LIMIT 5;
$$;


ALTER FUNCTION "public"."fn_recomendar_tecnica"("p_categoria" "text", "p_n_cores" integer, "p_complexidade_arte" "text", "p_material" "text", "p_qty" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_recomendar_tecnica"("p_categoria" "text", "p_n_cores" integer, "p_complexidade_arte" "text", "p_material" "text", "p_qty" integer) IS 'Recomenda top-5 técnicas para um cenário. Usa scoring por: nº cores, complexidade da arte, categoria do produto e material. Evita que cliente receba cotação ineficiente (ex: DTF para 1 cor).';



CREATE OR REPLACE FUNCTION "public"."fn_reconcile_category_products_count"("p_limit" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated   INT := 0;
  v_skipped   INT := 0;
  v_started_at TIMESTAMPTZ := clock_timestamp();
BEGIN
  -- Atualizar products_count apenas onde diverge (minimiza writes)
  WITH real_counts AS (
    SELECT
      c.id                                                    AS category_id,
      c.products_count                                        AS cached,
      COALESCE(
        (SELECT count(*) FROM public.products p
         WHERE p.category_id = c.id AND p.is_active = true), 0
      )::integer                                              AS real_count
    FROM public.categories c
    WHERE p_limit IS NULL OR c.id IN (
      -- Se p_limit definido, priorizar os mais divergentes
      SELECT c2.id FROM public.categories c2
      ORDER BY ABS(c2.products_count -
        COALESCE((SELECT count(*) FROM public.products p2
                  WHERE p2.category_id = c2.id AND p2.is_active = true), 0))
        DESC NULLS LAST
      LIMIT p_limit
    )
  ),
  divergentes AS (
    SELECT category_id, cached, real_count
    FROM real_counts
    WHERE cached IS DISTINCT FROM real_count
  )
  UPDATE public.categories c
  SET products_count = d.real_count
  FROM divergentes d
  WHERE c.id = d.category_id;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  v_skipped := (SELECT count(*) FROM public.categories) - v_updated;

  RETURN jsonb_build_object(
    'updated',    v_updated,
    'skipped',    v_skipped,
    'duration_ms', EXTRACT(MILLISECONDS FROM clock_timestamp() - v_started_at)::int,
    'ran_at',     v_started_at
  );
END;
$$;


ALTER FUNCTION "public"."fn_reconcile_category_products_count"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_reconcile_category_products_count"("p_limit" integer) IS 'Reconcilia categories.products_count com a contagem real de products.is_active=true. p_limit NULL = todas as categorias; número = N mais divergentes (uso de emergência). Chamado pelo pg_cron a cada 15min. Criado: 2026-06-23 (GAP-4 fix).';



CREATE OR REPLACE FUNCTION "public"."fn_reconcile_stock_gold"("p_dry_run" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_var int := 0; v_prod int := 0; v_vss int := 0; v_orphan int := 0;
  v_var_div int; v_prod_div int; v_vss_div int; v_orphan_div int;
  v_t0 timestamptz := clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_reconcile_stock_gold')::bigint) THEN
    RETURN jsonb_build_object('skipped','lock_ocupado');
  END IF;

  PERFORM set_config('app.bulk_import_mode','true', true);
  PERFORM set_config('app.write_source','reconcile', true);
  PERFORM set_config('app.skip_stock_snapshot','true', true);

  -- diagnóstico (antes)
  SELECT count(*) INTO v_orphan_div FROM variant_supplier_sources v
    WHERE v.is_active AND v.variant_id IN (SELECT id FROM product_variants WHERE is_active=false);
  SELECT count(*) INTO v_vss_div FROM variant_supplier_sources v
    WHERE v.is_active AND NOT COALESCE(v.removed_from_api,false)
      AND v.quantity IS DISTINCT FROM (COALESCE(v.stock_main_warehouse,0)+COALESCE(v.stock_other_warehouses,0));
  SELECT count(*) INTO v_var_div FROM (
    SELECT v.id FROM product_variants v
    LEFT JOIN variant_supplier_sources s ON s.variant_id=v.id AND s.is_active
    WHERE v.is_active
    GROUP BY v.id, v.stock_quantity
    HAVING COALESCE(v.stock_quantity,0) IS DISTINCT FROM COALESCE(sum(s.quantity),0)) z;
  SELECT count(*) INTO v_prod_div FROM (
    SELECT p.id FROM products p
    LEFT JOIN product_variants v ON v.product_id=p.id AND v.is_active
    WHERE p.is_active
    GROUP BY p.id, p.stock_quantity
    HAVING COALESCE(p.stock_quantity,0) IS DISTINCT FROM COALESCE(sum(v.stock_quantity),0)) z;

  IF p_dry_run THEN
    RETURN jsonb_build_object('dry_run', true,
      'vss_orfas', v_orphan_div,
      'vss_incoerentes', v_vss_div,
      'variantes_divergentes', v_var_div, 'products_divergentes', v_prod_div);
  END IF;

  -- nível -1: invariante estrutural (VSS ativa só sob variante ativa)
  WITH orphan AS (
    UPDATE variant_supplier_sources v SET is_active=false, updated_at=now()
    WHERE v.is_active AND v.variant_id IN (SELECT id FROM product_variants WHERE is_active=false)
    RETURNING v.id)
  SELECT count(*) INTO v_orphan FROM orphan;

  -- nível 0: coerência interna VSS (main+other == quantity)
  WITH upd AS (
    UPDATE variant_supplier_sources v
       SET stock_main_warehouse = v.quantity, stock_other_warehouses = 0, updated_at = now()
    WHERE v.is_active AND NOT COALESCE(v.removed_from_api,false)
      AND v.quantity IS DISTINCT FROM (COALESCE(v.stock_main_warehouse,0)+COALESCE(v.stock_other_warehouses,0))
    RETURNING v.id)
  SELECT count(*) INTO v_vss FROM upd;

  -- nível 1: VSS → product_variants
  WITH agg AS (
    SELECT v.id, COALESCE(sum(s.quantity) FILTER (WHERE s.is_active),0) AS q
    FROM product_variants v
    LEFT JOIN variant_supplier_sources s ON s.variant_id=v.id
    WHERE v.is_active
    GROUP BY v.id),
  upd AS (
    UPDATE product_variants v SET stock_quantity = agg.q
    FROM agg WHERE v.id=agg.id AND COALESCE(v.stock_quantity,0) IS DISTINCT FROM agg.q
    RETURNING v.id)
  SELECT count(*) INTO v_var FROM upd;

  -- nível 2: product_variants → products (cache + is_stockout)
  WITH agg AS (
    SELECT p.id, COALESCE(sum(v.stock_quantity) FILTER (WHERE v.is_active),0) AS q
    FROM products p
    LEFT JOIN product_variants v ON v.product_id=p.id
    WHERE p.is_active
    GROUP BY p.id),
  upd AS (
    UPDATE products p
       SET stock_quantity = agg.q, is_stockout = (agg.q <= 0), last_stock_update_at = now()
    FROM agg WHERE p.id=agg.id
      AND (COALESCE(p.stock_quantity,0) IS DISTINCT FROM agg.q
           OR p.is_stockout IS DISTINCT FROM (agg.q <= 0))
    RETURNING p.id)
  SELECT count(*) INTO v_prod FROM upd;

  RETURN jsonb_build_object(
    'vss_orfas_antes', v_orphan_div,
    'vss_incoerentes_antes', v_vss_div,
    'variantes_divergentes_antes', v_var_div,
    'products_divergentes_antes', v_prod_div,
    'vss_orfas_desativadas', v_orphan,
    'vss_coerencia_corrigidas', v_vss,
    'variantes_corrigidas', v_var,
    'products_corrigidos', v_prod,
    'segundos', round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,1),
    'ts', now());
END $$;


ALTER FUNCTION "public"."fn_reconcile_stock_gold"("p_dry_run" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_refresh_kit_component_variant_skus"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_ins integer; v_heal integer;
BEGIN
  -- 1) inserir novidades (novos componentes/variantes), semeando imagem/cor
  INSERT INTO public.kit_component_variant_skus
    (component_id, variant_id, kit_product_id, component_sku, slot_code, is_packaging,
     variant_color_code, variant_color_name, component_name, item_color_id,
     primary_image_url, image_source)
  SELECT s.component_id, s.variant_id, s.kit_product_id, s.component_sku, s.slot_code, s.is_packaging,
         s.variant_color_code, s.variant_color_name, s.component_name, s.item_color_id,
         s.component_image_url,
         CASE WHEN s.component_image_url IS NOT NULL THEN 'inherited_component' END
  FROM public.v_kit_component_skus s
  ON CONFLICT (component_id, variant_id) DO NOTHING;
  GET DIAGNOSTICS v_ins = ROW_COUNT;

  -- 2) auto-curar imagens que chegaram depois — SOMENTE onde está NULL (nunca sobrescreve)
  UPDATE public.kit_component_variant_skus k
  SET primary_image_url = c.primary_image_url,
      image_source      = 'inherited_component',
      updated_at        = now()
  FROM public.product_kit_components c
  WHERE c.id = k.component_id
    AND k.primary_image_url IS NULL
    AND c.primary_image_url IS NOT NULL;
  GET DIAGNOSTICS v_heal = ROW_COUNT;

  RETURN v_ins + v_heal;
END;
$$;


ALTER FUNCTION "public"."fn_refresh_kit_component_variant_skus"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_refresh_kit_component_variant_skus"() IS 'Sincroniza kit_component_variant_skus: (1) insere novos pares componente×variante; (2) auto-cura primary_image_url onde estiver NULL a partir do componente. Idempotente, não sobrescreve imagem já definida. Deleções cobertas por ON DELETE CASCADE.';



