Chamar após ingestão ou re-promoção de produtos.';



CREATE OR REPLACE FUNCTION "public"."fn_refresh_supplier_sync_telemetry"("p_supplier_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("supplier_code" "text", "linhas" bigint, "novo_status" "text", "novo_last_sync" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
begin
  return query
  with agg as (
    select r.supplier_id,
           count(*)::bigint                                   as n,
           max(r.imported_at)                                  as max_imported,
           count(*) filter (where r.status = 'failed')         as n_failed
    from public.supplier_products_raw r
    where p_supplier_id is null or r.supplier_id = p_supplier_id
    group by r.supplier_id
  ),
  upd as (
    update public.suppliers s
       set last_full_sync_at = a.max_imported,
           last_sync_status  = case when a.n_failed > 0 then 'failed' else 'completed' end,
           last_sync_error   = case when a.n_failed > 0 then s.last_sync_error else null end,
           updated_at        = now()
      from agg a
     where s.id = a.supplier_id
    returning s.code, a.n, s.last_sync_status, s.last_full_sync_at
  )
  select u.code::text, u.n::bigint, u.last_sync_status::text, u.last_full_sync_at
  from upd u;
end;
$$;


ALTER FUNCTION "public"."fn_refresh_supplier_sync_telemetry"("p_supplier_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_refresh_supplier_sync_telemetry"("p_supplier_id" "uuid") IS 'Recalcula last_full_sync_at/last_sync_status de suppliers a partir do estado real de supplier_products_raw. Idempotente. Chamar ao fim de cada sync (n8n) ou com NULL para todos.';



CREATE OR REPLACE FUNCTION "public"."fn_refresh_supplier_sync_timestamps"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_updated int := 0;
BEGIN
  WITH updated AS (
    UPDATE suppliers s
    SET last_full_sync_at = vss_agg.max_sync
    FROM (
      SELECT supplier_id, MAX(last_synced_at) AS max_sync
      FROM variant_supplier_sources
      GROUP BY supplier_id
    ) vss_agg
    WHERE s.id = vss_agg.supplier_id
      AND s.sync_enabled = true
      AND (s.last_full_sync_at IS NULL OR s.last_full_sync_at < vss_agg.max_sync - INTERVAL '30 minutes')
    RETURNING s.id
  )
  SELECT COUNT(*) INTO v_updated FROM updated;

  RETURN jsonb_build_object('suppliers_updated', v_updated, 'executed_at', NOW());
END;
$$;


ALTER FUNCTION "public"."fn_refresh_supplier_sync_timestamps"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reject_product_deactivation"("p_request_id" "uuid", "p_rejection_reason" "text" DEFAULT 'Não aprovado'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NOT NULL AND NOT public.is_admin_or_above(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Acesso negado: requer admin+');
  END IF;

  UPDATE product_deactivation_requests SET
    status          = 'rejected',
    rejected_by     = v_uid,
    rejected_at     = now(),
    rejection_reason = p_rejection_reason,
    updated_at      = now()
  WHERE id = p_request_id AND status = 'pending'
  RETURNING id INTO p_request_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nao_encontrado_ou_nao_pendente');
  END IF;

  RETURN jsonb_build_object('ok', true, 'request_id', p_request_id, 'status', 'rejected');
END;
$$;


