COMMENT ON FUNCTION "public"."fn_relatorio_cores_pendentes"() IS 'Relatório de pendências de mapeamento de cores. Retorna cores sem equivalência e variantes sem color_id. Fix 2026-06-11: cast varchar→text em todos os RETURN QUERY.';



CREATE OR REPLACE FUNCTION "public"."fn_remove_orphan_color_links"("p_product_id" "uuid", "p_old_color_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count_removed INTEGER := 0;
    v_has_other_variants BOOLEAN;
    v_category_id UUID;
BEGIN
    -- ========================================
    -- VALIDAÇÃO
    -- ========================================
    IF p_product_id IS NULL OR p_old_color_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Parâmetros inválidos',
            'removed', 0
        );
    END IF;
    
    -- ========================================
    -- Para cada categoria vinculada a essa cor
    -- ========================================
    FOR v_category_id IN
        SELECT cc.category_id
        FROM category_colors cc
        WHERE cc.color_group_id = p_old_color_id
          AND cc.is_active = true
    LOOP
        -- Verifica se ainda existem outras variantes com essa cor
        SELECT EXISTS(
            SELECT 1 
            FROM product_variants pv
            WHERE pv.product_id = p_product_id
              AND pv.color_id = p_old_color_id
        ) INTO v_has_other_variants;
        
        -- Se não há mais variantes com essa cor, remove o vínculo
        IF NOT v_has_other_variants THEN
            DELETE FROM product_category_assignments
            WHERE product_id = p_product_id
              AND category_id = v_category_id
              AND is_primary = false;  -- Só remove vínculos por cor (não primários)
            
            IF FOUND THEN
                v_count_removed := v_count_removed + 1;
            END IF;
        END IF;
    END LOOP;
    
    RETURN jsonb_build_object(
        'success', true,
        'product_id', p_product_id,
        'old_color_id', p_old_color_id,
        'removed', v_count_removed
    );
END;
$$;


ALTER FUNCTION "public"."fn_remove_orphan_color_links"("p_product_id" "uuid", "p_old_color_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_remove_orphan_color_links"("p_product_id" "uuid", "p_old_color_id" "uuid") IS 'Remove vínculos produto→categoria quando a cor é alterada/removida. v1.1 - 31/01/2026';



CREATE OR REPLACE FUNCTION "public"."fn_remove_similarity_pairs_on_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  DELETE FROM product_relationships pr
  WHERE pr.relationship_type = 'similar'
    AND (pr.product_id = OLD.product_id OR pr.related_product_id = OLD.product_id)
    AND NOT EXISTS (
      SELECT 1
      FROM product_similarity_group_members m1
      JOIN product_similarity_group_members m2
        ON m1.group_id = m2.group_id
        AND m1.product_id != m2.product_id
        AND m1.supplier_id != m2.supplier_id
      JOIN product_similarity_groups g ON g.id = m1.group_id
      WHERE g.is_active = true
        AND m1.product_id = pr.product_id
        AND m2.product_id = pr.related_product_id
    );
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."fn_remove_similarity_pairs_on_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_repair_canonical_chains"("p_max_iterations" integer DEFAULT 10) RETURNS TABLE("iterations_run" integer, "chains_repaired" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_iteration  int := 0;
  v_repaired   bigint;
  v_total      bigint := 0;
BEGIN
  LOOP
    v_iteration := v_iteration + 1;
    EXIT WHEN v_iteration > p_max_iterations;

    WITH chains AS (
      SELECT
        child.id                         AS child_id,
        mid.canonical_image_id           AS true_root_id
      FROM public.product_images child
      JOIN public.product_images mid ON mid.id = child.canonical_image_id
      WHERE child.canonical_image_id IS NOT NULL
        AND mid.canonical_image_id IS NOT NULL
        AND child.deleted_at IS NULL
      LIMIT 10000
    )
    UPDATE public.product_images pi
    SET canonical_image_id   = c.true_root_id,
        last_modified_source = 'migration',
        updated_at           = now()
    FROM chains c
    WHERE pi.id = c.child_id;

    GET DIAGNOSTICS v_repaired = ROW_COUNT;
    v_total := v_total + v_repaired;

    EXIT WHEN v_repaired = 0;
  END LOOP;

  RETURN QUERY SELECT v_iteration, v_total;
END;
$$;


ALTER FUNCTION "public"."fn_repair_canonical_chains"("p_max_iterations" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reposicao_backfill_today"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated int;
  v_t0 timestamptz := clock_timestamp();
  v_today date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;  -- "hoje" BR
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_reposicao_backfill_today')::bigint) THEN
    RETURN jsonb_build_object('skipped','lock_ocupado','ts',now());
  END IF;

  -- 1. Re-rodar agregação do dia atual BR (idempotente; grava flag day-boundary)
  PERFORM public.fn_aggregate_stock_daily(v_today);

  -- 2. Self-heal: flag = fronteira do dia (open=0 & close>0) para hoje BR
  UPDATE stock_daily_summary sds
  SET restock_zero_to_positive = (COALESCE(sds.stock_open,0) = 0 AND COALESCE(sds.stock_close,0) > 0)
  WHERE sds.summary_date = v_today
    AND sds.restock_zero_to_positive
        IS DISTINCT FROM (COALESCE(sds.stock_open,0) = 0 AND COALESCE(sds.stock_close,0) > 0);

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'updated', v_updated,
    'date', v_today,
    'version', 'v4_sp_tz',
    'segundos', ROUND(EXTRACT(EPOCH FROM clock_timestamp() - v_t0)::numeric, 2),
    'ts', now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_reposicao_backfill_today"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reprocessar_variantes_sem_cor"() RETURNS TABLE("variantes_processadas" integer, "variantes_vinculadas" integer, "variantes_pendentes" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_total INT;
    v_vinculadas INT;
BEGIN
    -- Contar antes
    SELECT COUNT(*) INTO v_total 
    FROM product_variants WHERE color_id IS NULL;
    
    -- Reprocessar por código SPOT
    UPDATE product_variants pv
    SET 
        color_id = ce.promo_variation_id,
        color_name = cv.name,
        color_hex = cv.hex_code,
        updated_at = now()
    FROM supplier_colors sc
    JOIN color_equivalences ce ON ce.supplier_color_id = sc.id
    JOIN color_variations cv ON cv.id = ce.promo_variation_id
    WHERE pv.attributes->>'codigo_cor' = sc.code
      AND pv.color_id IS NULL;
    
    -- Reprocessar por nome
    UPDATE product_variants pv
    SET 
        color_id = cv.id,
        color_name = cv.name,
        color_hex = cv.hex_code,
        updated_at = now()
    FROM color_variations cv
    WHERE pv.color_id IS NULL
      AND pv.attributes->>'cor' IS NOT NULL
      AND (
          LOWER(TRIM(pv.attributes->>'cor')) = LOWER(TRIM(cv.name))
          OR LOWER(cv.name) LIKE LOWER(TRIM(pv.attributes->>'cor')) || '%'
      );
    
    -- Contar depois
    SELECT COUNT(*) INTO v_vinculadas 
    FROM product_variants WHERE color_id IS NOT NULL;
    
    -- Retornar estatísticas
    RETURN QUERY SELECT 
        v_total,
        v_total - (SELECT COUNT(*)::INT FROM product_variants WHERE color_id IS NULL),
        (SELECT COUNT(*)::INT FROM product_variants WHERE color_id IS NULL);
END;
$$;


ALTER FUNCTION "public"."fn_reprocessar_variantes_sem_cor"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_reprocessar_variantes_sem_cor"() IS 'Reprocessa variantes sem color_id tentando vinculá-las. Retorna estatísticas.';



CREATE OR REPLACE FUNCTION "public"."fn_request_product_deactivation"("p_product_id" "uuid", "p_reason" "text", "p_reason_code" "text" DEFAULT 'manual'::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_p    products%ROWTYPE;
  v_uid  uuid := auth.uid();
  v_req  uuid;
  v_name text;
BEGIN
  -- Validar produto
  SELECT * INTO v_p FROM products WHERE id = p_product_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'produto_nao_encontrado');
  END IF;

  IF NOT v_p.is_active THEN
    RETURN jsonb_build_object('ok', false, 'error', 'produto_ja_inativo');
  END IF;

  -- Verificar se já existe solicitação pending para este produto
  IF EXISTS (
    SELECT 1 FROM product_deactivation_requests
    WHERE product_id = p_product_id AND status = 'pending'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ja_existe_solicitacao_pendente',
      'hint', 'Use fn_list_deactivation_requests() para ver pendentes');
  END IF;

  -- Nome do usuário solicitante
  SELECT COALESCE(raw_user_meta_data->>'full_name', email)
  INTO v_name FROM auth.users WHERE id = v_uid;

  INSERT INTO product_deactivation_requests (
    product_id, supplier_id, supplier_reference, product_name,
    reason, reason_code, notes,
    requested_by, requested_by_name, status
  )
  VALUES (
    p_product_id, v_p.supplier_id, v_p.supplier_reference, v_p.name,
    p_reason, p_reason_code, p_notes,
    v_uid, COALESCE(v_name,'sistema'), 'pending'
  )
  RETURNING id INTO v_req;

  RETURN jsonb_build_object(
    'ok', true,
    'request_id', v_req,
    'product_id', p_product_id,
    'product_name', v_p.name,
    'supplier_reference', v_p.supplier_reference,
    'status', 'pending',
    'message', 'Solicitação criada. Aguarda aprovação de administrador.'
  );
END;
$$;


ALTER FUNCTION "public"."fn_request_product_deactivation"("p_product_id" "uuid", "p_reason" "text", "p_reason_code" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reset_is_shared_on_canonical_null"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.canonical_image_id IS NULL AND OLD.canonical_image_id IS NOT NULL THEN
    NEW.is_shared := false;
    NEW.last_modified_source := COALESCE(NULLIF(NEW.last_modified_source, ''), 'edge_function');
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;


