CREATE OR REPLACE FUNCTION "public"."fn_resolve_supplier_arrivals"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_delta         integer;
  v_snapshot_date date;
BEGIN
  -- [C2] usar deltas pré-calculadas
  v_delta := COALESCE(NEW.stock_main_delta, 0) + COALESCE(NEW.stock_other_delta, 0);
  IF v_delta <= 0 THEN RETURN NULL; END IF;

  v_snapshot_date := NEW.captured_at::date;

  -- Idempotência: snapshot já resolveu uma promessa?
  IF EXISTS (
    SELECT 1 FROM public.supplier_replenishment_events
    WHERE arrival_snapshot_id = NEW.id
  ) THEN RETURN NULL; END IF;

  -- Casar com promessa pendente mais próxima
  UPDATE public.supplier_replenishment_events
  SET
    resolution          = 'fulfilled',
    actual_date         = v_snapshot_date,
    actual_quantity     = v_delta,
    resolved_at         = now(),
    arrival_snapshot_id = NEW.id,
    updated_at          = now()
  WHERE id = (
    SELECT id
    FROM public.supplier_replenishment_events
    WHERE source_id  = NEW.variant_supplier_source_id
      AND resolution = 'pending'
      AND ABS(promised_date - v_snapshot_date) <= 15
    ORDER BY
      ABS(promised_date - v_snapshot_date) ASC,
      ABS(COALESCE(promised_quantity, 0) - v_delta) ASC
    LIMIT 1
  );

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_resolve_supplier_arrivals"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_resolve_supplier_arrivals"() IS 'Trigger AFTER INSERT em stock_snapshots. Se delta (stock_main_delta + stock_other_delta) > 0, casa com a promessa pending mais próxima dentro de ±15 dias para o mesmo source_id, usando menor distância de dias e de quantidade. Idempotente: verifica arrival_snapshot_id antes de resolver (index: idx_sre_arrival_snapshot).';



CREATE OR REPLACE FUNCTION "public"."fn_resync_all_category_counts"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated integer := 0;
  v_color_inherited integer := 0;
BEGIN
  -- 1. Resync products_count via PCA
  UPDATE categories c
  SET products_count = COALESCE(sub.cnt, 0), updated_at = now()
  FROM (
    SELECT pca.category_id, COUNT(DISTINCT p.id) as cnt
    FROM product_category_assignments pca
    JOIN products p ON p.id = pca.product_id AND p.is_active = true
    GROUP BY pca.category_id
  ) sub
  WHERE c.id = sub.category_id AND c.products_count IS DISTINCT FROM sub.cnt;
  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- 2. Zerar categorias sem produtos
  UPDATE categories c
  SET products_count = 0, updated_at = now()
  WHERE c.products_count > 0
    AND NOT EXISTS (
      SELECT 1 FROM product_category_assignments pca
      JOIN products p ON p.id=pca.product_id AND p.is_active=true
      WHERE pca.category_id=c.id
    );

  -- 3. Restaurar visibilidade de categorias que ganharam produtos
  UPDATE categories c
  SET is_visible = true, updated_at = now()
  WHERE c.is_active = true AND c.is_visible = false AND c.products_count > 0;

  -- 4. Herdar color_hex de categorias novas sem cor (prevenção de gaps futuros)
  FOR v_color_inherited IN 2..6 LOOP
    UPDATE categories c
    SET color_hex = parent.color_hex, updated_at = now()
    FROM categories parent
    WHERE c.parent_id = parent.id
      AND c.level = v_color_inherited
      AND c.is_active = true
      AND c.color_hex IS NULL
      AND parent.color_hex IS NOT NULL;
  END LOOP;
  GET DIAGNOSTICS v_color_inherited = ROW_COUNT;

  RETURN jsonb_build_object(
    'updated_counts', v_updated,
    'color_inherited', v_color_inherited,
    'executed_at', now(),
    'total_visible', (SELECT COUNT(*) FROM categories WHERE is_active=true AND is_visible=true),
    'zero_color', (SELECT COUNT(*) FROM categories WHERE is_active=true AND color_hex IS NULL)
  );
END;
$$;


ALTER FUNCTION "public"."fn_resync_all_category_counts"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_resync_all_category_counts"() IS 'Ressincroniza products_count, is_visible e demais contadores das categorias. Chamar após grandes operações no catálogo ou via cron semanal.';



CREATE OR REPLACE FUNCTION "public"."fn_resync_categories_products_count"() RETURNS TABLE("categorias_corrigidas" integer, "total_categorias" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_fixed int;
  v_total int;
BEGIN
  WITH real_counts AS (
    SELECT 
      c.id AS category_id,
      (SELECT COUNT(DISTINCT pca.product_id) 
       FROM product_category_assignments pca
       JOIN products p ON p.id = pca.product_id
       WHERE pca.category_id = c.id 
         AND p.is_active = true
         AND (p.is_deleted IS NULL OR p.is_deleted = false)
      ) AS real_count
    FROM categories c WHERE c.is_active
  ),
  upd AS (
    UPDATE categories SET products_count = rc.real_count
    FROM real_counts rc
    WHERE categories.id = rc.category_id
      AND COALESCE(categories.products_count, -1) <> rc.real_count
    RETURNING 1
  )
  SELECT COUNT(*)::int INTO v_fixed FROM upd;
  
  SELECT COUNT(*)::int INTO v_total FROM categories WHERE is_active;
  
  RETURN QUERY SELECT v_fixed, v_total;
END;
$$;


ALTER FUNCTION "public"."fn_resync_categories_products_count"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_resync_categories_products_count"() IS 'Recalcula cache products_count em categorias ativas. Útil após imports em massa que podem bypassar triggers.';



CREATE OR REPLACE FUNCTION "public"."fn_resync_full_path_readable"("p_root_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("updated_count" integer, "elapsed_ms" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_start TIMESTAMPTZ := clock_timestamp();
    v_updated INT;
    v_root_chain TEXT;
BEGIN
    IF p_root_id IS NULL THEN
        -- Resync GLOBAL: partir das raízes reais
        WITH RECURSIVE correct_fpr AS (
            SELECT c.id, UPPER(COALESCE(c.name,'')) AS chain
            FROM categories c WHERE c.parent_id IS NULL
            UNION ALL
            SELECT child.id, cf.chain||' > '||UPPER(COALESCE(child.name,''))
            FROM categories child JOIN correct_fpr cf ON child.parent_id = cf.id
        )
        UPDATE categories cat SET full_path_readable = cf.chain
        FROM correct_fpr cf
        WHERE cat.id = cf.id AND cat.full_path_readable IS DISTINCT FROM cf.chain;
    ELSE
        -- Resync de subárvore: calcular a chain correta a partir dos ancestrais reais
        SELECT CASE WHEN c.parent_id IS NULL THEN UPPER(COALESCE(c.name,''))
                    ELSE (SELECT full_path_readable FROM categories WHERE id = c.parent_id)
                         ||' > '||UPPER(COALESCE(c.name,''))
               END INTO v_root_chain
        FROM categories c WHERE c.id = p_root_id;

        IF v_root_chain IS NULL THEN
            RAISE EXCEPTION 'Category % not found or parent has no full_path_readable', p_root_id;
        END IF;

        WITH RECURSIVE correct_fpr AS (
            SELECT p_root_id AS id, v_root_chain AS chain
            UNION ALL
            SELECT child.id, cf.chain||' > '||UPPER(COALESCE(child.name,''))
            FROM categories child JOIN correct_fpr cf ON child.parent_id = cf.id
        )
        UPDATE categories cat SET full_path_readable = cf.chain
        FROM correct_fpr cf
        WHERE cat.id = cf.id AND cat.full_path_readable IS DISTINCT FROM cf.chain;
    END IF;

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN QUERY SELECT v_updated, ROUND(EXTRACT(EPOCH FROM (clock_timestamp()-v_start))*1000, 2);
END;
$$;


ALTER FUNCTION "public"."fn_resync_full_path_readable"("p_root_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_resync_product_image_urls"("p_product_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_force" boolean DEFAULT false) RETURNS TABLE("product_id" "uuid", "action" "text", "primary_url_set" "text", "og_url_set" "text", "images_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product_id UUID;
  v_new_primary_url TEXT;
  v_new_og_url TEXT;
  v_new_fallback_url TEXT;
  v_new_set_url TEXT;
  v_new_images JSONB;
  v_images_count INTEGER;
  v_old_primary_url TEXT;
BEGIN
  -- Iterar sobre os produtos selecionados (ou todos)
  FOR v_product_id IN
    SELECT p.id
    FROM public.products p
    WHERE (p_product_ids IS NULL OR p.id = ANY(p_product_ids))
      AND p.is_active = true
    ORDER BY p.id
  LOOP
    -- Buscar primary_url atual para comparação
    SELECT primary_image_url INTO v_old_primary_url
    FROM public.products WHERE id = v_product_id;

    -- Calcular nova primary_image_url
    SELECT url_cdn INTO v_new_primary_url
    FROM public.product_images
    WHERE product_id = v_product_id AND is_active = true
      AND image_type NOT IN ('box','pouch','location','area','component')
    ORDER BY
      CASE
        WHEN image_type = 'main'    AND is_primary = true  THEN 0
        WHEN image_type = 'main'                           THEN 1
        WHEN image_type IN ('gallery','product') AND is_primary = true THEN 2
        WHEN image_type IN ('gallery','product')           THEN 3
        WHEN image_type = 'ambient'                        THEN 4
        WHEN image_type = 'set'    AND is_primary = true  THEN 5
        WHEN image_type = 'set'                            THEN 6
        WHEN image_type = 'logo'                           THEN 7
        ELSE 9
      END,
      is_primary DESC, display_order ASC NULLS LAST
    LIMIT 1;

    -- Pular se não forçado e URL não mudou
    IF NOT p_force AND v_new_primary_url IS NOT DISTINCT FROM v_old_primary_url THEN
      CONTINUE;
    END IF;

    -- Calcular og_image_url
    SELECT url_cdn INTO v_new_og_url
    FROM public.product_images
    WHERE product_id = v_product_id AND is_active = true
      AND image_type NOT IN ('box','pouch','location','area','component')
    ORDER BY
      CASE WHEN is_og_image = true                       THEN 0
           WHEN image_type = 'main' AND is_primary = true THEN 1
           WHEN image_type = 'main'                       THEN 2
           WHEN image_type IN ('gallery','product')       THEN 3
           WHEN image_type = 'ambient'                    THEN 4
           WHEN image_type = 'set'                        THEN 5
           ELSE 9 END,
      is_primary DESC, display_order ASC NULLS LAST
    LIMIT 1;

    -- Calcular fallback URL (url_original do mesmo produto)
    SELECT url_original INTO v_new_fallback_url
    FROM public.product_images
    WHERE product_id = v_product_id AND is_active = true
      AND url_original IS NOT NULL AND url_original != ''
      AND image_type NOT IN ('box','pouch','location','area','component')
    ORDER BY
      CASE
        WHEN image_type = 'main' AND is_primary = true THEN 0
        WHEN image_type = 'main'                       THEN 1
        ELSE 9
      END,
      is_primary DESC, display_order ASC NULLS LAST
    LIMIT 1;

    -- Calcular set_image_url
    SELECT url_cdn INTO v_new_set_url
    FROM public.product_images
    WHERE product_id = v_product_id AND is_active = true AND image_type = 'set'
    ORDER BY display_order ASC, created_at ASC
    LIMIT 1;

    -- Calcular array de imagens (jsonb)
    SELECT
      COALESCE(jsonb_agg(url_cdn ORDER BY
        CASE
          WHEN image_type = 'main'    AND is_primary = true THEN 0
          WHEN image_type = 'main'                          THEN 1
          WHEN image_type IN ('gallery','product')          THEN 2
          WHEN image_type = 'ambient'                       THEN 3
          WHEN image_type = 'set'                           THEN 4
          WHEN image_type = 'logo'                          THEN 5
          ELSE 9
        END,
        is_primary DESC, display_order ASC NULLS LAST
      ) FILTER (WHERE image_type NOT IN ('box','pouch','location','area','component')),
      '[]'::jsonb
    ),
    COUNT(*)::INTEGER
    INTO v_new_images, v_images_count
    FROM public.product_images
    WHERE product_id = v_product_id AND is_active = true;

    -- Aplicar atualização
    UPDATE public.products SET
      primary_image_url         = v_new_primary_url,
      og_image_url              = v_new_og_url,
      primary_image_fallback_url = v_new_fallback_url,
      set_image_url             = v_new_set_url,
      images                    = v_new_images,
      updated_at                = NOW()
    WHERE id = v_product_id;

    -- Retornar resultado
    RETURN QUERY
      SELECT
        v_product_id,
        CASE
          WHEN v_old_primary_url IS NULL AND v_new_primary_url IS NOT NULL THEN 'SET'
          WHEN v_old_primary_url IS NOT NULL AND v_new_primary_url IS NULL THEN 'CLEARED'
          ELSE 'UPDATED'
        END,
        COALESCE(v_new_primary_url, '(null)'),
        COALESCE(v_new_og_url, '(null)'),
        v_images_count;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_resync_product_image_urls"("p_product_ids" "uuid"[], "p_force" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_resync_product_image_urls"("p_product_ids" "uuid"[], "p_force" boolean) IS 'Re-sincroniza manualmente os campos de imagem em products a partir de product_images.
   Útil quando o trigger falhou ou produto recebeu imagens sem disparar sync.
   
   Uso:
     -- Resync de produtos específicos:
     SELECT * FROM fn_resync_product_image_urls(ARRAY[''uuid1'', ''uuid2'']::UUID[]);
     
     -- Resync de TODOS (só onde URL mudou):
     SELECT * FROM fn_resync_product_image_urls();
     
     -- Forçar resync de todos mesmo sem mudança:
     SELECT * FROM fn_resync_product_image_urls(NULL, TRUE);
   
   Adicionada 2026-06-15.';



CREATE OR REPLACE FUNCTION "public"."fn_resync_product_media"("p_product_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  WITH targets AS (
    SELECT p.id
    FROM products p
    WHERE p_product_ids IS NULL OR p.id = ANY(p_product_ids)
  ),
  agg AS (
    SELECT t.id AS product_id,
      COALESCE((
        SELECT jsonb_agg(url_cdn ORDER BY
          CASE WHEN image_type='main' AND is_primary THEN 0
               WHEN image_type='main' THEN 1
               WHEN image_type IN ('gallery','product') THEN 2
               WHEN image_type='ambient' THEN 3
               WHEN image_type='set' THEN 4
               WHEN image_type='logo' THEN 5 ELSE 9 END,
          is_primary DESC, display_order ASC NULLS LAST,
          created_at ASC, cloudflare_image_id ASC)
          FILTER (WHERE image_type NOT IN ('box','pouch','location','area','component'))
        FROM product_images WHERE product_id=t.id AND is_active), '[]'::jsonb) AS images,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active
          AND image_type NOT IN ('box','pouch','location','area','component')
        ORDER BY CASE WHEN is_og_image THEN 0
                      WHEN image_type='main' AND is_primary THEN 1
                      WHEN image_type='main' THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' THEN 5 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST,
                 created_at ASC, cloudflare_image_id ASC LIMIT 1) AS og_url,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active
          AND image_type NOT IN ('box','pouch','location','area','component')
        ORDER BY CASE WHEN image_type='main' AND is_primary THEN 0
                      WHEN image_type='main' THEN 1
                      WHEN image_type IN ('gallery','product') AND is_primary THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' AND is_primary THEN 5
                      WHEN image_type='set' THEN 6
                      WHEN image_type='logo' THEN 7 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST,
                 created_at ASC, cloudflare_image_id ASC LIMIT 1) AS primary_url,
      ( SELECT url_original FROM product_images
        WHERE product_id=t.id AND is_active AND url_original IS NOT NULL AND url_original<>''
        ORDER BY CASE WHEN image_type='main' AND is_primary THEN 0
                      WHEN image_type='main' THEN 1
                      WHEN image_type IN ('gallery','product') AND is_primary THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' AND is_primary THEN 5
                      WHEN image_type='set' THEN 6
                      WHEN image_type='logo' THEN 7 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST,
                 created_at ASC, cloudflare_image_id ASC LIMIT 1) AS fallback_url,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active AND image_type='set'
        ORDER BY display_order ASC, created_at ASC, cloudflare_image_id ASC LIMIT 1) AS set_url
    FROM targets t
  )
  UPDATE products p SET
    images                     = agg.images,
    og_image_url               = agg.og_url,
    primary_image_url          = agg.primary_url,
    primary_image_fallback_url = agg.fallback_url,
    set_image_url              = agg.set_url
  FROM agg
  WHERE p.id = agg.product_id
    AND ( p.images                     IS DISTINCT FROM agg.images
       OR p.og_image_url               IS DISTINCT FROM agg.og_url
       OR p.primary_image_url          IS DISTINCT FROM agg.primary_url
       OR p.primary_image_fallback_url IS DISTINCT FROM agg.fallback_url
       OR p.set_image_url              IS DISTINCT FROM agg.set_url );

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_resync_product_media"("p_product_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_resync_product_media"("p_product_ids" "uuid"[]) IS 'Recomputa, de forma set-based, determinística e idempotente, os campos de mídia desnormalizados em products para os product_ids dados (ou todos se NULL). Use após cargas em massa com triggers AFTER desabilitados para eliminar amplificação de escrita. Só escreve linhas que mudam.';



CREATE OR REPLACE FUNCTION "public"."fn_resync_product_physical_all"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_ok    integer := 0;
  v_skip  integer := 0;
  v_err   integer := 0;
  v_result boolean;
  r        record;
BEGIN
  FOR r IN SELECT product_id FROM product_physical LOOP
    BEGIN
      v_result := fn_sync_product_physical_from_products(r.product_id);
      IF v_result THEN v_ok := v_ok + 1;
      ELSE v_skip := v_skip + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_err := v_err + 1;
    END;
  END LOOP;
  RETURN jsonb_build_object('ok', v_ok, 'skip', v_skip, 'err', v_err, 'ts', now());
END;
$$;


ALTER FUNCTION "public"."fn_resync_product_physical_all"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_revoke_truncate_public"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
/*
  v1_2026-06-13 — Revoga TRUNCATE de anon/authenticated em todas as tabelas públicas.
  Supabase recria permissões via supabase_admin em novas tabelas/views/matviews.
  Este job roda diariamente para manter o inventário limpo.
*/
DECLARE v_antes int; v_depois int;
BEGIN
  SELECT count(*) INTO v_antes FROM information_schema.role_table_grants
  WHERE grantee IN ('anon','authenticated') AND privilege_type='TRUNCATE' AND table_schema='public';

  REVOKE TRUNCATE ON ALL TABLES IN SCHEMA public FROM anon;
  REVOKE TRUNCATE ON ALL TABLES IN SCHEMA public FROM authenticated;

  SELECT count(*) INTO v_depois FROM information_schema.role_table_grants
  WHERE grantee IN ('anon','authenticated') AND privilege_type='TRUNCATE' AND table_schema='public';

  RAISE NOTICE 'fn_revoke_truncate_public: antes=% depois=% revogados=%', v_antes, v_depois, v_antes-v_depois;
  RETURN v_antes - v_depois;
END $$;


ALTER FUNCTION "public"."fn_revoke_truncate_public"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_revoke_view_write_grants_on_create"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  obj record;
  view_name text;
BEGIN
  FOR obj IN
    SELECT object_type, schema_name, object_identity
    FROM pg_event_trigger_ddl_commands()
    WHERE object_type = 'view'
      AND schema_name = 'public'
  LOOP
    view_name := obj.object_identity;
    BEGIN
      EXECUTE format(
        'REVOKE INSERT, UPDATE, DELETE, REFERENCES, TRIGGER ON %s FROM anon, authenticated',
        view_name
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'fn_revoke_view_write_grants_on_create: could not revoke on %: %',
        view_name, SQLERRM;
    END;
  END LOOP;
END;
$$;


