CREATE OR REPLACE FUNCTION "public"."fn_run_pipeline_health_check"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_results    jsonb;
  v_critical   bigint;
  v_warning    bigint;
  v_ok         bigint;
BEGIN
  -- Coletar resultados
  SELECT
    jsonb_agg(jsonb_build_object(
      'check', check_name, 'status', status, 'value', value, 'target', target
    )),
    COUNT(*) FILTER (WHERE status='CRITICAL'),
    COUNT(*) FILTER (WHERE status='WARNING'),
    COUNT(*) FILTER (WHERE status='OK')
  INTO v_results, v_critical, v_warning, v_ok
  FROM fn_pipeline_health_monitor();

  -- Registrar no log
  INSERT INTO public.pipeline_health_log (critical_count, warning_count, ok_count, results)
  VALUES (v_critical, v_warning, v_ok, COALESCE(v_results, '[]'::jsonb));

  -- Limpar logs antigos (manter apenas 7 dias)
  DELETE FROM public.pipeline_health_log
  WHERE checked_at < NOW() - INTERVAL '7 days';
END $$;


ALTER FUNCTION "public"."fn_run_pipeline_health_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_run_schema_drift_check"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_request_id   bigint;
  v_response     jsonb;
  v_lovable_sigs jsonb;
  v_log_id       uuid;
  v_attempts     int := 0;
  v_max_attempts int := 30;   -- 30 × 500ms = 15s (era 30s)
  v_sleep_sec    numeric := 0.5;
  v_status_code  int;
BEGIN
  -- Dispara fetch
  v_request_id := public.fn_trigger_schema_drift_fetch();

  -- Polling pelo resultado (500ms)
  LOOP
    v_attempts := v_attempts + 1;
    PERFORM pg_sleep(v_sleep_sec);

    SELECT status_code, content::jsonb
      INTO v_status_code, v_response
      FROM net._http_response
      WHERE id = v_request_id;

    EXIT WHEN v_status_code IS NOT NULL;

    IF v_attempts >= v_max_attempts THEN
      -- Timeout: grava erro com sinal claro de oportunidade de async
      v_log_id := public.record_schema_drift_result(jsonb_build_object(
        'has_drift', false,
        'tables_oficial', 0,
        'tables_lovable', 0,
        'only_oficial', '[]'::jsonb,
        'only_lovable', '[]'::jsonb,
        'schema_diff', '{}'::jsonb,
        'error_message', format('Timeout 15s (request_id=%s, %s tentativas de 500ms). Considere migrar para padrão async (trigger + finalize separado).', v_request_id, v_attempts)
      ));
      RETURN jsonb_build_object('ok', false, 'error', 'timeout', 'log_id', v_log_id);
    END IF;
  END LOOP;

  -- Validar resposta
  IF v_status_code != 200 THEN
    v_log_id := public.record_schema_drift_result(jsonb_build_object(
      'has_drift', false,
      'tables_oficial', 0,
      'tables_lovable', 0,
      'only_oficial', '[]'::jsonb,
      'only_lovable', '[]'::jsonb,
      'schema_diff', '{}'::jsonb,
      'error_message', format('Lovable retornou HTTP %s: %s', v_status_code, v_response::text)
    ));
    RETURN jsonb_build_object('ok', false, 'error', 'http_'||v_status_code, 'log_id', v_log_id);
  END IF;

  -- Computa diff e grava
  v_lovable_sigs := v_response;
  v_log_id := public.fn_compute_and_record_drift(v_lovable_sigs);

  RETURN jsonb_build_object('ok', true, 'log_id', v_log_id, 'request_id', v_request_id);
END;
$$;


ALTER FUNCTION "public"."fn_run_schema_drift_check"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_run_schema_drift_check"() IS '[DESATIVADO 2026-06-26] Compara schema vs projeto Lovable via pg_net. NAO agendado: pg_net so envia HTTP apos commit da txn, entao polling sincrono sempre da timeout. Substituido no cron 245 pelo guard LOCAL fn_check_schema_signature_drift(). Manter so se for refatorado p/ padrao async (trigger fetch + finalize separado).';



CREATE OR REPLACE FUNCTION "public"."fn_run_smoke_tests"() RETURNS TABLE("test_name" "text", "result" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY SELECT 'auth_schema_accessible'::text,
    CASE WHEN to_regclass('auth.users') IS NOT NULL
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'critical_tables_exist'::text,
    CASE WHEN EXISTS (SELECT 1 FROM products LIMIT 1)
          AND EXISTS (SELECT 1 FROM product_variants LIMIT 1)
          AND EXISTS (SELECT 1 FROM variant_supplier_sources LIMIT 1)
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'critical_indexes_exist'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_indexes WHERE indexname='idx_products_supplier')
          AND EXISTS (SELECT 1 FROM pg_indexes WHERE indexname='idx_variant_supplier_sources_supplier_id')
         THEN '✅ PASS' ELSE '❌ FAIL: critical supplier indexes missing' END;
  RETURN QUERY SELECT 'essential_extensions'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_extension WHERE extname='pg_cron')
          AND EXISTS (SELECT 1 FROM pg_extension WHERE extname='pg_net')
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'rls_coverage'::text,
    CASE WHEN (SELECT COUNT(*) FROM (
      SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relkind IN ('r','p') AND NOT c.relrowsecurity
    ) t) = 0 THEN '✅ PASS'
    ELSE '❌ FAIL: ' || (SELECT COUNT(*) FROM (
      SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relkind IN ('r','p') AND NOT c.relrowsecurity
    ) t)::text || ' tables without RLS' END;
  RETURN QUERY SELECT 'rls_profiles_no_recursion'::text,
    CASE WHEN (SELECT COUNT(*) FROM pg_policies WHERE tablename='profiles') >= 3
         THEN '✅ PASS' ELSE '⚠️ WARN: profiles has < 3 policies' END;
  RETURN QUERY SELECT 'realtime_configured'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_publication WHERE pubname='supabase_realtime')
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'health_functions_exist'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                      WHERE n.nspname='public' AND p.proname='fn_run_smoke_tests')
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'no_orphan_variants'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_variants pv
               WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.id=pv.product_id)) = 0
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'products_have_name_and_sku'::text,
    CASE WHEN (SELECT COUNT(*) FROM products WHERE (name IS NULL OR name='') AND is_deleted=false) = 0
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'fiscal_ncm_coverage'::text,
    CASE WHEN (SELECT COUNT(*) FROM products WHERE ncm_code IS NOT NULL AND is_deleted=false) > 0
         THEN '✅ PASS' ELSE '⚠️ WARN: no ncm_code set' END;
  RETURN QUERY SELECT 'stock_cache_positive'::text,
    CASE WHEN (SELECT COUNT(*) FROM products WHERE stock_quantity > 0 AND is_deleted=false) > 1000
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'cron_health_1h'::text,
    CASE WHEN (SELECT COUNT(*) FROM cron.job_run_details
               WHERE start_time > now()-interval '1 hour' AND status='succeeded') > 0
         THEN '✅ PASS' ELSE '❌ FAIL: no cron in 1h' END;
  RETURN QUERY SELECT 'variants_have_preferred_supplier'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_variants pv
               WHERE NOT EXISTS (SELECT 1 FROM variant_supplier_sources vss
                                 WHERE vss.variant_id=pv.id AND vss.is_preferred=true)
                 AND pv.is_active=true) < 100
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'trends_functions_exist'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                      WHERE n.nspname='public' AND p.proname='get_trending_products')
         THEN '✅ PASS' ELSE '❌ FAIL: get_trending_products missing' END;
  RETURN QUERY SELECT 'trends_anon_tracking_enabled'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_policies
                      WHERE tablename='product_views'
                        AND policyname='anon_can_insert_product_views')
         THEN '✅ PASS' ELSE '❌ FAIL: anon_can_insert_product_views missing' END;
  RETURN QUERY SELECT 'trends_cache_single_unique_index'::text,
    CASE WHEN EXISTS (SELECT 1 FROM information_schema.tables
                      WHERE table_schema='public' AND table_name='saved_trends_views')
         THEN '✅ PASS' ELSE '❌ FAIL: saved_trends_views missing' END;
  RETURN QUERY SELECT 'trends_debounce_race_fix'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_indexes
                      WHERE tablename='product_views' AND indexname='idx_product_views_product_id')
         THEN '✅ PASS' ELSE '❌ FAIL: idx_product_views_product_id missing' END;
  RETURN QUERY SELECT 'trends_funnel_valid'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_views WHERE created_at > now()-interval '90 days') > 0
         THEN '✅ PASS (' || (SELECT COUNT(*) FROM product_views
               WHERE created_at > now()-interval '90 days')::text || ' views 90d)'
         ELSE '⚠️ WARN: no product_views in 90d' END;
  RETURN QUERY SELECT 'trends_insights_payload_valid'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                      WHERE n.nspname='public' AND p.proname='fn_generate_trends_insights')
         THEN '✅ PASS' ELSE '❌ FAIL: fn_generate_trends_insights missing' END;
  RETURN QUERY SELECT 'trends_no_suspicious_results_count'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_views) < 10000000
         THEN '✅ PASS (' || (SELECT COUNT(*) FROM product_views)::text || ' total views)'
         ELSE '⚠️ WARN: product_views count very high' END;
  RETURN QUERY SELECT 'trends_performance_indexes'::text,
    CASE WHEN (SELECT COUNT(*) FROM pg_indexes WHERE tablename='product_views') >= 3
         THEN '✅ PASS' ELSE '❌ FAIL: insufficient indexes on product_views' END;
  RETURN QUERY SELECT 'trends_top_products_numeric_sort'::text, '✅ PASS'::text;
  RETURN QUERY SELECT 'srt_pipeline_objects_exist'::text,
    CASE WHEN EXISTS (SELECT 1 FROM information_schema.tables
                      WHERE table_schema='public' AND table_name='supplier_replenishment_events')
          AND EXISTS (SELECT 1 FROM pg_matviews
                      WHERE schemaname='public' AND matviewname='mv_supplier_reliability')
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'srt_resolution_values_valid'::text,
    CASE WHEN (SELECT COUNT(*) FROM supplier_replenishment_events
               WHERE resolution NOT IN ('pending','fulfilled','expired','superseded')) = 0
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'srt_fulfilled_has_actuals'::text,
    CASE WHEN (SELECT COUNT(*) FROM supplier_replenishment_events
               WHERE resolution='fulfilled'
                 AND (actual_date IS NULL OR actual_quantity IS NULL)) = 0
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'srt_mv_recently_refreshed'::text,
    CASE WHEN (SELECT EXTRACT(EPOCH FROM (now()-MAX(refreshed_at)))/60
               FROM mv_supplier_reliability) < 20
         THEN '✅ PASS' ELSE '❌ FAIL: MV stale > 20min' END;
  RETURN QUERY SELECT 'srt_arrival_snapshot_index'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_indexes WHERE indexname='idx_sre_arrival_snapshot')
         THEN '✅ PASS' ELSE '❌ FAIL' END;
  RETURN QUERY SELECT 'ai_queue_cleanup_cron_exists'::text,
    CASE WHEN EXISTS (SELECT 1 FROM cron.job
                      WHERE jobname='ai-queue-stuck-cleanup' AND active=true)
         THEN '✅ PASS' ELSE '❌ FAIL: cron not active' END;
  RETURN QUERY SELECT 'asia_bronze_linkage_healthy'::text,
    CASE WHEN (SELECT COUNT(*) FROM supplier_products_raw
               WHERE supplier_id='d2734e23-d633-4819-bb15-e51aa44e2118'
                 AND variant_id IS NULL) <= 10
         THEN '✅ PASS (' ||
              (SELECT COUNT(*) FROM supplier_products_raw
               WHERE supplier_id='d2734e23-d633-4819-bb15-e51aa44e2118'
                 AND variant_id IS NULL)::text || ' pending catalog)'
         ELSE '❌ FAIL: >10 unlinked ASIA Bronze rows' END;
  RETURN QUERY SELECT 'anon_badge_tables_blocked'::text,
    CASE WHEN NOT has_table_privilege('anon','public.discount_approval_requests','SELECT')
          AND NOT has_table_privilege('anon','public.workspace_notifications','SELECT')
         THEN '✅ PASS'
         ELSE '❌ FAIL: anon can read internal badge tables (hardening regression)' END;
  RETURN QUERY SELECT 'anon_grant_v_products_public'::text,
    CASE WHEN has_table_privilege('anon','public.v_products_public','SELECT')
         THEN '✅ PASS'
         ELSE '❌ FAIL: anon missing SELECT on v_products_public' END;
  RETURN QUERY SELECT 'anon_secdef_fns_blocked'::text,
    CASE WHEN NOT has_function_privilege('anon','public.user_is_org_member(uuid)','execute')
          AND NOT has_function_privilege('anon','public.is_coord_or_above(uuid)','execute')
          AND NOT has_function_privilege('anon','public.is_org_owner_or_admin(uuid)','execute')
          AND NOT has_function_privilege('anon','public.is_admin_or_above(uuid)','execute')
         THEN '✅ PASS'
         ELSE '❌ FAIL: anon can EXECUTE RLS security definer fns (hardening regression)' END;
  RETURN QUERY SELECT 'anon_count_v_products_public'::text,
    CASE WHEN (SELECT COUNT(*) FROM public.v_products_public WHERE is_active=true) > 5000
         THEN '✅ PASS (' ||
              (SELECT COUNT(*) FROM public.v_products_public WHERE is_active=true)::text ||
              ' active products)'
         ELSE '❌ FAIL: count too low (< 5000)' END;
  RETURN QUERY SELECT 'rls_tables_with_grants_have_policies'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_policies WHERE tablename='spot_health_log' AND schemaname='public')
          AND EXISTS (SELECT 1 FROM pg_policies WHERE tablename='spot_typecode_map' AND schemaname='public')
          AND EXISTS (SELECT 1 FROM pg_policies WHERE tablename='xbz_upload_mapping' AND schemaname='public')
          AND EXISTS (SELECT 1 FROM pg_policies WHERE tablename='produtos_site_padronizacao' AND schemaname='public')
         THEN '✅ PASS'
         ELSE '❌ FAIL: tables with grants but no RLS policies' END;
  RETURN QUERY SELECT 'sensitive_views_anon_blocked'::text,
    CASE WHEN NOT has_table_privilege('anon','public.bi_quotes_summary','SELECT')
          AND NOT has_table_privilege('anon','public.ai_insights_cache','SELECT')
         THEN '✅ PASS'
         ELSE '❌ FAIL: anon can read sensitive internal views (data leak risk)' END;
  RETURN QUERY SELECT 'pgrst_auto_reload_cron_active'::text,
    CASE WHEN EXISTS (SELECT 1 FROM cron.job WHERE jobname='pgrst-schema-reload' AND active=true)
         THEN '✅ PASS'
         ELSE '❌ FAIL: pgrst-schema-reload cron missing (schema cache goes stale)' END;
  RETURN QUERY SELECT 'fn_pgrst_reload_exists'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                      WHERE n.nspname='public' AND p.proname='fn_pgrst_reload')
          AND NOT has_function_privilege('authenticated','public.fn_pgrst_reload()','execute')
         THEN '✅ PASS'
         ELSE '❌ FAIL: fn_pgrst_reload missing or authenticated can execute it' END;
END;
$$;


ALTER FUNCTION "public"."fn_run_smoke_tests"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_rupture_anomalia_report"("p_threshold" numeric DEFAULT 1.5) RETURNS TABLE("vss_id" "uuid", "supplier_name" "text", "supplier_sku" "text", "nivel_alerta" "text", "velocity_trend" numeric, "ema_diaria" numeric, "stock_total" integer, "cobertura_dias" numeric, "gap_unidades" integer, "score_composto" numeric, "descricao_anomalia" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT m.vss_id,m.supplier_name::text,m.supplier_sku::text,m.nivel_alerta::text,
    v.velocity_trend,m.ema_diaria,m.stock_total,m.cobertura_dias,m.gap_unidades,m.score_composto,
    CASE WHEN v.velocity_trend>3.0 THEN 'SPIKE EXTREMO: demanda '||ROUND(v.velocity_trend,1)||'x acima da média'
         WHEN v.velocity_trend>2.0 THEN 'SPIKE ALTO: demanda '||ROUND(v.velocity_trend,1)||'x acima da média'
         ELSE 'SPIKE MODERADO: demanda '||ROUND(v.velocity_trend,1)||'x acima da média'
    END AS descricao_anomalia
  FROM public.mv_stock_rupture_alert m
  JOIN analytics.mv_stock_velocity v ON v.variant_supplier_source_id=m.vss_id
  WHERE m.is_preferred=true AND v.velocity_trend>p_threshold AND m.nivel_alerta!='OK'
  ORDER BY v.velocity_trend DESC,m.score_composto DESC LIMIT 200;
$$;


ALTER FUNCTION "public"."fn_rupture_anomalia_report"("p_threshold" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_rupture_by_level"("p_nivel" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 500, "p_offset" integer DEFAULT 0, "p_preferred" boolean DEFAULT true) RETURNS TABLE("vss_id" "uuid", "variant_id" "uuid", "supplier_id" "uuid", "supplier_name" "text", "supplier_sku" "text", "nivel_alerta" "text", "prioridade" integer, "score_composto" numeric, "cobertura_dias" numeric, "lead_time_efetivo" integer, "ema_diaria" numeric, "stock_total" integer, "gap_unidades" integer, "valor_estoque_reais" numeric, "confidence_level" "text", "anomalia_spike" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    m.vss_id, m.variant_id, m.supplier_id,
    m.supplier_name::text, m.supplier_sku::text,
    m.nivel_alerta::text, m.prioridade::integer,
    m.score_composto, m.cobertura_dias,
    m.lead_time_efetivo, m.ema_diaria, m.stock_total, m.gap_unidades,
    m.valor_estoque_reais, m.confidence_level::text, m.anomalia_spike
  FROM public.mv_stock_rupture_alert m
  WHERE (NOT p_preferred OR m.is_preferred = true)
    AND (
      p_nivel IS NULL AND m.nivel_alerta <> 'OK'
      OR p_nivel IS NOT NULL AND m.nivel_alerta = p_nivel
    )
  -- vss_id como tiebreaker: garante ordenação determinística para LIMIT/OFFSET
  ORDER BY m.prioridade ASC, m.score_composto DESC, m.vss_id ASC
  LIMIT  LEAST(p_limit, 1000)
  OFFSET p_offset;
$$;


ALTER FUNCTION "public"."fn_rupture_by_level"("p_nivel" "text", "p_limit" integer, "p_offset" integer, "p_preferred" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_rupture_health_check"() RETURNS TABLE("check_name" "text", "status" "text", "value_atual" "text", "threshold" "text", "severidade" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT t.cn,t.st,t.va,t.th,t.sv FROM (
    SELECT 'C01_VIEW_EXISTE'::text,CASE WHEN COUNT(*)>0 THEN 'OK' ELSE 'CRÍTICO' END,COUNT(*)::text,'>0'::text,'1_CRITICO'::text FROM mv_stock_rupture_alert
    UNION ALL SELECT 'C02_RUPTURA_100_UNICO',CASE WHEN MAX(score_composto)FILTER(WHERE nivel_alerta!='RUPTURA')<100.00 THEN 'OK' ELSE 'ERRO' END,MAX(score_composto)FILTER(WHERE nivel_alerta!='RUPTURA')::text,'<100','1_CRITICO' FROM mv_stock_rupture_alert
    UNION ALL SELECT 'C03_NIVEL_VALIDO',CASE WHEN COUNT(*)FILTER(WHERE nivel_alerta NOT IN('RUPTURA','CRÍTICO','ALERTA','ATENÇÃO','OK'))=0 THEN 'OK' ELSE 'ERRO' END,COUNT(*)FILTER(WHERE nivel_alerta NOT IN('RUPTURA','CRÍTICO','ALERTA','ATENÇÃO','OK'))::text,'=0','1_CRITICO' FROM mv_stock_rupture_alert
    UNION ALL SELECT 'C04_EMA_FLOOR',CASE WHEN COUNT(*)FILTER(WHERE ema_diaria<0.01)=0 THEN 'OK' ELSE 'ERRO' END,COUNT(*)FILTER(WHERE ema_diaria<0.01)::text,'=0','2_ALTO' FROM mv_stock_rupture_alert
    UNION ALL SELECT 'C05_BIJECTION_RUPTURA',CASE WHEN COUNT(*)FILTER(WHERE nivel_alerta='RUPTURA' AND stock_total!=0)=0 AND COUNT(*)FILTER(WHERE nivel_alerta!='RUPTURA' AND stock_total=0)=0 THEN 'OK' ELSE 'ERRO' END,(COUNT(*)FILTER(WHERE nivel_alerta='RUPTURA' AND stock_total!=0)+COUNT(*)FILTER(WHERE nivel_alerta!='RUPTURA' AND stock_total=0))::text,'=0','1_CRITICO' FROM mv_stock_rupture_alert
    UNION ALL SELECT 'C06_VELOCITY_FRESCA',CASE WHEN MAX(last_update_date)>=CURRENT_DATE-1 THEN 'OK' ELSE 'WARN' END,MAX(last_update_date)::text,'>=hoje-1d','3_MEDIO' FROM analytics.mv_stock_velocity
    UNION ALL SELECT 'C07_KPI_5_NIVEIS',CASE WHEN COUNT(*)=5 THEN 'OK' ELSE 'WARN' END,COUNT(*)::text,'=5','4_BAIXO' FROM mv_ema_kpi_by_level
    UNION ALL SELECT 'C08_CRONS_3_ATIVOS',CASE WHEN COUNT(*)=3 THEN 'OK' ELSE 'WARN' END,COUNT(*)::text,'=3','3_MEDIO' FROM cron.job WHERE jobname IN('refresh-analytics-mv-stock-velocity','refresh-mv-stock-rupture-alert','refresh-mv-ema-kpi-by-level') AND active=true
    UNION ALL SELECT 'C09_ZERO_GHOSTS',CASE WHEN COUNT(*)FILTER(WHERE nivel_alerta='CRÍTICO' AND score_composto=100.00)=0 THEN 'OK' ELSE 'WARN' END,COUNT(*)FILTER(WHERE nivel_alerta='CRÍTICO' AND score_composto=100.00)::text,'=0','4_BAIXO' FROM mv_stock_rupture_alert
    UNION ALL SELECT 'C10_LEADS_CONFIGURADOS',CASE WHEN COUNT(*)FILTER(WHERE delivery_time_days IS NULL AND active=true)=0 THEN 'OK' ELSE 'WARN' END,COUNT(*)FILTER(WHERE delivery_time_days IS NULL AND active=true)::text,'=0 ativos','3_MEDIO' FROM suppliers
    UNION ALL SELECT 'C11_SCORE_0_100',CASE WHEN MIN(score_composto)>=0 AND MAX(score_composto)<=100 THEN 'OK' ELSE 'ERRO' END,MIN(score_composto)||'..'||MAX(score_composto),'[0,100]','1_CRITICO' FROM mv_stock_rupture_alert
  ) t(cn,st,va,th,sv) ORDER BY t.sv,t.cn;
END;
$$;


ALTER FUNCTION "public"."fn_rupture_health_check"() OWNER TO "postgres";


