CREATE OR REPLACE FUNCTION "public"."fn_safe_bool"("p" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v text;
BEGIN
  IF p IS NULL OR TRIM(p)='' THEN RETURN NULL; END IF;
  v := lower(unaccent(TRIM(p)));
  IF v IN ('sim','s','true','t','1','yes','y','ativo','active') THEN RETURN TRUE; END IF;
  IF v IN ('nao','n','false','f','0','no','inativo','inactive') THEN RETURN FALSE; END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  v := lower(TRIM(p));
  IF v IN ('sim','s','true','t','1','yes','y','ativo','active') THEN RETURN TRUE; END IF;
  IF v IN ('nao','não','n','false','f','0','no','inativo','inactive') THEN RETURN FALSE; END IF;
  RETURN NULL;
END; $$;


ALTER FUNCTION "public"."fn_safe_bool"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_safe_int"("p" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE v numeric;
BEGIN
  IF p IS NULL OR TRIM(p)='' THEN RETURN NULL; END IF;
  v := replace(TRIM(p), ',', '.')::numeric;
  RETURN trunc(v)::integer;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_safe_int"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_safe_jsonb_arr"("p_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  j jsonb;
BEGIN
  IF p_value IS NULL OR btrim(p_value) = '' THEN RETURN NULL; END IF;
  BEGIN
    j := p_value::jsonb;
    IF jsonb_typeof(j) = 'array' THEN
      RETURN CASE WHEN jsonb_array_length(j) > 0 THEN j ELSE NULL END;
    ELSIF jsonb_typeof(j) = 'object' THEN
      SELECT NULLIF(jsonb_agg(v), '[]'::jsonb) INTO j FROM jsonb_each_text(j) e(k, v) WHERE NULLIF(btrim(v),'') IS NOT NULL;
      RETURN j;
    ELSIF jsonb_typeof(j) = 'string' THEN
      RETURN jsonb_build_array(j #>> '{}');
    END IF;
    RETURN NULL;
  EXCEPTION WHEN OTHERS THEN
    RETURN (
      SELECT NULLIF(COALESCE(jsonb_agg(btrim(e)), '[]'::jsonb), '[]'::jsonb)
      FROM unnest(string_to_array(p_value, CASE WHEN position('|' in p_value) > 0 THEN '|' ELSE ',' END)) e
      WHERE btrim(e) <> ''
    );
  END;
END;
$$;


ALTER FUNCTION "public"."fn_safe_jsonb_arr"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_safe_num"("p" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p IS NULL OR TRIM(p)='' THEN RETURN NULL; END IF;
  RETURN replace(TRIM(p), ',', '.')::numeric;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_safe_num"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_safe_text_arr"("p_value" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN public.fn_safe_jsonb_arr(p_value) IS NULL THEN NULL
    ELSE (SELECT array_agg(e #>> '{}') FROM jsonb_array_elements(public.fn_safe_jsonb_arr(p_value)) e)
  END;
$$;


