CREATE OR REPLACE FUNCTION "public"."fn_sanitize_product_image_urls"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Sanitizar url_original (CDN do fornecedor)
  NEW.url_original := fn_sanitize_url(NEW.url_original);

  -- Sanitizar url_cdn (CF Images) — só aplicar trim e controles
  IF NEW.url_cdn IS NOT NULL THEN
    NEW.url_cdn := TRIM(NEW.url_cdn);
    NEW.url_cdn := REPLACE(NEW.url_cdn, CHR(13), '');
    NEW.url_cdn := REPLACE(NEW.url_cdn, CHR(10), '');
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sanitize_product_image_urls"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sanitize_product_image_urls"() IS 'Trigger BEFORE INSERT/UPDATE: sanitiza url_original e url_cdn em product_images.';



CREATE OR REPLACE FUNCTION "public"."fn_sanitize_text"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT NULLIF(btrim(regexp_replace(
           translate(p, chr(160)||chr(8203)||chr(8204)||chr(8205)||chr(65279), ' '),
           '\s+',' ','g')), '');
$$;


ALTER FUNCTION "public"."fn_sanitize_text"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sanitize_url"("p_url" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_url TEXT := p_url;
BEGIN
  IF v_url IS NULL THEN RETURN NULL; END IF;

  -- Trim espaços externos
  v_url := TRIM(v_url);

  -- Remover caracteres de controle embutidos (CR, LF, TAB)
  v_url := REPLACE(v_url, CHR(13), '');
  v_url := REPLACE(v_url, CHR(10), '');
  v_url := REPLACE(v_url, CHR(9),  '');

  -- Corrigir https:/ (1 slash) → https://
  -- Usando REGEXP_REPLACE para precisão: ^https:/(?!/)
  v_url := REGEXP_REPLACE(v_url, '^https:/([^/])', 'https://\1');

  -- Corrigir http:/ (1 slash) → http://
  v_url := REGEXP_REPLACE(v_url, '^http:/([^/])', 'http://\1');

  -- Se ficou vazio após trim, retornar NULL
  IF v_url = '' THEN RETURN NULL; END IF;

  RETURN v_url;
END;
$$;


ALTER FUNCTION "public"."fn_sanitize_url"("p_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sanitize_url"("p_url" "text") IS 'Normaliza URLs: corrige https:/(1slash), http:/(1slash), remove CR/LF/TAB embutidos, trim.';



CREATE OR REPLACE FUNCTION "public"."fn_save_ai_enrichment_results"("p_queue_id" "uuid", "p_product_id" "uuid", "p_ai_title" "text" DEFAULT NULL::"text", "p_ai_description" "text" DEFAULT NULL::"text", "p_ai_summary" "text" DEFAULT NULL::"text", "p_schema_json" "jsonb" DEFAULT NULL::"jsonb", "p_ai_model" "text" DEFAULT 'deepseek-chat'::"text", "p_success" boolean DEFAULT true, "p_error" "text" DEFAULT NULL::"text", "p_prompt_tokens" integer DEFAULT 0, "p_completion_tokens" integer DEFAULT 0, "p_generation_ms" integer DEFAULT 0, "p_context_snapshot" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_updated       INTEGER := 0;
    v_new_version   INTEGER;
    v_locked        TEXT[];
    v_cur_version   INTEGER;
BEGIN
    IF p_success THEN
        -- Obter locked_fields e ai_version atuais
        SELECT
            COALESCE(locked_fields, '{}'),
            COALESCE(ai_version, 0)
        INTO v_locked, v_cur_version
        FROM products WHERE id = p_product_id;

        v_new_version := v_cur_version + 1;

        -- ─────────────────────────────────────────────────────
        -- Atualizar produto Gold
        -- ─────────────────────────────────────────────────────
        UPDATE products
        SET
            ai_title = CASE
                WHEN 'ai_title' = ANY(v_locked) AND v_cur_version > 0
                THEN ai_title
                ELSE COALESCE(NULLIF(TRIM(p_ai_title), ''), ai_title)
            END,
            ai_description = CASE
                WHEN 'ai_description' = ANY(v_locked) AND v_cur_version > 0
                THEN ai_description
                ELSE COALESCE(NULLIF(TRIM(p_ai_description), ''), ai_description)
            END,
            -- ai_summary e schema_json: sempre atualiza (não editados manualmente)
            ai_summary   = COALESCE(NULLIF(TRIM(p_ai_summary), ''), ai_summary),
            schema_json  = COALESCE(p_schema_json, schema_json),
            ai_version   = v_new_version,
            ai_generated_at = now(),
            ai_model     = p_ai_model,
            updated_at   = now()
        WHERE id = p_product_id;

        GET DIAGNOSTICS v_updated = ROW_COUNT;

        -- ─────────────────────────────────────────────────────
        -- Registrar no histórico
        -- ─────────────────────────────────────────────────────
        INSERT INTO product_ai_history (
            product_id, version, ai_title, ai_description,
            model, prompt_tokens, completion_tokens, total_tokens,
            generation_time_ms, context_snapshot, generated_at
        )
        VALUES (
            p_product_id,
            v_new_version,
            p_ai_title,
            p_ai_description,
            p_ai_model,
            COALESCE(p_prompt_tokens, 0),
            COALESCE(p_completion_tokens, 0),
            COALESCE(p_prompt_tokens, 0) + COALESCE(p_completion_tokens, 0),
            COALESCE(p_generation_ms, 0),
            COALESCE(p_context_snapshot, jsonb_build_object(
                'model', p_ai_model, 'generated_at', now()
            )),
            now()
        )
        ON CONFLICT DO NOTHING;

        -- ─────────────────────────────────────────────────────
        -- Marcar fila como done
        -- ─────────────────────────────────────────────────────
        UPDATE ai_enrichment_queue
        SET
            status       = 'done',
            completed_at = now(),
            updated_at   = now()
        WHERE id = p_queue_id;

    ELSE
        -- Registrar erro ou re-queue para retry
        UPDATE ai_enrichment_queue
        SET
            status     = CASE
                           WHEN attempts >= max_attempts THEN 'error'
                           ELSE 'pending'
                         END,
            last_error = p_error,
            updated_at = now()
        WHERE id = p_queue_id;

        v_updated := 0;
    END IF;

    RETURN jsonb_build_object(
        'success',     p_success,
        'updated',     v_updated,
        'new_version', v_new_version,
        'queue_id',    p_queue_id,
        'product_id',  p_product_id
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'state', SQLSTATE);
END;
$$;


ALTER FUNCTION "public"."fn_save_ai_enrichment_results"("p_queue_id" "uuid", "p_product_id" "uuid", "p_ai_title" "text", "p_ai_description" "text", "p_ai_summary" "text", "p_schema_json" "jsonb", "p_ai_model" "text", "p_success" boolean, "p_error" "text", "p_prompt_tokens" integer, "p_completion_tokens" integer, "p_generation_ms" integer, "p_context_snapshot" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_save_ai_enrichment_results"("p_queue_id" "uuid", "p_product_id" "uuid", "p_ai_title" "text", "p_ai_description" "text", "p_ai_summary" "text", "p_schema_json" "jsonb", "p_ai_model" "text", "p_success" boolean, "p_error" "text", "p_prompt_tokens" integer, "p_completion_tokens" integer, "p_generation_ms" integer, "p_context_snapshot" "jsonb") IS 'v2 — Salva ai_title, ai_description (copywriting B2B), ai_summary (GEO), schema_json.
     Registra em product_ai_history com tokens/tempo.
     locked_fields protege ai_title/ai_description de edições manuais (ai_version>0).
     ai_summary e schema_json: sempre atualizados.';



CREATE OR REPLACE FUNCTION "public"."fn_save_quote_draft"("p_data" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE v_draft_id UUID;
BEGIN
    INSERT INTO public.quote_drafts (user_id, data, last_saved_at)
    VALUES (auth.uid(), p_data, now())
    ON CONFLICT (user_id) DO UPDATE SET data = EXCLUDED.data, last_saved_at = now()
    RETURNING id INTO v_draft_id;
    RETURN v_draft_id;
END;
$$;


