CREATE OR REPLACE FUNCTION "public"."fn_set_category_min_quantity"("p_category_slug" character varying, "p_min_quantity" integer) RETURNS TABLE("category_id" "uuid", "category_name" character varying, "old_min" integer, "new_min" integer, "products_affected" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_category_id UUID;
    v_category_name VARCHAR;
    v_old_min INTEGER;
    v_affected INTEGER;
BEGIN
    -- Buscar categoria pelo slug
    SELECT c.id, c.name, c.min_order_quantity 
    INTO v_category_id, v_category_name, v_old_min
    FROM categories c
    WHERE c.slug = p_category_slug;
    
    IF v_category_id IS NULL THEN
        RAISE EXCEPTION 'Categoria com slug "%" não encontrada', p_category_slug;
    END IF;
    
    -- Atualizar categoria (trigger propagará para produtos)
    UPDATE categories
    SET min_order_quantity = p_min_quantity
    WHERE id = v_category_id;
    
    -- Contar produtos afetados (qualificando a coluna)
    SELECT COUNT(*) INTO v_affected
    FROM products p
    WHERE p.category_id = v_category_id
      AND p.min_order_quantity IS NULL;
    
    RETURN QUERY SELECT v_category_id, v_category_name, v_old_min, p_min_quantity, v_affected;
END;
$$;


ALTER FUNCTION "public"."fn_set_category_min_quantity"("p_category_slug" character varying, "p_min_quantity" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_set_category_min_quantity"("p_category_slug" character varying, "p_min_quantity" integer) IS 'Configura a quantidade mínima de uma categoria pelo slug.
Exemplo: SELECT * FROM fn_set_category_min_quantity(''canetas'', 50);
Retorna: categoria atualizada e quantidade de produtos afetados.';



CREATE OR REPLACE FUNCTION "public"."fn_set_markup"("p_nivel" "text", "p_id" "uuid", "p_markup" numeric, "p_descricao" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_existing_id uuid;
    v_result      jsonb;
BEGIN
    -- Validar nível
    IF p_nivel NOT IN ('supplier','category','product') THEN
        RETURN jsonb_build_object('success', false,
            'error', 'nivel_invalido',
            'dica',  'Use: supplier | category | product');
    END IF;

    IF p_markup < 0 OR p_markup > 10000 THEN
        RETURN jsonb_build_object('success', false,
            'error', 'markup_fora_do_intervalo',
            'dica',  'Informe markup entre 0 e 10000 (ex: 115 = 115%)');
    END IF;

    -- Verificar se já existe regra para esse alvo
    SELECT id INTO v_existing_id
    FROM markup_configurations
    WHERE is_active = true
      AND CASE p_nivel
            WHEN 'supplier' THEN supplier_id = p_id AND category_id IS NULL AND product_id IS NULL
            WHEN 'category' THEN category_id = p_id AND product_id IS NULL
            WHEN 'product'  THEN product_id  = p_id
          END
    LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
        -- Atualizar existente
        UPDATE markup_configurations
        SET markup_percent = p_markup,
            description    = COALESCE(p_descricao, description),
            updated_at     = now()
        WHERE id = v_existing_id;

        v_result := jsonb_build_object(
            'success', true, 'operacao', 'UPDATE',
            'nivel', p_nivel, 'id_alvo', p_id,
            'markup_percent', p_markup
        );
    ELSE
        -- Inserir nova regra
        INSERT INTO markup_configurations
            (supplier_id, category_id, product_id, markup_percent, description, is_active)
        VALUES (
            CASE WHEN p_nivel = 'supplier' THEN p_id ELSE NULL END,
            CASE WHEN p_nivel = 'category' THEN p_id ELSE NULL END,
            CASE WHEN p_nivel = 'product'  THEN p_id ELSE NULL END,
            p_markup,
            COALESCE(p_descricao, p_nivel || ' markup ' || p_markup || '%'),
            true
        );

        v_result := jsonb_build_object(
            'success', true, 'operacao', 'INSERT',
            'nivel', p_nivel, 'id_alvo', p_id,
            'markup_percent', p_markup
        );
    END IF;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_set_markup"("p_nivel" "text", "p_id" "uuid", "p_markup" numeric, "p_descricao" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_set_markup"("p_nivel" "text", "p_id" "uuid", "p_markup" numeric, "p_descricao" "text") IS 'Configura markup (%) por nível: supplier | category | product.
Cria nova regra ou atualiza existente.
Exemplos:
  SELECT fn_set_markup(''supplier'', ''uuid-xbz'',     120.0, ''XBZ ajuste março'');
  SELECT fn_set_markup(''category'', ''uuid-bolsas'',  130.0, ''Bolsas premium'');
  SELECT fn_set_markup(''product'',  ''uuid-produto'', 140.0, ''Produto especial'');';



CREATE OR REPLACE FUNCTION "public"."fn_set_product_as_new"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.is_new IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.novelty_detected_at IS NULL THEN
      NEW.novelty_detected_at := NOW();
    END IF;
    IF NEW.novelty_expires_at IS NULL THEN
      NEW.novelty_expires_at := NEW.novelty_detected_at + INTERVAL '30 days';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    DECLARE
      was_new BOOLEAN := COALESCE(OLD.is_new, FALSE);
      already_active BOOLEAN := (
        NEW.novelty_expires_at IS NOT NULL AND
        NEW.novelty_expires_at > NOW()
      );
    BEGIN
      IF (was_new = FALSE OR NOT already_active) THEN
        NEW.novelty_detected_at := NOW();
        NEW.novelty_expires_at  := NOW() + INTERVAL '30 days';
      END IF;
      RETURN NEW;
    END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_set_product_as_new"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_set_product_as_new"() IS 'Preenche novelty_detected_at e novelty_expires_at quando is_new=true é definido/reativado. Dispara em INSERT e UPDATE(is_new). Idempotente: preserva expiração futura existente.';



