CREATE OR REPLACE FUNCTION "public"."fn_simular_combo_gravacao_kit_v1"("aplicacoes" "jsonb") RETURNS TABLE("app_ordem" integer, "kit_product_id" "uuid", "kit_component_id" "uuid", "componente_nome" "text", "tecnica_codigo" "text", "tabela_codigo" "text", "arte" "text", "cores" "text", "qty" integer, "location_code" "text", "largura_cm" numeric, "altura_cm" numeric, "preco_unit_faixa" numeric, "custo_natural" numeric, "piso_setup" numeric, "custo_final" numeric, "preco_unit_efetivo" numeric, "regra_ativada" "text", "motivo_erro" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH input AS (
    SELECT 
      ord::int AS app_ord,
      ((app->>'kit_product_id')::uuid) AS kit_prod_id,
      ((app->>'kit_component_id')::uuid) AS kit_comp_id,
      UPPER(COALESCE(app->>'location_code', 'LADO-A')) AS lado,
      (app->>'tecnica_codigo')::text AS tec_cod,
      COALESCE((app->>'largura')::numeric, COALESCE((app->>'largura_cm')::numeric, 0)) AS l,
      COALESCE((app->>'altura')::numeric, COALESCE((app->>'altura_cm')::numeric, 0)) AS a,
      COALESCE((app->>'cores')::int, 1) AS c,
      (app->>'qty')::int AS q,
      COALESCE(app->>'arte', '-') AS arte_t
    FROM jsonb_array_elements(aplicacoes) WITH ORDINALITY arr(app, ord)
  ),
  diag AS (
    SELECT 
      i.*,
      pkc.component_name AS comp_nome,
      kcpa.id AS print_area_id, kcpa.max_width, kcpa.max_height,
      t.id AS tab_id, t.codigo_tabela AS tab_cod,
      t.custo_setup, t.custo_setup_por_cor, t.markup_percent,
      t.cobra_por_cor, t.max_cores, t.ativo, t.usa_faixa_dimensional,
      f.preco_unitario, f.id AS faixa_id,
      CASE
        WHEN i.q IS NULL OR i.q <= 0 THEN 'ERRO_QTY_INVALIDA'
        WHEN i.c IS NULL OR i.c <= 0 THEN 'ERRO_CORES_INVALIDA'
        WHEN pkc.id IS NULL THEN 'ERRO_KIT_COMPONENT_INEXISTENTE'
        WHEN t.id IS NULL THEN 'ERRO_TECNICA_INEXISTENTE'
        WHEN NOT t.ativo THEN 'ERRO_TECNICA_INATIVA'
        WHEN i.c > t.max_cores THEN 'ERRO_CORES_EXCEDE_MAX'
        WHEN kcpa.id IS NULL THEN 'ERRO_KIT_COMPONENT_NAO_ACEITA_TECNICA'
        -- NOVO: rejeitar dimensões inválidas explícitas (não permitir l=0 ou negativo se a tabela usa faixa dimensional)
        WHEN t.usa_faixa_dimensional AND (i.l IS NULL OR i.l <= 0) THEN 'ERRO_LARGURA_INVALIDA'
        WHEN t.usa_faixa_dimensional AND (i.a IS NULL OR i.a <= 0) THEN 'ERRO_ALTURA_INVALIDA'
        WHEN i.l > kcpa.max_width::numeric THEN 'ERRO_LARGURA_EXCEDE_AREA'
        WHEN i.a > kcpa.max_height::numeric THEN 'ERRO_ALTURA_EXCEDE_AREA'
        WHEN f.id IS NULL THEN 'ERRO_FAIXA_NAO_ENCONTRADA'
        ELSE NULL
      END AS motivo
    FROM input i
    LEFT JOIN product_kit_components pkc ON pkc.id = i.kit_comp_id
    LEFT JOIN tabela_preco_gravacao_oficial t ON t.codigo_tabela = i.tec_cod
    LEFT JOIN kit_component_print_areas kcpa ON kcpa.kit_component_id = i.kit_comp_id
      AND kcpa.tabela_preco_id = t.id
      AND kcpa.location_code = i.lado
      AND kcpa.is_active = true
    LEFT JOIN tabela_preco_gravacao_oficial_faixa f ON f.tabela_preco_gravacao_id = t.id
      AND i.q BETWEEN f.quantidade_minima AND COALESCE(f.quantidade_maxima, 999999999)
      AND (
        t.usa_faixa_dimensional = false 
        OR (
          (f.largura_min IS NULL OR i.l BETWEEN f.largura_min::numeric AND f.largura_max::numeric)
          AND (f.altura_min IS NULL OR i.a BETWEEN f.altura_min::numeric AND f.altura_max::numeric)
        )
      )
  ),
  calc AS (
    SELECT 
      d.*,
      CASE WHEN d.custo_setup_por_cor THEN d.custo_setup * d.c ELSE d.custo_setup END AS piso_setup_v,
      (d.q * d.preco_unitario) AS natural_v
    FROM diag d
    WHERE d.motivo IS NULL
  ),
  resultado AS (
    SELECT 
      d.app_ord, d.kit_prod_id, d.kit_comp_id, d.comp_nome, d.tec_cod, d.tab_cod,
      d.arte_t, d.c::text || ' cor' AS cores_t, d.q, d.lado, d.l, d.a,
      d.preco_unitario,
      ROUND(c.natural_v::numeric, 2) AS custo_nat,
      d.custo_setup AS piso,
      ROUND(GREATEST(c.natural_v::numeric, c.piso_setup_v::numeric), 2) AS custo_fin,
      ROUND((GREATEST(c.natural_v::numeric, c.piso_setup_v::numeric) / d.q)::numeric, 4) AS preco_efet,
      CASE 
        WHEN d.motivo IS NOT NULL THEN d.motivo
        WHEN c.natural_v >= c.piso_setup_v THEN 'NATURAL_ACEITO'
        ELSE 'PISO_SETUP_APLICADO'
      END AS regra,
      d.motivo
    FROM diag d
    LEFT JOIN calc c ON c.app_ord = d.app_ord
  )
  SELECT 
    app_ord, kit_prod_id, kit_comp_id, comp_nome, tec_cod, tab_cod,
    arte_t, cores_t, q, lado, l, a,
    preco_unitario, custo_nat, piso, custo_fin, preco_efet, regra, motivo
  FROM resultado
  ORDER BY app_ord;
$$;


ALTER FUNCTION "public"."fn_simular_combo_gravacao_kit_v1"("aplicacoes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_simular_combo_gravacao_kit_v1"("aplicacoes" "jsonb") IS 'GAP #3 + correção pós-blindagem (auditoria 2026-04-29):
   - Calcula gravação de kits via kit_component_print_areas
   - Aplica UNIF-01: setup como piso, MAX(piso, qty*preco)
   - REJEITA dimensão <=0 quando tabela usa faixa dimensional (ERRO_LARGURA_INVALIDA / ERRO_ALTURA_INVALIDA)
   - Suporta qty até 999.999.999 (GAP #5)';



CREATE OR REPLACE FUNCTION "public"."fn_simular_combo_gravacao_v10"("aplicacoes" "jsonb") RETURNS TABLE("app_ordem" integer, "product_id" "uuid", "tecnica_codigo" "text", "arte" "text", "cores" "text", "qty" integer, "location_code" "text", "custo_natural" numeric, "piso_comercial_aplicado" numeric, "custo_final" numeric, "regra_ativada" "text", "venda_aplicacao" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH input AS (
    SELECT 
      ord::int AS app_ord,
      ((app->>'product_id')::uuid) AS prod_id,
      (app->>'tecnica_codigo')::text AS tec_cod,
      COALESCE((app->>'largura')::numeric, 0) AS l,
      COALESCE((app->>'altura')::numeric, 0) AS a,
      COALESCE((app->>'cores')::int, 1) AS c,
      (app->>'qty')::int AS q,
      UPPER(COALESCE(app->>'location_code', app->>'lado', 'LADO-A')) AS lado
    FROM jsonb_array_elements(aplicacoes) WITH ORDINALITY arr(app, ord)
  ),
  apps_enriched AS (
    SELECT 
      i.app_ord, i.lado, i.tec_cod, i.l, i.a, i.c, i.q, i.prod_id,
      t.id AS tab_id, t.grupo_tecnica,
      (pat.id IS NOT NULL) AS produto_aceita_tecnica,
      pat.max_width, pat.max_height,
      CASE 
        WHEN pat.id IS NULL THEN false
        WHEN i.l = 0 OR i.a = 0 THEN true
        ELSE (i.l <= pat.max_width AND i.a <= pat.max_height)
      END AS dimensao_valida,
      (pat.id IS NOT NULL) AS lado_valido,
      (
        SELECT COUNT(DISTINCT location_code) > 1
        FROM print_area_techniques pat2
        WHERE pat2.product_id = i.prod_id 
          AND pat2.tabela_preco_id = t.id
          AND pat2.is_active = true
      ) AS aceita_multi_lado
    FROM input i
    JOIN tabela_preco_gravacao_oficial t ON t.codigo_tabela = i.tec_cod
    LEFT JOIN print_area_techniques pat 
      ON pat.product_id = i.prod_id 
      AND pat.tabela_preco_id = t.id 
      AND pat.location_code = i.lado
      AND pat.is_active = true
  ),
  validacao AS (
    SELECT 
      EXISTS(SELECT 1 FROM apps_enriched WHERE grupo_tecnica = 'SUBLIMACAO') AS tem_subl,
      EXISTS(SELECT 1 FROM apps_enriched WHERE grupo_tecnica IN ('SERIGRAFIA','TRANSFER_DIGITAL')) AS tem_outro_grupo,
      (SELECT COUNT(*) FROM apps_enriched WHERE grupo_tecnica = 'SUBLIMACAO') AS n_apps_subl,
      EXISTS(SELECT 1 FROM apps_enriched WHERE grupo_tecnica = 'SUBLIMACAO' AND aceita_multi_lado = false) AS tem_subl_exclusiva_abs,
      (SELECT COUNT(DISTINCT lado) FROM apps_enriched 
         WHERE grupo_tecnica = 'SUBLIMACAO' AND aceita_multi_lado = true) AS n_lados_subl_multi,
      (SELECT COUNT(*) FROM apps_enriched 
         WHERE grupo_tecnica = 'SUBLIMACAO' AND aceita_multi_lado = true) AS n_apps_subl_multi,
      NOT EXISTS(SELECT 1 FROM apps_enriched WHERE produto_aceita_tecnica = false) AS todos_produtos_aceitam,
      NOT EXISTS(SELECT 1 FROM apps_enriched WHERE lado_valido = false) AS todos_lados_validos,
      NOT EXISTS(SELECT 1 FROM apps_enriched WHERE dimensao_valida = false) AS todas_dimensoes_validas
  ),
  combo_valido AS (
    SELECT CASE
      WHEN NOT v.todos_produtos_aceitam THEN false
      WHEN NOT v.todos_lados_validos THEN false
      WHEN NOT v.todas_dimensoes_validas THEN false
      WHEN v.tem_subl AND v.tem_outro_grupo THEN false
      WHEN v.tem_subl_exclusiva_abs AND v.n_apps_subl > 1 THEN false
      WHEN v.n_apps_subl_multi > 4 THEN false
      WHEN v.n_apps_subl_multi > v.n_lados_subl_multi THEN false
      ELSE true
    END AS ok
    FROM validacao v
  ),
  resolved AS (
    SELECT 
      i.app_ord, i.tec_cod, i.l, i.a, i.c, i.q, i.lado, i.prod_id,
      t.id AS tab_id, t.grupo_tecnica,
      t.custo_setup, t.custo_setup_por_cor,
      t.custo_aplicacao, t.markup_percent, t.max_cores,
      f.preco_unitario, f.ordem AS faixa_ordem,
      COALESCE(
        (t.opcoes_modificadores->'multiplicador_cor'->>i.c::text)::numeric,
        1.0
      ) AS mult_cor,
      -- v10 NOVA: setup_total agora é o PISO COMERCIAL (unificado em UNIF-01 25/04/2026)
      CASE WHEN t.custo_setup_por_cor THEN t.custo_setup * i.c
           ELSE t.custo_setup END AS setup_total,
      COALESCE((t.opcoes_modificadores->>'adicional_fotolito_por_cor')::numeric, 0) AS foto_a3
    FROM input i
    JOIN tabela_preco_gravacao_oficial t ON t.codigo_tabela = i.tec_cod
    JOIN tabela_preco_gravacao_oficial_faixa f ON f.tabela_preco_gravacao_id = t.id
    JOIN combo_valido cv ON cv.ok = true
    WHERE t.ativo = true
      AND i.q BETWEEN f.quantidade_minima AND COALESCE(f.quantidade_maxima, 2147483647)
      AND i.c BETWEEN 1 AND t.max_cores
      AND (
        t.usa_faixa_dimensional = false 
        OR (
          (f.largura_min IS NULL OR i.l = 0 OR i.l BETWEEN f.largura_min AND f.largura_max)
          AND (f.altura_min IS NULL OR i.a = 0 OR i.a BETWEEN f.altura_min AND f.altura_max)
        )
      )
  ),
  -- pico_anterior SEM setup
  pico_anterior AS (
    SELECT r.app_ord,
      MAX(
        CASE 
          WHEN r.grupo_tecnica = 'SERIGRAFIA' THEN
            fa.quantidade_maxima * fa.preco_unitario * r.mult_cor + r.foto_a3 * r.c
          WHEN r.grupo_tecnica = 'TAMPOGRAFIA' THEN
            fa.quantidade_maxima * fa.preco_unitario * r.mult_cor
          WHEN r.grupo_tecnica = 'SUBLIMACAO' THEN
            fa.quantidade_maxima * (fa.preco_unitario + r.custo_aplicacao)
          WHEN r.grupo_tecnica IN ('LASER','LASER_CO2','UV_DIGITAL') THEN
            fa.quantidade_maxima * fa.preco_unitario
          WHEN r.grupo_tecnica = 'BORDADO' THEN
            fa.quantidade_maxima * fa.preco_unitario
          ELSE 0
        END
      ) AS pico
    FROM resolved r
    JOIN tabela_preco_gravacao_oficial_faixa fa
      ON fa.tabela_preco_gravacao_id = r.tab_id
      AND fa.quantidade_maxima IS NOT NULL
      AND fa.quantidade_maxima < r.q
    GROUP BY r.app_ord
  ),
  calc AS (
    SELECT 
      r.*, COALESCE(pa.pico, 0) AS pico_anterior_v,
      -- v10 NOVA: nat = GRAVACAO PURA (sem setup somado)
      CASE 
        WHEN r.grupo_tecnica = 'SERIGRAFIA' THEN
          r.q * r.preco_unitario * r.mult_cor + r.foto_a3 * r.c
        WHEN r.grupo_tecnica = 'TAMPOGRAFIA' THEN
          r.q * r.preco_unitario * r.mult_cor
        WHEN r.grupo_tecnica = 'TRANSFER_DIGITAL' THEN
          r.q * ((r.l * r.a / 10000.0) * r.preco_unitario + r.custo_aplicacao)
        WHEN r.grupo_tecnica = 'SUBLIMACAO' THEN
          r.q * (r.preco_unitario + r.custo_aplicacao)
        WHEN r.grupo_tecnica IN ('LASER','LASER_CO2','UV_DIGITAL') THEN
          r.q * r.preco_unitario
        WHEN r.grupo_tecnica = 'BORDADO' THEN
          r.q * r.preco_unitario
        ELSE 0
      END AS nat
    FROM resolved r
    LEFT JOIN pico_anterior pa ON pa.app_ord = r.app_ord
  )
  SELECT 
    app_ord AS app_ordem,
    prod_id AS product_id,
    tec_cod AS tecnica_codigo,
    CASE WHEN l > 0 AND a > 0 THEN l || 'x' || a || ' cm' ELSE '-' END AS arte,
    CASE WHEN grupo_tecnica IN ('SERIGRAFIA','TAMPOGRAFIA') THEN c::text || ' cor'
         ELSE 'full color' END AS cores,
    q AS qty,
    lado AS location_code,
    ROUND(nat::numeric, 2) AS custo_natural,
    ROUND(setup_total::numeric, 2) AS piso_comercial_aplicado,
    ROUND(GREATEST(nat, pico_anterior_v, setup_total)::numeric, 2) AS custo_final,
    CASE 
      WHEN GREATEST(nat, pico_anterior_v) < setup_total THEN 'PISO_SETUP'
      WHEN pico_anterior_v > nat THEN 'ANTI_PARADOXO'
      ELSE 'natural'
    END AS regra_ativada,
    ROUND(
      (GREATEST(nat, pico_anterior_v, setup_total) * (1 + markup_percent/100))::numeric, 2
    ) AS venda_aplicacao
  FROM calc
  ORDER BY app_ord;
$$;


ALTER FUNCTION "public"."fn_simular_combo_gravacao_v10"("aplicacoes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_simular_combo_gravacao_v10"("aplicacoes" "jsonb") IS 'Simulação de combo de gravação (v10). Padronizado em UNIF-01 (25/04/2026). Aceita campos location_code OU lado (alias retrocompat) — propagado em 2026-04-25.';



CREATE OR REPLACE FUNCTION "public"."fn_simular_combo_gravacao_v11"("aplicacoes" "jsonb") RETURNS TABLE("app_ordem" integer, "product_id" "uuid", "tecnica_codigo" "text", "arte" "text", "cores" "text", "qty" integer, "location_code" "text", "custo_natural" numeric, "piso_comercial_aplicado" numeric, "custo_final" numeric, "regra_ativada" "text", "venda_aplicacao" numeric, "motivo_erro" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
WITH input AS (
  SELECT
    ord::int AS app_ord,
    ((app->>'product_id')::uuid) AS prod_id,
    (app->>'tecnica_codigo')::text AS tec_cod,
    COALESCE((app->>'largura')::numeric, 0) AS l,
    COALESCE((app->>'altura')::numeric, 0) AS a,
    COALESCE((app->>'cores')::int, 1) AS c,
    (app->>'qty')::int AS q,
    UPPER(COALESCE(app->>'location_code', app->>'lado', 'LADO-A')) AS lado,
    COALESCE(app->>'arte_id', 'AUTO_' || ord::text) AS arte_id
  FROM jsonb_array_elements(aplicacoes) WITH ORDINALITY arr(app, ord)
),
diag AS (
  SELECT
    i.*,
    t.id AS tab_id, t.grupo_tecnica, t.ativo, t.max_cores,
    pat.id AS pat_id, pat.max_width, pat.max_height,
    CASE
      WHEN i.q IS NULL OR i.q <= 0 THEN 'ERRO_QTY_INVALIDA'
      WHEN i.c IS NULL OR i.c <= 0 THEN 'ERRO_CORES_INVALIDA'
      WHEN t.id IS NULL THEN 'ERRO_TECNICA_INEXISTENTE'
      WHEN NOT t.ativo THEN 'ERRO_TECNICA_INATIVA'
      WHEN i.c > t.max_cores THEN 'ERRO_CORES_EXCEDE_MAX'
      WHEN pat.id IS NULL THEN 'ERRO_PRODUTO_NAO_ACEITA_TECNICA'
      WHEN i.l > 0 AND i.l > pat.max_width THEN 'ERRO_LARGURA_EXCEDE_AREA'
      WHEN i.a > 0 AND i.a > pat.max_height THEN 'ERRO_ALTURA_EXCEDE_AREA'
      ELSE NULL
    END AS motivo
  FROM input i
  LEFT JOIN tabela_preco_gravacao_oficial t ON t.codigo_tabela = i.tec_cod
  LEFT JOIN print_area_techniques pat ON pat.product_id = i.prod_id
    AND pat.tabela_preco_id = t.id AND pat.location_code = i.lado AND pat.is_active = true
),
combo_check AS (
  SELECT
    EXISTS(SELECT 1 FROM diag WHERE grupo_tecnica = 'SUBLIMACAO' AND motivo IS NULL) AS tem_subl,
    EXISTS(SELECT 1 FROM diag WHERE grupo_tecnica IN ('SERIGRAFIA','TRANSFER_DIGITAL','TAMPOGRAFIA','LASER','LASER_CO2','UV_DIGITAL','BORDADO') AND motivo IS NULL) AS tem_outro
),
diag_final AS (
  SELECT d.*,
    CASE
      WHEN d.motivo IS NOT NULL THEN d.motivo
      WHEN d.grupo_tecnica = 'SUBLIMACAO' AND cc.tem_outro THEN 'ERRO_SUBL_NAO_COMBINA_OUTRAS'
      ELSE NULL
    END AS motivo_final
  FROM diag d CROSS JOIN combo_check cc
),
resolved AS (
  SELECT
    d.app_ord, d.tec_cod, d.l, d.a, d.c, d.q, d.lado, d.prod_id, d.grupo_tecnica, d.arte_id,
    t.custo_setup, t.custo_setup_por_cor, t.custo_aplicacao, t.markup_percent,
    f.preco_unitario, f.ordem AS faixa_ordem, t.id AS tab_id,
    COALESCE((t.opcoes_modificadores->'multiplicador_cor'->>d.c::text)::numeric, 1.0) AS mult_cor,
    CASE WHEN t.custo_setup_por_cor THEN t.custo_setup * d.c ELSE t.custo_setup END AS setup_total,
    COALESCE((t.opcoes_modificadores->>'adicional_fotolito_por_cor')::numeric, 0) AS foto_a3
  FROM diag_final d
  JOIN tabela_preco_gravacao_oficial t ON t.id = d.tab_id
  JOIN tabela_preco_gravacao_oficial_faixa f ON f.tabela_preco_gravacao_id = t.id
    AND d.q BETWEEN f.quantidade_minima AND COALESCE(f.quantidade_maxima, 2147483647)
    AND (
      t.usa_faixa_dimensional = false
      OR (
        (f.largura_min IS NULL OR d.l = 0 OR d.l BETWEEN f.largura_min AND f.largura_max)
        AND (f.altura_min IS NULL OR d.a = 0 OR d.a BETWEEN f.altura_min AND f.altura_max)
      )
    )
  WHERE d.motivo_final IS NULL
),
arte_grupos AS (
  SELECT 
    arte_id, prod_id, tec_cod, c,
    MIN(app_ord) AS app_ord_lider,
    COUNT(*) AS qtd_aplicacoes_grupo
  FROM resolved
  GROUP BY arte_id, prod_id, tec_cod, c
),
pico_anterior AS (
  SELECT r.app_ord, MAX(
    CASE
      WHEN r.grupo_tecnica = 'SERIGRAFIA' THEN fa.quantidade_maxima * fa.preco_unitario * r.mult_cor + r.foto_a3 * r.c
      WHEN r.grupo_tecnica = 'TAMPOGRAFIA' THEN fa.quantidade_maxima * fa.preco_unitario * r.mult_cor
      WHEN r.grupo_tecnica = 'SUBLIMACAO' THEN fa.quantidade_maxima * (fa.preco_unitario + r.custo_aplicacao)
      -- FIX 2026-04-26: somar custo_aplicacao também em LASER/UV_DIGITAL/BORDADO/TRANSFER_DIGITAL
      WHEN r.grupo_tecnica IN ('LASER','LASER_CO2','UV_DIGITAL') THEN fa.quantidade_maxima * (fa.preco_unitario + r.custo_aplicacao)
      WHEN r.grupo_tecnica = 'BORDADO' THEN fa.quantidade_maxima * (fa.preco_unitario + r.custo_aplicacao)
      ELSE 0 END
  ) AS pico
  FROM resolved r
  JOIN tabela_preco_gravacao_oficial_faixa fa ON fa.tabela_preco_gravacao_id = r.tab_id
    AND fa.quantidade_maxima IS NOT NULL AND fa.quantidade_maxima < r.q
  GROUP BY r.app_ord
),
calc AS (
  SELECT
    r.app_ord, r.prod_id, r.tec_cod, r.l, r.a, r.c, r.q, r.lado,
    r.grupo_tecnica, r.markup_percent, r.arte_id,
    COALESCE(pa.pico, 0) AS pico_anterior_v,
    CASE 
      WHEN r.app_ord = ag.app_ord_lider THEN r.setup_total
      ELSE 0
    END AS piso_setup,
    ag.qtd_aplicacoes_grupo,
    ag.app_ord_lider,
    CASE
      WHEN r.grupo_tecnica = 'SERIGRAFIA' THEN r.q * r.preco_unitario * r.mult_cor + r.foto_a3 * r.c
      WHEN r.grupo_tecnica = 'TAMPOGRAFIA' THEN r.q * r.preco_unitario * r.mult_cor
      WHEN r.grupo_tecnica = 'TRANSFER_DIGITAL' THEN r.q * ((r.l * r.a / 10000.0) * r.preco_unitario + r.custo_aplicacao)
      WHEN r.grupo_tecnica = 'SUBLIMACAO' THEN r.q * (r.preco_unitario + r.custo_aplicacao)
      -- FIX 2026-04-26: somar custo_aplicacao também em LASER/UV_DIGITAL/BORDADO
      WHEN r.grupo_tecnica IN ('LASER','LASER_CO2','UV_DIGITAL') THEN r.q * (r.preco_unitario + r.custo_aplicacao)
      WHEN r.grupo_tecnica = 'BORDADO' THEN r.q * (r.preco_unitario + r.custo_aplicacao)
      ELSE 0 END AS nat
  FROM resolved r 
  LEFT JOIN pico_anterior pa ON pa.app_ord = r.app_ord
  LEFT JOIN arte_grupos ag ON ag.arte_id = r.arte_id 
    AND ag.prod_id = r.prod_id 
    AND ag.tec_cod = r.tec_cod 
    AND ag.c = r.c
),
saida AS (
  SELECT df.app_ord AS app_ordem, df.prod_id AS product_id, df.tec_cod AS tecnica_codigo,
    CASE WHEN df.l > 0 AND df.a > 0 THEN df.l || 'x' || df.a || ' cm' ELSE '-' END AS arte,
    df.c::text || ' cor' AS cores, df.q AS qty, df.lado AS location_code,
    NULL::numeric AS custo_natural, NULL::numeric AS piso_comercial_aplicado, NULL::numeric AS custo_final,
    df.motivo_final AS regra_ativada, NULL::numeric AS venda_aplicacao,
    df.motivo_final AS motivo_erro
  FROM diag_final df
  WHERE df.motivo_final IS NOT NULL

  UNION ALL

  SELECT app_ord, prod_id, tec_cod,
    CASE WHEN l > 0 AND a > 0 THEN l || 'x' || a || ' cm' ELSE '-' END,
    CASE WHEN grupo_tecnica IN ('SERIGRAFIA','TAMPOGRAFIA') THEN c::text || ' cor' ELSE 'full color' END,
    q, lado,
    ROUND(nat::numeric, 2),
    ROUND(piso_setup::numeric, 2),
    ROUND(GREATEST(nat, pico_anterior_v, piso_setup)::numeric, 2),
    CASE
      WHEN qtd_aplicacoes_grupo > 1 AND app_ord = app_ord_lider THEN 
        CASE
          WHEN GREATEST(nat, pico_anterior_v) < piso_setup THEN 'PISO_SETUP_LIDER_GRUPO'
          WHEN pico_anterior_v > nat THEN 'ANTI_PARADOXO_LIDER_GRUPO'
          ELSE 'natural_lider_grupo'
        END
      WHEN qtd_aplicacoes_grupo > 1 AND app_ord != app_ord_lider THEN 
        CASE
          WHEN pico_anterior_v > nat THEN 'ANTI_PARADOXO_MEMBRO_GRUPO'
          ELSE 'natural_membro_grupo'
        END
      WHEN GREATEST(nat, pico_anterior_v) < piso_setup THEN 'PISO_SETUP'
      WHEN pico_anterior_v > nat THEN 'ANTI_PARADOXO'
      ELSE 'natural' END,
    ROUND((GREATEST(nat, pico_anterior_v, piso_setup) * (1 + markup_percent/100))::numeric, 2),
    NULL::text
  FROM calc
)
SELECT * FROM saida ORDER BY app_ordem;
$$;


ALTER FUNCTION "public"."fn_simular_combo_gravacao_v11"("aplicacoes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_simular_combo_gravacao_v11"("aplicacoes" "jsonb") IS 'Simulação de combo de gravação. Setup é piso comercial (MAX vs natural). Aceita location_code OU lado. Agrupamento por arte_id (mesma logo em N gomos = 1 setup). FIX 2026-04-26: custo_aplicacao agora aplicado tambem em LASER/UV_DIGITAL/BORDADO (antes so SUBLIMACAO/TRANSFER_DIGITAL). Padronizado em UNIF-01, GUARDACHUVA-DIM-01, FIBER-PLAQ-01.';



CREATE OR REPLACE FUNCTION "public"."fn_simular_combo_gravacao_v12"("aplicacoes" "jsonb") RETURNS TABLE("app_ordem" integer, "product_id" "uuid", "tecnica_codigo" "text", "arte" "text", "cores" "text", "qty" integer, "location_code" "text", "custo_natural" numeric, "piso_comercial_aplicado" numeric, "custo_final" numeric, "regra_ativada" "text", "venda_aplicacao" numeric, "motivo_erro" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH input AS (
    SELECT 
      ord::int AS app_ord,
      ((app->>'product_id')::uuid) AS prod_id,
      (app->>'tecnica_codigo')::text AS tec_cod,
      COALESCE((app->>'largura')::numeric, 0) AS l,
      COALESCE((app->>'altura')::numeric, 0) AS a,
      COALESCE((app->>'cores')::int, 1) AS c,
      (app->>'qty')::int AS q,
      UPPER(COALESCE(app->>'location_code', app->>'lado', 'LADO-A')) AS lado
    FROM jsonb_array_elements(aplicacoes) WITH ORDINALITY arr(app, ord)
  ),
  diag AS (
    SELECT 
      i.*,
      t.id AS tab_id, t.grupo_tecnica, t.ativo, t.max_cores,
      pat.id AS pat_id, pat.max_width, pat.max_height,
      CASE
        WHEN i.q IS NULL OR i.q <= 0 THEN 'ERRO_QTY_INVALIDA'
        WHEN i.c IS NULL OR i.c <= 0 THEN 'ERRO_CORES_INVALIDA'
        WHEN t.id IS NULL THEN 'ERRO_TECNICA_INEXISTENTE'
        WHEN NOT t.ativo THEN 'ERRO_TECNICA_INATIVA'
        WHEN i.c > t.max_cores THEN 'ERRO_CORES_EXCEDE_MAX'
        WHEN pat.id IS NULL THEN 'ERRO_PRODUTO_NAO_ACEITA_TECNICA'
        WHEN i.l > 0 AND i.l > pat.max_width THEN 'ERRO_LARGURA_EXCEDE_AREA'
        WHEN i.a > 0 AND i.a > pat.max_height THEN 'ERRO_ALTURA_EXCEDE_AREA'
        ELSE NULL
      END AS motivo
    FROM input i
    LEFT JOIN tabela_preco_gravacao_oficial t ON t.codigo_tabela = i.tec_cod
    LEFT JOIN print_area_techniques pat ON pat.product_id = i.prod_id 
      AND pat.tabela_preco_id = t.id AND pat.location_code = i.lado AND pat.is_active = true
  ),
  combo_check AS (
    SELECT 
      EXISTS(SELECT 1 FROM diag WHERE grupo_tecnica = 'SUBLIMACAO' AND motivo IS NULL) AS tem_subl,
      EXISTS(SELECT 1 FROM diag WHERE grupo_tecnica IN ('SERIGRAFIA','TRANSFER_DIGITAL','TAMPOGRAFIA','LASER','LASER_CO2','UV_DIGITAL','BORDADO') AND motivo IS NULL) AS tem_outro
  ),
  diag_final AS (
    SELECT d.*,
      CASE
        WHEN d.motivo IS NOT NULL THEN d.motivo
        WHEN d.grupo_tecnica = 'SUBLIMACAO' AND cc.tem_outro THEN 'ERRO_SUBL_NAO_COMBINA_OUTRAS'
        ELSE NULL
      END AS motivo_final
    FROM diag d CROSS JOIN combo_check cc
  ),
  resolved AS (
    SELECT 
      d.app_ord, d.tec_cod, d.l, d.a, d.c, d.q, d.lado, d.prod_id, d.grupo_tecnica,
      t.custo_setup, t.custo_setup_por_cor, t.custo_aplicacao, t.markup_percent,
      f.preco_unitario, f.ordem AS faixa_ordem, t.id AS tab_id,
      COALESCE((t.opcoes_modificadores->'multiplicador_cor'->>d.c::text)::numeric, 1.0) AS mult_cor,
      -- v12: setup_total agora é o PISO COMERCIAL (unificado em UNIF-01 25/04/2026)
      CASE WHEN t.custo_setup_por_cor THEN t.custo_setup * d.c ELSE t.custo_setup END AS setup_total,
      COALESCE((t.opcoes_modificadores->>'adicional_fotolito_por_cor')::numeric, 0) AS foto_a3
    FROM diag_final d
    JOIN tabela_preco_gravacao_oficial t ON t.id = d.tab_id
    JOIN tabela_preco_gravacao_oficial_faixa f ON f.tabela_preco_gravacao_id = t.id
      AND d.q BETWEEN f.quantidade_minima AND COALESCE(f.quantidade_maxima, 2147483647)
      AND (
        t.usa_faixa_dimensional = false 
        OR (
          (f.largura_min IS NULL OR d.l = 0 OR d.l BETWEEN f.largura_min AND f.largura_max)
          AND (f.altura_min IS NULL OR d.a = 0 OR d.a BETWEEN f.altura_min AND f.altura_max)
        )
      )
    WHERE d.motivo_final IS NULL
  ),
  -- pico_anterior agora SEM setup (setup virou piso, não aditivo)
  pico_anterior AS (
    SELECT r.app_ord, MAX(
      CASE 
        WHEN r.grupo_tecnica = 'SERIGRAFIA' THEN fa.quantidade_maxima * fa.preco_unitario * r.mult_cor + r.foto_a3 * r.c
        WHEN r.grupo_tecnica = 'TAMPOGRAFIA' THEN fa.quantidade_maxima * fa.preco_unitario * r.mult_cor
        WHEN r.grupo_tecnica = 'SUBLIMACAO' THEN fa.quantidade_maxima * (fa.preco_unitario + r.custo_aplicacao)
        WHEN r.grupo_tecnica IN ('LASER','LASER_CO2','UV_DIGITAL') THEN fa.quantidade_maxima * fa.preco_unitario
        WHEN r.grupo_tecnica = 'BORDADO' THEN fa.quantidade_maxima * fa.preco_unitario
        ELSE 0 END
    ) AS pico
    FROM resolved r
    JOIN tabela_preco_gravacao_oficial_faixa fa ON fa.tabela_preco_gravacao_id = r.tab_id
      AND fa.quantidade_maxima IS NOT NULL AND fa.quantidade_maxima < r.q
    GROUP BY r.app_ord
  ),
  calc AS (
    SELECT 
      r.app_ord, r.prod_id, r.tec_cod, r.l, r.a, r.c, r.q, r.lado,
      r.grupo_tecnica, r.markup_percent,
      COALESCE(pa.pico, 0) AS pico_anterior_v,
      r.setup_total AS piso_setup,
      -- v12: nat = GRAVACAO PURA (sem setup somado)
      CASE 
        WHEN r.grupo_tecnica = 'SERIGRAFIA' THEN r.q * r.preco_unitario * r.mult_cor + r.foto_a3 * r.c
        WHEN r.grupo_tecnica = 'TAMPOGRAFIA' THEN r.q * r.preco_unitario * r.mult_cor
        WHEN r.grupo_tecnica = 'TRANSFER_DIGITAL' THEN r.q * ((r.l * r.a / 10000.0) * r.preco_unitario + r.custo_aplicacao)
        WHEN r.grupo_tecnica = 'SUBLIMACAO' THEN r.q * (r.preco_unitario + r.custo_aplicacao)
        WHEN r.grupo_tecnica IN ('LASER','LASER_CO2','UV_DIGITAL') THEN r.q * r.preco_unitario
        WHEN r.grupo_tecnica = 'BORDADO' THEN r.q * r.preco_unitario
        ELSE 0 END AS nat
    FROM resolved r LEFT JOIN pico_anterior pa ON pa.app_ord = r.app_ord
  ),
  saida AS (
    -- Linhas de erro (mesmo schema do v11)
    SELECT df.app_ord AS app_ordem, df.prod_id AS product_id, df.tec_cod AS tecnica_codigo,
      CASE WHEN df.l > 0 AND df.a > 0 THEN df.l || 'x' || df.a || ' cm' ELSE '-' END AS arte,
      df.c::text || ' cor' AS cores, df.q AS qty, df.lado AS location_code,
      NULL::numeric AS custo_natural, NULL::numeric AS piso_comercial_aplicado, NULL::numeric AS custo_final,
      df.motivo_final AS regra_ativada, NULL::numeric AS venda_aplicacao,
      df.motivo_final AS motivo_erro
    FROM diag_final df 
    WHERE df.motivo_final IS NOT NULL
    
    UNION ALL
    
    -- Linhas calculadas v12
    SELECT app_ord, prod_id, tec_cod,
      CASE WHEN l > 0 AND a > 0 THEN l || 'x' || a || ' cm' ELSE '-' END,
      CASE WHEN grupo_tecnica IN ('SERIGRAFIA','TAMPOGRAFIA') THEN c::text || ' cor' ELSE 'full color' END,
      q, lado,
      ROUND(nat::numeric, 2),
      ROUND(piso_setup::numeric, 2),  -- agora reporta o setup como piso
      ROUND(GREATEST(nat, pico_anterior_v, piso_setup)::numeric, 2),
      CASE 
        WHEN GREATEST(nat, pico_anterior_v) < piso_setup THEN 'PISO_SETUP'
        WHEN pico_anterior_v > nat THEN 'ANTI_PARADOXO'
        ELSE 'natural' END,
      ROUND((GREATEST(nat, pico_anterior_v, piso_setup) * (1 + markup_percent/100))::numeric, 2),
      NULL::text
    FROM calc
  )
  SELECT * FROM saida ORDER BY app_ordem;
$$;


ALTER FUNCTION "public"."fn_simular_combo_gravacao_v12"("aplicacoes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_simular_combo_gravacao_v12"("aplicacoes" "jsonb") IS 'Simulação de combo de gravação (v12 com motivo_erro). Padronizado em UNIF-01 (25/04/2026). Aceita campos location_code OU lado (alias retrocompat) — propagado em 2026-04-25.';



CREATE OR REPLACE FUNCTION "public"."fn_site_flag_divergent"("p_supplier" "uuid" DEFAULT 'd6718a29-e954-4c1b-bd84-03ea24884900'::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_flag int; v_clear int;
BEGIN
  WITH pairs AS (
    SELECT s.id,
      (SELECT array_agg(w) FROM unnest(regexp_split_to_array(lower(s.name),'\s+')) w WHERE length(w)>=4) AS s_tok,
      (SELECT array_agg(w) FROM unnest(regexp_split_to_array(lower(p.name),'\s+')) w WHERE length(w)>=4) AS a_tok,
      p.name AS api_name
    FROM public.produtos_site_padronizacao s
    JOIN public.produtos_padronizacao p
      ON p.supplier_id=s.supplier_id AND p.supplier_reference=s.supplier_reference
    WHERE s.supplier_id=p_supplier AND s.name IS NOT NULL AND p.name IS NOT NULL
  ),
  f AS (
    UPDATE public.produtos_site_padronizacao t
       SET status='rejected'::public.produtos_padronizacao_status,
           validation_errors=jsonb_build_object('api_divergente',true,'api_name',pr.api_name,
                                                 'motivo','site sem token>=4 em comum com produto da API (provavel pagina generica)'),
           updated_at=now()
      FROM pairs pr
     WHERE t.id=pr.id
       AND NOT (COALESCE(pr.s_tok,'{}') && COALESCE(pr.a_tok,'{}'))
       AND NOT (t.status='rejected' AND t.validation_errors ? 'api_divergente')
     RETURNING 1
  ),
  c AS (
    UPDATE public.produtos_site_padronizacao t
       SET status='standardized'::public.produtos_padronizacao_status,
           validation_errors=NULL, updated_at=now()
      FROM pairs pr
     WHERE t.id=pr.id
       AND (COALESCE(pr.s_tok,'{}') && COALESCE(pr.a_tok,'{}'))
       AND t.validation_errors ? 'api_divergente'
     RETURNING 1
  )
  SELECT (SELECT count(*) FROM f),(SELECT count(*) FROM c) INTO v_flag,v_clear;
  RETURN jsonb_build_object('rejeitados_divergentes',v_flag,'reabilitados',v_clear);
END $$;


ALTER FUNCTION "public"."fn_site_flag_divergent"("p_supplier" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_site_pipeline_health"("p_supplier" "uuid" DEFAULT 'd6718a29-e954-4c1b-bd84-03ea24884900'::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE r jsonb;
BEGIN
    SELECT jsonb_build_object(
        'ts', now(),
        'bronze', (SELECT jsonb_build_object(
            'total',count(*),'processed',count(*) FILTER (WHERE site_status::text='processed'),
            'failed',count(*) FILTER (WHERE site_status::text='failed'),
            'sem_scrape',count(*) FILTER (WHERE site_status IS NULL),
            'pct_done',round(100.0*count(*) FILTER (WHERE site_status::text='processed')/nullif(count(*),0),1)
        ) FROM supplier_products_raw WHERE supplier_id=p_supplier),
        'silver_api', (SELECT jsonb_build_object(
            'total_pais',count(*),'promoted',count(*) FILTER (WHERE status='promoted'),
            'ncm_pct',round(100.0*count(*) FILTER (WHERE ncm_code IS NOT NULL)/nullif(count(*),0),2),
            'sem_ncm_worklist',count(*) FILTER (WHERE validation_errors ? 'ncm_ausente_origem')
        ) FROM produtos_padronizacao WHERE supplier_id=p_supplier),
        'silver_site', (SELECT jsonb_build_object(
            'total',count(*),'promoted',count(*) FILTER (WHERE status='promoted'),
            'standardized',count(*) FILTER (WHERE status='standardized'),
            'rejected',count(*) FILTER (WHERE status='rejected'),
            'linkados',count(*) FILTER (WHERE product_id IS NOT NULL),
            'pct_promoted',round(100.0*count(*) FILTER (WHERE status='promoted')/nullif(count(*),0),1)
        ) FROM produtos_site_padronizacao WHERE supplier_id=p_supplier),
        'staging_imagens', (SELECT jsonb_build_object(
            'total',count(*),'produtos',count(DISTINCT sku),
            'pending',  count(*) FILTER (WHERE status='pending'),
            'uploading',count(*) FILTER (WHERE status='uploading'),
            'uploaded', count(*) FILTER (WHERE status='uploaded'),
            'error',    count(*) FILTER (WHERE status='error')
        ) FROM xbz_gallery_staging),
        'cron',(SELECT row_to_json(t) FROM (
            SELECT jobid,schedule,active FROM cron.job
            WHERE command ILIKE '%fn_xbz_site_tick%' LIMIT 1
        ) t)
    ) INTO r;
    RETURN r;
END $$;


ALTER FUNCTION "public"."fn_site_pipeline_health"("p_supplier" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_site_promote_to_gold"("p_supplier" "uuid" DEFAULT 'd6718a29-e954-4c1b-bd84-03ea24884900'::"uuid", "p_limit" integer DEFAULT NULL::integer, "p_only_new" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_linked integer:=0; v_phys_a integer:=0; v_phys_e integer:=0;
    v_props_b integer:=0; v_props_f integer:=0; v_rel integer:=0;
    v_xcat integer:=0; v_imgs integer:=0; v_promoted integer:=0;
BEGIN
    WITH lnk AS (
        SELECT s.id, p.product_id
        FROM public.produtos_site_padronizacao s
        JOIN public.produtos_padronizacao p
          ON p.supplier_id=s.supplier_id AND p.supplier_reference=s.supplier_reference
        WHERE s.supplier_id=p_supplier AND p.product_id IS NOT NULL
          AND s.product_id IS NULL AND s.status<>'rejected'
    )
    UPDATE public.produtos_site_padronizacao t
       SET product_id=lnk.product_id, updated_at=now()
      FROM lnk WHERE t.id=lnk.id;
    GET DIAGNOSTICS v_linked=ROW_COUNT;

    CREATE TEMP TABLE _scope ON COMMIT DROP AS
        SELECT s.* FROM public.produtos_site_padronizacao s
        WHERE s.supplier_id=p_supplier AND s.product_id IS NOT NULL
          AND s.status=CASE WHEN p_only_new
                            THEN 'standardized'::public.produtos_padronizacao_status
                            ELSE s.status END
          AND s.status<>'rejected'
        LIMIT COALESCE(p_limit,1000000000);

    IF NOT EXISTS (SELECT 1 FROM _scope) THEN
        RETURN jsonb_build_object('linked',v_linked,'note','nada_novo');
    END IF;

    INSERT INTO public.product_physical (product_id, diameter_cm)
        SELECT product_id, diameter_cm FROM _scope WHERE diameter_cm IS NOT NULL
        ON CONFLICT (product_id) DO UPDATE
            SET diameter_cm=COALESCE(public.product_physical.diameter_cm,EXCLUDED.diameter_cm), updated_at=now();
    GET DIAGNOSTICS v_phys_a=ROW_COUNT;

    INSERT INTO public.product_properties (product_id, property_code, property_value, source, raw_value)
        SELECT s.product_id, kv.code, kv.val, kv.src, kv.val FROM _scope s
        CROSS JOIN LATERAL (VALUES
            ('site_ficha_tecnica_pdf', s.datasheet_pdf_url, 'xbz_site'),
            ('site_modo_de_uso', s.usage_instructions, 'xbz_site'),
            ('site_disclaimer', s.disclaimer, 'xbz_site'),
            ('circumference_cm', s.circumference_cm::text, 'xbz_site'),
            ('site_categoria_path',(SELECT string_agg(c->>'nome',' > ' ORDER BY (c->>'nivel')::int)
                                    FROM jsonb_array_elements(COALESCE(s.categories,'[]'::jsonb)) c),'xbz_site'),
            ('site_url', s.source_url, 'xbz_site'),
            ('material_xbz_primary', NULLIF(public.extract_xbz_material_primary(
                upper(COALESCE(s.name,'')), upper(COALESCE(s.description,''))),''), 'xbz_extractor')
        ) AS kv(code,val,src)
        WHERE kv.val IS NOT NULL AND btrim(kv.val)<>''
        ON CONFLICT (product_id, property_code) DO UPDATE
            SET property_value=EXCLUDED.property_value, raw_value=EXCLUDED.raw_value,
                source=EXCLUDED.source, updated_at=now();
    GET DIAGNOSTICS v_props_b=ROW_COUNT;

    -- FIX 2026-06-22: ON CONFLICT DO NOTHING (sem especificar colunas) cobre AMBAS as
    -- constraints: a pairwise (product_id,related_product_id,relationship_type) E a
    -- canonical bidirecional (LEAST/GREATEST) idx_product_relationships_canonical_pair.
    -- A versão anterior usava ON CONFLICT (product_id,related_product_id,relationship_type)
    -- que ignorava o caso em que (B,A) já existe quando tentamos inserir (A,B).
    INSERT INTO public.product_relationships (product_id, related_product_id, relationship_type, is_active)
        SELECT DISTINCT s.product_id, rp.product_id, 'related', true FROM _scope s
        CROSS JOIN LATERAL jsonb_array_elements(COALESCE(s.related_references,'[]'::jsonb)) rel
        JOIN public.produtos_padronizacao rp
          ON rp.supplier_id=s.supplier_id AND rp.supplier_reference=rel->>'codigo'
          AND rp.product_id IS NOT NULL
        WHERE (rel->>'codigo') IS NOT NULL AND rp.product_id<>s.product_id
        ON CONFLICT DO NOTHING;  -- FIX: cobre canonical pair index + pairwise index
    GET DIAGNOSTICS v_rel=ROW_COUNT;

    INSERT INTO public.product_category_assignments (product_id, category_id, is_primary, display_order)
        SELECT DISTINCT s.product_id, xcat.category_id, false, 995 FROM _scope s
        CROSS JOIN LATERAL public.classify_xbz_category(upper(COALESCE(s.name,''))) xcat
        WHERE xcat.confidence IN ('high','medium') AND xcat.category_id IS NOT NULL
          AND xcat.category_name<>'NÃO CLASSIFICADO' AND s.name IS NOT NULL
        ON CONFLICT (product_id, category_id) DO NOTHING;
    GET DIAGNOSTICS v_xcat=ROW_COUNT;

    INSERT INTO public.product_physical (product_id, weight_g, height_cm, width_cm, length_cm)
        SELECT product_id, weight_g::numeric, height_cm, width_cm, depth_cm FROM _scope
        WHERE weight_g IS NOT NULL OR height_cm IS NOT NULL OR width_cm IS NOT NULL OR depth_cm IS NOT NULL
        ON CONFLICT (product_id) DO UPDATE
            SET weight_g=COALESCE(public.product_physical.weight_g,EXCLUDED.weight_g),
                height_cm=COALESCE(public.product_physical.height_cm,EXCLUDED.height_cm),
                width_cm=COALESCE(public.product_physical.width_cm,EXCLUDED.width_cm),
                length_cm=COALESCE(public.product_physical.length_cm,EXCLUDED.length_cm),
                updated_at=now();
    GET DIAGNOSTICS v_phys_e=ROW_COUNT;

    INSERT INTO public.product_properties (product_id, property_code, property_value, source, raw_value)
        SELECT s.product_id, kv.code, kv.val, 'xbz_site', kv.val FROM _scope s
        CROSS JOIN LATERAL (VALUES
            ('site_cores_swatches', CASE WHEN jsonb_array_length(COALESCE(s.colors,'[]'::jsonb))>0 THEN s.colors::text ELSE NULL END),
            ('gravacao_medida', s.engraving_text),
            ('gravacao_comprimento_cm', s.engraving_length_cm::text),
            ('gravacao_largura_cm', s.engraving_width_cm::text),
            ('gravacao_local', NULLIF(s.engraving_location,'')),
            ('site_video_youtube_id', CASE WHEN s.has_video AND s.video_embed_id IS NOT NULL THEN s.video_embed_id ELSE NULL END),
            ('site_video_watch_url', CASE WHEN s.has_video AND s.video_watch_url IS NOT NULL THEN s.video_watch_url ELSE NULL END),
            ('site_imagens_urls', CASE WHEN jsonb_array_length(COALESCE(s.images,'[]'::jsonb))>0 THEN s.images::text ELSE NULL END)
        ) AS kv(code,val)
        WHERE kv.val IS NOT NULL AND btrim(kv.val)<>''
        ON CONFLICT (product_id, property_code) DO UPDATE
            SET property_value=EXCLUDED.property_value, raw_value=EXCLUDED.raw_value, updated_at=now();
    GET DIAGNOSTICS v_props_f=ROW_COUNT;

    INSERT INTO public.xbz_gallery_staging (
        sku, source_url, product_id, supplier_id,
        display_order, image_type, is_primary,
        source, status, cf_custom_id, cf_filename, image_slug, populated_at
    )
    SELECT DISTINCT
        s.supplier_reference,
        img->>'url_origem',
        s.product_id,
        p_supplier,
        (img->>'ordem')::integer,
        CASE WHEN (img->>'ordem')::integer=0 THEN 'main' ELSE 'gallery' END,
        (img->>'ordem')::integer=0,
        'site', 'pending',
        'xbz-'||lower(regexp_replace(s.supplier_reference,'[^a-zA-Z0-9]','-','g'))
            ||CASE WHEN (img->>'ordem')::integer=0 THEN '-main'
                   ELSE '-gal-'||lpad((img->>'ordem'),2,'0') END,
        lower(regexp_replace(s.supplier_reference,'[^a-zA-Z0-9]','-','g'))
            ||CASE WHEN (img->>'ordem')::integer=0 THEN '-main'
                   ELSE '-gal-'||lpad((img->>'ordem'),2,'0') END||'.jpg',
        lower(regexp_replace(s.supplier_reference,'[^a-zA-Z0-9]','-','g')),
        now()
    FROM _scope s
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(s.images,'[]'::jsonb)) img
    WHERE (img->>'url_origem') IS NOT NULL AND btrim(img->>'url_origem')<>''
      AND (img->>'ordem')::integer BETWEEN 0 AND 9
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_imgs=ROW_COUNT;

    UPDATE public.produtos_site_padronizacao t
       SET status='promoted'::public.produtos_padronizacao_status,
           promoted_at=now(), updated_at=now()
    WHERE t.id IN (SELECT id FROM _scope);
    GET DIAGNOSTICS v_promoted=ROW_COUNT;

    RETURN jsonb_build_object(
        'linked',v_linked,'physical_diam',v_phys_a,'physical_dims',v_phys_e,
        'properties_b',v_props_b,'properties_f',v_props_f,
        'relationships',v_rel,'category_xbz',v_xcat,
        'imgs_staging',v_imgs,'promoted',v_promoted
    );
END $$;


ALTER FUNCTION "public"."fn_site_promote_to_gold"("p_supplier" "uuid", "p_limit" integer, "p_only_new" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_site_to_silver_all"("p_supplier" "uuid" DEFAULT 'd6718a29-e954-4c1b-bd84-03ea24884900'::"uuid", "p_limit" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_affected int; v_total int;
BEGIN
  INSERT INTO public.produtos_site_padronizacao AS t (
    raw_id, supplier_id, supplier_reference, source_url, source_hash, scraper_version,
    name, description, usage_instructions, supplier_internal_id, availability, disclaimer,
    weight_g, height_cm, width_cm, depth_cm, diameter_cm, circumference_cm,
    engraving_text, engraving_length_cm, engraving_width_cm, engraving_location,
    datasheet_pdf_url, has_video, video_platform, video_embed_id, video_embed_url,
    video_watch_url, video_channel_url, has_view_360, view_360_icon_url,
    primary_image_url, images, colors, categories, related_references,
    brand, moq, min_quantity, regular_price, sale_price, is_on_sale,
    status, standardized_at, updated_at
  )
  SELECT
    s.raw_id, s.supplier_id, s.codigo,
    s.site_data->>'url', s.site_hash, s.site_data#>>'{_meta,scraper_version}',
    public.fn_sanitize_text(s.site_data->>'nome'),
    public.fn_sanitize_text(s.site_data->>'descricao'),
    public.fn_sanitize_text(s.site_data->>'modo_de_uso'),
    s.site_data->>'id_interno_site',
    public.fn_sanitize_text(s.site_data->>'disponibilidade_site'),
    public.fn_sanitize_text(s.site_data->>'disclaimer'),
    (s.site_data->>'peso_g')::int,
    (s.site_data#>>'{dimensoes,altura_cm}')::numeric,
    (s.site_data#>>'{dimensoes,largura_cm}')::numeric,
    (s.site_data#>>'{dimensoes,profundidade_cm}')::numeric,
    (s.site_data#>>'{dimensoes,diametro_cm}')::numeric,
    (s.site_data#>>'{dimensoes,circunferencia_cm}')::numeric,
    public.fn_sanitize_text(s.site_data#>>'{gravacao,medida_texto}'),
    (s.site_data#>>'{gravacao,comprimento_cm}')::numeric,
    (s.site_data#>>'{gravacao,largura_cm}')::numeric,
    public.fn_sanitize_text(s.site_data#>>'{gravacao,local}'),
    s.site_data->>'ficha_tecnica_pdf',
    (s.site_data#>>'{video,indicador}')::boolean,
    s.site_data#>>'{video,plataforma}',  s.site_data#>>'{video,embed_id}',
    s.site_data#>>'{video,embed_url}',   s.site_data#>>'{video,watch_url}',
    s.site_data#>>'{video,canal}',
    (s.site_data#>>'{view_360,indicador}')::boolean, s.site_data#>>'{view_360,icone}',
    (SELECT img->>'url_origem'
       FROM jsonb_array_elements(COALESCE(s.site_data->'imagens','[]'::jsonb)) img
      WHERE img->>'tipo'='principal' ORDER BY (img->>'ordem')::int LIMIT 1),
    s.site_data->'imagens', s.site_data->'cores',
    s.site_data->'categorias', s.site_data->'relacionados',
    -- Campos WP-exclusive: null para XBZ (chaves ausentes no site_data XBZ)
    NULLIF(s.site_data->>'marca', ''),
    NULLIF(s.site_data->>'moq', '')::integer,
    NULLIF(s.site_data->>'qtd_minima', '')::integer,
    NULLIF(s.site_data->>'preco_normal', '')::numeric,
    NULLIF(s.site_data->>'preco_promo', '')::numeric,
    (s.site_data->>'em_promocao')::boolean,
    'standardized'::public.produtos_padronizacao_status, now(), now()
  FROM (
    SELECT DISTINCT ON (r.supplier_id, r.site_data->>'codigo')
      r.id AS raw_id, r.supplier_id, r.site_data->>'codigo' AS codigo,
      r.site_data, r.site_hash
    FROM public.supplier_products_raw r
    WHERE r.supplier_id = p_supplier
      AND r.site_status = 'processed'
      AND r.site_data IS NOT NULL
      AND r.site_data->>'codigo' IS NOT NULL
    ORDER BY r.supplier_id, r.site_data->>'codigo', r.id
    LIMIT COALESCE(p_limit, 1000000000)
  ) s
  ON CONFLICT (supplier_id, supplier_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, source_url=EXCLUDED.source_url,
    source_hash=EXCLUDED.source_hash, scraper_version=EXCLUDED.scraper_version,
    name=EXCLUDED.name, description=EXCLUDED.description,
    usage_instructions=EXCLUDED.usage_instructions,
    supplier_internal_id=EXCLUDED.supplier_internal_id,
    availability=EXCLUDED.availability, disclaimer=EXCLUDED.disclaimer,
    weight_g=EXCLUDED.weight_g, height_cm=EXCLUDED.height_cm,
    width_cm=EXCLUDED.width_cm, depth_cm=EXCLUDED.depth_cm,
    diameter_cm=EXCLUDED.diameter_cm, circumference_cm=EXCLUDED.circumference_cm,
    engraving_text=EXCLUDED.engraving_text,
    engraving_length_cm=EXCLUDED.engraving_length_cm,
    engraving_width_cm=EXCLUDED.engraving_width_cm,
    engraving_location=EXCLUDED.engraving_location,
    datasheet_pdf_url=EXCLUDED.datasheet_pdf_url,
    has_video=EXCLUDED.has_video, video_platform=EXCLUDED.video_platform,
    video_embed_id=EXCLUDED.video_embed_id, video_embed_url=EXCLUDED.video_embed_url,
    video_watch_url=EXCLUDED.video_watch_url, video_channel_url=EXCLUDED.video_channel_url,
    has_view_360=EXCLUDED.has_view_360, view_360_icon_url=EXCLUDED.view_360_icon_url,
    primary_image_url=EXCLUDED.primary_image_url,
    images=EXCLUDED.images, colors=EXCLUDED.colors,
    categories=EXCLUDED.categories, related_references=EXCLUDED.related_references,
    -- Fill-only nos 6 novos: COALESCE preserva valor existente se novo for null
    brand=COALESCE(EXCLUDED.brand, t.brand),
    moq=COALESCE(EXCLUDED.moq, t.moq),
    min_quantity=COALESCE(EXCLUDED.min_quantity, t.min_quantity),
    regular_price=COALESCE(EXCLUDED.regular_price, t.regular_price),
    sale_price=COALESCE(EXCLUDED.sale_price, t.sale_price),
    is_on_sale=COALESCE(EXCLUDED.is_on_sale, t.is_on_sale),
    status='standardized'::public.produtos_padronizacao_status,
    standardized_at=now(), updated_at=now()
  WHERE t.source_hash IS DISTINCT FROM EXCLUDED.source_hash;

  GET DIAGNOSTICS v_affected = ROW_COUNT;
  SELECT count(DISTINCT r.site_data->>'codigo') INTO v_total
  FROM public.supplier_products_raw r
  WHERE r.supplier_id=p_supplier AND r.site_status='processed' AND r.site_data IS NOT NULL;

  RETURN jsonb_build_object('afetados', v_affected, 'total_candidatos', v_total,
                            'normalizacao', 'fn_sanitize_text', 'rodado_em', now());
END $$;


ALTER FUNCTION "public"."fn_site_to_silver_all"("p_supplier" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_slugify"("p_text" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_result text;
BEGIN
  IF p_text IS NULL OR btrim(p_text) = '' THEN RETURN NULL; END IF;

  -- 1. Lower
  v_result := lower(btrim(p_text));

  -- 2. Substituição de acentos pt-BR + espanhol (cobertura ampla)
  v_result := translate(v_result,
    'áàãâäåéèêëíìîïóòõôöúùûüçñýÿœæ',
    'aaaaaaeeeeiiiiooooouuuucnyyoa'
  );

  -- 3. Remover qualquer caractere não-ASCII remanescente (paranoia)
  v_result := regexp_replace(v_result, '[^\x00-\x7F]', '', 'g');

  -- 4. Substituir espaço/underscore/pontuação por hífen
  v_result := regexp_replace(v_result, '[^a-z0-9]+', '-', 'g');

  -- 5. Colapsar múltiplos hífens
  v_result := regexp_replace(v_result, '-{2,}', '-', 'g');

  -- 6. Strip leading/trailing hyphens
  v_result := btrim(v_result, '-');

  RETURN NULLIF(v_result, '');
END;
$$;


ALTER FUNCTION "public"."fn_slugify"("p_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_slugify"("p_text" "text") IS 'Converte texto pt-BR para slug URL-safe. Ex: "GARRAFA EM ALUMÍNIO - 600 ML" → "garrafa-em-aluminio-600-ml"';



CREATE OR REPLACE FUNCTION "public"."fn_sm_batch_to_silver"("p_batch_size" integer DEFAULT 500) RETURNS TABLE("processed" integer, "errors" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bronze_id   uuid;
  v_processed   int := 0;
  v_errors      int := 0;
  v_supplier_id uuid;
BEGIN
  -- 1. Resolver supplier_id do SM de forma segura
  SELECT id INTO v_supplier_id
  FROM   public.suppliers
  WHERE  code = 'SOMARCAS'
  LIMIT  1;

  IF v_supplier_id IS NULL THEN
    RAISE WARNING 'fn_sm_batch_to_silver: supplier SOMARCAS não encontrado';
    RETURN QUERY SELECT 0, 0;
    RETURN;
  END IF;

  -- 2. Iterar sobre bronzes pendentes ou falhos (guard por enum — sem tabelas depreciadas)
  FOR v_bronze_id IN
    SELECT spr.id
    FROM   public.supplier_products_raw spr
    WHERE  spr.supplier_id = v_supplier_id
      AND  spr.status IN (
             'pending'::public.supplier_raw_status,
             'failed'::public.supplier_raw_status
           )
      AND  COALESCE(spr.attempts, 0) < 5
    ORDER BY spr.imported_at
    LIMIT  p_batch_size
  LOOP
    BEGIN
      PERFORM public.fn_sm_to_silver(v_bronze_id);
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      RAISE WARNING 'fn_sm_batch_to_silver: erro bronze % — %', v_bronze_id, SQLERRM;
    END;
  END LOOP;

  RETURN QUERY SELECT v_processed, v_errors;
END;
$$;


ALTER FUNCTION "public"."fn_sm_batch_to_silver"("p_batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_batch_to_silver"("p_batch_size" integer) IS 'DEPRECATED 2026-06-05: Silver legado (medallion 001). Substituido pelo pipeline de-para oficial (produtos_padronizacao via fn_standardize_supplier + fn_promote_supplier). Sem chamadores. Candidato a DROP em follow-up.';



CREATE OR REPLACE FUNCTION "public"."fn_sm_category_collect"("p_max" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net'
    AS $$
DECLARE
  rec          record;
  v_body       text;
  v_sc         int;
  v_m          text[];
  v_category_id int;
  v_urls       jsonb := '[]'::jsonb;
  v_url_item   jsonb;
  v_ok         int  := 0;
  v_fail       int  := 0;
  v_wait       int  := 0;
  v_total_urls int  := 0;
  v_matched    int  := 0;
  v_result     jsonb;
BEGIN
  FOR rec IN
    SELECT id, name, slug, category_id, fetch_req_id, site_url
    FROM sm_category_pages
    WHERE status = 'processing'
      AND fetch_req_id IS NOT NULL
    LIMIT p_max
  LOOP
    SELECT status_code, content INTO v_sc, v_body
    FROM net._http_response WHERE id = rec.fetch_req_id;

    IF NOT FOUND THEN
      v_wait := v_wait + 1;
      CONTINUE;
    END IF;

    IF v_sc <> 200 OR length(COALESCE(v_body,'')) < 200 THEN
      UPDATE sm_category_pages
        SET status='failed', last_error='HTTP '||COALESCE(v_sc::text,'?'),
            fetch_req_id=NULL
      WHERE id = rec.id;
      v_fail := v_fail + 1;
    ELSE
      -- 1. Se não tem category_id, tenta descobrir pela URL no markdown
      IF rec.category_id IS NULL THEN
        v_m := regexp_match(v_body,
          'somarcas\.com\.br/([0-9]+)/categorias/(' || rec.slug || ')');
        IF v_m IS NOT NULL THEN
          UPDATE sm_category_pages
            SET category_id = v_m[1]::int
          WHERE id = rec.id;
          -- Re-enqueue para scrape completo da categoria (agora com URL)
          UPDATE sm_category_pages
            SET status='pending', fetch_req_id=NULL
          WHERE id = rec.id;
          v_ok := v_ok + 1;
          DELETE FROM net._http_response WHERE id = rec.fetch_req_id;
          CONTINUE;
        END IF;
      END IF;

      -- 2. Extrai todos os (site_id, slug) de produtos na página
      v_urls := '[]'::jsonb;
      FOR v_m IN
        SELECT regexp_matches(v_body,
          'somarcas\.com\.br/([0-9]+)/produto/([a-z0-9][a-z0-9-]+)', 'g')
      LOOP
        v_urls := v_urls || jsonb_build_object(
          'site_id', v_m[1]::int,
          'slug',    v_m[2]
        );
      END LOOP;

      -- Desduplicar por site_id
      SELECT jsonb_agg(DISTINCT item) INTO v_urls
      FROM jsonb_array_elements(v_urls) item;

      v_total_urls := v_total_urls + COALESCE(jsonb_array_length(v_urls), 0);

      -- 3. Slug-match → sm_site_url_map
      IF jsonb_array_length(v_urls) > 0 THEN
        v_result := public.fn_sm_url_map_from_site_urls(v_urls);
        v_matched := v_matched + COALESCE((v_result->>'resolved')::int, 0);
      END IF;

      -- 4. Verificar paginação (simplificado — se encontrou produtos, marcar done)
      UPDATE sm_category_pages
        SET status          = 'done',
            products_found  = COALESCE(jsonb_array_length(v_urls), 0),
            last_scraped_at = now(),
            fetch_req_id    = NULL
      WHERE id = rec.id;

      v_ok := v_ok + 1;
    END IF;

    DELETE FROM net._http_response WHERE id = rec.fetch_req_id;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',         v_ok,
    'fail',       v_fail,
    'wait',       v_wait,
    'urls_found', v_total_urls,
    'matched',    v_matched,
    'ts',         now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_sm_category_collect"("p_max" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_category_collect"("p_max" integer) IS 'Coleta respostas de categorias, extrai (site_id, slug) dos produtos e chama fn_sm_url_map_from_site_urls para atualizar o mapa.';



CREATE OR REPLACE FUNCTION "public"."fn_sm_category_enqueue"("p_limit" integer DEFAULT 3, "p_jina_key" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'net'
    AS $$
DECLARE
  v_jina_key text := p_jina_key;
  v_headers  jsonb;
  rec        record;
  v_req      bigint;
  v_n        int  := 0;
BEGIN
  -- Vault: Jina API key
  IF v_jina_key IS NULL THEN
    BEGIN
      SELECT decrypted_secret INTO v_jina_key
      FROM vault.decrypted_secrets WHERE name='jina_api_key' LIMIT 1;
      IF v_jina_key LIKE '__PLACEHOLDER%' THEN v_jina_key := NULL; END IF;
    EXCEPTION WHEN OTHERS THEN v_jina_key := NULL;
    END;
  END IF;

  -- Markdown: menor que HTML, mesmo padrão de URL para extração
  v_headers := jsonb_build_object('Accept', 'text/markdown');
  IF v_jina_key IS NOT NULL THEN
    v_headers := v_headers || jsonb_build_object('Authorization', 'Bearer ' || v_jina_key);
  END IF;

  -- Watchdog: liberta processing > 60 min
  UPDATE sm_category_pages
    SET status='pending', fetch_req_id=NULL
  WHERE status = 'processing'
    AND COALESCE(updated_at, created_at) < now() - interval '60 minutes';

  -- Enfileira apenas categorias COM site_url (não usa Jina Search)
  FOR rec IN
    SELECT id, name, slug, category_id, site_url
    FROM sm_category_pages
    WHERE status IN ('pending')
      AND site_url IS NOT NULL       -- garante que NUNCA usa Search
      AND attempts < 5
    ORDER BY attempts, created_at
    LIMIT p_limit
  LOOP
    SELECT net.http_get(
      url                  := 'https://r.jina.ai/' || rec.site_url,
      headers              := v_headers,
      timeout_milliseconds := 55000
    ) INTO v_req;

    UPDATE sm_category_pages
      SET status       = 'processing',
          fetch_req_id = v_req,
          attempts     = attempts + 1,
          updated_at   = now()
    WHERE id = rec.id;

    v_n := v_n + 1;
  END LOOP;

  RETURN v_n;
END;
$$;


ALTER FUNCTION "public"."fn_sm_category_enqueue"("p_limit" integer, "p_jina_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_category_enqueue"("p_limit" integer, "p_jina_key" "text") IS 'Enfileira Jina Reader para páginas de categoria SM. Categorias com URL conhecida: scrape direto. Sem URL: Jina Search.';



CREATE OR REPLACE FUNCTION "public"."fn_sm_category_seed"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sup    uuid := '841cd690-210a-422a-908c-7676828db272';
  v_ins    int  := 0;
  v_rows   int  := 0;
  v_name   text;
  v_slug   text;
BEGIN
  -- Explodir pipe-delimited, slugificar, desduplicar e inserir
  INSERT INTO public.sm_category_pages (name, slug)
  SELECT DISTINCT
    trim(cat)                      AS name,
    public.fn_slugify(trim(cat))   AS slug
  FROM supplier_products_raw,
       regexp_split_to_table(raw_data->>'matriz_de_categorias', '\|') cat
  WHERE supplier_id = v_sup
    AND raw_data->>'matriz_de_categorias' IS NOT NULL
    AND raw_data->>'matriz_de_categorias' != ''
    AND trim(cat) != ''
    AND public.fn_slugify(trim(cat)) IS NOT NULL
    AND length(public.fn_slugify(trim(cat))) > 3
  ON CONFLICT (slug) DO NOTHING;

  GET DIAGNOSTICS v_ins = ROW_COUNT;

  RETURN jsonb_build_object(
    'categories_seeded', v_ins,
    'total_in_table',    (SELECT count(*) FROM sm_category_pages),
    'ts', now()
  );
END;
$$;


