CREATE OR REPLACE FUNCTION "public"."fn_sm_pipeline_health"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $$
DECLARE
  v_sup   uuid := '841cd690-210a-422a-908c-7676828db272';
  v_jina  text;
  v_cook  text;
  v_res   jsonb;
BEGIN
  -- Verificar Vault secrets (sem expor valores)
  BEGIN
    SELECT decrypted_secret INTO v_jina
    FROM vault.decrypted_secrets WHERE name='jina_api_key';
    SELECT decrypted_secret INTO v_cook
    FROM vault.decrypted_secrets WHERE name='sm_session_cookie';
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  SELECT jsonb_build_object(
    'ts', now(),
    'supplier', 'Só Marcas',
    'supplier_id', v_sup,

    -- ── Vault ─────────────────────────────────────────────────────────────
    'vault', jsonb_build_object(
      'jina_api_key',       CASE WHEN v_jina IS NULL OR v_jina LIKE '__PLACEHOLDER%'
                                 THEN 'placeholder/missing' ELSE 'ok' END,
      'sm_session_cookie',  CASE WHEN v_cook IS NULL OR v_cook LIKE '__PLACEHOLDER%'
                                 THEN 'placeholder/missing' ELSE 'ok' END
    ),

    -- ── Bronze ────────────────────────────────────────────────────────────
    'bronze', jsonb_build_object(
      'total',        (SELECT count(*) FROM supplier_products_raw WHERE supplier_id=v_sup),
      'site_pending', (SELECT count(*) FROM supplier_products_raw
                       WHERE supplier_id=v_sup AND site_status='pending'),
      'site_processing', (SELECT count(*) FROM supplier_products_raw
                          WHERE supplier_id=v_sup AND site_status='processing'),
      'site_processed',  (SELECT count(*) FROM supplier_products_raw
                          WHERE supplier_id=v_sup AND site_status='processed'),
      'site_failed',     (SELECT count(*) FROM supplier_products_raw
                          WHERE supplier_id=v_sup AND site_status='failed'),
      'site_skipped',    (SELECT count(*) FROM supplier_products_raw
                          WHERE supplier_id=v_sup AND site_status='skipped'),
      'site_promoted',   (SELECT count(*) FROM supplier_products_raw
                          WHERE supplier_id=v_sup AND site_promoted_at IS NOT NULL),
      'last_scraped_at', (SELECT max(site_scraped_at) FROM supplier_products_raw
                          WHERE supplier_id=v_sup),
      'pct_scraped', round(100.0 *
        (SELECT count(*) FROM supplier_products_raw
         WHERE supplier_id=v_sup AND site_status='processed') /
        NULLIF((SELECT count(*) FROM supplier_products_raw 
                WHERE supplier_id=v_sup AND site_status != 'skipped'), 0), 1),
      'errors_sample', (SELECT jsonb_agg(jsonb_build_object('codigo', raw_data->>'codigo',
                          'err', site_last_error, 'att', site_attempts))
                        FROM (SELECT raw_data, site_last_error, site_attempts
                              FROM supplier_products_raw
                              WHERE supplier_id=v_sup AND site_status='failed'
                              LIMIT 5) e)
    ),

    -- ── URL Map ───────────────────────────────────────────────────────────
    'url_map', jsonb_build_object(
      'total',           (SELECT count(*) FROM sm_site_url_map WHERE supplier_id=v_sup),
      'with_url',        (SELECT count(*) FROM sm_site_url_map
                          WHERE supplier_id=v_sup AND site_url IS NOT NULL),
      'without_site_id', (SELECT count(*) FROM sm_site_url_map
                          WHERE supplier_id=v_sup AND site_id IS NULL),
      'coverage_pct',    round(100.0 *
        (SELECT count(*) FROM sm_site_url_map WHERE supplier_id=v_sup AND site_url IS NOT NULL) /
        NULLIF((SELECT count(*) FROM supplier_products_raw WHERE supplier_id=v_sup), 0), 1),
      'by_source', (SELECT jsonb_object_agg(source, cnt)
                    FROM (SELECT source, count(*) AS cnt FROM sm_site_url_map
                          WHERE supplier_id=v_sup AND site_id IS NOT NULL
                          GROUP BY source) s),
      'search_status', (SELECT jsonb_object_agg(COALESCE(ss,'null'), cnt)
                        FROM (SELECT search_status AS ss, count(*) AS cnt
                              FROM sm_site_url_map
                              WHERE supplier_id=v_sup AND site_id IS NULL
                              GROUP BY ss) s)
    ),

    -- ── Gold ──────────────────────────────────────────────────────────────
    'gold', jsonb_build_object(
      'total_products',    (SELECT count(*) FROM products WHERE supplier_id=v_sup),
      'with_site_url',     (SELECT count(*) FROM products
                            WHERE supplier_id=v_sup AND supplier_product_url IS NOT NULL),
      'with_ncm',          (SELECT count(*) FROM products
                            WHERE supplier_id=v_sup AND ncm_code IS NOT NULL),
      'site_properties',   (SELECT count(*) FROM product_properties pp
                            JOIN products p ON p.id=pp.product_id
                            WHERE p.supplier_id=v_sup AND pp.source LIKE 'sm_site%'),
      'by_property_code',  (SELECT jsonb_object_agg(property_code, cnt)
                            FROM (SELECT pp.property_code, count(*) AS cnt
                                  FROM product_properties pp
                                  JOIN products p ON p.id=pp.product_id
                                  WHERE p.supplier_id=v_sup AND pp.source LIKE 'sm_site%'
                                  GROUP BY pp.property_code) s)
    ),

    -- ── Cron jobs ─────────────────────────────────────────────────────────
    'cron_jobs', (SELECT jsonb_agg(jsonb_build_object(
      'id', j.jobid, 'name', j.jobname, 'schedule', j.schedule, 'active', j.active,
      'last_run', jr.start_time, 'last_status', jr.status
    ))
    FROM cron.job j
    LEFT JOIN LATERAL (
      SELECT start_time, status FROM cron.job_run_details
      WHERE jobid = j.jobid ORDER BY start_time DESC LIMIT 1
    ) jr ON true
    WHERE j.jobname ILIKE '%sm%' OR j.command ILIKE '%sm%')

  ) INTO v_res;

  RETURN v_res;
END;
$$;


ALTER FUNCTION "public"."fn_sm_pipeline_health"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_pipeline_health"() IS 'Health check completo do SM Jina Scraping Pipeline. Retorna KPIs de Vault, Bronze, URL Map, Gold e Cron Jobs em um JSON.';



CREATE OR REPLACE FUNCTION "public"."fn_sm_populate_colors"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_total int;
  org_id  CONSTANT uuid := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
  sup_id  CONSTANT uuid := '841cd690-210a-422a-908c-7676828db272';
BEGIN
  WITH similares AS (
    SELECT unnest(string_to_array(trim(both ';' from raw_data->>'produtos_similares'), ';')) AS bloco
    FROM supplier_products_raw
    WHERE supplier_id = sup_id AND source_channel = 'api_rest'
      AND raw_data->>'produtos_similares' IS NOT NULL
  ),
  parsed AS (
    SELECT upper(trim(split_part(bloco,'|',2))) AS hex, trim(split_part(bloco,'|',5)) AS titulo
    FROM similares WHERE bloco LIKE '%|%' AND split_part(bloco,'|',2) LIKE '#%'
  ),
  repr AS (
    SELECT DISTINCT ON (hex) hex, titulo
    FROM (SELECT hex, titulo, COUNT(*) n FROM parsed GROUP BY hex, titulo) t
    ORDER BY hex, n DESC
  ),
  cores AS (
    SELECT hex, titulo,
      COALESCE(
        upper(trim((regexp_match(titulo,
          E'- ([A-Z\\xC0-\\xD6\\xD8-\\xF6\\xF8-\\xFF][A-Z\\xC0-\\xD6\\xD8-\\xF6\\xF8-\\xFF/]{1,25})(?:\\s*-\\s*\\d|$)',
          'i'))[1])),
        upper(trim((regexp_match(titulo,
          '(PRETO|PRETA|BRANCO|BRANCA|AZUL|VERDE|VERMELHO|VERMELHA|AMARELO|AMARELA|LARANJA|ROSA|CINZA|BEGE|MARROM|DOURADO|DOURADA|PRATA|PRATEADO|TRANSPARENTE|CARAMELO|VINHO|TURQUESA|TERRACOTA|GRAFITE|NUDE|AREIA|AMADEIRADO|AMADEIRADA|NATURAL|OURO|BORDO|LILÁS|ROXO|ROXA|CREME)',
          'i'))[1])),
        hex  -- fallback
      ) AS cor_nome
    FROM repr
  )
  INSERT INTO supplier_colors (
    organization_id, supplier_id, name, code, hex_code, api_color_id,
    api_description, api_raw_data, source, is_active, is_available
  )
  SELECT org_id, sup_id,
    -- FIX: name legível = "NomeCor #RRGGBB" ou só "#RRGGBB" se nome não extraído
    CASE
      WHEN trim(left(cor_nome,40)) ~* '^#[0-9A-Fa-f]{6}$'
        THEN hex   -- fallback: sem nome extraído, usa hex
      ELSE initcap(lower(trim(left(cor_nome,40)))) || ' ' || hex
    END,
    hex,   -- code
    hex,   -- hex_code
    hex,   -- api_color_id
    trim(left(cor_nome, 40)),  -- api_description = nome extraído
    jsonb_build_object('hex', hex, 'titulo_origem', titulo, 'cor_extraida', trim(left(cor_nome,40))),
    'api_rest', true, true
  FROM cores
  ON CONFLICT (organization_id, supplier_id, name)
  DO UPDATE SET
    api_description = EXCLUDED.api_description,
    api_raw_data    = EXCLUDED.api_raw_data,
    updated_at      = NOW();

  GET DIAGNOSTICS v_total = ROW_COUNT;
  RETURN jsonb_build_object('status','ok','colors_upserted',v_total,'supplier','SO_MARCAS','fix','name_legivel_v2');
END;
$_$;


ALTER FUNCTION "public"."fn_sm_populate_colors"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sm_populate_videos_from_site"("p_supplier_id" "uuid" DEFAULT '841cd690-210a-422a-908c-7676828db272'::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '60s'
    AS $$
DECLARE
  v_inseridos int := 0;
  v_t0        timestamptz := clock_timestamp();
BEGIN
  WITH videos_site AS (
    SELECT DISTINCT ON (youtube_id)
      spr.product_id,
      (regexp_match(spr.site_data->>'video_url', E'[?&]v=([A-Za-z0-9_-]{11})'))[1] AS youtube_id,
      spr.site_data->>'video_url'                                                    AS watch_url,
      p.name                                                                         AS nome_produto
    FROM supplier_products_raw spr
    JOIN products p ON p.id = spr.product_id
    WHERE spr.supplier_id = p_supplier_id
      AND spr.source_channel = 'api_rest'
      AND spr.site_data->>'video_url' IS NOT NULL
      AND spr.product_id IS NOT NULL
      AND (regexp_match(spr.site_data->>'video_url', E'[?&]v=([A-Za-z0-9_-]{11})'))[1] IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM product_videos pv2
        WHERE pv2.product_id = spr.product_id AND pv2.source_supplier = 'somarcas'
      )
    ORDER BY youtube_id, spr.updated_at DESC
  )
  INSERT INTO product_videos (
    product_id, cloudflare_video_id, url_stream, url_original,
    video_type, is_primary, display_order,
    source_supplier, source_youtube_id,
    title, cloudflare_status, is_active, organization_id
  )
  SELECT
    vs.product_id, 'sm_' || vs.youtube_id,
    'https://www.youtube.com/embed/' || vs.youtube_id,
    vs.watch_url, 'demo', true, 0, 'somarcas', vs.youtube_id,
    vs.nome_produto, 'youtube', true,
    '5db5aee1-064b-4ef4-9193-345dcd8274ea'
  FROM videos_site vs
  ON CONFLICT (product_id, cloudflare_video_id) DO NOTHING;  -- usa constraint existente

  GET DIAGNOSTICS v_inseridos = ROW_COUNT;

  UPDATE products p
  SET videos = (
    SELECT jsonb_agg(jsonb_build_object(
      'id', pv2.id, 'youtube_id', pv2.source_youtube_id,
      'embed_url', pv2.url_stream, 'watch_url', pv2.url_original,
      'is_primary', pv2.is_primary, 'title', pv2.title, 'plataforma', 'youtube'
    ) ORDER BY pv2.display_order)
    FROM product_videos pv2 WHERE pv2.product_id = p.id AND pv2.is_active = true
  )
  WHERE p.supplier_id = p_supplier_id
    AND EXISTS (SELECT 1 FROM product_videos pv3 WHERE pv3.product_id = p.id AND pv3.source_supplier = 'somarcas');

  RETURN jsonb_build_object('success', true, 'videos_inseridos', v_inseridos,
    'supplier', 'SO_MARCAS', 'segundos', round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,2));
END;
$$;


ALTER FUNCTION "public"."fn_sm_populate_videos_from_site"("p_supplier_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sm_promote_videos_from_site"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_inserted int := 0;
  v_demo_type_id uuid;
BEGIN
  SELECT id INTO v_demo_type_id FROM video_types WHERE code='demo' LIMIT 1;
  
  WITH sm_videos AS (
    SELECT 
      spr.supplier_sku,
      spr.site_data->>'video_url' AS video_url,
      regexp_replace(
        spr.site_data->>'video_url',
        '^.*[?&]v=([^&]+).*$', '\1'
      ) AS youtube_id
    FROM supplier_products_raw spr
    WHERE spr.supplier_id='841cd690-210a-422a-908c-7676828db272'
      AND spr.site_data->>'video_url' IS NOT NULL
      AND spr.site_data->>'video_url' LIKE '%youtube%'
  ),
  sm_with_product AS (
    SELECT DISTINCT ON (p.id, sv.youtube_id)
      sv.youtube_id,
      sv.video_url,
      sv.supplier_sku,
      p.id AS product_id
    FROM sm_videos sv
    JOIN products p ON p.supplier_reference = sv.supplier_sku
      AND p.supplier_id = '841cd690-210a-422a-908c-7676828db272'
    WHERE NOT EXISTS (
      SELECT 1 FROM product_videos pv
      WHERE pv.product_id = p.id
        AND pv.source_youtube_id = sv.youtube_id
    )
  ),
  ins AS (
    INSERT INTO product_videos (
      product_id,
      cloudflare_video_id,
      url_stream,
      source_youtube_id,
      url_original,
      cloudflare_status,
      video_type,
      video_type_id,
      is_primary,
      display_order,
      source_supplier,
      is_active
    )
    SELECT 
      swp.product_id,
      'sm_' || swp.youtube_id,
      'https://www.youtube.com/embed/' || swp.youtube_id,
      swp.youtube_id,
      swp.video_url,
      'youtube',
      'demo',
      v_demo_type_id,
      true,
      0,
      'somarcas',
      true
    FROM sm_with_product swp
    ON CONFLICT DO NOTHING
    RETURNING id
  )
  SELECT COUNT(*) INTO v_inserted FROM ins;
  
  RETURN jsonb_build_object(
    'ok', true,
    'inserted', v_inserted,
    'total_sm_videos_now', (SELECT COUNT(*) FROM product_videos pv 
                            JOIN products p ON p.id=pv.product_id 
                            WHERE p.supplier_id='841cd690-210a-422a-908c-7676828db272')
  );
END;
$_$;


ALTER FUNCTION "public"."fn_sm_promote_videos_from_site"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sm_session_check"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $$
DECLARE
  v_cookie       text;
  v_is_real      boolean := false;
  v_last_auth    timestamptz;
  v_price_count  int;
  v_status       text;
  v_alerta       text;
BEGIN
  -- 1. Lê o cookie do Vault
  BEGIN
    SELECT decrypted_secret INTO v_cookie
    FROM vault.decrypted_secrets WHERE name='sm_session_cookie' LIMIT 1;
  EXCEPTION WHEN OTHERS THEN v_cookie := NULL;
  END;

  -- 2. Verifica se é real (não placeholder)
  v_is_real := (v_cookie IS NOT NULL
                AND v_cookie NOT LIKE '__PLACEHOLDER%'
                AND length(btrim(v_cookie)) > 20);

  -- 3. Conta produtos com price_tiers gravados (scraping autenticado)
  SELECT count(*) INTO v_price_count
  FROM product_properties pp
  JOIN products p ON p.id = pp.product_id
  WHERE p.supplier_id = '841cd690-210a-422a-908c-7676828db272'
    AND pp.property_code = 'price_tiers_sm'
    AND pp.source = 'sm_site_scraping_auth';

  -- 4. Último scraping autenticado
  SELECT max(spr.site_scraped_at) INTO v_last_auth
  FROM supplier_products_raw spr
  WHERE spr.supplier_id = '841cd690-210a-422a-908c-7676828db272'
    AND spr.site_data->>'is_authenticated' = 'true';

  -- 5. Determina status
  IF NOT v_is_real THEN
    v_status := 'sem_cookie';
    v_alerta := '⚠️ SM Session: Cookie não configurado (placeholder). '
             || 'Atualize via SM Session Sync para ativar scraping B2B '
             || '(preços por faixa + caixa master).';
  ELSIF v_last_auth IS NULL OR v_last_auth < now() - interval '48 hours' THEN
    v_status := 'cookie_possivelmente_expirado';
    v_alerta := '⚠️ SM Session: Nenhum scraping autenticado recente. '
             || 'Cookie pode ter expirado. Renove via SM Session Sync.';
  ELSE
    v_status := 'ativo';
    v_alerta := NULL;
  END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'status',           v_status,
    'cookie_is_real',   v_is_real,
    'price_tiers_gold', v_price_count,
    'last_auth_scrape', v_last_auth,
    'alerta',           v_alerta,
    'ts',               now()
  ));
END;
$$;


ALTER FUNCTION "public"."fn_sm_session_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sm_site_collect"("p_max" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'extensions'
    AS $$
DECLARE
  v_sup         uuid := '841cd690-210a-422a-908c-7676828db272';
  rec           record;
  v_sc          int;
  v_body        text;
  v_payload     jsonb;
  v_hash        text;
  v_err         text;
  v_ok          int  := 0;
  v_fail        int  := 0;
  v_wait        int  := 0;
  v_new_urls    int  := 0;
  v_rows        int  := 0;
  v_rel         jsonb;
  v_rel_item    jsonb;
  v_rel_codigo  text;
  v_rel_sid     int;
  v_rel_slug    text;
  -- Acumulador de (site_id, slug) sem codigo → slug-match batch
  v_no_codigo   jsonb := '[]'::jsonb;
  v_slug_result jsonb;
BEGIN

  FOR rec IN
    SELECT spr.id                   AS spr_id,
           spr.site_fetch_req_id    AS req_id,
           spr.site_source_url      AS source_url,
           spr.raw_data->>'codigo'  AS codigo
    FROM   supplier_products_raw spr
    WHERE  spr.supplier_id  = v_sup
      AND  spr.site_status  = 'processing'
      AND  spr.site_fetch_req_id IS NOT NULL
    LIMIT  p_max
  LOOP
    SELECT status_code, content
    INTO   v_sc, v_body
    FROM   net._http_response
    WHERE  id = rec.req_id;

    IF NOT FOUND THEN
      v_wait := v_wait + 1;
      CONTINUE;
    END IF;

    v_err := NULL;

    -- Validação de qualidade mínima
    IF v_sc <> 200 THEN
      v_err := 'HTTP ' || COALESCE(v_sc::text, '?');
    ELSIF length(COALESCE(v_body,'')) < 500 THEN
      v_err := 'resposta_curta len=' || length(COALESCE(v_body,''));
    ELSIF position('Just a moment' IN v_body) > 0
       OR position('Enable JavaScript' IN v_body) > 0 THEN
      v_err := 'cloudflare_challenge';
    ELSE
      v_payload := public.fn_parse_sm_site_markdown(v_body, rec.source_url);

      IF v_payload ? 'error' THEN
        v_err := 'parse_error:' || (v_payload->>'error');
      -- Aceitar se há pelo menos fotos CDN OU relacionados (sem exigir codigo)
      ELSIF (v_payload->'fotos_cdn') IS NULL
         AND (v_payload->'relacionados') IS NULL
         AND (v_payload->>'video_url') IS NULL THEN
        v_err := 'pagina_nao_produto';
      END IF;
    END IF;

    IF v_err IS NULL THEN
      v_hash := encode(extensions.digest(v_payload::text, 'sha256'), 'hex');

      UPDATE supplier_products_raw
        SET site_data         = v_payload,
            site_hash         = v_hash,
            site_status       = 'processed',
            site_scraped_at   = now(),
            site_processed_at = now(),
            site_last_error   = NULL,
            site_fetch_req_id = NULL
      WHERE id = rec.spr_id;

      v_ok := v_ok + 1;

      -- ── Expande URL map com relacionados ───────────────────────────────
      v_rel := v_payload->'relacionados';
      IF v_rel IS NOT NULL AND jsonb_array_length(v_rel) > 0 THEN
        FOR v_rel_item IN SELECT * FROM jsonb_array_elements(v_rel) LOOP
          v_rel_sid   := (v_rel_item->>'site_id')::int;
          v_rel_slug  := v_rel_item->>'slug';
          v_rel_codigo:= v_rel_item->>'codigo';  -- pode ser NULL

          CONTINUE WHEN v_rel_sid IS NULL OR v_rel_slug IS NULL;

          IF v_rel_codigo IS NOT NULL THEN
            -- Path A: codigo conhecido → INSERT direto
            INSERT INTO public.sm_site_url_map
              (supplier_id, codigo, site_id, slug, source, confidence, last_verified_at)
            VALUES
              (v_sup, v_rel_codigo, v_rel_sid, v_rel_slug,
               'related_products', 'high', now())
            ON CONFLICT (supplier_id, codigo) DO UPDATE
              SET site_id          = EXCLUDED.site_id,
                  slug             = EXCLUDED.slug,
                  source           = EXCLUDED.source,
                  confidence       = EXCLUDED.confidence,
                  last_verified_at = EXCLUDED.last_verified_at
              WHERE sm_site_url_map.site_id IS DISTINCT FROM EXCLUDED.site_id;

            GET DIAGNOSTICS v_rows = ROW_COUNT;
            v_new_urls := v_new_urls + v_rows;
          ELSE
            -- Path B: sem codigo → acumula para slug-match em batch
            v_no_codigo := v_no_codigo || jsonb_build_object(
              'site_id', v_rel_sid, 'slug', v_rel_slug
            );
          END IF;
        END LOOP;
      END IF;

    ELSE
      UPDATE supplier_products_raw
        SET site_status       = 'failed',
            site_attempts     = COALESCE(site_attempts, 0) + 1,
            site_last_error   = v_err,
            site_fetch_req_id = NULL
      WHERE id = rec.spr_id;

      v_fail := v_fail + 1;
    END IF;

    DELETE FROM net._http_response WHERE id = rec.req_id;

  END LOOP;

  -- ── Batch slug-match para relacionados sem codigo ──────────────────────
  IF jsonb_array_length(v_no_codigo) > 0 THEN
    v_slug_result := public.fn_sm_url_map_from_site_urls(v_no_codigo);
    v_new_urls := v_new_urls + COALESCE((v_slug_result->>'resolved')::int, 0);
  END IF;

  RETURN jsonb_build_object(
    'ok',              v_ok,
    'fail',            v_fail,
    'aguardando',      v_wait,
    'new_url_map',     v_new_urls,
    'slug_matched',    COALESCE((v_slug_result->>'resolved')::int, 0),
    'slug_unmatched',  COALESCE((v_slug_result->>'unmatched')::int, 0),
    'ts',              now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_sm_site_collect"("p_max" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_site_collect"("p_max" integer) IS 'v2 — Coleta respostas Jina, valida, parseia e grava site_data. SECURITY DEFINER + search_path. Fix 5: relacionados sem codigo → slug-match via fn_sm_url_map_from_site_urls. Fix: critério de página válida usa fotos_cdn OR relacionados (sem exigir codigo).';



CREATE OR REPLACE FUNCTION "public"."fn_sm_site_enqueue"("p_limit" integer DEFAULT 5, "p_stale_days" integer DEFAULT 7, "p_jina_key" "text" DEFAULT NULL::"text", "p_with_auth" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'extensions', 'net'
    AS $$
DECLARE
  v_sup       uuid := '841cd690-210a-422a-908c-7676828db272';
  rec         record;
  v_req       bigint;
  v_n         int    := 0;
  v_jina_key  text   := p_jina_key;
  v_sm_cookie text;
  v_headers   jsonb;
  v_endpoint  text;
BEGIN

  -- 1. Vault: Jina API key
  IF v_jina_key IS NULL OR v_jina_key = '' THEN
    BEGIN
      SELECT decrypted_secret INTO v_jina_key
      FROM vault.decrypted_secrets WHERE name = 'jina_api_key' LIMIT 1;
      IF v_jina_key LIKE '__PLACEHOLDER%' THEN v_jina_key := NULL; END IF;
    EXCEPTION WHEN OTHERS THEN v_jina_key := NULL;
    END;
  END IF;

  -- 2. Vault: cookie SM (só se auth)
  IF p_with_auth THEN
    BEGIN
      SELECT decrypted_secret INTO v_sm_cookie
      FROM vault.decrypted_secrets WHERE name = 'sm_session_cookie' LIMIT 1;
      IF v_sm_cookie LIKE '__PLACEHOLDER%' THEN v_sm_cookie := NULL; END IF;
    EXCEPTION WHEN OTHERS THEN v_sm_cookie := NULL;
    END;
  END IF;

  -- 3. Watchdog: liberta 'processing' travado > 45 min
  UPDATE supplier_products_raw
    SET site_status = 'pending', site_fetch_req_id = NULL
  WHERE supplier_id = v_sup
    AND site_status = 'processing'
    AND COALESCE(site_enqueued_at, now() - interval '2 hours')
        < now() - interval '45 minutes';

  -- 4. Headers Jina
  v_headers := jsonb_build_object('Accept', 'text/markdown');
  IF v_jina_key IS NOT NULL THEN
    v_headers := v_headers || jsonb_build_object('Authorization', 'Bearer ' || v_jina_key);
  END IF;
  IF v_sm_cookie IS NOT NULL THEN
    v_headers := v_headers || jsonb_build_object('X-Set-Cookie', v_sm_cookie);
  END IF;

  -- Label do endpoint para rastreabilidade
  IF p_with_auth AND v_sm_cookie IS NOT NULL THEN
    v_endpoint := 'r.jina.ai/somarcas.com.br[auth]';
  ELSE
    v_endpoint := 'r.jina.ai/somarcas.com.br[public]';
  END IF;

  -- 5. Iterar produtos elegíveis (têm site_id no URL map)
  FOR rec IN
    SELECT
      spr.id                  AS spr_id,
      spr.raw_data->>'codigo' AS codigo,
      m.site_url
    FROM supplier_products_raw spr
    JOIN public.sm_site_url_map m
      ON  m.supplier_id = v_sup
      AND m.codigo      = spr.raw_data->>'codigo'
    WHERE spr.supplier_id = v_sup
      AND m.site_id       IS NOT NULL
      AND m.site_url      IS NOT NULL
      AND spr.site_status <> 'processing'
      AND (
            spr.site_status = 'pending'
         OR (spr.site_status = 'failed'    AND COALESCE(spr.site_attempts, 0) < 5)
         OR (spr.site_status = 'processed'
             AND COALESCE(spr.site_scraped_at, '2000-01-01'::timestamptz)
                 < now() - make_interval(days => p_stale_days))
      )
    ORDER BY
      CASE spr.site_status WHEN 'pending' THEN 1 WHEN 'processed' THEN 2 ELSE 3 END,
      COALESCE(spr.site_scraped_at, '2000-01-01'::timestamptz)
    LIMIT p_limit
  LOOP
    -- Disparo assíncrono via pg_net
    SELECT net.http_get(
      url                  := 'https://r.jina.ai/' || rec.site_url,
      headers              := v_headers,
      timeout_milliseconds := 55000
    ) INTO v_req;

    UPDATE supplier_products_raw
      SET site_status       = 'processing',
          site_fetch_req_id = v_req,
          site_source_url   = rec.site_url,
          site_enqueued_at  = now(),
          source_channel    = 'site_scraping',
          source_endpoint   = v_endpoint
    WHERE id = rec.spr_id;

    v_n := v_n + 1;
  END LOOP;

  RETURN v_n;
END;
$$;


ALTER FUNCTION "public"."fn_sm_site_enqueue"("p_limit" integer, "p_stale_days" integer, "p_jina_key" "text", "p_with_auth" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_site_enqueue"("p_limit" integer, "p_stale_days" integer, "p_jina_key" "text", "p_with_auth" boolean) IS 'Enfileira requests Jina (pg_net async) para produtos SM. p_with_auth=true injeta cookie SM. Watchdog liberta processing travado > 45 min.';



CREATE OR REPLACE FUNCTION "public"."fn_sm_site_promote"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_sup        uuid := '841cd690-210a-422a-908c-7676828db272';
  rec          record;
  v_product_id uuid;
  v_n_url      int := 0;
  v_n_video    int := 0;
  v_n_spec     int := 0;
  v_n_prices   int := 0;
  v_n_master   int := 0;
  v_n_fotos    int := 0;
  v_n_total    int := 0;
  v_rows       int := 0;
  v_yt_id      text;
BEGIN
  FOR rec IN
    SELECT
      spr.id                    AS spr_id,
      spr.site_data             AS sd,
      spr.raw_data->>'codigo'   AS codigo,
      spr.product_id            AS fk_product_id,
      m.site_url                AS canonical_site_url
    FROM supplier_products_raw spr
    LEFT JOIN public.sm_site_url_map m
      ON  m.supplier_id = v_sup
      AND m.codigo      = spr.raw_data->>'codigo'
    WHERE spr.supplier_id    = v_sup
      AND spr.site_status    = 'processed'
      AND spr.site_data      IS NOT NULL
      -- Repromover se site_data mudou (hash diferente) ou nunca promoveu
      AND (spr.site_promoted_at IS NULL
           OR spr.site_promoted_at < spr.site_processed_at)
    ORDER BY spr.site_processed_at
    LIMIT p_limit
  LOOP
    -- ── Lookup product_id no Gold ──────────────────────────────────────────
    -- Path 1: FK direto (quando Bronze já tem product_id populado)
    v_product_id := rec.fk_product_id;

    -- Path 2: join por supplier_reference (fallback robusto)
    IF v_product_id IS NULL THEN
      SELECT p.id INTO v_product_id
      FROM products p
      WHERE p.supplier_id        = v_sup
        AND p.supplier_reference = rec.codigo
        AND COALESCE(p.is_deleted, false) = false
      LIMIT 1;
    END IF;

    -- Path 3: join por sku_promo (ex: Bronze tem codigo=AS-01900, Gold tem sku_promo=AS-01900)
    IF v_product_id IS NULL THEN
      SELECT p.id INTO v_product_id
      FROM products p
      WHERE p.supplier_id = v_sup
        AND p.sku_promo   = rec.codigo
        AND COALESCE(p.is_deleted, false) = false
      LIMIT 1;
    END IF;

    IF v_product_id IS NULL THEN CONTINUE; END IF;

    v_n_total := v_n_total + 1;

    -- ── A. supplier_product_url ────────────────────────────────────────────
    IF rec.canonical_site_url IS NOT NULL THEN
      UPDATE products
        SET supplier_product_url = rec.canonical_site_url,
            updated_at           = now()
      WHERE id = v_product_id
        AND COALESCE(supplier_product_url,'') <> rec.canonical_site_url;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_n_url := v_n_url + v_rows;
    END IF;

    -- ── B. Vídeo YouTube ──────────────────────────────────────────────────
    IF rec.sd->>'video_url' IS NOT NULL THEN
      v_yt_id := substring(rec.sd->>'video_url' FROM 'v=([A-Za-z0-9_-]+)');
      INSERT INTO product_properties (product_id, property_code, property_value, source, raw_value)
      VALUES (v_product_id, 'video_youtube_url', rec.sd->>'video_url', 'sm_site_scraping', v_yt_id)
      ON CONFLICT (product_id, property_code) DO UPDATE
        SET property_value = EXCLUDED.property_value,
            raw_value      = EXCLUDED.raw_value,
            source         = EXCLUDED.source
        WHERE product_properties.property_value IS DISTINCT FROM EXCLUDED.property_value
           OR product_properties.source = 'sm_site_scraping';
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_n_video := v_n_video + v_rows;
    END IF;

    -- ── C. Spec técnica ───────────────────────────────────────────────────
    IF rec.sd->>'spec_tecnica_url' IS NOT NULL THEN
      INSERT INTO product_properties (product_id, property_code, property_value, source, raw_value)
      VALUES (v_product_id, 'spec_tecnica_url', rec.sd->>'spec_tecnica_url',
              'sm_site_scraping', rec.sd->>'spec_tecnica_url')
      ON CONFLICT (product_id, property_code) DO UPDATE
        SET property_value = EXCLUDED.property_value, source = EXCLUDED.source
        WHERE product_properties.property_value IS DISTINCT FROM EXCLUDED.property_value;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_n_spec := v_n_spec + v_rows;
    END IF;

    -- ── D. Fotos CDN extras (array → JSON em properties) ─────────────────
    IF rec.sd->'fotos_cdn' IS NOT NULL
       AND jsonb_array_length(rec.sd->'fotos_cdn') > 0 THEN
      INSERT INTO product_properties (product_id, property_code, property_value, source, raw_value)
      VALUES (v_product_id, 'fotos_cdn_sm',
              (rec.sd->'fotos_cdn')::text, 'sm_site_scraping',
              jsonb_array_length(rec.sd->'fotos_cdn')::text || ' fotos')
      ON CONFLICT (product_id, property_code) DO UPDATE
        SET property_value = EXCLUDED.property_value, source = EXCLUDED.source
        WHERE product_properties.property_value IS DISTINCT FROM EXCLUDED.property_value;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_n_fotos := v_n_fotos + v_rows;
    END IF;

    -- ── E. Price tiers (autenticado) ─────────────────────────────────────
    IF rec.sd->'price_tiers' IS NOT NULL
       AND jsonb_array_length(rec.sd->'price_tiers') > 0 THEN
      INSERT INTO product_properties (product_id, property_code, property_value, source, raw_value)
      VALUES (v_product_id, 'price_tiers_sm',
              (rec.sd->'price_tiers')::text, 'sm_site_scraping_auth',
              (rec.sd->'price_tiers')::text)
      ON CONFLICT (product_id, property_code) DO UPDATE
        SET property_value = EXCLUDED.property_value,
            raw_value      = EXCLUDED.raw_value,
            source         = EXCLUDED.source;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_n_prices := v_n_prices + v_rows;
    END IF;

    -- ── F. Caixa Master (autenticado) ─────────────────────────────────────
    IF rec.sd->'caixa_master' IS NOT NULL THEN
      INSERT INTO product_properties (product_id, property_code, property_value, source, raw_value)
      VALUES (v_product_id, 'caixa_master_sm',
              (rec.sd->'caixa_master')::text, 'sm_site_scraping',
              (rec.sd->'caixa_master')::text)
      ON CONFLICT (product_id, property_code) DO UPDATE
        SET property_value = EXCLUDED.property_value, raw_value = EXCLUDED.raw_value;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_n_master := v_n_master + v_rows;

      -- Colunas diretas em products (só se nulos)
      UPDATE products
        SET box_quantity  = COALESCE(box_quantity,
                              CASE WHEN rec.sd->'caixa_master'->>'qtd' IS NOT NULL
                                   THEN (rec.sd->'caixa_master'->>'qtd')::int END),
            box_weight_kg = COALESCE(box_weight_kg,
                              CASE WHEN rec.sd->'caixa_master'->>'peso_kg' IS NOT NULL
                                   THEN (rec.sd->'caixa_master'->>'peso_kg')::numeric END),
            updated_at    = now()
      WHERE id = v_product_id
        AND (box_quantity IS NULL OR box_weight_kg IS NULL);
    END IF;

    -- ── G. NCM / IPI ─────────────────────────────────────────────────────
    IF (rec.sd->>'ncm_site') IS NOT NULL OR (rec.sd->>'ipi_site') IS NOT NULL THEN
      UPDATE products
        SET ncm_code   = COALESCE(ncm_code, rec.sd->>'ncm_site'),
            ipi_rate   = COALESCE(ipi_rate,
                           CASE WHEN rec.sd->>'ipi_site' IS NOT NULL
                                THEN (rec.sd->>'ipi_site')::numeric END),
            updated_at = now()
      WHERE id = v_product_id
        AND (ncm_code IS NULL OR ipi_rate IS NULL);
    END IF;

    -- ── Marca como promovido ──────────────────────────────────────────────
    UPDATE supplier_products_raw
      SET site_promoted_at = now()
    WHERE id = rec.spr_id;

  END LOOP;

  RETURN jsonb_build_object(
    'produtos_processados', v_n_total,
    'urls',      v_n_url,
    'videos',    v_n_video,
    'specs',     v_n_spec,
    'fotos_cdn', v_n_fotos,
    'precos',    v_n_prices,
    'caixa_master', v_n_master,
    'ts', now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_sm_site_promote"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_site_promote"("p_limit" integer) IS 'Promove site_data SM do Bronze para Gold: URL canônica, YouTube, spec técnica, preço por faixa, caixa master (dims/qtd/peso). Aditivo — nunca destrói dados Gold. Usa product_properties para campos sem coluna nativa.';



CREATE OR REPLACE FUNCTION "public"."fn_sm_site_tick"("p_enqueue" integer DEFAULT 5, "p_collect" integer DEFAULT 20, "p_stale_days" integer DEFAULT 7, "p_with_auth" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'vault', 'extensions'
    AS $$
DECLARE
  v_enq  int;
  v_coll jsonb;
  v_prom jsonb;
BEGIN
  -- Ordem: collect primeiro (limpa responses pendentes) → enqueue → promote
  v_coll := public.fn_sm_site_collect(p_collect);
  v_enq  := public.fn_sm_site_enqueue(p_enqueue, p_stale_days, NULL, p_with_auth);
  v_prom := public.fn_sm_site_promote(50);
  RETURN jsonb_build_object(
    'collect',  v_coll,
    'enqueued', v_enq,
    'promote',  v_prom,
    'ts',       now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_sm_site_tick"("p_enqueue" integer, "p_collect" integer, "p_stale_days" integer, "p_with_auth" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_site_tick"("p_enqueue" integer, "p_collect" integer, "p_stale_days" integer, "p_with_auth" boolean) IS 'Orquestrador SM Jina Pipeline. Chama collect → enqueue → promote. FIX v2: SECURITY DEFINER + search_path correto.';



CREATE OR REPLACE FUNCTION "public"."fn_sm_stock_guard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_sm constant uuid := '841cd690-210a-422a-908c-7676828db272';
  v_unlocked int := 0;
  v_silver   int := 0;
  v_var      int := 0;
  v_gold     int := 0;
  v_vss      int := 0;
  v_pv_gold  int := 0;
  v_stockout int := 0;
BEGIN
  IF NOT pg_try_advisory_xact_lock(74108922) THEN
    RETURN jsonb_build_object('skipped', 'lock_busy', 'ts', now());
  END IF;

  -- Identificar-se como pipeline (não gerar auto-locks no trigger de manual edits)
  PERFORM set_config('app.write_source', 'pipeline', true);

  -- 0. Auto-limpeza: stock_quantity lockado é sempre acidente
  UPDATE products
  SET locked_fields = array_remove(locked_fields, 'stock_quantity')
  WHERE supplier_id = v_sm
    AND 'stock_quantity' = ANY(COALESCE(locked_fields, '{}'));
  GET DIAGNOSTICS v_unlocked = ROW_COUNT;

  -- 1. Silver ← Bronze  [regex blindado: só ASCII 0-9, máx 9 dígitos = sem overflow int]
  UPDATE produtos_padronizacao pp
  SET stock_quantity = GREATEST((r.raw_data->>'estoque')::int, 0),
      updated_at = now()
  FROM supplier_products_raw r
  WHERE r.id = pp.raw_id
    AND pp.supplier_id = v_sm
    AND (r.raw_data->>'estoque') ~ '^[0-9]{1,9}$'
    AND pp.stock_quantity IS DISTINCT FROM GREATEST((r.raw_data->>'estoque')::int, 0);
  GET DIAGNOSTICS v_silver = ROW_COUNT;

  -- 2. Variantes Silver ← pai
  UPDATE produtos_padronizacao_variantes ppv
  SET stock_quantity = pp.stock_quantity,
      updated_at = now()
  FROM produtos_padronizacao pp
  WHERE ppv.pad_id = pp.id
    AND ppv.supplier_id = v_sm
    AND pp.stock_quantity IS NOT NULL
    AND ppv.stock_quantity IS DISTINCT FROM pp.stock_quantity;
  GET DIAGNOSTICS v_var = ROW_COUNT;

  -- 3. Gold products ← Bronze  [regex blindado]
  UPDATE products p
  SET stock_quantity = GREATEST((r.raw_data->>'estoque')::int, 0),
      updated_at = now()
  FROM produtos_padronizacao pp
  JOIN supplier_products_raw r ON r.id = pp.raw_id
  WHERE pp.product_id = p.id
    AND pp.supplier_id = v_sm
    AND (r.raw_data->>'estoque') ~ '^[0-9]{1,9}$'
    AND p.stock_quantity IS DISTINCT FROM GREATEST((r.raw_data->>'estoque')::int, 0)
    AND NOT ('stock_quantity' = ANY(COALESCE(p.locked_fields, '{}')));
  GET DIAGNOSTICS v_gold = ROW_COUNT;

  -- 4. NOVO: VSS ← Bronze (fonte do agregado do trigger fn_sync_product_stock_cache)
  --    Corrigir aqui ELIMINA a gangorra: trigger trg_sync_stock_from_vss
  --    reconsolida products.stock_quantity + is_stockout automaticamente.
  --    GREATEST respeita constraint chk_vss_quantity_positive.
  UPDATE variant_supplier_sources vss
  SET quantity = GREATEST((r.raw_data->>'estoque')::int, 0),
      updated_at = now()
  FROM product_variants pv
  JOIN produtos_padronizacao pp ON pp.product_id = pv.product_id
  JOIN supplier_products_raw r ON r.id = pp.raw_id
  WHERE vss.variant_id = pv.id
    AND vss.supplier_id = v_sm
    AND pp.supplier_id = v_sm
    AND (r.raw_data->>'estoque') ~ '^[0-9]{1,9}$'
    AND vss.quantity IS DISTINCT FROM GREATEST((r.raw_data->>'estoque')::int, 0);
  GET DIAGNOSTICS v_vss = ROW_COUNT;

  -- 5. NOVO: product_variants (Gold) ← Bronze
  --    Sem cascata: trigger trg_sync_stock_from_variant só dispara em is_active.
  UPDATE product_variants pv
  SET stock_quantity = GREATEST((r.raw_data->>'estoque')::int, 0),
      updated_at = now()
  FROM produtos_padronizacao pp
  JOIN supplier_products_raw r ON r.id = pp.raw_id
  WHERE pv.product_id = pp.product_id
    AND pp.supplier_id = v_sm
    AND (r.raw_data->>'estoque') ~ '^[0-9]{1,9}$'
    AND pv.stock_quantity IS DISTINCT FROM GREATEST((r.raw_data->>'estoque')::int, 0);
  GET DIAGNOSTICS v_pv_gold = ROW_COUNT;

  -- 6. NOVO: is_stockout residual (campo derivado: sempre coerente com stock)
  UPDATE products p
  SET is_stockout = (p.stock_quantity <= 0),
      updated_at = now()
  FROM produtos_padronizacao pp
  WHERE pp.product_id = p.id
    AND pp.supplier_id = v_sm
    AND p.is_stockout IS DISTINCT FROM (p.stock_quantity <= 0);
  GET DIAGNOSTICS v_stockout = ROW_COUNT;

  RETURN jsonb_build_object(
    'locks_cleaned',  v_unlocked,
    'silver_fixed',   v_silver,
    'variants_fixed', v_var,
    'gold_fixed',     v_gold,
    'vss_fixed',      v_vss,
    'pv_gold_fixed',  v_pv_gold,
    'stockout_fixed', v_stockout,
    'ts', now());
END;
$_$;


ALTER FUNCTION "public"."fn_sm_stock_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sm_to_silver"("p_bronze_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_spr         public.supplier_products_raw%ROWTYPE;
  v_result_std  jsonb;
  v_result_var  jsonb;
  v_pad_id      uuid;
  v_parent_ref  text;
BEGIN
  -- ── 1. Carregar bronze ────────────────────────────────────────────────────
  SELECT * INTO v_spr FROM public.supplier_products_raw WHERE id = p_bronze_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error',   'bronze_nao_encontrado',
      'id',      p_bronze_id
    );
  END IF;

  -- ── 2. v1 — padronizar produto (usa supplier_field_mappings SM) ───────────
  v_result_std := public.fn_standardize_raw(p_bronze_id);

  -- ── 3. v1 — padronizar variante (cor, estoque, faixas de preço) ──────────
  v_result_var := public.fn_standardize_variant(p_bronze_id);

  -- ── 4. Promover ao Gold se padronização OK ────────────────────────────────
  v_pad_id := (v_result_std->>'padronizacao_id')::uuid;

  IF v_pad_id IS NOT NULL
     AND COALESCE((v_result_std->>'success')::boolean, true) IS NOT FALSE
  THEN
    -- Promove produto
    PERFORM public.fn_promote_padronizacao(v_pad_id);

    -- Promove variante(s) — SM é 1:1, mas chama padrão
    v_parent_ref := public.fn_derive_parent_ref(
                      v_spr.supplier_id,
                      v_spr.supplier_reference,
                      v_spr.raw_data
                    );
    PERFORM public.fn_promote_variants_of_parent(v_spr.supplier_id, v_parent_ref);
  END IF;

  -- ── 5. Marcar bronze como processado ─────────────────────────────────────
  UPDATE public.supplier_products_raw
  SET    status       = 'processed',
         processed_at = now()
  WHERE  id = p_bronze_id;

  RETURN jsonb_build_object(
    'success',         true,
    'pipeline',        'v1',
    'bronze_id',       p_bronze_id,
    'reference',       v_spr.supplier_reference,
    'padronizacao_id', v_pad_id,
    'campos',          v_result_std->>'campos',
    'variante',        v_result_var->>'variante_id',
    'note',            'v2→v1: silver_products/silver_variants depreciados; fn_clean_spot_name e classify_xbz_category removidos'
  );

EXCEPTION WHEN OTHERS THEN
  -- Registrar erro sem crash
  UPDATE public.supplier_products_raw
  SET last_error = jsonb_build_object(
                     'fn',  'fn_sm_to_silver',
                     'msg', SQLERRM,
                     'ts',  now()
                   ),
      attempts   = COALESCE(attempts, 0) + 1
  WHERE id = p_bronze_id;

  RETURN jsonb_build_object(
    'success',   false,
    'error',     SQLERRM,
    'bronze_id', p_bronze_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_sm_to_silver"("p_bronze_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_to_silver"("p_bronze_id" "uuid") IS 'DEPRECATED 2026-06-05: Silver legado (medallion 001). Substituido pelo pipeline de-para oficial (produtos_padronizacao via fn_standardize_supplier + fn_promote_supplier). Sem chamadores. Candidato a DROP em follow-up.';



CREATE OR REPLACE FUNCTION "public"."fn_sm_url_discover_collect"("p_max" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net'
    AS $$
DECLARE
  v_sup       uuid := '841cd690-210a-422a-908c-7676828db272';
  rec         record;
  v_body      text;
  v_sc        int;
  v_m         text[];
  v_site_id   int;
  v_slug      text;
  v_ok        int := 0;
  v_fail      int := 0;
  v_wait      int := 0;
BEGIN
  FOR rec IN
    SELECT id, codigo, slug, search_req_id
    FROM public.sm_site_url_map
    WHERE supplier_id    = v_sup
      AND search_status  = 'pending'
      AND search_req_id  IS NOT NULL
    LIMIT p_max
  LOOP
    SELECT status_code, content
    INTO   v_sc, v_body
    FROM   net._http_response
    WHERE  id = rec.search_req_id;

    IF NOT FOUND THEN
      v_wait := v_wait + 1;
      CONTINUE;
    END IF;

    v_site_id := NULL;
    v_slug    := NULL;

    IF v_sc = 200 AND length(COALESCE(v_body,'')) > 100 THEN
      v_m := regexp_match(v_body,
        'somarcas\.com\.br/([0-9]+)/produto/([a-z0-9][a-z0-9-]+)');
      IF v_m IS NOT NULL THEN
        v_site_id := v_m[1]::int;
        v_slug    := v_m[2];
        -- NOTA: site_url é GENERATED ALWAYS AS (site_id || slug)
        -- Não precisa ser setada explicitamente — o Postgres a computa.
      END IF;
    END IF;

    IF v_site_id IS NOT NULL THEN
      UPDATE public.sm_site_url_map
        SET site_id          = v_site_id,
            slug             = COALESCE(v_slug, slug),
            -- site_url NÃO É setada: é GENERATED column, auto-computada
            source           = 'jina_search',
            confidence       = 'medium',
            search_status    = 'done',
            last_verified_at = now()
      WHERE id = rec.id;
      v_ok := v_ok + 1;
    ELSE
      UPDATE public.sm_site_url_map
        SET search_status = 'failed',
            search_req_id = NULL
      WHERE id = rec.id;
      v_fail := v_fail + 1;
    END IF;

    DELETE FROM net._http_response WHERE id = rec.search_req_id;

  END LOOP;

  RETURN jsonb_build_object('ok',v_ok,'fail',v_fail,'wait',v_wait,'ts',now());
END;
$$;


ALTER FUNCTION "public"."fn_sm_url_discover_collect"("p_max" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_url_discover_collect"("p_max" integer) IS 'Coleta resultados Jina Search para descoberta de URLs SM. SECURITY DEFINER + search_path correto. NOTE: site_url é GENERATED ALWAYS AS, não precisa de SET explícito.';



CREATE OR REPLACE FUNCTION "public"."fn_sm_url_discover_via_search"("p_limit" integer DEFAULT 5, "p_jina_key" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'extensions', 'net'
    AS $$
DECLARE
  v_sup      uuid := '841cd690-210a-422a-908c-7676828db272';
  rec        record;
  v_req      bigint;
  v_n        int  := 0;
  v_jina_key text := p_jina_key;
  v_headers  jsonb;
  v_url      text;
BEGIN
  IF v_jina_key IS NULL THEN
    BEGIN
      SELECT decrypted_secret INTO v_jina_key
      FROM vault.decrypted_secrets WHERE name='jina_api_key' LIMIT 1;
      IF v_jina_key LIKE '__PLACEHOLDER%' THEN v_jina_key := NULL; END IF;
    EXCEPTION WHEN OTHERS THEN v_jina_key := NULL; END;
  END IF;

  v_headers := jsonb_build_object('Accept', 'text/markdown');
  IF v_jina_key IS NOT NULL THEN
    v_headers := v_headers || jsonb_build_object('Authorization', 'Bearer ' || v_jina_key);
  END IF;

  -- Watchdog
  UPDATE public.sm_site_url_map
    SET search_status = NULL, search_req_id = NULL
  WHERE supplier_id = v_sup
    AND search_status = 'pending'
    AND COALESCE(last_verified_at, now() - interval '2h') < now() - interval '60 minutes';

  FOR rec IN
    SELECT id, codigo
    FROM public.sm_site_url_map
    WHERE supplier_id = v_sup
      AND site_id IS NULL
      AND (search_status IS NULL OR search_status = 'failed')
      AND COALESCE(search_attempts, 0) < 3
    ORDER BY COALESCE(search_attempts, 0), discovered_at
    LIMIT p_limit
  LOOP
    -- SM códigos: só [A-Z0-9-] → sem encoding necessário
    -- URL: https://s.jina.ai/site:somarcas.com.br {codigo}
    -- %3A = colon, + = space (safe in query string)
    v_url := 'https://s.jina.ai/site%3Asomarcas.com.br%20' || rec.codigo;

    SELECT net.http_get(
      url                  := v_url,
      headers              := v_headers,
      timeout_milliseconds := 30000
    ) INTO v_req;

    UPDATE public.sm_site_url_map
      SET search_req_id    = v_req,
          search_status    = 'pending',
          last_verified_at = now(),
          search_attempts  = COALESCE(search_attempts, 0) + 1
    WHERE id = rec.id;

    v_n := v_n + 1;
  END LOOP;

  RETURN v_n;
END;
$$;


ALTER FUNCTION "public"."fn_sm_url_discover_via_search"("p_limit" integer, "p_jina_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sm_url_map_build"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'extensions'
    AS $_$
DECLARE
  v_sup      uuid := '841cd690-210a-422a-908c-7676828db272';
  v_seeded   int  := 0;
  v_resolved int  := 0;
  v_coverage numeric;
BEGIN

  -- ── STEP 1: Seed — insere todos os SM do Bronze no mapa (idempotente) ──
  -- Para cada produto, pré-popula com slug derivado do título canônico.
  -- site_id fica NULL até ser resolvido.
  INSERT INTO public.sm_site_url_map (
    supplier_id, codigo, slug, source, confidence
  )
  SELECT
    v_sup,
    raw_data->>'codigo'                           AS codigo,
    public.fn_slugify(raw_data->>'titulo')        AS slug,
    'bronze_seed',
    'low'    -- baixa confiança até termos o site_id real
  FROM supplier_products_raw
  WHERE supplier_id = v_sup
    AND (raw_data->>'codigo') IS NOT NULL
    AND btrim(raw_data->>'codigo') <> ''
  ON CONFLICT (supplier_id, codigo) DO UPDATE
    SET slug = COALESCE(sm_site_url_map.slug, EXCLUDED.slug)
    -- nunca sobrescreve slug já confirmado; só preenche NULL
  WHERE sm_site_url_map.slug IS NULL;

  GET DIAGNOSTICS v_seeded = ROW_COUNT;

  -- ── STEP 2: Similares parse ─────────────────────────────────────────────
  -- A. Explode produtos_similares em (codigo, site_id) via CTE
  -- B. JOIN com Bronze para obter o slug do título canônico
  -- C. UPSERT com site_id real + confidence='high'
  WITH

  raw_rows AS (
    SELECT raw_data->>'produtos_similares' AS sim_raw
    FROM supplier_products_raw
    WHERE supplier_id = v_sup
      AND raw_data->>'produtos_similares' IS NOT NULL
      AND raw_data->>'produtos_similares' NOT IN ('Nenhum', '', 'nenhum')
  ),

  -- Explode por ';'
  entries AS (
    SELECT btrim(entry) AS entry
    FROM raw_rows,
    LATERAL unnest(string_to_array(sim_raw, ';')) AS entry
    WHERE btrim(entry) <> ''
  ),

  -- Parse pipe-delimited: [codigo, hex, site_id, img, titulo]
  parsed AS (
    SELECT
      parts[1]                                          AS codigo,
      parts[3]                                          AS site_id_str
    FROM entries,
    LATERAL (SELECT string_to_array(entry, '|') AS parts) p
    WHERE array_length(string_to_array(entry, '|'), 1) >= 3
  ),

  -- Validar e desduplicar; descartar site_id=0 ou inválidos
  validated AS (
    SELECT DISTINCT ON (codigo)
      btrim(codigo) AS codigo,
      site_id_str::int AS site_id
    FROM parsed
    WHERE codigo IS NOT NULL
      AND btrim(codigo) <> ''
      AND codigo ~ '^[A-Z]{2,3}-[0-9]+'     -- formato esperado: AS-00610, IP-00503, KT-90397…
      AND site_id_str ~ '^[1-9][0-9]*$'     -- inteiro positivo (exclui 0)
    ORDER BY codigo, site_id_str::int DESC  -- pega o maior site_id em duplicatas (mais recente)
  ),

  -- JOIN com Bronze: slug derivado do título CANÔNICO (não abreviado do similares)
  enriched AS (
    SELECT
      v.codigo,
      v.site_id,
      COALESCE(
        public.fn_slugify(spr.raw_data->>'titulo'),  -- título completo do Bronze
        public.fn_slugify(v.codigo)                  -- fallback: slug do próprio código
      ) AS slug_canonico
    FROM validated v
    LEFT JOIN supplier_products_raw spr
      ON  spr.supplier_id = v_sup
      AND spr.raw_data->>'codigo' = v.codigo
  )

  INSERT INTO public.sm_site_url_map (
    supplier_id, codigo, site_id, slug, source, confidence, last_verified_at
  )
  SELECT
    v_sup, e.codigo, e.site_id, e.slug_canonico, 'produtos_similares', 'high', now()
  FROM enriched e
  ON CONFLICT (supplier_id, codigo) DO UPDATE
    SET
      site_id          = EXCLUDED.site_id,
      slug             = EXCLUDED.slug,
      source           = EXCLUDED.source,
      confidence       = EXCLUDED.confidence,
      last_verified_at = EXCLUDED.last_verified_at
    -- Atualiza sempre que a nova fonte tem site_id confirmado
    WHERE sm_site_url_map.site_id IS DISTINCT FROM EXCLUDED.site_id
       OR sm_site_url_map.slug    IS DISTINCT FROM EXCLUDED.slug;

  GET DIAGNOSTICS v_resolved = ROW_COUNT;

  -- ── STEP 3: Cobertura ──────────────────────────────────────────────────
  SELECT round(100.0 *
    (SELECT count(*) FROM public.sm_site_url_map
     WHERE supplier_id=v_sup AND site_id IS NOT NULL)
    /
    NULLIF((SELECT count(*) FROM supplier_products_raw WHERE supplier_id=v_sup), 0)
  , 1)
  INTO v_coverage;

  RETURN jsonb_build_object(
    'step1_seed_upserted',   v_seeded,
    'step2_resolved',        v_resolved,
    'total_in_map',          (SELECT count(*) FROM sm_site_url_map WHERE supplier_id=v_sup),
    'with_site_id',          (SELECT count(*) FROM sm_site_url_map WHERE supplier_id=v_sup AND site_id IS NOT NULL),
    'without_site_id',       (SELECT count(*) FROM sm_site_url_map WHERE supplier_id=v_sup AND site_id IS NULL),
    'coverage_pct',          v_coverage,
    'bronze_total',          (SELECT count(*) FROM supplier_products_raw WHERE supplier_id=v_sup),
    'ts',                    now()
  );
END;
$_$;


ALTER FUNCTION "public"."fn_sm_url_map_build"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_url_map_build"() IS 'Bootstrap do mapa de URLs SM. Step 1: seed (todos os 1.215 produtos com slug do Bronze). Step 2: resolve site_id numérico via parse de produtos_similares. Idempotente — seguro para re-executar.';



CREATE OR REPLACE FUNCTION "public"."fn_sm_url_map_from_site_urls"("p_urls" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sup       uuid := '841cd690-210a-422a-908c-7676828db272';
  v_resolved  int  := 0;
  v_unmatched int  := 0;
  v_total     int  := 0;
BEGIN
  SELECT count(*) INTO v_total
  FROM jsonb_array_elements(p_urls) u
  WHERE (u->>'site_id')::int > 0 AND u->>'slug' IS NOT NULL;

  IF v_total = 0 THEN
    RETURN jsonb_build_object('input_total',0,'resolved',0,'unmatched',0,'coverage_pct',0);
  END IF;

  WITH inc AS (
    SELECT DISTINCT ON (u->>'slug')
      (u->>'site_id')::int AS site_id,
      u->>'slug'           AS slug
    FROM jsonb_array_elements(p_urls) u
    WHERE (u->>'site_id')::int > 0 AND u->>'slug' IS NOT NULL
    ORDER BY u->>'slug', (u->>'site_id')::int DESC
  )
  INSERT INTO public.sm_site_url_map
    (supplier_id, codigo, site_id, slug, source, confidence, last_verified_at)
  SELECT DISTINCT ON (spr.raw_data->>'codigo')
    v_sup,
    spr.raw_data->>'codigo',
    i.site_id,
    i.slug,
    'category_scrape',
    CASE WHEN count(spr.id) OVER (PARTITION BY i.slug) > 1
         THEN 'medium' ELSE 'high' END,
    now()
  FROM inc i
  JOIN supplier_products_raw spr
    ON spr.supplier_id = v_sup
    AND public.fn_slugify(spr.raw_data->>'titulo') = i.slug
  ORDER BY spr.raw_data->>'codigo', i.site_id DESC
  ON CONFLICT (supplier_id, codigo) DO UPDATE
    SET site_id          = EXCLUDED.site_id,
        slug             = EXCLUDED.slug,
        source           = EXCLUDED.source,
        confidence       = EXCLUDED.confidence,
        last_verified_at = EXCLUDED.last_verified_at
    -- BUG FIX 10: só atualiza se ainda não tem site_id (bronze_seed)
    -- Não sobrescreve fontes confiáveis (produtos_similares, related_products)
    WHERE sm_site_url_map.site_id IS NULL;

  GET DIAGNOSTICS v_resolved = ROW_COUNT;

  SELECT count(*) INTO v_unmatched
  FROM (
    SELECT DISTINCT ON (u->>'slug') u->>'slug' AS slug
    FROM jsonb_array_elements(p_urls) u
    WHERE (u->>'site_id')::int > 0 AND u->>'slug' IS NOT NULL
    ORDER BY u->>'slug', (u->>'site_id')::int DESC
  ) inc2
  WHERE NOT EXISTS (
    SELECT 1 FROM supplier_products_raw spr
    WHERE spr.supplier_id = v_sup
      AND public.fn_slugify(spr.raw_data->>'titulo') = inc2.slug
  );

  RETURN jsonb_build_object(
    'input_total',  v_total,
    'resolved',     v_resolved,
    'unmatched',    v_unmatched,
    'coverage_pct', (SELECT round(100.0 *
      (SELECT count(*) FROM sm_site_url_map WHERE supplier_id=v_sup AND site_id IS NOT NULL) /
      NULLIF((SELECT count(*) FROM supplier_products_raw WHERE supplier_id=v_sup), 0), 1))
  );
END;
$$;


ALTER FUNCTION "public"."fn_sm_url_map_from_site_urls"("p_urls" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sm_url_map_from_site_urls"("p_urls" "jsonb") IS 'v4 — BUG FIX 10: ON CONFLICT só atualiza quando site_id IS NULL (não sobrescreve entradas de alta confiança como produtos_similares). BUG FIX 9: CTE em vez de temp table (re-entrante). BUG FIX 8: DISTINCT ON para evitar duplicatas.';



