CREATE OR REPLACE FUNCTION "public"."fn_spot_customization_prices_to_gold"("p_supplier_id" "uuid", "p_parent_ref" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_n integer;
BEGIN
  PERFORM set_config('app.bulk_import_mode','true', true);
  DELETE FROM public.product_customization_prices pcp
   USING public.produtos_padronizacao pp
   WHERE pcp.product_id = pp.product_id AND pp.supplier_id = p_supplier_id
     AND (p_parent_ref IS NULL OR pp.supplier_reference = p_parent_ref);

  INSERT INTO public.product_customization_prices
    (product_id, service_code, table_code, component, location, handling_cost, table_max_area_cm2, max_stitches, hotspot, min_qty, price)
  SELECT pp.product_id, r.service_code, r.table_code,
         public.fn_fix_mojibake(r.component), public.fn_fix_mojibake(r.location),
         r.handling_cost, r.table_max_area_cm2, r.max_stitches, r.hotspot,
         (SELECT array_agg((r.raw_data->>('MinQt'||i))::int ORDER BY i)
            FROM generate_series(1,15) i WHERE nullif(btrim(r.raw_data->>('MinQt'||i)),'') IS NOT NULL),
         (SELECT array_agg((r.raw_data->>('Price'||i))::numeric ORDER BY i)
            FROM generate_series(1,15) i WHERE nullif(btrim(r.raw_data->>('Price'||i)),'') IS NOT NULL)
  FROM public.supplier_customization_options_raw r
  JOIN public.produtos_padronizacao pp
    ON pp.supplier_id = r.supplier_id AND pp.supplier_reference = r.product_reference
  WHERE r.supplier_id = p_supplier_id AND pp.product_id IS NOT NULL
    AND (p_parent_ref IS NULL OR pp.supplier_reference = p_parent_ref);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;


ALTER FUNCTION "public"."fn_spot_customization_prices_to_gold"("p_supplier_id" "uuid", "p_parent_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_spot_detect_new_images"("p_limit" integer DEFAULT 200) RETURNS TABLE("ref" "text", "filename" "text", "cf_custom_id" "text", "source_url" "text", "product_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH bronze_imgs AS (
    SELECT DISTINCT ON (btrim(img_file))
      p.supplier_reference                                AS ref,
      btrim(img_file)                                     AS filename,
      'spot-' || LOWER(SPLIT_PART(btrim(img_file), '.', 1)) AS cf_custom_id,
      -- URL CORRETA: fotos/produtos, não cdn/media
      'https://www.spotgifts.com.br/fotos/produtos/'
        || btrim(img_file)                               AS source_url,
      p.id                                               AS product_id
    FROM supplier_products_raw spr
    JOIN products p ON spr.product_id = p.id
    CROSS JOIN LATERAL unnest(
      string_to_array(spr.raw_data->>'AllImageList', ',')
    ) AS img_file
    WHERE p.supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
      AND spr.raw_data->>'AllImageList' IS NOT NULL
      AND btrim(img_file) != ''
    ORDER BY btrim(img_file)
  )
  SELECT
    bi.ref,
    bi.filename,
    bi.cf_custom_id,
    bi.source_url,
    bi.product_id
  FROM bronze_imgs bi
  WHERE NOT EXISTS (
    SELECT 1 FROM product_images pi
    WHERE pi.cloudflare_image_id = bi.cf_custom_id
  )
  LIMIT p_limit;
$$;


