COMMENT ON FUNCTION "public"."fn_spot_direct_stock_gold"("p_items" "jsonb") IS 'Hot-path SPOT: atualiza estoque direto em variant_supplier_sources + product_variants. Sem Medallion. Reconciliado pelo Sync Full de madrugada.';



CREATE OR REPLACE FUNCTION "public"."fn_spot_enqueue_new_videos"() RETURNS TABLE("enfileirados" integer, "ja_existentes" integer, "sem_video" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enfileirados  INT := 0;
  v_existentes    INT := 0;
  v_sem_video     INT := 0;
  v_yt_id         TEXT;
  rec             RECORD;
BEGIN
  FOR rec IN
    SELECT DISTINCT ON (
      COALESCE(
        extract_youtube_id(spr.raw_data->>'VideoLink'),
        (regexp_match(spr.raw_data->>'VideoLink', '/shorts/([A-Za-z0-9_-]{11})'))[1]
      )
    )
      p.supplier_reference                                             AS ref,
      spr.raw_data->>'VideoLink'                                       AS video_url,
      COALESCE(
        extract_youtube_id(spr.raw_data->>'VideoLink'),
        (regexp_match(spr.raw_data->>'VideoLink', '/shorts/([A-Za-z0-9_-]{11})'))[1]
      )                                                                AS youtube_id
    FROM supplier_products_raw spr
    JOIN products p ON spr.product_id = p.id
    WHERE p.supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
      AND spr.raw_data->>'VideoLink' IS NOT NULL
      AND spr.raw_data->>'VideoLink' != ''
    ORDER BY COALESCE(
      extract_youtube_id(spr.raw_data->>'VideoLink'),
      (regexp_match(spr.raw_data->>'VideoLink', '/shorts/([A-Za-z0-9_-]{11})'))[1]
    )
  LOOP
    IF rec.youtube_id IS NULL THEN
      v_sem_video := v_sem_video + 1;
      CONTINUE;
    END IF;

    -- Verifica se já existe na fila
    IF EXISTS (
      SELECT 1 FROM video_import_queue
      WHERE youtube_id = rec.youtube_id
        AND source_supplier = 'SPOT'
    ) THEN
      v_existentes := v_existentes + 1;
      CONTINUE;
    END IF;

    -- Enfileira como pending
    INSERT INTO video_import_queue (
      youtube_id,
      youtube_url,
      source_supplier,
      product_references,
      status
    )
    SELECT
      rec.youtube_id,
      rec.video_url,
      'SPOT',
      ARRAY_AGG(DISTINCT p2.supplier_reference),
      'pending'
    FROM supplier_products_raw spr2
    JOIN products p2 ON spr2.product_id = p2.id
    WHERE p2.supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
      AND COALESCE(
        extract_youtube_id(spr2.raw_data->>'VideoLink'),
        (regexp_match(spr2.raw_data->>'VideoLink', '/shorts/([A-Za-z0-9_-]{11})'))[1]
      ) = rec.youtube_id;

    v_enfileirados := v_enfileirados + 1;
  END LOOP;

  RETURN QUERY SELECT v_enfileirados, v_existentes, v_sem_video;
END;
$$;


ALTER FUNCTION "public"."fn_spot_enqueue_new_videos"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_spot_enqueue_new_videos"() IS 'Enfileira na video_import_queue todos os VideoLink do Bronze SPOT que ainda não existem na fila.
 Agrupa múltiplos produtos com o mesmo YouTube ID em product_references[].
 Retorna: enfileirados (novos), ja_existentes (já na fila), sem_video (URL inválida).
 Usada na Fase 7 do workflow SPOT - GESTÃO DE PRODUTOS.';



CREATE OR REPLACE FUNCTION "public"."fn_spot_enqueue_vimeo_eu"("p_items" "jsonb") RETURNS TABLE("enfileirados" integer, "ja_existentes" integer, "ref_nao_encontrado" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enq   int := 0;
  v_dup   int := 0;
  v_miss  int := 0;
  v_item  jsonb;
  v_vid   text;
  v_ref   text;
  v_url   text;
  v_refs  text[];
  v_enqueued_refs text[] := '{}';  -- rastrear refs já enfileiradas neste batch
BEGIN
  FOR v_item IN SELECT jsonb_array_elements(p_items) LOOP
    v_vid := v_item->>'vimeo_id';
    v_ref := v_item->>'ref';
    v_url := 'https://vimeo.com/' || v_vid;

    -- Produto existe ativo?
    SELECT ARRAY_AGG(DISTINCT p.supplier_reference) INTO v_refs
    FROM products p
    WHERE p.supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
      AND p.supplier_reference = v_ref
      AND p.is_active = true;

    IF v_refs IS NULL OR array_length(v_refs, 1) = 0 THEN
      v_miss := v_miss + 1; CONTINUE;
    END IF;

    -- Já na fila (por vimeo_id)?
    IF EXISTS (SELECT 1 FROM video_import_queue
               WHERE youtube_id = v_vid AND source_supplier = 'SPOT') THEN
      v_dup := v_dup + 1; CONTINUE;
    END IF;

    -- Produto já tem vídeo pronto no Gold? → skip_has_video
    IF EXISTS (
      SELECT 1 FROM products p JOIN product_videos pv ON pv.product_id = p.id
      WHERE p.supplier_reference = v_ref
        AND p.supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
        AND pv.is_active = true AND pv.cloudflare_status = 'ready'
    ) THEN
      INSERT INTO video_import_queue
        (youtube_id, youtube_url, source_supplier, product_references, status)
      VALUES (v_vid, v_url, 'SPOT', v_refs, 'skip_has_video')
      ON CONFLICT DO NOTHING;
      v_dup := v_dup + 1; CONTINUE;
    END IF;

    -- FIX: Mesmo produto já foi enfileirado NESTE batch? → skip_has_video
    IF v_ref = ANY(v_enqueued_refs) THEN
      INSERT INTO video_import_queue
        (youtube_id, youtube_url, source_supplier, product_references, status)
      VALUES (v_vid, v_url, 'SPOT', v_refs, 'skip_has_video')
      ON CONFLICT DO NOTHING;
      v_dup := v_dup + 1; CONTINUE;
    END IF;

    -- Enfileira como pending
    INSERT INTO video_import_queue
      (youtube_id, youtube_url, source_supplier, product_references, status)
    VALUES (v_vid, v_url, 'SPOT', v_refs, 'pending')
    ON CONFLICT DO NOTHING;

    v_enqueued_refs := v_enqueued_refs || v_ref;
    v_enq := v_enq + 1;
  END LOOP;

  RETURN QUERY SELECT v_enq, v_dup, v_miss;
END;
$$;


ALTER FUNCTION "public"."fn_spot_enqueue_vimeo_eu"("p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_spot_enrich_image_colors"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated int := 0;
  v_skipped int := 0;
BEGIN
  -- Atualizar color_id e variant_id para imagens onde a cor está no filename
  -- Tipos: main, gallery, logo (set/ambient/box/pouch são de produto, sem cor)
  WITH updates AS (
    SELECT
      pi.id as img_id,
      pv.id as variant_id,
      pv.color_id
    FROM product_images pi
    JOIN products p ON p.id = pi.product_id
    JOIN suppliers s ON s.id = p.supplier_id
    JOIN product_variants pv ON pv.product_id = pi.product_id
      AND pv.color_code = substring(pi.filename FROM '^\d+_(\d+)')
    WHERE s.code = 'STRICKER'
      AND pi.color_id IS NULL
      AND pi.image_type IN ('main','gallery','logo')
      AND substring(pi.filename FROM '^\d+_(\d+)') IS NOT NULL
  )
  UPDATE product_images pi
  SET 
    color_id   = u.color_id,
    variant_id = u.variant_id,
    updated_at = now()
  FROM updates u
  WHERE pi.id = u.img_id
    AND u.color_id IS NOT NULL;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- Contar os que ficaram sem correspondência
  SELECT COUNT(*) INTO v_skipped
  FROM product_images pi
  JOIN products p ON p.id=pi.product_id
  JOIN suppliers s ON s.id=p.supplier_id
  WHERE s.code='STRICKER'
    AND pi.image_type IN ('main','gallery','logo')
    AND pi.color_id IS NULL;

  RETURN jsonb_build_object(
    'updated', v_updated,
    'still_without_color', v_skipped,
    'ran_at', now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_spot_enrich_image_colors"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_spot_eu_diff_get_refs"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("ref" "text", "all_images" "text", "main_image" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT DISTINCT ON (raw_data->>'ProdReference')
    raw_data->>'ProdReference'  AS ref,
    raw_data->>'AllImageList'   AS all_images,
    raw_data->>'MainImage'      AS main_image
  FROM supplier_products_raw
  WHERE supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
    AND LEFT(raw_data->>'ProdReference', 2) IN ('91','92','93','94','95','97','98','99')
    AND raw_data->>'IsStockOut' = 'false'
  ORDER BY raw_data->>'ProdReference'
  LIMIT p_limit OFFSET p_offset;
$$;


