CREATE OR REPLACE FUNCTION "public"."fn_spot_link_video"("p_queue_id" "uuid", "p_youtube_id" "text", "p_cf_stream_uid" "text", "p_url_hls" "text", "p_url_thumbnail" "text", "p_url_embed" "text", "p_duration_seconds" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  -- FIXED 2026-06-14: accountHash correto (era cd0f4eee...)
  v_cf_sub   CONSTANT text := 'customer-ksi0mrlcw6rwzezz';
  v_hls      text;
  v_thumb    text;
  v_embed    text;
  v_linked   int := 0;
  v_ref      text;
  v_prod_id  uuid;
  v_pv_id    uuid;
  v_queue    record;
  v_exists   boolean;
BEGIN
  -- Valida queue_id
  SELECT EXISTS(SELECT 1 FROM video_import_queue WHERE id = p_queue_id) INTO v_exists;
  IF NOT v_exists THEN
    RETURN jsonb_build_object('ok', false, 'error', 'queue_id not found: ' || p_queue_id::text);
  END IF;

  SELECT * INTO v_queue FROM video_import_queue WHERE id = p_queue_id;

  v_hls   := COALESCE(p_url_hls,
    'https://' || v_cf_sub || '.cloudflarestream.com/' || p_cf_stream_uid || '/manifest/video.m3u8');
  v_thumb := COALESCE(p_url_thumbnail,
    'https://' || v_cf_sub || '.cloudflarestream.com/' || p_cf_stream_uid || '/thumbnails/thumbnail.jpg');
  v_embed := COALESCE(p_url_embed,
    'https://iframe.cloudflarestream.com/' || p_cf_stream_uid);

  -- 1. Para cada ref do produto na fila: upsert product_videos + atualiza products.videos
  FOREACH v_ref IN ARRAY v_queue.product_references LOOP
    SELECT id INTO v_prod_id
    FROM products
    WHERE supplier_reference = v_ref
      AND supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
    LIMIT 1;

    CONTINUE WHEN v_prod_id IS NULL;

    -- Upsert: produto + cf_uid é chave única
    INSERT INTO product_videos (
      product_id, cloudflare_video_id, source_youtube_id, source_supplier,
      url_stream, url_hls, url_thumbnail, url_original,
      duration_seconds, cloudflare_status, video_type,
      is_primary, is_active, organization_id
    ) VALUES (
      v_prod_id, p_cf_stream_uid, p_youtube_id, 'SPOT',
      v_embed, v_hls, v_thumb, v_queue.youtube_url,
      p_duration_seconds, 'ready', 'product_video',
      true, true, '5db5aee1-064b-4ef4-9193-345dcd8274ea'
    )
    ON CONFLICT (product_id, cloudflare_video_id) DO UPDATE SET
      url_stream        = EXCLUDED.url_stream,
      url_hls           = EXCLUDED.url_hls,
      url_thumbnail     = EXCLUDED.url_thumbnail,
      cloudflare_status = 'ready',
      duration_seconds  = COALESCE(p_duration_seconds, product_videos.duration_seconds),
      updated_at        = now()
    RETURNING id INTO v_pv_id;

    -- 2. Atualizar products.videos JSONB cache
    UPDATE products p
    SET videos = (
      SELECT jsonb_agg(
        jsonb_build_object(
          'id',         pv2.id::text,
          'youtube_id', pv2.source_youtube_id,
          'cf_uid',     pv2.cloudflare_video_id,
          'embed_url',  pv2.url_stream,
          'hls_url',    pv2.url_hls,
          'thumbnail',  pv2.url_thumbnail,
          'watch_url',  pv2.url_original,
          'is_primary', pv2.is_primary,
          'plataforma', 'cloudflare_stream',
          'duration_s', pv2.duration_seconds
        )
        ORDER BY pv2.is_primary DESC NULLS LAST, pv2.created_at ASC
      )
      FROM product_videos pv2
      WHERE pv2.product_id = v_prod_id
        AND pv2.is_active = true
        AND pv2.cloudflare_status = 'ready'
        AND pv2.source_supplier = 'SPOT'
    ),
    updated_at = now()
    WHERE p.id = v_prod_id;

    v_linked := v_linked + 1;
  END LOOP;

  -- 3. Atualizar video_import_queue
  UPDATE video_import_queue
  SET
    cloudflare_video_id         = p_cf_stream_uid,
    cloudflare_hls              = v_hls,
    cloudflare_thumbnail        = v_thumb,
    cloudflare_embed            = v_embed,
    cloudflare_duration_seconds = p_duration_seconds,
    status                      = 'linked',
    completed_at                = now()
  WHERE id = p_queue_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'youtube_id',     p_youtube_id,
    'cf_stream_uid',  p_cf_stream_uid,
    'videos_updated', v_linked
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."fn_spot_link_video"("p_queue_id" "uuid", "p_youtube_id" "text", "p_cf_stream_uid" "text", "p_url_hls" "text", "p_url_thumbnail" "text", "p_url_embed" "text", "p_duration_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_spot_link_video"("p_queue_id" "uuid", "p_youtube_id" "text", "p_cf_stream_uid" "text", "p_url_hls" "text", "p_url_thumbnail" "text", "p_url_embed" "text", "p_duration_seconds" integer) IS 'Wrapper SPOT uniforme com mesma interface das funcoes fn_xbz/asia/sm_link_video. Internamente usa fluxo generico.';



CREATE OR REPLACE FUNCTION "public"."fn_spot_print_positions"("p_supplier_id" "uuid", "p_parent_ref" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_n integer;
BEGIN
  -- idempotente: limpa posições dos produtos-alvo e recria
  DELETE FROM public.product_print_positions ppp
   USING public.produtos_padronizacao pp
   WHERE ppp.product_id = pp.product_id AND pp.supplier_id = p_supplier_id
     AND (p_parent_ref IS NULL OR pp.supplier_reference = p_parent_ref);

  INSERT INTO public.product_print_positions
    (product_id, position_index, component, location, composed_location, area_label,
     technique_list, table_full_code, table_codes, table_codes_options, max_colors, handling_costs,
     area_image, component_image, location_image)
  SELECT p.id, g.n,
    public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>('Component'||g.n)),'')),
    public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>('Location'||g.n)),'')),
    public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>('ComposedLocation'||g.n)),'')),
    public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>('Area'||g.n)),'')),
    CASE WHEN nullif(btrim(spr.raw_data->>('CustomizationTypes'||g.n)),'') IS NOT NULL
         THEN to_jsonb(string_to_array(btrim(spr.raw_data->>('CustomizationTypes'||g.n)), ', ')) END,
    nullif(btrim(spr.raw_data->>('TableFullCode'||g.n)),''),
    nullif(btrim(spr.raw_data->>('TableCodes'||g.n)),''),
    CASE WHEN nullif(btrim(spr.raw_data->>('TableCodesOptions'||g.n)),'') IS NOT NULL
         THEN to_jsonb(string_to_array(btrim(spr.raw_data->>('TableCodesOptions'||g.n)), ', ')) END,
    CASE WHEN nullif(btrim(spr.raw_data->>('MaxColors'||g.n)),'') IS NOT NULL
         THEN to_jsonb(string_to_array(btrim(spr.raw_data->>('MaxColors'||g.n)), ', ')) END,
    CASE WHEN nullif(btrim(spr.raw_data->>('HandlingCosts'||g.n)),'') IS NOT NULL
         THEN to_jsonb(string_to_array(btrim(spr.raw_data->>('HandlingCosts'||g.n)), ', ')) END,
    nullif(btrim(spr.raw_data->>('Area'||g.n||'Image')),''),
    nullif(btrim(spr.raw_data->>('Component'||g.n||'Image')),''),
    nullif(btrim(spr.raw_data->>('Location'||g.n||'Image')),'')
  FROM public.products p
  JOIN public.produtos_padronizacao pp ON pp.product_id=p.id AND pp.supplier_id=p_supplier_id
  JOIN public.supplier_products_raw spr ON spr.id=pp.raw_id
  CROSS JOIN generate_series(1,8) g(n)
  WHERE (p_parent_ref IS NULL OR pp.supplier_reference=p_parent_ref)
    AND coalesce(nullif(btrim(spr.raw_data->>('Component'||g.n)),''),
                 nullif(btrim(spr.raw_data->>('Area'||g.n)),''),
                 nullif(btrim(spr.raw_data->>('Location'||g.n)),'')) IS NOT NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;


ALTER FUNCTION "public"."fn_spot_print_positions"("p_supplier_id" "uuid", "p_parent_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_spot_process_batch"("p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_sup uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_ref text; v_ok int := 0; v_err int := 0; v_errs jsonb := '[]'::jsonb;
BEGIN
  FOR v_ref IN
    SELECT DISTINCT raw_data->>'ProdReference' rr
    FROM public.supplier_products_raw
    WHERE supplier_id=v_sup AND raw_data->>'ProdReference' IS NOT NULL
    ORDER BY rr OFFSET p_offset LIMIT p_limit
  LOOP
    BEGIN
      PERFORM public.fn_spot_process_ref(v_ref); v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_err := v_err + 1; v_errs := v_errs || jsonb_build_object('ref',v_ref,'erro',SQLERRM);
    END;
  END LOOP;
  RETURN jsonb_build_object('processados',v_ok,'erros',v_err,'detalhe_erros',v_errs,'offset',p_offset,'limit',p_limit);
END $$;


ALTER FUNCTION "public"."fn_spot_process_batch"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_spot_process_ref"("p_parent_ref" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_sup uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_rep uuid; v_pad uuid; r record; v_vars int := 0;
  v_promo jsonb; v_promv jsonb; v_repl int; v_pos int; v_gold jsonb; v_recon int;
BEGIN
  PERFORM set_config('app.write_source','pipeline', true);
  PERFORM set_config('app.bulk_import_mode','true', true);

  -- 1. representante (raw com mais conteúdo) + padroniza PARENT via DE>PARA
  SELECT spr.id INTO v_rep FROM public.supplier_products_raw spr
   WHERE spr.supplier_id=v_sup AND spr.raw_data->>'ProdReference'=p_parent_ref
   ORDER BY length(spr.raw_data::text) DESC NULLS LAST, spr.id LIMIT 1;
  IF v_rep IS NULL THEN RETURN jsonb_build_object('success',false,'error','sem_raw','ref',p_parent_ref); END IF;
  PERFORM public.fn_standardize_raw(v_rep, p_parent_ref);
  -- NOTA: fn_standardize_raw (v2) usa fn_spot_split_list via DE>PARA para Materials.
  --       fn_spot_fix_materials removida desta etapa em 2026-06-06 (não mais necessária).

  -- 2. padroniza VARIANTES
  FOR r IN SELECT id FROM public.supplier_products_raw
            WHERE supplier_id=v_sup AND raw_data->>'ProdReference'=p_parent_ref LOOP
    PERFORM public.fn_standardize_variant(r.id); v_vars := v_vars + 1;
  END LOOP;

  -- 3. enrich Silver (taxonomia/SEO/extras/reparo encoding)
  --    Materials já correto pelo DE>PARA — fn_spot_fix_materials não é mais chamada.
  PERFORM public.fn_spot_silver_enrich(v_sup, p_parent_ref);

  -- 4. promove PARENT + VARIANTES (Silver → Gold)
  SELECT id INTO v_pad FROM public.produtos_padronizacao
   WHERE supplier_id=v_sup AND supplier_reference=p_parent_ref
   ORDER BY standardized_at DESC NULLS LAST LIMIT 1;
  v_promo  := public.fn_promote_padronizacao(v_pad);
  v_promv  := public.fn_promote_variants_of_parent(v_sup, p_parent_ref);

  -- 5. enrich Gold (variante + produto) + posições de impressão + reconciliação
  v_repl   := public.fn_spot_variant_repl_enrich(v_sup, p_parent_ref);
  v_pos    := public.fn_spot_print_positions(v_sup, p_parent_ref);
  v_gold   := public.fn_spot_gold_enrich(v_sup, p_parent_ref);
  v_recon  := public.fn_spot_reconcile_variant_to_legacy(v_sup, p_parent_ref);

  RETURN jsonb_build_object('success',true,'ref',p_parent_ref,'variantes',v_vars,
    'promote_parent',v_promo->'success','promote_variants',v_promv->'variantes_promovidas',
    'repl',v_repl,'print_positions',v_pos,'gold',v_gold,'reconciliadas',v_recon);
END $$;


ALTER FUNCTION "public"."fn_spot_process_ref"("p_parent_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_spot_reconcile_variant_to_legacy"("p_supplier_id" "uuid", "p_parent_ref" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_n integer;
BEGIN
  PERFORM set_config('app.bulk_import_mode','true', true);
  UPDATE public.variant_supplier_sources vss
  SET your_price      = f.your_price,
      next_quantity_1 = f.next_quantity_1, next_quantity_2 = f.next_quantity_2, next_quantity_3 = f.next_quantity_3,
      next_quantity_4 = f.next_quantity_4, next_quantity_5 = f.next_quantity_5, next_quantity_6 = f.next_quantity_6,
      next_date_1 = f.next_date_1, next_date_2 = f.next_date_2, next_date_3 = f.next_date_3,
      next_date_4 = f.next_date_4, next_date_5 = f.next_date_5, next_date_6 = f.next_date_6
  FROM public.product_variants lv
  JOIN public.products p ON p.id = lv.product_id AND p.supplier_id = p_supplier_id
  JOIN LATERAL (
      SELECT ppv.*
      FROM public.produtos_padronizacao_variantes ppv
      WHERE ppv.supplier_id = p_supplier_id
        AND ppv.parent_reference = p.supplier_reference
        AND ppv.color_code = lv.color_code
      ORDER BY ppv.variant_reference
      LIMIT 1
  ) f ON TRUE
  WHERE vss.variant_id = lv.id AND vss.supplier_id = p_supplier_id
    AND lv.is_active AND lv.color_code IS NOT NULL
    AND (p_parent_ref IS NULL OR p.supplier_reference = p_parent_ref);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;


ALTER FUNCTION "public"."fn_spot_reconcile_variant_to_legacy"("p_supplier_id" "uuid", "p_parent_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_spot_relink_family_images"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_relinked integer := 0;
BEGIN
  PERFORM set_config('app.bulk_import_mode', 'true', true);

  WITH candidatos AS (
    SELECT p.id,
      'spot-' || REPLACE(LOWER(SPLIT_PART(SPLIT_PART(p.primary_image_url,'/produtos/',2),'.',1)), '-', '_') AS cf_id
    FROM products p
    WHERE p.supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
      AND p.is_active = true
      AND p.primary_image_url IS NOT NULL
      AND p.primary_image_url NOT LIKE '%imagedelivery%'
      AND p.primary_image_url LIKE '%spotgifts.com.br%'
  ),
  validos AS (
    SELECT c.id, c.cf_id
    FROM candidatos c
    WHERE EXISTS (SELECT 1 FROM product_images pi 
                  WHERE pi.cloudflare_image_id = c.cf_id AND pi.is_active = true)
  ),
  updated AS (
    UPDATE products p
    SET primary_image_url = 'https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/' || v.cf_id || '/public',
        og_image_url      = 'https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/' || v.cf_id || '/public',
        locked_fields = (SELECT ARRAY(SELECT DISTINCT unnest(COALESCE(p.locked_fields,'{}') || ARRAY['primary_image_url']))),
        updated_at = NOW()
    FROM validos v
    WHERE p.id = v.id
    RETURNING p.id
  )
  SELECT COUNT(*) INTO v_relinked FROM updated;

  RETURN jsonb_build_object('relinked', v_relinked, 'ts', now());
END;
$$;


ALTER FUNCTION "public"."fn_spot_relink_family_images"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_spot_silver_enrich"("p_supplier_id" "uuid", "p_parent_ref" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_n integer;
BEGIN
  UPDATE public.produtos_padronizacao pp
  SET supplier_type = COALESCE(
        (SELECT m.canonical_type FROM public.spot_typecode_map m 
         WHERE m.legacy_code = nullif(btrim(spr.raw_data->>'TypeCode'),'')),
        nullif(btrim(spr.raw_data->>'Type'),'')
      ),
      supplier_type_code = COALESCE(
        (SELECT m.canonical_code FROM public.spot_typecode_map m 
         WHERE m.legacy_code = nullif(btrim(spr.raw_data->>'TypeCode'),'')),
        nullif(btrim(spr.raw_data->>'TypeCode'),'')
      ),
      supplier_subtype      = nullif(btrim(spr.raw_data->>'SubType'),''),
      supplier_subtype_code = nullif(btrim(spr.raw_data->>'SubTypeCode'),''),
      -- DISTINCT elimina duplicatas de CSV (ex: "Stockout,Stockout,SPOT")
      supplier_categories   = (SELECT to_jsonb(array_agg(DISTINCT btrim(e))) 
                               FROM unnest(string_to_array(spr.raw_data->>'Catalogs', ',')) e 
                               WHERE btrim(e) <> ''),
      supplier_seo_name              = public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>'SEOName'),'')),
      supplier_seo_short_description = public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>'SEOShortDescription'),'')),
      certificates       = (SELECT to_jsonb(array_agg(btrim(e))) FROM unnest(string_to_array(spr.raw_data->>'Certificates', ',')) e WHERE btrim(e) <> ''),
      certificate_files  = (SELECT to_jsonb(array_agg(btrim(e))) FROM unnest(string_to_array(spr.raw_data->>'CertificateFiles', ',')) e WHERE btrim(e) <> ''),
      related_references = (SELECT to_jsonb(array_agg(btrim(e))) FROM unnest(string_to_array(spr.raw_data->>'RelatedReferences', ',')) e WHERE btrim(e) <> ''),
      is_seasonal         = public.fn_safe_bool(spr.raw_data->>'IsSeasonal'),
      pvc_free            = public.fn_safe_bool(spr.raw_data->>'PvcFree'),
      is_stockout         = public.fn_safe_bool(spr.raw_data->>'IsStockOut'),
      is_new              = public.fn_safe_bool(spr.raw_data->>'NewProduct'),
      is_textil           = public.fn_safe_bool(spr.raw_data->>'IsTextil'),
      is_online_exclusive = public.fn_safe_bool(spr.raw_data->>'OnlineExclusive'),
      has_colors          = public.fn_safe_bool(spr.raw_data->>'HasColors'),
      has_sizes           = public.fn_safe_bool(spr.raw_data->>'HasSizes'),
      name               = public.fn_fix_mojibake(pp.name),
      short_description  = public.fn_fix_mojibake(pp.short_description),
      description        = public.fn_fix_mojibake(pp.description),
      combined_sizes     = public.fn_fix_mojibake(pp.combined_sizes),
      dimensions_display = public.fn_fix_mojibake(pp.dimensions_display),
      updated_at = now()
  FROM public.supplier_products_raw spr
  WHERE pp.raw_id = spr.id
    AND pp.supplier_id = p_supplier_id
    AND (p_parent_ref IS NULL OR pp.supplier_reference = p_parent_ref);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;


ALTER FUNCTION "public"."fn_spot_silver_enrich"("p_supplier_id" "uuid", "p_parent_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_spot_split_list"("p" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  WITH prot AS (
    SELECT regexp_replace(
             public.fn_fix_mojibake(COALESCE(p,'')),
             '(^|[[:space:],.])([[:alpha:]])\.[[:space:]]+',
             '\1\2.' || chr(1),
             'g') AS s
  )
  SELECT to_jsonb(
           COALESCE(
             array_agg(
               regexp_replace(                          -- v3: expande "C. " → "Couro " no início do elemento
                 replace(btrim(e), chr(1), ' '),
                 '^[Cc]\. ',
                 'Couro ',
                 'i'
               )
             ) FILTER (WHERE btrim(replace(e, chr(1), ' ')) <> ''),
             ARRAY[]::text[]))
  FROM prot, unnest(regexp_split_to_array(prot.s, '[.,][[:space:]]+')) AS e;
$$;


ALTER FUNCTION "public"."fn_spot_split_list"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_spot_stock_fast_sync"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sid      CONSTANT uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_vss      int := 0;
  v_variants int := 0;
  v_fixed    int := 0;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_spot_stock_fast_sync')::bigint) THEN
    RETURN jsonb_build_object('skipped','lock_ocupado','synced_at',now());
  END IF;

  -- PASSO 1: Bronze → VSS (6 janelas brutas, sem filtro — auditoria)
  WITH bronze AS (
    SELECT spr.supplier_sku AS sku,
      COALESCE((spr.stock_data->>'Quantity')::int,0) AS qty,
      NULLIF(spr.stock_data->>'NextQuantity1','')::int AS nq1, NULLIF(spr.stock_data->>'NextDate1','')::date AS nd1,
      NULLIF(spr.stock_data->>'NextQuantity2','')::int AS nq2, NULLIF(spr.stock_data->>'NextDate2','')::date AS nd2,
      NULLIF(spr.stock_data->>'NextQuantity3','')::int AS nq3, NULLIF(spr.stock_data->>'NextDate3','')::date AS nd3,
      NULLIF(spr.stock_data->>'NextQuantity4','')::int AS nq4, NULLIF(spr.stock_data->>'NextDate4','')::date AS nd4,
      NULLIF(spr.stock_data->>'NextQuantity5','')::int AS nq5, NULLIF(spr.stock_data->>'NextDate5','')::date AS nd5,
      NULLIF(spr.stock_data->>'NextQuantity6','')::int AS nq6, NULLIF(spr.stock_data->>'NextDate6','')::date AS nd6
    FROM supplier_products_raw spr
    WHERE spr.supplier_id=v_sid AND spr.stock_data IS NOT NULL AND spr.stock_data?'Quantity'
  )
  UPDATE variant_supplier_sources vss
  SET quantity=b.qty, stock_main_warehouse=b.qty,
      next_quantity_1=b.nq1, next_date_1=b.nd1, next_quantity_2=b.nq2, next_date_2=b.nd2,
      next_quantity_3=b.nq3, next_date_3=b.nd3, next_quantity_4=b.nq4, next_date_4=b.nd4,
      next_quantity_5=b.nq5, next_date_5=b.nd5, next_quantity_6=b.nq6, next_date_6=b.nd6,
      source='bronze_spot', last_synced_at=now(), updated_at=now()
  FROM bronze b WHERE vss.supplier_sku=b.sku AND vss.supplier_id=v_sid;
  GET DIAGNOSTICS v_vss = ROW_COUNT;

  -- PASSO 2: Bronze → PV (GOLD) com GUARD: só datas > CURRENT_DATE chegam ao Gold
  PERFORM set_config('app.bulk_import_mode','true',true);
  WITH bronze AS (
    SELECT supplier_sku AS sku,
           COALESCE((stock_data->>'Quantity')::int,0) AS qty,
           -- Guard anti-stale: datas passadas → NULL no PV (VSS mantém o bruto)
           CASE WHEN NULLIF(stock_data->>'NextDate1','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextQuantity1','')::int ELSE NULL END AS nq1,
           CASE WHEN NULLIF(stock_data->>'NextDate1','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextDate1','')::date    ELSE NULL END AS nd1,
           CASE WHEN NULLIF(stock_data->>'NextDate2','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextQuantity2','')::int ELSE NULL END AS nq2,
           CASE WHEN NULLIF(stock_data->>'NextDate2','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextDate2','')::date    ELSE NULL END AS nd2,
           CASE WHEN NULLIF(stock_data->>'NextDate3','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextQuantity3','')::int ELSE NULL END AS nq3,
           CASE WHEN NULLIF(stock_data->>'NextDate3','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextDate3','')::date    ELSE NULL END AS nd3,
           CASE WHEN NULLIF(stock_data->>'NextDate4','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextQuantity4','')::int ELSE NULL END AS nq4,
           CASE WHEN NULLIF(stock_data->>'NextDate4','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextDate4','')::date    ELSE NULL END AS nd4,
           CASE WHEN NULLIF(stock_data->>'NextDate5','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextQuantity5','')::int ELSE NULL END AS nq5,
           CASE WHEN NULLIF(stock_data->>'NextDate5','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextDate5','')::date    ELSE NULL END AS nd5,
           CASE WHEN NULLIF(stock_data->>'NextDate6','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextQuantity6','')::int ELSE NULL END AS nq6,
           CASE WHEN NULLIF(stock_data->>'NextDate6','')::date > CURRENT_DATE
                THEN NULLIF(stock_data->>'NextDate6','')::date    ELSE NULL END AS nd6
    FROM supplier_products_raw
    WHERE supplier_id=v_sid AND stock_data IS NOT NULL AND stock_data?'Quantity'
  )
  UPDATE product_variants pv
  SET stock_quantity  = b.qty,
      next_quantity_1 = b.nq1, next_date_1 = b.nd1,
      next_quantity_2 = b.nq2, next_date_2 = b.nd2,
      next_quantity_3 = b.nq3, next_date_3 = b.nd3,
      next_quantity_4 = b.nq4, next_date_4 = b.nd4,
      next_quantity_5 = b.nq5, next_date_5 = b.nd5,
      next_quantity_6 = b.nq6, next_date_6 = b.nd6,
      last_sync_at    = now()
  FROM bronze b
  WHERE pv.supplier_sku=b.sku AND pv.is_active=true
    AND (pv.stock_quantity  IS DISTINCT FROM b.qty
      OR pv.next_quantity_1 IS DISTINCT FROM b.nq1 OR pv.next_date_1 IS DISTINCT FROM b.nd1
      OR pv.next_quantity_2 IS DISTINCT FROM b.nq2 OR pv.next_date_2 IS DISTINCT FROM b.nd2
      OR pv.next_quantity_3 IS DISTINCT FROM b.nq3 OR pv.next_date_3 IS DISTINCT FROM b.nd3
      OR pv.next_quantity_4 IS DISTINCT FROM b.nq4 OR pv.next_date_4 IS DISTINCT FROM b.nd4
      OR pv.next_quantity_5 IS DISTINCT FROM b.nq5 OR pv.next_date_5 IS DISTINCT FROM b.nd5
      OR pv.next_quantity_6 IS DISTINCT FROM b.nq6 OR pv.next_date_6 IS DISTINCT FROM b.nd6);
  GET DIAGNOSTICS v_variants = ROW_COUNT;

  -- PASSO 3: is_stockout
  UPDATE products p SET is_stockout=(p.stock_quantity<=0),updated_at=now()
  WHERE p.supplier_id=v_sid AND p.is_active=true
    AND p.is_stockout IS DISTINCT FROM (p.stock_quantity<=0);
  GET DIAGNOSTICS v_fixed = ROW_COUNT;

  RETURN jsonb_build_object(
    'vss_updated',v_vss,'variants_updated',v_variants,'stockout_corrected',v_fixed,
    'source','bronze_spot',
    'guard_pv','datas_passadas_NAO_propagadas_ao_gold',
    'fixes',jsonb_build_array('B03','B05','FINAL-01-GUARD'), 'janelas_pv',6, 'synced_at',now()
  );
END;
$$;


