CREATE OR REPLACE FUNCTION "public"."fn_standardize_kit_component"("p_raw_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_raw          kit_component_enrichment_raw%ROWTYPE;
  v_pad_id       UUID;
  v_rd           JSONB;
  v_factor       NUMERIC;
  v_shape        VARCHAR(30);
  v_is_pkg       BOOLEAN;
  v_comp_type    VARCHAR(30);
  v_color        VARCHAR(50);
  v_len          INTEGER; v_wid INTEGER; v_hgt INTEGER;
  v_diam         INTEGER; v_wgt INTEGER;
BEGIN
  SELECT * INTO v_raw FROM kit_component_enrichment_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'kit_component_enrichment_raw % não encontrado', p_raw_id;
  END IF;
  IF v_raw.processed THEN
    RETURN v_raw.promoted_padronizacao_id;
  END IF;

  v_rd     := v_raw.raw_data;
  v_factor := CASE WHEN (v_rd->>'unit') = 'cm' THEN 10 ELSE 1 END;

  v_len  := NULLIF(ROUND(v_factor * COALESCE(
    (v_rd->>'length_mm')::NUMERIC,(v_rd->>'length')::NUMERIC,
    (v_rd->>'profundidade_mm')::NUMERIC,(v_rd->>'profundidade')::NUMERIC,
    (v_rd->>'comprimento_mm')::NUMERIC,(v_rd->>'comprimento')::NUMERIC)), 0)::INTEGER;
  v_wid  := NULLIF(ROUND(v_factor * COALESCE(
    (v_rd->>'width_mm')::NUMERIC,(v_rd->>'width')::NUMERIC,
    (v_rd->>'largura_mm')::NUMERIC,(v_rd->>'largura')::NUMERIC)), 0)::INTEGER;
  v_hgt  := NULLIF(ROUND(v_factor * COALESCE(
    (v_rd->>'height_mm')::NUMERIC,(v_rd->>'height')::NUMERIC,
    (v_rd->>'altura_mm')::NUMERIC,(v_rd->>'altura')::NUMERIC)), 0)::INTEGER;
  v_diam := NULLIF(ROUND(v_factor * COALESCE(
    (v_rd->>'diameter_mm')::NUMERIC,(v_rd->>'diameter')::NUMERIC,
    (v_rd->>'diametro_mm')::NUMERIC,(v_rd->>'diametro')::NUMERIC)), 0)::INTEGER;
  v_wgt  := NULLIF(COALESCE(
    (v_rd->>'weight_g')::NUMERIC,(v_rd->>'peso_g')::NUMERIC,
    (v_rd->>'peso')::NUMERIC), 0)::INTEGER;

  -- NOVO: cor do item (EN/PT, trim, vazio→NULL, truncado a 50)
  v_color := LEFT(NULLIF(TRIM(COALESCE(
    v_rd->>'color', v_rd->>'cor', v_rd->>'colour', v_rd->>'cor_item')),''),50);

  v_comp_type := LEFT(COALESCE(v_rd->>'component_type_code', v_raw.raw_component_type), 30);

  -- REGRA SHAPE (v2: têxteis planos classificados como 'flat')
  v_shape := CASE
    WHEN v_diam IS NOT NULL                                          THEN 'cylindrical'
    WHEN v_comp_type IN ('AVENTAL','TOALHA','FAIXA_ELASTICA',
                         'MASCARA_DORMIR','CAPA_CHUVA','ALMOFADA',
                         'LUVA','MOUSE_PAD')                        THEN 'flat'
    WHEN v_comp_type IN ('BOLSA','MOCHILA','SACOLA','ECOBAG',
                         'NECESSAIRE','BOLSA_TERMICA')               THEN 'irregular'
    WHEN v_hgt IS NOT NULL AND v_hgt < 10                            THEN 'flat'
    ELSE 'rectangular'
  END;

  v_is_pkg := COALESCE(
    (v_rd->>'is_packaging')::BOOLEAN,
    v_comp_type IN ('CAIXA','ESTOJO_NYLON','NECESSAIRE','MOCHILA','BOLSA_PRESENTE',
                    'ESTOJO_ALUMINIO','ESTOJO_BAMBU','ESTOJO_PU','ESTOJO',
                    'ESTOJO_COURO','ESTOJO_MADEIRA','ESTOJO_KRAFT','ESTOJO_CORTICA',
                    'ESTOJO_TNT','CAIXA_XADREZ')
  );

  INSERT INTO kit_component_padronizacao (
    kit_product_id, kit_component_id, raw_id,
    component_name, component_type_code, color, shape_type,
    length_mm, width_mm, height_mm, diameter_mm, weight_g,
    is_packaging,
    pkg_ext_length_mm, pkg_ext_width_mm, pkg_ext_height_mm,
    pkg_int_length_mm, pkg_int_width_mm, pkg_int_height_mm,
    pkg_int_diameter_mm, pkg_weight_g,
    pkg_material, pkg_color, pkg_finish, pkg_type_code,
    allows_personalization, quantity,
    enrichment_source, enrichment_confidence,
    padronizacao_status, notes
  ) VALUES (
    v_raw.kit_product_id, v_raw.kit_component_id, p_raw_id,
    COALESCE(v_rd->>'component_name', v_raw.raw_component_name, 'Componente sem nome'),
    v_comp_type, v_color, v_shape,
    v_len, v_wid, v_hgt, v_diam, v_wgt,
    v_is_pkg,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_ext_length_mm')::NUMERIC),0)::INTEGER END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_ext_width_mm')::NUMERIC),0)::INTEGER  END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_ext_height_mm')::NUMERIC),0)::INTEGER END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_int_length_mm')::NUMERIC),0)::INTEGER END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_int_width_mm')::NUMERIC),0)::INTEGER  END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_int_height_mm')::NUMERIC),0)::INTEGER END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_int_diameter_mm')::NUMERIC),0)::INTEGER END,
    CASE WHEN v_is_pkg THEN NULLIF((v_rd->>'pkg_weight_g')::INTEGER,0) END,
    CASE WHEN v_is_pkg THEN v_rd->>'pkg_material' END,
    CASE WHEN v_is_pkg THEN v_rd->>'pkg_color' END,
    CASE WHEN v_is_pkg THEN v_rd->>'pkg_finish' END,
    CASE WHEN v_is_pkg THEN LEFT(v_comp_type,30) END,
    COALESCE((v_rd->>'allows_personalization')::BOOLEAN, TRUE),
    COALESCE((v_rd->>'quantity')::INTEGER, 1),
    v_raw.source::VARCHAR(50), v_raw.source_confidence,
    'pending', v_rd->>'notes'
  )
  RETURNING id INTO v_pad_id;

  UPDATE kit_component_enrichment_raw
  SET processed = TRUE, processed_at = NOW(),
      promoted_padronizacao_id = v_pad_id, updated_at = NOW()
  WHERE id = p_raw_id;

  RETURN v_pad_id;
EXCEPTION WHEN OTHERS THEN
  UPDATE kit_component_enrichment_raw
  SET process_errors = jsonb_build_object('error', SQLERRM, 'at', NOW()), updated_at = NOW()
  WHERE id = p_raw_id;
  RAISE;
END;
$$;


ALTER FUNCTION "public"."fn_standardize_kit_component"("p_raw_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_standardize_kit_component"("p_raw_id" "uuid") IS 'BRONZE→PRATA: Normaliza unidades (mm/g), infere shape_type,
   separa campos de embalagem, insere em kit_component_padronizacao com status=pending.
   Idempotente: já processado retorna promoted_padronizacao_id existente.';



CREATE OR REPLACE FUNCTION "public"."fn_standardize_parent"("p_supplier_id" "uuid", "p_parent_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_rep uuid; v_res jsonb;
BEGIN
  -- representante: a raw com mais conteúdo (maior raw_data) do grupo; empate por menor id
  SELECT pv.raw_id INTO v_rep
  FROM public.produtos_padronizacao_variantes pv
  WHERE pv.supplier_id=p_supplier_id AND pv.parent_reference=p_parent_reference AND pv.raw_id IS NOT NULL
  ORDER BY length((SELECT raw_data::text FROM public.supplier_products_raw WHERE id=pv.raw_id)) DESC NULLS LAST, pv.raw_id
  LIMIT 1;
  IF v_rep IS NULL THEN RETURN jsonb_build_object('success',false,'error','sem_representante','parent',p_parent_reference); END IF;
  v_res := public.fn_standardize_raw(v_rep, p_parent_reference);
  -- Enriquecimento ASIA (dims/peso/caixa-master/galeria) pós-padronização do pai
  IF p_supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'::uuid THEN
    PERFORM public.fn_asia_enrich_parent(p_supplier_id, p_parent_reference);
  END IF;
  RETURN v_res;
END;
$$;


ALTER FUNCTION "public"."fn_standardize_parent"("p_supplier_id" "uuid", "p_parent_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_standardize_raw"("p_raw_id" "uuid", "p_override_reference" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  r          public.supplier_products_raw%ROWTYPE;
  m          RECORD;
  v_val      text; v_tx text; v_path text;
  v_assigns  jsonb := '{}'::jsonb;
  v_errs     jsonb := '[]'::jsonb;
  v_ncm text; v_ncm_raw text;
  v_pad_id uuid; v_ref text;
  v_status public.produtos_padronizacao_status;
  v_final_name text;
  v_money numeric;
  v_cols text[] := ARRAY[
    'name','description','short_description','cost_price','suggested_price','stock_quantity',
    'primary_image_url','images','ncm_code','weight_g','height_cm','width_cm','length_cm',
    'dimensions_display','box_length_cm','box_width_cm','box_height_cm','box_weight_kg',
    'box_volume_cm3','box_quantity','box_inner_quantity','brand','packing_type','repacking_type',
    'capacities','capacity_ml','min_quantity','ipi_rate','engraving_type','is_active',
    'product_type','origin_country','combined_sizes','box_image',
    'is_textil','is_stockout','is_online_exclusive','is_new','pvc_free','is_seasonal','has_colors','has_sizes',
    'allows_personalization','tags','materials','meta_keywords'
  ];
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado'); END IF;
  v_ref := COALESCE(NULLIF(TRIM(p_override_reference),''), r.supplier_reference);

  FOR m IN
    SELECT source_field, source_path, target_field, transform_type, transform_config, source_unit, target_unit
    FROM public.supplier_field_mappings
    WHERE supplier_id=r.supplier_id AND target_table='products' AND is_active=TRUE AND target_field=ANY(v_cols)
    ORDER BY priority NULLS LAST
  LOOP
    BEGIN
      IF m.source_path IS NOT NULL AND m.source_path <> '' THEN
        v_path := regexp_replace(m.source_path, E'^\\$\\.?', '');
        v_val  := r.raw_data #>> string_to_array(v_path, '.');
      ELSE
        v_val := r.raw_data ->> m.source_field;
      END IF;

      IF v_val IS NULL THEN CONTINUE; END IF;

      v_tx := public.fn_apply_transform(
        v_val, m.transform_type, m.transform_config,
        m.source_unit, m.target_unit,
        r.supplier_id
      );

      v_assigns := v_assigns || jsonb_build_object(m.target_field, v_tx);
    EXCEPTION WHEN OTHERS THEN
      v_errs := v_errs || jsonb_build_object('field', m.target_field, 'error', SQLERRM);
    END;
  END LOOP;

  -- FALLBACK genérico de name (2026-06-11)
  IF NULLIF(TRIM(v_assigns->>'name'),'') IS NULL THEN
    v_val := COALESCE(
      NULLIF(TRIM(r.raw_data->>'nome'),''),
      NULLIF(TRIM(r.raw_data->>'Nome'),''),
      NULLIF(TRIM(r.raw_data->>'name'),''),
      NULLIF(TRIM(r.raw_data->>'Name'),''),
      NULLIF(TRIM(r.raw_data->>'titulo'),''),
      NULLIF(TRIM(r.raw_data->>'Titulo'),''));
    IF v_val IS NOT NULL THEN
      v_assigns := v_assigns || jsonb_build_object('name', v_val);
    END IF;
  END IF;

  -- CLAMP money (2026-06-11): fora de (0, 99999999.99] não entra na Silver
  FOREACH v_val IN ARRAY ARRAY['cost_price','suggested_price'] LOOP
    IF v_assigns ? v_val THEN
      v_money := public.fn_safe_num(v_assigns->>v_val);
      IF v_money IS NOT NULL AND (v_money < 0 OR v_money > 99999999.99) THEN
        v_assigns := v_assigns - v_val;
        v_errs := v_errs || jsonb_build_object('field', v_val, 'error',
          'valor_fora_do_dominio: '||v_money::text);
      END IF;
    END IF;
  END LOOP;

  -- NCM: normaliza; inválido é removido
  v_ncm_raw := COALESCE(v_assigns->>'ncm_code', r.raw_data->>'Ncm', r.raw_data->>'ncm');
  IF v_ncm_raw IS NOT NULL THEN
    v_ncm := public.fn_normalize_ncm(v_ncm_raw);
    IF v_ncm IS NOT NULL THEN
      v_assigns := v_assigns || jsonb_build_object('ncm_code', v_ncm);
    ELSE
      v_assigns := v_assigns - 'ncm_code';
    END IF;
  END IF;

  SELECT id INTO v_pad_id FROM public.produtos_padronizacao
  WHERE supplier_id = r.supplier_id AND supplier_reference = v_ref;

  IF v_pad_id IS NULL THEN
    INSERT INTO public.produtos_padronizacao
      (supplier_id, supplier_reference, raw_id, status)
    VALUES (r.supplier_id, v_ref, r.id, 'pending')
    RETURNING id INTO v_pad_id;
  END IF;

  -- BRAND PERMANENTE
  v_assigns := v_assigns || jsonb_build_object(
    'brand', public.fn_brand_from_supplier(r.supplier_id)
  );

  -- Clamp: stock negativo → 0
  IF (v_assigns->>'stock_quantity') IS NOT NULL
    AND public.fn_safe_num(v_assigns->>'stock_quantity') IS NOT NULL
    AND public.fn_safe_num(v_assigns->>'stock_quantity') < 0 THEN
    v_assigns := v_assigns || jsonb_build_object('stock_quantity', 0);
  END IF;

  UPDATE public.produtos_padronizacao
  SET
    name               = COALESCE(public.fn_normalize_product_name(v_assigns->>'name'), name),
    description        = COALESCE((v_assigns->>'description')::text,                                   description),
    short_description  = COALESCE((v_assigns->>'short_description')::text,                             short_description),
    cost_price         = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'cost_price'),      0),        cost_price),
    suggested_price    = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'suggested_price'), 0),        suggested_price),
    stock_quantity     = COALESCE(public.fn_safe_int(v_assigns->>'stock_quantity'),                     stock_quantity),
    primary_image_url  = COALESCE((v_assigns->>'primary_image_url')::text,                             primary_image_url),
    images             = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'images'),                       images),
    ncm_code           = COALESCE((v_assigns->>'ncm_code')::text,                                      ncm_code),
    weight_g           = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'weight_g'),  0),              weight_g),
    height_cm          = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'height_cm'), 0),              height_cm),
    width_cm           = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'width_cm'),  0),              width_cm),
    length_cm          = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'length_cm'), 0),              length_cm),
    dimensions_display = COALESCE((v_assigns->>'dimensions_display')::text,                            dimensions_display),
    box_length_cm      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_length_cm'), 0),          box_length_cm),
    box_width_cm       = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_width_cm'),  0),          box_width_cm),
    box_height_cm      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_height_cm'), 0),          box_height_cm),
    box_weight_kg      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_weight_kg'), 0),          box_weight_kg),
    box_volume_cm3     = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_volume_cm3'),0),          box_volume_cm3),
    box_quantity       = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'box_quantity'), 0),           box_quantity),
    box_inner_quantity = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'box_inner_quantity'), 0),     box_inner_quantity),
    brand              = COALESCE((v_assigns->>'brand')::text,                                          brand),
    packing_type       = COALESCE((v_assigns->>'packing_type')::text,                                   packing_type),
    repacking_type     = COALESCE((v_assigns->>'repacking_type')::text,                                 repacking_type),
    capacities         = COALESCE((v_assigns->>'capacities')::text,                                     capacities),
    capacity_ml        = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'capacity_ml'), 0),            capacity_ml),
    min_quantity       = COALESCE(public.fn_safe_int(v_assigns->>'min_quantity'),                       min_quantity),
    ipi_rate           = COALESCE(public.fn_safe_num(v_assigns->>'ipi_rate'),                           ipi_rate),
    engraving_type     = COALESCE((v_assigns->>'engraving_type')::text,                                 engraving_type),
    is_active          = COALESCE(public.fn_safe_bool(v_assigns->>'is_active'),                         is_active),
    product_type       = COALESCE((v_assigns->>'product_type')::text,                                   product_type),
    origin_country     = COALESCE((v_assigns->>'origin_country')::text,                                 origin_country),
    combined_sizes     = COALESCE((v_assigns->>'combined_sizes')::text,                                 combined_sizes),
    box_image          = COALESCE((v_assigns->>'box_image')::text,                                      box_image),
    is_textil              = COALESCE(public.fn_safe_bool(v_assigns->>'is_textil'),              is_textil),
    is_stockout            = COALESCE(public.fn_safe_bool(v_assigns->>'is_stockout'),            is_stockout),
    is_online_exclusive    = COALESCE(public.fn_safe_bool(v_assigns->>'is_online_exclusive'),    is_online_exclusive),
    is_new                 = COALESCE(public.fn_safe_bool(v_assigns->>'is_new'),                 is_new),
    has_colors             = COALESCE(public.fn_safe_bool(v_assigns->>'has_colors'),             has_colors),
    has_sizes              = COALESCE(public.fn_safe_bool(v_assigns->>'has_sizes'),              has_sizes),
    allows_personalization = COALESCE(public.fn_safe_bool(v_assigns->>'allows_personalization'), allows_personalization),
    tags               = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'tags'),                         tags),
    materials          = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'materials'),                    materials),
    meta_keywords      = COALESCE(public.fn_safe_text_arr(v_assigns->>'meta_keywords'),                 meta_keywords),
    raw_id             = r.id,
    updated_at         = now()
  WHERE id = v_pad_id
  RETURNING name INTO v_final_name;

  -- STATUS EXPLÍCITO (2026-06-11): name ⇒ standardized; sem name ⇒ rejected.
  IF v_final_name IS NOT NULL AND TRIM(v_final_name) <> '' THEN
    v_status := 'standardized';
  ELSE
    v_status := 'rejected';
    v_errs := v_errs || jsonb_build_object('field','name','error',
      'name_ausente: nenhum mapping/fallback produziu nome');
  END IF;

  UPDATE public.produtos_padronizacao
  SET status            = v_status,
      standardized_at   = CASE WHEN v_status='standardized' THEN now() ELSE standardized_at END,
      validation_errors = CASE WHEN jsonb_array_length(v_errs) > 0 THEN v_errs ELSE NULL END
  WHERE id = v_pad_id;

  PERFORM public.fn_enrich_padronizacao(v_pad_id);

  RETURN jsonb_build_object(
    'success', v_status = 'standardized', 'pad_id', v_pad_id,
    'status', v_status, 'fields_set', v_assigns,
    'errors', v_errs
  );
END;
$_$;


ALTER FUNCTION "public"."fn_standardize_raw"("p_raw_id" "uuid", "p_override_reference" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_standardize_raw"("p_raw_id" "uuid", "p_override_reference" "text") IS 'Bronze->Silver (produto/pai) via de-para supplier_field_mappings + fallback generico de name. 2026-06-11: clamp money (0,1e8]; sem name => rejected + validation_errors + success=false (antes ficava pending invisivel com success=true).';



CREATE OR REPLACE FUNCTION "public"."fn_standardize_supplier"("p_supplier_id" "uuid", "p_limit" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_raw         RECORD;
  v_par         RECORD;
  v_vres        jsonb;
  v_pres        jsonb;
  v_variants    integer := 0;
  v_parents     integer := 0;
  v_erros       integer := 0;
  v_err_amostra jsonb   := '[]'::jsonb;
  v_touched     text[]  := ARRAY[]::text[];
  v_t0          timestamptz := clock_timestamp();
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;

  IF NOT pg_try_advisory_xact_lock(hashtext('fn_standardize_supplier:'||p_supplier_id::text)::bigint) THEN
    RETURN jsonb_build_object('success', true, 'skipped', 'lock_ocupado',
                              'supplier_id', p_supplier_id);
  END IF;

  PERFORM set_config('app.write_source', 'pipeline', true);

  FOR v_raw IN
      SELECT id, supplier_reference
      FROM public.supplier_products_raw
      WHERE supplier_id = p_supplier_id
        AND status = 'pending'
      ORDER BY imported_at NULLS LAST
      LIMIT p_limit
      FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      v_vres := public.fn_standardize_variant(v_raw.id);
      IF NOT COALESCE((v_vres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'variante_falhou:%', COALESCE(v_vres->>'error', 'desconhecido');
      END IF;
      v_variants := v_variants + 1;
      v_touched  := array_append(v_touched, COALESCE(v_vres->>'parent', ''));
    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra
          || jsonb_build_object('raw_id', v_raw.id, 'stage', 'variant', 'erro', SQLERRM);
      END IF;
      BEGIN
        UPDATE public.supplier_products_raw r
           SET process_errors = jsonb_build_object(
                 'stage','standardize','erro', SQLERRM, 'at', now())
         WHERE r.id = v_raw.id AND r.status IN ('pending','failed');
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END;
  END LOOP;

  FOR v_par IN
      SELECT DISTINCT parent_reference
      FROM public.produtos_padronizacao_variantes
      WHERE supplier_id = p_supplier_id
        AND parent_reference = ANY(v_touched)
        AND NULLIF(parent_reference, '') IS NOT NULL
  LOOP
    BEGIN
      v_pres := public.fn_standardize_parent(p_supplier_id, v_par.parent_reference);
      IF NOT COALESCE((v_pres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'pai_falhou_status_%: %', COALESCE(v_pres->>'status','?'),
          COALESCE(v_pres->>'error', v_pres->'errors'->0->>'error', 'sem_detalhe');
      END IF;
      v_parents := v_parents + 1;
    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra
          || jsonb_build_object('parent', v_par.parent_reference, 'stage', 'parent', 'erro', SQLERRM);
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true, 'supplier_id', p_supplier_id,
    'variantes_padronizadas', v_variants,
    'pais_padronizados', v_parents,
    'erros', v_erros, 'amostra_erros', v_err_amostra,
    'segundos', round(extract(epoch FROM clock_timestamp() - v_t0)::numeric, 1));
END $$;


ALTER FUNCTION "public"."fn_standardize_supplier"("p_supplier_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_standardize_supplier"("p_supplier_id" "uuid", "p_limit" integer) IS 'Pipeline Medallion (Fase 1->2): Bronze->Silver de-para em lote por fornecedor. Padroniza variantes (fn_standardize_variant) e depois os pais (fn_standardize_parent). Par simetrico de fn_promote_supplier (Fase 2->3). Idempotente; advisory lock por fornecedor.';



CREATE OR REPLACE FUNCTION "public"."fn_standardize_variant"("p_raw_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  r             public.supplier_products_raw%ROWTYPE;
  v_parent      text; v_code text; v_apiid text; v_cname text; v_chex text;
  v_col         RECORD;
  v_sku         text; v_supplier_sku text; v_stock integer; v_cost numeric; v_var_id uuid;
  v_fname       text; v_fcode text; v_fhex text; v_canonical_id uuid;
  v_cp1 numeric; v_cp2 numeric; v_cp3 numeric; v_cp4 numeric; v_cp5 numeric;
  v_mq1 int;    v_mq2 int;    v_mq3 int;    v_mq4 int;    v_mq5 int;
  v_nq1 int;    v_nq2 int;    v_nq3 int;
  v_nd1 date;   v_nd2 date;   v_nd3 date;
  v_mult        int;
  v_thumb       text;
  v_images      jsonb;
  v_videos      jsonb;
  v_cap_ml      int;
  -- M1/M2 2026-06-11: tamanho têxtil canônico + dimensões por SKU
  v_size_code   text;
  v_slen        numeric;
  v_swid        numeric;
  v_SPOT        uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_XBZ         uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
  v_ASIA        uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_SM          uuid := '841cd690-210a-422a-908c-7676828db272';
  m             RECORD; v_val text; v_tx text;
  v_pv_assigns  jsonb := '{}'::jsonb;
  v_vss_assigns jsonb := '{}'::jsonb;
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','raw_nao_encontrado'); END IF;
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);

  IF r.supplier_id = v_SPOT THEN
    -- M1 2026-06-11: removidos length_cm/width_cm da exclusão (mappings repontuados
    -- para size_length_cm/size_width_cm e reativados). size_id segue excluído
    -- (catálogo variation_values não-canônico; size_code texto é o padrão).
    FOR m IN SELECT sfm.source_field,sfm.target_field,sfm.target_table,sfm.transform_type,sfm.transform_config,sfm.source_unit,sfm.target_unit
             FROM public.supplier_field_mappings sfm
             WHERE sfm.supplier_id=v_SPOT AND sfm.target_table IN('product_variants','variant_supplier_sources')
               AND sfm.is_active=TRUE AND sfm.target_field NOT IN('color_id','size_id','web_sku')
             ORDER BY sfm.target_table,sfm.priority NULLS LAST LOOP
      v_val:=CASE WHEN m.transform_config->>'source_blob'='stock_data' THEN r.stock_data->>m.source_field ELSE r.raw_data->>m.source_field END;
      CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='';
      BEGIN v_tx:=public.fn_apply_transform(v_val,m.transform_type,m.transform_config,m.source_unit,m.target_unit,v_SPOT);
      EXCEPTION WHEN OTHERS THEN v_tx:=v_val; END;
      CONTINUE WHEN v_tx IS NULL;
      IF m.target_table='product_variants' THEN v_pv_assigns:=v_pv_assigns||jsonb_build_object(m.target_field,v_tx);
      ELSE v_vss_assigns:=v_vss_assigns||jsonb_build_object(m.target_field,v_tx); END IF;
    END LOOP;
    v_supplier_sku:=v_pv_assigns->>'supplier_sku'; v_code:=v_pv_assigns->>'color_code';
    v_cname:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'color_name'),''),r.raw_data->>'ColorDesc1');
    v_chex:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'color_hex'),''),r.raw_data->>'ColorHex1');
    v_thumb:=COALESCE(v_pv_assigns->>'selected_thumbnail',v_vss_assigns->>'supplier_thumbnail');
    v_sku:=r.supplier_reference;
    BEGIN v_images:=COALESCE(CASE WHEN v_pv_assigns?'images' THEN(v_pv_assigns->>'images')::jsonb END,CASE WHEN v_vss_assigns?'supplier_images' THEN(v_vss_assigns->>'supplier_images')::jsonb END,'[]'::jsonb); EXCEPTION WHEN OTHERS THEN v_images:='[]'::jsonb; END;
    BEGIN v_videos:=CASE WHEN v_vss_assigns?'supplier_videos' THEN(v_vss_assigns->>'supplier_videos')::jsonb END; EXCEPTION WHEN OTHERS THEN v_videos:=NULL; END;
    v_stock:=public.fn_safe_int(COALESCE(v_vss_assigns->>'quantity',v_vss_assigns->>'stock_main_warehouse',r.stock_data->>'Quantity',r.raw_data->>'StockQuantity'));
    v_cost:=public.fn_safe_num(COALESCE(v_vss_assigns->>'cost_price',r.raw_data->>'Price1'));
    v_cp1:=public.fn_safe_num(COALESCE(v_vss_assigns->>'cost_price_1',r.raw_data->>'Price1'));
    v_cp2:=public.fn_safe_num(v_vss_assigns->>'cost_price_2'); v_cp3:=public.fn_safe_num(v_vss_assigns->>'cost_price_3');
    v_cp4:=public.fn_safe_num(v_vss_assigns->>'cost_price_4'); v_cp5:=public.fn_safe_num(v_vss_assigns->>'cost_price_5');
    v_mq1:=public.fn_safe_int(v_vss_assigns->>'min_qty_1'); v_mq2:=public.fn_safe_int(v_vss_assigns->>'min_qty_2');
    v_mq3:=public.fn_safe_int(v_vss_assigns->>'min_qty_3'); v_mq4:=public.fn_safe_int(v_vss_assigns->>'min_qty_4'); v_mq5:=public.fn_safe_int(v_vss_assigns->>'min_qty_5');
    v_mult:=public.fn_safe_int(COALESCE(v_vss_assigns->>'sale_multiplier',r.raw_data->>'Multiplier'));
    v_nq1:=public.fn_safe_int(v_vss_assigns->>'next_quantity_1'); v_nq2:=public.fn_safe_int(v_vss_assigns->>'next_quantity_2'); v_nq3:=public.fn_safe_int(v_vss_assigns->>'next_quantity_3');
    v_nd1:=CASE WHEN v_vss_assigns->>'next_date_1'~'^\d{4}-\d{2}-\d{2}' THEN LEFT(v_vss_assigns->>'next_date_1',10)::date END;
    v_nd2:=CASE WHEN v_vss_assigns->>'next_date_2'~'^\d{4}-\d{2}-\d{2}' THEN LEFT(v_vss_assigns->>'next_date_2',10)::date END;
    v_nd3:=CASE WHEN v_vss_assigns->>'next_date_3'~'^\d{4}-\d{2}-\d{2}' THEN LEFT(v_vss_assigns->>'next_date_3',10)::date END;
    -- M1/M2 2026-06-11: tamanho + dims têxteis + capacity (mapping ativo era descartado)
    v_size_code:=NULLIF(TRIM(v_pv_assigns->>'size_code'),'');
    v_slen:=public.fn_safe_num(REPLACE(v_pv_assigns->>'size_length_cm',',','.'));
    v_swid:=public.fn_safe_num(REPLACE(v_pv_assigns->>'size_width_cm',',','.'));
    v_cap_ml:=COALESCE(public.fn_safe_int(v_pv_assigns->>'capacity_ml'),
                       public.fn_parse_capacity_ml(NULLIF(TRIM(r.raw_data->>'Capacity'),'')));

  ELSIF r.supplier_id = v_SM THEN
    FOR m IN SELECT sfm.source_field,sfm.target_field,sfm.target_table,sfm.transform_type,sfm.transform_config,sfm.source_unit,sfm.target_unit
             FROM public.supplier_field_mappings sfm
             WHERE sfm.supplier_id=v_SM AND sfm.target_table IN('product_variants','variant_supplier_sources') AND sfm.is_active=TRUE
             ORDER BY sfm.target_table,sfm.priority NULLS LAST LOOP
      v_val:=CASE WHEN m.transform_config->>'source_blob'='stock_data' THEN r.stock_data->>m.source_field ELSE r.raw_data->>m.source_field END;
      CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='';
      BEGIN v_tx:=public.fn_apply_transform(v_val,m.transform_type,m.transform_config,m.source_unit,m.target_unit,v_SM); EXCEPTION WHEN OTHERS THEN v_tx:=v_val; END;
      CONTINUE WHEN v_tx IS NULL;
      IF m.target_table='product_variants' THEN v_pv_assigns:=v_pv_assigns||jsonb_build_object(m.target_field,v_tx);
      ELSE v_vss_assigns:=v_vss_assigns||jsonb_build_object(m.target_field,v_tx); END IF;
    END LOOP;
    v_cname:=public.fn_extract_color_from_title(r.raw_data->>'titulo');
    v_chex:=(SELECT split_part(item,'|',2) FROM unnest(string_to_array(r.raw_data->>'produtos_similares',';')) item WHERE split_part(item,'|',1)=r.supplier_reference AND split_part(item,'|',2)~*'^#[0-9a-f]{6}$' LIMIT 1);
    v_supplier_sku:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'supplier_sku'),''),r.supplier_reference);
    v_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(COALESCE(v_pv_assigns->>'stock_quantity',r.raw_data->>'estoque'));
    v_cost:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price',r.raw_data->>'preco_sem_gravacao_sem_impostos'));
    v_cp1:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_1',r.raw_data->>'preco_sem_gravacao_sem_impostos'));
    v_cp2:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_2',r.raw_data->>'preco_com_gravacao_sem_impostos'));
    v_cp3:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_3',r.raw_data->>'preco_sem_gravacao_com_impostos'));
    v_cp4:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_4',r.raw_data->>'preco_com_gravacao_com_impostos'));
    v_mq1:=public.fn_safe_int(COALESCE(v_pv_assigns->>'min_qty_1',r.raw_data->>'quantidade_minima_sugerida'));
    v_thumb:=NULLIF(TRIM(COALESCE(v_pv_assigns->>'supplier_thumbnail',r.raw_data->>'url_foto')),'');
    BEGIN v_images:=CASE WHEN v_pv_assigns?'supplier_images' THEN(v_pv_assigns->>'supplier_images')::jsonb ELSE NULL END; EXCEPTION WHEN OTHERS THEN v_images:=NULL; END;
    v_size_code:=NULLIF(TRIM(v_pv_assigns->>'size_code'),'');

  ELSIF r.supplier_id = v_XBZ THEN
    v_apiid        := r.raw_data->>'CorWebPrincipalId';
    v_cname        := r.raw_data->>'CorWebPrincipal';
    v_supplier_sku := r.raw_data->>'CodigoComposto';
    v_stock        := GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel'),0));
    v_cost         := public.fn_safe_num(r.raw_data->>'PrecoVenda');
    v_sku          := 'XBZ-'||r.supplier_reference;
    v_mult         := CASE WHEN public.fn_safe_int(r.raw_data->>'Multiplos')>0 THEN public.fn_safe_int(r.raw_data->>'Multiplos') ELSE NULL END;
    v_mq1          := CASE WHEN public.fn_safe_int(r.raw_data->>'VendaMinima')>0 THEN public.fn_safe_int(r.raw_data->>'VendaMinima') ELSE NULL END;
    v_cap_ml := CASE
        WHEN r.raw_data->>'Nome' IS NOT NULL
         AND r.raw_data->>'Nome' !~* '(127v|220v|led|lampada|lâmpada|pisca)'
        THEN public.extract_capacity_ml(r.raw_data->>'Nome')
        ELSE NULL
    END;
    v_thumb := CASE
        WHEN r.raw_data->>'ImageLink' LIKE 'https://%' OR r.raw_data->>'ImageLink' LIKE 'http://%' THEN r.raw_data->>'ImageLink'
        WHEN r.raw_data->>'ImageLink' LIKE 'hhttps://%' THEN SUBSTRING(r.raw_data->>'ImageLink' FROM 2)
        WHEN r.raw_data->>'ImageLink' LIKE 'htt%brindes.com.br%' THEN 'https://cdn.xbzbrindes.com.br'||SUBSTRING(r.raw_data->>'ImageLink' FROM POSITION('brindes.com.br' IN r.raw_data->>'ImageLink')+14)
        ELSE NULL END;
    BEGIN v_images:=CASE WHEN r.site_data->'imagens' IS NOT NULL AND jsonb_array_length(r.site_data->'imagens')>0 THEN r.site_data->'imagens' ELSE NULL END; EXCEPTION WHEN OTHERS THEN v_images:=NULL; END;
    BEGIN v_videos:=CASE WHEN (r.site_data->'video'->>'indicador')::boolean=true AND r.site_data->'video'->>'embed_id' IS NOT NULL
        THEN jsonb_build_array(jsonb_build_object('embed_id',r.site_data->'video'->>'embed_id','embed_url',r.site_data->'video'->>'embed_url','watch_url',r.site_data->'video'->>'watch_url','plataforma','youtube','indicador',true))
        ELSE NULL END; EXCEPTION WHEN OTHERS THEN v_videos:=NULL; END;
    v_nd1:=CASE WHEN r.raw_data->>'ReposicaoDataPrevista' IS NOT NULL AND LEFT(r.raw_data->>'ReposicaoDataPrevista',4)!='0001' THEN LEFT(r.raw_data->>'ReposicaoDataPrevista',10)::date ELSE NULL END;
    v_nq1:=CASE WHEN r.raw_data->>'QuantidadeDisponivelEstoquePrincipal' IS NOT NULL AND GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel'),0))>GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivelEstoquePrincipal'),0)) THEN GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel'),0)-GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivelEstoquePrincipal'),0))) ELSE NULL END;

  ELSIF r.supplier_id = v_ASIA THEN
    v_cname:=r.raw_data->>'var_cor_nome'; v_chex:=r.raw_data->>'var_cor_hex';
    v_supplier_sku:=COALESCE(r.raw_data->>'var_referencia',r.supplier_reference);
    v_stock:=public.fn_safe_int(COALESCE(r.stock_data->>'qtd_estoque',r.raw_data->>'var_estoque'));
    v_cost:=public.fn_safe_num(r.raw_data->>'preco'); v_sku:='ASIA-'||r.supplier_reference;
    v_nd1:=CASE WHEN COALESCE(r.stock_data->'previsao_entrega'->0->>'data',r.raw_data->'previsao_entrega'->0->>'data')~'^\d{4}-\d{2}-\d{2}' THEN LEFT(COALESCE(r.stock_data->'previsao_entrega'->0->>'data',r.raw_data->'previsao_entrega'->0->>'data'),10)::date END;
    v_nq1:=public.fn_safe_int(COALESCE(r.stock_data->'previsao_entrega'->0->>'quantidade',r.raw_data->'previsao_entrega'->0->>'quantidade'));
  ELSE
    -- DE-PARA genérico (2026-06-11, Fase 6): fornecedores sem branch dedicado
    -- leem supplier_field_mappings (product_variants/VSS) como SPOT/SM,
    -- com fallback nas chaves convencionais do feed.
    FOR m IN SELECT sfm.source_field,sfm.target_field,sfm.target_table,sfm.transform_type,sfm.transform_config,sfm.source_unit,sfm.target_unit
             FROM public.supplier_field_mappings sfm
             WHERE sfm.supplier_id=r.supplier_id AND sfm.target_table IN('product_variants','variant_supplier_sources') AND sfm.is_active=TRUE
             ORDER BY sfm.target_table,sfm.priority NULLS LAST LOOP
      v_val:=CASE WHEN m.transform_config->>'source_blob'='stock_data' THEN r.stock_data->>m.source_field ELSE r.raw_data->>m.source_field END;
      CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='';
      BEGIN v_tx:=public.fn_apply_transform(v_val,m.transform_type,m.transform_config,m.source_unit,m.target_unit,r.supplier_id); EXCEPTION WHEN OTHERS THEN v_tx:=v_val; END;
      CONTINUE WHEN v_tx IS NULL;
      IF m.target_table='product_variants' THEN v_pv_assigns:=v_pv_assigns||jsonb_build_object(m.target_field,v_tx);
      ELSE v_vss_assigns:=v_vss_assigns||jsonb_build_object(m.target_field,v_tx); END IF;
    END LOOP;
    v_cname:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'color_name'),''),r.raw_data->>'cor');
    v_chex:=NULLIF(TRIM(v_pv_assigns->>'color_hex'),'');
    v_supplier_sku:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'supplier_sku'),''),NULLIF(TRIM(r.raw_data->>'sku_fornecedor'),''),r.supplier_reference);
    v_sku:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'sku'),''),r.supplier_reference);
    v_stock:=public.fn_safe_int(COALESCE(v_pv_assigns->>'stock_quantity',v_vss_assigns->>'quantity',r.raw_data->>'estoque'));
    v_cost:=public.fn_safe_num(COALESCE(v_vss_assigns->>'cost_price',v_pv_assigns->>'cost_price',r.raw_data->>'preco_custo',r.raw_data->>'preco_base',r.raw_data->>'preco'));
    v_cp1:=v_cost;
    v_thumb:=NULLIF(TRIM(COALESCE(v_pv_assigns->>'supplier_thumbnail',v_vss_assigns->>'supplier_thumbnail',r.raw_data->>'imagem_principal',r.raw_data->>'url_foto')),'');
    -- M2 2026-06-11: fornecedores genéricos também herdam size via de-para
    v_size_code:=NULLIF(TRIM(v_pv_assigns->>'size_code'),'');
    v_slen:=public.fn_safe_num(REPLACE(v_pv_assigns->>'size_length_cm',',','.'));
    v_swid:=public.fn_safe_num(REPLACE(v_pv_assigns->>'size_width_cm',',','.'));
    v_cap_ml:=COALESCE(v_cap_ml,public.fn_safe_int(v_pv_assigns->>'capacity_ml'));
  END IF;

  -- CLAMPS universais (2026-06-11, achados #5/#6 da simulação):
  -- estoque negativo não existe no domínio; custo fora de (0, 999999.9999]
  -- (teto do VSS numeric(10,4)) é lixo de feed e não entra na Silver.
  v_stock := GREATEST(0, v_stock);
  IF v_cost  IS NOT NULL AND (v_cost  < 0 OR v_cost  > 999999.9999) THEN v_cost  := NULL; END IF;
  IF v_cp1   IS NOT NULL AND (v_cp1   < 0 OR v_cp1   > 999999.9999) THEN v_cp1   := NULL; END IF;
  IF v_cp2   IS NOT NULL AND (v_cp2   < 0 OR v_cp2   > 999999.9999) THEN v_cp2   := NULL; END IF;
  IF v_cp3   IS NOT NULL AND (v_cp3   < 0 OR v_cp3   > 999999.9999) THEN v_cp3   := NULL; END IF;
  IF v_cp4   IS NOT NULL AND (v_cp4   < 0 OR v_cp4   > 999999.9999) THEN v_cp4   := NULL; END IF;
  IF v_cp5   IS NOT NULL AND (v_cp5   < 0 OR v_cp5   > 999999.9999) THEN v_cp5   := NULL; END IF;
  -- CLAMPS M1/M2 (2026-06-11, simulação 54 casos adversariais):
  -- dims têxteis fora de (0, 300] cm e capacidade fora de (0, 100000] mL são lixo de feed.
  IF v_slen IS NOT NULL AND (v_slen <= 0 OR v_slen > 300) THEN v_slen := NULL; END IF;
  IF v_swid IS NOT NULL AND (v_swid <= 0 OR v_swid > 300) THEN v_swid := NULL; END IF;
  IF v_cap_ml IS NOT NULL AND (v_cap_ml <= 0 OR v_cap_ml > 100000) THEN v_cap_ml := NULL; END IF;
  IF v_size_code IS NOT NULL AND length(v_size_code) > 10 THEN v_size_code := NULL; END IF;

  SELECT * INTO v_col FROM public.fn_match_supplier_color(r.supplier_id,v_code,v_apiid,v_cname,v_chex);
  -- FIX 2026-06-11: as 3 atribuições abaixo estavam na MESMA linha de um
  -- comentário `--` (patch 2026-06-09) e nunca executavam; color_code e
  -- color_hex saíam NULL. Agora em linhas próprias.
  v_fname:=public.fn_normalize_product_name(COALESCE(v_col.color_name,v_cname));
  v_fcode:=COALESCE(v_col.color_code,v_code);
  v_fhex:=COALESCE(v_col.color_hex,v_chex);
  -- SPOT CANONICAL CODE GUARD (pipeline-proof 2026-06-09):
  -- Preserva código 3-dígitos da API quando fn_match_supplier_color
  -- retorna código legado 2-dígitos via fallback de nome.
  IF r.supplier_id = v_SPOT AND v_code IS NOT NULL
     AND length(v_code) = 3 AND COALESCE(length(v_fcode), 0) < 3 THEN
    v_fcode := v_code;
  END IF;
  v_canonical_id:=public.fn_match_canonical_color(v_fname,v_fhex);

  INSERT INTO public.produtos_padronizacao_variantes AS pv (
    raw_id,supplier_id,parent_reference,variant_reference,sku,supplier_sku,color_name,color_code,color_hex,color_id,
    stock_quantity,cost_price,is_active,status,capacity_ml,
    cost_price_1,cost_price_2,cost_price_3,cost_price_4,cost_price_5,
    min_qty_1,min_qty_2,min_qty_3,min_qty_4,min_qty_5,
    next_quantity_1,next_quantity_2,next_quantity_3,next_date_1,next_date_2,next_date_3,
    sale_multiplier,supplier_thumbnail,supplier_images,supplier_videos,
    size_code,size_length_cm,size_width_cm
  ) VALUES (
    r.id,r.supplier_id,v_parent,r.supplier_reference,v_sku,v_supplier_sku,v_fname,v_fcode,v_fhex,v_canonical_id,
    v_stock,v_cost,true,'standardized'::public.produtos_padronizacao_status,v_cap_ml,
    v_cp1,v_cp2,v_cp3,v_cp4,v_cp5,
    v_mq1,v_mq2,v_mq3,v_mq4,v_mq5,
    v_nq1,v_nq2,v_nq3,v_nd1,v_nd2,v_nd3,
    v_mult,v_thumb,v_images,v_videos,
    v_size_code,v_slen,v_swid
  )
  ON CONFLICT (supplier_id,variant_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id,parent_reference=EXCLUDED.parent_reference,sku=EXCLUDED.sku,supplier_sku=EXCLUDED.supplier_sku,
    color_name=EXCLUDED.color_name,color_code=EXCLUDED.color_code,color_hex=EXCLUDED.color_hex,
    color_id=COALESCE(EXCLUDED.color_id,pv.color_id),
    stock_quantity=EXCLUDED.stock_quantity,cost_price=EXCLUDED.cost_price,is_active=EXCLUDED.is_active,status=EXCLUDED.status,
    capacity_ml=COALESCE(EXCLUDED.capacity_ml, pv.capacity_ml),
    cost_price_1=EXCLUDED.cost_price_1,cost_price_2=EXCLUDED.cost_price_2,cost_price_3=EXCLUDED.cost_price_3,
    cost_price_4=EXCLUDED.cost_price_4,cost_price_5=EXCLUDED.cost_price_5,
    min_qty_1=EXCLUDED.min_qty_1,min_qty_2=EXCLUDED.min_qty_2,min_qty_3=EXCLUDED.min_qty_3,
    min_qty_4=EXCLUDED.min_qty_4,min_qty_5=EXCLUDED.min_qty_5,
    next_quantity_1=EXCLUDED.next_quantity_1,next_quantity_2=EXCLUDED.next_quantity_2,next_quantity_3=EXCLUDED.next_quantity_3,
    next_date_1=EXCLUDED.next_date_1,next_date_2=EXCLUDED.next_date_2,next_date_3=EXCLUDED.next_date_3,
    sale_multiplier=EXCLUDED.sale_multiplier,
    supplier_thumbnail=EXCLUDED.supplier_thumbnail,supplier_images=EXCLUDED.supplier_images,supplier_videos=EXCLUDED.supplier_videos,
    size_code=COALESCE(EXCLUDED.size_code, pv.size_code),
    size_length_cm=COALESCE(EXCLUDED.size_length_cm, pv.size_length_cm),
    size_width_cm=COALESCE(EXCLUDED.size_width_cm, pv.size_width_cm),
    updated_at=now()
  RETURNING pv.id INTO v_var_id;

  RETURN jsonb_build_object(
    'success',true,'variante_id',v_var_id,'parent',v_parent,'cor',v_fname,
    'capacity_ml',v_cap_ml,'thumbnail',v_thumb IS NOT NULL,
    'images_count',CASE WHEN v_images IS NOT NULL THEN jsonb_array_length(v_images) ELSE 0 END,
    'has_video',v_videos IS NOT NULL,'cost_price',v_cost,'sale_multiplier',v_mult,'min_qty_1',v_mq1,
    'next_date_1',v_nd1,'next_quantity_1',v_nq1,
    'size_code',v_size_code,'size_length_cm',v_slen,'size_width_cm',v_swid
  );
END;
$_$;


ALTER FUNCTION "public"."fn_standardize_variant"("p_raw_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_standardize_variant"("p_raw_id" "uuid") IS 'Bronze->Silver (variante). De-para supplier_field_mappings p/ SPOT e SM; hardcoded XBZ/Asia; fallback generico. FIX 2026-06-11: v_fcode/v_fhex estavam comentados desde 2026-06-09 (color_code/hex saiam NULL).';



CREATE OR REPLACE FUNCTION "public"."fn_super_filtro"("p_search_term" "text" DEFAULT NULL::"text", "p_category_slug" "text" DEFAULT NULL::"text", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_brands" "text"[] DEFAULT NULL::"text"[], "p_only_in_stock" boolean DEFAULT false, "p_min_price" numeric DEFAULT NULL::numeric, "p_max_price" numeric DEFAULT NULL::numeric, "p_target_audiences" "text"[] DEFAULT NULL::"text"[], "p_is_kit" boolean DEFAULT NULL::boolean, "p_is_textil" boolean DEFAULT NULL::boolean, "p_is_thermal" boolean DEFAULT NULL::boolean, "p_has_gift_box" boolean DEFAULT NULL::boolean, "p_material_groups" "text"[] DEFAULT NULL::"text"[], "p_technique_groups" "text"[] DEFAULT NULL::"text"[], "p_color_groups" "text"[] DEFAULT NULL::"text"[], "p_date_slugs" "text"[] DEFAULT NULL::"text"[], "p_endomarketing" boolean DEFAULT NULL::boolean, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_sort" "text" DEFAULT 'name_asc'::"text") RETURNS TABLE("id" "uuid", "name" "text", "sku" "text", "slug" "text", "short_description" "text", "brand" character varying, "sale_price" numeric, "cost_price" numeric, "min_quantity" integer, "stock_quantity" integer, "is_stockout" boolean, "is_kit" boolean, "is_textil" boolean, "is_thermal" boolean, "is_featured" boolean, "is_bestseller" boolean, "is_new" boolean, "has_gift_box" boolean, "target_audience" "text"[], "primary_image_url" "text", "og_image_url" "text", "set_image_url" "text", "category_id" "uuid", "category_name" "text", "category_slug" "text", "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_search_normalized  text;
  v_tsquery            tsquery;
  v_category_uuid      uuid;
  v_category_provided  boolean := false;
  v_limit              integer := GREATEST(0, LEAST(COALESCE(p_limit, 50), 1000));
  v_offset             integer := GREATEST(0, COALESCE(p_offset, 0));
BEGIN
  IF p_search_term IS NOT NULL AND length(trim(p_search_term)) > 0 THEN
    v_search_normalized := left(lower(unaccent(trim(p_search_term))), 200);
    BEGIN
      v_tsquery := websearch_to_tsquery('portuguese', v_search_normalized);
    EXCEPTION WHEN OTHERS THEN v_tsquery := NULL; END;
    PERFORM set_config('pg_trgm.similarity_threshold', '0.2', true);
  END IF;

  IF p_category_id IS NOT NULL THEN
    v_category_uuid     := p_category_id;
    v_category_provided := true;
  ELSIF p_category_slug IS NOT NULL THEN
    v_category_provided := true;
    SELECT c.id INTO v_category_uuid FROM categories c WHERE c.slug = p_category_slug LIMIT 1;
  END IF;

  RETURN QUERY
  WITH
  mat_filter AS (
    SELECT DISTINCT pm.product_id FROM product_materials pm
    JOIN material_types mt ON mt.id=pm.material_id JOIN material_groups mg ON mg.id=mt.group_id
    WHERE p_material_groups IS NOT NULL AND array_length(p_material_groups,1) > 0
      AND mg.name = ANY(p_material_groups) AND pm.is_active=true
  ),
  tech_filter AS (
    SELECT DISTINCT pat.product_id FROM print_area_techniques pat
    JOIN tabela_preco_gravacao_oficial tpgo ON tpgo.id=pat.tabela_preco_id
    WHERE p_technique_groups IS NOT NULL AND array_length(p_technique_groups,1) > 0
      AND tpgo.grupo_tecnica = ANY(p_technique_groups) AND pat.is_active=true
  ),
  color_filter AS (
    SELECT DISTINCT pv.product_id FROM product_variants pv
    JOIN color_variations cv ON cv.id=pv.color_id JOIN color_groups cg ON cg.id=cv.group_id
    WHERE p_color_groups IS NOT NULL AND array_length(p_color_groups,1) > 0
      AND cg.name = ANY(p_color_groups) AND pv.is_active=true
  ),
  date_filter AS (
    SELECT DISTINCT pcd.product_id FROM product_commemorative_dates pcd
    JOIN commemorative_dates cd ON cd.id=pcd.commemorative_date_id
    WHERE p_date_slugs IS NOT NULL AND array_length(p_date_slugs,1) > 0
      AND cd.slug = ANY(p_date_slugs) AND pcd.is_active=true
  ),
  endo_filter AS (
    SELECT DISTINCT pt.product_id FROM product_tags pt JOIN tags t ON t.id=pt.tag_id
    WHERE p_endomarketing=true AND t.slug='endomarketing' AND t.is_active=true
  ),
  cat_filter AS (
    SELECT DISTINCT pca.product_id FROM product_category_assignments pca
    WHERE v_category_uuid IS NOT NULL AND pca.category_id = v_category_uuid
  ),
  base AS (
    SELECT
      p.id, p.name, p.sku, p.slug, p.short_description, p.brand,
      p.sale_price,
      NULL::numeric AS cost_price,  -- fix_version 20260717: NUNCA expor custo ao anon
      p.min_quantity, p.stock_quantity,
      p.is_stockout, p.is_kit, p.is_textil, p.is_thermal, p.is_featured,
      p.is_bestseller, p.is_new, p.has_gift_box, p.target_audience,
      p.primary_image_url, p.og_image_url, p.set_image_url,
      p.main_category_id AS category_id,
      c.name AS category_name, c.slug AS category_slug,
      CASE
        WHEN v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery
          THEN ts_rank_cd(p.search_vector, v_tsquery, 32)*2.0 + word_similarity(v_search_normalized, lower(unaccent(p.name)))
        WHEN v_search_normalized IS NOT NULL
          THEN word_similarity(v_search_normalized, lower(unaccent(p.name)))
        ELSE 0
      END AS relevance_score,
      COUNT(*) OVER() AS _total_count
    FROM products p
    LEFT JOIN categories c ON c.id = p.main_category_id
    WHERE
      p.is_active=true AND p.is_deleted IS NOT TRUE
      AND (v_search_normalized IS NULL
           OR (v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery)
           OR p.name % v_search_normalized
           OR lower(p.sku) LIKE '%'||v_search_normalized||'%')
      AND (
        NOT v_category_provided
        OR (v_category_uuid IS NOT NULL AND EXISTS (SELECT 1 FROM cat_filter cf WHERE cf.product_id=p.id))
      )
      AND (p_brands IS NULL OR array_length(p_brands,1) IS NULL OR p.brand = ANY(p_brands))
      -- fix_version 20260717: IS NOT TRUE corrige 3-valued logic (NOT NULL=NULL→excluía produtos).
      -- NULL IS NOT TRUE=TRUE (sem filtro=todos) | TRUE IS NOT TRUE=FALSE (só em estoque).
      -- Bug original: AND (NOT p_only_in_stock OR p.is_stockout=false) excluía 1.395 produtos.
      AND (p_only_in_stock IS NOT TRUE OR p.is_stockout=false)
      AND (p_min_price IS NULL OR p.sale_price >= p_min_price)
      AND (p_max_price IS NULL OR p.sale_price <= p_max_price)
      AND (p_target_audiences IS NULL OR array_length(p_target_audiences,1) IS NULL OR p.target_audience && p_target_audiences)
      AND (p_is_kit IS NULL OR p.is_kit=p_is_kit)
      AND (p_is_textil IS NULL OR p.is_textil=p_is_textil)
      AND (p_is_thermal IS NULL OR p.is_thermal=p_is_thermal)
      AND (p_has_gift_box IS NULL OR p.has_gift_box=p_has_gift_box)
      AND (p_material_groups IS NULL  OR array_length(p_material_groups,1) IS NULL  OR EXISTS(SELECT 1 FROM mat_filter   mf WHERE mf.product_id=p.id))
      AND (p_technique_groups IS NULL OR array_length(p_technique_groups,1) IS NULL OR EXISTS(SELECT 1 FROM tech_filter  tf WHERE tf.product_id=p.id))
      AND (p_color_groups IS NULL     OR array_length(p_color_groups,1) IS NULL     OR EXISTS(SELECT 1 FROM color_filter cf WHERE cf.product_id=p.id))
      AND (p_date_slugs IS NULL       OR array_length(p_date_slugs,1) IS NULL       OR EXISTS(SELECT 1 FROM date_filter  df WHERE df.product_id=p.id))
      AND (p_endomarketing IS NULL OR p_endomarketing=false OR EXISTS(SELECT 1 FROM endo_filter ef WHERE ef.product_id=p.id))
  )
  SELECT
    b.id, b.name::text, b.sku::text, b.slug::text, b.short_description::text,
    b.brand, b.sale_price, b.cost_price, b.min_quantity, b.stock_quantity,
    b.is_stockout, b.is_kit, b.is_textil, b.is_thermal, b.is_featured,
    b.is_bestseller, b.is_new, b.has_gift_box, b.target_audience,
    b.primary_image_url, b.og_image_url, b.set_image_url,
    b.category_id, b.category_name::text, b.category_slug::text, b._total_count
  FROM base b
  ORDER BY
    CASE p_sort WHEN 'name_asc'   THEN b.name END ASC  NULLS LAST,
    CASE p_sort WHEN 'name_desc'  THEN b.name END DESC NULLS LAST,
    CASE p_sort WHEN 'price_asc'  THEN b.sale_price END ASC  NULLS LAST,
    CASE p_sort WHEN 'price_desc' THEN b.sale_price END DESC NULLS LAST,
    CASE p_sort WHEN 'relevance'  THEN b.relevance_score
                WHEN 'bestseller' THEN CASE WHEN b.is_bestseller THEN 1 ELSE 0 END::numeric
    END DESC NULLS LAST,
    b.is_featured DESC, b.is_bestseller DESC, b.name ASC
  LIMIT v_limit OFFSET v_offset;
END;
$$;


ALTER FUNCTION "public"."fn_super_filtro"("p_search_term" "text", "p_category_slug" "text", "p_category_id" "uuid", "p_brands" "text"[], "p_only_in_stock" boolean, "p_min_price" numeric, "p_max_price" numeric, "p_target_audiences" "text"[], "p_is_kit" boolean, "p_is_textil" boolean, "p_is_thermal" boolean, "p_has_gift_box" boolean, "p_material_groups" "text"[], "p_technique_groups" "text"[], "p_color_groups" "text"[], "p_date_slugs" "text"[], "p_endomarketing" boolean, "p_limit" integer, "p_offset" integer, "p_sort" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_super_filtro"("p_search_term" "text", "p_category_slug" "text", "p_category_id" "uuid", "p_brands" "text"[], "p_only_in_stock" boolean, "p_min_price" numeric, "p_max_price" numeric, "p_target_audiences" "text"[], "p_is_kit" boolean, "p_is_textil" boolean, "p_is_thermal" boolean, "p_has_gift_box" boolean, "p_material_groups" "text"[], "p_technique_groups" "text"[], "p_color_groups" "text"[], "p_date_slugs" "text"[], "p_endomarketing" boolean, "p_limit" integer, "p_offset" integer, "p_sort" "text") IS 'Catálogo principal do storefront (SECURITY DEFINER). fix_version 20260717: bug p_only_in_stock=NULL corrigido via IS NOT TRUE. cost_price=NULL::numeric. ANTI-REGRESSAO: manter IS NOT TRUE no predicado de estoque.';



CREATE OR REPLACE FUNCTION "public"."fn_super_filtro_facets"("p_search_term" "text" DEFAULT NULL::"text", "p_category_slug" "text" DEFAULT NULL::"text", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_brands" "text"[] DEFAULT NULL::"text"[], "p_only_in_stock" boolean DEFAULT false, "p_min_price" numeric DEFAULT NULL::numeric, "p_max_price" numeric DEFAULT NULL::numeric, "p_target_audiences" "text"[] DEFAULT NULL::"text"[], "p_is_kit" boolean DEFAULT NULL::boolean, "p_is_textil" boolean DEFAULT NULL::boolean, "p_is_thermal" boolean DEFAULT NULL::boolean, "p_has_gift_box" boolean DEFAULT NULL::boolean, "p_material_groups" "text"[] DEFAULT NULL::"text"[], "p_technique_groups" "text"[] DEFAULT NULL::"text"[], "p_color_groups" "text"[] DEFAULT NULL::"text"[], "p_date_slugs" "text"[] DEFAULT NULL::"text"[], "p_endomarketing" boolean DEFAULT NULL::boolean) RETURNS TABLE("facet_type" "text", "facet_value" "text", "facet_slug" "text", "product_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_search_normalized text;
  v_tsquery           tsquery;
  v_category_uuid     uuid;
BEGIN
  IF p_search_term IS NOT NULL AND length(trim(p_search_term)) > 0 THEN
    v_search_normalized := lower(unaccent(trim(p_search_term)));
    BEGIN
      v_tsquery := websearch_to_tsquery('portuguese', unaccent(trim(p_search_term)));
    EXCEPTION WHEN OTHERS THEN v_tsquery := NULL; END;
    PERFORM set_config('pg_trgm.similarity_threshold', '0.2', true);
  END IF;

  IF p_category_id IS NOT NULL THEN
    v_category_uuid := p_category_id;
  ELSIF p_category_slug IS NOT NULL THEN
    SELECT c.id INTO v_category_uuid FROM categories c WHERE c.slug = p_category_slug LIMIT 1;
  END IF;

  RETURN QUERY
  WITH
  mat_filter   AS (SELECT DISTINCT pm.product_id FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id JOIN material_groups mg ON mg.id=mt.group_id WHERE p_material_groups IS NOT NULL AND mg.name=ANY(p_material_groups) AND pm.is_active=true),
  tech_filter  AS (SELECT DISTINCT pat.product_id FROM print_area_techniques pat JOIN tabela_preco_gravacao_oficial tpgo ON tpgo.id=pat.tabela_preco_id WHERE p_technique_groups IS NOT NULL AND tpgo.grupo_tecnica=ANY(p_technique_groups) AND pat.is_active=true),
  color_filter AS (SELECT DISTINCT pv.product_id FROM product_variants pv JOIN color_variations cv ON cv.id=pv.color_id JOIN color_groups cg ON cg.id=cv.group_id WHERE p_color_groups IS NOT NULL AND cg.name=ANY(p_color_groups) AND pv.is_active=true),
  date_filter  AS (SELECT DISTINCT pcd.product_id FROM product_commemorative_dates pcd JOIN commemorative_dates cd ON cd.id=pcd.commemorative_date_id WHERE p_date_slugs IS NOT NULL AND cd.slug=ANY(p_date_slugs) AND pcd.is_active=true),
  endo_filter  AS (SELECT DISTINCT pt.product_id FROM product_tags pt JOIN tags t ON t.id=pt.tag_id WHERE p_endomarketing=true AND t.slug='endomarketing' AND t.is_active=true),

  -- Conjunto base de produtos que passam nos filtros atuais
  base_ids AS (
    SELECT p.id
    FROM products p
    LEFT JOIN product_category_assignments pca ON pca.product_id=p.id AND pca.is_primary=true
    WHERE p.is_active=true AND p.is_deleted IS NOT TRUE
      AND (v_search_normalized IS NULL OR (v_tsquery IS NOT NULL AND p.search_vector@@v_tsquery) OR p.name%v_search_normalized OR lower(p.sku) LIKE '%'||v_search_normalized||'%')
      AND (v_category_uuid IS NULL OR pca.category_id=v_category_uuid OR p.main_category_id=v_category_uuid)
      AND (p_brands IS NULL OR p.brand=ANY(p_brands))
      AND (NOT p_only_in_stock OR p.is_stockout=false)
      AND (p_min_price IS NULL OR p.sale_price>=p_min_price)
      AND (p_max_price IS NULL OR p.sale_price<=p_max_price)
      AND (p_target_audiences IS NULL OR p.target_audience&&p_target_audiences)
      AND (p_is_kit IS NULL OR p.is_kit=p_is_kit)
      AND (p_is_textil IS NULL OR p.is_textil=p_is_textil)
      AND (p_is_thermal IS NULL OR p.is_thermal=p_is_thermal)
      AND (p_has_gift_box IS NULL OR p.has_gift_box=p_has_gift_box)
      AND (p_material_groups IS NULL  OR EXISTS(SELECT 1 FROM mat_filter   mf WHERE mf.product_id=p.id))
      AND (p_technique_groups IS NULL OR EXISTS(SELECT 1 FROM tech_filter  tf WHERE tf.product_id=p.id))
      AND (p_color_groups IS NULL     OR EXISTS(SELECT 1 FROM color_filter cf WHERE cf.product_id=p.id))
      AND (p_date_slugs IS NULL       OR EXISTS(SELECT 1 FROM date_filter  df WHERE df.product_id=p.id))
      AND (p_endomarketing IS NULL OR p_endomarketing=false OR EXISTS(SELECT 1 FROM endo_filter ef WHERE ef.product_id=p.id))
  )
  -- Brand facets
  SELECT 'brand', p.brand::text, LOWER(REGEXP_REPLACE(p.brand,'[^a-zA-Z0-9]','-','g'))::text, COUNT(DISTINCT p.id)
  FROM products p JOIN base_ids b ON b.id=p.id WHERE p.brand IS NOT NULL
  GROUP BY p.brand HAVING COUNT(DISTINCT p.id)>0

  UNION ALL
  -- Cor facets
  SELECT 'cor', cg.name, cg.slug, COUNT(DISTINCT b.id)
  FROM base_ids b JOIN product_variants pv ON pv.product_id=b.id AND pv.is_active=true
  JOIN color_variations cv ON cv.id=pv.color_id JOIN color_groups cg ON cg.id=cv.group_id
  GROUP BY cg.id,cg.name,cg.slug HAVING COUNT(DISTINCT b.id)>0

  UNION ALL
  -- Material facets
  SELECT 'material', mg.name, mg.slug, COUNT(DISTINCT b.id)
  FROM base_ids b JOIN product_materials pm ON pm.product_id=b.id AND pm.is_active=true
  JOIN material_types mt ON mt.id=pm.material_id JOIN material_groups mg ON mg.id=mt.group_id
  GROUP BY mg.id,mg.name,mg.slug HAVING COUNT(DISTINCT b.id)>0

  UNION ALL
  -- Técnica facets
  SELECT 'tecnica', tpgo.grupo_tecnica, LOWER(tpgo.grupo_tecnica), COUNT(DISTINCT b.id)
  FROM base_ids b JOIN print_area_techniques pat ON pat.product_id=b.id AND pat.is_active=true
  JOIN tabela_preco_gravacao_oficial tpgo ON tpgo.id=pat.tabela_preco_id
  WHERE tpgo.grupo_tecnica IS NOT NULL
  GROUP BY tpgo.grupo_tecnica HAVING COUNT(DISTINCT b.id)>0

  UNION ALL
  -- Target audience facets
  SELECT 'target_audience', 
    CASE val WHEN 'corporativo' THEN 'Corporativo' WHEN 'feminino' THEN 'Feminino'
             WHEN 'masculino' THEN 'Masculino' WHEN 'infantil' THEN 'Infantil'
             WHEN 'esportivo' THEN 'Esportivo' WHEN 'unissex' THEN 'Unissex'
             ELSE INITCAP(val) END,
    val, COUNT(DISTINCT b.id)
  FROM base_ids b JOIN products p ON p.id=b.id, UNNEST(p.target_audience) AS val
  GROUP BY val HAVING COUNT(DISTINCT b.id)>0;
END;
$$;


ALTER FUNCTION "public"."fn_super_filtro_facets"("p_search_term" "text", "p_category_slug" "text", "p_category_id" "uuid", "p_brands" "text"[], "p_only_in_stock" boolean, "p_min_price" numeric, "p_max_price" numeric, "p_target_audiences" "text"[], "p_is_kit" boolean, "p_is_textil" boolean, "p_is_thermal" boolean, "p_has_gift_box" boolean, "p_material_groups" "text"[], "p_technique_groups" "text"[], "p_color_groups" "text"[], "p_date_slugs" "text"[], "p_endomarketing" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_super_filtro_opcoes"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    -- Tamanhos disponíveis (apenas produtos com has_sizes=true)
    'tamanhos', (
      SELECT jsonb_agg(DISTINCT jsonb_build_object(
        'code',  pv.size_code,
        'total', cnt.total
      ) ORDER BY jsonb_build_object('code', pv.size_code, 'total', cnt.total))
      FROM product_variants pv
      JOIN products p ON p.id = pv.product_id AND p.is_active=true AND p.is_deleted=false
      JOIN (
        SELECT size_code, COUNT(DISTINCT product_id) AS total
        FROM product_variants
        WHERE is_active=true AND size_code IS NOT NULL
        GROUP BY size_code
      ) cnt ON cnt.size_code = pv.size_code
      WHERE pv.is_active=true AND pv.size_code IS NOT NULL
    ),
    -- Público-alvo distintos
    'publico_alvo', (
      SELECT jsonb_agg(jsonb_build_object('value', aud, 'total', cnt))
      FROM (
        SELECT unnest(target_audience) AS aud, COUNT(*) AS cnt
        FROM products
        WHERE is_active=true AND is_deleted=false
          AND target_audience IS NOT NULL
          AND array_length(target_audience,1) > 0
        GROUP BY aud
        ORDER BY cnt DESC
      ) t
    ),
    -- Gênero com contagem real
    'genero', (
      SELECT jsonb_agg(jsonb_build_object('value', gender, 'total', cnt))
      FROM (
        SELECT gender, COUNT(*) AS cnt
        FROM products
        WHERE is_active=true AND is_deleted=false AND gender IS NOT NULL
        GROUP BY gender ORDER BY cnt DESC
      ) t
    ),
    -- Acabamentos disponíveis
    'acabamento', (
      SELECT jsonb_agg(jsonb_build_object('value', fin, 'total', cnt))
      FROM (
        SELECT unnest(surface_finish) AS fin, COUNT(*) AS cnt
        FROM products
        WHERE is_active=true AND is_deleted=false
          AND surface_finish IS NOT NULL AND surface_finish <> '{}'
        GROUP BY fin ORDER BY cnt DESC
      ) t
    ),
    -- Técnicas de gravação (canonical)
    'tecnicas', (
      SELECT jsonb_agg(jsonb_build_object('value', engraving_type, 'total', cnt))
      FROM (
        SELECT engraving_type, COUNT(*) AS cnt
        FROM products
        WHERE is_active=true AND is_deleted=false AND engraving_type IS NOT NULL
        GROUP BY engraving_type ORDER BY cnt DESC
      ) t
    ),
    -- Stats gerais
    'total_produtos', (SELECT COUNT(*) FROM products WHERE is_active=true AND is_deleted=false),
    'em_estoque', (SELECT COUNT(*) FROM products WHERE is_active=true AND is_deleted=false AND stock_quantity > 0),
    'com_personalizacao', (SELECT COUNT(*) FROM products WHERE is_active=true AND is_deleted=false AND allows_personalization=true),
    'gerado_em', now()
  );
$$;


ALTER FUNCTION "public"."fn_super_filtro_opcoes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_super_filtro_price_range"("p_brands" "text"[] DEFAULT NULL::"text"[], "p_category_slug" "text" DEFAULT NULL::"text", "p_target_audiences" "text"[] DEFAULT NULL::"text"[], "p_is_textil" boolean DEFAULT NULL::boolean, "p_is_thermal" boolean DEFAULT NULL::boolean, "p_only_in_stock" boolean DEFAULT false) RETURNS TABLE("price_min" numeric, "price_max" numeric, "price_p25" numeric, "price_p75" numeric, "price_median" numeric, "price_avg" numeric, "total_with_price" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT
    MIN(p.sale_price) FILTER (WHERE p.sale_price >= 1)::numeric              AS price_min,
    MAX(p.sale_price)::numeric                                                AS price_max,
    PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY p.sale_price)::numeric      AS price_p25,
    PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY p.sale_price)::numeric      AS price_p75,
    PERCENTILE_CONT(0.5)  WITHIN GROUP (ORDER BY p.sale_price)::numeric      AS price_median,
    ROUND(AVG(p.sale_price), 2)::numeric                                     AS price_avg,
    COUNT(*)                                                                  AS total_with_price
  FROM products p
  LEFT JOIN product_category_assignments pca ON pca.product_id = p.id AND pca.is_primary = true
  LEFT JOIN categories c ON c.id = pca.category_id
  WHERE p.is_active = true
    AND p.is_deleted IS NOT TRUE
    AND p.sale_price IS NOT NULL AND p.sale_price > 0
    AND (p_brands IS NULL OR p.brand = ANY(p_brands))
    AND (p_category_slug IS NULL OR c.slug = p_category_slug)
    AND (p_target_audiences IS NULL OR p.target_audience && p_target_audiences)
    AND (p_is_textil IS NULL OR p.is_textil = p_is_textil)
    AND (p_is_thermal IS NULL OR p.is_thermal = p_is_thermal)
    AND (NOT p_only_in_stock OR p.is_stockout = false);
$$;


