Retorna estatísticas: total, com_cores, sem_cores.
Chamada: SELECT * FROM fn_sync_all_product_colors();';



CREATE OR REPLACE FUNCTION "public"."fn_sync_asia_colors"("p_cores" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier_id uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_org_id      uuid;
  v_inseridos   int  := 0;
  v_atualizados int  := 0;
  v_cor         jsonb;
  v_row_count   int;
BEGIN
  SELECT organization_id INTO v_org_id
  FROM supplier_colors WHERE supplier_id = v_supplier_id LIMIT 1;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'organization_id não encontrado para Asia Import';
  END IF;

  FOR v_cor IN SELECT * FROM jsonb_array_elements(p_cores)
  LOOP
    BEGIN
      INSERT INTO supplier_colors (
        supplier_id, organization_id, name, code,
        hex_code, api_color_id, image_url, source,
        is_active, is_available, api_raw_data, updated_at
      ) VALUES (
        v_supplier_id, v_org_id,
        v_cor->>'name',
        v_cor->>'slug',
        NULLIF(trim(v_cor->>'color'), ''),
        v_cor->>'id',
        NULLIF(trim(v_cor->>'photo'), ''),
        'api_hg_atributes',
        true, true, v_cor, now()
      )
      ON CONFLICT (organization_id, supplier_id, name)
      DO UPDATE SET
        code         = EXCLUDED.code,
        hex_code     = COALESCE(EXCLUDED.hex_code, supplier_colors.hex_code),
        api_color_id = COALESCE(EXCLUDED.api_color_id, supplier_colors.api_color_id),
        image_url    = COALESCE(EXCLUDED.image_url, supplier_colors.image_url),
        source       = 'api_hg_atributes',
        api_raw_data = EXCLUDED.api_raw_data,
        is_active    = true,
        updated_at   = now();

      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      -- v_row_count = 1 sempre (INSERT ou UPDATE)
      -- Usa xmax para distinguir: não disponível aqui, usa contagem simples
      v_atualizados := v_atualizados + v_row_count;

    EXCEPTION WHEN OTHERS THEN
      NULL; -- continua com as demais cores
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'processadas', v_atualizados,
    'total_input', jsonb_array_length(p_cores)
  );
END;
$$;


ALTER FUNCTION "public"."fn_sync_asia_colors"("p_cores" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_asia_colors"("p_cores" "jsonb") IS 'C4: UPSERT 51 cores canônicas do hg/atributes em supplier_colors. Enriquece api_color_id, slug, hex, photo.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_backfill_queue_on_pi_fill"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Cenário A: blurhash preenchido (NULL → valor)
  -- Marca item correspondente na fila como 'done'
  IF OLD.blurhash IS NULL AND NEW.blurhash IS NOT NULL THEN
    UPDATE public.image_backfill_queue
    SET
      status      = 'done',
      finished_at = clock_timestamp(),
      worker_id   = 'trigger-sync'
    WHERE product_image_id = NEW.id
      AND task              = 'blurhash'
      AND status            = 'pending';
  END IF;

  -- Cenário B: content_hash preenchido (NULL → valor)
  IF OLD.content_hash IS NULL AND NEW.content_hash IS NOT NULL THEN
    UPDATE public.image_backfill_queue
    SET
      status      = 'done',
      finished_at = clock_timestamp(),
      worker_id   = 'trigger-sync'
    WHERE product_image_id = NEW.id
      AND task              = 'content_hash'
      AND status            = 'pending';
  END IF;

  -- Trigger AFTER: retornar NEW não afeta a row (já commitada)
  -- mas é required pela assinatura RETURNS trigger
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_backfill_queue_on_pi_fill"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_backfill_queue_on_pi_fill"() IS 'Fired by trg_sync_backfill_queue AFTER UPDATE on product_images.
 Marks image_backfill_queue items as done when workers fill blurhash
 or content_hash directly in product_images (bypassing the queue).
 SECURITY DEFINER needed to bypass RLS on image_backfill_queue.
 Created 2026-06-18 — architectural debt fix for worker sync gap.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_category_image_url_on_slug_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  -- Constante: base da URL do Cloudflare Images (account hash fixo)
  v_base_url  CONSTANT text := 'https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/';
  -- Prefixo de naming convention para imagens de categoria
  v_prefix    CONSTANT text := 'cat-';
  -- Variant padrão (público)
  v_variant   CONSTANT text := '/public';
  -- URL canônica esperada para o slug ANTIGO
  v_old_canonical text;
BEGIN
  -- ── GUARD 1: image_url precisa estar preenchida para agir ───
  IF NEW.image_url IS NULL THEN
    RETURN NEW;
  END IF;

  -- ── GUARD 2: novo slug deve ser não-nulo e não-vazio ────────
  -- (evita construir URL inválida com NULL ou string vazia)
  IF NEW.slug IS NULL OR trim(NEW.slug) = '' THEN
    -- Slug virou nulo/vazio: decisão humana sobre image_url
    -- O trigger NÃO limpa automaticamente — preserva a URL
    RETURN NEW;
  END IF;

  -- ── GUARD 3: old slug deve ser não-nulo ─────────────────────
  -- (se OLD.slug era NULL, não havia URL canônica para comparar)
  IF OLD.slug IS NULL OR trim(OLD.slug) = '' THEN
    RETURN NEW;
  END IF;

  -- ── LÓGICA PRINCIPAL ────────────────────────────────────────
  -- Calcula a URL canônica que deveria existir para o slug ANTIGO
  v_old_canonical := v_base_url || v_prefix || OLD.slug || v_variant;

  -- Se a URL atual é exatamente a URL canônica do slug antigo:
  --   → Atualiza para a URL canônica do novo slug (sincronização automática)
  -- Se a URL atual é customizada (diferente do padrão):
  --   → NÃO altera nada (preserva intenção do autor)
  IF NEW.image_url = v_old_canonical THEN
    NEW.image_url := v_base_url || v_prefix || NEW.slug || v_variant;

    RAISE NOTICE
      '[trg_sync_image_url] category.id=% | slug: % → % | image_url atualizada automaticamente',
      NEW.id, OLD.slug, NEW.slug;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_category_image_url_on_slug_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_category_image_url_on_slug_change"() IS 'Trigger BEFORE UPDATE OF slug em categories.
Quando o slug muda, sincroniza image_url SE ela seguir o padrão canônico:
  https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/cat-{slug}/public
URLs customizadas (fora desse padrão) são preservadas sem alteração.
Guards: image_url NULL, novo slug NULL/vazio, old slug NULL → sem ação.
Emite RAISE NOTICE para auditoria em cada sincronização executada.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_color_variation_group"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.color_group_id IS DISTINCT FROM OLD.color_group_id
       AND NEW.group_id IS NOT DISTINCT FROM OLD.group_id THEN
      NEW.group_id := NEW.color_group_id;           -- canonico mudou -> espelha legado
    ELSIF NEW.group_id IS DISTINCT FROM OLD.group_id
       AND NEW.color_group_id IS NOT DISTINCT FROM OLD.color_group_id THEN
      NEW.color_group_id := NEW.group_id;           -- legado mudou -> espelha canonico
    END IF;
  END IF;
  IF NEW.color_group_id IS NULL AND NEW.group_id IS NOT NULL THEN
    NEW.color_group_id := NEW.group_id;
  ELSIF NEW.group_id IS NULL AND NEW.color_group_id IS NOT NULL THEN
    NEW.group_id := NEW.color_group_id;
  ELSIF NEW.group_id IS NOT NULL AND NEW.color_group_id IS NOT NULL
        AND NEW.group_id <> NEW.color_group_id THEN
    RAISE EXCEPTION 'color_variations: group_id(%) <> color_group_id(%) — divergencia bloqueada (fn_sync_color_variation_group)',
      NEW.group_id, NEW.color_group_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_color_variation_group"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_color_variation_group"() IS 'Mantem group_id (legado) e color_group_id (canonico) sempre identicos em color_variations. fix_version 2026-06-26 - anti-regressao, NAO REMOVER.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_derived_product_flags"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_new_expired      integer := 0;
  v_featured_exp     integer := 0;
  v_bestseller_exp   integer := 0;
BEGIN
  -- is_new: limpa produtos com novidade expirada
  UPDATE products
  SET is_new = false, updated_at = now()
  WHERE is_new = true
    AND is_new_expires_at IS NOT NULL
    AND is_new_expires_at < now();
  GET DIAGNOSTICS v_new_expired = ROW_COUNT;

  -- is_featured: limpa produtos com destaque expirado
  UPDATE products
  SET is_featured = false, updated_at = now()
  WHERE is_featured = true
    AND is_featured_expires_at IS NOT NULL
    AND is_featured_expires_at < now();
  GET DIAGNOSTICS v_featured_exp = ROW_COUNT;

  -- is_bestseller: limpa produtos com bestseller expirado
  UPDATE products
  SET is_bestseller = false, updated_at = now()
  WHERE is_bestseller = true
    AND is_bestseller_expires_at IS NOT NULL
    AND is_bestseller_expires_at < now();
  GET DIAGNOSTICS v_bestseller_exp = ROW_COUNT;

  RETURN jsonb_build_object(
    'version',               'v4_2026-06-22_removed_on_sale',
    'is_new_expired',        v_new_expired,
    'is_featured_expired',   v_featured_exp,
    'is_bestseller_expired', v_bestseller_exp
  );
END;
$$;


