COMMENT ON FUNCTION "public"."fn_sync_derived_product_flags"() IS 'Sincroniza flags derivadas em products: is_on_sale (ativa para stockout, expira por is_on_sale_expires_at), is_new / is_featured / is_bestseller (expiram por *_expires_at). Idempotente. Chamar após promote ou via cron diário.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_dimensions_display"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Se dimensions_display foi atualizado → espelhar em combined_sizes
    IF TG_OP = 'UPDATE' AND NEW.dimensions_display IS DISTINCT FROM OLD.dimensions_display THEN
        NEW.combined_sizes := NEW.dimensions_display;
    END IF;
    -- Se combined_sizes foi atualizado → espelhar em dimensions_display
    IF TG_OP = 'UPDATE' AND NEW.combined_sizes IS DISTINCT FROM OLD.combined_sizes THEN
        NEW.dimensions_display := NEW.combined_sizes;
    END IF;
    -- INSERT: garantir que ambos estejam alinhados
    IF TG_OP = 'INSERT' THEN
        IF NEW.dimensions_display IS NOT NULL AND NEW.combined_sizes IS NULL THEN
            NEW.combined_sizes := NEW.dimensions_display;
        ELSIF NEW.combined_sizes IS NOT NULL AND NEW.dimensions_display IS NULL THEN
            NEW.dimensions_display := NEW.combined_sizes;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_dimensions_display"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_dispatcher_log_from_net"() RETURNS TABLE("synced_count" integer, "failed_count" integer, "timeout_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'extensions'
    AS $$
DECLARE
  v_synced  int := 0;
  v_failed  int := 0;
  v_timeout int := 0;
  rec RECORD;
BEGIN
  FOR rec IN
    SELECT
      wdl.id                                               AS log_id,
      regexp_replace(wdl.response_body, '.*pg_net_request_id=(\d+).*', '\1')::bigint AS req_id,
      hr.status_code,
      LEFT(hr.content, 500)                               AS resp_content,
      hr.timed_out,
      hr.error_msg
    FROM public.webhook_dispatcher_log wdl
    JOIN net._http_response hr
      ON hr.id = regexp_replace(wdl.response_body, '.*pg_net_request_id=(\d+).*', '\1')::bigint
    WHERE wdl.http_status IS NULL
      AND wdl.response_body LIKE '%pg_net_request_id=%'
      AND wdl.fired_at > NOW() - INTERVAL '7 days'
  LOOP
    IF rec.timed_out THEN
      UPDATE public.webhook_dispatcher_log
      SET http_status     = 408,
          delivery_status = 'timeout',
          response_body   = 'TIMEOUT: ' || COALESCE(rec.error_msg, 'timed out'),
          responded_at    = NOW()
      WHERE id = rec.log_id;
      v_timeout := v_timeout + 1;

    ELSIF rec.status_code BETWEEN 200 AND 299 THEN
      UPDATE public.webhook_dispatcher_log
      SET http_status     = rec.status_code,
          delivery_status = 'delivered',
          response_body   = rec.resp_content
      WHERE id = rec.log_id;
      v_synced := v_synced + 1;

    ELSE
      UPDATE public.webhook_dispatcher_log
      SET http_status     = rec.status_code,
          delivery_status = 'failed',
          response_body   = rec.resp_content,
          error_message   = 'HTTP ' || rec.status_code || ': ' || LEFT(rec.resp_content, 200)
      WHERE id = rec.log_id;
      v_failed := v_failed + 1;
    END IF;
  END LOOP;

  RETURN QUERY SELECT v_synced, v_failed, v_timeout;
END;
$$;


ALTER FUNCTION "public"."fn_sync_dispatcher_log_from_net"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_dynamic_collections"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_nov_id   uuid := 'a1b2c3d4-0001-0000-0000-000000000001';
    v_stock_id uuid := 'a1b2c3d4-0002-0000-0000-000000000002';
    v_textil_id uuid := 'be449327-bb3c-4382-a564-f6151e63c410';
    v_ins_nov  int := 0;
    v_del_nov  int := 0;
    v_ins_stk  int := 0;
    v_del_stk  int := 0;
    v_ins_txt  int := 0;
BEGIN
    -- === NOVIDADES: adicionar produtos com novelty ativa ===
    INSERT INTO b2b_collection_products (b2b_collection_id, product_id, display_order, added_at)
    SELECT v_nov_id, pn.product_id,
           ROW_NUMBER() OVER (ORDER BY pn.detected_at DESC), now()
    FROM product_novelties pn
    JOIN products p ON p.id = pn.product_id
    WHERE pn.is_active = true AND p.is_active = true
    ON CONFLICT (b2b_collection_id, product_id) DO NOTHING;
    GET DIAGNOSTICS v_ins_nov = ROW_COUNT;

    -- Remover produtos cujas novelties expiraram da coleção Novidades
    DELETE FROM b2b_collection_products bcp
    WHERE bcp.b2b_collection_id = v_nov_id
      AND NOT EXISTS (
        SELECT 1 FROM product_novelties pn
        WHERE pn.product_id = bcp.product_id AND pn.is_active = true
      );
    GET DIAGNOSTICS v_del_nov = ROW_COUNT;

    -- === STOCKOUT: adicionar/remover baseado em flag ===
    INSERT INTO b2b_collection_products (b2b_collection_id, product_id, display_order, added_at)
    SELECT v_stock_id, p.id, ROW_NUMBER() OVER (ORDER BY p.name), now()
    FROM products p
    WHERE p.is_active = true AND p.is_stockout = true
    ON CONFLICT (b2b_collection_id, product_id) DO NOTHING;
    GET DIAGNOSTICS v_ins_stk = ROW_COUNT;

    DELETE FROM b2b_collection_products bcp
    WHERE bcp.b2b_collection_id = v_stock_id
      AND NOT EXISTS (
        SELECT 1 FROM products p
        WHERE p.id = bcp.product_id AND p.is_active = true AND p.is_stockout = true
      );
    GET DIAGNOSTICS v_del_stk = ROW_COUNT;

    -- === TÊXTIL: fechar gap ===
    INSERT INTO b2b_collection_products (b2b_collection_id, product_id, display_order, added_at)
    SELECT v_textil_id, p.id, ROW_NUMBER() OVER (ORDER BY p.name) + 800, now()
    FROM products p
    WHERE p.is_active = true AND p.is_textil = true
    ON CONFLICT (b2b_collection_id, product_id) DO NOTHING;
    GET DIAGNOSTICS v_ins_txt = ROW_COUNT;

    RETURN jsonb_build_object(
        'novidades_adicionados', v_ins_nov, 'novidades_removidos', v_del_nov,
        'stockout_adicionados',  v_ins_stk,  'stockout_removidos',  v_del_stk,
        'textil_adicionados',    v_ins_txt,
        'executed_at', now()
    );
END;
$$;


