COMMENT ON FUNCTION "public"."fn_sync_dynamic_collections"() IS 'Sincroniza coleções dinâmicas: Novidades (novelties ativas), Liquidação (is_stockout), Têxtil (is_textil). Executada por pg_cron diariamente.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_image_type_code"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_code text;
  v_id   uuid;
BEGIN

  -- ================================================================
  -- INSERT: OLD é NULL — branch explícito evita dependência implícita
  -- Prioridade: image_type varchar > image_type_id (callers legados passam só varchar)
  -- ================================================================
  IF TG_OP = 'INSERT' THEN
    -- Caso feliz: trg_auto_classify_image já garantiu consistência → early exit
    SELECT id, code INTO v_id, v_code FROM image_types WHERE id = NEW.image_type_id;
    IF v_id IS NOT NULL AND v_code = NEW.image_type THEN
      RETURN NEW;
    END IF;

    -- Incoerentes: derivar image_type_id do varchar (varchar = intenção do caller)
    SELECT id, code INTO v_id, v_code
    FROM image_types WHERE lower(code) = lower(NEW.image_type);
    IF v_id IS NOT NULL THEN
      NEW.image_type_id := v_id;
      NEW.image_type    := v_code;  -- canonicalizar casing
    ELSIF v_code IS NOT NULL THEN
      -- image_type inválido mas image_type_id é válido → usar FK como fallback
      NEW.image_type := v_code;
    END IF;

    RETURN NEW;
  END IF;

  -- ================================================================
  -- UPDATE: OLD existe — sync bidirecional (comportamento original mantido)
  -- ================================================================
  IF NEW.image_type_id IS DISTINCT FROM OLD.image_type_id THEN
    -- FK mudou → derivar varchar do FK
    SELECT code INTO v_code FROM image_types WHERE id = NEW.image_type_id;
    IF v_code IS NOT NULL THEN
      NEW.image_type := v_code;
    END IF;

  ELSIF NEW.image_type IS DISTINCT FROM OLD.image_type THEN
    -- VARCHAR mudou → derivar FK do varchar (com canonicalização de casing)
    SELECT id, code INTO v_id, v_code
    FROM image_types WHERE lower(code) = lower(NEW.image_type);
    IF v_id IS NOT NULL THEN
      NEW.image_type_id := v_id;
      NEW.image_type    := v_code;
    ELSE
      -- image_type inválido no UPDATE → reverter para o que o FK diz
      SELECT code INTO v_code FROM image_types WHERE id = NEW.image_type_id;
      IF v_code IS NOT NULL THEN
        NEW.image_type := v_code;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_image_type_code"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_image_type_code"() IS 'Trigger BEFORE INSERT+UPDATE em product_images.
Mantém image_type (varchar) e image_type_id (uuid FK) sempre coerentes.

INSERT: image_type varchar tem precedência.
  Se trg_auto_classify_image já garantiu consistência → early exit (fast path).
  Se incoerentes → deriva image_type_id do varchar (preserva intenção do caller).
  Se image_type inválido → usa image_type_id como fallback.

UPDATE: sync bidirecional.
  Se image_type_id mudou → deriva image_type do FK.
  Se image_type mudou → deriva image_type_id do varchar (com canonicalização de casing).
  Se image_type inválido no UPDATE → reverte para o code do FK.

Corrigido em 2026-06-17: eliminado bug onde INSERT com image_type explícito
  era sobrescrito pelo default do image_type_id, destruindo a intenção do caller.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_is_new_expires_at"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
/*
  v1_2026-06-13 — Mantém is_new_expires_at sincronizado com product_novelties.
  Chamado pelos jobs de novelty para garantir que a coluna reflita a realidade.
*/
DECLARE
  v_set int := 0;
  v_cleared int := 0;
BEGIN
  -- Setar: produtos is_new=true com novelty ativa mas is_new_expires_at NULL
  WITH d AS (
    UPDATE products p
    SET is_new_expires_at = pn.expires_at, updated_at = now()
    FROM product_novelties pn
    WHERE pn.product_id = p.id
      AND pn.is_active = true
      AND p.is_new = true
      AND (p.is_new_expires_at IS NULL OR p.is_new_expires_at != pn.expires_at)
    RETURNING 1
  ) SELECT count(*) INTO v_set FROM d;

  -- Limpar: produtos is_new=false que ainda têm is_new_expires_at preenchido
  WITH d AS (
    UPDATE products
    SET is_new_expires_at = NULL, updated_at = now()
    WHERE is_new = false
      AND is_new_expires_at IS NOT NULL
    RETURNING 1
  ) SELECT count(*) INTO v_cleared FROM d;

  RAISE NOTICE 'fn_sync_is_new_expires_at: set=% cleared=%', v_set, v_cleared;
  RETURN v_set + v_cleared;
END $$;


ALTER FUNCTION "public"."fn_sync_is_new_expires_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_is_stockout_all"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_fixed   int;
  v_t0      timestamptz := clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_sync_is_stockout_all')::bigint) THEN
    RETURN jsonb_build_object('skipped', 'lock_ocupado', 'ts', now());
  END IF;

  -- Sincronizar is_stockout baseado no stock_quantity calculado
  -- Cobre qualquer fornecedor que não atualiza is_stockout no seu sync
  UPDATE products p
  SET 
    is_stockout          = (p.stock_quantity <= 0),
    last_stock_update_at = now(),
    updated_at           = now()
  WHERE p.is_active = true
    AND p.is_stockout IS DISTINCT FROM (p.stock_quantity <= 0);

  GET DIAGNOSTICS v_fixed = ROW_COUNT;

  RETURN jsonb_build_object(
    'version',   'v1_universal_is_stockout_sync',
    'fixed',     v_fixed,
    'segundos',  round(extract(epoch FROM clock_timestamp() - v_t0)::numeric, 2),
    'ts',        now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_sync_is_stockout_all"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_is_stockout_all"() IS 'Sincroniza products.is_stockout com base em products.stock_quantity para TODOS os fornecedores. Cobre o gap de ASIA e qualquer outro fornecedor futuro que não atualiza is_stockout no sync. Idempotente. Usa advisory lock. Scheduled via pg_cron a cada 5 min.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_local_drift_to_schema_drift_log"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rec RECORD;
  v_only_oficial text[];
  v_only_lovable  text[];
BEGIN
  -- fix_version: drift_log_bridge_v1_20260627
  -- Busca a entrada mais recente de schema_signature_drift_log (check local)
  SELECT * INTO v_rec
  FROM schema_signature_drift_log
  ORDER BY ran_at DESC
  LIMIT 1;

  IF v_rec IS NULL THEN
    RETURN;
  END IF;

  -- Mapeia: tabelas adicionadas ao schema real = "only_oficial" (existem no
  -- Supabase oficial mas não no ponto de referência anterior).
  -- Tabelas removidas = "only_lovable" (estavam e sumiram).
  v_only_oficial := COALESCE(v_rec.tables_added, '{}');
  v_only_lovable  := COALESCE(v_rec.tables_removed, '{}');

  INSERT INTO schema_drift_log (
    ran_at,
    has_drift,
    tables_oficial,
    tables_lovable,
    only_oficial,
    only_lovable,
    schema_diff,
    notification_sent,
    error_message
  )
  VALUES (
    now(),
    v_rec.has_drift,
    (SELECT COUNT(DISTINCT table_name)
     FROM information_schema.tables
     WHERE table_schema = 'public'),
    (SELECT COUNT(DISTINCT table_name)
     FROM schema_signature_baseline),
    v_only_oficial,
    v_only_lovable,
    jsonb_build_object(
      'source',          'fn_check_schema_signature_drift',
      'baseline_label',  v_rec.baseline_label,
      'n_added',         v_rec.n_added,
      'n_removed',       v_rec.n_removed,
      'n_retyped',       v_rec.n_retyped,
      'columns_added',   v_rec.columns_added,
      'columns_removed', v_rec.columns_removed,
      'columns_retyped', v_rec.columns_retyped,
      'note',
        'Dados do check local (não HTTP Lovable) — bridged por fn_sync_local_drift_to_schema_drift_log'
    ),
    false,
    NULL  -- sem erro: veio do check local que funciona
  );
END;
$$;


ALTER FUNCTION "public"."fn_sync_local_drift_to_schema_drift_log"() OWNER TO "postgres";


