COMMENT ON FUNCTION "public"."fn_sync_novelty_expires_at"() IS 'Sincroniza novelty_expires_at ↔ is_new_expires_at em INSERT e UPDATE. novelty_expires_at é a coluna canônica.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_novelty_to_product"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Quando is_active muda em product_novelties, atualizar products.is_new
    
    IF TG_OP = 'UPDATE' THEN
        -- Se is_active mudou de TRUE para FALSE
        IF OLD.is_active = TRUE AND NEW.is_active = FALSE THEN
            UPDATE products 
            SET is_new = FALSE 
            WHERE id = NEW.product_id;
        END IF;
        
        -- Se is_active mudou de FALSE para TRUE (reativar)
        IF OLD.is_active = FALSE AND NEW.is_active = TRUE THEN
            UPDATE products 
            SET is_new = TRUE 
            WHERE id = NEW.product_id;
        END IF;
    END IF;
    
    IF TG_OP = 'DELETE' THEN
        -- Se deletar o registro de novidade, produto deixa de ser novo
        UPDATE products 
        SET is_new = FALSE 
        WHERE id = OLD.product_id;
    END IF;
    
    IF TG_OP = 'INSERT' THEN
        -- Se inserir novo registro de novidade, produto vira novo
        UPDATE products 
        SET is_new = TRUE 
        WHERE id = NEW.product_id;
    END IF;
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."fn_sync_novelty_to_product"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_novelty_to_product"() IS 'Sincroniza product_novelties.is_active com products.is_new automaticamente';



CREATE OR REPLACE FUNCTION "public"."fn_sync_pat_on_product_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Só age quando is_active muda
  IF NEW.is_active = OLD.is_active THEN
    RETURN NEW;
  END IF;

  IF NEW.is_active = false THEN
    -- Produto desativado: desativar todas as PATs
    UPDATE public.print_area_techniques
    SET is_active = false, updated_at = now()
    WHERE product_id = NEW.id AND is_active = true;
  END IF;
  -- Nota: NÃO reativamos PATs ao reativar produto —
  -- reativação é intencional e manual (controle de qualidade)

  RETURN NEW;
END;
$$;


