CREATE OR REPLACE FUNCTION "public"."fn_sync_product_images_to_products"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product_id UUID;
BEGIN
  v_product_id := COALESCE(NEW.product_id, OLD.product_id);

  UPDATE products SET
    images = COALESCE((
      SELECT jsonb_agg(url_cdn ORDER BY
        CASE
          WHEN image_type = 'main'    AND is_primary = true  THEN 0
          WHEN image_type = 'main'                           THEN 1
          WHEN image_type IN ('gallery','product')           THEN 2
          WHEN image_type = 'ambient'                        THEN 3
          WHEN image_type = 'set'                            THEN 4
          WHEN image_type = 'logo'                           THEN 5
          ELSE 9
        END,
        is_primary DESC,
        display_order ASC NULLS LAST
      ) FILTER (WHERE image_type NOT IN ('box','pouch','location','area','component'))
      FROM product_images
      WHERE product_id = v_product_id AND is_active = true
    ), '[]'::jsonb),

    og_image_url = (
      SELECT url_cdn FROM product_images
      WHERE product_id = v_product_id AND is_active = true
        AND image_type NOT IN ('box','pouch','location','area','component')
      ORDER BY
        CASE WHEN is_og_image = true                          THEN 0
             WHEN image_type = 'main' AND is_primary = true  THEN 1
             WHEN image_type = 'main'                         THEN 2
             WHEN image_type IN ('gallery','product')         THEN 3
             WHEN image_type = 'ambient'                      THEN 4
             WHEN image_type = 'set'                          THEN 5
             ELSE 9 END,
        is_primary DESC,
        display_order ASC NULLS LAST
      LIMIT 1
    ),

    -- CF CDN URL (primary display image)
    primary_image_url = (
      SELECT url_cdn
      FROM product_images
      WHERE product_id = v_product_id AND is_active = true
        AND image_type NOT IN ('box','pouch','location','area','component')
      ORDER BY
        CASE
          WHEN image_type = 'main'    AND is_primary = true  THEN 0
          WHEN image_type = 'main'                           THEN 1
          WHEN image_type IN ('gallery','product') AND is_primary = true THEN 2
          WHEN image_type IN ('gallery','product')           THEN 3
          WHEN image_type = 'ambient'                        THEN 4
          WHEN image_type = 'set'    AND is_primary = true  THEN 5
          WHEN image_type = 'set'                            THEN 6
          WHEN image_type = 'logo'                           THEN 7
          ELSE 9
        END,
        is_primary DESC,
        display_order ASC NULLS LAST
      LIMIT 1
    ),

    -- ─── NOVO: url_original do fornecedor como fallback quando CF falha ──────────
    -- Mesma ordem de prioridade que primary_image_url mas retorna url_original
    -- Usado pelo OptimizedImage para fallback: CF Images → supplier CDN → <ImageOff/>
    primary_image_fallback_url = (
      SELECT url_original
      FROM product_images
      WHERE product_id = v_product_id AND is_active = true
        AND url_original IS NOT NULL AND url_original != ''
      ORDER BY
        CASE
          WHEN image_type = 'main'    AND is_primary = true  THEN 0
          WHEN image_type = 'main'                           THEN 1
          WHEN image_type IN ('gallery','product') AND is_primary = true THEN 2
          WHEN image_type IN ('gallery','product')           THEN 3
          WHEN image_type = 'ambient'                        THEN 4
          WHEN image_type = 'set'    AND is_primary = true  THEN 5
          WHEN image_type = 'set'                            THEN 6
          WHEN image_type = 'logo'                           THEN 7
          ELSE 9
        END,
        is_primary DESC,
        display_order ASC NULLS LAST
      LIMIT 1
    )
    -- ────────────────────────────────────────────────────────────────────────────

  WHERE id = v_product_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."fn_sync_product_images_to_products"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_product_images_to_products"() IS 'Trigger AFTER INSERT/UPDATE/DELETE em product_images.
 Reconstrói products.images, og_image_url e primary_image_url.
 Hierarquia: main+is_primary → main → gallery/product → ambient → set → logo.
 Exclui: box, pouch, location, area, component.
 XBZ product type tratado como gallery (rank 2).
 primary_image_url nunca seleciona set antes de gallery.
 PATCH 2026-06-09 v2: hierarquia completa com product type + fix set priority.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_product_materials_to_jsonb"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product_id   UUID;
  v_new_materials JSONB;
  v_primary_mat   TEXT;
BEGIN
  v_product_id := COALESCE(NEW.product_id, OLD.product_id);
  IF v_product_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Guard anti-loop
  PERFORM set_config('app.bulk_import_mode', 'true', true);

  -- Calcular novos valores a partir dos registros ativos
  SELECT 
    COALESCE(jsonb_agg(mt.name ORDER BY pm2.sort_order, mt.name), '[]'::jsonb),
    (SELECT mt2.name
     FROM product_materials pm3
     JOIN material_types mt2 ON mt2.id = pm3.material_id
     WHERE pm3.product_id = v_product_id AND pm3.is_active = true
     ORDER BY pm3.percentage DESC NULLS LAST, pm3.sort_order ASC
     LIMIT 1)
  INTO v_new_materials, v_primary_mat
  FROM product_materials pm2
  JOIN material_types mt ON mt.id = pm2.material_id
  WHERE pm2.product_id = v_product_id AND pm2.is_active = true;

  -- Atualizar ambos os campos em uma única operação
  UPDATE products
  SET materials     = v_new_materials,
      auto_material = v_primary_mat,
      updated_at    = NOW()
  WHERE id = v_product_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."fn_sync_product_materials_to_jsonb"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_product_materials_to_jsonb"() IS 'Mantém products.materials JSONB e auto_material sincronizados com product_materials (fonte canônica).
 auto_material = material de maior percentual (material primário).
 Guard: app.bulk_import_mode=true evita loop com trg_products_auto_materials.
 v2.0 - 2026-06-11: adicionado sync de auto_material | M10';



CREATE OR REPLACE FUNCTION "public"."fn_sync_product_novelties"("p_recent_days_xbz" integer DEFAULT 60, "p_recent_days_asia" integer DEFAULT 60, "p_recent_days_sm" integer DEFAULT 60, "p_recent_days_88" integer DEFAULT 60, "p_expires_days" integer DEFAULT 60, "p_dry_run" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_stricker_id  uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
    v_xbz_id       uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
    v_asia_id      uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
    v_sm_id        uuid := '841cd690-210a-422a-908c-7676828db272';
    v_88_id        uuid;
    v_ins_stricker_new  int := 0;
    v_ins_stricker_cat  int := 0;
    v_ins_xbz           int := 0;
    v_ins_asia          int := 0;
    v_ins_sm            int := 0;
    v_ins_88            int := 0;
    v_total             int := 0;
BEGIN
    IF NOT pg_try_advisory_xact_lock(74108913) THEN
        RETURN jsonb_build_object('status','skipped','reason','advisory_lock_busy','ts',now());
    END IF;

    SELECT id INTO v_88_id FROM public.suppliers WHERE code='88BRINDES' LIMIT 1;

    IF p_dry_run THEN
        SELECT COUNT(*) INTO v_ins_stricker_new
        FROM public.products p
        JOIN public.supplier_products_raw spr
            ON spr.supplier_id=p.supplier_id
            AND SPLIT_PART(spr.supplier_sku,'-',1)=p.supplier_reference
        WHERE p.supplier_id=v_stricker_id
          AND p.is_active=true
          AND p.is_stockout=false                         -- FIX: filtro adicionado
          AND spr.raw_data->>'NewProduct'='true'
          AND COALESCE(spr.raw_data->>'IsStockOut','false')<>'true'
          AND NOT EXISTS(SELECT 1 FROM public.product_novelties pn WHERE pn.product_id=p.id AND pn.is_active=true);
        RETURN jsonb_build_object('status','dry_run','would_insert_stricker_new_product',v_ins_stricker_new,'ts',now());
    END IF;

    -- ─── STRICKER: NewProduct=true ──────────────────────────────────
    WITH to_insert AS (
        SELECT DISTINCT p.id AS product_id
        FROM public.products p
        JOIN public.supplier_products_raw spr
            ON spr.supplier_id=p.supplier_id
            AND SPLIT_PART(spr.supplier_sku,'-',1)=p.supplier_reference
        WHERE p.supplier_id=v_stricker_id
          AND p.is_active=true
          AND p.is_stockout=false                         -- FIX ←
          AND spr.raw_data->>'NewProduct'='true'
          AND COALESCE(spr.raw_data->>'IsStockOut','false')<>'true'
          AND NOT EXISTS(SELECT 1 FROM public.product_novelties pn WHERE pn.product_id=p.id AND pn.is_active=true)
    ), inserted AS (
        INSERT INTO public.product_novelties(product_id,supplier_id,supplier_code,source,detected_at,expires_at,is_active,is_highlighted,notes)
        SELECT ti.product_id,v_stricker_id,'STRICKER','spot_new_product',now(),now()+(p_expires_days||' days')::interval,true,false,
               'Detectado automaticamente via Bronze raw_data.NewProduct=true'
        FROM to_insert ti ON CONFLICT DO NOTHING RETURNING 1
    ) SELECT COUNT(*) INTO v_ins_stricker_new FROM inserted;

    -- ─── STRICKER: Catalogs Novidades ────────────────────────────────
    WITH to_insert AS (
        SELECT DISTINCT p.id AS product_id
        FROM public.products p
        JOIN public.supplier_products_raw spr
            ON spr.supplier_id=p.supplier_id
            AND SPLIT_PART(spr.supplier_sku,'-',1)=p.supplier_reference
        WHERE p.supplier_id=v_stricker_id
          AND p.is_active=true
          AND p.is_stockout=false                         -- FIX ←
          AND spr.raw_data->>'Catalogs' ILIKE '%Novidades%'
          AND COALESCE(spr.raw_data->>'NewProduct','false')<>'true'
          AND COALESCE(spr.raw_data->>'IsStockOut','false')<>'true'
          AND NOT EXISTS(SELECT 1 FROM public.product_novelties pn WHERE pn.product_id=p.id AND pn.is_active=true)
    ), inserted AS (
        INSERT INTO public.product_novelties(product_id,supplier_id,supplier_code,source,detected_at,expires_at,is_active,is_highlighted,notes)
        SELECT ti.product_id,v_stricker_id,'STRICKER','spot_catalogo_novidades',now(),now()+(p_expires_days||' days')::interval,true,false,
               'Detectado automaticamente via Bronze Catalogs contém Novidades'
        FROM to_insert ti ON CONFLICT DO NOTHING RETURNING 1
    ) SELECT COUNT(*) INTO v_ins_stricker_cat FROM inserted;

    -- ─── XBZ: recentemente promovidos ──────────────────────────────
    WITH to_insert AS (
        SELECT p.id AS product_id
        FROM public.products p
        WHERE p.supplier_id=v_xbz_id
          AND p.is_active=true
          AND p.is_stockout=false                         -- FIX ←
          AND p.created_at>=now()-(p_recent_days_xbz||' days')::interval
          AND NOT EXISTS(SELECT 1 FROM public.product_novelties pn WHERE pn.product_id=p.id AND pn.is_active=true)
    ), inserted AS (
        INSERT INTO public.product_novelties(product_id,supplier_id,supplier_code,source,detected_at,expires_at,is_active,is_highlighted,notes)
        SELECT ti.product_id,v_xbz_id,'XBZ','xbz_recently_promoted',p.created_at,p.created_at+(p_expires_days||' days')::interval,true,false,
               'XBZ promovido nos últimos '||p_recent_days_xbz||' dias'
        FROM to_insert ti JOIN public.products p ON p.id=ti.product_id
        ON CONFLICT DO NOTHING RETURNING 1
    ) SELECT COUNT(*) INTO v_ins_xbz FROM inserted;

    -- ─── ASIA: recentemente promovidos ──────────────────────────────
    WITH to_insert AS (
        SELECT p.id AS product_id
        FROM public.products p
        WHERE p.supplier_id=v_asia_id
          AND p.is_active=true
          AND p.is_stockout=false                         -- FIX ←
          AND p.created_at>=now()-(p_recent_days_asia||' days')::interval
          AND NOT EXISTS(SELECT 1 FROM public.product_novelties pn WHERE pn.product_id=p.id AND pn.is_active=true)
    ), inserted AS (
        INSERT INTO public.product_novelties(product_id,supplier_id,supplier_code,source,detected_at,expires_at,is_active,is_highlighted,notes)
        SELECT ti.product_id,v_asia_id,'ASIA','asia_recently_promoted',p.created_at,p.created_at+(p_expires_days||' days')::interval,true,false,
               'ASIA promovido nos últimos '||p_recent_days_asia||' dias'
        FROM to_insert ti JOIN public.products p ON p.id=ti.product_id
        ON CONFLICT DO NOTHING RETURNING 1
    ) SELECT COUNT(*) INTO v_ins_asia FROM inserted;

    -- ─── SOMARCAS ────────────────────────────────────────────────────
    WITH to_insert AS (
        SELECT p.id AS product_id
        FROM public.products p
        WHERE p.supplier_id=v_sm_id
          AND p.is_active=true
          AND p.is_stockout=false                         -- FIX ←
          AND p.created_at>=now()-(p_recent_days_sm||' days')::interval
          AND NOT EXISTS(SELECT 1 FROM public.product_novelties pn WHERE pn.product_id=p.id AND pn.is_active=true)
    ), inserted AS (
        INSERT INTO public.product_novelties(product_id,supplier_id,supplier_code,source,detected_at,expires_at,is_active,is_highlighted,notes)
        SELECT ti.product_id,v_sm_id,'SOMARCAS','sm_recently_promoted',p.created_at,p.created_at+(p_expires_days||' days')::interval,true,false,
               'SOMARCAS promovido nos últimos '||p_recent_days_sm||' dias'
        FROM to_insert ti JOIN public.products p ON p.id=ti.product_id
        ON CONFLICT DO NOTHING RETURNING 1
    ) SELECT COUNT(*) INTO v_ins_sm FROM inserted;

    -- ─── 88BRINDES ──────────────────────────────────────────────────
    IF v_88_id IS NOT NULL THEN
        WITH to_insert AS (
            SELECT p.id AS product_id
            FROM public.products p
            WHERE p.supplier_id=v_88_id
              AND p.is_active=true
              AND p.is_stockout=false                     -- FIX ←
              AND p.created_at>=now()-(p_recent_days_88||' days')::interval
              AND NOT EXISTS(SELECT 1 FROM public.product_novelties pn WHERE pn.product_id=p.id AND pn.is_active=true)
        ), inserted AS (
            INSERT INTO public.product_novelties(product_id,supplier_id,supplier_code,source,detected_at,expires_at,is_active,is_highlighted,notes)
            SELECT ti.product_id,v_88_id,'88BRINDES','88brindes_recently_promoted',p.created_at,p.created_at+(p_expires_days||' days')::interval,true,false,
                   '88BRINDES promovido nos últimos '||p_recent_days_88||' dias'
            FROM to_insert ti JOIN public.products p ON p.id=ti.product_id
            ON CONFLICT DO NOTHING RETURNING 1
        ) SELECT COUNT(*) INTO v_ins_88 FROM inserted;
    END IF;

    v_total := v_ins_stricker_new+v_ins_stricker_cat+v_ins_xbz+v_ins_asia+v_ins_sm+v_ins_88;

    RETURN jsonb_build_object(
        'status','ok','total_inserted',v_total,
        'stricker_new_product',v_ins_stricker_new,'stricker_catalogo',v_ins_stricker_cat,
        'xbz',v_ins_xbz,'asia',v_ins_asia,'somarcas',v_ins_sm,'88brindes',v_ins_88,
        'params',jsonb_build_object('expires_days',p_expires_days,
            'recent_days_xbz',p_recent_days_xbz,'recent_days_asia',p_recent_days_asia,
            'recent_days_sm',p_recent_days_sm,'recent_days_88',p_recent_days_88),
        'ran_at',now()
    );
END;
$$;


ALTER FUNCTION "public"."fn_sync_product_novelties"("p_recent_days_xbz" integer, "p_recent_days_asia" integer, "p_recent_days_sm" integer, "p_recent_days_88" integer, "p_expires_days" integer, "p_dry_run" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_product_novelties"("p_recent_days_xbz" integer, "p_recent_days_asia" integer, "p_recent_days_sm" integer, "p_recent_days_88" integer, "p_expires_days" integer, "p_dry_run" boolean) IS 'Detecta novidades por fornecedor e popula product_novelties. STRICKER: Bronze NewProduct=true e Catalogs=Novidades. XBZ/ASIA/SOMARCAS/88BRINDES: produtos promovidos recentemente. Idempotente, advisory lock 74108913. Retorna JSON com contagens.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_product_physical_from_products"("p_product_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
    v_weight_g   numeric; v_height_cm  numeric; v_width_cm   numeric; v_length_cm  numeric;
    v_diam_cm    numeric; v_cap_ml     numeric; v_shape      text;
    v_blen_cm    numeric; v_bwid_cm    numeric; v_bhei_cm    numeric;
    v_bwkg       numeric; v_bvol_cm3   numeric; v_bqty       integer;
    v_boxlen_mm  numeric; v_boxwid_mm  numeric; v_boxhei_mm  numeric; v_sat_existe boolean;
BEGIN
    SELECT
        NULLIF(weight_g,0), NULLIF(height_cm,0), NULLIF(width_cm,0), NULLIF(length_cm,0),
        NULLIF(diameter_cm,0), NULLIF(capacity_ml,0), shape_type,
        NULLIF(box_length_cm,0), NULLIF(box_width_cm,0), NULLIF(box_height_cm,0),
        NULLIF(box_weight_kg,0), NULLIF(box_volume_cm3,0), box_quantity,
        NULLIF(box_length_mm,0), NULLIF(box_width_mm,0), NULLIF(box_height_mm,0)
    INTO v_weight_g, v_height_cm, v_width_cm, v_length_cm, v_diam_cm, v_cap_ml, v_shape,
         v_blen_cm, v_bwid_cm, v_bhei_cm, v_bwkg, v_bvol_cm3, v_bqty,
         v_boxlen_mm, v_boxwid_mm, v_boxhei_mm
    FROM products WHERE id = p_product_id;

    IF NOT FOUND THEN RETURN FALSE; END IF;
    v_sat_existe := EXISTS(SELECT 1 FROM product_physical WHERE product_id = p_product_id);

    IF v_weight_g IS NULL AND v_height_cm IS NULL AND v_width_cm IS NULL
       AND v_length_cm IS NULL AND v_diam_cm IS NULL AND v_cap_ml IS NULL
       AND v_blen_cm IS NULL AND v_bwid_cm IS NULL AND v_bhei_cm IS NULL
       AND v_boxlen_mm IS NULL AND v_boxwid_mm IS NULL AND v_boxhei_mm IS NULL
       AND v_bqty IS NULL AND v_bwkg IS NULL AND v_bvol_cm3 IS NULL
       AND (v_shape IS NULL OR NOT v_sat_existe) THEN
        RETURN FALSE;
    END IF;

    IF v_boxlen_mm IS NOT NULL THEN v_blen_cm := v_boxlen_mm / 10.0; END IF;
    IF v_boxwid_mm IS NOT NULL THEN v_bwid_cm := v_boxwid_mm / 10.0; END IF;
    IF v_boxhei_mm IS NOT NULL THEN v_bhei_cm := v_boxhei_mm / 10.0; END IF;

    INSERT INTO product_physical (
        product_id, length_cm, width_cm, height_cm, diameter_cm,
        weight_g, capacity_ml, shape_type,
        box_length_cm, box_width_cm, box_height_cm,
        box_weight_kg, box_volume_cm3, box_quantity, created_at, updated_at
    ) VALUES (
        p_product_id, v_length_cm, v_width_cm, v_height_cm, v_diam_cm,
        v_weight_g, v_cap_ml, v_shape,
        v_blen_cm, v_bwid_cm, v_bhei_cm, v_bwkg, v_bvol_cm3, v_bqty, now(), now()
    )
    ON CONFLICT (product_id) DO UPDATE SET
        weight_g       = EXCLUDED.weight_g,
        height_cm      = EXCLUDED.height_cm,
        width_cm       = EXCLUDED.width_cm,
        length_cm      = EXCLUDED.length_cm,
        diameter_cm    = EXCLUDED.diameter_cm,
        capacity_ml    = EXCLUDED.capacity_ml,
        shape_type     = EXCLUDED.shape_type,
        box_length_cm  = EXCLUDED.box_length_cm,
        box_width_cm   = EXCLUDED.box_width_cm,
        box_height_cm  = EXCLUDED.box_height_cm,
        box_weight_kg  = EXCLUDED.box_weight_kg,
        box_volume_cm3 = EXCLUDED.box_volume_cm3,
        box_quantity   = EXCLUDED.box_quantity,
        updated_at     = now()
    WHERE (
        product_physical.weight_g       IS DISTINCT FROM EXCLUDED.weight_g       OR
        product_physical.height_cm      IS DISTINCT FROM EXCLUDED.height_cm      OR
        product_physical.width_cm       IS DISTINCT FROM EXCLUDED.width_cm       OR
        product_physical.length_cm      IS DISTINCT FROM EXCLUDED.length_cm      OR
        product_physical.diameter_cm    IS DISTINCT FROM EXCLUDED.diameter_cm    OR
        product_physical.capacity_ml    IS DISTINCT FROM EXCLUDED.capacity_ml    OR
        product_physical.shape_type     IS DISTINCT FROM EXCLUDED.shape_type     OR
        product_physical.box_length_cm  IS DISTINCT FROM EXCLUDED.box_length_cm  OR
        product_physical.box_width_cm   IS DISTINCT FROM EXCLUDED.box_width_cm   OR
        product_physical.box_height_cm  IS DISTINCT FROM EXCLUDED.box_height_cm  OR
        product_physical.box_weight_kg  IS DISTINCT FROM EXCLUDED.box_weight_kg  OR
        product_physical.box_volume_cm3 IS DISTINCT FROM EXCLUDED.box_volume_cm3 OR
        product_physical.box_quantity   IS DISTINCT FROM EXCLUDED.box_quantity
    );
    RETURN true;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_sync_product_physical_from_products(%) error: %', p_product_id, SQLERRM;
    RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."fn_sync_product_physical_from_products"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_product_physical_from_products"("p_product_id" "uuid") IS 'Copia dados físicos de products → product_physical. Idempotente via ON CONFLICT. Chamada por fn_promote_padronizacao após cada promote SPOT.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_product_seo_on_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  INSERT INTO public.product_seo (
    product_id, meta_title, meta_description, meta_keywords,
    canonical_url, robots_meta, og_title, og_description, og_image_url,
    schema_json, seo_score, seo_issues, seo_last_audit_at, updated_at
  )
  VALUES (
    NEW.id,
    NEW.meta_title, NEW.meta_description, NEW.meta_keywords,
    NEW.canonical_url, COALESCE(NEW.robots_meta,'index, follow'),
    NEW.og_title, NEW.og_description, NEW.og_image_url,
    NEW.schema_json, COALESCE(NEW.seo_score,0),
    COALESCE(NEW.seo_issues,'[]'::jsonb),
    NEW.seo_last_audit_at, now()
  )
  ON CONFLICT (product_id) DO UPDATE SET
    meta_title        = EXCLUDED.meta_title,
    meta_description  = EXCLUDED.meta_description,
    meta_keywords     = EXCLUDED.meta_keywords,
    canonical_url     = EXCLUDED.canonical_url,
    robots_meta       = EXCLUDED.robots_meta,
    og_title          = EXCLUDED.og_title,
    og_description    = EXCLUDED.og_description,
    og_image_url      = EXCLUDED.og_image_url,
    schema_json       = EXCLUDED.schema_json,
    seo_score         = EXCLUDED.seo_score,
    seo_issues        = EXCLUDED.seo_issues,
    seo_last_audit_at = EXCLUDED.seo_last_audit_at,
    updated_at        = now();
  RETURN NEW;
END;
$$;


