CREATE OR REPLACE FUNCTION "public"."fn_sync_stock_bronze_to_gold"("p_supplier_id" "uuid", "p_parent_ref" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_silver_updated int;
  v_gold_updated   int;
BEGIN
  -- ── PASSO 1: Bronze stock_data → Silver ──────────────────────────────────
  -- Atualiza SOMENTE os campos de estoque no Silver
  -- Fonte: supplier_products_raw.stock_data (Bronze)
  UPDATE public.produtos_padronizacao_variantes ppv
  SET
    stock_quantity  = public.fn_safe_int(spr.stock_data->>'Quantity'),
    next_quantity_1 = NULLIF(public.fn_safe_int(spr.stock_data->>'NextQuantity1'), 0),
    next_quantity_2 = NULLIF(public.fn_safe_int(spr.stock_data->>'NextQuantity2'), 0),
    next_quantity_3 = NULLIF(public.fn_safe_int(spr.stock_data->>'NextQuantity3'), 0),
    next_date_1     = NULLIF(spr.stock_data->>'NextDate1', '')::date,
    next_date_2     = NULLIF(spr.stock_data->>'NextDate2', '')::date,
    next_date_3     = NULLIF(spr.stock_data->>'NextDate3', '')::date,
    updated_at      = now()
  FROM public.supplier_products_raw spr
  WHERE ppv.raw_id      = spr.id
    AND ppv.supplier_id = p_supplier_id
    AND spr.supplier_id = p_supplier_id
    AND spr.stock_data  IS NOT NULL
    AND (p_parent_ref IS NULL OR ppv.parent_reference = p_parent_ref);

  GET DIAGNOSTICS v_silver_updated = ROW_COUNT;

  -- ── PASSO 2: Silver → Gold (VSS) ─────────────────────────────────────────
  -- Propaga stock_quantity e lotes 1-3 do Silver para o Gold
  -- COALESCE garante que VSS sem Silver ainda preserva valor existente
  UPDATE public.variant_supplier_sources vss
  SET
    quantity             = COALESCE(ppv.stock_quantity, vss.quantity),
    stock_main_warehouse = COALESCE(ppv.stock_quantity, vss.stock_main_warehouse),
    next_quantity_1      = COALESCE(ppv.next_quantity_1, vss.next_quantity_1),
    next_quantity_2      = COALESCE(ppv.next_quantity_2, vss.next_quantity_2),
    next_quantity_3      = COALESCE(ppv.next_quantity_3, vss.next_quantity_3),
    next_date_1          = COALESCE(ppv.next_date_1, vss.next_date_1),
    next_date_2          = COALESCE(ppv.next_date_2, vss.next_date_2),
    next_date_3          = COALESCE(ppv.next_date_3, vss.next_date_3),
    last_synced_at       = now(),
    source               = 'silver',
    updated_at           = now()
  FROM public.produtos_padronizacao_variantes ppv
  WHERE vss.variant_id  = ppv.variant_id
    AND vss.supplier_id = ppv.supplier_id
    AND ppv.supplier_id = p_supplier_id
    AND ppv.stock_quantity IS NOT NULL
    AND (p_parent_ref IS NULL OR ppv.parent_reference = p_parent_ref);

  GET DIAGNOSTICS v_gold_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'silver_updated', v_silver_updated,
    'gold_updated',   v_gold_updated,
    'supplier_id',    p_supplier_id,
    'parent_ref',     p_parent_ref
  );
END;
$$;


ALTER FUNCTION "public"."fn_sync_stock_bronze_to_gold"("p_supplier_id" "uuid", "p_parent_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_stock_bronze_to_gold_spot"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated int;
BEGIN
  WITH source AS (
    SELECT 
      spr.supplier_sku as sku,
      (spr.stock_data->>'Quantity')::int as qty
    FROM supplier_products_raw spr
    JOIN suppliers s ON s.id=spr.supplier_id
    WHERE s.code='STRICKER'
      AND spr.stock_data IS NOT NULL
      AND spr.stock_data->>'Quantity' IS NOT NULL
  )
  UPDATE product_variants pv
  SET 
    stock_quantity = src.qty,
    updated_at = now()
  FROM source src
  WHERE pv.sku = src.sku
    AND (pv.stock_quantity IS DISTINCT FROM src.qty);
  
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN jsonb_build_object('synced_variants', v_updated, 'synced_at', now());
END;
$$;


ALTER FUNCTION "public"."fn_sync_stock_bronze_to_gold_spot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_variant_to_product"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_product_id UUID;
    v_total_qty INTEGER;
    v_is_stockout BOOLEAN;
BEGIN
    -- Buscar product_id da variant
    v_product_id := NEW.product_id;
    
    -- Pular se product_id é NULL
    IF v_product_id IS NULL THEN
        RETURN NEW;
    END IF;
    
    -- Agregar estoque de todas as variantes do produto
    SELECT 
        COALESCE(SUM(stock_quantity), 0),
        COALESCE(SUM(stock_quantity), 0) = 0
    INTO v_total_qty, v_is_stockout
    FROM product_variants
    WHERE product_id = v_product_id
      AND is_active = true;
    
    -- Atualizar products
    UPDATE products
    SET 
        stock_quantity = v_total_qty,
        is_stockout = v_is_stockout,
        last_stock_update_at = NOW(),
        updated_at = NOW()
    WHERE id = v_product_id;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_variant_to_product"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_variant_to_product"() IS 'Agrega estoque de todas as variantes ativas para products.stock_quantity.
Disparado quando stock_quantity muda em product_variants.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_vss_to_variant"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_variant_id UUID;
    v_total_qty INTEGER;
    v_total_reserved INTEGER;
BEGIN
    -- Determinar variant_id afetado
    IF TG_OP = 'DELETE' THEN
        v_variant_id := OLD.variant_id;
    ELSE
        v_variant_id := NEW.variant_id;
    END IF;
    
    -- Pular se variant_id é NULL
    IF v_variant_id IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;
    
    -- Agregar estoque de todos os fornecedores ATIVOS para esta variante
    SELECT 
        COALESCE(SUM(quantity), 0),
        COALESCE(SUM(reserved_quantity), 0)
    INTO v_total_qty, v_total_reserved
    FROM variant_supplier_sources
    WHERE variant_id = v_variant_id
      AND is_active = true;
    
    -- Atualizar product_variants
    UPDATE product_variants
    SET 
        stock_quantity = v_total_qty,
        updated_at = NOW()
    WHERE id = v_variant_id;
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


