CREATE OR REPLACE FUNCTION "public"."fn_toggle_group_similarity_pairs"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF OLD.is_active IS NOT DISTINCT FROM NEW.is_active THEN
    RETURN NEW;
  END IF;

  IF NEW.is_active = true THEN
    INSERT INTO product_relationships
      (product_id, related_product_id, relationship_type, is_bidirectional, is_active, display_order)
    SELECT m1.product_id, m2.product_id, 'similar', true, true, 0
    FROM product_similarity_group_members m1
    JOIN product_similarity_group_members m2
      ON m1.group_id = m2.group_id
      AND m1.product_id != m2.product_id
      AND m1.supplier_id != m2.supplier_id
    WHERE m1.group_id = NEW.id
    ON CONFLICT (product_id, related_product_id, relationship_type) DO NOTHING;
  ELSE
    DELETE FROM product_relationships pr
    WHERE pr.relationship_type = 'similar'
      AND EXISTS (
        SELECT 1
        FROM product_similarity_group_members m1
        JOIN product_similarity_group_members m2
          ON m1.group_id = m2.group_id
          AND m1.product_id != m2.product_id
          AND m1.supplier_id != m2.supplier_id
        WHERE m1.group_id = OLD.id
          AND m1.product_id = pr.product_id
          AND m2.product_id = pr.related_product_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM product_similarity_group_members ma
        JOIN product_similarity_group_members mb
          ON ma.group_id = mb.group_id
          AND ma.product_id != mb.product_id
          AND ma.supplier_id != mb.supplier_id
        JOIN product_similarity_groups g ON g.id = ma.group_id
        WHERE g.is_active = true
          AND g.id != OLD.id
          AND ma.product_id = pr.product_id
          AND mb.product_id = pr.related_product_id
      );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_toggle_group_similarity_pairs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_tokenize_product_tags"("p_name" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $_$
  SELECT COALESCE(jsonb_agg(tok ORDER BY first_ord), '[]'::jsonb)
  FROM (
    SELECT tok, MIN(ord) AS first_ord
    FROM (
      SELECT t.tok, t.ord
      FROM regexp_split_to_table(lower(COALESCE(p_name,'')), '[^a-z0-9áàâãäéèêëíìîïóòôõöúùûüçñ]+')
           WITH ORDINALITY AS t(tok, ord)
    ) x
    WHERE length(tok) >= 3
      AND tok !~ '^[0-9]+$'
      AND tok NOT IN ('para','pelo','pela','pelos','pelas','sobre','entre','cada','como','mais','menos',
                      'este','esta','isso','aquele','aquela','seus','suas','com','por','dos','das','uma',
                      'uns','umas','até','ate','the','and','pçs','pcs','und','unid','tipo','modelo',
                      'unidade','unidades','aprox','aproximadamente')
    GROUP BY tok
    ORDER BY MIN(ord)
    LIMIT 12
  ) y;
$_$;


ALTER FUNCTION "public"."fn_tokenize_product_tags"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trg_compat_sync_optional"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    PERFORM fn_recalc_has_optional_packaging(OLD.product_id); RETURN OLD;
  ELSE
    PERFORM fn_recalc_has_optional_packaging(NEW.product_id);
    IF TG_OP='UPDATE' AND NEW.product_id IS DISTINCT FROM OLD.product_id THEN
      PERFORM fn_recalc_has_optional_packaging(OLD.product_id);
    END IF;
    RETURN NEW;
  END IF;
END$$;


