CREATE OR REPLACE FUNCTION "public"."fn_trg_sync_category_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Só age se category_id foi definido/mudou e existe valor válido
  IF NEW.category_id IS NULL OR NEW.category_id IS NOT DISTINCT FROM OLD.category_id THEN
    RETURN NEW;
  END IF;

  -- Inserir no PCA SOMENTE se o produto ainda não tem NENHUMA categoria
  -- (não sobrescreve curadoria manual ou categorizações mais específicas)
  INSERT INTO product_category_assignments (product_id, category_id, is_primary, display_order, created_at)
  SELECT NEW.id, NEW.category_id, true, 0, now()
  WHERE NOT EXISTS (
    SELECT 1 FROM product_category_assignments pca WHERE pca.product_id = NEW.id
  )
  ON CONFLICT (product_id, category_id) DO NOTHING;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trg_sync_category_assignment"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_trg_sync_category_assignment"() IS 'Sincroniza products.category_id → PCA SOMENTE para produtos sem nenhuma categoria ainda.
Não sobrescreve curadoria manual ou categorias mais específicas no PCA.
Conservador por design: previne loops pipeline→PCA→category_id.';



CREATE OR REPLACE FUNCTION "public"."fn_trg_sync_physical_on_product_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF (
    NEW.weight_g       IS DISTINCT FROM OLD.weight_g       OR
    NEW.height_cm      IS DISTINCT FROM OLD.height_cm      OR
    NEW.width_cm       IS DISTINCT FROM OLD.width_cm       OR
    NEW.length_cm      IS DISTINCT FROM OLD.length_cm      OR
    NEW.diameter_cm    IS DISTINCT FROM OLD.diameter_cm    OR
    NEW.capacity_ml    IS DISTINCT FROM OLD.capacity_ml    OR
    NEW.shape_type     IS DISTINCT FROM OLD.shape_type     OR
    NEW.box_length_cm  IS DISTINCT FROM OLD.box_length_cm  OR
    NEW.box_width_cm   IS DISTINCT FROM OLD.box_width_cm   OR
    NEW.box_height_cm  IS DISTINCT FROM OLD.box_height_cm  OR
    NEW.box_quantity   IS DISTINCT FROM OLD.box_quantity   OR
    NEW.box_weight_kg  IS DISTINCT FROM OLD.box_weight_kg  OR
    NEW.box_volume_cm3 IS DISTINCT FROM OLD.box_volume_cm3 OR
    NEW.box_length_mm  IS DISTINCT FROM OLD.box_length_mm  OR
    NEW.box_width_mm   IS DISTINCT FROM OLD.box_width_mm   OR
    NEW.box_height_mm  IS DISTINCT FROM OLD.box_height_mm
  ) THEN
    PERFORM public.fn_sync_product_physical_from_products(NEW.id);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trg_sync_physical_on_product_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trigger_auto_classify_product"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_result JSONB;
    v_category_id UUID;
BEGIN
    -- ========================================
    -- CONDIÇÕES PARA EXECUTAR:
    -- 1. Nome deve existir
    -- 2. Categoria deve ser NULL (não sobrescreve)
    -- 3. Apenas em INSERT ou UPDATE do campo name
    -- ========================================
    
    -- Se já tem categoria, não faz nada
    IF NEW.category_id IS NOT NULL THEN
        RETURN NEW;
    END IF;
    
    -- Se não tem nome, não faz nada
    IF NEW.name IS NULL OR TRIM(NEW.name) = '' THEN
        RETURN NEW;
    END IF;
    
    -- Em UPDATE, só executa se o nome mudou
    IF TG_OP = 'UPDATE' THEN
        IF OLD.name = NEW.name AND OLD.category_id IS NOT NULL THEN
            RETURN NEW;
        END IF;
    END IF;
    
    -- ========================================
    -- EXECUTAR CLASSIFICAÇÃO
    -- ========================================
    BEGIN
        -- Chamar função master de classificação
        SELECT fn_master_classify_product(NEW.name, NEW.id) INTO v_result;
        
        -- Extrair category_id do resultado
        IF v_result IS NOT NULL AND v_result->>'category_id' IS NOT NULL THEN
            v_category_id := (v_result->>'category_id')::UUID;
            
            -- Atualizar categoria no NEW
            NEW.category_id := v_category_id;
            
            -- Log opcional (comentar em produção se necessário)
            RAISE NOTICE 'Auto-classificado: % -> % (%)', 
                NEW.name, 
                v_result->>'category_slug',
                v_result->>'detected_type';
        END IF;
        
    EXCEPTION WHEN OTHERS THEN
        -- Em caso de erro, apenas loga e continua
        RAISE WARNING 'Erro ao classificar produto %: %', NEW.id, SQLERRM;
    END;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trigger_auto_classify_product"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trigger_auto_extract_attributes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_capacity INTEGER;
    v_dimensions JSONB;
    v_weight INTEGER;
    v_keywords TEXT[];
BEGIN
    -- Validação básica
    IF NEW.name IS NULL OR TRIM(NEW.name) = '' THEN
        RETURN NEW;
    END IF;
    
    -- Se UPDATE e nome não mudou, não fazer nada
    IF TG_OP = 'UPDATE' AND OLD.name = NEW.name THEN
        RETURN NEW;
    END IF;
    
    -- ═══════════════════════════════════════════════════════════
    -- ❌ NÃO EXTRAIR CORES DO NOME
    -- ═══════════════════════════════════════════════════════════
    -- MOTIVO: Conflita com arquitetura existente de cores
    -- As cores devem vir de:
    --   product_variants.color_id → color_variations
    -- E serem agregadas em products.colors[] via função separada
    -- ═══════════════════════════════════════════════════════════
    
    -- 1. Extrair capacidade (ml/L)
    IF NEW.capacity_ml IS NULL THEN
        v_capacity := fn_extract_capacity_from_name(NEW.name);
        IF v_capacity IS NOT NULL THEN
            NEW.capacity_ml := v_capacity;
            NEW.has_capacity := true;
        END IF;
    END IF;
    
    -- 2. Extrair dimensões (AxBxC cm/mm)
    IF NEW.length_cm IS NULL AND NEW.width_cm IS NULL AND NEW.height_cm IS NULL THEN
        v_dimensions := fn_extract_dimensions_from_name(NEW.name);
        IF v_dimensions IS NOT NULL THEN
            NEW.length_cm := (v_dimensions->>'length_cm')::NUMERIC;
            NEW.width_cm := (v_dimensions->>'width_cm')::NUMERIC;
            NEW.height_cm := (v_dimensions->>'height_cm')::NUMERIC;
        END IF;
    END IF;
    
    -- 3. Extrair peso (g/kg)
    IF NEW.weight_g IS NULL THEN
        v_weight := fn_extract_weight_from_name(NEW.name);
        IF v_weight IS NOT NULL THEN
            NEW.weight_g := v_weight;
        END IF;
    END IF;
    
    -- 4. Extrair keywords (para SEO)
    IF NEW.meta_keywords IS NULL OR array_length(NEW.meta_keywords, 1) IS NULL THEN
        v_keywords := fn_extract_keywords_from_name(NEW.name);
        IF array_length(v_keywords, 1) > 0 THEN
            NEW.meta_keywords := v_keywords;
        END IF;
    END IF;
    
    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Erro em fn_trigger_auto_extract_attributes: %', SQLERRM;
    RETURN NEW;
END;
$$;


