CREATE OR REPLACE FUNCTION "public"."fn_trigger_calculate_sale_price"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_markup numeric := 115.0;
BEGIN
    IF NEW.cost_price IS NULL OR NEW.cost_price <= 0 THEN
        RETURN NEW;
    END IF;

    -- Só recalcula se cost_price mudou, ou sale_price está vazio
    IF TG_OP = 'UPDATE'
       AND OLD.cost_price IS NOT DISTINCT FROM NEW.cost_price
       AND NEW.sale_price IS NOT NULL
    THEN
        RETURN NEW;
    END IF;

    -- ── Hierarquia de markup ──────────────────────────────────────────────
    -- 1. Produto específico  (product_id = este produto)
    -- 2. Categoria           (category_id = categoria do produto)
    -- 3. Fornecedor          (supplier_id = fornecedor do produto)
    -- 4. Global              (todos os IDs NULL)
    -- Desempate por especificidade: produto(1000) > categoria(100) > fornecedor(10) > global(0)
    SELECT mc.markup_percent
    INTO   v_markup
    FROM   markup_configurations mc
    WHERE  mc.is_active = true
      AND (mc.product_id  IS NULL OR mc.product_id  = NEW.id)
      AND (mc.category_id IS NULL OR mc.category_id = NEW.category_id)
      AND (mc.supplier_id IS NULL OR mc.supplier_id = NEW.supplier_id)
    ORDER BY
        (CASE WHEN mc.product_id  IS NOT NULL THEN 1000 ELSE 0 END) +
        (CASE WHEN mc.category_id IS NOT NULL THEN 100  ELSE 0 END) +
        (CASE WHEN mc.supplier_id IS NOT NULL THEN 10   ELSE 0 END)
        DESC
    LIMIT 1;

    -- Fallback: default_markup_percent do fornecedor
    IF v_markup IS NULL AND NEW.supplier_id IS NOT NULL THEN
        SELECT COALESCE(s.default_markup_percent, 115.0)
        INTO   v_markup
        FROM   suppliers s
        WHERE  s.id = NEW.supplier_id AND s.active = true;
    END IF;

    -- Fallback final
    v_markup := COALESCE(v_markup, 115.0);

    NEW.sale_price := ROUND(NEW.cost_price * (1 + v_markup / 100), 2);

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trigger_calculate_sale_price"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_trigger_calculate_sale_price"() IS 'Recalcula sale_price = cost_price × (1 + markup/100) em todo INSERT ou UPDATE de cost_price.
Hierarquia de markup: produto > categoria > fornecedor > global (markup_configurations) > suppliers.default_markup_percent > 115%.';



CREATE OR REPLACE FUNCTION "public"."fn_trigger_classify_packing"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_classification JSONB;
    v_class TEXT;
BEGIN
    -- Classificar a partir do packing_type
    IF NEW.packing_type IS NOT NULL AND NEW.packing_type <> '' THEN
        v_classification := fn_classify_packing_type(NEW.packing_type);
        IF v_classification IS NOT NULL THEN
            v_class := v_classification->>'classification';
            NEW.packing_classification := v_class::VARCHAR;
        END IF;
    ELSE
        -- Tentar extrair da descrição
        IF NEW.description IS NOT NULL AND NEW.description <> '' THEN
            DECLARE v_extracted JSONB;
            BEGIN
                v_extracted := fn_extract_packaging_from_description(NEW.description);
                IF v_extracted IS NOT NULL AND (v_extracted->>'found')::boolean = true THEN
                    NEW.packing_type := v_extracted->>'packaging_text';
                    v_classification := fn_classify_packing_type(NEW.packing_type);
                    IF v_classification IS NOT NULL THEN
                        v_class := v_classification->>'classification';
                        NEW.packing_classification := v_class::VARCHAR;
                    END IF;
                END IF;
            END;
        END IF;
    END IF;

    -- Setar flags derivados de forma atômica (mesmo passo)
    -- Assim, UPDATE de packing_type propaga corretamente para todas as flags
    IF NEW.packing_classification = 'commercial' THEN
        NEW.has_gift_box := TRUE;
        NEW.has_commercial_packaging := TRUE;
        NEW.has_optional_packaging := FALSE;
    ELSIF NEW.packing_classification = 'protective' THEN
        NEW.has_gift_box := FALSE;
        NEW.has_commercial_packaging := FALSE;
        NEW.has_optional_packaging := TRUE;
    ELSIF NEW.packing_classification IN ('none','unknown') OR NEW.packing_classification IS NULL THEN
        NEW.has_gift_box := FALSE;
        NEW.has_commercial_packaging := FALSE;
        NEW.has_optional_packaging := FALSE;
    END IF;

    RETURN NEW;
END;
$$;


