CREATE OR REPLACE FUNCTION "public"."fn_trigger_propagate_fpr"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;
    IF OLD.name IS NOT DISTINCT FROM NEW.name AND OLD.parent_id IS NOT DISTINCT FROM NEW.parent_id THEN RETURN NEW; END IF;
    IF OLD.parent_id IS DISTINCT FROM NEW.parent_id THEN
        WITH RECURSIVE sub AS (
            SELECT c.id,
                   NEW.full_path_readable||' > '||UPPER(COALESCE(c.name,'')) AS fpr,
                   NEW.path||c.id::TEXT||'/'                                   AS p,
                   NEW.level+1                                                  AS lv
            FROM categories c WHERE c.parent_id = NEW.id
            UNION ALL
            SELECT c2.id, s.fpr||' > '||UPPER(COALESCE(c2.name,'')), s.p||c2.id::TEXT||'/', s.lv+1
            FROM categories c2 JOIN sub s ON c2.parent_id = s.id
        )
        UPDATE categories ct
        SET full_path_readable = s.fpr, path = s.p, level = s.lv
        FROM sub s
        WHERE ct.id = s.id
          AND (ct.full_path_readable IS DISTINCT FROM s.fpr OR ct.path IS DISTINCT FROM s.p OR ct.level IS DISTINCT FROM s.lv);
    ELSE
        WITH RECURSIVE sub AS (
            SELECT c.id, NEW.full_path_readable||' > '||UPPER(COALESCE(c.name,'')) AS chain
            FROM categories c WHERE c.parent_id = NEW.id
            UNION ALL
            SELECT c2.id, s.chain||' > '||UPPER(COALESCE(c2.name,''))
            FROM categories c2 JOIN sub s ON c2.parent_id = s.id
        )
        UPDATE categories ct SET full_path_readable = s.chain FROM sub s
        WHERE ct.id = s.id AND ct.full_path_readable IS DISTINCT FROM s.chain;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trigger_propagate_fpr"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trigger_rebuild_swatches_on_image"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product_id   uuid;
  v_new_swatches jsonb;
BEGIN
  -- Guard 1: não rodar durante bulk import
  IF current_setting('app.bulk_import_mode', true) = 'true' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  v_product_id := COALESCE(NEW.product_id, OLD.product_id);

  -- Guard 2: só interessa se a imagem tem vínculo de variante ou cor
  -- (imagens genéricas do produto não afetam os swatches)
  IF COALESCE(NEW.variant_id, OLD.variant_id) IS NULL AND
     COALESCE(NEW.color_id,   OLD.color_id)   IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Guard 3: só types relevantes para swatches
  IF COALESCE(NEW.image_type, OLD.image_type) NOT IN ('main','gallery','product') THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Recalcular e atualizar apenas se mudou
  v_new_swatches := fn_rebuild_color_swatches(v_product_id);

  UPDATE products
    SET color_swatches = v_new_swatches
  WHERE id = v_product_id
    AND (color_swatches IS DISTINCT FROM v_new_swatches);

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."fn_trigger_rebuild_swatches_on_image"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trigger_rebuild_swatches_on_variant"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product_id  uuid;
  v_new_swatches jsonb;
BEGIN
  -- Guard 1: não rodar durante bulk import
  IF current_setting('app.bulk_import_mode', true) = 'true' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  v_product_id := COALESCE(NEW.product_id, OLD.product_id);

  -- Guard 2: calcular novo valor apenas se necessário
  v_new_swatches := fn_rebuild_color_swatches(v_product_id);

  -- Guard 3: só update se o valor realmente mudou (evita cascata de triggers em products)
  UPDATE products
    SET color_swatches = v_new_swatches
  WHERE id = v_product_id
    AND (color_swatches IS DISTINCT FROM v_new_swatches);

  RETURN COALESCE(NEW, OLD);
END;
$$;


