CREATE OR REPLACE FUNCTION "public"."fn_trigger_set_min_quantity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_category_min integer;
BEGIN
    IF NEW.min_order_quantity IS NULL AND NEW.category_id IS NOT NULL THEN
        -- Busca mínimo da categoria
        SELECT min_order_quantity INTO v_category_min
        FROM categories WHERE id = NEW.category_id;

        -- GREATEST: preserva o maior valor entre o atual e o da categoria
        -- Garante que não fica abaixo da categoria mas respeita mínimo do fornecedor
        IF v_category_min IS NOT NULL THEN
            NEW.min_quantity := GREATEST(
                COALESCE(NEW.min_quantity, 0),
                v_category_min
            );
        END IF;

    ELSIF NEW.min_order_quantity IS NOT NULL THEN
        -- Override explícito por produto — tem precedência máxima
        NEW.min_quantity := NEW.min_order_quantity;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trigger_set_min_quantity"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_trigger_set_min_quantity"() IS 'BEFORE INSERT/UPDATE em products.
Garante que min_quantity >= categories.min_order_quantity.
Usa GREATEST: preserva valores maiores vindos do fornecedor (VendaMinima),
nunca reduz abaixo do mínimo da categoria.
Override explícito: min_order_quantity no próprio produto tem precedência total.';



CREATE OR REPLACE FUNCTION "public"."fn_trigger_supplier_source_price"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_product_id UUID;
    v_sale_price NUMERIC;
BEGIN
    -- Só processa se o custo foi definido/alterado
    IF NEW.cost_price IS NOT NULL AND NEW.cost_price > 0 THEN
        -- Buscar product_id através da variante
        SELECT pv.product_id INTO v_product_id
        FROM product_variants pv
        WHERE pv.id = NEW.variant_id;
        
        IF v_product_id IS NOT NULL THEN
            -- Calcular preço do produto
            v_sale_price := fn_calculate_sale_price(v_product_id);
            
            IF v_sale_price IS NOT NULL THEN
                RAISE NOTICE 'Preço atualizado para produto %: R$ %', v_product_id, v_sale_price;
            END IF;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$_$;


