CREATE OR REPLACE FUNCTION "public"."fn_trigger_sync_descendants_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_delta INTEGER;
BEGIN
  -- ─────────────────────────────────────────────────────────────────────────
  -- INSERT: incrementar todos os ancestrais em +1 — CTE batch (1 UPDATE total)
  -- ─────────────────────────────────────────────────────────────────────────
  IF TG_OP = 'INSERT' AND NEW.parent_id IS NOT NULL THEN
    WITH RECURSIVE ancestors(id, parent_id, depth) AS (
      SELECT c.id, c.parent_id, 1
      FROM   categories c
      WHERE  c.id = NEW.parent_id
      UNION ALL
      SELECT c.id, c.parent_id, a.depth + 1
      FROM   categories c
      JOIN   ancestors a ON c.id = a.parent_id
      WHERE  a.parent_id IS NOT NULL
        AND  a.depth < 15  -- safety: bem acima dos 6 níveis ativos
    )
    UPDATE categories
    SET    descendants_count = descendants_count + 1
    WHERE  id IN (SELECT id FROM ancestors);

    RETURN NEW;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- DELETE: decrementar ancestrais por (1 + subtree) — CTE batch
  -- OLD.descendants_count já reflete o estado pré-deleção (trigger AFTER)
  -- ─────────────────────────────────────────────────────────────────────────
  IF TG_OP = 'DELETE' AND OLD.parent_id IS NOT NULL THEN
    v_delta := 1 + COALESCE(OLD.descendants_count, 0);

    WITH RECURSIVE ancestors(id, parent_id, depth) AS (
      SELECT c.id, c.parent_id, 1
      FROM   categories c
      WHERE  c.id = OLD.parent_id
      UNION ALL
      SELECT c.id, c.parent_id, a.depth + 1
      FROM   categories c
      JOIN   ancestors a ON c.id = a.parent_id
      WHERE  a.parent_id IS NOT NULL
        AND  a.depth < 15
    )
    UPDATE categories
    SET    descendants_count = GREATEST(0, descendants_count - v_delta)
    WHERE  id IN (SELECT id FROM ancestors);

    RETURN OLD;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- UPDATE parent_id: abordagem delta nos dois ramos — 2 CTEs batch
  --
  -- v_delta = subtree sendo movida (a categoria + todos seus descendentes)
  -- Ancestrais compartilhados recebem -delta e +delta → net = 0 ✓
  -- Sem full-recount (que exigia 1 CTE por ancestral no loop anterior)
  -- ─────────────────────────────────────────────────────────────────────────
  IF TG_OP = 'UPDATE' AND OLD.parent_id IS DISTINCT FROM NEW.parent_id THEN
    v_delta := 1 + COALESCE(OLD.descendants_count, 0);

    -- Ramo ANTIGO: decrementar (categoria + subtree saiu)
    IF OLD.parent_id IS NOT NULL THEN
      WITH RECURSIVE old_ancestors(id, parent_id, depth) AS (
        SELECT c.id, c.parent_id, 1
        FROM   categories c
        WHERE  c.id = OLD.parent_id
        UNION ALL
        SELECT c.id, c.parent_id, a.depth + 1
        FROM   categories c
        JOIN   old_ancestors a ON c.id = a.parent_id
        WHERE  a.parent_id IS NOT NULL
          AND  a.depth < 15
      )
      UPDATE categories
      SET    descendants_count = GREATEST(0, descendants_count - v_delta)
      WHERE  id IN (SELECT id FROM old_ancestors);
    END IF;

    -- Ramo NOVO: incrementar (categoria + subtree chegou)
    IF NEW.parent_id IS NOT NULL THEN
      WITH RECURSIVE new_ancestors(id, parent_id, depth) AS (
        SELECT c.id, c.parent_id, 1
        FROM   categories c
        WHERE  c.id = NEW.parent_id
        UNION ALL
        SELECT c.id, c.parent_id, a.depth + 1
        FROM   categories c
        JOIN   new_ancestors a ON c.id = a.parent_id
        WHERE  a.parent_id IS NOT NULL
          AND  a.depth < 15
      )
      UPDATE categories
      SET    descendants_count = descendants_count + v_delta
      WHERE  id IN (SELECT id FROM new_ancestors);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trigger_sync_descendants_count"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_trigger_sync_descendants_count"() IS 'AFTER trigger (INSERT/DELETE/UPDATE) que mantém descendants_count de todos os
ancestrais de uma categoria. Usa CTE batch recursiva em vez de WHILE loop —
reduz de N round-trips (1/nível) para 1 UPDATE batch. Abordagem delta no UPDATE
parent_id evita full-recount por ancestral. Safety: depth < 15, GREATEST(0,…).
Otimizado em: 2026-06-23.';



CREATE OR REPLACE FUNCTION "public"."fn_trigger_sync_pca_products_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_category_id uuid;
  v_count integer;
BEGIN
  -- Determinar qual category_id foi afetado
  IF TG_OP = 'DELETE' THEN
    v_category_id := OLD.category_id;
  ELSIF TG_OP = 'INSERT' THEN
    v_category_id := NEW.category_id;
  ELSIF TG_OP = 'UPDATE' THEN
    -- Se category_id mudou, atualizar ambos
    IF OLD.category_id IS DISTINCT FROM NEW.category_id THEN
      -- Decrementar a antiga
      SELECT COUNT(DISTINCT pca.product_id) INTO v_count
      FROM product_category_assignments pca
      JOIN products p ON p.id = pca.product_id
      WHERE pca.category_id = OLD.category_id
        AND (p.is_deleted = false OR p.is_deleted IS NULL)
        AND p.is_active = true;
      
      UPDATE categories SET products_count = v_count
      WHERE id = OLD.category_id;
    END IF;
    v_category_id := NEW.category_id;
  END IF;

  -- Recalcular contagem real para a categoria afetada
  SELECT COUNT(DISTINCT pca.product_id) INTO v_count
  FROM product_category_assignments pca
  JOIN products p ON p.id = pca.product_id
  WHERE pca.category_id = v_category_id
    AND (p.is_deleted = false OR p.is_deleted IS NULL)
    AND p.is_active = true;

  UPDATE categories SET products_count = v_count
  WHERE id = v_category_id;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trigger_sync_pca_products_count"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_trigger_sync_pca_products_count"() IS 'Mantém categories.products_count sincronizado automaticamente.
Conta apenas produtos com is_deleted=false AND is_active=true.
Fonte: product_category_assignments (tabela de vínculo N:N).
Criado em 2026-03-22 para substituir o trigger antigo que usava products.main_category_id.';



CREATE OR REPLACE FUNCTION "public"."fn_trigger_sync_product_status_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  -- Sync is_deleted -> deleted_at
  IF NEW.is_deleted IS DISTINCT FROM OLD.is_deleted THEN
    IF NEW.is_deleted = true AND NEW.deleted_at IS NULL THEN
      NEW.deleted_at := NOW();
    ELSIF NEW.is_deleted = false THEN
      NEW.deleted_at := NULL;
    END IF;
  ELSIF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
    NEW.is_deleted := (NEW.deleted_at IS NOT NULL);
  END IF;

  -- INVARIANT: deleted products MUST be inactive
  -- Se is_deleted=true, forçar is_active=false (sem bloqueio por trigger de deactivation,
  -- pois a deleção já é um passo mais grave que a desativação)
  IF NEW.is_deleted = true AND NEW.is_active = true THEN
    NEW.is_active := false;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trigger_sync_product_status_fields"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_trigger_sync_product_status_fields"() IS 'Mantém campos de status sincronizados: is_active↔active, is_deleted↔deleted_at.
Campos canônicos: is_active (70+ functions), is_deleted (11+ functions).
Campos legacy: active (4 views packaging), deleted_at (7 functions).';



