CREATE OR REPLACE FUNCTION "public"."fn_upsert_asia_wp_batch"("p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ASIA       uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_item       jsonb;
  v_parent_ref text;
  v_canon      jsonb;
  v_hash       text;
  v_rows       int;
  v_fetched    int := 0;
  v_updated    int := 0;
  v_parents    int := 0;
BEGIN
  IF jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'fn_upsert_asia_wp_batch: p_items deve ser array jsonb';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_fetched := v_fetched + 1;
    v_parent_ref := NULLIF(TRIM(v_item->>'sku'), '');
    CONTINUE WHEN v_parent_ref IS NULL;

    v_canon := public.fn_asia_wp_to_canonical(v_item);
    v_hash  := md5(v_canon::text);

    UPDATE public.supplier_products_raw r SET
      site_data       = v_canon,
      site_hash       = v_hash,
      site_source_url = v_canon->>'url',
      site_status     = CASE WHEN r.site_hash IS DISTINCT FROM v_hash
                             THEN 'processed'::supplier_raw_status
                             ELSE r.site_status END,
      site_scraped_at = now(),
      updated_at      = now()
    WHERE r.supplier_id = v_ASIA
      AND r.raw_data->>'referencia' = v_parent_ref;

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_updated := v_updated + v_rows;
    IF v_rows > 0 THEN v_parents := v_parents + 1; END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'fetched',         v_fetched,
    'matched_parents', v_parents,
    'updated_rows',    v_updated,
    'rodado_em',       now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_upsert_asia_wp_batch"("p_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_upsert_asia_wp_batch"("p_items" "jsonb") IS 'F2 ASIA: recebe array de produtos da WooCommerce Store API, converte p/ canonico via fn_asia_wp_to_canonical e grava na trilha site_* de supplier_products_raw (propaga ao grao pai->variantes). site_status->processed on change.';



CREATE OR REPLACE FUNCTION "public"."fn_upsert_stock_to_bronze"("p_supplier_id" "uuid", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item       jsonb;
  v_sku        text;
  v_updated    int := 0;
  v_not_found  int := 0;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_sku := v_item->>'Sku';
    IF v_sku IS NULL OR v_sku = '' THEN CONTINUE; END IF;

    UPDATE public.supplier_products_raw
    SET
      stock_data = v_item,
      updated_at = now()
    WHERE supplier_id  = p_supplier_id
      AND supplier_sku = v_sku;

    IF FOUND THEN
      v_updated := v_updated + 1;
    ELSE
      v_not_found := v_not_found + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'updated',    v_updated,
    'not_found',  v_not_found,
    'total',      jsonb_array_length(p_items)
  );
END;
$$;


ALTER FUNCTION "public"."fn_upsert_stock_to_bronze"("p_supplier_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_upsert_stock_to_bronze"("p_sku" "text", "p_quantity" integer, "p_next_date1" "text" DEFAULT ''::"text", "p_next_qty1" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier_id uuid;
  v_updated int;
BEGIN
  SELECT id INTO v_supplier_id FROM suppliers WHERE code='STRICKER' LIMIT 1;
  
  UPDATE supplier_products_raw
  SET 
    stock_data = jsonb_build_object(
      'Sku', p_sku,
      'Quantity', p_quantity,
      'NextQuantity1', p_next_qty1,
      'NextDate1', COALESCE(p_next_date1, ''),
      '_updated_at', now()::text
    ),
    updated_at = now()
  WHERE supplier_id = v_supplier_id
    AND supplier_sku = p_sku;
  
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN jsonb_build_object('sku', p_sku, 'updated', v_updated, 'quantity', p_quantity);
END;
$$;


ALTER FUNCTION "public"."fn_upsert_stock_to_bronze"("p_sku" "text", "p_quantity" integer, "p_next_date1" "text", "p_next_qty1" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_upsert_stocks_bulk_spot"("p_stocks" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier_id uuid;
  v_updated     int := 0;
  v_skipped     int := 0;
  v_item        jsonb;
  v_sku         text;
BEGIN
  SELECT id INTO v_supplier_id FROM suppliers WHERE code='STRICKER' LIMIT 1;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_stocks) LOOP

    v_sku := NULLIF(TRIM(COALESCE(
               v_item->>'Sku', v_item->>'WebSku',
               v_item->>'sku', v_item->>'webSku')), '');

    IF v_sku IS NULL THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    UPDATE supplier_products_raw
    SET
      stock_data = jsonb_build_object(
        'Sku',           v_sku,
        'Quantity',      COALESCE(NULLIF(v_item->>'Quantity','')::int, 0),
        -- 6 janelas de reposição (NextQuantity/NextDate 1..6)
        'NextQuantity1', NULLIF(v_item->>'NextQuantity1',''),
        'NextDate1',     NULLIF(v_item->>'NextDate1',''),
        'NextQuantity2', NULLIF(v_item->>'NextQuantity2',''),
        'NextDate2',     NULLIF(v_item->>'NextDate2',''),
        'NextQuantity3', NULLIF(v_item->>'NextQuantity3',''),
        'NextDate3',     NULLIF(v_item->>'NextDate3',''),
        'NextQuantity4', NULLIF(v_item->>'NextQuantity4',''),
        'NextDate4',     NULLIF(v_item->>'NextDate4',''),
        'NextQuantity5', NULLIF(v_item->>'NextQuantity5',''),
        'NextDate5',     NULLIF(v_item->>'NextDate5',''),
        'NextQuantity6', NULLIF(v_item->>'NextQuantity6',''),
        'NextDate6',     NULLIF(v_item->>'NextDate6',''),
        '_updated_at',   now()::text
      ),
      updated_at = now()
    WHERE supplier_id = v_supplier_id
      AND supplier_sku = v_sku;

    IF FOUND THEN
      v_updated := v_updated + 1;
    ELSE
      v_skipped := v_skipped + 1;
    END IF;

  END LOOP;

  RETURN jsonb_build_object(
    'updated',     v_updated,
    'skipped',     v_skipped,
    'total_input', jsonb_array_length(p_stocks),
    'synced_at',   now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_upsert_stocks_bulk_spot"("p_stocks" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_vacuum_high_dead_tuples"() RETURNS TABLE("tabela" "text", "dead_before" bigint, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_dead bigint;
BEGIN
  SELECT n_dead_tup INTO v_dead FROM pg_stat_user_tables WHERE relname='mv_product_images_audit';
  RETURN QUERY SELECT 'mv_product_images_audit'::text, v_dead, 'VACUUM agendado via cron'::text;
  SELECT n_dead_tup INTO v_dead FROM pg_stat_user_tables WHERE relname='mv_stock_rupture_alert';
  RETURN QUERY SELECT 'mv_stock_rupture_alert'::text, v_dead, 'VACUUM agendado via cron'::text;
  SELECT n_dead_tup INTO v_dead FROM pg_stat_user_tables WHERE relname='stock_snapshots';
  RETURN QUERY SELECT 'stock_snapshots'::text, v_dead, 'VACUUM agendado via cron'::text;
END;
$$;


