COMMENT ON FUNCTION "public"."fn_video_retry_errors"("p_supplier" "text", "p_dry_run" boolean) IS 'Classifica erros de video_import_queue por regex e: (a) marca permanentes (Video unavailable, etc) como retry_count=max_retries; (b) reseta transitorios (timeout, rate limit, 5xx) para pending. p_dry_run=true para preview.';



CREATE OR REPLACE FUNCTION "public"."fn_video_set_dimensions"("p_cf_uid" "text", "p_width" integer, "p_height" integer, "p_size_bytes" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_n int;
BEGIN
  UPDATE product_videos
  SET width_px        = p_width,
      height_px       = p_height,
      file_size_bytes = COALESCE(p_size_bytes, file_size_bytes),
