CREATE OR REPLACE FUNCTION "public"."fn_xbz_dispatch_image_batch"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net'
    AS $$
DECLARE
    v_count integer:=0; v_first_req_id bigint; v_last_req_id bigint;
    v_req_id bigint; v_mcp_id integer:=0; v_img RECORD;
BEGIN
    FOR v_img IN
        SELECT xgs.id, xgs.sku, xgs.display_order, xgs.source_url,
               xgs.product_id, xgs.cf_custom_id,
               xgs.image_type
        FROM public.xbz_gallery_staging xgs
        JOIN public.products p ON p.id=xgs.product_id AND p.is_active=true
        WHERE xgs.status='pending'
          AND xgs.cf_custom_id IS NOT NULL
          AND xgs.source_url IS NOT NULL
        ORDER BY xgs.sku, xgs.display_order
        LIMIT p_limit
    LOOP
        v_mcp_id := v_mcp_id+1;
        SELECT net.http_post(
            url   := 'https://cloudflare-deploy-mcp.adm01.workers.dev/mcp',
            body  := jsonb_build_object(
                'jsonrpc','2.0','id',v_mcp_id,'method','tools/call',
                'params', jsonb_build_object(
                    'name','cf_images_upload_url',
                    'arguments', jsonb_build_object(
                        'source_url', v_img.source_url,
                        'custom_id',  v_img.cf_custom_id,
                        'metadata',   jsonb_build_object(
                            'supplier','xbz','image_type',v_img.image_type,
                            'sku',v_img.sku,'display_order',v_img.display_order
                        )
                    )
                )
            ),
            headers := jsonb_build_object(
                'Content-Type','application/json','Accept','application/json, text/event-stream'
            ),
            timeout_milliseconds := 30000
        ) INTO v_req_id;

        INSERT INTO public.xbz_upload_mapping (request_id, staging_id, cf_custom_id, source_url)
        VALUES (v_req_id, v_img.id, v_img.cf_custom_id, v_img.source_url);

        UPDATE public.xbz_gallery_staging
           SET status='uploading', updated_at=now()
        WHERE id=v_img.id;

        v_count := v_count+1;
        IF v_first_req_id IS NULL THEN v_first_req_id:=v_req_id; END IF;
        v_last_req_id := v_req_id;
    END LOOP;
    RETURN jsonb_build_object('dispatched',v_count,'first_req_id',v_first_req_id,'last_req_id',v_last_req_id);
END $$;


ALTER FUNCTION "public"."fn_xbz_dispatch_image_batch"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_xbz_enqueue_videos"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enfileirados int := 0;
BEGIN
  INSERT INTO video_import_queue (
    youtube_id,
    youtube_url,
    source_supplier,
    product_references,
    status
  )
  SELECT DISTINCT ON (pv.source_youtube_id)
    pv.source_youtube_id                          AS youtube_id,
    pv.url_original                               AS youtube_url,
    'xbz'                                         AS source_supplier,
    ARRAY[p.supplier_reference]                   AS product_references,
    'pending'                                     AS status
  FROM product_videos pv
  JOIN products p ON p.id = pv.product_id
  WHERE pv.source_supplier = 'xbz'
    AND pv.cloudflare_status = 'youtube'
    AND pv.source_youtube_id IS NOT NULL
    AND p.supplier_reference IS NOT NULL
    -- Não duplicar: não enfileirar se já existe na fila
    AND NOT EXISTS (
      SELECT 1 FROM video_import_queue viq
      WHERE viq.youtube_id = pv.source_youtube_id
        AND viq.source_supplier = 'xbz'
    )
  ORDER BY pv.source_youtube_id, pv.created_at ASC;

  GET DIAGNOSTICS v_enfileirados = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok',              true,
    'enfileirados',    v_enfileirados,
    'fila_pendente',   (SELECT COUNT(*) FROM video_import_queue
                        WHERE source_supplier='xbz' AND status='pending')
  );
END;
$$;


ALTER FUNCTION "public"."fn_xbz_enqueue_videos"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_xbz_enqueue_videos"() IS '
Popula video_import_queue com os vídeos XBZ que ainda estão como "youtube"
(aguardando migração para Cloudflare Stream).

QUEM CHAMA
  · n8n: XBZ - GESTÃO DE PRODUTOS (nó F5b), a cada 30min
  · Manual: SELECT fn_xbz_enqueue_videos() para importação ad-hoc

LÓGICA
  1. Lê product_videos WHERE source_supplier=''xbz'' AND cloudflare_status=''youtube''
  2. Para cada youtube_id ainda ausente na fila, insere 1 linha em video_import_queue
     com status=''pending'' e product_references=[supplier_reference do produto]
  3. Retorna {ok, enfileirados, fila_pendente}

IDEMPOTENTE: usa NOT EXISTS — chamar N vezes não cria duplicatas.

CONTINUAÇÃO DO PIPELINE
  Após enfileirar, o VPS /workspace/xbz_video_import.js (PID periódico) processa
  a fila: fn_video_queue_next(''xbz'') → yt-dlp → CF Stream → fn_xbz_link_video.

DEPENDÊNCIAS
  · product_videos (leitura)
  · products (JOIN para supplier_reference)
  · video_import_queue (escrita)

PERMISSÕES: SECURITY DEFINER · GRANT anon, authenticated
';



CREATE OR REPLACE FUNCTION "public"."fn_xbz_enrich_from_site"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_site  jsonb;
    v_ref   text;
BEGIN
    -- Só executa para XBZ
    IF NEW.supplier_id != 'd6718a29-e954-4c1b-bd84-03ea24884900' THEN RETURN NEW; END IF;

    -- ════════════════════════════════════════════════════════════
    -- BLOCO 1: campos que NÃO dependem de site_data
    -- ════════════════════════════════════════════════════════════

    -- Defaults hardcoded
    IF NEW.brand          IS NULL THEN NEW.brand          := 'XBZ Brindes'; END IF;
    IF NEW.product_type   IS NULL THEN NEW.product_type   := 'product';     END IF;
    IF NEW.origin_country IS NULL THEN NEW.origin_country := 'China';       END IF;

    -- Flags booleanas sem fonte → false
    IF NEW.is_online_exclusive IS NULL THEN NEW.is_online_exclusive := false; END IF;
    IF NEW.is_seasonal         IS NULL THEN NEW.is_seasonal         := false; END IF;
    IF NEW.pvc_free            IS NULL THEN NEW.pvc_free            := false; END IF;
    IF NEW.has_sizes           IS NULL THEN NEW.has_sizes           := false; END IF;

    -- is_textil: keywords no nome ou categoria
    IF NEW.is_textil IS NULL THEN
        NEW.is_textil := (
            COALESCE(NEW.name,'') ~* '\m(nylon|neoprene|oxford|lona|poliéster|poliester|tnt|tecido|flanela|algodão|algodao|microfibra|veludo|viscose|moletom|malha|jeans|spandex|lycra|percal|couro sint)\M'
            OR COALESCE(NEW.supplier_type,'') IN (
                'Malas Mochilas Bolsas','Sacolas E Sacochilas',
                'Bolsas Termicas','Necessaires','Guarda Chuva'
            )
        );
    END IF;

    -- Materials: keyword lookup do nome + subtype
    IF NEW.materials IS NULL THEN
        NEW.materials := fn_xbz_derive_materials(NEW.name, NEW.supplier_subtype);
    END IF;

    -- allows_personalization: fallback para engraving_type (mesmo sem site)
    IF NEW.allows_personalization IS NULL THEN
        NEW.allows_personalization := (NEW.engraving_type IS NOT NULL);
    END IF;

    -- Supplier type/subtype das categories (se já preenchidas)
    IF NEW.supplier_type IS NULL AND NEW.supplier_categories IS NOT NULL THEN
        SELECT c->>'nome' INTO NEW.supplier_type
        FROM jsonb_array_elements(NEW.supplier_categories) c
        WHERE (c->>'nivel')::int = 1 LIMIT 1;
        SELECT c->>'path' INTO NEW.supplier_type_code
        FROM jsonb_array_elements(NEW.supplier_categories) c
        WHERE (c->>'nivel')::int = 1 LIMIT 1;
    END IF;
    IF NEW.supplier_subtype IS NULL AND NEW.supplier_categories IS NOT NULL THEN
        SELECT c->>'nome' INTO NEW.supplier_subtype
        FROM jsonb_array_elements(NEW.supplier_categories) c
        WHERE (c->>'nivel')::int = 2 LIMIT 1;
        SELECT c->>'path' INTO NEW.supplier_subtype_code
        FROM jsonb_array_elements(NEW.supplier_categories) c
        WHERE (c->>'nivel')::int = 2 LIMIT 1;
    END IF;

    -- ════════════════════════════════════════════════════════════
    -- Buscar site_data da variante representativa
    -- ════════════════════════════════════════════════════════════
    v_ref := NEW.supplier_reference;
    SELECT spr.site_data INTO v_site
    FROM supplier_products_raw spr
    WHERE spr.supplier_id = NEW.supplier_id
      AND (spr.supplier_reference = v_ref
           OR spr.supplier_reference LIKE v_ref || '-%')
      AND spr.site_status = 'processed'
      AND spr.site_data IS NOT NULL
    ORDER BY
        (spr.site_data->'gravacao'->>'medida_texto' IS NOT NULL) DESC,
        jsonb_array_length(COALESCE(spr.site_data->'relacionados','[]')) DESC,
        jsonb_array_length(COALESCE(spr.site_data->'imagens','[]')) DESC
    LIMIT 1;

    -- Early return se sem site_data (os campos do bloco 1 já foram definidos)
    IF v_site IS NULL THEN RETURN NEW; END IF;

    -- ════════════════════════════════════════════════════════════
    -- BLOCO 2: campos que dependem de site_data
    -- ════════════════════════════════════════════════════════════

    -- Colors (staging)
    IF NEW.colors IS NULL AND jsonb_array_length(COALESCE(v_site->'cores','[]')) > 0 THEN
        NEW.colors := v_site->'cores';
    END IF;

    -- has_colors
    IF NEW.has_colors IS NULL THEN
        NEW.has_colors := jsonb_array_length(COALESCE(v_site->'cores','[]')) > 1;
    END IF;

    -- Description
    IF NEW.description IS NULL AND length(COALESCE(v_site->>'descricao','')) >= 10
       AND v_site->>'descricao' NOT ILIKE 'http%' THEN
        NEW.description := v_site->>'descricao';
    END IF;

    -- Primary image
    IF NEW.primary_image_url IS NULL THEN
        SELECT img->>'url' INTO NEW.primary_image_url
        FROM jsonb_array_elements(COALESCE(v_site->'imagens','[]')) AS img
        WHERE (img->>'principal')::boolean = true LIMIT 1;
        IF NEW.primary_image_url IS NULL OR NEW.primary_image_url NOT ILIKE 'http%' THEN
            NEW.primary_image_url := NULL;
        END IF;
    END IF;

    -- Engraving
    IF NEW.engraving_type IS NULL THEN
        NEW.engraving_type := v_site->'gravacao'->>'medida_texto';
        IF NEW.engraving_type IS NOT NULL THEN
            NEW.allows_personalization := true;
        END IF;
    END IF;

    -- Related references
    IF NEW.related_references IS NULL AND
       jsonb_array_length(COALESCE(v_site->'relacionados','[]')) > 0 THEN
        SELECT jsonb_agg(r->>'codigo') INTO NEW.related_references
        FROM jsonb_array_elements(v_site->'relacionados') AS r
        WHERE (r->>'codigo') IS NOT NULL;
    END IF;

    -- Supplier categories
    IF NEW.supplier_categories IS NULL AND
       jsonb_array_length(COALESCE(v_site->'categorias','[]')) > 0 THEN
        SELECT jsonb_agg(jsonb_build_object(
            'nome',  c->>'nome','path',c->>'path',
            'nivel',(c->>'nivel')::int,'url',c->>'url'))
        INTO NEW.supplier_categories
        FROM jsonb_array_elements(v_site->'categorias') AS c
        WHERE (c->>'nome') IS NOT NULL;
    END IF;

    -- Dimensions (site, se API zerou)
    IF COALESCE(NEW.weight_g, 0) = 0 AND (v_site->>'peso_g') IS NOT NULL THEN
        NEW.weight_g := NULLIF((v_site->>'peso_g')::numeric, 0)::integer;
    END IF;
    IF COALESCE(NEW.height_cm, 0) = 0 THEN
        NEW.height_cm := NULLIF((v_site->'dimensoes'->>'altura_cm')::numeric, 0);
    END IF;
    IF COALESCE(NEW.width_cm, 0) = 0 THEN
        NEW.width_cm := NULLIF((v_site->'dimensoes'->>'largura_cm')::numeric, 0);
    END IF;
    IF NEW.length_cm IS NULL THEN
        NEW.length_cm := CASE
            WHEN (v_site->'dimensoes'->>'profundidade_cm')::numeric BETWEEN 0.1 AND 200
            THEN (v_site->'dimensoes'->>'profundidade_cm')::numeric ELSE NULL END;
    END IF;
    IF NEW.circumference_cm IS NULL THEN
        NEW.circumference_cm := NULLIF((v_site->'dimensoes'->>'circunferencia_cm')::numeric, 0);
    END IF;

    -- capacity_ml via regex do nome
    IF NEW.capacity_ml IS NULL AND NEW.name ~* '(\d+)\s*ml' THEN
        NEW.capacity_ml := (regexp_match(NEW.name, '(\d+)\s*ml', 'i'))[1]::integer;
    END IF;

    -- dimensions_display
    IF NEW.dimensions_display IS NULL THEN
        SELECT INTO NEW.dimensions_display
            CASE WHEN COUNT(*) > 0
                 THEN string_agg(v || 'cm', ' x ' ORDER BY ord)
                 ELSE NULL END
        FROM (VALUES
            (1, COALESCE(NEW.height_cm, 0)::text),
            (2, COALESCE(NEW.width_cm,  0)::text),
            (3, COALESCE(NEW.length_cm, 0)::text)
        ) AS t(ord, v)
        WHERE v::numeric > 0;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_xbz_enrich_from_site"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_xbz_enrich_from_site"() IS 'BEFORE INSERT/UPDATE em produtos_padronizacao (XBZ only).
Mapeia TODOS os campos disponíveis em site_data:
  Dimensões    : weight_g, height_cm, width_cm, length_cm, circumference_cm
  Capacidade   : capacity_ml (regex nome), dimensions_display (derivado)
  Conteúdo     : description, primary_image_url
  Gravação     : engraving_type (medida_texto)
  Relacionados : related_references (array de códigos)
  Categorias   : supplier_categories (hierarquia XBZ [{nome,path,nivel,url}])
JOIN: LIKE supplier_reference||"-%", prefere variante com mais dados.
Só preenche se NULL/zero — não sobrescreve edição manual.';



CREATE OR REPLACE FUNCTION "public"."fn_xbz_enrich_gold_extractors"("p_supplier" "uuid" DEFAULT 'd6718a29-e954-4c1b-bd84-03ea24884900'::"uuid", "p_limit" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE v_material int:=0; v_category int:=0;
BEGIN
  -- Enriquece produtos Gold (via API path) com os extractores XBZ-específicos:
  --   • extract_xbz_material_primary → property 'material_xbz_primary'
  --   • classify_xbz_category        → product_category_assignments (display_order=995)
  -- Idempotente: ON CONFLICT DO UPDATE / DO NOTHING.
  -- Seguro: aditivo, nunca sobrescreve canônico.

  -- Escopo: produtos Gold XBZ que têm nome disponível
  CREATE TEMP TABLE _gold_xbz ON COMMIT DROP AS
    SELECT DISTINCT pr.id AS product_id, pr.name
    FROM public.variant_supplier_sources vss
    JOIN public.product_variants pv ON pv.id=vss.variant_id
    JOIN public.products pr ON pr.id=pv.product_id
    WHERE vss.supplier_id=p_supplier AND pr.name IS NOT NULL
    LIMIT COALESCE(p_limit, 1000000000);

  -- (a) Material primário XBZ
  INSERT INTO public.product_properties (product_id, property_code, property_value, source, raw_value)
  SELECT g.product_id,
         'material_xbz_primary',
         public.extract_xbz_material_primary(upper(g.name), upper(g.name)),
         'xbz_extractor',
         public.extract_xbz_material_primary(upper(g.name), upper(g.name))
  FROM _gold_xbz g
  WHERE public.extract_xbz_material_primary(upper(g.name), upper(g.name)) IS NOT NULL
    AND btrim(public.extract_xbz_material_primary(upper(g.name), upper(g.name))) <> ''
  ON CONFLICT (product_id, property_code) DO UPDATE
    SET property_value=EXCLUDED.property_value, raw_value=EXCLUDED.raw_value,
        source=EXCLUDED.source, updated_at=now()
  WHERE public.product_properties.source <> 'xbz_extractor'   -- nunca sobrescreve manual
     OR public.product_properties.property_value IS DISTINCT FROM EXCLUDED.property_value;
  GET DIAGNOSTICS v_material = ROW_COUNT;

  -- (b) Categorias via classify_xbz_category (alta/média confiança)
  INSERT INTO public.product_category_assignments (product_id, category_id, is_primary, display_order)
  SELECT DISTINCT g.product_id, xcat.category_id, false, 995
  FROM _gold_xbz g
  CROSS JOIN LATERAL public.classify_xbz_category(upper(g.name)) xcat
  WHERE xcat.confidence IN ('high','medium')
    AND xcat.category_id IS NOT NULL
    AND xcat.category_name <> 'NÃO CLASSIFICADO'
  ON CONFLICT (product_id, category_id) DO NOTHING;
  GET DIAGNOSTICS v_category = ROW_COUNT;

  RETURN jsonb_build_object(
    'produtos_escopo', (SELECT count(*) FROM _gold_xbz),
    'material_xbz_upsert', v_material,
    'category_xbz_insert', v_category
  );
END $$;


ALTER FUNCTION "public"."fn_xbz_enrich_gold_extractors"("p_supplier" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_xbz_enrich_gold_extractors"("p_supplier" "uuid" DEFAULT 'd6718a29-e954-4c1b-bd84-03ea24884900'::"uuid", "p_limit" integer DEFAULT NULL::integer, "p_only_missing" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE v_material int:=0; v_category int:=0;
BEGIN
  CREATE TEMP TABLE _gold_xbz ON COMMIT DROP AS
    SELECT product_id, name FROM (
      SELECT DISTINCT ON (pr.id) pr.id AS product_id, pr.name, pr.created_at
      FROM public.variant_supplier_sources vss
      JOIN public.product_variants pv ON pv.id=vss.variant_id
      JOIN public.products pr ON pr.id=pv.product_id
      WHERE vss.supplier_id=p_supplier AND pr.name IS NOT NULL
        AND (
          NOT p_only_missing
          OR NOT EXISTS (SELECT 1 FROM public.product_properties pp2
                          WHERE pp2.product_id=pr.id AND pp2.property_code='material_xbz_primary')
        )
      ORDER BY pr.id, pr.created_at DESC
    ) sub
    ORDER BY created_at DESC
    LIMIT COALESCE(p_limit, 1000000000);

  IF NOT EXISTS (SELECT 1 FROM _gold_xbz) THEN
    RETURN jsonb_build_object('produtos_escopo',0,'note','sem_novidades');
  END IF;

  INSERT INTO public.product_properties (product_id, property_code, property_value, source, raw_value)
  SELECT g.product_id, 'material_xbz_primary',
         public.extract_xbz_material_primary(upper(g.name), upper(g.name)),
         'xbz_extractor',
         public.extract_xbz_material_primary(upper(g.name), upper(g.name))
  FROM _gold_xbz g
  WHERE public.extract_xbz_material_primary(upper(g.name), upper(g.name)) IS NOT NULL
    AND btrim(public.extract_xbz_material_primary(upper(g.name), upper(g.name))) <> ''
  ON CONFLICT (product_id, property_code) DO UPDATE
    SET property_value=EXCLUDED.property_value, raw_value=EXCLUDED.raw_value,
        source=EXCLUDED.source, updated_at=now()
  WHERE public.product_properties.source='xbz_extractor';
  GET DIAGNOSTICS v_material = ROW_COUNT;

  INSERT INTO public.product_category_assignments (product_id, category_id, is_primary, display_order)
  SELECT DISTINCT g.product_id, xcat.category_id, false, 995
  FROM _gold_xbz g
  CROSS JOIN LATERAL public.classify_xbz_category(upper(g.name)) xcat
  WHERE xcat.confidence IN ('high','medium')
    AND xcat.category_id IS NOT NULL AND xcat.category_name <> 'NÃO CLASSIFICADO'
  ON CONFLICT (product_id, category_id) DO NOTHING;
  GET DIAGNOSTICS v_category = ROW_COUNT;

  RETURN jsonb_build_object(
    'produtos_escopo', (SELECT count(*) FROM _gold_xbz),
    'material_xbz_upsert', v_material,
    'category_xbz_insert', v_category
  );
END $$;


ALTER FUNCTION "public"."fn_xbz_enrich_gold_extractors"("p_supplier" "uuid", "p_limit" integer, "p_only_missing" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_xbz_enrich_stock"("p_supplier_id" "uuid", "p_reference" "text", "p_qty" numeric DEFAULT NULL::numeric, "p_multiplos" numeric DEFAULT NULL::numeric, "p_disponivel" boolean DEFAULT NULL::boolean, "p_venda_minima" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated int;
BEGIN
  UPDATE supplier_products_raw
  SET
    raw_data = raw_data || jsonb_strip_nulls(jsonb_build_object(
      'QuantidadeDisponivel', p_qty::text,
      'Multiplos',            p_multiplos::text,
      'Disponivel',           p_disponivel::text,
      'VendaMinima',          p_venda_minima::text,
      '_ruiz_sync_at',        to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    )),
    updated_at = now()
  WHERE supplier_id       = p_supplier_id
    AND supplier_reference = p_reference
    AND raw_data IS NOT NULL;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'updated', v_updated,
    'reference', p_reference,
    'ts', now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_xbz_enrich_stock"("p_supplier_id" "uuid", "p_reference" "text", "p_qty" numeric, "p_multiplos" numeric, "p_disponivel" boolean, "p_venda_minima" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_xbz_enrich_stock_batch"("p_supplier_id" "uuid", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated int := 0;
BEGIN
  UPDATE supplier_products_raw spr
  SET
    raw_data   = spr.raw_data || patch.p,
    stock_data = COALESCE(spr.stock_data, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
      'QuantidadeDisponivel',                 item->'QuantidadeDisponivel',
      'QuantidadeDisponivelEstoquePrincipal', item->'QuantidadeDisponivelEstoquePrincipal',
      'ReposicaoDataPrevista',                item->'ReposicaoDataPrevista',
      'Disponivel',                           item->'Disponivel'
    ))
  FROM jsonb_array_elements(p_items) AS item
  CROSS JOIN LATERAL (
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'QuantidadeDisponivel',                 item->'QuantidadeDisponivel',
      'QuantidadeDisponivelEstoquePrincipal', item->'QuantidadeDisponivelEstoquePrincipal',
      'ReposicaoDataPrevista',                item->'ReposicaoDataPrevista',
      'Multiplos',                            item->'Multiplos',
      'VendaMinima',                          item->'VendaMinima',
      'Disponivel',                           item->'Disponivel',
      'IpiTaxa',                              item->'IpiTaxa',
      'PrecoVenda',                           item->'PrecoVenda',
      'IdProduto',                            item->'IdProduto',
      'CodigoXbz',                            item->'CodigoXbz',
      'StatusConfiabilidade',                 item->'StatusConfiabilidade'
    )) AS p
  ) patch
  WHERE spr.supplier_id = p_supplier_id
    AND spr.supplier_sku = item->>'CodigoComposto'
    AND spr.raw_data IS NOT NULL
    AND NOT (spr.raw_data @> patch.p);

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'updated',      v_updated,
    'total_input',  jsonb_array_length(p_items),
    'skipped_noop', jsonb_array_length(p_items) - v_updated,
    'campos',       'guard simetrico raw_data @> patch; sem carimbo de stock_synced_at; tipos JSON preservados',
    'ts',           now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_xbz_enrich_stock_batch"("p_supplier_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_xbz_enrich_stock_batch"("p_supplier_id" "uuid", "p_items" "jsonb") IS 'Enriquece raw_data XBZ com campos do consultaEstoque (preco/disponibilidade/IPI; quantidades quando o item as trouxer). v3: guard simetrico (NOT raw_data @> patch) — atualiza somente linhas com mudanca real; nao carimba stock_synced_at (marcador reservado a escritas reais de stock_data). Chaves _% sao removidas pelo trigger fn_spr_before_write.';



CREATE OR REPLACE FUNCTION "public"."fn_xbz_extract_min_quantity"("p_raw_data" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
    v_api_value  text;
    v_desc       text;
    v_match      text[];
    v_result     integer;
BEGIN
    -- ── Fonte 1: VendaMinima da API (primária) ────────────────────────────
    v_api_value := p_raw_data->>'VendaMinima';

    IF v_api_value IS NOT NULL AND v_api_value ~ '^\d+$' THEN
        v_result := v_api_value::integer;
        IF v_result > 0 THEN
            RETURN v_result;
        END IF;
    END IF;

    -- ── Fonte 2: regex na descrição (fallback) ────────────────────────────
    -- Padrões cobertos:
    -- "OBS.: PEDIDOS MÍNIMO DE 50 PEÇAS!"
    -- "PEDIDO MÍNIMO DE 100 PEÇAS"
    -- "PEDIDO MÍNIMO: 10 PÇS"
    v_desc := p_raw_data->>'Descricao';

    IF v_desc IS NOT NULL THEN
        v_match := regexp_match(
            v_desc,
            'PEDIDOS?\s*M[ÍI]NIMO\s*(?:DE\s*|:\s*)?(\d+)\s*P(?:E[ÇC]AS?|[ÇC]S)',
            'i'
        );
        IF v_match IS NOT NULL AND array_length(v_match, 1) > 0 THEN
            v_result := v_match[1]::integer;
            IF v_result > 0 THEN
                RETURN v_result;
            END IF;
        END IF;
    END IF;

    -- ── Sem fonte ─────────────────────────────────────────────────────────
    RETURN NULL;
END;
$_$;


ALTER FUNCTION "public"."fn_xbz_extract_min_quantity"("p_raw_data" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_xbz_extract_min_quantity"("p_raw_data" "jsonb") IS 'Extrai a quantidade mínima de venda da XBZ em cascata:
 1. VendaMinima da API (campo direto, confiável)
 2. Regex na Descricao: "PEDIDOS MÍNIMO DE X PEÇAS"
 Retorna NULL se nenhuma fonte encontrada.
 IMUTABLE — seguro para uso em índices e gerado columns.';



CREATE OR REPLACE FUNCTION "public"."fn_xbz_ficha_run_batch"("p_limit" integer DEFAULT 8) RETURNS TABLE("sku" "text", "extraidas" integer, "promovidas" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE r record; v_ext int; v_prom int;
BEGIN
  FOR r IN
    SELECT q.product_sku FROM v_xbz_ficha_parse_queue q
    WHERE q.prioridade=1
      AND NOT EXISTS(SELECT 1 FROM kit_component_ficha_staging s
                      WHERE s.product_sku=q.product_sku AND s.source ILIKE 'xbz_%jina')
    ORDER BY q.n_dim_heuristicas DESC, q.product_sku
    LIMIT p_limit
  LOOP
    v_ext := fn_fetch_xbz_ficha(r.product_sku, false);
    SELECT promoted INTO v_prom FROM fn_promote_kit_ficha_staging(r.product_sku);
    sku:=r.product_sku; extraidas:=coalesce(v_ext,0); promovidas:=coalesce(v_prom,0);
    RETURN NEXT;
  END LOOP;
END $$;


ALTER FUNCTION "public"."fn_xbz_ficha_run_batch"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_xbz_harvest_image_batch"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net'
    AS $$
DECLARE
    v_succeeded integer:=0; v_dup integer:=0; v_failed integer:=0;
    v_rec RECORD; v_inner_json jsonb; v_outcome text; v_cf_url text; v_pi uuid;
    v_existing_pi uuid;   -- FIX: para recuperar product_image_id quando cf_id já existe
    c_tid_main    CONSTANT uuid:='7ea182ff-edcc-4c4c-b7a1-443b07500f6c';
    c_tid_gallery CONSTANT uuid:='1590e144-e3f8-41e6-98f9-f4a25bae496d';
    c_tid_set     CONSTANT uuid:='c305d8b3-9af8-469e-aea5-88208def353f';
    c_tid_ambient CONSTANT uuid:='e8bf8d1f-b6f5-47c1-953b-616d354318a6';
    c_tid_detail  CONSTANT uuid:='055e7e81-61c5-4546-a43c-3256a581966e';
    c_tid_product CONSTANT uuid:='49991e77-2511-482a-bce3-15ab73c2b74f';
    c_org         CONSTANT uuid:='5db5aee1-064b-4ef4-9193-345dcd8274ea';
BEGIN
    FOR v_rec IN
        SELECT m.request_id, m.staging_id, m.cf_custom_id,
               xgs.product_id, xgs.display_order, xgs.source_url, xgs.image_type,
               r.status_code,
               (r.content::jsonb)->'result'->'content'->0->>'text' AS inner_text
        FROM public.xbz_upload_mapping m
        JOIN net._http_response r  ON r.id=m.request_id
        JOIN public.xbz_gallery_staging xgs ON xgs.id=m.staging_id
        WHERE m.status='pending' AND r.status_code IS NOT NULL
    LOOP
        v_inner_json:=NULL;
        BEGIN
            IF v_rec.inner_text LIKE '{%}' THEN v_inner_json:=v_rec.inner_text::jsonb; END IF;
        EXCEPTION WHEN OTHERS THEN v_inner_json:=NULL;
        END;

        v_outcome:=CASE
            WHEN v_inner_json IS NOT NULL AND v_inner_json->>'id' IS NOT NULL THEN 'uploaded'
            WHEN v_rec.inner_text LIKE '%already exists%' OR v_rec.inner_text LIKE '%5414%' THEN 'duplicate'
            WHEN v_rec.status_code!=200 OR v_rec.inner_text ILIKE '%error%'
              OR v_rec.inner_text IS NULL THEN 'error'
            ELSE 'unknown'
        END;

        v_cf_url:='https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/'||v_rec.cf_custom_id||'/public';

        IF v_outcome IN ('uploaded','duplicate') THEN
            v_pi:=NULL;
            v_existing_pi:=NULL;

            -- FIX GAP-4 (relacionado): verificar se cloudflare_image_id já existe em product_images
            -- para evitar violação de unique constraint "product_images_cloudflare_image_id_key"
            SELECT id INTO v_existing_pi
            FROM public.product_images
            WHERE cloudflare_image_id = v_rec.cf_custom_id
            LIMIT 1;

            IF v_existing_pi IS NOT NULL THEN
                -- CF ID já existe: reutilizar o product_image existente sem nova inserção
                v_pi := v_existing_pi;
                v_dup := v_dup + 1;
            ELSE
                INSERT INTO public.product_images (
                    product_id, cloudflare_image_id, url_cdn, url_original,
                    filename, image_type, image_type_id,
                    is_primary, display_order, source_supplier, supplier_code,
                    applies_to_color, is_active, organization_id
                ) VALUES (
                    v_rec.product_id, v_rec.cf_custom_id, v_cf_url, v_rec.source_url,
                    v_rec.cf_custom_id||'.jpg',
                    v_rec.image_type,
                    CASE v_rec.image_type
                        WHEN 'main'    THEN c_tid_main
                        WHEN 'set'     THEN c_tid_set
                        WHEN 'ambient' THEN c_tid_ambient
                        WHEN 'detail'  THEN c_tid_detail
                        WHEN 'product' THEN c_tid_product
                        ELSE c_tid_gallery
                    END,
                    v_rec.display_order=0, v_rec.display_order,
                    'XBZ','XBZ', false, true, c_org
                )
                ON CONFLICT (product_id, filename) WHERE (is_active=true AND filename IS NOT NULL)
                DO UPDATE SET cloudflare_image_id=EXCLUDED.cloudflare_image_id,
                              url_cdn=EXCLUDED.url_cdn,
                              image_type_id=EXCLUDED.image_type_id,
                              updated_at=now()
                RETURNING id INTO v_pi;

                IF v_outcome='duplicate' THEN v_dup:=v_dup+1; ELSE v_succeeded:=v_succeeded+1; END IF;
            END IF;

            UPDATE public.xbz_gallery_staging SET
                cloudflare_image_id = v_rec.cf_custom_id,
                cf_custom_id        = v_rec.cf_custom_id,
                cloudflare_url      = v_cf_url,
                status              = 'uploaded',
                uploaded_at         = now(),
                product_image_id    = v_pi,
                updated_at          = now()
            WHERE id=v_rec.staging_id;

            IF v_rec.display_order=0 THEN
                UPDATE public.products SET primary_image_url=v_cf_url, updated_at=now()
                WHERE id=v_rec.product_id
                  AND (primary_image_url IS NULL OR primary_image_url NOT LIKE '%imagedelivery%');
            END IF;

        ELSE
            UPDATE public.xbz_gallery_staging SET
                status        = 'error',
                error_message = left(coalesce(v_rec.inner_text,'no_response'),200),
                retry_count   = coalesce(retry_count,0)+1,
                updated_at    = now()
            WHERE id=v_rec.staging_id;
            v_failed:=v_failed+1;
        END IF;

        UPDATE public.xbz_upload_mapping SET status=v_outcome, harvested_at=now()
        WHERE request_id=v_rec.request_id;
    END LOOP;

    RETURN jsonb_build_object(
        'succeeded',v_succeeded,'duplicates',v_dup,'failed',v_failed,
        'still_pending',(SELECT COUNT(*) FROM public.xbz_upload_mapping WHERE status='pending')
    );
END $$;


