BEGIN
    IF NEW.order_number IS NULL THEN
        SELECT count(*) + 1 INTO next_val FROM public.orders 
        WHERE order_number LIKE 'PED-' || year_suffix || '-%';
        NEW.order_number := 'PED-' || year_suffix || '-' || lpad(next_val::text, 4, '0');
    END IF;
    RETURN NEW;
END;
$$;


