CREATE OR REPLACE FUNCTION "public"."generate_product_jsonld"("p_product_id" "uuid", "p_base_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product RECORD;
  v_category_name TEXT;
  v_images JSONB;
  v_faqs JSONB;
  v_schema JSONB;
BEGIN
  SELECT * INTO v_product FROM products WHERE id = p_product_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT name INTO v_category_name FROM categories
  WHERE id = COALESCE(v_product.main_category_id, v_product.category_id);

  SELECT COALESCE(jsonb_agg(url_cdn ORDER BY display_order),'[]'::jsonb) INTO v_images
  FROM product_images WHERE product_id=p_product_id AND is_active=true AND url_cdn IS NOT NULL;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    '@type','Question','name',question,
    'acceptedAnswer',jsonb_build_object('@type','Answer','text',answer)
  ) ORDER BY display_order),'[]'::jsonb)
  INTO v_faqs FROM product_faqs WHERE product_id=p_product_id AND is_active=true;

  v_schema := jsonb_build_object(
    '@context','https://schema.org','@type','Product',
    'name',v_product.name,
    'description',COALESCE(v_product.description,v_product.short_description,v_product.name),
    'image',v_images,
    'brand',jsonb_build_object('@type','Brand','name',COALESCE(v_product.brand,'Promo Brindes')),
    'category',v_category_name,
    'url',p_base_url||'/produto/'||COALESCE(v_product.slug,v_product.id::TEXT),
    'offers',jsonb_build_object(
      '@type','Offer','priceCurrency','BRL',
      'price',COALESCE(v_product.sale_price,v_product.cost_price,0),
      'availability',CASE WHEN COALESCE(v_product.stock_quantity,0)>0
        THEN 'https://schema.org/InStock' ELSE 'https://schema.org/OutOfStock' END,
      'seller',jsonb_build_object('@type','Organization','name','Promo Brindes')
    )
  );

  -- SKU (existe em products)
  IF v_product.sku IS NOT NULL THEN
    v_schema := v_schema || jsonb_build_object('sku', v_product.sku);
  END IF;
  -- NOTA: gtin/ean não existem em products — removidos

  IF jsonb_array_length(v_faqs) > 0 THEN
    v_schema := v_schema || jsonb_build_object('mainEntity', v_faqs);
  END IF;

  RETURN v_schema;
END;
$$;


ALTER FUNCTION "public"."generate_product_jsonld"("p_product_id" "uuid", "p_base_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_product_meta_description"("p_name" "text", "p_short_description" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_allows_personalization" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_description        TEXT;
  v_base               TEXT;
  v_personalization    TEXT := '';
  v_cta                TEXT := ' Solicite orçamento!';
  v_fallback_suffix    TEXT := ' para brindes corporativos e eventos promocionais.';
BEGIN
  IF p_name IS NULL THEN RETURN NULL; END IF;

  -- === BASE: prioridade short_desc > desc > fallback ===
  IF p_short_description IS NOT NULL
     AND LENGTH(TRIM(strip_html(p_short_description))) >= 20 THEN
    v_base := TRIM(REGEXP_REPLACE(strip_html(p_short_description), '\s+', ' ', 'g'));

  ELSIF p_description IS NOT NULL
        AND LENGTH(TRIM(strip_html(p_description))) >= 20 THEN
    v_base := truncate_text(
                TRIM(REGEXP_REPLACE(strip_html(p_description), '\s+', ' ', 'g')),
                110, ''
              );
  ELSE
    -- Fallback: nome + sufixo padrão (sempre ≥ 50 chars)
    v_base := p_name || v_fallback_suffix;
  END IF;

  -- === GARANTIR BASE MÍNIMA DE 30 CHARS ===
  -- Se strip_html gerou texto muito curto, expande com sufixo
  IF LENGTH(v_base) < 30 THEN
    v_base := v_base || v_fallback_suffix;
  END IF;

  -- === PERSONALIZAÇÃO ===
  IF p_allows_personalization THEN
    v_personalization := ' Personalização disponível.';
  END IF;

  -- === MONTAR ===
  v_description := v_base;

  IF LENGTH(v_description || v_personalization) <= 140 THEN
    v_description := v_description || v_personalization;
  END IF;

  IF LENGTH(v_description || v_cta) <= 165 THEN
    v_description := v_description || v_cta;
  END IF;

  -- === GARANTIR MÍNIMO 50 CHARS (constraint) ===
  -- Se ainda for curto demais, completa com contexto de brindes
  IF LENGTH(v_description) < 50 THEN
    v_description := v_description || ' Brinde corporativo personalizado. Solicite orçamento!';
  END IF;

  -- === GARANTIR MÁXIMO 170 CHARS (constraint) ===
  v_description := LEFT(v_description, 169);

  RETURN v_description;
END;
$$;


ALTER FUNCTION "public"."generate_product_meta_description"("p_name" "text", "p_short_description" "text", "p_description" "text", "p_allows_personalization" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_product_meta_description"("p_name" "text", "p_short_description" "text", "p_description" "text", "p_allows_personalization" boolean) IS 'Gera meta description SEO otimizada. Garante 50-169 chars (compatível com constraint chk_products_meta_desc_length). Prioridade: short_description > description > fallback.';



CREATE OR REPLACE FUNCTION "public"."generate_product_meta_title"("p_name" "text", "p_category_name" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_title TEXT;
  v_suffix TEXT := ' | Promo Brindes';
  v_max_name_length INTEGER;
BEGIN
  IF p_name IS NULL THEN
    RETURN NULL;
  END IF;
  
  -- Calcular espaço disponível (ideal 55 chars total)
  v_max_name_length := 55 - LENGTH(v_suffix);
  
  -- Se tiver categoria e couber, incluir
  IF p_category_name IS NOT NULL AND LENGTH(p_category_name) <= 15 THEN
    v_max_name_length := v_max_name_length - LENGTH(p_category_name) - 3; -- " - "
    
    IF LENGTH(p_name) > v_max_name_length THEN
      v_title := truncate_text(p_name, v_max_name_length, '');
    ELSE
      v_title := p_name;
    END IF;
    
    v_title := v_title || ' - ' || p_category_name || v_suffix;
  ELSE
    IF LENGTH(p_name) > v_max_name_length THEN
      v_title := truncate_text(p_name, v_max_name_length, '');
    ELSE
      v_title := p_name;
    END IF;
    
    v_title := v_title || v_suffix;
  END IF;
  
  RETURN v_title;
END;
$$;


ALTER FUNCTION "public"."generate_product_meta_title"("p_name" "text", "p_category_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_product_meta_title"("p_name" "text", "p_category_name" "text") IS 'Gera meta title otimizado (50-60 chars) no formato "Produto - Categoria | Promo Brindes"';



CREATE OR REPLACE FUNCTION "public"."generate_product_slug"("p_name" "text", "p_product_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_base_slug   text;
  v_final_slug  text;
  v_hex_suffix  text;
  v_counter     integer := 0;
BEGIN
  -- Validação de entrada
  IF p_name IS NULL OR LENGTH(TRIM(p_name)) = 0 THEN
    RETURN NULL;
  END IF;

  -- Gerar slug base via slugify
  v_base_slug  := slugify(p_name);
  v_final_slug := v_base_slug;

  -- ── CAMINHO RÁPIDO: slug base disponível ─────────────────────────
  IF NOT EXISTS (
    SELECT 1 FROM products
    WHERE slug = v_final_slug
      AND is_deleted = false
      AND (p_product_id IS NULL OR id <> p_product_id)
  ) THEN
    RETURN v_final_slug;
  END IF;

  -- ── COLISÃO: sufixo determinístico via UUID (O(1) garantido) ─────
  -- Usa os primeiros 8 hex do UUID do produto como sufixo.
  -- Elimina 100% do loop N+1 anterior que chegava a 18527 iterações.
  IF p_product_id IS NOT NULL THEN
    v_hex_suffix := LEFT(REPLACE(p_product_id::text, '-', ''), 8);
    v_final_slug := v_base_slug || '-' || v_hex_suffix;

    IF NOT EXISTS (
      SELECT 1 FROM products
      WHERE slug = v_final_slug
        AND is_deleted = false
        AND id <> p_product_id
    ) THEN
      RETURN v_final_slug;
    END IF;

    -- Fallback extremamente improvável: sufixo hex colidiu (duplo produto com mesmo UUID truncado)
    -- Usar slug completo: base-<uuid-completo-sem-hifens>
    v_final_slug := v_base_slug || '-' || REPLACE(p_product_id::text, '-', '');
    RETURN v_final_slug;
  END IF;

  -- ── FALLBACK: sem p_product_id (chamada externa sem contexto) ────
  -- Loop limitado a 999 (antes era ilimitado).
  WHILE v_counter < 999 LOOP
    v_counter    := v_counter + 1;
    v_final_slug := v_base_slug || '-' || v_counter;
    IF NOT EXISTS (
      SELECT 1 FROM products
      WHERE slug = v_final_slug
        AND is_deleted = false
        AND (p_product_id IS NULL OR id <> p_product_id)
    ) THEN
      RETURN v_final_slug;
    END IF;
  END LOOP;

  -- Último recurso: base + timestamp
  RETURN v_base_slug || '-' || EXTRACT(EPOCH FROM NOW())::bigint;
END;
$$;


