CREATE OR REPLACE FUNCTION "public"."generate_variant_sku"("p_product_code" "text", "p_supplier_color_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_promo_variation_id UUID;
    v_internal_code TEXT;
    v_sku TEXT;
BEGIN
    IF p_product_code IS NULL OR TRIM(p_product_code) = '' THEN
        RETURN NULL;
    END IF;
    
    SELECT promo_variation_id INTO v_promo_variation_id
    FROM color_equivalences
    WHERE supplier_color_id = p_supplier_color_id
      AND is_active = true
    ORDER BY verified DESC, confidence_score DESC
    LIMIT 1;
    
    IF v_promo_variation_id IS NULL THEN
        RETURN NULL;
    END IF;
    
    SELECT internal_code INTO v_internal_code
    FROM color_variations
    WHERE id = v_promo_variation_id;
    
    IF v_internal_code IS NULL THEN
        RETURN NULL;
    END IF;
    
    v_sku := TRIM(p_product_code) || '.' || v_internal_code;
    
    RETURN v_sku;
END;
$$;


ALTER FUNCTION "public"."generate_variant_sku"("p_product_code" "text", "p_supplier_color_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_variant_sku_by_color_code"("p_product_code" "text", "p_supplier_id" "uuid", "p_color_code" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_supplier_color_id UUID;
BEGIN
    SELECT id INTO v_supplier_color_id
    FROM supplier_colors
    WHERE supplier_id = p_supplier_id
      AND code = p_color_code
    LIMIT 1;
    
    IF v_supplier_color_id IS NULL THEN
        RETURN NULL;
    END IF;
    
    RETURN generate_variant_sku(p_product_code, v_supplier_color_id);
END;
$$;


ALTER FUNCTION "public"."generate_variant_sku_by_color_code"("p_product_code" "text", "p_supplier_id" "uuid", "p_color_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gerar_nome_variante"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_nome_produto TEXT;
    v_nome         TEXT;
BEGIN
    -- Se já tem nome preenchido, não sobrescreve
    IF NEW.name IS NOT NULL AND TRIM(NEW.name) != '' THEN
        RETURN NEW;
    END IF;

    -- Buscar nome do produto pai
    SELECT name INTO v_nome_produto FROM products WHERE id = NEW.product_id;

    -- Montar nome com até 3 dimensões
    v_nome := COALESCE(v_nome_produto, '');
    IF NEW.color_name IS NOT NULL AND NEW.color_name != '' THEN
        v_nome := v_nome || ' | ' || NEW.color_name;
    END IF;
    IF NEW.size_code IS NOT NULL AND NEW.size_code != '' THEN
        v_nome := v_nome || ' | ' || NEW.size_code;
    END IF;

    -- Limpar trailing separador se ficou só o produto
    v_nome := btrim(regexp_replace(v_nome, '\s*[|]\s*$', ''));

    -- ✅ PATCH: garantir MAIÚSCULO no nome final da variante
    IF v_nome != '' THEN
        NEW.name := public.fn_normalize_product_name(v_nome);
    END IF;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."gerar_nome_variante"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gerar_nome_variante"() IS 'BEFORE INSERT em product_variants.
 Gera name = "{product_name} | {color_name} | {size_code}" (partes existentes).
 PATCH 2026-06-09: aplica fn_normalize_product_name no nome final → MAIÚSCULO.';



CREATE OR REPLACE FUNCTION "public"."gerar_resumo_alertas_bitrix"("p_data_inicio" timestamp with time zone DEFAULT ("now"() - '1 day'::interval)) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_resultado JSONB;
    v_alertas JSONB;
    v_resumo JSONB;
BEGIN
    -- Buscar resumo
    SELECT jsonb_build_object(
        'total', COUNT(*),
        'criticos', COUNT(*) FILTER (WHERE nivel_alerta = 'CRITICO'),
        'urgentes', COUNT(*) FILTER (WHERE nivel_alerta = 'URGENTE'),
        'atencao', COUNT(*) FILTER (WHERE nivel_alerta = 'ATENCAO'),
        'info', COUNT(*) FILTER (WHERE nivel_alerta = 'INFO'),
        'aumentos', COUNT(*) FILTER (WHERE tipo_mudanca = 'AUMENTO'),
        'reducoes', COUNT(*) FILTER (WHERE tipo_mudanca = 'REDUCAO'),
        'novos', COUNT(*) FILTER (WHERE tipo_mudanca = 'NOVO')
    ) INTO v_resumo
    FROM spot_price_change_log
    WHERE detectado_em >= p_data_inicio
    AND bitrix_notificado = FALSE;
    
    -- Buscar alertas críticos e urgentes (detalhes)
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', id,
            'tabela', table_code_option,
            'tecnica', tecnica_nome,
            'area', area_descricao,
            'faixa', faixa_preco,
            'spot_anterior', spot_valor_anterior,
            'spot_novo', spot_valor_novo,
            'variacao_spot', spot_variacao_percentual,
            'nosso_preco', nosso_preco_atual,
            'margem_anterior', margem_anterior_percentual,
            'margem_nova', margem_nova_percentual,
            'impacto_margem', margem_variacao_pp,
            'nivel', nivel_alerta,
            'tipo', tipo_mudanca
        ) ORDER BY 
            CASE nivel_alerta 
                WHEN 'CRITICO' THEN 1 
                WHEN 'URGENTE' THEN 2 
                WHEN 'ATENCAO' THEN 3 
                ELSE 4 
            END,
            ABS(COALESCE(margem_variacao_pp, 0)) DESC
    ), '[]'::JSONB) INTO v_alertas
    FROM spot_price_change_log
    WHERE detectado_em >= p_data_inicio
    AND bitrix_notificado = FALSE
    AND nivel_alerta IN ('CRITICO', 'URGENTE', 'ATENCAO');
    
    -- Montar resultado
    v_resultado := jsonb_build_object(
        'data_verificacao', NOW(),
        'periodo_inicio', p_data_inicio,
        'resumo', v_resumo,
        'alertas_prioritarios', v_alertas
    );
    
    RETURN v_resultado;
END;
$$;


ALTER FUNCTION "public"."gerar_resumo_alertas_bitrix"("p_data_inicio" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gerar_resumo_alertas_bitrix"("p_data_inicio" timestamp with time zone) IS 'Gera JSON formatado para envio ao Bitrix24';



CREATE OR REPLACE FUNCTION "public"."get_abc_curve"("p_metric" character varying DEFAULT 'revenue'::character varying, "p_limit" integer DEFAULT 100) RETURNS TABLE("rank_position" integer, "product_id" "uuid", "sku" character varying, "name" character varying, "metric_value" numeric, "percentage" numeric, "cumulative_percentage" numeric, "abc_class" character, "stock_quantity" integer, "stock_value" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
WITH product_metrics AS (
    SELECT 
        p.id AS product_id,
        p.sku,
        p.name,
        CASE p_metric
            -- Revenue: soma de quantity * unit_price dos pedidos
            WHEN 'revenue' THEN COALESCE(
                (SELECT SUM(oi.quantity * oi.unit_price) 
                 FROM order_items oi 
                 WHERE oi.product_id = p.id),
                0
            )
            -- Quantity: soma de unidades vendidas
            WHEN 'quantity' THEN COALESCE(
                (SELECT SUM(oi.quantity)::NUMERIC 
                 FROM order_items oi 
                 WHERE oi.product_id = p.id),
                0
            )
            -- Stock Value: valor em estoque
            WHEN 'stock_value' THEN COALESCE(
                (SELECT SUM(pv.stock_quantity * COALESCE(pv.price_1, 0))
                 FROM product_variants pv
                 WHERE pv.product_id = p.id),
                0
            )
            ELSE 0
        END AS metric_value,
        -- Estoque total
        COALESCE(
            (SELECT SUM(pv.stock_quantity) FROM product_variants pv WHERE pv.product_id = p.id),
            0
        )::INTEGER AS stock_quantity,
        -- Valor em estoque (usando price_1)
        COALESCE(
            (SELECT SUM(pv.stock_quantity * COALESCE(pv.price_1, 0)) 
             FROM product_variants pv WHERE pv.product_id = p.id),
            0
        ) AS stock_value
    FROM products p
    WHERE p.is_active = true AND p.deleted_at IS NULL
),
ranked_products AS (
    SELECT 
        ROW_NUMBER() OVER (ORDER BY pm.metric_value DESC)::INTEGER AS rank_position,
        pm.product_id,
        pm.sku::VARCHAR,
        pm.name::VARCHAR,
        pm.metric_value::NUMERIC,
        (pm.metric_value / NULLIF(SUM(pm.metric_value) OVER (), 0) * 100)::NUMERIC(10,2) AS percentage,
        (SUM(pm.metric_value) OVER (ORDER BY pm.metric_value DESC) / 
         NULLIF(SUM(pm.metric_value) OVER (), 0) * 100)::NUMERIC(10,2) AS cumulative_percentage,
        pm.stock_quantity,
        pm.stock_value::NUMERIC
    FROM product_metrics pm
    WHERE pm.metric_value > 0
)
SELECT 
    rp.rank_position,
    rp.product_id,
    rp.sku,
    rp.name,
    rp.metric_value,
    rp.percentage,
    rp.cumulative_percentage,
    CASE 
        WHEN rp.cumulative_percentage <= 80 THEN 'A'
        WHEN rp.cumulative_percentage <= 95 THEN 'B'
        ELSE 'C'
    END::CHAR(1) AS abc_class,
    rp.stock_quantity,
    rp.stock_value
FROM ranked_products rp
ORDER BY rp.rank_position
LIMIT p_limit;
$$;


ALTER FUNCTION "public"."get_abc_curve"("p_metric" character varying, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_abc_curve"("p_metric" character varying, "p_limit" integer) IS 'Análise de Curva ABC (Pareto) para produtos';



CREATE OR REPLACE FUNCTION "public"."get_active_commemorative_dates"() RETURNS TABLE("id" "uuid", "name" "text", "slug" "text", "date_day" integer, "date_month" integer, "formatted_date" "text", "category" "text", "icon_name" "text", "color_hex" "text", "days_until" integer, "campaign_start_days" integer, "is_featured" boolean, "color_count" bigint, "product_count" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_day INT := EXTRACT(DAY FROM CURRENT_DATE);
    v_month INT := EXTRACT(MONTH FROM CURRENT_DATE);
    v_year INT := EXTRACT(YEAR FROM CURRENT_DATE);
BEGIN
    RETURN QUERY
    SELECT 
        cd.id,
        cd.name,
        cd.slug,
        cd.date_day,
        cd.date_month,
        CASE 
            WHEN cd.is_fixed_date AND cd.date_day IS NOT NULL 
            THEN LPAD(cd.date_day::TEXT, 2, '0') || '/' || LPAD(cd.date_month::TEXT, 2, '0')
            ELSE cd.variable_date_rule
        END,
        cd.category,
        cd.icon_name,
        cd.color_hex,
        CASE 
            WHEN cd.is_fixed_date AND cd.date_day IS NOT NULL THEN
                (make_date(
                    CASE WHEN cd.date_month < v_month OR (cd.date_month = v_month AND cd.date_day < v_day)
                    THEN v_year + 1 ELSE v_year END, cd.date_month, cd.date_day
                ) - CURRENT_DATE)::INT
            ELSE NULL
        END,
        cd.campaign_start_days,
        cd.is_featured,
        (SELECT COUNT(*) FROM commemorative_date_colors cdc WHERE cdc.commemorative_date_id = cd.id),
        0::BIGINT AS product_count
    FROM commemorative_dates cd
    WHERE cd.is_active = TRUE
      AND (
          cd.is_fixed_date = FALSE
          OR (make_date(
              CASE WHEN cd.date_month < v_month OR (cd.date_month = v_month AND cd.date_day < v_day)
                   THEN v_year + 1 ELSE v_year END,
              cd.date_month, cd.date_day
          ) - CURRENT_DATE)::INT <= cd.campaign_start_days
      )
    ORDER BY cd.date_month, cd.date_day NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."get_active_commemorative_dates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_novelties"("p_supplier_code" character varying DEFAULT NULL::character varying, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_only_highlighted" boolean DEFAULT false) RETURNS TABLE("novelty_id" "uuid", "product_id" "uuid", "product_name" "text", "product_sku" "text", "supplier_code" character varying, "supplier_product_code" character varying, "detected_at" timestamp with time zone, "expires_at" timestamp with time zone, "days_remaining" integer, "is_highlighted" boolean)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        n.id AS novelty_id,
        n.product_id,
        p.name AS product_name,
        p.sku AS product_sku,
        n.supplier_code,
        n.supplier_product_code,
        n.detected_at,
        n.expires_at,
        EXTRACT(DAY FROM (n.expires_at - NOW()))::INTEGER AS days_remaining,
        n.is_highlighted
    FROM public.product_novelties n
    JOIN public.products p ON n.product_id = p.id
    WHERE n.is_active = true
      AND n.expires_at > NOW()
      AND (p_supplier_code IS NULL OR n.supplier_code = p_supplier_code)
      AND (p_only_highlighted = false OR n.is_highlighted = true)
    ORDER BY n.detected_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;


