        pi.id,
        pi.cloudflare_image_id,
        pi.url_cdn,
        pi.url_cdn || '/thumbnail',
        it.code,
        it.name,
        it.category,
        pi.color_id,
        pi.display_order,
        pi.is_primary,
        it.show_in_gallery,
