CREATE OR REPLACE FUNCTION "public"."get_auto_test_job_status"("_limit" integer DEFAULT 20) RETURNS TABLE("run_started_at" timestamp with time zone, "run_ended_at" timestamp with time zone, "duration_ms" integer, "total_tested" integer, "ok_count" integer, "fail_count" integer, "retried_count" integer, "avg_latency_ms" integer)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;
  RETURN QUERY
  WITH ordered AS (
    SELECT cth.tested_at, cth.success, cth.latency_ms, cth.attempts, date_trunc('minute', cth.tested_at) AS bucket
    FROM public.connection_test_history cth
    WHERE cth.triggered_by = 'cron' AND cth.tested_at > now() - interval '7 days'
  ),
  runs AS (
    SELECT o.bucket,
      MIN(o.tested_at) AS run_started_at,
      MAX(o.tested_at) AS run_ended_at,
      GREATEST(EXTRACT(EPOCH FROM (MAX(o.tested_at) - MIN(o.tested_at))) * 1000, 0)::int AS duration_ms,
      COUNT(*)::int AS total_tested,
      COUNT(*) FILTER (WHERE o.success)::int AS ok_count,
      COUNT(*) FILTER (WHERE NOT o.success)::int AS fail_count,
      COUNT(*) FILTER (WHERE o.attempts > 1)::int AS retried_count,
      COALESCE(AVG(o.latency_ms) FILTER (WHERE o.latency_ms IS NOT NULL), 0)::int AS avg_latency_ms
    FROM ordered o GROUP BY o.bucket
  )
  SELECT r.run_started_at, r.run_ended_at, r.duration_ms, r.total_tested, r.ok_count, r.fail_count, r.retried_count, r.avg_latency_ms
  FROM runs r ORDER BY r.run_started_at DESC LIMIT GREATEST(1, LEAST(_limit, 100));
END;
$$;


ALTER FUNCTION "public"."get_auto_test_job_status"("_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_automation_stats"("p_supplier_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("metric" "text", "value" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Total de produtos
    RETURN QUERY
    SELECT 'total_products'::TEXT, COUNT(*)
    FROM products
    WHERE p_supplier_id IS NULL OR supplier_id = p_supplier_id;
    
    -- Com categoria
    RETURN QUERY
    SELECT 'with_category'::TEXT, COUNT(*)
    FROM products
    WHERE category_id IS NOT NULL
      AND (p_supplier_id IS NULL OR supplier_id = p_supplier_id);
    
    -- Sem categoria
    RETURN QUERY
    SELECT 'without_category'::TEXT, COUNT(*)
    FROM products
    WHERE category_id IS NULL
      AND (p_supplier_id IS NULL OR supplier_id = p_supplier_id);
    
    -- Com preço de venda
    RETURN QUERY
    SELECT 'with_sale_price'::TEXT, COUNT(*)
    FROM products
    WHERE sale_price IS NOT NULL AND sale_price > 0
      AND (p_supplier_id IS NULL OR supplier_id = p_supplier_id);
    
    -- Sem preço de venda
    RETURN QUERY
    SELECT 'without_sale_price'::TEXT, COUNT(*)
    FROM products
    WHERE (sale_price IS NULL OR sale_price = 0)
      AND (p_supplier_id IS NULL OR supplier_id = p_supplier_id);
    
    -- Vínculos de categoria
    RETURN QUERY
    SELECT 'category_assignments'::TEXT, COUNT(*)
    FROM product_category_assignments pca
    JOIN products p ON p.id = pca.product_id
    WHERE p_supplier_id IS NULL OR p.supplier_id = p_supplier_id;
    
    -- Vínculos de material
    RETURN QUERY
    SELECT 'material_links'::TEXT, COUNT(*)
    FROM product_materials pm
    JOIN products p ON p.id = pm.product_id
    WHERE p_supplier_id IS NULL OR p.supplier_id = p_supplier_id;
END;
$$;


