CREATE OR REPLACE FUNCTION "public"."get_best_supplier_for_quantity"("p_variant_id" "uuid", "p_quantity" integer, "p_criteria" character varying DEFAULT 'stock'::character varying) RETURNS TABLE("supplier_id" "uuid", "supplier_name" "text", "supplier_code" "text", "supplier_sku" character varying, "available_quantity" integer, "unit_cost" numeric, "lead_time_days" integer, "can_fulfill" boolean, "recommendation_reason" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    WITH supplier_analysis AS (
        SELECT 
            vss.supplier_id,
            s.name::TEXT AS supplier_name,
            s.code::TEXT AS supplier_code,
            vss.supplier_sku,
            (COALESCE(vss.quantity, 0) - COALESCE(vss.reserved_quantity, 0))::INTEGER AS available_qty,
            -- Calcular preço para a quantidade solicitada
            CASE 
                WHEN p_quantity >= COALESCE(vss.min_qty_5, 2147483647) THEN vss.cost_price_5
                WHEN p_quantity >= COALESCE(vss.min_qty_4, 2147483647) THEN vss.cost_price_4
                WHEN p_quantity >= COALESCE(vss.min_qty_3, 2147483647) THEN vss.cost_price_3
                WHEN p_quantity >= COALESCE(vss.min_qty_2, 2147483647) THEN vss.cost_price_2
                WHEN p_quantity >= COALESCE(vss.min_qty_1, 1) THEN vss.cost_price_1
                ELSE vss.cost_price
            END AS calculated_cost,
            vss.lead_time_days AS lead_time,
            vss.priority,
            COALESCE(vss.is_preferred, FALSE) AS is_preferred
        FROM variant_supplier_sources vss
        INNER JOIN suppliers s ON s.id = vss.supplier_id
        WHERE vss.variant_id = p_variant_id
        AND vss.is_active = TRUE
        AND COALESCE(vss.removed_from_api, FALSE) = FALSE
    )
    SELECT 
        sa.supplier_id,
        sa.supplier_name,
        sa.supplier_code,
        sa.supplier_sku,
        sa.available_qty AS available_quantity,
        sa.calculated_cost AS unit_cost,
        sa.lead_time AS lead_time_days,
        sa.available_qty >= p_quantity AS can_fulfill,
        CASE 
            WHEN sa.available_qty >= p_quantity THEN
                CASE p_criteria
                    WHEN 'stock' THEN 'Maior estoque disponível'
                    WHEN 'cost' THEN 'Menor custo unitário'
                    WHEN 'lead_time' THEN 'Menor prazo de entrega'
                    ELSE 'Recomendado'
                END
            WHEN sa.available_qty > 0 THEN 
                'Estoque parcial: ' || sa.available_qty || ' de ' || p_quantity
            ELSE 
                'Sem estoque disponível'
        END AS recommendation_reason
    FROM supplier_analysis sa
    ORDER BY 
        -- Primeiro: pode atender a quantidade?
        CASE WHEN sa.available_qty >= p_quantity THEN 0 ELSE 1 END,
        -- Segundo: critério escolhido
        CASE p_criteria
            WHEN 'stock' THEN -sa.available_qty
            WHEN 'cost' THEN COALESCE(sa.calculated_cost, 999999)
            WHEN 'lead_time' THEN COALESCE(sa.lead_time, 999)
            ELSE -sa.available_qty
        END,
        -- Terceiro: prioridade
        sa.priority ASC;
END;
$$;


ALTER FUNCTION "public"."get_best_supplier_for_quantity"("p_variant_id" "uuid", "p_quantity" integer, "p_criteria" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_best_supplier_for_quantity"("p_variant_id" "uuid", "p_quantity" integer, "p_criteria" character varying) IS 'Retorna fornecedores ordenados para uma quantidade específica.

PARÂMETROS:
- p_variant_id: UUID da variante
- p_quantity: quantidade desejada
- p_criteria: critério de ordenação (stock, cost, lead_time)

RETORNO:
- Lista de fornecedores ordenados pelo critério
- can_fulfill indica se pode atender toda quantidade
- unit_cost calcula preço escalonado para a quantidade

CRITÉRIOS:
- stock: prioriza maior estoque
- cost: prioriza menor custo (calculado pela faixa)
- lead_time: prioriza menor prazo

EXEMPLO:
SELECT * FROM get_best_supplier_for_quantity(
    ''uuid-variante'', 
    1000, 
    ''cost''
);

Criado em: 25/01/2026';



CREATE OR REPLACE FUNCTION "public"."get_bundle_suggestions"("_product_id" "uuid") RETURNS TABLE("product_id" "uuid", "product_name" "text", "product_image_url" "text", "cooccurrence_count" bigint, "frequency_percent" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH anchor_quotes AS (
    SELECT DISTINCT quote_id FROM public.quote_items WHERE product_id = _product_id
  ),
  total AS (SELECT COUNT(*)::numeric AS n FROM anchor_quotes),
  cooc AS (
    SELECT qi.product_id, MAX(qi.product_name) AS product_name,
      MAX(qi.product_image_url) AS product_image_url,
      COUNT(DISTINCT qi.quote_id) AS cnt
    FROM public.quote_items qi
    JOIN anchor_quotes aq ON aq.quote_id = qi.quote_id
    WHERE qi.product_id IS NOT NULL AND qi.product_id <> _product_id
    GROUP BY qi.product_id
  )
  SELECT c.product_id, c.product_name, c.product_image_url, c.cnt AS cooccurrence_count,
    ROUND((c.cnt::numeric / NULLIF((SELECT n FROM total), 0)) * 100, 1) AS frequency_percent
  FROM cooc c, total
  WHERE total.n >= 3 AND (c.cnt::numeric / NULLIF(total.n, 0)) >= 0.30
  ORDER BY c.cnt DESC LIMIT 5;
$$;


ALTER FUNCTION "public"."get_bundle_suggestions"("_product_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."categories" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "icon" "text",
    "description" "text",
    "parent_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "slug" "text" NOT NULL,
    "image_url" "text",
    "display_order" integer DEFAULT 0,
    "is_active" boolean DEFAULT true NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "organization_id" "uuid" DEFAULT '5db5aee1-064b-4ef4-9193-345dcd8274ea'::"uuid" NOT NULL,
    "bitrix_id" integer,
    "bitrix_modified_at" timestamp with time zone,
    "synced_at" timestamp with time zone,
    "sync_status" "text" DEFAULT 'synced'::"text",
    "level" integer DEFAULT 1 NOT NULL,
    "path" "text",
    "is_visible" boolean DEFAULT true,
    "color_hex" "text",
    "meta_title" "text",
    "meta_description" "text",
    "meta_keywords" "text"[],
    "products_count" integer DEFAULT 0 NOT NULL,
    "children_count" integer DEFAULT 0,
    "descendants_count" integer DEFAULT 0,
    "created_by" "uuid",
    "updated_by" "uuid",
    "deleted_at" timestamp with time zone,
    "full_path_readable" "text",
    "ai_summary" "text",
    "schema_json" "jsonb",
    "seo_priority" numeric(2,1) DEFAULT 0.7,
    "min_order_quantity" integer DEFAULT 1,
    "active" boolean GENERATED ALWAYS AS ("is_active") STORED,
    CONSTRAINT "categories_children_count_check" CHECK (("children_count" >= 0)),
    CONSTRAINT "categories_color_hex_check" CHECK (("color_hex" ~* '^#[0-9A-F]{6}$'::"text")),
    CONSTRAINT "categories_descendants_count_check" CHECK (("descendants_count" >= 0)),
    CONSTRAINT "categories_level_check" CHECK ((("level" >= 1) AND ("level" <= 10))),
    CONSTRAINT "categories_products_count_check" CHECK (("products_count" >= 0)),
    CONSTRAINT "categories_sync_status_check" CHECK (("sync_status" = ANY (ARRAY['synced'::"text", 'pending'::"text", 'error'::"text"]))),
    CONSTRAINT "check_no_self_reference" CHECK (("id" <> "parent_id")),
    CONSTRAINT "chk_categories_display_order_non_negative" CHECK (("display_order" >= 0)),
    CONSTRAINT "chk_categories_image_url_format" CHECK ((("image_url" IS NULL) OR ("image_url" ~ '^https://imagedelivery\.net/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+$'::"text"))),
    CONSTRAINT "chk_categories_name_not_empty" CHECK (("name" !~ '^[[:space:]]*$'::"text")),
    CONSTRAINT "chk_categories_seo_priority_range" CHECK ((("seo_priority" IS NULL) OR (("seo_priority" >= 0.0) AND ("seo_priority" <= 1.0)))),
    CONSTRAINT "chk_categories_slug_not_empty" CHECK (("slug" !~ '^[[:space:]]*$'::"text")),
    CONSTRAINT "chk_icon_lucide_format" CHECK ((("icon" IS NULL) OR ("icon" ~ '^[A-Z][a-z][a-zA-Z0-9]*$'::"text")))
);
ALTER TABLE ONLY "public"."categories" ALTER COLUMN "parent_id" SET STATISTICS 500;


ALTER TABLE "public"."categories" OWNER TO "postgres";


COMMENT ON TABLE "public"."categories" IS 'Árvore hierárquica de categorias (max 6 níveis, auto-referenciada via parent_id). CAMPOS CANÔNICOS: is_active (status), path (materialized path /uuid1/uuid2/), products_count (cache PCA). LEGADOS: active (= is_active), slug (UNIQUE). Dois tipos de raiz: taxonomia canônica (Bar|Cozinha etc.) e coleções endomarketing (Brindes|Unimed etc.).';



COMMENT ON COLUMN "public"."categories"."icon" IS 'Nome PascalCase de ícone Lucide React (ex: Coffee, Wine, PawPrint, Gamepad2). Regra: 1º char maiúsculo [A-Z], 2º char MINÚSCULO obrigatório [a-z], resto alphanumerico [a-zA-Z0-9]*. Constraint chk_icon_lucide_format: ^[A-Z][a-z][a-zA-Z0-9]*$ Garante que "COFFEE" (all-caps), "NULL" (string), siglas "TV"/"USB" sejam rejeitados. Todos os ícones reais do Lucide React seguem este padrão. Fonte de verdade: este campo. archive.category_icons é legada/arquivada.';



COMMENT ON COLUMN "public"."categories"."image_url" IS 'URL pública da imagem de capa da categoria, servida pelo Cloudflare Images CDN.

PADRÃO CANÔNICO (naming convention obrigatório para novas imagens):
  https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/cat-{slug}/public

COMPONENTES DA URL:
  • Account hash : vKMs9Ow8bA_enuhLXZ2HAw  (ID fixo da conta CF da Promo Brindes)
  • Image ID     : cat-{slug}               (prefixo "cat-" + slug da categoria)
  • Variant      : public                   (entrega pública sem autenticação)

ESCOPO ATUAL (2026-06-23):
  • Apenas categorias level=1 (raiz/parent_id IS NULL) têm image_url preenchido.
  • Level 2-5: intencionalmente NULL (navegação secundária sem imagem de capa).
  • Cobertura: 26/26 categorias raiz ativas (100%).

REGRAS DE NEGÓCIO:
  • Para fazer upload da imagem no Cloudflare Images, o image_id DEVE ser "cat-{slug}".
  • Se o slug mudar, a imagem no Cloudflare NÃO é renomeada automaticamente —
    apenas o registro no banco é atualizado pelo trigger
    trg_sync_image_url_on_slug_update (criado em 2026-06-23).
  • URLs fora do padrão canônico (customizadas) são aceitas e preservadas pelo trigger.
  • Formato validado pelo CHECK constraint: chk_categories_image_url_format
    (padrão: ^https://imagedelivery\.net/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+$).

CONSUMERS ATIVOS:
  • RPC  get_root_categories()            → menu principal / home do catálogo
  • RPC  get_category_with_children()     → página de listagem de categoria
  • VIEW vw_sitemap_categories            → sitemap XML (SEO / Google Image Search)
  • VIEW vw_sitemap_all                   → união de sitemaps
  • VIEW vw_category_completeness         → score de completude (15 pontos)

ATENÇÃO: O campo é nullable. Não adicionar URL se a imagem não existir no CF —
a URL seria válida no banco mas geraria 404 no CDN.';



COMMENT ON COLUMN "public"."categories"."display_order" IS 'Ordem de exibição (0=primeiro)';



COMMENT ON COLUMN "public"."categories"."is_active" IS 'CAMPO CANÔNICO de status de categoria. Controla visibilidade no catálogo, filtros e índices. 
Ao inativar uma categoria, setar is_active=false e propagar para subcategorias se necessário.
O campo legado "active" (Bitrix24) foi eliminado em 2026-06-22 após verificação de zero consumidores.';



COMMENT ON COLUMN "public"."categories"."bitrix_id" IS 'ID original da categoria no Bitrix24 para sincronização';



COMMENT ON COLUMN "public"."categories"."sync_status" IS 'Status de sincronização da categoria com sistemas externos. Valores: synced (OK), pending (aguardando sync), error (falhou). DEFAULT synced adicionado em 2026-06-23 — backfill de 477 NULLs para synced realizado.';



COMMENT ON COLUMN "public"."categories"."level" IS 'Nível na hierarquia (1=raiz, 2=sub, 3=sub-sub, etc)';



COMMENT ON COLUMN "public"."categories"."path" IS 'Materialized path para queries rápidas ex: /124/282/';



COMMENT ON COLUMN "public"."categories"."products_count" IS 'CACHE: Contagem de produtos ativos (p.is_active=true) vinculados a esta categoria via product_category_assignments (PCA). Inclui todos os PCA, não só is_primary. Atualizado pelo trigger fn_trigger_sync_pca_products_count (via PCA DML) e pelo cron category-resync-weekly (dom 02h). NÃO conta via products.category_id direto.';



COMMENT ON COLUMN "public"."categories"."children_count" IS 'CACHE: Total de subcategorias DIRETAS (parent_id = este id). Mantido em sincronia pelo trigger trigger_update_children_count (AFTER INSERT/DELETE/UPDATE OF parent_id). Zero inconsistências.';



COMMENT ON COLUMN "public"."categories"."descendants_count" IS 'CACHE: Total de TODAS as categorias descendentes (filhos, netos, ...). Mantido em sincronia pelo trigger trg_sync_descendants_count (AFTER INSERT/DELETE/UPDATE OF parent_id). Reconstruído via cron refresh-category-ancestors (diário 01h).';



COMMENT ON COLUMN "public"."categories"."full_path_readable" IS 'Caminho legível (ex: BAR | COZINHA > COPOS > VIDRO)';



COMMENT ON COLUMN "public"."categories"."ai_summary" IS 'Resumo da categoria para IAs';



COMMENT ON COLUMN "public"."categories"."seo_priority" IS 'Prioridade no sitemap (0.0 a 1.0)';



COMMENT ON COLUMN "public"."categories"."min_order_quantity" IS 'Quantidade mínima de pedido padrão para produtos desta categoria.
Produtos podem ter override via products.min_order_quantity.
Exemplos: Canetas=50, Mochilas=10, Chaveiros=100';



COMMENT ON CONSTRAINT "chk_categories_image_url_format" ON "public"."categories" IS 'Garante que image_url seja uma URL válida do Cloudflare Images (imagedelivery.net) com 3 segmentos de path (account/image_id/variant), ou NULL. Criado em 2026-06-23.';



COMMENT ON CONSTRAINT "chk_categories_name_not_empty" ON "public"."categories" IS 'Garante que name nunca seja vazio ou composto apenas de whitespace. Cobre: space, tab, newline, carriage return, form feed, vertical tab. Fix v2 (2026-06-23): substituiu trim() por regex [[:space:]] para cobertura completa.';



COMMENT ON CONSTRAINT "chk_categories_slug_not_empty" ON "public"."categories" IS 'Garante que slug nunca seja vazio ou composto apenas de whitespace. Cobre: space, tab, newline, carriage return, form feed, vertical tab. Fix v2 (2026-06-23): substituiu trim() por regex [[:space:]] para cobertura completa.';



