    CONSTRAINT "chk_cost_price_not_zero" CHECK ((("cost_price" IS NULL) OR ("cost_price" > (0)::numeric))),
    CONSTRAINT "chk_products_active_has_identity" CHECK ((NOT ("is_active" AND ("sku" IS NULL) AND ("supplier_reference" IS NULL)))),
    CONSTRAINT "chk_products_bestseller_requires_expires" CHECK ((NOT (("is_bestseller" = true) AND ("is_bestseller_expires_at" IS NULL)))),
    CONSTRAINT "chk_products_capacity_ml_pos" CHECK ((("capacity_ml" IS NULL) OR ("capacity_ml" > 0))),
    CONSTRAINT "chk_products_circumference_pos" CHECK ((("circumference_cm" IS NULL) OR ("circumference_cm" > (0)::numeric))),
    CONSTRAINT "chk_products_cofins_rate_range" CHECK ((("cofins_rate" IS NULL) OR (("cofins_rate" >= (0)::numeric) AND ("cofins_rate" <= (100)::numeric)))),
    CONSTRAINT "chk_products_featured_requires_expires" CHECK ((NOT (("is_featured" = true) AND ("is_featured_expires_at" IS NULL)))),
    CONSTRAINT "chk_products_gender_valid" CHECK ((("gender" IS NULL) OR (("gender")::"text" = ANY ((ARRAY['masculino'::character varying, 'feminino'::character varying, 'infantil'::character varying, 'unissex'::character varying])::"text"[])))),
    CONSTRAINT "chk_products_icms_rate_range" CHECK ((("icms_rate" IS NULL) OR (("icms_rate" >= (0)::numeric) AND ("icms_rate" <= (100)::numeric)))),
    CONSTRAINT "chk_products_ipi_rate_range" CHECK ((("ipi_rate" IS NULL) OR (("ipi_rate" >= (0)::numeric) AND ("ipi_rate" <= (100)::numeric)))),
    CONSTRAINT "chk_products_is_new_requires_expires" CHECK ((NOT (("is_new" = true) AND ("is_new_expires_at" IS NULL)))),
    CONSTRAINT "chk_products_lead_time_nonneg" CHECK ((("lead_time_days" IS NULL) OR ("lead_time_days" >= 0))),
    CONSTRAINT "chk_products_meta_desc_length" CHECK ((("meta_description" IS NULL) OR (("length"("meta_description") >= 50) AND ("length"("meta_description") <= 170)))),
    CONSTRAINT "chk_products_meta_title_length" CHECK ((("meta_title" IS NULL) OR (("length"("meta_title") >= 10) AND ("length"("meta_title") <= 70)))),
    CONSTRAINT "chk_products_min_order_positive" CHECK ((("min_order_quantity" IS NULL) OR ("min_order_quantity" >= 1))),
    CONSTRAINT "chk_products_min_quantity_pos" CHECK ((("min_quantity" IS NULL) OR ("min_quantity" >= 1))),
    CONSTRAINT "chk_products_name_max_length" CHECK (("length"("name") <= 250)),
    CONSTRAINT "chk_products_name_not_empty" CHECK (("length"(TRIM(BOTH FROM "name")) > 0)),
    CONSTRAINT "chk_products_pis_rate_range" CHECK ((("pis_rate" IS NULL) OR (("pis_rate" >= (0)::numeric) AND ("pis_rate" <= (100)::numeric)))),
    CONSTRAINT "chk_products_price_freshness_constant" CHECK ((("price_freshness_threshold_days" IS NULL) OR (("price_freshness_threshold_days" >= 1) AND ("price_freshness_threshold_days" <= 365)))),
    CONSTRAINT "chk_products_robots_meta_constant" CHECK ((("robots_meta" IS NULL) OR ("robots_meta" = 'index, follow'::"text"))),
    CONSTRAINT "chk_products_sale_price_nonneg" CHECK ((("sale_price" IS NULL) OR ("sale_price" >= (0)::numeric))),
    CONSTRAINT "chk_products_seo_score_range" CHECK ((("seo_score" IS NULL) OR (("seo_score" >= 0) AND ("seo_score" <= 100)))),
    CONSTRAINT "chk_products_sku_promo_equals_sku" CHECK ((("sku_promo")::"text" = "sku")),
    CONSTRAINT "chk_products_slug_format" CHECK ((("slug" IS NULL) OR ("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::"text"))),
    CONSTRAINT "chk_products_warranty_months_nonneg" CHECK ((("warranty_months" IS NULL) OR ("warranty_months" >= 0))),
    CONSTRAINT "chk_products_weight_nonneg" CHECK ((("weight_g" IS NULL) OR ("weight_g" >= 0))),
    CONSTRAINT "products_catalog_schema_check" CHECK (("catalog_schema" = ANY (ARRAY['active'::"text", 'stockout'::"text", 'promotional'::"text", 'seasonal'::"text"]))),
    CONSTRAINT "products_cost_price_nonneg" CHECK ((("cost_price" IS NULL) OR ("cost_price" >= (0)::numeric))),
    CONSTRAINT "products_dimensions_source_check" CHECK ((("dimensions_source" IS NULL) OR (("dimensions_source")::"text" = ANY ((ARRAY['cm'::character varying, 'mm'::character varying, 'estimated'::character varying, 'manual'::character varying, 'supplier'::character varying])::"text"[])))),
    CONSTRAINT "products_price_freshness_threshold_days_check" CHECK ((("price_freshness_threshold_days" IS NULL) OR (("price_freshness_threshold_days" >= 1) AND ("price_freshness_threshold_days" <= 365)))),
    CONSTRAINT "products_product_type_check" CHECK (("product_type" = ANY (ARRAY['product'::"text", 'packaging'::"text", 'accessory'::"text", 'kit'::"text", 'component'::"text"]))),
    CONSTRAINT "products_shape_type_check" CHECK ((("shape_type" IS NULL) OR (("shape_type")::"text" = ANY ((ARRAY['rectangular'::character varying, 'cylindrical'::character varying, 'irregular'::character varying])::"text"[])))),
    CONSTRAINT "products_supply_mode_check" CHECK ((("supply_mode")::"text" = ANY ((ARRAY['pronta_entrega_liso'::character varying, 'fabricado_personalizado'::character varying, 'fabricado_liso'::character varying])::"text"[])))
)
