COMMENT ON COLUMN "public"."products"."internal_height_cm" IS 'Dimensão interna (altura) para kits/embalagens. null_frac=99.8% (9 valores distintos). Usado em 12 arquivos frontend (kit-builder). DROP requer refatoração coordenada.';



COMMENT ON COLUMN "public"."products"."internal_width_cm" IS 'Dimensão interna (largura). null_frac=99.8%. Usado em kit-builder. DROP requer refatoração coordenada.';



COMMENT ON COLUMN "public"."products"."internal_length_cm" IS 'Dimensão interna (comprimento). null_frac=99.8%. Usado em kit-builder. DROP requer refatoração coordenada.';



COMMENT ON COLUMN "public"."products"."packaging_material" IS 'Material da embalagem. Ex: papel, plástico.';



COMMENT ON COLUMN "public"."products"."is_imported" IS 'TRUE se produto importado (vs nacional). Afeta cálculos fiscais.';



COMMENT ON COLUMN "public"."products"."lead_time_days" IS 'Prazo de produção em dias úteis. 82% preenchido (NULL=herda fornecedor). Valores: 2 ou 3.';



COMMENT ON COLUMN "public"."products"."supply_mode" IS 'Modalidade de fornecimento. FLAG-MORTA: constante pronta_entrega_liso. Futuro uso: diferenciar modos.';



COMMENT ON COLUMN "public"."products"."is_thermal" IS 'TRUE se produto térmico (garrafa, caneca). Classificação automática.';



COMMENT ON COLUMN "public"."products"."capacity_ml" IS 'Capacidade em ml (para copos, garrafas, canecas). Extraído do name por trigger.';



COMMENT ON COLUMN "public"."products"."slug" IS 'URL slug. CHECK garante formato a-z0-9-. Trigger trg_products_slug_redirect cria seo_redirects em UPDATE.';



COMMENT ON COLUMN "public"."products"."ai_summary" IS 'Sumário gerado por IA para product cards. Worker parado desde 2026-04-23.';



COMMENT ON COLUMN "public"."products"."target_audience" IS 'Público-alvo do produto (array). Ex: ["corporativo","executivo"].';



COMMENT ON COLUMN "public"."products"."schema_json" IS 'JSON-LD structured data para SEO (Product schema.org).';



COMMENT ON COLUMN "public"."products"."canonical_url" IS 'URL canônica SEO (/produto/{slug}). Gerada por trigger.';



COMMENT ON COLUMN "public"."products"."robots_meta" IS 'FLAG-MORTA: constante "index, follow" em 100% dos registros.
CHECK chk_products_robots_meta_constant garante imutabilidade.
Mantida para compat com v_products_public, vw_sitemap_products e fn_refresh_product_satellites.
Candidata a DROP quando essas referências forem refatoradas (hardcode o valor na view/função).
2026-06-23: CHECK de imutabilidade adicionado.';



COMMENT ON COLUMN "public"."products"."seo_score" IS 'Score SEO 0-100 calculado por fn_refresh_product_satellites. Auditoria.';



COMMENT ON COLUMN "public"."products"."seo_last_audit_at" IS 'Timestamp do último audit SEO.';



COMMENT ON COLUMN "public"."products"."seo_issues" IS 'Lista de problemas SEO identificados';



COMMENT ON COLUMN "public"."products"."og_title" IS 'Open Graph title. Default = meta_title. Social sharing.';



COMMENT ON COLUMN "public"."products"."og_description" IS 'Open Graph description. Default = meta_description.';



COMMENT ON COLUMN "public"."products"."og_image_url" IS 'Open Graph image. Default = primary_image_url.';



COMMENT ON COLUMN "public"."products"."description_packaging_info" IS 'Informações de embalagem extraídas automaticamente da descrição';



COMMENT ON COLUMN "public"."products"."has_optional_packaging" IS 'Indica se existe embalagem vendida separadamente para este produto';



COMMENT ON COLUMN "public"."products"."optional_packaging_ref" IS 'Referência de embalagem opcional. null_frac=99%+. 1 ref frontend. Candidata a DROP após refatoração.';



COMMENT ON COLUMN "public"."products"."packing_classification" IS 'Classificação semântica da embalagem. Derivada pelo pipeline.';



COMMENT ON COLUMN "public"."products"."ipi_rate" IS 'Alíquota IPI do produto (%)';



COMMENT ON COLUMN "public"."products"."tax_reference_state" IS 'UF de referência para cálculo de impostos';



COMMENT ON COLUMN "public"."products"."engraving_type" IS 'Técnica de gravação principal do produto. Ex: serigrafia, laser, bordado.';



COMMENT ON COLUMN "public"."products"."supplier_updated_at" IS 'Última atualização recebida do fornecedor. Frescor de sync.';



COMMENT ON COLUMN "public"."products"."has_gift_box" IS 'TRUE se tem caixa presente como padrão ou opção.';



COMMENT ON COLUMN "public"."products"."min_order_quantity" IS 'Override de mínimo por produto. 57% preenchido. NULL→herda categoria.';



COMMENT ON COLUMN "public"."products"."ai_title" IS 'Título gerado por IA. Par com ai_description. Worker parado desde 2026-04-23.';



COMMENT ON COLUMN "public"."products"."ai_description" IS 'Descrição gerada por IA. null_frac≈63% (worker parado desde 2026-04-23, reativação pendente). Gerado via ai_enrichment_queue.';



COMMENT ON COLUMN "public"."products"."ai_version" IS 'Versão do modelo de IA que gerou o conteúdo. Inteiro incremental.';



COMMENT ON COLUMN "public"."products"."ai_generated_at" IS 'Timestamp de geração do conteúdo de IA.';



COMMENT ON COLUMN "public"."products"."ai_model" IS 'Identificador do modelo de IA (ex: claude-3-sonnet-20240229).';



COMMENT ON COLUMN "public"."products"."box_image" IS 'URL da imagem da embalagem do produto. Origem: SPOT API BoxImage';



COMMENT ON COLUMN "public"."products"."repacking_classification" IS 'Classificação da embalagem COM gravação: commercial, protective, none, original';



COMMENT ON COLUMN "public"."products"."has_commercial_packaging" IS 'TRUE se tem embalagem comercial própria.';



COMMENT ON COLUMN "public"."products"."packaging_context" IS 'Contexto da embalagem comercial: always, with_customization, without_customization';



COMMENT ON COLUMN "public"."products"."bitrix_product_id" IS 'ID do produto no sistema Bitrix24 (ERP/CRM). 80% preenchido. Integração bidirecional.';



COMMENT ON COLUMN "public"."products"."novelty_detected_at" IS 'Quando o produto foi detectado como novidade. Alimenta badge "Novo".';



COMMENT ON COLUMN "public"."products"."novelty_expires_at" IS 'Quando expira o badge de novidade.';



COMMENT ON COLUMN "public"."products"."ncm_id" IS 'FK para ncm_codes. Populado automaticamente pelo trigger trg_sync_ncm_id a partir de ncm_code.';



COMMENT ON COLUMN "public"."products"."bitrix_images_synced_at" IS 'Timestamp do último sync de imagens com Bitrix24.';



COMMENT ON COLUMN "public"."products"."is_featured_expires_at" IS 'Quando expira o status de destaque (is_featured). NULL = permanente.';



COMMENT ON COLUMN "public"."products"."is_bestseller_expires_at" IS 'Quando expira o status bestseller. NULL = permanente.';



COMMENT ON COLUMN "public"."products"."is_new_expires_at" IS 'Quando expira o status de novo. NULL = permanente.';



COMMENT ON COLUMN "public"."products"."supplier_product_url" IS 'URL da pagina do produto no site do fornecedor (ex: https://www.xbzbrindes.com.br/09139a). Auto-gerado via padrao do fornecedor + supplier_reference. Pode ser editado manualmente.';



COMMENT ON COLUMN "public"."products"."cubic_weight" IS 'Peso cúbico (volume em cm³ / fator de cubagem do frete). Usado no cálculo de frete.';



COMMENT ON COLUMN "public"."products"."auto_material" IS 'Material detectado automaticamente pelo pipeline de IA. Texto livre.';



COMMENT ON COLUMN "public"."products"."price_updated_at" IS 'Timestamp da última atualização de preço (sale_price ou cost_price).';



COMMENT ON COLUMN "public"."products"."price_freshness_threshold_days" IS 'FLAG-MORTA: constante 60. Threshold de frescor de preço em dias. CHECK range 1-365. 2026-06-23.';



COMMENT ON COLUMN "public"."products"."set_image_url" IS 'URL da imagem "set" (todas as cores juntas) no Cloudflare Images. Usada como imagem de hover no catálogo. Sem sufixo de variante — concatenar /public. SPOT: image_type=set original. XBZ: imagem d1 reclassificada (2026-06-02).';



COMMENT ON COLUMN "public"."products"."search_vector" IS 'Vetor tsvector para busca full-text. Mantido por trigger (Weight A=name, B=description, C=tags). Alimenta fn_global_search.';



COMMENT ON COLUMN "public"."products"."locked_fields" IS 'Array de nomes de colunas protegidas de sobrescrita pelo pipeline. Gerenciado por trg_aa_capture_manual_edits.';



COMMENT ON COLUMN "public"."products"."supplier_type" IS 'Tipo do fornecedor deste produto. Derivado de suppliers.type.';



COMMENT ON COLUMN "public"."products"."supplier_subtype" IS 'Subtipo do fornecedor. Derivado de suppliers.subtype.';



COMMENT ON COLUMN "public"."products"."weight_gr" IS 'Gramatura têxtil em g/m² (texto, ex: "80 g/m²"). DIFERENTE de weight_g (peso em gramas). 114 registros (produtos têxteis).';



COMMENT ON COLUMN "public"."products"."is_seasonal" IS 'Produto sazonal. Classificação de sazionalidade (Natal, Páscoa, etc).';



COMMENT ON COLUMN "public"."products"."pvc_free" IS 'TRUE se produto é livre de PVC. Campo de compliance ambiental.';



COMMENT ON COLUMN "public"."products"."price_verified_at" IS 'Timestamp da última verificação manual de preço.';



COMMENT ON COLUMN "public"."products"."sub_brand" IS 'Sub-marca ou linha do produto (ex: Linha Premium, Linha Eco). 15.8% preenchido.';



COMMENT ON COLUMN "public"."products"."sub_brand_id" IS 'FK para a sub-marca (uuid). Par com sub_brand. 15.8% preenchido.';



COMMENT ON COLUMN "public"."products"."supplier_categories" IS 'Catálogos comerciais do fornecedor (ex: ["SPOT","Our Nature","Stockout"]). Origem: campo Catalogs do OptionalsComplete (SPOT). Fluxo: Bronze raw_data -> Prata (fn_spot_silver_enrich) -> Gold (fn_spot_gold_enrich).';



COMMENT ON COLUMN "public"."products"."catalog_schema" IS 'Segmento SPOT. Propagado de produtos_padronizacao.catalog_schema.
  active | stockout | promotional | seasonal';



COMMENT ON COLUMN "public"."products"."circumference_cm" IS 'Circunferência em cm (calculada de diameter_cm × π para objetos cilíndricos).';



COMMENT ON COLUMN "public"."products"."packing_type_canonical" IS 'Canônico normalizado de packing_type. Gerado automaticamente por fn_normalize_packing_type(). 21 valores possíveis. Sempre sincronizado com packing_type (coluna gerada).';



COMMENT ON COLUMN "public"."products"."price_last_verified_at" IS 'Última vez que o preço foi VERIFICADO (independente de ter mudado). Diferente de price_updated_at que só muda quando o preço muda. Usado para o badge #19 Freshness de Preço: stale = NOW()-price_last_verified_at > price_freshness_threshold_days. Atualizado pelo pipeline de sync de cada fornecedor.';



COMMENT ON COLUMN "public"."products"."color_swatches" IS 'jsonb de swatches de cor para exibição em grid. Gerado por fn_generate_color_swatches.';



COMMENT ON COLUMN "public"."products"."dimensions_source" IS 'Origem/unidade das dimensões escalares. Valores: cm, mm, estimated, manual, supplier. Migrado de dimensions->unit_detected em 2026-06-23.';



COMMENT ON COLUMN "public"."products"."modo_de_uso" IS 'Instruções de uso do produto, conforme publicado na página do produto XBZ (site_data.modo_de_uso). Campo informativo, não operacional.';



COMMENT ON COLUMN "public"."products"."is_closeout" IS 'Indica produto em ponta de estoque / liquidação no fornecedor XBZ (WebTipo=PONTA DE ESTOQUE). Atualizado via sync. Não afeta is_active — produto pode ser ativo e em liquidação simultaneamente.';



COMMENT ON COLUMN "public"."products"."xbz_stock_reliability_id" IS 'ID numérico do status de confiabilidade de estoque XBZ (IdStatusConfiabilidade). Valor conhecido: 10 = estoque confirmado por inventário recente. NULL = não informado ou fornecedor diferente de XBZ.';



COMMENT ON COLUMN "public"."products"."xbz_stock_reliability_text" IS 'Descrição completa do status de confiabilidade de estoque XBZ (StatusConfiabilidade). Ex.: "Quantidade CONFIÁVEL. Confirmada através de inventário realizado recentemente." Atualizado via sync.';



COMMENT ON COLUMN "public"."products"."is_online_exclusive" IS 'Indica produto de venda exclusiva pelo canal online no fornecedor Spot/Stricker (OnlineExclusive=true). Atualizado via sync. DEFAULT false para todos os fornecedores que não usam este flag.';



COMMENT ON COLUMN "public"."products"."category_name" IS 'Cache desnormalizado de categories.name via category_id. Mantido sincronizado por trg_sync_product_category_name. Restaurado em 2026-06-25 após migrations 20260519163704/164522 não terem executado em produção (statements:[]).';



COMMENT ON COLUMN "public"."products"."padronizacao_id" IS '[fix_version:silver_gold_link_20260627] FK para o registro Silver canônico (produtos_padronizacao)
 que originou este produto Gold. Populado pelo medallion promote tick.
 NULL = produto criado manualmente sem origem Silver.
 ON DELETE SET NULL: remoção do Silver não quebra o Gold.
 Para produtos com múltiplos Silver (multi-fornecedor), aponta para o Silver
 com promoted_at mais recente.';



COMMENT ON COLUMN "public"."products"."ean" IS 'Código de barras EAN. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."gtin" IS 'GTIN. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."icms_rate" IS 'Alíquota ICMS (%). CHECK 0-100. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."pis_rate" IS 'Alíquota PIS (%). CHECK 0-100. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."cofins_rate" IS 'Alíquota COFINS (%). CHECK 0-100. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."cfop" IS 'CFOP. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."csosn" IS 'CSOSN (Simples). fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."cest" IS 'CEST. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."tax_regime" IS 'Regime tributário. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."is_on_sale" IS 'Flag promoção. SEM requires-expires (evita novo crash). fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."is_on_sale_expires_at" IS 'Expiração da promoção. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."internal_diameter_cm" IS 'Diâmetro interno (cm). fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."packaging_color" IS 'Cor da embalagem. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."packaging_finish" IS 'Acabamento da embalagem. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."key_benefits" IS 'Benefícios-chave (array). fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."use_cases" IS 'Casos de uso (array). fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."warranty_months" IS 'Garantia (meses). fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."shipping_weight_kg" IS 'Peso para frete (kg). fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."shipping_width_cm" IS 'Largura p/ frete (cm). fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."shipping_height_cm" IS 'Altura p/ frete (cm). fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."shipping_length_cm" IS 'Comprimento p/ frete (cm). fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."freight_class" IS 'Classe de frete. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."default_carrier" IS 'Transportadora padrão. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."requires_special_shipping" IS 'Exige frete especial. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON COLUMN "public"."products"."shipping_notes" IS 'Observações de frete. fix_version=cadastro-produtos-audit-20260627-v1';



COMMENT ON CONSTRAINT "chk_cost_price_not_zero" ON "public"."products" IS 'cost_price NUNCA pode ser 0: NULL=desconhecido, >0=valor real.';



COMMENT ON CONSTRAINT "chk_products_name_not_empty" ON "public"."products" IS 'Bloqueia name vazio ou só whitespace - descoberto em auditoria pré-prod 23/04/2026';



CREATE OR REPLACE VIEW "public"."v_products_public" WITH ("security_invoker"='false') AS
 SELECT "p"."id",
    "p"."name",
    "p"."description",
    "p"."sku",
    "p"."category_id",
    "p"."supplier_id",
    NULL::numeric AS "cost_price",
    "p"."sale_price",
    "p"."stock_quantity",
    "p"."is_active" AS "active",
    "p"."created_at",
    "p"."updated_at",
    NULL::numeric AS "suggested_price",
        CASE
            WHEN (("p"."length_cm" IS NOT NULL) OR ("p"."width_cm" IS NOT NULL) OR ("p"."height_cm" IS NOT NULL) OR ("p"."weight_g" IS NOT NULL) OR ("p"."diameter_cm" IS NOT NULL) OR ("p"."shape_type" IS NOT NULL)) THEN "jsonb_build_object"('length_cm', "p"."length_cm", 'width_cm', "p"."width_cm", 'height_cm', "p"."height_cm", 'weight_g', "p"."weight_g", 'diameter_cm', "p"."diameter_cm", 'shape_type', "p"."shape_type", 'unit_detected', "p"."dimensions_source")
            ELSE NULL::"jsonb"
        END AS "dimensions",
    "p"."images",
    "p"."primary_image_url",
    "p"."videos",
    "p"."allows_personalization",
    "p"."colors",
    "p"."materials",
    "p"."tags",
    "p"."meta_title",
    "p"."meta_description",
    "p"."meta_keywords",
    "p"."is_featured",
    "p"."is_new",
    "p"."is_on_sale",
    "p"."view_count",
    "p"."favorite_count",
    "p"."order_count",
    NULL::"uuid" AS "organization_id",
    "p"."product_type",
    "p"."is_active",
    NULL::"uuid" AS "created_by",
    NULL::"uuid" AS "updated_by",
    "p"."sku_promo",
    "p"."short_description",
    "p"."main_category_id",
    "p"."brand",
    "p"."is_deleted",
    "p"."deleted_at",
    "p"."is_kit",
    "p"."is_bestseller",
    "p"."min_quantity",
    "p"."box_length_mm",
    "p"."box_width_mm",
    "p"."box_height_mm",
    "p"."box_weight_kg",
    "p"."has_colors",
    "p"."has_sizes",
    "p"."ean",
    "p"."gtin",
    "p"."ncm_code",
    "p"."origin_country",
    "p"."warranty_months",
    NULL::character varying(100) AS "manufacturer_sku",
    "p"."last_stock_update_at",
    "p"."supplier_reference",
    "p"."is_textil",
    "p"."has_capacity",
    "p"."combined_sizes",
    "p"."gender",
    "p"."is_stockout",
    NULL::boolean AS "is_online_exclusive",
    NULL::integer AS "catalog_page",
    "p"."weight_g",
    "p"."length_cm",
    "p"."width_cm",
    "p"."height_cm",
    "p"."dimensions_display",
    "p"."box_length_cm",
    "p"."box_width_cm",
    "p"."box_height_cm",
    "p"."box_volume_cm3",
    "p"."box_quantity",
    "p"."box_inner_quantity",
    "p"."packing_type",
    "p"."repacking_type",
    "p"."capacities",
    NULL::timestamp with time zone AS "last_sync_at",
    NULL::"uuid" AS "last_sync_supplier_id",
    NULL::character varying AS "sync_status",
    "p"."diameter_cm",
    "p"."shape_type",
    "p"."internal_height_cm",
    "p"."internal_width_cm",
    "p"."internal_length_cm",
    "p"."internal_diameter_cm",
    "p"."packaging_material",
    "p"."packaging_color",
    NULL::boolean AS "has_inner_cradle",
    NULL::character varying(50) AS "cradle_material",
    "p"."packaging_finish",
    "p"."is_imported",
    "p"."lead_time_days",
    NULL::boolean AS "requires_minimum_order",
    "p"."supply_mode",
    "p"."is_thermal",
    "p"."capacity_ml",
    "p"."slug",
    "p"."ai_summary",
    "p"."key_benefits",
    "p"."use_cases",
    "p"."target_audience",
    "p"."schema_json",
    "p"."canonical_url",
    "p"."robots_meta",
    "p"."seo_score",
    "p"."seo_last_audit_at",
    "p"."seo_issues",
    "p"."og_title",
    "p"."og_description",
    "p"."og_image_url",
    "p"."description_packaging_info",
    "p"."has_optional_packaging",
    "p"."optional_packaging_ref",
    "p"."packing_classification",
    ("p"."ipi_rate")::numeric AS "ipi_rate",
    ("p"."tax_reference_state")::character varying AS "tax_reference_state",
    "p"."engraving_type",
    "p"."supplier_updated_at",
    "p"."has_gift_box",
    "p"."min_order_quantity",
    "p"."ai_title",
    "p"."ai_description",
    "p"."ai_version",
    "p"."ai_generated_at",
    "p"."ai_model",
    "p"."box_image",
    "p"."repacking_classification",
    "p"."has_commercial_packaging",
    "p"."packaging_context",
    "p"."bitrix_product_id",
    "p"."novelty_detected_at",
    "p"."novelty_expires_at",
    "p"."ncm_id",
    NULL::timestamp with time zone AS "bitrix_images_synced_at",
    "p"."is_featured_expires_at",
    "p"."is_bestseller_expires_at",
    "p"."is_on_sale_expires_at",
    "p"."is_new_expires_at",
    "p"."supplier_product_url",
    "p"."freight_class",
    "p"."cubic_weight",
    NULL::"text" AS "auto_category",
    "p"."auto_material",
    NULL::double precision AS "classification_confidence",
    "p"."price_updated_at",
    NULL::"text" AS "external_id",
    "p"."price_freshness_threshold_days",
    "p"."set_image_url",
    "p"."is_seasonal",
    "p"."pvc_free",
    "p"."supplier_type",
    "p"."supplier_subtype",
    "p"."supplier_type_code",
    "p"."supplier_subtype_code",
    "p"."price_verified_at",
    "p"."circumference_cm",
    "p"."search_vector",
    "p"."primary_image_fallback_url",
    COALESCE("lc"."leaf_category_id", "p"."main_category_id", "p"."category_id") AS "leaf_category_id",
    "lc"."leaf_category_name",
    "lc"."leaf_category_level",
    "lc"."leaf_category_slug",
    COALESCE("lc"."leaf_category_id_safe", "p"."main_category_id", "p"."category_id") AS "leaf_category_id_safe",
    "p"."color_swatches",
    "p"."dimensions_source",
    "p"."default_carrier",
    "p"."shipping_weight_kg",
    "p"."shipping_width_cm",
    "p"."shipping_height_cm",
    "p"."shipping_length_cm",
    "p"."requires_special_shipping",
    "p"."shipping_notes",
    "p"."icms_rate",
    "p"."pis_rate",
    "p"."cofins_rate",
    "p"."cfop",
    "p"."csosn",
    "p"."cest",
    "p"."tax_regime"
   FROM ("public"."products" "p"
     LEFT JOIN "internal"."mv_product_leaf_category" "lc" ON (("lc"."product_id" = "p"."id")))
  WHERE (("p"."is_deleted" IS NOT TRUE) AND ("p"."is_active" = true));


ALTER VIEW "public"."v_products_public" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_products_public" IS 'PUBLIC PRODUCT PROJECTION (SECURITY DEFINER intencional / fix_version 20260717_v1). Mascara explicitamente cost_price=NULL, organization_id=NULL, created_by=NULL, etc. Roda como owner para ler products sem conceder acesso direto ao anon. NAO alterar para security_invoker=true (expoeria cost_price real ao anon via REST). Filter: is_active=true AND is_deleted IS NOT TRUE.';



CREATE OR REPLACE FUNCTION "public"."get_catalog_bestseller_page"("p_sort" "text" DEFAULT 'best-seller-supplier'::"text", "p_limit" integer DEFAULT 500, "p_offset" integer DEFAULT 0) RETURNS SETOF "public"."v_products_public"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_limit  integer := GREATEST(COALESCE(p_limit, 500), 0);
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_sql    text;
BEGIN
  IF p_sort = 'best-seller-supplier' THEN
    v_sql := '
      SELECT vp.*
      FROM public.v_products_public vp
      LEFT JOIN public.mv_product_intelligence mi ON mi.product_id = vp.id
      WHERE vp.active = true
      ORDER BY COALESCE(mi.turnover_score, 0) DESC NULLS LAST, vp.name ASC, vp.id ASC
      LIMIT ' || v_limit || ' OFFSET ' || v_offset;

  ELSIF p_sort = 'best-seller-promo' THEN
    v_sql := '
      SELECT vp.*
      FROM public.v_products_public vp
      LEFT JOIN (
        SELECT product_id AS pid, sum(COALESCE(quantity, 1)) AS promo_qty
        FROM public.quote_items
        WHERE product_id IS NOT NULL
        GROUP BY product_id
      ) qs ON qs.pid = vp.id
      WHERE vp.active = true
      ORDER BY
        COALESCE(qs.promo_qty, 0) DESC NULLS LAST,
        COALESCE(vp.is_bestseller, false) DESC,
        vp.name ASC, vp.id ASC
      LIMIT ' || v_limit || ' OFFSET ' || v_offset;

  ELSE
    v_sql := '
      SELECT vp.*
      FROM public.v_products_public vp
      WHERE vp.active = true
      ORDER BY vp.name ASC, vp.id ASC
      LIMIT ' || v_limit || ' OFFSET ' || v_offset;
  END IF;

  RETURN QUERY EXECUTE v_sql;
END;
$$;


ALTER FUNCTION "public"."get_catalog_bestseller_page"("p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_category_breadcrumbs"("p_category_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "slug" "text", "level" integer)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH RECURSIVE ancestors AS (
    -- Base: categoria inicial
    SELECT c.id, c.name, c.slug, c.level, c.parent_id
    FROM categories c
    WHERE c.id = p_category_id
      AND c.deleted_at IS NULL
    
    UNION ALL
    
    -- Recursivo: parents
    SELECT c.id, c.name, c.slug, c.level, c.parent_id
    FROM categories c
    INNER JOIN ancestors a ON c.id = a.parent_id
    WHERE c.deleted_at IS NULL
  )
  SELECT a.id, a.name, a.slug, a.level
  FROM ancestors a
  ORDER BY a.level ASC;
END;
$$;


