CREATE OR REPLACE FUNCTION "public"."get_edge_function_secret"("_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'vault', 'public', 'pg_temp'
    AS $$
DECLARE
  _secret text;
BEGIN
  IF _name NOT IN (
    'WEBHOOK_DISPATCHER_SECRET',
    'WEBHOOK_DISPATCHER_URL',
    'WEBHOOK_SECRET',
    'CONNECTIONS_AUTO_TEST_SECRET',
    'CRON_SECRET',
    'HASH_PRODUCT_IMAGES_CRON_SECRET',
    'GENERATE_BLURHASHES_CRON_SECRET',
    'BACKFILL_DIM_CRON_SECRET'
  ) THEN
    RAISE EXCEPTION 'Nome de secret nao autorizado: %', _name
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT decrypted_secret INTO _secret
  FROM vault.decrypted_secrets
  WHERE name = _name
  LIMIT 1;

  IF _secret IS NULL THEN
    RAISE EXCEPTION 'Secret % nao encontrado no vault', _name
      USING ERRCODE = 'no_data_found';
  END IF;

  RETURN _secret;
END;
$$;


ALTER FUNCTION "public"."get_edge_function_secret"("_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_edge_function_secret"("_name" "text") IS 'Whitelist de secrets autorizados: WEBHOOK_DISPATCHER_SECRET, WEBHOOK_DISPATCHER_URL, WEBHOOK_SECRET, CONNECTIONS_AUTO_TEST_SECRET, CRON_SECRET, HASH_PRODUCT_IMAGES_CRON_SECRET, GENERATE_BLURHASHES_CRON_SECRET, BACKFILL_DIM_CRON_SECRET';



CREATE OR REPLACE FUNCTION "public"."get_edge_functions_base_url"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'pg_temp'
    AS $_$
DECLARE
  _cfg text;
  _vault text;
BEGIN
  _cfg := NULLIF(current_setting('app.edge_functions_base_url', true), '');

  IF _cfg IS NOT NULL THEN
    IF _cfg ~ '^https://[a-z0-9-]+\.supabase\.co$' THEN
      RETURN _cfg;
    END IF;

    RAISE EXCEPTION 'app.edge_functions_base_url invalido: %', _cfg
      USING ERRCODE = '22023';
  END IF;

  SELECT decrypted_secret INTO _vault
  FROM vault.decrypted_secrets
  WHERE name = 'EDGE_FUNCTIONS_BASE_URL'
  LIMIT 1;

  IF _vault IS NOT NULL THEN
    IF _vault ~ '^https://[a-z0-9-]+\.supabase\.co$' THEN
      RETURN _vault;
    END IF;

    RAISE EXCEPTION 'Secret EDGE_FUNCTIONS_BASE_URL invalido no vault: %', _vault
      USING ERRCODE = '22023';
  END IF;

  RAISE EXCEPTION 'Base URL das Edge Functions nao configurada. Defina app.edge_functions_base_url ou secret EDGE_FUNCTIONS_BASE_URL.'
    USING ERRCODE = 'no_data_found';
END;
$_$;


ALTER FUNCTION "public"."get_edge_functions_base_url"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_edge_functions_base_url"() IS 'Resolve base URL das Edge Functions via current_setting(app.edge_functions_base_url) e fallback para vault EDGE_FUNCTIONS_BASE_URL.';



CREATE OR REPLACE FUNCTION "public"."get_favorite_list_counts"("_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("list_id" "uuid", "item_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT fl.id AS list_id, COUNT(fi.id)::bigint AS item_count
  FROM favorite_lists fl LEFT JOIN favorite_items fi ON fi.list_id = fl.id
  WHERE fl.user_id = COALESCE(_user_id, (SELECT auth.uid()))
    AND (COALESCE(_user_id, (SELECT auth.uid())) = (SELECT auth.uid())
      OR is_admin_or_above((SELECT auth.uid())))
    AND fl.is_archived = false
  GROUP BY fl.id ORDER BY fl.position ASC NULLS LAST, fl.created_at ASC;
$$;


