CREATE OR REPLACE FUNCTION "public"."get_image_full_metadata"("p_filename" "text", "p_supplier_code" character varying DEFAULT 'spot'::character varying) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_internal RECORD;
    v_result JSONB;
    v_url_base TEXT;
BEGIN
    -- Obter tipo interno
    SELECT * INTO v_internal
    FROM get_internal_image_type(p_filename, p_supplier_code)
    LIMIT 1;
    
    -- Definir URL base por fornecedor
    CASE upper(p_supplier_code)
        WHEN 'SPOT' THEN v_url_base := 'https://www.spotgifts.com.br/fotos/produtos/';
        ELSE v_url_base := '';
    END CASE;
    
    -- Montar resultado
    v_result := v_internal.parsed_data || jsonb_build_object(
        'image_type_id', v_internal.image_type_id,
        'image_type_code', v_internal.image_type_code,
        'image_type_name', v_internal.image_type_name,
        'category', v_internal.category,
        'display_priority', v_internal.display_priority,
        'url_base', v_url_base,
        'url_full', v_url_base || p_filename
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_image_full_metadata"("p_filename" "text", "p_supplier_code" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_image_full_metadata"("p_filename" "text", "p_supplier_code" character varying) IS 'Retorna metadados completos de uma imagem incluindo tipo interno, parsing e URLs. Útil para importação automatizada.';



CREATE OR REPLACE FUNCTION "public"."get_image_url_cdn"("p_image_id" "uuid", "p_width" integer DEFAULT NULL::integer, "p_height" integer DEFAULT NULL::integer, "p_format" character varying DEFAULT NULL::character varying) RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_url TEXT;
    v_params TEXT := '';
BEGIN
    SELECT url_cdn INTO v_url FROM public.product_images WHERE id = p_image_id;
    
    IF v_url IS NULL THEN RETURN NULL; END IF;
    
    IF p_width IS NOT NULL THEN
        v_params := '/width=' || p_width;
    END IF;
    
    IF p_height IS NOT NULL THEN
        v_params := v_params || CASE WHEN v_params != '' THEN ',' ELSE '/' END || 'height=' || p_height;
    END IF;
    
    IF p_format IS NOT NULL THEN
        v_params := v_params || CASE WHEN v_params != '' THEN ',' ELSE '/' END || 'format=' || p_format;
    END IF;
    
    RETURN v_url || v_params;
END;
$$;


ALTER FUNCTION "public"."get_image_url_cdn"("p_image_id" "uuid", "p_width" integer, "p_height" integer, "p_format" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_industry_benchmark_stats"("_company_ids" "uuid"[], "_days" integer DEFAULT 180) RETURNS TABLE("total_clients_sampled" integer, "avg_ltv" numeric, "avg_ticket" numeric, "avg_quotes_per_client" numeric, "avg_items_per_quote" numeric, "top_product_name" "text", "total_revenue" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_top_product_name text;
BEGIN
  -- Top produto pré-calculado (subquery isolada)
  SELECT qi.product_name INTO v_top_product_name
  FROM public.quote_items qi
  JOIN public.quotes q ON q.id = qi.quote_id
  WHERE q.client_id = ANY(_company_ids)
    AND q.status IS DISTINCT FROM 'cancelled'
    AND q.created_at >= now() - make_interval(days => _days)
  GROUP BY qi.product_name
  ORDER BY SUM(qi.quantity) DESC
  LIMIT 1;

  RETURN QUERY
  WITH quote_stats AS (
    SELECT 
      q.client_id,
      COUNT(*)::integer            AS quotes_count,
      COALESCE(AVG(q.total), 0)    AS avg_total,
      COALESCE(SUM(q.total), 0)    AS client_revenue
    FROM public.quotes q
    WHERE q.client_id = ANY(_company_ids)
      AND q.status IS DISTINCT FROM 'cancelled'
      AND q.status IS DISTINCT FROM 'draft'
      AND q.created_at >= now() - make_interval(days => _days)
    GROUP BY q.client_id
  ),
  items_stats AS (
    SELECT 
      q.client_id,
      AVG(item_count.cnt) AS avg_items
    FROM public.quotes q
    JOIN LATERAL (
      SELECT COUNT(*)::numeric AS cnt 
      FROM public.quote_items qi 
      WHERE qi.quote_id = q.id
    ) item_count ON true
    WHERE q.client_id = ANY(_company_ids)
      AND q.created_at >= now() - make_interval(days => _days)
    GROUP BY q.client_id
  )
  SELECT 
    COUNT(DISTINCT qs.client_id)::integer       AS total_clients_sampled,
    COALESCE(AVG(qs.client_revenue), 0)::numeric AS avg_ltv,
    COALESCE(AVG(qs.avg_total), 0)::numeric      AS avg_ticket,
    COALESCE(AVG(qs.quotes_count), 0)::numeric   AS avg_quotes_per_client,
    COALESCE(AVG(its.avg_items), 0)::numeric     AS avg_items_per_quote,
    v_top_product_name                           AS top_product_name,
    COALESCE(SUM(qs.client_revenue), 0)::numeric AS total_revenue
  FROM quote_stats qs
  LEFT JOIN items_stats its ON its.client_id = qs.client_id;
END $$;


ALTER FUNCTION "public"."get_industry_benchmark_stats"("_company_ids" "uuid"[], "_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_industry_benchmark_stats"("_company_ids" "uuid"[], "_days" integer) IS 'Estatísticas agregadas do setor (LTV médio, ticket médio, frequência) para benchmark cliente vs setor. Retorna 1 row com agregados — não expõe dados de clientes individuais. Usada pelo useClientVsIndustry.';



CREATE OR REPLACE FUNCTION "public"."get_industry_seasonality"("_company_ids" "uuid"[], "_months" integer DEFAULT 24) RETURNS TABLE("year" integer, "month" integer, "avg_quotes_per_company" numeric, "avg_revenue_per_company" numeric, "companies_active" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH per_client_month AS (
    SELECT q.client_id,
      EXTRACT(YEAR FROM q.created_at)::int AS y,
      EXTRACT(MONTH FROM q.created_at)::int AS m,
      COUNT(*)::numeric AS qc,
      COALESCE(SUM(q.total), 0)::numeric AS rev
    FROM public.quotes q
    WHERE q.client_id = ANY(_company_ids)
      AND q.status IN ('sent','viewed','approved','converted','pending_approval')
      AND q.created_at >= now() - (GREATEST(_months, 1) || ' months')::interval
      AND auth.uid() IS NOT NULL
    GROUP BY q.client_id, 2, 3
  )
  SELECT y AS year, m AS month,
    AVG(qc)::numeric AS avg_quotes_per_company,
    AVG(rev)::numeric AS avg_revenue_per_company,
    COUNT(DISTINCT client_id)::bigint AS companies_active
  FROM per_client_month
  GROUP BY y, m ORDER BY y, m;
$$;


ALTER FUNCTION "public"."get_industry_seasonality"("_company_ids" "uuid"[], "_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_industry_top_products"("_company_ids" "uuid"[], "_days" integer DEFAULT 90, "_limit" integer DEFAULT 10) RETURNS TABLE("product_id" "uuid", "product_name" "text", "product_image_url" "text", "total_quantity" bigint, "unique_clients" bigint, "unique_sellers" bigint, "total_revenue" numeric, "avg_unit_price" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT 
    oi.product_id,
    oi.product_name,
    oi.product_image_url,
    SUM(oi.quantity)::bigint                                AS total_quantity,
    COUNT(DISTINCT o.client_id)::bigint                     AS unique_clients,
    COUNT(DISTINCT o.seller_id)::bigint                     AS unique_sellers,
    COALESCE(SUM(oi.quantity * oi.unit_price), 0)::numeric  AS total_revenue,
    COALESCE(AVG(oi.unit_price), 0)::numeric                AS avg_unit_price
  FROM public.orders o
  JOIN public.order_items oi ON oi.order_id = o.id
  WHERE o.client_id = ANY(_company_ids)
    AND o.status IS DISTINCT FROM 'cancelled'
    AND o.status IS DISTINCT FROM 'draft'
    AND o.created_at >= now() - make_interval(days => _days)
  GROUP BY oi.product_id, oi.product_name, oi.product_image_url
  ORDER BY SUM(oi.quantity) DESC
  LIMIT _limit
$$;


ALTER FUNCTION "public"."get_industry_top_products"("_company_ids" "uuid"[], "_days" integer, "_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_industry_top_products"("_company_ids" "uuid"[], "_days" integer, "_limit" integer) IS 'Agrega top produtos do setor a partir de orders+order_items. SECURITY DEFINER pq vendedor precisa ver agregados de clientes do mesmo ramo (atravessa RLS). Retorna apenas dados agregados — nomes de clientes individuais NÃO são expostos.';



CREATE OR REPLACE FUNCTION "public"."get_inventory_health"() RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total_products  INTEGER;
  v_with_stock      INTEGER;
  v_low_stock       INTEGER;
  v_no_stock        INTEGER;
  v_total_value     NUMERIC;
  v_total_units     BIGINT;
BEGIN
  SELECT COUNT(*) INTO v_total_products
  FROM products WHERE is_active = true AND deleted_at IS NULL;

  SELECT COUNT(DISTINCT p.id) INTO v_with_stock
  FROM products p
  JOIN product_variants pv ON pv.product_id = p.id
  WHERE p.is_active = true AND p.deleted_at IS NULL
    AND pv.is_active = true          -- FIX: ignora variantes inativas
    AND pv.stock_quantity > 0;

  SELECT COUNT(DISTINCT p.id) INTO v_low_stock
  FROM products p
  JOIN product_variants pv ON pv.product_id = p.id
  WHERE p.is_active = true AND p.deleted_at IS NULL
    AND pv.is_active = true          -- FIX: ignora variantes inativas
    AND pv.stock_quantity > 0 AND pv.stock_quantity < 10;

  v_no_stock := v_total_products - v_with_stock;

  SELECT
    COALESCE(SUM(vss.quantity::bigint * COALESCE(vss.cost_price, 0)), 0),
    COALESCE(SUM(vss.quantity::bigint), 0)
  INTO v_total_value, v_total_units
  FROM product_variants pv
  JOIN products p          ON p.id = pv.product_id
  JOIN variant_supplier_sources vss ON vss.variant_id = pv.id AND vss.is_active = true
  WHERE p.is_active = true AND p.deleted_at IS NULL AND pv.is_active = true;

  RETURN json_build_object(
    'summary', json_build_object(
      'total_products',    v_total_products,
      'with_stock',        v_with_stock,
      'with_stock_pct',    ROUND((v_with_stock::NUMERIC / NULLIF(v_total_products,0) * 100), 1),
      'low_stock',         v_low_stock,
      'no_stock',          v_no_stock,
      'no_stock_pct',      ROUND((v_no_stock::NUMERIC / NULLIF(v_total_products,0) * 100), 1)
    ),
    'inventory', json_build_object(
      'total_units',  v_total_units,
      'total_value',  ROUND(v_total_value, 2),
      'currency',     'BRL',
      'note',         'Valor calculado via VSS cost_price (custo líquido fornecedor)'
    ),
    'alerts', json_build_object(
      'critical_low_stock', v_low_stock,
      'out_of_stock',       v_no_stock
    ),
    'generated_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."get_inventory_health"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_inventory_health"() IS 'Retorna análise de saúde do estoque';



CREATE OR REPLACE FUNCTION "public"."get_login_attempts_status"("_email" "text" DEFAULT NULL::"text", "_ip" "text" DEFAULT NULL::"text", "_window_minutes" integer DEFAULT 15) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'total', count(*),
    'success', count(*) FILTER (WHERE success = true),
    'failed', count(*) FILTER (WHERE success = false),
    'last_attempt', max(created_at)
  ) FROM public.login_attempts
  WHERE created_at > now() - (_window_minutes || ' minutes')::interval
    AND (_email IS NULL OR email = _email)
    AND (_ip IS NULL OR ip_address = _ip);
$$;


