CREATE OR REPLACE FUNCTION "public"."get_materials_complete_safe"() RETURNS TABLE("material_id" "uuid", "material_name" "text", "material_slug" "text", "material_description" "text", "group_id" "uuid", "group_name" "text", "group_slug" "text", "display_order" integer, "is_active" boolean)
