  v4 2026-06-07: refatorada para ler de v_product_videos_ready (deprecated)
';



CREATE OR REPLACE FUNCTION "public"."get_product_variants_with_prices"("p_product_id" "uuid", "p_quantity" integer DEFAULT 1) RETURNS TABLE("id" "uuid", "sku" "text", "sku_promo" "text", "color_name" "text", "color_hex" "text", "size_value" "text", "capacity" "text", "calculated_price" numeric, "stock_quantity" integer, "is_active" boolean, "next_quantity_1" integer, "next_date_1" "date", "next_quantity_2" integer, "next_date_2" "date", "next_quantity_3" integer, "next_date_3" "date", "has_upcoming_restock" boolean)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT pv.id,
           pv.sku::TEXT,
           pv.sku_promo::TEXT,
           cv.name::TEXT,
           cv.hex_code::TEXT,
           vv.value::TEXT,
           pv.capacity_ml::TEXT,
           get_variant_price(pv.id, p_quantity),
           pv.stock_quantity,
           pv.is_active,
           CASE WHEN pv.next_date_1 > CURRENT_DATE THEN pv.next_quantity_1 ELSE NULL END,
           CASE WHEN pv.next_date_1 > CURRENT_DATE THEN pv.next_date_1     ELSE NULL END,
           CASE WHEN pv.next_date_2 > CURRENT_DATE THEN pv.next_quantity_2 ELSE NULL END,
           CASE WHEN pv.next_date_2 > CURRENT_DATE THEN pv.next_date_2     ELSE NULL END,
           CASE WHEN pv.next_date_3 > CURRENT_DATE THEN pv.next_quantity_3 ELSE NULL END,
           CASE WHEN pv.next_date_3 > CURRENT_DATE THEN pv.next_date_3     ELSE NULL END,
           COALESCE(pv.next_date_1 IS NOT NULL AND pv.next_date_1 > CURRENT_DATE, false)
    FROM product_variants pv
    LEFT JOIN color_variations cv ON pv.color_id = cv.id
    LEFT JOIN variation_values vv ON pv.size_id = vv.id
    WHERE pv.product_id = p_product_id
    ORDER BY cv.name, vv.value;
END;
$$;


ALTER FUNCTION "public"."get_product_variants_with_prices"("p_product_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_products_by_category_colors"("p_category_slug" "text" DEFAULT 'brindes_sicoob'::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0, "p_only_in_stock" boolean DEFAULT false) RETURNS TABLE("product_id" "uuid", "product_sku" "text", "product_name" "text", "variant_id" "uuid", "variant_sku" "text", "color_variation_id" "uuid", "color_variation_name" character varying, "color_group_id" "uuid", "color_group_name" character varying, "color_group_slug" character varying, "color_hex" character varying, "stock_quantity" integer, "price_1" numeric, "image_url" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
    SELECT 
        p.id,
        p.sku,
        p.name,
        pv.id,
        pv.sku,
        cv.id,
        cv.name,
        cg.id,
        cg.name,
        cg.slug,
        COALESCE(cv.hex_code, cg.hex_code),
        COALESCE(pv.stock_quantity, 0),
        pv.price_1,
        CASE 
            WHEN pv.images IS NOT NULL AND jsonb_array_length(pv.images) > 0 
            THEN pv.images->0->>'url'
            ELSE NULL
        END
    FROM products p
    INNER JOIN product_variants pv ON pv.product_id = p.id
    INNER JOIN color_variations cv ON cv.id = pv.color_id
    INNER JOIN color_groups cg ON cg.id = cv.group_id
    INNER JOIN category_colors cc ON cc.color_group_id = cg.id
    INNER JOIN categories cat ON cat.id = cc.category_id
    WHERE cat.slug = p_category_slug
      AND p.is_active = true
      AND pv.is_active = true
      AND cg.is_active = true
      AND cc.is_active = true
      AND (NOT p_only_in_stock OR COALESCE(pv.stock_quantity, 0) > 0)
    ORDER BY cc.display_order, cg.name, p.name, pv.sku
    LIMIT p_limit
    OFFSET p_offset;
$$;


ALTER FUNCTION "public"."get_products_by_category_colors"("p_category_slug" "text", "p_limit" integer, "p_offset" integer, "p_only_in_stock" boolean) OWNER TO "postgres";


