CREATE OR REPLACE FUNCTION "public"."get_profile_and_roles"("_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '6000ms'
    AS $$
DECLARE
  v_profile jsonb;
  v_roles   jsonb;
BEGIN
  -- Guard NULL: _user_id nulo não tem significado válido
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'get_profile_and_roles: _user_id cannot be null'
      USING ERRCODE = '22004';
  END IF;

  -- Guard cross-user: só o próprio usuário (ou dev) pode buscar
  IF _user_id IS DISTINCT FROM auth.uid()
     AND NOT public.has_role(auth.uid(), 'dev'::app_role)
  THEN
    RAISE EXCEPTION 'forbidden: cannot query profile of another user'
      USING ERRCODE = '42501';
  END IF;

  -- Busca profile em index covering (user_id)
  SELECT to_jsonb(p) INTO v_profile
  FROM public.profiles p
  WHERE p.user_id = _user_id
  LIMIT 1;

  -- Agrega roles (covering index user_id+role entra em ação aqui)
  SELECT jsonb_agg(ur.role ORDER BY ur.role) INTO v_roles
  FROM public.user_roles ur
  WHERE ur.user_id = _user_id;

  RETURN jsonb_build_object(
    'profile', v_profile,
    'roles',   COALESCE(v_roles, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_profile_and_roles"("_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_profile_and_roles"("_user_id" "uuid") IS 'RPC combinada: retorna {profile, roles} em 1 round-trip. SECURITY DEFINER — garante que vendedor não veja perfil alheio. statement_timeout=6s (< 7s do withTimeout no cliente). Caller: useProfileRoles.fetchUserData via supabase.rpc. Criada em 2026-07-14 para resolver hydration_timeout:profile+roles:5000ms. Migration: 20260714112808_fix_auth_hydration_rpc_and_rls.';



CREATE OR REPLACE FUNCTION "public"."get_promo_sales_90d_by_product"() RETURNS TABLE("product_id" "uuid", "total_quantity" bigint, "total_revenue" numeric, "order_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    oi.product_id,
    SUM(oi.quantity)::bigint          AS total_quantity,
    SUM(oi.subtotal)::numeric         AS total_revenue,
    COUNT(DISTINCT oi.order_id)::bigint AS order_count
  FROM order_items oi
  JOIN orders o ON o.id = oi.order_id
  WHERE
    o.created_at >= (NOW() - INTERVAL '90 days')
    -- Exclui pedidos cancelados/estornados (não contam como venda)
    AND o.status NOT IN ('cancelled', 'refunded', 'cancelado', 'estornado')
    AND oi.product_id IS NOT NULL
  GROUP BY oi.product_id
  -- Apenas produtos com ao menos 1 unidade vendida
  HAVING SUM(oi.quantity) > 0;
$$;


ALTER FUNCTION "public"."get_promo_sales_90d_by_product"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_promo_sales_90d_by_product"() IS 'Retorna total de unidades vendidas, receita e número de pedidos dos últimos 90 dias, agrupados por product_id. Pedidos cancelados/estornados são excluídos.';



CREATE OR REPLACE FUNCTION "public"."get_promo_sales_ranking"() RETURNS TABLE("product_id" "uuid", "total_qty" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    qi.product_id,
    COALESCE(SUM(qi.quantity), 0)::bigint AS total_qty
  FROM quote_items qi
  JOIN quotes q ON q.id = qi.quote_id
  WHERE qi.product_id IS NOT NULL
    AND q.status IN ('approved', 'pending', 'sent', 'viewed', 'accepted')
  GROUP BY qi.product_id
  ORDER BY total_qty DESC;
$$;


ALTER FUNCTION "public"."get_promo_sales_ranking"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_promo_sales_ranking"() IS 'Ranking de vendas (volume bruto). SOMENTE authenticated/service_role. ANTI-REGRESSAO: NAO conceder anon (vaza metrica de negocio). Bestseller anon usa get_catalog_bestseller_page.';



CREATE OR REPLACE FUNCTION "public"."get_public_schema_signatures"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(jsonb_object_agg(table_name, sig), '{}'::jsonb)
  FROM (
    SELECT 
      table_name,
      string_agg(column_name || ':' || data_type, ',' ORDER BY column_name) AS sig
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name NOT LIKE '_backup_%'
      AND table_name NOT LIKE 'pg_%'
    GROUP BY table_name
  ) t;
$$;


ALTER FUNCTION "public"."get_public_schema_signatures"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_public_schema_signatures"() IS 'Fase 4 2026-05-22: usada pelo gate de drift cross-banco. Retorna assinaturas das tabelas public.';



