    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT fi.product_id, COUNT(*)::bigint AS fav_count
  FROM public.favorite_items fi
  WHERE fi.added_at >= (now() - make_interval(days => GREATEST(_days, 1)))
