CREATE OR REPLACE FUNCTION "public"."guard_mcp_api_keys_writes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role TEXT := current_setting('role', true);
  v_actor UUID := auth.uid();
BEGIN
  IF v_role = 'service_role' OR current_user = 'service_role' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  PERFORM public.record_mcp_access_violation(
    v_actor,
    'unauthorized_direct_write',
    'db_trigger:mcp_api_keys',
    TG_OP,
    COALESCE(NEW.id, OLD.id),
    NULL,
    NULL,
    NULL,
    jsonb_build_object('current_user', current_user, 'role', v_role)
  );

  RAISE EXCEPTION 'Direct writes to mcp_api_keys are not allowed';
END;
$$;


ALTER FUNCTION "public"."guard_mcp_api_keys_writes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_role TEXT;
    v_full_name TEXT;
    v_department TEXT;
    v_preferences JSONB;
BEGIN
    -- Role: lê do metadata, fallback 'sales'
    v_role := COALESCE(
        NULLIF(TRIM(NEW.raw_user_meta_data->>'role'), ''),
        'sales'
    );
    
    -- Validação: só aceita roles válidos
    IF v_role NOT IN ('admin', 'sales', 'manager') THEN
        v_role := 'sales';
    END IF;
    
    -- Nome: metadata 'name' ou 'full_name', fallback email
    v_full_name := COALESCE(
        NULLIF(TRIM(NEW.raw_user_meta_data->>'name'), ''),
        NULLIF(TRIM(NEW.raw_user_meta_data->>'full_name'), ''),
        NEW.email
    );
    
    -- Departamento
    v_department := NULLIF(TRIM(NEW.raw_user_meta_data->>'department'), '');
    
    -- Preferences (ex: title)
    v_preferences := '{}'::jsonb;
    IF NEW.raw_user_meta_data->>'title' IS NOT NULL THEN
        v_preferences := jsonb_build_object('title', NEW.raw_user_meta_data->>'title');
    END IF;

    INSERT INTO public.profiles (
        id, email, full_name, role,
        department, is_active, preferences,
        created_at, updated_at
    ) VALUES (
        NEW.id,
        NEW.email,
        v_full_name,
        v_role,
        v_department,
        TRUE,
        v_preferences,
        NOW(),
        NOW()
    );
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


