CREATE OR REPLACE FUNCTION "public"."insert_cloudflare_video"("p_product_id" "uuid", "p_cloudflare_video_id" character varying, "p_video_type" character varying DEFAULT 'demo'::character varying, "p_title" character varying DEFAULT NULL::character varying, "p_duration_seconds" integer DEFAULT NULL::integer, "p_width_px" integer DEFAULT NULL::integer, "p_height_px" integer DEFAULT NULL::integer, "p_is_primary" boolean DEFAULT false, "p_supplier_code" character varying DEFAULT 'PROMO_BRINDES'::character varying) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_video_id    uuid;
  v_existing_id uuid;
  v_cf_sub CONSTANT text := 'customer-ksi0mrlcw6rwzezz';
BEGIN
  -- Verificar se já existe
  SELECT id INTO v_existing_id
  FROM product_videos
  WHERE product_id = p_product_id
    AND cloudflare_video_id = p_cloudflare_video_id;

  IF v_existing_id IS NOT NULL THEN
    UPDATE product_videos SET
      title            = COALESCE(p_title, title),
      duration_seconds = COALESCE(p_duration_seconds, duration_seconds),
      width_px         = COALESCE(p_width_px, width_px),
      height_px        = COALESCE(p_height_px, height_px),
      cloudflare_status = 'ready',
      updated_at       = now()
    WHERE id = v_existing_id;
    RETURN v_existing_id;
  END IF;

  IF p_is_primary THEN
    UPDATE product_videos SET is_primary = false
    WHERE product_id = p_product_id AND is_primary = true;
  END IF;

  INSERT INTO product_videos (
    product_id, cloudflare_video_id,
    url_stream, url_hls, url_thumbnail,
    video_type, title, duration_seconds, width_px, height_px,
    source_supplier, cloudflare_status, is_primary, display_order, is_active, uploaded_at
  ) VALUES (
    p_product_id,
    p_cloudflare_video_id,
    'https://iframe.cloudflarestream.com/' || p_cloudflare_video_id,
    'https://' || v_cf_sub || '.cloudflarestream.com/' || p_cloudflare_video_id || '/manifest/video.m3u8',
    'https://' || v_cf_sub || '.cloudflarestream.com/' || p_cloudflare_video_id || '/thumbnails/thumbnail.jpg',
    p_video_type, p_title, p_duration_seconds, p_width_px, p_height_px,
    p_supplier_code, 'ready', p_is_primary,
    COALESCE((SELECT MAX(display_order)+1 FROM product_videos WHERE product_id=p_product_id), 1),
    true, now()
  ) RETURNING id INTO v_video_id;

  RETURN v_video_id;
END;
$$;


ALTER FUNCTION "public"."insert_cloudflare_video"("p_product_id" "uuid", "p_cloudflare_video_id" character varying, "p_video_type" character varying, "p_title" character varying, "p_duration_seconds" integer, "p_width_px" integer, "p_height_px" integer, "p_is_primary" boolean, "p_supplier_code" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."insert_cloudflare_video"("p_product_id" "uuid", "p_cloudflare_video_id" character varying, "p_video_type" character varying, "p_title" character varying, "p_duration_seconds" integer, "p_width_px" integer, "p_height_px" integer, "p_is_primary" boolean, "p_supplier_code" character varying) IS '
Insere ou atualiza um vídeo no Cloudflare Stream na tabela product_videos.
Operação idempotente: se já existe registro com o mesmo (product_id, cf_video_id),
faz UPDATE dos metadados; caso contrário, faz INSERT.

PARÂMETROS:
  p_product_id          uuid    — ID do produto destino
  p_cloudflare_video_id varchar — UID do CF Stream (32 hex chars)
  p_video_type          varchar — Tipo do vídeo (default: ''demo'')
  p_title               varchar — Título do vídeo (opcional)
  p_duration_seconds    integer — Duração em segundos (opcional)
  p_width_px            integer — Largura em pixels (opcional)
  p_height_px           integer — Altura em pixels (opcional)
  p_is_primary          boolean — Marcar como vídeo principal (default: false)
  p_supplier_code       varchar — Código do fornecedor (default: ''PROMO_BRINDES'')

RETORNA: uuid — ID do registro criado ou atualizado em product_videos

LÓGICA:
  1. Busca registro existente por (product_id, cloudflare_video_id)
  2. Se encontrou → UPDATE título/duração/dimensões, cloudflare_status=''ready''
  3. Se não encontrou e p_is_primary=true → desmarca is_primary dos demais
  4. INSERT com URLs construídas internamente (subdomain correto)

SUBDOMAIN: customer-ksi0mrlcw6rwzezz (accountHash, ≠ accountId cd0f4eee)
  URLs geradas: url_stream (embed), url_hls, url_thumbnail

HISTÓRICO:
  Bug 2026-06-07: lia de cloudflare_stream_config (tabela inexistente → NULL URL).
  Fix 2026-06-07: subdomain hardcoded como CONSTANT v_cf_sub.
';



CREATE OR REPLACE FUNCTION "public"."insert_or_update_product"("p_supplier_id" "uuid", "p_supplier_reference" "text", "p_product_data" "jsonb", "p_organization_id" "uuid" DEFAULT '5db5aee1-064b-4ef4-9193-345dcd8274ea'::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_product_id UUID;
    v_existing_id UUID;
    v_sku TEXT;
    v_supplier_code TEXT;
BEGIN
    -- Obter código do fornecedor
    SELECT code INTO v_supplier_code FROM suppliers WHERE id = p_supplier_id;
    
    -- Gerar SKU padrão
    v_sku := v_supplier_code || '-' || p_supplier_reference;
    
    -- Verificar se produto já existe (por supplier_reference + supplier_id)
    SELECT p.id INTO v_existing_id
    FROM products p
    WHERE p.supplier_reference = p_supplier_reference
    AND p.supplier_id = p_supplier_id;
    
    IF v_existing_id IS NOT NULL THEN
        -- UPDATE
        UPDATE products SET
            name = COALESCE(p_product_data->>'name', name),
            description = COALESCE(p_product_data->>'description', description),
            short_description = COALESCE(p_product_data->>'short_description', short_description),
            height_cm = COALESCE((p_product_data->>'height_cm')::NUMERIC, height_cm),
            width_cm = COALESCE((p_product_data->>'width_cm')::NUMERIC, width_cm),
            length_cm = COALESCE((p_product_data->>'length_cm')::NUMERIC, length_cm),
            weight = COALESCE((p_product_data->>'weight')::NUMERIC, weight),
            weight_g = COALESCE((p_product_data->>'weight_g')::INTEGER, weight_g),
            box_height_cm = COALESCE((p_product_data->>'box_height_cm')::NUMERIC, box_height_cm),
            box_width_cm = COALESCE((p_product_data->>'box_width_cm')::NUMERIC, box_width_cm),
            box_length_cm = COALESCE((p_product_data->>'box_length_cm')::NUMERIC, box_length_cm),
            box_weight_kg = COALESCE((p_product_data->>'box_weight_kg')::NUMERIC, box_weight_kg),
            box_quantity = COALESCE((p_product_data->>'box_quantity')::INTEGER, box_quantity),
            suggested_price = COALESCE((p_product_data->>'suggested_price')::NUMERIC, suggested_price),
            ncm_code = COALESCE(p_product_data->>'ncm_code', ncm_code),
            primary_image_url = COALESCE(p_product_data->>'primary_image_url', primary_image_url),
            dimensions_display = COALESCE(p_product_data->>'dimensions_display', dimensions_display),
            is_active = COALESCE((p_product_data->>'is_active')::BOOLEAN, is_active),
            sync_status = 'synced',
            last_sync_at = NOW(),
            updated_at = NOW()
        WHERE id = v_existing_id;
        
        v_product_id := v_existing_id;
    ELSE
        -- INSERT
        INSERT INTO products (
            id,
            organization_id,
            supplier_id,
            supplier_reference,
            sku,
            name,
            description,
            short_description,
            height_cm,
            width_cm,
            length_cm,
            weight,
            weight_g,
            box_height_cm,
            box_width_cm,
            box_length_cm,
            box_weight_kg,
            box_quantity,
            suggested_price,
            ncm_code,
            primary_image_url,
            dimensions_display,
            is_active,
            sync_status,
            last_sync_at,
            created_at,
            updated_at
        ) VALUES (
            gen_random_uuid(),
            p_organization_id,
            p_supplier_id,
            p_supplier_reference,
            v_sku,
            p_product_data->>'name',
            p_product_data->>'description',
            p_product_data->>'short_description',
            (p_product_data->>'height_cm')::NUMERIC,
            (p_product_data->>'width_cm')::NUMERIC,
            (p_product_data->>'length_cm')::NUMERIC,
            (p_product_data->>'weight')::NUMERIC,
            (p_product_data->>'weight_g')::INTEGER,
            (p_product_data->>'box_height_cm')::NUMERIC,
            (p_product_data->>'box_width_cm')::NUMERIC,
            (p_product_data->>'box_length_cm')::NUMERIC,
            (p_product_data->>'box_weight_kg')::NUMERIC,
            (p_product_data->>'box_quantity')::INTEGER,
            (p_product_data->>'suggested_price')::NUMERIC,
            p_product_data->>'ncm_code',
            p_product_data->>'primary_image_url',
            p_product_data->>'dimensions_display',
            COALESCE((p_product_data->>'is_active')::BOOLEAN, true),
            'synced',
            NOW(),
            NOW(),
            NOW()
        )
        RETURNING id INTO v_product_id;
    END IF;
    
    RETURN v_product_id;
END;
$$;


ALTER FUNCTION "public"."insert_or_update_product"("p_supplier_id" "uuid", "p_supplier_reference" "text", "p_product_data" "jsonb", "p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."insert_or_update_product"("p_supplier_id" "uuid", "p_supplier_reference" "text", "p_product_data" "jsonb", "p_organization_id" "uuid") IS 'Insere ou atualiza produto a partir de dados normalizados';



CREATE OR REPLACE FUNCTION "public"."insert_supplier_product_raw"("p_supplier_id" "uuid", "p_supplier_reference" "text", "p_raw_data" "jsonb", "p_import_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_id           UUID;
    v_supplier_sku TEXT;
BEGIN
    -- Auto-extrair supplier_sku: raw_data.'Sku' > raw_data.'sku' > supplier_reference
    v_supplier_sku := COALESCE(
        NULLIF(p_raw_data->>'Sku', ''),
        NULLIF(p_raw_data->>'sku', ''),
        NULLIF(p_supplier_reference, '')
    );

    INSERT INTO supplier_products_raw (
        id, supplier_id, supplier_reference, supplier_sku, raw_data, import_batch_id,
        imported_at, created_at, updated_at)
    VALUES (
        gen_random_uuid(), p_supplier_id, p_supplier_reference, v_supplier_sku,
        p_raw_data, p_import_batch_id, NOW(), NOW(), NOW())
    ON CONFLICT (supplier_id, supplier_reference) DO UPDATE SET
        raw_data        = EXCLUDED.raw_data,
        supplier_sku    = EXCLUDED.supplier_sku,
        import_batch_id = EXCLUDED.import_batch_id,
        imported_at     = NOW(),
        status          = CASE
                            WHEN supplier_products_raw.content_hash IS DISTINCT FROM EXCLUDED.content_hash
                            THEN 'pending'::supplier_raw_status
                            ELSE supplier_products_raw.status
                          END,
        updated_at      = NOW()
    RETURNING id INTO v_id;
    RETURN v_id;
END $$;


ALTER FUNCTION "public"."insert_supplier_product_raw"("p_supplier_id" "uuid", "p_supplier_reference" "text", "p_raw_data" "jsonb", "p_import_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."insert_supplier_product_raw"("p_supplier_id" "uuid", "p_supplier_reference" "text", "p_raw_data" "jsonb", "p_import_batch_id" "uuid") IS 'Insere produto raw de qualquer fornecedor (com detecção de mudanças via hash)';



CREATE OR REPLACE FUNCTION "public"."insert_xbz_image_staging"("p_product_code" character varying, "p_variant_code" character varying, "p_item_id" integer, "p_image_url" "text", "p_color_name" character varying DEFAULT NULL::character varying) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_metadata JSONB;
    v_staging_id UUID;
BEGIN
    v_metadata := extract_xbz_image_metadata(p_image_url);
    
    INSERT INTO xbz_image_import_staging (
        xbz_product_code,
        xbz_variant_code,
        xbz_item_id,
        original_url,
        filename,
        color_name,
        image_type,
        gallery_suffix,
        status
    ) VALUES (
        p_product_code,
        p_variant_code,
        p_item_id,
        p_image_url,
        v_metadata->>'filename',
        COALESCE(p_color_name, v_metadata->>'color_name'),
        v_metadata->>'image_type',
        v_metadata->>'gallery_suffix',
        'pending'
    )
    ON CONFLICT (xbz_variant_code, original_url) DO UPDATE SET
        xbz_item_id = EXCLUDED.xbz_item_id,
        color_name = COALESCE(EXCLUDED.color_name, xbz_image_import_staging.color_name),
        status = 'pending'
    RETURNING id INTO v_staging_id;
    
    RETURN v_staging_id;
END;
$$;


ALTER FUNCTION "public"."insert_xbz_image_staging"("p_product_code" character varying, "p_variant_code" character varying, "p_item_id" integer, "p_image_url" "text", "p_color_name" character varying) OWNER TO "postgres";


