CREATE OR REPLACE FUNCTION "public"."log_price_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF OLD.cost_1 IS DISTINCT FROM NEW.cost_1 
           OR OLD.cost_2 IS DISTINCT FROM NEW.cost_2
           OR OLD.cost_3 IS DISTINCT FROM NEW.cost_3
           OR OLD.cost_4 IS DISTINCT FROM NEW.cost_4
           OR OLD.cost_5 IS DISTINCT FROM NEW.cost_5 THEN
            
            INSERT INTO price_change_history (
                variant_id,
                change_type,
                old_values,
                new_values,
                price_variation_percent,
                source,
                changed_by
            ) VALUES (
                NEW.variant_id,
                'cost_update',
                jsonb_build_object(
                    'cost_1', OLD.cost_1, 'cost_2', OLD.cost_2, 'cost_3', OLD.cost_3,
                    'cost_4', OLD.cost_4, 'cost_5', OLD.cost_5
                ),
                jsonb_build_object(
                    'cost_1', NEW.cost_1, 'cost_2', NEW.cost_2, 'cost_3', NEW.cost_3,
                    'cost_4', NEW.cost_4, 'cost_5', NEW.cost_5
                ),
                CASE WHEN OLD.cost_1 > 0 THEN ROUND(((NEW.cost_1 - OLD.cost_1) / OLD.cost_1) * 100, 2) ELSE 0 END,
                NEW.source,
                NEW.updated_by
            );
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_price_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_rls_denial"("p_table_name" "text", "p_operation" "text", "p_endpoint" "text" DEFAULT NULL::"text", "p_query_summary" "text" DEFAULT NULL::"text", "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_target_seller_id" "uuid" DEFAULT NULL::"uuid", "p_policy_hint" "text" DEFAULT NULL::"text", "p_error_code" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_email TEXT; v_role TEXT; v_id UUID;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  IF p_operation NOT IN ('SELECT','INSERT','UPDATE','DELETE') THEN
    RAISE EXCEPTION 'invalid_operation';
  END IF;
  SELECT email, role INTO v_email, v_role
  FROM public.profiles WHERE user_id = v_uid LIMIT 1;
  INSERT INTO public.rls_denial_log (
    user_id, user_email, user_role, table_name, operation,
    endpoint, query_summary, target_id, target_seller_id,
    policy_hint, error_code, error_message, user_agent
  ) VALUES (
    v_uid, v_email, v_role, p_table_name, p_operation,
    p_endpoint, p_query_summary, p_target_id, p_target_seller_id,
    p_policy_hint, p_error_code, p_error_message, p_user_agent
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


