CREATE OR REPLACE FUNCTION "public"."magazine_reorder_items_atomic"("p_magazine_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_ordered_item_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_owner UUID;
  v_status TEXT;
  v_updated_at TIMESTAMPTZ;
  v_total INTEGER;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'magazine_auth_required' USING ERRCODE = '42501'; END IF;
  IF p_ordered_item_ids IS NULL OR cardinality(p_ordered_item_ids) > 500 OR array_position(p_ordered_item_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'magazine_item_ids_invalid' USING ERRCODE = '22023';
  END IF;
  IF (SELECT COUNT(DISTINCT id) FROM unnest(p_ordered_item_ids) AS ids(id)) <> cardinality(p_ordered_item_ids) THEN
    RAISE EXCEPTION 'magazine_item_ids_duplicated' USING ERRCODE = '22023';
  END IF;

  SELECT owner_id, status::TEXT, updated_at INTO v_owner, v_status, v_updated_at
    FROM public.magazines WHERE id = p_magazine_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'magazine_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_owner <> v_actor AND NOT COALESCE(public.has_role(v_actor, 'admin'::public.app_role), FALSE) THEN
    RAISE EXCEPTION 'magazine_forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_status <> 'draft' THEN RAISE EXCEPTION 'magazine_not_editable' USING ERRCODE = '55000'; END IF;
  IF v_updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'magazine_edit_conflict' USING ERRCODE = '40001';
  END IF;

  SELECT COUNT(*) INTO v_total FROM public.magazine_items WHERE magazine_id = p_magazine_id;
  IF v_total <> cardinality(p_ordered_item_ids)
     OR EXISTS (
       SELECT 1 FROM unnest(p_ordered_item_ids) AS ids(id)
        WHERE NOT EXISTS (
          SELECT 1 FROM public.magazine_items mi
           WHERE mi.magazine_id = p_magazine_id AND mi.id = ids.id
        )
     ) THEN
    RAISE EXCEPTION 'magazine_reorder_requires_complete_item_set' USING ERRCODE = '22023';
  END IF;

  WITH desired AS (
    SELECT id, ordinality - 1 AS position
      FROM unnest(p_ordered_item_ids) WITH ORDINALITY AS ids(id, ordinality)
  )
  UPDATE public.magazine_items AS mi
     SET position = desired.position,
         updated_at = clock_timestamp()
    FROM desired
   WHERE mi.magazine_id = p_magazine_id AND mi.id = desired.id;

  UPDATE public.magazines SET updated_at = clock_timestamp() WHERE id = p_magazine_id
  RETURNING updated_at INTO v_updated_at;
  RETURN jsonb_build_object('reordered', v_total, 'updated_at', v_updated_at);
END;
$$;


ALTER FUNCTION "public"."magazine_reorder_items_atomic"("p_magazine_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_ordered_item_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."magazine_reorder_items_v2"("p_magazine_id" "uuid", "p_expected_edit_version" bigint, "p_ordered_item_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_mag public.magazines%ROWTYPE; v_total INT; v_current UUID[]; v_result public.magazines%ROWTYPE;
BEGIN
 v_mag:=public.magazine_lock_v2(p_magazine_id,p_expected_edit_version,FALSE); IF v_mag.status<>'draft' THEN RAISE EXCEPTION 'magazine_not_editable' USING ERRCODE='55000'; END IF;
 IF p_ordered_item_ids IS NULL OR cardinality(p_ordered_item_ids)>500 OR array_position(p_ordered_item_ids,NULL) IS NOT NULL OR (SELECT count(DISTINCT x) FROM unnest(p_ordered_item_ids)x)<>cardinality(p_ordered_item_ids) THEN RAISE EXCEPTION 'magazine_item_ids_invalid' USING ERRCODE='22023'; END IF;
 SELECT count(*),array_agg(id ORDER BY position,id) INTO v_total,v_current FROM public.magazine_items WHERE magazine_id=p_magazine_id;
 IF v_total<>cardinality(p_ordered_item_ids) OR EXISTS(SELECT 1 FROM unnest(p_ordered_item_ids)x(id) WHERE NOT EXISTS(SELECT 1 FROM public.magazine_items mi WHERE mi.magazine_id=p_magazine_id AND mi.id=x.id)) THEN RAISE EXCEPTION 'magazine_reorder_requires_complete_item_set' USING ERRCODE='22023'; END IF;
 IF v_current IS NOT DISTINCT FROM p_ordered_item_ids THEN RETURN jsonb_build_object('reordered',0,'edit_version',v_mag.edit_version,'updated_at',v_mag.updated_at); END IF;
 WITH shifted AS(SELECT id,max(position) OVER()+row_number() OVER(ORDER BY position,id)+1 pos FROM public.magazine_items WHERE magazine_id=p_magazine_id) UPDATE public.magazine_items mi SET position=s.pos FROM shifted s WHERE mi.id=s.id;
 WITH desired AS(SELECT id,ordinality-1 pos FROM unnest(p_ordered_item_ids) WITH ORDINALITY x(id,ordinality)) UPDATE public.magazine_items mi SET position=d.pos FROM desired d WHERE mi.magazine_id=p_magazine_id AND mi.id=d.id;
 UPDATE public.magazines SET edit_version=v_mag.edit_version+1 WHERE id=p_magazine_id RETURNING * INTO v_result;
 RETURN jsonb_build_object('reordered',v_total,'edit_version',v_result.edit_version,'updated_at',v_result.updated_at);
END $$;


