    _data->>'channel',
    _data->>'audience',
    _data->>'tone',
    _data->>'cta',
    _data->>'occasion',
    COALESCE(_data->>'status', 'draft'),
    COALESCE(_data->'metadata','{}'::jsonb)
  )
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;


