CREATE OR REPLACE FUNCTION "public"."normalize_unit"("p_value" numeric, "p_source_unit" character varying, "p_target_unit" character varying) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Retornar NULL se valor é NULL
    IF p_value IS NULL THEN
        RETURN NULL;
    END IF;
    
    -- Se unidades são iguais, retornar valor original
    IF LOWER(p_source_unit) = LOWER(p_target_unit) THEN
        RETURN p_value;
    END IF;
    
    -- CONVERSÕES DE PESO
    IF LOWER(p_source_unit) = 'kg' AND LOWER(p_target_unit) = 'g' THEN
        RETURN p_value * 1000;
    ELSIF LOWER(p_source_unit) = 'g' AND LOWER(p_target_unit) = 'kg' THEN
        RETURN p_value / 1000;
    ELSIF LOWER(p_source_unit) = 'kg' AND LOWER(p_target_unit) = 'mg' THEN
        RETURN p_value * 1000000;
    ELSIF LOWER(p_source_unit) = 'mg' AND LOWER(p_target_unit) = 'kg' THEN
        RETURN p_value / 1000000;
    ELSIF LOWER(p_source_unit) = 'g' AND LOWER(p_target_unit) = 'mg' THEN
        RETURN p_value * 1000;
    ELSIF LOWER(p_source_unit) = 'mg' AND LOWER(p_target_unit) = 'g' THEN
        RETURN p_value / 1000;
    
    -- CONVERSÕES DE COMPRIMENTO
    ELSIF LOWER(p_source_unit) = 'm' AND LOWER(p_target_unit) = 'cm' THEN
        RETURN p_value * 100;
    ELSIF LOWER(p_source_unit) = 'cm' AND LOWER(p_target_unit) = 'm' THEN
        RETURN p_value / 100;
    ELSIF LOWER(p_source_unit) = 'm' AND LOWER(p_target_unit) = 'mm' THEN
        RETURN p_value * 1000;
    ELSIF LOWER(p_source_unit) = 'mm' AND LOWER(p_target_unit) = 'm' THEN
        RETURN p_value / 1000;
    ELSIF LOWER(p_source_unit) = 'cm' AND LOWER(p_target_unit) = 'mm' THEN
        RETURN p_value * 10;
    ELSIF LOWER(p_source_unit) = 'mm' AND LOWER(p_target_unit) = 'cm' THEN
        RETURN p_value / 10;
    
    -- CONVERSÕES DE VOLUME
    ELSIF LOWER(p_source_unit) = 'l' AND LOWER(p_target_unit) = 'ml' THEN
        RETURN p_value * 1000;
    ELSIF LOWER(p_source_unit) = 'ml' AND LOWER(p_target_unit) = 'l' THEN
        RETURN p_value / 1000;
    
    -- Conversão não suportada
    ELSE
        RAISE WARNING 'Conversão não suportada: % → %', p_source_unit, p_target_unit;
        RETURN p_value;
    END IF;
    
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Erro em normalize_unit: %', SQLERRM;
    RETURN p_value;
END;
$$;


ALTER FUNCTION "public"."normalize_unit"("p_value" numeric, "p_source_unit" character varying, "p_target_unit" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_unit"("p_value" numeric, "p_source_unit" character varying, "p_target_unit" character varying) IS 'Converte valores entre unidades de medida (kg↔g, cm↔mm, l↔ml, etc).';



CREATE OR REPLACE FUNCTION "public"."notify_discount_approval_request"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE seller_name TEXT; quote_num TEXT; admin_user RECORD;
BEGIN
  IF TG_OP = 'INSERT' AND NEW.status = 'pending' THEN
    SELECT full_name INTO seller_name FROM public.profiles WHERE user_id = NEW.seller_id;
    SELECT quote_number INTO quote_num FROM public.quotes WHERE id = NEW.quote_id;
    FOR admin_user IN SELECT ur.user_id FROM public.user_roles ur WHERE ur.role = 'admin' LOOP
      INSERT INTO public.workspace_notifications (user_id, title, message, type, category, action_url, metadata)
      VALUES (admin_user.user_id, '⚠️ Desconto acima do limite',
        COALESCE(seller_name, 'Vendedor') || ' solicitou ' || NEW.requested_discount_percent || '% de desconto no orçamento ' || COALESCE(quote_num, '') || ' (limite: ' || NEW.max_allowed_percent || '%).',
        'warning', 'quotes',
        '/admin/usuarios?tab=discounts&request=' || NEW.id::text,
        jsonb_build_object('request_id', NEW.id, 'quote_id', NEW.quote_id, 'quote_number', quote_num, 'seller_id', NEW.seller_id, 'requested_pct', NEW.requested_discount_percent, 'max_pct', NEW.max_allowed_percent));
    END LOOP;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'pending' AND NEW.status IN ('approved', 'rejected') THEN
    SELECT quote_number INTO quote_num FROM public.quotes WHERE id = NEW.quote_id;
    IF NEW.status = 'approved' THEN
      INSERT INTO public.workspace_notifications (user_id, title, message, type, category, action_url, metadata)
      VALUES (NEW.seller_id, '✅ Desconto aprovado!',
        'Seu desconto de ' || NEW.requested_discount_percent || '% no orçamento ' || COALESCE(quote_num, '') || ' foi aprovado.',
        'success', 'quotes', '/orcamentos',
        jsonb_build_object('request_id', NEW.id, 'quote_id', NEW.quote_id, 'quote_number', quote_num));
    ELSE
      INSERT INTO public.workspace_notifications (user_id, title, message, type, category, action_url, metadata)
      VALUES (NEW.seller_id, '❌ Desconto recusado',
        'Seu desconto de ' || NEW.requested_discount_percent || '% no orçamento ' || COALESCE(quote_num, '') || ' foi recusado.' || COALESCE(' Motivo: ' || NEW.admin_notes, ''),
        'warning', 'quotes', '/orcamentos',
        jsonb_build_object('request_id', NEW.id, 'quote_id', NEW.quote_id, 'quote_number', quote_num));
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_discount_approval_request"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_hardening_regression"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _private_buckets int;
  _sensitive_realtime int;
  _pg_trgm_in_extensions boolean;
  _cleanup_job_active boolean;
  _failures text[] := ARRAY[]::text[];
  _score int := 0;
  _max int := 5;
  _admin record;
  _notified int := 0;
  _msg text;
BEGIN
  SELECT count(*) INTO _private_buckets
  FROM storage.buckets
  WHERE id IN ('personalization-images','product-videos','supplier-logos','component-media')
    AND public = false;
  IF _private_buckets = 4 THEN _score := _score + 1;
  ELSE _failures := _failures || format('Buckets privados: %s/4', _private_buckets); END IF;

  SELECT count(*) INTO _sensitive_realtime
  FROM pg_publication_tables
  WHERE pubname = 'supabase_realtime' AND schemaname = 'public'
    AND tablename IN ('discount_approval_requests','kit_variants','kit_comments');
  IF _sensitive_realtime = 0 THEN _score := _score + 1;
  ELSE _failures := _failures || format('Tabelas sensíveis em realtime: %s', _sensitive_realtime); END IF;

  SELECT EXISTS (SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace
    WHERE e.extname = 'pg_trgm' AND n.nspname = 'extensions') INTO _pg_trgm_in_extensions;
  IF _pg_trgm_in_extensions THEN _score := _score + 1;
  ELSE _failures := _failures || 'pg_trgm fora do schema extensions'; END IF;

  SELECT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'cleanup-security-logs-daily' AND active = true) INTO _cleanup_job_active;
  IF _cleanup_job_active THEN _score := _score + 1;
  ELSE _failures := _failures || 'Job cleanup-security-logs-daily inativo'; END IF;

  _score := _score + 1;

  IF _score >= _max THEN
    RETURN jsonb_build_object('ok', true, 'score', _score, 'max', _max, 'notified', 0);
  END IF;

  _msg := format('Saúde do hardening caiu para %s/%s. Falhas: %s. Acesse /admin/seguranca-acesso.',
    _score, _max, array_to_string(_failures, '; '));

  FOR _admin IN SELECT user_id FROM public.user_roles WHERE role = 'admin' LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.workspace_notifications
      WHERE user_id = _admin.user_id AND category = 'security'
        AND title = '⚠️ Regressão de hardening detectada'
        AND created_at > now() - interval '20 hours'
    ) THEN
      INSERT INTO public.workspace_notifications (user_id, title, message, type, category, action_url, metadata)
      VALUES (_admin.user_id, '⚠️ Regressão de hardening detectada', _msg, 'warning', 'security',
        '/admin/seguranca-acesso',
        jsonb_build_object('score', _score, 'max', _max, 'failures', _failures));
      _notified := _notified + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'score', _score, 'max', _max, 'failures', _failures, 'notified', _notified);
END;
$$;


ALTER FUNCTION "public"."notify_hardening_regression"() OWNER TO "postgres";


