CREATE OR REPLACE FUNCTION "public"."recalc_order_total"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE v_order_id uuid;
BEGIN
  v_order_id := COALESCE(NEW.order_id, OLD.order_id);

  UPDATE public.orders o
  SET subtotal = COALESCE((
        SELECT SUM(ROUND(oi.quantity * (oi.unit_price - COALESCE(oi.discount_amount,0) + COALESCE(oi.personalization_cost,0)),2))
        FROM public.order_items oi
        WHERE oi.order_id = v_order_id
      ),0),
      total = ROUND(
        COALESCE((
          SELECT SUM(ROUND(oi.quantity * (oi.unit_price - COALESCE(oi.discount_amount,0) + COALESCE(oi.personalization_cost,0)),2))
          FROM public.order_items oi
          WHERE oi.order_id = v_order_id
        ),0)
        - COALESCE(o.discount_amount,0)
        + COALESCE(o.shipping_cost,0)
        + COALESCE(o.tax_amount,0)
      ,2),
      updated_at = now()
  WHERE o.id = v_order_id;

  RETURN COALESCE(NEW, OLD);
END$$;


ALTER FUNCTION "public"."recalc_order_total"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recalc_order_total"() IS 'Refatorada 2026-05-22 (Wave 3.2.A): usa orders.total (consolidado, sem mais total_amount).';



CREATE OR REPLACE FUNCTION "public"."recalculate_sale_prices"("p_variant_id" "uuid" DEFAULT NULL::"uuid", "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count INT := 0;
    r RECORD;
BEGIN
    FOR r IN 
        SELECT 
            vsp.id AS sale_id,
            vsp.variant_id,
            vsp.default_markup_percent,
            vct.cost_1, vct.cost_2, vct.cost_3, vct.cost_4, vct.cost_5,
            vct.min_qty_1, vct.min_qty_2, vct.min_qty_3, vct.min_qty_4, vct.min_qty_5,
            vsp.is_price_1_manual, vsp.is_price_2_manual, vsp.is_price_3_manual, 
            vsp.is_price_4_manual, vsp.is_price_5_manual
        FROM variant_sale_prices vsp
        JOIN variant_cost_tiers vct ON vct.variant_id = vsp.variant_id AND vct.is_active = true
        WHERE (p_variant_id IS NULL OR vsp.variant_id = p_variant_id)
          AND (p_organization_id IS NULL OR vsp.organization_id = p_organization_id)
          AND vsp.is_active = true
    LOOP
        UPDATE variant_sale_prices
        SET 
            price_1 = CASE WHEN NOT r.is_price_1_manual THEN ROUND(r.cost_1 * (1 + r.default_markup_percent/100), 2) ELSE price_1 END,
            price_2 = CASE WHEN NOT r.is_price_2_manual AND r.cost_2 IS NOT NULL THEN ROUND(r.cost_2 * (1 + r.default_markup_percent/100), 2) ELSE price_2 END,
            price_3 = CASE WHEN NOT r.is_price_3_manual AND r.cost_3 IS NOT NULL THEN ROUND(r.cost_3 * (1 + r.default_markup_percent/100), 2) ELSE price_3 END,
            price_4 = CASE WHEN NOT r.is_price_4_manual AND r.cost_4 IS NOT NULL THEN ROUND(r.cost_4 * (1 + r.default_markup_percent/100), 2) ELSE price_4 END,
            price_5 = CASE WHEN NOT r.is_price_5_manual AND r.cost_5 IS NOT NULL THEN ROUND(r.cost_5 * (1 + r.default_markup_percent/100), 2) ELSE price_5 END,
            min_qty_1 = r.min_qty_1,
            min_qty_2 = r.min_qty_2,
            min_qty_3 = r.min_qty_3,
            min_qty_4 = r.min_qty_4,
            min_qty_5 = r.min_qty_5,
            last_calculated_at = NOW(),
            updated_at = NOW()
        WHERE id = r.sale_id;
        
        v_count := v_count + 1;
    END LOOP;
    
    RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."recalculate_sale_prices"("p_variant_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_cf_image_status"("p_cf_id" "text", "p_exists" boolean) RETURNS TABLE("action" "text", "rows_affected" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$ DECLARE v_now timestamptz := now(); v_rows int := 0; BEGIN IF p_exists THEN UPDATE public.product_images SET cf_sync_status = 'verified', cf_verified_at = COALESCE(cf_verified_at, v_now), cf_last_checked_at = v_now, cf_last_error = NULL, last_modified_source = 'edge_function', updated_at = v_now WHERE cloudflare_image_id = p_cf_id AND deleted_at IS NULL AND cf_sync_status <> 'verified'; GET DIAGNOSTICS v_rows = ROW_COUNT; RETURN QUERY SELECT 'mark_verified'::text, v_rows; ELSE UPDATE public.product_images SET cf_sync_status = 'missing', cf_check_attempts = cf_check_attempts + 1, cf_last_checked_at = v_now, cf_last_error = COALESCE(cf_last_error, '') || ' | ' || v_now::text || ' recon: not_found_in_cloudflare', last_modified_source = 'edge_function', updated_at = v_now WHERE cloudflare_image_id = p_cf_id AND deleted_at IS NULL AND cf_sync_status = 'verified'; GET DIAGNOSTICS v_rows = ROW_COUNT; RETURN QUERY SELECT 'mark_missing'::text, v_rows; END IF; END; $$;


