CREATE OR REPLACE FUNCTION "public"."record_public_token_failure"("_resource_type" "text", "_resource_id" "text", "_attempted_token" "text", "_ip" "text", "_ua" "text", "_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _recent_failures int;
BEGIN
  INSERT INTO public.public_token_failures (
    resource_type, resource_id, attempted_token, ip_address, user_agent, reason
  ) VALUES (
    _resource_type, _resource_id, _attempted_token, _ip, _ua, _reason
  );

  IF _resource_id IS NULL THEN
    RETURN;
  END IF;

  SELECT count(*) INTO _recent_failures
  FROM public.public_token_failures
  WHERE resource_type = _resource_type
    AND resource_id = _resource_id
    AND created_at > now() - interval '1 hour';

  IF _recent_failures >= 5 THEN
    IF _resource_type = 'quote' THEN
      UPDATE public.quote_approval_tokens
      SET status = 'expired', updated_at = now()
      WHERE quote_id = _resource_id AND status = 'active';
    ELSIF _resource_type = 'kit' THEN
      UPDATE public.kit_share_tokens
      SET status = 'expired', updated_at = now()
      WHERE kit_id::text = _resource_id AND status = 'active';
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION "public"."record_public_token_failure"("_resource_type" "text", "_resource_id" "text", "_attempted_token" "text", "_ip" "text", "_ua" "text", "_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_public_token_failure"("_resource_type" "text", "_resource_id" "text", "_attempted_token" "text", "_ip" "text", "_ua" "text", "_reason" "text") IS 'Migrada do Lovable em 2026-05-22 (Lote F). Anti-bruteforce: registra falha de token público e auto-expira após 5 falhas em 1h.';



CREATE OR REPLACE FUNCTION "public"."record_schema_drift_result"("p_result" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_log_id        uuid;
  v_has_drift     boolean;
  v_only_oficial  text[];
  v_only_lovable  text[];
  v_schema_diff   jsonb;
  v_diff_count    integer;
  v_notify_count  integer := 0;
BEGIN
  v_has_drift    := COALESCE((p_result->>'has_drift')::boolean, false);
  v_only_oficial := COALESCE(ARRAY(SELECT jsonb_array_elements_text(p_result->'only_oficial')), ARRAY[]::text[]);
  v_only_lovable := COALESCE(ARRAY(SELECT jsonb_array_elements_text(p_result->'only_lovable')), ARRAY[]::text[]);
  v_schema_diff  := COALESCE(p_result->'schema_diff', '{}'::jsonb);
  v_diff_count   := (SELECT COUNT(*) FROM jsonb_object_keys(v_schema_diff));

  INSERT INTO public.schema_drift_log (
    has_drift, tables_oficial, tables_lovable,
    only_oficial, only_lovable, schema_diff,
    error_message
  ) VALUES (
    v_has_drift,
    COALESCE((p_result->>'tables_oficial')::integer, 0),
    COALESCE((p_result->>'tables_lovable')::integer, 0),
    v_only_oficial,
    v_only_lovable,
    v_schema_diff,
    NULLIF(p_result->>'error_message', '')
  )
  RETURNING id INTO v_log_id;

  IF v_has_drift THEN
    INSERT INTO public.workspace_notifications (
      user_id, title, message, type, category, metadata
    )
    SELECT 
      ur.user_id,
      'Schema drift detectado',
      format('Schema do Lovable e do Oficial divergem. only_oficial: %s; only_lovable: %s; tables com diff: %s',
        COALESCE(array_length(v_only_oficial, 1), 0),
        COALESCE(array_length(v_only_lovable, 1), 0),
        v_diff_count
      ),
      'warning',
      'system',
      jsonb_build_object(
        'log_id', v_log_id,
        'source', 'schema-drift-check',
        'only_oficial', v_only_oficial,
        'only_lovable', v_only_lovable,
        'tables_with_drift', (SELECT array_agg(k) FROM jsonb_object_keys(v_schema_diff) k)
      )
    FROM public.user_roles ur
    WHERE ur.role = 'admin';

    GET DIAGNOSTICS v_notify_count = ROW_COUNT;

    UPDATE public.schema_drift_log
    SET notification_sent = (v_notify_count > 0)
    WHERE id = v_log_id;
  END IF;

  RETURN v_log_id;
END;
$$;


ALTER FUNCTION "public"."record_schema_drift_result"("p_result" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_schema_drift_result"("p_result" "jsonb") IS 'Fase 4 2026-05-22: invocada pela edge function schema-drift-check. Grava log e notifica admins.';



CREATE OR REPLACE FUNCTION "public"."refresh_all_materialized_views"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'analytics'
    AS $$
BEGIN
  -- MVs com índice único → CONCURRENTLY (não bloqueia leituras)
  REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.mv_product_cards;
  REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.mv_product_compositions;
  REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.mv_material_group_stats;
  REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.mv_media_health;
  -- MVs de Intelligence: velocity PRIMEIRO (product_intelligence depende dela)
  REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.mv_stock_velocity;
  REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.mv_product_intelligence;
  -- MV sem índice único → refresh normal
  REFRESH MATERIALIZED VIEW analytics.categories_tree_visual;
  RAISE LOG '[refresh_all_materialized_views] Concluído (7 MVs) em %', clock_timestamp();
END;
$$;


