CREATE OR REPLACE FUNCTION "public"."repair_ownership_orphans"("_report_id" "uuid" DEFAULT NULL::"uuid", "_dry_run" boolean DEFAULT true, "_triggered_by_label" "text" DEFAULT 'manual_admin'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_report record;
  v_detail jsonb;
  v_table text;
  v_col text;
  v_null_count bigint;
  v_orphan_count bigint;
  v_action text;
  v_rows int;
  v_results jsonb := '[]'::jsonb;
  v_total_deleted int := 0;
  v_total_deactivated int := 0;
  v_total_manual int := 0;
  v_safe_delete text[] := ARRAY[
    'workspace_notifications', 'rls_denial_log',
    'mcp_audit_log', 'mcp_keys_audit_log',
    'role_migration_audit', 'login_attempts'
  ];
  v_has_active boolean;
  v_has_is_active boolean;
  v_has_status boolean;
BEGIN
  IF v_caller IS NULL OR NOT (
    has_role(v_caller, 'admin'::app_role) OR has_role(v_caller, 'dev'::app_role)
  ) THEN
    RAISE EXCEPTION 'repair_ownership_orphans: acesso negado';
  END IF;

  IF _report_id IS NULL THEN
    SELECT * INTO v_report
    FROM public.ownership_audit_reports
    ORDER BY generated_at DESC LIMIT 1;
  ELSE
    SELECT * INTO v_report
    FROM public.ownership_audit_reports WHERE id = _report_id;
  END IF;

  IF v_report.id IS NULL THEN
    RAISE EXCEPTION 'repair_ownership_orphans: nenhum relatório encontrado';
  END IF;

  FOR v_detail IN SELECT * FROM jsonb_array_elements(v_report.details)
  LOOP
    v_table := v_detail->>'table';
    v_col := v_detail->>'owner_column';
    v_null_count := COALESCE((v_detail->>'null_owner_count')::bigint, 0);
    v_orphan_count := COALESCE((v_detail->>'missing_user_count')::bigint, 0);

    SELECT EXISTS(SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name=v_table AND column_name='active')
      INTO v_has_active;
    SELECT EXISTS(SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name=v_table AND column_name='is_active')
      INTO v_has_is_active;
    SELECT EXISTS(SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name=v_table AND column_name='status')
      INTO v_has_status;

    IF v_null_count > 0 THEN
      v_action := 'manual_review';
      v_rows := 0;

      IF v_table = ANY(v_safe_delete) THEN
        v_action := 'deleted';
        IF NOT _dry_run THEN
          EXECUTE format('DELETE FROM public.%I WHERE %I IS NULL', v_table, v_col);
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_null_count::int;
        END IF;
        v_total_deleted := v_total_deleted + v_rows;
      ELSIF v_has_is_active THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format('UPDATE public.%I SET is_active=false WHERE %I IS NULL AND is_active=true', v_table, v_col);
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_null_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSIF v_has_active THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format('UPDATE public.%I SET active=false WHERE %I IS NULL AND active=true', v_table, v_col);
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_null_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSIF v_has_status THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format(
            'UPDATE public.%I SET status=''inactive'' WHERE %I IS NULL AND status<>''inactive''',
            v_table, v_col
          );
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_null_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSE
        v_rows := v_null_count::int;
        v_total_manual := v_total_manual + v_rows;
      END IF;

      INSERT INTO public.ownership_repair_logs(
        report_id, table_name, owner_column, issue_type, action,
        rows_affected, dry_run, triggered_by, triggered_by_label,
        notes
      ) VALUES (
        v_report.id, v_table, v_col, 'null_owner', v_action,
        v_rows, _dry_run, v_caller, _triggered_by_label,
        CASE WHEN v_action='manual_review'
          THEN 'Sem coluna active/is_active/status; tabela não está na allowlist de exclusão segura'
          ELSE NULL END
      );

      v_results := v_results || jsonb_build_object(
        'table', v_table, 'owner_column', v_col,
        'issue', 'null_owner', 'action', v_action,
        'rows_affected', v_rows, 'dry_run', _dry_run
      );
    END IF;

    IF v_orphan_count > 0 THEN
      v_action := 'manual_review';
      v_rows := 0;

      IF v_table = ANY(v_safe_delete) THEN
        v_action := 'deleted';
        IF NOT _dry_run THEN
          EXECUTE format(
            'DELETE FROM public.%I t WHERE t.%I IS NOT NULL
              AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = t.%I::uuid)',
            v_table, v_col, v_col
          );
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_orphan_count::int;
        END IF;
        v_total_deleted := v_total_deleted + v_rows;
      ELSIF v_has_is_active THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format(
            'UPDATE public.%I t SET is_active=false WHERE t.%I IS NOT NULL AND t.is_active=true
              AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = t.%I::uuid)',
            v_table, v_col, v_col
          );
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_orphan_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSIF v_has_active THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format(
            'UPDATE public.%I t SET active=false WHERE t.%I IS NOT NULL AND t.active=true
              AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = t.%I::uuid)',
            v_table, v_col, v_col
          );
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_orphan_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSIF v_has_status THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format(
            'UPDATE public.%I t SET status=''inactive'' WHERE t.%I IS NOT NULL AND t.status<>''inactive''
              AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = t.%I::uuid)',
            v_table, v_col, v_col
          );
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_orphan_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSE
        v_rows := v_orphan_count::int;
        v_total_manual := v_total_manual + v_rows;
      END IF;

      INSERT INTO public.ownership_repair_logs(
        report_id, table_name, owner_column, issue_type, action,
        rows_affected, dry_run, triggered_by, triggered_by_label,
        notes
      ) VALUES (
        v_report.id, v_table, v_col, 'missing_user', v_action,
        v_rows, _dry_run, v_caller, _triggered_by_label,
        CASE WHEN v_action='manual_review'
          THEN 'Sem coluna active/is_active/status; reparo automático inseguro — revisar manualmente'
          ELSE NULL END
      );

      v_results := v_results || jsonb_build_object(
        'table', v_table, 'owner_column', v_col,
        'issue', 'missing_user', 'action', v_action,
        'rows_affected', v_rows, 'dry_run', _dry_run
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'report_id', v_report.id,
    'dry_run', _dry_run,
    'totals', jsonb_build_object(
      'deleted', v_total_deleted,
      'deactivated', v_total_deactivated,
      'manual_review', v_total_manual
    ),
    'actions', v_results
  );
END;
$$;


ALTER FUNCTION "public"."repair_ownership_orphans"("_report_id" "uuid", "_dry_run" boolean, "_triggered_by_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reprocess_all_automations"("p_batch_size" integer DEFAULT 100, "p_supplier_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("processed" integer, "tags_linked" integer, "properties_linked" integer, "eco_marked" integer, "feminine_marked" integer, "dates_linked" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_product RECORD;
    v_processed INTEGER := 0;
    v_tags INTEGER := 0;
    v_properties INTEGER := 0;
    v_eco INTEGER := 0;
    v_feminine INTEGER := 0;
    v_dates INTEGER := 0;
    v_temp INTEGER;
    v_temp_bool BOOLEAN;
BEGIN
    -- Loop pelos produtos
    FOR v_product IN (
        SELECT p.id, p.supplier_id
        FROM products p
        WHERE (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
        ORDER BY p.created_at DESC
        LIMIT p_batch_size
    )
    LOOP
        -- Tags
        v_temp := fn_auto_link_tags(v_product.id, v_product.supplier_id);
        v_tags := v_tags + v_temp;
        
        -- Properties
        v_temp := fn_auto_link_properties(v_product.id, v_product.supplier_id);
        v_properties := v_properties + v_temp;
        
        -- ECO
        v_temp_bool := fn_auto_link_eco(v_product.id);
        IF v_temp_bool THEN v_eco := v_eco + 1; END IF;
        
        -- Feminino
        v_temp_bool := fn_auto_link_feminino(v_product.id);
        IF v_temp_bool THEN v_feminine := v_feminine + 1; END IF;
        
        -- Datas
        v_temp := fn_auto_link_commemorative_dates(v_product.id);
        v_dates := v_dates + v_temp;
        
        v_processed := v_processed + 1;
    END LOOP;
    
    processed := v_processed;
    tags_linked := v_tags;
    properties_linked := v_properties;
    eco_marked := v_eco;
    feminine_marked := v_feminine;
    dates_linked := v_dates;
    
    RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."reprocess_all_automations"("p_batch_size" integer, "p_supplier_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reprocess_all_automations"("p_batch_size" integer, "p_supplier_id" "uuid") IS 'Reprocessa todas as automações para produtos existentes. v1.0 - 30/01/2026';



CREATE OR REPLACE FUNCTION "public"."reprocess_all_products"("p_batch_size" integer DEFAULT 100, "p_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_force_reclassify" boolean DEFAULT false) RETURNS TABLE("processed" integer, "classified" integer, "materials_linked" integer, "prices_calculated" integer, "errors" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_product RECORD;
    v_result JSONB;
    v_materials INTEGER;
    v_price NUMERIC;
    v_processed INTEGER := 0;
    v_classified INTEGER := 0;
    v_materials_total INTEGER := 0;
    v_prices_total INTEGER := 0;
    v_errors INTEGER := 0;
BEGIN
    FOR v_product IN (
        SELECT p.id, p.name, p.category_id, p.supplier_id
        FROM products p
        WHERE (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
          AND (p_force_reclassify OR p.category_id IS NULL)
        ORDER BY p.created_at DESC
        LIMIT p_batch_size
    )
    LOOP
        BEGIN
            -- 1. Classificar (CORRIGIDO: ordem (name, id) + GRAVA o category_id)
            IF v_product.category_id IS NULL OR p_force_reclassify THEN
                v_result := fn_master_classify_product(v_product.name, v_product.id);
                IF v_result->>'category_id' IS NOT NULL THEN
                    UPDATE products
                       SET category_id = (v_result->>'category_id')::uuid
                     WHERE id = v_product.id;
                    v_classified := v_classified + 1;
                END IF;
            END IF;

            -- 2. Vincular materiais (path de derivação do batch)
            v_materials := fn_link_product_materials(v_product.id, v_product.supplier_id);
            v_materials_total := v_materials_total + v_materials;

            -- 3. Calcular preço
            v_price := fn_calculate_sale_price(v_product.id);
            IF v_price IS NOT NULL THEN
                v_prices_total := v_prices_total + 1;
            END IF;

            v_processed := v_processed + 1;

        EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors + 1;
            RAISE NOTICE 'Erro processando %: %', v_product.id, SQLERRM;
        END;
    END LOOP;

    processed := v_processed;
    classified := v_classified;
    materials_linked := v_materials_total;
    prices_calculated := v_prices_total;
    errors := v_errors;

    RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."reprocess_all_products"("p_batch_size" integer, "p_supplier_id" "uuid", "p_force_reclassify" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reprocess_all_products"("p_batch_size" integer, "p_supplier_id" "uuid", "p_force_reclassify" boolean) IS 'Reprocessa produtos existentes aplicando classificação, materiais e preços. v1.0 - 30/01/2026';



CREATE OR REPLACE FUNCTION "public"."reprocess_product_materials"("p_batch_size" integer DEFAULT 100, "p_supplier_id" "uuid" DEFAULT 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'::"uuid") RETURNS TABLE("processed" integer, "materials_linked" integer, "products_with_materials" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_product RECORD;
    v_materials INTEGER;
    v_processed INTEGER := 0;
    v_linked INTEGER := 0;
BEGIN
    -- Loop pelos produtos que ainda não têm materiais
    FOR v_product IN (
        SELECT p.id, p.supplier_id
        FROM products p
        LEFT JOIN product_materials pm ON pm.product_id = p.id
        WHERE p.supplier_id = p_supplier_id
          AND pm.id IS NULL  -- Apenas produtos SEM materiais
        ORDER BY p.created_at DESC
        LIMIT p_batch_size
    )
    LOOP
        v_materials := fn_link_product_materials(v_product.id, v_product.supplier_id);
        v_linked := v_linked + v_materials;
        v_processed := v_processed + 1;
    END LOOP;
    
    -- Contar produtos com materiais
    SELECT COUNT(DISTINCT product_id)
    INTO products_with_materials
    FROM product_materials;
    
    processed := v_processed;
    materials_linked := v_linked;
    
    RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."reprocess_product_materials"("p_batch_size" integer, "p_supplier_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reprocess_product_materials"("p_batch_size" integer, "p_supplier_id" "uuid") IS 'Reprocessa apenas materiais para produtos que ainda não têm. v1.0 - 30/01/2026';



CREATE TABLE IF NOT EXISTS "public"."discount_approval_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "quote_id" "uuid" NOT NULL,
    "seller_id" "uuid" NOT NULL,
    "requested_discount_percent" numeric(5,2) NOT NULL,
    "max_allowed_percent" numeric(5,2) NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "admin_id" "uuid",
    "admin_notes" "text",
    "seller_notes" "text",
    "responded_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "valid_until" timestamp with time zone,
    "quote_snapshot_hash" "text",
    CONSTRAINT "dar_valid_until_required_when_approved" CHECK ((("status" <> 'approved'::"text") OR ("valid_until" IS NOT NULL))),
    CONSTRAINT "discount_approval_requests_max_allowed_percent_check" CHECK ((("max_allowed_percent" >= (0)::numeric) AND ("max_allowed_percent" <= (100)::numeric))),
    CONSTRAINT "discount_approval_requests_requested_discount_percent_check" CHECK ((("requested_discount_percent" >= (0)::numeric) AND ("requested_discount_percent" <= (100)::numeric))),
    CONSTRAINT "discount_approval_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'expired'::"text"])))
);

ALTER TABLE ONLY "public"."discount_approval_requests" REPLICA IDENTITY FULL;


ALTER TABLE "public"."discount_approval_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."discount_approval_requests" IS 'Workflow de aprovação de desconto acima do limite. Vendedor solicita, supervisor+ aprova/rejeita. Schema oficial extraído de useDiscountApproval.ts.';



COMMENT ON CONSTRAINT "dar_valid_until_required_when_approved" ON "public"."discount_approval_requests" IS 'Garante que aprovações sempre têm vencimento explícito. O trigger fn_quotes_validate_discount verifica valid_until > now() (ou IS NULL como retrocompat para registros legados). O hook respondToApproval define valid_until = now() + 30 days ao aprovar.';



CREATE OR REPLACE FUNCTION "public"."request_discount_approval_transactional"("_quote_id" "uuid", "_seller_notes" "text" DEFAULT NULL::"text") RETURNS "public"."discount_approval_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _responsible_id uuid;
  _q public.quotes;
  _max_allowed numeric;
  _snapshot text;
  _existing public.discount_approval_requests;
  _result public.discount_approval_requests;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória.' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _q FROM public.quotes WHERE id = _quote_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Orçamento não encontrado.' USING ERRCODE = 'P0002';
  END IF;
  IF _q.seller_id IS DISTINCT FROM _uid AND _q.created_by IS DISTINCT FROM _uid THEN
    RAISE EXCEPTION 'Somente o vendedor responsável ou criador pode solicitar aprovação.'
      USING ERRCODE = '42501';
  END IF;
  IF _q.status NOT IN ('draft', 'pending', 'pending_approval') THEN
    RAISE EXCEPTION 'Status do orçamento não permite solicitar aprovação: %', _q.status
      USING ERRCODE = '23514';
  END IF;

  _responsible_id := COALESCE(_q.seller_id, _q.created_by);
  IF _responsible_id IS NULL THEN
    RAISE EXCEPTION 'Orçamento sem vendedor responsável.' USING ERRCODE = '23514';
  END IF;
  SELECT max_discount_percent INTO _max_allowed
  FROM public.seller_discount_limits WHERE user_id = _responsible_id;
  IF _max_allowed IS NULL THEN
    RAISE EXCEPTION 'Vendedor responsável sem limite de desconto cadastrado.'
      USING ERRCODE = '23514';
  END IF;
  IF COALESCE(_q.real_discount_percent, 0) <= _max_allowed THEN
    RAISE EXCEPTION 'O desconto real não excede a alçada do vendedor responsável.'
      USING ERRCODE = '23514';
  END IF;

  _snapshot := public.compute_quote_snapshot_hash(_quote_id);

  SELECT * INTO _existing
  FROM public.discount_approval_requests dar
  WHERE dar.quote_id = _quote_id
    AND dar.status = 'approved'
    AND (dar.valid_until IS NULL OR dar.valid_until > now())
    AND dar.requested_discount_percent >= _q.real_discount_percent
    AND dar.quote_snapshot_hash = _snapshot
  ORDER BY dar.responded_at DESC NULLS LAST, dar.created_at DESC
  LIMIT 1;

  IF FOUND THEN
    UPDATE public.quotes SET status = 'pending'
    WHERE id = _quote_id AND status <> 'pending';
    _result := _existing;
  ELSE
    SELECT * INTO _existing
    FROM public.discount_approval_requests dar
    WHERE dar.quote_id = _quote_id AND dar.status = 'pending'
    ORDER BY dar.created_at DESC LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      IF _existing.quote_snapshot_hash IS DISTINCT FROM _snapshot
         OR _existing.requested_discount_percent < _q.real_discount_percent
         OR _existing.seller_id IS DISTINCT FROM _responsible_id THEN
        RAISE EXCEPTION 'Já existe solicitação pendente para outro snapshot/percentual/vendedor.'
          USING ERRCODE = '23505';
      END IF;
      UPDATE public.quotes SET status = 'pending_approval'
      WHERE id = _quote_id AND status <> 'pending_approval';
      _result := _existing;
    ELSE
      INSERT INTO public.discount_approval_requests (
        quote_id, seller_id, requested_discount_percent, max_allowed_percent,
        status, seller_notes, quote_snapshot_hash
      ) VALUES (
        _quote_id, _responsible_id, _q.real_discount_percent, _max_allowed,
        'pending', NULLIF(btrim(_seller_notes), ''), _snapshot
      ) RETURNING * INTO _result;

      UPDATE public.quotes SET status = 'pending_approval' WHERE id = _quote_id;

      INSERT INTO public.quote_history (
        quote_id, user_id, action, description, field_changed, new_value, metadata
      ) VALUES (
        _quote_id, _uid, 'discount_approval_requested',
        format('Solicitação de desconto real %s%% (limite %s%%)',
          _q.real_discount_percent, _max_allowed),
        'discount', _q.real_discount_percent::text || '%',
        jsonb_build_object(
          'request_id', _result.id,
          'seller_id', _responsible_id,
          'requested_by', _uid,
          'seller_notes', NULLIF(btrim(_seller_notes), ''),
          'apparent_discount_percent', _q.discount_percent,
          'real_discount_percent', _q.real_discount_percent,
          'negotiation_markup_percent', COALESCE(_q.negotiation_markup_percent, 0),
          'max_allowed_percent', _max_allowed,
          'quote_snapshot_hash', _snapshot
        )
      );
    END IF;
  END IF;

  IF COALESCE(_q.negotiation_markup_percent, 0) > 0 THEN
    INSERT INTO public.admin_audit_log (
      user_id, action, resource_type, resource_id, request_id, source, status, details
    )
    SELECT
      _uid,
      'quote_negotiation_markup_applied',
      'quote',
      _quote_id::text,
      _result.id::text,
      'request_discount_approval_transactional',
      'success',
      jsonb_build_object(
        'approval_request_id', _result.id,
        'seller_id', _responsible_id,
        'requested_by', _uid,
        'negotiation_markup_percent', _q.negotiation_markup_percent,
        'apparent_discount_percent', _q.discount_percent,
        'real_discount_percent', _q.real_discount_percent,
        'max_allowed_percent', _max_allowed,
        'context', 'discount_approval_request'
      )
    WHERE NOT EXISTS (
      SELECT 1 FROM public.admin_audit_log aal
      WHERE aal.action = 'quote_negotiation_markup_applied'
        AND aal.resource_type = 'quote'
        AND aal.resource_id = _quote_id::text
        AND aal.details->>'context' = 'discount_approval_request'
        AND (
          aal.request_id = _result.id::text
          OR aal.details->>'approval_request_id' = _result.id::text
        )
    );
  END IF;

  RETURN _result;
END;
$$;


ALTER FUNCTION "public"."request_discount_approval_transactional"("_quote_id" "uuid", "_seller_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_step_up_challenge"("_action" "public"."step_up_action", "_target_ref" "text" DEFAULT NULL::"text", "_ip" "inet" DEFAULT NULL::"inet", "_user_agent" "text" DEFAULT NULL::"text") RETURNS TABLE("challenge_id" "uuid", "otp_plain" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid UUID := auth.uid();
  _otp TEXT;
  _otp_h TEXT;
  _cid UUID;
  _exp TIMESTAMPTZ;
  _recent_count INT;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'unauthorized: no session';
  END IF;

  IF NOT public.is_dev(_uid) THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, ip_address, user_agent)
    VALUES (_uid, _action, _target_ref, 'unauthorized', _ip, _user_agent);
    RAISE EXCEPTION 'forbidden: dev role required';
  END IF;

  SELECT count(*) INTO _recent_count
  FROM public.step_up_challenges
  WHERE user_id = _uid AND created_at > (now() - interval '1 hour');

  IF _recent_count >= 5 THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, ip_address, user_agent)
    VALUES (_uid, _action, _target_ref, 'rate_limited', _ip, _user_agent);
    RAISE EXCEPTION 'rate_limited: too many step-up requests';
  END IF;

  _otp := lpad((floor(random() * 1000000))::int::text, 6, '0');
  _otp_h := encode(digest(_otp || _uid::text, 'sha256'), 'hex');
  _exp := now() + interval '5 minutes';

  INSERT INTO public.step_up_challenges(user_id, action, target_ref, otp_hash, expires_at, ip_address, user_agent)
  VALUES (_uid, _action, _target_ref, _otp_h, _exp, _ip, _user_agent)
  RETURNING id INTO _cid;

  INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, ip_address, user_agent)
  VALUES (_uid, _action, _target_ref, 'challenge_requested', _cid, _ip, _user_agent);

  RETURN QUERY SELECT _cid, _otp, _exp;
END;
$$;


ALTER FUNCTION "public"."request_step_up_challenge"("_action" "public"."step_up_action", "_target_ref" "text", "_ip" "inet", "_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_mockup_credit_limits"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.mockup_credits SET 
    current_month_spent = 0.00,
    last_reset_month    = CURRENT_DATE
  WHERE last_reset_month IS NULL OR last_reset_month < date_trunc('month', CURRENT_DATE)::date;
  
  UPDATE public.mockup_credits SET 
    current_day_spent = 0.00,
    last_reset_day    = CURRENT_DATE
  WHERE last_reset_day IS NULL OR last_reset_day < CURRENT_DATE;
END $$;


ALTER FUNCTION "public"."reset_mockup_credit_limits"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_optimization_queue"("_only_running" boolean DEFAULT true) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  affected int;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF _only_running THEN
    UPDATE public.optimization_queue SET status = 'pending', started_at = NULL WHERE status = 'running';
  ELSE
    UPDATE public.optimization_queue SET status = 'pending', started_at = NULL, finished_at = NULL, error = NULL WHERE status IN ('running','failed','blocked');
  END IF;
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;
$$;


ALTER FUNCTION "public"."reset_optimization_queue"("_only_running" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_user_step_up_state"("_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_supervisor_or_above(auth.uid()) THEN RAISE EXCEPTION 'Permission denied'; END IF;
  DELETE FROM public.step_up_challenges WHERE user_id = _user_id AND consumed = false;
  DELETE FROM public.step_up_tokens WHERE user_id = _user_id AND consumed = false;
END $$;


ALTER FUNCTION "public"."reset_user_step_up_state"("_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_discount_approval_transactional"("_request_id" "uuid", "_approved" boolean, "_admin_notes" "text" DEFAULT NULL::"text") RETURNS "public"."discount_approval_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _quote_id uuid;
  _q public.quotes;
  _request public.discount_approval_requests;
  _decision text := CASE WHEN _approved THEN 'approved' ELSE 'rejected' END;
  _snapshot text;
BEGIN
  IF _uid IS NULL OR NOT public.is_supervisor_or_above(_uid) THEN
    RAISE EXCEPTION 'Apenas coordenador ou superior pode decidir aprovação.'
      USING ERRCODE = '42501';
  END IF;

  SELECT quote_id INTO _quote_id
  FROM public.discount_approval_requests WHERE id = _request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Solicitação não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO _q FROM public.quotes WHERE id = _quote_id FOR UPDATE;
  SELECT * INTO _request
  FROM public.discount_approval_requests WHERE id = _request_id FOR UPDATE;

  IF _request.quote_id IS DISTINCT FROM _quote_id THEN
    RAISE EXCEPTION 'Solicitação mudou durante a decisão.' USING ERRCODE = '40001';
  END IF;
  IF _request.status = _decision THEN RETURN _request; END IF;
  IF _request.status <> 'pending' THEN
    RAISE EXCEPTION 'Decisão terminal conflitante: solicitação já está %.', _request.status
      USING ERRCODE = '23514';
  END IF;

  _snapshot := public.compute_quote_snapshot_hash(_quote_id);
  IF _request.quote_snapshot_hash IS DISTINCT FROM _snapshot
     OR _request.requested_discount_percent < COALESCE(_q.real_discount_percent, 0) THEN
    RAISE EXCEPTION 'Snapshot ou percentual mudou; solicite nova aprovação.'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.discount_approval_requests
  SET status = _decision,
      admin_id = _uid,
      admin_notes = NULLIF(btrim(_admin_notes), ''),
      responded_at = clock_timestamp(),
      valid_until = CASE WHEN _approved THEN clock_timestamp() + interval '30 days' ELSE NULL END
  WHERE id = _request_id
  RETURNING * INTO _request;

  IF NOT _approved THEN
    PERFORM set_config('app.discount_approval_request_id', _request_id::text, true);
  END IF;

  UPDATE public.quotes
  SET status = CASE WHEN _approved THEN 'pending' ELSE 'draft' END
  WHERE id = _quote_id;

  INSERT INTO public.quote_history (
    quote_id, user_id, action, description, field_changed,
    old_value, new_value, metadata
  ) VALUES (
    _quote_id, _uid,
    CASE WHEN _approved THEN 'discount_approved' ELSE 'discount_rejected' END,
    format('Desconto de %s%% %s pelo gestor',
      _request.requested_discount_percent,
      CASE WHEN _approved THEN 'aprovado' ELSE 'rejeitado' END),
    'discount', _request.max_allowed_percent::text || '%',
    _request.requested_discount_percent::text || '%',
    jsonb_build_object(
      'request_id', _request_id,
      'admin_notes', NULLIF(btrim(_admin_notes), ''),
      'status', _decision
    )
  );

  RETURN _request;
END;
$$;


ALTER FUNCTION "public"."respond_discount_approval_transactional"("_request_id" "uuid", "_approved" boolean, "_admin_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_collection_item_from_trash"("_item_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'archive'
    AS $$
DECLARE v_row record;
BEGIN
  SELECT * INTO v_row FROM public.collection_items_trash WHERE id = _item_id AND user_id = auth.uid();
  IF NOT FOUND THEN RETURN false; END IF;

  INSERT INTO archive.collection_items (id, collection_id, product_id, color_name, color_hex, thumbnail_url, notes, price_at_save, sort_order)
  VALUES (
    COALESCE(v_row.original_id, gen_random_uuid()),
    v_row.collection_id,
    v_row.product_id,
    v_row.color_name,
    v_row.color_hex,
    v_row.thumbnail_url,
    v_row.notes,
    v_row.price_at_save,
    v_row.sort_order
  );

  DELETE FROM public.collection_items_trash WHERE id = _item_id;
  RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;


ALTER FUNCTION "public"."restore_collection_item_from_trash"("_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_favorite_from_trash"("_trash_id" "uuid", "_user_id" "uuid", "_fallback_list_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_trash           public.favorite_items_trash%ROWTYPE;
  v_list_id         uuid;
  v_item_id         uuid;
  v_original_list   uuid;
BEGIN
  SELECT * INTO v_trash
  FROM public.favorite_items_trash
  WHERE id = _trash_id AND user_id = _user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not-found');
  END IF;

  v_original_list := v_trash.list_id;

  SELECT id INTO v_list_id
  FROM public.favorite_lists
  WHERE id = v_trash.list_id
    AND user_id = _user_id
    AND is_archived = false;

  IF v_list_id IS NULL AND _fallback_list_id IS NOT NULL THEN
    SELECT id INTO v_list_id
    FROM public.favorite_lists
    WHERE id = _fallback_list_id
      AND user_id = _user_id
      AND is_archived = false;
  END IF;

  IF v_list_id IS NULL THEN
    v_list_id := public.ensure_default_favorite_list(_user_id);
  END IF;

  INSERT INTO public.favorite_items (
    list_id, user_id, product_id, variant_id, variant_info,
    note, price_at_save
  ) VALUES (
    v_list_id, _user_id, v_trash.product_id, v_trash.variant_id, v_trash.variant_info,
    v_trash.note, v_trash.price_at_save
  )
  ON CONFLICT (list_id, product_id, variant_id) DO NOTHING
  RETURNING id INTO v_item_id;

  DELETE FROM public.favorite_items_trash WHERE id = _trash_id;

  RETURN jsonb_build_object(
    'ok', true,
    'item_id', v_item_id,
    'list_id', v_list_id,
    'original_list_changed', (v_list_id IS DISTINCT FROM v_original_list)
  );
END;
$$;


ALTER FUNCTION "public"."restore_favorite_from_trash"("_trash_id" "uuid", "_user_id" "uuid", "_fallback_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_favorite_item_from_trash"("_item_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE v_row record;
BEGIN
  SELECT * INTO v_row FROM public.favorite_items_trash WHERE id = _item_id AND user_id = auth.uid();
  IF NOT FOUND THEN RETURN false; END IF;
  INSERT INTO public.favorite_items (id, list_id, user_id, product_id, variant_id, variant_info, note, price_at_save)
  VALUES (v_row.id, v_row.list_id, v_row.user_id, v_row.product_id, v_row.variant_id, v_row.variant_info, v_row.note, v_row.price_at_save);
  DELETE FROM public.favorite_items_trash WHERE id = _item_id;
  RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;


