CREATE OR REPLACE FUNCTION "public"."rpc_enrich_kit_component"("p_kit_component_id" "uuid", "p_source" character varying DEFAULT 'manual_admin'::character varying, "p_shape_type" character varying DEFAULT NULL::character varying, "p_length_mm" integer DEFAULT NULL::integer, "p_width_mm" integer DEFAULT NULL::integer, "p_height_mm" integer DEFAULT NULL::integer, "p_diameter_mm" integer DEFAULT NULL::integer, "p_weight_g" integer DEFAULT NULL::integer, "p_pkg_ext_length_mm" integer DEFAULT NULL::integer, "p_pkg_ext_width_mm" integer DEFAULT NULL::integer, "p_pkg_ext_height_mm" integer DEFAULT NULL::integer, "p_pkg_int_length_mm" integer DEFAULT NULL::integer, "p_pkg_int_width_mm" integer DEFAULT NULL::integer, "p_pkg_int_height_mm" integer DEFAULT NULL::integer, "p_pkg_material" character varying DEFAULT NULL::character varying, "p_pkg_color" character varying DEFAULT NULL::character varying, "p_pkg_finish" character varying DEFAULT NULL::character varying, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pkc        product_kit_components%ROWTYPE;
  v_raw_id     UUID;
  v_pad_id     UUID;
  v_comp_id    UUID;
BEGIN
  -- Verificar que componente existe
  SELECT * INTO v_pkc FROM product_kit_components WHERE id = p_kit_component_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'component not found');
  END IF;

  -- Inserir no bronze
  INSERT INTO kit_component_enrichment_raw (
    kit_product_id, kit_component_id,
    raw_component_name, raw_component_type,
    raw_data, source, source_confidence
  ) VALUES (
    v_pkc.kit_product_id, p_kit_component_id,
    v_pkc.component_name, v_pkc.component_type_code,
    jsonb_strip_nulls(jsonb_build_object(
      'component_name',         v_pkc.component_name,
      'component_type_code',    v_pkc.component_type_code,
      'unit',                   'mm',
      'shape_type',             p_shape_type,
      'length_mm',              p_length_mm,
      'width_mm',               p_width_mm,
      'height_mm',              p_height_mm,
      'diameter_mm',            p_diameter_mm,
      'weight_g',               p_weight_g,
      'is_packaging',           v_pkc.is_packaging,
      'pkg_ext_length_mm',      p_pkg_ext_length_mm,
      'pkg_ext_width_mm',       p_pkg_ext_width_mm,
      'pkg_ext_height_mm',      p_pkg_ext_height_mm,
      'pkg_int_length_mm',      p_pkg_int_length_mm,
      'pkg_int_width_mm',       p_pkg_int_width_mm,
      'pkg_int_height_mm',      p_pkg_int_height_mm,
      'pkg_material',           p_pkg_material,
      'pkg_color',              p_pkg_color,
      'pkg_finish',             p_pkg_finish,
      'notes',                  p_notes,
      'allows_personalization', v_pkc.allows_personalization,
      'quantity',               v_pkc.quantity
    )),
    p_source, 1.000  -- manual = confiança máxima
  ) RETURNING id INTO v_raw_id;

  -- Bronze → Prata (auto-padroniza)
  v_pad_id := fn_standardize_kit_component(v_raw_id);

  -- Auto-approve e promove (input manual = confiança total)
  UPDATE kit_component_padronizacao
  SET padronizacao_status = 'approved', reviewed_at = NOW()
  WHERE id = v_pad_id;

  v_comp_id := fn_promote_kit_component_padronizacao(v_pad_id);

  RETURN jsonb_build_object(
    'ok',           TRUE,
    'raw_id',       v_raw_id,
    'pad_id',       v_pad_id,
    'component_id', v_comp_id,
    'enrichment_status', (SELECT enrichment_status FROM product_kit_components WHERE id = v_comp_id)
  );
END;
$$;


ALTER FUNCTION "public"."rpc_enrich_kit_component"("p_kit_component_id" "uuid", "p_source" character varying, "p_shape_type" character varying, "p_length_mm" integer, "p_width_mm" integer, "p_height_mm" integer, "p_diameter_mm" integer, "p_weight_g" integer, "p_pkg_ext_length_mm" integer, "p_pkg_ext_width_mm" integer, "p_pkg_ext_height_mm" integer, "p_pkg_int_length_mm" integer, "p_pkg_int_width_mm" integer, "p_pkg_int_height_mm" integer, "p_pkg_material" character varying, "p_pkg_color" character varying, "p_pkg_finish" character varying, "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rpc_enrich_kit_component"("p_kit_component_id" "uuid", "p_source" character varying, "p_shape_type" character varying, "p_length_mm" integer, "p_width_mm" integer, "p_height_mm" integer, "p_diameter_mm" integer, "p_weight_g" integer, "p_pkg_ext_length_mm" integer, "p_pkg_ext_width_mm" integer, "p_pkg_ext_height_mm" integer, "p_pkg_int_length_mm" integer, "p_pkg_int_width_mm" integer, "p_pkg_int_height_mm" integer, "p_pkg_material" character varying, "p_pkg_color" character varying, "p_pkg_finish" character varying, "p_notes" "text") IS 'RPC pública: recebe dimensões de um componente de kit via painel admin,
   executa o fluxo completo bronze→prata→gold automaticamente.
   Input manual = auto-approve (confiança 1.0).';



CREATE OR REPLACE FUNCTION "public"."save_custom_kit_atomic"("p_request_id" "uuid", "p_kit_id" "uuid", "p_expected_revision" integer, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_kit public.custom_kits%ROWTYPE;
  v_existing_kit_id uuid;
  v_status text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_request_id IS NULL OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'request_id and object payload are required' USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(COALESCE(p_payload->'items_data', 'null'::jsonb)) <> 'array'
    OR jsonb_typeof(COALESCE(p_payload->'personalization_data', 'null'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'items_data must be an array and personalization_data must be an object'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE((p_payload->>'kit_quantity')::integer, 0) < 1
    OR COALESCE((p_payload->>'box_price')::numeric, -1) < 0
    OR COALESCE((p_payload->>'items_price')::numeric, -1) < 0
    OR COALESCE((p_payload->>'personalization_price')::numeric, -1) < 0
    OR COALESCE((p_payload->>'total_price')::numeric, -1) < 0
    OR COALESCE((p_payload->>'volume_usage_percent')::numeric, -1) < 0 THEN
    RAISE EXCEPTION 'kit quantity, prices and volume usage must be non-negative (quantity >= 1)'
      USING ERRCODE = '22023';
  END IF;

  SELECT kit_id
    INTO v_existing_kit_id
    FROM public.kit_save_requests
   WHERE request_id = p_request_id
     AND user_id = auth.uid();

  IF v_existing_kit_id IS NOT NULL THEN
    SELECT * INTO v_kit
      FROM public.custom_kits
     WHERE id = v_existing_kit_id
       AND user_id = auth.uid();
    RETURN to_jsonb(v_kit);
  END IF;

  v_status := COALESCE(p_payload->>'status', 'draft');
  IF v_status NOT IN ('draft', 'ready') THEN
    RAISE EXCEPTION 'Kit save accepts only draft or ready status' USING ERRCODE = '22023';
  END IF;

  IF p_kit_id IS NULL THEN
    INSERT INTO public.custom_kits (
      user_id, name, status, kit_type, box_data, items_data, personalization_data,
      kit_quantity, box_price, items_price, personalization_price, total_price,
      volume_usage_percent, color, icon, tag, description, is_favorite, revision
    ) VALUES (
      auth.uid(),
      COALESCE(NULLIF(btrim(p_payload->>'name'), ''), 'Kit sem nome'),
      v_status,
      COALESCE(NULLIF(p_payload->>'kit_type', ''), 'montado'),
      p_payload->'box_data',
      p_payload->'items_data',
      p_payload->'personalization_data',
      (p_payload->>'kit_quantity')::integer,
      (p_payload->>'box_price')::numeric,
      (p_payload->>'items_price')::numeric,
      (p_payload->>'personalization_price')::numeric,
      (p_payload->>'total_price')::numeric,
      (p_payload->>'volume_usage_percent')::numeric,
      COALESCE(NULLIF(p_payload->>'color', ''), '#3B82F6'),
      COALESCE(NULLIF(p_payload->>'icon', ''), 'Package'),
      NULLIF(p_payload->>'tag', ''),
      NULLIF(p_payload->>'description', ''),
      COALESCE((p_payload->>'is_favorite')::boolean, false),
      0
    )
    RETURNING * INTO v_kit;
  ELSE
    IF p_expected_revision IS NULL OR p_expected_revision < 0 THEN
      RAISE EXCEPTION 'expected revision is required to update a kit' USING ERRCODE = '22023';
    END IF;

    UPDATE public.custom_kits
       SET name = COALESCE(NULLIF(btrim(p_payload->>'name'), ''), name),
           status = v_status,
           kit_type = COALESCE(NULLIF(p_payload->>'kit_type', ''), kit_type),
           box_data = p_payload->'box_data',
           items_data = p_payload->'items_data',
           personalization_data = p_payload->'personalization_data',
           kit_quantity = (p_payload->>'kit_quantity')::integer,
           box_price = (p_payload->>'box_price')::numeric,
           items_price = (p_payload->>'items_price')::numeric,
           personalization_price = (p_payload->>'personalization_price')::numeric,
           total_price = (p_payload->>'total_price')::numeric,
           volume_usage_percent = (p_payload->>'volume_usage_percent')::numeric,
           color = COALESCE(NULLIF(p_payload->>'color', ''), color),
           icon = COALESCE(NULLIF(p_payload->>'icon', ''), icon),
           tag = NULLIF(p_payload->>'tag', ''),
           description = NULLIF(p_payload->>'description', ''),
           is_favorite = COALESCE((p_payload->>'is_favorite')::boolean, false),
           revision = revision + 1,
           updated_at = now()
     WHERE id = p_kit_id
       AND user_id = auth.uid()
       AND revision = p_expected_revision
     RETURNING * INTO v_kit;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Kit was changed or is no longer accessible. Reload before saving again.'
        USING ERRCODE = '40001';
    END IF;
  END IF;

  INSERT INTO public.kit_save_requests (request_id, user_id, kit_id)
  VALUES (p_request_id, auth.uid(), v_kit.id);

  RETURN to_jsonb(v_kit);
END;
$$;


ALTER FUNCTION "public"."save_custom_kit_atomic"("p_request_id" "uuid", "p_kit_id" "uuid", "p_expected_revision" integer, "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_custom_kit_atomic"("p_request_id" "uuid", "p_kit_id" "uuid", "p_expected_revision" integer, "p_payload" "jsonb") IS 'Kit Maker optimistic save: idempotent by request_id and conflict-safe by revision.';



