CREATE OR REPLACE FUNCTION "public"."search_notebooks_by_size"("p_width" numeric DEFAULT NULL::numeric, "p_height" numeric DEFAULT NULL::numeric, "p_format_code" character varying DEFAULT NULL::character varying, "p_tolerance" numeric DEFAULT 0.5) RETURNS TABLE("product_id" "uuid", "product_name" character varying, "format_code" character varying, "width_cm" numeric, "height_cm" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        p.id,
        p.name,
        pf.code,
        COALESCE(pns.width_cm, pf.width_cm),
        COALESCE(pns.height_cm, pf.height_cm)
    FROM products p
    JOIN product_notebook_specs pns ON p.id = pns.product_id
    LEFT JOIN paper_formats pf ON pns.format_id = pf.id
    WHERE 
        (p_format_code IS NULL OR pf.code = p_format_code)
        AND (
            p_width IS NULL 
            OR ABS(COALESCE(pns.width_cm, pf.width_cm) - p_width) <= p_tolerance
        )
        AND (
            p_height IS NULL 
            OR ABS(COALESCE(pns.height_cm, pf.height_cm) - p_height) <= p_tolerance
        );
END;
$$;


ALTER FUNCTION "public"."search_notebooks_by_size"("p_width" numeric, "p_height" numeric, "p_format_code" character varying, "p_tolerance" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_notebooks_by_size"("p_width" numeric, "p_height" numeric, "p_format_code" character varying, "p_tolerance" numeric) IS 'Busca cadernos por formato (código) ou dimensões (cm) com tolerância';



CREATE OR REPLACE FUNCTION "public"."search_products_fulltext"("p_search_term" "text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0, "p_category_slug" "text" DEFAULT NULL::"text", "p_only_in_stock" boolean DEFAULT false, "p_min_price" numeric DEFAULT NULL::numeric, "p_max_price" numeric DEFAULT NULL::numeric) RETURNS TABLE("ps_id" "uuid", "ps_sku" character varying, "ps_name" character varying, "ps_slug" character varying, "ps_description" "text", "ps_category_name" character varying, "ps_min_price" numeric, "ps_image_url" "text", "ps_total_stock" integer, "ps_relevance" numeric, "ps_match_highlights" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_search_normalized TEXT;
  v_tsquery           tsquery;
  v_category_id       uuid;
BEGIN
  IF p_search_term IS NULL OR length(trim(p_search_term)) = 0 THEN
    RETURN;
  END IF;

  v_search_normalized := lower(unaccent(trim(p_search_term)));

  BEGIN
    v_tsquery := websearch_to_tsquery('portuguese', unaccent(trim(p_search_term)));
  EXCEPTION WHEN OTHERS THEN
    v_tsquery := NULL;
  END;

  -- Resolver category_id uma única vez fora do loop
  IF p_category_slug IS NOT NULL THEN
    SELECT id INTO v_category_id FROM categories WHERE slug = p_category_slug LIMIT 1;
  END IF;

  PERFORM set_config('pg_trgm.similarity_threshold', '0.2', true);

  RETURN QUERY
  WITH variant_stock AS (
    -- Pré-agregar: 1 hash join global em vez de N lateral lookups
    SELECT pv.product_id, COALESCE(SUM(pv.stock_quantity), 0)::INT AS total_stock
    FROM product_variants pv
    WHERE pv.is_active = true
    GROUP BY pv.product_id
  )
  SELECT
    p.id,
    p.sku::VARCHAR,
    p.name::VARCHAR,
    p.slug::VARCHAR,
    p.description,
    c.name::VARCHAR,
    p.sale_price,
    p.primary_image_url,
    COALESCE(vs.total_stock, 0)::INT,
    (
      CASE WHEN v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery
           THEN ts_rank_cd(p.search_vector, v_tsquery, 32) * 2.0
           ELSE 0
      END +
      word_similarity(v_search_normalized, lower(unaccent(p.name))) * 1.0 +
      CASE WHEN lower(p.sku) LIKE '%' || v_search_normalized || '%' THEN 0.8 ELSE 0 END +
      CASE WHEN COALESCE(vs.total_stock, 0) > 0 THEN 0.3 ELSE 0 END
    )::NUMERIC,
    CASE
      WHEN v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery THEN 'fulltext'
      WHEN word_similarity(v_search_normalized, lower(unaccent(p.name))) > 0.3 THEN 'nome'
      WHEN lower(p.sku) LIKE '%' || v_search_normalized || '%' THEN 'sku'
      ELSE 'parcial'
    END
  FROM products p
  LEFT JOIN product_category_assignments pca ON pca.product_id = p.id AND pca.is_primary = true
  LEFT JOIN categories c ON c.id = pca.category_id
  LEFT JOIN variant_stock vs ON vs.product_id = p.id
  WHERE
    p.is_active = true
    AND p.is_deleted IS NOT TRUE
    AND p.sale_price IS NOT NULL
    AND (
      (v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery)
      OR p.name % v_search_normalized
      OR lower(p.sku) LIKE '%' || v_search_normalized || '%'
    )
    AND (p_category_slug IS NULL OR pca.category_id = v_category_id)
    AND (NOT p_only_in_stock OR COALESCE(vs.total_stock, 0) > 0)
    AND (p_min_price IS NULL OR p.sale_price >= p_min_price)
    AND (p_max_price IS NULL OR p.sale_price <= p_max_price)
  ORDER BY 10 DESC, COALESCE(vs.total_stock, 0) DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."search_products_fulltext"("p_search_term" "text", "p_limit" integer, "p_offset" integer, "p_category_slug" "text", "p_only_in_stock" boolean, "p_min_price" numeric, "p_max_price" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_products_semantic"("_query" "text", "_products" "jsonb", "_limit" integer DEFAULT 20) RETURNS TABLE("product_id" "text", "score" real, "matched_field" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  _normalized_query text;
BEGIN
  IF _query IS NULL OR length(trim(_query)) = 0 THEN RETURN; END IF;
  IF _products IS NULL OR jsonb_typeof(_products) <> 'array' THEN RETURN; END IF;
  _normalized_query := lower(trim(_query));
  RETURN QUERY
  WITH expanded AS (
    SELECT
      COALESCE(p->>'id', p->>'product_id', '') AS pid,
      lower(COALESCE(p->>'name', '')) AS pname,
      lower(COALESCE(p->>'description', '')) AS pdesc,
      lower(COALESCE(
        (SELECT string_agg(t::text, ' ') FROM jsonb_array_elements_text(COALESCE(p->'tags', '[]'::jsonb)) t), ''
      )) AS ptags,
      lower(COALESCE(p->>'category', '')) AS pcat
    FROM jsonb_array_elements(_products) AS p
  ),
  scored AS (
    SELECT pid,
      GREATEST(
        similarity(pname, _normalized_query) * 1.0,
        similarity(pdesc, _normalized_query) * 0.6,
        similarity(ptags, _normalized_query) * 0.8,
        similarity(pcat, _normalized_query) * 0.5
      ) AS best_score,
      CASE
        WHEN similarity(pname, _normalized_query) >= similarity(pdesc, _normalized_query)
         AND similarity(pname, _normalized_query) >= similarity(ptags, _normalized_query)
         AND similarity(pname, _normalized_query) >= similarity(pcat, _normalized_query) THEN 'name'
        WHEN similarity(ptags, _normalized_query) >= similarity(pdesc, _normalized_query)
         AND similarity(ptags, _normalized_query) >= similarity(pcat, _normalized_query) THEN 'tags'
        WHEN similarity(pdesc, _normalized_query) >= similarity(pcat, _normalized_query) THEN 'description'
        ELSE 'category'
      END AS field
    FROM expanded WHERE pid <> ''
  )
  SELECT pid, best_score::real, field FROM scored
  WHERE best_score > 0.05
  ORDER BY best_score DESC
  LIMIT GREATEST(_limit, 1);
END;
$$;


ALTER FUNCTION "public"."search_products_semantic"("_query" "text", "_products" "jsonb", "_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_records_rerank"("_query" "text", "_candidates" "jsonb") RETURNS TABLE("id" "text", "score" real, "matched_field" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  _q text;
BEGIN
  IF _query IS NULL OR length(trim(_query)) = 0 THEN RETURN; END IF;
  IF _candidates IS NULL OR jsonb_typeof(_candidates) <> 'array' THEN RETURN; END IF;
  _q := lower(trim(_query));
  RETURN QUERY
  WITH expanded AS (
    SELECT COALESCE(c->>'id', '') AS cid,
      lower(COALESCE(c->>'label', '')) AS clabel,
      lower(COALESCE(c->>'sublabel', '')) AS csublabel
    FROM jsonb_array_elements(_candidates) AS c
  ),
  scored AS (
    SELECT cid,
      GREATEST(
        similarity(clabel, _q) * 1.0,
        word_similarity(_q, clabel) * 0.9,
        similarity(csublabel, _q) * 0.7,
        word_similarity(_q, csublabel) * 0.6
      ) AS best_score,
      CASE WHEN similarity(clabel, _q) >= similarity(csublabel, _q) THEN 'label' ELSE 'sublabel' END AS field
    FROM expanded WHERE cid <> ''
  )
  SELECT cid, best_score::real, field FROM scored
  WHERE best_score > 0.05
  ORDER BY best_score DESC;
END;
$$;


ALTER FUNCTION "public"."search_records_rerank"("_query" "text", "_candidates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_suggestions"("p_partial_term" character varying, "p_limit" integer DEFAULT 10) RETURNS TABLE("suggestion" character varying, "suggestion_type" character varying, "count" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_term_normalized text;
  v_term_prefix     text;
  v_term_word       text;
BEGIN
  v_term_normalized := unaccent(lower(trim(p_partial_term)));
  v_term_prefix     := v_term_normalized || '%';
  v_term_word       := '% ' || v_term_normalized || '%';

  IF length(v_term_normalized) < 2 THEN RETURN; END IF;

  RETURN QUERY
  (
    SELECT
      p.name::VARCHAR AS suggestion,
      'produto'::VARCHAR AS suggestion_type,
      COUNT(*)::BIGINT AS count
    FROM products p
    WHERE p.is_active = true
      AND (p.is_deleted = false OR p.is_deleted IS NULL)
      AND (
        unaccent(lower(p.name)) LIKE v_term_prefix
        OR unaccent(lower(p.name)) LIKE v_term_word
      )
    GROUP BY p.name
    ORDER BY
      -- Prioridade 1: começa com o termo
      MIN(CASE WHEN unaccent(lower(p.name)) LIKE v_term_prefix THEN 0 ELSE 1 END),
      COUNT(*) DESC
    LIMIT p_limit / 2
  )
  UNION ALL
  (
    SELECT
      c.name::VARCHAR AS suggestion,
      'categoria'::VARCHAR AS suggestion_type,
      (SELECT COUNT(DISTINCT pca.product_id)
       FROM product_category_assignments pca
       JOIN products p2 ON p2.id = pca.product_id
       WHERE pca.category_id = c.id
         AND p2.is_active = true
         AND (p2.is_deleted = false OR p2.is_deleted IS NULL)
      )::BIGINT AS count
    FROM categories c
    WHERE c.is_active = true
      AND (
        unaccent(lower(c.name)) LIKE v_term_prefix
        OR unaccent(lower(c.name)) LIKE v_term_word
      )
    ORDER BY
      CASE WHEN unaccent(lower(c.name)) LIKE v_term_prefix THEN 0 ELSE 1 END,
      count DESC
    LIMIT p_limit / 2
  )
  ORDER BY count DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."search_suggestions"("p_partial_term" character varying, "p_limit" integer) OWNER TO "postgres";


