CREATE OR REPLACE FUNCTION "public"."seed_discount_test_users"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _seller_id uuid; _admin_id uuid;
BEGIN
  SELECT user_id INTO _seller_id FROM public.profiles WHERE email = 'seller-test@discount-approval.test' LIMIT 1;
  SELECT user_id INTO _admin_id FROM public.profiles WHERE email = 'admin-test@discount-approval.test' LIMIT 1;

  IF _seller_id IS NULL OR _admin_id IS NULL THEN
    RETURN jsonb_build_object('ok', false,
      'error', 'Test users not found. Create them via Supabase Admin API first.',
      'seller_exists', _seller_id IS NOT NULL,
      'admin_exists', _admin_id IS NOT NULL);
  END IF;

  INSERT INTO public.user_roles (user_id, role) VALUES (_seller_id, 'vendedor')
  ON CONFLICT (user_id, role) DO NOTHING;
  INSERT INTO public.user_roles (user_id, role) VALUES (_admin_id, 'admin')
  ON CONFLICT (user_id, role) DO NOTHING;

  UPDATE public.profiles SET role = 'vendedor' WHERE user_id = _seller_id;
  UPDATE public.profiles SET role = 'admin' WHERE user_id = _admin_id;

  RETURN jsonb_build_object('ok', true, 'seller_id', _seller_id, 'admin_id', _admin_id);
END;
$$;


ALTER FUNCTION "public"."seed_discount_test_users"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_digest_notification"("p_user_id" "uuid", "p_notification_ids" "uuid"[], "p_unread_count" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_title   text;
  v_message text;
BEGIN
  -- Valida parâmetros básicos
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'send_digest_notification: p_user_id não pode ser NULL';
  END IF;

  IF p_unread_count IS NULL OR p_unread_count <= 0 THEN
    RETURN; -- Nada a fazer
  END IF;

  -- Remove digests anteriores não lidos do mesmo usuário (evita flood)
  DELETE FROM public.workspace_notifications
  WHERE user_id = p_user_id
    AND type     = 'digest'
    AND is_read  = false;

  -- Monta mensagem adaptada ao volume
  IF p_unread_count = 1 THEN
    v_title   := 'Você tem 1 notificação pendente';
    v_message := 'Há 1 notificação aguardando sua leitura. Acesse o painel para ver os detalhes.';
  ELSE
    v_title   := format('Você tem %s notificações pendentes', p_unread_count);
    v_message := format(
      'Há %s notificações aguardando sua leitura. Acesse o painel para ver todos os detalhes.',
      p_unread_count
    );
  END IF;

  -- Insere o digest como notificação in-app consolidada
  INSERT INTO public.workspace_notifications (
    id,
    user_id,
    title,
    message,
    type,
    category,
    is_read,
    action_url,
    metadata,
    created_at
  ) VALUES (
    gen_random_uuid(),
    p_user_id,
    v_title,
    v_message,
    'digest',
    'system',
    false,
    '/notifications',
    jsonb_build_object(
      'digest', true,
      'unread_count', p_unread_count,
      'notification_ids', to_jsonb(p_notification_ids),
      'generated_at', now()
    ),
    now()
  );
END;
$$;


ALTER FUNCTION "public"."send_digest_notification"("p_user_id" "uuid", "p_notification_ids" "uuid"[], "p_unread_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_digest_notification"("p_user_id" "uuid", "p_notification_ids" "uuid"[], "p_unread_count" integer) IS 'Consolida notificações não lidas do usuário em uma única notificação do tipo digest. Remove digests antigos não lidos antes de inserir o novo, evitando acúmulo. Chamada pela edge function send-digest via service_role_key.';



