CREATE OR REPLACE FUNCTION "public"."set_custom_kit_pinned"("_kit_id" "uuid", "_is_pinned" boolean) RETURNS "public"."custom_kits"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  _actor_id uuid := auth.uid();
  _kit public.custom_kits;
BEGIN
  IF _actor_id IS NULL THEN
    RAISE EXCEPTION 'Authentication is required to change a pinned kit'
      USING ERRCODE = '28000';
  END IF;
  IF _kit_id IS NULL THEN
    RAISE EXCEPTION 'A kit id is required'
      USING ERRCODE = '22023';
  END IF;

  -- Serialise all pin changes for one owner before unpinning any row.
  PERFORM pg_advisory_xact_lock(hashtextextended(_actor_id::text || ':custom-kit-pin', 0));

  SELECT *
  INTO _kit
  FROM public.custom_kits
  WHERE id = _kit_id
    AND user_id = _actor_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Kit not found or not owned by the authenticated user'
      USING ERRCODE = '42501';
  END IF;

  IF _is_pinned THEN
    UPDATE public.custom_kits
    SET is_pinned = false
    WHERE user_id = _actor_id
      AND is_pinned
      AND id <> _kit_id;
  END IF;

  UPDATE public.custom_kits
  SET is_pinned = _is_pinned
  WHERE id = _kit_id
    AND user_id = _actor_id
  RETURNING * INTO _kit;

  RETURN _kit;
END;
$$;


ALTER FUNCTION "public"."set_custom_kit_pinned"("_kit_id" "uuid", "_is_pinned" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_custom_kit_pinned"("_kit_id" "uuid", "_is_pinned" boolean) IS 'Atomically pins or unpins one owned Kit Maker draft; serializes concurrent tabs per user.';



CREATE OR REPLACE FUNCTION "public"."set_is_imported_from_origin"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_stricker_id UUID := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
    v_country TEXT;
BEGIN
    -- STRICKER ou sem fornecedor: usa país de origem
    IF NEW.supplier_id = v_stricker_id OR NEW.supplier_id IS NULL THEN
        
        v_country := NULLIF(TRIM(NEW.origin_country), '');
        
        IF v_country IS NULL THEN
            -- Sem país definido
            IF TG_OP = 'INSERT' THEN
                NEW.is_imported := TRUE;
            ELSE
                NEW.is_imported := COALESCE(OLD.is_imported, TRUE);
            END IF;
        ELSIF UPPER(v_country) IN ('BRASIL', 'BR', 'BRAZIL') THEN
            -- Nacional
            NEW.is_imported := FALSE;
        ELSE
            -- Importado
            NEW.is_imported := TRUE;
        END IF;
    ELSE
        -- XBZ, ASIA, outros fornecedores: SEMPRE importado
        NEW.is_imported := TRUE;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_is_imported_from_origin"() OWNER TO "postgres";


