CREATE OR REPLACE FUNCTION "public"."sync_quote_discount_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_qid       uuid := COALESCE(NEW.quote_id, OLD.quote_id);
  v_status    text;
  v_resp      timestamptz;
  v_prev_role text := current_setting('request.jwt.claim.role', true);
BEGIN
  -- DAR mais recente do quote; NULL se nao sobrou nenhum (DELETE do ultimo) -> limpa o espelho
  SELECT status, responded_at INTO v_status, v_resp
  FROM public.discount_approval_requests
  WHERE quote_id = v_qid
  ORDER BY COALESCE(responded_at, created_at) DESC
  LIMIT 1;

  -- eleva contexto SOMENTE p/ o write derivado (mesmo escape hatch que immutability/validate ja reconhecem)
  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE public.quotes
  SET discount_approval_status = v_status,
      discount_approved_at     = v_resp
  WHERE id = v_qid
    AND (discount_approval_status IS DISTINCT FROM v_status
         OR discount_approved_at IS DISTINCT FROM v_resp);   -- guarda anti no-op

  -- restaura o contexto imediatamente
  PERFORM set_config('request.jwt.claim.role', COALESCE(v_prev_role, ''), true);

  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  -- espelhamento derivado NUNCA derruba a transacao primaria do DAR; auto-cura na proxima mudanca
  PERFORM set_config('request.jwt.claim.role', COALESCE(v_prev_role, ''), true);
  RAISE WARNING 'sync_quote_discount_approval falhou p/ quote %: % (espelhamento ignorado)', v_qid, SQLERRM;
  RETURN NULL;
END $$;


ALTER FUNCTION "public"."sync_quote_discount_approval"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_user_org_to_org_members"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF (TG_OP = 'INSERT') THEN
    INSERT INTO public.organization_members (organization_id, user_id, role, joined_at, created_at, updated_at)
    VALUES (NEW.organization_id, NEW.user_id, NEW.role, NEW.created_at, NEW.created_at, NEW.updated_at)
    ON CONFLICT (organization_id, user_id) DO UPDATE
      SET role = EXCLUDED.role, updated_at = EXCLUDED.updated_at;
    RETURN NEW;
  ELSIF (TG_OP = 'UPDATE') THEN
    UPDATE public.organization_members
      SET role = NEW.role, updated_at = NEW.updated_at
    WHERE organization_id = NEW.organization_id AND user_id = NEW.user_id;
    RETURN NEW;
  ELSIF (TG_OP = 'DELETE') THEN
    DELETE FROM public.organization_members
    WHERE organization_id = OLD.organization_id AND user_id = OLD.user_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."sync_user_org_to_org_members"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."test_classify_batch"("product_names" "text"[]) RETURNS TABLE("product_name" "text", "tipo_detectado" "text", "category_slug" "text", "material" "text", "confidence" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_name TEXT;
    v_result JSONB;
BEGIN
    FOREACH v_name IN ARRAY product_names LOOP
        v_result := classify_product(v_name);
        
        product_name := v_name;
        tipo_detectado := v_result->>'tipo_detectado';
        category_slug := v_result->>'category_slug';
        material := COALESCE(v_result->>'material', v_result->>'tipo');
        confidence := CASE 
            WHEN v_result->>'error' IS NOT NULL THEN 'BAIXO'
            WHEN v_result->>'warning' IS NOT NULL THEN 'MEDIO'
            WHEN v_result->>'category_slug' IS NOT NULL 
                 AND v_result->>'material' IS NOT NULL
                 AND v_result->>'material' != 'INDEFINIDO'
            THEN 'ALTO'
            WHEN v_result->>'category_slug' IS NOT NULL 
            THEN 'MEDIO'
            ELSE 'BAIXO'
        END;
        
        RETURN NEXT;
    END LOOP;
END;
$$;


