BEGIN
  IF TG_OP = 'INSERT' AND NEW.parent_id IS NOT NULL THEN
    -- Nova subcategoria: incrementar contador do parent
    UPDATE categories
    SET children_count = children_count + 1
    WHERE id = NEW.parent_id;
    
  ELSIF TG_OP = 'DELETE' AND OLD.parent_id IS NOT NULL THEN
    -- Categoria deletada: decrementar contador do parent
    UPDATE categories
    SET children_count = GREATEST(0, children_count - 1)
    WHERE id = OLD.parent_id;
    
  ELSIF TG_OP = 'UPDATE' AND OLD.parent_id IS DISTINCT FROM NEW.parent_id THEN
    -- Parent mudou: atualizar ambos
    IF OLD.parent_id IS NOT NULL THEN
      UPDATE categories 
      SET children_count = GREATEST(0, children_count - 1) 
      WHERE id = OLD.parent_id;
    END IF;
    
    IF NEW.parent_id IS NOT NULL THEN
      UPDATE categories 
      SET children_count = children_count + 1 
      WHERE id = NEW.parent_id;
    END IF;
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."update_parent_children_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_preferred_suppliers"("p_variant_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("updated_count" integer, "variants_processed" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_updated INTEGER := 0;
    v_processed INTEGER := 0;
BEGIN
    -- PASSO 1: Remove is_preferred de todos os registros relevantes
    UPDATE variant_supplier_sources
    SET is_preferred = FALSE
    WHERE (p_variant_id IS NULL OR variant_id = p_variant_id)
    AND is_preferred = TRUE;
    
    -- PASSO 2: Marca o de maior estoque como preferido para cada variante
    WITH best_per_variant AS (
        SELECT DISTINCT ON (variant_id)
            id,
            variant_id
        FROM variant_supplier_sources
        WHERE (p_variant_id IS NULL OR variant_id = p_variant_id)
        AND is_active = TRUE
        AND COALESCE(removed_from_api, FALSE) = FALSE
        ORDER BY 
            variant_id,
            COALESCE(quantity, 0) DESC,
            priority ASC,
            COALESCE(cost_price, 999999) ASC
    )
    UPDATE variant_supplier_sources vss
    SET is_preferred = TRUE
    FROM best_per_variant bpv
    WHERE vss.id = bpv.id;
    
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    
    -- Contar variantes processadas
    SELECT COUNT(DISTINCT variant_id)::INTEGER INTO v_processed
    FROM variant_supplier_sources
    WHERE (p_variant_id IS NULL OR variant_id = p_variant_id)
    AND is_active = TRUE
    AND COALESCE(removed_from_api, FALSE) = FALSE;
    
    RETURN QUERY SELECT v_updated, v_processed;
END;
$$;


ALTER FUNCTION "public"."update_preferred_suppliers"("p_variant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_preferred_suppliers"("p_variant_id" "uuid") IS 'Atualiza is_preferred para o fornecedor com MAIOR ESTOQUE.

PARÂMETROS:
- p_variant_id: UUID de uma variante específica, ou NULL para todas

RETORNO:
- updated_count: quantos registros foram marcados como preferidos
- variants_processed: quantas variantes foram processadas

CRITÉRIOS (em ordem):
1. Maior estoque disponível
2. Menor número de prioridade
3. Menor custo

QUANDO USAR:
- Após sincronização de estoque
- Cron job periódico
- Quando cadastrar novo fornecedor

EXEMPLOS:
SELECT * FROM update_preferred_suppliers();

SELECT * FROM update_preferred_suppliers(''uuid-da-variante'');

Criado em: 25/01/2026';



