CREATE OR REPLACE FUNCTION "public"."update_video_from_cloudflare"("p_cloudflare_video_id" character varying, "p_status" character varying, "p_duration_seconds" integer DEFAULT NULL::integer, "p_width_px" integer DEFAULT NULL::integer, "p_height_px" integer DEFAULT NULL::integer, "p_thumbnail_url" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_video_id uuid;
  v_cf_sub CONSTANT text := 'customer-ksi0mrlcw6rwzezz';
BEGIN
  UPDATE product_videos SET
    cloudflare_status = p_status,
    duration_seconds  = COALESCE(p_duration_seconds, duration_seconds),
    width_px          = COALESCE(p_width_px, width_px),
    height_px         = COALESCE(p_height_px, height_px),
    url_thumbnail     = COALESCE(p_thumbnail_url,
      'https://' || v_cf_sub || '.cloudflarestream.com/' || cloudflare_video_id || '/thumbnails/thumbnail.jpg'),
    cloudflare_error  = p_error_message,
    updated_at        = now()
  WHERE cloudflare_video_id = p_cloudflare_video_id
  RETURNING id INTO v_video_id;

  RETURN v_video_id IS NOT NULL;
END;
$$;


ALTER FUNCTION "public"."update_video_from_cloudflare"("p_cloudflare_video_id" character varying, "p_status" character varying, "p_duration_seconds" integer, "p_width_px" integer, "p_height_px" integer, "p_thumbnail_url" "text", "p_error_message" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_video_from_cloudflare"("p_cloudflare_video_id" character varying, "p_status" character varying, "p_duration_seconds" integer, "p_width_px" integer, "p_height_px" integer, "p_thumbnail_url" "text", "p_error_message" "text") IS '
Atualiza status e metadados de um vídeo em product_videos após evento do CF Stream.
Chamada quando o CF Stream processa o upload (status muda para ''ready'', ''error'', etc).

PARÂMETROS:
  p_cloudflare_video_id varchar — UID do CF Stream (chave de busca)
  p_status              varchar — Novo status (''ready'', ''error'', ''pendingupload'', etc.)
  p_duration_seconds    integer — Duração após processamento (opcional)
  p_width_px            integer — Largura final (opcional)
  p_height_px           integer — Altura final (opcional)
  p_thumbnail_url       text    — URL do thumbnail (opcional; se NULL, reconstrói)
  p_error_message       text    — Mensagem de erro se falhou (opcional)

RETORNA: boolean — true se encontrou e atualizou o registro

LÓGICA:
  UPDATE product_videos SET
    cloudflare_status = p_status,
    url_thumbnail = COALESCE(p_thumbnail_url, url reconstruída com subdomain correto),
    ...
  WHERE cloudflare_video_id = p_cloudflare_video_id

SUBDOMAIN: customer-ksi0mrlcw6rwzezz (accountHash, ≠ accountId cd0f4eee)
  Se p_thumbnail_url for NULL, a URL é reconstruída internamente
  com o subdomain correto.

HISTÓRICO:
  Bug 2026-06-07: lia de cloudflare_stream_config (tabela inexistente → NULL URL).
  Fix 2026-06-07: subdomain hardcoded como CONSTANT v_cf_sub.
';



CREATE OR REPLACE FUNCTION "public"."upsert_supplier_customization_raw"("p_supplier_id" "uuid", "p_table_code_option" "text", "p_raw_data" "jsonb", "p_table_code" "text" DEFAULT NULL::"text", "p_customization_type" "text" DEFAULT NULL::"text", "p_import_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE v_id uuid; v_hash text;
BEGIN
  v_hash := encode(digest(p_raw_data::text,'sha256'),'hex');
  INSERT INTO supplier_customization_raw
    (supplier_id, table_code, table_code_option, customization_type, raw_data, import_batch_id)
  VALUES (p_supplier_id,
          COALESCE(p_table_code, regexp_replace(p_table_code_option, '-[^-]+$', '')),
          p_table_code_option, p_customization_type, p_raw_data, p_import_batch_id)
  ON CONFLICT (supplier_id, table_code_option) DO UPDATE SET
     raw_data           = EXCLUDED.raw_data,
     customization_type = COALESCE(EXCLUDED.customization_type, supplier_customization_raw.customization_type),
     import_batch_id    = COALESCE(EXCLUDED.import_batch_id, supplier_customization_raw.import_batch_id),
     status             = CASE WHEN supplier_customization_raw.content_hash IS DISTINCT FROM v_hash
                               THEN 'pending'::supplier_raw_status ELSE supplier_customization_raw.status END,
     updated_at         = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $_$;


ALTER FUNCTION "public"."upsert_supplier_customization_raw"("p_supplier_id" "uuid", "p_table_code_option" "text", "p_raw_data" "jsonb", "p_table_code" "text", "p_customization_type" "text", "p_import_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_supplier_customization_raw"("p_supplier_id" "uuid", "p_table_code_option" "text", "p_raw_data" "jsonb", "p_table_code" "text", "p_customization_type" "text", "p_import_batch_id" "uuid") IS 'Grava feed CustomizationTables (grao = table_code_option). Idempotente por content_hash.';



CREATE OR REPLACE FUNCTION "public"."upsert_supplier_stock_raw"("p_supplier_id" "uuid", "p_supplier_reference" "text", "p_stock_data" "jsonb", "p_import_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_id uuid; v_hash text;
BEGIN
  v_hash := encode(digest(p_stock_data::text,'sha256'),'hex');
  INSERT INTO supplier_products_raw
    (supplier_id, supplier_reference, supplier_sku, raw_data,
     stock_data, stock_hash, stock_synced_at, status, import_batch_id)
  VALUES
    (p_supplier_id, p_supplier_reference, p_supplier_reference, '{}'::jsonb,
     p_stock_data, v_hash, now(), 'skipped'::supplier_raw_status, p_import_batch_id)
  ON CONFLICT (supplier_id, supplier_reference) DO UPDATE SET
     stock_data      = EXCLUDED.stock_data,
     stock_hash      = v_hash,
     stock_synced_at = now(),
     import_batch_id = COALESCE(EXCLUDED.import_batch_id, supplier_products_raw.import_batch_id),
     stock_status    = CASE WHEN supplier_products_raw.stock_hash IS DISTINCT FROM v_hash
                            THEN 'pending'::supplier_raw_status ELSE supplier_products_raw.stock_status END,
     updated_at      = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;


ALTER FUNCTION "public"."upsert_supplier_stock_raw"("p_supplier_id" "uuid", "p_supplier_reference" "text", "p_stock_data" "jsonb", "p_import_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_supplier_stock_raw"("p_supplier_id" "uuid", "p_supplier_reference" "text", "p_stock_data" "jsonb", "p_import_batch_id" "uuid") IS 'Grava feed Stocks na linha do SKU (trilha stock_*). Stub status=skipped se o produto ainda nao existir; reset stock_status->pending so quando o estoque muda.';



