CREATE OR REPLACE FUNCTION "public"."validate_status_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'quotes' THEN
    -- NOTA Fase B (12/05/2026): valores 'approved'/'rejected'/'pending_approval'/'viewed'
    -- são mantidos por compatibilidade histórica até decisão Fase C
    -- (novo ciclo de vida do orçamento sem rotas públicas).
    IF NEW.status NOT IN ('draft', 'pending', 'sent', 'approved', 'rejected', 'expired', 'revision', 'pending_approval', 'converted', 'viewed') THEN
      RAISE EXCEPTION 'Invalid quote status: %', NEW.status;
    END IF;
  END IF;
  IF TG_TABLE_NAME = 'orders' THEN
    IF NEW.status NOT IN ('pending', 'confirmed', 'in_production', 'shipped', 'delivered', 'cancelled') THEN
      RAISE EXCEPTION 'Invalid order status: %', NEW.status;
    END IF;
    IF NEW.fulfillment_status NOT IN ('unfulfilled', 'partially_fulfilled', 'fulfilled') THEN
      RAISE EXCEPTION 'Invalid fulfillment status: %', NEW.fulfillment_status;
    END IF;
  END IF;
  IF TG_TABLE_NAME = 'custom_kits' THEN
    IF NEW.status NOT IN ('draft', 'ready', 'shared', 'archived') THEN
      RAISE EXCEPTION 'Invalid kit status: %', NEW.status;
    END IF;
  END IF;
  -- ❌ REMOVIDOS (Fase B Decision 011): branches de kit_share_tokens e quote_approval_tokens
  --    Tables foram dropadas — rotas públicas com token não existem mais no modelo.
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_status_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_video_requirements"("p_width" integer, "p_height" integer, "p_duration_seconds" integer DEFAULT NULL::integer, "p_file_size_bytes" bigint DEFAULT NULL::bigint, "p_supplier_code" character varying DEFAULT 'DEFAULT'::character varying) RETURNS TABLE("is_valid" boolean, "validation_status" character varying, "issues" "text"[], "recommendations" "text"[])
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_req RECORD;
    v_issues TEXT[] := ARRAY[]::TEXT[];
    v_recommendations TEXT[] := ARRAY[]::TEXT[];
    v_status VARCHAR(30);
    v_file_size_mb DECIMAL;
BEGIN
    -- Buscar requisitos do fornecedor
    SELECT * INTO v_req
    FROM supplier_video_requirements
    WHERE supplier_code = p_supplier_code AND is_active = true;
    
    IF NOT FOUND THEN
        SELECT * INTO v_req
        FROM supplier_video_requirements
        WHERE supplier_code = 'DEFAULT' AND is_active = true;
    END IF;
    
    -- Validar dimensões mínimas
    IF p_width IS NOT NULL AND p_width < v_req.min_width_px THEN
        v_issues := array_append(v_issues, 
            format('Largura %spx abaixo do mínimo (%spx)', p_width, v_req.min_width_px));
    END IF;
    
    IF p_height IS NOT NULL AND p_height < v_req.min_height_px THEN
        v_issues := array_append(v_issues, 
            format('Altura %spx abaixo do mínimo (%spx)', p_height, v_req.min_height_px));
    END IF;
    
    -- Validar dimensões ideais (apenas recomendação)
    IF p_width IS NOT NULL AND p_width < v_req.ideal_width_px THEN
        v_recommendations := array_append(v_recommendations, 
            format('Largura %spx abaixo do ideal (%spx)', p_width, v_req.ideal_width_px));
    END IF;
    
    -- Validar duração
    IF p_duration_seconds IS NOT NULL THEN
        IF p_duration_seconds < v_req.min_duration_seconds THEN
            v_issues := array_append(v_issues, 
                format('Duração %ss abaixo do mínimo (%ss)', p_duration_seconds, v_req.min_duration_seconds));
        END IF;
        IF p_duration_seconds > v_req.max_duration_seconds THEN
            v_recommendations := array_append(v_recommendations, 
                format('Duração %ss excede o recomendado (%ss)', p_duration_seconds, v_req.max_duration_seconds));
        END IF;
    END IF;
    
    -- Validar tamanho do arquivo
    IF p_file_size_bytes IS NOT NULL THEN
        v_file_size_mb := p_file_size_bytes / 1024.0 / 1024.0;
        IF v_file_size_mb > v_req.max_file_size_mb THEN
            v_issues := array_append(v_issues, 
                format('Arquivo %.1fMB excede o máximo (%.0fMB)', v_file_size_mb, v_req.max_file_size_mb));
        END IF;
    END IF;
    
    -- Determinar status
    IF array_length(v_issues, 1) > 0 THEN
        v_status := 'REPROVADO';
    ELSIF array_length(v_recommendations, 1) > 0 THEN
        v_status := 'APROVADO_COM_RESSALVAS';
    ELSE
        v_status := 'APROVADO';
    END IF;
    
    RETURN QUERY SELECT 
        (array_length(v_issues, 1) IS NULL OR array_length(v_issues, 1) = 0),
        v_status,
        v_issues,
        v_recommendations;
END;
$$;


ALTER FUNCTION "public"."validate_video_requirements"("p_width" integer, "p_height" integer, "p_duration_seconds" integer, "p_file_size_bytes" bigint, "p_supplier_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vault_delete_secret"("p_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  IF NOT public.is_admin_strict(auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: only dev role can delete from vault'
      USING ERRCODE = '42501';
  END IF;
  
  DELETE FROM vault.secrets WHERE name = p_name;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted > 0;
END $$;


ALTER FUNCTION "public"."vault_delete_secret"("p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."vault_delete_secret"("p_name" "text") IS 'Remove secret do vault. Apenas dev. Retorna true se deletou.';



CREATE OR REPLACE FUNCTION "public"."vault_get_secret"("p_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $$
DECLARE
  v_value text;
BEGIN
  -- Gate: só dev pode ler em vault (edge functions usam service_role, bypassam isso)
  IF NOT public.is_admin_strict(auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: only dev role can read vault directly. Edge functions bypass via service_role.'
      USING ERRCODE = '42501';
  END IF;
  
  SELECT decrypted_secret INTO v_value 
  FROM vault.decrypted_secrets 
  WHERE name = p_name 
  LIMIT 1;
  
  RETURN v_value;  -- NULL se não existe
END $$;


ALTER FUNCTION "public"."vault_get_secret"("p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."vault_get_secret"("p_name" "text") IS 'Retorna valor decifrado de um secret. Apenas dev role. Edge functions devem usar service_role direto em vault.decrypted_secrets ou via integration_credentials helper.';



CREATE OR REPLACE FUNCTION "public"."vault_list_secret_names"() RETURNS TABLE("name" "text", "description" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $$
BEGIN
  -- Gate: dev e supervisor podem listar nomes (auditoria de inventário)
  IF NOT public.is_supervisor_or_above(auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: requires supervisor role or above'
      USING ERRCODE = '42501';
  END IF;
  
  RETURN QUERY
  SELECT s.name, s.description, s.created_at, s.updated_at 
  FROM vault.secrets s 
  ORDER BY s.name;
END $$;


ALTER FUNCTION "public"."vault_list_secret_names"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."vault_list_secret_names"() IS 'Lista secrets do vault sem expor valores. Supervisor+ pode auditar inventário.';



CREATE OR REPLACE FUNCTION "public"."vault_set_secret"("p_name" "text", "p_value" "text", "p_description" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'extensions'
    AS $$
DECLARE
  v_secret_id uuid;
BEGIN
  IF NOT public.is_admin_strict(auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: only dev role can write to vault'
      USING ERRCODE = '42501';
  END IF;

  SELECT id INTO v_secret_id FROM vault.secrets WHERE name = p_name LIMIT 1;
  
  IF v_secret_id IS NULL THEN
    -- API oficial: create_secret(new_secret, new_name, new_description)
    SELECT vault.create_secret(p_value, p_name, p_description) INTO v_secret_id;
  ELSE
    PERFORM vault.update_secret(v_secret_id, p_value, p_name, COALESCE(p_description, ''));
  END IF;
  
  RETURN v_secret_id;
END $$;


ALTER FUNCTION "public"."vault_set_secret"("p_name" "text", "p_value" "text", "p_description" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."vault_set_secret"("p_name" "text", "p_value" "text", "p_description" "text") IS 'Armazena/atualiza secret cifrado em vault.secrets via API oficial vault.create_secret/update_secret. Apenas dev. Idempotente.';



CREATE OR REPLACE FUNCTION "public"."verify_step_up_otp"("_challenge_id" "uuid", "_otp" "text") RETURNS TABLE("token" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid UUID := auth.uid();
  _row RECORD;
  _otp_h TEXT;
  _token TEXT;
  _token_h TEXT;
  _tid UUID;
  _exp TIMESTAMPTZ;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF;

  SELECT * INTO _row FROM public.step_up_challenges
  WHERE id = _challenge_id AND user_id = _uid AND consumed = false AND expires_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.step_up_audit_log(user_id, event_type, challenge_id, metadata)
    VALUES (_uid, 'failed', _challenge_id, '{"reason":"challenge_not_found_or_expired"}'::jsonb);
    RAISE EXCEPTION 'invalid_or_expired_challenge';
  END IF;

  IF NOT _row.password_verified THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, metadata)
    VALUES (_uid, _row.action, _row.target_ref, 'failed', _challenge_id, '{"reason":"password_not_verified"}'::jsonb);
    RAISE EXCEPTION 'password_not_verified_first';
  END IF;

  IF _row.attempts >= _row.max_attempts THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, metadata)
    VALUES (_uid, _row.action, _row.target_ref, 'failed', _challenge_id, '{"reason":"max_attempts"}'::jsonb);
    RAISE EXCEPTION 'max_attempts_exceeded';
  END IF;

  _otp_h := encode(digest(_otp || _uid::text, 'sha256'), 'hex');

  IF _otp_h <> _row.otp_hash THEN
    UPDATE public.step_up_challenges SET attempts = attempts + 1 WHERE id = _challenge_id;
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, metadata)
    VALUES (_uid, _row.action, _row.target_ref, 'failed', _challenge_id, jsonb_build_object('reason','wrong_otp','attempt', _row.attempts + 1));
    RAISE EXCEPTION 'invalid_otp';
  END IF;

  _token := encode(gen_random_bytes(32), 'hex');
  _token_h := encode(digest(_token, 'sha256'), 'hex');
  _exp := now() + interval '5 minutes';

  INSERT INTO public.step_up_tokens(user_id, action, target_ref, token_hash, challenge_id, expires_at)
  VALUES (_uid, _row.action, _row.target_ref, _token_h, _challenge_id, _exp)
  RETURNING id INTO _tid;

  UPDATE public.step_up_challenges
    SET otp_verified = true, consumed = true
    WHERE id = _challenge_id;

  INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, token_id)
  VALUES (_uid, _row.action, _row.target_ref, 'otp_verified', _challenge_id, _tid);
  INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, token_id)
  VALUES (_uid, _row.action, _row.target_ref, 'token_issued', _challenge_id, _tid);

  RETURN QUERY SELECT _token, _exp;
END;
$$;


ALTER FUNCTION "public"."verify_step_up_otp"("_challenge_id" "uuid", "_otp" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_step_up_password"("_challenge_id" "uuid", "_password_attempt" "text") RETURNS boolean
