CREATE TABLE IF NOT EXISTS "public"."product_images" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "product_id" "uuid" NOT NULL,
    "variant_id" "uuid",
    "color_id" "uuid",
    "cloudflare_image_id" character varying(100) NOT NULL,
    "url_cdn" "text" NOT NULL,
    "filename" character varying(255),
    "file_size_bytes" bigint,
    "width_px" integer,
    "height_px" integer,
    "format" character varying(20),
    "image_type" character varying(30) DEFAULT 'gallery'::character varying NOT NULL,
    "is_primary" boolean DEFAULT false,
    "display_order" integer DEFAULT 0,
    "applies_to_color" boolean DEFAULT false,
    "source_supplier" character varying(50),
    "url_original" "text",
    "is_active" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "image_type_id" "uuid" DEFAULT '1590e144-e3f8-41e6-98f9-f4a25bae496d'::"uuid" NOT NULL,
    "supplier_code" character varying(50),
    "alt_text" "text",
    "title_text" "text",
    "caption" "text",
    "is_og_image" boolean DEFAULT false,
    "organization_id" "uuid" DEFAULT '5db5aee1-064b-4ef4-9193-345dcd8274ea'::"uuid" NOT NULL,
    "cf_sync_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "cf_uploaded_at" timestamp with time zone,
    "cf_verified_at" timestamp with time zone,
    "cf_check_attempts" smallint DEFAULT 0 NOT NULL,
    "cf_last_error" "text",
    "cf_id_scheme" "text" GENERATED ALWAYS AS (
CASE
    WHEN (("cloudflare_image_id")::"text" ~ '^xbz_site_'::"text") THEN 'hash_legacy'::"text"
    WHEN ((("cloudflare_image_id")::"text" ~ '-dup-'::"text") OR (("cloudflare_image_id")::"text" ~ '-leg-'::"text") OR (("cloudflare_image_id")::"text" ~ '--ref'::"text") OR (("cloudflare_image_id")::"text" ~ '-legacy$'::"text")) THEN 'synthetic'::"text"
    WHEN (("cloudflare_image_id")::"text" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-'::"text") THEN 'uuid'::"text"
    WHEN (("cloudflare_image_id")::"text" ~ '-(main|gal-[0-9]+)$'::"text") THEN 'main_gal'::"text"
    WHEN (("cloudflare_image_id")::"text" ~ '-d[0-9]+$'::"text") THEN 'detail_dn'::"text"
    WHEN ((("cloudflare_image_id")::"text" ~ '-[0-9]{4,}-[0-9]{9,}$'::"text") OR (("cloudflare_image_id")::"text" ~ 'd[0-9]+-[0-9]{9,}$'::"text")) THEN 'slug_ts'::"text"
    WHEN (("cloudflare_image_id")::"text" ~ '_[0-9]'::"text") THEN 'legacy_cor'::"text"
    ELSE 'seq'::"text"
END) STORED,
    "content_hash" "text",
    "canonical_image_id" "uuid",
    "is_shared" boolean DEFAULT false NOT NULL,
    "r2_bucket" "text",
    "r2_object_key" "text",
    "last_modified_source" "text",
    "deleted_at" timestamp with time zone,
    "deleted_reason" "text",
    "blurhash" "text",
    "requires_signed_url" boolean DEFAULT false NOT NULL,
    "aspect_ratio" numeric GENERATED ALWAYS AS (
CASE
    WHEN (("height_px" IS NOT NULL) AND ("height_px" > 0) AND ("width_px" IS NOT NULL)) THEN "round"((("width_px")::numeric / ("height_px")::numeric), 4)
    ELSE NULL::numeric
END) STORED,
    "cf_last_checked_at" timestamp with time zone,
    CONSTRAINT "chk_blurhash_format" CHECK ((("blurhash" IS NULL) OR (("length"("blurhash") = 28) AND ("blurhash" ~ '^[0-9A-Za-z#\$%\*\+,\-\.\:\;=\?@\[\]\^_\{\|\}~]{28}$'::"text")))),
    CONSTRAINT "chk_pi_canonical_not_self" CHECK ((("canonical_image_id" IS NULL) OR ("canonical_image_id" <> "id"))),
    CONSTRAINT "chk_pi_cf_sync_status" CHECK (("cf_sync_status" = ANY (ARRAY['pending'::"text", 'uploading'::"text", 'uploaded'::"text", 'verified'::"text", 'missing'::"text", 'failed'::"text", 'orphaned'::"text"]))),
    CONSTRAINT "chk_pi_last_modified_source" CHECK ((("last_modified_source" IS NULL) OR ("last_modified_source" = ANY (ARRAY['pipeline'::"text", 'manual'::"text", 'lovable'::"text", 'claude'::"text", 'migration'::"text", 'n8n'::"text", 'edge_function'::"text", 'api'::"text"])))),
    CONSTRAINT "chk_product_images_alt_min" CHECK ((("alt_text" IS NULL) OR ("length"("alt_text") >= 10))),
    CONSTRAINT "chk_product_images_format_lc" CHECK ((("format" IS NULL) OR (("format")::"text" ~ '^[a-z0-9]+$'::"text"))),
    CONSTRAINT "chk_product_images_image_type" CHECK ((("image_type")::"text" = ANY ((ARRAY['main'::character varying, 'product'::character varying, 'set'::character varying, 'gallery'::character varying, 'ambient'::character varying, 'detail'::character varying, 'logo'::character varying, 'component'::character varying, 'location'::character varying, 'area'::character varying, 'box'::character varying, 'pouch'::character varying, 'bag'::character varying, 'mockup'::character varying, 'thumbnail'::character varying, 'vitrine_ambiente'::character varying, 'vitrine_pessoa'::character varying, 'other'::character varying])::"text"[])))
)
WITH ("autovacuum_vacuum_scale_factor"='0.02', "autovacuum_analyze_scale_factor"='0.01');
ALTER TABLE ONLY "public"."product_images" ALTER COLUMN "product_id" SET STATISTICS 1000;
ALTER TABLE ONLY "public"."product_images" ALTER COLUMN "variant_id" SET STATISTICS 500;


ALTER TABLE "public"."product_images" OWNER TO "postgres";


COMMENT ON TABLE "public"."product_images" IS 'Manifesto de metadados de imagens hospedadas no Cloudflare Images.
A tabela NÃO armazena bytes — é um registro de endereçamento e classificação.
As imagens físicas vivem em: https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/{cloudflare_image_id}/public

━━━ RELACIONAMENTOS ━━━
• products          → FK product_id    (ON DELETE CASCADE) — produto-pai obrigatório
• image_types       → FK image_type_id (DEFAULT gallery 1590e144-…) — vocabulário de tipos
• product_variants  → FK variant_id    (nullable) — imagem específica de variante de cor/tamanho
• color_variations  → FK color_id      (nullable) — imagem vinculada a uma cor específica
• organizations     → FK organization_id (DEFAULT 5db5aee1-064b-4ef4-9193-345dcd8274ea)

━━━ TRIGGERS (disparam nesta ordem no INSERT/UPDATE) ━━━
1. trg_auto_classify_image            BEFORE → fn_auto_classify_product_image()
   Lê o filename da url_cdn/url_original e infere image_type+image_type_id+is_primary+display_order.
   Se nenhum padrão casar, usa o image_type fornecido pelo chamador (ou "other").
2. trg_sync_image_type_code           BEFORE → fn_sync_image_type_code()
   Garante coerência entre image_type (varchar) e image_type_id (uuid FK).
   INSERT: varchar tem precedência; UPDATE: sync bidirecional.
3. trg_product_images_seo_autofill    BEFORE → auto-preenche alt_text, title_text (SEO).
4. trg_single_primary_image           AFTER  → garante no máximo 1 is_primary=true ativo por produto.
5. trg_autopromote_primary            AFTER  → se a primary é desativada, promove a próxima elegível.
6. trg_sync_images_to_product         AFTER  → propaga primary_image_url e images[] JSONB em products.
   ⚠️ Este trigger é o que mantém products.primary_image_url atualizado — não edite aquele campo diretamente.
7. trg_normalize_source_supplier      BEFORE → padroniza maiúsculas em source_supplier.

━━━ CONSTRAINTS CRÍTICAS ━━━
• cloudflare_image_id  UNIQUE  — ID único no Cloudflare. Nunca duplicar.
  Se a MESMA imagem CF precisar servir múltiplos produtos, use sufixo:
    {cf_id}-dup-{hash6}          ← quando o CF dedup cria uma cópia
    {cf_id}-leg-{product_id[:6]} ← para migração de imagens legadas
  Neste caso url_cdn continua apontando para a imagem original (sem o sufixo).
• alt_text  CHECK length >= 10  (ou NULL) — sem textos curtos demais.
• image_type  NOT NULL DEFAULT ''gallery''
• image_type_id  NOT NULL DEFAULT ''1590e144-e3f8-41e6-98f9-f4a25bae496d'' (= tipo ''gallery'')
  ⚠️ Default corrigido em 2026-06-17 de UUID(other) para UUID(gallery) — alinhado com image_type.
  Os dois campos são SEMPRE mantidos em sync pelos triggers acima.

━━━ PIPELINE MEDALLION ━━━
Bronze (supplier_products_raw) → Silver (produtos_padronizacao) → Gold (products) → product_images
Para INSERTs em massa vindo do pipeline, sempre definir antes:
  SELECT set_config(''app.write_source'', ''pipeline'', false);
Caso contrário fn_products_capture_manual_edits capturará as mudanças em locked_fields.

━━━ MONITORAMENTO DE QUALIDADE ━━━
• vw_image_type_coherence         — divergências image_type vs image_type_id (deve ser 0)
• product_qa_image_alerts         — alertas de produtos ativos sem imagem
• pg_cron ''qa-imageless-products'' (a cada 30 min) — varredura automática
• fn_qa_scan_imageless_products() — execução manual da varredura';



COMMENT ON COLUMN "public"."product_images"."id" IS 'PK UUID gerada automaticamente (gen_random_uuid). Nunca reutilizar.';



COMMENT ON COLUMN "public"."product_images"."product_id" IS 'FK → products.id  |  ON DELETE CASCADE.
Produto-pai obrigatório. Toda imagem pertence a exatamente um produto.
Ao deletar o produto, todas as suas imagens são deletadas em cascata.';



COMMENT ON COLUMN "public"."product_images"."variant_id" IS 'FK → product_variants.id  (nullable, ON DELETE SET NULL).
Vincula a imagem a uma variante específica de cor/tamanho do produto.
Quando a variante é deletada, o campo vira NULL e a imagem sobrevive sem vínculo.

━━━ QUANDO PREENCHER ━━━
• Preencher quando a imagem representa uma cor/variante específica do produto.
  Ex.: foto da caneta AZUL → variant_id = uuid da variante Azul.
• Deixar NULL quando a imagem se aplica a TODAS as variantes.

━━━ SEMÂNTICA DUPLA DE color_id (atenção!) ━━━
O campo color_id nem sempre indica a cor do produto. Contexto por image_type:
  → main/gallery/product (applies_to_color=true):
      color_id = COR DO PRODUTO → deve ter variant_id correspondente
  → location/area/component (applies_to_color=false — SPOT):
      color_id = COR DA TINTA DE IMPRESSÃO/GRAVAÇÃO, NÃO cor do produto.
      Estas imagens NÃO devem ter variant_id (aplicam-se a todas as variantes).
      Manter variant_id=NULL para esses 3 tipos é CORRETO POR DESIGN.

━━━ DADOS REAIS (2026-06-16) ━━━
• 16.383+ rows com variant_id preenchido (22% do total)
• 5.126+ produtos com ≥1 imagem por variante
• Fornecedores que usam: SPOT, XBZ, SOMARCAS, ASIA Import (todas as cores)
• 3.305 rows SPOT (location/area/component) com color_id mas variant_id=NULL → correto

━━━ GAP REMANESCENTE ━━━
~670 imagens XBZ applies_to_color=true com color_id mas sem variant_id.
Causa: inconsistência entre nome de cor na imagem (ex: "Fumê") e nome na variante
(ex: "Preto"). Sinônimos documentados em color_synonym_map.
Mapeamento: vw_product_images_variant_gap (gap_type=XBZ_COLOR_MISMATCH)
Solução: reprocessar via pipeline XBZ com tabela color_synonym_map.

━━━ INVARIANTES ━━━
• Se preenchido: variant_id.product_id DEVE = product_id desta row.
• Se preenchido: variant_id deve apontar para variante is_active=true.
• 0 cross-product mismatches permitidos (monitorar com vw_product_images_variant_gap).';



COMMENT ON COLUMN "public"."product_images"."color_id" IS 'FK → color_variations.id  (nullable, ON DELETE SET NULL).
Preenchido quando applies_to_color=true e a imagem pertence a uma cor.
NULL = imagem neutra (aplica-se a todas as cores).';



COMMENT ON COLUMN "public"."product_images"."cloudflare_image_id" IS 'Identificador único da imagem no Cloudflare Images (NOT NULL, UNIQUE globalmente).
Formato típico: {fornecedor}-{referencia}-{sequencial}
  Ex.: xbz-caneca-termica-27317-1771595129
       asia-cv250-01
       spot-66116-main
       sm-av-00401-main

⚠️ UNIQUE constraint: o mesmo CF image_id NÃO pode aparecer em duas rows.
Quando uma imagem CF serve múltiplos produtos, adicionar sufixo diferenciador:
  {cf_id}-dup-{hash6}          → cópia criada pelo Cloudflare
  {cf_id}-leg-{product_id[:6]} → migração de legados (padrão desta base)
Neste caso, url_cdn continua apontando para a URL original sem sufixo.';



COMMENT ON COLUMN "public"."product_images"."url_cdn" IS 'URL de entrega pública no Cloudflare CDN (NOT NULL).
Formato padrão: https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw/{cloudflare_image_id}/public
Variações de tamanho são acessadas por: /width=400 /format=webp /quality=85 etc.
Este campo deve sempre refletir a URL real da imagem no CF, mesmo quando
cloudflare_image_id tiver sufixo diferenciador (ex.: -leg-abc123).';



COMMENT ON COLUMN "public"."product_images"."filename" IS 'Nome do arquivo original (ex.: caneta-azul-001.jpg).
Usado por triggers de classificação automática. Pode ser NULL se não disponível.';



COMMENT ON COLUMN "public"."product_images"."file_size_bytes" IS 'Tamanho do arquivo em bytes conforme retornado pelo Cloudflare ou fornecedor.
Pode ser NULL para imagens legadas ou migradas sem metadados de tamanho.';



COMMENT ON COLUMN "public"."product_images"."width_px" IS 'Largura da imagem em pixels. Pode ser NULL para imagens não inspecionadas.';



COMMENT ON COLUMN "public"."product_images"."height_px" IS 'Altura da imagem em pixels. Pode ser NULL para imagens não inspecionadas.';



COMMENT ON COLUMN "public"."product_images"."format" IS 'Formato do arquivo: jpeg, png, webp, gif, avif.
CHECK: apenas caracteres alfanuméricos minúsculos [a-z0-9]. NULL = não identificado.';



COMMENT ON COLUMN "public"."product_images"."image_type" IS 'Código textual do tipo de imagem (NOT NULL, DEFAULT ''gallery'').
Preenchido automaticamente pelo trigger trg_auto_classify_image com base no filename.
Valores válidos (em sincronia com image_types.code):
  main           → imagem principal / capa do produto
  gallery        → vista alternativa / ângulo extra
  set            → foto do conjunto de todas as cores disponíveis
  ambient        → produto em ambiente/lifestyle
  detail         → close-up / detalhe de gravação ou material
  box            → embalagem / caixa
  pouch          → estojo / bolsa
  bag            → sacola
  logo           → imagem com logotipo aplicado
  mockup         → mockup gerado digitalmente
  thumbnail      → miniatura
  component      → componente isolado do produto
  location       → localização de gravação no produto
  area           → área de gravação dimensionada
  other          → não classificado (default de fallback)
⚠️ Sempre manter sincronizado com image_type_id.';



COMMENT ON COLUMN "public"."product_images"."is_primary" IS 'Marca a imagem como principal do produto no front-end (DEFAULT false).
⚠️ INVARIANTE: no máximo 1 row com is_primary=true E is_active=true por product_id.
Garantido pelo trigger trg_single_primary_image.
Quando esta row é desativada (is_active→false), o trigger trg_autopromote_primary
elege automaticamente a próxima imagem elegível como nova primary.
O campo products.primary_image_url é mantido em sincronia por trg_sync_images_to_product.';



COMMENT ON COLUMN "public"."product_images"."display_order" IS 'Ordem de exibição na galeria do produto (DEFAULT 0, auto-ajustado para MAX+1 pelo trigger).
Menor valor = aparece primeiro. Não é global — é relativo ao product_id.
Para reordenar manualmente: UPDATE product_images SET display_order=N WHERE id=...
em pipeline mode para não acionar triggers desnecessários.';



COMMENT ON COLUMN "public"."product_images"."applies_to_color" IS 'true → imagem válida apenas para a cor indicada em color_id (DEFAULT false).
false → imagem neutra, aparece para todas as variantes do produto.
Usar em conjunto com color_id.';



COMMENT ON COLUMN "public"."product_images"."source_supplier" IS 'Fornecedor de origem da imagem (normalizado em maiúsculas pelo trigger).
Valores em uso: XBZ, ASIA, SPOT, SOMARCAS, 88B, LEGADO.
Usado em relatórios de cobertura por fornecedor.';



COMMENT ON COLUMN "public"."product_images"."url_original" IS 'URL de origem antes da ingestão no Cloudflare (ex.: URL do site do fornecedor, S3, Azure CDN).
Usado pelo trigger trg_auto_classify_image para extrair o filename e classificar o tipo.
Mantido para rastreabilidade e re-download se necessário.';



COMMENT ON COLUMN "public"."product_images"."is_active" IS 'Soft-delete da imagem (DEFAULT true).
false → imagem oculta: não aparece no front, não conta para cobertura, não é primary.
Quando a primary ativa é desativada, o trigger trg_autopromote_primary
elege a próxima imagem ativa elegível. Não usar DELETE — usar is_active=false.';



COMMENT ON COLUMN "public"."product_images"."created_at" IS 'Timestamp de criação da row (DEFAULT now()). Imutável após inserção.';



COMMENT ON COLUMN "public"."product_images"."updated_at" IS 'Timestamp da última atualização. Atualizado automaticamente por trigger.';



COMMENT ON COLUMN "public"."product_images"."image_type_id" IS 'FK → image_types.id (NOT NULL, DEFAULT ''1590e144-e3f8-41e6-98f9-f4a25bae496d'' = tipo ''gallery'').
Contraparte UUID do campo image_type — os dois são SEMPRE mantidos em sync por:
  1. trg_auto_classify_image (BEFORE INSERT): hardcoda ambos simultaneamente
  2. trg_sync_image_type_code (BEFORE INS+UPD): bidirecional — mudar um sincroniza o outro

Via image_type_id é possível acessar metadados ricos da tabela image_types:
  is_primary_candidate · show_in_gallery · display_priority
  gallery_order · is_color_specific · category · subcategory

Tipos is_primary_candidate=true: main, vitrine_pessoa, vitrine_ambiente, set.
⚠️ Default corrigido em 2026-06-17 de UUID(other) para UUID(gallery), alinhando com image_type default.';



COMMENT ON COLUMN "public"."product_images"."supplier_code" IS 'Código interno de identificação do fornecedor — geralmente igual a source_supplier.
Mantido separado para casos em que source_supplier difere do código de sistema.';



COMMENT ON COLUMN "public"."product_images"."alt_text" IS 'Texto alternativo da imagem para SEO e acessibilidade (CHECK: length >= 10 ou NULL).
Auto-preenchido pelo trigger trg_product_images_seo_autofill combinando
nome do produto + cor + tipo. Ex.: "Caneta metal azul — imagem principal".
⚠️ Nunca inserir alt_text com menos de 10 caracteres: a constraint chk_product_images_alt_min rejeita.
Para contornar em batch, deixar NULL (o trigger preencherá).';



COMMENT ON COLUMN "public"."product_images"."title_text" IS 'Título da imagem para tooltip HTML (atributo title na tag <img>).
Complementa alt_text. Preenchido pelo mesmo trigger de SEO. Pode ser NULL.';



COMMENT ON COLUMN "public"."product_images"."caption" IS 'Legenda visível para o usuário (ex.: em galeria com zoom ou lightbox).
Opcional. Não confundir com alt_text (acessibilidade) ou title_text (tooltip).';



COMMENT ON COLUMN "public"."product_images"."is_og_image" IS 'true → imagem usada como og:image nas metatags OpenGraph (DEFAULT false).
Automaticamente definido como true quando a imagem é eleita is_primary=true
pelo trigger trg_auto_classify_image.';



COMMENT ON COLUMN "public"."product_images"."organization_id" IS 'FK → organizations.id (NOT NULL, DEFAULT ''5db5aee1-064b-4ef4-9193-345dcd8274ea'').
Esta base opera com uma única organização. Nunca alterar este default.';



COMMENT ON COLUMN "public"."product_images"."cf_sync_status" IS 'Estado do objeto no Cloudflare Images: pending|uploading|uploaded|verified|missing|failed|orphaned';



COMMENT ON COLUMN "public"."product_images"."cf_uploaded_at" IS 'Timestamp do upload concluido no Cloudflare (campo uploaded da API CF)';



COMMENT ON COLUMN "public"."product_images"."cf_verified_at" IS 'Timestamp when this image was last confirmed PRESENT in Cloudflare Images API. NULL if never verified or if currently missing.';



COMMENT ON COLUMN "public"."product_images"."cf_check_attempts" IS 'Numero de tentativas de verificacao/upload no CF';



COMMENT ON COLUMN "public"."product_images"."cf_last_error" IS 'Ultima mensagem de erro de upload/verificacao no CF';



COMMENT ON COLUMN "public"."product_images"."cf_id_scheme" IS 'Convencao do cloudflare_image_id (derivada): legacy_cor|dn|main_gal|slug_ts|synthetic|hash_legacy|uuid|seq';



COMMENT ON COLUMN "public"."product_images"."content_hash" IS 'Hash do binario (sha256) ou etag R2/CF para deduplicacao de conteudo';



COMMENT ON COLUMN "public"."product_images"."canonical_image_id" IS 'Aponta para a linha canonica quando esta e alias/duplicata (substitui o hack -dup-)';



COMMENT ON COLUMN "public"."product_images"."is_shared" IS 'TRUE quando a imagem fisica e compartilhada por multiplos produtos';



COMMENT ON COLUMN "public"."product_images"."r2_bucket" IS 'Bucket R2 do master/original (ex.: gift-store)';



COMMENT ON COLUMN "public"."product_images"."r2_object_key" IS 'Chave (UUID) do objeto master no R2 — liga DB <-> R2';



COMMENT ON COLUMN "public"."product_images"."last_modified_source" IS 'Origem da ultima escrita: pipeline|manual|lovable|claude|migration|n8n|edge_function|api';



COMMENT ON COLUMN "public"."product_images"."deleted_at" IS 'Soft-delete com carimbo (complementa is_active)';



COMMENT ON COLUMN "public"."product_images"."deleted_reason" IS 'Motivo do soft-delete';



COMMENT ON COLUMN "public"."product_images"."blurhash" IS 'Placeholder LQIP/blurhash para blur-up (evita layout shift)';



