CREATE TABLE IF NOT EXISTS "public"."kit_component_padronizacao" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "kit_product_id" "uuid" NOT NULL,
    "kit_component_id" "uuid",
    "raw_id" "uuid",
    "component_name" "text" NOT NULL,
    "component_type_code" character varying(30),
    "material_type_id" "uuid",
    "secondary_material_type_id" "uuid",
    "component_product_id" "uuid",
    "shape_type" character varying(30) DEFAULT 'rectangular'::character varying,
    "length_mm" integer,
    "width_mm" integer,
    "height_mm" integer,
    "diameter_mm" integer,
    "circumference_mm" integer,
    "weight_g" integer,
    "is_packaging" boolean DEFAULT false,
    "pkg_ext_length_mm" integer,
    "pkg_ext_width_mm" integer,
    "pkg_ext_height_mm" integer,
    "pkg_int_length_mm" integer,
    "pkg_int_width_mm" integer,
    "pkg_int_height_mm" integer,
    "pkg_int_diameter_mm" integer,
    "pkg_weight_g" integer,
    "pkg_material" character varying(100),
    "pkg_color" character varying(100),
    "pkg_finish" character varying(100),
    "pkg_type_code" character varying(30),
    "allows_personalization" boolean DEFAULT true,
    "quantity" integer DEFAULT 1,
    "enrichment_source" character varying(50),
    "enrichment_confidence" numeric(4,3),
    "notes" "text",
    "padronizacao_status" character varying(30) DEFAULT 'pending'::character varying,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "rejection_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "color" character varying(50),
    CONSTRAINT "chk_kcpad_cylinder_has_diameter" CHECK (((("shape_type")::"text" <> 'cylindrical'::"text") OR ("diameter_mm" IS NOT NULL))),
    CONSTRAINT "chk_kcpad_pkg_ext_min2" CHECK (((("pkg_ext_length_mm" IS NULL) AND ("pkg_ext_width_mm" IS NULL) AND ("pkg_ext_height_mm" IS NULL)) OR (((
CASE
    WHEN ("pkg_ext_length_mm" IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN ("pkg_ext_width_mm" IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN ("pkg_ext_height_mm" IS NOT NULL) THEN 1
    ELSE 0
END) >= 2))),
    CONSTRAINT "chk_kcpad_pkg_only_when_packaging" CHECK ((("is_packaging" = true) OR (("pkg_ext_length_mm" IS NULL) AND ("pkg_ext_width_mm" IS NULL) AND ("pkg_ext_height_mm" IS NULL) AND ("pkg_int_length_mm" IS NULL) AND ("pkg_int_width_mm" IS NULL) AND ("pkg_int_height_mm" IS NULL) AND ("pkg_material" IS NULL)))),
    CONSTRAINT "kit_component_padronizacao_circumference_mm_check" CHECK (("circumference_mm" > 0)),
    CONSTRAINT "kit_component_padronizacao_diameter_mm_check" CHECK (("diameter_mm" > 0)),
    CONSTRAINT "kit_component_padronizacao_enrichment_confidence_check" CHECK ((("enrichment_confidence" >= (0)::numeric) AND ("enrichment_confidence" <= (1)::numeric))),
    CONSTRAINT "kit_component_padronizacao_height_mm_check" CHECK (("height_mm" > 0)),
    CONSTRAINT "kit_component_padronizacao_length_mm_check" CHECK (("length_mm" > 0)),
    CONSTRAINT "kit_component_padronizacao_padronizacao_status_check" CHECK ((("padronizacao_status")::"text" = ANY ((ARRAY['pending'::character varying, 'approved'::character varying, 'rejected'::character varying, 'promoted'::character varying])::"text"[]))),
    CONSTRAINT "kit_component_padronizacao_pkg_ext_height_mm_check" CHECK (("pkg_ext_height_mm" > 0)),
    CONSTRAINT "kit_component_padronizacao_pkg_ext_length_mm_check" CHECK (("pkg_ext_length_mm" > 0)),
    CONSTRAINT "kit_component_padronizacao_pkg_ext_width_mm_check" CHECK (("pkg_ext_width_mm" > 0)),
    CONSTRAINT "kit_component_padronizacao_pkg_int_diameter_mm_check" CHECK (("pkg_int_diameter_mm" > 0)),
    CONSTRAINT "kit_component_padronizacao_pkg_int_height_mm_check" CHECK (("pkg_int_height_mm" > 0)),
    CONSTRAINT "kit_component_padronizacao_pkg_int_length_mm_check" CHECK (("pkg_int_length_mm" > 0)),
    CONSTRAINT "kit_component_padronizacao_pkg_int_width_mm_check" CHECK (("pkg_int_width_mm" > 0)),
    CONSTRAINT "kit_component_padronizacao_pkg_weight_g_check" CHECK (("pkg_weight_g" >= 0)),
    CONSTRAINT "kit_component_padronizacao_quantity_check" CHECK (("quantity" > 0)),
    CONSTRAINT "kit_component_padronizacao_shape_type_check" CHECK ((("shape_type")::"text" = ANY ((ARRAY['rectangular'::character varying, 'cylindrical'::character varying, 'flat'::character varying, 'irregular'::character varying, 'spherical'::character varying])::"text"[]))),
    CONSTRAINT "kit_component_padronizacao_weight_g_check" CHECK (("weight_g" >= 0)),
    CONSTRAINT "kit_component_padronizacao_width_mm_check" CHECK (("width_mm" > 0))
);


ALTER TABLE "public"."kit_component_padronizacao" OWNER TO "postgres";


COMMENT ON TABLE "public"."kit_component_padronizacao" IS 'PRATA: Dimensões físicas padronizadas de componentes de kits.
   Alimentada a partir de kit_component_enrichment_raw via fn_standardize_kit_component().
   Requer aprovação (padronizacao_status=approved) antes de promover ao gold.
   Campos length/width/height/diameter/circumference = dimensões do ITEM.
   Campos pkg_* = dimensões da EMBALAGEM (quando is_packaging=TRUE).';



COMMENT ON COLUMN "public"."kit_component_padronizacao"."circumference_mm" IS 'Para cylindrical: calculado automaticamente como ROUND(π × diameter_mm) por trigger.
   Para irregular: medida manual do perímetro. Usado em área de gravação wrap-around.';



COMMENT ON COLUMN "public"."kit_component_padronizacao"."pkg_int_length_mm" IS 'Dimensão interna ÚTIL da embalagem (espaço disponível). Diferente da ext por espessura das paredes.';



COMMENT ON COLUMN "public"."kit_component_padronizacao"."color" IS 'Cor do ITEM (distinta de pkg_color, que é da embalagem). Free-text padronizável. Alimenta product_kit_components.color via fn_promote_kit_component_padronizacao. NULL = desconhecida.';



