CREATE TABLE IF NOT EXISTS "public"."markup_configurations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid",
    "supplier_id" "uuid",
    "category_id" "uuid",
    "product_id" "uuid",
    "variant_id" "uuid",
    "markup_percent" numeric(5,2) NOT NULL,
    "description" "text",
    "is_active" boolean DEFAULT true,
    "priority" integer GENERATED ALWAYS AS (
CASE
    WHEN ("variant_id" IS NOT NULL) THEN 1
    WHEN ("product_id" IS NOT NULL) THEN 2
    WHEN ("category_id" IS NOT NULL) THEN 3
    WHEN ("supplier_id" IS NOT NULL) THEN 4
    WHEN ("organization_id" IS NOT NULL) THEN 5
    ELSE 6
END) STORED,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "created_by" "uuid",
    CONSTRAINT "chk_markup_positive" CHECK ((("markup_percent" >= (0)::numeric) AND ("markup_percent" <= (500)::numeric))),
    CONSTRAINT "chk_single_scope" CHECK ((((((
CASE
    WHEN ("variant_id" IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN ("product_id" IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN ("category_id" IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN ("supplier_id" IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN ("organization_id" IS NOT NULL) THEN 1
    ELSE 0
END) <= 1))
);


ALTER TABLE "public"."markup_configurations" OWNER TO "postgres";


COMMENT ON TABLE "public"."markup_configurations" IS 'Configurações de markup por nível hierárquico (SKU > Produto > Categoria > Fornecedor > Geral)';



COMMENT ON COLUMN "public"."markup_configurations"."priority" IS 'Prioridade calculada: 1=SKU, 2=Produto, 3=Categoria, 4=Fornecedor, 5=Organização, 6=Geral';



