CREATE OR REPLACE VIEW "public"."materials_complete" WITH ("security_invoker"='true') AS
 SELECT "mt"."id" AS "material_id",
    "mt"."organization_id",
    "mt"."name" AS "material_name",
    "mt"."slug" AS "material_slug",
    "mt"."description",
    "mg"."id" AS "group_id",
    "mg"."name" AS "group_name",
    "mg"."slug" AS "group_slug",
    "mt"."is_active",
    "count"(DISTINCT "pm"."product_id") AS "products_count",
    "mt"."created_at",
    "mt"."updated_at"
   FROM (("public"."material_types" "mt"
     JOIN "public"."material_groups" "mg" ON (("mt"."group_id" = "mg"."id")))
     LEFT JOIN "public"."product_materials" "pm" ON (("mt"."id" = "pm"."material_id")))
  GROUP BY "mt"."id", "mt"."organization_id", "mt"."name", "mt"."slug", "mt"."description", "mg"."id", "mg"."name", "mg"."slug", "mt"."is_active", "mt"."created_at", "mt"."updated_at";


