    CONSTRAINT "pbd_placements_valid" CHECK (("placements" <@ ARRAY['card_header_left'::"text", 'card_header_right'::"text", 'card_body'::"text", 'card_footer'::"text", 'corner_bl'::"text", 'corner_br'::"text", 'intelligence_panel'::"text", 'product_detail'::"text", 'catalog'::"text"])),
    CONSTRAINT "pbd_priority_range" CHECK ((("priority" >= 0) AND ("priority" <= 1000))),
    CONSTRAINT "pbd_source_kind_valid" CHECK (("source_kind" = ANY (ARRAY['computed'::"text", 'manual'::"text", 'pipeline'::"text", 'intelligence'::"text", 'ui_only'::"text", 'hybrid'::"text"]))),
    CONSTRAINT "pbd_surfaces_valid" CHECK (("surfaces" <@ ARRAY['catalog'::"text", 'super_filter'::"text", 'product_detail'::"text", 'novelties'::"text", 'comparison'::"text", 'quote_builder'::"text", 'inventory'::"text"]))
);


