CREATE TABLE IF NOT EXISTS "public"."product_kit_components" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "kit_product_id" "uuid" NOT NULL,
    "component_product_id" "uuid",
    "quantity" integer DEFAULT 1 NOT NULL,
    "is_optional" boolean DEFAULT false,
    "is_replaceable" boolean DEFAULT false,
    "allowed_variant_ids" "jsonb" DEFAULT '[]'::"jsonb",
    "display_order" integer DEFAULT 0,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "component_code" character varying(20),
    "component_name" character varying(200),
    "component_description" "text",
    "component_sku" character varying(50),
    "material" character varying(100),
    "color" character varying(50),
    "weight_g" integer,
    "length_mm" integer,
    "width_mm" integer,
    "height_mm" integer,
    "images" "jsonb" DEFAULT '[]'::"jsonb",
    "primary_image_url" "text",
    "allows_personalization" boolean DEFAULT true,
    "personalization_notes" "text",
    "supplier_component_code" character varying(20),
    "material_type_id" "uuid",
    "secondary_material_type_id" "uuid",
    "component_type_code" character varying(30),
    "is_packaging" boolean DEFAULT false,
    "diameter_mm" integer,
    "circumference_mm" integer,
    "shape_type" character varying(30) DEFAULT 'rectangular'::character varying,
    "pkg_ext_length_mm" integer,
    "pkg_ext_width_mm" integer,
    "pkg_ext_height_mm" integer,
    "pkg_int_length_mm" integer,
    "pkg_int_width_mm" integer,
    "pkg_int_height_mm" integer,
    "pkg_int_diameter_mm" integer,
    "pkg_weight_g" integer,
    "pkg_material" character varying(100),
    "pkg_color" character varying(100),
    "pkg_finish" character varying(100),
    "enrichment_status" character varying(30) DEFAULT 'missing'::character varying,
    "enrichment_source" character varying(50),
    "enrichment_confidence" numeric(4,3),
    "padronizacao_id" "uuid",
    "color_id" "uuid",
    "slot_code" character varying(6),
    "is_standalone_sellable" boolean DEFAULT false NOT NULL,
    "dim_source" character varying(20),
    "dim_source_url" "text",
    "weight_source" character varying(30),
    "material_source" character varying(30),
    CONSTRAINT "check_display_order_non_negative" CHECK (("display_order" >= 0)),
    CONSTRAINT "check_not_self_reference" CHECK (("kit_product_id" <> "component_product_id")),
    CONSTRAINT "check_quantity_positive" CHECK (("quantity" > 0)),
    CONSTRAINT "chk_component_identity" CHECK ((("component_product_id" IS NOT NULL) OR ("component_name" IS NOT NULL))),
    CONSTRAINT "chk_pkc_confidence_range" CHECK ((("enrichment_confidence" IS NULL) OR (("enrichment_confidence" >= (0)::numeric) AND ("enrichment_confidence" <= (1)::numeric)))),
    CONSTRAINT "chk_pkc_diameter_sane" CHECK ((("diameter_mm" IS NULL) OR (("diameter_mm" >= 1) AND ("diameter_mm" <= 800)))),
    CONSTRAINT "chk_pkc_height_sane" CHECK ((("height_mm" IS NULL) OR (("height_mm" >= 1) AND ("height_mm" <= 1500)))),
    CONSTRAINT "chk_pkc_length_sane" CHECK ((("length_mm" IS NULL) OR (("length_mm" >= 1) AND ("length_mm" <= 1500)))),
    CONSTRAINT "chk_pkc_slot_fmt" CHECK ((("slot_code" IS NULL) OR (("slot_code")::"text" ~ '^(K|E)[0-9]{1,3}$'::"text"))),
    CONSTRAINT "chk_pkc_slot_kind" CHECK ((("slot_code" IS NULL) OR ("is_packaging" AND (("slot_code")::"text" ~~ 'E%'::"text")) OR ((NOT "is_packaging") AND (("slot_code")::"text" ~~ 'K%'::"text")))),
    CONSTRAINT "chk_pkc_weight_sane" CHECK ((("weight_g" IS NULL) OR (("weight_g" >= 1) AND ("weight_g" <= 50000)))),
    CONSTRAINT "chk_pkc_width_sane" CHECK ((("width_mm" IS NULL) OR (("width_mm" >= 1) AND ("width_mm" <= 1500)))),
    CONSTRAINT "product_kit_components_check" CHECK (("kit_product_id" <> "component_product_id")),
    CONSTRAINT "product_kit_components_circumference_mm_check" CHECK (("circumference_mm" > 0)),
    CONSTRAINT "product_kit_components_diameter_mm_check" CHECK (("diameter_mm" > 0)),
    CONSTRAINT "product_kit_components_enrichment_confidence_check" CHECK ((("enrichment_confidence" >= (0)::numeric) AND ("enrichment_confidence" <= (1)::numeric))),
    CONSTRAINT "product_kit_components_enrichment_status_check" CHECK ((("enrichment_status")::"text" = ANY ((ARRAY['missing'::character varying, 'partial'::character varying, 'complete'::character varying])::"text"[]))),
    CONSTRAINT "product_kit_components_material_source_check" CHECK ((("material_source")::"text" = ANY ((ARRAY['ficha'::character varying, 'heuristic_type'::character varying, 'heuristic_name'::character varying, 'supplier_api'::character varying, 'manual'::character varying])::"text"[]))),
    CONSTRAINT "product_kit_components_quantity_check" CHECK (("quantity" > 0)),
    CONSTRAINT "product_kit_components_shape_type_check" CHECK ((("shape_type")::"text" = ANY ((ARRAY['rectangular'::character varying, 'cylindrical'::character varying, 'flat'::character varying, 'irregular'::character varying, 'spherical'::character varying])::"text"[]))),
    CONSTRAINT "product_kit_components_weight_source_check" CHECK ((("weight_source")::"text" = ANY ((ARRAY['measured_real'::character varying, 'inherited_total'::character varying, 'estimated_heuristic'::character varying, 'estimated_proportional'::character varying, 'supplier_api'::character varying, 'manual'::character varying])::"text"[])))
)
WITH ("autovacuum_vacuum_scale_factor"='0.05', "autovacuum_analyze_scale_factor"='0.05', "autovacuum_vacuum_threshold"='50', "autovacuum_analyze_threshold"='50');


