CREATE OR REPLACE VIEW "public"."products_with_materials" WITH ("security_invoker"='true') AS
 SELECT "p"."id" AS "product_id",
    "p"."organization_id",
    "p"."name" AS "product_name",
    "mt"."id" AS "material_id",
    "mt"."name" AS "material_name",
    "mg"."name" AS "material_group",
    "pm"."part",
    "pm"."percentage",
    "pm"."sort_order",
    "p"."created_at",
    "pm"."created_at" AS "material_added_at"
   FROM ((("public"."products" "p"
     JOIN "public"."product_materials" "pm" ON (("p"."id" = "pm"."product_id")))
     JOIN "public"."material_types" "mt" ON (("pm"."material_id" = "mt"."id")))
     JOIN "public"."material_groups" "mg" ON (("mt"."group_id" = "mg"."id")))
  ORDER BY "p"."name", "pm"."sort_order";


