    "min_qty_3" integer,
    "min_qty_4" integer,
    "min_qty_5" integer,
    "next_quantity_1" integer,
    "next_quantity_2" integer,
    "next_quantity_3" integer,
    "next_date_1" "date",
    "next_date_2" "date",
    "next_date_3" "date",
    "sale_multiplier" integer,
    "supplier_thumbnail" "text",
    "supplier_images" "jsonb",
    "supplier_videos" "jsonb",
    "next_quantity_4" integer,
