    CONSTRAINT "chk_padvar_color_id_requer_nome" CHECK ((("color_id" IS NULL) OR ("length"(TRIM(BOTH FROM COALESCE("color_name", ''::"text"))) > 0))),
    CONSTRAINT "chk_padvar_custo_nao_negativo" CHECK ((("cost_price" IS NULL) OR ("cost_price" >= (0)::numeric))),
    CONSTRAINT "chk_padvar_refs_nao_vazias" CHECK ((("length"(TRIM(BOTH FROM "variant_reference")) > 0) AND ("length"(TRIM(BOTH FROM "parent_reference")) > 0))),
    CONSTRAINT "chk_ppv_size_length" CHECK ((("size_length_cm" > (0)::numeric) AND ("size_length_cm" <= (300)::numeric))),
    CONSTRAINT "chk_ppv_size_width" CHECK ((("size_width_cm" > (0)::numeric) AND ("size_width_cm" <= (300)::numeric)))
)
WITH ("autovacuum_vacuum_scale_factor"='0.05', "autovacuum_analyze_scale_factor"='0.02');


