CASE
    WHEN ("category_id" IS NOT NULL) THEN ((('https://www.somarcas.com.br/'::"text" || ("category_id")::"text") || '/categorias/'::"text") || "slug")
    ELSE NULL::"text"
END) STORED,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
