CASE
    WHEN (("site_id" IS NOT NULL) AND ("slug" IS NOT NULL)) THEN ((('https://www.somarcas.com.br/'::"text" || ("site_id")::"text") || '/produto/'::"text") || "slug")
    ELSE NULL::"text"
END) STORED,
    "source" "text" DEFAULT 'unknown'::"text" NOT NULL,
