CREATE TABLE IF NOT EXISTS "public"."supplier_products_raw" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "supplier_id" "uuid" NOT NULL,
    "supplier_reference" character varying(50) NOT NULL,
    "raw_data" "jsonb" NOT NULL,
    "imported_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "import_batch_id" "uuid",
    "processed_at" timestamp with time zone,
    "process_errors" "jsonb",
    "product_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "supplier_sku" character varying,
    "variant_id" "uuid",
    "source_channel" "text" DEFAULT 'n8n'::"text" NOT NULL,
    "source_event_id" "text",
    "source_endpoint" "text",
    "attempts" integer DEFAULT 0 NOT NULL,
    "last_error" "jsonb",
    "status" "public"."supplier_raw_status" DEFAULT 'pending'::"public"."supplier_raw_status" NOT NULL,
    "images_status" "public"."supplier_raw_status" DEFAULT 'pending'::"public"."supplier_raw_status" NOT NULL,
    "content_hash" "text" NOT NULL,
    "images_processed" boolean GENERATED ALWAYS AS (("images_status" = 'processed'::"public"."supplier_raw_status")) STORED,
    "stock_data" "jsonb",
    "stock_hash" "text",
    "stock_status" "public"."supplier_raw_status" DEFAULT 'pending'::"public"."supplier_raw_status" NOT NULL,
    "stock_synced_at" timestamp with time zone,
    "stock_processed_at" timestamp with time zone,
    "site_data" "jsonb",
    "site_hash" "text",
    "site_status" "public"."supplier_raw_status" DEFAULT 'pending'::"public"."supplier_raw_status",
    "site_source_url" "text",
    "site_scraped_at" timestamp with time zone,
    "site_processed_at" timestamp with time zone,
    "site_fetch_req_id" bigint,
    "site_attempts" integer DEFAULT 0 NOT NULL,
    "site_last_error" "text",
    "site_enqueued_at" timestamp with time zone,
    "site_promoted_at" timestamp with time zone,
    CONSTRAINT "chk_spr_no_processed_with_errors" CHECK ((NOT (("status" = 'processed'::"public"."supplier_raw_status") AND ("process_errors" IS NOT NULL)))),
    CONSTRAINT "chk_spr_raw_object" CHECK (("jsonb_typeof"("raw_data") = 'object'::"text")),
    CONSTRAINT "chk_spr_reference_trimmed" CHECK ((("supplier_reference")::"text" = "btrim"(("supplier_reference")::"text"))),
    CONSTRAINT "chk_spr_sku_trimmed" CHECK ((("supplier_sku" IS NULL) OR (("supplier_sku")::"text" = "btrim"(("supplier_sku")::"text")))),
    CONSTRAINT "chk_spr_source_channel" CHECK (("source_channel" = ANY (ARRAY['n8n'::"text", 'file_upload'::"text", 'file_upload_retry'::"text", 'file_upload_fix'::"text", 'manual'::"text", 'api_direct'::"text", 'bitrix'::"text", 'mysql_sync'::"text", 'legacy'::"text", 'api_clientes'::"text", 'api_ruiz'::"text", 'api_carrinho'::"text", 'site_scraping'::"text", 'api_xml'::"text", 'api_rest'::"text", 'n8n_workflow'::"text", 'edge_function'::"text", 'api_oficial'::"text", 'hg_products'::"text", 'wc_store'::"text"])))
)
WITH ("autovacuum_vacuum_cost_limit"='2000', "fillfactor"='90', "autovacuum_vacuum_scale_factor"='0.01', "autovacuum_analyze_scale_factor"='0.005', "autovacuum_vacuum_cost_delay"='2');


ALTER TABLE "public"."supplier_products_raw" OWNER TO "postgres";


COMMENT ON TABLE "public"."supplier_products_raw" IS 'Bronze/landing de ingestão. GRÃO: 1 linha = 1 variante/SKU do fornecedor; o produto-pai é derivado na intermediária (produtos_padronizacao via fn_derive_parent_ref). raw_data é payload imutável do fornecedor; proveniência/controle ficam em colunas próprias.';



COMMENT ON COLUMN "public"."supplier_products_raw"."supplier_reference" IS 'Identificador da VARIANTE no fornecedor (o pai é derivado na silver).';



COMMENT ON COLUMN "public"."supplier_products_raw"."raw_data" IS 'Payload original do fornecedor (imutavel). NAO gravar metadados de controle aqui — use source_channel/source_endpoint/imported_at. fn_spr_before_write remove chaves _* legadas e recalcula content_hash.';



COMMENT ON COLUMN "public"."supplier_products_raw"."process_errors" IS 'Erros de processamento (entrada, escrita pelo worker).';



COMMENT ON COLUMN "public"."supplier_products_raw"."source_channel" IS 'Identifica a origem técnica da linha. Valores válidos:
   api_clientes   → XBZ /api/clientes/GetListaDeProdutos (F1)
   api_ruiz       → XBZ /api/ruiz/* portal (F2, não integrado)
   api_carrinho   → XBZ /api/carrinho/* portal (F3, não integrado)
   site_scraping  → Scraping xbzbrindes.com.br via Jina AI (F4)
   api_xml        → Spot/Stricker API XML de catálogo
   api_rest       → Só Marcas / Asia Import APIs REST
   n8n_workflow   → Workflow n8n automatizado (futuro)
   edge_function  → Edge Function Supabase (futuro)
   file_upload / file_upload_retry / manual / legacy → valores históricos';



COMMENT ON COLUMN "public"."supplier_products_raw"."source_endpoint" IS 'Endpoint específico da fonte. Ex: /api/clientes/GetListaDeProdutos, ws.spotgifts.com.br/api/v1SSL';



COMMENT ON COLUMN "public"."supplier_products_raw"."attempts" IS 'No de tentativas de processamento. Incrementada pelo trigger fn_spr_before_write a cada novo erro.';



COMMENT ON COLUMN "public"."supplier_products_raw"."last_error" IS 'Ultimo process_errors observado (mantido pelo trigger). Historico de falha da linha.';



COMMENT ON COLUMN "public"."supplier_products_raw"."content_hash" IS 'sha256 canônico do payload: raw_data sem chaves de metadado (prefixo _) e sem supplier_settings.hash_excluded_fields. Mantido por fn_spr_before_write (BEFORE INSERT/UPDATE). NÃO é mais coluna gerada.';



COMMENT ON COLUMN "public"."supplier_products_raw"."images_processed" IS 'Derivada (GENERATED) de images_status. SSOT = images_status; nunca escrever direto.';



COMMENT ON COLUMN "public"."supplier_products_raw"."stock_data" IS 'Feed Stocks cru deste SKU (Quantity, NextQuantity1..6/NextDate1..6, Country). Mesmo grao da variante; trilha independente: NAO polui raw_data nem content_hash do produto.';



COMMENT ON COLUMN "public"."supplier_products_raw"."stock_hash" IS 'sha256(stock_data) mantido pela RPC upsert_supplier_stock_raw (coluna plana de proposito p/ evitar rewrite da tabela).';



COMMENT ON COLUMN "public"."supplier_products_raw"."stock_status" IS 'Trilha Bronze->Gold do estoque (independente de status). RPC reseta p/ pending quando stock_hash muda.';



COMMENT ON COLUMN "public"."supplier_products_raw"."site_data" IS 'Trilha SITE (scraping da vitrine): payload completo da pagina do produto-pai (galeria, video, categorias, gravacao, dimensoes extra). Imutavel; tratamento no silver. Replicado nas variantes do mesmo CodigoAmigavel.';



COMMENT ON COLUMN "public"."supplier_products_raw"."site_status" IS 'Estado da trilha de site (scraping): pending->processing->processed/failed/skipped.';



COMMENT ON COLUMN "public"."supplier_products_raw"."site_fetch_req_id" IS 'pg_net request id da busca de site em voo (padrao fire/collect do scraper).';



CREATE OR REPLACE VIEW "public"."somarcas_catalogo_publico" WITH ("security_invoker"='true') AS
 SELECT "id",
    ("raw_data" ->> 'codigo'::"text") AS "codigo",
    ("raw_data" ->> 'titulo'::"text") AS "titulo",
    ("raw_data" ->> 'descricao'::"text") AS "descricao",
    ("raw_data" ->> 'url_foto'::"text") AS "url_foto",
    ("raw_data" -> 'matriz_de_fotos_adicionais'::"text") AS "fotos_adicionais",
    ("raw_data" -> 'matriz_de_categorias'::"text") AS "categorias",
    ("raw_data" -> 'produtos_similares'::"text") AS "produtos_similares",
    ("raw_data" ->> 'dimensoes_do_produto'::"text") AS "dimensoes_produto",
    ("raw_data" ->> 'dimensoes_da_embalagem'::"text") AS "dimensoes_embalagem",
    ("raw_data" ->> 'peso_da_embalagem'::"text") AS "peso_embalagem",
    ("raw_data" ->> 'embalagem_do_produto'::"text") AS "embalagem",
    ("raw_data" ->> 'garantia_do_produto'::"text") AS "garantia",
    ("raw_data" ->> 'tipo_gravacao'::"text") AS "tipo_gravacao",
    ("raw_data" ->> 'quantidade_minima_sugerida'::"text") AS "quantidade_minima",
    ("raw_data" ->> 'preco_com_gravacao_com_impostos'::"text") AS "preco_com_gravacao",
    ("raw_data" ->> 'preco_sem_gravacao_com_impostos'::"text") AS "preco_sem_gravacao",
    (COALESCE((("raw_data" ->> 'estoque'::"text"))::numeric, (0)::numeric) > (0)::numeric) AS "disponivel",
    ("raw_data" ->> 'data_ultima_atualizacao'::"text") AS "atualizado_em",
    "variant_id",
    "product_id"
   FROM "public"."supplier_products_raw" "r"
  WHERE (("supplier_id" = '841cd690-210a-422a-908c-7676828db272'::"uuid") AND (COALESCE("lower"(("raw_data" ->> 'produto_ativo'::"text")), 'sim'::"text") <> ALL (ARRAY['nao'::"text", 'não'::"text", 'false'::"text", '0'::"text", 'f'::"text", 'inativo'::"text", 'no'::"text"])));


ALTER VIEW "public"."somarcas_catalogo_publico" OWNER TO "postgres";


COMMENT ON VIEW "public"."somarcas_catalogo_publico" IS 'Catalogo publico So Marcas (role anon). So vitrine + precos COM impostos; estoque vira boolean disponivel. NUNCA expor precos sem impostos/ipi/ncm/estoque numerico. Filtro corrigido 2026-06: produto_ativo usa valor sim.';



