CREATE OR REPLACE VIEW "public"."v_smoke_tests_trend" WITH ("security_invoker"='true') AS
 SELECT "ran_at",
    ("count"(*))::integer AS "total",
    ("count"(*) FILTER (WHERE ("result" ~~ '%PASS%'::"text")))::integer AS "passed",
    ("count"(*) FILTER (WHERE ("result" ~~ '%FAIL%'::"text")))::integer AS "failed",
    ("count"(*) FILTER (WHERE ("result" ~~ '%WARN%'::"text")))::integer AS "warned",
    "avg"("duration_ms") AS "avg_duration_ms"
   FROM "public"."smoke_test_runs"
  GROUP BY "ran_at"
  ORDER BY "ran_at" DESC
 LIMIT 12;


ALTER VIEW "public"."v_smoke_tests_trend" OWNER TO "postgres";


