                   FROM "public"."variant_supplier_sources"
                  WHERE ("variant_supplier_sources"."is_active" = true)), (0)::bigint))::"text" AS "coalesce",
            'units'::"text"
        UNION ALL
         SELECT 'suppliers'::"text",
