CREATE OR REPLACE VIEW "public"."v_variant_sale_prices_public" WITH ("security_invoker"='false') AS
 SELECT "pv"."id" AS "variant_id",
    "pv"."product_id",
    "pv"."sku",
    "pv"."color_name",
    "vss"."min_qty_1",
    "round"(("vss"."cost_price_1" * ((1)::numeric + (COALESCE("mc_var"."markup_percent", "mc_prod"."markup_percent", "mc_cat"."markup_percent", "s"."default_markup_percent", 115.0) / (100)::numeric))), 2) AS "sale_price_1",
    "vss"."min_qty_2",
    "round"(("vss"."cost_price_2" * ((1)::numeric + (COALESCE("mc_var"."markup_percent", "mc_prod"."markup_percent", "mc_cat"."markup_percent", "s"."default_markup_percent", 115.0) / (100)::numeric))), 2) AS "sale_price_2",
    "vss"."min_qty_3",
    "round"(("vss"."cost_price_3" * ((1)::numeric + (COALESCE("mc_var"."markup_percent", "mc_prod"."markup_percent", "mc_cat"."markup_percent", "s"."default_markup_percent", 115.0) / (100)::numeric))), 2) AS "sale_price_3",
    "vss"."min_qty_4",
    "round"(("vss"."cost_price_4" * ((1)::numeric + (COALESCE("mc_var"."markup_percent", "mc_prod"."markup_percent", "mc_cat"."markup_percent", "s"."default_markup_percent", 115.0) / (100)::numeric))), 2) AS "sale_price_4",
    "vss"."min_qty_5",
    "round"(("vss"."cost_price_5" * ((1)::numeric + (COALESCE("mc_var"."markup_percent", "mc_prod"."markup_percent", "mc_cat"."markup_percent", "s"."default_markup_percent", 115.0) / (100)::numeric))), 2) AS "sale_price_5"
   FROM (((((("public"."product_variants" "pv"
     JOIN "public"."products" "p" ON ((("p"."id" = "pv"."product_id") AND ("p"."is_active" = true) AND ("p"."is_deleted" IS NOT TRUE))))
     JOIN "public"."variant_supplier_sources" "vss" ON ((("vss"."variant_id" = "pv"."id") AND ("vss"."is_preferred" = true))))
     LEFT JOIN "public"."suppliers" "s" ON (("s"."id" = "vss"."supplier_id")))
     LEFT JOIN "public"."markup_configurations" "mc_var" ON ((("mc_var"."variant_id" = "pv"."id") AND ("mc_var"."is_active" = true))))
     LEFT JOIN "public"."markup_configurations" "mc_prod" ON ((("mc_prod"."product_id" = "pv"."product_id") AND ("mc_prod"."variant_id" IS NULL) AND ("mc_prod"."category_id" IS NULL) AND ("mc_prod"."is_active" = true))))
     LEFT JOIN "public"."markup_configurations" "mc_cat" ON ((("mc_cat"."category_id" = ( SELECT "products"."category_id"
           FROM "public"."products"
          WHERE ("products"."id" = "pv"."product_id"))) AND ("mc_cat"."product_id" IS NULL) AND ("mc_cat"."variant_id" IS NULL) AND ("mc_cat"."is_active" = true))))
  WHERE ("pv"."is_active" = true);


ALTER VIEW "public"."v_variant_sale_prices_public" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_variant_sale_prices_public" IS 'PUBLIC PRICE PROJECTION (SECURITY DEFINER intencional / fix_version 20260717_v1). Emite apenas preco de venda por faixa de quantidade; custo/markup usados no calculo nunca sao expostos. Roda como owner para ler variant_supplier_sources/markup_configurations sem conceder essas tabelas sensiveis ao anon. NAO alterar para security_invoker=true.';



CREATE OR REPLACE VIEW "public"."v_variants_with_commemorative_dates" WITH ("security_invoker"='true') AS
 SELECT "pv"."id" AS "variant_id",
    "pv"."name" AS "variant_name",
    "pv"."sku" AS "variant_sku",
    "pv"."color_name",
    "pv"."color_hex",
    "p"."id" AS "product_id",
    "p"."name" AS "product_name",
    "p"."sku" AS "product_sku",
    "cd"."id" AS "commemorative_date_id",
    "cd"."name" AS "commemorative_date_name",
    "cd"."slug" AS "commemorative_date_slug",
    "cd"."date_month",
    "cd"."date_day",
    "cd"."category" AS "date_category",
    "cd"."icon_name" AS "date_icon",
    "cd"."color_hex" AS "date_color",
    "vcd"."is_featured",
    "vcd"."custom_description",
    ("vcd"."variant_id" IS NULL) AS "is_product_wide"
   FROM ((("public"."product_variants" "pv"
     JOIN "public"."products" "p" ON (("p"."id" = "pv"."product_id")))
     LEFT JOIN "public"."variant_commemorative_dates" "vcd" ON ((("vcd"."variant_id" = "pv"."id") OR (("vcd"."product_id" = "p"."id") AND ("vcd"."variant_id" IS NULL)))))
     LEFT JOIN "public"."commemorative_dates" "cd" ON (("cd"."id" = "vcd"."commemorative_date_id")))
  WHERE ("pv"."is_active" = true)
  ORDER BY "p"."name", "pv"."color_name", "cd"."date_month", "cd"."date_day";


ALTER VIEW "public"."v_variants_with_commemorative_dates" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_video_dashboard" WITH ("security_invoker"='true') AS
 SELECT COALESCE("video_type", 'sem_tipo'::character varying) AS "tipo",
    "cloudflare_status" AS "status",
    "count"(*) AS "quantidade",
    "count"(DISTINCT "product_id") AS "produtos",
    "sum"("duration_seconds") AS "duracao_total_seg",
    "round"("avg"("duration_seconds"), 0) AS "duracao_media_seg",
    "count"(*) FILTER (WHERE ("width_px" >= 1920)) AS "full_hd",
    "count"(*) FILTER (WHERE (("width_px" >= 1280) AND ("width_px" < 1920))) AS "hd",
    "count"(*) FILTER (WHERE (("width_px" < 1280) OR ("width_px" IS NULL))) AS "sd_ou_desconhecido"
   FROM "public"."product_videos" "pv"
  WHERE ("is_active" = true)
  GROUP BY COALESCE("video_type", 'sem_tipo'::character varying), "cloudflare_status"
  ORDER BY ("count"(*)) DESC;


ALTER VIEW "public"."v_video_dashboard" OWNER TO "postgres";


