    (("lpad"((("pv"."duration_seconds" / 60))::"text", 2, '0'::"text") || ':'::"text") || "lpad"((("pv"."duration_seconds" % 60))::"text", 2, '0'::"text")) AS "duration_formatted",
    "pv"."width_px",
