CREATE OR REPLACE VIEW "public"."vw_category_completeness" WITH ("security_invoker"='true') AS
 SELECT "c"."id",
    "c"."name",
    "c"."slug",
    "c"."level",
    "c"."is_active",
    "c"."is_visible",
    "c"."products_count",
    "count"(DISTINCT "p"."id") FILTER (WHERE ("p"."is_active" = true)) AS "produtos_ativos_main",
    "count"(DISTINCT "pca"."product_id") AS "produtos_via_pca",
    (EXISTS ( SELECT 1
           FROM "public"."category_copywriting_config" "cfg"
          WHERE ("cfg"."category_id" = "c"."id"))) AS "tem_copywriting",
    ("c"."icon" IS NOT NULL) AS "tem_icone",
    ("c"."meta_title" IS NOT NULL) AS "tem_seo_title",
    ("c"."color_hex" IS NOT NULL) AS "tem_cor",
    ("c"."image_url" IS NOT NULL) AS "tem_imagem",
    "round"((((((((
        CASE
            WHEN ("c"."meta_title" IS NOT NULL) THEN 20
            ELSE 0
        END +
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "public"."category_copywriting_config" "cfg"
              WHERE ("cfg"."category_id" = "c"."id"))) THEN 20
            ELSE 0
        END) +
        CASE
            WHEN ("c"."icon" IS NOT NULL) THEN 15
            ELSE 0
        END) +
        CASE
            WHEN ("c"."color_hex" IS NOT NULL) THEN 10
            ELSE 0
        END) +
        CASE
            WHEN ("c"."image_url" IS NOT NULL) THEN 15
            ELSE 0
        END) +
        CASE
            WHEN ("c"."description" IS NOT NULL) THEN 10
            ELSE 0
        END) +
        CASE
            WHEN ("c"."meta_description" IS NOT NULL) THEN 10
            ELSE 0
        END))::numeric, 0) AS "completude_score"
   FROM (("public"."categories" "c"
     LEFT JOIN "public"."products" "p" ON (("p"."main_category_id" = "c"."id")))
     LEFT JOIN "public"."product_category_assignments" "pca" ON (("pca"."category_id" = "c"."id")))
  WHERE ("c"."is_active" = true)
  GROUP BY "c"."id", "c"."name", "c"."slug", "c"."level", "c"."is_active", "c"."is_visible", "c"."products_count", "c"."meta_title", "c"."color_hex", "c"."image_url", "c"."description", "c"."meta_description", "c"."icon"
  ORDER BY "c"."level", ("round"((((((((
        CASE
            WHEN ("c"."meta_title" IS NOT NULL) THEN 20
            ELSE 0
        END +
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "public"."category_copywriting_config" "cfg"
              WHERE ("cfg"."category_id" = "c"."id"))) THEN 20
            ELSE 0
        END) +
        CASE
            WHEN ("c"."icon" IS NOT NULL) THEN 15
            ELSE 0
        END) +
        CASE
            WHEN ("c"."color_hex" IS NOT NULL) THEN 10
            ELSE 0
        END) +
        CASE
            WHEN ("c"."image_url" IS NOT NULL) THEN 15
            ELSE 0
        END) +
        CASE
            WHEN ("c"."description" IS NOT NULL) THEN 10
            ELSE 0
        END) +
        CASE
            WHEN ("c"."meta_description" IS NOT NULL) THEN 10
            ELSE 0
        END))::numeric, 0)) DESC;


ALTER VIEW "public"."vw_category_completeness" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_category_completeness" IS 'Score de completude por categoria (0–100 pts). Pesos: meta_title(20) + copywriting(20) + icone(15) + imagem(15) + cor(10) + descrição(10) + meta_description(10). CORRIGIDO em 2024: icone usa categories.icon IS NOT NULL em vez de subquery em category_icons (que era frágil e lenta).';



CREATE OR REPLACE VIEW "public"."vw_category_mapping_gaps" WITH ("security_invoker"='true') AS
 SELECT "s"."id" AS "supplier_id",
    "s"."name" AS "supplier_name",
    "sc"."id" AS "supplier_category_id",
    "sc"."supplier_code",
    "sc"."supplier_name" AS "supplier_category_name",
    "sc"."level" AS "supplier_level",
    ( SELECT "c"."name"
           FROM "public"."categories" "c"
          WHERE ("c"."is_active" = true)
          ORDER BY ("extensions"."similarity"("lower"("sc"."supplier_name"), "lower"("c"."name"))) DESC
         LIMIT 1) AS "suggested_canonical",
    ( SELECT "round"(("max"("extensions"."similarity"("lower"("sc"."supplier_name"), "lower"("c"."name"))))::numeric, 2) AS "round"
           FROM "public"."categories" "c"
          WHERE ("c"."is_active" = true)) AS "best_trgm_similarity",
    "sc"."created_at"
   FROM ("public"."supplier_categories" "sc"
     JOIN "public"."suppliers" "s" ON (("s"."id" = "sc"."supplier_id")))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM "public"."supplier_category_mappings" "scm"
          WHERE ("scm"."supplier_category_id" = "sc"."id"))))
  ORDER BY "s"."name", ( SELECT "round"(("max"("extensions"."similarity"("lower"("sc"."supplier_name"), "lower"("c"."name"))))::numeric, 2) AS "round"
           FROM "public"."categories" "c"
          WHERE ("c"."is_active" = true)) DESC NULLS LAST;


ALTER VIEW "public"."vw_category_mapping_gaps" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_category_mapping_gaps" IS 'Lista categorias de fornecedores ainda sem mapeamento para categoria canônica.
Inclui sugestão automática via trgm (best_trgm_similarity) para facilitar curadoria manual.
Use: SELECT * FROM vw_category_mapping_gaps ORDER BY best_trgm_similarity DESC para priorizar.';



