   FROM (("public"."category_target_audiences" "cta"
     JOIN "public"."categories" "c" ON (("c"."id" = "cta"."category_id")))
     JOIN "public"."target_audiences" "ta" ON (("ta"."id" = "cta"."target_audience_id")))
  ORDER BY "c"."name", "cta"."relevance_score" DESC;


ALTER VIEW "public"."vw_category_target_audiences" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_category_variation_types" WITH ("security_invoker"='true') AS
 WITH RECURSIVE "category_tree" AS (
         SELECT "c"."id" AS "category_id",
            "c"."name" AS "category_name",
            "c"."level" AS "category_level",
            "c"."parent_id",
            "cvt"."variation_type_id",
            "vt"."code" AS "variation_code",
            "vt"."name" AS "variation_name",
            "cvt"."is_required",
            "cvt"."display_order",
            false AS "is_inherited",
            1 AS "depth"
           FROM (("public"."categories" "c"
             JOIN "public"."category_variation_types" "cvt" ON (("c"."id" = "cvt"."category_id")))
             JOIN "public"."variation_types" "vt" ON (("cvt"."variation_type_id" = "vt"."id")))
          WHERE (("cvt"."is_active" = true) AND ("cvt"."inherit_from_parent" = true))
        UNION ALL
         SELECT "child"."id" AS "category_id",
            "child"."name" AS "category_name",
            "child"."level" AS "category_level",
            "child"."parent_id",
            "parent"."variation_type_id",
            "parent"."variation_code",
            "parent"."variation_name",
            "parent"."is_required",
            "parent"."display_order",
            true AS "is_inherited",
            ("parent"."depth" + 1)
           FROM ("public"."categories" "child"
             JOIN "category_tree" "parent" ON (("child"."parent_id" = "parent"."category_id")))
          WHERE (("child"."is_active" = true) AND (NOT (EXISTS ( SELECT 1
                   FROM "public"."category_variation_types" "cvt2"
                  WHERE (("cvt2"."category_id" = "child"."id") AND ("cvt2"."variation_type_id" = "parent"."variation_type_id") AND ("cvt2"."is_active" = true))))))
        )
 SELECT DISTINCT ON ("category_id", "variation_type_id") "category_id",
    "category_name",
    "category_level",
    "variation_type_id",
    "variation_code",
    "variation_name",
    "is_required",
    "display_order",
    "is_inherited"
   FROM "category_tree"
  ORDER BY "category_id", "variation_type_id", "depth";


ALTER VIEW "public"."vw_category_variation_types" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_category_variation_types" IS 'Mostra variações por categoria incluindo herança automática de categorias pai';



