CREATE OR REPLACE VIEW "public"."vw_products_by_property_category" WITH ("security_invoker"='true') AS
 SELECT "pd"."category",
    "count"(DISTINCT "pp"."product_id") AS "product_count",
    "count"("pp"."id") AS "property_count",
    "array_agg"(DISTINCT "pd"."name_pt" ORDER BY "pd"."name_pt") AS "properties_in_category"
   FROM ("public"."property_definitions" "pd"
     JOIN "public"."product_properties" "pp" ON (("pd"."code" = "pp"."property_code")))
  GROUP BY "pd"."category"
  ORDER BY ("count"(DISTINCT "pp"."product_id")) DESC;


