CREATE OR REPLACE VIEW "public"."vw_somarcas_materials" WITH ("security_invoker"='true') AS
 SELECT ("mt"."name")::"text" AS "material",
    "mg"."name" AS "grupo_material",
    "count"(DISTINCT "p"."id") AS "total_produtos",
    "sum"(
        CASE
            WHEN ("pv"."stock_quantity" > 0) THEN 1
            ELSE 0
        END) AS "produtos_com_estoque",
    COALESCE("sum"("pv"."stock_quantity"), (0)::bigint) AS "estoque_total",
    "round"("avg"("pm"."percentage"), 1) AS "percentual_medio",
    "min"("p"."cost_price") AS "preco_min",
    "max"("p"."cost_price") AS "preco_max",
    "round"("avg"("p"."cost_price"), 2) AS "preco_medio"
   FROM (((("public"."product_materials" "pm"
     JOIN "public"."material_types" "mt" ON (("mt"."id" = "pm"."material_id")))
     JOIN "public"."material_groups" "mg" ON (("mg"."id" = "mt"."group_id")))
     JOIN "public"."products" "p" ON (("p"."id" = "pm"."product_id")))
     LEFT JOIN "public"."product_variants" "pv" ON ((("pv"."product_id" = "p"."id") AND ("pv"."is_active" = true))))
  WHERE (("pm"."is_active" = true) AND ("p"."is_active" = true) AND ("p"."supplier_id" = '841cd690-210a-422a-908c-7676828db272'::"uuid"))
  GROUP BY "mt"."name", "mg"."name"
  ORDER BY ("count"(DISTINCT "p"."id")) DESC;


ALTER VIEW "public"."vw_somarcas_materials" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_somarcas_materials" IS 'Distribuição de materiais dos produtos Só Marcas — usa product_materials normalizada.
 Substitui versão legada com regex no Bronze. Inclui estoque, preços por material.
 Reescrito: 2026-06-11 | M6 - Melhoria integridade materiais';



CREATE OR REPLACE VIEW "public"."vw_somarcas_pending" WITH ("security_invoker"='true') AS
 SELECT "id",
    "supplier_reference" AS "sku",
    ("raw_data" ->> 'titulo'::"text") AS "titulo",
    (("raw_data" ->> 'estoque'::"text"))::integer AS "estoque",
    (("raw_data" ->> 'preco_com_gravacao_com_impostos'::"text"))::numeric AS "preco",
    "imported_at"
   FROM "public"."supplier_products_raw"
  WHERE (("supplier_id" = '841cd690-210a-422a-908c-7676828db272'::"uuid") AND ("status" <> 'processed'::"public"."supplier_raw_status"))
  ORDER BY "imported_at" DESC;


