CREATE OR REPLACE VIEW "public"."vw_supplier_products_raw_status" WITH ("security_invoker"='true') AS
 SELECT "s"."id" AS "supplier_id",
    "s"."name" AS "supplier_name",
    "count"(*) AS "total_produtos",
    "count"(*) FILTER (WHERE ("spr"."status" = 'processed'::"public"."supplier_raw_status")) AS "processados",
    "count"(*) FILTER (WHERE ("spr"."status" <> 'processed'::"public"."supplier_raw_status")) AS "pendentes",
    "count"(*) FILTER (WHERE ("spr"."process_errors" IS NOT NULL)) AS "com_erro",
    "round"(((("count"(*) FILTER (WHERE ("spr"."status" = 'processed'::"public"."supplier_raw_status")))::numeric * 100.0) / (NULLIF("count"(*), 0))::numeric), 2) AS "taxa_sucesso_pct",
    "min"("spr"."imported_at") AS "primeira_importacao",
    "max"("spr"."imported_at") AS "ultima_importacao",
    "avg"(EXTRACT(epoch FROM ("spr"."processed_at" - "spr"."imported_at"))) AS "tempo_medio_processamento_seg"
   FROM ("public"."supplier_products_raw" "spr"
     JOIN "public"."suppliers" "s" ON (("s"."id" = "spr"."supplier_id")))
  GROUP BY "s"."id", "s"."name"
  ORDER BY ("count"(*)) DESC;


